window.MLS_DATA = {"map": {"title": "MODERN LEGAL STUDIES", "subtitle": "当代法学系统学习平台", "editions": {"wacks": "Raymond Wacks, Understanding Jurisprudence: An Introduction to Legal Theory, 6th ed., Oxford University Press", "siems": "Mathias M. Siems, Comparative Law, 3rd ed., Oxford University Press", "hart": "H. L. A. Hart, The Concept of Law, 3rd ed., Oxford University Press"}, "stages": [{"id": "S1", "no": 1, "title": "法学基础与法律思维", "en": "Foundations of Law and Legal Thinking", "goal": "从零建立完整的法学知识框架：理解法律是什么、法律体系如何运作、核心概念的含义、法律与正义的关系，以及法治原则。", "modules": [{"id": "S1M1", "no": 1, "title": "法律是什么", "en": "What Is Law?", "lessons": [{"id": "S1M1K1", "title": "法律的定义与基本特征", "level": "core"}, {"id": "S1M1K2", "title": "法律与道德的区别", "level": "core"}, {"id": "S1M1K3", "title": "法律与习惯、宗教、社会规范的区别", "level": "fundamental"}, {"id": "S1M1K4", "title": "法律的强制性与规范性", "level": "core"}, {"id": "S1M1K5", "title": "法律的功能与社会作用", "level": "fundamental"}, {"id": "S1M1K6", "title": "法律与国家权力的关系", "level": "core"}]}, {"id": "S1M2", "no": 2, "title": "法律体系与法律渊源", "en": "Legal Systems and Sources of Law", "lessons": [{"id": "S1M2K1", "title": "法律体系的概念", "level": "core"}, {"id": "S1M2K2", "title": "成文法与不成文法", "level": "fundamental"}, {"id": "S1M2K3", "title": "宪法、法律、行政法规与判例", "level": "fundamental"}, {"id": "S1M2K4", "title": "法律渊源的层级", "level": "core"}, {"id": "S1M2K5", "title": "普通法与大陆法的基本区别", "level": "core"}, {"id": "S1M2K6", "title": "法律规范的结构", "level": "core"}]}, {"id": "S1M3", "no": 3, "title": "法律基本概念", "en": "Fundamental Legal Concepts", "lessons": [{"id": "S1M3K1", "title": "权利与义务", "level": "core"}, {"id": "S1M3K2", "title": "自由与责任", "level": "fundamental"}, {"id": "S1M3K3", "title": "法律主体", "level": "fundamental"}, {"id": "S1M3K4", "title": "法律人格", "level": "core"}, {"id": "S1M3K5", "title": "法律责任", "level": "core"}, {"id": "S1M3K6", "title": "法律效力", "level": "core"}, {"id": "S1M3K7", "title": "法律事实", "level": "fundamental"}, {"id": "S1M3K8", "title": "法律关系", "level": "core"}]}, {"id": "S1M4", "no": 4, "title": "法律与正义", "en": "Law and Justice", "lessons": [{"id": "S1M4K1", "title": "正义的概念", "level": "core"}, {"id": "S1M4K2", "title": "实体正义与程序正义", "level": "core"}, {"id": "S1M4K3", "title": "分配正义", "level": "core"}, {"id": "S1M4K4", "title": "矫正正义", "level": "core"}, {"id": "S1M4K5", "title": "平等原则", "level": "fundamental"}, {"id": "S1M4K6", "title": "法律公平与社会公平", "level": "fundamental"}]}, {"id": "S1M5", "no": 5, "title": "法治原则", "en": "The Rule of Law", "lessons": [{"id": "S1M5K1", "title": "Rule of Law 的含义", "level": "core"}, {"id": "S1M5K2", "title": "法律面前人人平等", "level": "fundamental"}, {"id": "S1M5K3", "title": "法律明确性与可预测性", "level": "core"}, {"id": "S1M5K4", "title": "司法独立", "level": "core"}, {"id": "S1M5K5", "title": "权力受到法律约束", "level": "core"}, {"id": "S1M5K6", "title": "程序正当性", "level": "core"}, {"id": "S1M5K7", "title": "法治与人治的区别", "level": "fundamental"}]}]}, {"id": "S2", "no": 2, "title": "法理学与比较法", "en": "Jurisprudence and Comparative Law", "goal": "深入理解不同法学流派，掌握世界主要法律体系与比较法方法，能够辨认并比较各家学说的核心主张。", "modules": [{"id": "S2M1", "no": 1, "title": "自然法理论", "en": "Natural Law Theory", "lessons": [{"id": "S2M1K1", "title": "自然法的思想起源", "level": "core"}, {"id": "S2M1K2", "title": "古希腊与罗马自然法思想", "level": "core"}, {"id": "S2M1K3", "title": "托马斯·阿奎那", "level": "core"}, {"id": "S2M1K4", "title": "格劳秀斯与现代自然法", "level": "core"}, {"id": "S2M1K5", "title": "现代自然法理论的复兴：富勒与菲尼斯", "level": "core"}, {"id": "S2M1K6", "title": "自然法与实在法的关系", "level": "debate"}, {"id": "S2M1K7", "title": "自然法理论的优势与批评", "level": "core"}]}, {"id": "S2M2", "no": 2, "title": "法律实证主义", "en": "Legal Positivism", "lessons": [{"id": "S2M2K1", "title": "法律实证主义的起源与主张", "level": "core"}, {"id": "S2M2K2", "title": "奥斯丁的命令理论", "level": "core"}, {"id": "S2M2K3", "title": "凯尔森的纯粹法学", "level": "core"}, {"id": "S2M2K4", "title": "哈特的法律规则理论", "level": "core"}, {"id": "S2M2K5", "title": "法律效力与道德正当性的区分", "level": "debate"}, {"id": "S2M2K6", "title": "法律实证主义的现代发展：拉兹", "level": "core"}, {"id": "S2M2K7", "title": "对法律实证主义的主要批评", "level": "core"}]}, {"id": "S2M3", "no": 3, "title": "法律现实主义与批判法学", "en": "Legal Realism and Critical Legal Studies", "lessons": [{"id": "S2M3K1", "title": "美国法律现实主义", "level": "core"}, {"id": "S2M3K2", "title": "斯堪的纳维亚法律现实主义", "level": "core"}, {"id": "S2M3K3", "title": "法官如何影响法律适用", "level": "core"}, {"id": "S2M3K4", "title": "法律与社会现实", "level": "fundamental"}, {"id": "S2M3K5", "title": "批判法学运动", "level": "core"}, {"id": "S2M3K6", "title": "法律与权力结构", "level": "debate"}]}, {"id": "S2M4", "no": 4, "title": "比较法基础", "en": "Foundations of Comparative Law", "lessons": [{"id": "S2M4K1", "title": "比较法的概念与研究方法", "level": "core"}, {"id": "S2M4K2", "title": "比较法的历史发展", "level": "fundamental"}, {"id": "S2M4K3", "title": "法律制度的分类", "level": "core"}, {"id": "S2M4K4", "title": "法律移植", "level": "core"}, {"id": "S2M4K5", "title": "法律趋同与法律分化", "level": "debate"}]}, {"id": "S2M5", "no": 5, "title": "世界主要法律体系", "en": "Major Legal Systems of the World", "lessons": [{"id": "S2M5K1", "title": "英美普通法系", "level": "core"}, {"id": "S2M5K2", "title": "欧洲大陆法系", "level": "core"}, {"id": "S2M5K3", "title": "德国法律传统", "level": "core"}, {"id": "S2M5K4", "title": "法国法律传统", "level": "core"}, {"id": "S2M5K5", "title": "北欧法律传统", "level": "fundamental"}, {"id": "S2M5K6", "title": "混合法律体系", "level": "core"}, {"id": "S2M5K7", "title": "宗教法与传统法的影响", "level": "core"}]}, {"id": "S2M6", "no": 6, "title": "比较法律制度", "en": "Comparative Legal Institutions", "lessons": [{"id": "S2M6K1", "title": "法院组织结构比较", "level": "core"}, {"id": "S2M6K2", "title": "判例制度与成文法制度", "level": "core"}, {"id": "S2M6K3", "title": "合同制度比较", "level": "core"}, {"id": "S2M6K4", "title": "财产权制度比较", "level": "core"}, {"id": "S2M6K5", "title": "侵权责任制度比较", "level": "core"}, {"id": "S2M6K6", "title": "刑事司法制度比较", "level": "core"}, {"id": "S2M6K7", "title": "法律解释方法比较", "level": "core"}]}]}, {"id": "S3", "no": 3, "title": "现代法哲学与深度研究", "en": "Modern Legal Philosophy and Advanced Study", "goal": "能够独立阅读法哲学经典，理解现代法律体系的理论基础，把握哈特之后的核心争论与当代议题。", "modules": [{"id": "S3M1", "no": 1, "title": "哈特的法律理论", "en": "Hart's Legal Theory", "lessons": [{"id": "S3M1K1", "title": "初级规则与次级规则", "level": "core"}, {"id": "S3M1K2", "title": "承认规则 Rule of Recognition", "level": "core"}, {"id": "S3M1K3", "title": "改变规则与裁判规则", "level": "core"}, {"id": "S3M1K4", "title": "法律体系的结构与存在条件", "level": "core"}, {"id": "S3M1K5", "title": "法律的开放性结构", "level": "core"}, {"id": "S3M1K6", "title": "法律的不确定性", "level": "debate"}, {"id": "S3M1K7", "title": "最低限度的自然法", "level": "core"}]}, {"id": "S3M2", "no": 2, "title": "法律与道德", "en": "Law and Morality", "lessons": [{"id": "S3M2K1", "title": "法律与道德是否必须分离", "level": "debate"}, {"id": "S3M2K2", "title": "法律的道德基础", "level": "core"}, {"id": "S3M2K3", "title": "恶法是否非法", "level": "debate"}, {"id": "S3M2K4", "title": "法律义务与道德义务", "level": "core"}, {"id": "S3M2K5", "title": "法律权威的正当性", "level": "core"}]}, {"id": "S3M3", "no": 3, "title": "法律解释与司法裁量", "en": "Legal Interpretation and Judicial Discretion", "lessons": [{"id": "S3M3K1", "title": "法律语言的模糊性", "level": "core"}, {"id": "S3M3K2", "title": "司法解释", "level": "core"}, {"id": "S3M3K3", "title": "法官自由裁量权", "level": "core"}, {"id": "S3M3K4", "title": "文义解释与目的解释", "level": "core"}, {"id": "S3M3K5", "title": "历史解释与体系解释", "level": "fundamental"}, {"id": "S3M3K6", "title": "法律原则与规则的关系", "level": "core"}]}, {"id": "S3M4", "no": 4, "title": "现代法哲学争论", "en": "Modern Debates in Legal Philosophy", "lessons": [{"id": "S3M4K1", "title": "哈特与富勒的争论", "level": "debate"}, {"id": "S3M4K2", "title": "哈特与德沃金的争论", "level": "debate"}, {"id": "S3M4K3", "title": "法律实证主义与自然法的冲突", "level": "debate"}, {"id": "S3M4K4", "title": "法律现实主义的挑战", "level": "core"}, {"id": "S3M4K5", "title": "法律与政治权力", "level": "core"}, {"id": "S3M4K6", "title": "现代法治的理论困境", "level": "core"}]}, {"id": "S3M5", "no": 5, "title": "当代法律议题", "en": "Contemporary Legal Issues", "lessons": [{"id": "S3M5K1", "title": "人工智能与法律责任", "level": "core"}, {"id": "S3M5K2", "title": "算法治理与法律监管", "level": "core"}, {"id": "S3M5K3", "title": "数据隐私与个人权利", "level": "core"}, {"id": "S3M5K4", "title": "数字时代的知识产权", "level": "core"}, {"id": "S3M5K5", "title": "国际人权法", "level": "core"}, {"id": "S3M5K6", "title": "全球化与法律秩序", "level": "core"}]}]}], "cases": [{"id": "C1", "title": "Marbury v. Madison", "zh": "马伯里诉麦迪逊", "court": "美国最高法院", "year": 1803, "theme": "司法审查"}, {"id": "C2", "title": "Brown v. Board of Education", "zh": "布朗诉教育委员会", "court": "美国最高法院", "year": 1954, "theme": "平等保护"}, {"id": "C3", "title": "Donoghue v Stevenson", "zh": "多诺霍诉史蒂文森", "court": "英国上议院", "year": 1932, "theme": "侵权法与注意义务"}, {"id": "C4", "title": "Entick v Carrington", "zh": "恩蒂克诉卡灵顿", "court": "英国王座法院", "year": 1765, "theme": "国家权力与个人自由"}, {"id": "C5", "title": "R v Jogee", "zh": "R 诉 Jogee", "court": "英国最高法院", "year": 2016, "theme": "共同犯罪与归责"}, {"id": "C6", "title": "Handyside v United Kingdom", "zh": "汉迪赛德诉英国", "court": "欧洲人权法院", "year": 1976, "theme": "表达自由与比例原则"}, {"id": "C7", "title": "Dudgeon v United Kingdom", "zh": "达奇森诉英国", "court": "欧洲人权法院", "year": 1981, "theme": "私人生活与道德立法"}]}, "lessons": {"S1M1K1": {"title": "法律的定义与基本特征", "EN": "The Definition and Nature of Law", "LEVEL": "core", "TAGS": "法的定义, 法律特征, 法理学入门", "TERMS": "法（Law）::由国家制定或认可、以国家强制力保证实施、调整人们行为的社会规范体系；法理学（Jurisprudence）::对法律的本质与运作进行系统反思的学科；规范（Norm）::规定应当如何行为的标准；制裁（Sanction）::违反规则时由国家施加的不利后果；规范性（Normativity）::规则以“应当”而非“描述”的方式指引行为;主权者（Sovereign）::奥斯丁理论中法律命令的来源", "SOURCE": "Wacks, Understanding Jurisprudence, ch.1；Hart, The Concept of Law, ch.1, ch.5；Siems, Comparative Law, Introduction", "terms": [{"term": "法（Law）", "def": "由国家制定或认可、以国家强制力保证实施、调整人们行为的社会规范体系"}, {"term": "法理学（Jurisprudence）", "def": "对法律的本质与运作进行系统反思的学科"}, {"term": "规范（Norm）", "def": "规定应当如何行为的标准"}, {"term": "制裁（Sanction）", "def": "违反规则时由国家施加的不利后果"}, {"term": "规范性（Normativity）", "def": "规则以“应当”而非“描述”的方式指引行为"}, {"term": "主权者（Sovereign）", "def": "奥斯丁理论中法律命令的来源"}], "sections": {"coreQuestion": "“法律是什么？”看起来是第一问，其实是法理学里最难回答的一问。我们每天都在和法律打交道——红灯停、签合同要履约、欠债要还钱——可一旦要给出一句能覆盖全部情形的定义，立即陷入困境。道德、宗教戒律、家族规矩、公司规章似乎也在告诉人该做什么，它们和法律到底差在哪里？如果答案只是“法律是国家定的”，那么国际法没有世界政府、习惯法没有成文条文，它们还算不算法律？本节要做的，是学会辨认法律这种社会现象的独特结构，理解为什么两千多年来最聪明的头脑仍为此争论不休；背下一个定义远远不够。", "definition": "在中文语境里，“法”与“法律”常有广狭之分：广义的“法”指一切具有规范性的社会规则体系，狭义的“法律”特指国家立法机关制定的规范性文件。本平台用“法律”（Law）指称一个更整体的现象：由政治权威制定或认可、以制度化方式实施、用以调整社会关系的行为规范体系。\n\n西方思想传统中，对法律的经典界定走过了几条不同的路。古罗马法学家乌尔比安（Ulpian）把法学定义为“神事与人事的知识，正义与不义的区分”。中世纪神学家托马斯·阿奎那（Thomas Aquinas）认为法律是“由关心共同体的人向共同体颁布的、以共同善为目标的理性的命令”。进入近代，功利主义思想家杰里米·边沁（Jeremy Bentham）与约翰·奥斯丁（John Austin）转向以“命令”界定法律：法律是主权者发布的、以制裁为后盾的命令，即“命令理论”（Command Theory）。\n\n twentieth 世纪最 influential 的转折来自 H. L. A. 哈特（H. L. A. Hart）。在《法律的概念》中，他把法律的核心放在“初级规则与次级规则的结合”（the union of primary and secondary rules）上，用以取代“命令”模型——初级规则直接规定人们该做什么或不该做什么，次级规则规定如何识别、改变和裁判这些初级规则。这个定义把法律从“暴力的命令”重新理解为“一套自我调整的社会规则制度”。Wacks 提醒我们，任何定义都服务于特定的理论目的，不存在一个对所有目的都同样适用的“法律”本质；要紧的是理解每种定义突出了法律的哪一面向，找到唯一正确的定义反倒无从谈起。", "history": "法律定义的演变，始终与西方社会政治结构的变迁同步。在古希腊，城邦（polis）的公民共同体观念催生了“法律是理性的命令”这一思路，法律与当时的宗教、习俗尚未清晰分离的。罗马帝国时期，万民法（ius gentium）与市民法（ius civile）的区分，让法学家第一次面对“不同民族有不同法律,但仍有某些共通原则”的比较法问题。\n\n中世纪欧洲，教会法与世俗法并存，法律的合法性最终被追溯到神的理性。近代民族国家兴起后，主权（Sovereignty）成为政治理论的核心概念，法律被重新理解为“主权者意志的产物”——奥斯丁的命令理论正是这一转向的产物，它试图把法律从道德和宗教中独立出来，使之成为可以被经验地研究的对象。\n\n到了二十世纪，两次世界大战与极权主义的经验，彻底动摇了“法律即命令”的信心：如果法律只是主权者的命令，那么纳粹德国的恶法是否也是“法律”？这一追问直接催生了哈特与富勒（Lon Fuller）的著名论战，也促使法理学在“法律实际上是什么”与“法律应当是什么”之间做出更精细的区分。理解法律的定义，必须把它放回这段思想史的脉络中。", "principle": "要把握法律的结构，可以从三个层次逐层推进。\n\n第一层，法律是一种规范（Norm）。规范不同于描述。描述告诉你“事实上发生了什么”，例如“昨天有人闯红灯”；规范告诉你“应当如何行为”，例如“不得闯红灯”。规范具有两个特征：它以“应当”（ought）的形式指引行为；当它被违反时，会引发批评或制裁。这一“应当”的维度，哲学上称为“规范性”（Normativity），是理解法律的第一把钥匙。\n\n第二层，法律是一种制度化的规范。道德、礼仪、习惯同样是规范，但法律的特殊性在于它由专门的机构（立法机关、法院、警察）以明确的程序制定、识别和强制执行。哈特强调，正是“次级规则”的出现——尤其是承认规则（Rule of Recognition）、改变规则（Rule of Change）与裁判规则（Rule of Adjudication）——把一个松散的“初级规则的社会”变成了真正意义上的法律体系（详见第三阶段第一模块）。\n\n第三层，法律具有“内部观点”（internal point of view）与“外部观点”（external point of view）两种面向。从外部看，法律是“某人做了某事就会遭受制裁”的经验规律；从内部看，法律是官员与公民共同接受的行为理由，人们用它来证成决定、批评他人。哈特认为，只从外部把法律理解为“威胁”是奥斯丁命令理论的根本缺陷——威胁能让人“不得不”做，却无法产生“有义务”做的规范体验。", "viewpoints": "围绕“法律是什么”，主要学说给出了不同的答案。\n\n自然法理论（Natural Law Theory）主张，法律与道德存在必然联系，一项严重违背正义的规则称不上真正的法律。其经典表述是“恶法非法”（lex iniusta non est lex）——这一命题在二战后被用来抨击纳粹政权的法律。\n\n法律实证主义（Legal Positivism）则坚持“法律与道德的分离命题”（Separation Thesis）：一项规则是否属于法律，取决于它是否被合法权威按照正确程序制定（即它的“来源”），而不取决于它是否道德。哈特的承认规则、凯尔森（Hans Kelsen）的基础规范（Grundnorm）、拉兹（Joseph Raz）的渊源命题（Sources Thesis），都是这一脉络的展开。\n\n法律现实主义（Legal Realism）把注意力从“书本上的法”转向“行动中的法”。美国现实主义者霍姆斯（Oliver Wendell Holmes Jr.）有句名言：“法律的生命不在逻辑，而在经验。”他们主张，真正决定案件结果的，往往是法官对政策与社会后果的判断，而非规则的机械适用。", "comparison": "把这几种学说并排看，可以更清楚地看到它们的分歧点。\n\n在“法律与道德的关系”上，自然法说“必然联系”，实证主义说“可以分离”,现实主义则干脆把道德争论还原为法官的个人偏好。在“法律的核心是什么”上，实证主义说是“规则体系”，现实主义说是“法官实际做的事”,自然法说是“实现正义的理性秩序”。\n\n需要警惕一种常见的误解：认为实证主义主张“法律不需要道德”或“恶法也是好法”。这是一个粗糙的漫画化。哈特本人的立场要微妙得多：他承认法律与道德在事实层面常常相互渗透，也承认法律必须满足某些“最低限度的自然法”条件才能维持自身；他坚持的仅仅是，在概念上，“是不是法律”与“是不是道德上正当”是两个应当分开判断的问题。把这两件事分开，恰恰是为了更清醒地批判恶法——承认它是法律，然后说“正因为它有效力，我们更有道德义务抵抗它”。", "debates": "法理学史上关于法律定义的经典争论，集中在实证主义与自然法之间。二十世纪五十至六十年代，哈特与富勒围绕“法律与道德是否必须分离”展开论战。富勒认为，法律的内在道德（程序正义的最低要求）与法律的概念本身密不可分，纳粹法律之所以是“法律”而非“蛮力”，正因为它仍保留了形式上的一般性、公开性、不溯及既往等要素；哈特则回应，承认纳粹法律是“法律”不妨碍我们谴责它，把极端邪恶的规则排除出“法律”概念，反而会遮蔽我们对其性质的认识。\n\n这场争论没有胜负，但它确立了一个此后所有法理学都必须面对的坐标：任何法律理论都要交代自己如何处理“效力”（validity）与“正当性”（legitimacy）的关系。Wacks 将这场论战列为理解法理学的关键入口之一（见其书第2.10节）。", "case": "一个能帮助理解“法律作为制度化规范”的现实例子，是英国宪法惯例与传统。英国至今没有一部成文的《宪法典》，但没有人会说英国“没有宪法”。构成英国宪法的，是《大宪章》（Magna Carta, 1215）、《权利法案》（Bill of Rights, 1689）、一系列议会制定法、司法判例，以及大量不成文的宪法惯例（constitutional conventions）。这些惯例虽然不像制定法那样由法院强制实施，却被政治行为者普遍遵守，并被视为具有约束力。\n\n这个例子说明：把法律简单等同于“国家制定、法院执行的成文规则”是不完整的。法律体系的边界比想象中更模糊，法律与非法律的社会规范之间存在广阔的中间地带。", "caseAnalysis": "就英国宪法而言，事实是：不存在单一的宪法文件；争议焦点是：不成文的惯例是否属于“法律”的一部分；从哈特的框架看，英国宪法惯例之所以具有规范性，是因为它们在官员群体中被从“内部观点”接受为正当的行为标准，尽管它们缺乏严格的法律制裁。这一案例的理论意义在于，它同时展示了法律的制度性（有专门机构与程序）与法律的开放性（边界并非泾渭分明）。\n\n它提醒学习者：法律的“定义”给不出一句可以背下来的句号，它是一组需要反复权衡的特征——规范性、制度性、强制性、开放性。不同理论强调不同特征，形成了我们后面要逐一学习的各种法学流派。", "summary": "法律是一种制度化的社会规范体系，它通过规则来指引行为，并以国家强制力为后盾，但它的本质远不止“命令”或“威胁”。理解法律，关键是把握三层结构：它是规范（以“应当”指引行为）、它是制度（有专门的制定与实施机构）、它有内外两种观点（既是从外部可观察的行为规律，也是从内部被接受的行为理由）。围绕“法律是什么”，自然法、实证主义、现实主义给出了不同答案，它们的分歧集中体现在法律与道德的关系、法律的核心要素两个问题上。本节给出的结论只是一个坐标，算不上一句定义——接下来所有法学理论，都可以在这个坐标系中找到自己的位置。", "furtherThinking": "1. 如果你认同一项严重不正义的规则“仍然是法律但不应被遵守”，你更接近哪个学派？如果把“不正义”作为“不是法律”的理由，又会遇到什么困难？\n2. 国际法没有世界政府、没有国际警察，为什么我们仍称它为“法律”？这对“法律＝主权者命令”的定义提出了什么挑战？\n3. 在一个算法自动做出决定的社会里，当规则由代码写成、由机器执行，“法律”的规范性会发生什么变化？"}, "en": "The Definition and Nature of Law", "level": "core", "tags": "法的定义, 法律特征, 法理学入门", "source": "Wacks, Understanding Jurisprudence, ch.1；Hart, The Concept of Law, ch.1, ch.5；Siems, Comparative Law, Introduction", "id": "S1M1K1"}, "S1M1K2": {"title": "法律与道德的区别", "EN": "The Distinction Between Law and Morality", "LEVEL": "core", "TAGS": "法律与道德, 分离命题, 哈特-富勒论战, 法律道德主义", "TERMS": "分离命题（Separation Thesis）::法律是否为法律取决于其社会来源而非道德价值；自然法理论（Natural Law Theory）::主张法律与道德存在必然联系的学说；法律实证主义（Legal Positivism）::以社会事实而非道德价值识别法律的学说；内在道德（Internal Morality of Law）::富勒提出的法律在程序上应满足的八项要求；恶法非法（lex iniusta non est lex）::严重不正义的规则不成其为法；法律道德主义（Legal Moralism）::主张国家可以用刑罚强制执行主流道德的立场；伤害原则（Harm Principle）::密尔主张只有防止伤害他人才能正当地干涉自由；最低限度的自然法（Minimum Content of Natural Law）::哈特承认法律必须满足的若干生存条件", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.10, ch.3；Hart, The Concept of Law, ch.1, ch.5, ch.9；Fuller, The Morality of Law, ch.3；Siems, Comparative Law, Introduction", "terms": [{"term": "分离命题（Separation Thesis）", "def": "法律是否为法律取决于其社会来源而非道德价值"}, {"term": "自然法理论（Natural Law Theory）", "def": "主张法律与道德存在必然联系的学说"}, {"term": "法律实证主义（Legal Positivism）", "def": "以社会事实而非道德价值识别法律的学说"}, {"term": "内在道德（Internal Morality of Law）", "def": "富勒提出的法律在程序上应满足的八项要求"}, {"term": "恶法非法（lex iniusta non est lex）", "def": "严重不正义的规则不成其为法"}, {"term": "法律道德主义（Legal Moralism）", "def": "主张国家可以用刑罚强制执行主流道德的立场"}, {"term": "伤害原则（Harm Principle）", "def": "密尔主张只有防止伤害他人才能正当地干涉自由"}, {"term": "最低限度的自然法（Minimum Content of Natural Law）", "def": "哈特承认法律必须满足的若干生存条件"}], "sections": {"coreQuestion": "『杀人偿命』『欠债还钱』既是法律命令，也是多数人认可的道德准则；于是很多人自然地把法律和道德当作同一件事的两种说法。可是仔细想想：蓄意杀人与正当防卫致人死亡，法律评价完全不同；合同违约通常只需赔偿，未必受到道德谴责；而某些不道德的行为——比如见死不救——在不少国家并不构成犯罪。法律与道德究竟在哪些层面上重合、又在哪些层面上分道扬镳？本节要回答的问题比『法律应不应该道德』这种口号更为精确：在识别『什么是法律』的时候，要不要把『它是否道德』当作必要条件？这个问题看似抽象，却直接决定了我们如何评价纳粹德国的恶法、如何思考同性行为的刑罪化，以及如何理解法官在疑难案件中的角色。", "definition": "道德（Morality）指关于善恶、正当与不正当的行为标准。Wacks 区分两类：一类是社会实际奉行的『社会道德』（social morality），另一类是批判现实制度的『理想道德』或『批判道德』（critical morality）。法律（Law）这里指由政治权威制定或认可、以制度化方式实施的行为规范体系。\n\n两者有真实的交叉：任何国家的刑法都禁止杀人、伤害、盗窃，这些禁令同时得到道德支持；法律和道德都使用『权利』『义务』『应当』这类词汇。但交叉不等于同一。法律实证主义的核心主张称为『分离命题』（Separation Thesis）：一条规则是否属于法律，取决于它是否由合法权威按正确程序制定或认可，即取决于它的社会来源，而不取决于它是否道德。哈特在 1957 年的霍姆斯讲座中把这一命题表述为『法律与道德之间不存在必然联系』（there is no necessary connection between law and morals）。\n\n需要立刻澄清：分离命题说的是『是不是法律』与『道德上正当不正当』是两个应分开判断的问题，而不是说法律可以不讲道德、司法者可以不关心道德。这是本节最容易被误读的地方。", "history": "在古代与中世纪，法律与道德并未清晰分开。托马斯·阿奎那（Thomas Aquinas）把法律定义为『由关心共同体的人向共同体颁布的、以共同善为目标的理性的命令』，在他那里，人法若背离理性与共同善就失去法的品格。这种自然法（Natural Law）思路统治了欧洲思想很久。\n\n近代民族国家兴起后，奥斯丁（John Austin）等人要建立一个可以被经验地研究的对象，于是把法律界定为主权者的命令，以制裁为后盾，刻意把道德问题排除出去。十九世纪的法理学由此形成了『法律是什么』（what law is）与『法律应当是什么』（what law ought to be）的分工。\n\n真正动摇这一分工的是二十世纪的极权主义经验。纳粹德国制定了许多程序上完全有效的法律，却服务于种族灭绝。如果法律只是『有效的规则』，我们还有没有语言去谴责它？带着这个困惑，哈特与富勒（Lon Fuller）在 1957—1958 年展开论战；紧接着，哈特又与德夫林勋爵（Lord Devlin）就刑法能否强制执行社会道德交锋。这两场论战奠定了此后所有讨论的坐标。", "principle": "第一层是识别标准的不同。道德规范的有效性来自其内容——它是否合乎正义、善或理性；法律规范的有效性在现代社会通常来自其来源——是否由有权的机关依程序制定。一把尺子量内容，一把尺子量出身，这是分离命题的要点。\n\n第二层是规范体验的不同。道德主要靠内心确信、良心谴责和社会舆论发挥作用；法律则以制度化机构（立法机关、法院、警察）和专门程序为后盾。哈特强调，从『内部观点』（internal point of view）看，法律人被训练成用规则来证成决定、批评他人；从『外部观点』（external point of view）看，法律表现为『做了某事就会遭受制裁』的经验规律。道德没有这样一套专门的官署、程序与职业共同体。\n\n第三层是评价维度的不同。说一条法律『有效』（valid），是在说它属于现行法律体系；说它『正当』（legitimate），是在作道德评价。两种评价可以分离：一条有效法律可能极不道德，一条道德上正当的主张可能尚未成为法律。把这两件事分开，恰恰使批判更精确——我们可以说『它在法律上有效，正因如此我们更有理由在道德上抵抗它』。\n\n第四层是哈特自己的限定。他承认法律与道德存在事实上的多重交叉，也承认法律必须满足『最低限度的自然法』（minimum content of natural law）才能维持自身——考虑到人类生存、身体脆弱、资源有限等基本事实，一个完全禁止杀人、完全不保护财产的规范体系很难长期运作。他还承认『法律的跳转』：一项道德原则只要被承认规则纳入，就成为法律原则。这些限定说明分离命题是一种概念上的谨慎，而非道德上的冷漠。", "viewpoints": "自然法理论一脉认为法律与道德有必然联系。阿奎那主张人法必须合乎自然法与共同善；当代的菲尼斯（John Finnis）在《自然法与自然权利》中继续这一路线；富勒则走了一条独特的程序路线，主张法律具有『内在道德』（inner morality of law）。\n\n法律实证主义一脉坚持分离命题。奥斯丁以命令、主权者、制裁三要素界定法律；凯尔森（Hans Kelsen）用基础规范（Grundnorm）构建一个纯粹规范的等级体系，把道德彻底逐出法学；哈特以初级规则与次级规则的结合取代命令理论；拉兹（Joseph Raz）提出渊源命题（Sources Thesis），强调识别法律只需追溯社会来源。\n\n在『刑法能否强制执行道德』这个问题上，德夫林勋爵代表法律道德主义：社会靠共享道德维系，严重不道德的行为即便在私人领域、未伤害他人，也可以被惩罚。哈特则以密尔（John Stuart Mill）的伤害原则（Harm Principle）回应，主张私人道德领域原则上不归法律管辖，尽管他本人承认法律可以有家长主义（paternalism）的空间——比如强制系安全带、戴头盔。", "comparison": "把两条路线并排看，分歧就清楚了。\n\n在『恶法的地位』上，自然法说『恶法非法』（lex iniusta non est lex），即严重不正义的规则不是法律；实证主义说『恶法亦法』——在效力意义上它仍是法律，但其道德缺陷构成抵抗的理由。在『研究对象』上，实证主义倾向于描述与分析既有的法律制度，自然法倾向于评价与批判。在『司法角色』上，强调分离的理论倾向于把法官看作适用既定规则者，强调联系的理论则更容易承认法官可诉诸道德原则。\n\n但要把对立说得更准确些。哈特与富勒的分歧并不在于『法律要不要道德』这种粗线条，而在于：富勒认为法律的概念本身就内含一套程序性的道德要求，违反到一定程度就不成其为法律；哈特则认为满足这些要求只是有效法律通常具备的特征，识别法律的概念标准仍然是社会来源。用哈特的比喻说，一把刀很钝仍是刀；富勒则倾向于说，钝到切不动东西的就不是刀了。", "debates": "第一场是哈特—富勒论战。1957 年 4 月，哈特在哈佛法学院发表霍姆斯讲座《实证主义与法律与道德的分离》，1958 年发表于《哈佛法律评论》；富勒同年以《实证主义与忠于法律——答哈特教授》回应。争论的导火索是战后西德的一个判例：一名德国妻子 1944 年向盖世太保检举丈夫发表诋毁希特勒的言论，丈夫被判死刑后改判赴俄国前线服役；1949 年妻子因『致使丈夫失去自由』被追诉，她以丈夫系依 1934 年纳粹法律被处罚为由辩护，法院仍判其有罪，理由是那项法律违背了『一切正派人的健全良知与正义感』。哈特认为法院判决错了，因为 1934 年的纳粹法律符合承认规则，是有效法律；富勒则认为纳粹『法律』严重背离道德，根本不成其为法律。值得注意的是，两人都更倾向于通过追溯立法来追究妻子的责任，而不是靠法院重新定义『法律』。\n\n富勒的正面主张是法律的『内在道德』：法律作为『使人类行为服从规则治理的事业』，必须满足八项程序性要求——一般性、公布、不溯及既往、明确、不矛盾、可行性、稳定性、官方行为与宣布的规则相一致。他用『雷克斯王』（King Rex）讲故事，说明违反了这些要求的统治者其实是在公布命令而非制定法律。哈特则反问：满足这些程序要求并不保证法律是正义的，南非种族隔离制度很可能也满足全部八项要求。\n\n第二场是哈特—德夫林论战。1957 年英国沃尔芬登委员会（主席为约翰·沃尔芬登爵士）建议将成年人之间自愿的私下同性行为与卖淫非罪化，其思路深受密尔伤害原则影响。1959 年德夫林在系列讲座中反驳：社会靠共享道德维系，道德纽带的松弛是社会解体的第一步，正如镇压颠覆活动是法律的事，镇压『恶习』同样是法律的事。哈特回击说，多元社会未必需要单一共享道德，宽容异端并不等于社会自杀；但他也承认法律可以在伤害原则上作有限扩张，以阻止明显的自我伤害。", "case": "最能说明争论分量的，还是前述战后西德的『告密者案』。事实本身不复杂：妻子借纳粹恶法陷害丈夫，战后却因这起陷害被审判。真正棘手的是法律形式：丈夫当年所受的处罚，确实有白纸黑字的法律授权，且该法律在形式上经过合法程序制定。\n\n争议焦点因此落在『用什么理由惩罚她』上——至于『妻子该不该受惩罚』，几乎所有人都认为她应受惩罚。法院选择了把那项纳粹法律逐出『法律』概念之外，宣称它违背正派人的良知，因而自始无效。这种思路更接近富勒。哈特认为这是用小聪明掩盖真实困难：如果承认它是法律，我们仍能说它极端邪恶、法官应尽量不去适用它；如果否认它是法律，我们反而掩盖了一个可怕的事实——那样的事情曾经以法律的名义发生。", "caseAnalysis": "从哈特的框架看，这个案子的结构是：事实层面，存在一个符合承认规则的纳粹制定法；效力层面，它在当时的法律体系内有效；正当性层面，它严重不道德。法院的做法是把第三层面的判断偷偷塞进第二层面，得出『它不是法律』的结论。哈特反对这种混淆，主张诚实面对：它有效，但它邪恶，正因为它披着法律外衣，后才更需要用明确的追溯性立法来清算。\n\n德夫林—哈特之争可以用同一个框架来看。德夫林把『社会是否认同这种道德』当作刑法合法性的根据，哈特则区分了『多数人反感』与『造成可识别的伤害』。哈特承认有些行为——比如当众重婚——因其公开性而伤害宗教感情，可以处罚；而私下成年人自愿的行为，仅仅因为别人『知道』而反感，不足处罚。这种区分至今仍影响各国的刑法改革。\n\n两个案例共同说明：法律与道德的区分不是书斋里的文字游戏，它决定了法院能否溯及既往地惩罚、国家能否把道德反感写成刑罚、公民是否有理由服从一项不正义的法律。", "summary": "法律与道德在内容上大量重合，但两者属于不同的规范类型。分离命题主张：识别法律靠社会来源，评价法律靠道德标准，二者应分开判断。自然法传统（阿奎那、富勒、菲尼斯）强调必然联系，实证主义传统（奥斯丁、凯尔森、哈特、拉兹）强调概念上的分离。哈特的贡献在于给出一种细致版本：他承认法律与道德在事实、目的、正义和效力承认上有多重连接，也承认最低限度的自然法要求，但坚持『是不是法律』与『是否正当』不能混为一谈。哈特—富勒论战与哈特—德夫林论战表明，这种区分无意于为恶法张目，也无意于为人类所有道德判断立法；它的用处在于让批判和改革有一个清晰的对象。", "furtherThinking": "1. 假设你在战后德国的法庭上，除了宣布纳粹法律『自始无效』和承认其有效但极端邪恶，还有第三种裁判方案吗？追溯性立法为何在法理上更可取？\n2. 哈特承认最低限度的自然法和法律的内在道德，这是否已经使『分离命题』名存实亡？分离命题的底线在哪里？\n3. 在多元社会中，如果多数群体的道德情感受到冒犯但没有可识别的伤害，刑法应当介入吗？请用哈特与德夫林各自的论据分别回答。"}, "en": "The Distinction Between Law and Morality", "level": "core", "tags": "法律与道德, 分离命题, 哈特-富勒论战, 法律道德主义", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.10, ch.3；Hart, The Concept of Law, ch.1, ch.5, ch.9；Fuller, The Morality of Law, ch.3；Siems, Comparative Law, Introduction", "id": "S1M1K2"}, "S1M1K3": {"title": "法律与习惯、宗教、社会规范的区别", "EN": "Law, Custom, Religion, and Social Norms", "LEVEL": "fundamental", "TAGS": "习惯法, 宗教法, 法律多元主义, 活法", "TERMS": "习惯（Custom）::长期反复实践而形成的、被共同体视为应当遵循的行为常规；社会规范（Social Norm）::群体内非国家制定却实际约束行为的标准；法律多元主义（Legal Pluralism）::同一社会中存在多个法律或规范秩序并存的状态；活法（Living Law）::埃利希提出的、实际支配社会生活而非见于法典的规则；宗教法（Religious Law）::以宗教经典与权威解释为依据的规范体系；活的习惯法（Living Customary Law）::未成文、仍在地方社会实际运行的习惯法", "SOURCE": "Wacks, Understanding Jurisprudence, ch.1, ch.8 §8.5；Siems, Comparative Law, ch.1, ch.8；Hart, The Concept of Law, ch.1, ch.7", "terms": [{"term": "习惯（Custom）", "def": "长期反复实践而形成的、被共同体视为应当遵循的行为常规"}, {"term": "社会规范（Social Norm）", "def": "群体内非国家制定却实际约束行为的标准"}, {"term": "法律多元主义（Legal Pluralism）", "def": "同一社会中存在多个法律或规范秩序并存的状态"}, {"term": "活法（Living Law）", "def": "埃利希提出的、实际支配社会生活而非见于法典的规则"}, {"term": "宗教法（Religious Law）", "def": "以宗教经典与权威解释为依据的规范体系"}, {"term": "活的习惯法（Living Customary Law）", "def": "未成文、仍在地方社会实际运行的习惯法"}], "sections": {"coreQuestion": "一个普通人一天之中会同时受多套规则支配：早晨按交通法开车，工作中遵守行业惯例，周末按宗教历法过节，家庭里遵循长幼有序的规矩。这些规则都在说『应当如何』，都在不同程度上约束我们，凭什么单独把『法律』挑出来？更进一步，如果一个社会里国家法、宗教戒律、部族习惯同时有效，我们是否还应该用『国家制定』作为法律的入场券？本节的任务是辨认法律与这些邻近现象之间的差别，同时说明为什么这种差别在今天反而越来越难维持。", "definition": "习惯（Custom）指长期反复实践形成的、被共同体视为应当遵循的行为常规，它通常没有成文文本，也不经过专门立法程序。宗教规范（Religious Norms）是以宗教经典与权威解释为依据的行为标准，如伊斯兰教法（Sharia）、犹太律法（Halakha）以及历史上的教会法。社会规范（Social Norm）是更宽泛的说法，涵盖礼仪、行规、家族规矩等一切非国家制定却实际约束行为的标准。\n\n埃利希（Eugen Ehrlich, 1862—1922）提出著名的『活法』（living law）概念：正式法律渊源只能呈现法律实际样态的一部分，真正在社会生活中支配人们行为的，是大量不成文的规则。Wacks 指出，这一概念与庞德（Roscoe Pound）的『行动中的法』（law in action）有相似之处，但批评者也指出埃利希未能说清活法与国家之间的关系。\n\n法律多元主义（Legal Pluralism）则指同一社会中存在多个法律或规范秩序并存的状态。Siems 在比较法中指出，在非西方国家，国家法往往只是诸多法律秩序中的一种；即使在西方，私人规制形式也日益受到关注。", "history": "早期社会的法律、宗教与习惯往往浑然一体，规范的正当性来自传统或神的意志。罗马法学家区分市民法（ius civile）与万民法（ius gentium），第一次意识到不同共同体的规则可以并存。中世纪欧洲教会法与世俗法并存，同一行为可能同时受两套管辖。近代民族国家兴起后，国家法逐渐取得压倒性地位：法律被等同于主权者制定或认可的规则，习惯与宗教规范被降格为『前现代』的残余。\n\n二十世纪发生了两次反转。一方面，哈特以『承认规则』为核心重建法律体系理论，把习惯纳入初级规则的范畴，却又指出缺乏次级规则的习惯社会无法发展为现代法律体系。另一方面，人类学、社会学与比较法学重新发现非国家规范的活力：埃利希的活法、法律多元主义、以及 Siems 对非洲与亚洲习惯法的研究，都表明『国家法即法律』只是一种特定历史情境下的看法。", "principle": "区分可以从四个层次逐层推进。\n\n第一，制度化程度不同。哈特指出，习惯与社会道德是『免疫于刻意改变』的：它们只能缓慢演化，没有人能在一夜之间修改一条习惯。法律则拥有专门机关——立法机关、法院、行政机关——能够有意识地识别、改变和适用规则。哈特用『制度化』一词概括这一转折：出现了有权识别、修改与执行规则的专门器官。他引用 Green 的概括：制度化带来的收益是适应性、确定性与效率，代价则是集中的权力可能被用来压迫那些无力支持它的群体。\n\n第二，强制方式不同。法律制裁由官方有组织地施加，具有可预测性；习惯与宗教规范的维系靠舆论、内心信念、群体排斥，通常是弥散而非集中的。当然，宗教社群也可能有组织化的惩戒，这一点提醒我们不要把『有制裁』当作法律的专利。\n\n第三，规则结构不同。哈特认为，仅有初级规则的社会是『初级规则的社会』：规则存在，但人们对『哪些规则有效』没有明确标准，争议无从权威地解决，规则也无法被有意识地改变。次级规则——承认规则、改变规则、裁判规则——的出现，才把一个松散的规范集合变成法律体系。值得注意的是，哈特承认承认规则本身在某种意义上是一种『司法习惯规则』，这说明法律与习惯的边界从来不是绝对的。\n\n第四，价值立场不同。宗教规范的正当性通常来自超越性来源；习惯的正当性来自延续与身份认同；现代国家法的正当性则更多来自制定程序与民主授权。三者发生冲突时，冲突的是正当性根基，而非仅仅内容。", "viewpoints": "Siems 在比较法中区分了四类习惯法，很有实用价值：一是『活的习惯法』（living customary law），即原始的、未成文、仍在地方层面实际运行的版本；二是『教科书习惯法』（textbook customary law），由学者或官员整理而成；三是『法典化习惯法』（codified customary law），由国家把习惯纳入立法；四是『司法习惯法』（judicial customary law），即法官在裁判中实际运用前三类习惯的方式。这个分类提醒我们：习惯一旦被国家承认或改编，其性质就已经发生变化。\n\nWacks 对法律多元主义持审慎态度。他引述 Tamanaha 的告诫：要避免两种相反错误——一是给国家法无条件的优先地位，二是假定其他规范体系与国家法处于平行地位。更稳妥的做法是具体考察每个规范体系与国家的实际关系。他还指出，法律多元主义最初的倡导者之一 Griffiths 后来放弃了这个概念，认为『规范多元主义』（normative pluralism）是更贴切的说法。", "comparison": "在规范来源上，国家法出自制定机关；宗教法出自经典与解释传统；习惯出自长期实践；社会规范出自群体互动。在改变方式上，国家法可通过专门程序迅速修改，其余三者通常只能渐变。在约束力来源上，国家法靠官方制裁与内部观点接受，宗教规范靠信仰与社群隶属，习惯靠传统与身份，社会规范靠舆论与面子。\n\n但相似之处同样重要：它们都调整行为、都用『应当』说话、都可能发生内容冲突。Siems 举出一个生动例子：伊斯兰教法禁止收取利息，这与现代银行业收取利息的做法直接冲突；集体所有权的观念也可能与银行以财产作抵押的贷款方式相抵触。这些冲突应当理解为不同规范秩序之间的价值冲突，而非『法律与非法法律』的对立。\n\n各国处理宗教规范与国家法关系的方式差异很大，不宜一概而论。美国联邦宪法第一修正案禁止确立国教，宗教规范主要作为个人信仰与社群自治事务存在；英国有国教会的历史传统，教会法院的某些职能至今留有痕迹；德国基本法保障宗教自由，同时国家法保持世俗性格。把三者说成同一种模式，是比较法的大忌。", "debates": "争论集中在：法律是否必须以国家为中心？传统实证主义倾向于肯定，认为没有承认规则就无法确定哪些规范属于法律。法律多元主义者则指出，在许多社会里，人们实际服从的规范并非国家法，若坚持国家中心主义，法学就会对真实的社会秩序视而不见。\n\n两派各有道理。国家中心主义的优势在于概念清晰，能够说明法律体系的统一性与可识别性；其弱点是对法律与社会生活的关系解释不足。多元主义的优势在于贴近经验现实；其弱点在于可能把一切规范都称为『法』，从而掏空法律概念。Wacks 的评述可作为平衡：国家法虽不处处强大，但通常极为重要，并且确实区别于其他竞争性的规范体系。更可取的研究策略，是具体考察各规范体系之间的联系、权威基础与实际被接受的程度，先不急于宣布何者为法。", "case": "一个可核实的例子来自比较法对习惯法的研究。Siems 指出，在非洲许多地区，西方继受的国家法与本土习惯法长期并存：大城市里国家法影响更大，农村地区习惯法可能仍占主导。同一块土地，国家登记簿上的所有权人与按家族传统主张权利的人可能并非同一人。他还提到，殖民政权曾把『活的习惯法』视为『不是真正的法律』，独立后的新领导人又常把它视为巩固全国权力的障碍。\n\n另一个例子是伊斯兰教法与现代金融的冲突：教法禁止高利贷（riba），而现代银行以利息为核心业务。一些国家通过金融创新寻求调和，另一些国家则形成了两套并行的金融规范。这两个例子都说明：规范冲突的解决，往往要靠制度设计安排两者的管辖范围；简单宣布其中一方『不是法』，于事无补。", "caseAnalysis": "就土地权利的例子而言，事实是：国家法与习惯法对同一资源给出不同归属规则；争议焦点是：哪一套规则应当被法院采纳；法律依据取决于具体国家的宪法与法律——有的国家承认习惯法的补充效力，有的国家只在特定领域承认；裁判理由通常要在统一法律秩序与尊重地方传统之间权衡。\n\n从哈特的框架看，关键在于承认规则如何界定有效法源：如果一国的承认规则把习惯列为法源，习惯法就是法律体系的一部分；如果没有，它就只是社会规范。从 Siems 的四分法看，问题还要再进一步：被法官采纳的习惯已经是『司法习惯法』，它未必等同于地方上实际通行的『活的习惯法』，甚至可能因脱离原有语境而失真。\n\n这个案例的理论意义在于：法律与习惯的界限是一套由承认规则、国家政策与社会实践共同划出的动态边界，而非一条固定的线。研究法律，不能只看法典，还要看法典之外实际运行的规则。", "summary": "法律与习惯、宗教、社会规范共享『应当如何』的形式，区别主要在制度化程度、强制方式、改变机制与正当性来源四个方面。哈特指出习惯社会缺乏次级规则，无法有意识地改变与裁判规则；埃利希提醒我们法典之外的『活法』才是社会真实运行的规则；Siems 的四类习惯法说明国家承认会改变习惯的性质；法律多元主义之争则提醒我们避免国家中心主义与概念泛化两种极端。理解这些区别，关键在于把『法律是什么』与『哪些规范值得服从』分开，同时承认二者之间存在广阔而变动的中间地带。", "furtherThinking": "1. 如果一国的承认规则明确把宗教经典列为法源，那么依据该经典作出的裁判是不是『法律』？哈特与法律多元主义者会如何分别回答？\n2. 埃利希的『活法』概念对法学研究有何贡献？为什么说它难以说明国家在活法形成中的作用？\n3. 在土地、婚姻、继承等领域，国家法与习惯法冲突时，应当优先保护法律统一性还是地方传统？请给出可操作的判断标准。"}, "en": "Law, Custom, Religion, and Social Norms", "level": "fundamental", "tags": "习惯法, 宗教法, 法律多元主义, 活法", "source": "Wacks, Understanding Jurisprudence, ch.1, ch.8 §8.5；Siems, Comparative Law, ch.1, ch.8；Hart, The Concept of Law, ch.1, ch.7", "id": "S1M1K3"}, "S1M1K4": {"title": "法律的强制性与规范性", "EN": "Coercion and Normativity in Law", "LEVEL": "core", "TAGS": "强制性, 规范性, 制裁, 义务与被迫, 授权性规则", "TERMS": "强制性（Coercivity）::法律以国家强制力为后盾而具有的约束性质；规范性（Normativity）::规则以『应当』而非描述的方式指引行为的性质；制裁（Sanction）::违反规则时由国家施加的不利后果；义务（Obligation）::被社会规则承认为应当履行、可受批评要求履行的事项；被迫（Obliged）::因受威胁而不得不做某事的状态；授权性规则（Power-conferring Rules）::赋予人们改变法律地位之能力的规则；基础规范（Grundnorm）::凯尔森理论中被预设为法律体系效力最终根据的规范；内部观点（Internal Point of View）::参与者把规则当作正当行为理由来接受的态度", "SOURCE": "Wacks, Understanding Jurisprudence, ch.3, ch.4；Hart, The Concept of Law, ch.1, ch.5, ch.6；Green 导论, The Concept of Law, 3rd ed.", "terms": [{"term": "强制性（Coercivity）", "def": "法律以国家强制力为后盾而具有的约束性质"}, {"term": "规范性（Normativity）", "def": "规则以『应当』而非描述的方式指引行为的性质"}, {"term": "制裁（Sanction）", "def": "违反规则时由国家施加的不利后果"}, {"term": "义务（Obligation）", "def": "被社会规则承认为应当履行、可受批评要求履行的事项"}, {"term": "被迫（Obliged）", "def": "因受威胁而不得不做某事的状态"}, {"term": "授权性规则（Power-conferring Rules）", "def": "赋予人们改变法律地位之能力的规则"}, {"term": "基础规范（Grundnorm）", "def": "凯尔森理论中被预设为法律体系效力最终根据的规范"}, {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作正当行为理由来接受的态度"}], "sections": {"coreQuestion": "提到法律，很多人第一反应是警察、监狱和罚款。可翻开任何一部法典，大量条文并不以惩罚相威胁：如何订立合同、如何成立婚姻、如何立遗嘱、法院如何组成——这些规则没有一条在说『否则罚款』。如果法律的本质真的是强制，这些规则算不算法律？反过来，如果法律只是『应当如何』的说教，它又凭什么比道德更有约束力？本节要拆开两个常被混为一谈的词：强制性（coercivity）与规范性（normativity），并回答一个关键问题——制裁在法律中究竟处于什么位置。", "definition": "强制性指法律以国家强制力为后盾的性质，最典型的表现是制裁（Sanction）：违反规则时由国家施加的不利后果，如罚金、监禁、赔偿。规范性（Normativity）则指规则以『应当』（ought）而非『是』（is）的方式指引行为：它告诉人们应当如何行动，并为批评与要求提供理由。\n\n哈特区分了两组极易混淆的概念。第一组是描述与规范：『昨天有人闯红灯』是描述，『不得闯红灯』是规范。第二组是义务（obligation）与被迫（obliged）：抢匪命令受害者交出钱包并威胁开枪，受害者是『被迫』交出；而纳税人依法纳税，是『有义务』纳税。哈特认为，把法律义务还原为被威胁后的被迫，是对法律性质的根本误解。\n\n授权性规则（Power-conferring Rules）是另一个关键概念：它们赋予人们改变法律地位的能力，如订立合同、成立婚姻、订立遗嘱的规则。这类规则的特点是：不遵守的后果落在达不到预期的法律效果上——合同不成立、婚姻无效、遗嘱不生效，惩罚并不出场。", "history": "近代法理学的开端几乎就是强制理论的胜利。边沁（Jeremy Bentham）与奥斯丁（John Austin）把法律理解为命令：奥斯丁的三要素是主权者的命令、习惯性服从、以制裁为后盾。Wacks 指出，边沁特别强调制裁与义务的连接——在他那里，制裁创造了法律义务，没有制裁的规则不是『完整的法律』。\n\n凯尔森（Hans Kelsen）在二十世纪上半叶提出纯粹法学，把法律界定为强制秩序。他把法律描绘为规范等级体系：每一级规范的效力来自更高一级规范，最终追溯到被预设的基础规范（Grundnorm）。基础规范有两个功能：使强制秩序能够被看作客观有效的秩序，从而区别于强盗的勒索；以及解释法律秩序的统一与无矛盾。\n\n转折发生在哈特。他在《法律的概念》第一章用『枪匪情境』（the gunman situation）做比喻，指出刑法典看起来像是『放大了的枪匪情境』，但这种化约经不起推敲。Green 在导论中进一步发挥：法律以制裁为『计划 B』，而『计划 A』是人民在无人监督的情况下自觉遵守；强制是法律权力的硬边缘，激励与表达则是它的软边缘。", "principle": "第一层，规范性的运作方式。规则与习惯性行为的差别在于：许多人每周都去看电影，这只是行为上的趋同；而『进教堂必须脱帽』是一条规则，因为偏离会引发批评。哈特强调『必须』『应当』这类词的规范功能，并把人们对规则的接受称为内部观点（internal point of view）——官员与公民用规则来证成决定、批评他人，而不是仅仅预测别人会做什么。\n\n第二层，强制性的准确位置。哈特并不否认法律常常有制裁，他否认的是制裁构成法律的本质。他的著名说法是：制裁是『计划 B』——当计划 A（自觉遵守）失败时才启动。美国法典中就有这样的规则：国旗『不应用作接收、持有、携带或递送任何物品的容器』，却没有规定违反的罚则。这类规范的存在说明，法律规则可以在没有制裁的情况下仍能指引行为。\n\n第三层，授权性规则的挑战。婚姻、合同、遗嘱规则提供的是一套『配方』：照着做，就能产生预期的法律效果；命令人们做什么并非其功能。不照做的结果是预期效果落空，并不会招来惩罚。哈特指出，把『无效』说成一种制裁是混淆：那里根本没有一道命令，所谓『制裁』不过是授权性规则本身。凯尔森曾试图挽救强制理论，说授权性规则只是法律的片段，制裁藏在别处——比如要求扶养配偶的规则。哈特的回应很精彩：这种重构在逻辑上并非不可能，问题在于缺乏动机，并且违背了法理学应当忠实于法律实践者实际如何使用规则的方法论约束。\n\n第四层，凯尔森的方案。基础规范是被预设的，其效力不来自另一条规范。Wacks 指出，凯尔森自己也说这是一种『法学假说』（juristic hypothesis）、一种『在本体论上中立的 methodological maxim』——它并非道德正当性的来源，只是理解法律秩序的前提。基础规范的选取取决于整个法律秩序是否『大体上』（by and large）有效。", "viewpoints": "奥斯丁把法律定义为主权者的命令，以制裁为后盾；主权者是多数人习惯服从、自己却不服从任何人的人。这个模型的优点是把法律从道德中独立出来，使之可被经验研究；缺点是解释不了国际法、宪法性规则与授权性规则，也解释不了人们对法律的义务体验。\n\n凯尔森用基础规范和规范等级体系重建了法律的统一性。他把法律与道德严格分离，并明确拒绝把国家理解为置于法律之上的独立实体——在他看来，法律与国家在本质上都是强制秩序。\n\n哈特以规则理论取代命令理论：法律是初级规则与次级规则的结合，次级规则中的承认规则解决『哪些规则有效』，改变规则解决『如何修改』，裁判规则解决『谁有权裁判』。哈特承认法律需要某种最低限度的社会事实条件，也承认制裁在法律体系中的普遍存在，但拒绝把强制当作法律的核心。\n\nGreen 的评述可作为补充：非强制性法律并非无所作为，它们同样表达和引导社会权力；例如曾经把异族或同性婚姻规定为无效的规则，并没有『强制』谁，却成功地塑造了个人生活与公共文化。", "comparison": "命令理论与规则理论的分歧，可以浓缩为一个问题：法律首先是『某人命令你做事』，还是『一套可供遵循和使用的规则体系』？在命令理论里，法律的身份来自命令者的地位；在规则理论里，法律的身份来自承认规则所确立的社会实践。前者能解释刑法，却解释不了授权性规则；后者能解释完整的法律体系，但需要说明承认规则本身的性质——哈特承认它最终是一种社会事实，接近于官员群体中的习惯。\n\n凯尔森与哈特虽然同属实证主义，处理强制问题的方式却不同。凯尔森坚持法律本质上是强制秩序，用基础规范把授权性规则『兜回』强制体系；哈特则认为这种重构虽然可能，却没有必要，并且扭曲了法律实践。两人分歧的实质，是法学理论应当以逻辑上的完美自洽为目标，还是以忠实描述法律使用者的实际理解为目标。\n\n还要区分两个常见误解。其一，『法律有强制性』不等于『法律就是暴力』——规范性的存在意味着法律提供的是可被援引、可被批评的理由，而非单纯的威胁。其二，『法律有规范性』也不等于『法律就是道德』——规范性只表示规则以『应当』方式运作，不表示它应当被道德赞许。", "debates": "最经典的争论是：法律的本质是不是强制？奥斯丁与凯尔森倾向于肯定，哈特明确否定。哈特的论据有三：其一，许多法律规则（授权性规则、宣告性规则）并不附带制裁；其二，即便在刑法领域，把法律化为威胁也解释不了义务体验——人们说『我有义务纳税』与说『我被迫交钱』，语义与实践中都不同；其三，命令模型无法说明法律的连续性——主权者更替后法律依然有效，因为有效性的根据是承认规则而非个人的意志。\n\n反过来，批评者指出哈特低估了权力。Green 承认哈特对『把无效当作制裁』的批评是对的，但认为这不应导致忽视授权性规则与社会权力的关联。法律即便不强制，也在分配能力、塑造激励、表达价值。这种批评起到的是提醒作用：强制性只是法律的一个维度，而非全部；哈特的理论并未因此被推翻。\n\n另一场争论涉及服从法律的道德义务。拉兹（Joseph Raz）主张，即便在正当的法律体系中，也不存在服从法律的初步道德义务；法治对拉兹而言是一种『消极德性』（negative virtue），它减少滥权风险，却不赋予法律独立的道德价值。自然法理论则倾向于认为，正当的法律能够产生服从的道德理由。这一争论表明，强制性与正当性的关系至今仍是开放问题。", "case": "两个例子能把抽象讨论落地。第一个来自美国法典：其中规定了如何尊重国旗，明确说国旗『不应用作接收、持有、携带或递送任何物品的容器』，却没有配套罚则。按奥斯丁的标准，这很难算『完整法律』；按哈特的标准，它仍是一条法律规则，因为它由有权机关依程序制定，并被官员与公民用作行为标准，只是属于不依赖制裁的那类。\n\n第二个例子是婚姻规则。规定什么样的人可以结婚、婚姻如何成立，是典型的授权性规则。历史上，一些法域曾把不同种族之间或同性之间的婚姻定为无效。哈特会说：这里并没有用刑罚强迫谁；它的做法是拒绝给某些人使用『婚姻』这一法律工具的能力。Green 补充说，这仍然在深刻地塑造社会生活——它传递了哪些关系值得法律承认的信号。", "caseAnalysis": "就国旗规则而言，事实是：有一条明确的成文规则，但没有罚则；争议焦点是：没有制裁的规则是否仍是法律；从哈特的框架看，它的法律效力来自承认规则对法源的确认，其规范性来自它被作为行为标准接受和使用，制裁的缺席并不取消这两点。这个例子直接支持『制裁是计划 B』的论断。\n\n就婚姻规则而言，事实是：不遵守配方不会受罚，只会使预期法律效果落空；争议焦点是：『无效』是否是一种制裁；哈特的答案是明确的——那里根本没有命令，因此也没有对不服从的惩罚，无效只是能力未获行使。凯尔森试图通过把授权性规则解释为『片段』来保留强制理论，但哈特认为这种解释没有实践动机。\n\n两个案例的共同理论意义在于：法律的规范性不等于强制性，强制性也不等于制裁。法律之所以『有约束力』，是因为它被制度化为一套可供援引、批评和使用的规则实践；制裁只是这套实践在失灵时启动的后备机制。", "summary": "法律的强制性指其以国家强制力为后盾，规范性指其以『应当』方式指引行为；两者相关但不可等同。奥斯丁把法律化为命令加制裁，凯尔森用基础规范把强制秩序解释为客观有效的规范体系，哈特则以初级规则与次级规则的结合取代命令模型。哈特的关键贡献在于区分义务与被迫、指出制裁只是『计划 B』，并说明授权性规则不靠惩罚运作。Green 进一步提醒：即便不强制，法律仍在表达和塑造社会权力。理解这一点，才能既不被『法律即暴力』的愤世嫉俗所困，也不被『法律即道德说教』的天真所误导。", "furtherThinking": "1. 如果一条规则完全没有制裁，也没有人被要求遵守它，它还能不能算法律？请借助哈特的承认规则与内部观点给出判断标准。\n2. 凯尔森的基础规范被称为『本体论中立的方法论准则』，这是否成功地把道德逐出了法学？如果基础规范的选择取决于法律秩序的实效，这是否意味着强力即正当？\n3. 拉兹说法治只是『消极德性』，你同意吗？请分别用自然法理论与实证主义的思路评估这一命题。"}, "en": "Coercion and Normativity in Law", "level": "core", "tags": "强制性, 规范性, 制裁, 义务与被迫, 授权性规则", "source": "Wacks, Understanding Jurisprudence, ch.3, ch.4；Hart, The Concept of Law, ch.1, ch.5, ch.6；Green 导论, The Concept of Law, 3rd ed.", "id": "S1M1K4"}, "S1M1K5": {"title": "法律的功能与社会作用", "EN": "The Functions and Social Role of Law", "LEVEL": "fundamental", "TAGS": "法律功能, 社会控制, 社会工程, 法律工作, 功能主义", "TERMS": "功能主义（Functionalism）::从法律对社会所起的作用来理解法律的进路；社会控制（Social Control）::社会引导成员行为、维持秩序的机制；社会工程（Social Engineering）::庞德把法律视为权衡利益、构建社会的工具；法律工作（Law Jobs）::卢埃林提出的法律在社会中承担的六项基本任务；法的行动（Law in Action）::实际运作中的法律，与书本上的法相对；恢复性法律（Restitutive Law）::以恢复原状而非惩罚为中心的法律类型", "SOURCE": "Wacks, Understanding Jurisprudence, ch.7；Siems, Comparative Law, ch.1；Hart, The Concept of Law, ch.1", "terms": [{"term": "功能主义（Functionalism）", "def": "从法律对社会所起的作用来理解法律的进路"}, {"term": "社会控制（Social Control）", "def": "社会引导成员行为、维持秩序的机制"}, {"term": "社会工程（Social Engineering）", "def": "庞德把法律视为权衡利益、构建社会的工具"}, {"term": "法律工作（Law Jobs）", "def": "卢埃林提出的法律在社会中承担的六项基本任务"}, {"term": "法的行动（Law in Action）", "def": "实际运作中的法律，与书本上的法相对"}, {"term": "恢复性法律（Restitutive Law）", "def": "以恢复原状而非惩罚为中心的法律类型"}], "sections": {"coreQuestion": "法律究竟『拿来做什么』？有人说它维护秩序，有人说它解决纠纷，也有人说它不过是统治阶级的工具。这些说法各自看到一部分真相，却很少说清法律的各项功能之间是什么关系。更麻烦的是，不同社会处理同一问题的方式可能完全不同：对『许诺被人信赖却未履行』，有的法域靠违约赔偿，有的靠宗教戒律，有的靠家族调解。如果功能相同而形式各异，比较法凭什么把不同制度放在一起研究？本节从功能角度审视法律：它对社会做了哪些事，这些功能之间有无冲突，以及功能视角本身的限度在哪里。", "definition": "功能主义（Functionalism）是从法律对社会所起的作用来理顺法律现象的进路，它的基本假设是：社会要存续，某些基本需求必须被满足，法律正是满足这些需求的一种制度安排。社会控制（Social Control）指社会引导成员行为、维持秩序的各种机制，法律只是其中一种——尽管在现代社会可能是最重要的一种。\n\n庞德（Roscoe Pound）引入『社会工程』（social engineering）的比喻：法律的任务是识别、保护各种利益，以最小摩擦与资源浪费满足尽可能多的利益。卢埃林（Karl Llewellyn）则用『法律工作』（law jobs）描述法律承担的任务。与这些功能视角相对，哈特提醒我们：法律虽然服务于目的，但它首先是一套规则实践——法律也有失灵和代价，并非天然有益。", "history": "功能视角在十九世纪末至二十世纪初的欧美法学中兴起，是对概念法学与形式主义的一种反动。在德国，耶林（Jhering）批评『概念法学』（jurisprudence of conceptions），主张法律要服务于社会目的。在美国，庞德与卢埃林分别以社会学法学和法律现实主义推动『书本上的法』（law in books）向『行动中的法』（law in action）转向。\n\n涂尔干（Émile Durkheim）从社会学角度提出，法律反映社会团结的形式：简单同质社会以机械团结与压制性法律为主，分工发达的社会则以有机团结与恢复性法律为主。Wacks 还提到滕尼斯（Tönnies）的共同体／社会二分，以及 Nonet 与 Selznick 的压制法／自主法／回应法三阶段说。这些理论共同把法律放回社会结构中理解。", "principle": "第一层是行为指引与协调。哈特晚年有一句概括：除了为人类行为提供指南和批评标准之外，很难再为法律找到更具体的目的。这意味着法律的首要功能是让人们在规划生活时能预期他人行为：知道合同会兑现、交通规则会被遵守、财产不会被任意夺取。\n\n第二层是纠纷解决。卢埃林认为法律最重要的工作就是『处理麻烦案件』（the disposition of trouble cases）：『就纠纷做点什么，并且做得合理，这就是法律的事业。』他列出的六项法律工作是：调整麻烦案件；预防性地引导行为与预期；预防性地重新引导行为与预期以适应变化；分配权威并确定决策程序；在群体内提供方向与激励；以及『法学方法的工作』。\n\n第三层是社会控制与规划。Green 指出，法律作为社会控制的主要功能，并不主要体现在法庭上的诉讼，而体现在法庭之外法律被用于控制、引导和规划生活的多种方式。这一点把法律从『打官司的学问』扩展为『组织社会的学问』。\n\n第四层是社会变迁的工具。法律既能巩固既有秩序，也能推动改革：通过立法改变权利分配、通过宪法保障新群体、通过行政规制应对新问题。庞德用『文明社会的法理学假设』（jural postulates）来说明法律如何随社会变化而调整。\n\n第五层是表达与象征。法律不仅分配资源，也表达价值：把某种关系承认为婚姻、把某种行为定为犯罪，都在传递社会评价。非强制性的法律同样在做这件事。\n\n第六层是代价与失灵。哈特引用 Green 的概括：制度化带来适应性、确定性与效率的收益，代价则是集中权力可能被用于压迫；法律还面临『法律主义』（legalistic）的风险——变得技术化、晦涩、远离被治理者的生活。法律并非无条件的好东西。", "viewpoints": "庞德把法律看作社会工程：利益是个人或群体寻求满足的需求，法律通过赋予权利来保护利益；冲突的利益要在『同一层面』上权衡。他的目标是以最小摩擦满足最多利益。批评者认为这种分类过于人为、形式化。\n\n卢埃林的功能主义更为激进：法律是一台『有目的而无自身价值』的引擎。他的着眼点是制度实际做什么，而不是法律宣称什么。涂尔干则把法律与道德紧密联系起来：法律是社会道德的表达，在没有道德承诺支撑时，法律就不再成其为社会的一部分。\n\n哈特的态度更谨慎：法律确实服务于目的，但目的本身并不足以定义法律，也不能保证法律是正当的。拉兹甚至认为法治只是一种『消极德性』。这三种立场提示我们：谈法律的功能时，要区分『法律实际做了什么』与『法律应当做什么』。", "comparison": "功能主义与规范理论的区别在于提问方式：功能主义问『法律对社会起了什么作用』，规范理论问『法律应当是什么』。二者并不互斥，但不可混淆——描述功能不等于赞许该功能。\n\n在法律与其他社会规范的功能上，法律的特点是制度化、可变更、可预测；道德、宗教与习惯同样指引行为、维系团结，但缺乏专门机关与程序。Siems 的比较法强调：不同法域解决同一社会问题的方式可能差异巨大，关键是找到『功能等价物』（functional equivalents）而非拘泥于形式。\n\n还要区分法律的不同功能之间可能相互冲突：追求确定性可能牺牲个案公平；强化社会控制可能压制创新；表达道德立场可能引发群体对立。法律的功能是一组需要权衡的诉求，而非一张和谐清单。", "debates": "第一个争论是功能主义能否价值中立。庞德自称以科学方式分类利益，但批评者指出，所谓『社会工程』隐含着对某些利益的偏好；马克思主义者更直截了当地认为，法治与权利话语是掩盖权力关系的意识形态。Wacks 记载，Nagel 等人对『法律完全中立』的说法持怀疑态度。这一争论提醒我们：功能描述往往已经带有价值预设。\n\n第二个争论是法律对社会变迁的角色。一种观点认为法律是保守力量，把既有权力格局固定化；另一种观点认为法律是改革工具，民权立法与宪法权利的发展就是明证。较稳妥的回答是：法律在两种角色之间摆动，取决于谁控制立法程序、司法如何解释规则，以及社会运动能否把诉求转化为法律语言。", "case": "Siems 介绍过一个很有启发性的比较法教学案例：二十世纪八十年代斯坦福大学开设的『法律在截然不同的国家』课程，比较美国、中国、埃及和博茨瓦纳的法律制度。尽管差异巨大，课程仍以共同问题为线索，例如『一个许诺被作出、被信赖、却未被履行时，社会怎么办？』以及『一个有财产、有职位、有社会地位的人去世后，谁来继承这一切？』\n\n这个案例的方法论意义在于：这种做法先确定社会问题，再看不同制度如何回答，而不是从条文对比入手。它把法律理解为解决社会问题的一种方式，而非一套孤立的概念体系。", "caseAnalysis": "就『许诺被信赖却未履行』而言，事实是：各方对同一社会问题给出不同答案；争议焦点是：这些不同答案能否被放在同一框架下比较；Siems 的回答是肯定的——比较法的功能方法允许我们比较『功能等价物』，即便它们在形式上完全不同。\n\n从庞德的视角看，这里涉及个体信赖利益与交易安全的平衡；从卢埃林的视角看，法律在处理『麻烦案件』中显示其真实面貌；从涂尔干的视角看，不同社会因团结形式不同而发展出不同的责任方式。这个案例说明，功能视角既是一种研究工具，也是一把双刃剑：它让我们看到不同制度的共同点，却也可能低估形式背后的文化差异。", "summary": "法律的功能可以从六个层面理解：行为指引与协调、纠纷解决、社会控制与规划、社会变迁工具、价值表达、以及不可忽视的代价与失灵。庞德的社会工程、卢埃林的六项法律工作、涂尔干的法律与社会团结理论，分别从利益平衡、制度任务和社会结构角度提供了经典框架。哈特的贡献在于提醒我们：法律服务于目的，但目的不定义法律，也不保证其正当性。功能视角富有启发，但须警惕把功能描述混同于价值辩护，也要看到不同功能之间的张力。", "furtherThinking": "1. 卢埃林说法律是『有目的而无自身价值』的引擎，这个比喻的限度在哪里？能否用它解释宪法权利的价值？\n2. 庞德的利益分类被批评为过于人为。如果你是立法者，你会如何权衡『交易安全』与『弱势群体保护』这两类利益？\n3. 法律既能固化权力，也能推动改革。请各举一个例子，并说明决定法律扮演哪种角色的制度条件是什么。"}, "en": "The Functions and Social Role of Law", "level": "fundamental", "tags": "法律功能, 社会控制, 社会工程, 法律工作, 功能主义", "source": "Wacks, Understanding Jurisprudence, ch.7；Siems, Comparative Law, ch.1；Hart, The Concept of Law, ch.1", "id": "S1M1K5"}, "S1M1K6": {"title": "法律与国家权力的关系", "EN": "Law and State Power", "LEVEL": "core", "TAGS": "国家与法律, 主权, 权力分立, 法治, 违宪审查", "TERMS": "国家（State）::在特定领土上垄断合法强制力的政治组织；主权（Sovereignty）::最高、独立、不受更高权威支配的权力；权力分立（Separation of Powers）::立法、行政、司法权由不同机关行使的制度安排；法治（Rule of Law）::权力行使须受一般、公开、稳定规则约束的理念；法治国（Rechtsstaat）::德国传统中受法治保障、提供法律安全国家；违宪审查（Judicial Review）::由法院审查法律是否符合宪法的制度；基础规范（Grundnorm）::凯尔森理论中被预设的法律体系效力根据", "SOURCE": "Wacks, Understanding Jurisprudence, ch.3, ch.4, ch.7；Siems, Comparative Law, ch.8；Hart, The Concept of Law, ch.5, ch.6", "terms": [{"term": "国家（State）", "def": "在特定领土上垄断合法强制力的政治组织"}, {"term": "主权（Sovereignty）", "def": "最高、独立、不受更高权威支配的权力"}, {"term": "权力分立（Separation of Powers）", "def": "立法、行政、司法权由不同机关行使的制度安排"}, {"term": "法治（Rule of Law）", "def": "权力行使须受一般、公开、稳定规则约束的理念"}, {"term": "法治国（Rechtsstaat）", "def": "德国传统中受法治保障、提供法律安全国家"}, {"term": "违宪审查（Judicial Review）", "def": "由法院审查法律是否符合宪法的制度"}, {"term": "基础规范（Grundnorm）", "def": "凯尔森理论中被预设的法律体系效力根据"}], "sections": {"coreQuestion": "我们常说『国家制定法律』，可又说『法律面前人人平等』、『依法行政』。前者把法律当作国家的工具，后者却要求法律约束国家本身。这两句话是否矛盾？如果法律出自国家，国家凭什么要服从法律？反过来，如果法律高于国家，那法律又从何而来？这不只是概念游戏：它决定了法院能否宣布议会通过的法律无效、行政机关能否以国家利益为由突破程序、以及公民在多大程度上可以主张权利。本节要梳理法律与国家权力之间的双向关系，并通过比较不同国家的制度安排说明：答案往往取决于具体的宪制结构，而非一句抽象的原则。", "definition": "国家（State）在现代政治理论中通常指在特定领土上垄断合法强制力的政治组织。主权（Sovereignty）指最高、独立、不受更高权威支配的权力，近代由博丹（Jean Bodin）与霍布斯（Thomas Hobbes）系统阐述。权力分立（Separation of Powers）指立法、行政、司法权由不同机关行使，并通过制衡防止权力集中。\n\n法治（Rule of Law）是要求权力行使受一般、公开、稳定规则约束的理念；德语传统中的法治国（Rechtsstaat）强调国家须提供法律安全。Wacks 指出，Kelsen 认为并非每个法律秩序都是法治国：一个相对集权、专制的强制秩序，只要不提供法律安全，仍是法律秩序、仍构成国家，但这不是一种政治价值判断。\n\n违宪审查（Judicial Review）指由法院审查立法是否符合宪法的制度。它在各国采取非常不同的形式，这一点后面会详细展开。", "history": "近代国家理论以主权为核心。霍布斯主张，人们为了避免自然状态下的恐惧，通过契约把权力让渡给主权者；主权者不受法律约束，因为正是他的意志构成了法律。奥斯丁（John Austin）在十九世纪把这一思路转化为法理学：法律是主权者的命令，主权者的特征是多数人习惯服从他而他不服从任何人。\n\n孟德斯鸠（Montesquieu）在《论法的精神》中系统阐述权力分立，主张权力若不受约束就会被滥用；洛克（John Locke）则主张有限政府与各分支之间的制衡。凯尔森在二十世纪上半叶做了一次彻底反转：他拒绝把国家理解为立于法律之上的独立实体，认为国家的机构、权力与职能都由法律界定，国家与法律秩序在本质上是一回事。\n\n二战之后，宪法审查与人权保障成为制度建设的重心。Siems 记载，德国、奥地利、意大利在战后由立法者引入或扩展了违宪审查，加拿大在 1982 年跟进，许多中东欧国家在后共产主义时代也建立了类似制度。Wacks 还提到哈贝马斯（Jürgen Habermas）关于现代主权形式的讨论，显示这一议题至今仍在演化。", "principle": "第一层，国家创造法律。从经验上看，现代法律主要由国家制定或认可：立法机关制定成文法，法院形成判例，行政机关发布规章，国家机器负责执行。没有国家机器，法律的制定与实施都缺乏组织载体。这是『法律是国家意志』这一说法的经验基础。\n\n第二层，法律塑造国家。凯尔森指出，国家的机构、权限与职能都由法律规定：何为议会、何为法院、谁有权宣战、谁有权征税，都是法律问题。在这个意义上，法律秩序构成了国家；『国家先存在然后创造法律』的叙述顺序被颠倒了。凯尔森甚至说，把国家等同于法律秩序，就无法再用法律去『证成』国家——因为国家本身就是法律秩序。\n\n第三层，法律的相对独立性。哈特通过承认规则说明：法律体系的存续取决于官员对规则的接受以及公民普遍的服从，而不是取决于某一统治者的意志。主权者更替、政府换届，法律秩序仍能延续。这使法律既依赖国家，又不完全等同于国家某一时刻的意志。\n\n第四层，权力分工与制约。法律不仅组织国家权力，还分割和限制它。立法权制定一般规则，行政权执行规则，司法权裁判争议。三权分立的核心是：任何机关都不能垄断全部权力，尤其是不能既制定规则又裁判自己是否违反规则。\n\n第五层，法治与合法性。法治要求权力受一般规则约束，但法治有两种理解。形式理解强调规则的一般性、公开性、不溯及既往、稳定与可执行；实质理解则要求法律内容符合正义或人权。拉兹（Joseph Raz）代表形式理解，并强调法治只是一种『消极德性』：它减少专断权力的风险，却不赋予法律独立的道德价值。\n\n第六层，违宪审查。当议会法律可能违反宪法时，由谁来裁判？这是法律与国家权力关系最尖锐的体现。Siems 指出，这里存在两种相反的理由：一方面，有限政府要求人权能够约束包括立法者在内的国家；另一方面，在民主社会里，『活跃』和『政治化』的法官不应挑战由议会优先所表达的民意。这个张力没有标准答案，各国制度选择差异很大。", "viewpoints": "奥斯丁把法律定义为主权者的命令，主权者自身不受法律限制——因为法律的身份恰恰来自他的命令。这一模型的清晰性很强，但它难以解释：为什么宪法能够约束立法机关？为什么国际法没有世界主权者却仍被称为法律？\n\n凯尔森以基础规范和规范等级体系取代意志论。基础规范是被预设的，不是由任何现实意志制定的；法律秩序的效力最终取决于它是否『大体上』有效。凯尔森明确拒绝国家高于法律，也拒绝用法律来『证成』国家——在他那里，国家与法律都是强制秩序，价值判断被排除在外。\n\n哈特从社会事实角度理解法律的根基：承认规则存在于官员的共同实践中。法律与国家的关系因此不是单向的：法律依赖官员的接受，官员的身份又由法律界定。这是一种循环，但不是恶性循环——它是任何制度都存在的一种自我指涉。\n\n洛克主张有限政府与分支制衡；孟德斯鸠主张权力分立；拉兹则对法治的价值保持低调，认为即便在正当的法律体系中，也不存在服从法律的初步道德义务。这些立场共同构成了现代宪制理论的谱系。", "comparison": "在『国家与法律谁先谁后』上，奥斯丁式思路是国家先于法律，法律是国家命令的产物；凯尔森式思路是二者同一，国家是法律秩序的人格化；哈特则提供一种实践论的答案：法律体系的存在依赖于官员与公民的规范性实践，国家与法律在这种实践中相互构成。\n\n在『如何对待议会立法』上，英美与欧陆呈现出不同模式，不能混为一谈。英国长期坚持相对严格的议会主权模式，对司法审查较为审慎；美国则由普通法院在个案中审查立法，Siems 记载美国最高法院在 1803 年的里程碑判决中确立了这一点；德国、奥地利、意大利在二战后建立了专门的宪法法院；法国最初类似英国，1958 年引入有限的抽象审查，2008 年允许公民提出宪法申诉。Siems 还指出，美国、瑞典、瑞士由同一法院处理宪法问题与其他法律问题，而奥地利、德国、法国、意大利设有独立的宪法法院或宪法委员会——后者建立在 Kelsen 的一个主张之上：普通法院只负责适用议会的法律，不负责评价它。\n\n需要强调：这些模式各有其历史成因，不能简单说哪一种『更先进』。议会主权模式强调民主授权，宪法法院模式强调基本权利的制度保障。", "debates": "第一个争论是主权是否受法律限制。奥斯丁的回答是否定的：主权者不可能受自己命令的约束。批评者指出，这一模型解释不了立宪主义的核心实践——宪法恰恰是对国家权力的法律限制。现代宪制国家的回答是：主权者可以受宪法约束，但约束的正当性最终仍需回到某种政治授权或制宪权理论。\n\n第二个争论是违宪审查的民主正当性。支持者认为，基本权利若不指派专门机关保护，就会沦为政治多数可以随意牺牲的装饰；有限政府要求法律制定者也受法律约束。反对者认为，由非民选法官推翻民选议会的法律，是『反多数难题』；议会之前的制衡机制已经足够。Siems 的梳理表明，这场争论在各国制度中留下了不同答案：有的国家由普通法院承担审查，有的国家设立专门宪法机关，有的国家仍维持议会主权。\n\n第三个争论是法治的价值。拉兹认为法治是消极德性，减少滥权却不担保正当；自然法传统则倾向于认为，符合法治的形式要求本身就有道德价值，因为它承认人的主体地位。Wacks 指出，对拉兹而言，即使在正当的法律体系中也不存在服从法律的初步义务——这一结论至今仍有争议。", "case": "比较法提供了一个清晰的制度图谱。Siems 记载：美国最高法院在 1803 年的里程碑判决中允许对初级立法进行司法审查；澳大利亚和以色列的法院也推进了审查；德国、奥地利、意大利在二战后由立法者引入或扩大审查；加拿大在 1982 年跟进；中东欧多国在后共产主义时代建立了类似制度。相反，英国仍遵循相对严格的议会主权模式，对司法审查较为犹豫；法国起初类似英国，1958 年引入有限的抽象审查，2008 年开放公民宪法申诉。\n\n在组织形式上，美国、瑞典、瑞士由普通法院一并处理宪法问题；奥地利、德国、法国、意大利则设立独立的宪法法院或宪法委员会。后一模式直接受 Kelsen 影响：普通法院只适用法律，评价法律的任务交给专门机关。", "caseAnalysis": "就事实而言，这些国家面对的是同一个问题：当议会立法可能与宪法或基本权利冲突时，谁有权作出有约束力的判断？争议焦点是民主正当性与权利保障孰轻孰重。从法律技术上看，各国选择了不同的解决路径：分散式审查由普通法院在个案中进行，优点是贴近具体争议，缺点是可能造成不同法院之间的分歧；集中式审查由专门机关进行，优点是统一与专业，缺点是可能脱离具体案件的事实语境。\n\n从理论上看，这些差异说明『法律约束国家权力』并不是一条可以脱离制度细节来谈论的原则。它必须通过具体的管辖权配置、法官选任程序、判决效力规则才能落实。凯尔森的影响尤其值得注意：他既主张国家与法律秩序同一，又设计了专门宪法法院的蓝图，把政治性的宪法判断集中化、法律化。\n\n这个案例的理论意义在于：法律与国家的关系是一组在历史中形成的制度解决方案，很难用单一命题概括。学习法理学，就是要理解每种方案背后的前提与代价。", "summary": "法律与国家权力是相互构成的关系：国家提供法律制定与实施的机器，法律则界定国家机构的存在、权限与程序。奥斯丁强调国家高于法律，凯尔森主张国家与法律秩序同一，哈特以承认规则说明二者在官员实践中的相互依赖。现代宪制通过权力分立与法治原则限制国家权力，而违宪审查制度的具体形态——美国 1803 年确立的普通法院审查、德国等国的专门宪法法院、英国坚持的议会主权——体现了民主正当性与权利保障之间的不同平衡。理解这种关系，关键在于摆脱『法律要么是国家工具、要么高于国家』的二选一，看到二者在具体制度中的复杂纠缠。", "furtherThinking": "1. 奥斯丁说主权者不受法律限制，现代宪法却宣称约束立法机关。这两种说法能否调和？如果能，需要引入什么理论前提？\n2. 由专门宪法法院审查立法（德国模式）与由普通法院在个案中审查（美国模式），哪一种更能兼顾法律统一与个案正义？请说明理由。\n3. 拉兹说即使正当的法律体系也不产生服从法律的初步道德义务。在宪法国家中，这一命题是否仍然成立？公民守法的道德理由究竟来自哪里？"}, "en": "Law and State Power", "level": "core", "tags": "国家与法律, 主权, 权力分立, 法治, 违宪审查", "source": "Wacks, Understanding Jurisprudence, ch.3, ch.4, ch.7；Siems, Comparative Law, ch.8；Hart, The Concept of Law, ch.5, ch.6", "id": "S1M1K6"}, "S1M2K1": {"title": "法律体系的概念", "EN": "The Concept of a Legal System", "LEVEL": "core", "TAGS": "法律体系, 承认规则, 次级规则, 法体系的存在条件", "TERMS": "法律体系（Legal System）::由初级规则与次级规则结合而成、具有统一识别标准的规范性制度整体；初级规则（Primary Rules）::直接规定人们应当做或不得做什么的行为规则；次级规则（Secondary Rules）::规定如何识别、改变与裁判初级规则的特殊规则；承认规则（Rule of Recognition）::官员据以识别哪些规则属于有效法律的共同标准；改变规则（Rule of Change）::授权特定机关制定、修改或废止法律规则的规则；裁判规则（Rule of Adjudication）::授权特定机关判断规则是否被违反并作出裁判的规则；内部观点（Internal Point of View）::参与者把规则当作正当行为标准来接受与使用的态度；法系（Legal Family）::依据法律历史、思维方法与实在法特征对各国法律体系所作的分类", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Hart, The Concept of Law, ch.6；Siems, Comparative Law, ch.3-4", "terms": [{"term": "法律体系（Legal System）", "def": "由初级规则与次级规则结合而成、具有统一识别标准的规范性制度整体"}, {"term": "初级规则（Primary Rules）", "def": "直接规定人们应当做或不得做什么的行为规则"}, {"term": "次级规则（Secondary Rules）", "def": "规定如何识别、改变与裁判初级规则的特殊规则"}, {"term": "承认规则（Rule of Recognition）", "def": "官员据以识别哪些规则属于有效法律的共同标准"}, {"term": "改变规则（Rule of Change）", "def": "授权特定机关制定、修改或废止法律规则的规则"}, {"term": "裁判规则（Rule of Adjudication）", "def": "授权特定机关判断规则是否被违反并作出裁判的规则"}, {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作正当行为标准来接受与使用的态度"}, {"term": "法系（Legal Family）", "def": "依据法律历史、思维方法与实在法特征对各国法律体系所作的分类"}], "sections": {"coreQuestion": "上一节我们把法律理解为一种制度化的规范。但单个规则还不足以构成我们日常所说的“法律体系”：一国之内有成百上千条规则，它们凭什么被认作同一个体系的一部分？新旧规则不断更替，凭什么说变化之后的法仍是“同一个”体系？更进一步，一个社会要满足什么最低条件，我们才可以说它“存在”一个法律体系，而不只是存在若干零散的规范？这些问题看似抽象，实则关乎我们如何理解法律的统一性、连续性与有效性。本节以哈特（H. L. A. Hart）的框架为主轴，说明法律体系无法化约为一堆规则的简单堆砌；它是初级规则与次级规则有机结合、并以承认规则为最终坐标的制度结构。同时也引入比较法上的“法系”概念，区分“一个法律体系”与“一类法律体系”这两个不同层次的问题。", "definition": "法律体系（Legal System）在法理学上有狭义与广义两种用法。狭义指一国或一个政治共同体内部实际运作的、由有效法律规则构成的规范整体；哈特在《法律的概念》第六章处理的正是这个意义上的法律体系。广义则把若干具有共同历史渊源的国家的法律归为一类，此时更常用的词是“法系”（Legal Family）或“法律传统”（Legal Tradition），例如大陆法系与普通法系。\n\n在哈特的狭义定义中，法律体系的核心命题是：它是初级规则（Primary Rules）与次级规则（Secondary Rules）的结合。初级规则直接规定行为——不得杀人、必须纳税、合同应当履行；次级规则则关于规则本身——规定哪些规则有效（承认规则）、如何修改规则（改变规则）、谁来判断规则是否被违反（裁判规则）。Wacks 概括得好：规则对于理解法律是必要的，但并不充分；我们还需要知道规则关于什么、被期待完成什么任务，以及那些不受规则支配的法律决定如何运作。因此哈特从不说法律“只是”规则的集合，他强调初级与次级规则的结合“处于法律体系的中心，但并不是全部”。\n\n由此可得出法律体系的三个可观察标志：规则的效力有统一的识别标准；规则可以被有意识地制定与改变；规则的适用与裁判由专门机关承担。三者分别对应承认规则、改变规则与裁判规则。", "history": "把法律理解为一个“体系”，是近代分析的产物。古代法律多以判例、习惯或王权命令的形态零散存在，缺乏“规则体系”的自我意识。罗马法学家第一次系统地把法律材料编排为体系，《国法大全》（Corpus Juris Civilis）就是这种体系化冲动的成果，它后来在中世纪欧洲被“继受”，成为超越国界的共同法（ius commune）。\n\n近代民族国家兴起后，主权（Sovereignty）观念要求在一国之内确立法律的统一来源，法律体系遂被理解为“主权者意志的系统表达”。奥斯丁（John Austin）的命令理论把这种理解推到极端：法律是主权者发布的、以制裁为后盾的命令，体系不过是命令的集合。二十世纪中期，哈特在批判命令理论的基础上重构了法律体系概念：他把焦点从“谁在命令”转向“规则如何被识别与运作”，从而把法律体系理解为一套自我调整的规范制度。\n\n在比较法层面，二兹维格特（Konrad Zweigert）与科茨（Hein Kötz）等人发展出“法系”分类，把世界法律按历史与思维方式的亲缘关系分组；Siems 则指出，“法系”观念近年影响有所减弱，但它仍是理解世界法律地图的重要工具。理论重心从“命令”到“规则体系”、再到“法系比较”的转移，正是本节概念的历史脉络。", "principle": "理解法律体系，可分三层推进。\n\n第一层是“从初级规则社会到法律体系”的跨越。哈特设想一个只有初级规则的前法律社会：规则靠社会压力维持，没有专门的制定机关，也没有判断机关。这种社会能运转，但有三重缺陷——规则的不确定性（不知哪些规则有效）、静态性（无法有意识地改变规则）、以及无效率的争端解决。次级规则正是对这三重缺陷的回应：承认规则消除不确定性，改变规则克服静态性，裁判规则提升争端解决的效率。哈特把这一跨越比作从“前法律的世界”迈入“法律的世界”，其代价是权力可能被集中组织起来用于压迫。\n\n第二层是承认规则的核心地位。承认规则是官员用来识别有效法律的共同标准。Wacks 依哈特指出，法律体系“存在”须满足两个条件：有效的义务规则被社会成员普遍遵守；官员从内部观点接受改变规则与裁判规则，并且从内部观点接受承认规则。承认规则本身不是由更高规则制定的，它以一种社会实践的方式存在——其存在条件就是它被实际遵循。这与交通靠右行驶的惯例类似：规则之所以能指引行为，正在于它被普遍遵守。\n\n第三层是内部观点与外部观点的区分。从外部看，法律体系只是“某人做某事后会遭受制裁”的经验规律；从内部看，它是官员与公民共同接受的行为理由与批评标准。哈特强调，承认规则必须被官员从内部观点接受，法律体系才能存在。Griffiths 式的“法律是官员的实践”这一洞见，使法律体系的重心从“暴力威胁”转向“制度化的规范接受”。", "viewpoints": "哈特的主张最为系统。他认为法律体系的“中心”是初级规则与次级规则的结合，其中承认规则是最关键的次级规则。他明确反对奥斯丁自上而下的金字塔式命令图景，也警惕另一种误解——以为法律体系是一台自动售货机，投入事实就吐出判决。哈特承认，上诉法院大量活动是在“解决有争议的案件”而非“适用确定的法律”，这完全可以容纳在他的理论之内。\n\nWacks 的阐述强调两点。其一，法律体系以“有效性”为核心组织概念：规则的效力来自另一条更有效力的规则，最终汇入承认规则。其二，法律体系有“代价”：制度化带来确定性、可变通性与效率，却也使中心化的权力可能被用来压迫那些无法提供支持的群体。因此法律并非天然善的，它的某些失败方式与其作为社会制度的本性紧密相连——法律可能变得“法律主义”（legalistic），技术化而远离被治理者的生活。\n\n在比较法一端，Siems 主张“法系”分类依据三个维度：法律史、法律思维与实在法特征。他把普通法系界定为以英国法为基础的法律体系，把大陆法系界定为受欧洲大陆传统影响的体系，并注意到法系概念在晚近的式微。这三种视角分别回答了“体系如何构成”“体系如何运作”“体系如何分类”三个不同问题。", "comparison": "把哈特与奥斯丁并排看，分歧十分清楚。奥斯丁以“命令＋主权者＋制裁”界定法律，体系是垂直的命令链；哈特以“规则＋承认”界定法律，体系是水平的规则实践网络。奥斯丁那里，法律效力源于统治者的实际支配；哈特那里，法律效力源于被接受的承认规则。前者的模型适合解释强制性，后者更适合解释义务的规范体验与法律的连续性。\n\n再与凯尔森（Hans Kelsen）比较。凯尔森用“规范层级”（hierarchy of norms）与基础规范（Grundnorm）解释体系统一：每一规范的效力来自更高规范，最终追溯到被预设的基础规范。哈特的承认规则与凯尔森的基础规范功能相近，都是效力的终极支点；区别在于，哈特把承认规则理解为可被经验观察的官员社会实践，凯尔森的基础规范则是一个理论预设（见 Wacks 第4.1节对二者的比较）。前者更“接地气”，后者更抽象。\n\n与“法系”概念比较时需注意层次差异：法律体系是单一共同体的规范整体，法系是若干法律体系的分类集合。把“大陆法系”当作一个法律体系，就像把“哺乳动物”当作一只动物——范畴层次错了。Siems 明确提醒，法律体系（law of a single country）与法系（legal families）不可混用。", "debates": "法律体系理论的核心争论，围绕“法律体系的统一性究竟建立在什么之上”展开。\n\n哈特一方的答案是：建立在承认规则这一社会实践之上。官员们实际共享的识别标准，使分散的规则凝结为“一个”体系；体系的存在是一个事实问题，而非价值问题。这延续了法律实证主义“法律与道德分离”的立场——一个有效运作的法律体系可能在道德上极其邪恶，但它在概念上仍是一个法律体系。\n\n富勒（Lon Fuller）一方提出挑战：法律体系不仅有“外在合法性”，还有“内在道德”（inner morality）。他列出法律体系的八项要求——一般性、公开性、不溯及既往、明确性、不矛盾、可遵守、稳定、官方行为与规则一致——并认为法律体系按其本性必须满足这些程序性要求。哈特回应说，这些要求能满足“形式合法性”，却无法保证实质正义；Wacks 也指出，南非种族隔离制度很可能满足富勒的八项要求，可见富勒的认可并不使一个法律体系免于批判。\n\n另一场争论来自德沃金（Ronald Dworkin）。他批评哈特把法律体系描绘为“规则模型”，遗漏了原则（principles）这一维度——法律体系不仅包含规则，还包含道德原则，法官在疑难案件中要依据原则作出“整体性的”（integrity）判决。哈特在《法律的概念》后记中回应，承认法律体系中确有原则，但坚持可以从承认规则的社会实践角度说明原则如何被识别。这场争论把“法律体系是什么”的问题，深化为“法律体系包含什么”的问题。", "case": "英国宪法的运作，是理解“法律体系”开放性的绝佳样本。英国至今没有一部名为《宪法》的单一法典，其宪法由《大宪章》（Magna Carta, 1215）、《权利法案》（Bill of Rights, 1689）、一系列议会制定法、司法判例以及大量宪法惯例（constitutional conventions）共同构成。这些成分形态各异：制定法是典型初级规则；议会主权原则与司法独立的运作依赖次级规则；而宪法惯例虽然不像制定法那样有严格法律制裁，却被政治行为者普遍遵守，并被视为具有约束力。\n\n这个例子说明，法律体系的边界比“国家制定、法院执行的成文规则”这一公式更宽。判断某物是否属于法律体系，要看它在体系中是否扮演可被承认规则识别的角色，而不只看它是否写在法典里。英国的例子也提醒我们，次级规则未必都以成文形式出现——承认规则常常就是隐含在官员实践中的标准。\n\n另一个对照是欧盟法律体系。欧盟法有自己的法院、自己的效力层级，却又依赖成员国的宪法秩序才得以生效，其承认规则处于“国家宪法秩序与国际法秩序之间”的独特位置。这类例子显示，法律体系并不总是与国家边界严丝合缝。", "caseAnalysis": "就英国宪法而言，可作如下结构化分析。事实层面：不存在单一宪法文件，规则来源多样。争议焦点：不成文的宪法惯例是否属于法律体系的组成部分。法律依据：哈特的框架提供识别标准——凡被官员从内部观点接受为行为标准、并能在裁判或政治实践中被援引者，皆可纳入体系的功能范围。\n\n裁判理由层面，英国法院在若干案件中确实援引宪法惯例来论证判决的正当性，尽管惯例本身通常不产生可诉的强制执行。这恰好印证了哈特关于“承认规则是一种社会实践”的命题：识别哪些规范属于体系，靠的是官员群体实际共享的标准，而非一张清单。\n\n理论意义在于，英国宪法同时展示了法律体系的统一性与开放性。统一性体现在：尽管来源多样，它们被共同当作“英国宪法”这一整体来谈论和运作。开放性体现在：体系的边界来自实践而非定义，因而会随实践缓慢移动。这个案例也说明了为何把法律体系等同于“成文法典”是站不住脚的——那种理解只能覆盖大陆法系法典化国家的部分经验，一旦放到英国或欧盟就失效。学习法律体系概念，关键在于掌握“规则＋承认标准”的结构，而不是记住某一国的制度外观。", "summary": "法律体系是初级规则与次级规则的结合，其统一性来自承认规则这一被官员从内部观点接受的社会实践。一个法律体系的存在须满足两个条件：有效规则被普遍遵守，官员接受改变规则、裁判规则与承认规则。哈特的框架把法律理解为自我调整的规范制度，区别于奥斯丁的命令链与凯尔森的基础规范预设；德沃金则提醒我们，体系中还有原则的维度。比较法上的“法系”是法律体系的分类集合，与之处于不同范畴层次。英国宪法的例子表明，法律体系的边界由实践划定，并不以成文与否为唯一标准。掌握“规则如何被识别、改变与裁判”这一主线，就掌握了理解一切法律体系的钥匙。", "furtherThinking": "1. 如果一个社会的官员群体对“哪些规则有效”各持己见、没有共享的识别标准，按哈特的说法它还算一个法律体系吗？这种“承认规则失效”的状态在法律史上出现过吗？\n2. 德沃金说法律体系包含原则，哈特说原则也要靠承认规则来识别。这两种说法的分歧是实质性的，还是可以用不同层次的描述来调和？\n3. 欧盟法既非国际法也非国内法，它的“承认规则”会不会属于多个共同体共享的叠合实践？这对“一个体系对应一个承认规则”的公式提出了什么挑战？"}, "en": "The Concept of a Legal System", "level": "core", "tags": "法律体系, 承认规则, 次级规则, 法体系的存在条件", "source": "Wacks, Understanding Jurisprudence, ch.4；Hart, The Concept of Law, ch.6；Siems, Comparative Law, ch.3-4", "id": "S1M2K1"}, "S1M2K2": {"title": "成文法与不成文法", "EN": "Statute Law and Unwritten Law", "LEVEL": "fundamental", "TAGS": "成文法, 不成文法, 判例法, 习惯法", "TERMS": "成文法（Statute Law）::由立法机关按法定程序制定并以文字形式颁布的法律；不成文法（Unwritten Law）::未以统一法典形式出现、而以判例、习惯或惯例形态存在的法律；制定法（Statute）::立法机关制定的单项规范性文件；判例法（Case Law）::由法院判决形成、可供后续案件援引的法律；习惯法（Customary Law）::由长期社会实践并形成法律确信的习惯性规则；法典化（Codification）::将某一法律领域的规则系统编排为统一法典的活动", "SOURCE": "Siems, Comparative Law, ch.3；Wacks, Understanding Jurisprudence, ch.1, ch.4", "terms": [{"term": "成文法（Statute Law）", "def": "由立法机关按法定程序制定并以文字形式颁布的法律"}, {"term": "不成文法（Unwritten Law）", "def": "未以统一法典形式出现、而以判例、习惯或惯例形态存在的法律"}, {"term": "制定法（Statute）", "def": "立法机关制定的单项规范性文件"}, {"term": "判例法（Case Law）", "def": "由法院判决形成、可供后续案件援引的法律"}, {"term": "习惯法（Customary Law）", "def": "由长期社会实践并形成法律确信的习惯性规则"}, {"term": "法典化（Codification）", "def": "将某一法律领域的规则系统编排为统一法典的活动"}], "sections": {"coreQuestion": "翻开德国民法典，你会看到一部结构严密、条文编号井然的法典；翻开英国的法律汇编，你却找不到一部包罗万象的“民法典”，裁判理由大量依赖于先前的判决。同属欧洲国家，为什么法律的“长相”差别这么大？成文法与不成文法的区分，表面上只是“写没写下来”，深层却牵涉法律从何而来、法官多大程度上可以造法、以及法律能否被有意识地改变等根本问题。本节要厘清这组概念的真实含义，避免把“不成文”误解为“不存在”或“不明确”。", "definition": "成文法（Statute Law）指由立法机关依法定程序制定、以文字形式颁布的法律。它的典型载体是制定法（Statute）与法典（Code）。不成文法（Unwritten Law）指未以统一书面法典形式呈现，而以判例（Case Law）、习惯（Custom）或宪法惯例（Constitutional Convention）等形态存在的法律。需要立即澄清两点。\n\n第一，不成文法不等于“没有文字”。英国判例有书面判决报告，习惯也可能被记录；“不成文”指的是没有一部系统编纂的权威文本，而非完全没有文字载体。\n\n第二，成文法不等于“法典”。Siems 指出，即使在美国这样的普通法国家，也存在成文的《统一商法典》（Uniform Commercial Code, UCC）以及加州等州的民法典；但这些成文法多为对既有判例的整理与体系化，与大陆法系那种追求“清晰、连贯、自足、完整”的法典在观念上并不相同。\n\n因此，成文法与不成文法的区分，关键在法律的“来源与表现形式”：一条规则的权威，是来自立法机关的制定行为，还是来自长期实践与司法判决的积累。", "history": "成文法与不成文法的分野，与两大法系的形成同步。大陆法系的成文法传统可追溯到罗马法。公元六世纪，东罗马皇帝查士丁尼（Justinian）主持编纂《国法大全》（Corpus Juris Civilis，533年），十一世纪欧洲大陆“继受”罗马法，大学学者推动了这一进程，故大陆法常被称为“学者的法”。十八、十九世纪民族国家兴起，各国把罗马法与地方习惯编纂为统一法典，1804年《法国民法典》与1900年《德国民法典》成为标志性成果。《法国民法典》追求“像圣经一样简单”的明晰，而《德国民法典》风格更概念化、更学院化。\n\n普通法则走另一条路。1066年诺曼征服后，威廉一世建立统一法院体系，以标准化令状（writs）为基础形成普通法。判决逐渐积累为判例，先例约束后案，形成判例法传统。Siems 引 Maitland 的名言概括其韧性：“我们埋葬了诉讼形式，它们却仍在坟墓中统治我们。”两种路径塑造了两种法律形态，也塑造了人们对“什么是法律”的不同直觉。", "principle": "成文法与不成文法各有其运作逻辑。\n\n成文法的核心逻辑是“预先设定”。立法机关在行为发生之前就以抽象条文规定权利义务，法官的任务是把条文适用于具体案件。这种模式的优势在于确定性与可预期性：公民可以事先查阅法条安排自己的行为。它适合表达“应当建立什么制度”的政策决定。\n\n不成文法的核心逻辑是“事后生长”。规则在案件裁判中逐渐形成，法官从既往判决中提取原则，再适用于新案。Siems 指出，普通法是“反应性”的——它“等待解释的契机”；由于缺乏系统性的法典，普通法法官强调具体案件事实的精细考量，Macmillan 勋爵称普通法为“一部适应人类生活万千差异的实用法典”。\n\n两者并非截然对立。现代各国法律体系几乎都是混合形态：大陆法系国家有大量单行立法与判例，普通法国家也有成文法与法典。真正的差别在于“重心”——成文法传统以法典为体系骨架，判例为补充；不成文法传统以判例为骨架，成文法为重要但相对次要的来源。Siems 强调，在普通法世界，制定法被视为某种“例外”，因而司法解释传统上较为狭窄；而大陆法法官则倾向于把论证锚定在法典之上。", "viewpoints": "从学者立场看，成文法与不成文法之争实为“法的确定性与法的适应性”之争。\n\n支持成文法的一方强调民主正当性与法的安定性。立法机关经民主程序制定规则，公民可事先知晓，法官的自由裁量受到约束。Siems 记述，《法国民法典》第5条曾明文禁止法官以一般性规则裁判案件，其背景是旧制度下法院以普遍规则阻挠改革；立法者追求严格分权，要求法律“按法典写下的原样适用”。\n\n支持不成文法的一方强调经验与适应力。普通法法官在个案中发展规则，能对社会争议作出回应。Siems 指出，普通法法官相对愿意在社会争议问题上展现司法创造性，并对经济学等社会科学论证持开放态度，其“市场智慧”受到赞扬。\n\n中间立场认为，两种形态各有短长，现代趋势是相互靠拢。Siems 观察到，大陆法法典解释已从早期机械的字面解释，转向考虑立法历史与目的的“注解方法”与“目的论方法”；而普通法的司法解释也从字面规则逐渐转向立法史与目的。两大传统在方法上正在趋同。", "comparison": "把两种法律形态并排看，差异集中在三点。\n\n在法的来源上，成文法以立法行为为效力依据，不成文法以司法判决与社会习惯为效力依据。这对应着哈特所说的改变规则与承认规则的不同运作方式。\n\n在法官角色上，成文法传统下法官主要是“适用者”，其创造性被谨慎对待；不成文法传统下法官同时是“造法者”，先例约束与司法创造并存。但须注意，Siems 提醒大陆法法官在解释制定法时其实拥有相当裁量空间，其方法被批评为“实证主义、机械、缺乏创造”，也可被同情地描述为“尊重立法者决定、以理性可预测的方式适用法律”。\n\n在体系形态上，成文法传统追求法典化与体系完整；普通法国家的法典多数只是既有判例的合并整理，体系化程度较低。Siems 举美国《统一商法典》为例，指出它受大陆法起草风格影响，但在普通法世界中属于例外。", "debates": "成文法与不成文法领域最持久的争论，是“法官是否应当被允许造法”。\n\n大陆法一端的经典立场是限制司法造法。《法国民法典》第5条禁止法官制定一般性规则，体现的是立法权与司法权严格分离的理念：法律的改变属于立法机关的职责。这一立场在十九世纪与概念法学的鼎盛期相呼应，人们相信法典是自足的理性体系，法官只需从事逻辑推演。\n\n普通法一端的立场则承认司法造法的正当性。先例约束原则（stare decisis）本身就意味着法官在造法——既往判决成为后续案件的法律来源。Siems 记述，英国法官愿意为社会争议建立政策，其对个人权利与自由的保护被认为阻止了政治权力的暴力侵入。\n\n争论的复杂性在于，两边都在向对方靠拢。大陆法国家承认，严格字面解释在多年前已被证明不可行，瑞士民法典第1条第2款甚至明文规定：法典没有相关规定时，法官依习惯法裁判，习惯法也没有时，依“他作为立法者会确立的规则”裁判。而普通法国家则通过成文法与法典（如 UCC）加强了体系化。结果是一场没有输赢的争论：分歧仍在，但双方都承认对方发现了自己忽略的问题。", "case": "一个便于理解的现实案例，是英国宪法与《大宪章》。英国没有成文宪法典，但《大宪章》（Magna Carta, 1215）、《权利法案》（Bill of Rights, 1689）等成文文件，与大量不成文的宪法惯例共同构成英国宪法。这些惯例虽无严格法律制裁，却被政治行为者普遍遵守，并在司法论证中被援引。这说明不成文的规范同样可能具有规范性，其约束力来自长期实践形成的共识，而非来自某次立法行为。\n\n另一个对照是美国《统一商法典》。它是成文法，却被所有州以细微修改采纳，成为普通法世界成文法运动的代表。Siems 指出，UCC 的起草受大陆法风格影响，且其内容大量是对既有商事判例的整理。这个例子说明成文与不成文的界限是流动的：一部成文法可能主要是判例的编纂，而一个不成文法传统也可能产出高度体系化的成文规则。", "caseAnalysis": "就英国宪法而言，可作如下分析。事实：不存在单一宪法文本，宪法由异质成分构成。争议焦点：不成文惯例是否属于法律。法律依据：从功能角度看，惯例在官员实践中被当作行为标准，并可在裁判中被援引。\n\n裁判理由层面，英国法院在相关案件中承认宪法惯例的正当性论证作用，尽管惯例通常不直接产生可强制执行的义务。这契合哈特关于承认规则是社会实践的观点：规范的体系身份，取决于它被实际识别与使用的方式。\n\n就 UCC 而言，事实是它以成文法形式出现；争议在于它究竟体现成文法逻辑还是判例法逻辑；答案在于它是判例的“整理”而非“重新设计”，故其解释仍深受判例思维影响。\n\n理论意义在于，两个案例共同表明：成文法与不成文法的区分是有用的分析工具，但不是贴在具体规则上的永久标签。判断一条规则的性格，要考察它从何取得权威、如何被解释、在整个体系中扮演什么角色。把“成文”等同于“现代”、把“不成文”等同于“落后”，都是站不住脚的线性史观。", "summary": "成文法由立法机关制定并以文字颁布，不成文法以判例、习惯与惯例等形态存在；“不成文”指没有系统编纂的权威文本，不等于没有文字或不明确。成文法逻辑重预先设定与法的安定性，不成文法逻辑重事后生长与适应性。两种形态在现代各国普遍混合，差别在体系重心。学者争论的焦点是法官造法的边界：大陆法传统限制司法造法，普通法传统承认先例的造法功能，而两大传统在方法上正相互靠拢。英国宪法与 UCC 的例子说明，成文与不成文的分界是流动的，判断规则性格要看其权威来源与体系角色。", "furtherThinking": "1. 一部主要由判例整理而成的成文法典（如 UCC），究竟应归入成文法还是不成文法？这个例子对“成文／不成文”二分法提出了什么挑战？\n2. 如果宪法惯例被法院作为裁判依据援引，它是否就“变成”了成文法？约束力与表现形式之间是什么关系？\n3. 在大陆法国家，判例虽非正式法源却在实践中被下级法院广泛遵循。这种“事实上的先例”与普通法系的先例约束，差别究竟有多大？"}, "en": "Statute Law and Unwritten Law", "level": "fundamental", "tags": "成文法, 不成文法, 判例法, 习惯法", "source": "Siems, Comparative Law, ch.3；Wacks, Understanding Jurisprudence, ch.1, ch.4", "id": "S1M2K2"}, "S1M2K3": {"title": "宪法、法律、行政法规与判例", "EN": "Constitution, Statute, Administrative Regulation and Precedent", "LEVEL": "fundamental", "TAGS": "宪法, 法律位阶, 行政法规, 判例", "TERMS": "宪法（Constitution）::规定国家根本制度与公民基本权利的最高法；法律（Statute）::由立法机关制定的规范性文件；行政法规（Administrative Regulation）::行政机关依法律授权制定的规范性文件；判例（Precedent）::可作为后续案件裁判依据的先前判决；司法审查（Judicial Review）::法院审查法律是否符合宪法的制度；议会主权（Parliamentary Sovereignty）::英国宪法中议会立法权至上的原则；违宪审查（Constitutional Review）::由特定机关判断法律是否违宪的制度", "SOURCE": "Siems, Comparative Law, ch.3, ch.8；Wacks, Understanding Jurisprudence, ch.4", "terms": [{"term": "宪法（Constitution）", "def": "规定国家根本制度与公民基本权利的最高法"}, {"term": "法律（Statute）", "def": "由立法机关制定的规范性文件"}, {"term": "行政法规（Administrative Regulation）", "def": "行政机关依法律授权制定的规范性文件"}, {"term": "判例（Precedent）", "def": "可作为后续案件裁判依据的先前判决"}, {"term": "司法审查（Judicial Review）", "def": "法院审查法律是否符合宪法的制度"}, {"term": "议会主权（Parliamentary Sovereignty）", "def": "英国宪法中议会立法权至上的原则"}, {"term": "违宪审查（Constitutional Review）", "def": "由特定机关判断法律是否违宪的制度"}], "sections": {"coreQuestion": "一个国家的法律不是平铺在同一平面上的。宪法、议会制定的法律、政府颁布的行政法规、法院作出的判例，它们的效力并不相同：当行政法规与法律冲突时，谁让路？当法律与宪法冲突时，又该听谁的？这些问题看似只是法条层级的排列，实则牵涉一国如何安排权力、如何保护权利、以及由谁来充当“最终裁判”。本节逐项梳理这四类法律形式，并以英美与欧陆的不同制度为对照，说明“位阶”难以被简化为一张通用表格，它其实是各国权力结构的投影。", "definition": "宪法（Constitution）是规定国家根本制度、权力配置与公民基本权利的最高法。其形式各国不同：美国有1787年制定的成文宪法典，德国有1949年的《基本法》（Grundgesetz），英国则没有单一成文宪法典，宪法由《大宪章》《权利法案》、制定法、判例与惯例共同构成。\n\n法律（Statute）在此指立法机关依职权制定的规范性文件。它是现代国家调整社会关系的主要形式，其效力仅次于宪法。\n\n行政法规（Administrative Regulation）指行政机关依法律授权制定的规范性文件。它之所以必要，是因为议会不可能事无巨细地规定一切执行细节，需要行政机关在法律框架内制定具体规则。其效力低于法律，不得与法律抵触——这是“法律保留”与“授权明确性”要求的体现。\n\n判例（Precedent）指可作为后续案件裁判依据的先前判决。在普通法国家，先例具有约束力（stare decisis）；在大陆法国家，判例通常不是正式法源，却在实践中被下级法院广泛参考。\n\n四类形式的关系可概括为：宪法居于顶端，法律次之，行政法规再次；判例的位阶则取决于法系——在普通法是正式法源，在大陆法多为事实上的权威而非形式上的法源。", "history": "宪法作为“最高法”的观念，近代才确立。美国1787年宪法是世界上第一部成文的国家宪法，它以“根本法”的姿态为普通法律设定边界，并提出了一个此前没有答案的问题：谁来判定普通法律是否违反宪法？1803年，美国最高法院在马伯里诉麦迪逊案（Marbury v. Madison, 5 US 137）中确立了司法审查（Judicial Review）制度，由法院宣告违宪的法律无效。Siems 指出，这一 landmark decision 此后影响了许多国家。\n\n欧陆走另一条路。凯尔森（Hans Kelsen）主张普通法院只应“适用”而不应“评价”议会法律，违宪审查应交给专门机关。二战后，德国、奥地利、意大利在美国的制度影响下建立了专门宪法法院；法国1958年引入有限制的抽象审查，2008年开放公民宪法申诉。英国则坚持严格的议会主权（Parliamentary Sovereignty），法院长久以来无权以违宪为由推翻议会的主要立法。\n\n行政法规的兴起与行政国家（administrative state）的成长同步。随着政府职能扩张，议会越来越多地通过授权法把细节规则交给行政机关制定，行政法规遂成为数量庞大的法律形式，也带来“授权是否过宽”“如何监督行政立法”等新问题。", "principle": "理解四类法律形式的关系，可从三条线索展开。\n\n第一条是效力层级（hierarchy of norms）。凯尔森提出，法律体系的效力是一条自下而上的链条：每一规范的效力来自更高规范，最终追溯到被预设的基础规范（Grundnorm）。Wacks 描述这一层级：最抽象的是基础规范，其下是历史上的第一部宪法，再下是立法与司法制定的较具体规范，直到最个别化的规范（如执法员有权扣押特定债务人的财产）。宪法高于法律、法律高于行政法规，正是这一层级结构的具体体现。\n\n第二条是权限分配。位阶背后是“谁有权制定什么”的问题。宪法由制宪权或修宪程序产生；法律由立法机关制定；行政法规由行政机关在法律授权范围内制定。授权理论要求：行政机关不能自我授权，其规则不得超越授权范围，否则无效。这便是“越权无效”原则。\n\n第三条是判例的特殊地位。判例与前三类不同——其权威并不来自某次“制定”行为；经由裁判的反复积累，它逐渐生长出来。在普通法系，判例是正式法源，先例约束后案；Siems 记述，普通法中“既往案件被视为有约束力的先例，法官适用的是自己制定出的法”。在大陆法系，判例不是正式法源，但法官职业生涯与案件负荷使其倾向于遵循上级法院的裁判，形成事实上的权威。", "viewpoints": "关于位阶安排，各国制度呈现不同取向。\n\n美国模式强调法院的审查权。自1803年马伯里案起，普通法院即可在个案中审查法律是否违宪。Siems 指出，美国、瑞典、瑞士等国由同一套法院同时处理宪法问题与其他法律问题（分散式审查）。\n\n欧陆模式强调专门机关。德国、奥地利、法国、意大利设立独立的宪法法院或宪法委员会，其理论基础正是凯尔森关于普通法院只适用不评价的主张。Siems 指出，这种模式的后果包括宪法法院法官任命需特殊程序，且并非所有宪法法官都必须是法律职业者。\n\n英国模式强调议会至上。英国遵循相对严格的议会主权模型，法院对议会立法的审查持克制态度。这一立场近年有所松动，但基本格局未变。\n\n就判例而言，普通法国家把判例视为主干法源，成文法反而常被视为例外；大陆法国家以法典为主干，判例起补充作用。Siems 强调，两种模式在方法上正相互靠拢：大陆法解释转向目的论，普通法解释也日益重视立法史与目的。", "comparison": "把四类形式并排比较，可见三个关键差异。\n\n在效力来源上，宪法来自制宪权，法律来自立法权，行政法规来自被授权的行政权，判例来自司法裁判的权威。四者对应四种不同的权力，位阶排列实则反映了权力之间的等级关系。\n\n在变更难度上，宪法最难变更（常需特别多数或复杂程序），法律次之（普通立法程序），行政法规最易（行政程序）；判例则通过“推翻先例”逐渐演变，其变更由法院自身完成。\n\n在审查机制上，对行政法规的审查通常由普通法院进行；对法律的合宪性审查各国差别最大——美国由普通法院附带审查，德国由宪法法院集中审查，英国传统上由议会自我把关。Siems 指出，法国自1958年起实行有限制的抽象审查，2008年起公民可提出宪法申诉，显示审查机制处于演变之中。\n\n一个重要对照：在普通法国家，“判例”与“成文法”的关系是“主干与补充”；在大陆法国家则相反。但这并不意味普通法国家没有法律位阶——成文法一旦制定，其效力通常高于判例，法院须适用成文法。位阶与法源类型是两回事，不能混为一谈。", "debates": "本领域最经典的争论，是“法院应否有权审查议会立法”。\n\n支持司法审查的一方从有限政府与人权保障出发：既然宪法是最高法，就需要有人确保普通法律不越界；Siems 指出，在民主制度中，权利保护不能只靠选举，还需要事前的分权制衡与事后的司法审查。美国1803年确立司法审查，二战后德国、奥地利、意大利、加拿大（1982年）等国相继引入，往往受美国影响。\n\n反对或谨慎的一方从民主正当性出发：议会是人民意志的表达，让“ activist、政治性的法官”推翻议会立法，可能侵蚀民主。Siems 把英国描述为对司法审查“较为犹豫”的典型，坚持严格的议会主权；法国长期持类似立场，直到1958年才引入有限审查。\n\n凯尔森提供了第三种思路：把审查权交给专门宪法法院，既避免普通法官过度政治化，又使宪法获得专门守护。这一模式为战后欧陆多国采纳，也影响了法国宪法委员会的设计。\n\n争论至今未有定论，但趋势清晰：Siems 指出，人权保护在西方世界已被广泛接受，司法审查的可获得性显著扩展；不过，审查权的具体配置——由谁审、审什么、如何审——仍由各国历史与制度传统决定。", "case": "马伯里诉麦迪逊案（Marbury v. Madison, 5 US 137, 1803）是理解法律位阶与司法审查的经典案例。案件背景是美国总统亚当斯卸任前任命了一批法官，其中威廉·马伯里（William Marbury）的委任状被新任国务卿麦迪逊（James Madison）扣留。马伯里依据《司法法》（Judiciary Act of 1789）向最高法院申请强制令，要求交付委任状。\n\n争议焦点在于：最高法院是否应签发强制令，以及《司法法》的相关条款是否违反宪法。首席大法官马歇尔（John Marshall）主笔的判决作出了一项影响深远的处理：法院认定马伯里的权利受到侵害，但《司法法》赋予最高法院签发此类强制令的权限超出了宪法第三条规定的原始管辖范围，因此该条款违宪、不能适用。\n\n裁判理由是：宪法是最高法律，与宪法抵触的国会法律无效；解释法律是法院的职责。这一判决巧妙地把案件结果（马伯里败诉）与制度建构（确立司法审查）结合起来。\n\n另一个对照是德国。二战后德国《基本法》设立联邦宪法法院（Bundesverfassungsgericht），由专门机关集中审查法律合宪性，Siems 把它列入“独立宪法法院”模式，其理论基础正是凯尔森区分“适用”与“评价”的主张。", "caseAnalysis": "就马伯里案作结构化分析。事实层面：委任状被扣留，申请人依《司法法》请求救济。争议焦点：法院是否有权签发强制令，以及授权条款是否合宪。\n\n法律依据层面，案件的核心不在于马伯里是否有权，而在于法院面对“法律与宪法冲突”时应如何处理。裁判理由层面，马歇尔的推理可拆为三步：第一，权利受侵害应有救济；第二，救济方式须有法律依据；第三，《司法法》相关条款扩张了最高法院的原始管辖权，与宪法第三条抵触，故无效。\n\n理论意义层面，该案把“宪法高于法律”的抽象命题，转化为“法院可宣告违宪法律无效”的具体制度。它使美国走上分散式司法审查道路，与后来欧陆的集中式宪法法院模式形成对照。Siems 把它列为1803年的 landmark decision，并指出此后许多国家的审查制度都在不同程度上受其影响。\n\n需要提醒的是，美国模式与英国议会主权模式的差异不该被抹平。在英国，法院传统上不能以违宪为由推翻议会的主要立法；这是两种宪法哲学的分歧，而非同一制度的不同阶段。把“司法审查”当作普适规则，会遮蔽各国制度的真实差异。", "summary": "宪法、法律、行政法规与判例构成一国法律体系的主要形式。宪法居最高位阶，法律次之，行政法规不得与法律抵触；判例的位阶取决于法系，在普通法系是正式法源，在大陆法系多为事实权威。位阶结构背后是权限分配：制宪权、立法权、行政权与司法权各有其产物。凯尔森的规范层级为理解位阶提供了理论框架。围绕法院能否审查议会立法，形成美国式的分散审查、德国式的集中审查与英国式的议会主权三种模式；马伯里案（1803）确立了美国的司法审查。理解这些形式，关键在于把握“谁的效力来自谁”这一主线，而非死记一张通用层级表。", "furtherThinking": "1. 在英国议会主权模式下，如果议会通过一项明显侵犯人权的法律，法院应如何应对？这与美国模式下的处理有何根本不同？\n2. 行政法规由行政机关制定，却可能深刻影响公民权利。在法律保留原则下，哪些事项必须由议会立法规定，哪些可以授权行政机关？\n3. 大陆法国家的判例虽非正式法源，却在实际中被遵循。这种“事实上的约束力”与判例法的“规范上的约束力”，界限应当如何划分？"}, "en": "Constitution, Statute, Administrative Regulation and Precedent", "level": "fundamental", "tags": "宪法, 法律位阶, 行政法规, 判例", "source": "Siems, Comparative Law, ch.3, ch.8；Wacks, Understanding Jurisprudence, ch.4", "id": "S1M2K3"}, "S1M2K4": {"title": "法律渊源的层级", "EN": "The Hierarchy of Sources of Law", "LEVEL": "core", "TAGS": "法律渊源, 效力层级, 基础规范, 承认规则, 渊源命题", "TERMS": "法律渊源（Sources of Law）::法律规则借以取得效力与权威的来源或表现形式；正式法源（Formal Sources）::被法律体系明确承认可直接援引的法源；非正式法源（Informal Sources）::学理、惯例等有影响力但不具正式约束力的材料；效力层级（Hierarchy of Norms）::规范依效力高低排列形成的等级序列；基础规范（Grundnorm）::凯尔森理论中被预设为全部规范效力最终来源的规范；渊源命题（Sources Thesis）::拉兹主张法律的识别应诉诸社会来源而非道德价值的命题；Lex Superior::上位法优于下位法的冲突规则；Lex Posterior::后法优于前法的冲突规则；Lex Specialis::特别法优于一般法的冲突规则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Hart, The Concept of Law, ch.6；Siems, Comparative Law, ch.3, ch.8", "terms": [{"term": "法律渊源（Sources of Law）", "def": "法律规则借以取得效力与权威的来源或表现形式"}, {"term": "正式法源（Formal Sources）", "def": "被法律体系明确承认可直接援引的法源"}, {"term": "非正式法源（Informal Sources）", "def": "学理、惯例等有影响力但不具正式约束力的材料"}, {"term": "效力层级（Hierarchy of Norms）", "def": "规范依效力高低排列形成的等级序列"}, {"term": "基础规范（Grundnorm）", "def": "凯尔森理论中被预设为全部规范效力最终来源的规范"}, {"term": "渊源命题（Sources Thesis）", "def": "拉兹主张法律的识别应诉诸社会来源而非道德价值的命题"}, {"term": "Lex Superior", "def": "上位法优于下位法的冲突规则"}, {"term": "Lex Posterior", "def": "后法优于前法的冲突规则"}, {"term": "Lex Specialis", "def": "特别法优于一般法的冲突规则"}], "sections": {"coreQuestion": "打开任何一部法律汇编，你都会遇到一个基本事实：规则之间有高低之分。宪法压倒法律，法律压倒行政法规，上级法院的判决压倒下级法院的判决。但我们很少追问：这种“高低”究竟是什么？是文本更漂亮，还是制定机关更权威？当两条规则打架时，凭什么说这一条应当让位？更进一步，整个效力链条的最终支点在哪里——它自己是“有效”的，还是被“预设”为有效的？本节要回答的，正是法律效力的来源、排序与终极基础这三个层层递进的问题。它们构成理解法律体系运作的骨架。", "definition": "法律渊源（Sources of Law）指法律规则借以取得效力与权威的来源或表现形式。这个概念有两层常见用法：一是“实质渊源”，指法律内容事实上从何处来（习惯、道德、社会需求、比较法经验）；二是“形式渊源”，指法律体系中哪些材料被承认为具有法律约束力的规则。本节主要讨论后者，即 formal sources。\n\n形式渊源可再分为正式法源与非正式法源。制定法、判例、习惯在有些体系中属于正式法源；学理、法官评注、政策文件通常属于非正式法源——它们影响裁判，却不能直接作为请求权基础。Siems 指出，大陆法国家中，学者的“主流学说”（德国的 herrschende Lehre、法国的 la doctrine）虽非法律渊源，其影响力却“几乎与实在法相当”。\n\n效力层级（Hierarchy of Norms）指规范依效力高低排列成的等级序列。它使“上位法优于下位法”（lex superior）、“后法优于前法”（lex posterior）、“特别法优于一般法”（lex specialis）等冲突规则成为可能。这些规则看似技术性，实则是法律体系保持统一与可预测的前提——没有它们，规则冲突时将无从决断。", "history": "法律渊源层级的理论化，是分析法学兴起的产物。近代国家把法律理解为“主权者的命令”时，效力来源被简单地归于主权者意志，层级问题退化为“谁离主权者更近”。奥斯丁（John Austin）的命令理论即持此看法。\n\n凯尔森（Hans Kelsen）在二十世纪上半叶构建了纯粹的规范层级理论。他追问：一条规范为什么有效？答案是：因为它被另一条更高规范授权；如此递推，终有尽头，那便是被预设的基础规范（Grundnorm）。Wacks 记述，凯尔森以“收税人与强盗”作比：二者都要求你交钱，也都表现出主观意志，但只有收税人的要求是客观有效的——因为强盗的强制命令缺乏“持久有效性”，人们不会预设一个要求服从它的基础规范。这个对比生动展示了有效性与效力的区别。\n\n哈特（H. L. A. Hart）在二十世纪中期提供了另一答案。他把效力终极支点从“预设规范”改为“社会实践”：承认规则（Rule of Recognition）之所以是最终标准，正因为官员们在实践中实际使用它来识别有效法律。拉兹（Joseph Raz）后来提出渊源命题（Sources Thesis），主张法律的存在与识别应诉诸可观察的社会来源，而非道德价值。\n\n比较法维度上，Siems 指出两大法系对渊源的排序不同：大陆法以法典为核心，普通法以判例为核心；但两者都发展出处理冲突的层级规则，且现代趋势是相互靠拢。", "principle": "法律渊源的层级可从三个层次逐层把握。\n\n第一层是“效力的传递”。凯尔森的模型是动态的：法由事实行为创造（如一项司法判决），该事实把规范效力从授权规范传递给被授权规范。授权规范有效且具备赋权能力，被创造的规范就有效。Wacks 描述了一条完整的链条：基础规范（最抽象的“应当”）→历史上的第一部宪法→立法或司法制定的较具体规范→最个别化的规范（如执法员扣押特定债务人财产）→强制行为本身。每一环的效力都来自上一环。\n\n第二层是“识别的标准”。哈特把问题从“效力如何传递”转为“我们凭什么说某规范属于体系”。承认规则提供识别标准：凡满足标准者即为有效法律。Wacks 依哈特指出，法律体系存在须满足两条件：有效义务规则被普遍遵守；官员从内部观点接受改变规则、裁判规则与承认规则。承认规则本身不是由更高规则制定的，它以社会实践方式存在——其存在条件就是被实际遵循，恰如靠右行驶的惯例。\n\n第三层是“冲突的解决”。当规范发生冲突，层级规则提供决断标准。除前述 lex superior、lex posterior、lex specialis 外，还有“新法优于旧法”“特别法优于普通法”等具体化形式。Siems 的瑞士民法典例子很典型：第1条第2款明文规定，法典未规定时依习惯法，习惯法也没有时依“他作为立法者会确立的规则”——这是一条把“法源顺序”写进法典的罕见实例，等于把层级规则正式化。", "viewpoints": "凯尔森的观点以“纯粹性”为标志。他要把法学从社会学、道德哲学中剥离出来，只研究“规范应当如何”的形式结构。其规范层级理论把所有法律效力追溯到被预设的基础规范，从而回答了“效力无限递推”的难题。他的代价是把基础规范定位为一个理论预设而非可观察事实——Wacks 指出，这本身引发争议：基础规范究竟是“被预设”还是“存在于法律意识之中”？\n\n哈特的观点以“社会实践”为核心。承认规则不宜被理解为神秘预设，它是官员实际共享的识别标准。这使法效力问题可被经验地研究，也延续了实证主义“法律与道德分离”的立场：一条规则是否有效，取决于它是否满足承认规则的标准，而非它是否道德。\n\n拉兹的观点更彻底。渊源命题主张，法律的存在与内容最终由社会来源决定；道德价值可以影响法律内容，但“是不是法律”的识别标准必须是价值中立的来源。这一命题把实证主义的来源取向推到最纯粹的形态。\n\nSiems 的比较法视角则提醒：源理论的抽象框架必须落到具体制度。大陆法中，法典是核心渊源，判例与学理起补充作用；普通法中，判例是核心渊源，成文法常被视为例外。但两者都面临同一问题——如何在多个渊源之间建立可操作的层级与冲突规则。", "comparison": "凯尔森与哈特的差异是本节最核心的对照。二者都寻求效力的终极支点，也都拒绝把道德作为该支点；区别在支点的性质。凯尔森的基础规范是被“预设”的，属于理论构造；哈特的承认规则是被“实践”的，属于社会事实。Wacks 设有专节比较二者（第4.1节），指出功能相近而性质不同。可以说，凯尔森提供了“逻辑上完备”的模型，哈特提供了“经验上可检验”的模型。\n\n渊源命题与自然法理论形成另一重对照。拉兹主张识别法律看来源；自然法理论主张严重不义的规则欠缺法的品格。前者强调确定性，后者强调正当性。这场争论在 S1M1 已有展开，此处只需指出：它同样决定了“法律渊源”的范围——若采自然法立场，道德原则可直接成为法律渊源；若采渊源命题，道德原则只有经制度化承认才进入法律。\n\n大陆法与普通法的渊源排序也值得比较。Siems 指出，在大陆法国家，法官把论证锚定在法典之上；在普通法国家，法官更零星地引用制定法，因为判例才是主干渊源。但现代趋势是两者靠拢：大陆法解释转向目的论，普通法解释转向立法史与目的。渊源层级因而难称静态分类，它随实践缓慢演变。", "debates": "法律渊源理论的第一场经典争论，是“效力最终建于何处”。奥斯丁溯及主权者，凯尔森溯及基础规范，哈特溯及承认规则，拉兹溯及社会来源。Wacks 记述，这些尝试都试图回答同一个问题：为什么我们说一条规则“有效”，而不只是“有人在执行它”？争论的焦点在于：这个最终支点必须是“事实”还是可以是“预设”？凯尔森的基础规范因不是事实而被批评为神秘；哈特的承认规则因是社会实践而更受青睐，却又面临“官员实践能否真正统一”的质疑——Wacks 记述有学者（如 Zipursky）指出，承认规则既要是可被陈述的标准，又要是法官的社会实践，而命题与实践之间并非同一事物。\n\n第二场争论关于“道德能否成为法律渊源”。L. L. 富勒（Lon Fuller）主张法律有“内在道德”，一套法律体系必须满足一般性、公开性、不溯及既往、明确性、不矛盾、可遵守、稳定、官方行为与规则一致等八项要求。按此说，这些程序性原则本身就构成法律效力的条件。哈特与拉兹则坚持，道德考量不能直接影响“是不是法律”的判断。Wacks 指出，富勒的八项要求可满足形式合法性，却无法保证实质正义——南非种族隔离制度很可能全部满足，可见富勒式认可并不使体系免于批判。\n\n第三场争论来自德沃金（Ronald Dworkin）。他批评哈特把法律当作规则体系，遗漏了原则；原则没有“全有或全无”的适用方式，而是以“分量”起作用。若原则属于法律，法律渊源就不只是制定法与判例，还包含道德原则。这场争论把渊源层级从“规则之间”扩展到“规则与原则之间”。", "case": "法国与英国关于严格责任的判例发展，是观察法律渊源层级运作的绝佳窗口。Siems 记述：德国就若干事故类型制定了大量特别法，法院倾向于不越过这些立法；法国法院则走得更远——1930年2月13日，法国最高法院（Cour de Cassation）合并庭在 Jand'heur 案中，把《法国民法典》第1384条这一笼统条款解释为规定严格责任，从而无需大量特别立法。英国方面，1868年上议院在 Rylands v. Fletcher 案（[1868] UKHL 1, (1868) LR 3 HL 330）中判定，某物从土地逃逸造成损害时，占有人承担严格责任；这一原则后来有所扩展，但英国法院比美国法院更不愿将其普遍化。\n\n三个国家的对照极具启发。德国法院恪守立法划定的边界，显示“制定法居于核心渊源”的大陆法取向；法国法院从一个模糊的法典条文发展出严格责任，显示判例在法典框架内的创造性；英国上议院则通过判例直接创设规则，显示普通法以判例为主干渊源的传统。三者在几十年间面对类似的社会问题，却诉诸不同层级的渊源、得出路径不同但可比较的解决方案。", "caseAnalysis": "就 Jand'heur 案与 Rylands 案作结构化分析。事实层面，两案都涉及事故损害的赔偿问题，且既有的成文法规定并不明确或不存在。争议焦点在于：法院能否以及如何从现有渊源中发展出严格责任规则。\n\n法律依据层面，法国法院诉诸《法国民法典》第1384条的笼统表述，通过解释使其成为严格责任的依据；英国法院则直接从判例传统中提炼出新规则。裁判理由层面，差别恰恰体现了渊源层级的文化差异：在法国，法官须把论证锚定在法典条文上，因而“解释”成为主要工具；在英国，法官可诉诸判例的积累与类推，“造法”更为显性。\n\n理论意义层面，这两个案例说明：渊源层级并非抽象教条，它是塑造裁判方法的实际力量。它决定了法官可以在哪里寻找依据、以何种方式论证、以及裁判的权威来自何处。Siems 同时指出，Zweigert 与 Kötz 认为普通法国家严格责任的相对重要性可能与程序因素（陪审团、集体诉讼、律师费）有关——这提醒我们，渊源层级之外，制度环境同样塑造法律的发展。\n\n两个案例也印证了前述“方法趋同”的判断：法国通过解释发展责任法，英国也在若干领域以立法介入（如交通事故），两大传统正从各自的主干渊源出发，向对方的方法借鉴。", "summary": "法律渊源是法律规则取得效力的来源，分为正式与非正式两类；效力层级使上位法优于下位法、后法优于前法、特别法优于一般法等冲突规则得以运作。凯尔森以规范层级与基础规范解释效力传递，哈特以承认规则的社会实践解释效力识别，拉兹以渊源命题主张识别须诉诸社会来源。凯尔森的基础规范是理论预设，哈特的承认规则是可观察实践，二者功能相近而性质不同。围绕效力支点、道德能否成为渊源、原则是否属于法律，形成持续争论。Jand'heur 案与 Rylands 案显示，渊源层级如何实际塑造不同法系的裁判方法。掌握“效力从何而来、如何排序、最终止于何处”，就掌握了法律渊源理论的主线。", "furtherThinking": "1. 哈特说承认规则是社会实践，凯尔森说基础规范是被预设的。若一个社会官员对识别标准各持己见，哪一种理论更能解释这种情况？\n2. 国际法没有世界立法机关，其“渊源”主要靠条约与习惯。这种情形对拉兹的渊源命题构成支持还是挑战？\n3. 若道德原则通过宪法基本权利条款进入法律体系，它是否变成了正式法源？这是否会模糊法律与道德的界限？"}, "en": "The Hierarchy of Sources of Law", "level": "core", "tags": "法律渊源, 效力层级, 基础规范, 承认规则, 渊源命题", "source": "Wacks, Understanding Jurisprudence, ch.4；Hart, The Concept of Law, ch.6；Siems, Comparative Law, ch.3, ch.8", "id": "S1M2K4"}, "S1M2K5": {"title": "普通法与大陆法的基本区别", "EN": "Basic Differences Between Common Law and Civil Law", "LEVEL": "core", "TAGS": "普通法, 大陆法, 法系, 法律方法, 比较法", "TERMS": "普通法（Common Law）::以英国法为基础、以判例为主干渊源的法律传统；大陆法（Civil Law）::受欧洲大陆罗马法传统影响、以法典为核心渊源的法律传统；法系（Legal Family）::依法律历史、思维与实在法特征对法律体系所作的分类；令状（Writs）::中世纪英格兰标准化的诉讼形式，普通法由此生长；先例约束（Stare Decisis）::既往判决对后续案件具有约束力的原则；法院组织（Court Organisation）::不同法系在普通法院与专门法院之间的制度安排差异；相似推定（Praesumptio Similitudinis）::茨威格特与科茨提出的、发达国家法律实务结果往往相似的命题", "SOURCE": "Siems, Comparative Law, ch.3；Wacks, Understanding Jurisprudence, ch.8", "terms": [{"term": "普通法（Common Law）", "def": "以英国法为基础、以判例为主干渊源的法律传统"}, {"term": "大陆法（Civil Law）", "def": "受欧洲大陆罗马法传统影响、以法典为核心渊源的法律传统"}, {"term": "法系（Legal Family）", "def": "依法律历史、思维与实在法特征对法律体系所作的分类"}, {"term": "令状（Writs）", "def": "中世纪英格兰标准化的诉讼形式，普通法由此生长"}, {"term": "先例约束（Stare Decisis）", "def": "既往判决对后续案件具有约束力的原则"}, {"term": "法院组织（Court Organisation）", "def": "不同法系在普通法院与专门法院之间的制度安排差异"}, {"term": "相似推定（Praesumptio Similitudinis）", "def": "茨威格特与科茨提出的、发达国家法律实务结果往往相似的命题"}], "sections": {"coreQuestion": "学习法律的人常听到一句话：世界上有两大法系，英美是普通法，欧陆是大陆法。这句话不算错，却容易催生一张粗糙的对照表——普通法靠判例，大陆法靠法典；普通法法官造法，大陆法法官适用法。这样的对照在入门时有用，却掩盖了真实图景的复杂性。普通法与大陆法的区别究竟在哪些层面？这些区别是根本性的，还是仅仅“形式不同、实质相近”？两大传统在今天是否正在趋同？本节以 Siems《比较法》第三章为主要依据，逐层梳理二者的起源、渊源、方法、法院组织与学术角色，并引入对该二分法的批判性反思。", "definition": "普通法（Common Law）与大陆法（Civil Law）在 Siems 那里首先是给法律体系群组所贴的“标签”：大致而言，普通法国家是以英国法为基础的法律体系，大陆法国家是受欧洲大陆传统影响的体系。他特别提醒，这两个词都有多重含义。\n\n就“普通法”而言：在一国之内，它可以指与“衡平法”（equity）相对的那部分法；可以指与普通法国家的制定法相对的判例法；可以指与地方法相对的、适用范围更广的共同法；在比较法语境中，则指以英国法为渊源的法系。就“大陆法”而言：它既可以指欧陆法系，也可以在一国之内指与刑法、公法相对的私法领域（如合同法、侵权法）。\n\n由此可得一个重要的方法论提醒：谈“普通法与大陆法的区别”时，必须先说清在哪个层次上谈。Siems 指出，比较法通说认为若干主题处于二分的核心——法律渊源与法律方法、法律风格与技术、制度与程序，外加一个较具体领域（合同法）。本节围绕这些主题展开。\n\n法系（Legal Family）概念的基础在于：世界法律体系的多样性并非随机，国家群组在法律史、法律思维与实在法上共享特征。Siems 同时指出，法系观念近年影响有所减弱，但仍是比较法的重要工具。", "history": "大陆法传统建立在罗马法之上。Siems 指出，古罗马法原本采用今天更常与普通法联系的个案式（casuistic）风格。公元六世纪初，东罗马皇帝查士丁尼主持编纂《国法大全》（Corpus Juris Civilis，533年）；十一世纪，欧洲大陆“继受”罗马法，大学推动了这一进程，故大陆法常被称为“学者的法”（learned law）。被继受的罗马法是超越国界的共同法（ius commune），取代或补充了地方法习惯；司法实施被置于国家严格控制之下，以防腐败并确保统一适用。十八、十九世纪民族国家兴起，各国把罗马法与地方习惯法典化：1804年《法国民法典》被视为现代大陆法传统的象征，追求“像圣经一样简单”；1900年《德国民法典》风格更概念化、更学院化。法典化既造成欧陆内部的分化，也随殖民帝国及日本、土耳其等国的自愿移植扩散到全球。\n\n普通法的起源“看起来更清晰”。1066年诺曼征服后，征服者威廉加冕为英格兰国王，以封建土地制度与新法院体系控制国家并统一法律。法律建立在标准化令状（writs）之上，法院以伦敦为中心，巡回法官在各地办案；事实认定交给陪审团，以便地方居民接受王室司法。十七世纪，詹姆斯一世试图凭借封建权力主张全国土地所有权，议会介入，产权保护与司法独立随之加强；法官逐渐撰写详尽判决，把程序性的令状转化为实体规则。Maitland 的名言概括其韧性：“我们埋葬了诉讼形式，它们却仍在坟墓中统治我们。”殖民把这一传统带到美国、澳大利亚、印度。", "principle": "两大传统的差异可从四条线索逐层理解。\n\n第一，渊源与法律方法。Siems 指出，大陆法国家的民法典、商法典、刑法典、民诉法典与刑诉法典多在十九世纪出现；其法典体现启蒙运动的理想——清晰、连贯、系统、自足、完整。普通法国家也有法典化：美国律师戴维·达德利·菲尔德（David Dudley Field）在十九世纪中叶起草《民事诉讼法典》，先被纽约州采纳并影响今日《联邦民事诉讼规则》；加州、蒙大拿等州有民法典；《统一商法典》（UCC）被所有州以细微修改采纳；独立前的印度亦有法典化。但差别在于：大陆法典追求体系的完整与自足，普通法国家的法典多是对既有判例的合并整理，体系化程度较低。法国1989年设立最高法典化委员会（Commission Supérieure de Codification）以新颁与重编法典，正体现立法者对法典理念的坚持。\n\n第二，司法解释方法。Siems 记述，《法国民法典》第5条禁止法官以一般性、规范性规定裁判案件，背景是旧制度下法院以普遍规则阻挠改革；其理想是严格分权、禁止司法造法。但十九、二十世纪的经验表明机械字面解释不可行，大陆法解释遂转向：考虑立法历史以实现立法者意图的“注解方法”（exegetical method），以及条文不明时诉诸法律客观目的的“目的论方法”（teleological method），例外情形下还可扩张解释或类推。普通法的成文法解释传统上以字面规则（literal rule）为主，另有黄金规则（golden rule）避免荒谬结果、瑕疵规则（mischief rule）弥补法律欲救治的缺陷；不过也逐步转向立法史与目的。关键差别仍在：普通法以判例为主干，制定法被视为例外，故司法解释传统上较窄。\n\n第三，法院与司法角色。普通法的审判既解决个案，也“自下而上”发展法律，具有反应性——它“等待解释的契机”。Macmillan 勋爵说：“基于法律一致性的论证容易误导，因为普通法是一部适应人类生活万千差异的实用法典。”先例约束意味着法官适用的是自己同行制定的法，法律因而渐进演化；普通法法官对社会争议较愿展现司法创造性，对经济学等社会科学论证较开放，并因独立而被誉为对个人权利与自由的保护者。大陆法法官则在解释制定法上有较大裁量，方法却被批评为实证主义、机械、缺乏创造；同情的说法是尊重立法者、以理性可预测的方式适用法律。制度上，大陆法法官是职业文官、身处层级体系、案件负荷高，故重心在“实施”而非“发展”法律。\n\n第四，学术角色与法院组织。大陆法传统是“学者的法”：德国教授对法律性格影响深远，与英格兰的法官、法国的立法者形成对照；潘德克顿学派（Pandectists）几乎写了1900年民法典，2002年改革也以教授报告为基础；德国的“主流学说”（herrschende Lehre）与法国的“学理”（la doctrine）几乎与实在法同等重要。普通法的学术与实务交织较少，Geoffrey Samuel 观察到，法律职业与司法的狭隘视角反而促使部分学者转向社会科学或哲学。法院组织上，大陆法国家按法律领域设不同法院：德国有行政、劳动、社会保障、税务专门法院及联邦宪法法院；法国有最高行政法院（Conseil d'État）；普通法国家传统上不区分公法与私法法院，国家在普通法院中只是普通一方；英国如今有专门裁判所，但未形成德国、法国那样的独立法院系列。上诉制度上，大陆法的上诉范围更广，第一级上诉可重审事实与法律；第二级上诉中德国采“复审模式”（revision model），法国采“撤销模式”（cassation model）。", "viewpoints": "Siems 呈现的是比较法主流描述。他强调，两大法系的典型特征主要源于少数国家的影响：大陆法方面是法国法与德国法，普通法方面是英国法以及晚近的美国法。因此聚焦这四个体系即可把握主流图景，但他也声明随后将作批判性分析。\n\n茨威格特（Konrad Zweigert）与科茨（Hein Kötz）提出著名的“相似推定”（praesumptio similitudinis）：撇开深受道德观念影响的领域（主要在家庭法与继承法），聚焦于私法中相对“非政治性”的部分，会发现发达国家以相同或非常相似的方式回应法律实务的需求。Merryman 同样认为，作为规则，人们可以期待两组法律体系在类似案件中产生类似结果；Nottage 称之为“两条路径通向同一目标”。Goff 勋爵则概括为：普通法与大陆法的差异“更多在形式而非实质”。\n\nSiems 的批判性立场则提醒：这些“主流描述”本身需要被审视。法系分类有其历史局限与欧洲中心、新殖民偏见；而且法律实践的差异并不总能用“形式／实质”二分来打发。他在结构上把主流描述与批判分析分开，本身即表明：学习两大法系，既要掌握通说图景，也要保持对通说的反思。", "comparison": "把两大传统逐项并排，差异与趋同同时浮现。\n\n在法的渊源上，大陆法以法典为核心、判例为补充；普通法以判例为核心、成文法为例外。但 Siems 指出，普通法国家的法典化并不罕见，只是性质多为判例整理。\n\n在法官角色上，大陆法法官被视为“适用者”，普通法法官同时是“造法者”。但 Siems 也指出大陆法法官在解释时有相当裁量，而普通法法官受先例约束，其创造性并非无边。\n\n在法律方法上，大陆法从机械字面解释转向注解与目的论方法，普通法从字面规则转向立法史与目的——两者朝同一方向移动。\n\n在法院组织上，大陆法多设专门法院，普通法传统上由普通法院管辖公法与私法；但英国已有行政裁判所，美国也有专门法院，差别在程度而非有无。\n\n在学术角色上，大陆法学理影响巨大，普通法学理与实务较疏离；但英格兰法律委员会（Law Commission）通常由教授担任委员，普通法的教义学研究也高度关注判例。结论是：差异是真实的，但不是绝对的；通说对照表该被当作理解入口，而非最终结论。", "debates": "最持久的争论，是“普通法与大陆法的二分究竟是不是根本性的”。\n\n一方认为它是比较法的“最基本、讨论最多的问题”。Siems 引述传统比较法的说法：这一区分构成“法律秩序的基本建筑模块”，是“世界上占主导地位的法律体系”。按此说，不理解这一二分，就无从理解世界法律地图。\n\n另一方以 Zweigert、Kötz、Merryman 等为代表，主张在相似问题下结果趋同，差异“更多在形式而非实质”。Siems 进一步给出对该趋同倾向的心理学解释：二战后比较法由欧陆学者与移居美国的犹太移民主导，这两个群体都倾向于强调不同国家、种族、宗教人群之间的共性。这是一种对学术史的社会学反思，而非对结论本身的否定——它提示我们，“趋同”命题可能部分源于学术社群的构成。\n\n争论的第三个层面是“法系概念是否仍然有用”。Siems 指出，法系观念近年影响减弱，新的比较法更多关注国际法、跨国法与具体领域；但他同时承认，法系作为工具仍被广泛使用。于是问题变成：法系是描述法律世界的可靠地图，还是一张需要不断修订的旧地图？Siems 的立场是审慎的——既使用主流分类，又系统检视其局限。\n\n这场争论没有结论，却给学习者一个重要启示：比较法的价值不仅在于记住差异，更在于理解差异为何被这样描述、由谁描述、服务于什么目的。", "case": "严格责任（strict liability）在三国的发展，是观察两大传统方法差异的窗口。Siems 记述：德国就若干事故类型制定了大量特别法，这些法律常设不可抗力例外并限制赔偿额，法院倾向于不越过这些立法；法国的路径截然不同——1930年2月13日，法国最高法院（Cour de Cassation）合并庭在 Jand'heur 案中，把《法国民法典》第1384条这一笼统条款解释为规定严格责任，从而减少对特别立法的需求；英格兰与美国方面，判例亦发挥重要作用，1868年上议院在 Rylands v. Fletcher 案（[1868] UKHL 1, (1868) LR 3 HL 330）中判定，某物从土地逃逸造成损害时占有人承担严格责任。不过英国法院比美国法院更不愿将该原则普遍化，立法也在交通事故等领域介入。\n\n三国面对相似的社会问题——工业事故中的损害救济——却诉诸不同层级的渊源、发展出不同方法：德国法院恪守立法划定的边界，法国法院从法典的一般条款中“解释”出规则，英国法院从判例中“提炼”出规则。Zweigert 与 Kötz 还指出，美国严格责任的相对重要性可能与陪审团、集体诉讼、律师费等程序因素相关——这提醒我们，法系差异之外，程序制度同样塑造实体法的发展。", "caseAnalysis": "就上述对照作结构化分析。事实层面：三国都面对事故损害赔偿问题，既有成文法或笼统或不完整。争议焦点：法院能否、以及以何种方式发展出严格责任规则。\n\n法律依据层面，三国分别诉诸特别立法、民法典一般条款与判例传统。裁判理由层面，法国法院须把论证锚定在法典条文上，故以“解释”为工具；英国法院可直接从判例传统中类推，故“造法”更为显性；德国法院则把变革留给立法者。这正体现了 Siems 所说的“法律渊源与法律方法”是二分的核心主题。\n\n理论意义层面，案例同时支持两种看似对立的判断。一方面，方法差异真实存在：法官的角色、论证的锚点、规则的生长方式都不同。另一方面，结果层面确实趋同：三国最终都形成了严格责任制度，印证了“相似推定”与“形式重于实质”的命题。可以说，这个案例把“差异”与“趋同”同时摆在桌面上：差异在方法与形式，趋同在问题与结果。\n\n需要警惕的是把差异绝对化。Siems 指出，大陆法国家中上级法院的裁判在实践中也产生类似先例的影响；普通法国家也有成文法与法典。因此，Rylands 与 Jand'heur 的对照应被理解为“典型倾向”的例证，而非“非此即彼”的证明。", "summary": "普通法与大陆法是依据法律史、法律思维与实在法特征划分的两大法系，其典型特征主要源于英国法与美国法、法国法与德国法的影响。二者在渊源、解释方法、法院角色、学术地位与法院组织上存在系统差异：大陆法以法典为核心、法官侧重适用、学理影响巨大、按领域设专门法院；普通法以判例为核心、法官参与造法、学术与实务较疏离、传统上由普通法院统辖。但差异并非绝对，现代趋势是方法上的相互靠拢。围绕二分法的根本性形成争论：传统说视之为比较法的基本问题，Zweigert、Kötz 与 Merryman 等则以“相似推定”主张结果趋同、差异在形式。Siems 主张既掌握主流图景，又反思其历史局限。严格责任的跨文化发展表明，差异在方法与形式，趋同在问题与结果。", "furtherThinking": "1. 如果两大法系在结果上趋同而在方法上迥异，那么法系分类的价值究竟何在？它描述的是“法律是什么”，还是“法律人如何思考”？\n2. 英国脱欧后，其普通法传统与欧盟大陆法传统的关系将如何演变？法律移植与法系边界之间是什么关系？\n3. 中国法律体系在渊源上接近大陆法系，但在司法改革中引入了典型案例指导制度。这种混合会带来哪些方法论上的张力？"}, "en": "Basic Differences Between Common Law and Civil Law", "level": "core", "tags": "普通法, 大陆法, 法系, 法律方法, 比较法", "source": "Siems, Comparative Law, ch.3；Wacks, Understanding Jurisprudence, ch.8", "id": "S1M2K5"}, "S1M2K6": {"title": "法律规范的结构", "EN": "The Structure of Legal Norms", "LEVEL": "core", "TAGS": "法律规范, 规则, 原则, 开放结构, 授权规则", "TERMS": "法律规范（Legal Norm）::规定人们在特定条件下应当如何行为的标准；行为模式（Pattern of Behaviour）::法律规范中规定可以、应当或禁止如何行为的部分；法律后果（Legal Consequence）::法律规范中规定遵守或违反时产生何种结果的部分；义务规则（Duty-imposing Rules）::要求人们做或不做特定行为的规则；授权规则（Power-conferring Rules）::赋予人们改变法律地位之能力的规则；法律原则（Legal Principles）::以『分量』而非全有全无方式起作用的评价标准；开放结构（Open Texture）::语言在核心明确之外总存在边界模糊情形的特性；临界案件（Penumbral Cases）::语言适用与否不确定的边缘情形", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4-5；Hart, The Concept of Law, ch.1, ch.7, Postscript；Siems, Comparative Law, ch.3", "terms": [{"term": "法律规范（Legal Norm）", "def": "规定人们在特定条件下应当如何行为的标准"}, {"term": "行为模式（Pattern of Behaviour）", "def": "法律规范中规定可以、应当或禁止如何行为的部分"}, {"term": "法律后果（Legal Consequence）", "def": "法律规范中规定遵守或违反时产生何种结果的部分"}, {"term": "义务规则（Duty-imposing Rules）", "def": "要求人们做或不做特定行为的规则"}, {"term": "授权规则（Power-conferring Rules）", "def": "赋予人们改变法律地位之能力的规则"}, {"term": "法律原则（Legal Principles）", "def": "以『分量』而非全有全无方式起作用的评价标准"}, {"term": "开放结构（Open Texture）", "def": "语言在核心明确之外总存在边界模糊情形的特性"}, {"term": "临界案件（Penumbral Cases）", "def": "语言适用与否不确定的边缘情形"}], "sections": {"coreQuestion": "“禁止杀人”“合同应当履行”“公民有言论自由”——这些句子看起来都是法律规范，但它们的内部结构相同吗？一条规范由哪些部分构成？规则与原则是不是同一种东西？为什么有些规则违反后会招致惩罚，另一些（如结婚、订立合同）不遵守却只是“不成立”而非“受罚”？这些问题看似琐碎，实则决定了我们如何理解法律的运作方式：法官如何适用规范、如何填补漏洞、以及法律在多大程度上能为行为提供确定指引。本节从规范的基本结构入手，逐层剖析规则的内部构造、功能分类与边界难题。", "definition": "法律规范（Legal Norm）是规定人们在特定条件下应当如何行为的标准。凯尔森（Hans Kelsen）把“规范”界定为“某物应当存在或应当发生，尤其是人应当以特定方式行为”。Wacks 指出，红灯与“门应当关上”这样的陈述都可视为规范。\n\n在中文法理学的分析框架中，一条完整的法律规范通常被拆解为三个要素：假定条件（何时、何地、对谁适用）、行为模式（可以、应当或禁止如何行为）、法律后果（遵守或违反时产生何种结果）。这一“三要素说”是便于教学的分析工具；也有的学说把假定条件并入行为模式，形成“行为模式＋法律后果”的二要素框架。两种拆分方式并无绝对优劣，关键在于能否说明规范如何指引行为。\n\n哈特（H. L. A. Hart）提供了另一组更富理论张力的分类。他区分义务规则（Duty-imposing Rules）与授权规则（Power-conferring Rules）：前者要求人们做或不做某事，后者赋予人们改变法律地位的能力——立法、结婚、订立合同、订立遗嘱都属于后者。他还区分初级规则与次级规则，以及规则与原则。\n\n原则（Legal Principles）与规则的关键差别在于适用方式：规则以“全有或全无”（all-or-nothing）的方式适用，一旦有效即要求结论成立；原则则以“分量”（weight）参与权衡，不直接决定结论。德沃金（Ronald Dworkin）正是以此批评哈特的“规则模型”。", "history": "对法律规范结构的反思，随法律理论重心转移而展开。近代命令理论把法律简化为“主权者的命令＋制裁”，规范结构因而被理解为“命令—威胁”的二段式。奥斯丁（John Austin）认为，一切法律规则都是命令，违反即招致制裁。\n\n凯尔森的纯粹法学把规范结构理解为“条件—制裁”的模式。Wacks 记述，凯尔森把一切立法还原为“如果X，那么Y”的形式（X是某行为，Y是制裁）。这一还原被广泛批评为过于狭窄：它把形式置于意义之上，预设法律本质上是强制，而忽略了法律的调节功能。\n\n哈特在《法律的概念》中突破了这一图景。他通过“规则与习惯”的区分说明规范的特殊性：棋手不仅以相同方式移动皇后，还对这种方式持有“批判反思态度”——把它当作标准，对他人的走法发表意见，并承认他人批评的正当性。规范由此被重新理解为被参与者从内部观点接受的标准，“被观察到的常规行为”这一图景随之退场。\n\n德沃金在二十世纪七十年代进一步挑战哈特，主张法律体系包含原则，规则模型无法解释原则在疑难案件中的作用。哈特在《法律的概念》后记中回应了这一批评，争论延续至今。", "principle": "法律规范的结构可从五个层次逐层把握。\n\n第一层是规范与事实的区分。凯尔森指出，“门应当关上”与红灯都是规范，因为它们表达“应当”；而“门关着”只是描述。Wacks 强调，规范作为“应当”陈述，其有效性须由另一规范授权，而非由事实直接推出。\n\n第二层是规范与习惯的区分。哈特以象棋为喻：棋手共享移动皇后的习惯，但规范不止于此——他们对走法持有批判反思态度，把它当作评价标准。Wacks 记述，哈特借此说明，规则的存在条件是被实践；但规则一旦存在，其指引行为并不取决于每条规则实际上被遵守。\n\n第三层是逻辑结构。若按凯尔森的还原，规范可写作“若X则Y”，即条件行为引发制裁。Wacks 记述批评意见：J. W. Harris 指出，衡量有效性须先知道规范内容，而“义务”概念必须独立于“制裁”概念，“法理论必须分别定义义务与制裁”。凯尔森把一切规范还原为制裁条件式的做法，被批评为把复杂的规范结构压扁了。\n\n第四层是功能分类。哈特区分义务规则与授权规则。Green 在《法律的概念》导论中解释：制裁是法律的“Plan B”，“Plan A”是人们在无人监督时自发遵守；许多法律规范并不以制裁为后盾。美国法典中有规范告诫人们如何尊重国旗（如“国旗不得用作盛放、接收、携带或递送物品的容器”），却未设罚则。结婚、订立合同等授权规则亦是如此：不按法定方式操作，结果是“婚姻无效”“合同不成立”，而非“受惩罚”。哈特还反驳凯尔森的“权宜之计”——凯尔森说授权规则只是法律的碎片，制裁藏在别处；哈特回应说这种重构在逻辑上完全可行，缺的是动机，也与法理学的方法论约束相悖。\n\n第五层是规则的边界。哈特指出语言具有开放结构（Open Texture）：词语有清晰的核心含义，却总有若干临界案件（Penumbral Cases）适用与否不确定。Wacks 强调，这并不等于词义完全任意——与美国法律现实主义者不同，哈特认为多数案件中法官只需直接适用规则，无需诉诸道德或政治考量。开放结构只说明“规则无法为一切可能案件预置答案”。", "viewpoints": "凯尔森把规范理解为以制裁为后盾的“应当”陈述，其结构可用“如果X，那么Y”概括。他的贡献在于把规范从道德中剥离，建立纯粹的规范科学；其代价是对规范结构做了过度狭窄的还原。\n\n哈特的核心贡献在于把规范理解为“被内部观点接受的社会规则”。他区分义务规则与授权规则，指出制裁并非法律规范的普遍要素；他区分规则与习惯，强调批判反思态度；他提出开放结构，承认规则的边界不确定性却拒绝走向规则怀疑论。Green 概括得好：哈特从不说法律“只是”规则，规则“处于法律体系的中心，但并不是全部”。\n\n德沃金的核心主张是：法律不仅包含规则，还包含原则。原则以分量起作用，在“疑难案件”中决定判决。他以 Riggs v. Palmer 案说明：当规则没有明确例外时，法院仍可依据“任何人不得从自己的错误中获利”的原则否定继承权。这证明法律材料的范围大于规则集合。\n\nWacks 的综述强调，规范结构是理解法律性质的入口：从“命令—制裁”到“规则—实践”再到“规则—原则”的演变，反映了法理学对法律复杂性的逐步承认。", "comparison": "凯尔森与哈特对规范结构的理解形成鲜明对照。凯尔森以制裁为中心，把规范还原为条件—后果模式；哈特以规则实践为中心，把制裁降为“Plan B”。前者强调法律的强制性，后者强调法律的规范性。Wacks 记述，哈特承认强制确实存在，他反对的是把强制当作法律的本质。\n\n规则与原则的对照同样重要。规则在适用上是“全有或全无”：一条有效规则若适用，就给出确定结论。原则则提供理由，其分量需与其他原则权衡。德沃金由此认为，法律体系是“无漏洞”的——即使没有直接规则，原则仍可提供答案。哈特则通过开放结构承认真正的漏洞存在，并承认法官在漏洞处行使裁量。\n\n中文法理学的“三要素说”与哈特的分类处于不同层次。三要素说分析单条规则的构成（条件、模式、后果）；哈特的功能分类分析规则在法律体系中的作用（义务或授权、初级或次级）。二者并非竞争关系，只是处于不同分析层次的工具：前者适合法律适用教学，后者适合法理反思。", "debates": "第一场争论是“规则模型是否足以描述法律”。德沃金以 Riggs 案为据，主张法律包含原则，规则模型无法解释原则的适用。哈特在后记中作出两项让步：承认法律体系中确有原则，也承认承认规则可以识别原则；但他坚持，原则的识别最终仍须诉诸官员的社会实践。争论的焦点因此从“有没有原则”转向“原则如何被识别”。\n\n第二场争论围绕开放结构展开。法律现实主义者认为，语言的模糊性意味着规则无法确定裁判，法官实际上在造法。哈特承认前件，拒绝后件：Wacks 指出，哈特明确反驳“词义完全任意”的看法，认为多数案件中法官直接适用规则即可，只有临界案件才需要裁量。这场争论的实质是：规则的确定性应当被高估还是低估？\n\n第三场争论关于强制的地位。凯尔森认为法律以强制为本质，授权规则只是“碎片”，制裁藏在别处。哈特反驳说，把授权规则重构为“义务＋制裁”缺乏动机，且违背法理学应尊重的概念区分。Green 指出，这一争论关涉法理学的方法论约束：理论不应为了维护某个教条而扭曲我们实际使用的概念。\n\n三场争论共同指向一个核心问题：法律规范究竟是“命令”、“规则”还是“理由”？不同回答塑造了不同的法律观。", "case": "Riggs v. Palmer（115 NY 506, 22 NE 188, 1889）是讨论规范结构最经典的案例之一。案情极其简单：帕尔默（Palmer）为继承祖父的遗产而将其毒杀，遗嘱本身形式有效、且指定帕尔默为受益人。按纽约州继承法规则，遗嘱有效、继承人资格无明文例外，帕尔默表面上有权取得遗产。\n\n争议焦点是：遗嘱继承规则是否应当让位于一项法律原则——“任何人不得从自己的错误中获利”（no man should profit from his own wrong）。纽约州法院最终判决：谋杀者不得从被害人的遗嘱中继承。Wacks 记述，德沃金正是用此案反驳“规则模型”：既然规则没有规定例外，法院却依据原则排除了规则的适用，说明法律体系中包含规则之外的标准。\n\n另一个来自 Green 导论的例子有助于理解授权规则：美国法典中有若干规范告诫公民如何尊重国旗，却未附罚则；结婚、订立合同等规则的不遵守只导致“无效”而非“处罚”。这两个例子与 Riggs 案形成对照：前者显示“无制裁的规范”确实存在，后者显示“原则可以压倒规则”。", "caseAnalysis": "就 Riggs 案作结构化分析。事实层面：遗嘱有效、继承人实施了谋杀、继承法规则未设相应例外。争议焦点：在规则沉默处，法院能否援引原则改变规则的适用结果。\n\n法律依据层面，法院诉诸的是一项原则，更高位阶的规则在此缺席。裁判理由层面，德沃金的解读是：原则以“分量”起作用，它不推翻规则，却能在特定情境中压倒规则——因为“不得从错误中获利”这一原则的力量，足以超过“有效遗嘱应予执行”这一规则所代表的确定性价值。\n\n理论意义层面，该案至少揭示三点。第一，法律规范的集合比规则集合更广：原则同样参与裁判。第二，规则的“全有或全无”适用并非绝对：原则可以在特定案件中介入。第三，所谓“法律漏洞”未必是真正的空白——在法律材料中，原則可能提供规则之外的答案。\n\n不过，哈特一方的解读仍有空间：他可以承认该案中存在原则，同时追问法院援引该原则的权限从何而来——若权限来自承认规则的社会实践，则原则仍被纳入规则体系的整体框架。两种解读的分歧，因此是“原则如何进入法律”的分歧，而非“原则是否存在”的分歧。Riggs 案的价值，正在于把这一抽象分歧呈现为一个可感的案例。", "summary": "法律规范是规定“应当如何行为”的标准。中文法理学常把它拆为假定条件、行为模式与法律后果三要素；凯尔森以“如果X，那么Y”的条件—制裁模式还原规范结构，却因过度狭窄受到批评。哈特以批判反思态度区分规则与习惯，以义务规则与授权规则区分规范功能，并指出制裁只是“Plan B”——结婚、合同等授权规则的不遵守只导致无效而非处罚。哈特还提出开放结构：语言有清晰核心，也有临界案件，但词义并非任意。德沃金以 Riggs v. Palmer（1889）案说明法律包含以分量起作用的原则，规则模型不足以描述法律。三场争论——规则模型是否充分、开放结构意味着什么、强制是否本质——共同塑造了我们对法律规范结构的理解。", "furtherThinking": "1. 若一条规范没有制裁（如尊重国旗的告诫），它凭什么仍是法律规范？哈特的“Plan B”说法能否说明这一点？\n2. 德沃金说原则以分量起作用，哈特说原则须经承认规则识别。这两种说法是否可能同时成立？如果能，各自的层次是什么？\n3. 在自动驾驶、算法治理的场景中，当规则由代码写成，“假定条件—行为模式—法律后果”的结构会发生什么变化？开放结构会以何种形式重现？"}, "en": "The Structure of Legal Norms", "level": "core", "tags": "法律规范, 规则, 原则, 开放结构, 授权规则", "source": "Wacks, Understanding Jurisprudence, ch.4-5；Hart, The Concept of Law, ch.1, ch.7, Postscript；Siems, Comparative Law, ch.3", "id": "S1M2K6"}, "S1M3K1": {"title": "权利与义务", "EN": "Rights and Duties", "LEVEL": "core", "TAGS": "权利义务, 霍菲尔德, 权利理论, 法理学", "TERMS": "权利（Right）::法律上主体可主张的利益、自由、权力或豁免；义务（Duty）::法律要求主体为或不为一定行为的约束；主张权（Claim Right）::与他人义务相对应的权利，是狭义的『权利』；自由权（Liberty/Privilege）::主体可为或不为某事而他人不负相应义务；权力（Power）::主体通过其意志改变他人法律地位的能力；豁免（Immunity）::主体不受他人权力改变其法律地位的状态；相关性（Correlativity）::权利与义务如同一枚硬币的两面，一方存在意味着另一方存在；意志论（Will Theory）::以主体能否支配义务履行为权利本质的理论；利益论（Interest Theory）::以保护权利人的利益为权利目的的理论", "SOURCE": "Wacks, Understanding Jurisprudence, ch.10（尤其10.1、10.2、10.3）；Hart, The Concept of Law, ch.5；Siems, Comparative Law, Introduction", "terms": [{"term": "权利（Right）", "def": "法律上主体可主张的利益、自由、权力或豁免"}, {"term": "义务（Duty）", "def": "法律要求主体为或不为一定行为的约束"}, {"term": "主张权（Claim Right）", "def": "与他人义务相对应的权利，是狭义的『权利』"}, {"term": "自由权（Liberty/Privilege）", "def": "主体可为或不为某事而他人不负相应义务"}, {"term": "权力（Power）", "def": "主体通过其意志改变他人法律地位的能力"}, {"term": "豁免（Immunity）", "def": "主体不受他人权力改变其法律地位的状态"}, {"term": "相关性（Correlativity）", "def": "权利与义务如同一枚硬币的两面，一方存在意味着另一方存在"}, {"term": "意志论（Will Theory）", "def": "以主体能否支配义务履行为权利本质的理论"}, {"term": "利益论（Interest Theory）", "def": "以保护权利人的利益为权利目的的理论"}], "sections": {"coreQuestion": "『我有权利』这句话，几乎是现代人最熟悉的法律语言。可它究竟在说什么？说『我有言论自由的权利』和说『我有要求你还钱的权利』，是不是同一回事？再进一步：有权利就一定有人负有义务吗？警察有查处犯罪的职责，是否意味着每个市民都有权利要求警察办案？父母对未成年子女负有照顾义务，这是否意味着子女『拥有』一项可主张的权利？这些问题看似琐碎，却直指法律结构的心脏。权利与义务是法律关系的内容，是理解法律运作的第一把钥匙。本节要做的，是把这个被用得最滥的词拆开，看清它内部究竟有几种完全不同的东西。", "definition": "在日常语言里，『权利』是一个包裹得太紧的词。美国法学家韦斯利·霍菲尔德（Wesley Hohfeld）在《司法推理中适用的基本法律概念》中做了一次著名的拆解：命题『X 有权做 R』实际上可能表达四种彼此独立的意思。\n\n第一种是主张权（Claim Right），即 Y（或任何人）负有让 X 做 R 的义务，这是狭义的、真正意义上的『权利』。霍菲尔德自己的例子是：若 X 有权要求 Y 不得踏入 X 的土地，其对应面就是 Y 负有不得踏入该地的义务。第二种是自由权（Liberty，霍菲尔德称 privilege），即 X 可以自由地做或不做某事，而 Y 对 X 并不负有相应的义务——例如 X 有权戴帽子，只意味着 Y 没有『要求 X 不戴帽子』的权利，Y 完全可能把帽子全买下来不肯卖给 X。第三种是权力（Power），即 X 有能力通过自己的行为改变既有的权利、义务或法律关系，例如出售自己的财产。第四种是豁免（Immunity），即 X 不受 Y（或任何人）的权力支配，其法律地位不因他人意志而改变。\n\n霍菲尔德进一步为这四种法律关系配上了『对立面』（opposites）与『对应面』（correlatives）：主张权的对应面是义务，自由权的对应面是『无权利』（no-right），权力的对应面是责任（liability，即被他人改变法律地位的易受性），豁免的对应面是无能力（disability）。这套图式被 Wacks 称为分析法律权利的起点，至今仍是法理学入门的必修内容。", "history": "权利话语的兴盛，与近代个人主义的兴起同步。在古希腊罗马，法律讨论的中心是『正义』与『共同善』，而非个体可以主张的权利；罗马法中的『权利』（ius）更多指一种客观的秩序而非个人持有的东西。中世纪的神学把权利追溯到神的理性。真正把『权利』推到中心的，是近代的社会契约论与自然权利学说：霍布斯（Thomas Hobbes）、洛克（John Locke）、卢梭（Jean-Jacques Rousseau）假设人人原本处于一种『自然状态』，拥有某些先于国家和法律的权利，人们通过契约让渡部分权利以换取保护。美国《独立宣言》把『生命、自由与追求幸福』写成『不可转让的权利』，法国《人权宣言》则诉诸『天赋人权』，权利从此成为现代政治法律语言的通用语。\n\n进入二十世纪，权利概念在两次世界大战与极权主义的阴影下获得了新的紧迫性。1948 年联合国《世界人权宣言》（Universal Declaration of Human Rights）以及 1976 年两项国际公约的通过，使『人权』成为国际社会的共同语言。Wacks 指出，人权概念要说得通，就必须把它理解为根本的、不可剥夺的，无论它是否得到实在法的承认。权利从一种哲学修辞变成了法律体系的结构性要素。", "principle": "理解权利与义务，关键要抓住三层逻辑。\n\n第一层是『相关性命题』（correlativity thesis）。霍菲尔德认为，权利与义务如同一枚硬币的两面：说 X 拥有主张权，等于说 Y 对 X 负有义务；反之，说 Y 负有义务，也应能找到某个 X 拥有权利。这个命题抓住了法律关系的交互性——每一项法律纠纷至少涉及两方，法院必须回答『被告是否对原告负有义务』。J. W. 哈里斯（J. W. Harris）为霍菲尔德辩护时说，相关性是法律的『最小公分母』：即便严格说被告并不对原告负义务，诉讼也迫使我们以『原告—被告』的对应关系来描述它。\n\n第二层是对相关性的质疑。Wacks 提醒，刑法中的许多义务并不对应任何人的权利。警察负有举报犯罪的职责，却并不『欠』任何特定的人这份职责；系安全带的义务也通常不被理解为对某个具体的人负有。麦考密克（Neil MacCormick）更进一步：义务常常是为了保护权利而被设定的，其存在逻辑先于权利，而非与权利共存。这些反例说明，相关性是一个有力的分析工具，却不是覆盖一切情形的铁律。\n\n第三层是『权利的本质是什么』。这里分化出两种经典理论。哈特主张意志论（Will Theory）：权利的核心，是权利人对义务能否被履行拥有支配力，尤其是放弃（waive）他人义务的能力；权利保护的是个人的选择、自由与自我实现。麦考密克则主张利益论（Interest Theory）：权利的目的不在于保护选择，而在于保护权利人的某项利益；只要保护某人的利益是被承认的、设定义务的理由，他就可以说拥有权利。利益论能解释儿童的权利——儿童显然无法『放弃』什么，但没人会因此说儿童没有权利。", "viewpoints": "围绕权利，几位思想家给出了影响深远的主张。\n\n德沃金（Ronald Dworkin）提出著名的『权利作为王牌』（rights as trumps）命题：权利是先于并压倒一般福利考量的东西，它之所以应受保护，是因为它排除了『外部偏好』——即那种希望别人如何生活的偏好。德沃金认为，把外部偏好强加于人，等于判定他人是低等的、不配被平等对待；权利则表达了对每个人『平等关怀与尊重』（equal concern and respect）这一基本政治权利。不过他也承认，为避免灾难或取得重大利益时，连言论自由这样的基本权利也可能要让位于公共利益。\n\n哈特与麦考密克的分歧如上所述：前者看重『选择』，后者看重『利益』。Wacks 还介绍了杰沃斯（Alan Gewirth）的论证：我们无法在不承认权利重要性的前提下，为公共利益而否认他人的权利——因为要说服某人放弃其权利，至少得先承认他有思考的权利。这一论证试图为权利找到超越功利计算的哲学根基。", "comparison": "把几种立场并排看，分歧就更清楚了。\n\n在『权利与义务是否必然成对出现』上，霍菲尔德和哈特倾向于肯定（至少对主张权而言），而麦考密克和刑法义务的例子提示我们要谨慎。在『权利的本质』上，意志论看重权利人的支配与选择，利益论看重权利所服务的利益；前者解释契约权得心应手，后者解释儿童、精神障碍者的权利更有力。\n\n值得注意的是，Wacks 特别指出，这两种理论的支持者（麦考密克本人除外）通常都接受相关性命题，并把它作为论证的核心。同时也要警惕一种粗糙的漫画化：不能把意志论说成『权利人可以为所欲为』，也不能把利益论说成『只要对某人有好处就是他的权利』。两种理论都在认真地追问：当我们说『这是他的权利』时，我们究竟在承诺什么。", "debates": "权利领域最持久的争论，是权利能否被功利主义容纳。德沃金明确主张，任何功利主义都无法为认真对待权利提供充分基础；边沁（Jeremy Bentham）那一派则把权利视为『利益的剧场』，认为权利的价值最终要还原为普遍福利。反对者指出，功利主义承认权利，就等于把权利交给了幸福计算——今天算下来保护它划算就保护，明天不划算就剥夺，这样的权利不过是『脆弱的保证』。\n\n争论的另一条线索是权利的种类。Wacks 梳理了人权学说的三个代际：第一代是十七、十八世纪以消极自由为核心的政治公民权利；第二代是经济、社会、文化权利，本质上是积极权利；第三代是集体性的『团结权利』，包括发展权、健康环境权、和平权等。每一代的出现都伴随着争论：第二代权利能否像第一代那样得到司法救济？第三代权利是否只是政治口号？这些争论说明，权利的概念虽然被高频使用，其边界与内涵始终处在争议之中。", "case": "一个能展示相关性命题复杂性的案例，是英国的 Johnson v Phillips（1976）。案中一名警官在紧急情况下，指示驾车者逆行驶出单行道，以疏通交通。争执的焦点是：警察负有促进交通顺畅的义务，这一义务是否赋予某个特定的人以相应的权利？法院的判决给出的答案是：在这种情形下，并没有产生一项与警察义务相对应的个人权利。Wacks 把它与霍菲尔德的分析联系起来：这里存在一个一般性的、未被关联的『义务』，却找不到一个持有对应权利的特定主体。\n\n另一个例子是 Quinn v Leatham（1901）。在该案中，林德利勋爵（Lord Lindley）说，原告有权随心所欲地谋生，只要不违法、不侵犯他人权利，其『对应面是每个人都有不阻碍此项自由的一般义务』。霍菲尔德本人引用这段话，用来说明『自由』这种权利的确有一个对应的、一般性的义务。Wacks 却指出，这种说法其实站不住脚：我有权戴帽子，绝不意味着你就有义务不阻止我戴帽子——你大可以把帽子都买光。", "caseAnalysis": "就 Johnson v Phillips 而言，事实是一名警官为疏通交通而作出逆行指示；争议焦点是警官的义务是否对应个人权利；法院倾向于认为不存在这样的对应权利。这个案例的理论意义在于，它提醒我们：法律生活中的许多义务是『面向公众的』（public-regarding），它们维护的是一种秩序或公共利益，而不是为某个 identifiable 的个人创设一项可主张的权利。把每一项义务都硬塞进『某人有对应权利』的模子，反而会扭曲我们对法律现实的理解。\n\nQuinn v Leatham 的案例则展示了相反方向的陷阱：把『自由』误当成『要求他人不干涉的权利』。霍菲尔德的贡献正在于让我们看清，自由权与主张权是两种不同性质的东西——前者只是说『我可以做，且我不因此欠谁义务』，后者才是『你必须做，因为我有权要你做』。把两者混为一谈，就会把『我做得到』误解成『别人有义务让我做』。这两个案例一正一反，恰好勾勒出相关性命题的适用边界。", "summary": "权利与义务是法律结构的基本单元，但『权利』一词包裹着至少四种不同的法律关系：主张权、自由权、权力与豁免。霍菲尔德的相关性命题揭示了权利与义务在结构上的对应关系，尤其是主张权与义务的共生关系；这一命题虽有力，却在刑法义务、一般性义务等场合遭遇反例，需要谨慎对待。在权利的本质问题上，哈特的意志论强调选择与支配，麦考密克的利益论强调利益保护，二者各有解释力。德沃金的『权利作为王牌』把权利提升到压倒福利的高度，却也不得不承认极端情形下权利可让位于公共利益。理解权利，关键是先分清它属于哪一种法律关系，再追问它保护的是什么。", "furtherThinking": "1. 如果一项义务不对应任何人的权利（如警察追捕罪犯的职责），那么当警察怠于履职时，谁有资格提起诉讼？这是否说明『权利』概念并非法律救济的必要前提？\n2. 用利益论解释『儿童权利』似乎更顺畅，但它会不会把权利标准放得太宽，以至于任何对某人有利的事情都变成了一项权利？利益论该如何划定边界？\n3. 德沃金把权利比作『王牌』，可他本人又承认紧急状态下权利可以被压倒。那么权利究竟是无条件的王牌，还是一种分量较重的理由？这个保留会不会削弱他的整个理论？"}, "en": "Rights and Duties", "level": "core", "tags": "权利义务, 霍菲尔德, 权利理论, 法理学", "source": "Wacks, Understanding Jurisprudence, ch.10（尤其10.1、10.2、10.3）；Hart, The Concept of Law, ch.5；Siems, Comparative Law, Introduction", "id": "S1M3K1"}, "S1M3K2": {"title": "自由与责任", "EN": "Liberty and Responsibility", "LEVEL": "fundamental", "TAGS": "自由, 责任, 强制, 言论自由, 法理学", "TERMS": "自由（Liberty/Freedom）::主体可按自己意志行动而不受外部强制的状态；消极自由（Negative Liberty）::免于他人或国家干涉的自由；积极自由（Positive Liberty）::主体得以自我实现、参与自治的实质能力；责任（Responsibility）::主体因其行为而应承受法律评价或后果的地位；强制（Coercion）::以威胁或不利后果迫使他人行动；必要性抗辩（Defence of Necessity）::为避免更大损害而实施通常违法行为的抗辩事由；言论自由（Freedom of Expression）::表达思想与意见而不受不当限制的自由", "SOURCE": "Wacks, Understanding Jurisprudence, ch.10.6；Hart, The Concept of Law, ch.1, ch.5；Leslie Green 导论, 'Law and Power'", "terms": [{"term": "自由（Liberty/Freedom）", "def": "主体可按自己意志行动而不受外部强制的状态"}, {"term": "消极自由（Negative Liberty）", "def": "免于他人或国家干涉的自由"}, {"term": "积极自由（Positive Liberty）", "def": "主体得以自我实现、参与自治的实质能力"}, {"term": "责任（Responsibility）", "def": "主体因其行为而应承受法律评价或后果的地位"}, {"term": "强制（Coercion）", "def": "以威胁或不利后果迫使他人行动"}, {"term": "必要性抗辩（Defence of Necessity）", "def": "为避免更大损害而实施通常违法行为的抗辩事由"}, {"term": "言论自由（Freedom of Expression）", "def": "表达思想与意见而不受不当限制的自由"}], "sections": {"coreQuestion": "自由和责任常常被当成一对反义词：自由多了，责任就少了；管得严了，自由就缩了。可法律上的真实关系要微妙得多。为什么一个被持枪歹徒逼着去犯罪的人，通常不被追究刑事责任？为什么一个自愿签下合同的人，即使后来后悔也要承担履约责任？自由让人得以选择，而选择似乎正是责任的前提——可一旦选择被强制扭曲，责任又随之撤退。本节要厘清：法律上的自由究竟意味着什么？它和责任之间是一种什么关系？当自由发生冲突时（比如一方的言论自由与另一方的尊严），法律又如何权衡？", "definition": "自由（Liberty/Freedom）在法律上有两种基本用法。消极意义上的自由，是『免于干涉』：霍菲尔德所说的自由权，指的是主体可以做某事而他人并不负有阻止的义务；你有权戴帽子，不等于别人有义务供给你帽子。积极意义上的自由，则强调主体实际具备按自己意志行动、参与自我治理的能力，它关心的不只是『没人拦你』，还有『你有没有真正的选择条件』。\n\n责任（Responsibility）是一个多维概念。在刑法里，它意味着主体因其行为具备可归责性，应承受刑罚；在民法里，它常指对损害后果承担赔偿或履约的义务。哈特（H. L. A. H. Hart）特别区分了『被迫去做』（being obliged）与『有义务去做』（having an obligation）：持枪的威胁能让人『不得不』交出钱包，却并不产生『应当交出』的规范义务。这句话是理解自由与责任关系的钥匙——责任以意志的自愿性为根基，当意志被强制彻底压倒，责任的根基也就松动了。", "history": "近代自由观念的成型，与社会契约论者的思考密不可分。霍布斯（Thomas Hobbes）在《利维坦》里描绘的自然状态，是人人自由却彼此为战的图景；人们让渡部分自由给主权者，换取生命与财产的安全。洛克（John Locke）则主张，人们让渡的只是执行自然法的权利，生命、自由、财产这些基本权利是不可让渡的。这两种思路奠定了后世自由理论的两种取向：一种强调秩序与安全对自由的前提性，一种强调个体权利对国家权力的优先性。\n\n二十世纪，自由问题获得了新的制度表达。美国宪法第一修正案（First Amendment）明言『国会不得制定法律……剥夺言论或出版自由』；英国则在 1998 年《人权法》（Human Rights Act 1998）中把《欧洲人权公约》的权利引入国内法。Wacks 指出，在英国，法院在《人权法》的影响下，对表达自由的理解趋于宽泛。同一时期，政治哲学中出现了以赛亚·伯林（Isaiah Berlin）对消极自由与积极自由的经典区分，为分析自由概念提供了至今仍在使用的框架。", "principle": "理解自由与责任的关系，可分三步。\n\n第一，自由是责任的前提。法律通常只对具备选择能力的人归责。一个精神病人或幼童造成损害，之所以责任能力受限，正因为其自由选择的能力不足。哈特在讨论法律与权力时指出， people who are forced by threat to do things are generally not held responsible——被威胁迫使的人之所以不被追责，是因为他们的意志被压倒（will is overborne）。这与哈特对『义务』的规范性理解是一致的：义务预设了主体能够理解并遵守规则。\n\n第二，责任也为自由划定边界。我的自由止于你的自由开始之处。言论自由之所以需要边界，正因为滥用表达会侵害他人的尊严、名誉或安全。Wacks 在讨论言论自由时指出，自由主义理论家一般把表达自由当作一项权利，德沃金（Ronald Dworkin）更把它与人的尊严、平等关怀与尊重联系起来；但这个权利也要与诽谤法、 obscenity 法所保护的利益相平衡。\n\n第三，自由之间存在冲突，需要权衡而非绝对化。密尔（John Stuart Mill）的『真理论证』认为，压制任何言论都是『假定自己 infallible（不会犯错）』，只有让思想自由流通，真理才能被发现。Wacks 则提醒，密尔关于客观真理存在与理性必胜的预设都值得怀疑；施auer（Frederick Schauer）也追问：真理本身是不是服务于更深层的善（如幸福或尊严）？如果真理只是工具性的，那『思想自由市场』的论证就不再是无条件的。", "viewpoints": "在自由与责任的关系上，两位作者的观点值得对照。\n\n哈特关注的是自由的法律结构。他强调，法律规则既设定义务，也授予权力；授权性规则（power-conferring rules）让人得以通过遗嘱、合同、婚姻来塑造自己的法律世界，把私人公民变成『私人立法者』。这种『造法能力』正是自由在法律中的积极体现。同时，哈特坚持义务与威胁的根本区分：法律之所以能产生义务，是因为它被从『内部观点』接受为行为标准，而非仅仅因为背后有制裁。\n\n德沃金则从权利角度为自由辩护。他把言论自由视为与人格尊严相关的基本权利，这项『王牌』可以压倒共同体压制言论的利益。不过德沃金也承认，当表达造成对他人的伤害时，自由主义内部本身也有争论：究竟保护的是说话者的自我实现，还是听众获取信息的利益？Wacks 指出，保护听众的论证多属政策论证（基于共同体利益），保护说话者的则多属原则论证（基于个人优先）。", "comparison": "把消极自由与积极自由并排看，能看清政策分歧的根源。\n\n消极自由要求『别管我』，倾向于限制国家的干预，强调言论、信仰、契约的自由；积极自由要求『让我有能力做』，倾向于国家提供教育、社会保障等条件，使自由成为实质而非形式。这两种取向并非简单对立：现代宪法往往同时保护免于干涉的自由，并通过社会权保障实质条件。Wacks 梳理的人权三代际，恰好对应了这一演变：第一代的消极权利、第二代的积极社会经济权利、第三代的集体团结权利。\n\n在言论自由的论证上，也可以看到类似的对照：密尔、米尔顿（Milton）式的真理论证和民主论证属于后果论，看重自由带来的社会好处；德沃金式的权利论证则属于原则论，看重自由对人的尊严的意义。Wacks 提醒，这两种论证有时会被混合甚至混淆，学生在分析时应当把它们拆开，看清各自的前提和力度。", "debates": "自由领域最经典的争论，是强制与责任的关系。一个被胁迫的人是否该为自己的行为负责？这个问题在刑法中通过『必要性抗辩』（Defence of Necessity）呈现。富勒（Lon L. Fuller）在 1949 年发表的虚拟案例『洞穴探险者案』（The Case of the Speluncean Explorers），把这一问题推到极致：几名被困的探险者为活命而抽签决定吃掉其中一人，幸存者是否构成谋杀？这个案例基于两起真实的普通法判例——英国的 R v Dudley & Stephens（1884）与美国的 US v Holmes（1842）。\n\n在这个问题上，分歧双方都很坚决。一种观点认为，饥饿与死亡威胁压倒了意志，被逼到绝境的人没有真正的选择，不应被归责；另一种观点则认为，法律不能认可『以命换命』的逻辑，否则会打开任意剥夺他人生命的闸门，即便是抽签也不能使杀人正当化。富勒通过几位态度各异的法官意见，展示了法律原则之间的张力。Wacks 把它收入教材，正是因为它生动地说明：自由与责任的边界，往往在最极端的情境中才被真正检验。", "case": "一个能展示自由与责任之张力的现实案例，是美国的言论自由判例传统。美国宪法第一修正案对言论自由提供了世界上最强水平的保护之一，法院多次判决，即使令人反感的言论也受保护——这背后是『思想自由市场』的信念：应对有害思想的最佳办法是更多言论，而非审查。\n\n与之对照，英国采取的是另一种平衡路径。在《人权法 1998》框架下，表达自由是受保护的权利，但法院更愿意在言论自由与其他价值（如名誉权、公共秩序）之间作利益衡量。Wacks 指出，英国法院在人权法的影响下对表达自由的理解趋向宽泛，但并未采纳美国那种近乎绝对的保护模式。这一美英对比提醒我们：同样是『言论自由』，在不同宪法传统中有着不同的保护强度与权衡方式，把它当成一套放之四海而皆准的规则是危险的。", "caseAnalysis": "就洞穴探险者案（及其背后的 R v Dudley & Stephens）而言，事实是幸存者在极端饥饿下杀死并食用了一名同伴；争议焦点是必要性能否成为谋杀罪的抗辩；法律依据是普通法中必要性抗辩的严格界限。法院最终拒绝把必要性扩展到杀人——即便不杀也会死，法律仍要求对生命保持尊重。这个案例的理论意义在于，它划定了自由与责任的极限：极端情境确实削弱了选择的自愿性，但法律共同体仍坚持某些底线不因情境而让渡。\n\n它给我们的启示是双重的。一方面，责任以自由为前提，当意志被彻底压倒，归责的确会变得困难；另一方面，自由并非无限，法律会用原则为它设界，即便在生死关头亦然。把这两个方面结合起来，才能理解为什么法律既会因胁迫而减免责任，又会为自由划定不可逾越的边界。", "summary": "自由与责任彼此依存：责任以主体的自由选择为前提，自由又因责任而获得边界；把二者看成此消彼长的对手会失准。消极自由强调免于干涉，积极自由强调实质的选择能力；哈特对『被迫』与『义务』的区分、对授权性规则的分析，揭示了自由在法律中的规范结构。在言论自由领域，密尔的真理论证与德沃金的权利论证分别代表了后果论与原则论的路径，美英两国则发展出保护强度不同的制度模式。洞穴探险者案表明，即便在生死关头，自由与责任的边界仍需通过原则权衡来划定，而不是交给单纯的功利计算。", "furtherThinking": "1. 密尔的『真理论证』预设了理性最终会战胜谬误。如果在一个信息被算法操纵、假新闻泛滥的环境里，这个预设不再成立，思想自由市场还能自证其正当性吗？\n2. 哈特说被威胁者『没有真正的选择』所以不承担责任。但哲学家普遍认为，胁迫并不取消选择，只是让选择的代价变得极高。这两种看法哪一种更符合法律实践？\n3. 美国对言论自由近乎绝对的保护，与英国的利益衡量模式，哪一种更好地平衡了自由与尊严？请结合具体情境说明理由。"}, "en": "Liberty and Responsibility", "level": "fundamental", "tags": "自由, 责任, 强制, 言论自由, 法理学", "source": "Wacks, Understanding Jurisprudence, ch.10.6；Hart, The Concept of Law, ch.1, ch.5；Leslie Green 导论, 'Law and Power'", "id": "S1M3K2"}, "S1M3K3": {"title": "法律主体", "EN": "Legal Subjects", "LEVEL": "fundamental", "TAGS": "法律主体, 权利能力, 行为能力, 自然人, 比较法", "TERMS": "法律主体（Legal Subject）::能享有权利、承担义务并参与法律关系的主体；自然人（Natural Person）::基于出生而取得法律人格的人；法律主体资格（Legal Personality）::作为权利义务承载者的法律地位；权利能力（Legal Capacity）::作为权利义务主体的法律资格；行为能力（Capacity to Act）::以自己的行为独立取得权利、承担义务的能力；法人（Juridical/Legal Person）::法律拟制的人，可独立享有权利与承担义务；无能力（Disability/Incapacity）::法律上不能独立实施有效法律行为的状态", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Hart, The Concept of Law, ch.4；Siems, Comparative Law, Introduction & ch.7", "terms": [{"term": "法律主体（Legal Subject）", "def": "能享有权利、承担义务并参与法律关系的主体"}, {"term": "自然人（Natural Person）", "def": "基于出生而取得法律人格的人"}, {"term": "法律主体资格（Legal Personality）", "def": "作为权利义务承载者的法律地位"}, {"term": "权利能力（Legal Capacity）", "def": "作为权利义务主体的法律资格"}, {"term": "行为能力（Capacity to Act）", "def": "以自己的行为独立取得权利、承担义务的能力"}, {"term": "法人（Juridical/Legal Person）", "def": "法律拟制的人，可独立享有权利与承担义务"}, {"term": "无能力（Disability/Incapacity）", "def": "法律上不能独立实施有效法律行为的状态"}], "sections": {"coreQuestion": "走进一间教室，你会看到几十个学生；走进一家公司，你会看到员工、经理、股东。可在法律眼里，这些人并不都以同样的身份出现。有的能签合同，有的签了也无效；有的能起诉应诉，有的必须由监护人代理。更奇怪的是，公司明明是一堆纸张和招牌的组合，法律却允许它『起诉』和『被起诉』，像一个人那样行动。法律凭什么决定谁是『人』、谁不是？一个刚出生的婴儿、一个植物人、一家跨国公司，它们在法律上的地位有何不同？本节就是要弄清：成为法律的『主体』，需要具备什么资格。", "definition": "法律主体（Legal Subject），指能够成为权利和义务的承载者、并能参与法律关系的实体。在大陆法系（civil law）传统中，这通常被分解为两种资格：权利能力（Legal Capacity），即作为权利义务主体的资格；行为能力（Capacity to Act），即以自己的行为独立取得权利、承担义务的能力。两者并不重合：一个婴儿有权利能力（可以拥有财产、继承遗产），却没有行为能力（不能独立签合同）。\n\n西方法律传统中，法律主体主要分两类。自然人（Natural Person）基于出生而取得法律人格；法人（Juridical/Legal Person）则是法律拟制的人，诸如公司、社团、基金会，可独立享有权利与承担义务。罗马法最早发展出『人格』（persona）的概念，并用身份（status）来界定谁能成为权利主体——奴隶在罗马法中是权利的客体而非主体。Wacks 指出，『身份』一词曾长期承载着这种区分：某些存在物在获得法律承认的『身份』之前，并不被当作可持有权利的主体。", "history": "法律主体概念的演变，是一部『谁能算作人』的扩张史。在古罗马，只有自由的罗马公民才具备完整人格，奴隶、外邦人和家子（处于家父权下的子女）都受到不同程度的能力限制。中世纪欧洲，封建身份把人绑定在等级与土地上。近代自然权利学说和政治契约论改变了这一切：霍布斯（Thomas Hobbes）、洛克（John Locke）、卢梭（Jean-Jacques Rousseau）都从某种意义上的『自然人』出发，主张人生而自由平等，法律主体资格因而获得了普遍化的哲学基础。\n\n法人制度则是另一条线索。罗马法已承认某些团体具有独立人格；中世纪教会法发展出『社团人格』理论；到十九世纪，随着公司制度的勃兴，法人成为现代经济生活的核心主体。Wacks 讨论人权概念时指出，十八世纪末法国《人权宣言》与英国普通法传统对『人』的理解并不完全一致——美国革命诉诸『天赋人权』，而英国更强调渐进的、判例式的权利确认。Siems 则提醒，比较法研究不能预设各国对『法律主体』的理解完全一致，(contextual approach，语境化方法)要求把这些概念放回各自的法律文化中考察。", "principle": "理解法律主体，可从三个层次推进。\n\n第一层是『承载者』资格。霍菲尔德（Wesley Hohfeld）的法律关系图式以『人』为基本单位，每一项权利、义务、权力、豁免都归属于特定的主体。哈特（H. L. A. Hart）进一步指出，主权者与被统治者的传统模型，把社会成员想象为习惯性服从的『臣民』；但现代法律体系中，主体不仅承担义务，更能通过授权性规则（遗嘱、合同、婚姻）创设自己的法律世界，成为『私人立法者』。\n\n第二层是能力分级。权利能力与行为能力的分离，是法律保护与法律自治之间的平衡。法律赋予婴儿权利能力，是为了保护其利益；限制其行为能力，是为了防止其因判断力不足而受损。哈特提到，行使立遗嘱、订合同等权力需要具备『能力或最低个人资格』（如成年、神志正常）——这正是法律通过规则设定主体资格的方式。\n\n第三层是法人的特殊性。公司作为独立的法律主体，其意志通过机关（董事会、股东会）形成，其责任以财产为限。Siems 在比较公司法时提到『揭开公司面纱』（piercing the corporate veil）的制度：当股东滥用公司独立人格时，法院可否认其独立地位，追究股东个人责任。这一制度恰好说明，法人的独立人格是一种法律技术，可以被维护，也可以在极端情形下被穿透。", "viewpoints": "关于法律主体的本质，两位作者提供了不同视角。\n\n哈特关注的是规则如何构造主体。他反对把法律简化为『主权者命令臣民』的模型，强调正是次级规则（尤其是承认规则、改变规则、裁判规则）的出现，使一个社会从松散的初级规则状态进入法律世界。在这样的体系里，主体身份由规则界定：谁有权立法、谁有权裁判、谁具备订约能力，都是规则配置的结果。哈特还用『一人二角』的例子说明：立法者以公职身份立法，以私人身份守法——同一个自然人可以同时占据不同的法律主体位置。\n\nSiems 则从比较法角度强调语境。他指出，比较法研究者若假定各国都有相同的法律主体概念，会被误导；中国、日本等国既有成文法典，也有类似的法学教育方式，律师和法官会就实在法的细节（如揭开公司面纱）展开技术性讨论。这说明，法律主体虽是普适的分析范畴，其具体内容却镶嵌在各国的制度语境之中。", "comparison": "把不同法系对法律主体的处理并排看，能看清各自特点。\n\n在大陆法系，法律主体资格通常由法典明文规定：德国《民法典》（Bürgerliches Gesetzbuch, BGB）以『人』为第一编的核心，自然人的权利能力始于出生、终于死亡，法人则另有专章规定。这种法典化路径追求概念的抽象与体系的严整。英美法系（common law）则更多通过判例逐步界定主体的能力与责任边界，概念上更经验、更灵活。Wacks 提醒，不能把两大法系的区别绝对化：现代英国也有成文的人权法，德国法也高度依赖判例的发展。\n\n在自然人与法人的关系上，两种法系都承认法人可独立享有权利，但对法人本质的理解有差别：有的理论把法人视为实实在在的『有机体』（如德国的团体人格说），有的则视其为法律技术的拟制（如英格兰的『特许权说』）。Siems 指出，公司法的治理模式（股东中心还是利益相关者中心）在不同国家差别很大，这些都影响到法律主体的构造。", "debates": "法律主体领域最根本的争论，是『人格的边界』。谁有资格成为法律主体？历史上，奴隶、妇女、殖民地人民、精神障碍者都曾被排除或部分排除在完整的法律主体资格之外。废奴运动、妇女解放运动、民权运动，本质上都是争取法律主体资格的斗争。Wacks 在讨论动物权利时把这一争论推向极致：动物能否成为拥有权利的主体？支持者认为，动物有感受痛苦的利益，应当被承认为权利主体；反对者（如 RG Frey）则认为，权利概念对动物而言是『多余的累赘』（rights as excess baggage），利益本身不足以构成权利。\n\n争论的焦点在于：成为法律主体的门槛究竟是什么？是理性与自主意志（康德式标准），还是感受利益的能力（功利主义标准）？如果采用前者，婴儿、精神障碍者和动物都难以符合；如果采用后者，门槛又似乎太低。Wacks 指出，这两种标准的冲突至今未有定论，它提醒我们：法律主体需要被论证和辩护，它从来都是一项法律判断，算不得自明的事实。", "case": "一个能展示法律主体资格如何被争夺的现代场景，是公司法中的『揭开公司面纱』。正常情况下，公司作为独立法人，股东仅以出资额为限承担责任，这正是公司独立人格的核心价值。但在某些情形下——例如股东利用公司转移资产、逃避债务，或公司资本显著不足、人格混同——法院会否认公司的独立人格，直接追究股东的责任。\n\nSiems 把这一现象作为比较法研究中『 Western 与 Eastern 法律文化并非不可调和』的例子：即便是被认为更强调关系与语境的东方社会，其法院同样会就公司面纱这类高度技术化的实在法问题展开专业讨论。这个案例说明，法人的独立人格既是法律赋予的特权，也伴随着被穿透的风险；法律主体资格从来都可以被有条件地承认或否认，绝无绝对可言。", "caseAnalysis": "就『揭开公司面纱』而言，事实是股东利用公司独立地位损害债权人利益；争议焦点是公司人格能否被否认；法律依据是公司法中关于法人人格否认的规则与判例。法院的裁判逻辑在于：当独立人格被滥用为规避责任的工具时，继续维护它就背离了公平。这个案例的理论意义在于，它把法律主体从一个抽象概念还原为一种可以被权衡的制度安排。\n\n它同时提醒学习者：权利能力与行为能力、自然人与法人，这些分类都是法律为特定社会目的而设计的工具，自然事实的反映只是表层观感。理解法律主体，关键落在追问上：法律为什么要赋予某类实体以主体资格？背定义帮不上忙。这种资格在什么条件下会被限制或剥夺？", "summary": "法律主体是能够享有权利、承担义务并参与法律关系的实体，其资格由法律规则配置，而非自然事实的自动结果。权利能力与行为能力的分离，体现了法律保护与法律自治的平衡；自然人与法人的二分，则展示了法律拟制技术的力量。哈特揭示了规则如何构造主体并把人变成『私人立法者』，Siems 提醒我们法律主体概念必须放在具体法律语境中理解。围绕人格边界的争论——从奴隶解放到动物权利——表明，谁能成为法律主体始终是一个需要被论证的问题。揭开公司面纱的制度进一步说明，法律主体资格是可以被有条件地承认或否认的制度安排。", "furtherThinking": "1. 如果法律主体资格取决于理性与自主意志，那么婴儿、严重精神障碍者和植物人是否应被排除在完整的主体资格之外？如果取决于感受利益的能力，门槛又是否过低？请给出你自己的标准并论证。\n2. 法人既然是法律拟制的人，它能否像自然人一样享有尊严和人权？赋予公司『人格权』在逻辑上和实践中会遇到什么困难？\n3. 揭开公司面纱制度在不同国家的适用标准差异很大。这种差异说明法律主体概念具有怎样的性质？比较法研究应如何处理这种差异？"}, "en": "Legal Subjects", "level": "fundamental", "tags": "法律主体, 权利能力, 行为能力, 自然人, 比较法", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Hart, The Concept of Law, ch.4；Siems, Comparative Law, Introduction & ch.7", "id": "S1M3K3"}, "S1M3K4": {"title": "法律人格", "EN": "Legal Personality", "LEVEL": "core", "TAGS": "法律人格, 法人, 公司人格, 权利能力, 比较法", "TERMS": "法律人格（Legal Personality）::作为权利义务主体的法律地位与资格；自然人人格（Natural Personality）::基于出生而取得的、每个人平等享有的法律人格；法人人格（Juridical Personality）::法律拟制的人所享有的独立主体地位；独立人格（Separate Personality）::法人与其成员在法律上相互区分的状态；有限责任（Limited Liability）::股东仅以出资额为限对公司债务承担责任；揭开公司面纱（Piercing the Corporate Veil）::在人格被滥用时否认法人独立地位、追究成员责任的制度；人格权（Personality Rights）::保护主体人格利益的权利", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Hart, The Concept of Law, ch.4, ch.5；Siems, Comparative Law, ch.7", "terms": [{"term": "法律人格（Legal Personality）", "def": "作为权利义务主体的法律地位与资格"}, {"term": "自然人人格（Natural Personality）", "def": "基于出生而取得的、每个人平等享有的法律人格"}, {"term": "法人人格（Juridical Personality）", "def": "法律拟制的人所享有的独立主体地位"}, {"term": "独立人格（Separate Personality）", "def": "法人与其成员在法律上相互区分的状态"}, {"term": "有限责任（Limited Liability）", "def": "股东仅以出资额为限对公司债务承担责任"}, {"term": "揭开公司面纱（Piercing the Corporate Veil）", "def": "在人格被滥用时否认法人独立地位、追究成员责任的制度"}, {"term": "人格权（Personality Rights）", "def": "保护主体人格利益的权利"}], "sections": {"coreQuestion": "一家公司欠下巨债，债权人能否直接找老板要钱？ ordinarily 不能——因为公司是一个独立的『人』，债务是它的，不是老板的。可如果老板把公司当成提款机，用公司名义借债、把钱转进自己腰包，法律还认不认这道墙？再往前追问：法律凭什么把一家由纸张、招牌和银行账户组成的组织当作『人』？这个『人』和血肉之躯的自然人，在法律上到底是不是一回事？公司有没有『尊严』，能不能主张人权？这些问题逼我们面对一个更根本的追问：法律人格究竟是一种自然事实，还是一项法律技术？本节将沿着罗马法的人格概念、近代的自然权利学说，一直追到现代公司法中的人格否认制度。", "definition": "法律人格（Legal Personality），指某一实体作为权利义务主体而存在的法律地位。它是『成为法律上的人』的资格，回答的是『谁可以持有权利、承担义务、参与法律关系』这一前置问题。在大陆法系法典中，法律人格通常与权利能力（Rechtsfähigkeit）紧密相连：一个人格者，就是能够成为权利义务承载者的人。\n\n法律人格有两张面孔。自然人人格（Natural Personality）基于出生而取得，在现代法治国家，每个自然人平等地享有人格，不因身份、性别、种族而有差别——这与罗马法时代人格被身份等级切割的状况形成鲜明对照。法人人格（Juridical Personality）则是法律拟制（legal fiction）的产物：公司、社团、基金会等组织，被法律承认为『人』，可独立持有财产、签订合同、起诉应诉，并在很多情形下仅以自身财产对外承担责任。\n\n需要区分的是，法律人格不等于生物学意义上的人。霍菲尔德（Wesley Hohfeld）的法律关系图式以『人』为单位，但这里的『人』是法律关系的节点，而非血肉之躯。同样，哈特（H. L. A. Hart）也提醒，同一自然人可以占据不同的法律人格位置：立法者以公职身份立法，又以私人身份守法——人格是规则配置的结果。", "history": "法律人格的概念，可以追溯到罗马法。罗马法用『人格』（persona）与身份（status）来界定谁能成为权利主体：只有自由的罗马公民才具备完整人格，奴隶是权利的客体，家子（处于家父权下的子女）的人格也受到限制。Wacks 指出，『身份』一词长期承载着这种区分——某些存在物在获得法律承认的『身份』之前，并不被当作可持有权利的主体。法律人格在起源上，是一种区隔与排斥的技术。\n\n近代自然权利学说彻底改写了自然人人格。霍布斯（Thomas Hobbes）、洛克（John Locke）、卢梭（Jean-Jacques Rousseau）从某种『自然人』出发，主张人生而自由平等；康德的道德哲学更把人格尊严建立在理性与自主意志之上。美国《独立宣言》的『天赋人权』、法国《人权宣言》的『人生而自由且权利平等』，把普遍平等的人格写进政治法律文件。自然人人格从此获得了普遍化的哲学基础。\n\n法人人格的演变是另一条线索。罗马法已承认某些团体具有独立人格，中世纪教会法发展出社团人格理论，十九世纪公司制度的勃兴使法人成为经济生活的核心主体。英国通过 1844 年《公司法》与 1856 年《公司法》逐步确立公司独立人格与有限责任原则；随后 Salomon v A Salomon & Co Ltd（1897）这一上议院判例，把『公司与其成员相互独立』确立为普通法的基本原则。Siems 则提醒，研究这些制度必须放回各自的法律文化语境，不能假定各国对人格的理解完全一致。", "principle": "理解法律人格，可分四层。\n\n第一层是『主体化』的逻辑。法律在这里做的是构造『人』；把『人』当作现成摆在那里、只待被发现的对象，恐怕站不住。当法律说某公司是『法人』，它是在赋予该组织一系列法律能力：持有财产、缔结合同、承担责任。哈特指出，这些能力来自授权性规则（power-conferring rules）——正是规则使人能够设立公司、订立遗嘱、缔结婚姻，从而塑造自己的法律世界。人格因此是规则赋予的地位，而非自然生成的属性。\n\n第二层是独立人格与有限责任。公司独立人格的核心是：公司财产与股东财产分离，公司以自身财产对外承担责任，股东仅以出资额为限负责。这带来巨大的经济功能——鼓励投资、降低风险、使资本得以聚集成大规模企业。Siems 在比较公司法时指出，股东中心模式与市场导向的治理结构，在英美与欧洲大陆呈现出不同形态，但独立人格与有限责任是现代公司法的共同基石。\n\n第三层是人格的否认与穿透。独立人格一旦被滥用，法律便准备把它刺穿。Siems 提到『揭开公司面纱』（piercing the corporate veil）制度：当股东利用公司转移资产、逃避债务、导致人格混同时，法院可否认公司的独立地位，直接追究股东责任。这说明法律人格是一种可被维护、也可被穿透的制度工具——它的边界由法律根据公平与效率来判断。\n\n第四层是人格的扩张与争议。当法人被承认为『人』，是否也应享有某些人权与人格权？自然人的人格权保护生命、名誉、隐私等人格利益；公司能否主张『名誉权』或『言论自由』？这一问题在各国宪法与判例中的答案并不一致，它把法律人格从技术概念推向了价值争论。", "viewpoints": "围绕法律人格，几位作者提供了关键视角。\n\n哈特把人格放在规则理论的框架里。他反对把法律理解为『主权者对臣民的命令』，强调正是初级规则与次级规则的结合构成了法律体系。在这样的体系中，主体身份是规则配置的产物：谁有资格订立合同、设立公司、提起诉讼，都由规则界定。哈特还用『一人二角』的例子说明：同一个自然人可以同时以公职身份和私人身份出现——法律人格可以被拆分，这正说明人格是制度构造而非生物事实。\n\nSiems 从比较法角度强调语境的重要性。他指出，比较法研究者若假定各国对法律主体的理解完全一致，会被误导。中国、日本等国的法院同样会就揭开公司面纱这类高度技术化的实在法问题展开专业讨论——这说明法律人格制度虽普遍存在，其具体形态却镶嵌在各国制度语境之中。Wacks 则通过自然权利学说与动物权利争论，展示了人格概念背后的哲学张力：人格的门槛究竟是理性自主，还是感受利益的能力？", "comparison": "把自然人人格与法人人格并排看，差异十分清楚。\n\n自然人人格基于出生，普遍、平等、不可让与；法人人格基于法律的承认，其范围由设立目的与法律规定限定。自然人享有人格权，受宪法基本权利保护；法人的权利则主要围绕财产与经营活动展开。二者也有共同点：都能作为权利义务的承载者，都能起诉应诉，都在法律关系的网络中占据节点位置。\n\n在法人本质问题上，存在两种经典理论。『拟制说』认为法人并无真实意志，其人格是法律为便利而拟制的，权利能力来自国家的授予；『实在说』或『有机体说』则认为法人是具有自身意志与目的的实在社会团体，人格是其固有属性。德国学说的团体人格理论更接近后者，英美传统的特许权说则更接近前者。Siems 指出，不同国家公司治理模式的差异（股东中心还是利益相关者中心），与这些理论取向有深层关联。", "debates": "法人是否应被承认为享有基本权利的『人』，是当代最活跃的争论之一。\n\n支持赋予法人基本权利的理由在于：法人拥有独立于成员的财产与意志，其活动（如出版、传教、经营）本身就是基本权利所要保护的对象；若法人不能主张言论自由或宗教自由，这些权利在组织化时代就会落空。美国判例中，法院曾承认公司享有某些宪法保护（如就近出版自由），并出现过著名的 Citizens United v Federal Election Commission（2010）关于公司政治献金的争议。\n\n反对意见同样有力：基本权利的价值根基是人的尊严与自主，而公司没有感受痛苦或追求自我实现的能力，把人权赋予公司会稀释人权概念，并使资本力量借人权之名获得不当的政治影响。Wacks 在讨论动物权利时呈现的『理性自主 vs 感受利益』标准之争，在这里以相反的方向重演：公司有理性决策机制，却无感受能力——它恰恰暴露了任一标准的局限。争论至今未有定论，它提示我们：法律人格是法律 technology，但把它延伸到何处，终究是一个价值判断。", "case": "Salomon v A Salomon & Co Ltd（1897）是确立公司独立人格的里程碑判例。Salomon 把自己的企业卖给一家按公司法设立的公司，自己与公司及其家人作为股东，公司则以债券形式欠他一笔钱。公司后来破产，债权人主张：公司不过是 Salomon 的『另一个自我』，他应对公司债务负责。上议院拒绝这一主张，确认公司自注册之日起就是一个独立的法律人格，其债务与股东个人财产分离，Salomon 作为有担保债权人还可优先受偿。\n\n这个判例奠定了普通法系公司独立人格与有限责任的基石。Wacks 在该书论及『自然人与法律人格』时强调，人格是法律规则构造的结果；Salomon 案正是这一命题的经典注脚——法律把一个组织当作独立的『人』，完全是规则运作的产物。与之相对，Siems 提到的『揭开公司面纱』制度，则代表了同一逻辑的另一面：当独立人格被滥用为逃避责任的工具时，法院会刺穿这层面纱。", "caseAnalysis": "就 Salomon 案而言，事实是股东兼债权人主张公司债务应由个人承担；争议焦点是公司是否具有独立于股东的法律人格；法律依据是公司法关于注册公司独立地位的规定。上议院的裁判理由是：公司一经合法注册，即成为一个与其成员不同的法律人，其财产与债务归公司自身；股东仅在出资范围内负责。这一裁判的理论意义在于，它把『法人人格』从一种特许特权转变为一种普遍可及的法律技术。\n\n把它与揭开公司面纱制度合看，就能看到法律人格的完整图景：一方面，法律赋予组织独立人格，使资本得以积聚、交易得以稳定；另一方面，法律保留在人格被滥用时否认它的权力。Salomon 案确立的是『原则』，面纱制度确立的是『例外』，二者共同构成了现代法人人格制度的张力结构。对学习者而言，关键落在理解法律为何、以及在何种条件下承认或否认人格；记住『公司是不是人』的标准答案帮助不大。", "summary": "法律人格是实体作为权利义务主体而存在的法律地位，它是法律规则构造的产物，从来算不得自然事实。自然人人格基于出生而普遍平等，法人人格则出于法律拟制，服务于聚资交易等社会目的。独立人格与有限责任是现代公司法的基石，Salomon 案（1897）把这一原则确立为普通法的基本规则；而揭开公司面纱制度则表明，人格在被滥用时可被否认。在法人本质问题上，拟制说与实在说各有支持；在法人是否应享有基本权利的问题上，支持者与反对者各执一词。理解法律人格，核心是把它当作一种可被承认、可被限制、可被穿透的法律技术，并追问其背后的价值判断。", "furtherThinking": "1. 如果把法律人格看作规则构造的产物，那么赋予公司『人格权』或『人权』在逻辑上是否自洽？支持者和反对者各自诉诸什么样的人格标准？\n2. Salomon 案确立了独立人格，面纱制度又允许否认人格。这两种 seemingly 相反的做法，背后是否存在一条一致的公平逻辑？请尝试整合说明。\n3. 罗马法以身份切割人格，现代法以平等武装人格。这一转变背后是哪些社会力量与哲学观念的推动？它是否真正完成，还是仍在延续？"}, "en": "Legal Personality", "level": "core", "tags": "法律人格, 法人, 公司人格, 权利能力, 比较法", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Hart, The Concept of Law, ch.4, ch.5；Siems, Comparative Law, ch.7", "id": "S1M3K4"}, "S1M3K5": {"title": "法律责任", "EN": "Legal Liability", "LEVEL": "core", "TAGS": "法律责任, 制裁, 归责, 过失, 严格责任, 法理学", "TERMS": "法律责任（Legal Liability）::主体因违反义务或造成法定损害而应承受的不利法律后果；义务（Obligation/Duty）::法律要求主体为或不为一定行为的约束；制裁（Sanction）::违反规则时由国家施加的不利后果；归责（Imputation/Attribution）::将损害或行为归于特定主体并使其承担责任的过程；过失责任（Fault Liability）::以过错为承担责任前提的归责原则；严格责任（Strict Liability）::不以过错为前提、只要造成损害即承担的责任；因果关系（Causation）::行为与损害之间的引起与被引起关系；无效（Nullity）::法律行为因欠缺要件而不产生预期效果", "SOURCE": "Wacks, Understanding Jurisprudence, ch.1, ch.10；Hart, The Concept of Law, ch.3, ch.5；Siems, Comparative Law, ch.11（tort law）", "terms": [{"term": "法律责任（Legal Liability）", "def": "主体因违反义务或造成法定损害而应承受的不利法律后果"}, {"term": "义务（Obligation/Duty）", "def": "法律要求主体为或不为一定行为的约束"}, {"term": "制裁（Sanction）", "def": "违反规则时由国家施加的不利后果"}, {"term": "归责（Imputation/Attribution）", "def": "将损害或行为归于特定主体并使其承担责任的过程"}, {"term": "过失责任（Fault Liability）", "def": "以过错为承担责任前提的归责原则"}, {"term": "严格责任（Strict Liability）", "def": "不以过错为前提、只要造成损害即承担的责任"}, {"term": "因果关系（Causation）", "def": "行为与损害之间的引起与被引起关系"}, {"term": "无效（Nullity）", "def": "法律行为因欠缺要件而不产生预期效果"}], "sections": {"coreQuestion": "变质的姜汁啤酒里躺着一只蜗牛，喝下它的人病了一场——谁能为此负责？是制造商、装瓶商，还是那家餐馆？把责任推给『运气不好』显然不行，可要让人赔偿，就得说清楚凭什么。法律上的责任，每天都在被追究：交通肇事、合同违约、产品致害、环境污染。但『责任』这个词底下藏着好几个不同的问题：责任以什么为前提？是不是只要造成了损害就该赔？没有过错要不要负责？法律和道德上的责任是一回事吗？本节要拆开责任的构成要件，看清法律是如何把一项不利后果『归』到某个人头上的。", "definition": "法律责任（Legal Liability），指主体因违反法定义务或造成法律所禁止的损害，而应承受不利法律后果的状态。它可以表现为刑罚、赔偿、罚款、无效等多种形式。理解责任，先要区分三个紧密相关却不同的词：义务、责任与制裁。义务（Obligation/Duty）是『应当做』的约束；责任（Liability）是这个约束被违反后的『应受追究』状态；制裁（Sanction）则是追究的具体内容——国家施加的惩罚或强制赔偿。\n\n哈特（H. L. A. Hart）对这三个概念做了经典的澄清。他指出，刑法规则以制裁为后盾，这确实与『以威胁为后盾的命令』有几分相似：刑法把某些行为设定为应予避免的『义务』，违反即构成『违法』或『犯罪』，伴随的处罚或『制裁』用来提供不去做这些行为的动机。侵权责任法则以赔偿受害人的损害为主要目的，其规则同样设定义务，违反构成『义务之违反』（breach of duty），赔偿或其他救济被称为『制裁』。\n\n但哈特警告，不能把所有法律都理解成『命令＋制裁』。有一类规则的功能在授予权力（power-conferring rules），让人通过遗嘱、合同、婚姻来创设权利义务，义务的设定并不在其中。这类规则被违反时，后果是『无效』（nullity）而非惩罚——遗嘱少了两个见证人，行为无效（nullity），但立遗嘱人并未『犯罪』或『违反义务』。哈特专门反驳了把无效也当作一种制裁的说法，因为无效是规则本身的组成部分，而非附加的威胁。", "history": "责任观念的演变，与社会对『归责』的理解同步。早期法律实行结果责任：只要造成了损害，就要负责，不问是否有过错。古代法典中常见的『以牙还牙』，体现的正是这种朴素的同态复仇逻辑。随着理性法的发展，责任逐渐与过错挂钩——只有在行为人能够选择却选择了错误时，归责才是正当的。这一转变把责任建立在自由意志之上：一个人只应为自己能够控制的行为负责。\n\n近代刑事实证学派与民法学者进一步细化了责任理论。刑法中发展出故意、过失、因果关系的体系；民法中，过错责任（Fault Liability）长期占据中心。但工业化带来的事故风险，使严格责任（Strict Liability）兴起：在高度危险活动中，即使没有过错，行为人也须对损害负责。Siems 在比较侵权法时指出，德国、英国、法国、美国等国在损害赔偿的范围与责任认定上各有路径——例如德国法院对精神损害赔偿较为保守，并有意识地限制赔偿数额，而英美法系的侵权法则更依赖判例发展。", "principle": "归责是一个分层判断的过程，可以拆成几步。\n\n第一步是『义务是否存在』。责任以义务为前提：没有义务，就没有违反义务，也就没有责任。哈特指出，侵权法与刑法都通过规则设定『义务』，这是归责的起点。但义务并不总是对应某个人的权利——刑法中许多义务是『面向公众的』，Wacks 举警察举报犯罪的义务为例，它并不赋予任何特定个人以主张权。\n\n第二步是『违反与损害』。有了义务，还需证明义务被违反、且造成了法律所禁止的损害。在侵权法中，这通常表现为注意义务（duty of care）的违反与损害结果。这一步涉及因果关系（Causation）的判断：损害必须是行为所引起的，而非纯粹的巧合。Siems 在比较各国侵权法时指出，因果关系的认定标准，是各国差异的重要来源。\n\n第三步是『过错与归责标准』。这是责任理论的分水岭。过失责任以过错为前提：只有故意或过失地违反义务，才承担责任。严格责任则不以过错为前提：在高度危险、产品责任等领域，只要造成损害就要负责，其正当性在于风险控制与损失分散——谁从危险活动中获益，谁就应承担风险。\n\n第四步是『责任的限制与免除』。即使满足上述条件，责任也可能因抗辩事由而减免：正当防卫、紧急避险、不可抗力、受害人同意等。哈特在讨论自由与责任时指出，被威胁而被迫行动的人，其意志被压倒，通常不被归责——这正是责任以自由选择为前提的体现。", "viewpoints": "哈特对责任理论的贡献，集中在『义务、责任、制裁』的区分与对命令理论的批判上。他反对凯尔森（Hans Kelsen）把法律归结为『主规范规定制裁』的观点——凯尔森认为不存在禁止谋杀的法，只有指导官员对杀人者适用制裁的法。哈特反驳说，这种还原扭曲了法律的社会功能：刑法规则的首要任务是指导普通公民的行为，制裁只是应对规则失败的『辅助手段』。他把法律理解为『初级规则与次级规则的结合』，责任规则正是初级规则的一部分。\n\n在责任与自由的关系上，哈特坚持：义务预设了主体能够理解并遵守规则；威胁能让人『不得不』做（being obliged），却不能产生『有义务』做（having an obligation）的规范体验。Leslie Green 在哈特导论中进一步指出：被威胁迫使的人通常不被追究责任，因为他们的意志被压倒（will is overborne）。这一命题把责任牢牢锚定在自由选择之上。\n\nWacks 则通过权利分析补充了另一面：责任与权利的关系并非一一对应。刑法中的义务可能不对应任何人的权利，这提示我们，责任并非总是『对某人的责任』，它也可能是『对法秩序的责任』。", "comparison": "把过失责任与严格责任并排看，能看清两种归责逻辑。\n\n过失责任以道德上的可非难性为基础：行为人本可选择不造成损害，却选择了不当行为，因此应受谴责并赔偿。它强调的是『惩罚过错』与『矫正不正义』。严格责任则舍弃了过错要件，转而关注风险的分配：在危险活动中，即便行为人已尽最大注意，损害仍可能发生，此时让控制风险并从活动中获益的人承担损失，更符合公平与效率。Siems 指出，严格责任在各国的产品责任、环境责任中都有体现，但适用范围与抗辩事由差别很大。\n\n在大陆法系与英美法系之间，责任体系也有明显差异。大陆法系倾向以法典化的一般条款构造归责（如德国民法典的侵权责任条款），逻辑抽象、体系严整；英美法系则通过一个个具体判例累积出注意义务的范围，经验、灵活。Wacks 提醒，不能把两大法系的区别绝对化——它们在现代都面临同样的归责难题，且在很多结果上趋于接近。", "debates": "责任法中最经典的争论，是『法律与道德在责任上是否应当分离』。这其实是哈特—富勒（Hart-Fuller）论战在责任领域的具体化。\n\n一种观点主张，法律责任应当反映道德责任：只有道德上应受谴责的人，才应被法律追究。这接近自然法的立场，强调法律与道德的必然联系。另一种观点（法律实证主义）主张，法律责任与道德责任可以分离：一项规则是否有效、一个人是否应负责，取决于它是否被合法权威按正当程序制定和适用，而不取决于它是否道德。哈特坚持后一种立场，但他同时承认，法律必须满足某些『最低限度的自然法』条件才能维持自身。\n\n争论的另一条线索是严格责任的正当性。支持者以风险控制与损失分散为依据；反对者则担心，不以过错为前提的责任会背离责任制度的道德基础，把人变成纯粹的『风险承担工具』。Wacks 在讨论道德与法律时梳理了这些立场，提醒学习者：责任制度的设计，终究是在自由、公平与效率之间做权衡。", "case": "Donoghue v Stevenson（1932）是侵权法中确立注意义务的经典判例，也是理解法律责任的绝佳素材。案情是：原告在餐馆喝了一瓶姜汁啤酒，倒出一半时发现瓶底有一只腐烂的蜗牛，她因此患病，遂向制造商索赔。当时的法律难题在于：原告与制造商之间并无合同关系（啤酒是朋友买的），按传统契约法，制造商似无义务。\n\n上议院最终判决制造商负有赔偿义务。奥金·阿特金勋爵（Lord Atkin）提出了著名的『邻人原则』（neighbour principle）：你必须采取合理注意，避免那些可以合理预见会伤害『邻人』的行为——邻人指的是那些与你关系如此紧密，以至于你应当预见到自己的行为会影响他们的人。Siems 在比较侵权法时引用了此案，哈特在《法律的概念》中则把它作为通过『建构性解释』识别原则的范例——阿特金勋爵把此前分散的各个注意义务规则背后的共同原则揭示出来。", "caseAnalysis": "就 Donoghue v Stevenson 而言，事实是饮料中混入蜗牛致人患病；争议焦点是制造商对非合同当事人是否负有注意义务；法律依据是侵权法中的注意义务与邻人原则；裁判理由是：制造商与最终消费者之间存在足够紧密的关系，使其应预见产品缺陷可能造成伤害，因而负有合理注意的义务。这个案例的理论意义极为深远：它把责任从合同关系的狭窄框架中解放出来，确立了产品责任与一般注意义务的基础。\n\n从责任构成的角度看，此案完整体现了归责的步骤：存在注意义务（邻人原则）、义务被违反（未确保饮料洁净）、造成损害（患病）、因果关系成立（饮用变质饮料致病）。它同时说明，责任的范围是通过原则的发展而扩张的——哈特借此说明，法律原则可以经由司法推理被识别并成为裁判依据。把这一案例与严格责任、过失责任的区分结合起来看，就能理解现代责任法如何在『过错』与『风险』之间不断调整边界。", "summary": "法律责任是主体因违反义务或造成法定损害而承受的不利后果，其核心是归责——把一项不利后果正当地归于特定主体。哈特厘清了义务、责任、制裁三者的关系，批判了把一切法律还原为『命令＋制裁』和把无效当作制裁的观点，强调制裁只是应对规则失败的辅助手段。责任以自由选择为前提，被胁迫者意志被压倒时通常不被归责。归责通常经过义务存在、违反与损害、过错标准、限制免除四个步骤。过失责任以可非难性为基础，严格责任以风险控制与损失分散为依据；两大法系各有路径。Donoghue v Stevenson 通过邻人原则确立了注意义务，展示了责任范围如何通过原则发展而扩张。理解责任，关键在于把握自由、公平与效率之间的持续权衡。", "furtherThinking": "1. 严格责任不以过错为前提，这是否背离了『责任以自由选择为前提』的原则？请为严格责任寻找一种不与自由冲突的正当性论证。\n2. 哈特说制裁只是『应对规则失败的辅助手段』。如果一种法律规则完全没有制裁（如某些倡导性规范），它还能被称为法律吗？这会不会动摇『法律以制裁为后盾』的传统定义？\n3. Donoghue v Stevenson 通过『邻人原则』扩张了责任范围。法官在这类案件中是在『发现』既有法律，还是在『创设』新法律？请结合哈特的原则理论说明。"}, "en": "Legal Liability", "level": "core", "tags": "法律责任, 制裁, 归责, 过失, 严格责任, 法理学", "source": "Wacks, Understanding Jurisprudence, ch.1, ch.10；Hart, The Concept of Law, ch.3, ch.5；Siems, Comparative Law, ch.11（tort law）", "id": "S1M3K5"}, "S1M3K6": {"title": "法律效力", "EN": "Legal Validity", "LEVEL": "core", "TAGS": "法律效力, 承认规则, 有效性, 法律实证主义, 哈特", "TERMS": "法律效力（Legal Validity）::一项规则或行为在法律体系内被承认为有效、具有约束力的属性；承认规则（Rule of Recognition）::哈特理论中用以识别哪些规则属于有效法律的根本次级规则；有效性标准（Criteria of Validity）::判断一项规则是否属于法律的依据；基础规范（Grundnorm/Basic Norm）::凯尔森理论中法律体系效力的终极预设；分离命题（Separation Thesis）::法律是否有效与是否道德可以分开判断的主张；无效（Invalidity/Nullity）::法律行为或规则不发生预期法律效力的状态；法律体系（Legal System）::由初级规则与次级规则结合而成的规范体系", "SOURCE": "Hart, The Concept of Law, ch.5, ch.6, ch.9；Wacks, Understanding Jurisprudence, ch.3, ch.4；Leslie Green 导论, 'Law as a Social Construction'", "terms": [{"term": "法律效力（Legal Validity）", "def": "一项规则或行为在法律体系内被承认为有效、具有约束力的属性"}, {"term": "承认规则（Rule of Recognition）", "def": "哈特理论中用以识别哪些规则属于有效法律的根本次级规则"}, {"term": "有效性标准（Criteria of Validity）", "def": "判断一项规则是否属于法律的依据"}, {"term": "基础规范（Grundnorm/Basic Norm）", "def": "凯尔森理论中法律体系效力的终极预设"}, {"term": "分离命题（Separation Thesis）", "def": "法律是否有效与是否道德可以分开判断的主张"}, {"term": "无效（Invalidity/Nullity）", "def": "法律行为或规则不发生预期法律效力的状态"}, {"term": "法律体系（Legal System）", "def": "由初级规则与次级规则结合而成的规范体系"}], "sections": {"coreQuestion": "翻开任何一部法典，你都会看到『本法自某日起施行』之类的话。可这句话凭什么有效？一部法律之所以是法律，究竟是因为它内容正义，还是因为它出自有权机关、按正确程序制定？如果一部法律极其邪恶——比如纳粹德国的种族法案——它还算不算『法律』？如果算，我们在什么意义上说它『有效』？这些问题看似抽象，却关乎我们如何识别法律、如何批判恶法。法律效力是法理学的核心概念，它要回答的是：在一个法律体系内部，是什么赋予一条规则以『法律』的身份和约束力？本节将沿着哈特的承认规则、凯尔森的基础规范，一直到哈特—富勒论战，梳理效力的来源、标准和限度。", "definition": "法律效力（Legal Validity），指一项规则、行为或决定在法律体系内被承认为有效、因而具有约束力的属性。它至少有两层含义：其一，在形式层面，一项规则是否『属于』该法律体系——即它是否通过了体系的识别标准；其二，在内容层面，规则要求的行为是否对主体产生约束力。英文中 validity 与 effectiveness（实效）有别：一条规则可能在法律上有效却在社会中少有人遵守，也可能被广泛遵守却因程序瑕疵而无效。\n\n在法律实证主义（Legal Positivism）内部，效力主要由规则的『来源』决定。哈特（H. L. A. Hart）主张，一条规则是否有效，取决于它是否满足法律体系承认规则所设定的有效性标准（criteria of validity），而非它是否道德。凯尔森（Hans Kelsen）则用基础规范（Grundnorm）来解释效力链条：个别规范的效力来自上级规范，最终追溯到一个被预设的、不再需要更高规范授权的终极规范。\n\n自然法理论（Natural Law Theory）则主张，效力与道德存在必然联系：严重违背正义的规则（『恶法』）在严格意义上不具有法律的效力。这便是『恶法非法』（lex iniusta non est lex）的命题。效力问题因此成为法律与道德关系的试金石。", "history": "对效力来源的追问，与主权国家的兴起同步。近代主权理论把法律的效力追溯到主权者的意志：奥斯丁（John Austin）认为法律是主权者的命令，其效力来自主权者的权威与制裁的后盾。这种『命令理论』把效力理解为一种自上而下的授权关系。\n\n进入二十世纪，两次世界大战与极权主义的经验彻底动摇了这一框架。如果法律只是主权者的命令，那么纳粹德国那些极端邪恶的种族法案是否也是『法律』？这一问题在战后引发了哈特与富勒（Lon Fuller）的著名论战。富勒主张，法律的内在道德（程序正义的最低要求）与法律的概念本身密不可分，纳粹法律因丧失这些要素而不足以称为法律；哈特则回应，承认纳粹法律是『法律』不妨碍我们谴责它，把它排除出法律概念反而会遮蔽对其性质的认识。Wacks 将这场论战列为理解法理学的关键入口。\n\n同一时期，凯尔森的纯粹法学（Pure Theory of Law）试图建立一个排除道德与社会学因素的效力理论，以基础规范作为法律体系统一性的基础。哈特则在批判奥斯丁与凯尔森的基础上，用『初级规则与次级规则的结合』和承认规则理论，重构了对效力的理解。", "principle": "理解法律效力，可从四个层次推进。\n\n第一层是『效力链条』。在一个现代法律体系中，规则层层授权：议会依宪法制定法律，法院依法裁判，行政机关依法作出决定，孤立存在的规则并不多见。每一层规范的效力都来自上一层规范的授权。凯尔森把这一追问推到终点，提出基础规范——一个被法律共同体接受为终极有效性的预设。法律体系的所有规范效力，最终都建立在这个基础之上。\n\n第二层是哈特的『承认规则』。哈特认为，在复杂社会中，仅靠习惯不足以识别法律，需要次级规则来克服初级规则的确定性不足、静态性与无效力争议等缺陷。其中承认规则用以识别哪些规则属于有效法律。哈特设想，英国的承认规则大致是『女王议会制定的即为法律』（Whatever the Queen in Parliament enacts is law）；在美国，法院则把宪法当作具有最高效力的法律渊源。Green 指出，承认规则是一种惯例性的社会规则，其存在取决于法院、官员和私人共同接受的实践中。\n\n第三层是『效力与道德的分离』。哈特坚持，判断一条规则是否属于法律，用的是承认规则的社会标准，而非道德标准。这就是分离命题（Separation Thesis）。它的意思是：『是不是法律』与『是不是道德上正当』是两个应当分开判断的问题；『法律不需要道德』属于误读。哈特同时承认，法律必须满足某些『最低限度的自然法』条件（如保护生命、财产）才能维持自身。\n\n第四层是『效力与实效』。一条规则可能在法律上有效却实效寥寥，也可能实效广泛却因程序瑕疵而无效。哈特强调，承认规则的存在是一种社会实践的事实，它既不同于道德判断，也不等同于规则被实际遵守的程度。", "viewpoints": "哈特与凯尔森代表了法律实证主义内部两种效力理论。\n\n凯尔森的纯粹法学追求彻底的价值中立：法律效力来自规范体系内部的授权关系，终极根据是基础规范——一个被预设的、不再追问其有效性的规范。法律体系的统一性，就在于所有规范都能追溯至这一基础。凯尔森甚至把法律归结为『规定制裁的主规范』，认为不存在禁止谋杀的法，只有命令官员对杀人者适用制裁的法。\n\n哈特则批判了这种还原。他认为，法律体系的基础落在一项被实际接受的社会规则——承认规则上，逻辑预设只是表面。Green 引述哈特：加州限速 55 英里的命题之所以为真，对奥斯丁而言只是因为制定它的立法者恰好掌权，对哈特而言则是因为加州人民接受并继续接受州与联邦宪法中的权力架构。效力因此根植于一种社会实践，而非纯粹的逻辑预设。\n\n德沃金（Ronald Dworkin）则对哈特提出挑战：法律不仅包含规则，还包含原则；原则的效力来自其道德分量，承认规则的社会来源标准在这里力有未逮。哈特在《法律的概念》第三版的后记（Postscript）中回应，原则只要被官方承认（如通过司法采纳），就可纳入法律，承认规则可以包含这种标准。这一争论把效力的来源问题进一步复杂化。", "comparison": "把法律实证主义与自然法理论并排看，分歧十分清楚。\n\n在『效力是否取决于道德』上，实证主义说可以分离（来源决定效力），自然法说必然联系（正义是效力的要件）。在『如何识别有效法律』上，实证主义诉诸社会事实（承认规则、制定程序），自然法诉诸道德理性。在『恶法的地位』上，实证主义倾向于承认其法律效力同时予以道德谴责，自然法则主张『恶法非法』。\n\n需要警惕一种粗糙的漫画化：实证主义并不主张『法律不需要道德』或『恶法就是好法』。哈特的立场微妙得多——他承认法律与道德在事实层面常相互渗透，也承认法律须满足最低限度的自然法条件；他坚持的仅是概念上的区分：是不是法律，与是不是道德上正当，应分开判断。Wacks 提醒，把两者分开恰恰是为了更清醒地批判恶法——承认它是法律，然后说『正因为它有效力，我们更有道德义务抵抗它』。", "debates": "哈特—富勒论战是效力领域的经典争论，其背景是纳粹德国的恶法。\n\n富勒认为，法律有其『内在道德』——一般性、公开性、不溯及既往、明确性、不矛盾、可行性、稳定性、官方行为与法律一致等程序性要求。这些要求与法律的概念本身密不可分：一项规则若彻底背离这些要求，就不再是『法律』，而只是赤裸裸的暴力。纳粹法律之所以仍被称作法律，只因它还保留了某些形式要素；但那些极其恶劣的条文，已接近于非法。\n\n哈特反驳说，把极端邪恶的规则排除出法律概念，是一个危险的混淆。承认纳粹法律是法律，同时谴责它，比宣布『它不是法律』更诚实——后者会遮蔽我们对其性质的认识，也会让人误以为只要宣布某规则『不是法律』就可以不予抵抗。哈特坚持，效力与正当性的区分是概念上的，这个区分正是为了让道德批判更精准。Wacks 指出，这场争论没有胜负，但它确立了一个此后所有法理学都必须面对的坐标：任何法律理论都要交代自己如何处理效力（validity）与正当性（legitimacy）的关系。", "case": "一个能展示效力来源差异的现实对比，是英美两国宪法对法律效力的不同安排。\n\n在英国，按哈特的设想，承认规则大致是『女王议会制定的即为法律』——议会制定的法律具有最高效力，法院无权审查其有效性。这体现了议会主权（parliamentary sovereignty）的传统。在美国，宪法具有最高效力，联邦最高法院有权审查国会立法是否违宪；违反宪法的法律可被宣告无效（judicial review）。Green 引述德沃金对哈特的转述：加州限速 55 英里之所以为真，美国版本是因为人民接受了宪法所设定的权力架构。\n\n这两个例子说明，『什么样的规则是有效法律』在一个法律体系内部是由其承认规则决定的，而各体系的承认规则并不相同。理解法律效力，必须放进具体的制度语境——这也是为什么不能把美国、英国、德国的法律制度混为一谈。Siems 的比较法研究反复强调，概念的形式相似并不等于制度功能的等同。", "caseAnalysis": "就英美对比而言，事实是两国对『最高效力来源』的安排不同：英国以议会制定法为最高，美国以宪法为最高并辅以司法审查；争议焦点是效力来源是否可以脱离具体制度被一般化；法律依据是各自的宪法惯例与判例。从哈特的框架看，两国的承认规则内容不同，但其功能相同——都提供了识别有效法律的社会标准。\n\n这个案例的理论意义在于，它把抽象的『效力』概念落到了制度层面：效力是一个法律体系通过社会规则赋予的身份，规则自身带不来它。把美国模式当成唯一模式，或以为英国『没有宪法就谈不上效力标准』，都是错误的。Wacks 与 Siems 从不同角度提醒我们：法律的概念框架具有一般性，但其具体实现形态镶嵌在各自的法律文化之中。", "summary": "法律效力指规则或行为在法律体系内被承认为有效的属性，核心问题是『是什么赋予规则以法律的身份与约束力』。法律实证主义以来源决定效力：凯尔森诉诸基础规范，哈特诉诸作为社会实践的承认规则；分离命题主张效力与道德可以分开判断。自然法则主张效力与道德必然联系，『恶法非法』。哈特—富勒论战表明，承认恶法为法不妨碍谴责它，把二者分开反而使批判更精准。英美两国效力来源的不同安排说明，效力是体系通过社会规则赋予的身份，必须放进具体制度语境理解。理解法律效力，关键是把效力与实效、效力与正当性分别厘清。", "furtherThinking": "1. 如果一条规则被官方普遍承认并遵守，但它的内容极其不正义，哈特会怎么说它的效力？自然法学者又会怎么说？你更认同哪一种，为什么？\n2. 德沃金主张法律包含原则，而原则的效力来自道德分量而非社会来源。这对哈特的承认规则理论构成了怎样的挑战？哈特的后记回应是否足够？\n3. 在一个联邦制国家或国际法体系中，可能存在多个相互竞争的效力标准。哈特的承认规则理论能否处理这种情形？请说明理由。"}, "en": "Legal Validity", "level": "core", "tags": "法律效力, 承认规则, 有效性, 法律实证主义, 哈特", "source": "Hart, The Concept of Law, ch.5, ch.6, ch.9；Wacks, Understanding Jurisprudence, ch.3, ch.4；Leslie Green 导论, 'Law as a Social Construction'", "id": "S1M3K6"}, "S1M3K7": {"title": "法律事实", "EN": "Legal Facts", "LEVEL": "fundamental", "TAGS": "法律事实, 事实认定, 因果关系, 证据, 法律推理", "TERMS": "法律事实（Legal Facts）::被法律规则赋予法律意义、能够引起法律后果的事实；事件（Event）::不以当事人意志为转移而能引起法律后果的事实；行为（Act）::以当事人意志为转移、能引起法律后果的事实；事实认定（Fact-finding）::确定案件事实是否成立的司法过程；举证责任（Burden of Proof）::由哪一方承担证明事实存在的责任；开放结构（Open Texture）::法律规则在边缘地带存在不确定性的特性；司法认知（Judicial Notice）::法院对某些显著事实无须证明即可认定", "SOURCE": "Hart, The Concept of Law, ch.7；Wacks, Understanding Jurisprudence, ch.1, ch.7；Siems, Comparative Law, ch.11", "terms": [{"term": "法律事实（Legal Facts）", "def": "被法律规则赋予法律意义、能够引起法律后果的事实"}, {"term": "事件（Event）", "def": "不以当事人意志为转移而能引起法律后果的事实"}, {"term": "行为（Act）", "def": "以当事人意志为转移、能引起法律后果的事实"}, {"term": "事实认定（Fact-finding）", "def": "确定案件事实是否成立的司法过程"}, {"term": "举证责任（Burden of Proof）", "def": "由哪一方承担证明事实存在的责任"}, {"term": "开放结构（Open Texture）", "def": "法律规则在边缘地带存在不确定性的特性"}, {"term": "司法认知（Judicial Notice）", "def": "法院对某些显著事实无须证明即可认定"}], "sections": {"coreQuestion": "法庭上最激烈争夺的，往往是『到底发生了什么』；法律条文怎么解释反倒退居其次。被告当天是否在场？那份合同是否真的签过？产品缺陷是否致人患病？这些看起来是『事实问题』，可它们一旦进入法律程序，就成了被法律规则筛选、评价和构造过的东西，纯粹的事实色彩随之褪去。并非所有发生过的『事实』都是法律关心的事实——今天下了雨，和一场车祸是否因雨天路滑而起，在法律上意义完全不同。本节要弄清：什么样的『事实』才能成为法律事实？法律事实与自然事实的区别在哪里？为什么事实认定会成为法律推理中最困难、也最关键的环节？", "definition": "法律事实（Legal Facts），指被法律规则赋予法律意义、能够引起法律关系产生、变更或消灭的事实。一个事实之所以是『法律事实』，不在于它在自然界中是否发生过，而在于法律规则是否把它作为某种法律后果的条件。例如，人的出生与死亡，作为自然事件是生物学意义上的事实，但法律把它们构造为权利能力取得与终止的法律事实，引发继承、婚姻等一系列法律后果。\n\n大陆法系通常把法律事实分为两大类：事件（Event）与行为（Act）。事件是不以当事人意志为转移的事实，如出生、死亡、自然灾害、时间经过；行为是以当事人意志为转移的事实，如订立合同、实施侵权、提起诉讼。行为又可按是否符合法律规定分为合法行为与违法行为。这一分类的意义在于：不同类别的事实，其法律后果的构成要件不同。\n\n法律事实要经过『事实认定』（Fact-finding）才能进入裁判。在诉讼中，事实由证据来证明，由法官或陪审团认定。这条道路上布满了难题：证据可能不足、证词可能矛盾、事实与法律问题可能纠缠不清。哈特（H. L. A. Hart）指出，法律规则具有开放结构（open texture），在边缘地带存在不确定性——这条特性同样适用于事实认定，因为『同一事实是否符合规则的描述』常常是可争辩的。", "history": "对法律事实的系统化处理，与近代证据法和诉讼制度的发展同步。中世纪的证据制度（如神判、宣誓）把事实认定交给超自然或形式化的程序；近代理性主义兴起后，事实认定逐渐转向以证据和逻辑为基础的判断。大陆法系发展出职权主义的调查模式，法官主动查明事实；英美法系则发展出当事人主义的对抗模式，由双方举证、陪审团或法官裁决事实。\n\n十九世纪末至二十世纪，法律现实主义（Legal Realism）对『事实』提出挑战。美国现实主义者霍姆斯（Oliver Wendell Holmes Jr.）有句名言：『法律的生命不在逻辑，而在经验。』现实主义者主张，真正决定案件结果的，往往是法官对事实与社会后果的判断，而非规则的机械适用。这一思路把事实认定推到法律理论的中心：如果法律规则本身是不确定的，那么案件的结果就取决于法官如何认定事实。\n\nWacks 在讨论法律与事实时指出，法律规则兼具开放结构与确定性核心：在清晰的核心地带，规则适用相对确定；在边缘地带，则留下较大的裁量空间。Siems 在比较各国侵权法时指出，举证责任分配、因果关系认定标准等事实认定机制，是各国制度差异的重要来源。", "principle": "理解法律事实，可分三层。\n\n第一层是『事实的法律构造』。法律事实是规则筛选的结果，对自然事实的复制从来只是表象。同一场车祸，对不同法律问题而言是不同事实：对侵权责任，关键是过错与因果；对保险理赔，关键是事故是否在承保范围；对交通违章，关键是是否违反信号。法律关心的是事实中具有法律意义的那部分，其余的都被忽略。\n\n第二层是『事实与规范的纠缠』。法律事实的认定往往离不开法律规则。要说『某行为构成违约』，既要确定事实（是否交货、是否付款），又要适用规则（何为违约）。哈特指出，即使在事实层面，判断也常常需要借助法律标准——『合理注意』『可预见性』这类标准本身就带有规范性，使事实认定与法律评价难以截然分开。\n\n第三层是『证明与责任分配』。事实认定的核心机制是举证责任（Burden of Proof）：主张某一事实存在的一方，通常承担证明责任；证明达不到标准，主张就不能成立。这一分配往往直接决定案件结果。在侵权法中，因果关系与过错的举证责任如何分配，是各国制度的重大差异——Siems 指出，这正是比较法研究的重要领域。", "viewpoints": "哈特对法律事实的讨论，围绕规则的开放结构展开。他指出，所有规则都有一个确定的核心，也存在一个边缘的『开放结构』：在核心地带，规则的适用是清楚的；到了边缘，规则是否适用就变成可争辩的问题。这种不确定性意味着，法官在面对边缘案件时，需要在某种意义上『创设』法律，而非机械适用。事实认定同样如此——一个事实是否符合规则的描述，在边缘地带常常没有唯一答案。\n\n法律现实主义（Legal Realism）则走得更远。Wacks 介绍，现实主义者把注意力从『书本上的法』转向『行动中的法』，强调法官对事实与社会后果的判断才是决定性的。霍姆斯（Oliver Wendell Holmes Jr.）的『法律的生命不在逻辑，而在经验』，正是对这一立场的概括。这一视角提醒我们，事实认定不是一个纯粹的技术过程，它不可避免地包含判断与选择。\n\nWacks 同时提醒，不能把法律的确定性全盘否定。法律规则在大多数情形下是明确的，事实认定也在大多数情形下能达成共识；把边缘地带的不确定性夸大为『法律完全不确定』，是一种过头的主张。", "comparison": "把大陆法系与英美法系的事实认定模式并排看，差异很清楚。\n\n大陆法系倾向职权主义：法官主导事实调查，主动询问当事人与证人，追求实质真实；英美法系倾向当事人主义：事实由双方提出证据、交叉询问，法官或陪审团居中裁判，强调程序正当。两种模式各有优劣：职权主义更利于查明真相，但可能削弱当事人的对抗；当事人主义更能保障程序公正，却可能让财富与资源影响事实认定。Siems 指出，随着两大法系的交流，这些差异在现代有所缩小，但制度基因仍在。\n\n在举证责任上，各国也有不同安排。一般原则是『谁主张、谁举证』，但在产品责任、医疗事故等领域，现代法律常采用举证责任倒置或推定，以保护弱势一方。这些制度安排说明，事实认定从来不只是认识论问题，它还承载着公平与政策考量。", "debates": "法律事实领域最经典的争论，是法律现实主义与法律形式主义（Legal Formalism）之争。\n\n形式主义主张，法律是一个相对封闭的逻辑体系，法官通过逻辑推演即可从既定规则中得出判决；事实认定是一个客观的过程，证据指向唯一的事实真相。现实主义则反驳：法律规则存在开放结构与不确定性，事实认定充满判断与选择，法官的个人经验、社会背景乃至政策偏好都会影响结论。霍姆斯的名言『法律的生命不在逻辑，而在经验』成为现实主义的旗帜。\n\nWacks 在呈现这场争论时提醒，双方都不应被漫画化。形式主义并非主张法律可以脱离社会，现实主义也并非主张法官可以任意裁判。更合理的理解是：法律在大多数案件中提供了相对确定的指引，但在边缘地带确实需要判断。Siems 的比较法研究进一步表明，不同制度通过不同的程序设计（如陪审团、职权调查）来应对这种不确定性，各有其合理性。", "case": "Donoghue v Stevenson（1932）不仅是一个责任法案例，也是理解法律事实认定的好素材。原告声称在姜汁啤酒中发现了蜗牛并因此患病——这些都需要通过证据来证明。案件中的关键事实包括：饮料中含有蜗牛、蜗牛在装瓶时即在其中（而非事后进入）、原告确实因此患病。这些事实一旦被认定，就触发了制造商注意义务的法律后果。\n\n此案的事实认定还引出一个有趣的问题：啤酒瓶是不透明的，消费者无法事先看到瓶内情况，这一『事实』在法律上被构造为制造商与消费者之间关系紧密、消费者无从自我保护的理由，从而支持了注意义务的存在。哈特在《法律的概念》中把此案作为『建构性解释』的范例——法官不仅认定事实，还揭示了事实背后的法律原则。这个案例说明，事实认定与法律评价在司法实践中是相互交织的。", "caseAnalysis": "就 Donoghue v Stevenson 的事实层面而言，争议焦点是：饮料中的蜗牛是否确实存在、是否由制造商的责任造成、与原告疾病是否有因果关系。法律依据是侵权法中关于注意义务与因果关系的要求。法院在认定这些事实的基础上，结合邻人原则，判决制造商承担责任。这个案例的理论意义在于，它展示了『事实—证据—法律后果』的完整链条：自然事实（瓶中有蜗牛）经过证据证明成为法律事实，再经由法律规则（注意义务、因果关系）的评价，最终产生赔偿的法律后果。\n\n它同时印证了哈特关于开放结构的观点：『瓶中蜗牛导致疾病』这一事实在核心意义上清楚，但要把它纳入『制造商是否违反合理注意』的法律评价，就需要判断——而判断离不开标准与原则。把这一案例与法律现实主义的洞见结合起来看，就能理解：事实认定既是认识活动，也是法律活动，它处在法律推理的枢纽位置。", "summary": "法律事实是被法律规则赋予意义、能引起法律后果的事实；它属于规则筛选与构造的产物，与自然事实并不等同。大陆法系通常把法律事实分为事件与行为，二者构成要件不同。事实认定通过举证责任、证据审查等机制完成，其分配往往决定案件结果。哈特指出法律规则的开放结构使边缘地带的事实认定充满可争辩性，法律现实主义则强调事实认定中的判断与选择。大陆法系职权主义与英美法系当事人主义代表两种不同的应对路径。Donoghue v Stevenson 展示了自然事实如何经证据与法律评价转化为法律后果。理解法律事实，关键要看到事实认定是认识活动与法律活动的交织。", "furtherThinking": "1. 哈特说规则有『开放结构』，现实主义说法官的判断决定案件。如果事实认定总免不了判断，那么『以事实为根据』的司法原则还成立吗？它应当被如何理解？\n2. 举证责任的分配直接影响案件结果。既然如此，举证责任制度设计的正当性基础是什么——是发现真相，还是实现公平？请结合产品责任中的举证倒置说明。\n3. 在算法辅助断案的时代，事实认定越来越多地依赖数据与模型。这会让法律事实认定更客观，还是会把新的偏见嵌入其中？"}, "en": "Legal Facts", "level": "fundamental", "tags": "法律事实, 事实认定, 因果关系, 证据, 法律推理", "source": "Hart, The Concept of Law, ch.7；Wacks, Understanding Jurisprudence, ch.1, ch.7；Siems, Comparative Law, ch.11", "id": "S1M3K7"}, "S1M3K8": {"title": "法律关系", "EN": "Legal Relations", "LEVEL": "core", "TAGS": "法律关系, 霍菲尔德, 相关性, 权利义务, 法理学", "TERMS": "法律关系（Legal Relation）::法律规则调整主体之间形成的权利义务联系；法律地位（Legal Position）::主体在法律关系中所处的权利义务状态；相关性（Correlativity）::权利与义务等法律概念之间一一对应的结构关系；对物权/对人权（Right in Rem / Right in Personam）::可对抗所有人或仅可对抗特定人的权利；法律关系三要素（Three Elements）::法律关系的主体、客体与内容；初级规则（Primary Rules）::直接规定主体行为义务的规则；次级规则（Secondary Rules）::规定如何识别、改变与裁判初级规则的规则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.10.1；Hart, The Concept of Law, ch.5, ch.6；Siems, Comparative Law, Introduction & ch.7", "terms": [{"term": "法律关系（Legal Relation）", "def": "法律规则调整主体之间形成的权利义务联系"}, {"term": "法律地位（Legal Position）", "def": "主体在法律关系中所处的权利义务状态"}, {"term": "相关性（Correlativity）", "def": "权利与义务等法律概念之间一一对应的结构关系"}, {"term": "对物权/对人权（Right in Rem / Right in Personam）", "def": "可对抗所有人或仅可对抗特定人的权利"}, {"term": "法律关系三要素（Three Elements）", "def": "法律关系的主体、客体与内容"}, {"term": "初级规则（Primary Rules）", "def": "直接规定主体行为义务的规则"}, {"term": "次级规则（Secondary Rules）", "def": "规定如何识别、改变与裁判初级规则的规则"}], "sections": {"coreQuestion": "买了杯咖啡，你和店家之间就产生了一组关系：你有权要求给你咖啡，店家有权要求你付钱；你付了钱、店家给了咖啡，关系便告终结。这一来一往，就是法律关系的缩影。可法律关系远比这复杂：房东与租客、股东与公司、债权人与债务人、国家与公民——每一对关系都由若干权利、义务、权力、责任交织而成。法律关系的本质是什么？它和道德关系、社会关系相比，特殊在哪里？霍菲尔德（Wesley Hohfeld）那张著名的『法律关系表』究竟想说明什么？本节将把法律关系拆成其基本单元，看清法律是如何把人与人之间的联系编织成一张规范之网的。", "definition": "法律关系（Legal Relation），指法律规则调整主体之间行为时所形成的权利义务联系。它是法律调整社会关系的结果：当社会关系被法律规则赋予法律意义，主体之间便形成法律上的权利义务联系。法律关系由三个要素构成：主体（参与法律关系的当事人）、客体（权利义务所指向的对象，如物、行为、智力成果）与内容（主体享有的权利和承担的义务）。\n\n法律关系不同于一般的社会关系或道德关系。朋友之间的情谊、路人之间的礼貌，虽也是『关系』，却不由法律调整，也不产生法律上的强制力。法律关系的特殊性在于：它由法律规则界定，其内容可以用法律术语精确描述，并在被违反时引发法律救济。\n\n霍菲尔德（Wesley Hohfeld）为分析法律关系提供了经典工具。他把法律关系还原为几种基本的『法律关系』（jural relations）：主张权（claim right）与义务（duty）、自由权（liberty）与无权利（no-right）、权力（power）与责任（liability）、豁免（immunity）与无能力（disability）。每一对都是对应面（correlatives）——同一关系从两端看的两个名字。Wacks 把这套图式称为分析法律权利的起点。", "history": "法律关系概念的成型，与近代法律体系的系统化同步。罗马法学已经发展出精细的权利分类，如『对物权』（right in rem，可对抗所有人）与『对人权』（right in personam，仅可对抗特定人）的区分，这为分析法律关系提供了早期框架。但把法律关系提炼为一套一般理论，是十九世纪分析法学的工作。\n\n霍菲尔德在 1913 年与 1919 年发表的文章（后收入《司法推理中适用的基本法律概念》）中，针对当时法律语言中『权利』一词的混乱，提出了一套精确的分析框架。他追求的是一种『最小公分母』式的清晰：把各种复杂的法律主张，还原为几种基本法律关系及其组合。Wacks 指出，霍菲尔德的分析至今仍是法理学入门的必修内容，同时也是理解法律体系结构的钥匙。\n\n二十世纪，哈特（H. L. A. Hart）把法律关系放在更宏大的规则理论中考察。他提出法律是初级规则与次级规则的结合：初级规则直接规定人们的行为义务，次级规则规定如何识别、改变与裁判初级规则；正是这种结合，把一个松散的『初级规则社会』变成真正的法律体系。法律关系因此呈现为嵌套在制度结构中的规范联系，零散的权利义务对只是它的表层。", "principle": "理解法律关系，可分四层。\n\n第一层是『关系的对应性』。霍菲尔德的核心洞见是：法律概念总是成对出现。说 X 有主张权，等于说 Y 有义务；说 X 有自由权，等于说 Y 无权利。这种对应性（correlativity）属于同一法律事实的两种描述，修辞层面无从解释。J. W. 哈里斯（J. W. Harris）为霍菲尔德辩护时说，相关性是法律的『最低共同点』——因为每一项司法争议至少涉及两方，法院必须把关系表述为原告与被告之间的对应状态。\n\n第二层是『四种基本关系』。除了主张权—义务、自由权—无权利，还有权力—责任与豁免—无能力。权力是改变他人法律地位的能力，其对应面是他人的『责任』（易受性，即被改变的可能）；豁免是不受他人权力改变的状态，其对应面是他人的『无能力』。霍菲尔德用这些基本单元的组合，去分析复杂的法律主张——一份地产权，往往是一束由多种关系组成的『权利束』。\n\n第三层是『关系的制度基础』。法律关系由规则构造而成，自然形成的说法难以成立。哈特指出，正因为有承认规则、改变规则和裁判规则，我们才拥有『法律体系』的概念；法律关系正是在这个制度框架中被识别、改变与裁判的。没有次级规则，社会只有松散的初级规则，法律关系的确定性就无从谈起。\n\n第四层是『对物权与对人权』。法律关系还可以按对抗范围分类：对物权（right in rem）可对抗不特定的所有人，如物权；对人权（right in personam）仅可对抗特定人，如合同债权。这一区分影响法律关系的主体范围与救济方式，是大陆法系与英美法系共有的分析工具。", "viewpoints": "霍菲尔德与哈特从不同层次揭示了法律关系的本质。\n\n霍菲尔德致力于概念的精确化。他反对把『权利』当成一个含混的万能词，坚持把它拆成主张权、自由权、权力、豁免四种基本法律关系，并为每种关系配上对应面与对立面。Wacks 提醒，霍菲尔德的目标落在提供一种分析工具上，让法律推理更清晰；给『权利』下定义反倒不是重点。他的 critics 指出，这套图式无法充分分析权利的本质，也忽略了义务与权力的多种类型；哈里斯则辩护说，法律概念必须在具体制度语境（如财产权观念）中理解，不能冻结在『瞬时的法律体系』中。\n\n哈特则从制度层面理解法律关系。他强调，法律体系的基础是初级规则与次级规则的结合。次级规则中的承认规则提供有效性标准，改变规则使法律可以被有意识地修改，裁判规则使纠纷可以被权威地解决。正是在这个制度框架内，法律关系才获得确定性、可变性与可裁判性。哈特还用『开放结构』提醒，规则在边缘地带的适用是可争辩的，法律关系也因此在边缘处保持开放。", "comparison": "把霍菲尔德的分析与哈特的制度理论并排看，能看到两个层次。\n\n霍菲尔德关注的是『微观』：法律关系的基本单元是什么？如何把复杂的法律主张拆解为几种基本关系？哈特关注的是『宏观』：这些关系何以构成一个法律体系？答案是次级规则的引入。二者构成互补关系：霍菲尔德提供了分析法律关系的语法，哈特解释了这套语法得以运作的制度条件，冲突之说无从谈起。\n\n在权利与义务的关系上，霍菲尔德与哈特（在权利理论上）都倾向于相关性命题——主张权与义务如同一枚硬币的两面。但 Wacks 指出，这一命题在刑法义务等场合遭遇反例：警察举报犯罪的职责并不对应任何特定人的权利，系安全带的义务也通常不被理解为『对某人的义务』。麦考密克（Neil MacCormick）更进一步：义务常常是为保护权利而设的，逻辑上先于权利。这些质疑提醒我们，相关性是强有力的分析工具，却不是覆盖一切情形的铁律。", "debates": "法律关系领域最根本的争论，是相关性命题（correlativity thesis）的适用范围。\n\n霍菲尔德的立场是强相关：每一种法律权利都有一个对应的义务（或责任、无能力），反之亦然。批评者则举出反例：刑法中的义务往往没有对应的个人权利；我们对动物、婴儿可能负有义务，而它们是否『拥有权利』仍有争议。麦考密克指出，义务常为保护权利而设——先有需要保护的权利，才有相应的义务，二者并非简单的共生。\n\n哈里斯的辩护则更为精细。他承认在严格意义上被告可能并不对原告负义务，但强调法律实践（litigation）总是以对抗双方的形式展开：有人起诉，有人应诉，法院必须回答『被告是否对原告负有义务』。相关性因此是描述诉讼关系的一种『方便方式』。Wacks 总结说，司法推理必然浸透着关于私权与公德的道德与政治观念，纯粹霍菲尔德式的分析并不足够——这为非相关性的权利概念留下了空间。\n\n这场争论的深层意义在于：它追问法律关系是否可以被形式化地分析，还是不可避免地要诉诸道德与政治判断。它把霍菲尔德的精确性与法律现实主义的洞见连接起来，构成本节最有理论张力的部分。", "case": "Johnson v Phillips（1976）是展示法律关系复杂性的好例子。案中一名警官在紧急情况下指示驾车者逆行驶出单行道，以疏通交通。争执的焦点是：警察促进交通顺畅的义务，是否对应某个特定驾车者的权利？从霍菲尔德的框架看，这里存在一个一般性的、面向公众的『义务』，却找不到一个持有对应主张权的特定主体——法院倾向于认为并没有产生这样的对应权利。\n\n这个案例说明，现实中的法律关系并不总是整齐地两两配对。公共职责常常创造一种『对世界的义务』（duty to the world at large），而非『对某人的义务』。Wacks 借此提醒，把每一项义务都硬塞进『某人有对应权利』的模子，会扭曲我们对法律现实的理解。法律关系的形式结构清晰，但其具体内容需要结合制度语境与实践来判断。", "caseAnalysis": "就 Johnson v Phillips 而言，事实是警官为疏通交通作出逆行指示；争议焦点是警察的义务是否对应个人权利；法律依据是公共职责与注意义务的规则；裁判倾向于认为不存在特定个人的对应权利。这个案例的理论意义在于，它检验了相关性命题的边界：在公共职责领域，义务与权利的关系变得松散，霍菲尔德式的对应关系不再自动成立。\n\n把它与哈特的制度理论结合看，就能理解：法律关系结构的清晰来自规则的制度安排，而非概念的自明。霍菲尔德提供的分析工具在私人之间的法律关系（合同、财产）中用得顺手，一旦进入公共法领域，就要结合道德与政治判断。Wacks 的告诫——司法推理『必然浸透着道德与政治观念』——在这里得到了具体的印证。", "summary": "法律关系是法律规则调整主体之间形成的权利义务联系，由主体、客体、内容三要素构成，其特殊性在于由法律界定并可引发法律救济。霍菲尔德把法律关系还原为四种基本关系及其对应面，提供了精确的分析语法；哈特则从制度层面说明，正是初级规则与次级规则的结合使法律关系具有确定性、可变性与可裁判性。相关性命题主张权利与义务成对出现，却在刑法义务、公共职责等场合遭遇反例，引发哈里斯与麦考密克之间的争论。Johnson v Phillips 表明，现实中的法律关系并不总是整齐配对，公共职责常表现为无对应权利的一般义务。理解法律关系，既要掌握其形式结构，也要看到制度语境与实践判断的塑造作用。", "furtherThinking": "1. 霍菲尔德的相关性命题在私人关系中相当清晰，在公共职责领域却漏洞频出。这是否说明法律关系必须区分『私法关系』与『公法关系』两类，各有不同的结构？\n2. 哈特说法律体系的基础是次级规则。如果承认规则本身是开放的、可争辩的，那么法律关系的确定性究竟建立在什么之上？\n3. 一份地产权常被形容为一束『权利束』。请用霍菲尔德的四种基本关系，尝试分析你拥有的一套住房中可能包含哪些法律关系。"}, "en": "Legal Relations", "level": "core", "tags": "法律关系, 霍菲尔德, 相关性, 权利义务, 法理学", "source": "Wacks, Understanding Jurisprudence, ch.10.1；Hart, The Concept of Law, ch.5, ch.6；Siems, Comparative Law, Introduction & ch.7", "id": "S1M3K8"}, "S1M4K1": {"title": "正义的概念", "EN": "The Concept of Justice", "LEVEL": "core", "TAGS": "正义, 法理学, 正义理论, 法律与道德", "TERMS": "正义（Justice）::给予每个人应得之物、使相同案件受到相同处理的社会理想与德性；应得（Desert）::依据功绩、需要或贡献而应获得某种对待的根据；分配正义（Distributive Justice）::关于社会利益与负担如何在成员间分配的正义；矫正正义（Corrective Justice）::关于矫正错误、补偿损害的正义；程序正义（Procedural Justice）::关于决定过程是否公平的正义；实体正义（Substantive Justice）::关于决定结果与内容是否公正的正义；自然法（Natural Law）::主张法律与道德存在必然联系的理论；法律实证主义（Legal Positivism）::主张法律与道德在概念上可以分离的理论", "SOURCE": "Wacks, Understanding Jurisprudence, ch.9；Hart, The Concept of Law, ch.8；Siems, Comparative Law, ch.10", "terms": [{"term": "正义（Justice）", "def": "给予每个人应得之物、使相同案件受到相同处理的社会理想与德性"}, {"term": "应得（Desert）", "def": "依据功绩、需要或贡献而应获得某种对待的根据"}, {"term": "分配正义（Distributive Justice）", "def": "关于社会利益与负担如何在成员间分配的正义"}, {"term": "矫正正义（Corrective Justice）", "def": "关于矫正错误、补偿损害的正义"}, {"term": "程序正义（Procedural Justice）", "def": "关于决定过程是否公平的正义"}, {"term": "实体正义（Substantive Justice）", "def": "关于决定结果与内容是否公正的正义"}, {"term": "自然法（Natural Law）", "def": "主张法律与道德存在必然联系的理论"}, {"term": "法律实证主义（Legal Positivism）", "def": "主张法律与道德在概念上可以分离的理论"}], "sections": {"coreQuestion": "我们几乎每天都在使用「正义」这个词：看到插队被人指责「不公平」，听到判决结果会说「正义得到伸张」，讨论税收时会争「这样分配不正义」。可是，一旦要回答「正义到底是什么」，人们立刻众说纷纭。有人说是「各得其所」，有人说是「法律面前人人平等」，有人说是「最大化社会幸福」。更麻烦的是，正义常常被用作批判法律的武器——我们说一条法律「不正义」，似乎意味着它不够格被称为法律。这就引出了法理学上一连串根本问题：正义有没有一个可被辨认的核心结构？它与法律、道德、公平是何种关系？法律与正义之间是不是存在必然联系？本节先来辨认这个概念的骨架，一句现成的定义留到最后再谈，理解为何两千多年来最出色的头脑仍在为它争论。", "definition": "正义（Justice）在西方思想传统中有一个流传最广的表述：给予每个人应得之物（rendering to each his due）。亚里士多德（Aristotle）在《尼各马可伦理学》第五卷中把正义视为一种德性，其内容是「把相等的东西相等地对待，把不相等的东西按其不相等的程度区别对待」。这句话看似简单，实则包含两个层次：一是形式上的一致性，二是判断「何时相同、何时不同」的标准。\n\n哈特（H. L. A. Hart）在《法律的概念》中把这两个层次说得更清楚。他写道，正义观念包含两个部分：一个恒定不变的成分，可以概括为「相同案件相同处理」（treat like cases alike）；另一个是变动不居的成分，即在特定目的下判断哪些案件相同、哪些不同的标准。例如，高考加分政策是否正义，争论的往往落在「哪些考生属于应当被区别对待的情形」上；「应否相同对待考生」几乎无人反对。\n\nWacks 提醒我们，正义是一个「难以捉摸的理想」（elusive ideal），从柏拉图、亚里士多德到边沁、罗尔斯、诺齐克，思想家们并未就定义达成一致。因此，学习正义概念的关键不在于背诵某句话，而在于掌握它的内部结构：形式的一致性要求加实质性的判断标准，二者缺一不可。只有形式，正义会沦为机械的刻板；只有实质标准而无一致性，正义就变成任意的偏私。", "history": "正义理论的_history与西方社会结构的变迁紧密相连。在古希腊，城邦（polis）是公民共同体，正义被理解为一种使共同体井然有序的德性。亚里士多德把正义放在伦理学的框架中讨论，把它与节制、勇敢等德性并列，并主张德性是对过度与不及之间的「中道」（Golden Mean）的追求——勇敢过度成鲁莽，不及成怯懦；正义则是在利己与利他之间保持恰当的平衡。\n\n罗马法学家把正义界定为「给予每个人应得之物的坚定而永恒的意志」，并把法学称为「神事与人事的知识、正义与不义的区分」。中世纪神学把正义的最终根据追溯到神的理性与自然法。近代民族国家兴起后，霍布斯、洛克、卢梭的社会契约论把正义重新解释为人们为摆脱自然状态而订立的契约的产物，正义从此与个体权利、国家权力的正当性联系在一起。\n\n进入十九世纪，边沁（Jeremy Bentham）的功利主义把正义还原为「最大化幸福」，并以「快乐与痛苦」为道德计算的基础，他甚至把自然权利讥讽为「踩着高跷的胡说」。二十世纪两次世界大战与极权主义的经验，则使正义重新成为法理学的中心议题：纽伦堡审判之后，人们不得不追问，严重违背正义的统治秩序是否还配称为「法律」。", "principle": "理解正义的内部结构，可以从四个层次逐层推进。\n\n第一，正义具有「应得」的结构。无论是称赞一种安排正义，还是谴责它不正义，我们通常都在诉诸某种应得根据：或按功绩（谁贡献多谁多得），或按需要（谁更困难谁多助），或按身份与约定（契约约定了什么就得到什么）。应得根据不同，正义的结论就不同。罗尔斯（John Rawls）称，这是一个「判断标准」的问题。\n\n第二，正义包含形式与实质两个层面。形式层面就是哈特所说的「相同案件相同处理」，它要求规则被一致地适用，不允许对同样情形任意区别对待。这一层面与法治、合法性密切相关，被称为形式正义（Formal Justice）。实质层面则追问：用来判断「相同」的标准本身是否公正？一个把奴隶与主子视为「不同」的法律体系，完全可能一致地适用其规则，却在实质上极不正义。Wacks 引述戴维·莱昂斯（David Lyons）的判断：以统一、regular 的方式处理案件「可能是正义的必要条件，却不是充分条件」。\n\n第三，正义与道德既有联系又有区别。正义通常被视为道德的一个特殊部门——它关乎人与人之间利益与负担的分配、权利的界定以及对错误的矫正，而不是关乎个人品格的全部。可以说，不正义是一种特殊的道德缺陷，但并非所有道德缺陷都是不正义。\n\n第四，正义在类型上可以展开。亚里士多德区分了分配正义（涉及利益与负担在社会成员中的分配，主要是立法者关心的事）与矫正正义（涉及对犯罪与侵权行为的救济，主要是法院关心的事）。现代法学又在此基础上发展出报应正义（Retributive Justice）、补偿正义（Compensatory Justice）、程序正义与实体正义等分支。", "viewpoints": "围绕正义，几位关键思想家给出了影响深远的答案。\n\n亚里士多德把正义视为一种德性，并区分了「算术的平等」与「几何的平等」：前者对应矫正正义，要求在所有当事人之间一律平等，不问身份高低；后者对应分配正义，要求按各人的功绩或价值成比例地分配。\n\n哈特提出了一个影响广泛的形式标准：正义在于「相同案件相同处理」。Wacks 指出，哈特这一「基本上是程序性的标准」获得了相当广泛的接受。但哈特本人也承认，面对一条不正义的法律，把相同案件相同处理反而可能造成不义——这提示了形式标准的界限。\n\n罗尔斯在《正义论》（A Theory of Justice, 1972）中提出「作为公平的正义」（justice as fairness）。他反对功利主义为了总量而牺牲个人的做法，主张正义问题先于善的问题，并以「原初状态」（original position）与「无知之幕」（veil of ignorance）为思想装置，推导出两条正义原则。\n\n诺齐克（Robert Nozick）在《无政府、国家与乌托邦》（Anarchy, State and Utopia）中提出资格理论（entitlement theory），主张正义取决于持有物的历史来源是否正当，而非是否符合某种分配模式。他与罗尔斯一样反对功利主义，但在分配问题上走向了相反方向。", "comparison": "把正义与几个相邻概念并排看，边界会更清晰。\n\n正义与法律：自然法理论主张二者存在必然联系，严重不正义的规则不是真正的法律（「恶法非法」）；法律实证主义坚持分离命题，认为一条规则是不是法律，取决于它的来源而非道德价值。这是法理学关于正义最持久的争论。\n\n正义与道德：正义是道德中关注制度、分配与权利的那一部分；道德还包括仁慈、忠诚等不直接进入制度设计的德性。把正义等同于全部道德，会使它失去分析的锋芒。\n\n正义与公平：在日常语言中两者常被混用，但学理上可以区分。公平（Fairness）更强调程序的中立与机会的均等，正义则还包括应得、功绩与对错误的矫正。罗尔斯把他的理论命名为「作为公平的正义」，恰恰是想用公平来诠释正义，而不是把两者等同。\n\n正义与效率：一项安排可能效率很高却不正义，也可能很正义却代价高昂。功利主义倾向于把正义纳入效率的计算，而罗尔斯、诺齐克、德沃金（Ronald Dworkin）都反对把正义还原为效率。", "debates": "法理学上关于正义最经典的争论，是「法律与正义是否存在必然联系」。\n\n自然法一方的论据是：法律的目的是实现正义与共同善，一条严重违背正义的规则从根本上背离了法律的目的，因此不配称为法律。二战后，这一思路被用来处理纳粹政权的法律，拉德布鲁赫（Gustav Radbruch）等人的观点影响很大。\n\n实证主义一方的论据是：把道德标准引入法律的概念，会使法律的识别标准变得不确定，人们无法清楚地知道什么是法律什么时候生效；更清醒的做法是承认恶法也是法律，然后正当地抵抗它。哈特在与富勒（Lon Fuller）的论战中坚持这一立场——Wacks 记录，哈特与富勒的论战于1957年发起、1958年发表于《哈佛法律评论》，是二十世纪法理学的标志性事件。\n\n争论的双方其实共享一个前提：都反对不正义。分歧在于概念策略——是把不正义排除出法律概念，还是把不正义保留在法律概念之内加以谴责。Wacks 把这场争论列为理解法理学的关键入口，因为任何法律理论都必须交代自己如何处理「效力」与「正当性」的关系。", "case": "1945年至1946年的纽伦堡审判（Nuremberg trials）是理解正义与法律关系的经典案例。第二次世界大战结束后，同盟国在德国纽伦堡设立国际军事法庭（International Military Tribunal），对纳粹德国的主要战犯进行审判。审判依据《国际军事法庭宪章》，罪名包括破坏和平罪、战争罪与反人道罪。\n\n被告提出的一项核心抗辩是：他们的行为在当时纳粹德国的法律秩序下是合法的，事后用新的法律标准追究事前的行为，违反了「法无明文规定不为罪」的原则。这一抗辩把法律实证主义的难题以最尖锐的形式摆上台面：如果合法性完全由既有的法律秩序决定，那么对合法行为的追诉就缺乏法律依据。\n\n法庭最终驳回了这一抗辩，坚持某些严重违反国际法与人类基本道德的行为，不论国内法如何规定，都应承担刑事责任。Wacks 指出，纽伦堡审判所确立的原则——某些行为构成国际罪行——对自然法思想的复兴产生了重大影响。", "caseAnalysis": "就纽伦堡审判而言，事实层面是：战犯的行为依当时德国国内法可能具有形式合法性；争议焦点是：事后设定的国际法标准能否用来评价并惩罚先前的行为。\n\n从法律实证主义的角度看，这涉及法律的明确性与不溯及既往原则，追诉确实面临合法性难题；从自然法角度看，当国内法严重背离正义与人类基本价值时，它丧失了主张服从的资格，国际法庭的做法是对更高层次法律秩序的维护。\n\n裁判理由的核心在于：某些罪行之严重，已超出任何主权国家可以合法授权的范围，国际法对此早有禁止性规定，因此不存在真正的「事后立法」问题。\n\n理论意义在于，纽伦堡审判把「法律与正义的关系」从书斋争论变成了制度实践。它提示我们：形式合法性是法治的重要条件，但不是道德豁免证；当法律秩序本身沦为犯罪的工具时，正义会要求人们重新审视法律的效力与正当性。这也解释了为什么战后的法理学格外关注「法律是否必须具备某种最低限度的正义」这一问题。", "summary": "正义的核心结构是「给予每个人应得之物」，它包含形式与实质两个层面：形式层面要求相同案件相同处理，实质层面要求判断「相同与否」的标准本身公正。只有形式而无实质，正义会沦为机械或偏私的工具。亚里士多德奠定了分配正义与矫正正义的区分，哈特提出了影响广泛的形式标准，罗尔斯、诺齐克则在现代政治哲学中把正义问题推向深入。围绕法律与正义是否必然联系，自然法与法律实证主义形成了持久争论；纽伦堡审判表明，这一争论关乎如何面对极端不正义的制度实践，概念游戏之说低估了它。掌握这些骨架，后续讨论分配、矫正、程序与实体正义时才有共同的坐标。", "furtherThinking": "1. 如果一条法律的程序完美无缺、适用完全一致，但内容严重歧视某一群体，你会说它「不正义」还是「不是法律」？两种说法各自带来什么后果？\n2. 哈特说「相同案件相同处理」是正义的一部分，但判断案件是否相同的标准从何而来？能否找到完全中立、不受价值影响的标准？\n3. 纽伦堡审判中「依当时国内法合法」的抗辩被驳回，这是否意味着明确性与不溯及既往原则可以被牺牲？应如何划定例外边界？"}, "en": "The Concept of Justice", "level": "core", "tags": "正义, 法理学, 正义理论, 法律与道德", "source": "Wacks, Understanding Jurisprudence, ch.9；Hart, The Concept of Law, ch.8；Siems, Comparative Law, ch.10", "id": "S1M4K1"}, "S1M4K2": {"title": "实体正义与程序正义", "EN": "Substantive Justice and Procedural Justice", "LEVEL": "core", "TAGS": "实体正义, 程序正义, 正当程序, 形式正义", "TERMS": "程序正义（Procedural Justice）::关于作出决定的过程是否公平、中立、可参与的正义；实体正义（Substantive Justice）::关于决定内容与结果是否公正、权利与利益分配是否合理的正义；形式正义（Formal Justice）::规则被一致、公开、无偏私地适用的正义；正当程序（Due Process）::要求国家在剥夺个人生命、自由或财产前遵循公平程序的原则；自然正义（Natural Justice）::英美法中要求裁判者中立、听取双方意见的最低程序原则；内在道德（Internal Morality）::富勒提出的法律在程序上应具备的最低要求", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Hart, The Concept of Law, ch.8；Siems, Comparative Law, ch.10", "terms": [{"term": "程序正义（Procedural Justice）", "def": "关于作出决定的过程是否公平、中立、可参与的正义"}, {"term": "实体正义（Substantive Justice）", "def": "关于决定内容与结果是否公正、权利与利益分配是否合理的正义"}, {"term": "形式正义（Formal Justice）", "def": "规则被一致、公开、无偏私地适用的正义"}, {"term": "正当程序（Due Process）", "def": "要求国家在剥夺个人生命、自由或财产前遵循公平程序的原则"}, {"term": "自然正义（Natural Justice）", "def": "英美法中要求裁判者中立、听取双方意见的最低程序原则"}, {"term": "内在道德（Internal Morality）", "def": "富勒提出的法律在程序上应具备的最低要求"}], "sections": {"coreQuestion": "设想两幅场景。第一幅：一场审判中，法官耐心听取双方举证，允许被告逐一质证，判决书写明了理由，最终却因为一条歧视性法律而判被告败诉。第二幅：另一位法官完全不按程序办事，不给被告陈述机会，凭个人好恶作出了一个结果上恰好公正的判决。这两个场景哪个更接近「正义」？前者程序无可挑剔而结果不公，后者结果正确而过程专断。这个思想实验逼出了法理学上一组关键区分：程序正义与实体正义。二者能否分离？能否各自独立成立？当它们冲突时应当如何取舍？本节要做的，就是把这对概念拆开来看，并借助真实案例检验它们的解释力。", "definition": "程序正义（Procedural Justice）关注的是决定「如何作出」：裁判者是否中立、当事人是否有陈述和申辩的机会、过程是否公开、理由是否说明、规则是否被一致适用。它的核心要求是「任何人都不得做自己案件的法官」（nemo judex in causa sua）以及「听取另一方的意见」（audi alteram partem），这两条合称自然正义（Natural Justice）。在英美法中，正当程序（Due Process）原则把这类要求提升为宪法性原则。\n\n实体正义（Substantive Justice）关注的是决定「是什么」：最终的结果、权利与义务的分配本身是否公正。例如，同工同酬是否得到实现、刑罚是否与罪责相称、某项法律是否不正义（unjust）到不应被适用，都属于实体正义的问题。\n\n把二者看成同一维度的两端会失准：它们属于评价法律决定的两套不同标准。Wacks 在讨论法官道德时明确指出，这里存在一个「实体正义与程序正义的区分」（the distinction between substantive and procedural justice）。哈特所主张的「相同案件相同处理」，被 Wacks 判定为「基本上是程序性的标准」。这意味着，一个法官即使严格遵循程序，仍可能在实体上制造不义。", "history": "程序正义的观念在英美法中渊源深厚。英国的不成文宪法传统中，自然正义原则长期约束着裁判权与行政权，要求裁判者中立、当事人获得听证。美国宪法第五修正案与第十四修正案的正当程序条款，把这一传统写入宪法文本，使程序正义成为审查立法与行政行为的最高准则之一。\n\n与之相对，大陆法系更强调实体法的体系化建构，法院的角色被理解为正确地适用法典、实现实体正义。Wacks 引述的比较法研究提示，普通法与民法法系在法官角色、程序风格上存在差异：普通法法官更倚重对抗制程序，民法法系的职业法官则在等级体系中追求实体正确的裁判。这种差异使两地对程序与实体的侧重有所不同，但都不否认两者需要兼顾。\n\n二十世纪，富勒（Lon Fuller）把程序维度推向极致。他在《法律的道德性》中提出法律的「内在道德」（Internal Morality），列举了使法律成为可能的一系列程序性要求——一般性、公开性、不溯及既往、明确性、不矛盾等。Wacks 指出，富勒采取的是一种「程序性自然法」立场：他关注法律体系在程序上是否健全，而不是直接判定每条法律的内容是否正义。", "principle": "程序正义与实体正义的关系，可以从三层逻辑展开。\n\n第一层，两者各有不可替代的价值。程序正义保障人的尊严与参与感——即使结果不利，一个被认真倾听、被告知理由的人，更容易接受决定。它同时约束权力，防止裁判者任意妄为。实体正义则回应人们对「正当结果」的期待：如果结果本身严重不公，再精致的程序也只是在「文明地制造不义」。\n\n第二层，两者可能发生冲突。Wacks 举出了经典情境：在种族隔离制度下，一位法官公正无私地适用隔离法律，对相同案件相同处理。从程序正义看，他无可指摘；但从实体正义看，他在助长不义。相反，如果他拒绝适用该法律，他可能违反了「依法裁判」的程序性义务，却在实体上更接近正义。Wacks 引述戴维·莱昂斯的判断：统一地处理案件「可能是正义的必要条件，却不是充分条件」，并总结说「仅仅遵守形式正义的原则，不足以达到道德上正确的门槛」。\n\n第三层，程序标准本身也可能是「薄」的。哈特的「相同案件相同处理」只要求一致性，并不回答「用什么标准判断相同」。如果标准是种族，一致适用只会放大不义。因此，成熟的程序正义理论往往要求在最低限度上纳入某些实体考量——这使程序与实体的界线变得模糊，也正是富勒「内在道德」与纯粹形式主义的分野所在。", "viewpoints": "哈特提供了影响深远的程序性标准：正义在于「相同案件相同处理」。Wacks 指出，这一「基本上是程序性的标准已获得相当广泛的接受」。但哈特同时承认，面对不义法律，一致适用反而可能造成不义，这说明程序标准的适用有边界。\n\n富勒在《法律的道德性》中主张法律具有内在道德，即一套使规则得以被服从的程序性德性。Wacks 强调，富勒的立场是程序性的而非实体性的自然法：即使规则内容有争议，只要它满足一般性、公开性、不溯及既往等形式要求，就具备法律性。但 Wacks 也提醒，遵守富勒的内在道德并不保证法律一定正义——他的论证支持的往往只是「偶然的联系」而非「必然的联系」。\n\n德沃金（Ronald Dworkin）从另一个方向推进。Wacks 指出，德沃金所谓的「合法性」（legality）服务于一种独立价值——「政治完整性」（political integrity），其含义是法律面前人人平等，不仅是法律被照字面执行，更在于政府必须依一套原则上适用于所有人的原则来治理。任意的强制或惩罚，即便偶尔提高了效率，也违反了政治平等这一核心维度。这实际上把实体性的平等价值注入了对合法性的理解。", "comparison": "把程序正义与实体正义并列对照，可以看到几种典型组合。\n\n程序正义优先的典型是法律实证主义的形式分支与富勒的程序性自然法：只要规则制定与适用过程符合公开、一般、一致、不溯及既往等要求，法律就具备正当性的重要基础。其优点是标准清晰、可操作，缺点是可能对严重不义的内容无能为力。\n\n实体正义优先的典型是自然法与各类实质法治理论：法律必须满足正义或权利保障的实质要求才配称法律。其优点是能直面恶法，缺点是实质正义的标准容易多元而难以形成稳定共识。\n\n折中立场承认两者的相互依赖：程序是实体得以稳定实现的保障，实体为程序提供价值方向。Wacks 对哈特与富勒的讨论实际上支持这种折中——任何理论都要交代自己如何处理效力与正当性的关系，而不能只取一端。\n\n还需区分形式正义与程序正义：形式正义强调规则适用的一致与公开，是哈特「相同案件相同处理」的核心；程序正义的范围更广，还包括听证、中立、理由说明等具体要求。两者常被合称，但严格说程序正义比形式正义更厚。", "debates": "程序与实体之争，最集中地体现在「法官面对不义法律时应如何做」这一经典难题上。\n\nWacks 在讨论「正义的法官」时，描述了两种可能：其一，一位公平、诚实、公正的法官，却认为种族隔离在道德上可以辩护；其二，法官承认制度不义，但认为接受任命可以通过改善不公来「行善」。第一种情形暴露了程序德性的局限——中立、无偏私、讲理这些「司法德性」，并不足以保证法官在实体上是道德的。Wacks 引述 Cover 的《Justice Accused》，记录了温德尔·菲利普斯法官因抗议要求交还逃奴的法律而辞职的事例，说明「有德性的法官」这一说法本身需要追问：德性究竟指程序上的公正，还是实体上的正当？\n\n争论的实质是：能否在纯程序层面上找到令人满意的正义或道德概念？Wacks 的结论倾向于否定。他说，在程序层面上我们「不太可能找到令人满意的正义概念」，并断言「仅仅遵守形式正义的原则，是道德上正确与否的不充分门槛」。一位严格执行不道德法律的法官，即便一丝不苟地满足了正当程序要求，仍然「未能做到道德，也未能做到正义」。\n\n反驳一方会强调：若允许法官以个人实体判断拒绝适用法律，法律的可预测性与法治就会被侵蚀，每个人的命运将取决于裁判者的价值偏好。这一担忧正是法律实证主义坚持分离命题的现实理由。争论至今没有定论，但它确定了讨论的边界：程序与实体都是评价法律不可或缺的维度，问题在于如何权衡。", "case": "美国最高法院1963年判决的吉迪恩诉温赖特案（Gideon v. Wainwright, 372 U.S. 335）是程序正义的经典案例。克拉伦斯·厄尔·吉迪恩（Clarence Earl Gideon）因被控闯入并盗窃佛罗里达州一家台球厅的财物而受审。他请求法院为其指定律师，但依据当时佛罗里达州法律，只有在可能判处死刑的案件中才必须为贫困被告指定律师，法院拒绝了他的请求。吉迪恩自行辩护，被判有罪并处五年监禁。\n\n吉迪恩在狱中手写请愿书上诉至美国最高法院。最高法院于1963年作出一致判决，裁定第六修正案的律师协助权属于「根本性与基础性」的权利，通过第十四修正案的正当程序条款适用于各州，各州必须为无力聘请律师的重罪被告提供律师。判决推翻了先前的判例，吉迪恩获准重新审判，这次有律师辩护的他被判无罪。\n\n本案的戏剧性在于：如果没有律师帮助，一个可能无罪的人被定罪；程序缺陷直接导致了实体错误。这使吉迪恩案成为说明程序正义与实体正义相互关联的教科书式案例。", "caseAnalysis": "就吉迪恩案而言，事实层面是：州法院依当时州法拒绝为贫困被告指定律师；争议焦点是：第六修正案的律师权是否通过正当程序条款约束各州。\n\n法律依据方面，最高法院把律师协助权理解为公正审判不可或缺的工具，而非可有可无的优待。裁判理由在于：在对抗制程序中，一个不懂法律的普通人几乎无法有效质证、提出抗辩与适用法律，缺乏律师将使审判徒具形式，实体的真实与公正难以实现。\n\n从程序正义角度，本案确认了「获得律师帮助」是公平审判的最低要求之一，体现了自然正义中「被听取」的精神。从实体正义角度，本案说明程序保障并非只是繁文缛节——它直接影响判决的正确性。吉迪恩重审获无罪的结果，为这一判断提供了有力的经验佐证。\n\n理论意义上，本案支持了「程序与实体相互依赖」的折中立场：没有程序保障，实体正义难以稳定实现；而程序规则的正当性，又取决于它是否真正服务于公平裁判这一实体目标。它也提示我们，正当程序是防止错判的制度装置，对效率的拖累只是误解。", "summary": "程序正义评价决定「如何作出」，实体正义评价决定「是什么」。哈特的「相同案件相同处理」是典型的程序性标准，但其局限在于无法回答判断同异的标准是否公正；富勒以「内在道德」把程序性要求系统化，但 Wacks 指出遵守程序并不保证结果正义。Wacks 进一步表明，仅在程序层面寻找令人满意的正义概念是困难的——一位严格遵守程序、适用不义法律的法官，仍然未能做到正义。吉迪恩案则说明，程序保障与实体正确并非对立：缺乏律师帮助的审判，既程序有缺陷，也导致实体错误。理解这一点，才能明白为何现代法治既要正当程序，也要对法律内容保持实体性的审视。", "furtherThinking": "1. 如果你是种族隔离制度下的法官，拒绝适用隔离法会破坏法律的确定性，适用它又助长不义。你会如何选择？这种两难说明纯粹程序标准的什么局限？\n2. 富勒的「内在道德」只要求程序健全，是否足以使一套法律获得服从的资格？请举出反例加以检验。\n3. 吉迪恩案表明程序保障能减少错判。这是否意味着程序越复杂、越严格，实体正义就越有保障？请说明可能的边际效应。"}, "en": "Substantive Justice and Procedural Justice", "level": "core", "tags": "实体正义, 程序正义, 正当程序, 形式正义", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Hart, The Concept of Law, ch.8；Siems, Comparative Law, ch.10", "id": "S1M4K2"}, "S1M4K3": {"title": "分配正义", "EN": "Distributive Justice", "LEVEL": "core", "TAGS": "分配正义, 罗尔斯, 诺齐克, 差别原则, 资格理论", "TERMS": "分配正义（Distributive Justice）::关于社会利益与负担如何在成员之间分配的正义；功绩（Desert/Merit）::依据贡献、努力或才能而应得分配份额的根据；原初状态（Original Position）::罗尔斯设想的选择正义原则的虚拟处境；无知之幕（Veil of Ignorance）::使选择者不知自身社会地位与天赋的思想装置；差别原则（Difference Principle）::允许不平等仅在有利于最不利者时被接受的原则；资格理论（Entitlement Theory）::诺齐克主张正义取决于持有物获取与转让历史正当性的理论", "SOURCE": "Wacks, Understanding Jurisprudence, ch.9；Siems, Comparative Law, ch.10", "terms": [{"term": "分配正义（Distributive Justice）", "def": "关于社会利益与负担如何在成员之间分配的正义"}, {"term": "功绩（Desert/Merit）", "def": "依据贡献、努力或才能而应得分配份额的根据"}, {"term": "原初状态（Original Position）", "def": "罗尔斯设想的选择正义原则的虚拟处境"}, {"term": "无知之幕（Veil of Ignorance）", "def": "使选择者不知自身社会地位与天赋的思想装置"}, {"term": "差别原则（Difference Principle）", "def": "允许不平等仅在有利于最不利者时被接受的原则"}, {"term": "资格理论（Entitlement Theory）", "def": "诺齐克主张正义取决于持有物获取与转让历史正当性的理论"}], "sections": {"coreQuestion": "一个社会的财富、机会、权力与负担应当如何分配？为什么有人天生富裕、有人一生贫困，这种差别是「正义的」还是「需要被纠正的」？税收、社会保障、教育资源倾斜、平权行动，这些政策各自诉诸什么样的正义标准？有人说「按贡献分配才公平」，有人说「应当照顾最不利者」，还有人说「只要来路正当，结果是否平均无所谓」。分配正义（Distributive Justice）就是研究这些问题的理论部门。它要追问的是：判断一种分配是否正义，究竟依据什么原则？罗列政策在这里只是起点。本节将以亚里士多德的问题意识为起点，重点展开罗尔斯与诺齐克两种在现代政治哲学中居于中心地位、且相互对立的答案。", "definition": "分配正义（Distributive Justice）关注的是社会中可分配之物——财富、收入、机会、权利、荣誉——以及负担与责任，应当依据什么原则在成员之间进行分配。亚里士多德在《尼各马可伦理学》第五卷中把分配正义界定为「按功绩或价值成比例地分配」，并指出这主要是立法者（而不是法院）关心的事务。Wacks 的归纳是：分配正义「关心的是按照每个人的应得或功绩给予其相应份额」。\n\n与矫正正义不同，分配正义涉及的是「几何的平等」——按各人相应的比例分配，而非一律平等。这就引出了两个关键问题：第一，用什么作为比例的标准？功绩、需要、身份、贡献，都可能成为候选。第二，不平等本身是否可接受？如果可以，需要什么条件来证成？\n\n在现代政治哲学中，分配正义问题获得了更尖锐的形式。罗尔斯把正义的主题规定为「社会基本结构」——即社会主要制度分配基本权利与义务、划分由社会合作产生的利益与负担的方式。诺齐克则把焦点从「分配的结果模式」转向「持有的历史过程」，从而对罗尔斯式理论发起根本挑战。Wacks 把两人的理论列为第9章四种正义理论中的两种，并指出「当代自由主义思想的主导性影响」在罗尔斯的著作中体现得最为明显。", "history": "分配正义的问题意识可以追溯到亚里士多德对「成比例平等」的分析，但其在现代形态的形成，与近代社会的平等化诉求和福利国家的兴起密切相关。法国大革命提出的「自由、平等、博爱」，使平等成为现代政治的合法性语言；工业化和垄断带来的巨大贫富差距，则迫使思想家回答「形式的平等是否足够」这一现实问题。\n\n二十世纪上半叶，功利主义长期主导英语世界的政治哲学：边沁、密尔（John Stuart Mill）主张最大化总体幸福，19世纪末的西季威克（Henry Sidgwick）延续了这一传统。功利主义的弱点是，它可能为了总量而牺牲少数人的基本权利——Wacks 指出，罗尔斯和诺齐克都反对这种「为了总体利益而牺牲个人」的做法。\n\n1971年罗尔斯《正义论》的出版被视为分水岭。Wacks 记载，该书1972年出版后引发了海量讨论，此后「任何一种政治哲学要么在罗尔斯的理论框架内工作，要么解释为什么不这样做」。诺齐克1974年出版的《无政府、国家与乌托邦》则以自由至上主义立场正面回应，两人共同塑造了此后数十年的分配正义讨论。", "principle": "罗尔斯的理论可以从三个环节理解。\n\n第一，对功利主义的批判。罗尔斯认为功利主义有两个根本缺陷：其一，它没有认真对待「人的分离性」（the separateness of persons），把社会当成一个可以跨人加总幸福的超个人；其二，正当（right）应先于善（good），正义原则不能建立在某种特定的善观念之上。因此，正义问题优先于效率问题。\n\n第二，原初状态与无知之幕。罗尔斯设想人们在一种「原初状态」（original position）中选择正义原则，他们被「无知之幕」（veil of ignorance）遮蔽，不知道自己的阶级、天赋、性别、种族与善观念。Wacks 生动地转述了这一意象：人们如同坐在树下，各自被无知之幕笼罩，共同商议正义原则。由于无人知道揭幕之后自己会处于何种地位，理性选择将遵循「最大最小化」（maximin）策略——即最大化最不利者的前景。\n\n第三，两条正义原则。在这一约束下，罗尔斯论证人们会选择：第一，平等的基本自由原则；第二，社会与经济不平等应当这样安排，使它们（a）在机会公平平等的条件下向所有人开放职位，（b）有利于社会中最不利成员的最大利益——后者即「差别原则」（difference principle）。Wacks 指出，罗尔斯所谓的「基本善」（primary goods）包括权利、自由、权力、机会与收入等。\n\n诺齐克的理论则沿另一条路径展开。\n\n第一，资格理论的核心是：分配是否正义，取决于每个人对持有物的获取与转让是否在历史上正当，而不是取决于结果是否符合某种模式。若初始获取正当、后续转让自愿，则无论结果多不平等，都是正义的。\n\n第二，对「模式化分配」的批判。诺齐克认为，任何试图维持某种分配模式（如按功绩、按需要或按差别原则）的国家，都必须不断干预人们的自愿交换，从而侵犯自由。他提出了著名的「张伯伦论证」（Wilt Chamberlain example）：若初始分配 D1 是正义的，球迷自愿掏钱看张伯伦打球，使他的收入远高于常人，这种新分配依然是正义的；要阻止这种结果，就必须持续干涉人们自愿的行为。Wacks 指出，这是诺齐克用来揭示「非资格理论缺陷」的核心例证。\n\n第三，最弱意义国家。诺齐克主张一种「守夜人式国家」（night-watchman state），其职能仅限于防止暴力、盗窃与欺诈，以及保护契约等，任何超出这一范围的再分配都缺乏正当性。他把税收与强迫劳动相类比，认为它侵犯了个人对自己才能与劳动成果的所有权。", "viewpoints": "亚里士多德奠定了「按功绩成比例分配」的基本框架，并把分配正义定位为立法者的事务。他的思路预设了一个共同认可的价值尺度——所谓「功绩」必须依托于共同体对何为有价值的一致理解。\n\n罗尔斯（John Rawls, 1921–2002）把分配正义重构为一种「作为公平的正义」（justice as fairness）。Wacks 指出，罗尔斯的敌意主要针对功利主义未能承认人的分离性，以及正义应先于善。他通过原初状态与无知之幕的设定，把分配问题转化为「在不确定自身地位时你会选择什么原则」的理性选择问题，并以差别原则为不平等设定证成条件。罗尔斯后来在《政治自由主义》（1993）中修正并深化了自己的理论，以回应社群主义等批评。\n\n诺齐克（Robert Nozick, 1938–2002）以资格理论反驳一切「模式化」分配。Wacks 强调，诺齐克的核心主张是：如果每个人对其持有物拥有资格，分配就是正义的，「无论它呈现出何种模式」。他明确主张「自由与平等不可调和」，任何再分配都预设了过度强大的国家权力，而国家本身在道德上是「内在地令人反感」的。", "comparison": "罗尔斯与诺齐克构成现代分配正义讨论中最鲜明的对照。\n\n在正义的判断对象上，罗尔斯关注分配的结果结构与基本制度安排，诺齐克关注持有物的历史来源。前者问「结果合理吗」，后者问「来路正当吗」。\n\n在平等与自由的关系上，罗尔斯试图通过差别原则把自由和平等协调起来，认为不平等只有在惠及最不利者时才可接受；诺齐克则认为二者不可调和，为了平等而进行的再分配必然侵犯自由。\n\n在国家角色上，罗尔斯的理论要求国家通过税收和制度设计调节社会基本结构；诺齐克主张最弱意义国家，反对超出保护性职能的再分配。Wacks 指出，诺齐克把任何模式化分配视为对国家权力的扩张，并把所得税比作强迫劳动。\n\n在方法上，罗尔斯依赖一种理想化的契约论装置（原初状态），诺齐克依赖一种历史性的权利理论。Wacks 记录了双方及第三方对彼此的批评：罗尔斯的原初状态被批评为「预先设定了它所寻求的结论」，诺齐克的理论被批评为预设了过于狭窄的权利观，忽视了福利权等积极权利。\n\n值得注意的是，两人虽在分配问题上尖锐对立，却共享一个前提：都反对功利主义，都高度重视个人权利的不可侵犯性。Wacks 提醒读者，不要因为诺齐克结论激进就把他简单标签化——他的论证在自由主义内部具有严肃的哲学根基。", "debates": "罗尔斯与诺齐克之争，是当代分配正义的经典争论。\n\n罗尔斯一方的论据：其一，天赋与家庭背景是道德上任意的，没有人「应得」自己的天赋，因此把天赋带来的收益全部归于个人缺乏正当性；其二，差别原则提供了一个可接受的检验标准——不平等若能使最不利者受益，就获得了证成；其三，原初状态的设定保证了对每个人的公平，因为无人能利用自己的偶然优势讨价还价。\n\n诺齐克一方的论据：其一，若持有物的历史链条正当（获取正当、转让自愿），结果无论多不平等都正义，模式化原则必然要求不断干预自由交换；其二，张伯伦论证表明，即使从正义的初始状态出发，自愿行为也会自发产生不平等，维持模式只能靠强制；其三，个人对自己的才能与劳动拥有所有权，税收再分配侵犯了这种权利。\n\n双方的批评者分别从各自立场发起攻击。Wacks 记载，罗尔斯的理论被批评为意识形态上有偏（马克思主义者认为其预设了非平等主义的前提）、原初状态「必然产出罗尔斯所设定的结论」；德沃金则主张，罗尔斯理论深处其实是每个人平等关怀与尊重的权利，这项权利构成社会契约的前提，而非其产物。诺齐克方面，批评集中于：其「历史条件」的证成是否可能、最弱国家如何从无政府状态中自然产生、把所得税类比强迫劳动是否成立，以及为何只承认财产权与消极自由而排除福利权。\n\n争论没有胜负，但它确立了一个此后所有分配理论都必须面对的坐标：任何分配正义理论，都要交代自己如何处理「模式与历史」「平等与自由」「天赋的任意性与个人权利」这三组张力。", "case": "美国最高法院1978年判决的加州大学董事会诉巴基案（Regents of the University of California v. Bakke, 438 U.S. 265）是分配正义在教育资源分配领域的经典案例。艾伦·巴基（Allan Bakke）是一名白人申请者，两度申请加州大学戴维斯分校医学院被拒，而该校为少数族裔申请者保留了16个名额。他提起诉讼，主张这一政策违反宪法第十四修正案的平等保护条款与联邦民权法。\n\n加州最高法院判决该校政策违宪。美国最高法院于1978年作出判决，意见出现分歧：法院裁定刚性种族配额（rigid quota）违宪，但多数意见同时认为，种族可以作为大学录取中的一项「加分因素」予以考虑，以实现学生群体的多样性。巴克获准入学。\n\n本案把分配正义的抽象争论变成了具体的制度问题：教育机会这一「社会基本善」应当如何分配？为纠正历史歧视而进行的种族倾斜，是实现了更实质的公平，还是制造了对个体的新的不公？案件结果体现了一种折中——拒绝刚性配额，但允许有限度的种族考量。", "caseAnalysis": "就巴基案而言，事实层面是：医学院为少数族裔保留固定名额，白人申请者因该政策被拒；争议焦点是：为矫正历史不公而实行的种族优惠，是否违反平等保护原则。\n\n从罗尔斯的视角看，教育资源是社会基本善，其分配应向最不利者倾斜；若少数族裔在历史与结构上处于不利地位，倾斜政策可以被差别原则证成，因为它最终有利于改善最不利群体的处境。从诺齐克的视角看，按种族分配名额是一种模式化分配，它侵犯了个体（如巴克）基于自身成绩获得资格的资格，且必须依靠国家的强制分类与干预来维持。\n\n最高法院的裁判理由体现了对两种价值的平衡：刚性配额对个体的伤害过于直接，被判定违宪；但完全无视种族因素，又可能固化历史不公，因此允许把种族作为多样性考量中的一个因素。\n\n理论意义上，本案说明分配正义直接塑造教育、就业与社会流动的制度设计，纯粹的书斋问题之说并不成立。它也提示罗尔斯与诺齐克框架的现实边界：现实制度往往在「照顾不利者」与「尊重个体资格」之间寻找具体折中，而非彻底采纳某一种理论。此后美国最高法院在2003年的格鲁特案与2013年的费舍尔案中继续面对同类问题，说明这一张力长期存在。", "summary": "分配正义追问社会利益与负担应当依何原则分配。亚里士多德提出「按功绩成比例分配」，把问题交给立法者。现代讨论中，罗尔斯以原初状态与无知之幕推导出平等自由原则与差别原则，主张不平等仅在有利于最不利者时才可接受；诺齐克以资格理论反驳，主张只要获取与转让的历史正当，结果无论多不平等都正义，并反对一切模式化分配与再分配国家。两人的争论围绕模式与历史、平等与自由、天赋的任意性与个人权利三组张力展开。巴基案表明，这些抽象原则在教育资源分配等现实制度中，往往需要在照顾不利者与尊重个体资格之间寻找具体平衡。", "furtherThinking": "1. 如果一个人的高收入完全来自一种「道德上任意」的天赋（如天生的音乐才能），罗尔斯会如何证成对其征税？诺齐克又会如何反驳？\n2. 张伯伦论证是否真的推翻了所有模式化分配？请设想一种情形，说明即使存在自愿交易，初始模式仍可能被破坏，并讨论这是否构成对诺齐克的支持。\n3. 巴基案中「种族作为加分因素」的折中，是否同时满足了罗尔斯与诺齐克各自的核心关切？为什么两派都可能对这一结果不满意？"}, "en": "Distributive Justice", "level": "core", "tags": "分配正义, 罗尔斯, 诺齐克, 差别原则, 资格理论", "source": "Wacks, Understanding Jurisprudence, ch.9；Siems, Comparative Law, ch.10", "id": "S1M4K3"}, "S1M4K4": {"title": "矫正正义", "EN": "Corrective Justice", "LEVEL": "core", "TAGS": "矫正正义, 交换正义, 侵权法, 报应, 补偿", "TERMS": "矫正正义（Corrective Justice）::通过矫正错误、恢复被扰乱的平等来处理侵害与损害的正义；交换正义（Commutative Justice）::矫正正义的别称，强调对等交换与返还；算术的平等（Arithmetical Equality）::不问身份高低、对当事人一律平等对待的平等观；报应正义（Retributive Justice）::主张刑罚正当性在于罪责与应报的正义理论；补偿正义（Compensatory Justice）::主张以赔偿使受害者恢复原状的正义理论；过错责任（Fault Liability）::以过错作为承担责任基础的归责原则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.9；Siems, Comparative Law, ch.7, ch.10", "terms": [{"term": "矫正正义（Corrective Justice）", "def": "通过矫正错误、恢复被扰乱的平等来处理侵害与损害的正义"}, {"term": "交换正义（Commutative Justice）", "def": "矫正正义的别称，强调对等交换与返还"}, {"term": "算术的平等（Arithmetical Equality）", "def": "不问身份高低、对当事人一律平等对待的平等观"}, {"term": "报应正义（Retributive Justice）", "def": "主张刑罚正当性在于罪责与应报的正义理论"}, {"term": "补偿正义（Compensatory Justice）", "def": "主张以赔偿使受害者恢复原状的正义理论"}, {"term": "过错责任（Fault Liability）", "def": "以过错作为承担责任基础的归责原则"}], "sections": {"coreQuestion": "某人过失撞坏了你的车，法院判他赔偿——为什么？小偷被判返还赃物并接受惩罚——为什么？这两件事与「国家如何分配财富」显然不是同一类问题。它们关乎当一个人错误地损害了另一个人时，应当如何「把事情扳回正轨」；社会利益如何在人群中配置属于另一个问题。这类问题归属于矫正正义（Corrective Justice）。它与分配正义共同构成亚里士多德正义二分法的两翼，却遵循完全不同的逻辑：一个按几何比例分配，一个按算术平等矫正。本节要回答：矫正正义的核心结构是什么？它与分配正义、报应、补偿之间是何种关系？它在现代侵权法与刑法中如何体现？", "definition": "矫正正义（Corrective Justice），在亚里士多德的传统中也称交换正义（Commutative Justice），关注的是当一个人对另一个人造成错误损害时，如何通过矫正恢复被破坏的平等状态。Wacks 的概括十分明确：矫正（或交换）正义「是法院的正义，适用于对犯罪或民事过错的救济」，它「要求所有人一律被平等对待」。\n\n矫正正义的核心结构是「错误的矫正」。它预设了一种初始的平等状态，侵害行为打破了这种状态，使一方获得不正当利益、另一方遭受不正当损失；正义的任务在于消除这种不当的得与失，使双方回到应有的位置。这就像天平：原本平衡，一方被人为压低，矫正就是移走那份额外的重量，让天平恢复水平。\n\n在平等的形式上，矫正正义对应亚里士多德所说的「算术的平等」（Arithmetical Equality）——它不考虑当事人的身份、地位或功绩，只问损害与补偿是否对等。这与分配正义所依据的「几何的平等」（按各人价值成比例分配）形成鲜明对照：一个是「一律平等」，一个是「按比例的平等」。\n\n现代法学中，矫正正义主要体现于侵权法（Tort Law）与合同法（Contract Law）的责任承担，以及刑法中的报应与惩罚问题。它又可细分为补偿正义（Compensatory Justice，着眼于使受害者恢复原状）与报应正义（Retributive Justice，着眼于使犯罪者承受与其罪责相称的惩罚）。", "history": "矫正正义的思想源头在亚里士多德的《尼各马可伦理学》第五卷。Wacks 指出，亚里士多德对正义的分析「至今仍构成大多数正义讨论的起点」，而其矫正与分配的区分，正是这一分析的核心遗产。亚里士多德把矫正正义与「自愿的和不自愿的交往」联系起来：在自愿交往（如契约）中，矫正正义处理公平交易被破坏的情形；在不自愿交往（如侵害）中，它处理损害与补偿。\n\n罗马法继承并发展了这一思路，把「给予每个人应得之物」的原则落实到私法责任之中，强调返还与赔偿的对等性。近代自然法传统把矫正正义与个人的天赋权利联系起来：侵害他人权利之所以应被矫正，是因为权利本身具有不可侵犯性。\n\n进入现代，矫正正义在两大法系中以不同方式展开。在英美法系，侵权法以过错责任为核心，强调通过判例逐步界定注意义务与损害赔偿责任；Wacks 关于比较法的讨论提示，普通法与民法法系在法官角色与程序风格上存在差异，但都把矫正侵害作为私法的基本功能之一。在大陆法系，侵权责任被系统地编入民法典，矫正正义与权利保护、损害赔偿体系相结合。\n\n二十世纪下半叶，矫正正义遭遇来自两个方向的挑战：一是经济分析法学派把侵权法理解为「事故成本的最小化」工具，二是分配正义理论主张侵权法应服务于社会风险的公平分散。这些争论使矫正正义的内在逻辑被重新审视。", "principle": "矫正正义的逻辑可以从四个层次展开。\n\n第一，初始平等与破坏。矫正正义预设当事人之间原本处于一种平等或平衡的状态——你享有财产不受侵害的利益，我负有不得侵害的义务。侵害行为打破了这种平衡：侵害者获得了不当利益（如省下了本应支付的赔偿），受害者承受了不当损失。\n\n第二，矫正的方向是「返还」与「恢复」。矫正的目标是消除不当的得失差额；惩罚性的额外剥夺属于报应正义的任务。这解释了为什么侵权赔偿通常以「恢复原状」或「等价赔偿」为原则：赔偿额应当与损害相当，而不是越多越好。 打个比方，矫正正义像一位修理匠，目的是把损坏的东西修好，而不是借机牟利。\n\n第三，归责以过错为纽带。为什么应由特定的侵害者承担矫正义务？因为损害可归责于他的过错行为——他本可避免却未避免。这就是过错责任（Fault Liability）的核心。Wacks 在讨论相关问题时指出，侵权法与刑法都以「过错」作为归责的重要基础。无过错责任的兴起虽然对这一纽带构成挑战，但其正当性往往仍需借助风险与公平的观念来说明。\n\n第四，与分配正义的逻辑对比。分配正义问「社会基本善应当如何依功绩或需要分配」，其标准是比例性的、面向未来的制度设计；矫正正义问「已经发生的错误应当如何被纠正」，其标准是对等性的、面向过去的纠纷解决。Wacks 以亚里士多德的说法区分了二者：前者是立法者关心的事，后者是法院关心的事。", "viewpoints": "亚里士多德确立了矫正正义的基本框架：它处理人们之间自愿与不自愿交往中的不平等，按算术平等原则恢复平衡，是法院而非立法者的事务。\n\n现代补偿理论把矫正正义理解为「使受害者恢复原状」。在这种观点下，赔偿的正当性来自于损害的填补：侵害者应当把受害者恢复到侵害未发生时的状态，这既是对受害者权利的尊重，也是对被破坏的平等秩序的恢复。\n\n报应理论则强调矫正正义中的惩罚维度。Wacks 在相关讨论中提到，诺齐克曾把报应性惩罚描述为「一种交流行为」（an act of communicative behavior），并主张惩罚的适当性应与行为的严重性相称；这一观点后来由简·汉普顿（Jean Hampton）加以发展。Wacks 记载，这类理论把惩罚理解为对错误行为的回应与沟通，而非单纯的威慑工具。\n\n经济分析的挑战者则提出，侵权法的目标不应是抽象的「矫正」，而应是降低事故的总成本——通过配置责任来激励潜在加害人采取成本有效的预防措施。这种观点把矫正正义的工具化，遭到坚持权利本位者的反驳：若赔偿只是成本工具，受害者的权利就被牺牲了。", "comparison": "矫正正义与几组相邻概念的关系值得厘清。\n\n矫正正义与分配正义：前者是法院的正义、算术的平等、面向过去、处理错误；后者是立法者的正义、几何的平等、面向制度、处理份额。二者不可混用——把分配问题当作矫正问题，会导致用「谁应得」的思路处理「谁受损」；反之则会把社会制度问题错误地还原为个案纠纷。\n\n矫正正义与补偿正义：补偿正义可视为矫正正义在私法中的具体形态，强调赔偿与损害的相当性。二者在方向上一致，都着眼于把被破坏的状态恢复。\n\n矫正正义与报应正义：前者着眼于恢复平等，后者着眼于罪责应报。二者在刑法中交织：刑罚既要补偿受害者（如附带民事赔偿），也要表达对犯罪的谴责。Wacks 记载，诺齐克与汉普顿的交流理论为报应提供了超越单纯报复的哲学说明。\n\n矫正正义与法律公平：矫正正义要求对当事人一律平等对待，体现了形式正义的要求；但形式上的对等（如同一赔偿标准）未必带来实质公平，这与实体／程序正义的张力相通。", "debates": "矫正正义领域最持久的争论，是侵权法的目的究竟是什么——是矫正错误，还是分散损失？\n\n矫正正义一方的论据：其一，侵权法的核心是对错误的回应，赔偿的正当性来自侵害者应当为自己的过错负责；其二，把赔偿理解为「恢复受害者的权利」，尊重了人的自主与尊严；其三，若把侵权法变为纯粹的损失分散工具，受害者就被降格为社会政策的客体。\n\n分配／工具主义一方的论据：其一，现代事故（如交通事故、产品责任）往往是社会实践的副产品，要求单个加害人全额赔偿既不公平也可能使其破产；其二，通过保险与责任社会化，可以把损失分散给全社会，使受害者获得更可靠的救济；其三，侵权法应当追求事故成本的最小化，而不是拘泥于「谁对谁错」的形式。\n\n争论的焦点可以概括为：侵权法应当「向后看」还是「向前看」？矫正正义向后看，关注已经发生的错误与恢复；工具主义向前看，关注未来的风险预防与成本配置。Wacks 在讨论相关问题时指出，法律现实主义者倾向于把判决理解为政策选择，这为工具主义提供了支持；而坚持权利本位的学者则担忧由此消解对错的道德意义。\n\n这场争论在现实制度中表现为过错责任与无过错责任的并存：前者体现矫正正义的逻辑，后者更多体现风险分散的考量。两大法系在具体制度上各有侧重，但都未彻底放弃其中一端。Wacks 的比较法讨论提醒我们，不能把某一法系的特定规则当作普适的「矫正正义」本身。", "case": "英国上议院1932年判决的唐纳休诉史蒂文森案（Donoghue v. Stevenson, [1932] AC 562）是矫正正义在侵权法中的里程碑案例。梅·唐纳休（May Donoghue）在苏格兰一家咖啡馆购买了一瓶姜汁啤酒，朋友替她买并递给她。她喝下后发现瓶中有一只腐烂的蜗牛，随即因惊吓与不适就医，声称因此患上胃炎。\n\n当时英国法要求原告与被告之间存在合同关系才能就产品缺陷索赔（「合同相对性」原则），而唐纳休本人并未直接购买该瓶饮料——是朋友买的。因此她缺乏合同上的请求权基础。\n\n上议院最终以多数意见判决她胜诉。大法官阿特金（Lord Atkin）提出了著名的「邻人原则」（neighbor principle）：人们必须对那些与自己如此接近、以致在作为或不作为时应合理考虑到会受影响的人负注意义务。 制造商对最终消费者负有注意义务，不能因合同链条的断裂而逃避责任。\n\n本案确立了现代过失侵权法的基础，把矫正义务从合同关系中解放出来，直接以「合理注意」与「可预见的损害」为根据。它使矫正正义得以覆盖那些没有合同关系却实际遭受损害的情形。", "caseAnalysis": "就唐纳休案而言，事实层面是：原告饮用含蜗牛的姜汁啤酒后患病，但与制造商之间不存在直接合同关系；争议焦点是：制造商对非合同当事人的消费者是否负有注意义务。\n\n法律依据方面，法院突破了合同相对性的限制，确立了以「邻人原则」为核心的注意义务理论。裁判理由在于：制造商能够预见其产品若存在缺陷会危害消费者健康，因此应合理采取预防措施；消费者无从自行检验密封瓶内的产品，只能依赖制造商的注意。\n\n从矫正正义角度，本案的核心在于：被告的过失（未确保产品卫生）造成了原告的损害，矫正的任务是使这一不当损害得到填补。阿特金勋爵的邻人原则为「谁应向谁承担矫正义务」提供了一般性的判断标准——以可预见性与接近性取代了偶然的合同关系。\n\n从理论意义看，本案说明矫正正义的具体规则需要不断演化，才能覆盖新的损害形态。它也提示我们，矫正正义与分配考量并非截然分离：把责任延伸到制造商，既是对错误的矫正，也包含「由最能控制风险者承担责任」的政策判断。两大法系后来在产品质量责任上的发展，都可以在这一张力中得到理解。", "summary": "矫正正义是「法院的正义」，其任务是通过矫正错误恢复被破坏的平等，遵循算术平等的逻辑，与分配正义的几何比例、立法者视角形成对照。它的核心结构包括初始平等、不当得失、恢复原状与过错归责。补偿正义着眼于使受害者恢复原状，报应正义着眼于罪责应报，二者都是矫正正义在现代法中的展开。围绕侵权法的目的，矫正正义理论与损失分散／经济分析理论形成了持久争论：前者向后看，关注错误的纠正；后者向前看，关注风险的预防与成本的配置。唐纳休案表明，矫正义务的具体范围需要随社会关系的变化而不断调整，其规则演化中始终交织着矫正与分配两种考量。", "furtherThinking": "1. 若一家工厂依法排放废气，附近居民因此患病，工厂并无「过错」。矫正正义还能否为赔偿提供根据？如果不能，需要诉诸什么理论？\n2. 无过错责任与「由最能控制风险者承担责任」的政策，是否在悄悄用分配正义的逻辑替换矫正正义？请讨论两者的边界。\n3. 诺齐克把报应惩罚理解为「交流行为」，这一说法如何回应「惩罚只是报复」的批评？它又能说明刑罚的哪些具体制度？"}, "en": "Corrective Justice", "level": "core", "tags": "矫正正义, 交换正义, 侵权法, 报应, 补偿", "source": "Wacks, Understanding Jurisprudence, ch.9；Siems, Comparative Law, ch.7, ch.10", "id": "S1M4K4"}, "S1M4K5": {"title": "平等原则", "EN": "The Principle of Equality", "LEVEL": "fundamental", "TAGS": "平等, 平等保护, 形式平等, 实质平等", "TERMS": "平等原则（Principle of Equality）::要求相同情况相同对待、禁止任意差别对待的基本法律原则；形式平等（Formal Equality）::要求规则一致适用、不因身份而区别对待的平等观；实质平等（Substantive Equality）::要求考虑实际处境差异、通过差别对待实现真正公平的平等观；平等保护（Equal Protection）::美国宪法第十四修正案要求各州对任何人提供平等法律保护的原则；政治完整性（Political Integrity）::德沃金提出的政府须依普遍适用于所有人的原则治理的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4, ch.9；Siems, Comparative Law, ch.10", "terms": [{"term": "平等原则（Principle of Equality）", "def": "要求相同情况相同对待、禁止任意差别对待的基本法律原则"}, {"term": "形式平等（Formal Equality）", "def": "要求规则一致适用、不因身份而区别对待的平等观"}, {"term": "实质平等（Substantive Equality）", "def": "要求考虑实际处境差异、通过差别对待实现真正公平的平等观"}, {"term": "平等保护（Equal Protection）", "def": "美国宪法第十四修正案要求各州对任何人提供平等法律保护的原则"}, {"term": "政治完整性（Political Integrity）", "def": "德沃金提出的政府须依普遍适用于所有人的原则治理的价值"}], "sections": {"coreQuestion": "「人人生而平等」是现代政治最熟悉的一句话，但它的法律含义并不自明。人当然在身高、才能、财富上千差万别，法律说「平等」，究竟是在说什么？是要求法律对所有人一视同仁，还是要求法律积极拉平实际差距？如果给残疾人提供无障碍设施、给贫困学生提供助学金，这是平等还是对他人的「不平等」？本节要厘清平等原则的基本含义、它与其他正义概念的关系，以及形式平等与实质平等这一核心分歧。", "definition": "平等原则（Principle of Equality）是要求社会成员在法律上受到相同对待、禁止基于任意理由的差别对待的基本原则。它的最简表达，正是哈特所说的「相同案件相同处理」（treat like cases alike）——这一点在正义概念中已经被确认为形式正义的核心。\n\n平等原则包含两个层面。其一，形式平等（Formal Equality）：法律规则应当普遍适用，不因身份、种族、性别、财富而有差别；同样的案件应得到同样的处理。其二，实质平等（Substantive Equality）：考虑到人们在实际处境上的差异，单纯的同等对待可能固化不公，因此需要通过对不利者的差别性支持来达致真正的公平。\n\n在美国宪法中，平等原则集中体现于第十四修正案的平等保护条款（Equal Protection Clause），要求各州「对在其管辖范围内的任何人提供平等的法律保护」。Wacks 在讨论德沃金时指出，德沃金所说的「合法性」服务于政治完整性（Political Integrity）——即法律面前人人平等，不仅是法律被照字面执行，更在于政府必须依一套原则上适用于所有人的原则来治理；任意的强制或惩罚，即便偶尔提高效率，也违反了政治平等这一核心维度。", "history": "平等观念的现代形态，与近代反封建、反特权的政治斗争紧密相连。法国大革命把「平等」写入《人权宣言》，美国《独立宣言》宣告「人人生而平等」，两者的矛头都指向基于出身与身份的等级特权。近代法律的兴起，本身就把「取消身份特权、确立普遍适用规则」作为一项核心成就。\n\n在英美法中，平等原则通过宪法判例逐步展开。美国1868年通过的第十四修正案，最初旨在保护刚获得解放的黑人奴隶，后来成为反对种族隔离、性别歧视等一系列平等斗争的宪法武器。Wacks 指出，哈特曾言，如今「人生而有权被同等对待」这一原则已被广泛接受，以至于种族歧视者往往不得不辩称被歧视者「不是完全的人」，以掩盖其对平等原则的背离。\n\n二十世纪以来，平等原则的重心逐渐从形式平等转向实质平等：人们意识到，取消法律上的歧视只是第一步，历史形成的结构性不利不会因为形式上的中立而自动消失。这一转变在比较法层面也有体现——Wacks 关于比较法的讨论提示，不同法系在司法角色与程序风格上的差异，会影响平等原则的具体落实方式。", "principle": "平等原则的内在逻辑可以从三层展开。\n\n第一，平等需要一个「比较项」。说 A 与 B 应被平等对待，必须说明在哪个方面平等——是投票权、受教育权，还是税负？脱离具体领域谈平等，只会得到空洞的口号。这也是为什么平等原则总是与「平等保护某个具体权利」连用。\n\n第二，平等要求「相关理由」的统治。差别对待并非一律被禁止，只有基于不相关或任意理由（如种族、性别）的差别才被禁止。如果差别对待有正当理由（如按成绩录取、按收入累进征税），它可以是平等的而非歧视。平等原则的真正敌人是「任意性」，而非一切区别。\n\n第三，形式平等与实质平等的张力。形式平等说：同样的情况同样对待。实质平等反驳：看似同样的情况，实际处境可能截然不同——让一个健全人和一个轮椅使用者「同样」走楼梯，形式平等反而制造了排斥。因此，实质平等要求考察差别对待的实际效果，允许甚至要求为消除结构性不利而采取倾斜措施。", "viewpoints": "哈特把「相同案件相同处理」视为正义的恒定成分，这为形式平等提供了经典表述。在他看来，这一原则的广泛接受程度如此之高，以至于公开的歧视都必须伪装成「被歧视者不同」的说辞。\n\n德沃金把平等提升到法律理论的核心。Wacks 指出，对德沃金而言，法律与道德并非分离，法律的概念本身包含道德判断；他所谓的政治完整性，要求政府依一套适用于所有人的原则治理。Wacks 还记载，德沃金批评罗尔斯，认为罗尔斯「深层理论」的核心是每个人获得平等关怀与尊重的权利，这项权利反而构成契约得以展开的前提，社会契约的产物之说站不住。\n\n罗尔斯则以差别原则处理平等：不平等只有在对最不利者有利时才可接受，这实际上把形式平等推进到实质平等的方向。", "comparison": "平等原则与相关概念的关系需要辨析。\n\n平等与正义：平等是正义的重要组成部分，但不是全部。正义还包括应得、功绩、对错误的矫正等维度。一项安排可能平等却不正义（如平均分配给最不需要的人），也可能正义却不平等（如按功绩差别奖励）。\n\n形式平等与实质平等：前者追求规则一致与无歧视，标准清晰、可操作；后者追求实际公平，但「何为公平」容易众说纷纭。二者并非简单对立——多数现代法律制度同时包含两者：形式上禁止歧视，实际上允许为矫正不利而倾斜。\n\n平等与自由：二者可能冲突。要求结果平等往往需要限制某些人的自由（如通过税收再分配），而放任自由又可能产生巨大的事实不平等。罗尔斯试图通过差别原则协调二者，诺齐克则认为二者不可调和。", "debates": "平等原则的核心争论，是形式平等与实质平等何者优先。\n\n形式平等一方的论据：其一，形式标准清晰、可预测，便于操作与审查；其二，按身份或群体进行差别对待，本身就有滑向歧视与偏私的风险；其三，法律应当「无视差异」，这正是法治尊严之所在。\n\n实质平等一方的论据：其一，形式中立可能掩盖并固化历史形成的结构性不利；其二，看似相同的对待可能对处境不利者造成更重的负担；其三，真正的平等要求关注结果与实际效果，而非仅仅宣布「机会均等」。\n\n这一争论在美国平等保护的宪法实践中表现为：法院在审查歧视性分类时，需要判断是否存在「正当理由」，以及对历史不利是否应采取补偿性措施。Wacks 记录的德沃金对罗尔斯的批评，则提供了另一重视角——平等属于法律论证的前提性权利，契约产物的说法难以自圆，这使平等原则具有超越具体政策的底盘地位。", "case": "美国最高法院1954年判决的布朗诉教育委员会案（Brown v. Board of Education, 347 U.S. 483）是平等原则的里程碑案例。此前，1896年的普莱西诉弗格森案确立了「隔离但平等」（separate but equal）原则，允许种族隔离的公共教育设施存在。布朗案中，多名黑人儿童及其家长提起诉讼，主张堪萨斯州等地公立学校实行种族隔离，违反第十四修正案的平等保护条款。\n\n最高法院于1954年作出一致判决，宣告公共教育中的种族隔离本身就构成对平等保护的违反，推翻了「隔离但平等」在公立教育领域的适用。法院指出，把黑人儿童仅因种族而与其他年龄、资格相似的孩子隔离开来，会在他们心中造成低人一等的感觉，从而可能对他们的心灵与思想造成无法弥补的伤害。\n\n本案的意义在于：法院没有停留在「设施是否同等」的形式比较上，而是直面隔离制度本身对平等尊严的损害，体现了从形式平等向实质平等的推进。", "caseAnalysis": "就布朗案而言，事实层面是：公立学校按种族分校；争议焦点是：隔离但平等是否违反第十四修正案的平等保护条款。\n\n法律依据是宪法第十四修正案。裁判理由在于：隔离本身即是一种伤害，它给被隔离群体打上了「低人一等」的标签，因此即使物质设施相当，隔离制度仍构成不平等。\n\n从形式平等角度看，「隔离但平等」声称对两个种族提供了同等的设施，似乎符合「同样对待」；但从实质平等角度看，隔离制度本身就是基于种族的差别对待，且其社会效果是固化种族等级。布朗法院采纳了后者。\n\n理论意义上，本案说明平等原则的判断不能停留在字面或设施层面，必须考察制度的实际效果与社会意义。它也印证了 Wacks 引述哈特的判断：公开的种族歧视必须寻找伪装，而当「隔离」这种伪装被揭穿后，平等原则的锋芒就显现出来。布朗案此后成为各国反歧视法与平等权发展的重要参照。", "summary": "平等原则要求相同案件相同对待、禁止任意差别对待，其最简表达是哈特的「相同案件相同处理」。它包含形式平等与实质平等两个层面：前者追求规则一致与无歧视，后者关注实际处境差异与结构性不利。德沃金把平等提升为法律理论的核心，主张政府须依普遍适用的原则治理；罗尔斯以差别原则推动实质平等。形式与实质之争的焦点在于：形式中立是否足以实现真正公平。布朗案表明，法院可以超越「隔离但平等」的形式比较，直面隔离对平等尊严的实质损害——这正是平等原则从抽象命题走向现实制度的关键一步。", "furtherThinking": "1. 若一所大学为保证少数群体入学而设定倾斜政策，这违反形式平等吗？它是否可能促进实质平等？请分别给出论据。\n2. 哈特说种族歧视者往往辩称被歧视者「不是完全的人」。这一观察揭示了歧视怎样的论证结构？\n3. 德沃金认为平等关怀与尊重的权利是契约的前提而非产物。如果成立，这对法律与道德的关系意味着什么？"}, "en": "The Principle of Equality", "level": "fundamental", "tags": "平等, 平等保护, 形式平等, 实质平等", "source": "Wacks, Understanding Jurisprudence, ch.4, ch.9；Siems, Comparative Law, ch.10", "id": "S1M4K5"}, "S1M4K6": {"title": "法律公平与社会公平", "EN": "Legal Fairness and Social Fairness", "LEVEL": "fundamental", "TAGS": "法律公平, 社会公平, 形式正义, 法的局限", "TERMS": "法律公平（Legal Fairness）::法律制度在规则制定与适用中所体现的公平，包括程序中立与平等适用；社会公平（Social Fairness）::社会在利益、机会与负担分配上达到的实质公平状态；法律实证主义（Legal Positivism）::主张法律与道德在概念上可以分离的理论；形式正义（Formal Justice）::规则被一致、公开适用的正义；实质正义（Substantive Justice）::结果与内容本身公正的正义；政治完整性（Political Integrity）::德沃金提出的政府须依普遍适用于所有人的原则治理的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.4, ch.9；Siems, Comparative Law, ch.10", "terms": [{"term": "法律公平（Legal Fairness）", "def": "法律制度在规则制定与适用中所体现的公平，包括程序中立与平等适用"}, {"term": "社会公平（Social Fairness）", "def": "社会在利益、机会与负担分配上达到的实质公平状态"}, {"term": "法律实证主义（Legal Positivism）", "def": "主张法律与道德在概念上可以分离的理论"}, {"term": "形式正义（Formal Justice）", "def": "规则被一致、公开适用的正义"}, {"term": "实质正义（Substantive Justice）", "def": "结果与内容本身公正的正义"}, {"term": "政治完整性（Political Integrity）", "def": "德沃金提出的政府须依普遍适用于所有人的原则治理的价值"}], "sections": {"coreQuestion": "法律公平等于社会公平吗？一座城市规定「所有人不得在公园露宿」，规则对谁都一样，程序也很公正；但无家可归者因此失去栖身之处，有人会说这「合法却不公平」。反过来，一项旨在缩小贫富差距的再分配政策，可能实现了社会公平，却被批评「违反了法律的确定性」。这类现象提示我们，「公平」在法律之内和法律之外可能有不同的含义。本节要区分法律公平与社会公平，分析二者为何既有联系又会冲突，并借助现实案例说明法律在促进社会公平上的能力与限度。", "definition": "法律公平（Legal Fairness）指法律制度在规则制定与适用过程中所体现的公平。它主要包括：规则的一般性与公开性、适用的一致性、程序的中立性、裁判者的无偏私、当事人获得听证的机会。Wacks 在讨论哈特的正义观时指出，哈特的「相同案件相同处理」是一种基本上是程序性的标准，这正是法律公平的核心表达。富勒的「内在道德」所列举的一般性、公开性、不溯及既往、明确性等要求，也都是法律公平的具体内容。\n\n社会公平（Social Fairness）指社会在利益、机会与负担的分配上达到的实质公平状态。它关心的是分配结果是否合理：贫富差距是否过大、机会是否真正均等、历史形成的不利是否得到矫正；规则是否被一致适用属于另一层追问。社会公平的问题，与分配正义高度重叠——罗尔斯的差别原则、诺齐克的资格理论，都是关于社会公平的不同答案。\n\n二者的关系可以概括为：法律公平是法律体系「内部的德性」，社会公平是整个社会「外部的结果」。法律公平关注「法律如何运作」，社会公平关注「社会变成什么样」。", "history": "近代法律的兴起，本身就把法律公平作为一项核心成就：取消身份特权，确立普遍适用的规则，使权力受到公开、稳定规则的约束。法律实证主义进一步把「法律是什么」与「法律应当是什么」区分开来，使法律的识别不依赖于道德判断。Wacks 指出，实证主义的分离命题主张「是不是法律」与「是不是道德上正当」是两个应分开判断的问题，法律不需要道德的主张则是误解。这一区分，为法律公平与社会公平的分离提供了理论基础：一套法律可以在程序上完全合格，同时在结果上极不公平。\n\n二十世纪，福利国家的兴起和权利运动的发展，使社会公平成为法律制度必须回应的诉求。平等保护、反歧视、社会保障等制度的建立，体现了法律试图缩小与社会公平之间距离的努力。比较法研究也显示，不同国家在「法律对社会公平的介入程度」上差异显著——Wacks 引用的比较法材料提示，法系差异会影响制度设计的具体形态，因此不能把某一法系的做法当作普适标准。", "principle": "理解法律公平与社会公平的关系，可以从三层展开。\n\n第一，二者的评价标准不同。法律公平评价的是过程与形式：规则是否公开、是否一致适用、当事人是否被听取。社会公平评价的是结果与结构：谁得到了什么、机会是否真的开放、不利是否得到矫正。一个公正的拍卖程序可能产生极不平等的结果；一个极度平等的结果可能来自任意的分配过程。\n\n第二，二者可能相互促进，也可能相互冲突。相互促进的情形：正当程序有助于减少错判，从而改善结果（吉迪恩案即为例证）。相互冲突的情形：严格保护财产权与契约自由，可能维护了法律公平，却固化了巨大的社会不平等；而为追求社会公平而实行的再分配，往往需要频繁调整规则、赋予行政机关较大裁量空间，从而削弱法律的确定性与可预测性。\n\n第三，法律对社会公平的作用有其限度。法律可以改变制度规则，却难以直接改变资源占有与社会结构；法律可以通过反歧视促进机会开放，却无法保证每个人都能利用机会。这提醒我们，把社会公平的全部期待寄托于法律，会让法律承担它无法完成的任务，最终反而损害法律公平。", "viewpoints": "哈特的形式正义标准为法律公平提供了经典表述：一致适用、无偏私、相同案件相同处理。Wacks 指出，这一标准获得广泛接受，但也承认其局限——面对不义法律，一致适用可能造成不义。\n\n富勒从程序角度强化了法律公平：法律的内在道德要求规则一般性、公开、明确、不溯及既往。Wacks 强调，富勒的立场是程序性自然法，他关心法律在程序上是否健全，而非直接判定每条法律的内容是否正义；但 Wacks 也提醒，遵守内在道德并不保证法律一定正义。\n\n德沃金试图把社会公平的维度引入对法律的理解。Wacks 指出，德沃金的「合法性」服务于政治完整性——政府须依普遍适用于所有人的原则治理，任意强制违反政治平等。这实际上把实体性的平等价值注入了法律公平的概念，使二者不再是截然分离的两极。\n\n批判法律研究（Critical Legal Studies）等思潮则提出更激进的质疑：形式上的法律公平可能掩盖并再生产社会的不平等，所谓「法律面前人人平等」可能只是让既有的权力结构获得合法外衣。Wacks 在讨论法治的批判时提及这类观点，可作为理解「法律公平是否足以带来社会公平」的重要参照。", "comparison": "法律公平与社会公平的关系，可以对照几种典型立场。\n\n法律实证主义倾向于强调二者的区分：法律的效力来自来源而非道德，因此法律公平可以独立于社会公平而被评价。其优点是标准清晰，缺点是可能对严重不公的社会后果无动于衷。\n\n自然法与德沃金式理论倾向于强调二者的联系：法律应当服务于正义与政治平等，因此法律公平不能与社会公平彻底脱钩。其优点是能回应不公，缺点是标准可能多元而难以稳定。\n\n批判性立场则认为法律公平本身可能就是社会不公平的组成部分——形式上的中立把结构性的不平等当作「既成事实」接受下来，从而使其合法化。\n\n需要防止两种误解：其一，认为「只要法律公平，社会就必然公平」——这是把法律工具神化；其二，认为「法律公平与社会公平毫无关系」——这忽视了制度对资源分配的深刻影响。较稳妥的看法是：法律公平是社会公平的必要制度条件之一，但不是充分条件。", "debates": "围绕法律能否实现社会公平，存在两种对立主张。\n\n肯定一方认为：法律是塑造社会分配的有力工具。通过反歧视法、社会保障法、累进税制与教育机会的制度化保障，法律可以直接改变利益与机会的分配格局。德沃金的政治完整性理论说明，法律本身就包含平等价值的承诺，因此法律公平与社会公平在深层是贯通的。\n\n怀疑一方认为：法律的作用被高估了。其一，法律规则总是在既有权力与资源格局中制定，法律公平往往反映的是既得利益者的利益；其二，形式平等的适用可能掩盖实质不公，使不平等看起来「合法」；其三，法律的实施依赖资源，弱势群体即便享有权利也缺乏行使权利的能力。Wacks 记录的马克思主义与批判理论对法治的批评，大致沿这一方向展开——例如 E. P. 汤普森（E. P. Thompson）把法治理解为对权力的有效抑制，而批评者则质疑这种理解是否掩盖了法治的意识形态功能。\n\n争论的焦点可以概括为：法律公平是不是社会公平的充分条件？肯定方的答案是否定的但有条件地乐观——法律至少可以提供制度框架；怀疑方的答案同样否定，但更悲观——这个框架本身可能就是问题的一部分。两方都承认，法律公平不是社会公平的充分条件，分歧在于它对必要条件的表述与对制度潜力的评估。", "case": "美国最高法院2015年判决的奥贝格费尔诉霍奇斯案（Obergefell v. Hodges, 576 U.S. 644）是观察法律公平与社会公平关系的典型案例。案件涉及密歇根、肯塔基、俄亥俄和田纳西等州拒绝向同性伴侣颁发结婚证，或拒绝承认其他州颁发的同性婚姻证书。原告主张各州的做法违反第十四修正案的正当程序条款与平等保护条款。\n\n最高法院于2015年以5比4的多数意见判决各州必须为同性伴侣颁发结婚证书，并承认其他州合法的同性婚姻。判决把婚姻自由理解为个人自主与尊严的核心，并强调平等保护的要求。\n\n本案的戏剧性在于：在同性婚姻尚未被社会普遍接受的时期，法院通过宪法裁判改变了法律的规则体系，使此前在法律上处于不利地位的群体获得了平等的制度地位。这既展示了法律促进社会公平的能力，也引发了关于法院是否越界、是否应当等待民主进程的法律争论——反对意见正是从法律公平（民主程序与司法克制）的角度提出质疑。", "caseAnalysis": "就奥贝格费尔案而言，事实层面是：多个州拒绝向同性伴侣提供婚姻登记与承认；争议焦点是：这种拒绝是否违反宪法上的正当程序与平等保护。\n\n裁判理由的核心在于：婚姻涉及个人自主、尊严与平等，各州不得在无充分理由的情况下剥夺一部分人获得这一制度保障的资格。法院把自由与平等两条线索结合起来，使判决既有实体价值导向，又依托宪法条款的正式法律形式。\n\n从法律公平角度，本案的反对意见强调：婚姻制度的变革应通过民主立法完成，法院以宪法名义强行统一规则，损害了联邦制下各州的自主与法律的可预测性。这一质疑提示了法律公平对「由谁、以何种程序改变规则」的关注。\n\n从社会公平角度，多数意见关注同性伴侣在制度上的不利地位及其尊严损害，体现了实质平等的诉求。案件说明，法律公平与社会公平的推进有时需要以法律公平的内部程序（宪法裁判）为途径，但也可能因改变规则的方式而引发新的公平争议。\n\n理论意义上，本案表明法律公平与社会公平并非简单的手段与目的关系：宪法裁判本身既是法律程序，又承载实体价值；对它的评价必须同时兼顾程序正当性与结果的正当性。这也呼应了 Wacks 对哈特与富勒争论的总结——任何法律理论都要交代自己如何处理效力与正当性的关系。", "summary": "法律公平是法律制度在规则制定与适用中的公平，体现为一般性、公开性、一致适用与程序中立；社会公平是社会在利益与机会分配上的实质公平状态。二者评价标准不同，可能相互促进（正当程序减少错判），也可能相互冲突（保护形式财产权固化不平等；追求社会公平削弱法律确定性）。哈特与富勒从程序角度强化法律公平，德沃金把政治完整性注入合法性概念，批判理论则质疑形式公平可能掩盖社会不公。奥贝格费尔案显示，法律可以通过宪法裁判推进社会公平，但改变规则的方式本身也会引发法律公平层面的争议。较稳妥的结论是：法律公平是社会公平的必要制度条件，但不是充分条件。", "furtherThinking": "1. 一项政策若显著改善了弱势群体的处境，却需要频繁修改规则并赋予行政机关较大裁量，你如何评价它对法律公平与社会公平的双重影响？\n2. 批判理论认为形式法律公平可能掩盖社会不平等。请举出一个具体制度例子，说明这种「掩盖」是如何发生的。\n3. 奥贝格费尔案中，法院推动社会公平的方式是否损害了法律公平？请分别列出多数意见与反对意见各自关注的价值。"}, "en": "Legal Fairness and Social Fairness", "level": "fundamental", "tags": "法律公平, 社会公平, 形式正义, 法的局限", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.4, ch.9；Siems, Comparative Law, ch.10", "id": "S1M4K6"}, "S1M5K1": {"title": "Rule of Law 的含义", "EN": "The Meaning of the Rule of Law", "LEVEL": "core", "TAGS": "法治, 规则之治, 戴雪, 形式法治, 实质法治", "TERMS": "法治（Rule of Law）::要求权力受法律约束、法律居于至高地位的政治法律理想；依法统治（Rule by Law）::把法律仅当作统治工具、法律本身不受约束的治理方式；法律至上（Supremacy of Law）::戴雪法治理论的第一层含义，即法律高于专断权力；形式法治（Formal Rule of Law）::强调规则的一般性、公开性、明确性与不溯及既往的法治观；实质法治（Substantive Rule of Law）::要求法律内容本身符合正义与人权保障的法治观；否定性德性（Negative Virtue）::拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立的道德价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "terms": [{"term": "法治（Rule of Law）", "def": "要求权力受法律约束、法律居于至高地位的政治法律理想"}, {"term": "依法统治（Rule by Law）", "def": "把法律仅当作统治工具、法律本身不受约束的治理方式"}, {"term": "法律至上（Supremacy of Law）", "def": "戴雪法治理论的第一层含义，即法律高于专断权力"}, {"term": "形式法治（Formal Rule of Law）", "def": "强调规则的一般性、公开性、明确性与不溯及既往的法治观"}, {"term": "实质法治（Substantive Rule of Law）", "def": "要求法律内容本身符合正义与人权保障的法治观"}, {"term": "否定性德性（Negative Virtue）", "def": "拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立的道德价值"}], "sections": {"coreQuestion": "「法治」是当代政治与法律话语中最常被引用的词之一，但它的含义远比口号复杂。当一个政府说「我们实行法治」时，它可能只是说「我们有法律、依法办事」，也可能是在承诺权力受到真正约束、公民基本权利得到保障。这两种承诺的分量截然不同。法治与「依法统治」（Rule by Law）有何区别？它是否只关乎程序形式，还是必须包含实质正义？拉兹（Joseph Raz）为什么说法治只是一种「否定性德性」？本节将梳理法治的核心含义、主要理论分歧，并借助判例说明法治原则如何实际约束权力。", "definition": "法治（Rule of Law）是一种政治法律理想，其核心要求是：法律在社会治理中居于至高地位，一切权力——尤其是国家权力——都必须在法律的框架内行使，任何人都不得凌驾于法律之上。\n\n这一概念在英语世界中有一个经典的表述框架，来自英国法学家戴雪（A. V. Dicey）。Wacks 在相关讨论中指出，戴雪的法治观包括三层含义：其一，法律的至上性（Supremacy of Law），即法律高于专断权力，不受任意意志的支配；其二，法律面前人人平等（Equality before the Law），即所有人同受法律约束；其三，宪法是权利保障的结果而非渊源——英国宪法是法院保护个人权利的结果，而非成文宪法授予权利。\n\nWacks 特别记录了拉兹（Joseph Raz）的一个关键判断：有人主张法律因其符合法治理想而具有道德性，但拉兹反驳说，虽然遵守法治能减少行政权力的滥用，却并不赋予法律独立的道德价值；对拉兹而言，法治是一种「否定性德性」（negative virtue），因为专断权力的风险恰恰是法律本身所制造的。Wacks 还指出，拉兹由此得出结论：即便在公正的法律体系中，也不存在服从法律的初步义务（prima facie duty）。\n\n法治与「依法统治」（Rule by Law）的区分至关重要：后者只要求统治者依据法律行事，法律本身可以是压迫性的、可以任意修改；前者则要求法律本身具备一般性、稳定性、公开性等品质，并真正约束权力。", "history": "法治观念的根源可以追溯到古代。亚里士多德在《政治学》中提出，法治优于人治，因为法律凝聚了多数人的智慧且不受欲望支配。英国1215年的《大宪章》（Magna Carta）开启了以法律约束王权的传统，1689年《权利法案》进一步确立了议会主权与法律至上的原则。\n\n戴雪在十九世纪撰写《英宪精义》（Introduction to the Study of the Law of the Constitution），系统总结了英国宪法中的法治传统，使「Rule of Law」成为宪法理论的核心概念。Wacks 指出，戴雪的三层含义至今仍是讨论法治的起点。\n\n二十世纪，法治经历了深刻的理论分化。富勒（Lon Fuller）在《法律的道德性》中提出法律的「内在道德」，从程序角度强化了法治的形式要求；拉兹则从法律实证主义立场把法治界定为一种形式性的、价值中立的理想；德沃金（Ronald Dworkin）把「合法性」（legality）理解为政治完整性，赋予法治更厚的道德内涵。二战后，宪法审查、人权保障与国际法治的发展，使实质法治的维度日益突出。\n\n比较法研究也显示，法治在不同社会有不同的制度形态。Siems 的《比较法》专门讨论了「发展与法治」问题，并列出「法治的可能功能与例证」，说明法治既是规范理想，也是发展政策中的核心议题。", "principle": "法治原则的内部逻辑可以从三层展开。\n\n第一，法治要求「法的统治」而非「人的统治」。这意味着权力行使必须有法律授权，且必须符合法律；法律必须具有一般性——它针对抽象的人与行为，而不是针对特定个人发布的专断命令。这是法治与专断权力的根本分界。\n\n第二，法治包含一系列形式性要求。富勒的「内在道德」对此作了系统概括：规则应当一般、公开、明确、不矛盾、不溯及既往、可以被遵守、稳定。Wacks 指出，富勒关注的是法律在程序上是否健全——这些要求使法律成为可被服从的对象，也使人们能够规划自己的行为。拉兹所强调的，也大致是这一层面的要求：法律应当清晰、稳定、公开，以减少专断。\n\n第三，法治是否当然带来正义，是理论分歧的焦点。形式法治（Formal Rule of Law）认为，法治只关乎法律的形式品质与权力约束机制，不保证内容正义——这正是拉兹「否定性德性」命题的含义。实质法治（Substantive Rule of Law）则认为，法治必须包含对基本权利与正义的保障，否则「法治」可能沦为压迫的精致工具。Wacks 记录的马克思主义者对法治的批评，正是从这里切入：汤普森（E. P. Thompson）把法治理解为对权力的有效抑制与对公民自由的保护，而批评者则质疑这种理解是否掩盖了法治的意识形态功能。", "viewpoints": "戴雪奠定了法治的经典框架：法律至上、法律面前人人平等、宪法作为权利保障的结果。他的关注重点是英国不成文宪法下普通法对个体自由的保护。\n\n富勒提出法律的内在道德，列举了使法律成为可能的八种程序性要求。Wacks 强调，富勒采取的是程序性自然法立场；但他也提醒，遵守这些要求并不保证法律一定正义——富勒的论证支持的往往只是偶然的联系。\n\n拉兹（Joseph Raz）在《法律的概念》相关讨论之外，进一步把法治定位为形式性的、价值中立的理想。Wacks 指出，拉兹反驳「法治证明法律道德性」的说法，主张法治仅能减少行政权力的滥用，是一种否定性德性。\n\n德沃金把合法性理解为政治完整性，主张政府须依一套原则上适用于所有人的原则治理，任意强制违反政治平等。这把实体性的平等价值注入了法治概念。", "comparison": "形式法治与实质法治的对照，是理解法治含义的主线。\n\n形式法治一方（拉兹、富勒在某种程度上）：法治的强项是标准清晰、可操作，能够有效约束专断权力，且不必在价值多元的社会中强行就「什么是正义」达成一致。其弱点是可能对严重不义的法律无能为力——一套程序完美但内容压迫的法律，依然可以通过形式法治的检验。\n\n实质法治一方（德沃金、自然法传统、部分宪法理论）：法治必须包含基本权利与正义的保障，否则就失去了它区别于「依法统治」的本质。其弱点是标准可能过于宽泛，使法治概念失去操作性，并被批评者指责为把特定政治立场伪装成法律原则。\n\n中间立场承认形式要求是法治的必要基础，同时主张在一定限度内纳入权利保障等实质要素。Wacks 的论述倾向于这种审慎态度：他既重视戴雪、富勒、拉兹所强调的形式维度，也不回避法治的批判性问题。\n\n还需区分法治与几个相邻概念：法治不同于「法制」（legal system，泛指法律制度本身）；法治也不同于「依法统治」（Rule by Law），后者不要求法律本身受约束；法治还与民主相关但不等同——民主强调谁作出决定，法治强调决定如何作出、权力如何被约束。Wacks 记录了「民主与法治」这一专题，说明二者之间存在张力而非简单的同一关系。", "debates": "法治领域最经典的争论，是法治的形式性与实质性之争。\n\n形式论者的论据：其一，法治的核心功能是提供确定性与可预测性，使人们能规划行为；其二，在价值多元的社会中，形式标准比实质标准更容易达成共识；其三，拉兹指出，把实质正义塞进法治概念，会混淆「法律应当是什么」与「法律是什么」两个问题。\n\n实质论者的论据：其一，形式法治无法区分良法与恶法，可能使法治成为暴政的遮羞布；其二，二战后人权宣言与宪法权利的实践表明，法治应当包含对基本权利的保障；其三，德沃金的政治完整性说明，法律实践本身就包含道德判断，法治不可能价值中立。\n\nWacks 记录的拉兹命题在此处值得重述：拉兹承认遵守法治能减少专断权力之害，但坚持这不赋予法律独立的道德价值；他甚至主张即使在公正的法律体系中，也没有服从法律的初步道德义务。这一立场把形式法治的逻辑推到极致，也激起了实质论者的强烈回应。\n\n争论的现实意义在于：当一个国家自称实行法治时，我们需要追问它承诺的是哪一层含义。Wacks 引用的比较法材料显示，法治作为「发展」议题在国际语境中被广泛使用，不同国家和机构对它的理解并不相同——这使法治成为一个既重要又需要谨慎使用的概念。", "case": "美国最高法院1803年判决的马伯里诉麦迪逊案（Marbury v. Madison, 5 U.S. (1 Cranch) 137）是法治原则的奠基性案例。案件源于联邦党人亚当斯总统卸任前的「午夜任命」：威廉·马伯里（William Marbury）被任命为治安法官，但任命状未及时送达。新任杰斐逊政府拒绝交付，马伯里依据《1789年司法法》向最高法院申请强制令。\n\n最高法院由首席大法官马歇尔（John Marshall）撰写意见。法院裁定：马伯里有权获得任命状，但《1789年司法法》中赋予最高法院直接签发强制令的条款违反了宪法第三条关于最高法院原始管辖权的规定，因此该条款无效。法院由此确立了联邦法院审查国会立法是否合宪的权力——即司法审查（Judicial Review）制度。\n\n本案的意义在于：它把「法律至上」具体化为「宪法至上」，使成文宪法成为约束政府权力的最高法律，并使法院成为维护这一约束的机构。这一制度安排正是戴雪所谓「法律至上性」在美国宪法秩序中的具体形态。", "caseAnalysis": "就马伯里案而言，事实层面是：总统任命的官员未获任命状，新政府拒绝交付；争议焦点是：最高法院是否有权依据《司法法》直接签发强制令，以及该法是否合宪。\n\n裁判理由的核心在于：宪法是最高法律，国会制定的法律若与宪法冲突则无效；判定法律合宪与否，是司法部门的职责。这一推理把法律至上从抽象原则变成了可操作的制度机制。\n\n从法治角度看，本案包含两层意义。其一，它确立了权力受法律约束的原则——即使是国会制定的法律，也必须在宪法划定的界限内；总统与行政机关同样不能凌驾于法律之上。其二，它通过司法审查为权利保障提供了制度渠道，使法治不只是纸面宣言。\n\n但本案也提示了法治的复杂性：司法审查意味着由法院而非民选机关决定法律是否合宪，这本身引发「反多数难题」的争论——法院在维护法治的同时，是否僭越了民主决策的领域？这正是 Wacks 所记载的「民主与法治」张力的具体体现。\n\n理论意义上，马伯里案说明法治需要具体的制度载体：没有独立的司法与违宪审查机制，法律至上原则就难以对权力形成真实约束。它也表明，法治的形式要求（规则的至上性与一致性）与实质价值（权利保障）在实践中往往通过同一套制度来推进。", "summary": "法治（Rule of Law）的核心要求是法律至上、权力受法律约束、人人同受法律保护。戴雪的三层含义——法律至上、法律面前人人平等、宪法作为权利保障的结果——奠定了经典框架；富勒的内在道德强化了其形式要求；拉兹把法治定位为减少专断权力之害的「否定性德性」，坚持其价值中立；德沃金则以政治完整性注入实体平等价值。形式法治与实质法治的分歧，焦点在于法治是否必须包含正义与权利保障。马伯里案通过确立司法审查，把法律至上具体化为宪法至上和可操作的制度机制，同时也暴露了法治与民主之间的张力。理解法治，必须同时把握其形式骨架与价值争议。", "furtherThinking": "1. 如果一套法律在形式上完全符合富勒的内在道德，却规定了对某一群体的系统性压迫，它是否仍算「法治」？形式论者与实质论者会如何回答？\n2. 拉兹说法治是「否定性德性」、且即使公正法律体系也无服从的初步义务。这一立场在道德上是否有吸引力？请给出支持与反对的论据。\n3. 马伯里案确立的司法审查，使法院有权推翻民选立法机关的法律。这究竟是法治的胜利，还是对民主的威胁？"}, "en": "The Meaning of the Rule of Law", "level": "core", "tags": "法治, 规则之治, 戴雪, 形式法治, 实质法治", "source": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "id": "S1M5K1"}, "S1M5K2": {"title": "法律面前人人平等", "EN": "Equality Before the Law", "LEVEL": "fundamental", "TAGS": "法律面前人人平等, 戴雪, 平等保护, 法治", "TERMS": "法律面前人人平等（Equality Before the Law）::所有人同受法律约束、同受法律保护、不因身份享有特权或遭受歧视的原则；法律至上（Supremacy of Law）::戴雪法治观的第一层含义，即法律高于专断权力；特权（Privilege）::特定身份或群体享有的、不受普遍法律约束的特殊权利；平等保护（Equal Protection）::美国宪法第十四修正案要求各州对任何人提供平等法律保护的原则；政治完整性（Political Integrity）::德沃金提出的政府须依普遍适用于所有人的原则治理的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "terms": [{"term": "法律面前人人平等（Equality Before the Law）", "def": "所有人同受法律约束、同受法律保护、不因身份享有特权或遭受歧视的原则"}, {"term": "法律至上（Supremacy of Law）", "def": "戴雪法治观的第一层含义，即法律高于专断权力"}, {"term": "特权（Privilege）", "def": "特定身份或群体享有的、不受普遍法律约束的特殊权利"}, {"term": "平等保护（Equal Protection）", "def": "美国宪法第十四修正案要求各州对任何人提供平等法律保护的原则"}, {"term": "政治完整性（Political Integrity）", "def": "德沃金提出的政府须依普遍适用于所有人的原则治理的价值"}], "sections": {"coreQuestion": "「法律面前人人平等」听起来天经地义，但它的实际含义需要拆解。它是否意味着所有人在任何方面都必须被同等对待？如果法律对未成年人、精神障碍者或残疾人作出特别规定，是否违背了这一原则？如果官员违法与普通人受到不同处理，又触犯了什么？本节要厘清这一原则的基本含义、它在戴雪法治理论中的位置，以及它与特权、平等保护、实质平等之间的关系。", "definition": "法律面前人人平等（Equality Before the Law）是一项要求所有人同受法律约束、同受法律保护的法律原则。它至少包含三层含义：其一，任何人不得凌驾于法律之上，掌握权力者同样要守法；其二，法律对所有人一体适用，不因身份、地位、财富而有差别；其三，所有人平等享有法律提供的保护与救济。\n\n在戴雪（A. V. Dicey）的法治理论中，法律面前人人平等是第二层含义，与法律至上性、宪法作为权利保障的结果共同构成法治的三要素。Wacks 在相关讨论中记录了戴雪的这一框架；Wacks 还引述哈特的观察，指出如今「人生而有权被同等对待」这一原则已被广泛接受，以至于种族歧视者也不得不辩称被歧视者「不是完全的人」，以掩盖其对平等原则的背离。\n\n德沃金（Ronald Dworkin）把这一原则推进到更深的层面。Wacks 指出，德沃金所谓的政治完整性（Political Integrity），其含义是法律面前人人平等，不仅是法律被照字面执行，更在于政府必须依一套原则上适用于所有人的原则来治理；任意的强制或惩罚，即便偶尔提高效率，也违反了政治平等这一核心维度。\n\n需要注意的是，法律面前人人平等并不要求法律对所有情形作完全相同的处理。合理的差别——如对未成年人的特别保护、对弱势群体的照顾——只要基于正当理由并普遍适用，并不违反这一原则。它反对的是没有正当理由的特权与歧视。", "history": "法律面前人人平等的观念，是在反对身份特权的斗争中形成的。欧洲封建时代，贵族、教士与平民适用不同的法律，享有不同的权利与义务。近代民族国家与民法典的兴起，以「法律面前人人平等」为原则，取消了基于身份的法律特权，确立了普遍适用的法律人格。这是现代法律区别于等级法的重要标志。\n\n在英美法中，这一原则与法治传统同步发展。戴雪在《英宪精义》中把它概括为英国宪法的基石之一：不仅普通人受普通法院管辖，官员亦无特殊豁免。在美国，1868年第十四修正案的平等保护条款，使这一原则获得了宪法明文依据，并成为此后反种族隔离、反性别歧视等运动的法律武器。\n\n二十世纪以来，人们逐渐意识到，形式上的同等适用并不足以消除实际存在的不平等。这使法律面前人人平等的传统含义受到实质平等诉求的挑战：如果起点极不平等，同等的法律适用可能只是把既有的不平等固定下来。Wacks 记录的自由至上主义与平等主义之争，正是这一理论紧张的表现。", "principle": "法律面前人人平等的逻辑可以从三层展开。\n\n第一，它反对特权。特权意味着某些人不受普遍法律约束，或享有他人没有的法律优待。法律面前人人平等要求废除这类身份性差别，使权力与权利的分配遵循普遍规则。这是它与法治的直接关联：没有平等适用，法律至上就会被架空为「部分人至上」。\n\n第二，它要求进行「相关分类」。法律必然对人群作出分类（如按年龄、收入、职业），但分类必须有正当理由且与立法目的相关。以种族或性别作分类，通常被视为高度可疑；以成绩或需要作分类，则可能被接受。判断一个分类是否违反平等，关键在于差别对待的理由是否正当、是否任意。\n\n第三，它与实质平等存在张力。形式意义上的平等要求「同样情况同样对待」，但「情况是否相同」的判断本身可能带有价值预设。把处境截然不同的人当作「相同」来对待，可能造成事实上的不平等。这就是布朗案所揭示的问题：「隔离但平等」在形式上声称同等对待，实际上却固化了种族等级。", "viewpoints": "戴雪把法律面前人人平等界定为法治的第二层含义，强调官员与普通人同受普通法律约束，无身份豁免。\n\n哈特为这一原则提供了最简形式的表述——「相同案件相同处理」。Wacks 指出，这一标准的广泛接受程度，使得公开的歧视都必须伪装成「被歧视者不同」。\n\n德沃金把平等理解为法律实践中的根本价值。Wacks 记载，德沃金批评罗尔斯，认为其深层理论的核心是每个人获得平等关怀与尊重的权利；这项权利构成契约的前提，社会契约的产物之说难以成立。这使法律面前人人平等具有了超越具体规则的道德深度。\n\n密尔（John Stuart Mill）等自由主义者则强调，平等的核心是机会开放而非结果均等——只要不存在人为的出身特权，人们可以平等地进入竞争，结果的不平等不必视为不公。这一点在 Wacks 关于自由与平等关系的讨论中有所体现——诺齐克更绝对地主张二者不可调和。", "comparison": "法律面前人人平等与几个概念的关系需要区分。\n\n与法律至上：二者是法治的一体两面。法律至上强调法律高于权力，法律面前人人平等强调法律平等地适用于所有人。没有后者，前者可能沦为「部分人利用法律统治其他人」。\n\n与平等保护：平等保护是这一原则在美国宪法中的具体制度形态，主要经由第十四修正案的司法解释展开；法律面前人人平等则是更一般的法理原则。\n\n与实质平等：前者是形式原则，要求规则平等适用；后者关注结果与结构性不利。布朗案显示，最高法院借助平等保护条款，把实质平等的诉求纳入了宪法判断——这为传统原则注入了新的内容。\n\n与特权：特权是这一原则的直接对立面。废除身份特权是近代法律现代化的重要成就，但新的特权形式（如基于财富的影响力）仍不断出现，使这一原则保持现实紧迫性。", "debates": "围绕法律面前人人平等的核心争论，是形式平等与实质平等何者应当主导。\n\n形式平等一方认为：法律应当无视身份差异，一律适用；差别对待容易滑向歧视，且标准难以统一；形式平等标准清晰，有利于可预测性与法治。\n\n实质平等一方认为：形式中立可能掩盖结构性不利；看似相同的对待对处境不利者可能更不公平；真正的平等要求关注实际效果，允许对不利者进行倾斜。\n\n这一争论在美国宪法判例中得到充分体现。1896年的普莱西诉弗格森案（Plessy v. Ferguson, 163 U.S. 537）确立了「隔离但平等」，声称隔离设施只要相当即符合平等保护；1954年的布朗案则宣告公立教育中的种族隔离本身即违反平等保护。两案之间的转向，正体现了从形式平等向实质平等的推进。\n\nWacks 记录的哈特观察也为争论提供了线索：当歧视者不得不否认被歧视者「完全是人」时，说明平等原则本身具有强大的规范力量——任何差别对待都必须给出可被接受的理由，否则就会暴露为纯粹的偏见。", "case": "美国最高法院1896年判决的普莱西诉弗格森案（Plessy v. Ferguson, 163 U.S. 537）是理解法律面前人人平等形式局限的经典案例。路易斯安那州1890年通过《隔离车厢法》，要求铁路提供「平等但隔离」的设施。荷马·普莱西（Homer Plessy）具有八分之一黑人血统，他故意坐在白人车厢以测试该法，遭逮捕并被定罪。\n\n普莱西上诉主张，该法违反第十三、十四修正案。最高法院于1896年判决维持原判，认为只要设施平等，种族隔离并不违反平等保护；法院还声称，若隔离被认定为歧视，那只是因为黑人自己选择了这种解释。这一判决确立了「隔离但平等」原则，为种族隔离制度的长期存续提供了法律依据。\n\n本案的吊诡之处在于：它以「平等」之名行隔离之实，把形式上的同等设施当作平等的全部含义，从而掩盖了隔离制度本身的等级性质。正因如此，它成为后来布朗案推翻的对象。", "caseAnalysis": "就普莱西案而言，事实层面是：州法要求铁路种族隔离，普莱西因坐在白人车厢被捕；争议焦点是：隔离设施是否违反第十四修正案的平等保护。\n\n法院的裁判理由建立在形式平等之上：只要为两个种族提供的设施「平等」，隔离本身不构成歧视；平等保护要求的是同等设施，而非混合乘坐。\n\n从法律面前人人平等的形式理解看，这一判决似乎自洽——两个种族都被同等隔离，没有谁被排除在铁路服务之外。但从实质平等角度看，隔离制度本身就是基于种族的差别对待，并把黑人标记为「低人一等」，其社会效果远超设施比较。\n\n理论意义上，普莱西案展示了形式平等原则被滥用时的危险：当「同等对待」被理解为「同等隔离」，平等原则反而成为固化等级的工具。这也印证了 Wacks 引述哈特的判断——歧视者会试图把被歧视者描述为「不同」，以规避平等原则的约束。1954年布朗案推翻这一原则，标志着法律面前人人平等从形式走向实质。", "summary": "法律面前人人平等是戴雪法治理论的第二层含义，要求所有人同受法律约束与保护，反对身份特权。哈特的「相同案件相同处理」提供了其最简表述，德沃金则以政治完整性赋予其道德深度。这一原则的关键在于反对任意的特权与歧视，允许基于正当理由的合理差别。形式平等与实质平等之争在其宪法实践中展开：普莱西案以「隔离但平等」把形式平等推向荒谬，布朗案则以「隔离本身即伤害」实现了向实质平等的转向。这说明，法律面前人人平等是一项需要在具体制度中不断检验其真实含义的原则，一句可以停止追问的口号远远不够。", "furtherThinking": "1. 如果一家保险公司按年龄差别定价，这是否违反法律面前人人平等？判断的关键词是什么？\n2. 普莱西案中法院说「隔离是否构成歧视取决于黑人如何解释」。这种说法为什么可疑？请结合哈特的观察分析。\n3. 德沃金把平等关怀与尊重的权利视为契约的前提。如果把这一观点推到底，它对「法律面前人人平等」的理解会带来什么变化？"}, "en": "Equality Before the Law", "level": "fundamental", "tags": "法律面前人人平等, 戴雪, 平等保护, 法治", "source": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "id": "S1M5K2"}, "S1M5K3": {"title": "法律明确性与可预测性", "EN": "Legal Clarity and Predictability", "LEVEL": "core", "TAGS": "法律明确性, 可预测性, 不溯及既往, 富勒, 法治", "TERMS": "法律明确性（Legal Clarity/Certainty）::法律规则应当清晰、确定、可被理解地表达的要求；可预测性（Predictability）::人们能够依据法律预先安排行为并预期其法律后果的性质；不溯及既往（Non-retroactivity）::法律只适用于其生效后发生的行为、不得追诉既往行为的要求；内在道德（Internal Morality）::富勒提出的法律须满足的一般性、公开性、明确性、不矛盾等程序性要求；法的明确性原则（Principle of Legal Certainty）::要求法律内容清楚、稳定且可被公民据以规划行为的原则；模糊无效（Void for Vagueness）::美国法中因法律用语过于模糊而宣告其违宪的原则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Siems, Comparative Law, ch.10", "terms": [{"term": "法律明确性（Legal Clarity/Certainty）", "def": "法律规则应当清晰、确定、可被理解地表达的要求"}, {"term": "可预测性（Predictability）", "def": "人们能够依据法律预先安排行为并预期其法律后果的性质"}, {"term": "不溯及既往（Non-retroactivity）", "def": "法律只适用于其生效后发生的行为、不得追诉既往行为的要求"}, {"term": "内在道德（Internal Morality）", "def": "富勒提出的法律须满足的一般性、公开性、明确性、不矛盾等程序性要求"}, {"term": "法的明确性原则（Principle of Legal Certainty）", "def": "要求法律内容清楚、稳定且可被公民据以规划行为的原则"}, {"term": "模糊无效（Void for Vagueness）", "def": "美国法中因法律用语过于模糊而宣告其违宪的原则"}], "sections": {"coreQuestion": "如果法律规定「不得从事有伤风化的行为」，你能事先知道自己会不会违法吗？如果政府今天修改税率，并要求补缴去年的税款，这种规则还值得遵守吗？这些问题涉及法治的一项基础要求：法律必须明确，并且能够让人预测行为的后果。法律若模糊不清或朝令夕改，人们就无法规划生活，权力的任意性也就有了可乘之机。本节要讨论明确性与可预测性的具体内涵、富勒「内在道德」中与之相关的要求、哈特与富勒论战中围绕溯及既往的分歧，以及法院如何用「模糊无效」原则处理不明确的法律。", "definition": "法律明确性（Legal Clarity / Legal Certainty）指法律规则应当以清晰、确定、不含混的方式表达，使受众能够理解其要求。可预测性（Predictability）则指人们能够依据现行法律预先安排自己的行为，并合理预期其法律后果。二者是法治形式维度的核心内容：只有规则明确且稳定，人们才有可能「依法行事」。\n\n富勒（Lon Fuller）在《法律的道德性》中提出法律的「内在道德」（Internal Morality），列举了一系列使法律成为可被服从之对象的程序性要求。Wacks 指出，这些要求包括：法律的一般性、公开颁布、不溯及既往、明确性、不矛盾、可以被遵守、稳定性，以及官方行为与法律的一致性。其中，明确性与不溯及既往直接关系到可预测性。\n\n不溯及既往（Non-retroactivity）要求法律只对其生效后的行为产生约束力，不得用它来追究此前已经发生的行为。这是可预测性的时间维度：人们只能根据行为当时的法律来判断其合法性。Wacks 记录了哈特与富勒论战中的一个细节：两人都更倾向于制定溯及既往的立法来处理纳粹时期的罪行，但对这一做法与法治要求的关系有不同理解——这提示我们，明确性与不溯及既往虽是法治的重要原则，却并非绝对不可权衡。\n\n在美国法中，明确性要求通过「模糊无效」（Void for Vagueness）原则获得司法表达：如果一条法律用语过于模糊，以致普通公民无法理解何种行为被禁止，法院可以宣告其违宪。", "history": "明确性与可预测性的诉求，与近代的形式法治传统密切相关。随着成文法与法典化的兴起，人们期待法律能够以精确的文字确定权利义务，从而减少法官的任意裁量。大陆法系的法典化传统尤其强调法律的体系化与明确性；普通法虽然以判例为主，但同样重视「遵循先例」所带来的可预测性。\n\n富勒在二十世纪中期把这些要求系统化。Wacks 指出，富勒采取的是一种程序性自然法立场：他关注的是法律在形式上是否健全，而非直接判定每条法律的内容是否正义。他的「八种使法律成为可能的方式」把明确性、不溯及既往等要求提升为法律的「内在道德」。\n\n哈特与富勒的论战进一步凸显了这些原则的复杂性。Wacks 记载，这场论战于1957年发起、1958年发表于《哈佛法律评论》，核心议题是法律与道德的关系，但其中涉及溯及既往立法的讨论，直接触及明确性与可预测性的边界。\n\n比较法层面，Siems 的《比较法》在讨论「法律与发展」时，把法治的形式要素作为重要指标，并列出「法治的可能功能与例证」，说明明确性与可预测性在制度评估中具有实际操作意义。", "principle": "明确性与可预测性的逻辑可以从三层展开。\n\n第一，明确性服务于人的自主。如果人们无法知道法律禁止什么，就无从选择守法；法律因而失去了指引行为的功能。富勒之所以把这些要求称为「内在道德」，正是因为它们使法律成为可以被服从的对象——一套模糊、矛盾、溯及既往的规则，根本无法被人遵守。\n\n第二，可预测性约束权力。明确、公开、稳定的规则缩小了官员任意解释与适用的空间。反之，模糊的法律为选择性执法提供了温床：执法者可以决定对谁适用、何时适用。这正是法治与「人治」在制度层面的关键差异之一。\n\n第三，明确性与裁量之间存在张力。法律语言不可能穷尽一切情形，总会有边缘案例需要法官解释。过度追求明确会使法律僵化，无法应对新情况；过度容忍模糊则会损害可预测性。哈特的「开放结构」（open texture）理论指出，法律语言在核心地带相对确定，在边缘地带则存在不确定，这是任何法律体系都必须面对的常态。如何在确定性与灵活性之间取得平衡，是司法技术的核心难题。", "viewpoints": "富勒把明确性、不溯及既往、公开性、稳定性等列为法律的内在道德。Wacks 强调，富勒关注的是程序健全性，且遵守这些要求并不保证法律内容正义——这是他对富勒立场的重要限定。\n\n哈特在《法律的概念》中承认法律语言存在开放结构，边缘案件的裁判需要法官行使裁量。这使哈特对明确性的态度比富勒更为现实：他承认法律不可能完全确定，但强调规则的核心地带仍提供了稳定的指引。\n\n拉兹（Joseph Raz）从形式法治立场强调法律的清晰、稳定与公开。Wacks 指出，拉兹认为遵守法治能减少专断权力之害——明确性正是减少专断的重要机制。\n\n德沃金（Ronald Dworkin）则反对哈特式的「强自由裁量」观。他认为，即便在疑难案件中，法律也包含可供援引的原则，法官的任务是找到「唯一正确答案」，而非任意造法。这实际上在不牺牲可预测性的前提下，为法律的开放性提供了另一种解释。", "comparison": "明确性与可预测性可以与几个概念对照理解。\n\n明确性与确定性：明确性指表达的清晰，确定性指结果的稳定。一部法律可能文字明确，却因频繁修改而缺乏确定性；也可能文字模糊，却因长期稳定的解释而形成可预测的实践。\n\n明确性与自由裁量：明确性越高，裁量空间越小；裁量越宽，可预测性越弱。但完全排除裁量既不可能也不可取——法律需要适应个案正义与新情况。\n\n富勒与哈特的分歧：富勒把明确性等要求视为法律的概念性条件，认为严重违反者不配称法律；哈特则把这些要求视为法治的价值标准，承认极端不明确的规则仍可能是法律，只是不值得服从。这一分歧延续了自然法与实证主义在「法律与道德关系」上的根本对立。\n\n形式法治与实质正义：明确性属于形式要求，它本身不保证法律内容的正义——富勒的内在道德被批评为「只保证形式不保证内容」，Wacks 也指出这一点。", "debates": "围绕明确性与不溯及既往，最经典的争论发生在哈特与富勒之间。\n\n争论的背景是二战后如何惩治纳粹罪行。Wacks 记载，哈特认为应该用溯及既往的立法来惩治那些依当时法律合法的罪行，因为这样做虽然牺牲了法治的某些要求，却是道德上必要的；富勒则坚持法律的内在道德要求不溯及既往，认为纳粹『法律』因严重违反这些要求而根本不是法律。\n\n富勒一方的论据：其一，法律要成为可被服从的对象，就必须公开、明确、不溯及既往；其二，溯及既往的惩罚使公民无法依据当时的法律安排行为，破坏了法律指引功能；其三，承认纳粹规则为『法律』会混淆法律与赤裸暴力的界限。\n\n哈特一方则回应：其一，把极端邪恶的规则排除出法律概念，反而会遮蔽对其性质的认识；其二，溯及既往的立法虽然不完美，但它是面对极端不义时「两害相权取其轻」的选择；其三，法律与道德的分离并不妨碍我们谴责恶法。Wacks 总结，哈特与富勒都更倾向于制定溯及既往的立法，分歧在于如何理论化这一做法——这使争论具有了超越具体结论的哲学意义。\n\n争论的后续影响在于：它使明确性与不溯及既往从技术性要求上升为法治理论的核心议题，并促使后来的学者思考：在极端情况下，形式法治的要求是否可以让位于实质正义？Wacks 指出，任何法律理论都要交代自己如何处理效力与正当性的关系——这正是争论留给后世的坐标。", "case": "美国最高法院1972年判决的帕帕克里斯托诉杰克逊维尔市案（Papachristou v. City of Jacksonville, 405 U.S. 156）是「模糊无效」原则的经典案例。佛罗里达州杰克逊维尔市的一项流浪条例规定，「游荡者」（vagrants）、「无赖」（loiterers）以及「以其他方式不以诚实方式谋生者」等可以被认定为犯罪并处罚。\n\n两名被告因违反该条例被定罪。最高法院一致裁定该条例违宪，理由是：条例用语过于模糊，普通公民无法据此判断何种行为构成犯罪；它赋予警察过大的裁量权，导致任意执法；同时它还把贫穷与无业状态本身犯罪化。\n\n法院指出，明确性是正当程序的基本要求——法律必须给出可理解的禁止标准，使公民能够据此规划行为，并防止执法者任意选择执法对象。\n\n本案成为美国宪法「模糊无效」原则的标志性判例，说明明确性属于宪法层面的权利保障要求，立法技术偏好之说过于轻描淡写。", "caseAnalysis": "就帕帕克里斯托案而言，事实层面是：被告因违反内容模糊的流浪条例被定罪；争议焦点是：该条例是否符合正当程序对明确性的要求。\n\n法律依据是宪法第十四修正案的正当程序条款。裁判理由在于：条例中「游荡」「无赖」「不以诚实方式谋生」等用语缺乏客观标准，公民无法预判何种行为违法；这种模糊性必然导致警察的选择性执法，从而使法律沦为任意权力的工具。\n\n从明确性角度，本案展示了富勒「内在道德」的现实意义：一套无法被理解的规则，根本不能成为可被服从的对象。从可预测性角度，本案说明模糊法律如何损害人们对行为后果的合理预期——公民无法知道自己的正常生活行为是否会在某天被认定为犯罪。\n\n从权力约束角度，本案的核心担忧是裁量权的滥用：模糊条款使执法者可以任意决定对谁执法，这与法治「法的统治而非人的统治」直接冲突。\n\n理论意义上，本案把富勒与哈特争论中的抽象原则具体化：明确性要求不仅是立法建议，更是可以通过宪法审查来实施的硬性约束。它也提示我们，形式法治的要求具有真实的权利保障功能——模糊法律的受害者往往是社会中的弱势者。", "summary": "法律明确性要求规则清晰、确定、可被理解，可预测性要求人们能据法律预先安排行为并预期后果。二者是法治形式维度的核心，服务于人的自主与对权力的约束。富勒将其纳入法律的「内在道德」，哈特承认法律语言的开放结构并强调裁量的不可避免，拉兹从形式法治立场强调清晰与稳定，德沃金则以原则论证限制任意裁量。哈特与富勒围绕溯及既往立法的争论表明，明确性与不溯及既往虽是重要原则，却在极端不义面前可能面临权衡。帕帕克里斯托案通过「模糊无效」原则，把这些抽象要求变成了可实施的宪法约束，说明形式法治的要求具有真实的权利保障功能。", "furtherThinking": "1. 如果一条法律措辞明确但每月修改一次，它的明确性是否足以保证可预测性？请说明明确性与稳定性之间的关系。\n2. 哈特与富勒都倾向于用溯及既往立法惩治纳粹罪行，但理由不同。请分别重建两人的论证，并说明分歧的哲学意义。\n3. 在疑难案件中，法官必然要解释模糊的法律。这是否意味着可预测性只是一个程度问题，而非可以实现的目标？"}, "en": "Legal Clarity and Predictability", "level": "core", "tags": "法律明确性, 可预测性, 不溯及既往, 富勒, 法治", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Siems, Comparative Law, ch.10", "id": "S1M5K3"}, "S1M5K4": {"title": "司法独立", "EN": "Judicial Independence", "LEVEL": "core", "TAGS": "司法独立, 分权, 法官, 司法问责, 法治", "TERMS": "司法独立（Judicial Independence）::法院与法官在裁判时不受行政、立法及私人不当影响的状态；分权（Separation of Powers）::立法、行政、司法三种权力由不同机关行使的宪制原则；司法问责（Judicial Accountability）::法官须对其裁判行为承担责任、接受监督的要求；职业法官（Career Judge）::在民法法系中经专门训练、按等级晋升的法官类型；司法能动主义（Judicial Activism）::法院积极介入政策与权利保护的司法倾向；司法克制（Judicial Restraint）::法院尊重民选机关决定、审慎行使审查权的司法倾向", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.3, ch.7, ch.10", "terms": [{"term": "司法独立（Judicial Independence）", "def": "法院与法官在裁判时不受行政、立法及私人不当影响的状态"}, {"term": "分权（Separation of Powers）", "def": "立法、行政、司法三种权力由不同机关行使的宪制原则"}, {"term": "司法问责（Judicial Accountability）", "def": "法官须对其裁判行为承担责任、接受监督的要求"}, {"term": "职业法官（Career Judge）", "def": "在民法法系中经专门训练、按等级晋升的法官类型"}, {"term": "司法能动主义（Judicial Activism）", "def": "法院积极介入政策与权利保护的司法倾向"}, {"term": "司法克制（Judicial Restraint）", "def": "法院尊重民选机关决定、审慎行使审查权的司法倾向"}], "sections": {"coreQuestion": "如果法官判案时要看政府的脸色，或者担心得罪舆论而作出违心判决，法治还剩下多少？司法独立是法治的关键制度支柱，但它从来不是绝对的概念：法官独立意味着不受不当干预，是否也意味着不受任何监督？独立与问责如何平衡？普通法系与大陆法系的法官角色差异，会如何影响我们对「独立」的理解？美国最高法院2000年的布什诉戈尔案，更直接引发了「法院是否越权」的争论。本节将梳理司法独立的含义、制度保障、比较法差异与核心争论。", "definition": "司法独立（Judicial Independence）指法院与法官在审理和裁判案件时，不受行政机关、立法机关及其他外部力量的不当干预，只依据法律与事实作出判断的状态。它包含两个层面：\n\n其一，机构独立（institutional independence）：司法机构在组织、财政与人事上相对独立于其他权力部门，法院拥有自己的管理体系与预算，裁判不被行政机关左右。\n\n其二，个人独立（individual independence）：法官在个案裁判中享有独立性，不受上级法官或外部压力的不当控制，其职业保障（如任期、薪酬）使其无后顾之忧。\n\n司法独立植根于分权（Separation of Powers）理论。Siems 在《比较法》中提到，「分权、法治与民主」被视为一组相互关联的原则，司法权与立法、行政权的分离是现代宪制的重要特征。\n\n但司法独立并非意味着「司法至上」。它必须与司法问责（Judicial Accountability）相平衡：法官虽有裁判独立，仍须对其行为负责，接受上诉审查、纪律监督与公众监督。独立保障的是「不受不当干预」，而不是「不受任何约束」。", "history": "司法独立观念的形成，与近代分权理论密切相关。孟德斯鸠（Montesquieu）在《论法的精神》中系统阐述了分权学说，主张立法、行政、司法三权分立，以防止权力滥用——若司法权与立法权合并，法官将成为立法者，公民的生命与自由将受专断支配。\n\n英国1701年《王位继承法》（Act of Settlement）确立了法官「品行端正期间任职」（during good behaviour）的原则，使法官不再随国王意志任免，这被视为司法独立的重要制度起点。美国宪法第三条以「良好行为」保障联邦法官的任期，并禁止减少法官薪酬，把司法独立写入宪法。\n\n进入现代，司法独立的制度形态在不同法系中呈现差异。Siems 的比较法研究指出，大陆法系的法官往往是「职业法官」（career judge），在等级化的司法体系中按资历晋升，强调对法律的严格适用；普通法系的法官则多从资深律师中产生，更强调个人判断与对抗制程序。Wacks 的著作也在不同章节讨论了法官角色、司法德性与裁判的难题。\n\n二十世纪以来，随着法院审查立法与行政行为权力的扩张，司法独立引发新的争论：当法院推翻民选机关的决定时，独立的司法是否变成了「反多数」的机构？", "principle": "司法独立的逻辑可以从三层展开。\n\n第一，司法独立是公正裁判的前提。法官若受制于政府或私人压力，就无法中立地听取双方意见，程序正义与实体正义都会落空。它也是权力约束机制的关键：没有独立法院，法律对权力的约束就缺乏可靠的裁判者。\n\n第二，司法独立需要具体的制度保障。任期保障防止法官因作出不受欢迎的判决而被撤职；薪酬保障防止通过经济手段施压；机构独立（如法院自主管理预算与人事）防止行政部门的间接控制。这些制度安排的共同目标，是让法官「敢于依法裁判」。\n\n第三，司法独立必须与问责相平衡。绝对的独立可能导致司法专横：法官若不受任何监督，其错误与偏见无从纠正。因此，上诉制度、裁判理由公开、纪律处分机制与公众批评，都是对司法的必要制约。Wacks 在讨论法官道德时指出，人们期待法官具备公正、无偏私、讲理等「司法德性」，但仅凭这些德性并不足以保证道德正确——这说明制度性的问责与价值审视都不可缺少。", "viewpoints": "孟德斯鸠的分权理论为司法独立提供了经典论证：权力集中必然导致滥用，司法权必须与立法、行政权分离。\n\n戴雪（A. V. Dicey）的法治理论把司法独立与法律面前人人平等联系起来——普通人同受普通法院管辖、官员无特殊豁免，这一格局以独立司法为前提。\n\nSiems 的比较法研究提示，两大法系的法官制度差异显著：民法法系的职业法官在等级体系中追求法律适用的统一，普通法系法官则更强调个人判断。Siems 还记录了「司法独立」在不同国家制度中的不同实现形式，提醒我们不要把某一法系的安排当成普适标准。\n\n德沃金（Ronald Dworkin）从「法律作为完整性」的角度为司法独立提供哲学支持：法官的任务是在法律原则的整体中找到「唯一正确答案」，这需要相对于政治压力的独立性；但法官也受法律原则的约束，并非随心所欲。\n\n法律现实主义者则提出反思：霍姆斯（Oliver Wendell Holmes Jr.）名言「法律的生命不在逻辑，而在经验」，提示法官的社会背景与政策判断会影响裁判；这意味着司法独立并不保证裁判的客观性，需要警惕法官以「独立」之名掩盖价值选择。", "comparison": "司法独立与几个概念的关系需要辨析。\n\n司法独立与司法问责：前者保障法官不受不当干预，后者要求法官承担责任。二者并非零和——合理的问责机制（如上诉审查、公开说理）反而能强化司法独立的正当性，因为它证明独立不是为错误背书。\n\n司法独立与分权：分权是司法独立的制度基础，但司法独立只是分权的一个面向；分权还要求立法、行政各自独立并相互制衡。\n\n普通法系与大陆法系的差异：普通法系法官的地位较高、个人独立色彩较强；大陆法系职业法官更强调层级与法律适用的统一。Siems 的比较法讨论提醒，两种模式各有优劣，不能简单断言某一种更「独立」。\n\n司法能动主义与司法克制：这是围绕司法独立功能的两极。能动主义主张法院应积极保护权利、纠正政治过程失灵；克制主义主张法院应尊重民选机关的决定。二者的张力在布什诉戈尔案中表现得淋漓尽致。", "debates": "司法独立最经典的争论，是它是否应当受到民主的约束，以及法院应在多大程度上介入政策。\n\n支持强司法独立的论据：其一，独立法院是权利保障的最后屏障，多数人的民主决策可能侵犯少数人权利；其二，法官不受选举周期影响，能够从长远与原则角度裁判；其三，法律适用需要专业判断，不应屈从于政治压力。\n\n质疑强司法独立的论据：其一，法官并非民选，由他们推翻民选机关的决定存在「反多数难题」；其二，法官的社会背景与价值偏好会影响裁判，独立可能掩盖司法的主观性；其三，过度的独立可能使法院脱离社会，削弱判决的可接受性。\n\nWacks 记录的德沃金与法律现实主义之间的分歧，为这场争论提供了理论背景：德沃金相信法律原则能够约束法官，现实主义则怀疑原则的决定性。Wacks 在讨论法官面对不义法律的两难时，也揭示了独立的复杂性——一位在种族隔离制度下严格依法裁判的法官，其「独立」反而可能服务于不义。\n\n争论的现实形态是司法能动主义与司法克制的张力：能动主义强调独立法院的积极功能，克制主义强调民主程序的优先性。这一张力在美国最高法院的判例中反复出现。", "case": "美国最高法院2000年判决的布什诉戈尔案（Bush v. Gore, 531 U.S. 98）是围绕司法独立与司法能动争论最激烈的案例之一。2000年美国总统大选中，小布什与戈尔在佛罗里达州的票数极为接近，该州启动重新计票。佛罗里达州最高法院命令继续人工计票，小布什阵营上诉至联邦最高法院。\n\n联邦最高法院于2000年12月作出终局裁决：停止重新计票，实际上确认了小布什的胜选。多数意见认为，各郡采用不同的计票标准，违反了宪法第十四修正案的平等保护条款。\n\n判决在美国社会引发巨大争议。批评者认为，最高法院以5比4的党派分化投票介入政治进程，是司法能动主义的典型表现，损害了法院作为中立裁判者的形象；支持者则认为，法院是在宪法层面纠正州法院的法律错误，履行了维护法治与平等保护的职责。\n\n本案把司法独立的双重面向同时暴露出来：一方面，法院不受政治压力左右、独立适用宪法，体现了司法独立的价值；另一方面，法院介入高度政治化的选举争议，又引发了对司法越权与法院合法性的担忧。", "caseAnalysis": "就布什诉戈尔案而言，事实层面是：总统选举计票争议，州法院命令重新计票，联邦最高法院介入并叫停；争议焦点是：联邦法院是否有权介入，以及其裁判是否受政治考量影响。\n\n法律依据方面，多数意见以平等保护条款为核心——不同郡采用不同计票标准，使选票的效力因地域而异。裁判理由强调宪法统一标准的重要性。\n\n从司法独立角度，本案展示了独立法院的两个面向。一方面，最高法院在高度政治化的情境中作出裁判，未屈从于政治压力，体现了「依法裁判」的独立性；另一方面，5比4的分裂投票与介入选举的时机，使公众怀疑裁判是否受到党派因素影响——这正是 Wacks 与现实主义传统提醒我们警惕的「独立」与「客观」之间的落差。\n\n从司法问责角度，批评者要求法院更审慎地行使权力，并通过充分的说理来证明裁判的法律基础；取消法院审查权的主张并非其本意。这提示：司法独立的正当性，最终依赖于裁判的可论证性与公众的接受。\n\n理论意义上，本案说明司法独立是一项需要在具体情境中权衡的制度安排，抽象的好事说帮不上忙。它既可能是权利与法治的守护者，也可能因过度介入而损耗自身的合法性。Wacks 关于法官道德与司法德性的讨论，正可作为评价本案的参照：中立、无偏私的司法德性，是否足以回应公众对司法独立与政治介入的双重期待？", "summary": "司法独立指法院与法官不受行政、立法及私人不当干预，只依据法律与事实裁判的状态，包括机构独立与个人独立两个层面，其制度基础是分权理论。它必须有任期、薪酬等制度保障，同时须与司法问责相平衡。普通法系与大陆法系在法官角色与制度形态上存在差异，Siems 的比较法研究提醒我们避免单一标准。司法独立的核心争论，是它应否受民主约束以及法院介入政策的范围——布什诉戈尔案把这一争论推到极致：独立法院既是法治的守护者，其介入政治的方式又会引发合法性争议。理解司法独立，必须同时看到它的价值与边界。", "furtherThinking": "1. 法官「不受不当干预」与「不受任何监督」的分界在哪里？请设计一种制度安排，使二者兼顾。\n2. 布什诉戈尔案中，最高法院是在维护法治还是在越权介入政治？请分别列出支持与批评双方的论据。\n3. Siems 指出普通法与大陆法系的法官制度差异。这些差异会如何影响「司法独立」在非西方国家制度设计中的可移植性？"}, "en": "Judicial Independence", "level": "core", "tags": "司法独立, 分权, 法官, 司法问责, 法治", "source": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.3, ch.7, ch.10", "id": "S1M5K4"}, "S1M5K5": {"title": "权力受到法律约束", "EN": "Power Bound by Law", "LEVEL": "core", "TAGS": "权力约束, 法律至上, 宪政, 越权无效, 行政法", "TERMS": "权力受法律约束（Power Bound by Law）::国家权力的存在与行使均须有法律依据并受法律限制的原则；法律至上（Supremacy of Law）::戴雪法治观的第一层含义，即法律高于专断权力；越权无效（Ultra Vires）::行政机关超越法定权限的行为无效的原则；司法审查（Judicial Review）::法院审查立法或行政行为是否合法的制度；自由裁量（Discretion）::在法律授权范围内由官员酌情判断的权力；消极德性（Negative Virtue）::拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立道德价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "terms": [{"term": "权力受法律约束（Power Bound by Law）", "def": "国家权力的存在与行使均须有法律依据并受法律限制的原则"}, {"term": "法律至上（Supremacy of Law）", "def": "戴雪法治观的第一层含义，即法律高于专断权力"}, {"term": "越权无效（Ultra Vires）", "def": "行政机关超越法定权限的行为无效的原则"}, {"term": "司法审查（Judicial Review）", "def": "法院审查立法或行政行为是否合法的制度"}, {"term": "自由裁量（Discretion）", "def": "在法律授权范围内由官员酌情判断的权力"}, {"term": "消极德性（Negative Virtue）", "def": "拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立道德价值"}], "sections": {"coreQuestion": "一个政府可以说「我们依法行政」，但它的「法」可能是一条赋予它无限权力的法律。此时权力是否真的受到了约束？权力受法律约束是法治最核心的命题，但它面临一个根本追问：谁来约束「制定规则的权力」？如果立法机关可以随意修改法律，法律对权力的约束会不会只是一句空话？本节要梳理这一原则的含义、制度机制与理论分歧，并借助英国的经典判例说明法院如何把「法律至上」转化为对权力的实际限制。", "definition": "权力受到法律约束（Power Bound by Law）是指：国家权力的存在与行使都必须有法律依据，且不得超越法律划定的界限。它是戴雪（A. V. Dicey）法治理论的第一层含义——法律至上性（Supremacy of Law）——的直接展开。Wacks 在相关讨论中记录了戴雪的这一框架：法律高于专断权力，任何人不得凭借身份或意志凌驾于法律之上。\n\n这一原则包含两个基本要求。其一，权力必须有法律依据（legality）：行政机关不能自行创设权力，每一项干预公民权利的措施都必须能追溯到法律的授权。其二，权力不得越界（ultra vires）：即使有授权，权力也只能在授权范围内行使，超越权限的行为无效。\n\n在制度层面，权力约束依赖多重机制：议会立法对行政权的界定、法院通过司法审查（Judicial Review）对行政与立法行为的合法性审查、基本权利对立法权的实体限制，以及分权体制下各权力部门之间的相互制衡。\n\n拉兹（Joseph Raz）为这一原则提供了一个审慎的说明。Wacks 指出，拉兹认为遵守法治能减少行政权力的滥用，是一种「否定性德性」（negative virtue）——它不赋予法律独立的道德价值，但确实降低专断统治的风险。这一判断准确概括了权力受法律约束的实际功能：它不能保证权力必然善良，但能防止权力任意。", "history": "权力受法律约束的观念，起源于对专断权力的反抗。英国1215年的《大宪章》（Magna Carta）以法律形式限制国王的征税与司法权，开启了「王在法下」的传统。1689年《权利法案》进一步确立议会权力高于王权，使政府权力受到法律与议会的双重约束。戴雪在十九世纪系统总结了这一传统，把法律至上性作为英国宪法的基石。\n\n在大陆法系，权力约束主要通过行政法与宪法审查体系实现：行政机关的行为须有法律授权，法院（尤其是行政法院与宪法法院）有权审查其合法性。Siems 的比较法研究提到，「分权、法治与民主」是相互关联的原则，不同国家在权力约束的制度安排上各有特色。\n\n二十世纪以来，福利国家的兴起使行政权大幅扩张，行政机关获得广泛的自由裁量（Discretion）空间。这使「权力受法律约束」面临新的挑战：当法律赋予行政机关宽泛的裁量权时，如何确保它不被滥用？行政法中的程序控制、理由说明要求与司法审查标准，正是对这一挑战的制度回应。", "principle": "权力受法律约束的逻辑可以从三层展开。\n\n第一，法律依据原则。权力必须来自法律的授予，没有法律依据的权力行使是非法的一一这是「法无授权不可为」的行政法逻辑。它与公民「法无禁止即可为」形成对照，体现了对权力的严格态度。\n\n第二，越权无效原则。即使权力来自法律授权，一旦超出授权范围，行为即属无效（ultra vires）。法院通过解释授权法律的范围来判断权力是否越界，这使司法审查成为限制权力的关键技术。\n\n第三，自由裁量与约束的张力。现代行政离不开裁量——法律不可能预见一切情形，必须留给官员酌情判断的空间。但裁量若不受约束，就可能变成专断。因此，法律通过界定裁量的范围、要求说明理由、提供程序保障与司法审查，把裁量纳入法治轨道。Wacks 记录的拉兹命题在此具有解释力：法治不能消除裁量，但能减少其被滥用的风险。", "viewpoints": "戴雪把法律至上性作为法治的第一层含义，强调法律高于专断权力，一切权力行使都必须以法律为依据。\n\n拉兹把法治理解为减少专断权力之害的「否定性德性」。Wacks 指出，拉兹反驳了「法律因符合法治而具有道德性」的说法，但他承认法治能减少行政权力的滥用——这正是权力受法律约束的实际价值。\n\n德沃金（Ronald Dworkin）从政治完整性出发，主张政府必须依一套原则上适用于所有人的原则治理，任意的强制或惩罚违反政治平等。这为权力约束提供了实体性的维度：权力不仅要「有法律依据」，其所依据的原则还必须是正当的。\n\nE. P. 汤普森（E. P. Thompson）在 Wacks 的记述中把法治理解为「对权力的有效抑制与对公民自由的保护」。这一历史主义的法定义突出了权力约束的解放面向——法治是公民对抗权力的屏障，统治者的工具之说恰为其反面。\n\n批判者对这一原则提出质疑：如果法律本身由权力制定，法律对权力的约束是否只是权力自选的限制？这是形式法治与实质法治争论在权力问题上的反映。", "comparison": "权力受法律约束与几个概念的关系值得辨析。\n\n与法律至上：法律至上是原则的宣示，权力受法律约束是这一原则在操作层面的展开。前者回答「什么最高」，后者回答「权力如何被限制」。\n\n与人治：人治意味着权力行使取决于统治者的个人意志，法治则要求权力依普遍规则行使。二者的分界正在于权力是否受法律约束。\n\n与权力制衡：分权与制衡是权力约束的制度手段之一，但权力受法律约束的范围更广——它还包括议会立法、司法审查、基本权利保障等机制。\n\n形式约束与实质约束：形式约束要求权力有法律依据、不越权；实质约束进一步要求法律本身符合正义与人权。拉兹的定位偏向形式约束，德沃金与实质法治论者则要求二者结合。", "debates": "围绕权力受法律约束的核心争论，是形式约束是否足够。\n\n形式论者的论据：其一，要求权力有法律依据、不越权，标准清晰、可操作；其二，在价值多元的社会中，形式约束比实质约束更容易达成共识；其三，拉兹指出，形式法治已能有效减少专断权力之害，不必强求法律内容符合特定的正义观。\n\n实质论者的论据：其一，如果法律本身不正义，「依法行使权力」仍可能造成压迫；其二，纳粹德国的历史表明，形式合法性和权力约束可以同时为恶服务；其三，德沃金的政治完整性说明，权力的正当性不能仅来自「有法律依据」，还必须来自可辩护的原则。\n\nWacks 记录的哈特与富勒论战，为这一争论提供了思想背景：哈特坚持承认恶法为法律，以便更清醒地抵抗它；富勒则主张严重违反内在道德的规则不是法律。在权力问题上，这一分歧表现为：是先在形式上确认权力的合法性再加以批判，还是直接否认不义权力的合法性。\n\n争论的现实意义在于：权力受法律约束是法治的最低要求，但它是否构成充分条件，取决于我们对法治采取形式还是实质的理解。多数现代宪制选择了折中路线：以形式约束为基础，同时通过基本权利与宪法审查加入实质限制。", "case": "英国1765年判决的恩蒂克诉卡林顿案（Entick v. Carrington, 19 Howell's State Trials 1030）是权力受法律约束的奠基性判例。政府官员依据国务大臣签发的搜查令，强行进入约翰·恩蒂克（John Entick）的住宅，搜查并扣押了他的文件与书籍。恩蒂克提起诉讼，主张官员的行为构成非法侵入。\n\n被告辩称，搜查令由国务大臣签发，因此行为具有合法性。法院由卡姆登勋爵（Lord Camden）主审，判决原告胜诉。卡姆登勋爵的名言是：对公民财产的每一次侵犯，无论多么轻微，都需要法律的支持；行政权力不能凭自身的权威创设新的权利。法院认定，国务大臣签发的搜查令没有法律依据，因为当时并无法律授权此类搜查，因此官员的行为构成非法侵入。\n\n本案确立了「没有法律依据的权力行使即非法」的原则，成为行政法上越权无效理论的经典来源。它也被 Wacks 等学者视为法治原则的早期司法确认——权力必须能在法律中找到自己的根据。", "caseAnalysis": "就恩蒂克案而言，事实层面是：官员持国务大臣签发的搜查令进入民宅搜查；争议焦点是：行政官员能否仅凭上司的命令侵犯公民财产，以及搜查令是否有法律依据。\n\n法律依据方面，法院坚持普通法的立场：任何对公民权利与财产的干预，必须有明确的法律授权。卡姆登勋爵强调，不能在法律之外为行政权力寻找根据。\n\n裁判理由的核心在于：国务大臣签发的搜查令本身不是法律，它不能创造新的权力；没有议会立法授权，这种搜查就是非法的。\n\n从权力受法律约束角度，本案确立了两个关键命题：其一，权力必须有法律依据（legality）；其二，权力不得越权（ultra vires）。行政官员不能以其职务或上级命令作为干预公民权利的充分理由。\n\n从法治角度，本案把「法律至上」从政治原则转化为司法可执行的规则：法院有权审查权力行使的法律根据，并宣告无根据的行为无效。这正是法治区别于「依法统治」的关键所在——要害在于法院能够独立检验是否真的有法可依，政府口称「依法」远远不够。\n\n理论意义上，本案说明权力约束需要具体的制度机制：独立的司法、可诉诸法院的权利救济，以及「任何权力都有法律边界」的坚定信念。它也提示我们，权力受法律约束需要在具体判例中逐步建构，抽象的口号撑不起法治传统。", "summary": "权力受法律约束是法治的核心命题，要求权力的存在与行使都有法律依据且不得越界，体现了戴雪的「法律至上性」。其制度机制包括法律依据原则、越权无效原则与司法审查，同时必须处理自由裁量带来的挑战。拉兹把法治定位为减少专断权力之害的「否定性德性」，准确概括了这一原则的实际功能；德沃金的政治完整性则要求权力所依据的原则本身正当。形式约束与实质约束之争，焦点在于「有法律依据」是否足够。恩蒂克案通过否定无法律依据的搜查，把法律至上转化为司法可执行的规则，说明权力约束需要独立司法与可诉救济作为支撑。", "furtherThinking": "1. 如果议会通过一条法律，授权政府任意拘留公民而无需说明理由，权力是否仍「受法律约束」？形式约束在此显露出什么局限？\n2. 现代行政离不开自由裁量。请设计几种把裁量纳入法治轨道的机制，并说明各自的优缺点。\n3. 恩蒂克案强调「任何权力干预都需法律根据」。这一原则在反恐或紧急状态下是否应有所松动？为什么？"}, "en": "Power Bound by Law", "level": "core", "tags": "权力约束, 法律至上, 宪政, 越权无效, 行政法", "source": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "id": "S1M5K5"}, "S1M5K6": {"title": "程序正当性", "EN": "Procedural Propriety and Due Process", "LEVEL": "core", "TAGS": "程序正当性, 正当程序, 自然正义, 听证权, 法治", "TERMS": "程序正当性（Procedural Propriety）::权力行使的过程应当公平、中立、公开并保障参与的要求；正当程序（Due Process）::要求国家在剥夺个人生命、自由或财产前遵循公平程序的宪法原则；自然正义（Natural Justice）::英美法中要求裁判者中立、听取双方意见的最低程序原则；听证权（Right to be Heard）::当事人在对其不利的决定作出前获得陈述机会的权利；程序中立（Impartiality）::裁判者不得有偏私、须平等对待双方的要求；内在道德（Internal Morality）::富勒提出的法律须满足的一般性、公开性、明确性等程序性要求", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Siems, Comparative Law, ch.7, ch.10", "terms": [{"term": "程序正当性（Procedural Propriety）", "def": "权力行使的过程应当公平、中立、公开并保障参与的要求"}, {"term": "正当程序（Due Process）", "def": "要求国家在剥夺个人生命、自由或财产前遵循公平程序的宪法原则"}, {"term": "自然正义（Natural Justice）", "def": "英美法中要求裁判者中立、听取双方意见的最低程序原则"}, {"term": "听证权（Right to be Heard）", "def": "当事人在对其不利的决定作出前获得陈述机会的权利"}, {"term": "程序中立（Impartiality）", "def": "裁判者不得有偏私、须平等对待双方的要求"}, {"term": "内在道德（Internal Morality）", "def": "富勒提出的法律须满足的一般性、公开性、明确性等程序性要求"}], "sections": {"coreQuestion": "一个行政机关可以不经听证就吊销你的执照吗？一份判决可以不说明理由就宣告你有罪吗？如果答案是否定的，理由何在？程序正当性（Procedural Propriety）关注的就是这类问题：权力在作出影响个人利益的决定时，必须遵循怎样的过程才算「正当」。它与正当程序（Due Process）、自然正义（Natural Justice）等概念紧密相连，是法治在程序维度的核心要求。本节要厘清程序正当性的内涵、富勒「内在道德」的程序基础、它与实体正义的关系，并通过美国最高法院的标志性判例说明程序保障如何具体落实。", "definition": "程序正当性（Procedural Propriety）是指权力行使的过程必须符合公平、中立、公开与参与的要求。它的核心命题是：结果的正确性不能为过程的专断辩护——即使决定结果碰巧正确，如果过程不公平，决定仍然具有正当性缺陷。\n\n程序正当性在英美法中有两个经典表述。其一是自然正义（Natural Justice），包含两条最低原则：「任何人不得做自己案件的法官」（nemo judex in causa sua），要求裁判者中立无偏私；「听取另一方的意见」（audi alteram partem），要求当事人获得听证机会。其二是正当程序（Due Process），美国宪法第五、第十四修正案把它提升为宪法性原则，要求国家在剥夺个人生命、自由或财产前遵循公平程序。\n\n在富勒（Lon Fuller）的理论中，程序正当性获得了系统化的哲学表达。Wacks 指出，富勒提出法律的「内在道德」（Internal Morality），列举了一般性、公开性、不溯及既往、明确性、不矛盾、可以被遵守、稳定性、官方行为与法律一致等要求。这些都是程序性的——它们关心法律是否具备「可被服从」的品质。Wacks 强调，富勒采取的是一种程序性自然法立场。\n\n程序正当性与实体正义有别：前者评价「决定如何作出」，后者评价「决定内容是否公正」。二者都是评价法律决定的必要维度，但侧重不同。", "history": "程序正当性的观念在英美法中有着深厚传统。英国的自然正义原则长期约束着裁判权与行政权，要求裁判者中立、当事人获得听证。这一传统随着英国殖民与宪法发展传播到美国，并被写入宪法修正案的正当程序条款。\n\n在美国，正当程序条款最初主要被理解为程序性保障——要求政府遵循公平的司法与行政程序。二十世纪，法院逐渐发展出「实体正当程序」（substantive due process）理论，用该条款保护某些不受政府任意干涉的基本权利，使正当程序同时具有程序与实体两个维度。\n\n富勒在二十世纪中期的工作，为程序正当性提供了理论系统化。Wacks 指出，富勒关注的是法律在程序上是否健全，并把这些要求称为法律的「内在道德」。他反对法律实证主义把法律与道德完全分离，主张法律本身就包含一套程序性的道德要求。\n\n比较法视角下，Siems 指出普通法与民法法系在程序风格上存在差异：普通法强调对抗制与程序公正，民法法系更侧重实体正确的裁判。但这并不意味着大陆法系忽视程序——Wacks 关于比较法的讨论提示，两大法系都发展出了约束权力滥用的程序机制，只是形式不同。", "principle": "程序正当性的逻辑可以从三层展开。\n\n第一，程序正当性保障人的尊严。让人在对其不利的决定中发言、被告知理由、由中立的裁判者审理，是对其作为理性主体的尊重。即使结果不利，一个被认真对待的人更容易接受决定——这就是程序正义的「正当化功能」。\n\n第二，程序正当性约束权力。公开、参与、中说理的要求，使权力行使暴露在可审查的目光下，减少任意与偏私。Wacks 引述的戴雪法治传统中，普通人同受普通法院管辖、法官中立无偏私，正是这一逻辑的体现。\n\n第三，程序正当性与实体正义的复杂关系。程序保障通常有助于实体正确——听证使裁判者获得更多信息，从而更可能作出正确决定。但二者也可能冲突：Wacks 在讨论法官道德时指出，一位严格遵守程序、适用不义法律的法官，仍未能做到实体正义；仅遵守形式正义原则「不足以达到道德上正确的门槛」。这说明程序正当性虽重要，却不是万能的。", "viewpoints": "富勒系统阐述了法律的内在道德，把公开、明确、不溯及既往等程序要求视为法律的内在德性。Wacks 强调，这是程序性自然法立场，但遵守这些要求并不保证法律内容正义。\n\n哈特（H. L. A. Hart）的「相同案件相同处理」是程序性标准的经典表述。Wacks 指出，哈特的标准获得广泛接受，但其局限在于无法回答判断同异的标准是否公正。\n\n德沃金（Ronald Dworkin）从政治完整性出发，主张政府须依普遍适用于所有人的原则治理，任意强制违反政治平等。这把程序正当性与实体性的平等价值联系起来。\n\n美国最高法院通过一系列判例，把正当程序具体化为可操作的保障。其中，1970年的戈德堡诉凯利案（Goldberg v. Kelly）是关于福利程序中听证权的标志性判决，确立了在终止福利给付前必须提供通知与听证的要求。", "comparison": "程序正当性与相邻概念的关系需要厘清。\n\n程序正当性与正当程序：前者是一般法理概念，后者是美国宪法上的具体原则；前者涵盖范围更广，后者具有宪法强制力。\n\n程序正当性与自然正义：自然正义是英美法中程序正当性的传统表述，包含中立与听证两条核心原则；程序正当性是更现代、更一般的概括。\n\n程序正当性与形式正义：形式正义强调规则一致适用，程序正当性除了中立与一致，还包括参与、听证与说理，范围更广。\n\n程序正当性与实体正当程序：前者关注过程公平，后者关注权利内容是否应受保护。二者同属正当程序条款的两个维度，但审查标准不同。", "debates": "程序正当性领域的核心争论，是程序保障与效率、程序正义与实体正义之间的权衡。\n\n效率一方认为：过度的程序要求会拖慢决策、增加成本，影响行政效率；在某些情况下（如紧急处置），事前听证并不现实；程序应当「够用就好」，而非越多越好。\n\n程序保障一方认为：程序是权力的合法化装置，缺乏程序的决定即便结果正确也缺乏正当性；程序成本是保障自由与尊严的必要代价；所谓「效率」不能成为剥夺听证权的理由。\n\n戈德堡案正体现了这场争论。案件涉及纽约市在终止福利给付前是否必须提供听证。市政府主张，事后听证已足够，事前听证会加重行政负担。最高法院则承认福利对受益人的极端重要性，要求在终止前提供通知与听证机会。\n\nWacks 关于「仅遵守程序不足以保证实体正义」的讨论，为争论增加了第三个维度：程序正当性虽有必要，却不能替代对法律内容的实体审视。一位遵守所有程序要求却适用不义法律的法官，仍然未做到正义。这意味着，完整的法治既需要程序正当性，也需要实体正当性的补充。", "case": "美国最高法院1970年判决的戈德堡诉凯利案（Goldberg v. Kelly, 397 U.S. 254）是程序正当性在行政法领域的里程碑案例。纽约市的社会福利部门依据行政程序，在未举行听证的情况下终止了对多名受益人的家庭援助（AFDC）给付。受益人主张，这种终止违反了宪法第十四修正案的正当程序条款。\n\n最高法院于1970年判决受益人胜诉。法院承认，福利给付不同于普通的政府恩惠（privilege），它关乎受益人的基本生存；在终止之前，必须提供充分的通知与一次「建设性的听证」（constructive hearing），包括口头陈述、提交证据与质证的机会。\n\n法院的推理强调了「政府恩惠」与「权利」区分的过时——在现代福利国家，公共援助是受益人的法定权利，其终止涉及重大利益，因此必须遵循正当程序。法院同时承认，正式听证会增加行政成本，但认为这一成本是保障程序公平的合理代价。\n\n本案把正当程序条款的适用范围从传统的司法程序扩展到行政福利领域，极大提升了程序正当性的制度地位。", "caseAnalysis": "就戈德堡案而言，事实层面是：行政机关未举行听证即终止福利给付；争议焦点是：终止福利前是否必须提供事前听证。\n\n法律依据是宪法第十四修正案的正当程序条款。裁判理由在于：福利给付关乎基本生存，属于受保护的利益；终止前的听证能够减少错误终止的风险，并保障受益人的参与权与尊严。\n\n从程序正当性角度，本案确认了听证权、通知权与陈述权的核心地位——这些正是自然正义「听取另一方意见」的具体化。法院明确拒绝以行政效率为由牺牲这些保障。\n\n从实体正义角度，本案同样具有意义：听证不仅本身是公平的，还能减少错误决定，从而改善结果。这与吉迪恩案的逻辑相通——程序保障与实体正确相互促进。\n\n从理论意义看，本案标志着正当程序从「司法程序专属」走向「覆盖所有影响重大利益的政府行为」。它说明程序正当性是权力行使必须支付的合法性成本，形式主义的繁文缛节是常见误解。Wacks 关于程序与实体关系的讨论，则提醒我们：听证保障虽必要，却不能替代对福利制度本身是否正义的实体评价。", "summary": "程序正当性要求权力行使过程公平、中立、公开并保障参与，其核心是自然正义的中立与听证原则，以及美国宪法上的正当程序条款。富勒的「内在道德」为程序正当性提供了系统的哲学表达，哈特、德沃金分别从形式标准与政治完整性角度作出贡献。程序正当性既保障人的尊严、约束权力，又通常有助于实体正确，但 Wacks 提醒，仅遵守程序不足以保证实体正义。戈德堡案把正当程序扩展到行政福利领域，确立了终止福利前必须提供通知与听证的要求，说明程序保障是权力合法性的必要成本。理解程序正当性，必须把它与实体正义结合起来，而非孤立看待。", "furtherThinking": "1. 在紧急状态（如公共卫生危机）下，事前听证可能不现实。程序正当性是否应当有所让步？如果让步，需要哪些替代性保障？\n2. 戈德堡案承认听证会增加行政成本。当程序成本与受益人的利益不成比例时，如何确定程序保障的适当程度？\n3. Wacks 说仅遵守程序不足以保证实体正义。请构思一个程序完美但实体不义的具体制度，并说明应当如何补足其实体维度。"}, "en": "Procedural Propriety and Due Process", "level": "core", "tags": "程序正当性, 正当程序, 自然正义, 听证权, 法治", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.4；Siems, Comparative Law, ch.7, ch.10", "id": "S1M5K6"}, "S1M5K7": {"title": "法治与人治的区别", "EN": "The Distinction Between Rule of Law and Rule of Man", "LEVEL": "fundamental", "TAGS": "法治, 人治, rule by law, 专断, 分权", "TERMS": "人治（Rule of Man）::权力行使主要取决于统治者个人意志而非普遍规则的治理方式；法治（Rule of Law）::法律居于至高地位、权力受法律约束的治理方式；依法统治（Rule by Law）::把法律仅当作统治工具、法律本身不受约束的治理方式；贤人政治（Philosopher-King）::柏拉图设想的由智慧统治者治理的理想政体；专断（Arbitrariness）::权力行使不受规则约束、取决于任意意志的状态；形式法治（Formal Rule of Law）::强调规则一般性与程序约束的法治观", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "terms": [{"term": "人治（Rule of Man）", "def": "权力行使主要取决于统治者个人意志而非普遍规则的治理方式"}, {"term": "法治（Rule of Law）", "def": "法律居于至高地位、权力受法律约束的治理方式"}, {"term": "依法统治（Rule by Law）", "def": "把法律仅当作统治工具、法律本身不受约束的治理方式"}, {"term": "贤人政治（Philosopher-King）", "def": "柏拉图设想的由智慧统治者治理的理想政体"}, {"term": "专断（Arbitrariness）", "def": "权力行使不受规则约束、取决于任意意志的状态"}, {"term": "形式法治（Formal Rule of Law）", "def": "强调规则一般性与程序约束的法治观"}], "sections": {"coreQuestion": "「法治优于人治」是现代政治的常识，但这个判断需要论证。为什么不由最聪明、最善良的人来统治？如果统治者真的是贤能之士，人治难道不比僵化的法律更灵活、更英明吗？另一方面，法律也可能被当作统治工具——「依法统治」与「法治」只差一个介词，含义却天差地别。本节要厘清法治与人治的核心区别，分析柏拉图式的贤人政治论证，区分法治与「依法统治」，并借助英国2019年的最高法院判例说明法治原则如何现实地约束最高行政权力。", "definition": "人治（Rule of Man）指权力行使主要取决于统治者个人意志，而非受普遍、稳定的规则约束的治理方式。其核心特征是：权力的边界不清晰、决定取决于统治者的判断与好恶、公民无法据规则预先安排行为。\n\n法治（Rule of Law）则指法律居于至高地位、权力受法律约束的治理方式。戴雪（A. V. Dicey）的经典框架包括法律至上、法律面前人人平等与宪法作为权利保障的结果三层含义。Wacks 在相关讨论中记录了这一框架，并引述拉兹（Joseph Raz）的判断：法治是一种「否定性德性」，它不能保证权力必然善良，但能减少专断权力之害。\n\n二者的核心区别可以概括为三点。其一，规则的普遍性：法治依靠抽象、普遍适用的规则；人治依靠针对具体情境的个人判断。其二，权力的可约束性：法治下权力有明确边界且可被审查；人治下权力边界模糊、难以约束。其三，行为的可预测性：法治下公民能据法律预期后果；人治下后果取决于统治者的意志。\n\n还需区分法治与「依法统治」（Rule by Law）。后者只要求统治者依据法律行事，但法律本身可以是压迫性的、可以任意修改，法律只是统治工具。法治则要求法律本身具备一般性、稳定性、公开性等品质，并真正约束权力。这一区分是理解二者关系的关键。", "history": "法治与人治之争，在西方思想传统中源远流长。柏拉图（Plato）在《理想国》中设想由「哲学王」（Philosopher-King）统治，认为只有真正掌握善的理念的智者才能作出最好的治理，法律作为一般规则反而难以应对具体情境的复杂性。这是人治（贤人政治）最经典的论证。\n\n亚里士多德（Aristotle）在《政治学》中提出了相反的论点：法治优于人治，因为法律凝聚了多数人的智慧，且不受个人欲望与偏见的支配；即使有优秀人才，权力也容易腐蚀人，而法律没有欲望。这一论证奠定了此后法治理论的基础。\n\n近代民族国家兴起后，法治成为反对专制王权的政治语言。英国《大宪章》（1215）、《权利法案》（1689）与戴雪的宪法理论，逐步确立了「王在法下」的传统。二十世纪极权主义的经验则使法治与人治的对立获得了新的紧迫性——当法律被极权政权当作统治工具时，「依法统治」与法治的区别变得生死攸关。\n\nWacks 记录的哈特与富勒论战、纽伦堡审判等议题，都处于这一思想史脉络之中：如何防止法律沦为赤裸的权力工具，是法治理论的核心关切。", "principle": "法治与人治的区别可以从三层展开。\n\n第一，规则治理与个人治理的认识论差异。法治依靠普遍规则，其优势在于规则的稳定性与可预期性，使无数陌生人能据此协调行为；人治依靠个人判断，其优势在于灵活性与情境适应性，但代价是不确定性。亚里士多德的论证正是：规则的普遍智慧胜过个人的易错判断。\n\n第二，权力约束的机制差异。法治通过分权、司法审查、基本权利等制度机制约束权力；人治缺乏这类机制，权力主要依靠统治者的自我约束。Wacks 记录的比较法材料显示，不同国家在权力约束的制度安排上各有特色，但都以「法律高于任意意志」为共同基础。\n\n第三，法治对人性弱点的防范。法治的核心洞见是：权力倾向于腐败，绝对权力绝对腐败。因此，不能把公民的命运寄托于统治者的品德。这与柏拉图对哲学王的信赖形成对照——法治的支持者承认优秀统治者的可能，但坚持制度性的约束更可靠。", "viewpoints": "亚里士多德主张法治优于人治，理由是法律凝聚集体智慧且不受欲望支配。这为法治提供了经典论证。\n\n戴雪从英国宪法实践出发，把法治概括为法律至上、法律面前人人平等与宪法作为权利保障的结果三层含义，使法治成为描述性且可操作的宪制原则。\n\n拉兹把法治定位为「否定性德性」——Wacks 指出，拉兹认为法治能减少行政权力的滥用，但不赋予法律独立的道德价值。这一审慎定位说明：法治不承诺好结果，但能防止最坏的专断。\n\n富勒（Lon Fuller）从程序角度强化法治：法律的「内在道德」使规则成为可被服从的对象，而人治下的任意命令不具备这种品质。\n\n批判者则提出反思：法治的形式要求可能被权力利用，使「依法统治」获得合法外衣。Wacks 记录的马克思主义者对法治的批评，正是提醒我们：形式上的法律约束未必等于实质的权力约束。", "comparison": "法治与人治的对照可以列表式地展开。\n\n在规则形态上，法治依靠普遍、抽象、稳定的规则；人治依靠具体、临时的个人命令。\n\n在权力边界上，法治下权力有明确法律边界、可被审查；人治下权力边界模糊、难以制约。\n\n在决策依据上，法治下决策以法律与先例为依据；人治下决策以统治者的判断与意志为依据。\n\n在公民地位上，法治下公民是享有权利的主体；人治下公民是治理的对象。\n\n法治与「依法统治」的区分同样重要：后者把法律当作工具，前者把法律当作约束。一个政权可以「有法可依」却仍是变相的人治——当法律可以任意修改、权力不受法律约束时，「依法统治」实质上就是人治的伪装。\n\n形式法治与实质法治的分歧也影响对这一问题的回答：形式法治认为只要规则普遍、稳定、公开，就已实现法治；实质法治进一步要求法律内容符合正义与人权。", "debates": "法治与人治的经典争论，是「贤人是否优于良法」。\n\n人治一方的论据：其一，法律是一般规则，无法预见一切具体情境，可能在某些情况下导致不公；其二，真正贤能的统治者能够因地制宜、作出比机械适用法律更明智的决定；其三，历史上有不少贤君良相的治理成就，说明人治并非必然糟糕。\n\n法治一方的论据：其一，亚里士多德指出，法律凝聚多人智慧，胜过个人判断；其二，权力容易腐蚀人，难以保证统治者永远贤能；其三，人治缺乏可预测性，公民无法据以规划生活；其四，即便出现贤人，其继任者未必贤能，制度比个人更可靠。\n\n这场争论在当代有一种折中形态：现代法治并不完全排斥人的判断——法官的自由裁量、行政机关的酌情权都是必要的一一但要求这些判断在法律框架内行使、接受程序与审查的约束。换言之，现代法治追求的是「规则之治下的合理裁量」，而非机械的规则自动售货机。\n\nWacks 记录的拉兹命题为争论提供了现代坐标：法治无法保证良政，但能减少专断之害。这是一种低调但坚实的辩护——它不承诺人治不可能有任何优势，但坚持法治在防范权力滥用上具有不可替代的制度价值。", "case": "英国最高法院2019年判决的R（米勒）诉首相案（R (Miller) v. The Prime Minister, [2019] UKSC 41）是法治约束最高行政权力的标志性案例。2019年，首相鲍里斯·约翰逊（Boris Johnson）在议会审议脱欧法案期间，建议女王将议会休会（prorogation）五周。这一决定被批评为规避议会监督、试图强行推进无协议脱欧。\n\n本案由英国最高法院11名法官组成合议庭审理。法院于2019年9月一致裁定：首相建议议会休会的决定违法（unlawful）并无效（null and void），因为在不具备正当理由的情况下，休会阻止议会履行其宪法职能，违反了宪法原则。法院指出，议会的立法权与监督权是宪法核心，行政权不得通过休会手段妨碍议会运作。\n\n这是英国历史上法院首次裁定首相的建议违法，具有重大的宪制意义。它表明，即便是最高行政首脑，其行使特权（prerogative power）也必须受法律与宪法原则的约束。", "caseAnalysis": "就米勒案而言，事实层面是：首相建议女王令议会休会五周；争议焦点是：这一建议是否合法，法院是否有权审查。\n\n法律依据方面，法院依据英国宪法基本原则——议会主权与议会的宪法职能。裁判理由在于：行政权行使特权时必须尊重议会履行宪法职能的能力；无正当理由的长期休会妨碍了议会的立法与监督权，因此违法。\n\n从法治与人治的角度，本案的意义在于：它否定了「行政首脑可以自行决定如何运用特权」的人治逻辑。首相的建议属于必须受法律原则约束的权力行使，不可审查的政治决定之说难以成立。法院通过宣告其无效，体现了「权力受法律约束」的法治核心。\n\n从司法审查角度，本案展示了独立司法作为法治守护者的功能——当政治过程本身出现障碍时，法院能够介入界定权力的宪法界限。这也呼应了戴雪的传统：普通人同受普通法律管辖，官员并无超越法律的特权。\n\n理论意义上，米勒案说明法治可以在具体制度中约束最高权力，抽象口号之说因此失效。它也提醒我们，法治与人治的区别并非「有法律／没法律」，而在于权力是否真正受法律的约束——即使是有法律依据的权力（如特权），也必须在法律划定的界限内行使。", "summary": "法治与人治的核心区别在于：法治依靠普遍、稳定、可预测的规则约束权力，人治则取决于统治者的个人意志。亚里士多德以「法律凝聚多人智慧且不受欲望支配」论证法治优于人治；柏拉图的哲学王设想则代表人治的经典论证。戴雪、拉兹、富勒分别从宪制框架、否定性德性与程序内在道德等角度深化了法治理论。法治还必须与「依法统治」区分——后者把法律当工具，前者把法律当约束。米勒案表明，即便最高行政首脑行使特权，也须受宪法原则约束并可被法院审查，这正体现了法治对权力的实际限制。理解这一区别，关键在于追问：权力是否真正受法律约束，而不仅仅是「有法可依」。", "furtherThinking": "1. 柏拉图哲学王的论证是否有说服力？如果真的出现一位智慧超群的统治者，法治是否应让他有更大的裁量空间？\n2. 「依法统治」（Rule by Law）与「法治」（Rule of Law）的中文译名只差一字，在实际制度中如何区分？请举例说明。\n3. 米勒案中，法院裁定首相建议违法。这是否意味着法院在介入政治？请结合司法独立与民主的关系讨论。"}, "en": "The Distinction Between Rule of Law and Rule of Man", "level": "fundamental", "tags": "法治, 人治, rule by law, 专断, 分权", "source": "Wacks, Understanding Jurisprudence, ch.4；Siems, Comparative Law, ch.10", "id": "S1M5K7"}, "S2M1K1": {"title": "自然法的思想起源", "EN": "The Intellectual Origins of Natural Law", "LEVEL": "core", "TAGS": "自然法, 思想史, 柏拉图, 亚里士多德, 斯多葛学派", "TERMS": "自然法（Natural Law）::以人的理性与本性为根据、具有普遍约束力的法律或正义原则；自然（Physis）::古希腊哲学中指事物本性、生长秩序，与人为约定相对；约定（Nomos）::城邦制定的人为法律与习俗；宇宙理性（Logos）::斯多葛学派中支配万物的普遍理性法则；目的论（Teleology）::以事物内在目的解释其本性与完善状态的思维方式", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.1；Siems, Comparative Law, ch.4", "terms": [{"term": "自然法（Natural Law）", "def": "以人的理性与本性为根据、具有普遍约束力的法律或正义原则"}, {"term": "自然（Physis）", "def": "古希腊哲学中指事物本性、生长秩序，与人为约定相对"}, {"term": "约定（Nomos）", "def": "城邦制定的人为法律与习俗"}, {"term": "宇宙理性（Logos）", "def": "斯多葛学派中支配万物的普遍理性法则"}, {"term": "目的论（Teleology）", "def": "以事物内在目的解释其本性与完善状态的思维方式"}], "sections": {"coreQuestion": "自然法（Natural Law）观念何以在西方思想中反复出现？它要回答的核心问题是：在城邦制定的法律之外，是否存在一种更高的、人应当遵守的正义秩序？如果法律与道德发生冲突，人应当服从哪一个？本节追溯自然法在古希腊、罗马的源头，厘清physis（自然）与nomos（约定）的古老对立，说明自然法如何从宇宙秩序的哲学思辨，逐步转化为可操作的法律与政治原则。理解这一起源，是把握阿奎那、格劳秀斯乃至富勒、菲尼斯全部理论的前提——他们的分歧，几乎都能在这一原初问题中找到雏形。", "definition": "自然法指一种诉诸人的理性与本性、主张其效力不依赖任何实在权威（制定机关）而自具正当性的规范体系。它包含三项基本主张。第一，存在客观的正义原则，这些原则可以被人的理性所发现，而非由任何立法者随意创制。第二，这些原则具有普遍性，对所有时代、所有民族的人一体适用，因而高于特定城邦或王国的制定法。第三，人间法律的正当性，最终要由它是否符合这些更高原则来检验。\n\n在古希腊语境中，这一思路表现为physis（自然）与nomos（约定／法律）的区分。physis指事物依其本性生长、运作的秩序，nomos则指城邦通过立法与习俗确立的人为规则。自然法支持者主张，合乎自然的秩序在价值上先于、也高于人为约定。需要留意，自然法传统内部并不统一：有的理论把自然法理解为一套具体的行为规范（如“不得杀人”），有的则把它理解为一种检验法律是否正义的理性标准（如富勒的程序性自然法）。二者都自称自然法，差别却很大。", "history": "自然法思想的诞生与古希腊城邦（polis）的政治经验密切相关。公元前五世纪前后，希腊城邦林立，各邦法律与风俗差异巨大，同时又彼此冲突。这种局面催生了一个问题：既然不同城邦的法律如此不同，是否存在某种超越各邦的、普遍有效的是非标准？智者学派（Sophists）中的不少人给出怀疑论回答，认为法律不过是强者利益的体现，约定优于自然。苏格拉底、柏拉图与亚里士多德则走向另一条路，坚持存在客观的、可由理性把握的正义。\n\n罗马共和国与帝国时期，这一思想被引入法律实践。罗马法学家面对不同民族适用不同法律现实，发展出万民法（ius gentium）概念，并把它与源于各民族共同理性的自然法（ius naturale）相联系。中世纪，自然法被基督教神学吸纳，阿奎那将其系统化为神学体系的一部分。近代民族国家兴起后，自然法又被格劳秀斯等人改造为世俗的国际法与社会契约理论基石。二十世纪，经历极权主义与两次世界大战，自然法以富勒、菲尼斯的新形态复兴。可见自然法史是一部不断被重新解释的思想史。", "principle": "自然 law 的论证结构可拆为三层。\n\n第一层是目的论（Teleology）的宇宙观。古希腊人相信万物各有其目的（telos），橡树的目的在长成橡树，人的目的在过一种有德性的、幸福的生活。正义因此成为人实现其本性的内在要求，任意性在这里没有位置。亚里士多德在《政治学》中提出，人天生是政治动物，城邦共同体使人得以实现善的生活；法律若背离这一目的，就失去正当性。\n\n第二层是理性可发现性原则。自然法是人运用理性反思人性、社会与世界秩序的结果，启示或神秘体验的产物之说与之相去甚远。这使自然法具有可论辩、可批判的品格——任何人都可以援引理性检验现行法律，而不必诉诸权威。斯多葛学派把这种理性称为宇宙理性（Logos），认为它弥漫于万物之中，人因分有理性而与万物同属一个宇宙共同体。\n\n第三层是效力层级的观念。自然法主张存在一个规范等级：人法（human law）从属于自然法，自然法又从属于永恒法（eternal law，见阿奎那一节）。当下位法与上位法冲突时，下位法的效力受到质疑。这一层级结构是后来“恶法非法”命题的思想土壤。不过须注意，早期自然法思想主要是哲学与政治思辨，尚未形成像后世那样精密的法律效力理论，其价值更多在于确立“法律要接受正义检验”这一根本方向。", "viewpoints": "柏拉图在《理想国》中借苏格拉底之口追问“正义本身是什么”，主张存在超越个别城邦法律的正义理念（Form of the Good），现实法律应当分有这一理念。他倾向于认为，未经哲学论证的法律只是意见，唯有理性洞见的正义才是真理。\n\n亚里士多德在《尼各马可伦理学》中区分自然正义与法律正义：自然正义在各地皆有效，不因人们认可与否而改变；法律正义则源于城邦的具体规定，可以变动。他承认城邦法律的权威性，但强调法律必须以促进共同善为目的，并将『良法』与『良政』相联系。\n\n斯多葛学派（芝诺、克吕西波、罗马的西塞罗、塞内卡）把自然法推向普遍主义。西塞罗在《国家篇》中留下著名表述：真正的法律是正当的理性，它永恒不变，对所有民族、所有时代有效，违背它的元老院决议或人民法皆无效。这一论述把physis与nomos的对立提升为系统的自然法命题。\n\n罗马法学家乌尔比安（Ulpian）把法学界定为“神事与人事的知识、正义与不义的区分”，并把自然法界定为自然教给一切动物的规则；《查士丁尼法学总论》则把自然法、万民法、市民法并列，成为后世理解罗马法分类的通行框架。", "comparison": "自然法与法律实证主义（Legal Positivism）的分野，在此已见端倪。自然法把法律的正当性系于其内容是否符合正义；实证主义则把“是不是法律”系于其来源是否合法。前者关心法律应当是什么，后者关心法律实际上是什么。二者不是简单的价值对立：自然法也要谈法律的有效与无效，实证主义也要谈法律的道德批判，分歧在于用哪个标准来界定“法律”这一概念。\n\n自然法与法律现实主义（Legal Realism）同样存在张力。现实主义把注意力转向法官实际做法，倾向于怀疑规则能决定案件结果；自然法则相信理性可以发现客观的正义标准，并据此批评现实中的法律。可以说，前者对规则的决定力持怀疑态度，后者对理性的规范性力量保持信心。\n\n在自然法传统内部，也有“强自然法”与“软自然法”之别（Wacks §2.7）。强版本主张不符合正义的规则根本不是法律；软版本只主张不正义的法律在道德上有缺陷、可能丧失服从义务，但仍可称为法律。理解这一区别，对把握后文哈特与富勒的论战十分关键。", "debates": "自然法思想史上第一场根本争论，是physis与nomos之争。智者学派代表如普罗泰戈拉主张“人是万物的尺度”，认为法律与道德只是人为约定，随城邦与时代而变；特拉西马库斯在《理想国》中更直言正义不过是强者的利益。苏格拉底与柏拉图则反驳：若法律只是强者的工具，就不存在真正的正义，城邦也将失去共同生活的根基。亚里士多德采取较温和的立场：他承认约定性法律的存在与必要，但坚持自然正义构成城邦法律的正当性边界。\n\n这一争论的深层结构是：法律的正当性究竟来自程序上的制定（谁有权制定、如何制定），还是来自内容上的正义（制定了什么）。两千年来，自然法与实证主义之争不断重演这一结构。值得注意的是，双方的立场并不总是漫画式对立：亚里士多德既承认法律的制定性，又要求法律指向共同善；近代实证主义也不否认法律应当追求正义，只是拒绝把正义作为“是不是法律”的判断标准。\n\n另一场争论关乎自然法能否脱离神学。阿奎那把自然法纳入神的永恒法秩序；格劳秀斯则提出，自然法的有效性甚至在无神论假设下也成立（etiamsi daremus）。这一“世俗化”转向，使自然法成为近代国际法与人权理论的通用语言，也埋下了当代菲尼斯与世俗自由主义者争论的种子。", "case": "一个体现自然法思维的现实案例，是二战后国际法对“反人类罪”的追诉。纽伦堡审判（1945—1946）中，辩护方提出：被告行为符合当时德国的制定法，依“法无明文不为罪”原则不能定罪。检方则诉诸更高层级的正义原则，主张某些行为即使在形式上合乎国内法，也因严重违背文明社会的基本准则而构成犯罪。《联合国宪章》与《世界人权宣言》（1948）进一步把若干基本权利确立为超越国界、超越当时当地法律的普遍标准。\n\n这一案例把“法律与正义冲突时如何裁判”的抽象问题变成了现实的制度实践：国际社会实际上采纳了某种自然法式立场，即承认存在最低限度的、不因国家法律而消失的人权标准。", "caseAnalysis": "就纽伦堡审判而言，事实是：被告以执行本国法律为辩护理由；争议焦点在于，符合制定法的行为能否因违背更高正义原则而被定罪。从自然法的层级结构看，制定法处于规范等级的下位，严重违背基本正义的法律丧失正当性，不能为暴行提供抗辩。从裁判理由看，法庭实际上区分了“形式合法的权威”与“正当的权威”，把后者系于文明社会公认的最低正义标准。\n\n这一案例的理论意义在于，它展示了自然法思维在现实中的制度形态：当国内法与普遍人权发生冲突时，国际法实践倾向于承认某种超越国家法的效力层级。不过，自然法的批评者也会追问：谁来判定哪些原则属于这种“更高标准”？若不同文明、不同法域对正义的理解不同，诉诸自然法会不会导致法律的不确定性？这一追问，正是自然法理论必须持续回应的难题。", "summary": "自然法起源于古希腊physis与nomos的区分，其思想内核是相信存在可被理性发现、普遍有效、高于人定法的正义秩序。柏拉图以理念论为基础，亚里士多德以目的论与共同善为基础，斯多葛学派以宇宙理性（Logos）为基础，共同奠定了自然法的基本框架。罗马法学家把它转化为ius naturale与ius gentium的法律分类，中世纪神学把它纳入永恒法体系，近代格劳秀斯把它世俗化为国际法与社会契约的理论基础。自然法与实证主义的分歧集中在正当性来源问题上：内容正义还是制定来源。这一分歧在“恶法”问题上最为尖锐，并在纽伦堡审判等现实实践中获得制度表达。", "furtherThinking": "1. 如果不同文化对“正义”的理解存在深刻差异，诉诸自然法能否提供确定的裁判标准？还是会掩盖特定群体的价值偏好？\n2. 亚里士多德承认自然正义与法律正义并存，这对“恶法非法”的强自然法命题构成支持还是限制？\n3. 国际人权法把某些权利视为超越国界的普遍标准，这在何种意义上延续了斯多葛学派的世界公民观念？"}, "en": "The Intellectual Origins of Natural Law", "level": "core", "tags": "自然法, 思想史, 柏拉图, 亚里士多德, 斯多葛学派", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.1；Siems, Comparative Law, ch.4", "id": "S2M1K1"}, "S2M1K2": {"title": "古希腊与罗马自然法思想", "EN": "Natural Law Thought in Ancient Greece and Rome", "LEVEL": "core", "TAGS": "自然法, 亚里士多德, 斯多葛学派, 罗马法, 万民法", "TERMS": "自然正义（Natural Justice）::依事物本性而有效、不因城邦规定而改变的正义；法律正义（Legal Justice）::由城邦制定、可随时代与地方变化的正义；万民法（Ius Gentium）::罗马法中据称由各民族共同理性形成、适用于所有民族的法律；市民法（Ius Civile）::罗马城邦专属、仅适用于罗马公民的法律；自然法（Ius Naturale）::罗马法中被认为由自然本身确立、动物与人类共同具有的规则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.1；Siems, Comparative Law, ch.4", "terms": [{"term": "自然正义（Natural Justice）", "def": "依事物本性而有效、不因城邦规定而改变的正义"}, {"term": "法律正义（Legal Justice）", "def": "由城邦制定、可随时代与地方变化的正义"}, {"term": "万民法（Ius Gentium）", "def": "罗马法中据称由各民族共同理性形成、适用于所有民族的法律"}, {"term": "市民法（Ius Civile）", "def": "罗马城邦专属、仅适用于罗马公民的法律"}, {"term": "自然法（Ius Naturale）", "def": "罗马法中被认为由自然本身确立、动物与人类共同具有的规则"}], "sections": {"coreQuestion": "古希腊与罗马如何把“自然”与“法律”的关系问题，发展成一套影响后世两千年的法理框架？本节要厘清三组概念：亚里士多德对自然正义与法律正义的区分、斯多葛学派的宇宙理性与世界公民观念、罗马法学家对自然法／万民法／市民法的三分。它们的意义不只在思想史：当今天的国际法学者主张存在超越国界的普遍标准，或当比较法学者讨论不同法律传统是否有共同底線时，使用的仍是这套古老语汇。本节的任务是把这些概念的原始含义、彼此关联与内在张力讲清楚。", "definition": "亚里士多德在《尼各马可伦理学》第五卷中，把正义（dikaion）区分为自然正义与法律正义。自然正义（Natural Justice）指其效力来自事物本性、在各地都相同的正义；法律正义（Legal Justice）指最初由城邦规定、可以随时间和地点改变的规则。这一区分奠定了自然法的基本语法：有一部分正义不依赖人的制定而有效。\n\n斯多葛学派（Stoicism）把自然法建立在宇宙理性（Logos）之上。Logos既是宇宙运行的法则，也是人应当遵循的理性。由于人人分有理性，所有人—无论希腊人或野蛮人、自由人或奴隶—都同属一个世界城邦（cosmopolis）。这一世界公民观念，是近代国际法与个人权利观念的重要源头。\n\n罗马法学家把希腊哲学转化为可操作的法律分类。乌尔比安（Ulpian，约170—223）把自然法界定为“自然教给一切动物的规则”，并把法学定义为“神事与人事的知识、正义与不义的区分”。盖尤斯（Gaius）《法学阶梯》开篇即区分市民法（Ius Civile）与万民法（Ius Gentium）：前者是罗马民族特有的法，后者是自然理性在所有民族中确立的法。《查士丁尼法学总论》（Institutes, 533）继承这一框架，把自然法、万民法、市民法并列为三种法。", "history": "公元前四世纪至公元前三世纪，希腊城邦制度由盛转衰，马其顿与后来的罗马成为主导力量。政治共同体边界的扩大，使“不同民族适用不同法律”成为日常经验。亚里士多德对自然正义与法律正义的区分，正是对城邦法律相对性的哲学回应：既然各邦法律不同，就必须说明哪些正义原则是普遍的。\n\n斯多葛学派兴起于希腊化时期，其世界公民观念是对城邦共同体瓦解的哲学回应：当政治共同体不再能成为忠诚的唯一对象，哲人转向一个以理性为基础的普遍共同体。罗马征服地中海世界后，这一观念为统治多民族帝国提供了思想工具。\n\n罗马法学家面对的则是实际的司法问题：帝国境内不同民族、不同身份的人适用不同法律，罗马公民法（ius civile）的严格形式主义难以应对跨民族交易。万民法（ius gentium）概念由此发展出来，作为处理外来人与罗马人之间关系的较灵活法律。值得注意的是，万民法在罗马法中的原初含义更接近“各民族共有的实在法”，而非纯粹的自然法理念，两者在历史中逐渐合流，这一细节对准确理解罗马法至关重要。", "principle": "古罗马三种法的划分可整理为一个由普遍到特殊的层级。\n\n第一层，自然法（ius naturale）：由自然本身确立，被认为不仅适用于人类，也适用于动物。乌尔比安的表述—自然教给一切动物的规则—至今常被引用。这一概念带有强烈的目的论色彩：自然法体现的是自然赋予的本能与理性秩序。\n\n第二层，万民法（ius gentium）：由各民族共同理性确立，为所有民族所遵守。它与自然法的区别在于，万民法是人类社会的产物，而自然法在更原初的意义上属于自然本身。但在罗马法学家的实际表述中，两者常被认为内容重合，界限并不清晰。\n\n第三层，市民法（ius civile）：特定城邦或民族为自己制定的法律，仅对其成员有效。它最具体、最易变，也最可能偏离自然理性。\n\n这三层的关系，为后来的自然法理论提供了两个关键要素。其一是效力等级观念：越靠近自然，正当性越高。其二是普遍性与特殊性的张力：市民法的有效性限于特定共同体，而自然法与万民法主张普遍适用。这一张力在近代转化为国际法与国内法的关系问题，在当代则转化为全球正义与法律多元主义的问题。", "viewpoints": "亚里士多德的核心贡献在于为自然法提供了目的论框架。他认为自然的万物皆有目的（telos），人的目的在过有德性的生活，城邦的目的在促进共同善（common good）。正义作为“给予每人所应得”的德性，其内容由人的本性与共同善决定。他明确区分自然正义与法律正义，并承认法律正义虽可变动，却仍应尽可能接近自然正义。值得注意的是，亚里士多德并未发展出一套“恶法非法”的激进命题，他总体上仍主张服从城邦法律，只有在法律严重违背共同善时才保留批判空间。\n\n斯多葛学派的核心贡献在于普遍主义。克吕西波（Chrysippus）等早期斯多葛学者把Logos理解为贯穿宇宙的理性法则，人因分有Logos而与神、与他人同属一个理性共同体。罗马时期的西塞罗（Cicero）在《国家篇》中给出经典表述：真正的法律是正当的理性，永恒不变，对所有民族与时代有效；元老院决议或人民法若违背它，便不具法律的性质。塞内卡（Seneca）则强调人人皆具理性灵魂，奴隶与自由人在人性上平等。\n\n罗马法学家的贡献在于制度化。盖尤斯、乌尔比安、保罗（Paulus）等人通过法学阶梯与法学答复（responsa）汇编，把抽象的自然法理念转化为法律教育与司法实践中的分类工具。查士丁尼《法学总论》以『正义是给予每个人其应得之物的坚定而永恒的意志』开篇，把自然法、万民法、市民法的三分确立为法学教科书的正统框架。", "comparison": "希腊自然法与罗马自然法的差别值得重视。希腊自然法主要是哲学思辨：它关心正义的理念、人的目的、宇宙的秩序，带有强烈的形而上学与实践哲学色彩。罗马自然法则更多是法律技术：法学家关心的是分类、法律效力、司法管辖与法律适用，自然法概念被纳入实在法的体系之中。可以说，希腊人提供了自然法的灵魂，罗马人提供了它的法律骨架。\n\n在自然正义与法律正义的关系上，亚里士多德与后来的强自然法论者之间存在差别。亚里士多德承认法律正义的独立存在与可变性，并未主张不正义的制定法当然无效；强自然法命题—严重不正义的法律不是法律—是后世（尤其经阿奎那与二战后自然法复兴）才被明确化的。把“恶法非法”直接归给亚里士多德，是一种时代错置。\n\n斯多葛学派与罗马法学家对自然法的理解亦有差异。斯多葛学派的自然法与Logos、世界公民相连，带有强烈的伦理与政治平等含义；罗马法学家虽然接受了自然法概念，却把它主要用于法律分类，其平等含义在奴隶制现实面前大打折扣—乌尔比安一边说自然法教给一切动物，一边承认奴隶制作为万民法制度的存在。这一矛盾提示：自然法的平等承诺与其在现实法律中的落实之间，始终存在落差。", "debates": "古代自然法思想中的核心争论，是自然（physis）与约定（nomos）何者优先。智者学派的一些代表（如卡利克利斯，见柏拉图《高尔吉亚篇》）主张自然意味着强者统治，法律只是弱者约束强者的约定；普罗泰戈拉则主张感觉与意见的相对性。苏格拉底—柏拉图传统反驳说，若正义只是约定，就不会有对法律的真诚批评，哲学追问本身也失去意义。\n\n第二场争论关乎自然法与奴隶制。斯多葛学派从人人分有理性出发，强调人在本性上平等；然而罗马法与罗马社会广泛承认奴隶制，万民法被当作奴隶制的正当性依据之一。这一张力在古代世界无法彻底化解，却为近代自然法思想家（如洛克）批判奴隶制、为现代人权观念否定奴隶制提供了概念资源。\n\n第三场争论关乎自然法与公民法的关系。西塞罗式的强自然法命题声称违背自然法的制定法无效；但在罗马法的实际运作中，市民法作为有效的法律体系持续运行。如何在承认制定法效力的同时保留对它的正义批判，这一直是自然法理论必须处理的难题，也是后来阿奎那区分“法律的腐败”与“法律本身”所要解决的议题。", "case": "《世界人权宣言》（Universal Declaration of Human Rights, 1948）第1条宣告“人人生而自由，在尊严和权利上一律平等”，第2条确认这些权利对所有民族、所有国家普遍适用。这一表述在语调上明显承袭了斯多葛学派的世界公民观念与西塞罗式的普遍法语言：某些尊严与权利不依赖任何特定国家的法律而属于所有人。\n\n另一个更具法学技术意味的例子，是国际法院在“科索沃咨询意见”（International Court of Justice, Advisory Opinion on Kosovo's Declaration of Independence, 2010）中对国际法与国内法关系的处理。法院区分了国际法是否禁止独立宣言与单方面宣布独立是否违反塞尔维亚国内宪法的问题，指出国际法并不禁止后者。这一区分—国际法层面与国内宪法层面各自具有独立的效力判断—正是罗马法中不同法律层级并存观念的现代回响。", "caseAnalysis": "以《世界人权宣言》为例，事实是：二战后国际社会以普遍人权语言宣告一系列超越国界的权利标准；争议焦点在于，这些权利是否只是特定历史语境下的政治共识，还是根植于人之为人的本性。从斯多葛传统看，普遍人权之所以能对所有民族有效，是因为所有人同具理性与尊严，这构成超越国界的共同基础。从裁判／构造理由看，《宣言》采用“人人生而…”的普遍命题形式，而非“某国公民享有…”的特殊授权形式，这一措辞本身即延续了自然法的普遍主义语法。\n\n这一案例的理论意义在于，它展示了古代自然法概念在现代制度中的延续与变形。但批评者会指出：人权的普遍表述背后，仍可能隐含特定文化对“尊严”“自由”的理解。这提示我们，古代斯多葛学派的普遍主义既是人类平等观念的宝贵资源，也需要警惕把某一种生活方式包装成“自然”的普遍要求。理解这种双重性，是成熟把握自然法传统的关键。", "summary": "古希腊与罗马自然法思想完成了从哲学思辨到法律概念的转化。亚里士多德以目的论区分自然正义与法律正义，确立超验正义标准的存在；斯多葛学派以宇宙理性（Logos）与世界公民观念，把自然法普遍化、伦理化；罗马法学家通过自然法（ius naturale）、万民法（ius gentium）、市民法（ius civile）的三分，把抽象理念转化为可操作的法律分类体系。三者共同确立了效力等级、普遍适用、理性可发现三项自然法要素。同时，这一传统内部存在张力：普遍平等承诺与奴隶制现实并存，希腊的哲学思辨与罗马的法律技术取向各异，强自然法命题与实在法实践之间保持距离。这些张力成为后世自然法理论持续处理的议题。", "furtherThinking": "1. 乌尔比安一边宣称自然法教给一切动物，一边承认奴隶制的正当性，这种矛盾告诉我们关于自然法概念的什么？\n2. 罗马万民法原本接近“各民族共有的实在法”，后来却被等同于自然法，这一转变对国际法的正当性论证有何影响？\n3. 亚里士多德对自然正义与法律正义的区分，能否为当代“宪法审查是否应诉诸自然法”的争论提供启示？"}, "en": "Natural Law Thought in Ancient Greece and Rome", "level": "core", "tags": "自然法, 亚里士多德, 斯多葛学派, 罗马法, 万民法", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.1；Siems, Comparative Law, ch.4", "id": "S2M1K2"}, "S2M1K3": {"title": "托马斯·阿奎那", "EN": "Thomas Aquinas and Natural Law", "LEVEL": "core", "TAGS": "自然法, 阿奎那, 永恒法, 人法, 恶法非法", "TERMS": "永恒法（Eternal Law）::上帝支配整个宇宙的理性计划；自然法（Natural Law）::理性生物对永恒法的分有，以实践理性原则为内容；人法（Human Law）::由人类权威制定的实证法律，其约束力源于自然法；神法（Divine Law）::通过《圣经》启示给予的、高于人法与自然法的神圣法律；分有（Participation）::阿奎那用来说明理性生物共享永恒法秩序的核心概念；实践理性（Practical Reason）::关于人应当如何行动、追求何种善的理性能力", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.1.2, §2.2；Hart, The Concept of Law, Postscript", "terms": [{"term": "永恒法（Eternal Law）", "def": "上帝支配整个宇宙的理性计划"}, {"term": "自然法（Natural Law）", "def": "理性生物对永恒法的分有，以实践理性原则为内容"}, {"term": "人法（Human Law）", "def": "由人类权威制定的实证法律，其约束力源于自然法"}, {"term": "神法（Divine Law）", "def": "通过《圣经》启示给予的、高于人法与自然法的神圣法律"}, {"term": "分有（Participation）", "def": "阿奎那用来说明理性生物共享永恒法秩序的核心概念"}, {"term": "实践理性（Practical Reason）", "def": "关于人应当如何行动、追求何种善的理性能力"}], "sections": {"coreQuestion": "阿奎那如何把自然法从一个哲学观念改造为一套严密的法律等级体系？他提出的四种法律（永恒法、自然法、人法、神法）各自处于什么位置、彼此如何关联？他与“恶法非法”（lex iniusta non est lex）这一命题究竟是什么关系？本节要说明：阿奎那的自然法理论既把法律的根基追溯到神的理性，又通过实践理性与共同善的概念，为世俗的法律批判保留了空间。澄清这些细节，有助于避免把阿奎那简单化为一个“教会权威代言人”。", "definition": "阿奎那（Thomas Aquinas, 1225—1274）是多明我会（Dominican）神学家，其法律理论集中见于《神学大全》（Summa Theologica）第二部第二集。他把法律（lex）一般地界定为“由关心共同体的理性存在者向共同体颁布的、以共同善为目标的理性的命令”。这一界定包含四个要素：理性、颁布、共同体、共同善。\n\n阿奎那区分四种法律。永恒法（Eternal Law）是上帝支配整个宇宙的理性计划，是一切法律的终极根源。自然法（Natural Law）是理性生物对永恒法的分有（participation），其内容由实践理性的基本原则构成，人借以判断行为是否合乎理性。人法（Human Law）是人类权威为特定共同体制定的实证法律，其约束力来自自然法。神法（Divine Law）则是通过《圣经》启示给予人的神圣法律，用以补充自然法与人法的不足。\n\n分有（participatio）是理解阿奎那的关键。菲尼斯（John Finnis）指出，阿奎那所谓分有聚焦于因果关系：某性质之所以存在于一物之中，是因为它被具有类似性质的更高原因所造成；普通的“部分分享整体”之意在此并不适用。自然法之所以为法，正因为它源自永恒法这一更高的理性秩序。", "history": "十三世纪的欧洲，亚里士多德的著作经阿拉伯世界重新传入，对基督教神学产生巨大冲击。阿奎那的历史功绩，在于把亚里士多德的伦理学、政治学与目的论，系统地整合进基督教神学框架。他接受了亚里士多德关于人天生趋向共同善、实践理性可辨别善恶的基本立场，同时把法律秩序的终极根基置于上帝的永恒法之中。\n\n当时的欧洲，教会法与世俗法并存，皇帝、教皇、封建领主各自主张立法权威。阿奎那的四分法为这一复杂局面提供了秩序：所有人间权威的立法权，都从属于更高的理性与神圣秩序。人法若背离自然法，就丧失其作为“法”的充分正当性。这一理论既为世俗法律的权威提供了神圣基础，也为批判不正义的法律划出了边界。\n\n阿奎那的影响远超中世纪。菲尼斯在二十世纪重新阐释阿奎那，强调其理论中的实践理性与基本善思想，使阿奎那成为当代自然法复兴的重要资源。Wacks 指出，阿奎那自然法理论中关于人法约束力源于自然法的主张，是理解其法律观的核心命题。", "principle": "阿奎那的自然法体系可拆为四个层次逐层理解。\n\n第一层是等级结构。永恒法居于顶端，是宇宙的理性秩序；自然法是理性生物对永恒法的分有；人法由自然法推导而来；神法从外部补充前三者。这一结构的关键在于：下位法的效力来自上位法。人法之所以能约束人，是因为它分有了自然法的理性，而自然法又分有了永恒法。\n\n第二层是实践理性的认识论。自然法的内容靠人的实践理性对人性、善与基本价值的反思而获得，神秘启示在此没有位置。阿奎那区分第一原则与次级原则：第一原则（如“善应当被追求和实行，恶应当被避免”）是自明的、不可证明的；次级原则则由第一原则经由推理得出，适用于具体情境，可能因环境而难以判断。\n\n第三层是共同善的指向。阿奎那强调，法律必须以共同善（common good）为目标。法律若沦为统治者私人利益的工具，就背离了法律的本质。这一共同善的指向，是区分真正的法律与“法律的腐败”的标准。\n\n第四层是不正义法律的处理。这是阿奎那理论中最微妙的部分。他指出，人法若违背自然法，就不再具有法律的约束力，反而成为“法律的腐败”（corruptio legis）。但 Wacks 特别提醒，广为流传的命题“恶法非法”（lex iniusta non est lex）严格说来并非阿奎那本人的原话。阿奎那的实际论述更接近：违背自然法的法律在道德上有缺陷，丧失被服从的道德权威，其在严格意义上是否还能称为“法”，需要细致辨析。", "viewpoints": "阿奎那的核心主张可以概括为五点。\n\n其一，自然法是永恒法在理性生物中的分有，其内容是实践理性的原则。Wacks 引述阿奎那：自然法的内容“包括实践理性的原则，人的行动据此被判断为合理或不合理”。正是这一理性特征，使自然法配称为“法”。\n\n其二，自然法的基本善。阿奎那认为，自然法要求人追求某些基本善，如生命、繁殖、知识、社会交往等。人能凭理性辨认这些善，并据以判断行为。菲尼斯后来将其发展为“七种基本的人类繁盛形式”。\n\n其三，人法的效力来自自然法。阿奎那明确主张，人法（posited human law）的约束力源于自然法；因此，人法必须与自然法一致，才能获得正当性。\n\n其四，对“恶法”的细致处理。阿奎那承认某些法律在极端情况下可能不具约束力。但他并未简单宣布一切不正义的法律“不是法律”。他区分了不同情形：有些法律因违背自然法而完全丧失法的性质，有些则只是在特定方面偏离正义。Wacks 指出，把“恶法非法”直接当作阿奎那的原话，是一种过度简化。\n\n其五，法律与道德的关系。阿奎那主张法律与道德存在内在关联，但并非简单等同。法律关心的是外在行为与共同秩序，道德关心的是内在意向与灵魂的善；法律可以容忍某些道德上不完美但不严重破坏共同善的行为。", "comparison": "阿奎那与亚里士多德的关系是继承与改造。两者都以目的论与共同善为基础，都主张法律应指向人的完善。差别在于：亚里士多德的自然法停留在哲学与政治层面，阿奎那则把它纳入神学体系，以永恒法为终极根基，并发展出四分的法律等级。\n\n阿奎那与近代法律实证主义形成鲜明对照。实证主义（尤其奥斯丁与拉兹）主张，法律的存在取决于社会来源，与道德无关；阿奎那则主张，人法的效力最终系于自然法。这一对立在哈特与富勒的论战中重新爆发。不过，阿奎那与极端自然法论者之间也有差别：他保留了法律与道德的分层，一切不完美的法律都无效的主张并非他的立场。\n\n阿奎那与当代菲尼斯之间既有承继也有差异。菲尼斯继承阿奎那的实践理性与基本善思路，但刻意淡化其神学形而上学色彩，强调自然法可以从世俗的、实践理性的角度加以阐明。菲尼斯甚至批评把“恶法非法”归于阿奎那是一种误读，主张阿奎那的实际立场比这一口号要精致得多。", "debates": "围绕阿奎那的第一场争论，是“恶法非法”命题的归属与含义。传统上，这一命题被归到阿奎那名下，并在二战后被用来批判纳粹法律。但 Wacks 依据菲尼斯的研究指出，阿奎那本人似乎从未明确提出这一命题。阿奎那更接近的说法是：违背自然法的法律丧失道德权威，人没有服从的义务，他称这类法律为“法律的腐败”。这一区分意义重大：它把“法律在道德上是否正当”与“法律在概念上是否存在”两个问题分开处理，为后来实证主义与自然法的争论留下了微妙的中间地带。\n\n第二场争论关乎自然法是否依赖神学。阿奎那的自然法是永恒法在人身上的分有，其终极根基是神的理性。菲尼斯在当代重释阿奎那时，强调实践理性与基本善的自明性，试图使自然法摆脱对神学前提的依赖。批评者则认为，菲尼斯的做法背离了阿奎那的本意，抽去了自然法的形而上学根基。\n\n第三场争论关乎自然法内容的确定性。阿奎那区分第一原则与次级原则，承认次级原则在具体适用中可能模糊不清。批评者由此发问：如果自然法的内容需要具体化、可能出错，它如何能作为评判人法的确定标准？这一问题在当代多元社会中尤为尖锐。", "case": "一个可用于检验阿奎那框架的现实例子，是战后德国处理纳粹时期法律的“拉德布鲁赫公式”（Radbruch Formula）。古斯塔夫·拉德布鲁赫（Gustav Radbruch）在二战后提出：当制定法与正义的矛盾达到“不可容忍”的程度时，该法律即丧失法的性质，法官有义务拒绝适用。这一公式在德国联邦宪法法院与联邦最高法院的若干判决中被援引，用于处理纳粹时期依据当时有效法律实施的行为。\n\n从阿奎那的框架看，拉德布鲁赫公式明显带有自然法色彩：它承认存在高于实证法的正义标准，极端不正义的法律丧失约束力。但两者也有差别：阿奎那的出发点是永恒法与自然法的等级秩序，拉德布鲁赫则是在实证主义传统内部，对法律确定性原则作出的例外性修正。Wacks 指出，哈特与富勒在1958年的论战中，都曾讨论拉德布鲁赫的立场（见《哈佛法律评论》71卷）。", "caseAnalysis": "就拉德布鲁赫公式而言，事实是：战后德国法院面对依当时有效法律实施的暴行，需要决定是否承认这些法律的效力；争议焦点在于，法律的安定性（法的确定性）与正义，何者在极端情况下优先。从阿奎那的角度看，严重违背自然法的“法律”丧失道德权威，这为拒绝适用提供了正当性论证。从裁判理由看，拉德布鲁赫公式设定了极高的门槛—只有“不可容忍”的矛盾才触发例外，以避免法官凭个人道德偏好随意否定法律。\n\n这一案例的理论意义在于，它把“恶法非法”从一个口号变成了可操作的司法标准，同时也暴露了它的风险：谁来判断何谓“不可容忍”？如果标准过于宽泛，法律确定性将受损；如果过于狭窄，又可能无法应对极端不义。阿奎那区分第一原则与次级原则的做法，恰好提示了这种判断的复杂性：原则层面可以明确，具体适用却需要审慎的理性推理。", "summary": "阿奎那把自然法系统化为四种法律的等级体系：永恒法为宇宙理性计划，自然法是理性生物对永恒法的分有，人法由上两者获得约束力，神法从外部补充。其核心在于：法律的效力有层级，人法必须合乎自然法，方能充分正当。他以实践理性解释自然法的可认识性，以共同善解释法律的目的，以“法律的腐败”描述严重不义的法律。关于“恶法非法”，阿奎那本人的立场比这一口号更精细：他指出的方向是不义之法道德权威的丧失，简单宣布其不存在并非他的做法。理解这种精细性，是避免把阿奎那漫画化的关键，也是进入当代自然法与实证主义之争的必要准备。", "furtherThinking": "1. 菲尼斯说“恶法非法”是对阿奎那的误读，这一辨析对当代自然法理论有何意义？\n2. 如果自然法的第一原则自明而次级原则可能出错，法官在判断“极端不义”时应如何避免主观任意？\n3. 阿奎那把人法的效力系于自然法，这与现代宪法审查中以基本权利限制立法的实践，在结构上是否可比？"}, "en": "Thomas Aquinas and Natural Law", "level": "core", "tags": "自然法, 阿奎那, 永恒法, 人法, 恶法非法", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.1.2, §2.2；Hart, The Concept of Law, Postscript", "id": "S2M1K3"}, "S2M1K4": {"title": "格劳秀斯与现代自然法", "EN": "Grotius and Modern Natural Law", "LEVEL": "core", "TAGS": "自然法, 格劳秀斯, 国际法, 社会契约, 霍布斯, 洛克", "TERMS": "格劳秀斯（Hugo Grotius）::十七世纪荷兰法学家，近代国际法与自然法世俗化的关键人物；即使假设上帝不存在（etiamsi daremus）::格劳秀斯的著名假设，用以说明自然法的有效性不依赖神的意志；国际法（International Law）::调整国家之间关系的法律体系，格劳秀斯被视为其奠基者之一；社会契约（Social Contract）::通过同意建立政治权威与法律秩序的理论；自然权利（Natural Rights）::人依本性而享有的、先于或独立于国家法律的权利", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.1, §2.3；Siems, Comparative Law, ch.4", "terms": [{"term": "格劳秀斯（Hugo Grotius）", "def": "十七世纪荷兰法学家，近代国际法与自然法世俗化的关键人物"}, {"term": "即使假设上帝不存在（etiamsi daremus）", "def": "格劳秀斯的著名假设，用以说明自然法的有效性不依赖神的意志"}, {"term": "国际法（International Law）", "def": "调整国家之间关系的法律体系，格劳秀斯被视为其奠基者之一"}, {"term": "社会契约（Social Contract）", "def": "通过同意建立政治权威与法律秩序的理论"}, {"term": "自然权利（Natural Rights）", "def": "人依本性而享有的、先于或独立于国家法律的权利"}], "sections": {"coreQuestion": "格劳秀斯为什么被称为近代国际法之父？他提出的“即使假设上帝不存在”（etiamsi daremus）这一著名假设，究竟想证明什么？本节要说明：格劳秀斯把自然法从神学体系中剥离出来，使其成为一种可以凭人的理性与本性加以论证的世俗理论，从而为近代国际法、社会契约论与人权话语提供了通用语言。同时要看到，经霍布斯、洛克、卢梭的改造，自然法逐渐让位于以“自然权利”为中心的理论形态，这一转向深刻塑造了现代法律与政治哲学。", "definition": "胡戈·格劳秀斯（Hugo Grotius，本名 Huig de Groot，1583—1645），荷兰法学家、政治家，其代表作《战争与和平法》（De Jure Belli ac Pacis, 1625）系统阐述了战争的正当性、条约的约束力与国际法的基本原则，被视为近代国际法的奠基之作。\n\n格劳秀斯的核心命题，是自然法的有效性独立于神的意志。他提出一个思想实验：即便我们假设上帝不存在（etiamsi daremus non esse Deum），自然法所禁止的某些行为依然是“内在地错误的”（intrinsically wrong）。用他自己的话说，某些行为之所以错误，不在于上帝如此规定，而在于其本身与人的理性本性相冲突。Wacks 指出，格劳秀斯正是以这一方式把自然法“世俗化”（secular adaptation）。\n\n这一转向的哲学意义在于：自然法的正当性基础从“神的意志”转移到“人的理性与社会本性”。法律不再需要诉诸启示或教会权威，而可以通过对人的本性、社会性与理性的反思得到论证。这为后来不同信仰、不同文化的人们共同讨论法律与正义提供了平台。", "history": "十七世纪的欧洲，宗教改革与宗教战争撕裂了基督教世界。三十年战争（1618—1648）的惨烈，使思想家迫切寻找一种超越教派分歧的秩序原则。格劳秀斯本人亲历荷兰国内的宗教与政治冲突，并因政治立场被囚禁、流亡。在这样的背景下，把自然法建立在各派都能接受的理性基础上，具有强烈的现实诉求。\n\n1648年《威斯特伐利亚和约》确立了以主权国家为基础的国际秩序。这一秩序需要一个理论来说明：彼此独立、互不统属的国家之间，何以存在有约束力的法律？格劳秀斯的自然法理论正好提供了答案：国家如同个人，同受自然法约束；条约必须遵守，战争须受正义限制。Wacks 把格劳秀斯与霍布斯、洛克、卢梭、布莱克斯通并列为自然法世俗化与政治化改造的代表人物。\n\n与此同时，社会契约理论在英国与大陆迅速发展。霍布斯、洛克、卢梭虽然都使用自然法与自然权利的语言，却赋予其截然不同的政治含义。自然法思想由此从一种关于“法律应当符合正义”的学说，转化为关于“政治权威如何正当化”的理论。", "principle": "格劳秀斯的自然法理论可拆为三个环节。\n\n第一环是自然法的独立性。自然法之所以有效，是因为它合乎人的理性与社会本性，而不是因为神的意志如此规定。格劳秀斯区分了“上帝不能做什么”与“上帝不做什么”：有些行为因其内在性质而不可被上帝许可，因为它们与人的本性根本冲突。这一区分把道德标准从神的任意意志中解放出来。\n\n第二环是自然法的可认识性。人可以通过反思自身的社会性与理性，发现自然法的基本要求。格劳秀斯认为，人天生趋向社会交往，爱好和平、厌恶冲突，这些倾向本身就是自然法的根据。法律的正当性因此可以被经验地、理性地论证。\n\n第三环是自然法的适用范围。自然法不仅约束个人，也约束国家与统治者。国际法正是自然法在国家间关系中的体现：条约必须遵守、战争须有正当理由、战争行为须受限制。这一主张为正在形成的主权国家体系提供了法律框架。\n\n值得注意的是，自然法在格劳秀斯之后发生了形态转变。霍布斯把自然权利（自我保存）置于自然法之前，自然法被理解为理性为保全生命而推导出的戒条；洛克则从自然法推导出自然权利（生命、自由、财产），并主张政府的目的正在保护这些权利。Wacks 指出，霍布斯与洛克在这一问题上的方向恰好相反：霍布斯的自然权利在逻辑上先于自然法，洛克则由自然法推导出自然权利。这一差别，深刻影响了后世对权利与法律关系的理解。", "viewpoints": "格劳秀斯的核心主张有四。\n\n其一，自然法的有效性不以神的意志为条件。“即使假设上帝不存在”的命题，是这一主张最凝练的表达。Wacks 强调，格劳秀斯所说的某些行为是“内在地错误的”，无论上帝是否规定。\n\n其二，国际法以自然法为基础。国家之间虽无共同的最高权威，但仍受自然法约束。条约必须遵守（pacta sunt servanda）因此成为国际法的基本原则。\n\n其三，战争须受正义约束。格劳秀斯在《战争与和平法》中系统讨论正当战争的理由与战争中的行为限制，把自然法的理性主义应用于国际冲突。\n\n其四，自然法可被理性认识。人的社会性与理性，使人能够发现自然法的内容，无需依赖超自然启示。\n\n霍布斯（Thomas Hobbes, 1588—1679）在《利维坦》（1651）中，从人在自然状态中自我保存的权利出发，主张人们为免于暴力死亡而相互订立契约，把权力让渡给主权者（sovereign）。Wacks 指出，霍布斯以恐惧（fear）为统一解释：无论是“按约建立的主权”还是“以取得方式建立的主权”，其共同逻辑都是恐惧。自然法在霍布斯那里，被改造为理性为自我保存而推导出的若干戒条。\n\n洛克（John Locke, 1632—1704）在《政府论（下篇）》中主张，人在自然状态中依自然法享有生命、自由、财产等自然权利；政府的正当性来自被统治者对保护这些权利的同意；当政府违背这一目的时，人民有权反抗。Wacks 指出，洛克以自然法（即理性）为自然权利的根据，这与霍布斯把自然权利置于自然法之前的做法恰成对照。", "comparison": "格劳秀斯与阿奎那的关系，是“世俗化”的关系。两者都主张存在高于人法的自然法，都承认自然法可被理性认识。差别在于根基：阿奎那把自然法纳入永恒法的神学秩序，格劳秀斯则使自然法摆脱神学依赖。格劳秀斯保留了自然法的内容与功能，却更换了它的哲学基础。\n\n霍布斯与洛克的分野，是近代自然法理论内部最重要的对立。两者都以社会契约说明政治权威的起源，都以自然状态为理论出发点。差别在于：霍布斯把自然状态描绘为一切人反对一切人的战争，强调恐惧与自我保存，主张主权者权力几乎不受限制；洛克把自然状态描绘为受自然法约束的相对和平状态，强调自然权利与政府的正当目的，主张政府权力须受限制、人民保有反抗权。Wacks 把霍布斯的自然权利观称为“自由市场版本的自然权利”，它以每个人保全自己生命的基本权利为前提。\n\n古典自然法与现代自然权利之间也有区别。古典自然法（如阿奎那）以义务与共同善为中心，强调人应当依理性追求善；现代自然权利理论以权利与个体为中心，强调国家不得侵犯个人的先在权利。这一从“义务本位”到“权利本位”的转向，是近代法律思想的重要转折。", "debates": "围绕格劳秀斯的第一场争论，是自然法能否脱离神学而独立。格劳秀斯的“即使假设上帝不存在”命题，被批评者视为对神学的不敬，也被某些自然法论者视为抽空了自然法的终极根基。支持者则认为，唯有如此，自然法才能成为不同信仰者共同接受的跨文化与跨宗教标准。这一争论在当代以菲尼斯与世俗自由主义者的形式重演。\n\n第二场争论关乎自然法与自然权利的优先性。霍布斯主张自然权利在逻辑上先于自然法，自然法只是理性为保全生命而推导的工具；洛克主张自然法（理性）是自然权利的根据。Wacks 明确指出，霍布斯与洛克在这一问题上的方向相反。这一分歧影响深远：若权利先于法律，法律的正当性就得看它是否保护权利；若法律（自然法）先于权利，权利就要从法律的理性秩序中推导出来。\n\n第三场争论关乎社会契约的解释。霍布斯的契约是每个人向主权者让渡权利，以换取安全；洛克的契约是人民信托政府保护权利，政府违背信托则人民可收回权力。两者的分歧，实质上是权威与自由何者优先的分歧，构成近代宪政理论的基本坐标。", "case": "《联合国宪章》（1945）序言宣告“承认对人类大家庭所有成员固有尊严及其平等权利与自决权的尊重”，并确立主权平等、和平解决国际争端、不干涉内政等原则。这些表述延续了格劳秀斯以降的古典国际法语言：国家即使在无世界政府的情况下，仍受共同法律原则约束。\n\n一个更具争议性的现实例子，是人道主义干预。当一国政府大规模迫害或屠杀其本国人民时，国际社会是否有权甚至有义务进行干预？支持者援引普遍人权与“保护责任”（Responsibility to Protect, 2005年联合国世界首脑会议成果）论证，认为主权不是绝对盾牌；反对者则强调《联合国宪章》第2条的主权平等与不干涉原则，担忧人道主义干预沦为强权政治的工具。这一争论的结构—普遍人权与主权秩序哪个优先—正是格劳秀斯式自然法与国际法实证主义之争的当代版本。", "caseAnalysis": "就人道主义干预而言，事实是：国际社会面对一国内部的大规模暴行，需要在尊重主权与保护人权之间作出选择；争议焦点在于，是否允许以人权为由突破不干涉原则。从格劳秀斯式自然法立场看，人的尊严与基本权利先于国家主权，严重违反自然法的政权不能仅以主权为抗辩。从实证主义立场看，国际法的有效性来自国家同意，未经同意的干预缺乏法律根据。\n\n从裁判／论证理由看，“保护责任”框架试图折中两者：它承认主权国家负有保护本国人民的首要责任，仅在国家“明显未能”履行这一责任时，国际社会才承担补充责任，且须通过联合国安理会授权。这一制度设计，既承认自然法式的人道关切，又保留了国家同意的程序门槛。\n\n这一案例的理论意义在于，它展示了近代自然法两个面向的当代延续：格劳秀斯的普遍主义为人权干预提供了论证资源，而主权与同意的框架则体现了实证主义对法律确定性的坚持。理解两者的张力，是进入当代国际法法理学的前提。", "summary": "格劳秀斯通过“即使假设上帝不存在”的著名假设，把自然法的有效性从神的意志转移到人的理性与社会本性，完成了自然法的世俗化。这一转向使自然法成为近代国际法与社会契约理论的通用语言：国家间关系受自然法约束，条约必须遵守，战争须受正义限制。继格劳秀斯之后，霍布斯与洛克以社会契约说明政治权威的起源，但因对自然权利与自然法何者优先的分歧，走向截然不同的政治结论—前者强调恐惧与安全，后者强调权利与对政府的限制。这一从古典自然法到现代自然权利的转向，奠定了现代法律与政治哲学的基本问题结构，其张力在当代人道主义干预等议题中依然清晰可见。", "furtherThinking": "1. 格劳秀斯所说的某些行为“内在地错误”，是否为法律实证主义所容纳？若不能，分歧的根源在哪里？\n2. 霍布斯与洛克对自然权利与自然法何者优先的分歧，对当代宪法权利的论证方式有何影响？\n3. 人道主义干预中，普遍人权与国家主权之间的张力能否通过制度设计彻底化解？"}, "en": "Grotius and Modern Natural Law", "level": "core", "tags": "自然法, 格劳秀斯, 国际法, 社会契约, 霍布斯, 洛克", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.1, §2.3；Siems, Comparative Law, ch.4", "id": "S2M1K4"}, "S2M1K5": {"title": "现代自然法理论的复兴：富勒与菲尼斯", "EN": "The Revival of Modern Natural Law: Fuller and Finnis", "LEVEL": "core", "TAGS": "自然法, 富勒, 菲尼斯, 法律的内在道德, 基本善", "TERMS": "法律的内在道德（Inner Morality of Law）::富勒提出的法律程序性成就标准，包括一般性、公开性、不溯及既往等八项要求；愿望的道德（Morality of Aspiration）::富勒对内在道德的定性，指法律体系力求达到的卓越标准而非最低义务；基本善（Basic Goods）::菲尼斯理论中人先天追求、不可再还原的七种根本善；实践合理性（Practical Reasonableness）::菲尼斯理论中统摄基本善追求、回答『我应当做什么』的理性要求；共同的善（Common Good）::共同体成员共享的、使个人善得以实现的社会条件", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.5, §2.6；Fuller, The Morality of Law；Finnis, Natural Law and Natural Rights", "terms": [{"term": "法律的内在道德（Inner Morality of Law）", "def": "富勒提出的法律程序性成就标准，包括一般性、公开性、不溯及既往等八项要求"}, {"term": "愿望的道德（Morality of Aspiration）", "def": "富勒对内在道德的定性，指法律体系力求达到的卓越标准而非最低义务"}, {"term": "基本善（Basic Goods）", "def": "菲尼斯理论中人先天追求、不可再还原的七种根本善"}, {"term": "实践合理性（Practical Reasonableness）", "def": "菲尼斯理论中统摄基本善追求、回答『我应当做什么』的理性要求"}, {"term": "共同的善（Common Good）", "def": "共同体成员共享的、使个人善得以实现的社会条件"}], "sections": {"coreQuestion": "二十世纪自然法何以复兴？富勒（Lon Fuller）与菲尼斯（John Finnis）分别以何种方式重述自然法？前者把自然法理解为法律在程序上的“内在道德”，后者则以亚里士多德式的“基本善”与“实践合理性”重建自然法的实体内容。两人的路径差别很大，却共同回应了同一个历史挑战：在法律实证主义占主导、极权主义经验阴影未散的时代，如何为法律的道德正当性保留一席之地？本节要讲清两种复兴方案的论证结构、具体主张与各自面临的批评。", "definition": "富勒（Lon L. Fuller, 1902—1978）在《法律的道德性》（The Morality of Law, 1964）中提出，法律具有一种“内在道德”（Inner Morality of Law）。他通过一位虚构的君主 Rex 试图制定法律却屡屡失败的寓言，归纳出法律体系应满足的八项程序性要求（desiderata）：(1) 存在一般性的规则；(2) 规则须公开颁布；(3) 不溯及既往；(4) 清晰明确；(5) 不自相矛盾；(6) 要求的内容具有可履行性；(7) 规则须保持相对稳定；(8) 已颁布的规则与官方实际行为之间须保持一致。富勒强调，这八项要求属于“愿望的道德”（morality of aspiration），是法律体系力求达到的卓越标准，而非仅仅关乎颁布者是否履行义务的“义务的道德”。\n\n菲尼斯（John Finnis, 1941— ）在《自然法与自然权利》（Natural Law and Natural Rights, 1980；第二版 2011）中，以当代分析哲学的方式重述阿奎那传统。他提出七种“基本善”（basic forms of human flourishing）：生命、知识、游戏、审美体验、社交（友谊）、实践合理性、宗教。这些善是“自明的”、不可再推导的——Wacks 指出，菲尼斯认为欲望无法告诉我们应当欲望什么，他因而采取亚里士多德式的进路，把基本善理解为人的完善形式。此外，菲尼斯提出九项“实践合理性的基本要求”，统摄人对基本善的追求，其中包括要求人促进其共同体的“共同的善”（common good）。", "history": "二十世纪上半叶，法律实证主义在英语世界与欧陆占据主导。奥斯丁的命令理论与凯尔森的纯粹法学致力于把法律研究对象从道德中剥离出来。然而，两次世界大战与极权主义的经验动摇了这一格局：如果法律只是主权者的命令，那么纳粹德国的恶法在形式上仍是“法律”，法理学似乎失去了批判极权主义的概念工具。\n\n在这样的背景下，富勒于1958年在《哈佛法律评论》与哈特展开著名论战。富勒反对把法律视为“价值中立的事实”，主张法律本身即是一种有目的的事业（purposive enterprise），其存在离不开程序性的道德要求。Wacks 指出，富勒拒绝把第三帝国的“法律”承认为法律，这一立场为哈特所反对。\n\n菲尼斯的复兴发生在另一语境中。二十世纪六七十年代，功利主义与法律实证主义主导英语法哲学，自然法被视为形而上学残余。菲尼斯以分析哲学的严谨风格重述自然法，使其重新进入主流法哲学的讨论。Wacks 称他为“当代自然法的主要（也是最容易接近的）倡导者”。菲尼斯自称其著作是“导论性”的，并否认原创性，但其影响深远。", "principle": "富勒的理论逻辑可拆为三层。\n\n第一层，法律是有目的的事业。富勒认为，法律的存在意义在于使人的行为服从规则的治理。要实现这一目标，规则必须具备某些形式品质。如果规则完全不公开、溯及既往、自相矛盾、要求不可能做到的行为，那么规则就无法发挥指引行为的功能——它根本够不上“法律”，只剩下统治者任意意志的表达。\n\n第二层，八项要求是法律的概念性条件。富勒的论证是：违反这些要求到一定程度，一个规则体系就不再能被称为法律体系。因此，法律与道德之间存在“必然联系”——这层联系落在程序道德上（规则必须具备形式合法性），内容道德（规则必须正义）则另属一层。Wacks 特别指出，富勒采取的是程序性自然法进路，而非实体性自然法进路。\n\n第三层，富勒的立场有其限度。Wacks 提醒，富勒的论证实际上大多只支持法律与道德之间的“偶然联系”（contingent connection）而非“必然联系”。而且，富勒的承认并不使一个法律体系免受批判——“富勒式的认可并不会使一个法律体系超越责备”。这八项要求只是法律有效运作的必要条件，远非正义的充分条件：一个满足全部八项要求的规则体系，仍可能是极端邪恶的。\n\n菲尼斯的理论逻辑同样可以拆为三层。\n\n第一层，基本善是自明的出发点。菲尼斯拒绝从“是”推导出“应当”——他同意休谟（David Hume）对这类论证的批评。基本善是实践理性直接把握到的、人因其本性而追求的根本善；从欲望、事实或人类学中推导的路径在这里走不通。Wacks 强调，这些善是“不可推导的”（underived）。\n\n第二层，实践合理性统摄基本善的追求。人可能以错误的方式追求善，因而需要九项实践合理性的基本要求来规范选择：包括生活计划的一贯性、对各基本善的均衡追求、不任意偏私、保持承诺、在可容忍的范围内接受牺牲等。菲尼斯以此把“我应当做什么”的回答建立在理性选择的结构上。\n\n第三层，共同的善是法律的指向。菲尼斯借“共同的善”概念发展其法律理论：人只有在共同体中才能实现基本善，法律的正当性在于促进共同的善。Wacks 指出，菲尼斯强调共同善的中心地位，并以此发展其对法律与权利的理解。在2011年的后记中，菲尼斯把“恶法非法”这类命题描述为“松散的”（loose），表明他对古典自然法口号持审慎态度。", "viewpoints": "富勒的核心主张有四点。\n\n其一，法律具有内在道德，即八项程序性要求。一个规则体系若严重违反这些要求，就丧失了法律的资格。\n\n其二，这些要求属于“愿望的道德”，指向法律体系的卓越，而非最低限度的义务。富勒借此强调，法律是一种需要被好好经营的事业，单纯的权力工具之称过于单薄。\n\n其三，忠于法律（fidelity to law）不只是服从赤裸的权力。富勒在论战中批评实证主义把法律当作“无道德的事实”（amoral datum），认为这会使人在面对恶法时丧失批判的语汇。\n\n其四，程序性自然法不等于实质正义。富勒并不主张满足八项要求就保证法律正义；他只主张这些要求是法律存在的前提。这一点常被误解。\n\n菲尼斯的核心主张亦有四点。\n\n其一，自然法的出发点是七种基本善，它们自明、不可还原、对所有人有效。\n\n其二，实践理性可以回答“我应当做什么”。菲尼斯反对从欲望或事实推导应当，而是诉诸人的实践理性对善的把握。\n\n其三，共同的善是法律与政治正当性的核心。个人善的实现离不开共同体条件，法律应当促进共同的善。\n\n其四，对阿奎那的重新阐释。菲尼斯认为，阿奎那关于自然法的贡献长期被误解，他通过澄清“分有”等概念，恢复阿奎那实践哲学的本来面目。Wacks 指出，菲尼斯在其2011年后记中把“自然法＝恶法非法”一类命题称为“松散的”表述。", "comparison": "富勒与菲尼斯代表了自然法复兴的两种路径。富勒是程序性、形式性的：他不关心法律应当促进哪些实质价值，只关心法律作为规则体系必须具备的形式品质。菲尼斯则是实体性的：他明确提出一套可辨认的客观善（七种基本善），并以之评判法律与政治。可以说，富勒在寻找法律的最低形式条件，菲尼斯在重建法律的实质价值基础。\n\n富勒与哈特的分歧集中在“必然联系”上。哈特承认法律与道德在事实上常有交叠，也承认法律须满足某些“最低限度的自然法”才能维持自身，但坚持在概念上“是不是法律”与“是否道德正当”应分开判断。富勒则主张内在道德是法律的概念性条件。Wacks 指出，许多评论者（包括哈特）认为，富勒的论证实际上只支持偶然联系，而非必然联系。\n\n菲尼斯与法律实证主义的分歧集中在法律与道德的关系上。实证主义（尤其拉兹）主张，识别法律只需诉诸社会来源，无需道德论证；菲尼斯则坚持，对法律的理解离不开对实践理性与共同善的理解。Wacks 指出，拉兹的渊源命题（sources thesis）与菲尼斯的自然法理论虽结论相反，却共享一个前提：法律理论必须说明法律何以能主张权威。\n\n在自然法传统内部，菲尼斯与阿奎那既有承继也有差别。菲尼斯继承实践理性、基本善与共同善的思路，却淡化其神学形而上学色彩，强调自然法可以在世俗的、实践理性的层面被阐明。批评者认为这背离了阿奎那的本意，菲尼斯则回应说阿奎那长期被误解。", "debates": "哈特—富勒论战（1957—1959）是二十世纪法理学的标志性事件。论战的直接背景是二战后如何处理纳粹法律的问题。富勒主张，纳粹法律严重违反了法律的内在道德（特别是公开性、不溯及既往、官方行为与规则的一致），因而根本不配称为法律。哈特则反驳：把极端邪恶的规则排除出“法律”概念，反而会遮蔽对其性质的认识；承认它是法律，然后说“正因为它有效力，我们更有道德义务抵抗它”，一种是更清醒的批判立场。\n\n论战的核心分歧有三。第一，法律与道德是否存在“必然联系”？富勒说是（程序性的），哈特说否（只有偶然联系与最低限度条件）。第二，“内在道德”是否真的是道德？哈特认为，富勒的八项要求关乎法律的效率（efficacy），与道德无关；富勒则坚持它们构成一种“愿望的道德”。第三，极端邪恶的规则是否应被称为法律？富勒拒绝，哈特接受。Wacks 指出，这场论战没有胜负，但它确立了一个此后所有法理学都必须面对的坐标：任何法律理论都要交代效力与正当性的关系。\n\n围绕菲尼斯的争论集中在三点。其一，他对阿奎那的解读是否准确？部分托马斯主义者认为他过度世俗化了阿奎那。其二，七种基本善是否遗漏了重要的善？Wacks 提到，批评者认为他的基本善过于局限，例如共同的善是否应当包含“工作的权利”。其三，他的政治立场是否过于保守？Wacks 指出，许多学生发现菲尼斯的家庭模型过于理想化，其政治立场过于保守。菲尼斯在后期著作中对第三项基本善的说法有所让步。", "case": "富勒虚构的“洞穴探险者案”（The Case of the Speluncean Explorers, 1949）虽是思想实验，却成为法理学经典文本，并被 Wacks 用作理解法律理论各立场的切入口。案件设定：五名洞穴探险者被困，为生存而杀死并食用了一名同伴，被判死刑后上诉。五位法官给出截然不同的判决意见，分别体现实证主义、自然法、法律现实主义等立场。Wacks 指出，其中 Handy 法官是极端的现实主义者，Foster 法官则采取目的论的解释进路；而“洞穴探险者案”中的某些意见，正是富勒自身立场的伪装版本。\n\n这个案例的理论价值在于，它把抽象的法理学分歧转化为具体裁判：同一个事实，在不同法律理论下可以得出不同结论。Wacks 还提到一个耐人寻味的细节：哈特与富勒都倾向于认为，在这个案件中颁布溯及既往的立法是可取的——这显示两人在具体问题上并非总是立场对立。", "caseAnalysis": "就洞穴探险者案而言，事实是：探险者为求生杀死同伴，实证法明文规定杀人者处死刑；争议焦点在于，极端情境下是否应严格适用法律，抑或考虑更高的正义与目的。从富勒的立场看，法律的目的事业属性要求法官考虑规则与共同善的关系；从哈特的立场看，承认法律的严格性，同时通过独立的道德判断来处理极端案件，更能保持概念的清晰。\n\n从裁判理由看，五位法官的意见展示了不同法理立场的具体运作：有的强调规则文字的明确，有的强调法律的目的，有的强调民意与后果，有的强调自然法上的自我保存。这一多元性说明，法理学分歧直接进入司法裁判的理由结构，书斋里的抽象争论之说并不成立。\n\n这一案例的理论意义在于，它把“法律与道德的关系”这一抽象命题，转化为“法官在疑难案件中应当如何裁判”的具体问题。富勒借这一案例表明，法律不能脱离其目的与道德维度而被理解；哈特则借它说明，区分“法律是什么”与“法律应当是什么”，恰恰是为了更负责任地作出道德判断。", "summary": "富勒与菲尼斯在二十世纪以不同方式复兴了自然法。富勒提出法律的“内在道德”，以八项程序性要求作为法律体系的概念性条件，主张法律是有目的的事业，反对把法律当作无道德的事实。其与哈特的论战，围绕法律与道德是否存在必然联系、内在道德是否真为道德、极端恶法是否仍为法律三个问题展开，深刻塑造了现代法理学的问题结构。菲尼斯则以七种基本善与九项实践合理性要求重建自然法的实体内容，强调共同的善的核心地位，并以分析哲学的方法重新阐释阿奎那。两者的差别在于：富勒走程序性路线，菲尼斯走实体性路线；前者寻求法律的最低形式条件，后者重建法律的实质价值基础。他们共同表明，法律实证主义主导的时代，并未终结关于法律道德正当性的追问。", "furtherThinking": "1. 富勒的八项要求若只被理解为法律效率的必要条件，是否仍配称“道德”？哈特与富勒在这一问题上的分歧，哪一方更有说服力？\n2. 菲尼斯的基本善被批评为“过于狭隘”，这一批评是否会动摇其理论？请结合共同善的概念分析。\n3. 洞穴探险者案中，承认恶法为法律反而有助于抵抗恶法——这一哈特式命题能否在极端情境下成立？"}, "en": "The Revival of Modern Natural Law: Fuller and Finnis", "level": "core", "tags": "自然法, 富勒, 菲尼斯, 法律的内在道德, 基本善", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.5, §2.6；Fuller, The Morality of Law；Finnis, Natural Law and Natural Rights", "id": "S2M1K5"}, "S2M1K6": {"title": "自然法与实在法的关系", "EN": "The Relationship Between Natural Law and Positive Law", "LEVEL": "debate", "TAGS": "自然法, 法律实证主义, 哈特, 富勒, 法律效力, 道德正当性", "TERMS": "实在法（Positive Law）::由合法权威按程序制定、以社会事实为存在根据的法律；分离命题（Separation Thesis）::实证主义主张法律的识别与道德评价在概念上应分开；必然联系（Necessary Connection）::自然法主张法律的性质本身包含道德要求；最低限度的自然法（Minimum Content of Natural Law）::哈特承认法律为维持自身必须满足的若干基于人性事实的条件；拉德布鲁赫公式（Radbruch Formula）::极端不正义的法律丧失法性质的司法准则", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.7—§2.10；Hart, The Concept of Law, ch.9；Fuller, The Morality of Law, ch.3", "terms": [{"term": "实在法（Positive Law）", "def": "由合法权威按程序制定、以社会事实为存在根据的法律"}, {"term": "分离命题（Separation Thesis）", "def": "实证主义主张法律的识别与道德评价在概念上应分开"}, {"term": "必然联系（Necessary Connection）", "def": "自然法主张法律的性质本身包含道德要求"}, {"term": "最低限度的自然法（Minimum Content of Natural Law）", "def": "哈特承认法律为维持自身必须满足的若干基于人性事实的条件"}, {"term": "拉德布鲁赫公式（Radbruch Formula）", "def": "极端不正义的法律丧失法性质的司法准则"}], "sections": {"coreQuestion": "自然法与实在法（Positive Law）的关系，是法理学最核心的争论之一。问题的提法是：法律的效力究竟取决于什么？如果一项由合法机关按程序制定、内容却极端邪恶的规则，是否仍是“法律”？自然法论者倾向于否认，实证主义者倾向于承认。这一分歧看似抽象，实则关系到法官在极端情境下是否有义务拒绝适用法律，关系到公民面对恶法时有无抵抗的权利。本节把各种立场放在同一坐标系中，逐一检视其论据与弱点，并说明这场争论为何至今没有定论。", "definition": "实在法（Positive Law）指由特定社会的合法权威按照既定程序制定或认可、以社会事实为存在根据的法律。它的合法性来自“被制定”这一事实（positus，即“被放置”），而非来自其内容是否符合某种超越标准。法律实证主义（Legal Positivism）正是以实在法为核心概念的理论，主张识别法律是否存在、内容为何，最终要诉诸社会事实，而非道德论证。\n\n自然法（Natural Law）则主张，法律与道德之间存在某种联系：或者法律的内容必须符合正义（实体版本），或者法律体系必须满足某些程序条件（富勒的程序版本）。在强自然法版本中，严重不正义的规则根本不是法律，即“恶法非法”。\n\n两种立场的分歧可以放在“效力”（validity）与“正当性”（legitimacy）两个概念上定位。效力回答“这是否是一项有效的法律”，正当性回答“这项法律在道德上是否值得服从”。自然法倾向于把二者联系起来，实证主义倾向于把二者分开。Wacks 指出，哈特与富勒的论战之所以重要，正在于它迫使所有法理学理论交代自己如何处理这两个概念的关系。", "history": "自然法与实在法的关系问题，在不同历史阶段有不同的表现形态。\n\n在中世纪，阿奎那把法律纳入永恒法—自然法—人法的等级体系，人法的效力来自自然法，自然法又来自永恒法。在这一框架中，两者是上位与下位的关系，自然法构成实在法正当性的来源与边界。\n\n近代民族国家兴起后，主权（Sovereignty）成为政治理论的核心概念。边沁（Jeremy Bentham）与奥斯丁（John Austin）转向以“命令”与“来源”界定法律，把法律从道德与宗教中独立出来。自然法与实在法由此从“上下位关系”转变为“对立关系”：一边主张法律符合道德才有效力，另一边主张法律的识别无需道德。\n\n二十世纪的极权主义经验，使这场争论获得新的紧迫性。如果法律只是主权者的命令，纳粹法律在形式上完全有效，法理学似乎失去了批判极权主义的概念工具。二战后，德国法学家拉德布鲁赫提出，极端不正义的法律丧失法的性质；哈特与富勒则在1958年的《哈佛法律评论》上展开论战，把这一议题推向法理学讨论的中心。Wacks 指出，这场论战至今仍是理解法理学的关键入口。", "principle": "可以把关于自然法与实在法关系的立场，整理为四种典型模型。\n\n模型一：强自然法（Strong Natural Law）。严重不正义的规则根本不是法律。其论据是：法律的概念本身包含道德要求，违背到一定程度的规则丧失法律资格。其难点是：谁来判定“严重不正义”？不同判断者可能得出不同结论，从而威胁法律确定性。\n\n模型二：弱自然法（Weak Natural Law）。不正义的法律仍然是法律，但丧失被服从的道德义务。其论据是：承认恶法为法律不妨碍谴责它，反而使批判更准确。其难点是：如果法律效力与道德完全脱钩，“自然法”的独特贡献在哪里？\n\n模型三：极端实证主义（Exclusive Positivism）。法律的识别只诉诸社会来源，道德论证在识别阶段无立足之地。拉兹（Joseph Raz）的渊源命题（Sources Thesis）是这一立场的代表。其论据是：唯有如此，法律才能提供确定的行为指引，并诚实地说明其权威主张。其难点是：如何解释法律为何能主张道德权威？\n\n模型四：包容实证主义（Inclusive Positivism）。法律识别一般诉诸社会来源，但如果一个社会的承认规则（Rule of Recognition）把道德标准纳入其中，道德可以成为法律有效性的条件。哈特后期倾向于这一立场。其论据是：它在保持实证主义核心的同时，承认道德标准在某些法律体系中的实际作用。其难点是：承认道德标准进入法律，是否会模糊实证主义与自然法的界限？\n\n哈特提出一个精细的限定：任何法律体系都必须具备“最低限度的自然法”才能维持自身。基于人的脆弱性、大体平等、有限利他主义、有限理解力等事实，法律必须包含禁止暴力、保护财产、要求信守承诺等基本内容。Wacks 指出，这一 concession 表明哈特并未完全无视法律与道德的联系：他把这层联系定位在“法律存在的必要条件”，而非“法律概念的必然要素”。", "viewpoints": "富勒的核心主张是：法律具有内在道德，八项程序性要求（一般性、公开性、不溯及既往、清晰、不矛盾、可履行、稳定、官方行为与规则一致）是法律体系的概念性条件。纳粹法律严重违反这些要求，因而不配称为法律。Wacks 强调，富勒采取的是程序性自然法进路，而非实体性自然法进路。\n\n哈特的核心主张是：在概念上，法律的存在与法律的道德价值是两个应分开判断的问题。他承认法律与道德在事实层面常相互渗透，也承认法律必须满足最低限度的自然法条件，但坚持“是不是法律”与“是否道德正当”应分开。他反驳富勒：把极端邪恶的规则排除出法律概念，反而会遮蔽对其性质的认识。\n\n拉兹的核心主张是渊源命题：识别法律的存在与内容，不需要、也不应求助于任何道德论证，只能诉诸社会来源。Wacks 引述拉兹：法律的识别若依赖某一套道德信念，就违反了渊源命题。拉兹据此批评包容实证主义，主张纯净的实证主义。\n\n德沃金（Ronald Dworkin）提供第三种视角。他批评实证主义把法律理解为规则体系，主张法律还包含道德原则；在疑难案件中，法官须通过“整体性”（integrity）的解释，从法律实践中提炼出最能证成既往实践的原则。Wacks 指出，德沃金把法律与道德的关系理解为一种“解释性”的关系，既不同于强自然法的本体论主张，也不同于实证主义的分离命题。", "comparison": "强自然法、弱自然法、实证主义三者的根本分歧，在于对“恶法”的处理方式。强自然法说：恶法不是法律。弱自然法说：恶法是法律，但不应服从。实证主义说：恶法是法律，是否服从是另一个道德问题。这三种立场在日常直觉中都有支持者，分歧的实质在于：把“不道德”的因素放进“法律是什么”的定义中，会带来什么理论后果。\n\n富勒与哈特的关键分歧，在于“内在道德”的性质。哈特认为，富勒的八项要求关乎法律能否有效运作（efficacy），属于效率问题，与道德无关。富勒则坚持，这些要求构成“愿望的道德”，是法律作为事业的内在组成部分。Wacks 指出，许多评论者认为富勒的论证实际上只支持偶然联系，而非必然联系——满足八项要求的法律体系仍可能是邪恶的。这一批评击中了富勒理论的要害：程序合法性并不保证实质正义。\n\n拉兹与哈特的分歧，在于道德能否通过承认规则进入法律。哈特的包容实证主义允许这种可能，拉兹的排他实证主义则坚决反对。Wacks 指出，拉兹担心的是：一旦允许道德论证进入法律识别，法律的确定性就将受损，法律理论也难以保持描述性。\n\n德沃金与实证主义的分歧，在于法律是否只包含规则。实证主义以承认规则作为法律体系的基础，德沃金则主张原则同样是法律的一部分，且原则的识别离不开道德判断。这一争论把“法律与道德的关系”从效力问题转向了解释问题。", "debates": "哈特—富勒论战（1957—1959）是这一主题的核心文本。论战的起点是对二战后德国法律问题的处理。拉德布鲁赫在战后提出，极端不正义的法律丧失法的性质（即“拉德布鲁赫公式”），德国法院在若干判决中援引了这一公式。\n\n富勒在论战中主张，纳粹法律严重违反了法律的内在道德——它随意发布追溯性法律，秘密制定规则，官方行为与宣布的规则严重背离——因此根本不构成法律体系。哈特则回应：这种主张会模糊一个重要的道德区分——“这项规则在道德上应受谴责”与“这项规则不是法律”。哈特认为，承认纳粹法律的效力，然后明确宣布其道德上的极端邪恶，才是更诚实、更清醒的批判方式。\n\nWacks 指出，论战中双方都倾向于认为，在洞穴探险者案中颁布溯及既往的立法是可取的——这说明两人在具体问题上并非总是立场对立，分歧更多在概念层面。Wacks 还指出，论战没有胜负，但它确立了一个坐标：任何法律理论都要交代效力与正当性的关系。\n\n拉德布鲁赫公式本身也引发争论。支持者认为，它为法官拒绝适用极端邪恶的法律提供了准则；反对者认为，它损害法律安定性，且“不可容忍的不正义”标准过于模糊，容易沦为法官主观偏好的工具。这一争论的深层，是法的安定性与正义之间的价值冲突。", "case": "德国战后“告密者案”（Informer Case，联邦最高法院，1951年）是检验上述理论的经典案例。案情大致是：被告在纳粹时期向当局告发他人，导致后者被处死；战后，被告依据当时有效的纳粹法律为自己辩护，主张其行为合法。法院最终判定被告有罪，其理由大致是：纳粹政权那些允许迫害无辜者的法律，违背了文明社会的基本法律原则，丧失了法的效力。\n\n这一裁判体现了拉德布鲁赫公式的实际运用：极端不正义的法律被否认法律效力。从强自然法视角看，法院做法完全正确——违背基本正义的“法律”自始无效。从哈特的视角看，法院的做法在道德上可以理解，但概念上更诚实的做法是：承认那些法律在形式上是有效的，同时明确宣告其道德上的极端邪恶，并据此正当化对被告的惩罚。\n\n另一个对照案例是南非种族隔离时期的法律。Wacks 提到，富勒认为南非的种族隔离立法严重偏离了法律的内在道德。但批评者指出：种族隔离法律在形式上可能符合公开性、一般性、不溯及既往等要求，这说明满足富勒的八项要求并不足以保证实质正义。这一点成为反驳富勒“内在道德足以区分法律与蛮力”的重要论据。", "caseAnalysis": "就告密者案而言，事实是：被告依当时有效法律实施告发行为，战后被追诉；争议焦点在于，是否承认那些法律的效力。从自然法视角看，极端不正义的法律丧失正当性，不能作为辩护理由。从实证主义视角看，法院应承认那些法律在形式上有效，同时在道德上予以谴责，并寻找明确的道德根据来正当化追诉。\n\n从裁判理由看，法院实际采取的是拉德布鲁赫式的立场：在法律安定性与正义的冲突中，当矛盾达到不可容忍的程度时，正义优先。这一立场的优点是为抵抗极端邪恶提供了法律语言；其风险则在于标准模糊，可能打开法官以个人道德否定法律的大门。\n\n这两个案例共同说明，自然法与实在法的关系问题并非书斋里的抽象思辨。在极端情境中，理论立场会直接影响裁判结果和公民对法律的态度。富勒试图通过内在道德为法律的道德性提供概念基底；哈特则坚持概念清晰与道德清醒可以并存；拉兹以渊源命题维护法律的确定性；德沃金以解释性整体观把道德原则纳入法律。这些方案各有得失，至今仍在角力。", "summary": "自然法与实在法的关系，可通过四种模型把握：强自然法主张极端不正义的规则不是法律；弱自然法主张其仍是法律但丧失服从义务；排他实证主义主张法律识别只诉诸社会来源；包容实证主义允许承认规则把道德纳入效力条件。哈特提出“最低限度的自然法”作为法律存在的必要条件的限定，富勒则以八项程序性要求作为法律的概念性条件，二人围绕必然联系、内在道德的性质与恶法的称谓展开论战。Wacks 指出，这场论战没有胜负，却确立了效力与正当性这一此后所有法理学都必须面对的坐标。拉德布鲁赫公式与告密者案表明，这一争论在司法实践中具有直接后果。成熟的立场，既不应把法律与道德的关系简化为一句话，也不应回避在极端情境中作出判断的责任。", "furtherThinking": "1. 在告密者案中，哈特式的“承认恶法为法律再予以谴责”与拉德布鲁赫式的“否认恶法效力”，哪一种更能维护法治？请说明理由。\n2. 富勒的八项要求若不能保证实质正义（如南非种族隔离法所示），它还能否被称为“道德”？\n3. 德沃金以解释性整体观处理法律与道德的关系，是否真正超越了哈特与富勒的二元对立？"}, "en": "The Relationship Between Natural Law and Positive Law", "level": "debate", "tags": "自然法, 法律实证主义, 哈特, 富勒, 法律效力, 道德正当性", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.7—§2.10；Hart, The Concept of Law, ch.9；Fuller, The Morality of Law, ch.3", "id": "S2M1K6"}, "S2M1K7": {"title": "自然法理论的优势与批评", "EN": "The Strengths and Criticisms of Natural Law Theory", "LEVEL": "core", "TAGS": "自然法, 法理学批判, 人权, 道德, 法律确定性", "TERMS": "是—应当问题（Is—Ought Problem）::休谟提出的质疑，即从描述性事实难以逻辑地推出规范性应当；不确定性（Indeterminacy）::自然法原则在具体适用中难以得出唯一确定结论的批评；硬自然法（Hard Natural Law）::主张不正义法律丧失法资格的强版本；软自然法（Soft Natural Law）::承认不正义法律仍为法但丧失服从义务的版本；法律安定性（Legal Certainty）::法律应提供明确、可预测的行为指引的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.4, §2.7, §2.9；Finnis, Natural Law and Natural Rights", "terms": [{"term": "是—应当问题（Is—Ought Problem）", "def": "休谟提出的质疑，即从描述性事实难以逻辑地推出规范性应当"}, {"term": "不确定性（Indeterminacy）", "def": "自然法原则在具体适用中难以得出唯一确定结论的批评"}, {"term": "硬自然法（Hard Natural Law）", "def": "主张不正义法律丧失法资格的强版本"}, {"term": "软自然法（Soft Natural Law）", "def": "承认不正义法律仍为法但丧失服从义务的版本"}, {"term": "法律安定性（Legal Certainty）", "def": "法律应提供明确、可预测的行为指引的价值"}], "sections": {"coreQuestion": "自然法理论为何能在历经两千多年后仍保持生命力？它到底解决了什么问题，又带来了哪些新的困难？本节先把自然法理论的强项与软肋都摆上桌面，站队的事留待读者自己判断。支持者认为，自然法为批判恶法、论证人权与限制权力提供了不可替代的概念资源；批评者则指出，它诉诸的“人性”“理性”“正义”往往含混不清，容易把特定群体的价值偏好包装成普遍真理。理解双方论据，是形成成熟判断的前提。", "definition": "自然法理论（Natural Law Theory）是一族主张法律与道德存在某种联系的学说，其共同特征是：法律的正当性不能仅从其制定来源得到说明，还必须诉诸某种关于正义、人性或共同善的考量。Wacks 转述一位自然法论者的说法：对自然法的最佳描述，是它提供了某种东西，用以处理“是什么”（is）与“应当是什么”（ought）之间的张力——自然法理论试图化解这一张力。\n\n自然法理论的强项，通常围绕三个功能展开。第一是批判功能：它为评价现行法律提供超越实定秩序的标准，使“这项法律不正义”成为可说、可论证的命题。第二是论证功能：它为基本权利、人权、国际法等提供正当性基础，说明为何某些权利不因国家法律而改变。第三是整合功能：它把法律理解为有目的的社会实践，指向共同善，从而避免把法律降格为纯粹的权力技术。\n\n自然法理论的典型弱点，则集中在四个词上：含混、循环、多元、保守。“人性”“理性”“善”这些概念本身充满争议；从人性事实推导应当，面临休谟式质疑；对善的清单可能因人而异；而把某种特定生活形式当作“自然”，可能固化既有权力结构。", "history": "自然法理论在历史上多次衰落又多次复兴。近代科学革命与实证主义兴起后，诉诸目的论与宇宙秩序的自然法逐渐丧失智识信誉，边沁（Jeremy Bentham）更以犀利言辞抨击自然法与自然权利。Wacks 指出，边沁对自然法的攻击，使这一理论在十九世纪长期处于守势。\n\n二十世纪两次世界大战与极权主义的经验，改变了这一格局。法律实证主义强调法律与道德分离，看似难以回应“形式上合法的暴行”；自然法凭借对正义与人性尊严的诉诸，重新获得道义力量。富勒的“内在道德”与菲尼斯的“基本善”，是这一复兴的两种理论形态。\n\n然而，复兴并不意味着所有难题都被解决。在价值多元、文化多元的当代社会，诉诸“人的本性”或“实践理性”能否得出所有人都能接受的结论，成为一个尖锐问题。Wacks 在讨论菲尼斯时指出，许多学生觉得他的家庭模型过于理想化、政治立场过于保守、基本善过于局限。这些批评反映了自然法理论在当代面临的核心挑战。", "principle": "评估自然法理论，可以从“它解决了什么问题”与“它制造了什么问题”两条线索展开。\n\n第一条线索：它解决的问题。法律实证主义把“是不是法律”系于社会来源，这带来一个后果：一项形式上完全合法、内容上极端邪恶的规则，在概念上仍是法律。实证主义者可以说“这是法律，但太邪恶不应服从”，但这一表述依赖一个独立于法律之外的道德判断。自然法理论则主张，法律的概念本身应包含道德维度，从而在概念层面就拒绝给恶法以“法律”的称号。这一做法的优势是：它使道德批判成为法律理论内部的组成部分，而非外部附加。\n\n第二条线索：它制造的问题。要把道德纳入法律概念，就必须回答“谁的道德”“哪种正当性”。这正是休谟式质疑的用武之地：从“人事实上追求某些善”能否推出“法律应当促进这些善”？菲尼斯明确承认，从“是”推出“应当”的论证是无效的，他因此拒绝从欲望或事实推导应当，转而诉诸实践理性对基本善的直接把握。但批评者会追问：实践理性对善的把握，是否真的具有普遍有效性，还是只是某一传统、某一阶层价值观的投射？\n\n第三条线索：确定性与灵活性的权衡。强自然法把严重不正义的规则排除出法律概念，这强化了道德批判，却可能损害法律安定性——如果每个人都可凭自己的正义观否认法律的效力，法律作为公共行为指引的功能将受损。软自然法则采取较温和的立场：不正义的法律仍是法律，但丧失服从的道德义务。Wacks 区分“硬自然法”与“软自然法”，正是要提示：自然法内部在这一点上并无共识。", "viewpoints": "自然法理论的优势，可归纳为四点。\n\n其一，它提供批判极权与暴政的概念工具。二战后，自然法语言成为控诉纳粹暴行的重要资源。富勒拒绝承认第三帝国的“法律”为法律，正是这一功能的体现。\n\n其二，它为人权与国际法提供正当性基础。《世界人权宣言》等文件所主张的普遍权利，其论证逻辑明显带有自然法色彩：某些权利属于人之为人，不因国界或实定法而改变。\n\n其三，它把法律理解为有目的的实践。富勒把法律视为“有目的的事业”，菲尼斯把法律指向共同的善，两人都强调法律是承载价值的社会实践，中性技术之称难以概括。\n\n其四，它强调法律与道德的关联，使法理学不致沦为纯粹的概念分析。Wacks 指出，自然法提醒人们关注法律与正义、权利、道德的关系，这是法律理论不可放弃的维度。\n\n自然法理论的批评，同样可归纳为四点。\n\n其一，概念含混。“人性”“理性”“自然”“共同善”这些核心概念，本身就没有统一定义，不同理论家可以赋予其不同内容。\n\n其二，“是—应当”问题。休谟指出，从描述性前提难以逻辑地推出规范性结论。菲尼斯虽承认这一点，但其“基本善自明”的主张，仍被批评为把有待论证的前提当成了出发点。\n\n其三，价值多元与主观任意。在一个价值多元的社会中，谁的“善”能被认定为普遍的？批评者认为，自然法往往把特定文化、特定阶层的生活形式包装成“自然”的要求。Wacks 提到对菲尼斯的具体批评：家庭模型过于理想化、政治过于保守、基本善过于狭隘。\n\n其四，损害法律安定性。强自然法允许法官以“不正义”为由否认法律效力，这可能打开主观任意的大门，削弱法律的可预测性。", "comparison": "自然法与法律实证主义的分歧，可以归结为对两个问题的不同回答。第一，“是不是法律”是否取决于道德？自然法说“是”，实证主义说“否”。第二，把道德纳入法律概念，是利大于弊还是弊大于利？自然法说“利”，实证主义说“弊”——因为这会牺牲法律的确定性与描述性。\n\n但这一对立不应被夸大。Wacks 反复提醒，实证主义并不主张法律不需要道德，也不主张恶法就是好法。哈特承认法律与道德在事实层面常相互渗透，也承认法律必须满足最低限度的自然法条件。菲尼斯也把“恶法非法”这类命题称为“松散的”表述。这表明，双方在很多具体判断上的距离，远比概念口号所显示的要小。\n\n自然法与法律现实主义的关系，则体现为另一种张力。现实主义怀疑规则能决定案件结果，强调法官的个人因素与社会后果；自然法则相信理性可以发现客观的正义标准。前者对规则决定力持怀疑态度，后者对理性的规范性力量保持信心。不过，富勒对法律“目的事业”的强调，与现实主义对法律社会效果的关注，存在某些相通之处。\n\n在自然法内部，菲尼斯与富勒的差别也值得注意。富勒走程序路线，把道德限定为法律的形式条件；菲尼斯走实体路线，提出一套客观的基本善。程序路线的优势是较少卷入价值争议，劣势是保证不了实质正义；实体路线的优势是提供具体价值标准，劣势是更容易被批评为价值独断。", "debates": "关于自然法优势与批评的经典争论，集中在“自然法是否空洞”这一问题上。\n\n批评者认为，自然法的核心命题——法律应当符合正义——几乎是同义反复：问“什么是正义的法律”，答案只是“正义的法律就是符合正义的法律”。如果自然法不能具体说明正义的内容，它就缺乏实践指导力。富勒的八项要求试图回应这一批评：它们把“法律的内在道德”具体化为可检验的程序标准。但哈特的反驳是，这些标准关乎效率而非道德，且满足它们并不保证法律正义。\n\n菲尼斯则以基本善理论回应。他承认基本善是实践理性直接把握的自明前提，经验事实推不出它们。Wacks 指出，菲尼斯明确拒绝从欲望推导应当，并同意休谟对“是—应当”论证的批评。但批评者认为，把基本善称为“自明的”，并不能证明其普遍性——它只是把争议推到了一个不再被追问的起点。\n\n另一场争论关乎自然法是否必然保守。批评者认为，诉诸“人的本性”与“传统”，往往强化既有社会结构，为现状提供正当性。菲尼斯被批评为家庭模型理想化、政治立场保守、基本善狭隘，正是这一批评的反映。菲尼斯的支持者则回应：基本善是普遍的、跨文化的人类善，对它们的追求需要制度条件，这恰恰可以为批判压迫性制度提供标准。\n\nWacks 的评论较为平衡：自然法与实证主义的争论虽重要，却并非定论（inconclusive）。他提醒读者，自然法理论的价值未必在于其语言学主张——即“法律”一词的定义——而在于它坚持法律必须接受道德追问这一实践立场。这一评论，为理解自然法的优势与局限提供了恰当的落脚点。", "case": "一个体现自然法优势与局限的现实案例，是国际刑事法院（International Criminal Court, ICC）对战争罪与反人类罪的追诉。ICC 的《罗马规约》（1998）把种族灭绝、反人类罪、战争罪等列为国际罪行，并主张这些罪行不因国内法的授权而免责。这一制度明显延续了自然法的思路：存在超越国家法律的、对人的尊严的基本保护。\n\n从优势角度看，ICC 的实践表明，自然法语言能够为追究大规模暴行提供法律基础，弥补国内法可能失效的漏洞。从局限角度看，ICC 的管辖权与定罪标准仍由国家间的条约与政治协商决定，不同国家对“正义”的理解存在分歧；批评者指责 ICC 的选择性起诉与地缘政治偏见，这正呼应了对自然法“谁的正义”的质疑。\n\n另一个案例是当代关于“不义法律”的公共讨论。当某地法律允许歧视、压迫或严重损害弱势群体时，社会运动者常诉诸“更高的正义”来要求改革。这种语言明显是自然法式的。但它同时引发争议：运动者所主张的“正义”是否真的普遍？还是特定群体的价值偏好？这再次说明，自然法的批判力量与不确定性是同一枚硬币的两面。", "caseAnalysis": "就国际刑事法院而言，事实是：国际社会建立了超越国家的刑事追诉机制，以处理最严重的暴行；争议焦点在于，这一机制的正当性根据是什么。从自然法视角看，人的尊严与基本权利构成超越国界的底线，任何国内法不得授权侵犯；这为 ICC 提供了正当性论证。从批评视角看，ICC 的标准与运作仍受国际政治影响，所谓“普遍正义”可能带有特定文化的印记。\n\n从制度理由看，《罗马规约》通过补充性原则（complementarity）处理与国际正义与国家主权的关系：只有在国家不愿或不能真正追究时，ICC 才介入。这一设计，试图在自然法的普遍主义与实证主义的国家同意之间取得平衡。\n\n这一案例的理论意义在于，它具体展示了自然法的双重面相：一方面，它提供了批判国家暴行、保护基本尊严的语汇；另一方面，它的实际操作仍离不开制度程序与政治协商，无法完全摆脱“谁来决定正义”的问题。对自然法的恰当评估，应当同时看到这两面：既承认它不可替代的批判功能，也不回避它在确定性与普遍性上的困难。", "summary": "自然法理论的优势在于：为批判恶法提供概念工具，为人权与国际法提供正当性基础，把法律理解为指向共同善的有目的实践，并坚持法律必须接受道德追问。其批评则集中在：核心概念含混、面临“是—应当”问题、在价值多元社会中可能流于主观任意、并有固化现状的保守风险。Wacks 区分硬自然法与软自然法，提示自然法内部对“恶法是否为法”并无共识；他对菲尼斯的具体批评，则提示把某种生活形式当作“自然”的危险。恰当的评价是：自然法的价值未必在于给出“法律”一词的唯一正确定义，而在于坚持法律与正义的关联不可被抹去。这一坚持使其在法律实证主义主导的时代仍保持生命力，但也要求它持续回应确定性与普遍性的质疑。", "furtherThinking": "1. 如果自然法不能给出确定的正义标准，它作为批判工具的价值是否会大打折扣？\n2. 菲尼斯把基本善称为“自明的”，这一策略是否成功回避了休谟的“是—应当”质疑？\n3. 国际刑事法院的实践在何种意义上体现了自然法的优势，又在何种意义上印证了对它的批评？"}, "en": "The Strengths and Criticisms of Natural Law Theory", "level": "core", "tags": "自然法, 法理学批判, 人权, 道德, 法律确定性", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.4, §2.7, §2.9；Finnis, Natural Law and Natural Rights", "id": "S2M1K7"}, "S2M2K1": {"title": "法律实证主义的起源与主张", "EN": "The Origins and Claims of Legal Positivism", "LEVEL": "core", "TAGS": "法律实证主义, 边沁, 分离命题, 法的有效性, 功利主义", "TERMS": "法律实证主义（Legal Positivism）::主张法律的存在取决于社会来源而非道德价值的理论；分离命题（Separation Thesis）::法律与道德在概念上可以或应当分开的主张；法的有效性（Legal Validity）::一项规则是否属于特定法律体系的问题；功利主义（Utilitarianism）::以最大多数人的最大幸福为评价标准的伦理理论；法的确定性（Legal Certainty）::法律应提供明确可预测的行为指引的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.3 §3.1—§3.4；Hart, The Concept of Law, ch.1, ch.5", "terms": [{"term": "法律实证主义（Legal Positivism）", "def": "主张法律的存在取决于社会来源而非道德价值的理论"}, {"term": "分离命题（Separation Thesis）", "def": "法律与道德在概念上可以或应当分开的主张"}, {"term": "法的有效性（Legal Validity）", "def": "一项规则是否属于特定法律体系的问题"}, {"term": "功利主义（Utilitarianism）", "def": "以最大多数人的最大幸福为评价标准的伦理理论"}, {"term": "法的确定性（Legal Certainty）", "def": "法律应提供明确可预测的行为指引的价值"}], "sections": {"coreQuestion": "法律实证主义（Legal Positivism）为什么在近代兴起？它的核心主张究竟是什么？本节要说明：实证主义是作为自然法的对立面出现的，它试图把法律从道德与形而上学的迷雾中拉回可观察的社会事实。边沁（Jeremy Bentham）对普通法与传统自然法的猛烈抨击，奥斯丁（John Austin）以命令界定法律，构成“古典实证主义”；哈特（H. L. A. Hart）、凯尔森（Hans Kelsen）、拉兹（Joseph Raz）则发展出更精细的“现代实证主义”。理解实证主义，关键要把握它是一套关于“如何识别法律”的理论；“法律不需要道德”属于对它最常见的误读。", "definition": "法律实证主义是一族共享若干核心承诺的理论。Wacks 指出，实证主义并非仅仅是法理学立场：其中心主张（无论表现为逻辑实证主义、科学实证主义、哲学实证主义、社会学实证主义还是法律实证主义）是，唯一真正的知识是科学知识。在法律领域，这一立场表现为拒斥形而上学的法律观，主张法律的研究应面向可观察、可描述的社会事实。\n\n法律实证主义的第一个核心命题是分离命题（Separation Thesis）：法律的存在与内容，取决于它是否由合法权威按照正确程序制定或认可（即它的来源），而不取决于它是否道德。第二个核心命题是法的有效性（Validity）来自社会来源：一项规则是不是法律，最终要看它能否通过一个社会的识别标准（如哈特的承认规则、拉兹的社会渊源）加以确认。第三个核心命题是描述性立场：法理学应当描述法律实际上是什么，而不是规定法律应当是什么。\n\n必须立即澄清一个常见误解：实证主义并不主张法律不需要道德，也不主张恶法就是好法。它主张的是，“是不是法律”与“是不是道德上正当”是两个应当分开判断的问题。哈特本人也承认，法律与道德在事实层面常常相互渗透，且法律必须满足某些最低限度的条件才能维持自身。把两者分开，恰恰是为了更清醒地批判恶法。", "history": "法律实证主义兴起于十八、十九世纪的功利主义与民族国家时代。边沁（1748—1832）把批判的矛头指向英国普通法（common law）与自然法理论。Wacks 把边沁称为“法理学的路德”（the Luther of jurisprudence），因为他像路德挑战教会权威一样，挑战了布莱克斯通（William Blackstone）所代表的传统法律观。边沁对自然法的抨击极为尖刻，他认为自然权利不过是“ nonsense upon stilts”（高跷上的胡言乱语）一类东西。\n\n边沁对普通法的批评集中在它的不确定性（indeterminacy）上。Wacks 指出，边沁认为普通法的“理论”与其实践相去甚远，规则表达不清，其效力本身就可疑。法律的不确定性会传染到合法性（legitimacy）：接受规则权威，往往就是接受法律整体的权威，而这会导致对法律的盲目服从。边沁的 remedy 是法典化（codification）与功利主义的清晰立法。\n\n奥斯丁（1790—1859）在《法理学范围之确定》（The Province of Jurisprudence Determined, 1832）中，把边沁的批判方向系统化，提出法律是主权者的命令（command）并以制裁为后盾。这构成“古典实证主义”的核心。进入二十世纪，凯尔森与哈特分别在欧陆与英语世界，以更精致的理论取代了奥斯丁的简单命令模型，使实证主义重新获得哲学尊严。", "principle": "法律实证主义的理论逻辑，可从三个层次把握。\n\n第一层是“法律是什么”的回答方式。实证主义把法律理解为一种社会制度，其存在完全取决于社会事实：谁有权制定、按什么程序制定、是否被实际接受。这使法律成为可以被经验地观察和描述的对象，符合近代科学主义的理想。\n\n第二层是分离命题的精确含义。分离命题有强弱两种版本。强版本（分离命题的“严格形式”）主张，法律与道德在概念上没有任何必然联系；弱版本只主张，法律的识别在原则上不依赖道德判断。Wacks 指出，哈特与拉兹在这一问题上仍有分歧：拉兹坚持只有社会来源能供给合法性标准（渊源命题），哈特则允许承认规则把道德标准纳入法律的有效性条件（包容实证主义）。\n\n第三层是描述性与承诺性的区分。实证主义坚持法理学应描述法律，而非美化或规定法律。拉兹区分了“承诺性陈述”（committed statements，即从法律体系内部接受其有效性）与“超脱性陈述”（detached statements，即描述某人或某体系的法律主张而不予接受）。这一区分使法学家可以在不认同某法律体系道德价值的前提下，准确描述其内容。\n\n第四层是承认规则的核心地位。在哈特的理论中，承认规则（Rule of Recognition）是法律体系中识别有效法律的最终标准，它本身无需更高规则授权，就存在于官员的共同实践之中。这一“最终标准”的安排，使法律体系获得自我识别的能力。", "viewpoints": "边沁的核心主张是功利主义与法律改革。他以“最大多数人的最大幸福”为评价标准，抨击自然权利与判例法的模糊性，主张通过法典化实现法律的确定性与可接近性。Wacks 指出，边沁坚定地“用事实的硬通货支付一切”（everything must pay up in the hard currency of fact），其对自然法的攻击极为猛烈。\n\n奥斯丁的核心主张是命令理论：法律是主权者发布的、以制裁为后盾的命令。主权者是社会大多数人习惯服从、而它自己不服从任何人的权威。Wacks 指出，奥斯丁区分按约建立的主权与以取得方式建立的主权，两者共同的逻辑是恐惧。\n\n哈特的核心主张是法律规则理论：法律的核心落在初级规则与次级规则的结合上，命令模型只是早期实证主义的遗产。Wacks 指出，哈特通过批判奥斯丁的“持枪者理论”（gunman theory）与凯尔森的基础规范（Grundnorm），提出了一种中性（neutral）的法律理论。哈特被 MacCormick 称为“休谟式的”（Humean），与“康德式的”凯尔森形成对照。\n\n凯尔森的核心主张是纯粹法学（Pure Theory of Law）：法律是关于“应当”（sollen）的规范体系，与关于“是”（sein）的事实和道德严格区分。法律体系的效力来自基础规范（Grundnorm），一个被假定为有效的最高规范。\n\n拉兹的核心主张是渊源命题：识别法律的存在与内容，只需诉诸社会来源，无需道德论证。Wacks 引述拉兹：若把法律的识别系于特定道德信念，就违反了渊源命题。", "comparison": "古典实证主义（边沁、奥斯丁）与现代实证主义（凯尔森、哈特、拉兹）之间存在明显差别。古典版本倾向于把法律还原为命令、制裁与主权者，模型简单但解释力有限；现代版本则把法律理解为复杂的规则体系或规范体系，强调法律的规范性（normativity）与制度结构，而非单纯的强制。\n\n实证主义与自然法的分歧集中在正当性来源上。自然法诉诸内容正义或理性秩序；实证主义诉诸社会来源。但二者并非完全不可调和：哈特的最低限度自然法、包容实证主义都显示出某种中间地带。Wacks 指出，拉兹的渊源命题与菲尼斯的自然法理论虽然结论相反，却共享一个前提：法律理论必须说明法律何以能主张权威。\n\n实证主义与法律现实主义的关系较为复杂。现实主义者也常被视为实证主义者，因为两者都拒绝自然法的形而上学；但现实主义把注意力转向法官实际行为，怀疑规则能决定案件结果，这与实证主义对规则体系的强调不同。Wacks 称美国法律现实主义为“现代法理学的一大悖论”：它既是经验主义的，又自称为实证主义。", "debates": "实证主义内部的第一场争论，是“分离命题”的强弱版本之争。拉兹的排他实证主义坚持，道德论证在识别法律的阶段没有立足之地；哈特的包容实证主义则允许，若一个社会的承认规则把道德标准纳入其中，道德可以成为法律有效性的条件。Wacks 指出，拉兹担心一旦允许道德论证进入法律识别，法律的确定性与描述性都会受损。\n\n第二场争论关乎法律的规范性。奥斯丁以制裁解释法律的约束力，哈特则在《法律的概念》中批判这一模型：抢匪的威胁能让人“不得不”（obliged）做某事，却无法产生“有义务”（obligation）做的规范体验。哈特主张，法律的核心在于规则被从“内部观点”（internal point of view）接受为行为理由。这一批判，使实证主义从“强制论”转向“规则论”。\n\n第三场争论关乎实证主义能否回应恶法。自然法论者批评实证主义无法批判纳粹法律；实证主义者的回应是：承认恶法为法律，再予以道德谴责，比否认其法资格更清醒、更负责。哈特与富勒的论战（见模块一第六节）正是这一争论的集中体现。Wacks 指出，这场论战无定论，却确立了效力与正当性的坐标。", "case": "英国宪法的例子，常被用来检验实证主义的法律识别理论。英国没有成文宪法典，其宪法由《大宪章》（Magna Carta, 1215）、《权利法案》（Bill of Rights, 1689）、议会制定法、司法判例以及大量宪法惯例（constitutional conventions）构成。从哈特的框架看，英国宪法的识别标准存在于官员的共同实践之中，承认规则未必写成单一文件。\n\n这一例子对实证主义既是支持也是挑战。支持在于：它说明法律体系的识别标准是一种社会事实（官员的实践），符合实证主义的基本方向。挑战在于：它表明法律与非法定的社会规范之间存在广阔的中间地带，法律的边界比“制定法＋制裁”的模型更为模糊。\n\n另一个例子是国际法。国际法没有世界政府与国际警察，若按奥斯丁的命令理论，它很难被称为法律。现代实证主义通过扩展“法律体系”的概念（如哈特承认原始法律体系的存在条件）来处理这一问题。这说明实证主义必须不断修正自己的模型，才能解释复杂的法律现象。", "caseAnalysis": "就英国宪法而言，事实是：不存在单一宪法文件，但英国宪法被普遍承认为有效法律秩序；争议焦点在于，不成文惯例是否属于法律的一部分。从哈特的视角看，识别标准存在于官员实践中——他们把某些惯例当作正当的行为标准来接受和使用；写在某处的条文并非其所在。这体现了“内部观点”（internal point of view）与承认规则的核心地位。\n\n从裁判理由看，英国法院在处理宪法性案件时，会诉诸宪法惯例与宪法性原则，尽管这些惯例缺乏严格的法律制裁。这说明法律体系的边界是开放的，实证主义必须容纳这种开放性。\n\n这一案例的理论意义在于，它展示了现代实证主义的解释力与局限。它能解释为何无成文宪法典仍有宪法（社会事实的识别标准），但也必须面对法律边界模糊带来的理论压力。对实证主义的恰当理解，应看到它提供了分析法律结构的工具，而非给出一个简单的法律定义。", "summary": "法律实证主义作为自然法的对立面兴起，其核心是主张法律的存在取决于社会来源而非道德价值。边沁以功利主义抨击自然法与普通法的不确定性，奥斯丁以命令理论开启古典实证主义，凯尔森、哈特、拉兹则发展出更精致的现代版本。实证主义的核心承诺包括分离命题、社会来源命题与描述性立场，但必须澄清：它主张的是“是不是法律”与“是否道德正当”应分开判断；“法律不需要道德”从来不是它的主张。实证主义内部在分离命题强弱、法律效力基础、承认规则是否可纳入道德等问题上存在持续争论；外部则面临自然法与法律现实主义的批评。英国宪法与国际法等例子，既展示了实证主义解释法律制度的工具价值，也暴露了其模型简化现实的局限。", "furtherThinking": "1. 实证主义坚持描述性立场，能否真正做到价值中立？请结合拉兹的承诺性／超脱性陈述分析。\n2. 分离命题的强弱版本之争，是否只是措辞之争？它会影响对具体案件的裁判吗？\n3. 英国宪法惯例的例子，对『法律＝制定法＋制裁』这一简单的实证主义模型构成何种挑战？"}, "en": "The Origins and Claims of Legal Positivism", "level": "core", "tags": "法律实证主义, 边沁, 分离命题, 法的有效性, 功利主义", "source": "Wacks, Understanding Jurisprudence, ch.3 §3.1—§3.4；Hart, The Concept of Law, ch.1, ch.5", "id": "S2M2K1"}, "S2M2K2": {"title": "奥斯丁的命令理论", "EN": "John Austin's Command Theory of Law", "LEVEL": "core", "TAGS": "法律实证主义, 奥斯丁, 命令理论, 主权者, 制裁", "TERMS": "命令理论（Command Theory）::把法律界定为主权者发布的、以制裁为后盾的命令的理论；主权者（Sovereign）::被社会大多数人习惯服从、而自身不服从任何人的权威；制裁（Sanction）::不服从命令时由国家施加的不利后果；持枪者理论（Gunman Theory）::哈特对奥斯丁模型的讽刺性概括，指其与匪徒持枪威胁相似；习惯性服从（Habitual Obedience）::奥斯丁用以说明主权者地位的事实性概念", "SOURCE": "Wacks, Understanding Jurisprudence, ch.3 §3.1, §3.3, §3.4；Hart, The Concept of Law, ch.1", "terms": [{"term": "命令理论（Command Theory）", "def": "把法律界定为主权者发布的、以制裁为后盾的命令的理论"}, {"term": "主权者（Sovereign）", "def": "被社会大多数人习惯服从、而自身不服从任何人的权威"}, {"term": "制裁（Sanction）", "def": "不服从命令时由国家施加的不利后果"}, {"term": "持枪者理论（Gunman Theory）", "def": "哈特对奥斯丁模型的讽刺性概括，指其与匪徒持枪威胁相似"}, {"term": "习惯性服从（Habitual Obedience）", "def": "奥斯丁用以说明主权者地位的事实性概念"}], "sections": {"coreQuestion": "奥斯丁（John Austin）为何把法律界定为“命令”？这一理论的三个要素是什么？它为何在法理学史上影响巨大，又为何被哈特（H. L. A. Hart）批评为过度简化？本节要说明：奥斯丁的命令理论是古典实证主义的典型形态，它成功地把法律研究从自然法的形而上学中拉回经验世界，却因无法解释法律的连续性、规范性与国际法现象，最终被哈特的规则理论取代。理解这一兴衰，是理解实证主义从古典走向现代的关键。", "definition": "奥斯丁（1790—1859）在《法理学范围之确定》（The Province of Jurisprudence Determined, 1832）中，提出法律的命令理论（Command Theory）。其核心公式可概括为：法律＝主权者的命令＋以制裁为后盾。\n\n这一定义包含三个要素。第一，命令（command）：法律是表达意愿的意志行为，由上级向下级发出，要求后者为或不为某种行为。第二，主权者（sovereign）：命令的来源是确定的权威。奥斯丁界定主权者为：社会大多数人习惯地服从其命令，而它自己不习惯服从任何确定的其他人。第三，制裁（sanction）：命令以不利后果为后盾，不服从将招致惩罚。缺乏制裁的命令，不构成严格意义上的法律。\n\n奥斯丁严格区分法律与道德。道德规则不具有“命令”的形式，也没有确定的发布者与制裁；法律则是明确的、由权威发布的、以强制力保障的。这一区分把法律研究对象从道德评价中剥离出来，使法学成为可经验研究的学科。Wacks 指出，奥斯丁与边沁同样坚定地站在实证主义一端，边沁“用事实的硬通货支付一切”，奥斯丁则紧随其后。", "history": "奥斯丁的理论是十九世纪英国政治与法律思想的产物。当时英国普通法（common law）占据主导，判例法体系庞杂、规则模糊，边沁已对其展开猛烈抨击。奥斯丁继承了边沁的批判方向，但更系统地回答“什么是法律”这一问题。\n\n当时的政治理论以主权（sovereignty）为核心概念。霍布斯（Thomas Hobbes）已把主权者的权威建立在恐惧与自我保存之上，并区分按约建立的主权与以取得方式建立的主权。Wacks 指出，奥斯丁同样讨论了这两种建立主权的方式，并认为二者共同的逻辑是恐惧——人们因害怕更坏的后果而服从权威。奥斯丁把这一政治理论转化为法理学的法律定义。\n\n奥斯丁任职于伦敦大学学院（University College London），是英国第一位法理学教授。他的讲稿虽在其生前影响有限，死后却产生巨大影响，成为分析法学（analytical jurisprudence）传统的奠基文本。Wacks 把其理论作为“古典法律实证主义”的核心代表。", "principle": "奥斯丁的命令理论可拆为三个逻辑环节。\n\n第一环是“命令”作为法律的形式。法律必须表达一种意志：主权者希望臣民为或不为某事。这一意志通过命令传达，构成法律的主观方面。奥斯丁由此把法律与那些非意志性的规则（如自然法则、道德箴言）区分开来。\n\n第二环是“主权者”作为法律的来源。法律的效力来自发布者的权威地位，而权威地位由“习惯性服从”这一社会事实构成。奥斯丁的主权者具有三个特征：持续被服从、自身不服从更高权威、意志具有普遍性。Wacks 指出，奥斯丁把法的效力基础系于主权（sovereignty），这与凯尔森以效力（efficacy）为基础的路径形成对照。\n\n第三环是“制裁”作为法律的保障。命令若无制裁相伴，就只是建议而非法律。制裁使法律区别于道德和宗教戒律。这一环节使奥斯丁的理论具有强烈的经验主义色彩：法律的存在可以被观察到——谁在发号施令、谁在服从、不服从会受到什么惩罚。\n\n然而，这一模型面临解释困难。Wacks 指出，把法律限定为命令，无法充分解释那些非命令形态的法律：习惯法并非任何人发布的命令；国际法没有世界主权者；授权性规则（如规定如何订立遗嘱、如何组成公司）提供的是便利，义务并不在其中。这些问题成为哈特批判的切入点。", "viewpoints": "奥斯丁的核心主张可概括为五点。\n\n其一，法律是主权者的命令。这是其理论的定义性命题，Wacks 将其置于“古典法律实证主义”的核心位置。\n\n其二，主权者是法律的确定来源。主权者的地位由习惯性服从构成，而非由法律授予——因为若由法律授予，就会陷入循环论证。\n\n其三，制裁是法律不可或缺的要素。没有制裁的命令，不构成严格意义上的法律。\n\n其四，法律与道德可以分离。法学研究“法律实际上是什么”，而道德评价属于另一个问题。这一分离命题是实证主义的核心承诺。\n\n其五，主权权力不受法律限制。Wacks 指出，奥斯丁认为授予 unlimited power 给政治主权者以惩罚，是相互义务的必然逻辑。主权者自身不能被法律约束，因为它正是法律的来源。", "comparison": "奥斯丁与边沁的关系，是继承与差异并存。两者都主张功利主义与法律改革，都反对自然法与普通法的模糊性，都站在实证主义一端。Wacks 的比较指出：边沁坚持一切都要用“事实的硬通货”支付，更接近实证主义的极端；奥斯丁虽有经验主义倾向，却也承认某些道德因素。两者的差别在于理论重心：边沁关注法律改革与法典化，奥斯丁关注法律的概念定义。\n\n奥斯丁与霍布斯的关系，是政治理论与法理学的关系。霍布斯在《利维坦》中以恐惧与自我保存论证主权者的绝对权威；奥斯丁把这一政治结论转化为法律定义。Wacks 指出，两人都以恐惧为统一解释：无论是按约建立的主权还是以取得方式建立的主权，其共同逻辑都是恐惧。\n\n奥斯丁与哈特的关系，是批判与超越。哈特在《法律的概念》第一章中，系统批判奥斯丁的命令模型。Wacks 指出，哈特以“持枪者理论”讽刺奥斯丁：若匪徒持枪命令你交出钱包，这也是命令＋威胁，但我们不会称其为法律。哈特的批判表明，奥斯丁模型未能解释法律的规范性与连续性。\n\n奥斯丁与凯尔森的关系，同为古典实证主义但路径不同。Wacks 指出，两者都试图以某种识别法律之所以为法律的标准来说明法律，但奥斯丁诉诸主权，凯尔森诉诸效力（efficacy）与基础规范（Grundnorm）。", "debates": "围绕奥斯丁的第一场争论，是制裁是否为法律的必要要素。奥斯丁坚持没有制裁就没有法律；哈特则反驳：许多法律规则（如授权性规则）并不以制裁为后盾，却无疑是法律。Wacks 指出，哈特对“作为制裁的法律”的批判是《法律的概念》的重要内容。这一争论推动实证主义从“强制论”走向“规则论”。\n\n第二场争论关乎主权者的界定。奥斯丁以“习惯性服从”界定主权者，但批评者指出：习惯性服从只是事实上的服从，无法解释为何人们“有义务”服从。哈特以“承认规则”与“内部观点”取代习惯性服从，试图解释法律的规范性。Wacks 指出，哈特认为奥斯丁的模型忽略了法律被接受为行为理由的维度。\n\n第三场争论关乎国际法。奥斯丁因国际法没有世界主权者，倾向于否认其严格意义上的法律地位。这一结论被批评为过度狭窄——国际法在国际实践中被普遍承认为法律。现代实证主义通过扩展法律体系的概念来处理这一问题，Wacks 指出哈特承认原始法律体系的存在条件，正是这一方向的努力。\n\nWacks 把奥斯丁称为“naive empiricist?”（天真的经验主义者？），以问号形式提示：奥斯丁的经验主义虽有洞见，却过度简化了法律的复杂结构。", "case": "一个检验奥斯丁模型的现实例子，是现代行政法中的授权性规则。各国法律普遍规定行政机关的设立、权限与程序，如《中华人民共和国行政许可法》规定哪些机关可以颁发许可、按什么程序颁发。这类规则赋予机关权力、提供行为框架，既不直接命令公民为或不为某事，也不以制裁为后盾。\n\n从奥斯丁的模型看，这类规则难以被解释为“主权者的命令＋制裁”，因为它们是授权性的而非义务性的。从哈特的视角看，这类规则属于次级规则（secondary rules），与初级规则共同构成法律体系。Wacks 指出，哈特批判奥斯丁的关键论据之一，正是命令理论无法解释法律的这一面向。\n\n另一个例子是国际法。联合国、世界贸易组织等国际机构并无世界政府式的权威，国际条约主要依赖国家同意与自我执行。若严格按奥斯丁的模型，国际法难以被称为法律；但国际法在国际关系中被实际遵守、被国际法院适用，其法律地位在实践中被广泛承认。这一张力，暴露了奥斯丁模型的解释局限。", "caseAnalysis": "就授权性规则而言，事实是：现代法律中大量规则赋予权力、设定程序，而非直接施加义务；争议焦点在于，这类规则是否属于法律。从奥斯丁的视角看，若没有命令与制裁，就难以纳入其定义。从哈特的视角看，这类规则是次级规则，是法律体系成熟的标志。\n\n从裁判理由看，当法院依据授权性规则审查行政行为是否越权时，它实际适用的正是这类规则——这证明它们具有法律效用。因此，命令理论的定义过于狭窄。\n\n这一案例的理论意义在于，它展示了概念定义对理论解释力的制约。奥斯丁试图用“命令＋制裁”这一简单模型统一解释所有法律现象，但法律实践的复杂性超出了这一模型。哈特以初级规则与次级规则的结合取而代之，正是为了更准确地描述法律的实际结构。", "summary": "奥斯丁的命令理论把法律界定为主权者的命令、以制裁为后盾，并通过“习惯性服从”界定主权者地位。这一理论作为古典实证主义的代表，成功地把法律从自然法的形而上学中剥离出来，使法学成为可经验研究的学科；其法律与道德分离的立场，也奠定了实证主义的基本方向。然而，这一模型面临严重解释困难：它无法说明授权性规则、习惯法与国际法的法律地位，也无法解释法律的规范性与连续性。哈特以“持枪者理论”讽刺其过度简化，并以规则理论取代之。Wacks 以“天真的经验主义者？”的问号概括奥斯丁：其洞见与局限同样鲜明。理解这一兴衰，是把握实证主义从古典走向现代的关键。", "furtherThinking": "1. 如果主权者的权威来自习惯性服从，这种纯粹事实性的服从能否解释公民『有义务』服从法律？\n2. 奥斯丁认为国际法不是严格意义上的法律，这一结论在当代国际法实践中是否站得住脚？\n3. 授权性规则（如规定如何订立遗嘱）不见得有制裁，为什么我们仍把它们当作法律？"}, "en": "John Austin's Command Theory of Law", "level": "core", "tags": "法律实证主义, 奥斯丁, 命令理论, 主权者, 制裁", "source": "Wacks, Understanding Jurisprudence, ch.3 §3.1, §3.3, §3.4；Hart, The Concept of Law, ch.1", "id": "S2M2K2"}, "S2M2K3": {"title": "凯尔森的纯粹法学", "EN": "Hans Kelsen's Pure Theory of Law", "LEVEL": "core", "TAGS": "法律实证主义, 凯尔森, 纯粹法学, 基础规范, 规范层级", "TERMS": "纯粹法学（Pure Theory of Law）::凯尔森主张的、排除道德社会学等混杂因素的法律理论；基础规范（Grundnorm / Basic Norm）::法律体系中作为效力最终根据的被假定的最高规范；规范层级（Hierarchy of Norms）::由基础规范向下授权构成的规范性等级结构；实效（Efficacy）::规范被实际遵守和适用的事实状态；应当（Sollen）::凯尔森用以界定法律规范的规范性范畴，与描述事实的『是』相对", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4 §4.3；Hart, The Concept of Law, ch.6", "terms": [{"term": "纯粹法学（Pure Theory of Law）", "def": "凯尔森主张的、排除道德社会学等混杂因素的法律理论"}, {"term": "基础规范（Grundnorm / Basic Norm）", "def": "法律体系中作为效力最终根据的被假定的最高规范"}, {"term": "规范层级（Hierarchy of Norms）", "def": "由基础规范向下授权构成的规范性等级结构"}, {"term": "实效（Efficacy）", "def": "规范被实际遵守和适用的事实状态"}, {"term": "应当（Sollen）", "def": "凯尔森用以界定法律规范的规范性范畴，与描述事实的『是』相对"}], "sections": {"coreQuestion": "凯尔森（Hans Kelsen）为何要创建一种“纯粹”的法学？他所谓的“纯粹”究竟排除了什么？基础规范（Grundnorm）在体系中起什么作用？本节要说明：凯尔森试图把法律理论从道德、政治、社会学与形而上学中彻底净化，建立一门像自然科学一样精密的规范科学。他以“基础规范”作为法律体系效力的最终根据，以规范层级解释法律效力，形成与奥斯丁命令理论、哈特规则理论并列的独特路径。理解凯尔森，是理解实证主义欧陆传统的关键。", "definition": "凯尔森（1881—1973）的纯粹法学（Pure Theory of Law）是一套严格的法律理论。其“纯粹性”体现在：它只研究法律本身，排除一切非法律因素——既排除道德评价（与正义无关），也排除社会学事实（不研究人们实际如何行为），还排除政治意识形态。凯尔森要建立的，是一门关于法律规范（norm）的科学。\n\n凯尔森把法律界定为规范（norm）体系，规范属于“应当”（Sollen）的范畴，而非描述事实的“是”（Sein）的范畴。Wacks 指出，凯尔森区分“是什么”（Sein）与“应当是什么”（Sollen），法律科学家关注的是规范所要求的应当行为，人的实际行为属于社会学考察的对象。\n\n基础规范（Grundnorm / Basic Norm）是凯尔森体系的核心。它是一个被假定为有效的最高规范，整个法律体系的效力都由此推导而来。基础规范本身无需另一条更高规范授权，它是法律思维得以可能的逻辑前提——类似于康德哲学中的先验范畴。Wacks 指出，基础规范位于规范层级的顶端。\n\n规范层级（Hierarchy of Norms）是基础规范向下授权形成的结构：宪法从基础规范获得效力，法律从宪法获得效力，行政法规从法律获得效力，个别裁判从行政法规获得效力。每一级规范的效力来自上一级的授权，最终追溯至基础规范。", "history": "凯尔森的思想深受康德（Immanuel Kant）哲学影响。MacCormick 的名言—“哈特是休谟式的，凯尔森是康德式的”—精准概括了两人的哲学气质差异。凯尔森是康德的追随者，试图建立一种先验的、逻辑严密的规范理论，与哈特的经验主义、渐进式理论形成对照。\n\n二十世纪初的欧陆，法律理论深受自然法、法律实证主义与社会学法学的影响。凯尔森希望超越这些纷争，建立一种价值中立、方法纯粹的法律科学。他曾参与奥地利宪法法院的工作，并起草1920年奥地利宪法，其理论与其对宪法审查制度的实践关切密切相关。\n\nWacks 指出，凯尔森是“你遇到的最不被理解的法律理论家”之一，其理论之难懂部分源于其高度的抽象性。Wacks 自己也承认，他多年来一直努力减少凯尔森给学生带来的“痛苦与煎熬”。但纯粹法学的重要性不容否认—Wacks 称其已成为法律理论中极为重要（即便影响力略逊）的分支。", "principle": "凯尔森的理论逻辑可拆为四个环节。\n\n第一环是事实与规范的二分。凯尔森严格区分“是”（Sein）与“应当”（Sollen）。关于“是什么”的陈述可以被真假检验，属于事实科学；关于“应当是什么”的陈述属于规范科学，不能被真假检验，只能被有效或无效评价。法律属于后者。这一二分使法律理论摆脱对经验事实的依赖，成为纯粹的规范科学。\n\n第二环是规范的效力链条。一条规范之所以有效，靠的是它由一条更高规范授权制定；道德上的正当、实际被遵守，都不是效力来源。效力（validity）是一种规范的归属关系：某规范属于某一法律体系，是因为它能被追溯到该体系的基础规范。\n\n第三环是基础规范的必要性。效力链条不能无限追溯，必须在某处停止。基础规范就是这一终点——它属于法律思维的逻辑前提，实证法序列在它之前止步。凯尔森把它理解为一种“假定”（hypothesis）：法律科学家为了描述法律体系，必须假定基础规范有效。Wacks 指出，拉兹后来把这一“虚幻地接受”（fictitiously accept）基础规范的做法，作为描述法律体系的必要条件。\n\n第四环是实效与效力的区分。凯尔森区分规范的效力（validity，属于应当层面）与实效（efficacy，属于是层面）。一条规范可能有效但实效不佳，也可能被实际遵守但无效。基础规范的效力预设了整个法律体系大体上具有实效——一个完全失效的法律体系，其基础规范也被认为不再有效。Wacks 指出，凯尔森把法的效力基础系于实效（efficacy），这与奥斯丁系于主权（sovereignty）形成对照。", "viewpoints": "凯尔森的核心主张可概括为五点。\n\n其一，法律是关于“应当”的规范体系，与“是”的事实严格区分。Wacks 指出，凯尔森合法地被归为法律实证主义者——他区分“是什么”与“应当是什么”，但远比一般实证主义复杂。\n\n其二，法律与道德必须分离。凯尔森坚持法律与道德话语之间的差异如此之大，以至于不能用道德标准判断法律的有效性。纯粹法学要把一切道德考量排除在法律科学之外。\n\n其三，基础规范是法律效力的最终根据。它是被假定为有效的最高规范，整个法律体系由此获得统一性。\n\n其四，法律科学不研究人的实际行为。Wacks 指出，凯尔森认为法律科学家关注的焦点是规范本身，人类行为留给因果科学。这一立场使纯粹法学与法律现实主义、社会学法学形成鲜明对照。\n\n其五，法律体系是动态规范体系。基础规范授权制定下级规范，形成层层授权的等级结构；法律的发展体现为规范的创制与废止，这一“动态”特征使纯粹法学区别于静态的自然法等级观。", "comparison": "凯尔森与奥斯丁的关系，同属古典实证主义而路径迥异。Wacks 指出，两者都试图说明法律之所以为法律的标准，但奥斯丁诉诸主权者的命令与制裁，凯尔森诉诸基础规范与效力。奥斯丁的模型具有强烈的经验与强制色彩，凯尔森的模型则是逻辑与规范性的。MacCormick 的名言—“哈特是休谟式的，凯尔森是康德式的”—虽针对哈特与凯尔森，也间接提示凯尔森与经验主义传统的距离。\n\n凯尔森与哈特的关系，是规范性与经验性的对照。Wacks 引述 MacCormick：哈特是休谟式的，凯尔森是康德式的。哈特从社会事实（官员的实践）出发解释法律的最终标准（承认规则），凯尔森则从逻辑前提（基础规范）出发。Wacks 还指出，凯尔森的体系具有“比哈特更强的规范性”（stronger normativity）。哈特在《法律的概念》第六章中讨论并批判了凯尔森的基础规范理论，认为它有必要但解释得不够好。\n\n凯尔森与自然法传统的关系，是彻底的对立。自然法把法律效力系于内容正义，凯尔森则坚持效力与道德无关。凯尔森比哈特更坚决地排斥自然法，Wacks 指出他对任何概念性法律思考（尤其自然法）都持怀疑态度。\n\n凯尔森与法律现实主义的关系，同样对立。现实主义关注法官实际做什么，凯尔森则坚持法律科学不研究人的实际行为。Wacks 指出，斯堪的纳维亚现实主义者（如罗斯）在某些方面与凯尔森有相似之处——都反对形而上学—但路径不同。", "debates": "围绕凯尔森的第一场争论，是基础规范的性质。批评者追问：基础规范究竟是实在的法律规范，还是法律理论的逻辑预设？若是前者，它的效力从何而来？若是后者，它如何能成为法律效力的真实根据？凯尔森倾向于把它理解为法律思维的“假定”（hypothesis），但这引发质疑：一个被假定的规范，如何能支撑整个法律体系的效力？Wacks 指出，哈特在《法律的概念》中接受了基础规范的某种必要性，但认为凯尔森对它解释得不够好。\n\n第二场争论关乎“纯粹性”是否可能。批评者认为，法律理论不可能完全排除道德与社会因素：选择研究什么、如何解释法律效力，本身就隐含价值判断。Wacks 指出，凯尔森的纯粹理论虽被批评为“paying a high price”，却仍是一项雄心勃勃的哲学事业。\n\n第三场争论关乎实效与效力的关系。凯尔森主张基础规范的效力预设法律体系大体具有实效，但批评者指出：若效力最终依赖实效，凯尔森就并未真正摆脱经验事实，他的“纯粹”规范理论也就打了折扣。", "case": "一个体现凯尔森理论现实影响的例子，是宪法审查制度。凯尔森曾参与起草1920年奥地利宪法，并担任奥地利宪法法院法官，是宪法审查制度的重要设计者。从规范层级看，宪法是位于普通法律之上的规范，普通法律不得抵触宪法；宪法法院的任务，正是审查普通法律是否符合宪法这一上位规范。\n\n这一制度的理论基础，正是凯尔森的规范层级理论：法律效力来自上位规范的授权，违宪法律因缺乏上位规范依据而无效。Wacks 提到，Raymond Wacks 本人曾撰写题为《一国两制基础规范？基本法与基础规范》的论文，把凯尔森的理论用于分析香港《基本法》—这说明基础规范理论在当代宪法理论中仍有生命力。\n\n另一个例子是国际法与国内法的关系。凯尔森试图用纯粹法学解释国际法：国际法也有自己的基础规范，国内法与国际法之间的关系可由规范层级理论说明。这一努力虽未完全成功，却展示了纯粹法学试图统一解释所有法律现象的雄心。", "caseAnalysis": "就宪法审查而言，事实是：宪法法院有权审查并撤销违宪的普通法律；争议焦点在于，法院凭什么宣告一项由合法机关制定的法律无效。从凯尔森的规范层级看，答案在于：普通法律的效力来自宪法授权，违宪法律因超越授权而缺乏效力根据。从裁判理由看，法院所做的工作，正是识别并维护规范层级中的效力链条。\n\n从理论意义看，宪法审查制度为凯尔森的抽象理论提供了制度对应物：规范层级是现代宪政的制度现实，纯粹思辨之说难以概括。但同时，它也暴露了理论的局限：规范层级并不能说明“谁来解释宪法”这一现实政治问题，凯尔森的纯粹法学有意回避了这一维度。\n\n这一案例说明，凯尔森的理论长于解释法律效力结构，短于解释法律运作中的政治与经验因素。这正是其“纯粹性”的代价：它提供了高度清晰的概念工具，却刻意悬置了法律实践中的许多复杂因素。Wacks 称凯尔森的理论“subtle and profound”，同时承认其理解难度，这一评价恰如其分。", "summary": "凯尔森的纯粹法学试图建立一门排除道德、社会学与政治因素的法律科学。他以“是”（Sein）与“应当”（Sollen）的区分为根基，把法律界定为规范体系；以基础规范（Grundnorm）作为法律效力的最终逻辑前提；以规范层级解释法律体系内部的效力链条；以实效与效力的区分处理规范与实际的关系。这一理论比哈特更具规范性，体现康德的哲学气质（MacCormick：哈特是休谟式的，凯尔森是康德式的）。其主要争论集中在基础规范的性质、纯粹性的可能与实效和效力的关系上。宪法审查制度为规范层级理论提供了现实对应，但也暴露其回避政治与经验维度的局限。凯尔森的贡献在于提供了高度清晰的法律结构分析工具，其代价则是抽象性与解释力的边界。", "furtherThinking": "1. 基础规范若只是法律思维的『假定』，它能否真正支撑法律体系的效力？请比较哈特承认规则的处理方式。\n2. 凯尔森把法的效力系于实效，这是否削弱了他所标榜的『纯粹性』？\n3. 宪法审查制度在何种意义上印证了规范层级理论，又在何种意义上超出了它？"}, "en": "Hans Kelsen's Pure Theory of Law", "level": "core", "tags": "法律实证主义, 凯尔森, 纯粹法学, 基础规范, 规范层级", "source": "Wacks, Understanding Jurisprudence, ch.4 §4.3；Hart, The Concept of Law, ch.6", "id": "S2M2K3"}, "S2M2K4": {"title": "哈特的法律规则理论", "EN": "H. L. A. Hart's Theory of Legal Rules", "LEVEL": "core", "TAGS": "法律实证主义, 哈特, 初级规则, 次级规则, 承认规则, 内部观点", "TERMS": "初级规则（Primary Rules）::直接规定人们应为或不为某种行为的规则；次级规则（Secondary Rules）::规定如何识别、改变与裁判初级规则的程序性规则；承认规则（Rule of Recognition）::用以识别哪些规则属于有效法律的最终标准；内部观点（Internal Point of View）::参与者把规则当作正当行为理由来接受和使用的态度；开放结构（Open Texture）::语言在边缘地带存在不确定性的特征", "SOURCE": "Hart, The Concept of Law, ch.1, ch.5—ch.7, ch.9；Wacks, Understanding Jurisprudence, ch.4 §4.2", "terms": [{"term": "初级规则（Primary Rules）", "def": "直接规定人们应为或不为某种行为的规则"}, {"term": "次级规则（Secondary Rules）", "def": "规定如何识别、改变与裁判初级规则的程序性规则"}, {"term": "承认规则（Rule of Recognition）", "def": "用以识别哪些规则属于有效法律的最终标准"}, {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作正当行为理由来接受和使用的态度"}, {"term": "开放结构（Open Texture）", "def": "语言在边缘地带存在不确定性的特征"}], "sections": {"coreQuestion": "哈特（H. L. A. Hart）为何用“规则”取代“命令”来界定法律？初级规则与次级规则的结合为什么是法律体系的核心？承认规则、内部观点与开放结构分别解决什么问题？本节要说明：哈特在批判奥斯丁命令理论与凯尔森基础规范理论的基础上，提出法律是初级规则与次级规则的结合，并以承认规则作为法律体系的最终识别标准。这一理论使实证主义从“强制论”转向“规则论”，成为二十世纪法理学的里程碑。", "definition": "哈特（1907—1992）在《法律的概念》（The Concept of Law, 1961；第二版 1994，第三版由 Leslie Green 作导论、含德沃金后记）中，提出以规则理论为核心的法律实证主义。其核心命题是：法律体系的核心在于初级规则（primary rules）与次级规则（secondary rules）的结合。\n\n初级规则直接规定人们应当做或不做某事，如“不得杀人”“应当纳税”。它们要求人们为或不为特定行为，无论其愿意与否。次级规则则规定如何识别、改变与裁判初级规则。哈特区分三种次级规则：承认规则（Rule of Recognition）用以确定哪些规则是有效法律；改变规则（Rule of Change）用以规定如何制定、修改或废止法律；裁判规则（Rule of Adjudication）用以规定谁有权判定初级规则是否被违反。\n\n承认规则是哈特理论中最重要的概念。它是法律体系中识别有效法律的最终标准，本身无需另一条更高规则授权，就存在于官员的共同实践中。Wacks 转述《法律的概念》中的观点：法律的真正根据在于共同体作为一个整体对一项根本的“主规则”（即承认规则）的接受。对奥斯丁而言，加州限速55英里的规定为真，只因制定它的立法者恰好在当地掌权；对哈特而言，这一规定为真，是因为加州人民接受并持续接受州与联邦宪法所确立的权威体系。\n\n内部观点（internal point of view）指参与者把规则当作正当的行为理由来接受和使用：他们用规则来证成决定、批评他人。外部观点（external point of view）则只是从外部观察规律性地发生了什么。哈特强调，法律体系的存在既需要官员从内部观点接受承认规则，也需要公民在相当程度上遵守规则。", "history": "哈特的理论诞生于二十世纪中叶的牛津，深受日常语言哲学（ordinary language philosophy）与休谟经验主义传统影响。MacCormick 的名言—“哈特是休谟式的，凯尔森是康德式的”—精准概括了两人的气质差异：哈特从社会事实与人类实践出发，渐进地建构理论；凯尔森则从逻辑前提出发，追求体系的纯粹与严密。\n\n哈特在《法律的概念》第一章中，系统批判奥斯丁的命令理论。Wacks 指出，哈特批判了奥斯丁的“持枪者理论”（gunman theory）与凯尔森的基础规范（Grundnorm），提出了一种中性的法律理论。哈特认为，把法律理解为命令，无法解释法律的连续性、规范性与授权性规则；而凯尔森的基础规范虽有必要，却解释得不够好。\n\n二战后极权主义的经验，也深刻影响了哈特。他与富勒（Lon Fuller）在1958年展开著名论战，并在《法律的概念》第九章提出“最低限度的自然法”概念，承认法律必须满足某些基于人性的条件。这些论述表明，哈特的实证主义试图在概念清晰与道德关切之间取得平衡，对道德问题无动于衷的印象需要修正。", "principle": "哈特的理论逻辑可拆为四个层次。\n\n第一层是从“命令”到“规则”的转向。哈特指出，命令模型无法解释法律的三个面向：其一，法律具有连续性—一部法律在制定它的政府下台后仍有效；其二，法律具有广泛性—许多法律规则的功能在赋予权力（如订立遗嘱的规则），命令任何人做事并非其任务；其三，法律的规范性—抢匪的威胁让人“不得不”（obliged）交出钱包，却不能产生“有义务”（obligation）交钱的规范体验。规则模型则能解释这些现象。\n\n第二层是初级规则与次级规则的结合。哈特设想一个只有初级规则的社会（前法律社会），这类社会存在三个缺陷：不确定性（哪些规则有效不明确）、静态性（规则难以有意识地改变）、无效性（争议无法权威解决）。次级规则的引入分别对应解决这三个缺陷：承认规则解决不确定性，改变规则解决静态性，裁判规则解决无效性。三者结合，使前法律社会转变为法律社会。\n\n第三层是承认规则的终极地位。承认规则是法律体系的基础，它关乎存在与否，有效或无效的问题在它这里派不上用场——它存在于官员的共同实践中。哈特认为，承认规则可以是复杂的、由多种标准构成的（如成文宪法、判例、惯例等），其核心特征是：官员们从内部观点把它接受为识别法律的共同标准。\n\n第四层是开放结构与司法裁量。哈特承认语言具有“开放结构”（open texture）：在边缘案例中，规则的语词可能无法确定地涵盖当前情形。此时法官需要进行裁量，但这种裁量并非任意——它仍在法律框架内进行，且大多数案件都有明确答案。哈特在这一问题上既反对机械形式主义，也反对规则怀疑论。", "viewpoints": "哈特的核心主张可概括为五点。\n\n其一，法律是初级规则与次级规则的结合。这是哈特对“法律是什么”的核心回答，Wacks 将其作为理解哈特理论的入口。\n\n其二，承认规则是法律体系的最终标准。它存在于官员实践中，是法律体系统一性的基础。Wacks 转述：法律的真正根据在于共同体对根本主规则的接受。\n\n其三，法律体系的存在需要内部观点。仅有习惯性服从不足以构成法律体系；官员必须从内部观点接受承认规则，把它当作行为理由与批评标准。\n\n其四，法律与道德可以分离，但存在最低限度的自然法。哈特坚持在概念上区分“是不是法律”与“是否道德正当”，同时基于人的脆弱性、大体平等、有限利他主义、有限理解力等事实，承认法律必须包含禁止暴力等最低条件以维持自身。\n\n其五，语言有开放结构，法官在疑难案件中有裁量权，但受法律框架约束。这一立场使哈特既区别于形式主义，也区别于法律现实主义。", "comparison": "哈特与奥斯丁的关系，是批判与超越。哈特以“持枪者理论”讽刺奥斯丁的模型，指出威胁与义务的区别：威胁产生的是“被迫”（obliged），而非“义务”（obligation）。哈特以规则理论取代命令理论，解释了法律连续性、授权性规则与规范性。\n\n哈特与凯尔森的关系，是经验与逻辑的对照。Wacks 引述 MacCormick：哈特是休谟式的，凯尔森是康德式的。哈特的承认规则存在于官员的社会实践中，凯尔森的基础规范则是逻辑假定。Wacks 还指出，凯尔森的体系具有比哈特“更强的规范性”。哈特在《法律的概念》第六章中既承认基础规范的必要性，又批评其解释不足。\n\n哈特与富勒的关系，是实证主义与自然法之争的集中体现。富勒主张法律与道德有必然联系，哈特主张分离，并认为承认恶法为法有助于更清醒地批判恶法。Wacks 指出，这场论战无定论，却确立了效力与正当性的坐标。\n\n哈特与德沃金的关系，是后期法理学的重要争论。德沃金在《法律的概念》第三版后记（Postscript）中批评哈特忽视法律原则，认为法律不仅包含规则，也包含道德原则。哈特的回应是：承认规则可以容纳原则，但这不改变实证主义的核心。Wacks 指出，德沃金把法律与道德的关系理解为解释性的关系，提出“怀疑的解释性判断”（sceptical interpretive judgment）等概念。", "debates": "围绕哈特的第一场争论，是承认规则的性质。批评者追问：承认规则存在于官员实践中，这是否意味着它只是一种社会事实？若如此，它如何产生规范性？哈特的回应是：承认规则的存在本身即包含接受它的内部观点，事实与规范在此交织。这一争论把法理学带向对“社会事实能否产生规范性”的深层讨论。\n\n第二场争论关乎开放结构与司法裁量。形式主义者批评哈特过分强调语言的不确定性，削弱了法律的确定性；法律现实主义者则批评哈特过于保守，低估了法官创造法律的空间。哈特在两者之间寻找中间道路：在大多数案件中规则有确定答案，只在边缘地带存在裁量。\n\n第三场争论关乎法律与道德的关系。富勒批评哈特对恶法的处理不够严肃；德沃金则从内部批评哈特的规则模型，主张原则是法律的一部分。Wacks 指出，德沃金认为哈特的模型无法充分解释法律实践中的道德维度。\n\nWacks 将哈特的理论概括为“中性理论”（neutral theory），它试图在奥斯丁的“gunman”理论与凯尔森的 Grundnorm 之间，找到一条既承认法律的社会基础、又解释其规范性的道路。", "case": "一个体现哈特理论的现实例子，是司法判例中的“遵循先例”（stare decisis）制度。在英美法系中，法院在裁判时会遵循上级法院与本院先前的判决。从哈特的框架看，遵循先例既涉及初级规则（实体法规则），也涉及次级规则——特别是裁判规则（谁有权裁判）与承认规则（哪些先例具有约束力）。\n\n当法院面对一个先例是否适用的争议时，它实际在运用承认规则的标准：哪些判决构成本法域的有约束力先例？这些标准往往存在于司法共同体的实践中，单一法条很少能容纳它们。这正体现了哈特的核心观点：承认规则是官员共同实践中的社会事实。\n\n另一个例子是疑难案件中的司法裁量。当法律语词在边缘地带含义不清时（如“车辆”是否包括自行车进入公园），法官需要作出判断。哈特会承认这里存在开放结构与裁量，但强调法官仍须在法律体系的价值框架内论证，而非随意创造。Wacks 指出，洞穴探险者案中不同法官的意见，正展示了不同法律理论对疑难案件的处理方式。", "caseAnalysis": "就遵循先例而言，事实是：法院依据先前判决裁判，但并非所有先例都有同等约束力；争议焦点在于，识别先例约束力的标准是什么。从哈特的视角看，这一标准存在于司法共同体的实践中，是承认规则的具体体现。从裁判理由看，法官在判断某先例是否适用时，会诉诸一系列实践标准（法院层级、判决理由与附带意见的区分、事实类似性等），这些标准共同构成承认规则的内容。\n\n这一案例的理论意义在于，它把哈特的抽象概念具体化：承认规则就是司法实践中实际运作的识别标准，神秘的“最高规范”印象随之消解。同时，它也展示了开放结构的现实存在——先例的适用范围总可能有争议，法官的裁量不可避免。\n\n对哈特理论的恰当理解，应看到它的双重贡献：既解释了法律体系如何以社会事实为基础而运作（承认规则存在于实践中），又解释了法律何以能提供确定性与规范性（内部观点与规则的接受）。Wacks 称哈特的工作“illuminated the meaning of legal concepts”—照亮了法律概念的意义，这一评价恰当地概括了其理论价值。", "summary": "哈特以规则理论取代命令理论，主张法律体系的核心是初级规则与次级规则的结合。次级规则中的承认规则、改变规则与裁判规则，分别解决前法律社会的不确定性、静态性与无效性。承认规则作为识别有效法律的最终标准，存在于官员的共同实践中，法律体系的存在需要官员从内部观点接受它。哈特还提出语言的开放结构与司法裁量，在形式主义与规则怀疑论之间寻找中间道路，并基于人性事实承认“最低限度的自然法”。这一理论既批判了奥斯丁的命令模型，又修正了凯尔森的基础规范理论，成为二十世纪实证主义的典范。它与富勒、德沃金的争论，持续塑造着法理学的基本问题结构。", "furtherThinking": "1. 承认规则存在于官员的实践中，这种社会事实如何产生『有义务』服从法律的规范性？\n2. 语言的开放结构是否意味着法官在疑难案件中实际在创造法律？哈特的裁量理论能否回应规则怀疑论？\n3. 哈特承认『最低限度的自然法』，这是否意味着他事实上放弃了分离命题？"}, "en": "H. L. A. Hart's Theory of Legal Rules", "level": "core", "tags": "法律实证主义, 哈特, 初级规则, 次级规则, 承认规则, 内部观点", "source": "Hart, The Concept of Law, ch.1, ch.5—ch.7, ch.9；Wacks, Understanding Jurisprudence, ch.4 §4.2", "id": "S2M2K4"}, "S2M2K5": {"title": "法律效力与道德正当性的区分", "EN": "The Distinction Between Legal Validity and Moral Legitimacy", "LEVEL": "debate", "TAGS": "法律效力, 道德正当性, 分离命题, 哈特, 富勒, 拉德布鲁赫", "TERMS": "法律效力（Legal Validity）::一项规则是否属于特定法律体系的有效法律；道德正当性（Moral Legitimacy）::法律在道德上是否值得服从的性质；分离命题（Separation Thesis）::法律效力与道德价值在概念上可分开判断的主张；拉德布鲁赫公式（Radbruch Formula）::极端不正义的法律丧失法性质的准则；最低限度的自然法（Minimum Content of Natural Law）::哈特承认的法律维持自身所需的人性条件", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.10, ch.4 §4.5；Hart, The Concept of Law, ch.9, Postscript", "terms": [{"term": "法律效力（Legal Validity）", "def": "一项规则是否属于特定法律体系的有效法律"}, {"term": "道德正当性（Moral Legitimacy）", "def": "法律在道德上是否值得服从的性质"}, {"term": "分离命题（Separation Thesis）", "def": "法律效力与道德价值在概念上可分开判断的主张"}, {"term": "拉德布鲁赫公式（Radbruch Formula）", "def": "极端不正义的法律丧失法性质的准则"}, {"term": "最低限度的自然法（Minimum Content of Natural Law）", "def": "哈特承认的法律维持自身所需的人性条件"}], "sections": {"coreQuestion": "法律效力与道德正当性的区分，是实证主义与自然法之争的核心。问题的提法是：判断一项规则“是不是有效的法律”，与判断它“在道德上是否正当”，究竟是同一个问题还是两个问题？如果是两个问题，二者能否以及如何分开？这一区分听起来抽象，却直接决定法官面对极端邪恶的法律时应如何裁判、公民面对不义之法时有无抵抗义务。本节把各种立场放在同一框架中，逐一检视其论据与后果，并说明为何这场争论至今没有定论。", "definition": "法律效力（Legal Validity）回答的是“这是否是一项有效的法律”：一项规则是否属于某一特定法律体系，能否被该体系的识别标准确认为有效。对实证主义而言，这取决于社会来源——规则是否由合法权威按正确程序制定，是否能被承认规则识别。道德正当性（Moral Legitimacy）回答的是“这项法律在道德上是否值得服从”：它是否公正、是否尊重人的尊严、是否促进共同善。\n\n分离命题（Separation Thesis）主张，这两个问题在概念上应当分开。一项规则可以有效但不道德（恶法），也可以道德上可取但不是有效法律（如尚未立法的道德要求）。分离命题的根据在于：把道德考量混入法律识别，会损害法律的确定性与公共可识别性。\n\n需要立刻澄清：分离命题绝不等于“法律与道德无关”或“恶法亦好法”。哈特明确承认，法律与道德在事实层面常常相互渗透，也承认法律必须满足某些“最低限度的自然法”条件才能维持自身。分离命题的精确含义是：在概念层面，“是不是法律”与“是否道德正当”是两个应当分别回答的问题。", "history": "效力与正当性的区分，在近代主权国家兴起后获得明确形态。边沁（Jeremy Bentham）与奥斯丁（John Austin）把法律定义为有权机关制定的命令，从而把法律效力系于来源而非内容。这一转向使法学摆脱自然法的形而上学，成为可经验研究的学科。\n\n二十世纪的极权主义经验，使这一区分获得新的紧迫性。若法律效力完全系于来源，纳粹德国那些形式有效的法律就都是“法律”，法理学似乎失去了批判暴政的概念工具。二战后，德国法学家古斯塔夫·拉德布鲁赫（Gustav Radbruch）提出，当制定法与正义的矛盾达到“不可容忍”的程度时，该法律丧失法的性质。这被称为“拉德布鲁赫公式”。\n\n哈特与富勒在1958年的《哈佛法律评论》上展开论战，把这一议题推向法理学中心。富勒主张法律有“内在道德”，纳粹法律严重违反之，因而不配称为法律；哈特则坚持承认恶法为法、再予以谴责，才是更清醒的批判方式。Wacks 指出，这场论战无定论，却确立了效力与正当性这一此后所有法理学都必须面对的坐标。", "principle": "效力与正当性的关系，可用四种模型来定位。\n\n模型一：强自然法。严重不正义的规则丧失法的资格，效力取决于道德正当性。其优点是为抵抗暴政提供直接概念工具；其缺点是“何谓严重不正义”缺乏确定标准，可能损害法律安定性。\n\n模型二：弱自然法。不正义的法律仍是有效法律，但丧失服从的道德义务。其优点是兼顾法律确定性与道德批判；其缺点是“自然法”的独特贡献变得模糊——因为实证主义者也会说同样的话。\n\n模型三：排他实证主义（拉兹）。法律效力只取决于社会来源，道德论证在识别阶段无立足之地。拉兹的渊源命题（Sources Thesis）主张：识别法律的存在与内容，不需要也不应诉诸任何道德论证。其优点是法律确定性与描述性；其缺点是难以解释法律何以能主张权威。\n\n模型四：包容实证主义（哈特后期）。法律识别一般诉诸社会来源，但若一个社会的承认规则把道德标准纳入其中，道德可成为法律效力条件。其优点是承认法律实践的现实复杂性；其缺点是可能模糊实证主义与自然法的界限。\n\n哈特还提出“最低限度的自然法”这一精细限定。基于人的脆弱性、大体平等、有限利他主义、有限理解力与意志力等事实，哈特认为任何法律体系都必须包含禁止暴力、保护财产、要求信守承诺等基本内容，否则无法维持自身。Wacks 指出，这一限定表明哈特把联系定位为“法律存在的必要条件”，并未将其提升为“法律概念的必然道德要素”，完全无视联系的说法因此站不住。", "viewpoints": "哈特的核心主张是：在概念上区分法律效力与道德正当性。他认为，把极端邪恶的规则排除出法律概念，反而会遮蔽对其性质的认识；承认它是法律，然后明确宣布其道德上的极端邪恶，才是更清醒的批判方式。哈特还区分了法律的“最低限度的自然法”与道德正当性：前者是法律存在的事实条件，后者是价值评价。\n\n富勒的核心主张是：法律具有内在道德，八项程序性要求（一般性、公开性、不溯及既往、清晰、不矛盾、可履行、稳定、官方行为与规则一致）是法律体系的概念性条件。纳粹法律严重违反这些要求，因而不构成法律体系。Wacks 强调，富勒采取的是程序性自然法进路：他并不主张法律内容必须正义，只主张法律必须具备形式合法性。\n\n拉兹的核心主张是渊源命题：识别法律只诉诸社会来源，无需道德论证。Wacks 引述拉兹：若把法律的识别系于特定道德信念，就违反了渊源命题。拉兹据此批评包容实证主义，也区分承诺性陈述（从体系内部接受法律有效）与超脱性陈述（描述而不接受）。\n\n德沃金（Ronald Dworkin）提供第三种视角。他批评实证主义把法律理解为规则体系，主张法律还包含道德原则；在疑难案件中，法官须通过“整体性”（integrity）的解释，从法律实践中提炼出最能证成既往实践的原则。Wacks 指出，德沃金把这一解释性判断称为“怀疑的解释性判断”（sceptical interpretive judgment），它既不同于强自然法的本体论主张，也不同于实证主义的分离命题。\n\n拉德布鲁赫的核心主张是：当制定法与正义的矛盾达到不可容忍程度时，法律丧失法的性质。这一公式在德国战后司法中被援引，但其标准模糊性也引发争议。", "comparison": "四种模型的根本分歧，在于“不道德”是否影响“法资格”。强自然法说是，实证主义说否，弱自然法居于中间但立场模糊。这一分歧在日常直觉中都能找到支持者：面对极端暴政，人们倾向于否认恶法的效力；面对日常法律，人们又希望法律保持确定与稳定。理论的困难在于如何一贯地处理这两种直觉。\n\n哈特与富勒的关键分歧，在于内在道德的性质。哈特认为富勒的八项要求关乎法律能否有效运作（efficacy），属于效率问题；富勒则坚持它们构成“愿望的道德”。Wacks 指出，许多评论者认为富勒的论证实际上只支持偶然联系，而非必然联系——满足八项要求的法律体系仍可能是极端邪恶的，南非种族隔离法就是常被援引的反例。\n\n拉兹与哈特的分歧，在于道德能否通过承认规则进入法律。哈特的包容实证主义允许这种可能，拉兹的排他实证主义坚决反对。Wacks 指出，拉兹担心一旦允许道德论证进入法律识别，法律确定性将受损，法律理论也难以保持描述性。\n\n德沃金与哈特的分歧，在于法律是否只包含规则。哈特后期承认承认规则可以把原则纳入，但坚持这仍属社会来源的识别；德沃金则主张原则的有效性根植于道德解释，而非单纯的社会来源。Wacks 指出，德沃金把法律与道德的关系理解为一种解释性关系，这构成对实证主义的根本挑战。", "debates": "哈特—富勒论战（1957—1959）是这一主题的核心文本。Wacks 指出，论战发表于1958年《哈佛法律评论》71卷，哈特与富勒分别撰文。论战的直接背景是二战后如何处理纳粹法律问题。\n\n论战的第一个分歧是：法律与道德是否存在必然联系？富勒说是（程序性的），哈特说否（只有偶然联系与最低限度条件）。第二个分歧是：内在道德是否真的是道德？哈特认为它关乎效率，富勒坚持它是愿望的道德。第三个分歧是：极端邪恶的规则是否应被称为法律？富勒拒绝，哈特接受。\n\nWacks 指出一个耐人寻味的细节：双方都倾向于认为，在洞穴探险者案中颁布溯及既往的立法是可取的——这说明两人在具体问题上并非总是立场对立，分歧更多在概念层面。Wacks 还指出，论战没有胜负，但它确立了一个坐标：任何法律理论都要交代效力与正当性的关系。\n\n拉德布鲁赫公式本身也引发争论。支持者认为它为法官拒绝适用极端邪恶的法律提供了准则；反对者认为它损害法律安定性，且“不可容忍的不正义”标准过于模糊，可能沦为法官主观偏好的工具。这一争论的深层，是法的安定性与正义之间的价值冲突。", "case": "德国战后“告密者案”（Informer Case，联邦最高法院，1951年）是检验这些立场的经典案例。案情大致是：被告在纳粹时期向当局告发他人，导致后者被处死；战后，被告依据当时有效的纳粹法律为自己辩护，主张其行为合法。法院最终判定被告有罪，理由大致是：纳粹政权中那些允许迫害无辜者的法律，违背了文明社会的基本法律原则，丧失了法的效力。\n\n从强自然法视角看，法院做法完全正确——违背基本正义的“法律”自始无效。从哈特的视角看，法院的结论在道德上可以理解，但概念上更诚实的做法是：承认那些法律在形式上有效，同时明确宣告其道德上的极端邪恶，并据此正当化对被告的惩罚。拉德布鲁赫公式则为法院提供了折中的裁判语言：极端不正义的法律丧失法性质。\n\n另一个对照案例是南非种族隔离时期的法律。Wacks 提到，富勒认为南非的种族隔离立法严重偏离了法律的内在道德。但批评者指出：种族隔离法律在形式上可能符合公开性、一般性、不溯及既往等要求，这说明满足富勒的八项要求并不足以保证实质正义。这一点成为反驳富勒“内在道德足以区分法律与蛮力”的重要论据。", "caseAnalysis": "就告密者案而言，事实是：被告依当时有效法律实施告发行为，战后被追诉；争议焦点在于是否承认那些法律的效力。从自然法视角看，极端不正义的法律丧失正当性，不能作为辩护理由。从实证主义视角看，应承认那些法律形式上有效，同时在道德上予以谴责。\n\n从裁判理由看，法院实际采取拉德布鲁赫式立场：在法律安定性与正义的冲突中，当矛盾达到不可容忍程度时，正义优先。这一立场的优点是为抵抗极端邪恶提供法律语言；风险则在于标准模糊，可能打开法官以个人道德否定法律的大门。\n\n德沃金在这一问题上提供了第三条思路：法官不应简单宣布某法律“无效”，而应通过整体性解释，从法律体系的原则资源中提炼出能够证成裁判的道德原则。这样，道德考量被纳入法律推理内部，而非作为外部否定。\n\n这两个案例共同说明，效力与正当性的区分并非书斋里的抽象思辨。在极端情境中，理论立场会直接影响裁判结果与公民对法律的态度。富勒试图通过内在道德为法律提供概念基底；哈特坚持概念清晰与道德清醒可以并存；拉兹以渊源命题维护法律确定性；德沃金以解释性整体观把道德原则纳入法律。这些方案各有得失，至今仍在角力。", "summary": "法律效力与道德正当性的区分，可通过四种模型定位：强自然法主张极端不正义规则丧失法资格；弱自然法承认其仍为法但丧失服从义务；排他实证主义主张法律识别只诉诸社会来源；包容实证主义允许承认规则把道德纳入效力条件。哈特以“最低限度的自然法”作为法律存在的必要条件的限定，富勒以八项程序性要求作为法律的概念性条件，二人围绕必然联系、内在道德性质与恶法称谓展开论战。Wacks 指出论战无定论，却确立了效力与正当性的坐标。拉德布鲁赫公式与告密者案表明，这一争论在司法实践中具有直接后果。德沃金的整体性解释则提供了超越二元对立的第三种思路。成熟的立场，既不应把两者关系简化为一句话，也不应回避在极端情境中作出判断的责任。", "furtherThinking": "1. 在告密者案中，哈特式“承认恶法为法再予谴责”与拉德布鲁赫式“否认恶法效力”，哪一种更能同时维护法治与正义？\n2. 德沃金的整体性解释是否真正超越了哈特与富勒的二元对立，还是只是把自然法立场换了一种说法？\n3. 哈特的“最低限度的自然法”如果足以排除极端邪恶的法律，他与富勒的分歧是否只是程度之分？"}, "en": "The Distinction Between Legal Validity and Moral Legitimacy", "level": "debate", "tags": "法律效力, 道德正当性, 分离命题, 哈特, 富勒, 拉德布鲁赫", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.10, ch.4 §4.5；Hart, The Concept of Law, ch.9, Postscript", "id": "S2M2K5"}, "S2M2K6": {"title": "法律实证主义的现代发展：拉兹", "EN": "The Modern Development of Legal Positivism: Joseph Raz", "LEVEL": "core", "TAGS": "法律实证主义, 拉兹, 渊源命题, 排他实证主义, 实践理性", "TERMS": "渊源命题（Sources Thesis）::法律的识别只依赖社会来源、无需道德论证的主张；排他实证主义（Exclusive Positivism）::坚持道德不能构成法律效力条件的实证主义版本；承诺性陈述（Committed Statements）::从法律体系内部接受其法律有效性的陈述；超脱性陈述（Detached Statements）::描述法律主张而不予接受的陈述；实践理性（Practical Reason）::关于行动理由与应当如何行动的理性能力", "SOURCE": "Wacks, Understanding Jurisprudence, ch.4 §4.4；Raz, Practical Reason and Norms；Hart, The Concept of Law, Postscript", "terms": [{"term": "渊源命题（Sources Thesis）", "def": "法律的识别只依赖社会来源、无需道德论证的主张"}, {"term": "排他实证主义（Exclusive Positivism）", "def": "坚持道德不能构成法律效力条件的实证主义版本"}, {"term": "承诺性陈述（Committed Statements）", "def": "从法律体系内部接受其法律有效性的陈述"}, {"term": "超脱性陈述（Detached Statements）", "def": "描述法律主张而不予接受的陈述"}, {"term": "实践理性（Practical Reason）", "def": "关于行动理由与应当如何行动的理性能力"}], "sections": {"coreQuestion": "拉兹（Joseph Raz）如何把法律实证主义推进到一个更纯粹、更精致的形态？他的渊源命题（Sources Thesis）究竟主张什么？承诺性陈述与超脱性陈述的区分为何重要？本节要说明：拉兹以“社会来源唯一论”坚持法律的识别无需道德论证，发展出排他实证主义（exclusive positivism），并以实践理性、法律权威与陈述分类等理论，回应实证主义面临的核心挑战。理解拉兹，是理解当代实证主义与自然法之争（尤其与菲尼斯之争）的关键。", "definition": "拉兹是当代最重要的法律实证主义者之一，其代表作包括《实践理性与规范》（Practical Reason and Norms）与《法律体系的概念》（The Concept of a Legal System）。Wacks 把拉兹与哈特、凯尔森、科尔曼（Jules Coleman）并列为现代实证主义的代表。\n\n渊源命题（Sources Thesis）是拉兹理论的基石。Wacks 引述其表述：识别法律的存在与内容，不需要也不求助于任何道德论证。换言之，一项规则是不是法律、其内容是什么，最终只能由社会事实（如立法机关的制定、法院的判决、社会实践）来确定。Wacks 指出，拉兹尤为突出地坚持只有社会来源才能供给合法性（legality）的标准。\n\n排他实证主义（Exclusive Positivism）是渊源命题的直接后果。拉兹主张，道德在任何情况下都不能构成法律有效性的条件；对此，哈特的包容实证主义（允许承认规则纳入道德标准）被拉兹视为对实证主义的背离。Wacks 指出，拉兹的立场与菲尼斯的自然法理论虽结论相反，却共享一个前提：法律理论必须说明法律何以能主张权威。\n\n承诺性陈述（committed statements）与超脱性陈述（detached statements）的区分，是拉兹对法理学方法论的重要贡献。前者是从某一法律体系内部作出的、接受其法律有效性的陈述（如法官说“根据本法，被告有罪”）；后者是对这种陈述的描述，而不必接受其内容（如法学家说“英国法官会认为根据本法被告有罪”）。这一区分使法学家能够在不认同某法律体系道德价值的前提下，准确描述其内容。", "history": "拉兹的理论发展于二十世纪后半叶，正值法律实证主义与自然法论战重新激化之时。哈特在《法律的概念》中提出包容实证主义的可能性，德沃金（Ronald Dworkin）则从道德原则角度批评实证主义。拉兹在这种情况下，站出来为更严格的实证主义版本辩护。\n\n拉兹深受哈特影响，却比哈特更坚决。他继承哈特对法律与道德分离的承诺，但拒绝哈特在包容实证主义中的松动。Wacks 指出，拉兹认为纯粹的法律理论必须严格遵守渊源命题，仅以社会事实识别法律。为此，他甚至借用了凯尔森的基础规范概念：法学家若要规范地描述法律体系，必须“虚幻地”（fictitiously）接受法律人的基础规范（the basic norm of the legal man）。\n\n拉兹也是法律权威理论的重要代表。他主张法律的本质性主张是它拥有正当权威，而实践理性可以说明这种权威如何可能。Wacks 提到，拉兹甚至提出过一个“异想天开”的解释：无政府主义者可能在特定场合成为法官，以便最能破坏法律体系—这一例子说明他对权威与实际服从关系的思考。", "principle": "拉兹的理论逻辑可拆为四个层次。\n\n第一层是渊源命题的论证。拉兹认为，法律之所以能成为公共的、可识别的行为指引，正是因为它能被社会事实所识别。若法律的识别需要道德论证，就会出现两个后果：其一，人们必须先知道答案才能识别法律，导致循环；其二，法律的确定性受损，因为道德论证本身充满争议。因此，只有社会来源能供给合法性标准。\n\n第二层是排他实证主义的立场。渊源命题要求：道德不进入法律识别。这与哈特的包容实证主义形成对比。Wacks 指出，拉兹认为若法律的识别依赖某一套道德信念，就违反了渊源命题，因为这使得法律识别依赖于特定的道德立场。\n\n第三层是法律权威与实践理性。拉兹主张，法律对受众主张正当权威（legitimate authority），这种主张可由实践理性加以说明：法律通过提供行动理由，帮助人们更好地遵循理性要求。Wacks 指出，拉兹与菲尼斯的自然法理论虽结论相反，却都致力于说明法律何以能主张权威——这是两者深层的共同问题意识。\n\n第四层是陈述分类与方法论。拉兹通过承诺性与超脱性陈述的区分，说明法学家如何既能描述法律，又不承诺接受其道德正当性。为了规范地描述一个法律体系，法学家可以不承诺地或虚幻地接受凯尔森式的基础规范——即“法律人”的视角。Wacks 指出，这是拉兹把凯尔森的理论工具纳入实证主义框架的独特做法。", "viewpoints": "拉兹的核心主张可概括为五点。\n\n其一，渊源命题：法律的识别只依赖社会来源，无需道德论证。Wacks 明确指出，拉兹坚持只有社会来源能供给合法性标准。\n\n其二，排他实证主义：道德在任何情况下都不能成为法律有效性的条件。这使拉兹区别于哈特的包容立场。\n\n其三，法律主张正当权威：法律的本质在于它对受众提出正当权威的主张，实践理性可以说明这种主张的可能基础。\n\n其四，承诺性与超脱性陈述的区分：法学家可以描述法律主张而不接受其有效性，从而保持价值中立的方法论立场。\n\n其五，法律理论的描述性：法理学应当描述法律，而非规定法律应当是什么。为了规范地描述法律体系，可以不承诺地接受“法律人的基础规范”。", "comparison": "拉兹与哈特的关系，是继承与激化。哈特提出分离命题与承认规则，但后期允许承认规则把道德标准纳入法律有效性条件（包容实证主义）。拉兹则坚持渊源命题的纯粹性，反对任何道德进入法律识别。Wacks 指出，拉兹对包容实证主义的批评，基于对法律确定性与描述性的关切。哈特在《法律的概念》第三版后记中回应了德沃金的批评，也间接涉及与拉兹的争论。\n\n拉兹与凯尔森的关系，是工具性的继承。凯尔森以基础规范为法律效力的逻辑前提，拉兹虽不认同其全部理论，却借用“法律人的基础规范”这一概念，说明法学家如何能规范地描述法律体系。Wacks 指出，拉兹认为为了描述法律，必须非承诺地或虚幻地接受凯尔森式的基础规范。\n\n拉兹与菲尼斯的关系，是当代实证主义与自然法之争的焦点。Wacks 指出，拉兹的渊源命题与菲尼斯的自然法理论虽结论相反，却共享一个前提：法律理论必须说明法律何以能主张权威。菲尼斯从基本善与实践合理性出发说明法律的权威；拉兹则从社会来源与实践理性出发。两人的分歧，集中体现了当代法理学的基本路线之争。\n\n拉兹与德沃金的关系，是对立。德沃金主张道德原则是法律的一部分，法官在疑难案件中须通过解释提炼原则；拉兹则坚持法律只由社会来源识别，道德论证不进入法律识别。这一分歧贯穿当代法理学。", "debates": "围绕拉兹的第一场争论，是排他实证主义与包容实证主义之争。拉兹认为，一旦允许道德通过承认规则进入法律，就会损害法律的确定性与描述性；哈特则认为，承认道德标准进入法律，只是承认某些法律体系的实际做法，并不违背实证主义的核心。Wacks 指出，这一争论是当代实证主义内部最重要的分歧。\n\n第二场争论关乎渊源命题能否成立。批评者（尤其德沃金与自然法论者）指出，在许多法律体系中，道德原则确实被当作法律来适用，若坚持渊源命题，就无法解释这一现象。拉兹的回应是：这类原则之所以有法律约束力，是因为它们已被社会来源（如宪法条文、司法先例）采纳，而非因为它们道德上正当。\n\n第三场争论关乎法律权威。拉兹主张法律必然主张正当权威，批评者则追问：如果法律事实上经常不道德，它凭什么主张权威？拉兹以实践理性说明权威的可能基础，但批评者认为这一说明过于理想化。Wacks 提到拉兹那个“无政府主义者成为法官以破坏法律”的异想天开的例子，正说明他对权威与实际服从关系的复杂思考。", "case": "一个检验渊源命题的现实例子，是宪法中的道德性条款。许多国家的宪法包含“人的尊严不可侵犯”“法律面前人人平等”等原则性条款。这类条款的措辞明显带有道德色彩。问题在于：法院适用这些条款时，是否在进行道德论证？\n\n从拉兹的视角看，答案是否定的：这些条款之所以是法律，是因为它们被写入宪法这一社会事实；法院适用它们，是在执行社会来源所确认的法律内容，而非诉诸独立的道德判断。从德沃金的视角看，答案则是肯定的：适用这类条款必然涉及道德解释，法律与道德在此无法分离。Wacks 指出，这一争论正是拉兹与德沃金分歧的具体体现。\n\n另一个例子是国际法中的“强行法”（ius cogens）概念。某些国际法规范（如禁止种族灭绝）被认为具有强制性，不得通过条约排除。这类规范的识别是否依赖道德判断？拉兹式回应会强调它们已被国际条约与习惯等社会来源确认；自然法论者则会主张其效力来自对人类尊严的普遍尊重。", "caseAnalysis": "就宪法道德条款而言，事实是：法院在适用“人的尊严”等条款时，需要对其含义作出判断；争议焦点在于，这种判断是否属于道德论证。从拉兹的视角看，法院是在解释已被社会来源采纳的法律内容，其判断仍属法律识别而非道德评价；尊严条款的法律效力来自宪法制定这一社会事实。从德沃金的视角看，对尊严的解释必然涉及道德判断，法律与道德在此交融。\n\n从裁判理由看，法院在解释尊严条款时，往往会诉诸社会共识、宪法传统与判例，而非纯粹个人道德。这为拉兹提供了某种支持：实际裁判中，所谓道德判断常被转化为对社会来源（先例、共识）的援引。但德沃金会反驳：对社会共识的选择本身已隐含道德判断。\n\n这一案例的理论意义在于，它把渊源命题从抽象论题转化为可检验的问题：当法律文本使用道德语汇时，法官是否在进行道德论证？拉兹与德沃金的分歧，直接影响我们对司法裁判性质的理解。Wacks 指出，拉兹与菲尼斯虽结论相反却共享对法律权威问题的关切，这一点也在此类案例中体现——无论从社会来源还是从实践理性出发，理论都必须说明法院凭什么作出有约束力的裁判。", "summary": "拉兹把法律实证主义推进为排他实证主义，以渊源命题坚持法律的识别只依赖社会来源、无需道德论证。他主张道德在任何情况下都不能构成法律效力条件，并通过承诺性与超脱性陈述的区分，说明法学家如何在不认同某法律体系道德价值的前提下描述其内容；为了规范地描述法律，他借用凯尔森式“法律人的基础规范”这一工具。拉兹与哈特在包容／排他实证主义上分歧，与德沃金在法律是否包含原则上对立，与菲尼斯虽结论相反却共享对法律权威问题的关切。宪法道德条款与国际强行法等案例，把渊源命题转化为可检验的问题。拉兹的贡献在于把实证主义推向逻辑更一贯、方法更自觉的形态，其面临的挑战则在于如何解释道德语汇在真实法律实践中的运作。", "furtherThinking": "1. 拉兹的渊源命题能否解释宪法中『人的尊严』这类道德性条款的司法适用？请比较德沃金的解释路径。\n2. 排他实证主义与包容实证主义的分歧，是实质分歧还是术语之争？请结合承认规则分析。\n3. 拉兹与菲尼斯都关心法律何以能主张权威，但答案相反。哪一种更能解释法律在道德多元社会中的运作？"}, "en": "The Modern Development of Legal Positivism: Joseph Raz", "level": "core", "tags": "法律实证主义, 拉兹, 渊源命题, 排他实证主义, 实践理性", "source": "Wacks, Understanding Jurisprudence, ch.4 §4.4；Raz, Practical Reason and Norms；Hart, The Concept of Law, Postscript", "id": "S2M2K6"}, "S2M2K7": {"title": "对法律实证主义的主要批评", "EN": "Main Criticisms of Legal Positivism", "LEVEL": "core", "TAGS": "法律实证主义, 批评, 德沃金, 自然法, 法律现实主义", "TERMS": "法律原则（Legal Principles）::与规则不同、具有道德维度且以分量方式起作用的法律标准；整体性（Integrity）::德沃金解释性法理学的核心德性，要求把法律实践理解为连贯的整体；规则怀疑论（Rule Skepticism）::怀疑规则能决定案件结果的法律现实主义立场；价值中立（Value Neutrality）::实证主义追求的描述性理想，即不承诺特定道德立场；法的安定性（Legal Certainty）::法律应提供明确稳定行为指引的价值", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2 §2.9, ch.5 §5.2, ch.6；Hart, The Concept of Law, Postscript", "terms": [{"term": "法律原则（Legal Principles）", "def": "与规则不同、具有道德维度且以分量方式起作用的法律标准"}, {"term": "整体性（Integrity）", "def": "德沃金解释性法理学的核心德性，要求把法律实践理解为连贯的整体"}, {"term": "规则怀疑论（Rule Skepticism）", "def": "怀疑规则能决定案件结果的法律现实主义立场"}, {"term": "价值中立（Value Neutrality）", "def": "实证主义追求的描述性理想，即不承诺特定道德立场"}, {"term": "法的安定性（Legal Certainty）", "def": "法律应提供明确稳定行为指引的价值"}], "sections": {"coreQuestion": "法律实证主义在二十世纪占据主导，但它遭到了来自哪些方向的批评？这些批评各自击中了什么要害？本节梳理四条主要批评路线：自然法论的批评（忽视法律道德本质）、德沃金的原则批评（法律不只是规则）、法律现实主义的批评（过度形式化、脱离法律实际运作）、以及批判法学对社会维度的忽视的批评。理解这些批评，是形成对实证主义平衡评价的前提——既看到它提供的概念工具，也看到它的解释边界。", "definition": "对法律实证主义的批评，可依其出发点分为四类。\n\n自然法批评的核心，是实证主义忽视了法律的道德本质。Wacks 转述自然法论者的主张：实证主义对价值中立法律描述（value-free account of law）的追求，遭到了自然法论者的反驳——它忽略了法律的本质，即法律的道德维度；制定法律的行为“能够而且应当受道德原则与规则指导”，这些道德规范是客观的事务。\n\n德沃金（Ronald Dworkin）的批评核心，是实证主义把法律理解为规则体系，忽视了法律原则。法律原则（Legal Principles）与法律规则不同：规则以“全有或全无”的方式适用，原则则以“分量”（weight）的方式起作用；原则具有道德维度，是法律实践不可或缺的一部分。德沃金在疑难案件中诉诸赫拉克勒斯（Hercules）式的理想法官，通过“整体性”（integrity）的解释，从法律实践中提炼出最能证成既往实践的原则。\n\n法律现实主义（Legal Realism）的批评核心，是实证主义过度关注规则与概念，脱离法律实际运作。现实主义者主张“法律就是法院说的那样”，强调法官的个人因素、社会后果与心理学因素。Wacks 指出，现实主义者拒绝逻辑的单一路径，寻求包括社会学与心理学在内的多种科学探究路径，Llewellyn 把现实主义理解为对超越性（transcendental）形而上学的攻击。\n\n批判法学（Critical Legal Studies）的批评，则针对实证主义对法律与权力关系的忽视。Wacks 指出，批判法律理论的中心主题，是怀疑发现统一法律秩序的可能性；法律被描绘为不确定、矛盾且与社会政治权力（尤其经济权力）深度交织。", "history": "对实证主义的批评，与实证主义本身同步发展。边沁与奥斯丁建立古典实证主义时，自然法论者立即予以反击，指责其把法律降格为暴力命令。二十世纪，实证主义经凯尔森与哈特而精致化，批评也随之升级。\n\n德沃金在二十世纪六七十年代发起对实证主义的全面挑战。Wacks 把德沃金的法理学列为其书第五章的核心内容，其中包括“Hercules and hard cases”（赫拉克勒斯与疑难案件）与“the rights thesis”（权利 thesis）等节。德沃金的批评尤其有力，因为它来自实证主义内部的问题意识：他承认法律是一种制度实践，但主张实证主义没能充分解释这种实践中的道德维度。\n\n法律现实主义的批评更早，源于美国 progressive 时代对形式主义（formalism）的反动。霍姆斯（Oliver Wendell Holmes Jr.）、卢埃林（Karl Llewellyn）、弗兰克（Jerome Frank）等人，把注意力从“书本上的法”转向“行动中的法”。Wacks 指出，现实主义者对模糊理论的不耐烦，是其经验主义气质的体现。\n\n批判法学在1970年代的美国兴起，Wacks 指出它表达了对法律与法律理论的广泛马克思主义批判，延续并激进了现实主义的传统。", "principle": "四条批评路线的论证逻辑可逐层展开。\n\n第一层：自然法批评的论证。其前提是“法律的概念包含道德”；其推论是：实证主义把道德排除出法律概念，就无法解释为何法律能主张道德权威，也无法充分批判恶法。Wacks 指出，自然法论者认为实证主义的价值中立追求，实际上忽略了法律的本质。这一批评的力量在于它指向法律的现象学体验：人们确实把法律当作有权威的、应当遵守的东西，而非纯粹事实。\n\n第二层：德沃金的论证。其前提是“法律不仅包含规则，还包含原则”；其证据是疑难案件中法官实际援引道德原则裁判；其推论是：实证主义的承认规则模型（以社会来源识别法律）无法解释原则的法律地位。德沃金以“整体性”（integrity）作为解释性德性，要求法官像链式小说（chain novel）的作者一样，在保持与既往实践连贯的前提下推进法律。Wacks 指出，德沃金把法律与道德的关系理解为一种解释性关系。\n\n第三层：现实主义的论证。其前提是“法律的功能是解决纠纷、服务社会”；其证据是法官实际作出判决的过程充满个人判断；其推论是：实证主义对规则体系的强调掩盖了法律运作的真实动力。霍姆斯的名言“法律的生命不在逻辑，而在经验”是这一批评的集中表达。\n\n第四层：批判法学的论证。其前提是“法律与社会权力结构深度交织”；其推论是：实证主义把法律描述为中立规则体系，掩盖了法律作为权力工具的功能。Wacks 指出，批判法律理论家把法律描绘为不确定的、政治的、与社会经济权力相连的。", "viewpoints": "自然法批评的核心代表是富勒与菲尼斯。富勒以“内在道德”论证法律与道德的必然联系；菲尼斯以“基本善”与实践合理性说明法律的正当性。Wacks 指出，自然法论者认为实证主义忽略了法律的本质——其道德性。\n\n德沃金的核心主张是：法律包含原则，原则具有道德维度；在疑难案件中，法官须通过整体性解释，从法律实践中提炼出最有道德说服力的原则；权利是法律的王牌（rights as trumps），个人权利优先于集体功利目标。Wacks 的书中专设“the rights thesis”（权利 thesis）一节讨论这一理论。哈特在《法律的概念》第三版后记中回应德沃金，承认法律中存在原则，但坚持原则仍须通过社会来源（如司法实践）识别。\n\n法律现实主义的核心主张是“法律就是法院说的那样”（霍姆斯／罗斯式的表述），强调经验、行为与社会后果。Wacks 指出，现实主义者（如 Handy 法官式的极端现实主义）把法律理解为法官实际做的事。现实主义批评实证主义的形式主义倾向，主张“行动中的法”才是研究对象。\n\n批判法学的核心主张是法律的不确定性（indeterminacy）与法律的政治性。Wacks 指出，CLS 认为法律远非连贯的规则与教义体系，而是不确定的、与社会政治经济权力相连的；社会正义是空洞的承诺。", "comparison": "自然法批评与德沃金批评的关系，既相似又不同。两者都主张法律包含道德维度，都批评实证主义的分离命题。差别在于：自然法论者通常在本体论层面主张法律与道德有必然联系；德沃金则通过解释学进路，主张道德原则是法律实践内部的一部分。Wacks 指出，德沃金把法律与道德的关系理解为解释性关系，这既不同于强自然法，也不同于实证主义的分离命题。\n\n德沃金批评与现实主义批评的关系，也有微妙之处。两者都批评实证主义的形式主义，都强调司法裁判中的判断因素。但德沃金强调判断受原则约束（整体性），现实主义者则倾向于认为判断更自由、更受社会与个人因素影响。可以说，德沃金为司法裁量设定了道德框架，现实主义者则更关注裁量的经验现实。\n\n现实主义批评与批判法学批评的关系，是继承与激进。Wacks 指出，批判法学在许多方面延续了美国法律现实主义的传统，二者都怀疑法律的中立性，都强调法律与政治的联系。差别在于：现实主义偏经验与心理学，批判法学偏政治哲学与马克思主义，且后者更强调法律对社会关系的构成性（constitutive）作用。", "debates": "德沃金与哈特的争论，是当代法理学最重要的争论之一。德沃金在《法律的概念》第三版后记（Postscript）中，系统批评哈特的规则模型：哈特把法律理解为初级规则与次级规则的结合，但忽视了原则；原则不是规则，不能以“全有或全无”方式适用，而以“分量”起作用；承认规则作为社会来源标准，无法充分解释原则的法律效力。\n\n哈特的回应是：承认规则可以容纳原则，只要是法律共同体在实践中把它们当作法律来接受；这仍属社会事实问题。Wacks 指出，哈特在后期著作中承认法律中包含道德原则，但坚持这并不动摇实证主义的核心—是否属于法律，最终仍取决于社会来源德沃金与哈特的这一争论，把“法律与道德的关系”从效力问题深化为法律推理的性质问题。\n\n现实主义对实证主义的批评，则集中在“形式主义”这一靶子上。Wacks 指出，现实主义者拒绝逻辑的单一路径，寻求社会学、心理学等多种科学探究路径。霍姆斯的名言“法律的生命不在逻辑，而在经验”成为这一批评的标志。然而，Wacks 也指出，现实主义常被视为实证主义的一支，因为它同样拒绝自然法的形而上学—这一“悖论”提示，现实主义的批评主要是方法论层面的，而非彻底否定实证主义。", "case": "一个检验德沃金原则批评的著名案例，是纽约上诉法院1889年的“里格斯诉帕尔默案”（Riggs v. Palmer, 115 N.Y. 506）。案情是：帕尔默因担心祖父修改遗嘱而将其毒杀，随后依据遗嘱主张继承遗产。遗嘱本身符合法定形式要件，按实证法规则应属有效。但法院最终判定帕尔默不得继承，理由是：任何人都不得从自己的错误行为中获利（no one shall profit from his own wrong）这一法律原则，优先于遗嘱继承的规则。\n\n从德沃金的视角看，这一案例证明法律包含原则：当规则与原则冲突时，法官诉诸原则裁判，而原则的效力来自其道德说服力与整体性要求，而非单纯的社会来源。从拉兹的视角看，这一原则之所以有法律效力，是因为它已被司法先例等社会来源采纳。Wacks 的书中虽未直接讨论里格斯案，但“Hercules and hard cases”（赫拉克勒斯与疑难案件）一节所处理的正是这类问题。\n\n另一个案例是富勒虚构的洞穴探险者案（The Case of the Speluncean Explorers, 1949）。Wacks 指出，其中 Handy 法官是极端的现实主义者，把法律理解为法官实际做的事；Foster 法官则采取目的论的进路。这一思想实验具体展示了现实主义批评的立场：所谓法律规则，在疑难案件中并不能自动给出答案。", "caseAnalysis": "就里格斯诉帕尔默案而言，事实是：遗嘱符合法定形式，杀人者依规则有权继承；争议焦点在于，是否应适用“不得从自身错误中获利”的原则排除其继承权。从德沃金的视角看，原则作为法律的一部分，其分量在此超过形式规则；法官通过整体性解释，从法律体系中提炼出这一原则并据此裁判。从实证主义视角看，需解释这一原则的法律地位：它是否已被先例采纳？若已采纳，其效力仍可归于社会来源。\n\n从裁判理由看，法院诉诸的是法律体系内部既有的道德原则，“创造新法”的指责在这里失焦。这为德沃金提供了支持：法律原则确实是法律实践的一部分。但拉兹式回应也会指出：这一原则之所以能被法院适用，是因为它在先前判例中已被确认，仍属社会来源。\n\n这一案例的理论意义在于，它把抽象争论具体化：当规则与道德原则冲突时，法官的裁判依据究竟是什么？德沃金据此论证法律包含原则，实证主义则须说明原则如何能被社会来源识别。Wacks 指出，这一争论没有简单答案，但它持续推动法理学深化对法律推理的理解。", "summary": "对法律实证主义的批评主要来自四个方向。自然法批评指责其忽视法律的道德本质，以富勒的内在道德与菲尼斯的基本善为代表。德沃金的批评最为系统：法律不仅包含规则，还包含具有道德维度、以分量起作用的原则；疑难案件中法官须通过整体性解释提炼原则；权利是优先于功利的王牌。法律现实主义的批评针对形式主义，强调“行动中的法”与法官的实际判断，霍姆斯“法律的生命不在逻辑而在经验”是其标志。批判法学则批评实证主义忽视法律与社会权力结构的关联，强调法律的不确定性与政治性。这些批评各有侧重：自然法与德沃金指向法律的道德维度，现实主义指向法律的经验运作，批判法学指向法律的社会权力维度。Wacks 指出，哈特在后期已承认法律中包含原则，但坚持社会来源仍是识别标准。这些批评共同划定了实证主义的解释边界，也推动了法理学的持续发展。", "furtherThinking": "1. 里格斯诉帕尔默案中，『不得从自身错误中获利』的原则是法律还是道德？拉兹与德沃金会如何各自主张？\n2. 法律现实主义常被视为实证主义的一支，它对实证主义的批评是否只是方法论层面的？\n3. 自然法批评与德沃金的原则批评都强调法律的道德维度，二者的根本差别在哪里？"}, "en": "Main Criticisms of Legal Positivism", "level": "core", "tags": "法律实证主义, 批评, 德沃金, 自然法, 法律现实主义", "source": "Wacks, Understanding Jurisprudence, ch.2 §2.9, ch.5 §5.2, ch.6；Hart, The Concept of Law, Postscript", "id": "S2M2K7"}, "S2M3K1": {"title": "美国法律现实主义", "EN": "American Legal Realism", "LEVEL": "core", "TAGS": "法律现实主义, 霍姆斯, 卢埃林, 弗兰克, 规则怀疑论", "TERMS": "美国法律现实主义（American Legal Realism）::二十世纪美国以经验与实践为取向、怀疑形式主义的法律理论运动；规则怀疑论（Rule Skepticism）::怀疑规则能自动决定案件结果的立场；事实怀疑论（Fact Skepticism）::怀疑审判中事实认定可靠性的立场；行动中的法（Law in Action）::法律在实际运作中的样子，与书本上的法相对；形式主义（Formalism）::相信法律决定可由规则逻辑地推出的司法理念", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6 §6.1—§6.2；Holmes, The Path of the Law", "terms": [{"term": "美国法律现实主义（American Legal Realism）", "def": "二十世纪美国以经验与实践为取向、怀疑形式主义的法律理论运动"}, {"term": "规则怀疑论（Rule Skepticism）", "def": "怀疑规则能自动决定案件结果的立场"}, {"term": "事实怀疑论（Fact Skepticism）", "def": "怀疑审判中事实认定可靠性的立场"}, {"term": "行动中的法（Law in Action）", "def": "法律在实际运作中的样子，与书本上的法相对"}, {"term": "形式主义（Formalism）", "def": "相信法律决定可由规则逻辑地推出的司法理念"}], "sections": {"coreQuestion": "美国法律现实主义（American Legal Realism）为什么被称为“现代法理学的一大悖论”？它怀疑规则能决定案件结果，却又常被归入实证主义阵营。本节要说明：现实主义是对十九世纪末形式主义（formalism）的反动，其代表人物霍姆斯（Oliver Wendell Holmes Jr.）、卢埃林（Karl Llewellyn）、弗兰克（Jerome Frank）把注意力从“书本上的法”转向“行动中的法”，强调经验、社会后果与法官的实际判断。理解现实主义，关键在于把握它对法律确定性的怀疑与对法律科学化的追求之间的张力。", "definition": "美国法律现实主义是二十世纪二三十年代在美国兴起的法律思想运动。Wacks 指出，现实主义者拒斥逻辑的单一路径，转而求助于包括社会学、心理学在内的多种科学探究路径；用卢埃林的话来说，现实主义意味着对超越性（transcendental）形而上学的攻击。\n\n现实主义内部有不同侧重。规则怀疑论（Rule Skepticism）怀疑规则能自动决定案件结果，认为在规则适用中存在空隙与不确定性。事实怀疑论（Fact Skepticism）则更进一步，怀疑审判中对事实的认定是否可靠——这一侧重尤其与弗兰克相关。Wacks 指出，弗兰克若被理解为极端的特殊主义者（particularist），其立场就与早期罗斯（Ross）相邻。\n\n现实主义的核心口号是把法律理解为“行动中的法”（law in action），而非“书本上的法”（law in books）。霍姆斯的名言“法律的生命不在逻辑，而在经验”（The life of the law has not been logic: it has been experience）是这一取向最凝练的表达。Wacks 还提到一句广为流传的表述：“法律就是法院说的那样！”（The law is what the courts say it is!）——它虽常被归于现实主义整体，实则罗斯也有类似表述。", "history": "现实主义兴起于美国 progressive 时代（约1890—1920）对形式主义司法理念的反动。当时美国法院（尤其最高法院）常以“自由放任”的经济理念，借自然法式的“正当程序”论证推翻社会立法。形式主义（Formalism）相信法律决定可由规则逻辑地推出，法官只是“自动售货机”。现实主义者认为这种说法掩盖了法官实际的价值判断。\n\n霍姆斯在1897年发表《法律之路》（The Path of the Law），以实用主义与经验主义哲学为现实主义奠基。Wacks 指出，霍姆斯那句名言出现在该文一段引人注目的文字末尾，成为现实主义最常被引用的表述。霍姆斯还以“漂浮在天空中的幽灵”（brooding omnipresence）讽刺自然法式的法律观——Wacks 提到，某种观点“类似于霍姆斯令人难忘地称为『brooding omnipresence』的东西”。\n\n卢埃林与弗兰克在1930年代把现实主义推向高峰。卢埃林的《荆棘丛》（The Bramble Bush, 1930）与弗兰克的《法律与现代精神》（Law and the Modern Mind, 1930）成为运动经典。Wacks 把霍姆斯、卢埃林、弗兰克列为必须了解的三位代表人物。", "principle": "现实主义的理论逻辑可拆为四个层次。\n\n第一层是对形式主义的批判。形式主义主张：法律规则体系是完备的，法官通过逻辑涵摄即可从规则推出唯一正确答案。现实主义者反驳：规则语言本身存在开放与模糊；规则之间可能冲突；更重要的是，法官在裁判中受个人经验、政策判断与社会后果考量影响。霍姆斯的名言正是对“逻辑决定论”的否定。\n\n第二层是规则怀疑论。规则怀疑论者认为，既然规则不能唯一决定结果，那么声称“法律决定案件”就是神话。卢埃林的名言大意是：法律就是官员处理纠纷所做的事（what officials do about disputes）。Wacks 指出，现实主义者拒绝单一的逻辑路径，强调社会学与心理学等经验科学。\n\n第三层是事实怀疑论。弗兰克把怀疑推进到事实认定层面：初审法院对“发生了什么”的认定，本身就充满不确定性——证人记忆不可靠、证据可能被伪造、法官与陪审团受心理因素影响。因此，所谓“法律适用”建立在不稳固的事实基础之上。Wacks 指出，弗兰克若被理解为极端特殊主义者，就与早期罗斯相邻。\n\n第四层是现实主义的方法论。Wacks 指出，现实主义者“more empirically minded”—更注重经验；他们寻求用科学方法研究法律的实际运作。这一取向使现实主义与法律社会学、行为主义法学、法律经济学等后续运动相连。同时，Wacks 也提到现实主义的“保守主义”批评——现实主义者在揭露法律不确定性的同时，可能低估法律规则对权力的制约功能。", "viewpoints": "霍姆斯的核心主张是经验主义的法律观。他在《法律之路》中宣称“法律的生命不在逻辑，而在经验”，强调法律的发展来自社会需要与实际经验，而非抽象逻辑。他把普通法比作“一种神秘的、漂浮的权威”，并反对把法律当作自然法的命令。Wacks 把霍姆斯列为美国现实主义的领袖人物。\n\n卢埃林的核心主张是规则怀疑与功能主义。他主张法律就是官员实际处理纠纷的行为，强调研究“行动中的法”。卢埃林也发展出“法律工作”（law-jobs）与制度分析的路径，关注法律在社会中承担的功能。Wacks 指出，现实主义在他那里意味着对超越性形而上学的拒斥。\n\n弗兰克的核心主张是事实怀疑论。他在《法律与现代精神》中主张，法院的判决很大程度上取决于法官对事实的认定，而事实认定充满不确定性；所谓规则的确定性是一种“基本的法律神话”。Wacks 指出，弗兰克若被理解为极端特殊主义者，其立场便与早期罗斯相邻。", "comparison": "美国现实主义与斯堪的纳维亚现实主义共享“现实主义”之名，却有显著差别。Wacks 指出，两者虽大体上都是现实主义者，但这种相似往往只是表面的：美国人处于英国经验主义哲学传统之中，斯堪的纳维亚人则更具哲学与形而上学批判色彩；美国人的研究范围更集中于司法过程，斯堪的纳维亚人的法理学范围更广，涵盖整个法律体系；美国人更注重经验，斯堪的纳维亚人更关注哲学本体论。Wacks 甚至提到，有人认为两者的相似纯属偶然。\n\n现实主义与法律实证主义的关系是“悖论性”的。Wacks 称美国法律现实主义为现代法理学的一大悖论：它一方面拒绝自然法的形而上学，与实证主义同属经验主义阵营；另一方面又怀疑规则能决定案件，与实证主义对规则体系的强调不同。可以说，现实主义在方法论上是经验主义的（近于实证主义），在司法理论上则是怀疑论的（异于实证主义）。\n\n现实主义与自然法传统直接对立。自然法相信理性可以发现客观正义标准，现实主义则倾向于把这些标准还原为法官的判断与社会后果。霍姆斯对“brooding omnipresence”的讽刺，正是针对自然法式的法律观。\n\n现实主义与批判法学（CLS）之间是继承关系。Wacks 指出，批判法学在许多方面类似于美国法律现实主义这一更早的运动，二者都怀疑法律的中立性与确定性。差别在于：现实主义偏经验与心理学，CLS 更强调法律的政治性与对权力关系的构成作用。", "debates": "围绕现实主义的第一场争论，是“规则怀疑论是否成立”。批评者（如哈特）指出：如果规则完全不能决定案件，法律就失去指引功能，法官的任意将不受约束。哈特在《法律的概念》中以“开放结构”回应：语言在边缘地带不确定，但大多数案件有明确答案，法官裁量仍在框架内。Wacks 指出，现实主义与哈特的这场交锋，是二十世纪法理学的重要线索。\n\n第二场争论是“现实主义是否保守”。批评者认为，现实主义揭露法律不确定性，却未分析法律服务于何种社会利益，其经验主义可能沦为对现状的描述与默认。Wacks 提到对现实主义者保守主义的批评，并指出这一批评在 CLS 与女性主义、后现代理论中被重新提起。\n\n第三场争论关乎现实主义与实证主义的关系。一些人把现实主义视为实证主义的一支（因其经验主义与反形而上学），另一些人则强调其对规则决定力的怀疑构成对实证主义的挑战。Wacks 以“一大悖论”概括这一复杂关系。", "case": "一个体现现实主义思维的案例，是美国最高法院1930年代的“新政”判例转型。在早期，最高法院曾以“正当程序”（due process）为由推翻若干社会立法（如 Lochner v. New York, 1905，虽早于新政，但体现形式主义取向）。随着现实主义的兴起与法官构成的变化，法院逐渐转向承认立法机关在经济社会规制上的广泛裁量权，如 NLRB v. Jones & Laughlin Steel Corp.（1937）等判决。从现实主义视角看，这一转变与社会经济危机、政治压力和法官对后果的判断密切相关，纯粹逻辑推演的产物之说过于单薄。\n\n另一个经典文本是富勒虚构的洞穴探险者案（The Case of the Speluncean Explorers, 1949）。Wacks 指出，其中 Handy 法官是“极端的现实主义者”（arch-realist），把法律理解为法官实际做的事，强调民意与后果；Foster 法官则采取目的论的解释进路。这一思想实验把现实主义对司法裁判的理解具体化：同一事实，在不同司法理念下可得出不同结论。", "caseAnalysis": "就新政判例转型而言，事实是：最高法院从推翻社会经济立法转向认可广泛规制权；争议焦点在于，这一转变是法律逻辑的必然展开，还是社会现实与法官判断作用的结果。从形式主义视角看，判决应依据宪法原则的逻辑推演；从现实主义视角看，社会危机、政治环境与法官对后果的判断深刻影响了裁判。\n\n从裁判理由看，法院在判决中确实诉诸宪法文本与先例，但这些材料在危机语境下被赋予不同权重——这正体现了现实主义的核心洞见：规则与理由并非自动决定结果，解释者的判断介入其中。\n\n这一案例的理论意义在于，它把“规则能否决定案件”的抽象争论，转化为可观察的司法史。现实主义提醒我们：法律适用从来不是纯粹的逻辑操作，社会后果与法官判断始终是裁判的组成部分。但哈特的回应也值得记取：承认判断的存在，不等于否认规则框架的约束作用。Wacks 对现实主义“悖论”的定位，提示我们既要看到它对形式主义的纠偏价值，也要警惕它可能对法律确定性造成的侵蚀。", "summary": "美国法律现实主义以霍姆斯、卢埃林、弗兰克为代表，是对形式主义司法理念的反动。它以“法律的生命不在逻辑，而在经验”为标志，把注意力从“书本上的法”转向“行动中的法”，强调社会学、心理学等经验方法。内部有规则怀疑论（卢埃林）与事实怀疑论（弗兰克）两种侧重，前者怀疑规则决定案件，后者怀疑事实认定的可靠性。Wacks 称其为“现代法理学的一大悖论”：它既因反形而上学而近于实证主义，又因怀疑规则决定力而挑战实证主义。它与斯堪的纳维亚现实主义在哲学气质、研究范围与方法上差别明显；与 CLS 之间是继承与激进的关系。现实主义的贡献在于揭开了司法裁判中经验与判断的面纱，其争议则在于是否过度削弱了法律的确定性与约束功能。", "furtherThinking": "1. 规则怀疑论若走向极端，会不会消解法律作为公共行为指引的功能？哈特的回应是否足够？\n2. 弗兰克的事实怀疑论对司法制度改革有何启示？事实认定的不确定性能否被制度性地降低？\n3. 美国现实主义与斯堪的纳维亚现实主义虽同名，哲学基础差异巨大。这种差异对各自的批判力度有何影响？"}, "en": "American Legal Realism", "level": "core", "tags": "法律现实主义, 霍姆斯, 卢埃林, 弗兰克, 规则怀疑论", "source": "Wacks, Understanding Jurisprudence, ch.6 §6.1—§6.2；Holmes, The Path of the Law", "id": "S2M3K1"}, "S2M3K2": {"title": "斯堪的纳维亚法律现实主义", "EN": "Scandinavian Legal Realism", "LEVEL": "core", "TAGS": "法律现实主义, 罗斯, 奥利弗克罗纳, 朗兹特, 形而上学怀疑论", "TERMS": "斯堪的纳维亚法律现实主义（Scandinavian Legal Realism）::以形而上学批判为核心、拒斥自然法与规范形而上学的北欧法律理论；形而上学怀疑论（Metaphysics-scepticism）::拒斥不可经验验证的法律实体与抽象规范概念的立场；独立命令（Independent Imperatives）::奥利弗克罗纳用以描述法律规则的命令性命题；社会福利（Social Welfare）::朗兹特用以说明法律目的的核心概念； 象棋类比（Chess Analogy）::罗斯用以说明规则与社会实践关系的著名比喻", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6 §6.3；Ross, On Law and Justice；Olivecrona, Law as Fact", "terms": [{"term": "斯堪的纳维亚法律现实主义（Scandinavian Legal Realism）", "def": "以形而上学批判为核心、拒斥自然法与规范形而上学的北欧法律理论"}, {"term": "形而上学怀疑论（Metaphysics-scepticism）", "def": "拒斥不可经验验证的法律实体与抽象规范概念的立场"}, {"term": "独立命令（Independent Imperatives）", "def": "奥利弗克罗纳用以描述法律规则的命令性命题"}, {"term": "社会福利（Social Welfare）", "def": "朗兹特用以说明法律目的的核心概念"}, {"term": "象棋类比（Chess Analogy）", "def": "罗斯用以说明规则与社会实践关系的著名比喻"}], "sections": {"coreQuestion": "斯堪的纳维亚法律现实主义与美国法律现实主义为何同名却差异巨大？阿尔夫·罗斯（Alf Ross）、卡尔·奥利弗克罗纳（Karl Olivecrona）、维赫尔姆·朗兹特（A. V. Lundstedt）各自的核心主张是什么？本节要说明：北欧现实主义的独特性在于其形而上学怀疑论——它把批判矛头指向自然法、规范效力与法律权利等“看不见的实体”，试图以经验与心理学为基础重建法律概念。理解这一路径，是把握现实主义内部多样性的关键。", "definition": "斯堪的纳维亚法律现实主义（Scandinavian Legal Realism）是二十世纪上半叶在北欧兴起的法律理论运动，代表人物为罗斯（1899—1979）、奥利弗克罗纳（1897—1980）与朗兹特（1882—1955）。Wacks 指出，这三人是这一立场的代表，其中罗斯与奥利弗克罗纳的著作影响最大，朗兹特的观点则较为极端且常引人发笑。\n\n与美国现实主义相比，北欧现实主义具有三个特征。第一，它更是形而上学怀疑论者（metaphysics-sceptics）：拒斥自然法、抽象规范与法律权利等不可经验验证的实体。第二，它的研究范围更广，涵盖整个法律体系，而不限于司法过程。第三，它更具哲学色彩，而非纯粹经验取向。Wacks 指出，美国人处于英国经验主义哲学传统中，斯堪的纳维亚人则更偏哲学批判；美国人更注重经验，斯堪的纳维亚人的法理学范围则更宽。\n\nWacks 转述罗斯的名言式表述：“法律就是法院说的那样！”（The law is what the courts say it is!）——这与美国现实主义的口号相通，但罗斯的论证方式更具哲学分析性。", "history": "斯堪的纳维亚法律现实主义兴起于二十世纪上半叶的北欧，与当时逻辑实证主义与经验主义哲学的流行密切相关。北欧法学传统本就较少受自然法形而上学影响，注重法律的社会功能与制度实践，这为现实主义的接受提供了土壤。\n\n罗斯的代表作《法律与正义》（On Law and Justice, 1958，由 Margaret Dutton 翻译）系统阐述其法律观。奥利弗克罗纳的《作为事实的法律》（Law as Fact, 1939；第二版 1971）则对法律形而上学发起更激进的攻击。朗兹特以其激进的社会福利论著称，Wacks 指出他的某些观点甚至成为笑柄——其“社会福利”概念被认为过于模糊，以致有评论称其理论中除了“作者对原创性的主张”外别无新意。\n\nWacks 指出，斯堪的纳维亚现实主义者与法律实证主义者之间的亲和性，在北欧现实主义那里达到顶点（apogee）。这提示他们的立场虽被称为“现实主义”，却与实证主义共享对形而上学的拒斥。", "principle": "北欧现实主义的理论逻辑可拆为四个环节。\n\n第一环是对自然法与规范形而上学的批判。奥利弗克罗纳在《作为事实的法律》中发动“对形而上学更激进的攻击”。他追问：法律权利的来源是什么？若回答“法律体系”或“基础规范”，他会认为这是无意义的、形而上学的回答。对奥利弗克罗纳而言，法律规则是“独立命令”（independent imperatives）：以命令形式呈现的命题，其约束力来自心理与社会事实，而非某种抽象规范。\n\n第二环是“法律语言具有魔幻色彩”的批判。Wacks 指出，奥利弗克罗纳认为法律规则仿佛通过某种“魔咒”（magical incantation）就能给出问题的答案，法律概念被赋予了“魔幻意义”（magical significance）。他拒绝把法律概念当作超越经验的东西，主张以心理学事实说明其运作。Wacks 还指出，奥利弗克罗纳颠倒了通常“法律反映道德价值”的观点，主张法律影响道德，而非相反。\n\n第三环是罗斯的象棋类比。罗斯要我们想象一局象棋，有第三方在旁观。他追问：我们如何确定支配棋局的规则？仅仅观察棋子的移动（事实）是不够的；规则存在于参与者对待棋局的态度之中。社会生活的情形与此类似：许多个体行为受规则指导，而规则作为社会事实存在。罗斯用这一类比说明，法律规范存在于社会实践中、被参与者当作有约束力的东西来对待；纯粹的物理事实与超验实体都不是它的位置。\n\n第四环是朗兹特的社会福利论。朗兹特把法律视为“几乎只是社会存在的事实”，并以“社会福利”作为法律的目的与评价标准。Wacks 指出，对朗兹特最明显的批评是其“社会福利”概念并不明确——若缺乏可操作的判准，这一概念就难以发挥批判功能。", "viewpoints": "罗斯的核心主张是：法律是社会事实，其效力来自社会接受。他拒绝超验的规范概念，主张以经验方式研究法律。罗斯在《法律与正义》中拒绝了奥利弗克罗纳的“心理现实主义”，显示两人虽有共同的反形而上学立场，具体路径却不同。他的象棋类比，是说明规则与社会实践关系的经典比喻。\n\n奥利弗克罗纳的核心主张是：法律规则是“独立命令”，其约束力可由心理与社会事实说明。他激进地批判法律形而上学，认为追问法律效力的“来源”只会得到无意义的回答。他强调心理条件作用（conditioning）在法律运作中的作用，并颠倒法律与道德的关系，主张法律影响道德。Wacks 指出，对奥利弗克罗纳的批评包括其心理学预设、对强制（coercion）的说明过于简单等。\n\n朗兹特的核心主张是：法律是社会存在的事实，应以“社会福利”为目的。Wacks 指出，他的观点虽激进却常被批评为模糊，甚至成为笑柄——其著作的原创性受到质疑。", "comparison": "北欧现实主义与美国现实主义的差别，是内部比较的重点。Wacks 概括为三点：其一，美国人处于英国经验主义传统，斯堪的纳维亚人更具哲学批判色彩；其二，美国人的研究较集中于司法过程，斯堪的纳维亚人的法理学范围更广，涵盖整个法律体系；其三，美国人更注重经验，斯堪的纳维亚人更偏哲学思辨。Wacks 甚至提到，有人认为二者相似纯属偶然。\n\n罗斯与奥利弗克罗纳虽有共同的反形而上学立场，却有重要差别。罗斯在《法律与正义》中明确拒绝奥利弗克罗纳的“心理现实主义”，表明他不认同把法律完全还原为心理状态。奥利弗克罗纳更激进地主张法律语言具有“魔幻意义”，罗斯则更强调规则作为社会事实的制度性。\n\n北欧现实主义与法律实证主义的关系是亲和而非对立。Wacks 指出，两者之间的亲和性在斯堪的纳维亚现实主义那里达到顶点。这与美国现实主义和实证主义的“悖论性”关系形成对照。原因可能在于：北欧现实主义虽然反形而上学，却不像美国现实主义那样全面怀疑规则的决定作用。\n\n北欧现实主义与自然法传统直接对立。它对自然法的批判比美国现实主义更彻底——从本体论层面否认“自然正义”这类超验实体的存在，简单还原为法官偏好的做法在此之外。", "debates": "围绕北欧现实主义的第一场争论，是“法律效力概念是否可保留”。奥利弗克罗纳主张追问法律效力的来源是无意义的形而上学；罗斯则试图以社会事实重新解释效力，保留这一概念的某种功能。Wacks 指出，罗斯与奥利弗克罗纳在“心理现实主义”上的分歧，正体现这一争论。\n\n第二场争论关乎心理学方法在法律理论中的地位。奥利弗克罗纳强调心理条件作用，但批评者认为其心理学预设过于简化。Wacks 指出，对奥利弗克罗纳的批评包括其心理学说明与对强制的说明。罗斯虽反对形而上学，却也不完全接受奥利弗克罗纳的心理学路径。\n\n第三场争论关乎“社会福利”能否作为法律标准。朗兹特以社会福利为核心，但批评者指出这一概念过于模糊。Wacks 转述的批评—除了作者对原创性的主张外别无新意—虽尖刻，却点出以模糊价值概念支撑法律理论的困难。", "case": "一个可用于检验罗斯象棋类比的现实例子，是国际象棋或足球等竞技运动的规则运作。以足球为例：球员在场上的行为可被物理地描述（某人踢球、球入门），但“越位”“犯规”等规则不能仅从物理事实中读出—它们存在于球员、裁判与观众共同接受并使用的实践之中。第三方可以观察这些行为并推断规则，但规则的“约束力”来自参与者对它的态度。罗斯的象棋类比正是要说明法律规范的类似地位：法律既是社会事实，又具有规范性，其约束力来自参与者从内部把它当作规则来对待。\n\n另一个例子是当代企业对“合规”（compliance）的实践。企业设立合规部门，是因为法律规则被组织内部接受为行为标准；每条规则都有警察在旁监督的设想并不现实。从罗斯的视角看，这正说明法律规范的约束力来自社会实践中的接受，而非超验的效力根据。", "caseAnalysis": "就竞技规则而言，事实是：规则不能从物理事实中直接读出，却实际约束着参与者；争议焦点在于，这种约束力的性质是什么。从罗斯的视角看，规则存在于参与者的共同实践之中，既非纯物理事实，也非超验实体。从奥利弗克罗纳的视角看，规则的约束力可由心理与社会条件作用说明。从自然法视角看，则会诉诸某种正当性标准。\n\n从理论意义看，这一类比把抽象的本体论争论具体化：法律规范的“存在”方式，类似于游戏规则的存在方式。这一洞见对理解法律的规范性有重要价值——它提示我们，规范性既不需要超验基础，也不能被还原为物理事实。\n\n但类比也有局限：法律规则与国家强制、制度权威相连，比游戏规则更复杂。朗兹特的“社会福利”概念所面临的批评，正提示了以模糊价值概念支撑法律标准的风险。Wacks 把斯堪的纳维亚现实主义定位为“形而上学怀疑论”的极端形态，这一评价恰当地概括了其贡献与边界。", "summary": "斯堪的纳维亚法律现实主义以罗斯、奥利弗克罗纳、朗兹特为代表，其核心是形而上学怀疑论：拒斥自然法与规范形而上学，以经验与心理学重建法律概念。奥利弗克罗纳在《作为事实的法律》中提出“独立命令”概念，批判法律语言的“魔幻意义”，并颠倒法律与道德的通常关系。罗斯在《法律与正义》中以象棋类比说明规则作为社会事实的存在方式，并拒绝奥利弗克罗纳的心理现实主义。朗兹特以“社会福利”为核心，但其概念模糊性受到批评。与美国现实主义相比，北欧现实主义更具哲学色彩、研究范围更广、与实证主义更亲和。其贡献在于以彻底的经验主义澄清法律概念的本体论地位，其局限则在于心理学预设的简化与价值标准的模糊。", "furtherThinking": "1. 罗斯的象棋类比能否说明法律规范的约束力？它与哈特的『内部观点』有何异同？\n2. 奥利弗克罗纳主张法律影响道德而非相反，这一『颠倒』在当代法理学中是否仍有意义？\n3. 朗兹特的『社会福利』概念因模糊而受批评，这是否说明法律理论无法回避价值标准的明确化？"}, "en": "Scandinavian Legal Realism", "level": "core", "tags": "法律现实主义, 罗斯, 奥利弗克罗纳, 朗兹特, 形而上学怀疑论", "source": "Wacks, Understanding Jurisprudence, ch.6 §6.3；Ross, On Law and Justice；Olivecrona, Law as Fact", "id": "S2M3K2"}, "S2M3K3": {"title": "法官如何影响法律适用", "EN": "How Judges Influence the Application of Law", "LEVEL": "core", "TAGS": "法官, 司法裁量, 规则怀疑论, 开放结构, 赫拉克勒斯", "TERMS": "司法裁量（Judicial Discretion）::法官在规则不确定的地带作出选择的余地；开放结构（Open Texture）::语言在边缘案例中存在不确定性的特征；事实怀疑论（Fact Skepticism）::弗兰克主张的、对事实认定可靠性的怀疑；稳定性因素（Steadying Factors）::约束法官判断、使裁判可预期的制度与职业因素；整体性（Integrity）::德沃金要求法官把法律实践理解为连贯整体的解释德性", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6；Hart, The Concept of Law, ch.7；Dworkin, Taking Rights Seriously", "terms": [{"term": "司法裁量（Judicial Discretion）", "def": "法官在规则不确定的地带作出选择的余地"}, {"term": "开放结构（Open Texture）", "def": "语言在边缘案例中存在不确定性的特征"}, {"term": "事实怀疑论（Fact Skepticism）", "def": "弗兰克主张的、对事实认定可靠性的怀疑"}, {"term": "稳定性因素（Steadying Factors）", "def": "约束法官判断、使裁判可预期的制度与职业因素"}, {"term": "整体性（Integrity）", "def": "德沃金要求法官把法律实践理解为连贯整体的解释德性"}], "sections": {"coreQuestion": "如果法律规则不能自动决定案件结果，那么法官的个人判断在多大程度上影响法律适用？这种影响是法律的缺陷，还是法律运作的常态？本节要说明：现实主义揭示了法官在裁判中的判断空间，但这一空间并非无限——制度约束、职业传统与法律原则共同构成了法官判断的边界。哈特的“开放结构”、德沃金的“整体性”与现实主义的“规则怀疑论”，对这一问题给出了不同回答。理解这些回答，是理解司法裁判性质的关键。", "definition": "法官影响法律适用的问题，源于规则的确定性不足。法律规则以语言表述，而语言存在“开放结构”（Open Texture）：在中心地带，规则含义清晰；在边缘地带，规则是否涵盖当前情形可能产生争议。哈特承认这一点，但认为大多数案件有明确答案。\n\n司法裁量（Judicial Discretion）指法官在规则不确定的地带作出选择的余地。现实主义倾向于扩大这一余地：霍姆斯说“法律的生命不在逻辑，而在经验”；罗斯说“法律就是法院说的那样”；卢埃林说法律就是官员处理纠纷所做的事。Wacks 指出，法官在裁判中受个人经验、政策判断与社会后果考量影响。\n\n事实怀疑论（Fact Skepticism）则由弗兰克代表：不仅规则不确定，“发生了什么”这一事实认定本身也不确定。证人记忆、证据可靠性与法官心理都会影响事实认定，而这些认定往往决定案件结果。\n\n与怀疑论相对的是对司法约束的强调。德沃金以“整体性”（Integrity）要求法官像链式小说的作者一样，在保持与既往实践连贯的前提下推进法律；原则作为法律的一部分，对法官构成约束。哈特也强调，裁量只在边缘地带存在，且仍在法律框架内运作。", "history": "对法官角色的关注，与对法律确定性的追问同步。十九世纪形式主义相信法官只是“宣布法律”的嘴巴，判决可由规则逻辑地推出。这种“自动售货机”式的司法观，在美国 progressive 时代受到现实主义的猛烈抨击。霍姆斯在《法律之路》（1897）中，以经验主义颠覆了逻辑决定论。\n\n二十世纪中叶，哈特以“开放结构”回应现实主义的挑战：既承认规则有不确定地带，又维护法律的确定性。德沃金则更进一步，主张即使在疑难案件中，法官也受法律原则约束，存在唯一“正确答案”。Wacks 指出，德沃金把这种判断称为“怀疑的解释性判断”（sceptical interpretive judgment），它要求法官在法律实践中寻找最能证成既往实践的原则。\n\n与此同时，法律社会学与行为主义法学以经验方法研究法官行为，关注法官的背景、态度与判决之间的关系。这一路径把“法官如何影响法律适用”从规范问题转化为经验问题。", "principle": "法官影响法律适用的机制，可从四个层次分析。\n\n第一层是规则适用的不确定性。语言的开放结构使规则在边缘地带含义不清；规则之间可能冲突；法律可能存在空隙。这些情况为法官判断留下空间。哈特承认这一层，但强调其有限性。\n\n第二层是事实认定的不确定性。弗兰克指出，初审法院对“发生了什么”的认定本身充满变数。即使规则明确，若事实认定不同，判决也会不同。这一层常被忽视，却对案件结果有决定性影响。Wacks 指出，弗兰克作为极端特殊主义者，其立场与早期罗斯相邻。\n\n第三层是法官的个人因素。法官的背景、价值观、政策偏好与对社会后果的判断，都会影响裁判。现实主义把这些因素视为法律运作的真实组成部分，而非应被消除的偏差。霍姆斯的经验主义、卢埃林对“官员实际行为”的关注，都是这一层的体现。\n\n第四层是制度约束。Wacks 指出，现实主义者虽强调法官的实际行为，但制度性因素——如遵循先例、上级审查、法律教育与职业文化——对法官判断构成约束。卢埃林后期也强调使裁判可预期的“稳定性因素”。德沃金的原则理论与哈特的开放结构理论，都可以理解为对这一层的规范化说明：法官的判断是受约束的判断，而非任意的选择。", "viewpoints": "现实主义的核心观点是：法官的判断深度参与法律适用。霍姆斯以经验对抗逻辑，罗斯宣称法律就是法院说的那样，卢埃林把法律理解为官员处理纠纷的行为，弗兰克则揭示事实认定的不确定性。Wacks 指出，现实主义者拒绝单一的逻辑路径，寻求包括社会学与心理学在内的多种科学方法。\n\n哈特的核心观点是中间道路：语言有开放结构，法官在边缘地带有裁量权，但裁量仍在法律框架内；大多数案件有明确答案。这既反对机械形式主义，也反对规则怀疑论。\n\n德沃金的核心观点是：法官即使在疑难案件中也受原则约束。他批评“裁量”概念遮蔽了法官的道德责任，主张法官须通过整体性解释，从法律实践中提炼出最能证成既往实践的原则，权利是优先于功利的“王牌”。\n\n富勒的洞穴探险者案（1949）以五位法官的不同意见，具体展示了不同司法理念如何导致不同判决。Wacks 指出，Handy 法官是极端的现实主义者，Foster 法官则采取目的论的解释进路。这一文本是理解法官角色的经典教材。", "comparison": "现实主义与哈特的分歧，集中在判断空间的大小。现实主义倾向于认为规则对裁判的决定力有限，法官判断无处不在；哈特则坚持规则在大多数案件中决定结果，判断只在边缘地带介入。这一分歧的实质，是对法律确定性价值的不同权重。\n\n哈特与德沃金的分歧，集中在疑难案件中是否存在“正确答案”。哈特承认裁量空间，德沃金则主张原则可提供正确答案。Wacks 指出，德沃金把法律与道德的关系理解为解释性关系，法官须通过整体性判断寻找最本分（fit）且最有道德说服力的解释。\n\n现实主义与德沃金看似对立，却有相通处：两者都否认规则能机械决定案件。差别在于，现实主义倾向于把判断理解为经验与政策的过程，德沃金则把判断理解为受原则约束的道德解释过程。可以说，德沃金为司法判断设定了规范性框架，现实主义则更关注判断的经验现实。\n\n在法官角色问题上，斯堪的纳维亚现实主义与美国现实主义亦有差别。前者更关注法律概念的本体论地位，后者更关注司法过程的实际运作。Wacks 指出，美国人对司法过程更专注，斯堪的纳维亚人的法理学范围更广。", "debates": "第一场争论是“司法裁量是否应被承认”。形式主义者否认裁量，认为法官只是适用法律；现实主义者承认并强调裁量；哈特承认有限裁量；德沃金则试图以原则消解裁量，主张所谓裁量不过是法官在多个可接受解释中作判断。Wacks 指出，德沃金对裁量概念的批评，是其解释性法理学的重要部分。\n\n第二场争论是“法官个人因素是否应影响裁判”。批评者认为，法官背景与偏好影响判决，会损害法治的平等性；现实主义者则回应，这种影响本就存在，问题在于如何使它透明、可问责，而非假装它不存在。\n\n第三场争论关乎“司法裁判的客观性”。若法官判断不可避免，裁判还能否客观？哈特以规则框架与承认规则提供客观性基础；德沃金以整体性原则提供客观性标准；现实主义者则倾向于消解客观性神话，强调判断的语境性。Wacks 指出，洞穴探险者案中不同法官的意见，正展示了客观性的困难。", "case": "英国“女王诉达德利与斯蒂芬斯案”（R v Dudley & Stephens, 1884；上诉审 1885）是检验法官角色的经典真实案例。案情是：一艘游艇沉没，四名船员漂流海上，为求生而杀死并食用了一名重伤同伴。三人被以谋杀罪起诉。Wacks 把该案与洞穴探险者案并列提及（见其书相关章节）。\n\n案件的核心争议是：在极端生存情境下，是否可以以“必要”（necessity）作为谋杀罪的抗辩？法院最终拒绝了这一抗辩，判定谋杀罪成立，但量刑上予以宽大。从现实主义视角看，这一裁判体现了法官在规则与后果之间的权衡：严格适用谋杀罪规则会导致严酷结果，但承认必要抗辩又可能打开危险缺口。从德沃金视角看，法官须在尊重法律规则与回应道德直觉之间，通过原则解释寻找可证成的裁判。\n\n另一个案例是法官在“疑难案件”中的意见分歧。Wacks 指出，洞穴探险者案中 Handy 法官与 Foster 法官的鲜明对比，说明同一事实在不同司法理念下可得出不同结论。虽然该案是虚构的，但它所揭示的法官角色差异，在真实裁判中同样存在。", "caseAnalysis": "就达德利案而言，事实是：漂流船员为求生杀死同伴，被以谋杀罪起诉；争议焦点在于，“必要”能否作为谋杀罪的抗辩。从现实主义视角看，法官的判决深受其对后果与社会影响的判断影响——完全否认必要抗辩可能显得冷酷，但承认它又可能危及法律对生命的保护。从形式主义视角看，谋杀罪的构成要件明确，必要不能作为抗辩。\n\n从裁判理由看，法院坚持了规则的严格性，同时在量刑上体现宽大。这一处理方式，体现了法官在规则与后果之间的平衡——既维护规则的权威，又回应道德直觉。Wacks 提到该案与洞穴探险者案的关联，提示我们必须正视极端情境下法官角色的复杂性。\n\n这一案例的理论意义在于，它把“法官如何影响法律适用”具体化：在规则与道德直觉冲突的案件中，法官的判断确实塑造了结果。但哈特的回应仍有价值——法官的判断并未脱离法律框架，而是在规则、先例与制度约束中进行。德沃金则会强调，法官须通过原则解释，使裁判与法律实践的整体价值相连贯。", "summary": "法官影响法律适用的问题，源于规则的开放结构、事实认定的不确定性与法官个人因素的存在。现实主义以霍姆斯、卢埃林、弗兰克为代表，强调经验、政策判断与实际行为，揭示了法官判断在裁判中的真实作用。哈特以“开放结构”与有限裁量回应，主张大多数案件有明确答案；德沃金以“整体性”与原则理论回应，主张法官在疑难案件中也受原则约束、存在正确答案。达德利案等真实案例表明，法官的判断确实塑造裁判结果，但这种判断并非任意——制度约束、职业传统与法律原则共同构成边界。Wacks 对现实主义“悖论”的定位，提示我们既要承认法官角色的现实，也要维护法律确定性的价值。", "furtherThinking": "1. 法官的个人背景与价值观影响判决，这是法律缺陷还是法律常态？应如何通过制度设计提升透明度与可问责性？\n2. 哈特的有限裁量与德沃金的整体性解释，哪一种更能约束法官的主观任意？\n3. 事实怀疑论对司法制度有何启示？能否通过程序改革降低事实认定的不确定性？"}, "en": "How Judges Influence the Application of Law", "level": "core", "tags": "法官, 司法裁量, 规则怀疑论, 开放结构, 赫拉克勒斯", "source": "Wacks, Understanding Jurisprudence, ch.6；Hart, The Concept of Law, ch.7；Dworkin, Taking Rights Seriously", "id": "S2M3K3"}, "S2M3K4": {"title": "法律与社会现实", "EN": "Law and Social Reality", "LEVEL": "fundamental", "TAGS": "法律与社会, 行动中的法, 法律社会学, 活法, 法律移植", "TERMS": "行动中的法（Law in Action）::法律在实际社会运作中的样态；书本上的法（Law in Books）::以文本形式存在的法律规则；活法（Living Law）::埃利希提出的、实际支配社会生活的秩序；法律社会学（Sociology of Law）::以经验方法研究法律与社会关系的学科；法律移植（Legal Transplant）::法律制度从一个社会向另一个社会的移转", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6 §6.1；Siems, Comparative Law, ch.2, ch.6", "terms": [{"term": "行动中的法（Law in Action）", "def": "法律在实际社会运作中的样态"}, {"term": "书本上的法（Law in Books）", "def": "以文本形式存在的法律规则"}, {"term": "活法（Living Law）", "def": "埃利希提出的、实际支配社会生活的秩序"}, {"term": "法律社会学（Sociology of Law）", "def": "以经验方法研究法律与社会关系的学科"}, {"term": "法律移植（Legal Transplant）", "def": "法律制度从一个社会向另一个社会的移转"}], "sections": {"coreQuestion": "书本上的法律与社会中实际运作的法律，是否同一回事？如果法律规定与社会现实脱节，会产生什么后果？本节要说明：法律现实主义把“行动中的法”置于“书本上的法”之上，推动了法律社会学的发展；法律的比较研究也提示，法律制度的实际效果取决于它所在的社会语境。理解法律与社会现实的关系，是理解法律为何“纸面上完美、实践中走样”的关键。", "definition": "法律与社会现实的关系，可从三组概念入手。\n\n第一组是“书本上的法”（law in books）与“行动中的法”（law in action）。前者指以文本形式存在的法律规则，后者指法律在社会中实际如何运作。美国法律现实主义的核心贡献，正是把注意力从前者的逻辑分析转向后者的实际观察。霍姆斯的名言“法律的生命不在逻辑，而在经验”，是这一转向的标志。\n\n第二组是“活法”（living law）概念。奥地利法学家埃利希（Eugen Ehrlich）在《法律社会学基本原理》（1913）中提出，社会生活中实际支配人们行为的秩序，未必等同于国家制定的法律；真正的“活法”存在于社会共同体自身的实践之中。这一概念把法律研究的视野从国家制定法扩展到社会自发秩序。\n\n第三组是法律社会学（Sociology of Law）与法律移植（Legal Transplant）。法律社会学以经验方法研究法律与社会的关系；比较法研究则关注法律制度在不同社会中的运作。Wacks 指出，现实主义对法律社会语境的关注，构成对法律形式主义的重要纠偏；Siems 的比较法研究也强调，法律制度的效果离不开其社会语境。", "history": "十九世纪的法学主流关注法律概念的逻辑分析，倾向于把法律理解为封闭的规范体系。这种取向在英国分析法学与德国概念法学中尤为明显。然而，工业化与城市化带来的社会变迁，使纸面上的法律规则与社会现实之间的落差日益显著。\n\n美国法律现实主义在二十世纪二三十年代兴起，正是对这一落差的回应。Wacks 指出，现实主义者拒绝单一的逻辑路径，转而求助于社会学、心理学等经验科学；他们把法律置于社会语境中理解。Wacks 还指出，斯堪的纳维亚现实主义者的法理学范围更广，涵盖整个法律体系，其研究同样具有社会指向。\n\n比较法研究则提供了另一重视角。Siems 指出，不同法律传统（legal families）的制度安排各有其社会历史基础；法律制度从一个社会移植到另一个社会时，其效果往往取决于是否契合当地的社会条件。这提示我们，法律并非可以脱离语境而自动运作的技术工具。", "principle": "法律与社会现实的关系，可从三个层次理解。\n\n第一层是法律对社会现实的依赖。法律规则由社会制定，其正当性与有效性离不开社会的接受与制度支撑。哈特的承认规则存在于官员的共同实践中，罗斯的象棋类比强调规则存在于参与者的态度中——这些理论都指向一个共同点：法律的社会基础。\n\n第二层是法律对社会现实的作用。法律不仅是社会的反映，也塑造社会行为。奥利弗克罗纳甚至主张法律影响道德，而非仅仅反映道德。法律通过赋予权利、设定义务、组织制度，参与社会秩序的构造。\n\n第三层是法律与社会现实的脱节。当法律规定与社会现实相距过远时，可能出现两种后果：一是法律被普遍规避，丧失实际约束力；二是法律通过非正式的社会机制被“改造”，形成与文本不同的运作逻辑。法律现实主义与法律社会学关注的，正是这种脱节及其后果。", "viewpoints": "现实主义者的核心主张是：理解法律必须研究它在实际中的运作。霍姆斯以经验对抗逻辑；卢埃林主张法律就是官员处理纠纷的行为；弗兰克揭示事实认定的不确定性。Wacks 指出，现实主义者把法律置于社会语境中理解，这构成对形式主义的有力冲击。\n\n埃利希的核心主张是：社会中存在“活法”，即实际支配社会生活的秩序，它未必等同于国家法。这一概念把法律研究的视野扩展到社会自发秩序。\n\n比较法学者的核心主张是：法律制度的运作依赖社会语境。Siems 的比较法研究强调法律传统与社会条件的关联，法律移植的成功与否取决于制度与社会的契合度。", "comparison": "法律的现实主义视角与形式主义视角形成对照。形式主义关注法律概念的逻辑结构，相信规则可决定裁判；现实主义关注法律的实际运作，怀疑规则的决定力。前者长于概念分析，后者长于经验描述。Wacks 指出，现实主义的意义在于把法律放到社会语境中理解。\n\n法律社会学与分析法学亦形成对照。分析法学（如凯尔森的纯粹法学）追求价值中立与概念纯粹，刻意排除社会事实；法律社会学则主动引入社会学方法，研究法律在社会中的实际效果。Wacks 指出，凯尔森坚持法律科学家不关心人的实际行为，这与现实主义的社会取向截然相反。\n\n在法律与社会现实问题上，哈特的立场居于中间。他承认法律的社会基础（承认规则存在于官员实践中），也承认法律对社会行为的规范作用，但坚持法理学应描述法律的概念结构，而非变为社会学。这一立场提示：关注社会现实，不必放弃概念分析。", "debates": "关于法律与社会现实的第一场争论，是“法学应否引入社会学方法”。形式主义者与纯粹法学者主张法学应保持概念纯粹，排斥社会学；现实主义者则主张法律必须结合社会现实才能被理解。Wacks 指出，现实主义者拒绝单一的逻辑路径，寻求包括社会学、心理学在内的多种科学探究路径。这场争论塑造了法律社会学的发展空间。\n\n第二场争论关乎“法律能否脱离社会语境而被移植”。比较法研究中的法律移植争论，涉及法律制度能否跨文化有效运作。Siems 的比较法研究强调法律传统与社会条件的关联，这为质疑“法律移植万能论”提供了依据。\n\n第三场争论关乎“法律是社会现实的反映还是塑造者”。马克思主义传统倾向于强调法律对经济基础的依赖，而奥利弗克罗纳则主张法律影响道德。Wacks 指出，奥利弗克罗纳颠倒了通常“法律反映道德价值”的观点。这一争论的实质，是法律与社会之间因果方向的问题。", "case": "美国1920至1933年的“禁酒令”（Prohibition，宪法第十八修正案及其实施法）是法律与社会现实脱节的经典案例。法律明文禁止制造、销售与运输酒精饮料，但社会大众对饮酒有广泛需求，结果是禁酒令并未真正消除饮酒，反而催生了大规模地下酒类生产、走私与有组织犯罪。1933年，宪法第二十一修正案废除了禁酒令。\n\n从“书本上的法”看，禁酒令是正式有效的法律；从“行动中的法”看，它在实际中大规模被规避，并产生了立法者未曾预料的后果。这一案例说明，法律规则的效力与其社会效果之间存在落差：一项法律可以在形式上有效，却因缺乏社会接受而难以实现其目标。\n\n从比较法角度看，不同社会对类似问题的制度回应也不同——有些国家通过高税收与管制而非全面禁止来管理酒精消费。Siems 的比较法框架提示，制度设计必须考虑其社会语境。", "caseAnalysis": "就禁酒令而言，事实是：全面禁酒的法律与社会普遍饮酒的习俗相冲突；争议焦点在于，法律能否凭借强制力改变深层的社会行为模式。从现实主义视角看，禁酒令的失败说明法律不能脱离社会现实而被有效实施——纸面规则与社会实践之间存在巨大落差。从形式主义视角看，法律的效力不取决于其被遵守的程度，禁酒令在废止前仍是有效法律。\n\n这一案例的理论意义在于，它区分了法律的“效力”与“实效”。法律可以在效力上成立，却在实效上失败。Wacks 指出，凯尔森也区分了效力与实效，只不过他是在规范体系内部作此区分。现实主义与法律社会学则把这一区分推向经验研究：是什么因素使法律在社会中“起作用”？\n\n这一案例也提示法律移植的限度：一项在某一社会看似合理的制度，移植到社会条件不同的环境中，可能产生截然不同的效果。Siems 的比较法研究强调，法律制度的运作离不开其社会历史基础。", "summary": "法律与社会现实的关系，是法律现实主义与法律社会学的核心议题。“书本上的法”与“行动中的法”的区分，揭示了法律规则与社会实际运作之间的落差；埃利希的“活法”概念，把法律研究的视野从国家制定法扩展到社会自发秩序；比较法研究则强调法律制度对社会语境的依赖。现实主义以霍姆斯、卢埃林、弗兰克为代表，主张以经验方法研究法律的实际运作，构成对形式主义的重要纠偏；凯尔森的纯粹法学则刻意排除社会事实，与之形成对照。禁酒令的案例具体说明，法律可以在形式上有效却在实效上失败。理解法律与社会现实的关系，有助于避免把法律当作脱离社会的技术工具，也为法律改革提供了经验基础。", "furtherThinking": "1. 『法律有效』与『法律在社会中起作用』是否同一回事？禁酒令的案例说明了什么？\n2. 埃利希的『活法』概念对理解当代社会中的习惯法、行业规则有何启示？\n3. 法律移植要成功，需要考虑哪些社会条件？请结合比较法视角分析。"}, "en": "Law and Social Reality", "level": "fundamental", "tags": "法律与社会, 行动中的法, 法律社会学, 活法, 法律移植", "source": "Wacks, Understanding Jurisprudence, ch.6 §6.1；Siems, Comparative Law, ch.2, ch.6", "id": "S2M3K4"}, "S2M3K5": {"title": "批判法学运动", "EN": "The Critical Legal Studies Movement", "LEVEL": "core", "TAGS": "批判法学, CLS, 不确定性, 马克思主义, 法律与政治", "TERMS": "批判法学运动（Critical Legal Studies, CLS）::二十世纪七十年代美国兴起的、以马克思主义与跨学科方法批判法律中立性的运动；法律不确定性（Legal Indeterminacy）::法律规则与教义无法确定地决定裁判结果的主张；拆解（Trashing）::CLS 用以揭示法律概念内在矛盾与政治性的批判方法；意识形态霸权（Ideological Hegemony）::葛兰西提出的、统治观念借文化与制度取得支配地位的观念；共同体主义转向（Communitarian Move）::CLS 与社群主义共享的、强调共同体价值的理论取向", "SOURCE": "Wacks, Understanding Jurisprudence, ch.13 §13.1；Siems, Comparative Law, ch.4", "terms": [{"term": "批判法学运动（Critical Legal Studies, CLS）", "def": "二十世纪七十年代美国兴起的、以马克思主义与跨学科方法批判法律中立性的运动"}, {"term": "法律不确定性（Legal Indeterminacy）", "def": "法律规则与教义无法确定地决定裁判结果的主张"}, {"term": "拆解（Trashing）", "def": "CLS 用以揭示法律概念内在矛盾与政治性的批判方法"}, {"term": "意识形态霸权（Ideological Hegemony）", "def": "葛兰西提出的、统治观念借文化与制度取得支配地位的观念"}, {"term": "共同体主义转向（Communitarian Move）", "def": "CLS 与社群主义共享的、强调共同体价值的理论取向"}], "sections": {"coreQuestion": "批判法学运动（Critical Legal Studies, CLS）为何在二十世纪七十年代的美国兴起？它如何把法律现实主义对确定性的怀疑，推进为对法律中立性的全面批判？本节要说明：CLS 把法律理解为政治与权力斗争的场域，主张法律规则具有根本的不确定性，所谓法律的中立性与客观性掩盖了特定社会利益。理解 CLS，是理解当代法律理论中“法律与政治”之争的关键。", "definition": "批判法学运动（Critical Legal Studies, CLS）是二十世纪七十年代在美国兴起的法律思想运动。Wacks 指出，CLS 表达了一种广义的马克思主义法律批判，并持续对法律与政治关系的观念产生影响——尽管这种影响处于下降之中。\n\nCLS 的核心主张是法律不确定性（Legal Indeterminacy）。Wacks 指出，批判法律理论的中心主题，是怀疑能否发现一套统一的规则与教义体系；在批判法律理论家笔下，法律被描绘为不确定的、矛盾的政治与社会经济力量的产物。社会正义在 CLS 看来是一个空洞的承诺。\n\nCLS 的另一核心主张是法律的政治性。Wacks 指出，CLS 信徒把法律描绘为对特定社会关系的构成性（constitutive）因素，法律远非中立的工具。Wacks 还提到，社会正义在 CLS 中被视为空洞的承诺，法律与自由市场等安排被认为服务于特定利益。\n\n“拆解”（trashing）是 CLS 的典型批判方法。Wacks 的书以“Trashing CLS?”（拆解 CLS？）为章节标题，表明这一方法既被用于批判主流法律理论，也被用于自我反思。拆解旨在揭示法律概念与教义的内在矛盾，暴露其政治功能。\n\nCLS 还是一场跨学科运动。Wacks 指出，其重要特征是跨学科性，汲取政治学、社会学、历史学、哲学等领域的资源。", "history": "CLS 兴起于二十世纪七十年代的美国，其社会背景是民权运动、反越战运动与新左派思潮的高涨。Wacks 指出，CLS 在许多方面类似于更早的美国法律现实主义运动——它像现实主义一样怀疑法律的中立性，但更激进、更具政治自觉。\n\nWacks 把 CLS 的出现形容为在当时“沉闷的”（stultifying）法学界中吹进的一股新鲜空气；他甚至说，如果法理学是“流行音乐”，那么 CLS 可能是它的“摇滚”继承者。这一比喻说明 CLS 的反叛姿态。\n\nCLS 的思想资源包括马克思主义、法兰克福学派批判理论、葛兰西（Antonio Gramsci）的意识形态霸权理论等。Wacks 指出，“意识形态霸权”概念出现在意大利马克思主义者葛兰西的狱中著作中，指统治观念借教育、文化等机制取得支配地位。这一理论为 CLS 分析法律如何维持社会不平等提供了工具。\n\nWacks 也指出，CLS 的影响在后期有所下降（declining influence），但它对女性主义法学、后现代法学、批判种族理论等后续运动产生了深远影响。", "principle": "CLS 的理论逻辑可拆为四个环节。\n\n第一环是对法律确定性的怀疑。CLS 继承现实主义的规则怀疑论，但走得更远：法律规则不仅在某些情况下不确定，而且在其结构本身就充满矛盾。任何法律规则都可以被引用以支持相反的结论，因为法律语言包含相互竞争的价值与逻辑。\n\n第二环是对法律中立性的批判。自由主义法学把法律描绘为中立的规则体系，超越阶级与利益冲突。CLS 则主张，所谓中立性是一种意识形态：法律实际上体现并再生产特定的社会权力关系。Wacks 指出，古典马克思主义理论特别拒斥“法律可以是中立的”这一观念。\n\n第三环是法律对社会关系的构成性。CLS 不满足于说“法律反映利益”，而主张法律构成（constitutive）社会关系本身——法律创造并维持了特定的身份、权利与权力结构。Wacks 指出，CLS 信徒把法律描绘为对社会关系具有构成性的东西。\n\n第四环是共同体主义转向。Wacks 指出，共同体主义转向（communitarian move）是 CLS 工程与社群主义共享的特征。这一转向试图在批判自由主义个人主义的同时，寻找替代性的社会价值基础。", "viewpoints": "CLS 的核心主张可概括为五点。\n\n其一，法律具有根本的不确定性。Wacks 指出，批判法律理论的中心主题是怀疑统一规则教义体系的可能性，法律被描绘为不确定的、矛盾的。\n\n其二，法律是政治的。CLS 拒斥法律与政治的分离，主张法律决定本质上是政治判断。社会正义在其看来是空洞的承诺。\n\n其三，法律维护特定利益。CLS 以马克思主义为资源，分析法律如何服务于特定阶级与利益，尤其是自由市场等制度安排。\n\n其四，法律对社会关系具有构成性。法律主动塑造社会关系，被动反映社会的图景忽略了它的建构能力。\n\n其五，方法是跨学科与自我反思的。CLS 汲取多学科资源，并以“拆解”方法批判包括自身在内的法律理论。Wacks 的“Trashing CLS?”章节标题，正体现这种自我反思。", "comparison": "CLS 与法律现实主义的关系，是继承与激进。Wacks 指出，CLS 在许多方面类似于美国法律现实主义：两者都怀疑法律的中立性与确定性，都反对形式主义。差别在于：现实主义偏经验与心理学，关注法官实际行为；CLS 偏政治哲学与马克思主义，关注法律与权力结构的关系。可以说，现实主义揭示了法律的不确定性，CLS 则把这种不确定性政治化。\n\nCLS 与法律实证主义的关系，是对立。实证主义主张法律与道德分离、法律可由社会来源识别；CLS 则主张法律本身就是政治与意识形态，所谓中立识别掩盖了权力关系。Wacks 指出，CLS 对法律抱有“deep suspicion”（深度怀疑）。\n\nCLS 与自由主义法学的关系，是根本对立。自由主义法学相信法律的中立性、确定性与权利保护；CLS 则把这些视为意识形态神话。Wacks 指出，马克思主义法学的任务之一是批判自由主义政治哲学的核心。\n\nCLS 与后续批判理论的关系，是源流。Wacks 指出，现实主义是 CLS、女性主义与后现代理论等批判理论的先驱；CLS 本身也对后续运动产生深远影响。共同体主义转向则是 CLS 与社群主义共享的特征。", "debates": "围绕 CLS 的第一场争论，是“法律不确定性是否成立”。批评者（如哈特、德沃金）认为，CLS 夸大了法律的不确定性：大多数法律问题有明确答案，规则与原则提供了实质约束。德沃金的整体性理论尤其针对不确定性论题，主张法官可通过原则找到正确答案。CLS 则回应，所谓“正确答案”不过是特定解释共同体的政治选择。\n\n第二场争论关乎“拆解方法的破坏性”。Wacks 以“Trashing CLS?”为章节标题，提示 CLS 的拆解方法既是其武器，也招致批评：如果一切法律概念都被解构为政治伪装，法律理论的批判性如何可能？CLS 的支持者则会说，揭示矛盾正是为了重构更公正的制度。\n\n第三场争论关乎“CLS 是否提供建设性方案”。批评者认为 CLS 长于批判、短于建构，其“社会正义是空洞承诺”的判断可能导致虚无主义。Wacks 提到共同体主义转向，正可视为 CLS 寻找替代性价值基础的一种努力。", "case": "一个可用于检验 CLS 主张的现实例子，是美国宪法中的“平等保护条款”（Equal Protection Clause, 第十四修正案）的司法适用。该条款措辞抽象——“任何州不得…否认任何人获得法律的平等保护”。在历史上，法院曾用它推翻种族隔离（如 Brown v. Board of Education, 1954），也曾以它认可某些差别对待。\n\n从 CLS 视角看，这一条款的不确定性正说明法律教义的矛盾性：同一抽象原则可支持不同甚至相反的裁判，其结果取决于法院的政治语境与价值选择。法院的判决是在特定历史条件下作出的政治判断，从条文中逻辑推出的说法难以成立。\n\n另一个例子是合同法中“诚实信用”与“契约自由”的张力。两项原则都出现在法律体系中，但在具体案件中可能指向相反结论。CLS 会以这类张力说明，法律教义内部包含相互竞争的价值，所谓“法律的逻辑展开”往往掩盖了价值选择。", "caseAnalysis": "就平等保护条款而言，事实是：同一抽象宪法条款在不同时期被适用于不同议题，产生不同结论；争议焦点在于，这些结论是法律逻辑的展开，还是政治判断的产物。从 CLS 视角看，条款的抽象性使法官的价值选择得以介入，所谓“中立适用”是神话。从德沃金视角看，法官须通过整体性解释，找到与宪法传统最连贯且道德上最有说服力的理解——这既承认判断的存在，又为判断设定约束。\n\n从裁判理由看，法院确实会援引先例、文本与宪法价值，但这些材料的选择与权重往往反映时代精神。这为 CLS 提供了支持，但哈特的回应仍有价值：法官的判断在法律框架内进行，并非不受约束。\n\n这一案例的理论意义在于，它把“法律不确定性”从抽象命题转化为可观察的司法现象。CLS 的贡献在于揭示法律教义中的矛盾与政治性，其局限则在于可能低估法律框架的约束作用。Wacks 把 CLS 定位为“广义马克思主义法律批判”，并指出其影响虽在下降却持续存在，这一评价恰当地概括了其地位。", "summary": "批判法学运动（CLS）于二十世纪七十年代在美国兴起，以广义马克思主义批判为底色，核心主张包括法律的根本不确定性、法律的政治性、法律对特定利益的维护、法律对社会关系的构成性，以及跨学科与自我反思的方法。Wacks 指出，CLS 的中心主题是怀疑统一规则教义体系的可能性，法律被描绘为不确定、矛盾且与社会经济权力相连；社会正义在其看来是空洞承诺。CLS 继承并激进了法律现实主义的怀疑精神，与实证主义和自由主义法学根本对立，并深刻影响了女性主义法学、后现代法学等后续运动。关于不确定性、拆解方法的破坏性与是否提供建设性方案的争论，持续围绕 CLS 展开。平等保护条款的案例说明，CLS 对法律教义矛盾的揭示具有解释力，但其可能低估法律框架的约束作用。", "furtherThinking": "1. 法律不确定性是法律的固有特征，还是 CLS 的夸大之词？请结合德沃金的整体性理论分析。\n2. CLS 的『拆解』方法在批判法律意识形态的同时，是否也消解了自身批判的根据？\n3. CLS 与法律现实主义的差别，仅仅是激进程度之分，还是理论根本不同？"}, "en": "The Critical Legal Studies Movement", "level": "core", "tags": "批判法学, CLS, 不确定性, 马克思主义, 法律与政治", "source": "Wacks, Understanding Jurisprudence, ch.13 §13.1；Siems, Comparative Law, ch.4", "id": "S2M3K5"}, "S2M3K6": {"title": "法律与权力结构", "EN": "Law and Power Structures", "LEVEL": "debate", "TAGS": "法律与权力, 批判法学, 马克思主义, 意识形态霸权, 法治", "TERMS": "权力结构（Power Structures）::社会中资源、地位与影响力的制度化分配格局；法律工具论（Instrumental View of Law）::把法律视为统治阶级或强势集团工具的立场；意识形态霸权（Ideological Hegemony）::葛兰西提出的、统治观念借制度与文化取得自愿遵从的机制；法律拜物教（Legal Fetishism）::把法律当作独立自足的神秘实体的观念；法治（Rule of Law）::以普遍规则约束权力、保障权利的政治法律理想", "SOURCE": "Wacks, Understanding Jurisprudence, ch.13；Hart, The Concept of Law, ch.9；Raz, The Authority of Law", "terms": [{"term": "权力结构（Power Structures）", "def": "社会中资源、地位与影响力的制度化分配格局"}, {"term": "法律工具论（Instrumental View of Law）", "def": "把法律视为统治阶级或强势集团工具的立场"}, {"term": "意识形态霸权（Ideological Hegemony）", "def": "葛兰西提出的、统治观念借制度与文化取得自愿遵从的机制"}, {"term": "法律拜物教（Legal Fetishism）", "def": "把法律当作独立自足的神秘实体的观念"}, {"term": "法治（Rule of Law）", "def": "以普遍规则约束权力、保障权利的政治法律理想"}], "sections": {"coreQuestion": "法律是权力的工具，还是对权力的约束？这是法理学中争论最持久的问题之一。批判法学与马克思主义传统倾向于把法律理解为维护社会不平等的权力技术；自由主义法理论则强调法律的中立性、普遍性与对权力的制约。本节要把双方论据摆在同一平台上，检视“法律工具论”“法律相对自主性”“意识形态霸权”等核心概念，并说明为何这场争论无法被简单裁决。理解这一争论，是理解法律在当代社会中角色的关键。", "definition": "权力结构（Power Structures）指社会中资源、地位与影响力的制度化分配格局。法律与权力结构的关系问题，追问的是：法律只是既有权力分配的表达与工具，还是能够独立于、甚至制约权力？\n\n法律工具论（Instrumental View of Law）把法律视为统治集团推行其意志、维护其利益的工具。Wacks 指出，古典马克思主义理论特别拒斥“法律可以是中立的”这一观念，并批评马克思主义者倾向于把一切法律都当作阶级统治的工具。\n\n意识形态霸权（Ideological Hegemony）是葛兰西（Antonio Gramsci）提出的概念。Wacks 指出，“意识形态霸权”出现在意大利马克思主义者葛兰西的狱中著作中，指统治观念通过教育、文化等机制取得支配地位，使被统治者“自愿”接受现有秩序。这一概念比简单的“强制论”更精细：权力不仅靠压制，也靠塑造人们的观念与常识。\n\n法律拜物教（Legal Fetishism）指把法律当作独立自足、自发生效的神秘实体的观念。Wacks 指出，许多马克思主义者明确拒斥法律拜物教，主张揭示法律背后的社会关系。\n\n法治（Rule of Law）则是自由主义传统的核心理想：以普遍、公开、稳定的规则约束权力行使，保障个人权利。拉兹（Joseph Raz）等学者强调法治的价值，主张法治使法律能够指引行为并约束专断权力。", "history": "对法律与权力关系的思考，在马克思主义传统中占有核心地位。马克思（Karl Marx）在《资本论》等著作中，把法律与国家的性质置于资本主义生产方式的语境中理解。Wacks 指出，马克思主义法学的一大任务是批判自由主义政治哲学的核心，并分析法律如何服务于特定阶级的利益。\n\n二十世纪的马克思主义法律理论，发展出更精细的立场。Wacks 提到，有些马克思主义者主张抛弃法律与上层建筑的简单二分，把法律视为物质基础的一部分；也有人批评把法律孤立为上层建筑的独特部分。葛兰西的意识形态霸权理论，为理解法律如何维持社会共识提供了新工具。\n\n批判法学运动（CLS）在1970年代把这一批判推向美国法学界。Wacks 指出，CLS 表达了广义的马克思主义法律批判，法律被描绘为不确定的、与社会政治经济力量相连的。自由主义法学则坚持法律的中立性与法治价值，形成对峙。", "principle": "法律与权力结构的关系，可用四种模型来定位。\n\n模型一：工具论。法律是统治集团意志的直接表达，是维护特定利益的工具。其优点是揭示了法律与利益的关联；其缺点是过于简单，无法解释法律为何有时也保护弱者、约束强者。Wacks 指出，把一切法律都视为阶级统治工具的观点受到批评。\n\n模型二：构成论。法律构成社会关系本身——它创造并维持特定的身份、权利与权力结构，反映利益只是其中一个侧面。Wacks 指出，CLS 信徒把法律描绘为对社会关系具有构成性的东西。这一模型的优点是解释了法律为何能塑造社会现实；其缺点是可能夸大法律的决定作用。\n\n模型三：霸权论。法律通过塑造观念与常识，使现有权力关系取得“自愿”的接受。葛兰西的意识形态霸权理论是这一模型的代表。其优点是解释了为何法律权威能被广泛接受；其缺点是可能低估强制与物质因素。\n\n模型四：相对自主论。法律虽与社会权力相连，却具有相对自主性与自身逻辑：法律职业、法律传统与制度程序，使法律不能完全还原为权力意志。哈特的规则理论、承认规则与内部观点，提供了理解这种相对自主性的概念工具。法治理论也强调，普遍规则能够约束权力，即便权力本身制定规则。", "viewpoints": "马克思主义与 CLS 的核心主张是：法律与权力结构深度交织。Wacks 指出，古典马克思主义理论拒斥法律中立的观念；CLS 的中心主题是怀疑统一规则教义体系的可能性，法律被描绘为不确定、矛盾且服务于特定社会经济力量。葛兰西的意识形态霸权理论，则解释了法律如何维持统治的“同意”基础。\n\n自由主义法理论的核心主张是：法律作为普遍规则体系，能够约束权力并保障权利。哈特以承认规则与内部观点说明法律体系的运作，强调法律不只是命令；拉兹以渊源命题与法律权威理论，说明法律何以能主张正当权威，并强调法治的价值；德沃金以权利是“王牌”的命题，主张个人权利优先于集体功利目标。\n\n福柯（Michel Foucault）等当代理论家则从权力与话语的角度，分析法律如何生产与规训社会主体。这一路径与 CLS 有相通处，都强调法律与权力的深层关联。", "comparison": "工具论与构成论的差别，在于法律与权力的因果关系方向。工具论认为权力先于法律，法律是权力的表达；构成论认为法律与权力相互构成，法律参与塑造权力关系本身。Wacks 指出，CLS 对法律的描绘既强调其不确定性，也强调其构成性。\n\n霸权论与强制论的差别，在于权力维持的方式。强制论强调法律的国家强制力，霸权论则强调法律通过塑造观念取得“自愿”接受。葛兰西的理论为理解法律权威的“同意”基础提供了工具。\n\n自由主义法治论与 CLS 批判论的分歧，集中在法律能否中立。自由主义相信普遍规则可以超越特定利益，约束权力；CLS 则把这种“中立性”视为意识形态神话。Wacks 指出，CLS 对法律抱有深度怀疑，社会正义在其看来是空洞承诺。\n\n相对自主论试图在两者之间寻找中间地带：法律既不是纯粹的权力工具，也不是完全中立的规则体系；它有自身的制度逻辑与职业传统，这种逻辑使其能够在一定程度上约束权力。哈特的规则理论与法治理论，是这一立场的重要资源。", "debates": "第一场争论是“法律能否中立”。自由主义传统肯定，CLS 与马克思主义否定。Wacks 指出，古典马克思主义理论特别拒斥法律中立的观念；而马克思主义法学的一大任务，正是批判自由主义政治哲学的核心。这场争论的深层，是法律是否可能超越其社会起源而提供普遍正义。\n\n第二场争论关乎“法律是自主的还是被决定的”。工具论强调法律被社会力量决定；相对自主论强调法律有自身逻辑。Wacks 提到，有些马克思主义者主张抛弃法律与上层建筑的简单二分，把法律视为物质基础的一部分，这说明马克思主义内部对这一问题也无共识。\n\n第三场争论关乎“法治是否可能”。法治论者认为普遍规则可约束权力；CLS 认为所谓法治不过是掩盖权力运作的意识形态。Wacks 指出，CLS 对法律的怀疑以及“社会正义是空洞承诺”的判断，构成对法治理想的根本挑战。\n\nWacks 还提到，马克思主义传统内部对权利的态度并不一致：革命马克思主义者对权利“基本没有兴趣”，这主要是因为它们体现了特定的个人主义与自由主义观念。这提示我们，“法律与权力”的争论内部还有更细的分歧。", "case": "美国最高法院的“普莱西诉弗格森案”（Plessy v. Ferguson, 1896）与“布朗诉教育委员会案”（Brown v. Board of Education, 1954），是检验法律与权力关系的经典案例。普莱西案中，法院以“隔离但平等”（separate but equal）原则认可了种族隔离，为黑人争取平等权利设置法律障碍。布朗案中，法院推翻了这一原则，宣告公立学校中的种族隔离违反平等保护条款。\n\n从工具论视角看，普莱西案体现了法律作为维护白人至上权力结构的工具；布朗案则说明法律也可成为挑战既有权力结构的武器。从霸权论视角看，普莱西案的“隔离但平等”原则，为不平等的社会秩序提供了合法性叙事，使隔离看起来“自然”且“合法”。从法治论视角看，布朗案说明法律原则（平等保护）能够被用作批判和改造既有制度的资源——法律的普遍性原则具有超越其社会起源的批判力量。\n\n另一个例子是劳动法是制衡资本还是服务资本的历史争论。Wacks 指出，CLS 把自由市场等制度安排视为服务于特定利益，这为分析劳动法的功能提供了批判视角。", "caseAnalysis": "就普莱西案与布朗案而言，事实是：同一宪法平等保护条款，在不同历史时期被用于支持相反的社会安排；争议焦点在于，法律是权力结构的工具，还是能够超越权力结构。从 CLS 视角看，两案说明法律教义的不确定性：同一条款既能支持隔离也能支持平等，结果取决于法院所处的政治语境。从霸权论视角看，普莱西案反映了法律如何为种族等级提供合法性。从法治论视角看，布朗案说明法律的普遍原则可以被用来挑战不义制度。\n\n从裁判理由看，布朗案法院诉诸宪法平等保护原则与社会科学的经验证据，论证隔离本身即造成不平等。这一裁判说明，法律论证不只是政治力量的直接表达——它包含原则论证与经验论证，具有相对自主的推理逻辑。\n\n这一案例的理论意义在于，它同时展示了法律的两种面相：法律可以是维护权力的工具（普莱西案），也可以是挑战权力的资源（布朗案）。相对自主论或许最能解释这种双面性：法律与权力结构深度相连，但其制度逻辑与普遍性原则使其能够在特定条件下成为改造社会的力量。Wacks 对 CLS 的定位——广义马克思主义批判、影响下降却持续存在——提示我们，这场争论仍在继续，任何简单化的答案都难免片面。", "summary": "法律与权力结构的关系，可通过四种模型定位：工具论把法律视为权力意志的直接表达；构成论强调法律参与塑造社会关系；霸权论借葛兰西的理论说明法律如何取得“自愿”接受；相对自主论则强调法律有自身的制度逻辑，能在一定程度上约束权力。马克思主义与 CLS 强调法律与权力、阶级利益、意识形态的深度交织，拒斥法律中立神话；自由主义法理论（哈特、拉兹、德沃金）则强调法律的规范性、权威与权利保护。Wacks 指出，古典马克思主义拒斥法律中立观念，CLS 把法律描绘为不确定且与社会权力相连，而马克思主义内部对法律的上层建筑地位与权利问题亦有分歧。普莱西案与布朗案同时展示了法律作为权力工具与批判资源的双面性。成熟的立场，应当既承认法律与权力的深层关联，也不否认法律普遍原则的批判潜力。", "furtherThinking": "1. 法律工具论与相对自主论，哪一种更能解释布朗案这样的『法律挑战权力』现象？\n2. 葛兰西的意识形态霸权理论，对理解法律为何能取得自愿服从有何贡献？其局限是什么？\n3. 自由主义法治理想在权力高度不平等的社会中是否可能？请结合 CLS 的批判分析。"}, "en": "Law and Power Structures", "level": "debate", "tags": "法律与权力, 批判法学, 马克思主义, 意识形态霸权, 法治", "source": "Wacks, Understanding Jurisprudence, ch.13；Hart, The Concept of Law, ch.9；Raz, The Authority of Law", "id": "S2M3K6"}, "S2M4K1": {"title": "比较法的概念与研究方法", "EN": "The Concept and Research Methods of Comparative Law", "LEVEL": "core", "TAGS": "比较法, 功能主义, 法律体系, 研究方法", "TERMS": "比较法（Comparative Law）::对两个或两个以上法律体系、制度或规则进行比较研究的学科与方法；法律体系（Legal System）::一国或一共同体中由法院、法律规则与法律方法构成的制度整体；功能主义（Functionalism）::从社会问题或功能需求出发比较不同法律体系解决方案的研究路径；功能等价物（Functional Equivalent）::不同法律体系中解决同一社会问题的不同制度或规则；法律文化（Legal Culture）::一个共同体中关于法律的价值观念、思维习惯与行为模式；宏观比较（Macro-comparison）::对整个法律体系或法律家族进行的比较；微观比较（Micro-comparison）::对具体法律规则或个案进行的比较；明示的比较法（Explicit Comparative Law）::以比较为自觉目的系统展开的学术研究；默示的比较法（Implicit Comparative Law）::在社会科学研究中不那么自觉地运用的比较视角；语境化（Contextualisation）::把法律规则放回其政治经济社会环境中理解的研究取向", "SOURCE": "Siems, Comparative Law, ch.1, ch.2, ch.11；Zweigert & Kötz, Introduction to Comparative Law, Introduction", "terms": [{"term": "比较法（Comparative Law）", "def": "对两个或两个以上法律体系、制度或规则进行比较研究的学科与方法"}, {"term": "法律体系（Legal System）", "def": "一国或一共同体中由法院、法律规则与法律方法构成的制度整体"}, {"term": "功能主义（Functionalism）", "def": "从社会问题或功能需求出发比较不同法律体系解决方案的研究路径"}, {"term": "功能等价物（Functional Equivalent）", "def": "不同法律体系中解决同一社会问题的不同制度或规则"}, {"term": "法律文化（Legal Culture）", "def": "一个共同体中关于法律的价值观念、思维习惯与行为模式"}, {"term": "宏观比较（Macro-comparison）", "def": "对整个法律体系或法律家族进行的比较"}, {"term": "微观比较（Micro-comparison）", "def": "对具体法律规则或个案进行的比较"}, {"term": "明示的比较法（Explicit Comparative Law）", "def": "以比较为自觉目的系统展开的学术研究"}, {"term": "默示的比较法（Implicit Comparative Law）", "def": "在社会科学研究中不那么自觉地运用的比较视角"}, {"term": "语境化（Contextualisation）", "def": "把法律规则放回其政治经济社会环境中理解的研究取向"}], "sections": {"coreQuestion": "比较法（Comparative Law）究竟是一门独立的学科，还是一种可以附着在任何法律研究上的方法？当一位立法者研究美国公司法、一位法官阅读德国判决时，他们所做的『比较』与法学院课堂上系统性的比较法研究是否同一回事？更进一步，比较法凭什么把语言不同、历史各异的法律体系放在同一张桌面上？Siems 提醒我们，『比较常常通过误导性或夸大的二元对立来进行』，那么比较法应当如何避免把复杂差异压扁成『英美法对大陆法』这样的口号？本节要解决的，正是比较法的对象、功能与基本方法这三件事，尤其要弄清 Siems 所说的『语境化』(contextualised) 比较到底意味着什么。", "definition": "比较法（Comparative Law）是对两个或两个以上法律体系、制度或规则进行比较研究的学科，也是一套可运用于立法、司法与教学的方法。Siems 区分『明示的比较法』(explicit comparative law)——以比较为自觉对象、在课程与著作中系统展开的研究——与『默示的比较法』(implicit comparative law)——在社会学、政治学、经济学研究中不自觉运用的比较视角。这一区分说明，比较的冲动广泛存在，但成为一门学科需要方法论上的自觉。\n\n从研究尺度看，比较可分为宏观比较（macro-comparison）与微观比较（micro-comparison）：前者比较整个法律体系或法律家族（如普通法系与大陆法系），后者比较具体规则或个案（如两大法系对违约金的处理）。从功能看，比较法服务于理解外国法、反思并改进本国法、推动法律协调与统一、以及支持法律发展（law and development）等目的。\n\n比较法与相邻学科的关系需要厘清。它与法理学（Jurisprudence）不同：后者追问『法律是什么』这类普遍问题，前者强调不同地方的法律如何不同又如何相通。它与法律史也不同：法律史关心时间轴上的演变，比较法关心同一时段不同空间中的差异；不过 Siems 强调，任何严肃的比较都离不开历史语境，二者实为互补而非对立。", "history": "比较法的兴起与现代民族国家、法典化运动和跨文化交流同步。罗马法学家早已用万民法（ius gentium）处理不同民族法律中的共通成分，近代的『罗马法继受』(reception) 则让一套超越国界的共同法（ius commune）覆盖了欧洲大陆。十九世纪民族国家兴起、法典化运动展开，法国 1804 年民法典与德国 1900 年民法典成为两大范本，各国立法者开始有意识地参照他国经验，比较法由此获得实践动力。殖民扩张把欧洲法律带到亚洲与非洲，既传播了法律，也制造出混合体系。二十世纪两次世界大战之后，国际人权法与区域一体化的发展进一步推动比较法走向制度化与教学化。Siems 的教科书以『语境化』为特色，正是对早期比较法偏重规则、忽略政治经济背景倾向的修正。", "principle": "比较法如何操作？主流答案来自 Zweigert 与 Kötz 的功能主义（functionalism）路径，可分三步。第一步，选定一个功能性问题作为比较起点——不问『某国法条怎么写』，而问『当合同一方违约时，法律如何保护另一方』。第二步，在各体系中寻找解决同一问题的制度，即功能等价物（functional equivalent）；名称不同、教义不同并不妨碍它们承担相同功能。第三步，比较各方案的实际效果并作出评价。\n\n功能主义的优点是把不同法系拉平到同一问题平面，避免被概念术语的表象迷惑。其弱点也明显：它预设『所有社会面临相同问题』，可能忽略问题本身是被文化地定义的。Siems 在书中专门列出『对功能主义的批评』(critics of functionalism)，指出功能主义倾向于聚焦西方国家、把规则从语境中抽离、并把『哪种方案更好』的价值判断伪装成中立分析。因此他主张把法律放回其政治、经济与社会环境中理解，并引入政策评价（policy evaluation）。\n\n比较还必须处理『可比性』难题。不同体系中的术语常是『假朋友』：字面相同的词未必对应相同制度。以『善意』(good faith) 为例，它在大民法系是贯穿合同法的基本原则，在英格兰法中却长期不被承认为一般原则；若仅凭字面比较，会得出错误结论。可比的起点应当是功能与效果，而非术语本身。", "viewpoints": "功能主义一脉以 Zweigert、Kötz、Markesinis 为代表，强调比较法的实用价值。Markesinis 呼吁『增加智识互动与借鉴』(increase intellectual interaction and borrowings)，视比较法为改进本国法的工具；Alan Watson 更把法律移植（legal transplants）看作法律发展的常态。\n\n文化主义一脉以 Pierre Legrand 为代表。他认为法律『不只是法律文本中的词』，规则的意义取决于解释者在其文化认知框架中的理解；由此他提出『法律移植的不可能性』(impossibility of legal transplants)，主张法律的地方性知识无法被连根拔起地搬运。Siems 采取折中而开放的立场：既承认功能比较的价值，又以社会法学（socio-legal）方法、数值比较（numerical comparative law）与语境分析加以补充，主张比较法是一门『开放的学科』(an open subject)。", "comparison": "把功能主义与文化主义并置，分歧集中在三点。其一，比较的起点：前者从问题与功能入手，后者从意义与文化入手。其二，对差异的态度：前者倾向于寻找可通约的共通项，后者强调差异的不可化约。其三，对移植的判断：前者乐观，后者怀疑。\n\n需要避免一种粗糙说法，即把功能主义说成『只关心条文』、把文化主义说成『只谈玄学』。Siems 提醒，功能主义内部也发展出对『政策评价』的自觉反思，而文化主义者也承认立法者确实会互相借鉴文本。两者的真实分歧更多在于：当我们在两种制度间看到相似的功能时，这种相似是『真实的』，还是观察者用同一问题框架投射出来的？这一争论没有终局，但它塑造了比较法的自我理解。", "debates": "比较法史上最持久的争论，是『可比性—功能主义之争』。二十世纪中期，Zweigert 与 Kötz 确立功能主义的正统地位，主张比较法应围绕功能等价物展开，以此绕开概念差异。Legrand 在二十世纪九十年代以后发起批评，认为功能主义预设了一份普适的『问题清单』，把活生生的法律文化压扁成干瘪的功能描述，其结果是『抹平差异』(marginalising difference)。他甚至主张，一种法律制度对他者而言『只能在我的条件下被理解』(can only ever be intelligible to me on my terms)。\n\nSiems 的回应是语境化与多元化方法。他明确指出，比较常常通过误导性或夸大的二元对立来进行，因而既要警惕过度强调差异，也要警惕过度强调共性。他主张比较法应吸收社会法学的洞见——研究『行动中的法』(law in action) 而非仅『书本上的法』(law in books)——并借助量化手段测量法律规则与司法实践。这场争论的遗产是：今天的比较法学者普遍意识到，方法的选择本身就是一种理论立场。", "case": "一个能说明功能比较如何运作的例子，是两大法系对『合同中的善意』(good faith) 的处理。大陆法系把善意视为一般原则：德国民法典第 311 条第 2 款把缔约前关系纳入债的关系，使善意原则适用于缔约过失；法国借侵权法处理缔约阶段的责任；荷兰以公平原则为基础。普通法系长期拒绝把善意作为一般原则——1766 年 Mansfield 勋爵虽曾称善意是『适用于一切合同与交往的支配原则』，但 1992 年 Walford v Miles 案中 Ackner 勋爵明确表示反对。\n\n然而功能比较追问的是：普通法是否以别的方式实现了相近效果？答案是肯定的：默示条款（implied terms）、对显失公平交易的衡平救济、消费者保护立法都在承担类似功能。Siems 援引的研究表明，在英美法院的司法实践中，善意只是『一个较弱的解释工具』(a weak interpretative tool)。这个案例说明，判断两个体系是否『相同』，取决于我们比较的是术语还是功能。", "caseAnalysis": "就『善意』案例而言，事实层面是：德国、法国、荷兰以不同教义技术承认缔约阶段的保护义务，英格兰法则长期否认一般善意原则。争议焦点在于：普通法是否真的缺少大陆法意义上的善意？从功能主义视角看，答案倾向于『否』——不同制度安排可以达到相近结果；Sacco 关于英法律师讨论赠与合同的著名例子也表明，操作规则（operative rules）可能相似，而解释它们的教义装置（dogmatic apparatus）却完全相反。\n\n从文化主义视角看，答案则倾向于『是』——Teubner 把善意移植到普通法称为『法律刺激物』(legal irritant)，认为这种抽象开放的原则是『大陆法律文化的独特表达』。Siems 提供的经验材料进一步复杂化了画面：Common Core 项目研究了欧洲法律体系解决三十个善意案例的情况，十一个得到相同结果，九个大体和谐但不完美，十个出现显著分歧，而英格兰法『常常但并非总是』走自己的路。\n\n这个案例的理论意义在于：它同时展示了功能等价物的解释力与限度。功能比较揭示结果层面的趋同，文化分析提醒我们趋同背后的机制差异。一个成熟的分析必须同时回答『结果是否相似』与『相似是如何被制造出来的』这两个问题。", "summary": "比较法既是一门学科也是一套方法，其对象涵盖法律体系、制度与规则，其尺度可为宏观或微观。主流的功能主义路径从社会问题出发寻找功能等价物，优点是跨越概念表象、直指实际效果；其局限在于可能过度抽离语境、把价值判断伪装成中立分析。Legrand 的文化主义强调法律的意义依赖解释者所在的文化认知框架，并由此怀疑真正的移植。Siems 以语境化、社会法学与量化方法加以综合，主张比较法是一门开放学科。善意案例表明：结果相似与机制相似是两件事，比较法必须在二者之间保持张力。", "furtherThinking": "1. 如果你要比较两国对『职场性骚扰』的法律规制，你会从功能问题入手，还是从两国法律概念的历史语义入手？两种方法各会漏掉什么？\n2. 当立法者说『我们借鉴了德国经验』时，这句话在功能主义者和文化主义者耳中分别意味着什么？\n3. 在算法与平台治理这类新兴领域，尚无成熟的外国制度可参照，比较法还能做什么？"}, "en": "The Concept and Research Methods of Comparative Law", "level": "core", "tags": "比较法, 功能主义, 法律体系, 研究方法", "source": "Siems, Comparative Law, ch.1, ch.2, ch.11；Zweigert & Kötz, Introduction to Comparative Law, Introduction", "id": "S2M4K1"}, "S2M4K2": {"title": "比较法的历史发展", "EN": "The Historical Development of Comparative Law", "LEVEL": "fundamental", "TAGS": "比较法史, 罗马法继受, 法典化, 法律家族", "TERMS": "万民法（Ius Gentium）::罗马法中处理不同民族共同法律问题的规则体系；罗马法继受（Reception of Roman Law）::中世纪后期欧洲大陆重新采纳罗马法的历史过程；共同法（Ius Commune）::中世纪欧洲超越国界的通用法律传统；法典化（Codification）::把法律系统编纂为统一法典的立法运动；法律家族（Legal Family）::基于共同历史、思维与规则而划分的国家法律群体；法律起源（Legal Origins）::经济学与政治学用法律传统解释经济绩效的研究路径", "SOURCE": "Siems, Comparative Law, ch.3, ch.4, ch.8", "terms": [{"term": "万民法（Ius Gentium）", "def": "罗马法中处理不同民族共同法律问题的规则体系"}, {"term": "罗马法继受（Reception of Roman Law）", "def": "中世纪后期欧洲大陆重新采纳罗马法的历史过程"}, {"term": "共同法（Ius Commune）", "def": "中世纪欧洲超越国界的通用法律传统"}, {"term": "法典化（Codification）", "def": "把法律系统编纂为统一法典的立法运动"}, {"term": "法律家族（Legal Family）", "def": "基于共同历史、思维与规则而划分的国家法律群体"}, {"term": "法律起源（Legal Origins）", "def": "经济学与政治学用法律传统解释经济绩效的研究路径"}], "sections": {"coreQuestion": "比较法不是凭空出现的学问，它的形成与欧洲法律史上几次大转折紧密相连。为什么罗马法的继受会让欧洲大陆形成不同于英格兰的法律传统？十九世纪的法典化运动又如何同时塑造了比较法的对象与动力？理解比较法的历史，有助于回答一个现实问题：今天我们把世界法律划分为『普通法系』与『大陆法系』，这套地图究竟是历史的产物，还是放之四海的真理？本节沿着罗马法、继受、法典化、殖民与全球化几条线索，勾勒比较法的形成过程。", "definition": "比较法的历史发展，指的是比较研究作为一种法律实践与学术方法的形成与演变过程。它既包括比较意识的萌芽（如罗马法中的万民法 ius gentium），也包括比较法作为独立学科的制度化。与之密切相关的概念是法律家族（legal family）：Siems 指出，法律家族的核心思想在于，世界法律体系的多样性有规律可循，若干国家在法律历史、法律思维与实在规则上共享特征。近代经济学与政治学又提出法律起源（legal origins）理论，用法律传统解释经济绩效，使法律家族概念获得新的生命力。", "history": "比较法的历史动力来自三个层面的互动。其一是罗马法的遗产：公元六世纪查士丁尼主持编纂的《国法大全》(Corpus Juris Civilis, 533 AD) 在十一世纪于欧洲大陆复兴，形成所谓『继受』(reception)。Siems 强调三个特征：大学推动了罗马法的传播，故大陆法常被称为『学者法』(learned law)；被继受的罗马法是一种超越国界的共同法（ius commune），取代或补充了地方法习惯；司法实施被置于国家的严格控制之下。其二是民族国家与法典化：十八、十九世纪国家开始把罗马法与地方法编纂为统一法典，1804 年法国民法典被视为现代大陆法传统的象征，1900 年德国民法典则风格更概念化、更教授化。其三是殖民与全球化：欧洲法律随殖民帝国扩散，日本、土耳其等国还主动移植了大陆法典，比较法由此获得世界尺度。", "principle": "理解这段历史，可把握三条相互交织的线索。\n\n第一条是『共同法—国家法典』的转化。继受时期的欧洲大陆共享一套罗马法共同法，但民族国家兴起后，各国法典化逐渐改变了查士丁尼版本的罗马法，共同性因而削弱。Siems 指出，欧洲不同地方早就有不同的『共同法』（法国的 droit commun、德国的 gemeine Recht、西班牙的 derecho común），它们并未因罗马法继受而消失。\n\n第二条是『学者法』传统的延续。在大陆，大学教授对法律的影响深远——据说十九世纪德国的潘德克顿学派（Pandectists）『写就了』1900 年民法典，德国 2002 年的民法典改革也以教授报告为基础。这与英格兰由法官主导、法国由立法者主导的格局形成对照。\n\n第三条是英格兰的独立路径。1066 年诺曼征服后，威廉一世以标准化的令状（writs）与巡回审判统一法律，事实认定交由陪审团。Maitland 的名言概括其深远影响：『我们埋葬了诉讼形式，它们却仍在坟墓中统治我们。』这份以判例为基础的传统随殖民传播到美国、澳大利亚与印度。", "viewpoints": "关于这段历史如何塑造今日格局，学者有不同侧重。传统比较法（如 Zweigert 与 Kötz）强调法律家族的分类意义，把法国民法典与德国民法典视为大陆法的两大范本，把英格兰与美国视为普通法的两支。Siems 则采取更审慎的态度：他既承认法国与德国法的强大影响，又提醒法典化运动实际上『导致了欧洲大陆法律的分化』，并指出不少分类法把北欧国家单列，因为它们没有采纳综合性法典。这一视角为理解法律趋同与分化埋下伏笔。", "comparison": "比较法的历史叙述可与传统法律史对照。法律史关注某一法律规则的纵向演变，比较法则关注同一时期不同社会的横向差异；但 Siems 强调二者互补——不理解罗马法继受的历史，就无法理解为何大陆法系是『学者法』，为何判例在法国不具有正式渊源地位。与纯粹的法律思想史相比，比较法的历史叙述更关注制度（法院、大学、法典）如何塑造法律思维，而非仅仅观念的流变。", "debates": "围绕比较法的历史，一个持续争论是：法律家族的分类在今日还有多少解释力？Siems 在书中专门讨论『过度强调差异』『过度强调共性』与『忽视混合体』(disregard of hybrids) 三种偏向。批评者认为，把世界法律画成普通法与大陆法两张标签，会遮蔽大量事实：法国法与德国法的差异可能大于法国法与英格兰法的差异；美国法与英格兰法之间也存在深刻分歧；许多殖民地法则是混合体。由此引出的问题是：历史形成的分类，今天究竟是认识工具，还是思维枷锁？这一争论在后续章节继续展开。", "case": "日本的法律现代化是法律移植.history 的典型案例。明治维新后，日本主动移植西方法典，其民法典与商法典深受德国法影响，刑法则受法国法影响。Siems 把日本与土耳其并列，作为『自愿移植大陆法主要法典』的例子。这个案例说明，法律家族的形成既可能来自殖民强制，也可能来自主动选择；历史传播路径决定了日本法在比较法地图上被归入大陆法系，但其本土习惯法要素始终存在。", "caseAnalysis": "就日本而言，事实是：十九世纪末日本在短时间内完成了法典化，主要参照德国与法国模式。争议焦点在于：这种移植是否真的让日本法变成『德国法』？功能视角会关注制度是否运转，文化视角则质疑外来法典能否脱离本土语境。Siems 的经验研究显示，移植后的法律往往在运作中发生变形，『没有不变形的运输』。这一案例的理论意义在于：法律家族的归属描述的是历史的来源，而非当下的全部现实；比较法必须区分『历史谱系』与『实际运作』两个层面。", "summary": "比较法的历史可概括为：罗马法提供共同遗产，继受塑造大陆的学者法传统，民族国家法典化使法国与德国民法典成为范本并造成大陆内部的分化，殖民与主动移植把两大传统扩散到全球。英格兰则走上以令状、判例与陪审团为特征的独立路径，并随殖民影响美国等地。法律家族的概念有助于把握这段历史，但 Siems 提醒不要把它绝对化：混合体系、西方化与内部差异都在削弱两张标签的解释力。历史是理解比较法的钥匙，却不是它的终点。", "furtherThinking": "1. 罗马法继受让大学教授在大陆法中占据核心地位，这种『学者法』传统今天是否仍明显？请举例。\n2. 法典化既传播了大陆法，又造成大陆内部的分化。这一双重效应说明了什么？\n3. 若一个国家的法律同时受德国法、法国法与本土习惯影响，把它归入『大陆法系』会遮蔽什么？"}, "en": "The Historical Development of Comparative Law", "level": "fundamental", "tags": "比较法史, 罗马法继受, 法典化, 法律家族", "source": "Siems, Comparative Law, ch.3, ch.4, ch.8", "id": "S2M4K2"}, "S2M4K3": {"title": "法律制度的分类", "EN": "The Classification of Legal Systems", "LEVEL": "core", "TAGS": "法律家族, 法律传统, 混合体系, 法律起源", "TERMS": "法律家族（Legal Family）::基于共同历史、法律思维与规则而划分的国家法律群体；法律传统（Legal Tradition）::与法律家族相近、强调历史连续性的分类单位；法律文化（Legal Culture）::共同体中关于法律的价值观念与思维行为模式；混合体系（Hybrid/Mixed Legal System）::融合两种或两种以上法律传统的制度；罗马法族（Romanist Group）::以法国民法典为范本的大陆法分支；日耳曼法族（Germanic Group）::以德国民法典为范本的大陆法分支；法律起源理论（Legal Origins Theory）::用法律传统的差异解释经济与制度绩效的研究路径", "SOURCE": "Siems, Comparative Law, ch.3, ch.4；Zweigert & Kötz, Introduction to Comparative Law, Part One", "terms": [{"term": "法律家族（Legal Family）", "def": "基于共同历史、法律思维与规则而划分的国家法律群体"}, {"term": "法律传统（Legal Tradition）", "def": "与法律家族相近、强调历史连续性的分类单位"}, {"term": "法律文化（Legal Culture）", "def": "共同体中关于法律的价值观念与思维行为模式"}, {"term": "混合体系（Hybrid/Mixed Legal System）", "def": "融合两种或两种以上法律传统的制度"}, {"term": "罗马法族（Romanist Group）", "def": "以法国民法典为范本的大陆法分支"}, {"term": "日耳曼法族（Germanic Group）", "def": "以德国民法典为范本的大陆法分支"}, {"term": "法律起源理论（Legal Origins Theory）", "def": "用法律传统的差异解释经济与制度绩效的研究路径"}], "sections": {"coreQuestion": "比较法的第一步往往是『分类』：把世界各国的法律整理成若干类别。我们熟悉的『大陆法系』『普通法系』就是这种分类的产物。但分类真的只是中性的整理吗？当把一个国家贴上『大陆法』标签时，我们实际上断言了它与法德法等国家共享某些本质特征。这些断言可靠吗？那些同时受多种传统影响的国家（如路易斯安那、魁北克、南非）又该归到哪里？本节考察法律制度分类的标准、主要方案及其局限，重点理解 Siems 为何既承认分类的价值，又反复警告不要把它绝对化。", "definition": "法律制度分类，是依据若干共同特征把世界各国的法律体系归入不同类别的工作。Siems 指出，大多数比较法教科书都设有『法律家族』(legal families) 章节，有些用『法律传统』(legal traditions) 或『法律文化』(legal cultures) 等术语。其核心思想是：世界法律体系的多样性『并非随机』，成组的国家在法律历史、法律思维与实在规则上共享特征。\n\n分类的单位与层次需要区分。最粗略的层次是『法系』，如大陆法系与普通法系；第二层次是在大陆法系内部分出罗马法族（Romanist group，以法国民法典为范本）与日耳曼法族（Germanic group，以德国民法典为范本）；更细的层次则可包括北欧法、宗教法等。Siems 还提到经济学与政治学中的法律起源（legal origins）理论，它把法律家族用于解释经济绩效，使分类获得了新的用途。", "history": "法律家族的分类观念与近代比较法同步成长。十九世纪法典化之后，法国民法典与德国民法典成为两大输出范本，学者自然以它们为中心划分大陆法内部。二十世纪，Zweigert 与 Kötz 的《比较法总论》确立了以『法律圈』(Rechtskreis) 为核心的分类体系，影响深远。勒内·达维德（René David）等法国学者也提出各有侧重的方案。进入二十一世纪，全球化与混合体系的增多使传统分类面临压力，Siems 在第四章专设『批判分析』一节，讨论分类中过度强调差异、过度强调共性与忽视混合体三种偏向。", "principle": "分类如何具体操作？可从标准、层级与有效性三个层面理解。\n\n第一，分类标准。Siems 指出，一个国家属于哪个法律家族，往往由法律的『方式』(way of doing law) 决定——即法律渊源、法律方法、法院组织与推理风格等。例如是否以法典为主要渊源、判例是否具有约束力、法官是职业官僚还是独立裁断者，都是常用指标。他强调，『法律思维方式』(way of thinking about law) 同样是关键标准。\n\n第二，分类层级。传统上先分大陆法与普通法两大阵营，再在大陆法内区分法国法族与德国法族。Siems 指出，不少分类法还会为北欧国家单列一类，理由是它们没有采纳综合性法典，与其他大陆体系有别。\n\n第三，分类的有效性。分类是『理想类型』(ideal type)，现实国家很少完全符合。Siems 指出，现代大陆法国家可能有与罗马法恰好相反的规则（如允许实际履行）；欧洲各国早就有不同的『共同法』；民族国家的法典化又不断改造共同遗产。因此分类描述的是倾向与谱系，而非严格的封装。", "viewpoints": "关于分类的标准与价值，学者有不同主张。Zweigert 与 Kötz 主张以『法律样式』(Rechtskreis) 为核心，把法律思维方式作为划分标准，并强调功能比较应建立在正确分类之上。达维德（René David）则更强调意识形态与世界观因素，把法律家族与社会的政治、经济、文化背景联系起来。\n\nLegrand 从文化主义出发质疑分类本身：法律的意义嵌在具体的文化认知框架中，所谓『家族相似性』若只关注规则的文字，便是 superficial（表面的）、rhetorical（修辞的）。Siems 综合各方，采取一种实用而审慎的立场：分类不可避免，也有认知价值，但必须警惕把它当作理解法律的唯一工具。", "comparison": "法律家族分类可与『法律起源理论』对照。前者是法学家为主的传统工作，关注法律思维与制度；后者是经济学家与政治学家的路径，把法律传统作为解释变量，研究其对金融发展、公司治理等的影响。两者共享『法律传统有持久影响』的直觉，但后者更追求可量化的相关性，前者更重视历史与文化的解释。Siems 提醒，法律起源理论虽有启发性，但也可能把复杂的法律传统简化为几个可测变量。\n\n分类还可与『法律文化』概念对照。法律家族强调制度与规则的亲缘，法律文化强调价值观念与思维习惯。前者便于宏观制图，后者便于解释同一家族内部的差异。", "debates": "分类领域最有影响的争论，是传统二分法是否仍然有效。Siems 归纳了三种偏向：过度强调差异（overemphasis of differences）、过度强调共性（overemphasis of similarities）与忽视混合体（disregard of hybrids）。\n\n支持二分者认为，大陆法与普通法在渊源、方法、法院与程序上形成相对连贯的『 bundles 』（ bundles of features），彼此难以混合。批评者则指出：法国法与德国法的差异可能大于法国法与英格兰法的差异；美国法与英格兰法也相去甚远；殖民与全球化制造了大量混合体系；此外，所谓『西方化』(Westernisation) 正在重塑多国法律，使传统分类失去解释力。Siems 的结论是审慎的：批判二分法反对把它当作理解法律的主要工具，差异的存在并不因此被否认。这一立场贯穿全书，也连接着后面的混合体系与趋同讨论。", "case": "混合法律体系是检验分类边界的试金石。Siems 在第四章『忽视混合体』一节讨论了这一现象：路易斯安那与魁北克的私法保留法国法传统，而公法与美国、加拿大其他地区相通；南非的法律则同时带有罗马—荷兰法与英美法成分。这些法域无法被干净地塞进『大陆法』或『普通法』任一格子。它们说明，法律家族的边界常常是历史接触、殖民与移民的产物，而非逻辑上互斥的类别。", "caseAnalysis": "以路易斯安那为例，其法律地图上呈现明显的『混合』特征：私法传统承袭法国民法与西班牙法的影响，采用民法典；但公法、程序与许多商事制度则与美国普通法趋同。争议焦点是：它究竟属于大陆法系还是普通法系？无论选哪一边，都会遮蔽另一半事实。\n\n从分类理论看，这一案例的意义在于揭示『理想类型』的限度：分类是为认知目的而作的简化，现实中的法律体系往往处于交叉地带。Siems 借此类案例主张，比较法应把混合体视为常态而非例外，并警惕把分类标签当作本质判断。对于学习者而言，重要的是理解某个国家为何呈现这样的混合，以及混合带来了哪些制度后果；记住它属于哪个法系反倒次要。", "summary": "法律制度分类是比较法的基础工作，法律家族、法律传统、法律文化是常用单位，主要标准为法律渊源、法律方法、法院组织与思维方式。传统方案先分大陆法与普通法，再细分罗马法族与日耳曼法族，北欧常被单列。分类具有认知价值，但它是理想类型而非严格封装。Siems 强调要避免过度强调差异、过度强调共性与忽视混合体三种偏向，并警惕把法律家族标签当作理解法律的唯一工具。路易斯安那、魁北克等混合体系表明，法律地图的边界往往是历史接触的产物，分類应当保持开放。", "furtherThinking": "1. 如果让你为『法律思维方式』设计可操作的分类指标，你会选择哪些？这些指标能区分法国法与德国法吗？\n2. 混合体系的存在，是分类方案的失败，还是提醒我们分类只是工具？请论证。\n3. 经济学家的『法律起源理论』把法律传统当作解释变量，这种做法与法学家的法律家族研究有何得失？"}, "en": "The Classification of Legal Systems", "level": "core", "tags": "法律家族, 法律传统, 混合体系, 法律起源", "source": "Siems, Comparative Law, ch.3, ch.4；Zweigert & Kötz, Introduction to Comparative Law, Part One", "id": "S2M4K3"}, "S2M4K4": {"title": "法律移植", "EN": "Legal Transplants", "LEVEL": "core", "TAGS": "法律移植, 法律借用, Watson, Legrand, 法律刺激物", "TERMS": "法律移植（Legal Transplant）::把一国或一法域的法律规则、制度或理念引入另一法律体系的过程；法律借用（Legal Borrowing）::移植的另一种说法，强调主动采纳外国法；输入的法（Law in Context）::需要结合社会语境理解的法律；法律刺激物（Legal Irritant）::Teubner 用语，指外来规则进入本土体系后引发的扰动；法律移植的不可能性（Impossibility of Legal Transplants）::Legrand 的主张，认为规则在移植中必然因解释而改变；合法性生成型移植（Legitimacy-generating Transplant）::为获取声望或现代性象征而采纳外国法的移植", "SOURCE": "Siems, Comparative Law, ch.8；Watson, Legal Transplants；Legrand 相关论文", "terms": [{"term": "法律移植（Legal Transplant）", "def": "把一国或一法域的法律规则、制度或理念引入另一法律体系的过程"}, {"term": "法律借用（Legal Borrowing）", "def": "移植的另一种说法，强调主动采纳外国法"}, {"term": "输入的法（Law in Context）", "def": "需要结合社会语境理解的法律"}, {"term": "法律刺激物（Legal Irritant）", "def": "Teubner 用语，指外来规则进入本土体系后引发的扰动"}, {"term": "法律移植的不可能性（Impossibility of Legal Transplants）", "def": "Legrand 的主张，认为规则在移植中必然因解释而改变"}, {"term": "合法性生成型移植（Legitimacy-generating Transplant）", "def": "为获取声望或现代性象征而采纳外国法的移植"}], "sections": {"coreQuestion": "2005 年，中国公司法引入股东代表诉讼（derivative action）制度，其范本在很大程度上来自美国法。一家公司的董事损害公司利益时，股东可以代表公司起诉——这条规则为何会被引入？美国是否参与其中？它在中国真的能运作吗？这些正是 Siems 用来开启『法律移植』一章的提问。法律移植是比较法中最富争议的话题之一：有人视之为法律进步的捷径，有人认为它注定失败甚至有害。本节梳理移植的动机、机制与理论争论，并尝试给出平衡的评估。", "definition": "法律移植（legal transplant）指把一国或一法域的法律规则、制度或理念引入另一法律体系的过程，又称法律借用（legal borrowing）。Siems 指出，这一概念由 Alan Watson 在二十世纪七十年代系统提出（其著作初版于 1971 年），但类似的思考可追溯更早——边沁在 1782 年就思考过『移植法律』。\n\n移植的对象并不限于规则条文本身，还包括法律制度与结构。Siems 区分移植的动机与『如何运作』两类问题：前者追问为什么引入，后者追问引入后是否以及如何生效。按动机可分：为获取实际效益的成本节约型移植；为获取声望或现代性象征的合法性生成型移植（legitimacy-generating transplant）；由特定利益集团推动的企业家型移植（entrepreneurial transplant）；以及旨在降低制度间交易成本的移植。这一分类说明，移植未必是『择优录用』的理性过程。", "history": "法律移植的历史几乎与法律史本身一样古老。Siems 强调，全球化趋势并非二十世纪才有；罗马法的继受就是一场大规模移植——大量大陆国家的私法建立在罗马法的继受之上。近代殖民扩张把欧洲法律带到亚洲、非洲与美洲，既传播了制度，也制造了混合体系。二十世纪以后，人权法的全球化、区域一体化（如欧盟）与发展援助中的制度输出，使移植呈现出新的规模与形式。中国 2005 年公司法引入美国式股东代表诉讼，正是这一长期历史中的当代案例。", "principle": "理解移植是否『有效』，需先厘清『有效』的含义。Siems 指出，『运作』(work) 一词并不清晰：它是指移植的规则像在母国一样运作，还是指得到良好执行，抑或指契合输入国的社会需求？这一定义难题，是各方争论的根源之一。\n\n从机制上看，移植要经历『选择—引入—实施—适应』几个环节。选择阶段涉及动机（效益、合法性、交易成本）；引入阶段涉及文本与制度的搬运；实施阶段受制于执法能力、司法文化与利益结构；适应阶段则可能出现本土化改造。Siems 强调，法律与社会、经济、文化、政治过程之间存在互补性(complementarities)，因此脱离语境的复制往往难以奏效；但『不适应』有时是刻意的——移植的目的可能恰恰是改变既有社会。\n\n因此 Siems 主张把批评的锋芒对准『盲目照搬』(blind borrowing)，而非『反思性的域外学习』(reflective learning from abroad)。他援引 Rubin 的说法：『从外国法里能借来的很少，能学到的很多』(little can be borrowed, but much can be learned from foreign law)。", "viewpoints": "移植理论围绕 Watson 与 Legrand 形成两座高峰。\n\nAlan Watson 被视为法律移植概念的奠基人。作为法律史家与罗马法学者，他从罗马法继受中得出洞见：私法事务通常不为政府所关心，而交由法律专家处理，因此其规则与概念『能够在不与任何特定民族、时期或地点保持紧密联系的情况下存续』。他有一句名言：『借用，哪怕是不假思索的借用，才是法律游戏的名称』(borrowing, even mindless, is the name of the legal game)。基于此，他对移植持乐观态度。Markesinis 等实用主义比较法学者也支持加强借鉴。\n\nPierre Legrand 则代表怀疑立场。他反对『法律只是文本中的词』，主张『意义是规则被解释者适用的函数』；解释总是主观的，受制于特定国家的文化与心智。由此他提出『法律移植的不可能性』：规则在跨越体系时必然改变——『随着对规则理解的改变，规则的意义改变；随着意义的改变，规则本身改变』。他借 Latour 的话说，不存在『不变形的运输』(transportation without transformation)。", "comparison": "把各派并排看，可定位四种立场。\n\n其一是 Watson 的乐观论：移植普遍且可行，规则可脱离语境存续。其二是 Legrand 的怀疑论：真正的移植不可能，表面的相似只是文字与修辞。其三是『有害论』：Teubner 称移植为『法律刺激物』(legal irritant)，认为外来规则会污染或扰乱本土法律秩序；另有观点强调法律与社会的互补性，认为复制会失败。其四是折中论：Siems 指出多数学者取中间立场——移植既非清晰的成功也非彻底的失败，而是『混合的图景』(a mixed picture)，关键是『尽可能好地选择与设计移植』。\n\nSiems 还提醒，Watson 与 Legrand 的分歧或许部分是术语之争：双方都承认立法者确实会互相抄文本，分歧在于是否把这种现象称为『移植』，以及是否应当鼓励借鉴。这一洞见有助于把争论从立场对立转向经验问题。", "debates": "移植研究最著名的争论，即 Watson—Legrand 之争。Watson 以法律史为据，认为私法规则具有可移植性，『即使一个查士丁尼时代的学生被送到二十世纪，也会对现代欧洲民法典很少有惊奇』。Legrand 则从解释学与后现代视角反击：规则的意义由解释者在具体文化中建构，因此跨体系的『同一规则』只是幻觉；Watson 所举的罗马法与后世民法典的相似，在他看来是『无意义的、表面的、纯修辞的』。\n\nSiems 的评估是：两种极端都走了太远。今天不存在『纯粹的法律体系』，所有体系都在吸收世界各地的观念，因此对外来影响一概怀疑是夸大；但同时，移植确实需要考虑输入国的不同环境。更稳妥的表述是反对盲目照搬，而肯定反思性学习。Siems 还以 Galanter 的比喻作结：法律像语言，能够吸收外来影响，同时『保留自身独特的结构与风味』；Arvind 则以葡萄藤嫁接作比——移植的效果取决于土壤与栽培。", "case": "中国 2005 年公司法引入股东代表诉讼是 Siems 全章的引子。该制度允许股东在公司怠于追究董事责任时代表公司起诉，规则『在很大程度上以美国法为模型』。Siems 据此提出一连串问题：中国为何这样做？美国是否介入？这条外来规则在中国是否真正发挥作用？这是否为法律改革的常态，又是否值得推荐？\n\n他进一步指出，移植、趋同与发展之间的关系是『典型但非必然』的：中国公司法与美国法的相似可被视为趋同，引入规则也可能意在刺激经济发展，但三者之间并无必然因果。这一案例把抽象争论落到了具体制度上。", "caseAnalysis": "就股东代表诉讼而言，事实是：中国在 2005 年修订公司法时纳入了这一源自美国的制度。争议焦点在于：外国规则是否以及在何种意义上在中国『运作』。 optimistic 视角会关注移植带来的制度收益——为股东提供救济、完善公司治理；怀疑视角则追问：在缺乏相应司法传统、律师激励与诉讼文化的环境中，条文能否转化为实践。\n\nSiems 的分析框架提示，回答不能停留在『成功/失败』二元：应分别考察文本是否被采纳、执行是否有效、是否契合社会需求，以及移植是否服务于改变社会的刻意目标。这个案例的理论意义在于：它把 Watson 与 Legrand 的抽象分歧转化为可经验研究的问题——移植的效果因法律领域和国家而异，因而在公司法这样的领域，功能性的借鉴与本土的适应往往同时发生。", "summary": "法律移植是把外国的规则、制度或理念引入本国体系的过程，动机多样，包括效益、合法性、交易成本与集团利益。理论上，Watson 主张移植普遍可行，规则可脱离语境存续；Legrand 主张移植不可能，因为意义随解释而改变；Teubner 等则强调其扰乱效应。Siems 综合各方，主张避免极端：不存在纯粹的法律体系，盲目照搬与一概怀疑都不可取，关键在于结合语境审慎选择与设计移植。中国 2005 年公司法的案例说明，移植、趋同与发展之间关系典型但非必然，效果须分文本、执行与契合度分别评估。", "furtherThinking": "1. 若一项移植规则在输入国长期『不起作用』，这能否证明 Legrand 的『不可能性』命题？还需要排除哪些因素？\n2. 『盲目照搬』与『反思性学习』的界限在哪里？请为一个引入外国制度的发展中国家设计评估清单。\n3. 知识产权、公司法等领域的移植，与刑法、家庭法的移植，成功率是否不同？为什么？"}, "en": "Legal Transplants", "level": "core", "tags": "法律移植, 法律借用, Watson, Legrand, 法律刺激物", "source": "Siems, Comparative Law, ch.8；Watson, Legal Transplants；Legrand 相关论文", "id": "S2M4K4"}, "S2M4K5": {"title": "法律趋同与法律分化", "EN": "Legal Convergence and Legal Divergence", "LEVEL": "debate", "TAGS": "法律趋同, 法律分化, 西方化, 法律移植, 全球化", "TERMS": "法律趋同（Convergence of Laws）::不同法律体系的法律现象随时间变得更加相似的趋势；法律分化（Legal Divergence）::法律体系之间差异扩大或维持的趋势；协调/统一（Harmonisation）::以刻意规划推动法律规则统一的过程；功能趋同（Functional Convergence）::不同法律规则产生可比效果而形成的趋同；形式趋同（Formal Convergence）::法律规则文本趋于一致；西方化（Westernisation）::非西方法律体系采纳西方法律模式的现象；区域化（Regionalisation）::在区域层面形成共同法律规则的过程；跨国化（Transnationalisation）::超越国家框架的私法规则形成过程", "SOURCE": "Siems, Comparative Law, ch.9 (Fading state borders)；ch.3, ch.8", "terms": [{"term": "法律趋同（Convergence of Laws）", "def": "不同法律体系的法律现象随时间变得更加相似的趋势"}, {"term": "法律分化（Legal Divergence）", "def": "法律体系之间差异扩大或维持的趋势"}, {"term": "协调/统一（Harmonisation）", "def": "以刻意规划推动法律规则统一的过程"}, {"term": "功能趋同（Functional Convergence）", "def": "不同法律规则产生可比效果而形成的趋同"}, {"term": "形式趋同（Formal Convergence）", "def": "法律规则文本趋于一致"}, {"term": "西方化（Westernisation）", "def": "非西方法律体系采纳西方法律模式的现象"}, {"term": "区域化（Regionalisation）", "def": "在区域层面形成共同法律规则的过程"}, {"term": "跨国化（Transnationalisation）", "def": "超越国家框架的私法规则形成过程"}], "sections": {"coreQuestion": "全球化究竟让各国的法律越来越像，还是越来越不同？一方面，国际人权条约、区域一体化（如欧盟）、跨国商事规则似乎让各国法律彼此靠近；另一方面，法律移植的失败、本土文化的抵抗、各国制度路径的依赖又不断制造差异。Siems 把这一议题放在『 fading state borders 』（国家边界的消逝）的框架下讨论，并提醒一个关键的方法论警告：法律规则的相似，可能是真实的全球现象，也可能主要是知识分子的建构。本节要厘清趋同与分化的概念、类型、动力与反向力量，并对『西方化』命题保持批判的距离。", "definition": "法律趋同（convergence of laws）指不同法律体系的法律现象『变得更加相似』的趋势。Siems 特别指出，这个词并不意味它们会变得完全相同，也不意味着我们能绝对确定地预测某些法律变化一定会发生；它的价值在于帮助我们理解塑造法律发展的各种力量。\n\n与之相对，法律分化（divergence）指法律体系之间差异扩大或维持的趋势。二者与法律移植（legal transplants）和协调/统一（harmonisation）相关但不同：移植可能促成趋同，也可能造成分化——例如若多数国家原本规则相似，其中一半转而移植某个『异类』国家的规则，全球反而会更分化；趋同也可在没有移植的情况下发生，例如各国合作解决某个尚无先例的社会问题。\n\n在术语上，有观点把协调（harmonisation）视为刻意的过程，把趋同视为自发演化的结果；但更常见的用法是把趋同作为更宽泛的术语，涵盖以刻意统一为目标的协调与『自然的/演化的』趋同两种类型。", "history": "趋同讨论的兴起与二十世纪末的全球化浪潮同步。Siems 把相关现象放在三重视角下：法律移植（第八章）、国家边界消逝下的趋同、区域化与跨国化（第九章），以及法律与发展（第十章）。冷战结束后，民主制度与法治理念扩散，宪法与国家治理出现明显趋同；欧盟的一体化把区域法律统一推向前台；跨国商事惯例、国际标准合同与商事规则（如 UNIDROIT 原则）形成超越国家的规则层。与此同时，九一一之后的安全立法、各国对金融危机的不同应对，以及民粹主义回潮，又展示了分化与反向运动的存在。", "principle": "理解趋同，关键在于区分类型与动力。\n\n第一，趋同的类型学。Siems 列出了多种趋同：政治学中的 Colin Hay 区分输入、范式、政策、合法性—修辞、结果与过程趋同；公司法文献则区分形式趋同（formal convergence，规则文本一致）、功能趋同（functional convergence，产生可比效果）、契约趋同（contractual convergence，通过合同安排达到等效）、混合趋同（hybrid convergence，企业迁移注册地）、规范趋同（normative convergence，法外规范趋同）与制度趋同（institutional convergence，企业结构事实上的相似）。Ronald Gilson 主张功能趋同比形式趋同更可能，因为障碍太多而问题相似。\n\n第二，趋同的动力。Siems 在表中列出推动趋同的力量：经济一体化与竞争压力、国际组织与条约、跨国公司与法律实务的国际化、法律职业共同体的知识传播，以及问题解决逻辑的相似——各地面对相似的问题，容易找到相似的答案。\n\n第三，分化的反向力量。路径依赖、本土法律文化、既有制度的互补性、国家主权对法律统一的抵制，以及移植的失败，都会维持或扩大差异。Siems 特别指出，法律与发展领域的批评者认为，外来法律往往『不起作用』(law does not work)，自上而下的方法与脱离语境的西方法可能适得其反。", "viewpoints": "关于趋同是否真实、是否可取，学界形成不同立场。\n\n乐观立场认为，经济与制度的竞争会趋向『优者胜出』(race to the top)，法律规则在跨国互动中自然趋同；宪法领域的民主与法治扩散、公司法领域的股东保护趋同是常见证据。Siems 提到，有研究显示宪法趋同表现为『缓慢而稳定』的民主形式与最低限度法治理解的传播，违宪审查制度日益被接受。\n\n怀疑立场则指出，许多『趋同』只是表面的：规则文本相似，但执行与效果差异巨大；Charny 所谓的制度趋同、Milhaupt 的规范趋同，说明趋同可能发生在正式法律之外。同时，趋同也可能意味着美国化或西方化，引发对法律多样性与主权的担忧。\n\nSiems 的立场是审慎的折中：他既承认趋同在某些领域确实发生，又强调『是否趋同』往往得不到简单的『是/否』答案，因为答案取决于我们考察的是规则文本、实际运作还是制度结构。", "comparison": "趋同可与法律移植、协调、区域化、跨国化对照。\n\n与法律移植相比：移植是单向的『输入』，趋同是多向的『靠近』；移植是趋同的可能机制之一，但如前所述，移植也可能导致分化。\n\n与协调（harmonisation）相比：协调是有意的制度设计（如欧盟指令），趋同则可能是无意的演化结果；前者如立法者主动统一规则，后者如各国面对相似经济压力而独立采纳相似制度。\n\n与区域化、跨国化相比：区域化是在区域层面形成共同规则（欧盟是典型），跨国化是超越国家的私法规则形成（如跨国商事惯例）。Siems 把这些视为『趋同、区域化、跨国化』三种相近但不同的现象，共同构成国家边界消逝的主题。", "debates": "趋同讨论中最核心的争论，是『趋同还是分化』以及『规范性还是实证性』。\n\n实证层面的争论是：法律到底是否在趋同？支持者列举宪法民主化、股东保护指数上升、公司法的西方化曲线等证据；反对者指出，正式规则的相似不代表实践相似，各国在执法、司法与合规上的差异依然巨大，甚至『趋同』可能只是观察者用同一框架投射的结果——这正是 Siems 反复警告的『把共同性当作知识分子建构』的风险。\n\n规范层面的争论是：趋同是否可取？支持者认为趋同降低交易成本、促进合作与法治；批评者担心趋同等于西方化乃至美国化，抹平有价值的法律多样性，削弱国家主权与民主问责。Siems 把这一争论称为『讨论：规范性与实证性』(discussion: normative and positive)，强调必须把『是否正在趋同』的事实判断与『是否应当趋同』的价值判断分开。\n\n值得注意的是，Siems 明确反对把趋势写成规律：趋同不意味着完全相同，也不意味着可以绝对预测。这种谨慎的表述，本身就是对过度简单化的抵制。", "case": "公司法是趋同研究最丰富的领域之一。Siems 指出，公司法文献识别出多种趋同：功能趋同、契约趋同、混合趋同等，并讨论股东保护趋同的量化研究。图表中曾展示中东欧国家（捷克、拉脱维亚、斯洛文尼亚）股东保护的『西方化』曲线，显示这些国家在转型过程中逐步采纳西方式的股东保护规则。\n\n另一个例子是宪法趋同：Siems 引述的概括表明，民主形式、最低限度的法治理解、宪法作为根本法的观念、以及对立法行为进行违宪审查的制度，都在全球范围内缓慢而稳定地扩散。然而他同时强调，这种扩散伴随大量变异，并非整齐划一。", "caseAnalysis": "以中东欧股东保护的『西方化』为例，事实是：转型国家在私有化与资本市场建设中，大量借鉴了西方式的公司法与证券监管规则，量化指标显示其股东保护水平在一段时间内明显向西方靠拢。争议焦点在于：这种靠拢是真实的功能趋同，还是仅仅形式上的文本复制？\n\n从功能趋同视角看，若规则确实改善了投资者保护、降低了融资成本，那么即便路径不同，也可视为趋同。从怀疑视角看，若规则只存在于纸面，执行与司法并未跟上，则只是『形式趋同』(formal convergence)。Siems 的研究进一步显示，趋同曲线可能出现停滞甚至逆转，说明趋同不是单向不可逆的过程。\n\n这个案例的理论意义在于：它把『趋同还是分化』的抽象争论转化为可测量、可比较的经验问题，同时提醒我们区分规则文本、实际执行与制度效果三个层次。它也呼应了全书的主题——比较法必须把法律规则放回其政治经济语境中理解。", "summary": "法律趋同指法律现象变得更相似，但并非完全相同，也不意味着可以绝对预测；法律分化则是差异的维持或扩大。趋同与移植、协调相关但不同：移植可能促成趋同也可能造成分化，协调是有意的统一而趋同更宽泛。趋同有多种类型——形式、功能、契约、混合、规范、制度趋同；其动力包括经济一体化、国际组织、法律职业传播与问题解决逻辑的相似，反向力量则包括路径依赖、法律文化、制度互补性与主权抵制。规范层面须区分『是否趋同』的事实判断与『是否应当趋同』的价值判断。Siems 的立场是审慎折中：趋同在某些领域真实发生，但答案往往不是简单的『是或否』，且须警惕把相似当作知识分子的建构。", "furtherThinking": "1. 如果各国公司法规则文本越来越像，但执行水平差异巨大，这算『趋同』吗？应采用哪种趋同概念来判断？\n2. 趋同若意味着西方化或美国化，是否必然损害法律多样性？请举一个可能『趋同而不西方化』的领域。\n3. 如何区分『真实的全球趋同』与『知识分子用同一框架投射出的相似』？请设计一个可操作的检验方法。"}, "en": "Legal Convergence and Legal Divergence", "level": "debate", "tags": "法律趋同, 法律分化, 西方化, 法律移植, 全球化", "source": "Siems, Comparative Law, ch.9 (Fading state borders)；ch.3, ch.8", "id": "S2M4K5"}, "S2M5K1": {"title": "英美普通法系", "EN": "The Anglo-American Common Law System", "LEVEL": "core", "TAGS": "普通法系, 英格兰法, 判例法, 对抗制, 衡平法", "TERMS": "普通法（Common Law）::源于英格兰、以司法判例为基础的法律传统；令状（Writ）::中世纪英格兰开启诉讼的标准化司法文书；衡平法（Equity）::由大法官发展、用以补救普通法僵化的法律体系；遵循先例（Stare Decisis）::法院受先前判决约束的原则；判决理由（Ratio Decidendi）::判决中具有约束力的核心法律理由；附带意见（Obiter Dicta）::判决中不具有约束力的附带表述；对抗制（Adversarial System）::由当事人主导举证与质证的程序模式", "SOURCE": "Siems, Comparative Law, ch.3；ch.2", "terms": [{"term": "普通法（Common Law）", "def": "源于英格兰、以司法判例为基础的法律传统"}, {"term": "令状（Writ）", "def": "中世纪英格兰开启诉讼的标准化司法文书"}, {"term": "衡平法（Equity）", "def": "由大法官发展、用以补救普通法僵化的法律体系"}, {"term": "遵循先例（Stare Decisis）", "def": "法院受先前判决约束的原则"}, {"term": "判决理由（Ratio Decidendi）", "def": "判决中具有约束力的核心法律理由"}, {"term": "附带意见（Obiter Dicta）", "def": "判决中不具有约束力的附带表述"}, {"term": "对抗制（Adversarial System）", "def": "由当事人主导举证与质证的程序模式"}], "sections": {"coreQuestion": "提到普通法系，很多人脑海里浮现的是『英美法』三个字，仿佛英格兰与美国的法律是一回事。Siems 却反复提醒，『英格兰法与美国法之间也可能存在深刻分歧』，甚至从一个欧洲视角看，『英格兰的司法体系更像大陆体系，而不像美国』。那么，普通法系究竟有什么共同内核，能把英格兰、美国、澳大利亚、印度等法域连在一起？它又为何内部差异巨大？本节先勾勒普通法系的历史起源与共同特征，再着重区分英格兰法与美国法，避免把两者混为一谈。", "definition": "普通法（Common Law）作为法系概念，指以英格兰法律为基础、经由殖民扩散而形成的法律传统；Siems 指出，普通法国家是那些『法律以英格兰法为基础』的体系。这一术语本身有多重含义：在法系层面指普通法家族；在一国内部，可指与衡平法（equity）相对的普通法，也可指与制定法相对的判例法，还可指与地方法相对的通行法律。\n\n普通法系的核心制度包括：以判例为主要法律渊源、遵循先例（stare decisis）原则、对抗制（adversarial system）诉讼程序、陪审团（jury）的传统、以及法官通过判决发展法律的『自下而上』造法方式。Siems 强调，普通法的这些要素彼此关联，形成一个相对连贯的制度『束』(bundle)。", "history": "普通法的起源相对清晰。1066 年诺曼征服后，威廉一世及后继者以封建土地制度与新的法院体系控制国家、统一法律。法律建立在标准化的诉讼形式——令状（writs）之上，法院以伦敦为中心，巡回法官到各地审理，事实认定交由陪审团，以利王室司法在地方获得接受。十七世纪，詹姆斯一世试图凭借封建权力主张全国土地所有权，议会介入，由此形成更强的财产权保护与更独立的司法。法官逐渐撰写详尽的判决，把令状的程序性 origins 转化为实体规则。Maitland 的名言概括其后果：『我们埋葬了诉讼形式，它们却仍在坟墓中统治我们。』殖民使这一传统传播到美国、澳大利亚、印度等地。", "principle": "普通法的运作逻辑可从三个层面理解。\n\n第一，判例与先例。普通法的法律主要寓于判决之中。判决不仅解决个案，还构成未来案件的先例。法官须区分案件事实的差异，并区分判决理由（ratio decidendi，有约束力）与附带意见（obiter dicta，无约束力）。Siems 指出，这一过程既保证一致性与可预测性，又使法律能随情势变迁而调适——『从个案到个案的推理』(reasoning from case to case) 是其精髓。\n\n第二，法官的角色。普通法的法院不只是解决个别冲突，更是『自下而上』发展法律的手段。普通法是反应性的（reactive），它『等待解释的契机』。法官愿意在社会争议问题上展现司法创造性，并对经济学等社会科学论证相对开放，被誉为具有『市场智慧』(market-wise)。\n\n第三，对抗制与程序。普通法审判传统上是单一的口头事件，集中呈现全部证据，这是陪审团频繁使用的结果。当事人及其律师在诉讼中积极主动，承担原本由法院完成的任务；法官相对中立、被动，类似『中立的裁判』(neutral umpire) 或『帮助争吵双方的邻居』。这解释了为何普通法特别重视审前准备——美国 1938 年引入的广泛证据开示（discovery）规则即其极端体现。", "viewpoints": "关于普通法的本质，不同学者有不同侧重。Siems 综合主流观点指出，普通法法官以归纳式、论辩式、实用主义的推理风格著称；其判决详尽叙述事实，能让人看到『法官审案时脑中真正想的是什么』。Lord Macmillan 则提醒，『基于法律一致性的论证容易误导，因为普通法是适应人类生活多样性的实用法典』。\n\nSiems 同时强调普通法内部的连贯性：法院结构、职业法官制、陪审团、民事程序形式、法官角色、裁判方法与判决风格彼此相连，构成一个难以拆分的整体。但这一『连贯』判断在英格兰与美国之间需要打折——两者差异显著，下文分解。", "comparison": "普通法系常与大陆法系对照。在渊源上，普通法以判例为主、制定法处次要地位（虽日益重要），大陆法以法典为主；在推理上，普通法归纳、类比、注重个案事实，大陆法演绎、三段论、注重抽象规则；在法官角色上，普通法法官独立造法，大陆法法官更像法律适用者；在程序上，普通法对抗制、口头、集中，大陆法更偏书面、分阶段、法官主导。Siems 提醒，这种对照是『理想类型』，现实中存在趋同：两大法系都使用混合的论证方式，法官与学者都扮演交互角色。", "debates": "普通法系内部的经典争论，是『英格兰法与美国法是否根本相似』。Siems 指出，正如英格兰与美国是『被共同语言分开的两个民族』，其法律体系也是『被普通法分开的』。一派强调美国的混合性：美国拒绝了许多普通法原则、采纳了大陆法要素（如 Field 的民事诉讼法典、Llewellyn 主导的 UCC）。另一派强调『美国例外论』：Kagan 认为『美国的法律方式』是一种严格的『对抗性法治主义』(adversarial legalism)，与所有其他体系都不同，包括英格兰。\n\n从欧洲视角看，差异尤为明显：美国保留陪审团、广泛的审前开示、当事人主导的对抗制、胜者亦自付费用、风险代理（contingency fee）、集体诉讼（class actions），形成『诉讼人激进主义』(litigant activism)；英格兰则有败诉方付费规则、更积极的法官案件管理、更同质保守的司法。Siems 的结论是：把英格兰法与美国法预设为根本相似，本身可能误导。", "case": "证据开示（discovery）规则是英美差异的绝佳例证。在美国，由于陪审团审判需要『单一事件』式集中审理，双方在审前负有广泛向对方披露可能证据的义务；这套规则直到 1938 年才引入。而英格兰版的普通法中，审前开示的重要性远低于美国。Siems 指出，在大陆法国家，证据开示形式更有限，且不限于审前阶段，它们更多依靠举证责任转移或实体法规则（如严格责任）来应对信息不对称。\n\n另一个例子是法官遴选：美国强调法官选任的民主正当性，通过选举或政治任命，政治、社会与道德价值常起关键作用；英格兰则重视专业资格，从出庭律师（barrister）到 recorder 再到法官，形成更同质、更少政治化的职业晋升路径。", "caseAnalysis": "以陪审团为例：事实是，陪审团曾是一切普通法国家民事与刑事审判事实认定的核心；今天，民事陪审团在多数普通法国家已消失，美国是显著例外——陪审团被视为美国文化与民主的关键要素。争议焦点是：陪审团是否仍是普通法系的共同特征？Siems 指出，即便在已废除陪审团的地方，其历史影响仍在：想象一个『幽灵陪审团』(phantom jury) 有助于理解普通法审判的核心特征，如口头原则与审判作为单一事件。\n\n这一案例的理论意义在于：它展示了如何识别法律传统的『结构性遗产』——一项制度即便在形式上消亡，仍塑造着程序的形态。它也再次提醒：普通法系的共同性更多体现在方法论与思维方式上，而非每一项具体制度的现存状态；英格兰与美国在这一制度上的分野，说明法系内部的多样性不容抹杀。", "summary": "普通法系是以英格兰法为基础、经殖民扩散形成的法律传统，核心特征包括判例渊源、遵循先例、对抗制、陪审团传统与法官造法。其历史源于 1066 年诺曼征服后的令状与王室司法，经 Maitland 所谓『诉讼形式的统治』塑造而成。判例中区分判决理由与附带意见，法官以归纳、实用方式发展法律。然而 Siems 强调，普通法系远非同质：英格兰与美国在陪审团、证据开示、法官遴选、违宪审查、费用规则等方面差异显著，甚至出现『英格兰更像大陆、美国才是例外』的判断。理解普通法系，既要把握共同内核，也要警惕把英美混为一谈。", "furtherThinking": "1. 普通法系的共同性主要体现在方法论还是具体制度上？请各举一例说明。\n2. 『幽灵陪审团』这一说法对理解大陆法与普通法程序差异有何启发？\n3. 若要把『对抗性法治主义』输出到一个大陆法国家，可能遇到哪些制度文化上的阻力？"}, "en": "The Anglo-American Common Law System", "level": "core", "tags": "普通法系, 英格兰法, 判例法, 对抗制, 衡平法", "source": "Siems, Comparative Law, ch.3；ch.2", "id": "S2M5K1"}, "S2M5K2": {"title": "欧洲大陆法系", "EN": "The European Civil Law System", "LEVEL": "core", "TAGS": "大陆法系, 法典化, 罗马法, 成文法, 职权主义", "TERMS": "大陆法（Civil Law）::以罗马法为基础、以法典为主要渊源的欧洲法律传统；法典化（Codification）::把法律编纂为系统法典的运动；国法大全（Corpus Juris Civilis）::查士丁尼主持编纂的罗马法汇编；共同法（Ius Commune）::中世纪欧洲超越国界的罗马法共同传统；三段论（Syllogism）::大陆法裁判的大前提—小前提—结论推理模式；涵摄（Subsumption）::把具体事实归入抽象法律规则的操作；职权主义（Inquisitorial）::法官在查明事实中发挥主动作用的程序模式", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "大陆法（Civil Law）", "def": "以罗马法为基础、以法典为主要渊源的欧洲法律传统"}, {"term": "法典化（Codification）", "def": "把法律编纂为系统法典的运动"}, {"term": "国法大全（Corpus Juris Civilis）", "def": "查士丁尼主持编纂的罗马法汇编"}, {"term": "共同法（Ius Commune）", "def": "中世纪欧洲超越国界的罗马法共同传统"}, {"term": "三段论（Syllogism）", "def": "大陆法裁判的大前提—小前提—结论推理模式"}, {"term": "涵摄（Subsumption）", "def": "把具体事实归入抽象法律规则的操作"}, {"term": "职权主义（Inquisitorial）", "def": "法官在查明事实中发挥主动作用的程序模式"}], "sections": {"coreQuestion": "大陆法系常被概括为『成文法系』，但这一说法容易遮蔽更多东西。为什么同属大陆法，法国民民法典追求『像圣经一样简单』，德国民法典却以抽象、概念化著称？为什么大陆法法官在解释法律时有相当 discretion，人们却仍说他们是『法律适用者』？Siems 提醒，大陆法并非罗马法的现代翻版，内部差异巨大。本节考察大陆法系的历史根基、共同特征与内部多样性，重点比较法国法与德国法，并纠正对大陆法的几种刻板印象。", "definition": "大陆法（Civil Law）作为法系概念，指受欧洲大陆罗马法传统影响、以法典化为主要特征的法律体系；Siems 指出，大陆法国家是『受欧洲大陆传统影响』的体系。需注意 civil law 一词的多义：在法系层面指大陆法家族；在一国内部，可指与刑法、公法相对的私法领域（如合同法、侵权法）。\n\n大陆法系的共同特征包括：以系统性法典为主要法律渊源；法律思维偏演绎与概念化，强调规则的抽象与体系；法官被视为法律的适用者，以三段论方式裁判；诉讼程序偏书面与职权主义，法官在查明事实中较主动；法学教授（而非法官）在传统上影响巨大，故有『学者法』(learned law) 之称。Siems 强调，这些要素彼此关联，构成一个相互支撑的整体。", "history": "大陆法的根基是罗马法。公元六世纪，东罗马皇帝查士丁尼主持编纂《国法大全》(Corpus Juris Civilis, 533 AD)。十一世纪，罗马法在欧洲大陆复兴，即『继受』(reception)，形成超越国界的共同法（ius commune）。Siems 归纳继受的三个特征：大学推动罗马法传播，故大陆法被称为学者法；共同法超越国界、补充地方法；司法实施受国家严格控制以保证统一。十八、十九世纪民族国家兴起，各国把罗马法与地方法编纂为统一法典，1804 年法国民法典成为现代大陆法的象征，1900 年德国民法典则风格迥异。法典化既传播了大陆法，也造成大陆内部的分化。", "principle": "大陆法的运作逻辑可从四层理解。\n\n第一，法典的理想。大陆法法典承启蒙运动理念，追求清晰、连贯、系统、自足、完整地处理特定法律部门。Siems 指出，这一理想至今仍被立法者珍视——法国 1989 年设立最高法典化委员会（Commission Supérieure de Codification），推动新法典的制定与旧法典的重构。\n\n第二，法律的解释。法国民法典曾规定『法官不得以一般性与规范性规定裁判案件』，旨在防止法官造法、维护权力分立。但十九、二十世纪的事实证明，狭隘的字面解释不可行。今天大陆法常用解释方法包括：探求立法者意图的启示法（exegetical method），以及在条文含糊、立法意图不明时依据法律客观目的的目的论方法（teleological method）。瑞士民法典更明确授权：法典未提供可适用规定时，法官依习惯法裁判，再依其作为立法者会确立的规则裁判。\n\n第三，法官的推理。大陆法法官被认为以三段论（syllogism）推理：先识别法律规则及其解释，再把事实涵摄（subsume）于规则之下，最后适用法律后果。事实仅在关联到相关法律规则时才有意义。Pound 1921 年曾讽刺大陆法官如同『司法自动售货机』(judicial slot machine)——投入事实、吐出判决。Siems 指出，这种描述既可刻薄地批评为机械、无创造性，也可善意地理解为尊重立法者、理性且可预测地适用法律。\n\n第四，法学教授的角色。大陆法传统中学术影响深远：德国民法典被认为由潘德克顿学派写就，德国 2002 年民法典改革以教授报告为基础；教授撰写多卷本评注，形成『通说』(herrschende Lehre / la doctrine)，其地位几近实在法。", "viewpoints": "关于大陆法的本质，Siems 综合主流观点：大陆法法官在解释法律时有较大 discretion，但解释完成后『只是法律适用者』；法院组织强化这一取向——法官是公务员，处于等级化的职业晋升体系中，案件负荷繁重，使其聚焦于实施法律而非发展法律。Mirjan Damaska 把这种权威组织方式概括为一种等级制（vertical）理想，与普通法的协调制（horizontal）理想相对。\n\nSiems 同时提醒，这种『机械适用』的图景是漫画化的。真实情况更为复杂：大陆法通过一般条款（如善意原则）发展法律，法院在裁判中扮演积极角色。", "comparison": "大陆法系与普通法系的对照是经典议题。在渊源上，大陆法以法典为主、判例非渊源；普通法以判例为主。在推理上，大陆法演绎、抽象、重视体系；普通法归纳、类比、重视个案事实。在法官角色上，大陆法法官为职业官僚、法律适用者；普通法法官独立、造法者。在程序上，大陆法偏书面、职权、分阶段；普通法偏口头、对抗、集中。\n\n但 Siems 强调，这是理想类型。现实中出现趋同：大陆法法典不再是首要渊源，普通法进入『成文法时代』；两大法系在解释方法、判决风格上都使用混合论证。Zweigert 等人的功能主义比较正是在这种趋同背景下更有意义。", "debates": "大陆法研究的经典争论，是其内部是否同质。Siems 指出，现代大陆法国家可能有与罗马法恰好相反的规则（如允许实际履行）；欧洲各地早有不同『共同法』（droit commun、gemeine Recht、derecho común），并未因继受而消失；民族国家法典化又持续改造共同遗产。因此有观点认为，『法国法与德国法的差异可能一样大甚至大于法国法与英格兰法的差异』。\n\n在此基础上，多数分类区分大陆法内部的罗马法族（法国法族）与日耳曼法族（德国法族），并把北欧国家单列。Siems 的批判性结论是：大陆法是多样化的法律传统的集合，而非统一模本；把『大陆法』当作单一对象来分析，本身就可能误导。", "case": "法国法与德国法的差异是最好的例证。在民法典风格上，法国民法典以简明清晰著称，追求通俗易懂；德国民法典以概念化、体系化、教授化著称，有严密的抽象结构。在判决风格上，德国判决呈学术化风格，使用多级标题与条文链（Paragraphenkette），并频繁引用判例与学术著作；法国判决则以极简著称，往往只有几行、几乎不超过一页，传统上不引用先例与学术文献，最高法院（Cour de Cassation）的风格至今未变。\n\n在合同法上，两国也有差异：德国民法典第 280 条第 1 款通常要求过错，法国法则更常区分合同类型、仅在不可抗力时排除损害赔偿。Siems 指出，Lasser 认为法国判决的简洁并不代表缺乏政策考量——政策论证存在于报告法官的意见与总检察长的意见中，形成一种『二元划分』(bifurcation)。", "caseAnalysis": "以判决风格为例：事实是，德国判决详尽、结构严密、大量引用，法国判决极简、不引先例。争议焦点是：这种差异说明什么？表面看，德国法重视学术与先例、法国法排斥二者。但 Siems 提供更细的解释：法国判决的简短被辩护为提供清晰性，与民法典简明风格一致；Lasser 则指出，政策论证在法国以『二元划分』方式存在于判决之外的文本中。\n\n这一案例的理论意义在于：它揭示了『法律风格』背后的制度文化——德国的教授法传统与法国的议会至上、法官抑制传统。它也再次说明，大陆法内部差异显著，简单贴『大陆法』标签会遮蔽法德之间真实存在的不同。对比较法学习者而言，具体比较法域永远优于笼统的法系概括。", "summary": "大陆法系是以罗马法为基础、经继受与法典化形成的法律传统，核心特征包括法典化、演绎推理、法官作为法律适用者、职权主义程序与法学教授的深远影响。其精神可由三段论与涵摄概括，但实际的解释方法已发展出启示法、目的论方法等。Siems 强调大陆法并非罗马法的统一现代版本：法国民法典简明、德国民法典概念化；两国判决风格、合同规则差异显著；欧洲各地历史上存在多种共同法。多数分类因而区分罗马法族与日耳曼法族，并把北欧单列。理解大陆法，须在把握共同基因的同时，记住其内部的分化与趋同。", "furtherThinking": "1. 法国民法典的『简明』与德国民法典的『概念化』，各自反映了怎样的政治与学术背景？\n2. 大陆法法官既是『法律适用者』又通过一般条款发展法律，这两种角色如何共存？\n3. 随着普通法进入『成文法时代』、大陆法判例作用上升，两大法系的区别是否会最终消失？"}, "en": "The European Civil Law System", "level": "core", "tags": "大陆法系, 法典化, 罗马法, 成文法, 职权主义", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M5K2"}, "S2M5K3": {"title": "德国法律传统", "EN": "The German Legal Tradition", "LEVEL": "core", "TAGS": "德国法, 民法典, 潘德克顿学派, 概念法学, 教义学", "TERMS": "德国民法典（Bürgerliches Gesetzbuch, BGB）::1900 年生效的德国民法典，以概念化体系著称；潘德克顿学派（Pandectists）::十九世纪德国罗马法学者，主张以概念体系重构法律；概念法学（Begriffsjurisprudenz）::强调概念体系与逻辑演绎的法学方法；教义学（Dogmatik）::对现行法进行体系化解释与理论建构的学问；总则（Allgemeiner Teil）::民法典中统辖各编的抽象一般规则部分；法律行为（Rechtsgeschäft）::以意思表示为核心、旨在产生法律效果的行为；通说（Herrschende Lehre）::德国法学中被普遍接受的主流学说", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "德国民法典（Bürgerliches Gesetzbuch, BGB）", "def": "1900 年生效的德国民法典，以概念化体系著称"}, {"term": "潘德克顿学派（Pandectists）", "def": "十九世纪德国罗马法学者，主张以概念体系重构法律"}, {"term": "概念法学（Begriffsjurisprudenz）", "def": "强调概念体系与逻辑演绎的法学方法"}, {"term": "教义学（Dogmatik）", "def": "对现行法进行体系化解释与理论建构的学问"}, {"term": "总则（Allgemeiner Teil）", "def": "民法典中统辖各编的抽象一般规则部分"}, {"term": "法律行为（Rechtsgeschäft）", "def": "以意思表示为核心、旨在产生法律效果的行为"}, {"term": "通说（Herrschende Lehre）", "def": "德国法学中被普遍接受的主流学说"}], "sections": {"coreQuestion": "德国法在比较法地图上占据特殊地位：它与法国法同为大陆法的两大范本，却呈现出截然不同的气质。为什么德国民法典以抽象、概念化、教授化著称，而法国民法典简明通俗？为什么德国法学教授对法律的影响如此深远，甚至有人说教授『写就了』民法典？德国法的这些特征，如何在其民法典结构、司法推理与法学教育中体现？本节聚焦德国法律传统，理解其『概念—教义』性格的来龙去脉，同时留意 Siems 对德国法『例外论』的审慎态度。", "definition": "德国法律传统指以德国民法典（Bürgerliches Gesetzbuch, BGB）为核心、以概念化与教义学（Dogmatik）为特征的制度与思维传统。它在法律家族分类中属于大陆法的『日耳曼法族』(Germanic group)，与以法国民法典为范本的罗马法族相对。\n\n德国法的核心特征包括：高度体系化与抽象化的民法典结构；以概念法学（Begriffsjurisprudenz）为底蕴的法律思维；法学教授在立法与解释中的主导地位；通说（herrschende Lehre）几近于正式法源的地位；以及严谨、学术化的判决风格。Siems 指出，德国民法典 1900 年的风格『更具概念性与教授性』，与法国民法典形成鲜明对照。", "history": "德国法律传统的形成与十九世纪的历史语境密不可分。当时德意志尚未统一，罗马法在大学中作为共同法被讲授。以萨维尼（Friedrich Carl von Savigny）为代表的历史法学派强调法律是民族精神的产物，反对仓促法典化；但其后的潘德克顿学派（Pandectists）却致力于以罗马法材料构建严密的概念体系，被誉为『写就了』1900 年民法典。\n\nSiems 指出，潘德克顿学派是十九世纪德国的罗马法学家，他们『基本上写就了民法典』；德国 2002 年的民法典改革同样以教授报告为基础。大学教育在德国法律传统中居于核心地位——大学与实务教育对所有法律职业者统一，只有最优秀的毕业生才能成为法官，且法官年轻时即被任命，走上终身公务员生涯。这种『学者法』传统，使教授的学说对立法与司法都影响深远。", "principle": "德国法的运作逻辑可从四个层面理解。\n\n第一，法典的体系化结构。德国民法典采用『总则—分则』(Allgemeiner Teil / Besonderer Teil) 的抽象结构，把可普遍适用的规则（如法律行为、行为能力）提炼为总则，统辖合同、物权、亲属、继承等分则。这种『抽象—概括』的编纂技术，追求逻辑自洽与体系严密，与法国民法典按主题平铺的体例迥异。\n\n第二，概念法学的思维。德国法强调以概念建构与逻辑演绎处理法律问题。法律行为（Rechtsgeschäft）这一抽象概念，正是这一思维的产物——它以意思表示为核心，把合同、遗嘱等具体行为统合于一个一般理论之下。Siems 指出，德国法院在复杂案件中采用严格的逻辑方法，使用多级标题与条文链（Paragraphenkette），语言技术性很强。\n\n第三，教义学与通说。德国法学重视教义学（Dogmatik）——对现行法进行体系化解释与理论建构。教授撰写多卷本评注，对法典逐条释义。在这一过程中形成的通说（herrschende Lehre），虽非正式法源，却『几乎与实在法同等重要』。法院判决经常引用学术著作，德国法官甚至表示他们『确实查阅这些著作』并关注学者观点。\n\n第四，法官的角色。Siems 指出，大陆法法官在解释法律时有较大 discretion，但一旦解释完成便只是法律适用者；德国法官尤为如此。德国法院的组织强化这一定位：法官是职业公务员，在层级体系中晋升，案件负荷繁重，使其聚焦实施法律而非发展法律。Damaska 把这种权威组织方式概括为等级制（vertical）理想。", "viewpoints": "关于德国法的特征，Siems 综合学界看法：德国法律思维以学者法传统、概念化、教义化为显著标志；教授对立法与司法解释的影响在主要法系中尤为突出。与英格兰法官主导、法国立法者主导相比，德国可说是『教授主导』的格局。\n\n但 Siems 同时提醒，不应把德国法简化为『机械概念法学』。他引用批评观点指出，把大陆法官描述为『狭窄、机械、无创造性』并不准确；德国法通过一般条款（如善意原则 BGB §242）发展法律，法院在裁判中扮演积极角色。他更以 Zimmermann 的观察提醒：当今德国法与法国法一样，都是罗马法与本土传统共同的产物，而非罗马法的纯粹复制。", "comparison": "德国法与法国法同为大陆法范本，差异却十分显著。\n\n在法典风格上，德国民法典抽象、概念化、体系严密（含总则编），法国民法典简明、通俗、平铺直叙。在判决风格上，德国判决学术化、长篇、引用密集，法国判决极简、传统上不引先例与学说。在法学角色上，德国教授主导、通说影响巨大，法国学者也有影响（la doctrine）但法院风格不同。在合同规则上，德国民法典第 280 条第 1 款通常要求过错，法国法更常区分合同类型。\n\n两者与普通法系相比，又共享大陆法的基因：法典化、演绎推理、法官作为适用者、教授影响。Siems 把这些差异置于『多样性中的统一』框架下理解：法德既是大陆法核心，又各有独特传统。", "debates": "围绕德国法，一个经典争论是概念法学的得失。十九世纪的概念法学追求把法律构建为无漏洞的概念体系，相信通过逻辑演绎可从概念中推出一切答案。这一路径的批评者（如法律现实主义与利益法学）指责其脱离生活、机械僵化、掩盖价值判断。Siems 在书中转述了 Pound 的『司法自动售货机』讽刺，也引用 Kötz 的反思：即便在德国，法官也是在宽泛原则下运作，实务者最终仍须考察判例以预测疑难案件的裁判。\n\nSiems 的立场是审慎的：概念法学确有僵化风险，但德国法通过一般条款与教义学发展，展现出适应性；把德国法等同于『机械适用』是误解。这一争论也联系着更一般的议题——法律形式主义与法律现实主义之间的张力，这在第三阶段法理学中有更深入的讨论。", "case": "德国民法典第 242 条（善意履行）与第 311 条第 2 款（缔约过失）是展示德国法教义学精细化特征的恰当例子。第 242 条要求债务人依诚信原则履行给付，被视为民法典中的『一般条款』，赋予法官根据个案发展规则的余地。第 311 条第 2 款把缔约前的交往关系纳入债的关系，使善意原则适用于缔约过失责任（culpa in contrahendo）。\n\nSiems 指出，德国法中的善意原则并非道德说教，也不赋予法官无拘束的自由裁量；德国法院运用善意原则，是为了发展出可靠适用于个案的规则类别，而非在个案中用『更公平』的方案取代合同或法律的后果。这与普通法对善意的疑虑形成对照——Teubner 甚至把善意移植到普通法称为『法律刺激物』。", "caseAnalysis": "以缔约过失责任为例：事实是，德国民法典第 311 条第 2 款把缔约前关系纳入债的关系，使当事人在合同成立前也负有依善意行事的义务。争议焦点是：这种安排是否赋予法官过大的自由裁量、破坏合同自由与法的安定性？\n\n德国教义学的回答是：通过精细化的规则建构，把抽象原则转化为可预测的适用类别，从而兼顾个案公平与法的安定性。Siems 的比较研究进一步显示，法国以侵权法、荷兰以公平原则处理缔约阶段责任，功能上相近但教义路径不同；Common Core 项目研究三十个善意案例，结果有同有异，英格兰法『常常但并非总是』走自己的路。\n\n这一案例的理论意义在于：它展示了德国法教义学的核心能力——把抽象原则『操作化』为可靠规则；也展示了功能比较的必要性：不同法系以不同教义装置达成相近结果。", "summary": "德国法律传统以 1900 年民法典为核心，具有概念化、体系化、教义学与学者主导的特征。它在大陆法内部属于日耳曼法族，与法国法族相对。其形成得益于潘德克顿学派的概念建构与大学教授的深远影响，通说地位几近实在法。德国民法典的总则—分则结构、法律行为概念、条文链式判决，都体现了概念—教义思维。但 Siems 提醒，不应把德国法简化为机械概念法学：一般条款与教义学发展使其保持适应性；德国法同样是罗马法与本土传统的产物，与法国法、普通法既有区别也有趋同。", "furtherThinking": "1. 德国民法典的『总则—分则』结构体现了怎样的思维？它有哪些优点与风险？\n2. 如果说德国法是『教授主导』、英格兰法是『法官主导』、法国法是『立法者主导』，这种概括各自遮蔽了什么？\n3. 一般条款（如 BGB §242）如何在个案公平与法的安定性之间取得平衡？这对中国民法典解释有何启示？"}, "en": "The German Legal Tradition", "level": "core", "tags": "德国法, 民法典, 潘德克顿学派, 概念法学, 教义学", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M5K3"}, "S2M5K4": {"title": "法国法律传统", "EN": "The French Legal Tradition", "LEVEL": "core", "TAGS": "法国法, 拿破仑法典, 民法典, 行政法院, 判决风格", "TERMS": "法国民法典（Code Civil / Code Napoléon）::1804 年颁布、以简明清晰著称的法国民法典；拿破仑法典（Code Napoléon）::法国民法典的别称；最高行政法院（Conseil d'État）::法国最高行政法院，公法领域的最高裁判机关；最高法院（Cour de Cassation）::法国民刑领域的最高法院；二元划分（Bifurcation）::Lasser 用以描述法国政策论证与判决文本分离的概念；不可抗力（Force Majeure）::法国合同法中排除责任的事由", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "法国民法典（Code Civil / Code Napoléon）", "def": "1804 年颁布、以简明清晰著称的法国民法典"}, {"term": "拿破仑法典（Code Napoléon）", "def": "法国民法典的别称"}, {"term": "最高行政法院（Conseil d'État）", "def": "法国最高行政法院，公法领域的最高裁判机关"}, {"term": "最高法院（Cour de Cassation）", "def": "法国民刑领域的最高法院"}, {"term": "二元划分（Bifurcation）", "def": "Lasser 用以描述法国政策论证与判决文本分离的概念"}, {"term": "不可抗力（Force Majeure）", "def": "法国合同法中排除责任的事由"}], "sections": {"coreQuestion": "法国民法典被 Siems 称为『现代大陆法传统的象征』，其影响随拿破仑的征服与殖民扩散到世界各地。然而法国法呈现出一种有趣的张力：一方面，法典追求简明通俗，宣称『像圣经一样简单』；另一方面，法国法院的判决以极简、封闭著称，传统上不引用先例与学说。这种『简单』背后藏着怎样的制度逻辑？法国法与德国法同为大陆法范本，差异何在？本节聚焦法国法律传统，理解其民法典精神、法院组织与判决风格，并借助 Lasser 的『二元划分』理论破除对法国法的误解。", "definition": "法国法律传统指以 1804 年法国民法典（Code Civil，又称拿破仑法典 Code Napoléon）为核心、以简明清晰与议会立法至上为特征的制度与思维传统。在法律家族分类中，法国法属于大陆法的『罗马法族』(Romanist group)，是众多大陆法国家法典的范本。\n\n法国法的核心特征包括：简明通俗的法典编纂；议会至上的共和传统与对法官造法的警惕；民刑与行政分立的双轨法院体系，以最高行政法院（Conseil d'État）为公法最高裁判机关、最高法院（Cour de Cassation）为民刑最高法院；极简且不引先例的判决风格；以及学者（la doctrine）通过评注与教科书对法律的阐释影响。Siems 指出，法国民法典『以抽象方式起草，同时力求通俗易懂——像圣经一样简单』。", "history": "法国法律传统的形成与法国大革命及拿破仑时代紧密相连。大革命推翻旧制度，追求法律面前人人平等与统一，1791 年宪法确立了立法至上的原则。1804 年，拿破仑主持颁布民法典，将革命原则与既有法律技术相结合，成为现代大陆法的象征。民法典第 5 条明确禁止法官『以一般性与规范性规定裁判案件』，其背景是旧制度下的巴黎高等法院（Parlements）曾以发布普遍适用的规则阻挠改革；因此民法典旨在维护严格的分权、禁止法官造法，要求法律按法典文字准确适用。\n\nSiems 指出，与法国民法典相对，1900 年德国民法典风格更为概念化、教授化，法典化运动由此导致了欧洲大陆法律的分化。法国法随殖民与自愿移植扩散到比利时、荷兰、意大利、西班牙、拉美、埃及等地，形成广泛的『法国法族』。", "principle": "法国法的运作逻辑可从四个层面理解。\n\n第一，法典的精神。法国民法典以简明、清晰、可接近为理想，与德国民法典的抽象体系化形成鲜明对照。Siems 指出，法国 1989 年设立最高法典化委员会，至今仍推动新法典的制定与旧法典的重构，显示法典理想的持久生命力。\n\n第二，法官的角色。民法典第 5 条禁止法官以一般性规则裁判，体现对法官造法的警惕。这种立场与法国的议会至上与分权观念一脉相承——法官只是适用立法者意志。Siems 指出，大陆法法官在解释法律时有较大 discretion，但解释完成后便只是法律适用者；法国法官尤其强调尊重立法者。\n\n第三，法院组织。法国有民刑法院与行政法院两套体系。最高行政法院（Conseil d'État）是公法领域的最高法院，但其宪法职能较德国联邦宪法法院更为有限；普通法院不能审理涉及国家的案件，故 1987 年设立下级行政法院。Siems 指出，这与德国设有行政、劳动、社保、税务等专门法院及联邦宪法法院的格局有别。\n\n第四，判决风格。法国判决以极简著称，往往只有几行、几乎不超过一页，传统上不引用学术文献与先例。Siems 指出其辩护理由是简短带来清晰，与民法典简明风格一致；但批评者称之为『晦涩』(cryptic)。自二十世纪七十年代末起，巴黎上诉法院提供更详尽的理由，但最高法院（Cour de Cassation）的风格至今未变。", "viewpoints": "关于法国法的性格，Siems 综合学界看法：法国法以议会立法至上、法官抑制、简明法典与极简判决为特征。德国的教授、英格兰的法官、法国的立法者，分别代表了三种不同的法律主导力量格局。\n\n但 Siems 提醒，不要从判决简短就推断法国法缺乏政策思考。他重点介绍了 Mitchell Lasser 的研究：Lasser 关注法国形式主义判决中『未被报告的话语』，发现政策导向的论证在法国同样存在，只是与判决相分离——这种『二元划分』(bifurcation) 体现在报告法官（reporting judge）的意见与总检察长（advocate-general）的意见中（部分案件中公开）。因此，美法之间的差异关乎『司法心态』(judicial mentalities)，而非是否存在实质审议。", "comparison": "法国法与德国法同为大陆法范本，差异显著。\n\n在法典风格上，法国民法典简明通俗，德国民法典概念抽象、含总则编。在判决风格上，法国极简、不引先例学说，德国学术化、引用密集、条文链。在宪法审查上，法国最高行政法院的宪法职能有限，德国联邦宪法法院权能强大。在法院体系上，法国以二元普通—行政法院为特色，德国则有更多专门法院。\n\n两者与普通法系相比，共享大陆法基因；但法国法的简明法典与议会至上，与德国的教义学与教授主导，构成大陆法内部的两种典型。Siems 把这些差异置于法律家族分类框架下理解：法国法族与德国法族的分野，是大陆法内部多样性的体现。", "debates": "围绕法国法，一个有趣的争论是其极简判决是否意味着司法推理的缺失。美国比较法学者 Michael Wells 从美国视角出发，认为美国律师期待判决中有『理性与坦诚』(reason and candor) 以保证公平与正当性；而法国意见只是『几百词的无信息量三段论』，说明这种关联未必如美国人想的那么重要。\n\nLasser 则提供了更精细的解释：法国的政策论证被『二元划分』到判决之外，说它没有这类论证会失准；差异在于司法心态与话语组织形式。Siems 借这一争论说明：比较法不能仅看形式，而要深入法律文化内部；表面的相似或差异，可能掩盖更深层的机制。这一争论也呼应全书主题——法律风格背后是制度与文化的整体。", "case": "法国民法典第 1152 条关于违约金的规定，以及合同法中的不可抗力制度，是展示法国法特色的具体例子。Siems 指出，在违约金问题上，大陆法国家原则上允许违约金条款，但法院有控制手段：德国法可将『过高』的违约金减至合理数额，法国法则在违约金『明显过高或过低』时可增减（民法典第 1152 条）。这与普通法区分『罚金条款』（无效）与『预定损害赔偿条款』（有效）的做法不同。\n\n在损害赔偿的过错要件上，Siems 指出：德国民法典第 280 条第 1 款通常要求过错，法国法更常区分合同类型、仅在不可抗力（force majeure）时排除损害赔偿，而普通法以严格责任为起点——如 1945 年 Alderslade v Hendon Laundry 案中洗衣店须对未洗好衣物负责，不以尽到注意为抗辩。", "caseAnalysis": "以违约金比较为例：事实是，法国法允许违约金条款，法院可在明显过高或过低时调整；德国法可减至合理数额；普通法则因对价理论区分罚金（无效）与预定损害赔偿（有效）。争议焦点是：不同制度是否达成相近结果？\n\n从功能视角看，三者都试图在尊重当事人约定与防止滥用之间平衡，只是技术手段不同。法国第 1152 条的『增减』机制，与德国第 343 条的『减额』机制，功能相近而表述有别；普通法的罚金禁令则源于对价理论——约定罚金因缺乏对价而无效。Sacco 关于英法律师讨论赠与合同的例子也显示，操作规则可能相似，而教义装置完全相反。\n\n这一案例的理论意义在于：它展示了法国法在私法技术上的独特性，也说明功能比较的必要性——不同教义路径可达成相近结果。它也提醒我们，法国法与传统上『法官造法』的普通法在方法论上确有差异，但差异的具体内容需通过细致比较才能把握。", "summary": "法国法律传统以 1804 年民法典为核心，属大陆法罗马法族，以简明法典、议会立法至上、法官抑制、二元法院体系与极简判决为特征。民法典第 5 条禁止法官以一般规则裁判，反映分权与对法官造法的警惕。判决极简传统由最高法院延续至今，但 Lasser 的『二元划分』理论揭示：政策论证以报告法官与总检察长意见的形式存在于判决之外，法美差异关乎司法心态而非有无审议。法德同为大陆法范本，却在法典风格、判决写作、宪法审查与法院体系上差异显著。理解法国法，须超越『简单』『晦涩』等表象，深入其制度文化。", "furtherThinking": "1. 法国民法典第 5 条禁止法官造法，但今天法国法官实际上是否完全不造法？请结合一般条款思考。\n2. Lasser 的『二元划分』理论对理解『司法推理』这一概念有何启发？\n3. 法国法与德国法同为大陆法范本，若你要为一个移植大陆法典的国家提供咨询，你会建议参照哪一号范本？为什么？"}, "en": "The French Legal Tradition", "level": "core", "tags": "法国法, 拿破仑法典, 民法典, 行政法院, 判决风格", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M5K4"}, "S2M5K5": {"title": "北欧法律传统", "EN": "The Nordic Legal Tradition", "LEVEL": "fundamental", "TAGS": "北欧法, 斯堪的纳维亚法, 法律家族, 福利国家", "TERMS": "北欧法（Nordic Law）::丹麦、瑞典、挪威、芬兰、冰岛等北欧国家的法律传统；斯堪的纳维亚法（Scandinavian Law）::北欧法的核心组成部分，常指丹麦、瑞典、挪威三国法；法律现实主义（Legal Realism）::强调法律社会效果与现实运作的法学思潮；福利国家模式（Welfare State Model）::以国家主导社会保障与再分配为特征的治理模式", "SOURCE": "Siems, Comparative Law, ch.4；Zweigert & Kötz, Introduction to Comparative Law", "terms": [{"term": "北欧法（Nordic Law）", "def": "丹麦、瑞典、挪威、芬兰、冰岛等北欧国家的法律传统"}, {"term": "斯堪的纳维亚法（Scandinavian Law）", "def": "北欧法的核心组成部分，常指丹麦、瑞典、挪威三国法"}, {"term": "法律现实主义（Legal Realism）", "def": "强调法律社会效果与现实运作的法学思潮"}, {"term": "福利国家模式（Welfare State Model）", "def": "以国家主导社会保障与再分配为特征的治理模式"}], "sections": {"coreQuestion": "在世界法律地图上，北欧国家的位置颇为微妙：它们通常被归入大陆法系的日耳曼法族，却又常常被单列为一类。为什么？北欧法与德国法、法国法有哪些不同？Siems 指出，一些分类法为北欧国家设立独立类别，理由是它们『没有采纳综合性法典』，并强调其福利国家模式与立法者之间的密切互动。本节考察北欧法律传统的特征与分类地位，理解法律家族分类的边界问题。", "definition": "北欧法（Nordic Law）指丹麦、瑞典、挪威、芬兰、冰岛等北欧国家的法律传统，其核心是斯堪的纳维亚法（Scandinavian Law，常指丹麦、瑞典、挪威三国法）。Siems 指出，斯堪的纳维亚国家最常被归入日耳曼大陆法，但也有观点主张，其福利国家模式与立法者之间的密切互动，足以支持一个独立而相对统一的北欧法律家族。\n\n北欧法的典型特征包括：缺乏像法德那样包罗万象的综合性法典；法律渊源较为多元，判例与学说的地位不同于典型大陆法；法律思维务实、经验主义，受法律现实主义影响较深；以及法律与福利国家治理的紧密结合。", "history": "北欧法律传统有着不同于欧洲大陆的发展路径。中世纪后期，北欧各国形成了各自的地方习惯法，未经历欧洲大陆那样全面的罗马法继受。近代民族国家兴起后，北欧国家虽编纂了一些法典（如瑞典1734 年法典、丹麦与挪威的法典），但并未形成法国民法典或德国民法典那样高度抽象、体系化的综合法典。十九、二十世纪，北欧国家发展出以议会立法为核心、以社会福利为取向的法律制度，法律职业规模较小、法官与学者互动密切，形成务实、灵活的法律风格。二十世纪，北欧的法律现实主义（又称 Uppsala 学派）对法律的社会效果与『行动中的法』予以高度关注。", "principle": "理解北欧法的分类地位，可从三个层面入手。\n\n第一，与大陆法的共性。北欧国家在私法的许多领域受德国法影响，法律教育、概念体系与法院组织与大陆法有相似之处，故常被视为日耳曼大陆法的一支。Siems 指出，斯堪的纳维亚国家『最常被归入日耳曼大陆法』。\n\n第二，与典型大陆法的差异。北欧国家没有采纳综合性法典，法律渊源相对分散；其法律思维更务实、更少概念主义。Siems 明确指出，一些分类法因北欧国家『没有采纳综合性法典』而将其单列；其福利国家模式与立法者之间的密切互动，也支持独立分类的主张。\n\n第三，现实主义传统。北欧法律现实主义强调研究法律的实际运作，关注法律在社会中的效果，这与 Siems 所倡导的社会法学(socio-legal)方法多有契合。这一传统使北欧法在方法论上更接近法律现实主义，而非德国式的概念教义学。", "viewpoints": "关于北欧法的分类，学界存在两种主张。传统分类（如 Zweigert 与 Kötz）把北欧法归入日耳曼大陆法族，强调其与德国法的历史联系。另一派学者则主张，北欧国家构成一个独立而相对统一的法律家族，理由是共同的福利国家模式、相似的治理结构、法律职业的紧密互动，以及无综合法典的共同特征。Siems 采取开放态度：他既承认北欧法与大陆法的联系，也承认独立分类的理由，并把这一争议视为法律家族分类边界模糊的例证。", "comparison": "北欧法与德国法的对照具有代表性。德国法以高度体系化的民法典、概念教义学与教授主导为特征；北欧法则无综合法典、思维务实、受现实主义影响。两者虽共享大陆法基因，却呈现不同的法律风格。\n\n北欧法与普通法系也有可比之处：两者都较少依赖综合法典，都重视判例的实际作用，法律思维都偏经验主义。但北欧国家在法院组织与法律职业上更接近大陆法——法官为职业公务员，大学法律教育居于核心。这种『混合特征』进一步说明，法律家族的边界并非泾渭分明。", "debates": "北欧法的分类地位本身，就是法律家族分类争论的缩影。Siems 在书中讨论分类的三种偏向：过度强调差异、过度强调共性与忽视混合体。北欧法的案例提示：若把它完全并入德国法族，就忽视了其无综合法典、福利国家导向与现实主义传统；若把它完全独立，又可能夸大其与大陆法的差异。\n\n更根本地说，北欧法的分类难题说明：法律家族是为认知目的而设的『理想类型』，现实中的法律体系往往处于交叉地带。Siems 借此类案例主张，比较法应把混合与边缘情形视为常态，而非例外。", "case": "瑞典的法律制度改革是体现北欧法务实风格的例子。瑞典在合同法、消费者保护与社会保障领域，倾向于通过单行立法与判例发展规则，而非依赖一部包罗万象的民法典。其法律改革往往由政府委员会推动，广泛征求社会意见，体现立法者与社会需求的密切互动。Siems 提到的『福利国家模式』与『立法者之间的密切互动』，正可在这一治理风格中得到理解。这一案例说明，北欧法的『实用主义』不仅体现在法律技术上，也体现在法律与社会的联系方式上。", "caseAnalysis": "就瑞典法律改革而言，事实是：北欧国家通过单行立法、委员会提案与判例发展法律，未采纳法德式综合法典。争议焦点是：这种安排应被理解为『大陆法的变体』还是『独立的法律家族』？\n\n从共性视角看，北欧私法的许多概念与制度源自德国法，法律教育与法院组织也相近，故可归入日耳曼法族。从差异视角看，无综合法典、福利国家导向、现实主义传统与紧密的立法者互动，支持独立分类。Siems 的框架提示，两种答案各有依据，关键在于明确分类的目的：若用于理解法律渊源与方法，独立分类更有解释力；若用于理解私法制度的谱系，归入日耳曼法族亦无不可。\n\n这一案例的理论意义在于：它把法律家族分类的相对性具体化——分类服务于特定认知目的，为法律体系贴唯一正确标签的做法难以为继。", "summary": "北欧法指丹麦、瑞典、挪威、芬兰、冰岛等国的法律传统，核心为斯堪的纳维亚法。它通常被归入大陆法的日耳曼法族，但因未采纳综合性法典、具有福利国家模式与立法者密切互动等特征，常被一些分类法单列为独立的法律家族。北欧法思维务实、受法律现实主义影响，与德国式的概念教义学形成对照。Siems 以这一分类争议说明，法律家族是为认知目的而设的理想类型，现实中的法律体系常处于交叉地带。理解北欧法，既要看到它与大陆法的联系，也要尊重其独特制度风格。", "furtherThinking": "1. 北欧法应被归入日耳曼大陆法族，还是独立成类？请基于分类目的给出论证。\n2. 北欧法律现实主义与 Siems 倡导的社会法学方法有何相通之处？\n3. 一个没有综合性法典的法律体系，在方法论上更接近大陆法还是普通法？请举例说明。"}, "en": "The Nordic Legal Tradition", "level": "fundamental", "tags": "北欧法, 斯堪的纳维亚法, 法律家族, 福利国家", "source": "Siems, Comparative Law, ch.4；Zweigert & Kötz, Introduction to Comparative Law", "id": "S2M5K5"}, "S2M5K6": {"title": "混合法律体系", "EN": "Mixed Legal Systems", "LEVEL": "core", "TAGS": "混合法系, 法律家族, 路易斯安那, 魁北克, 南非, 法律多元", "TERMS": "混合法律体系（Mixed Legal System）::融合两种或两种以上法律传统的制度；法律多元主义（Legal Pluralism）::同一社会中存在多个法律秩序并存的现象；罗马—荷兰法（Roman-Dutch Law）::源于荷兰、在南非等地沿用的大陆法传统；民法传统（Civilian Tradition）::大陆法的法律传统；普通法传统（Common Law Tradition）::英美法的法律传统；混合法院（Mixed Court）::由不同传统法官共同组成的裁判机构", "SOURCE": "Siems, Comparative Law, ch.4；ch.5", "terms": [{"term": "混合法律体系（Mixed Legal System）", "def": "融合两种或两种以上法律传统的制度"}, {"term": "法律多元主义（Legal Pluralism）", "def": "同一社会中存在多个法律秩序并存的现象"}, {"term": "罗马—荷兰法（Roman-Dutch Law）", "def": "源于荷兰、在南非等地沿用的大陆法传统"}, {"term": "民法传统（Civilian Tradition）", "def": "大陆法的法律传统"}, {"term": "普通法传统（Common Law Tradition）", "def": "英美法的法律传统"}, {"term": "混合法院（Mixed Court）", "def": "由不同传统法官共同组成的裁判机构"}], "sections": {"coreQuestion": "如果法律家族是彼此排斥的类别，那么路易斯安那、魁北克、南非该如何归类？这些法域的私法承袭大陆法（尤其是法国法）传统，公法或程序却深受普通法影响；南非更是罗马—荷兰法与英美法并存。Siems 把『忽视混合体』(disregard of hybrids) 列为法律家族分类的三大偏向之一。本节考察混合法律体系的成因、类型与理论意义，理解它如何揭示法律家族的相对性——把它当成分类的『例外』会错失要点。", "definition": "混合法律体系（mixed legal system）指融合两种或两种以上法律传统的制度。Siems 指出，在分类中，混合体系的类别通常仅限于少数受大陆法与普通法双重影响的国家，如苏格兰与南非；但更广义的混合也存在于西方传统与宗教法、习惯法的交汇处。\n\n需要区分混合体系与法律多元主义（legal pluralism）：前者指一个法律体系内部融合了多种传统；后者指同一社会中存在多个法律秩序（如国家法与习惯法、宗教法并存）。两者相关但不同——混合体系往往是法律多元在历史中制度化的结果。\n\nSiems 强调，混合体系的存在是对『大分野』(great divides) 式分类的挑战。既然『大分野是诱人的组织技术』，但分类必然简化，那么混合体正是被简化掉的部分。", "history": "混合法律体系大多是历史接触的产物。殖民扩张把欧洲法律带到美洲、非洲与亚洲，不同宗主国的法律、移民带来的习惯与原住地法律相互叠加，形成混合。路易斯安那曾为法国殖民地、后归属美国，私法保留法国民法传统，公法与美国普通法趋同；魁北克在英属北美框架下保留法国民法传统；南非先后受荷兰与英国统治，形成罗马—荷兰法与普通法的混合。Siems 指出，西方传统与习惯法的混合（如在非洲）同样普遍，并可区分多种习惯法类型。这些历史表明，混合是法律传播与接触的常态结果。", "principle": "理解混合体系，可从成因、类型与方法三个层面展开。\n\n第一，成因。混合源于法律传统的空间移动与叠加：殖民征服、移民、贸易、法律移植都会把一种传统植入另一传统的环境。Siems 指出，法律移植与混合体系密切相关——移植把规则从一处搬到另一处，而混合是移植长期积累的结果。\n\n第二，类型。Siems 提到混合的多种形式：大陆法与普通法的混合（如路易斯安那、魁北克、苏格兰、南非）；西方传统与宗教法的混合（如穆斯林国家的商法与家庭法分立）；西方传统与习惯法的混合（如非洲国家）。他还提到习惯法的四种类型——活的习惯法（living customary law，原初不成文形态）、教科书习惯法、法典化习惯法等，显示混合的具体形态复杂多样。\n\n第三，方法。研究混合体系，功能主义方法尤显价值：既然传统的标签失效，就应从具体问题入手，考察不同传统在同一个法域中如何搭配运作。Siems 强调，比较法应把混合体视为检验分类边界的试金石，而非需要排除的异常。", "viewpoints": "关于混合体系的意义，Siems 持明确立场：把『忽视混合体』列为分类的偏向之一，意味着混合体系应当被正视。他的论断是：『在今天的世界里，不存在纯粹的法律体系；所有法律体系都在吸收世界各地的观念。』这一判断把混合从例外提升为常态。\n\n在这一视角下，混合体系不仅是分类难题，更是理解法律发展的窗口：它展示了法律传统如何接触、冲突、融合，以及移植的规则如何在新环境中变形。Siems 借 Galanter 的比喻说明：法律像语言，能够吸收外来影响同时『保留独特的结构与风味』——混合体系正是这一过程的活标本。", "comparison": "混合体系与普通法系、大陆法系的关系，可通过具体法域对照理解。\n\n路易斯安那：私法承法国法传统（采用民法典），公法、程序与许多商事制度与美国普通法趋同。魁北克：民法传统保留，公法属加拿大普通法框架。南非：罗马—荷兰法与普通法并存，还有习惯法的地位。苏格兰：大陆法私法传统与英国普通法公法并存。\n\n这些法域说明，法系标签是『理想类型』：现实中的法律体系常处于交叉地带，任何单一标签都会遮蔽一半事实。混合体系既是法律史的产物，也是比较法方法论的试金石。", "debates": "围绕混合体系，一个根本争论是：混合是否意味着分类方案的失败？一种观点认为，混合体系的存在证明法律家族分类是人为的、站不住脚的；另一种观点认为，混合只是少数例外，不影响分类的总体有效性。\n\nSiems 的立场介于两者之间：他承认混合体系对传统分类构成挑战，但并未主张放弃分类；相反，他主张把混合视为常态，警惕把分类标签当作本质判断。他批评『过度强调差异』『过度强调共性』与『忽视混合体』三种偏向，实际上是在为分类『降温』——分类仍有用，但必须保持开放与自我反思。这一立场连接着全书对西方化、趋同与文化主义的讨论。", "case": "路易斯安那与魁北克是经典案例。路易斯安那原为法国殖民地，1803 年并入美国后，其私法仍保留法国民法与西班牙法的影响，采用法典；但公法、程序与商事制度则与美国普通法趋同。魁北克在英属北美框架下保留法国民法传统，形成民法与英美公法并存的格局。\n\nSiems 在讨论分类时还提到非洲的混合：西方（通常是大陆法）传统与习惯法的混合，并区分活的习惯法、教科书习惯法、法典化习惯法等类型。这些案例说明，混合是法律在全球流动与接触中的普遍结果，某一法域的偶然现象之说难以解释。", "caseAnalysis": "以路易斯安那为例：事实是，其私法承大陆法传统、公法与普通法趋同。争议焦点是：它应归入大陆法系还是普通法系？无论选择哪一边，都会遮蔽另一半事实。\n\n从分类理论看，这一案例揭示了标签的限度：法律家族是认知工具，现实体系常处于交叉地带。Siems 借此类案例主张，比较法应把混合视为常态，并关注混合带来的制度后果——例如，法官必须在两套思维间切换，法律教育须兼顾两种传统，规则的解释与适用可能出现独特的张力。\n\n这一案例的理论意义在于：它把『法律家族分类的相对性』具体化，也说明比较法必须超越标签，深入分析每个法域独特的历史构成与运作机制。对于学习者而言，路易斯安那式的混合体系是最好的『反例』——它提醒我们，任何分类都只是对复杂现实的简化。", "summary": "混合法律体系指融合两种或两种以上法律传统的制度，典型如路易斯安那、魁北克、苏格兰与南非。它大多源于殖民、移民与法律移植等历史接触，形式包括大陆法与普通法的混合、西方传统与宗教法或习惯法的混合。Siems 把『忽视混合体』列为法律家族分类的偏向之一，并断言不存在纯粹的法律体系。混合体系意味着法律家族是认知目的下的理想类型，现实常处于交叉地带；它既是分类难题，也是理解法律接触、移植与变形的窗口。比较法应把混合视为常态，超越标签，深入分析具体法域的历史构成与运作。", "furtherThinking": "1. 混合体系的存在，是法律家族分类的失败，还是提醒我们分类只是工具？请论证。\n2. 法律多元主义与混合法律体系有何区别与联系？请举例说明。\n3. 路易斯安那的法官同时面对大陆法私法与普通法公法，这种混合可能带来哪些方法论上的挑战？"}, "en": "Mixed Legal Systems", "level": "core", "tags": "混合法系, 法律家族, 路易斯安那, 魁北克, 南非, 法律多元", "source": "Siems, Comparative Law, ch.4；ch.5", "id": "S2M5K6"}, "S2M5K7": {"title": "宗教法与传统法的影响", "EN": "The Influence of Religious and Traditional Law", "LEVEL": "core", "TAGS": "宗教法, 伊斯兰法, 习惯法, 法律多元, 法律与宗教", "TERMS": "宗教法（Religious Law）::以宗教教义与经典为根基的法律体系，如伊斯兰法、犹太法、印度教法；伊斯兰法（Islamic Law / Sharia）::以古兰经与圣训为基础的伊斯兰法律传统；习惯法（Customary Law）::基于长期形成的习俗与惯例而非成文立法的法律；法律多元主义（Legal Pluralism）::同一社会中多个法律秩序并存的现象；教会法（Canon Law）::基督教教会制定的法律体系；世俗化（Secularisation）::法律与宗教制度分离的过程", "SOURCE": "Siems, Comparative Law, ch.4；ch.5；ch.10", "terms": [{"term": "宗教法（Religious Law）", "def": "以宗教教义与经典为根基的法律体系，如伊斯兰法、犹太法、印度教法"}, {"term": "伊斯兰法（Islamic Law / Sharia）", "def": "以古兰经与圣训为基础的伊斯兰法律传统"}, {"term": "习惯法（Customary Law）", "def": "基于长期形成的习俗与惯例而非成文立法的法律"}, {"term": "法律多元主义（Legal Pluralism）", "def": "同一社会中多个法律秩序并存的现象"}, {"term": "教会法（Canon Law）", "def": "基督教教会制定的法律体系"}, {"term": "世俗化（Secularisation）", "def": "法律与宗教制度分离的过程"}], "sections": {"coreQuestion": "在现代法律地图上，宗教法与传统法占据着一个容易被忽视却极为重要的位置。Siems 指出，西方法律传统区别于『宗教与部落共同体的法律』，并把法律与宗教的分离列为西方法律的特征之一。但这一区分本身值得追问：宗教法在当代世界是否仍有生命力？习惯法与国家法如何共处？当比较法把目光投向西方之外时，如何避免用西方的法律概念去裁剪其他文化？本节考察宗教法与传统法的类型、与现代法律的关系，以及它们对比较法方法论的挑战。", "definition": "宗教法（religious law）指以宗教教义与经典为根基的法律体系，主要类型包括伊斯兰法（Islamic Law / Sharia）、犹太法（Halakha）、印度教法（Hindu law）与基督教教会法（Canon Law）。Siems 指出，宗教的分类可从亚伯拉罕诸教、印度宗教与东亚宗教等主要类别入手。\n\n传统法（traditional law）在此主要指习惯法（customary law）——基于长期形成的习俗与惯例、而非成文立法的法律。Siems 在法律家族分类中讨论宗教法与传统法：许多分类法设有基于伊斯兰法、印度教的类别，与相应宗教传统紧密相连；许多非西方国家的法律则兼具西方传统与习惯法的混合特征。\n\n法律多元主义（legal pluralism）是理解这两类法律的关键概念：在同一社会中，国家法、宗教法与习惯法可能同时存在、各自调整不同领域（如家庭、继承与商事）。", "history": "法律与宗教的关系经历了漫长演变。在西方法律传统中，教会法曾是中世纪欧洲的重要法律体系，与世俗法并存；近代民族国家兴起与世俗化（secularisation）进程，使法律逐渐与宗教分离——Siems 把『法律与宗教的分离』列为西方法律的具体因素之一。但在世界其他地区，宗教法与传统法并未经历同样的分离：伊斯兰法至今在穆斯林国家的家庭法、继承法乃至商事领域发挥作用；印度教法影响个人法；习惯法在非洲与亚洲的许多社区仍是调整社会关系的重要规范。Siems 指出，即便在西方国家，法律中仍可见宗教法的历史痕迹，如英格兰法中的教会法、信托法的罗马渊源等。", "principle": "理解宗教法与传统法的当代地位，可从三个层面展开。\n\n第一，分类中的地位。Siems 指出，许多法律家族分类把伊斯兰法、印度教法等作为与宗教传统紧密相连的类别；同时，非洲与东亚的法律常被以地理文化标准分类（如东亚法、非洲法）。这些分类反映了一个假定：这些文化的法律有其特殊性。\n\n第二，混合与多元。Siems 强调，西方传统与习惯法的混合在非洲等地十分普遍，并可区分活的习惯法、教科书习惯法、法典化习惯法等类型。法院的结构（部落法院与国家法院）、法官裁判的依据、判决的实际效力，都呈现复杂混合。这说明宗教法与传统法在与现代法律持续互动，静态遗存的印象需要修正。\n\n第三，功能与价值的张力。宗教法与传统法常被视为与现代法治、人权价值存在张力——例如对个人权利、性别平等的不同理解。Siems 在『法律与发展』一章中讨论法治在不同语境中的理解，提示不能以单一标准评判。比较法的任务之一，正是理解这些法律在各自社会中的功能，而非简单套用西方标准。", "viewpoints": "关于宗教法与传统法的地位，Siems 持一种平衡而批判的立场。一方面，他承认西方法律传统以法律与宗教分离为特征，并把宗教法、部落法作为其对照；另一方面，他反对把这种区分绝对化。他明确指出，普通法与伊斯兰法之间存在可比之处——两者都基于『分权化的制度体系』(decentralised system of institutions)。这一洞见很有意义：它提示宗教法并非与现代法律截然对立，而可能在制度形态上与现代法律有相通之处。\n\nSiems 还强调，宗教法的影响并未随现代化消失。 globalization 时代，宗教法的全球流动（如伊斯兰金融、宗教法在移民社区的作用）使比较法必须持续关注这一领域。", "comparison": "宗教法、习惯法与西方法律传统形成多组对照。\n\n与普通法相比：Siems 指出普通法与伊斯兰法都基于分权化的制度体系，存在结构相似性；这与人们通常强调的差异形成对照。\n\n与大陆法相比：大陆法以国家制定法典、法律与宗教分离为特征；宗教法则以宗教经典为渊源、往往与国家法并存。但当代许多穆斯林国家把伊斯兰法要素纳入国家法典，形成混合。\n\n与现代国家法相比：习惯法基于习俗、多为不成文、由社区权威实施；国家法基于立法、成文、由国家法院实施。但在非洲等地，二者长期共存、相互渗透。\n\n这些对照说明，宗教法与传统法具有自身逻辑、并与现代制度持续互动，现代法律的『残存』之称低估了它们。", "debates": "围绕宗教法与传统法，比较法中的经典争论，是普遍主义与文化相对主义之间的张力。普遍主义立场倾向于以现代法治、人权等标准评判所有法律体系，宗教法与传统法常被贴上『落后』『不兼容』的标签；文化相对主义则强调每种法律都在特定文化中形成、服务于特定社会需求，反对用单一标准衡量。\n\nSiems 的立场倾向于审慎的中间路线。他批判『西方化』(Westernisation) 的简单化叙述，主张理解法律的社会语境；同时他并不回避讨论法治、人权的价值问题。他把法律与宗教的关系、宗教法与现代法律的张力视为比较法必须严肃面对的议题，反对简单化的二元判断。这一立场呼应了他对法律家族分类的整体态度：既承认差异，又警惕夸大差异。", "case": "伊斯兰法的当代地位是一个核心案例。Siems 指出，许多分类法设有基于伊斯兰法的类别；在穆斯林国家，伊斯兰法在家庭、继承与个人身份领域持续发挥关键作用，一些国家还把伊斯兰法原则纳入宪法或立法；同时，伊斯兰金融等新兴领域使宗教法跨越国界流通。\n\n另一个例子是非洲的习惯法。Siems 区分活的习惯法、教科书习惯法与法典化习惯法，指出西方传统与习惯法的混合在非洲广泛存在。部落法院与国家法院并存、法官裁判依据的多元，都展示了法律多元主义的实际形态。这些案例说明，宗教法与传统法在与现代制度的互动中持续演变，静态之说并不成立。", "caseAnalysis": "以非洲习惯法的混合为例：事实是，在前殖民地国家，西方法（通常是大陆法）与本土习惯法长期共存，形成活的习惯法、教科书习惯法、法典化习惯法等不同形态。争议焦点是：这种混合应被理解为法律的『未现代化』，还是一种有自身逻辑的制度安排？\n\nSiems 的分析框架提示，答案取决于我们采用何种评价标准。从功能视角看，习惯法在基层社区提供纠纷解决、维护社会秩序，具有实际功能；从制度视角看，它与国家法院体系的关系复杂，既有补充也有张力。Siems 还指出，评价宗教法与传统法时，应避免以西方标准作简单裁断，而要理解其在具体社会中的角色。\n\n这一案例的理论意义在于：它把宗教法与传统法从『历史遗存』提升为比较法必须严肃对待的当代现象，并展示了法律多元主义、混合与功能分析等概念的解释力。它也呼应全书的语境化主题：理解法律，必须把它放回其社会文化环境。", "summary": "宗教法与传统法是比较法不可忽视的领域。宗教法包括伊斯兰法、犹太法、印度教法与教会法等，传统法主要指习惯法。Siems 指出，西方法律传统以法律与宗教分离为特征，并把宗教法、部落法作为对照，但他反对把这一区分绝对化——普通法与伊斯兰法都基于分权化的制度体系，存在结构相似性。习惯法在非洲等地与国家法长期共存，形成活的习惯法、教科书习惯法、法典化习惯法等形态。围绕宗教法与传统法的争论，体现普遍主义与文化相对主义的张力。理解这些法律，须避免西方中心主义，将其放回具体社会文化语境，这正是比较法语境化方法的要义。", "furtherThinking": "1. Siems 说普通法与伊斯兰法都基于『分权化的制度体系』，这一相似性对打破西方中心主义有何意义？\n2. 习惯法与国家法在非洲长期共存，这对『法律全国统一』的传统观念提出了什么挑战？\n3. 在评价宗教法与现代人权价值的关系时，比较法应如何在普遍标准与文化语境之间取得平衡？"}, "en": "The Influence of Religious and Traditional Law", "level": "core", "tags": "宗教法, 伊斯兰法, 习惯法, 法律多元, 法律与宗教", "source": "Siems, Comparative Law, ch.4；ch.5；ch.10", "id": "S2M5K7"}, "S2M6K1": {"title": "法院组织结构比较", "EN": "Comparative Court Organisation", "LEVEL": "core", "TAGS": "法院组织, 专门法院, 陪审团, 上诉制度, 职业法官", "TERMS": "法院组织（Court Organisation）::法院的设置、层级、管辖权与法官构成的制度安排；专门法院（Specialised Court）::按案件类型设立的专门审判机构；普通法院（Ordinary Court）::审理一般私刑案件的常规法院；上诉（Appeal）::对下级法院裁判的复审程序；再审模型（Revision Model）::德国式上级法院可替代下级裁判的模式；撤销模型（Cassation Model）::法国式上级法院仅撤销并发回的模式；职业法官（Career Judge）::经专门培训、以司法为职业的法官；陪审团（Jury）::由普通公民组成、负责事实认定的审判组织", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "法院组织（Court Organisation）", "def": "法院的设置、层级、管辖权与法官构成的制度安排"}, {"term": "专门法院（Specialised Court）", "def": "按案件类型设立的专门审判机构"}, {"term": "普通法院（Ordinary Court）", "def": "审理一般私刑案件的常规法院"}, {"term": "上诉（Appeal）", "def": "对下级法院裁判的复审程序"}, {"term": "再审模型（Revision Model）", "def": "德国式上级法院可替代下级裁判的模式"}, {"term": "撤销模型（Cassation Model）", "def": "法国式上级法院仅撤销并发回的模式"}, {"term": "职业法官（Career Judge）", "def": "经专门培训、以司法为职业的法官"}, {"term": "陪审团（Jury）", "def": "由普通公民组成、负责事实认定的审判组织"}], "sections": {"coreQuestion": "一个国家的法院如何组织，看似只是技术问题，实则深刻影响法律的运作方式。为什么德国设有行政、劳动、社保、税务等专门法院和一个强大的联邦宪法法院，而英美法系长期不区分公法与私法法院？为什么大陆法国家的上诉可以重新审查事实，普通法国家却通常不能？陪审团、职业法官、合议庭与独任法官的安排，背后是怎样的治理理念？本节比较两大法系的法院组织，理解制度安排与法律方法之间的内在关联。", "definition": "法院组织（court organisation）指法院的设置、层级、管辖权与法官构成的制度安排。Siems 指出，法院组织是普通法与大陆法差异最显著的领域之一，且各项差异相互关联，任意拼凑的印象并不准确。\n\n主要相关概念包括：普通法院（ordinary court）与专门法院（specialised court）的区分；上诉制度中的再审模型（revision model，德国式，上级法院可替代下级裁判）与撤销模型（cassation model，法国式，上级法院仅撤销并发回重审）；职业法官（career judge，经专门培训、终身任职）与独立法官、陪审团（jury）、参审员（lay judge）等不同裁判主体；以及合议庭（panel）与独任法官（single judge）的审判组织形式。", "history": "法院组织的差异有深厚的历史根源。Siems 指出，大陆法国家按法律领域区分法院，可追溯到罗马法对国家事务与个人事务的严格区分——法院最初主要处理私人事务与刑法，故有普通法院;行政等公法事务则由专门法院处理。与之相对，普通法国家传统上不区分私法与公法法院，国家在民事赔偿中『只是一个普通当事人』，由普通管辖法院审理。\n\n陪审团的历史则与英格兰王室司法的本土接受相关——1066 年后，事实认定交由陪审团，以利王室司法在地方获得认可。Siems 指出，陪审团曾是所有普通法国家民事与刑事审判的核心，后来在多数国家消失，美国是显著例外。", "principle": "法院组织的比较可从四个层面展开。\n\n第一，法院的类型。Siems 指出，大陆法国家倾向按领域设专门法院：德国有行政、劳动、社会保障、税务等专门法院，外加联邦宪法法院；法国的最高行政法院（Conseil d'État）是公法最高法院，1987 年又设下级行政法院。普通法国家传统上不区分公私法院，国家在普通法院中作为普通一方；英国虽有行政裁判所（tribunals），但其裁决可上诉至普通法院，未形成独立法院体系。\n\n第二，上诉制度。Siems 指出，大陆法国家的上诉更为广泛：第一级上诉法院不仅审查法律，还可重新审查事实；第二级上诉中，德国采再审模型（上级法院可替代下级裁判），法国采撤销模型（上级法院仅撤销并发回）。普通法国家虽也有多级法院（如英格兰 1875 年设上诉法院，后上诉至英国最高法院），但上诉通常不能重新审查事实，且是否准许上诉往往由法院裁量。\n\n第三，法官的性质。大陆法法官多为职业公务员，经大学教育与专门考试（法国法官须通过考试并接受司法学院培训；德国大学与实务教育统一，仅最优秀毕业生可任法官），年轻时任命，终身从事司法职业。普通法法官传统上无专门培训，英格兰从资深出庭律师中任命，被视为『质量勋章』；美国则有选举、政治任命等多种方式。\n\n第四，审判组织。大陆法法院倾向合议庭审判，普通法法院独任法官更常见（但重大上诉案件多为合议庭）。陪审团在普通法国家历史上用于民事与刑事事实认定；大陆法国家的陪审仅限于刑事，且形式不同——德国 1924 年废除陪审团，代之以参审员（Schöffen）制度，法国在重罪法庭（cour d'assises）仍用陪审员，德法在劳动、商事等专门法院均有非职业法官参与，与职业法官组成混合法庭。", "viewpoints": "关于法院组织的差异，Siems 综合 Damaska 的分析：大陆法的权威组织遵循等级制（vertical）理想，强调职业法官、层级监督与法律适用的统一；普通法遵循协调制（horizontal）理想，以法官与陪审团为主体，权力分散。Damaska 还从集中/分散与协调/保护两个维度构建了比较矩阵。\n\nSiems 指出，这些差异相互关联：大陆法的职业法官与层级结构使上诉复审下级工作显得合理；普通法的陪审团与口头、集中审理使上诉法院难以重建事实，而先例的约束力又减少了对广泛上诉的需求。", "comparison": "法院组织的比较揭示了『形式』与『功能』的关系。\n\n大陆法与普通法的法院组织对照鲜明：在法院类型上，专门法院对普通法院；在上诉范围上，可复审事实对通常仅限法律；在法官性质上，职业公务员对独立专业人士；在审判组织上，合议庭对独任法官；在事实认定上，参审员对陪审团。\n\n但这些对照是理想类型，现实中存在趋同与混合：英国有行政裁判所，普通法国家也有专门化；大陆法国家鼓励集中审理与口头程序；两大法系都引入多元纠纷解决机制。Siems 强调，比较法应避免把差异绝对化，而应关注各项制度如何相互支撑。", "debates": "法院组织领域的一个争论，是陪审团制度的价值。支持者认为陪审团体现民主参与、防止国家权力滥用，是美国『文化与民主的关键要素』；批评者则质疑其专业性、效率与潜在的偏见。Siems 指出，陪审团在多数普通法国家的民事审判中已经消失，美国是例外；但即便消失，其结构性影响仍在——『幽灵陪审团』(phantom jury) 帮助理解普通法审判的口头原则与集中审理。\n\n另一个争论是专门法院的利弊。支持者认为专门法院提供专业裁判、提高效率；批评者担心其造成法律适用的碎片化。Siems 指出，普通法国家通过律师的专业化（solicitors、barristers 各专领域）作为专门法院的替代。", "case": "德国的宪法法院与专门法院是法院组织特色的典型。德国联邦宪法法院（Bundesverfassungsgericht）权能强大，可审查立法合宪性；Siems 指出，德国还有行政、劳动、社会保障、税务等专门法院，构成复杂的法院体系。与之相对，英格兰没有成文宪法，法官不能审查议会立法的有效性，传统上也没有独立的行政法院体系——行政裁判所的裁决可上诉至普通法院。\n\n在参审制方面，德国 1924 年废除陪审团、改用参审员（Schöffen），非职业法官与职业法官共同组成合议庭，既决定事实也决定法律；这与英美陪审团只决定事实、与法官分离的模式形成鲜明对照。", "caseAnalysis": "以德法上诉模式为例：事实是，德国采再审模型，上级法院可替代下级裁判；法国采撤销模型，上级法院仅撤销并发回。争议焦点是：两种模式各有什么制度逻辑？\n\nSiems 指出，这与法官的组织方式相关：大陆法的职业法官处于层级体系中，强调问责，上级法官复审下级工作显得合理；而普通法因陪审团与口头集中审理难以重建事实，加上先例的约束力，上诉范围较窄。法国撤销模型体现对下级裁判权的尊重与分权，德国再审模型则强调统一与效率。\n\n这一案例的理论意义在于：它把法院组织的『技术差异』与深层的治理理念（等级制对协调制、问责对独立）联系起来。它说明，比较法院组织不能停留在制度描述，而要追问制度背后的功能与价值。", "summary": "法院组织是普通法与大陆法差异显著的领域。大陆法倾向按领域设专门法院（德国行政、劳动、社保、税务法院与联邦宪法法院；法国最高行政法院与行政法院），上诉范围广泛且可复审事实，法官为职业公务员、合议庭审判，陪审限于刑事且多为参审制；普通法传统上不区分公私法院，上诉通常不涉及事实，法官多为独立专业人士，独任审判较常见，陪审团历史上用于民事刑事（美国保留民事陪审团）。Damaska 以等级制与协调制理想概括两种模式。这些差异相互关联，并与宪法结构、法律方法深度绑定，是理解比较法律制度的重要入口。", "furtherThinking": "1. 德国的再审模型与法国的撤销模型，各反映怎样的分权与效率观念？\n2. 陪审团在多数普通法国家民事审判中消失，但在美国保留。这种差异说明了什么？\n3. 专门法院与普通法院的取舍，对法律适用的统一性与专业性各有什么影响？"}, "en": "Comparative Court Organisation", "level": "core", "tags": "法院组织, 专门法院, 陪审团, 上诉制度, 职业法官", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M6K1"}, "S2M6K2": {"title": "判例制度与成文法制度", "EN": "Case Law and Statutory Law Systems", "LEVEL": "core", "TAGS": "判例法, 成文法, 遵循先例, 法典化, 法律渊源", "TERMS": "判例法（Case Law）::以法院判决为法律渊源的法律形式；成文法/制定法（Statute Law）::由立法机关制定的规范性文件；遵循先例（Stare Decisis）::法院受先前判决约束的原则；先例（Precedent）::可供后续案件援引的先前判决；判决理由（Ratio Decidendi）::判决中具有约束力的核心理由；附带意见（Obiter Dicta）::判决中不具约束力的附带表述；法典化（Codification）::把法律系统编纂为法典的运动；法律渊源（Sources of Law）::法律规范的正式来源", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "判例法（Case Law）", "def": "以法院判决为法律渊源的法律形式"}, {"term": "成文法/制定法（Statute Law）", "def": "由立法机关制定的规范性文件"}, {"term": "遵循先例（Stare Decisis）", "def": "法院受先前判决约束的原则"}, {"term": "先例（Precedent）", "def": "可供后续案件援引的先前判决"}, {"term": "判决理由（Ratio Decidendi）", "def": "判决中具有约束力的核心理由"}, {"term": "附带意见（Obiter Dicta）", "def": "判决中不具约束力的附带表述"}, {"term": "法典化（Codification）", "def": "把法律系统编纂为法典的运动"}, {"term": "法律渊源（Sources of Law）", "def": "法律规范的正式来源"}], "sections": {"coreQuestion": "普通法系的中心是判例，大陆法系的中心是成文法典——这是比较法最流行的说法。但 Siems 提醒，这一图景需要大幅修正：大陆法的法典不再是首要渊源，普通法已进入『成文法时代』。判例与成文法的关系远比『二选一』复杂。本节考察判例制度与成文法制度各自的运作逻辑、二者的真实差异与趋同，并借助 MacCormick 与 Summers 的先例研究，澄清『先例』在两大法系中的不同地位。", "definition": "判例法（case law）指以法院判决为法律渊源的法律形式；成文法/制定法（statute law）指由立法机关制定的规范性文件。Siems 指出，在普通法世界，传统上判例是主要渊源，制定法虽日益重要但在概念上处于次要地位；在大陆法国家，分析通常从民法典开始，但也不否认判例与特别制定法（如消费者保护法）的作用。\n\n判例制度的核心概念是遵循先例（stare decisis）：法院受先前判决约束。先例（precedent）中，判决理由（ratio decidendi）具有约束力，附带意见（obiter dicta）则否。成文法制度的核心则是法典化（codification）——把法律系统编纂为清晰、连贯、自足的法典。\n\nSiems 强调，判例与成文法的区分是理解两大法系法律方法、法院角色与法学教育的关键，但这一区分本身是理想类型，需要细致辨析。", "history": "判例法的形成与英格兰普通法的历史同步。Siems 指出，1066 年后，法官逐渐撰写详尽判决，把令状的程序性 origins 转化为实体规则，判例由此成为法律的主要载体；先例的约束力保障一致性，同时『从个案到个案的推理』使法律能适应变迁。Maitland 关于『诉讼形式在坟墓中统治我们』的名言，正反映了判例传统的历史深度。\n\n成文法与法典化的高峰则在十九世纪的大陆。Siems 指出，大陆主要法典（民商、刑事、民诉、刑诉）在十九世纪涌现，承启蒙运动理想，追求清晰、系统、自足。法国 1804 年民法典、德国 1900 年民法典是代表。值得注意的是，普通法国家也有法典化——美国 David Dudley Field 的民事诉讼法典、统一商法典（UCC）等——但 Siems 指出，普通法的法典化多为对既有判例的整合，与大陆法法典的体系化理想不同。", "principle": "判例制度与成文法制度的运作逻辑可从四层理解。\n\n第一，法律渊源的地位。普通法以判例为主、制定法为辅；大陆法以法典为主、判例非渊源。但 Siems 指出，这一区分已松动：大陆法主要法典不再是最重要的渊源，普通法则进入『成文法时代』(age of statutes)。\n\n第二，推理方式。普通法法官从个案到个案推理，注重事实细节，先例的识别依赖区分事实差异与提炼判决理由；大陆法法官以三段论推理，从抽象规则出发涵摄事实。Siems 指出，普通法的判决详尽、归纳、实用，大陆法的判决演绎、抽象、注重原则。\n\n第三，先例的运作。MacCormick 与 Summers 主持的比较研究（基于各国报告）发现：普通法法院详细讨论先例以识别判决理由、仔细考量事实；大陆法法院则倾向于把裁判化约为法律原则，事实在未来案件中不发挥作用，且常需寻找一系列判决才确认某项裁判路径。研究也发现两大法系出现一定趋同，但差异仍在。\n\n第四，制定法的解释。Siems 指出，普通法传统上有字面规则（literal rule）、黄金规则（golden rule）、瑕疵规则（mischief rule）等解释方法，且因制定法被视为例外，解释较窄；大陆法则有启示法、目的论方法等。但 Vogenauer 对法国、德国、英格兰制定法解释的比较研究显示，三国虽起点不同，实际使用相似的正式与价值导向论证组合。", "viewpoints": "关于判例与成文法的关系，Siems 综合主流观点：普通法的判例制度强化了法律的适应性与一致性，法院通过区分事实与提炼判决理由，在无综合法典的情况下实现法律发展；大陆法的成文法制度强调法的安定性、可预测性与立法者意志的尊重。\n\n但 Siems 强调，把两者绝对化是错误的。他引用 Martin Shapiro 的观点，认为『大陆法法官简单机械适用完备自明规则』的假定是『根本错误的』；Markesinis 与 Fedtke 也指出，把大陆法官的职能描述为『狭窄、机械、无创造性』并不准确，他们在一般条款（如善意原则）的适用中同样增量地发展法律。反之，Kötz 指出，普通法法官也在宽泛原则下运作，实务者最终仍须查阅先例。", "comparison": "判例制度与成文法制度的对照可从多个维度展开。\n\n在渊源上，判例对法典；在推理上，归纳类比对方法条涵摄三段论；在法官角色上，造法者对适用者；在判决风格上，详尽说理对简洁抽象；在先例效力上，正式约束对非渊源（但有说服力）。\n\n但趋同同样明显：大陆法中存在使最高法院判决有约束力的特别法，判例的实践性权威（persuasive authority）被承认；普通法中制定法数量激增，司法解释从字面转向立法史与目的。Siems 引用 Duncan Kennedy 的『法律思想三次全球化』理论：古典法律思想（以德国法律科学为基础）、社会（以法国对实证主义限制的学术为驱动）、政策分析（美国法律学术）——说明法律思想早已跨越法系边界。", "debates": "判例与成文法制度的经典争论，是『大陆法判例是否真正具有约束力』。传统观点认为，大陆法判决不具正式约束力、判例非法源——在法国，拿破仑法典正是为防止法官造法而设计；在德国，法学传统的强大也在促进全国统一，无需约束性先例。\n\n但 Siems 指出，这幅图景并不完整：一些大陆法国家有特别法使最高法院裁判具有约束力；上级法院裁判在实践中具有的说服力，可被视同先例。不过 MacCormick 与 Summers 的研究表明，差异依然存在：普通法法院详细讨论先例并考量事实，大陆法法院则化约为原则、较少关注事实细节。\n\n这一争论的深层，是法的安定性（成文法所长）与个案适应（判例所长的权衡。Siems 的立场是：两大法系在渊源与推理上确有差异，但都发展出处理法律确定性与灵活性张力的机制，差异是程度而非类别上的。", "case": "UCC（统一商法典）是普通法成文法化的典型例子。Siems 指出，UCC 由 Karl Llewellyn 等人主导起草，被美国各州几乎无修改地采纳，其起草风格受大陆法影响。但 Siems 强调，UCC 是例外——普通法国家的法典化多为对既有判例的整合，而非大陆法式的体系化重构。\n\n另一案例是德国民法典。Siems 指出，它被视为学者法的产物，潘德克顿学派『写就了』法典；但今天德国法院通过一般条款与判例发展法律，法学家与法官的互动使成文法制度保持活力。", "caseAnalysis": "以 MacCormick 与 Summers 的先例研究为例：事实是，该研究基于各国报告，比较普通法与大陆法国家先例的运作。争议焦点是：两大法系在先例上的差异是否正在消失？\n\n研究发现：总体上出现趋同，但差异仍在——普通法法院详细讨论先例、识别判决理由、仔细考量事实；大陆法法院则把裁判化约为法律原则，事实在未来案件中不发挥作用，且常需一系列判决才确认路径。德国联邦宪法法院等甚至有特别法赋予判决约束力。\n\n这一案例的理论意义在于：它用经验材料纠正了简单的二元叙述——既否认『大陆法完全无先例』的误解，也否认『两大法系已无差别』的夸大。它说明，比较法必须通过细致的制度比较，而非口号式的标签，来把握法律渊源的真相。", "summary": "判例法与成文法制度是两大法系的核心差异，但远非『二选一』。普通法以判例为主要渊源、遵循先例、归纳推理、法官造法；大陆法以法典为主要渊源、演绎推理、法官适用法律。先例中判决理由有约束力、附带意见无；MacCormick 与 Summers 的研究显示普通法详细讨论先例与事实、大陆法化约为原则。但现实出现显著趋同：大陆法判例作用上升，普通法进入成文法时代，司法解释方法相互靠拢。Siems 强调，两大法系都发展出平衡确定性与灵活性的机制，差异是程度而非类别的；理解这一点，是把握比较法律制度的关键。", "furtherThinking": "1. 若一个大陆法国家的判例在实践中具有事实上的约束力，它是否仍属于『成文法制度』？\n2. UCC 这类普通法法典，与法国民法典在起草理念上有何根本不同？\n3. MacCormick 与 Summers 的研究方法（基于国别报告的比较）有何优点与局限？"}, "en": "Case Law and Statutory Law Systems", "level": "core", "tags": "判例法, 成文法, 遵循先例, 法典化, 法律渊源", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M6K2"}, "S2M6K3": {"title": "合同制度比较", "EN": "Comparative Contract Law", "LEVEL": "core", "TAGS": "合同法, 对价, 善意, 实际履行, 违约金", "TERMS": "对价（Consideration）::普通法中合同成立所需的价值交换要素；意思表示合意（Meeting of Minds）::大陆法强调的合同主观要素；善意（Good Faith）::大陆法的一般合同原则，普通法中争议较大；实际履行（Specific Performance）::要求违约方按约履行的救济方式；有效违约（Efficient Breach）::普通法允许以赔偿代替履行的经济逻辑；缔约过失（Culpa in Contrahendo）::合同成立前的过失责任；罚金条款（Penalty Clause）::约定违约时支付款项的条款；预定损害赔偿（Liquidated Damages）::对损失的真诚预先估计", "SOURCE": "Siems, Comparative Law, ch.2 (Comparative contract law)；ch.3", "terms": [{"term": "对价（Consideration）", "def": "普通法中合同成立所需的价值交换要素"}, {"term": "意思表示合意（Meeting of Minds）", "def": "大陆法强调的合同主观要素"}, {"term": "善意（Good Faith）", "def": "大陆法的一般合同原则，普通法中争议较大"}, {"term": "实际履行（Specific Performance）", "def": "要求违约方按约履行的救济方式"}, {"term": "有效违约（Efficient Breach）", "def": "普通法允许以赔偿代替履行的经济逻辑"}, {"term": "缔约过失（Culpa in Contrahendo）", "def": "合同成立前的过失责任"}, {"term": "罚金条款（Penalty Clause）", "def": "约定违约时支付款项的条款"}, {"term": "预定损害赔偿（Liquidated Damages）", "def": "对损失的真诚预先估计"}], "sections": {"coreQuestion": "合同法是比较法最经典的领域之一。Siems 指出，各法律体系在合同成立、不履行与救济等基本问题上既有共同划分，又差异足够有趣，因此成为比较法的热门题材。为什么普通法要求『对价』(consideration)，大陆法却以『意思表示合意』为核心？为什么大陆法以实际履行为原则、普通法以损害赔偿为原则？为什么『善意』在大陆法是不言而喻的原则，在英格兰法却长期被拒斥？本节比较两大法系合同法的核心差异，并借助功能主义视角考察不同制度如何达成相近结果。", "definition": "合同制度比较，是对不同法律体系中合同成立、效力、履行、违约救济等规则的对照研究。Siems 指出，比较合同法著作通常以普通法与大陆法的划分为主线，重点聚焦英格兰、法国与德国法。\n\n核心概念包括：对价（consideration）——普通法中合同成立需有当事人交换有价值之物，赠与因而缺乏对价；意思表示合意（meeting of minds）——大陆法强调合同的主观要素；善意（good faith）——大陆法的一般原则；实际履行（specific performance）与损害赔偿（damages）——两种主要救济；罚金条款（penalty clause）与预定损害赔偿（liquidated damages）——普通法对违约金的两分。\n\nSiems 强调，虽然起点不同，但两种制度的结果『往往相似』——这是功能比较的关键洞见。", "history": "合同制度的差异有深厚的历史根源。Siems 指出，普通法合同法以判例为起点、制定法起日益重要但概念上次要的作用；大陆法分析则从民法典开始，也不否认判例与特别制定法（如消费者保护法）的作用。学者在大陆法合同法中扮演重要角色——『法国合同法中的学者，犹如英格兰合同法中的法官』。\n\n在学理层面，Siems 指出，大陆法合同法的主观解释、善意原则等，被联系到康德的个人意志自由与责任原则以及自然法思想；普通法合同法则强调结果的可预测性。Kahn-Freund 的名言概括了社会经济背景的差异：『英格兰合同法是为 shopkeepers 之国设计的』，『法国制度是为 peasants 设计的』——Siems 指出，这反映了英格兰法院受理更多航运、国际贸易与金融服务案件，在个案正义与交易安全之间偏向后者。", "principle": "合同制度的比较可从四个核心主题展开。\n\n第一，合同成立。Siems 指出，大多数合同通过要约与承诺订立，这是两大法系的共同起点。但概念层面，普通法以客观方式定义合同——要求交换承诺（exchange of promises）；大陆法则更强调主观的意思表示合意。合同解释上，普通法为法律确定性采客观起点，大陆法则偏好当事人意图。然而 Siems 强调，两种方法都不纯粹，最终结果往往相似。\n\n第二，对价与赠与。普通法有对价原则——有效合同需交换有价值之物，不要求公平充分，但无对价（尤其赠与）不能构成合同；赠与虽被承认，但须以契据（deed）形式使其有约束力。大陆法无对价问题，把赠与视为合同，但民法典常要求公证（notarial deed）等形式。Sacco 关于英法律师讨论赠与合同的著名例子表明：英法律师会说，正式赠与在英格兰有效是因『它不是合同、不受对价约束』，在法国有效是因『它是合同、因而有约束力』——操作规则相似，教义装置却完全相反。\n\n第三，善意与缔约前义务。大陆法有一般善意原则：德国民法典第 311 条第 2 款把缔约前关系纳入债的关系，使善意适用于缔约过失；法国依侵权法、荷兰依公平原则处理缔约责任。普通法中善意是争议话题：1766 年 Mansfield 勋爵曾称善意是支配原则，但 1992 年 Walford v Miles 案中 Ackner 勋爵反对；其主要替代机制是默示条款、对显失公平交易的衡平救济与消费者保护立法。Teubner 把善意移植到普通法称为『法律刺激物』，Siems 则指出善意只是『较弱的解释工具』。\n\n第四，救济。在实际履行上，大陆法以履行为原则——『买受人要的是那匹马，损害赔偿权替代不了它』；普通法相反，Holmes 说普通法上守约义务只是『不守约就赔钱』的预测，因而允许『有效违约』(efficient breach)，但有例外（美国 UCC §2-716 对独特物品可判实际履行；英国 Co-operative Insurance v Argyll Stores [1998]）。在过错要件上，德国民法典第 280 条第 1 款通常要求过错，法国法区分合同类型、仅在不可抗力时排除责任，普通法以严格责任为起点（1945 年 Alderslade v Hendon Laundry 案）。在违约金上，大陆法原则上允许并可调整（德国 §343 可减，法国第 1152 条可增减），普通法则因对价理论区分无效的罚金条款与有效的预定损害赔偿（Dunlop Pneumatic Tyre v New Garage [1915]）。", "viewpoints": "关于合同制度的差异，Siems 综合主流观点：普通法合同法的核心特征是强调结果的可预测性——偏好客观解释、拒绝善意原则、限制实际履行；大陆法合同法的主观解释与善意原则，则被联系到康德的个人意志自由与自然法思想。\n\n但 Siems 强调，差异不宜夸大。Common Core 项目研究了欧洲法律体系解决三十个善意案例的情况：十一个得到相同结果，九个大体和谐但不完美，十个出现显著分歧，英格兰法『常常但并非总是』走自己的路。这一经验材料说明，功能上的趋同与教义上的差异并存。", "comparison": "合同制度的对照可从多维度展开。\n\n在渊源上，普通法以判例为主、大陆法以法典为主；在合同概念上，客观交换承诺对主观意思合意；在解释上，客观标准对当事人意图；在善意上，争议拒斥对一般原则；在履行救济上，损害赔偿对实际履行；在过错上，严格责任对过错要求；在违约金上，罚金/预定损害赔偿两分对允许并调整。\n\n但这些对照是理想类型。Siems 指出，许多中间方案存在：普通法通过默示条款与衡平救济达致公平；大陆法也重视合同自由、市场与当事人对立的立场。德国法中，善意并非道德说教，也不赋予法官无拘束裁量，法院用它发展可靠适用的规则类别。", "debates": "合同法最经典的争论之一，是善意原则能否移植到普通法。Teubner 把善意移植到普通法称为『法律刺激物』(legal irritant)，认为这种抽象开放的原则是『大陆法律文化的独特表达』。Siems 援引的研究显示，在英美法院实践中，善意只是『一个较弱的解释工具』，尤其不被用于确立缔约前的义务。\n\n但大陆法方面也需要警惕夸大善意的作用。Siems 指出，在德国，合同自由、当事人对立立场与市场经济才是合同法的主要原则，善意只在例外情形下让位于其他政策理由；德国法院运用善意，是为了发展可靠适用的规则，而非在个案中用『更公平』取代合同或法律的后果。这一争论说明，比较法必须同时看到『原则的表述』与『实际的运作』。", "case": "实际履行的差异是典型案例。Siems 引用一句谚语：大陆法『买受人要的是那匹马，损害赔偿权替代不了它』——意即履行请求权是核心。普通法则如 Holmes 所言，守约义务只是『不守约就赔钱』的预测，故允许有效违约。但例外存在：美国 UCC §2-716 允许在物品独特或其他适当情形下判实际履行；英国上议院 1998 年 Co-operative Insurance Society v Argyll Stores 案则拒绝强制履行经营义务。\n\nSiems 指出，普通法允许有效违约有经济论据支持——它使资源能流向更高价值的用途。但两大法系在实践中可能殊途同归：当标的物独特或损害赔偿不足时，普通法也会给予实际履行。", "caseAnalysis": "以 Alderslade v Hendon Laundry [1945] 案为例：事实是，洗衣公司未能洗好客户衣物，辩称已尽合理注意。法院指出，洗衣公司承担的是『洗好衣物』的义务，而非『尽合理注意洗衣物』的义务，未能洗好即须负责，不以尽到注意为抗辩。\n\n争议焦点是：违约责任是否以过错为要件？Siems 指出，普通法合同责任的起点是严格责任；洗衣案正是这一立场的体现。而大陆法（尤其德国民法典第 280 条第 1 款）通常要求过错，但常有举证责任转移；法国法更常区分合同类型，仅在不可抗力时排除责任。\n\n这一案例的理论意义在于：它展示了普通法与大陆法在违约责任起点上的根本差异——严格责任对过错责任。但 Siems 提醒，这只是起点：两大法系都有中间方案（调整举证责任、客观注意标准、区分合同类型），结果常常相似。功能比较因此必须既看起点，也看最终效果。", "summary": "合同制度比较显示，两大法系在合同成立、善意、救济等方面存在系统差异：普通法强调客观、对价、结果可预测性、严格责任与损害赔偿；大陆法强调主观合意、善意、过错责任与实际履行。Sacco 的赠与例子说明操作规则可能相似而教义装置相反；Alderslade 案与 UCC 则分别体现严格责任与实际履行的例外。Siems 以 Common Core 研究说明功能趋同与教义差异并存：三十个善意案例中结果有同有异。Teubner 的『法律刺激物』与对德国善意实践的分析提醒我们，必须区分原则的表述与实际的运作。理解合同法，需在具体规则与功能效果之间往返。", "furtherThinking": "1. Sacco 的赠与例子说明『操作规则相似而教义装置相反』，这对功能比较方法有何启示？\n2. 普通法允许『有效违约』，大陆法以实际履行为原则，这两种立场各反映了怎样的经济与社会假设？\n3. 善意原则在德国法中被『操作化』为可靠规则，这一经验对完善中国合同履行规则有何借鉴？"}, "en": "Comparative Contract Law", "level": "core", "tags": "合同法, 对价, 善意, 实际履行, 违约金", "source": "Siems, Comparative Law, ch.2 (Comparative contract law)；ch.3", "id": "S2M6K3"}, "S2M6K4": {"title": "财产权制度比较", "EN": "Comparative Property Law", "LEVEL": "core", "TAGS": "财产权, 所有权, 物权法定, 信托, 用益", "TERMS": "财产权/物权（Property Rights）::对物享有并可由法律保护的支配权；所有权（Ownership）::对物最全面的支配权；物权法定（Numerus Clausus）::物权种类由法律限定、当事人不得自由创设的原则；信托（Trust）::普通法中受托人为受益人管理财产的制度；用益权（Usufruct）::大陆法中他人之物上设定的使用收益权利；先占（Occupation）::通过占有无主物取得所有权的方式；登记（Registration）::不动产权利变动的公示方式", "SOURCE": "Siems, Comparative Law, ch.2, ch.3, ch.7", "terms": [{"term": "财产权/物权（Property Rights）", "def": "对物享有并可由法律保护的支配权"}, {"term": "所有权（Ownership）", "def": "对物最全面的支配权"}, {"term": "物权法定（Numerus Clausus）", "def": "物权种类由法律限定、当事人不得自由创设的原则"}, {"term": "信托（Trust）", "def": "普通法中受托人为受益人管理财产的制度"}, {"term": "用益权（Usufruct）", "def": "大陆法中他人之物上设定的使用收益权利"}, {"term": "先占（Occupation）", "def": "通过占有无主物取得所有权的方式"}, {"term": "登记（Registration）", "def": "不动产权利变动的公示方式"}], "sections": {"coreQuestion": "财产权制度是两大法系差异与趋同并存的又一领域。一个常被提及的说法是：大陆法有物权法定原则、普通法有信托制度，两者似乎南辕北辙。但 Siems 指出，普通法与大陆法『在它们允许的类信托安排的类型上并无根本不同』。那么，财产权制度比较应如何进行？信托真的是普通法独有的吗？物权法定原则在两大法系中地位如何？本节比较财产权的核心制度，并借助功能主义视角理解不同法系如何回应相似的财产与交易需求。", "definition": "财产权（property rights）指对物享有并可由法律保护的支配权。两大法系在财产权的基本问题上共享一些划分——如所有权（ownership）与他物权的区分、不动产与动产的区分、取得与转让的方式——但在具体制度设计上差异显著。\n\n核心概念包括：物权法定（numerus clausus）——大陆法中物权种类由法律限定、当事人不得自由创设的原则；信托（trust）——普通法中受托人（trustee）为受益人（beneficiary）管理财产的制度，具有『普通法所有权与衡平法所有权分离』的结构；用益权（usufruct）——大陆法中在他人之物上设定的使用收益权利；先占（occupation）——通过占有无主物取得所有权；登记（registration）——不动产权利变动的公示方式。\n\nSiems 强调，信托常被误认为普通法独有，但功能比较显示大陆法也有类似的财产管理安排。", "history": "财产权制度的差异有深刻的历史根源。Siems 指出，大陆法的财产权概念深受罗马法影响，所有权被理解为对物的绝对支配，物权体系以所有权的分解与限制为特征；物权法定原则保障了物权种类的明确与交易安全。\n\n普通法的财产权则与封建土地制度密切相关。1066 年诺曼征服后，威廉一世以封建土地所有制与令状体系构建土地权利，形成了复杂的地产权（estates）体系。信托则源于中世纪英格兰的『用益』(use) 制度——为规避封建负担与限制，人们将财产转移给受托人管理，衡平法逐渐保护受益人的权益，形成普通法所有权与衡平法所有权并存的独特结构。Siems 指出，Glenn 在描述英格兰法时，甚至提到信托法的罗马渊源（罗马法中的 fideicommissum），说明信托并非纯粹『土生土长』。", "principle": "财产权制度的比较可从四个层面展开。\n\n第一，所有权的观念。大陆法的所有权强调对物的直接、绝对支配，物权体系围绕所有权展开；普通法则发展出封建的地产权体系与所有权的时空分割。Siems 指出，这影响了两者对财产的保护与交易方式。\n\n第二，物权法定与类型自由。大陆法的物权法定原则（numerus clausus）限定物权种类，保障交易安全与公示；普通法虽无严格对应的原则，但通过判例与法定的权益类型，也限制了当事人可创设的财产权益种类。功能上，两者都在处理『物权类型明确性』与『当事人自治』的张力。\n\n第三，信托与功能等价物。Siems 指出，信托是普通法的独特制度——受托人为受益人管理财产，实现所有权与受益权分离。但大陆法也有功能相近的安排：如大陆法的用益权、财团法人、以及为特定目的设立的财产管理机制。Siems 明确表示，普通法与大陆法『在它们允许的类信托安排的类型上并无根本不同』，只是概念化方式不同。这是功能比较的绝佳例证。\n\n第四，公示与取得。两大法系都发展出不动产登记制度、动产交付与先占等规则。Siems 指出，财产权的取得与转让规则，各法系往往有功能相近但技术不同的设计。", "viewpoints": "关于财产权制度的比较，Siems 采取功能主义的立场：虽然概念与教义不同，但不同法系回应相似的财产需求——如财产分割管理、投资工具、担保交易——时，往往发展出功能等价的制度。信托与大陆法的类信托安排，正是这种功能等价的典型。\n\nSiems 同时提醒，功能比较不能抹平差异。信托的『双重所有权』结构（普通法所有权与衡平法所有权）在大陆法的物权体系中找不到精确对应，直接移植会遭遇概念障碍。这与他在法律移植一章中的立场一致：法律规则的意义依赖其所在的体系语境。", "comparison": "财产权制度的对照可从多维度展开。\n\n在所有权观念上，大陆法的绝对支配对普通法的地产权分割；在物权类型上，法定限定对判例发展；在财产管理上，大陆法的用益权、财团对普通法的信托；在公示上，登记制度的细节各异；在概念化上，大陆法的物权体系对普通法的普通法/衡平法双重结构。\n\n但这些对照是理想类型。Siems 强调功能视角：信托与大陆法类信托安排、物权法定与普通法的权益类型限制，都在处理相似问题。差异更多在于『如何概念化』，而非『能否实现』。", "debates": "财产权领域的一个经典争论，是信托能否移植到大陆法国家。乐观者认为信托是一种灵活的财产管理工具，可带来经济效率；怀疑者指出，信托的『双重所有权』结构与大陆法的所有权绝对性、物权法定原则格格不入，移植后会变形。\n\nSiems 的立场延续其一贯的审慎：信托的功能（财产分割管理、保护受益人）在大陆法中可通过其他制度实现，但作为概念的『信托』直接移植会遭遇教义障碍。他引用 Glenn 关于信托罗马渊源的讨论，说明信托并非与大陆法毫无历史关联。这一争论呼应全书的主题：移植的成败取决于是否与本土体系兼容。", "case": "信托的跨法域传播是典型案例。Siems 指出，一些大陆法国家（如通过 1985 年《海牙信托公约》）开始承认信托，但将其纳入本土法律框架时遇到概念困难——如何把『普通法所有权与衡平法所有权分离』翻译成大陆法的物权语言？这一困难正体现了 Siems 关于移植的观点：规则的文字可以搬运，但其意义依赖解释者的认知框架。\n\n另一个例子是物权法定（numerus clausus）原则在两大法系的体现。Siems 指出，普通法通过判例发展的权益类型（如地产权的各种形态）事实上也限制了当事人可创设的物权种类，与大陆法的物权法定有功能相似性。", "caseAnalysis": "以信托移植为例：事实是，信托作为普通法的财产管理制度，被引入若干大陆法法域，但其『双重所有权』结构与大陆法物权体系存在张力。争议焦点是：信托能否在不改变大陆法基本概念的前提下被成功移植？\n\n从功能视角看，信托的实质功能——财产管理、受益人保护、所有权与利益分离——在大陆法中可通过财团法人、用益权等实现。从教义视角看，信托的普通法/衡平法所有权二分在大陆法中缺乏对应范畴，直接移植会造成体系冲突。\n\nSiems 的分析框架提示，答案取决于我们比较的是功能还是概念。他明确表示两大法系在类信托安排上并无根本不同，这支持功能主义的乐观判断；但他对法律移植的整体审慎态度，又提醒我们注意概念翻译的困难。\n\n这一案例的理论意义在于：它展示了财产权比较中功能与教义两个层面的张力，也说明比较法必须在两者之间保持自觉。", "summary": "财产权制度比较显示，两大法系在所有权观念、物权类型、财产管理与公示方式上差异显著：大陆法强调所有权绝对支配与物权法定，普通法发展出封建地产权体系与独特的信托制度。但 Siems 强调，信托并非普通法独有——两大法系在类信托安排上并无根本不同，功能比较揭示了不同概念化方式背后相似的财产管理需求。信托移植的案例说明，功能的等价不等于概念的兼容，移植的成败取决于与本土体系的契合。理解财产权制度，须在功能与教义两个层面之间往返，避免标签化的二元对立。", "furtherThinking": "1. 信托的『双重所有权』结构为何难以被大陆法物权体系接纳？这对法律移植有何启示？\n2. 物权法定原则在两大法系中功能相似而形式不同，这说明了什么？\n3. 若要用功能主义方法比较两大法系的担保交易制度，你会从哪些问题入手？"}, "en": "Comparative Property Law", "level": "core", "tags": "财产权, 所有权, 物权法定, 信托, 用益", "source": "Siems, Comparative Law, ch.2, ch.3, ch.7", "id": "S2M6K4"}, "S2M6K5": {"title": "侵权责任制度比较", "EN": "Comparative Tort Law", "LEVEL": "core", "TAGS": "侵权责任, 过失, 严格责任, 因果关系, 损害赔偿", "TERMS": "侵权法（Tort Law）::调整因侵害他人权益而生赔偿责任的私法部门；过失责任（Fault Liability）::以行为人过错为要件的责任；严格责任（Strict Liability）::不以过错为要件的责任；因果关系（Causation）::行为与损害之间的因果联系；可预见性（Foreseeability）::普通法限定责任范围的概念；一般条款（General Clause）::大陆法民法典中的概括性责任条款；侵权法功能（Functions of Tort Law）::补偿、威慑与惩罚等目标", "SOURCE": "Siems, Comparative Law, ch.2, ch.5, ch.7", "terms": [{"term": "侵权法（Tort Law）", "def": "调整因侵害他人权益而生赔偿责任的私法部门"}, {"term": "过失责任（Fault Liability）", "def": "以行为人过错为要件的责任"}, {"term": "严格责任（Strict Liability）", "def": "不以过错为要件的责任"}, {"term": "因果关系（Causation）", "def": "行为与损害之间的因果联系"}, {"term": "可预见性（Foreseeability）", "def": "普通法限定责任范围的概念"}, {"term": "一般条款（General Clause）", "def": "大陆法民法典中的概括性责任条款"}, {"term": "侵权法功能（Functions of Tort Law）", "def": "补偿、威慑与惩罚等目标"}], "sections": {"coreQuestion": "侵权法是比较法中一个耐人寻味的领域：两大法系在基本功能上高度一致——补偿受害人、威慑不当行为——却在制度技术上走了不同的路。普通法由一个个独立侵权类型（如 negligence、trespass）构成，大陆法则有民法典中的一般条款（如法国民法典第 1382 条、德国民法典第 823 条）。Siems 在社会法学章节中比较侵权法，并讨论诉讼率、责任扩张等经验问题。本节比较两大法系侵权法的结构、归责原则与责任范围，并考察侵权法的社会功能。", "definition": "侵权法（tort law）是调整因侵害他人权益而产生的赔偿责任的私法部门。Siems 指出，在世界范围内，侵权法是各法律体系共享的基本私法领域之一——它们『把私法划分为财产、侵权与合同等大领域，并以相似方式分析这些领域』。\n\n核心概念包括：过失责任（fault liability，以过错为要件）与严格责任（strict liability，不以过错为要件）；因果关系（causation，行为与损害的因果联系）；可预见性（foreseeability，普通法限定责任范围的概念）；一般条款（general clause，如法国民法典第 1382 条『任何人因过错致他人损害应负赔偿责任』、德国民法典第 823 条）；以及侵权法的功能——补偿、威慑、惩罚。\n\nSiems 强调，两大法系在侵权法上的差异是结构与概念层面的，功能上则高度相通。", "history": "侵权法的形成与各国法律发展路径相关。普通法的侵权法由令状体系演变而来，形成了 trespass（直接侵害）、case（间接损害）等独立的诉讼形式，后发展出过失（negligence）这一统一原则，但保留各类侵权类型的分立。从业经验主义色彩浓厚，法官通过个案发展规则。\n\n大陆法的侵权法则深受罗马法《阿奎利亚法》(Lex Aquilia) 与自然法思想影响，近代民法典以概括性一般条款统摄各类侵权。法国民法典第 1382 条以过错责任为单一一般条款；德国民法典第 823 条则区分对绝对权的侵害（第 823 条第 1 款）与违反保护他人法律（第 823 条第 2 款），结构更为精细。Siems 指出，两大类法系的差异——法国法与德国法在侵权法上的不同——是大陆法内部多样性的体现。", "principle": "侵权法的比较可从四个层面展开。\n\n第一，体系结构。普通法侵权法是『类型化』的——由 negligence、trespass、nuisance、defamation 等独立侵权构成，各有要件；大陆法侵权法则以一般条款统摄，通过判例与学说发展出细致的区分。Siems 指出，这种结构差异影响了法律思维：普通法从个案类推，大陆法从一般原则演绎。\n\n第二，归责原则。Siems 指出，两大法系都经历从过失责任到严格责任扩展的过程。普通法中，Rylands v Fletcher 案确立了高度危险活动的严格责任；大陆法中，各国通过特殊侵权类型（如产品责任、环境责任）发展严格责任。Siems 在社会法学章节讨论比较侵权法，并提到责任扩张的趋势。\n\n第三，责任范围。普通法通过可预见性（foreseeability）、因果关系等概念限定责任范围——著名的『蛋壳头骨』规则（受害人特殊体质不影响责任）与 Palsgraf 案（可预见性与责任范围）是其体现。大陆法则通过因果关系、过错、法规目的等理论限定责任。\n\n第四，社会功能。Siems 指出，侵权法的功能包括补偿、威慑与损失分散；不同法系对功能各有侧重。美国侵权法因陪审团、风险代理与集体诉讼等因素，惩罚性赔偿与责任扩张更为显著；Siems 提到美国侵权法在隐私等领域更具保护性，刑罚更严厉、社会保险较弱。", "viewpoints": "关于侵权法的比较，Siems 强调功能主义视角：两大法系在基本任务上一致——为损害提供救济、分配损失、威慑不当行为——差异主要在于实现这些任务的概念工具。功能比较因此能把不同类型的规则拉到同一问题平面。\n\n但 Siems 也提醒，侵权法的运作深受社会语境影响。他在社会法学章节讨论诉讼率与法律文化——美国、英格兰、德国、荷兰、日本的诉讼率差异显著——说明侵权法的实际效果不能脱离司法制度与社会文化来理解。", "comparison": "侵权法的对照可从多维度展开。\n\n在体系结构上，普通法的类型化侵权对大陆法的一般条款；在推理方式上，个案类推对原则演绎；在归责原则上，过失与严格责任的混合对类似但表述不同的结构；在责任限定上，可预见性对法规目的与因果关系理论；在社会功能上，补偿威慑的共同目标与不同侧重。\n\n但这些对照是理想类型。Siems 指出，功能上高度相通：产品责任、交通事故、医疗损害等现代问题中，两大法系都发展出相近的救济机制；差异更多在于教义表述与制度环境。", "debates": "侵权法领域的一个经典争论，是侵权法的首要功能——补偿还是威慑。补偿论者强调填补受害人损失；威慑论者强调通过责任促使行为人采取预防措施；还有学者强调损失分散（通过保险等机制）。Siems 指出，不同法系对这些功能各有侧重，美国法更强调惩罚与威慑（惩罚性赔偿、集体诉讼），大陆法与英格兰法更侧重补偿。\n\n另一个争论是责任扩张的限度。Siems 在社会法学章节提到，侵权法经历了责任扩张的趋势，但也引发关于『诉讼爆炸』与『赔偿文化』的担忧，尤其在 American exceptionalism 的语境下。", "case": "美国侵权法的独特性是 Siems 反复提及的案例。他指出，由于陪审团审判、风险代理（contingency fee）、集体诉讼（class actions）与『诉讼人激进主义』(litigant activism)，美国的侵权诉讼在范围与赔偿额上都更为突出；惩罚性赔偿、对隐私的强保护是其表现。Kagan 的『对抗性法治主义』(adversarial legalism) 正是对美国法律风格的概括。\n\n与之相对，Siems 提到德国、日本等国诉讼率较低，社会保险在损失补偿中扮演更大角色。这些差异说明，侵权法的实际运作与一国的司法制度、保险体系、法律文化紧密相关——这正是社会法学方法要揭示的。", "caseAnalysis": "以产品责任为例：事实是，各国对产品缺陷致害都发展出严格责任或近似机制，但形式不同——美国通过判例与 Restatement 发展严格产品责任，欧洲通过产品责任指令（体现大陆法传统）统一规则。争议焦点是：这些制度在功能上是否等价？\n\n从功能视角看，各国都以保护消费者、分配产品风险为目标，功能高度相通；从教义视角看，普通法通过判例发展、大陆法通过指令与民法典，路径各异。Siems 的社会法学视角进一步提示，法律的实际效果还取决于诉讼制度与保险安排——美国的高诉讼率与风险代理放大了侵权责任的实际影响。\n\n这一案例的理论意义在于：它展示了功能比较与社会法学方法的互补——前者揭示规则的趋同，后者揭示规则运作的制度环境。理解侵权法，必须同时看规则与社会。", "summary": "侵权法是比较法中功能相通而结构有别的典型领域。普通法以类型化侵权与个案类推为特征，通过可预见性等概念限定责任；大陆法以民法典一般条款与原则演绎为特征，通过过错、因果关系与法规目的限定责任。两大法系都经历从过失责任到严格责任的扩展，在补偿、威慑、损失分散等功能上各有侧重。Siems 以社会法学方法揭示，侵权法的实际运作深受诉讼率、陪审团、风险代理、保险体系等制度环境的影响——美国侵权法的独特性正是其例。比较侵权法，须在功能、教义与社会语境三个层面同时展开。", "furtherThinking": "1. 普通法的类型化侵权与大陆法的一般条款，各有什么优缺点？\n2. 美国侵权法的『诉讼人激进主义』与其司法制度、保险体系有何关联？\n3. 侵权法的补偿、威慑、损失分散三大功能之间是否存在张力？如何在制度设计中平衡？"}, "en": "Comparative Tort Law", "level": "core", "tags": "侵权责任, 过失, 严格责任, 因果关系, 损害赔偿", "source": "Siems, Comparative Law, ch.2, ch.5, ch.7", "id": "S2M6K5"}, "S2M6K6": {"title": "刑事司法制度比较", "EN": "Comparative Criminal Justice Systems", "LEVEL": "core", "TAGS": "刑事司法, 对抗制, 职权主义, 陪审团, 量刑, 监禁率", "TERMS": "刑事司法（Criminal Justice）::刑事追诉、审判与刑罚执行的制度体系；对抗制（Adversarial System）::控辩双方主导、法官中立裁判的刑事程序；职权主义（Inquisitorial System）::法官主导查明事实的刑事程序；陪审团（Jury）::由公民组成决定有罪与否的审判组织；辩诉交易（Plea Bargaining）::控辩协商以认罪换取较轻处理的机制；监禁率（Incarceration Rate）::被监禁人口占总人口的比例；恢复性司法（Restorative Justice）::强调修复损害与和解的司法模式", "SOURCE": "Siems, Comparative Law, ch.2, ch.5, ch.7", "terms": [{"term": "刑事司法（Criminal Justice）", "def": "刑事追诉、审判与刑罚执行的制度体系"}, {"term": "对抗制（Adversarial System）", "def": "控辩双方主导、法官中立裁判的刑事程序"}, {"term": "职权主义（Inquisitorial System）", "def": "法官主导查明事实的刑事程序"}, {"term": "陪审团（Jury）", "def": "由公民组成决定有罪与否的审判组织"}, {"term": "辩诉交易（Plea Bargaining）", "def": "控辩协商以认罪换取较轻处理的机制"}, {"term": "监禁率（Incarceration Rate）", "def": "被监禁人口占总人口的比例"}, {"term": "恢复性司法（Restorative Justice）", "def": "强调修复损害与和解的司法模式"}], "sections": {"coreQuestion": "刑事司法是法律比较中最能体现制度文化差异的领域之一。美国的刑事司法以高监禁率、辩诉交易与陪审团著称；大陆法国家则强调法官职权、职业法官与较低的监禁率（北欧国家尤为突出）。为什么会有这些差异？Siems 在社会法学章节专门讨论比较刑法，并把政治经济与监禁率的关系作为研究主题。本节比较两大法系刑事司法程序的差异、量刑与刑罚理念，并借助社会法学方法分析监禁率的跨文化差异。", "definition": "刑事司法（criminal justice）指刑事追诉、审判与刑罚执行的制度体系。核心概念包括：对抗制（adversarial system）——控辩双方主导举证质证、法官中立裁判，普通法国家典型；职权主义（inquisitorial system）——法官主导查明事实，大陆法国家传统；陪审团（jury）——由公民组成决定有罪与否；辩诉交易（plea bargaining）——控辩协商以认罪换取较轻处理；监禁率（incarceration rate）——被监禁人口占比；恢复性司法（restorative justice）——强调修复损害与和解。\n\nSiems 指出，刑事司法是法律与社会互动最为鲜明的领域，其运作深受政治、经济与文化因素影响。", "history": "刑事程序的差异有深厚历史根源。普通法的刑事审判围绕陪审团展开，形成了当事人主导、口头、集中审理的对抗制；法官保持中立，事实认定由陪审团负责。Siems 指出，陪审团在美国被视为『文化与民主的关键要素』，至今在刑事审判中广泛使用。\n\n大陆法的刑事程序则源于罗马—教会法的职权传统，强调由法官（或预审法官）依职权查明事实，追求实质真实；陪审团在大陆法国家命运各异——德国 1924 年废除陪审团、代之以参审员（Schöffen），法国在重罪法庭（cour d'assises）仍保留陪审员。Siems 指出，在大陆法中，职业法官与非职业法官组成混合法庭，非职业法官既决定事实也决定法律，与普通法陪审团不同。\n\n近代以来，两大法系出现趋同：人权公约（如《欧洲人权公约》）推动了程序保障的统一；辩诉交易式的协商机制在大陆法国家以不同形式出现；同时美国的对抗制也面临对其效率与公正的反思。", "principle": "刑事司法的比较可从四个层面展开。\n\n第一，程序模式。普通法采对抗制——控辩双方是主角，法官为中立裁判（『邻居帮助争吵双方』），当事人主导举证与质证；证据规则（如排除传闻证据、禁止诱导性提问）因陪审团而发展。大陆法采职权主义——法官主导查明事实，询问证人、指定专家，证据大多可采纳，由法院评估可信度；Siems 指出，大陆法法官被认为比普通法法官『更具管理性』(more managerial)。\n\n第二，事实认定。普通法由陪审团决定有罪与否，法官决定法律问题；大陆法由职业法官与参审员组成的混合法庭共同决定事实与法律。Siems 指出，陪审团在多数普通法国家的民事审判中消失，但在刑事审判中（尤其美国）仍具核心地位。\n\n第三，定罪后的处理。美国广泛采用辩诉交易——绝大多数刑事案件通过认罪协商解决；Siems 指出，这与当事人主导、资源不均与高案件量相关。大陆法传统上对辩诉交易较谨慎，但近几十年出现各种协商机制（如德国的『处罚令』与协商程序）。在量刑上，美国有量刑指南与强制性最低刑，争议不断；大陆法国家量刑相对较轻、较注重比例原则。\n\n第四，社会语境。Siems 在社会法学章节讨论比较刑法，并提及政治经济与监禁率的关系。美国的监禁率在发达国家中异常高，Kagan 指出美国刑罚更严厉、社会保险较弱；北欧国家则以低监禁率与恢复性司法理念著称。这些差异说明，刑罚制度深受社会政策与政治经济影响。", "viewpoints": "关于刑事司法的差异，Siems 综合学界看法：普通法的对抗制强调程序正义、当事人自治与法官中立；大陆法的职权主义强调实质真实、法官查明与效率。两种模式各有价值——对抗制有利于防止国家权力滥用、保障被告权利；职权主义有利于发现真相与统一适用法律。\n\nSiems 强调，这种差异不能脱离社会语境理解。他引用研究指出，刑事司法与政治经济之间存在关联——监禁率的高低与社会政策、经济实力、社会福利水平相关。这体现了社会法学方法的核心：把法律现象放回其社会环境。", "comparison": "刑事司法的对照可从多维度展开。\n\n在程序模式上，对抗制对职权主义；在事实认定上，陪审团对混合法庭；在证据规则上，严格的排除规则对较宽松的可采性；在辩诉交易上，美国的普遍性对大陆法的谨慎引入；在刑罚理念上，美国的严厉高监禁率对大陆法（尤其北欧）的比例原则与恢复性司法。\n\n但这些对照是理想类型，且存在趋同：人权公约推动程序保障统一；协商机制在两大法系扩散；两国都面临监狱过度拥挤、再犯率等共同问题。Siems 强调，比较刑事司法须避免简单标签，关注实际运作与社会效果。", "debates": "刑事司法领域的经典争论，是对抗制与职权主义孰优孰劣。支持对抗制者强调其对被告权利的保护、对控方权力的制约；批评者指出其成本高、效率低、加剧资源不均——美国的高监禁率与辩诉交易的普遍性，被批评为『正义的商品化』。支持职权主义者强调其查明真相的能力与效率；批评者则担心法官权力过大、被告保护不足。\n\nSiems 的立场是审慎的：两种模式各有逻辑、各有得失，且都在改革中相互借鉴；评价须结合具体社会语境。他通过社会法学方法指出，监禁率等实践指标与政治经济因素相关，不能单纯从法律规则推断。", "case": "美国的高监禁率与辩诉交易是最突出的案例。Siems 指出，美国刑事制裁更严厉、社会保险较弱，监禁率在发达国家中异常高；绝大多数刑事案件通过辩诉交易解决，陪审团审判反而成为少数。Kagan 的『对抗性法治主义』概括了这种高度对抗、政治化的法律风格。Siems 还提到大法官 Scalia 对某些分歧的评论，将其归因于英国的影响（此处指特定法律发展中的分歧）。\n\n与之相对，北欧国家的低监禁率与恢复性司法是另一极。Siems 在北欧法律传统与法律与发展章节中多次提及，福利国家模式、社会政策与刑事司法的联系值得关注。这些案例说明，刑事司法制度是理解法律与社会关系的最佳窗口之一。", "caseAnalysis": "以辩诉交易为例：事实是，美国绝大多数刑事案件通过控辩协商、被告人认罪换取较轻处理而解决，正式审判成为例外。争议焦点是：这种机制是效率的选择，还是对程序正义的侵蚀？\n\n支持者认为，辩诉交易在案件量巨大的现实中提供了可行的解决方式，避免审判的资源消耗与不确定性；被告也可获得较轻的处理。批评者指出，它可能导致无辜者认罪、加剧资源不均——贫困被告更易接受不利交易——并使量刑偏离实质正义。\n\nSiems 的分析框架提示，辩诉交易与美国对抗制、陪审团审判的高成本、当事人主导及资源不均的制度环境密切相关；在大陆法国家，职业法官主导、审判成本较低，协商机制的形态与程度也不同。这个案例的理论意义在于：它揭示了刑事程序制度与社会资源、诉讼文化的深层关联，说明比较不能停留在规则文本，而要追问制度的社会功能。", "summary": "刑事司法是比较法中制度文化差异鲜明的领域。普通法采对抗制、陪审团、严格证据规则与当事人主导；大陆法采职权主义、混合法庭、法官查明事实与较宽松的证据规则。美国的辩诉交易、量刑指南与高监禁率，与大陆法（尤其北欧）的比例原则、恢复性司法与低监禁率形成对照。Siems 以社会法学方法揭示，监禁率等实践指标与政治经济、社会政策密切相关，不能单纯从法律规则推断。两大法系的差异是理想类型，且正因人权公约与协商机制扩散而趋同。比较刑事司法，须在程序模式、刑罚理念与社会语境三个层面展开。", "furtherThinking": "1. 对抗制与职权主义各自的优缺点是什么？能否设计一种融合二者优点的混合模式？\n2. 美国的高监禁率与辩诉交易，反映了哪些社会与制度因素？\n3. 恢复性司法理念能否被引入对抗制国家？可能遇到哪些文化障碍？"}, "en": "Comparative Criminal Justice Systems", "level": "core", "tags": "刑事司法, 对抗制, 职权主义, 陪审团, 量刑, 监禁率", "source": "Siems, Comparative Law, ch.2, ch.5, ch.7", "id": "S2M6K6"}, "S2M6K7": {"title": "法律解释方法比较", "EN": "Comparative Legal Interpretation", "LEVEL": "core", "TAGS": "法律解释, 文本主义, 目的解释, 普通法解释规则, 法系比较", "TERMS": "法律解释（Legal Interpretation）::确定法律规范含义与适用范围的活动；字面规则（Literal Rule）::按条文字面含义解释；黄金规则（Golden Rule）::为避免荒谬结果而修正字面含义；瑕疵规则（Mischief Rule）::探求法律欲补救的缺陷；启示法（Exegetical Method）::探求立法者意图的解释方法；目的论方法（Teleological Method）::依据法律客观目的的解释；一般条款（General Clause）::民法典中概括性的原则条款", "SOURCE": "Siems, Comparative Law, ch.2, ch.3", "terms": [{"term": "法律解释（Legal Interpretation）", "def": "确定法律规范含义与适用范围的活动"}, {"term": "字面规则（Literal Rule）", "def": "按条文字面含义解释"}, {"term": "黄金规则（Golden Rule）", "def": "为避免荒谬结果而修正字面含义"}, {"term": "瑕疵规则（Mischief Rule）", "def": "探求法律欲补救的缺陷"}, {"term": "启示法（Exegetical Method）", "def": "探求立法者意图的解释方法"}, {"term": "目的论方法（Teleological Method）", "def": "依据法律客观目的的解释"}, {"term": "一般条款（General Clause）", "def": "民法典中概括性的原则条款"}], "sections": {"coreQuestion": "法律解释是法律适用的核心环节。一个常见印象是：大陆法法官探求立法者意图，普通法法官拘泥于条文文字。但 Siems 通过 Vogenauer 的比较研究指出，法国、德国、英格兰三国虽起点不同，实际使用相似的正式与价值导向论证组合。那么，两大法系的解释方法到底有何差异？解释方法与法律渊源、法官角色、判决风格如何关联？本节比较两大法系的解释方法，澄清『形式主义对现实主义』这一流行叙事，并展示趋同的现实。", "definition": "法律解释（legal interpretation）指确定法律规范含义与适用范围的活动。Siems 指出，解释方法是法律方法的核心，与法律渊源、法院角色和判决风格紧密关联。\n\n核心概念包括：普通法的字面规则（literal rule）、黄金规则（golden rule）、瑕疵规则（mischief rule）；大陆法的启示法（exegetical method，探求立法者意图）、目的论方法（teleological method，依据法律客观目的）、以及类推适用；一般条款（general clause）的解释；以及普通法对判例的区分技术（distinguishing）。\n\nSiems 强调，两大法系在解释方法上既有不同的传统侧重，也有实际的趋同。", "history": "法律解释方法的差异有历史根源。Siems 指出，大陆法法典化承启蒙理想，追求清晰、自足、完整，法国民法典第 5 条曾禁止法官以一般性规则裁判，要求按法典文字准确适用。但随着时间推移，狭隘字面解释被证明不可行，大陆法发展出探求立法者意图与法律目的的方法。\n\n普通法则因判例为主要渊源，制定法被视为例外，解释传统上较窄，发展出字面规则、黄金规则、瑕疵规则等。但随着制定法激增，普通法解释也逐渐从字面转向立法史与目的。Siems 指出，Vogenauer 对法国、德国、英格兰制定法解释的比较研究显示，各国在解释方法上出现明显趋同。", "principle": "法律解释方法的比较可从四个层面展开。\n\n第一，普通法的解释规则。Siems 指出，普通法的制定法解释传统上以字面规则（literal rule）为主，除非导致荒谬结果（黄金规则 golden rule），或未能充分处理法律欲补救的缺陷（瑕疵规则 mischief rule）。但因制定法被视为例外，解释较窄。不过 Siems 强调，与普通法一致，解释已逐渐从字面转向立法史与目的。\n\n第二，大陆法的解释方法。Siems 指出，今天大陆法常用的解释工具包括：探求立法者意图、给法律以完整效果的启示法（exegetical method）；当条文含糊、立法意图不明时，依据法律客观目的的目的论方法（teleological method）；目的对一般性条款尤其重要；例外情况下，为给法律完整效果，可扩张解释甚至类推适用——瑞士民法典更明确授权法官在法无规定时依习惯法、再依其作为立法者会确立的规则裁判。\n\n第三，对一般条款的解释。Siems 指出，大陆法的一般条款（如善意原则）赋予法官发展法律的余地，法院通过一般条款增量地发展法律——这类似普通法的判例法。德国法院运用善意原则，是为了发展可靠适用的规则类别，而非在个案中任意裁量。\n\n第四，解释与法律方法的关系。Siems 强调，解释方法与法律渊源、法官角色、判决风格相互关联：大陆法法官以三段论推理、重视法典，解释上探求立法意图与目的；普通法法官从个案推理、重视判例，解释上从字面转向目的，但保留对文本与先例的尊重。", "viewpoints": "关于解释方法的差异，Siems 综合主流观点：大陆法法官在解释法律时有较大 discretion，但解释完成后便只是法律适用者——他们把法律适用建立在法典基础上；普通法法官则更 ad hoc 地引用制定法，即便在高度法典化的领域也如此。\n\n但 Siems 强调，把解释方法绝对化是错误的。他引用 Stefan Vogenauer 的研究——该研究比较法国、德国与英格兰的制定法解释，发现三国虽起点不同，实际使用相似的正式与价值导向论证组合。他还指出，英国法院已放弃狭隘解释，例如允许对制定法条文进行类推。这说明，形式主义与现实主义的分野，在解释的实际运作中并不像理论上那样分明。", "comparison": "解释方法的对照可从多维度展开。\n\n在基本态度上，普通法传统重文本与先例，大陆法传统重立法意图与目的；在方法体系上，普通法的字面/黄金/瑕疵规则对大陆法的启示法/目的论/类推；在法官角色上，普通法法官较 ad hoc 引用制定法，大陆法法官把推理锚定于法典；在一般条款上，大陆法通过一般条款发展法律，普通法则通过判例与衡平。\n\n但趋同显著：Vogenauer 研究表明三国使用相似的论证组合；普通法解释转向目的，大陆法解释也重视文本与体系。Siems 借 Duncan Kennedy 的『法律思想三次全球化』说明法律思想跨越法系边界——古典（德国法律科学）、社会（法国学术）、政策分析（美国学术）的全球化，使解释方法相互渗透。", "debates": "解释方法的经典争论，是形式主义与现实主义（或文本主义与目的主义）之争。形式主义强调法律的确定性、拘束法官、尊重立法者；目的主义强调法律的适应性、实现正义、回应社会需求。Siems 在多个层面对此保持审慎。\n\n他指出，把大陆法描述为机械适用、把普通法描述为纯形式主义，都是误解：大陆法通过一般条款发展法律，普通法法官也在宽泛原则下运作。Markesinis 与 Fedtke 指出，把大陆法官职能描述为『狭窄、机械、无创造性』并不准确；Shapiro 认为大陆法官机械适用的假定『根本错误』；Kötz 则指出英国法官同样在宽泛原则下运作。\n\nSiems 的立场是：两大法系都发展出处理确定性与灵活性张力的机制，差异是程度与表述上的，而非本质上的。这一立场呼应全书的语境化与去绝对化主题。", "case": "Vogenauer 的研究是最有说服力的案例。Siems 指出，Stefan Vogenauer 对法国、德国与英格兰的制定法解释进行了全面比较，结论是：尽管三国起点不同，实际使用相似的正式论证（如文本、体系）与价值导向论证（如目的、政策）的组合。这一经验研究直接挑战了『大陆法主观探意图、普通法客观拘文字』的刻板印象。\n\n另一个案例是瑞士民法典第 1 条：它明确授权法官在法典无规定时依习惯法裁判，再依其作为立法者会确立的规则裁判。Siems 引用这一条款说明，大陆法早已承认法官在法律补充中的角色，机械适用只是漫画化的想象。", "caseAnalysis": "以 Vogenauer 研究为例：事实是，比较法国、德国、英格兰的制定法解释，发现三国使用相似的论证组合。争议焦点是：这是否意味着两大法系的解释方法已经趋同、差异消失？\n\nSiems 的解读是：起点不同但工具箱相似——三大法系都使用文本、体系、目的、政策等论证，只是权重与制度表达不同。这既支持趋同论，也提示差异仍在：大陆法法官把推理锚定于法典与立法意图，普通法法官更 ad hoc 地引用制定法并尊重先例。\n\n这一案例的理论意义在于：它用经验材料纠正了理论上的过度简化。比较法不能停留在『名义上的方法』，而要考察『实际使用的论证』。Siems 借此倡导一种语境化、经验化的比较方法，这正是全书的主旨。", "summary": "法律解释方法是法律适用的核心。普通法传统有字面规则、黄金规则、瑕疵规则，大陆法传统有启示法、目的论方法与类推，并重视一般条款的适用。两大法系在解释方法上确有传统侧重——普通法重文本与先例、ad hoc 引用制定法，大陆法锚定法典、探求意图与目的——但 Siems 通过 Vogenauer 的研究表明，三国实际使用相似的正式与价值导向论证组合。形式主义与现实主义的对立在运作中被稀释：大陆法通过一般条款发展法律，普通法从字面转向目的。理解法律解释，须超越刻板印象，考察实际的论证实践，并在确定性与灵活性、文本与目的之间把握平衡。", "furtherThinking": "1. Vogenauer 的研究发现三国使用相似的论证组合，这是否意味着法律解释的『法系差异』不重要了？\n2. 一般条款（如善意）使大陆法法官能够发展法律，这与普通法判例法有何异同？\n3. 在文本主义与目的主义之间，你认为法律解释应如何平衡确定性与适应性？请结合具体法域说明。"}, "en": "Comparative Legal Interpretation", "level": "core", "tags": "法律解释, 文本主义, 目的解释, 普通法解释规则, 法系比较", "source": "Siems, Comparative Law, ch.2, ch.3", "id": "S2M6K7"}, "S3M1K1": {"title": "初级规则与次级规则", "EN": "Primary Rules and Secondary Rules", "LEVEL": "core", "TAGS": "哈特, 规则理论, 法律体系", "TERMS": "初级规则（Primary Rules）::直接规定人们应当做或不做某事的义务规则；次级规则（Secondary Rules）::以初级规则为对象、规定其识别/改变/裁判的高阶规则；承认规则（Rule of Recognition）::用以确定哪些规则具有效力的终极次级规则；改变规则（Rules of Change）::授权制定/修改/废止初级规则的次级规则；裁判规则（Rules of Adjudication）::授权权威判定初级规则是否被违反的次级规则；内部观点（Internal Point of View）::参与者把规则当作行为理由与批评标准来接受的态度；开放结构（Open Texture）::一般语言规则在边缘地带留下不确定性的特征", "SOURCE": "Hart, The Concept of Law, ch.5；Hart, The Concept of Law, Postscript, s.3；Wacks, Understanding Jurisprudence, ch.2", "terms": [{"term": "初级规则（Primary Rules）", "def": "直接规定人们应当做或不做某事的义务规则"}, {"term": "次级规则（Secondary Rules）", "def": "以初级规则为对象、规定其识别/改变/裁判的高阶规则"}, {"term": "承认规则（Rule of Recognition）", "def": "用以确定哪些规则具有效力的终极次级规则"}, {"term": "改变规则（Rules of Change）", "def": "授权制定/修改/废止初级规则的次级规则"}, {"term": "裁判规则（Rules of Adjudication）", "def": "授权权威判定初级规则是否被违反的次级规则"}, {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作行为理由与批评标准来接受的态度"}, {"term": "开放结构（Open Texture）", "def": "一般语言规则在边缘地带留下不确定性的特征"}], "sections": {"coreQuestion": "法律常被想象成一张「禁止你做什么」的命令清单：不得杀人、不得盗窃、必须纳税。但如果法律真的只是这些禁止性规则的堆砌，立刻会遇到三个尴尬的问题：我们凭什么知道哪些规则算法律、哪些不算？法律如何与时俱进地修改自身？发生争议时谁有权作出权威判定？本节要解决的正是这个「法律如何自我调整」的谜题。哈特（H. L. A. Hart）通过区分初级规则（Primary Rules）与次级规则（Secondary Rules），把法律从静态的命令集合，重新理解为一个能够自我识别、自我更新、自我裁判的制度体系。这是理解其后所有理论（承认规则、法律效力、司法裁量）的起点。", "definition": "初级规则（Primary Rules，又称 primary rules of obligation）是直接规定行为义务的规则：它要求人们做或不做某事，而不问其是否愿意。例如「不得杀人」「必须纳税」都属于初级规则。它们构成社会控制的第一层，存在于任何有规则的社会中，包括没有政府、没有法院的「初级规则社会」。\n\n次级规则（Secondary Rules）则是以初级规则为对象的规则，规定初级规则如何被识别、引入、废止、变更，以及其违反如何被权威地确定。它们处在「更高一层」，是「关于规则的规则」。哈特把次级规则分为三类：承认规则（Rule of Recognition）、改变规则（Rules of Change）与裁判规则（Rules of Adjudication）。\n\n两者的关键差别在于调整对象：初级规则调整行为（about actions），次级规则调整规则（about rules）。相应地，初级规则主要施加义务（duty），而次级规则大多授予权力（power）——赋予立法、缔约、判决的能力。理解次级规则，必须借助「内部观点」（Internal Point of View）：参与者把规则当作共同的行为理由与批评标准来接受，而不只是记录「谁会受罚」的外部规律。", "history": "奥斯丁（John Austin）的命令理论把法律化约为主权者以制裁为后盾的命令，但它解释不了三组现象：法律的持续性（主权者更替后法律仍有效）、法律对立法权自身的限制，以及大量「授权性规则」（如合同、遗嘱、财产转让）——这些规则赋予人们达成合法安排的能力，根本不像威胁。哈特在《法律的概念》（The Concept of Law）第五章宣告「重新开始」（a fresh start），以初级规则与次级规则的结合取代命令模型。这一转向把法理学从追问「法律是何种实体」，转为追问「规则体系如何运作」，为分析法律效力、合法性、司法权等概念提供了全新的分析工具。", "principle": "要把握这一区分，可以分三层推进。\n\n第一层，仅靠初级规则的社会及其三大缺陷。哈特设想一个没有立法机关、法院与官员的社会，人们仅凭一套义务规则共处。这样的社会必然面临三种困境：其一，不确定性（uncertainty）——没有权威文本或官员，无法确定哪些规则有效、某条规则的精确边界何在，规则只是一盘散沙，如同 etiquette（礼仪）规则；其二，静态性（static quality）——规则只能靠习惯的生长或衰败缓慢演变，无法有意识地废除旧规则、引入新规则；其三，无效率（inefficiency of diffuse social pressure）——是否违反规则由当事人自行判断、私力救济，纠纷无休无止，还会引发世仇与浪费。哈特强调，这些缺陷在初级规则社会内部无法自行克服，补救之道只能是引入「另一种」规则。\n\n第二层，三种补救。承认规则解决不确定性：它指定某些特征（如由特定机关制定、载入权威文本、长期习惯、司法判决）作为识别初级规则的终局标志。改变规则解决静态性：它授权个人或机关引入新规则、废止旧规则；私法领域中立遗嘱、订合同、转让财产的授权规则，也是改变规则的 cousin（近亲）。裁判规则解决无效率：它授权特定的人权威地判定初级规则是否已被违反，并由此界定法官、法院、管辖权、判决等概念。\n\n第三层，结合的意义。三类次级规则与初级规则结合，构成「法律体系的核心」（the heart of a legal system）。次级规则大多是授予权力的规则，它们不施加义务而赋予能力，这解释了法律作为制度工具的能动性。更重要的是，承认规则的出现带来了「法律效力」（legal validity）观念的胚胎——规则不再是互不关联的清单，而被统一为一个有层级、有来源的体系。", "viewpoints": "哈特的核心命题是：法律的中心在于初级规则与次级规则的结合（the union of primary and secondary rules）。这一命题包含两层意思。其一，在概念层面，法律体系必然包含次级规则；否则便无法克服初级规则社会的三重缺陷，也就永远停留在「前法律」阶段。其二，在分析层面，次级规则揭示了法律特有的「反思性」——法律能够用规则来控制自身，知道自己从哪里来、如何改变、由谁裁判。\n\n哈特同时保持了一种可贵的克制。他明确警告：这一结合虽居法律体系的「中心」，却并非「全部」（it is not the whole）。离开中心越远，越需要容纳性质不同的要素，例如规则的开放结构、法律与道德的关系。此外，内部观点贯穿全部分析：次级规则之所以能够运作，正是因为官员与参与者从内部接受它们为共同的行为标准。外部观察者只能记录「人们接受这些规则」的事实，却无法据此解释规则的规范力量。", "comparison": "与奥斯丁命令理论比较：命令理论把法律看作「威胁」，只能解释人们「不得不」（obliged）服从，却解释不了「有义务」（obligation）的规范体验，更解释不了授权性规则。次级规则理论则能解释法律不仅禁止，还赋予能力。抢匪的威胁与法律义务的区别，恰在于后者能被从内部观点接受。\n\n与凯尔森（Hans Kelsen）的纯粹法学比较：凯尔森以「基础规范」（Grundnorm）作为全部法律效力的终极预设，哈特则以承认规则取而代之，并强调承认规则是一项可被观察的「社会实践事实」，而非一个被预设的规范。\n\n与自然法理论比较：次级规则中的承认规则提供的是效力的社会来源标准——某规则是不是法律，取决于它是否符合社会接受的识别判准，而非其内容是否正义。这正是法律实证主义「渊源命题」的雏形。", "debates": "围绕次级规则的第一场重要争论，是承认规则是否只能包含「谱系」（pedigree）标准。德沃金（Ronald Dworkin）批评哈特把法律的识别基础限定为形式化的来源，忽视了法律原则同样是法律的一部分，因此主张放弃承认规则理论。哈特在《后记》（Postscript）中回应：承认规则并不必然只包含谱系标准；一个社会的承认规则完全可以把正义原则或实体道德价值纳入效力判准（如美国宪法中的平等保护条款），这就是后来被称为「柔性实证主义」（soft positivism）的立场。因此，承认原则与法律原则并无矛盾。\n\n第二场争论关乎方法论：次级规则究竟是「存在的社会事实」，还是一种「诠释性实践」？德沃金主张，识别法律离不开「建构性诠释」（constructive interpretation），法理学本身即是裁判的「无声序章」。哈特则坚持描述性法理学的可能性：外部观察者能够描述参与者如何从内部观点接受规则，而不必自己接受或赞成这些规则。这场争论预示了后面关于「规则与原则」「司法裁量」的全部交锋。", "case": "英国宪法的演进，提供了从初级规则社会走向完整法律体系的历史样本。1215 年的《大宪章》（Magna Carta）主要是一组限制王权、保障贵族权利的初级规则，尚缺乏系统的识别与变更机制。此后数百年间，议会制定法、普通法判例与宪法惯例逐渐累积：议会主权（parliamentary sovereignty）原则确立了「议会制定法为最高法律渊源」这一承认规则；《议会法》（Parliament Acts 1911/1949）为法律的改变提供了成文框架；法院的审判权则由普通法与制定法共同界定，构成裁判规则。到十九世纪，英国已形成一个虽无单一宪法典、却具备完整次级规则结构的法律体系。这一进程说明：法律体系的关键并不在于是否有一部成文法典，而在于是否形成了稳定地识别、改变与裁判规则的实践。", "caseAnalysis": "就英国宪法而言，事实是：对王权的约束最初表现为分散的初级规则，后来才逐步获得识别与变更的机制。争议焦点在于：不成文的宪法惯例（constitutional conventions）是否属于「法律」的一部分。从哈特的框架看，宪法惯例虽缺乏严格的法律制裁，却在官员群体中被从内部观点接受为正当的行为标准，因而具有规范性；但它们通常不能由法院强制实施，故其法律地位仍是开放的问题。在法律依据上，议会主权作为承认规则的核心，由法院在一系列判例中反复确认；在裁判理由上，法院通过适用制定法与先例，把政治惯例与可强制执行的法律规范区分开来。其理论意义在于：这一案例既展示了次级规则如何把零散规则整合为体系（承认规则提供统一的识别标准），也展示了法律体系边界的开放性——次级规则本身也有开放结构，其适用在边缘情形上仍需要裁量。", "summary": "初级规则直接规定行为义务，次级规则以初级规则为对象，规定其识别、改变与裁判。仅有初级规则的社会面临不确定性、静态性与无效率三大缺陷；承认规则、改变规则、裁判规则分别是三种补救，三者与初级规则结合，构成法律体系的核心。次级规则多为授权性规则，赋予立法、缔约与判决的能力，使法律具备自我调整的制度能力。哈特强调这种结合是法律体系的中心而非全部，其运作依赖于参与者的内部观点。掌握这一区分，是理解法律效力、法律体系与法官角色等后续问题的前提。", "furtherThinking": "1. 如果一个社会只有承认规则，却没有改变规则与裁判规则，它算不算一个法律体系？这对「法律必须能适应变化」的常识提出了什么挑战？\n2. 国际社会长期只有类似初级规则的行为规范，而缺乏强制性的次级规则，这是否意味着国际法在某种意义上还不是「完全」的法律？\n3. 在算法治理中，若规则由代码自动执行，改变规则与裁判规则将如何体现？「规则之治」会不会滑向「代码之治」？"}, "en": "Primary Rules and Secondary Rules", "level": "core", "tags": "哈特, 规则理论, 法律体系", "source": "Hart, The Concept of Law, ch.5；Hart, The Concept of Law, Postscript, s.3；Wacks, Understanding Jurisprudence, ch.2", "id": "S3M1K1"}, "S3M1K2": {"title": "承认规则", "EN": "The Rule of Recognition", "LEVEL": "core", "TAGS": "哈特, 承认规则, 法律效力", "TERMS": "承认规则（Rule of Recognition）::用以确定哪些规则属于有效法律的终极次级规则；法律效力（Legal Validity）::一条规则因符合承认规则的判准而成为法律的属性；终极规则（Ultimate Rule）::自身不再由更高规则授权、其存在体现为社会实践事实的规则；内部陈述（Internal Statement）::从接受规则立场作出的『这是法律』式表述；外部陈述（External Statement）:: Observer 描述他人接受规则的陈述；软实证主义（Soft Positivism）::承认道德原则可经由承认规则纳入效力判准的立场", "SOURCE": "Hart, The Concept of Law, ch.6, s.1；Hart, The Concept of Law, Postscript, ss.2, 4；Harris v Dönges 1954 (South Africa)", "terms": [{"term": "承认规则（Rule of Recognition）", "def": "用以确定哪些规则属于有效法律的终极次级规则"}, {"term": "法律效力（Legal Validity）", "def": "一条规则因符合承认规则的判准而成为法律的属性"}, {"term": "终极规则（Ultimate Rule）", "def": "自身不再由更高规则授权、其存在体现为社会实践事实的规则"}, {"term": "内部陈述（Internal Statement）", "def": "从接受规则立场作出的『这是法律』式表述"}, {"term": "外部陈述（External Statement）", "def": "Observer 描述他人接受规则的陈述"}, {"term": "软实证主义（Soft Positivism）", "def": "承认道德原则可经由承认规则纳入效力判准的立场"}], "sections": {"coreQuestion": "在任何法律体系里，我们每天都在说「这是有效的法律」「那条规定已经失效」。可是，判断一条规则「有效」的最终标准到底是什么？如果标准本身也是一条法律规则，那它的效力又从何而来？这个追问很容易滑向无穷后退：A 的效力来自 B，B 来自 C，永无尽头。本节要回答的，正是哈特（H. L. A. Hart）如何以「承认规则」（Rule of Recognition）切断这一后退，把法律效力 anchoring（锚定）在一个可被观察的社会实践之上，并说明为什么承认规则被称为「终极的次级规则」。", "definition": "承认规则（Rule of Recognition）是哈特理论中最重要的次级规则，它规定了用以识别哪些初级规则具有法律效力（Legal Validity）的标准。简言之，它回答「什么样的规则算法律」：在简单社会里，标准可能是「记载于权威文本」；在现代社会里，标准通常是复合的，包括成文宪法、 legislative enactment（立法制定）、司法先例等，并按「上位法优于下位法」的位阶排列。\n\n承认规则有三个关键特征。其一，它是终极的（ultimate）：在它之上不再有更高的授权规则，它的存在不来自另一条规则的授权，而来自官员群体实际的、共同的接受与使用。其二，它是社会实践的规则：它的存在方式体现在官员识别法律的实际行为中，写在某处的情形反倒少见——虽然偶尔会被法院明确表述（如英国法院宣称议会制定法至上），但多数时候它是「未被言明」的。其三，它被从内部观点（Internal Point of View）接受：官员用它来识别法律、批评彼此的偏离，把它当作共同的公务行为标准。\n\n由此产生两类陈述：内部陈述（Internal Statement）是从接受规则的立场说「这是法律」，外部陈述（External Statement）则是观察者说「在该国，人们把某机关制定的规则当作法律」。哈特以「比赛的记分规则」作比：比赛中很少有人复述计分规则，但裁判与选手都在用它判断何为得分。", "history": "承认规则理论是哈特回应奥斯丁（John Austin）主权者理论的产物。奥斯丁把法律效力归于主权者的命令，但这一解释在两方面失败：它说明不了法律的连续性（主权者更替后法律为何仍有效），也说明不了法律对立法权自身的限制。哈特在《法律的概念》第六章提出，真正构成法律体系基础的，是被接受并使用的承认规则。二战后，随着成文宪法审查制度与违宪审查的兴起，「效力最终来源于何处」成为紧迫的实践问题；哈特的分析为理解宪法法院、权力分立与法律效力冲突提供了概念工具。在《后记》中，他又用承认规则回应德沃金（Ronald Dworkin）关于法律原则的挑战，使这一概念成为整部理论的中枢。", "principle": "理解承认规则，可以分四层。\n\n第一层，效力判准的多元化与位阶化。在发达的法律体系中，承认规则指向各种「法律渊源」（sources of law）：制定法、习惯、判例等，单一文本已不足以概括。这些判准之间可能冲突，于是承认规则还会安排它们的相对位阶，例如普通法（common law）从属于制定法（statute）。哈特特别提醒，必须区分「位阶从属」与「来源派生」：习惯与判例可被制定法剥夺效力，但其法律地位来自承认规则的授予，而不是「隐性立法权」的产物。\n\n第二层，承认规则的存在方式。它是「不复述即被使用」的规则：其存在由官员的共同实践所证明。这与礼仪规则不同——礼仪被遵守却不必然被当作批评标准；承认规则则被官员当作公务行为的共同标准，偏离会被视为失职而受批评。\n\n第三层，内部陈述与外部陈述的区分。当法官说「这是法律」时，他在从内部使用承认规则；当法学家说「在英国，议会制定法被当作法律」时，他在从外部描述这一事实。哈特强调，描述性的法理学可以从外部记录内部观点，而不必自己接受该法律。\n\n第四层，承认规则与「开放结构」。承认规则本身也是一般规则，因而也有开放结构（Open Texture）：在边缘情形上，一条规则是否满足效力判准可能发生争议。哈特以南非 1954 年的宪法危机（Harris v Dönges）说明，当官员对终极判准本身产生分歧时，法律体系的健康运行就会受到威胁。", "viewpoints": "哈特的核心主张是：承认规则是一个法律体系中「终极的次级规则」，它为识别有效法律提供权威性判准；它的存在本身就是一种社会事实，体现为官员群体的共同接受与使用。据此，「法律效力」指的是：一条规则符合了社会中被接受的识别标准；神秘属性的色彩随之褪去。\n\n哈特还澄清了两个常被误解之处。第一，承认规则不必只以「谱系」（pedigree）即形式来源为判准。他明确承认，在某些体系（如美国）中，终极的效力判准可能把正义原则或实体道德价值纳入其中，作为宪法性限制的内容。第二，承认规则虽是「规则」，却不同于普通规则：普通规则的效力来自承认规则的授权，而承认规则的效力来自它被实际接受和行使这一事实。它是法律体系的「基石」，自身却不是由任何更高法律规则所确立。", "comparison": "与凯尔森（Hans Kelsen）比较：凯尔森以「基础规范」（Grundnorm）为全部法律效力的终极预设，它是先验的、逻辑上的假定；哈特则以承认规则为经验的社会事实——它存在，是因为官员事实上这样做。哈特认为后者更能说明法律体系的现实运作与变革。\n\n与奥斯丁比较：奥斯丁以「主权者的习惯性服从」为法律基础，无法说明效力的规范性与法律的连续性；承认规则把基础从「谁在发号施令」转移到「什么样的标准被共同接受为识别法律的方式」。\n\n与德沃金比较：德沃金主张法律不仅包含规则，还包含原则，而原则无法通过承认规则的谱系判准识别，因而主张放弃承认规则。哈特在《后记》中回应：原则同样可以经由承认规则被识别（如宪法中的原则条款），而且德沃金的「建构性诠释」本身也要预设对「既判法」的识别，这恰恰离不开承认规则。", "debates": "承认规则引发的核心争论，是「法律与道德在效力识别上是否必然分离」。哈特主张，法律的存在与内容可依社会来源（立法、判例、习惯）识别，无须诉诸道德，除非该法律自身把道德纳入了判准——这就是他区分「决定性理由」与「柔性实证主义」的方式。德沃金则坚持，每一条法律命题的成立都必然包含道德判断；法律原则是既适合又有道德正当性地诠释既能解释法律实践的整体。\n\n争论的第二个焦点是承认规则是否可能「被违反」。哈特承认，承认规则也存在开放结构，官员们可能在终极判准上产生分歧（如南非的宪法危机），此时法律体系处于病理状态。德沃金则据此论证法律的本质本身就是争议性的（「法律作为完整性」law as integrity），不存在一个所有官员共享的、可作为事实描述的承认规则。哈特的回应是：理论分歧的存在并不否认多数情形中共享实践的事实，法理学应当描述这种实践，而非把争议本身上升为法律的本质。", "case": "南非 1954 年的 Harris v Dönges 案，是哈特在《法律的概念》中亲自引用的承认规则「病理」案例。当时，南非议会与法院对议会是否有权以特定程序修改涉及「有色人种选民」资格的宪法性法律产生分歧：议会依自己的权限理解通过了相关措施，法院则宣告其无效。议会的回应是设立一个特别上诉「法院」来受理对普通法院判决的上诉；特别法院进而推翻普通法院的判决，而普通法院又宣告设立特别法院的法律无效。哈特指出，如果这一循环不被中止，就会在「什么是识别有效法律的终极标准」上陷入无休止的摇摆，官员之间（尤其是司法官员之间）的常规和谐——这是识别承认规则的前提——将被悬置。所幸政府后来认为继续推进此路不明智，循环才告停止。这个案子生动地说明：承认规则体现在官员协同实践中的事实，纸面条文容纳不了它；一旦这种协同破裂，法律体系便进入病理状态。", "caseAnalysis": "就 Harris v Dönges 而言，事实是议会与法院对议会立法权限（即终极效力判准）各执一词；争议焦点是：谁有权最终判定一条法律是否有效。从哈特框架看，这是关于「承认规则本身是什么」的争议，普通的法律争议之名并不贴切——它属于法律体系的病理而非正常运行。裁判理由上，各方都援引了自己所理解的宪法性判准，却没有一个双方共同接受的标准来裁判这场标准之争。理论意义在于：第一，它证明承认规则的存在是经验事实，依赖于官员实践的一致性；第二，它显示即使在这种危机中，大量不涉及宪法问题的日常法律操作仍照常进行——哈特以此说明法律体系的存在陈述是「双面」的（Janus-faced），既看公民的普遍服从，也看官员对次级规则的接受；第三，它预告了开放结构理论：终极判准在边缘处同样模糊，需要裁量。", "summary": "承认规则是法律体系中终极的次级规则，它提供识别有效法律的判准，使法律效力获得统一的社会基础。它的存在方式是官员群体共同接受与使用的社会实践，而非更高规则的授权；它通过内部陈述与外部陈述的区分，把「这是法律」与「人们视此为法律」区分开来。承认规则可以是复合且分层的，甚至在柔性实证主义中纳入道德价值。承认规则本身也有开放结构，其实践一旦破裂，法律体系即陷入病理。理解承认规则，是理解法律效力、法律体系存在条件以及后续规则与原则之争的关键。", "furtherThinking": "1. 如果一个社会的法官在终极效力判准上长期无法达成一致，我们还能说那里存在一个法律体系吗？这与哈特的「最低条件」说如何协调？\n2. 当宪法把「尊严不可侵犯」写入效力判准时，承认规则是否就此变成了道德原则？哈特的「柔性实证主义」与德沃金的理论还剩下什么差别？\n3. 在网络平台治理中，若平台的「社区准则」由一个管理员团队最终解释，这个团队的解释实践在何种意义上类似于承认规则？"}, "en": "The Rule of Recognition", "level": "core", "tags": "哈特, 承认规则, 法律效力", "source": "Hart, The Concept of Law, ch.6, s.1；Hart, The Concept of Law, Postscript, ss.2, 4；Harris v Dönges 1954 (South Africa)", "id": "S3M1K2"}, "S3M1K3": {"title": "改变规则与裁判规则", "EN": "Rules of Change and Rules of Adjudication", "LEVEL": "core", "TAGS": "哈特, 次级规则, 立法权, 司法权", "TERMS": "改变规则（Rules of Change）::授权制定/修改/废止初级规则或改变个人法律地位的次级规则；裁判规则（Rules of Adjudication）::授权权威判定初级规则是否被违反的次级规则；授权性规则（Power-conferring Rules）::赋予主体以法律能力去改变法律关系的规则；立法权（Legislative Power）::由改变规则授予的制定与废止法律的权力；司法权（Judicial Power）::由裁判规则授予的权威判定违反事实的权力；管辖权（Jurisdiction）::裁判规则所划定的裁判权限范围", "SOURCE": "Hart, The Concept of Law, ch.5, s.3；Hart, The Concept of Law, ch.6, s.1；Marbury v. Madison, 5 U.S. (1 Cranch) 137 (1803)", "terms": [{"term": "改变规则（Rules of Change）", "def": "授权制定/修改/废止初级规则或改变个人法律地位的次级规则"}, {"term": "裁判规则（Rules of Adjudication）", "def": "授权权威判定初级规则是否被违反的次级规则"}, {"term": "授权性规则（Power-conferring Rules）", "def": "赋予主体以法律能力去改变法律关系的规则"}, {"term": "立法权（Legislative Power）", "def": "由改变规则授予的制定与废止法律的权力"}, {"term": "司法权（Judicial Power）", "def": "由裁判规则授予的权威判定违反事实的权力"}, {"term": "管辖权（Jurisdiction）", "def": "裁判规则所划定的裁判权限范围"}], "sections": {"coreQuestion": "承认规则解决了「哪些规则是法律」的问题，但一个活的法律体系还必须能够做两件事：有意识地修改自己的规则，以及在发生争议时由特定的人作出有约束力的判定。哈特（H. L. A. Hart）把承担这两项功能的次级规则分别称为「改变规则」（Rules of Change）与「裁判规则」（Rules of Adjudication）。本节要厘清：这两类规则各自解决什么问题、它们如何授予权力而非施加义务、它们与承认规则之间存在怎样的结构关联，以及它们如何解释立法权与司法权这两个核心的政治—法律概念。", "definition": "改变规则（Rules of Change）是授权特定个人或机关引入新的初级规则、修改或废止既有初级规则的次级规则。它解决的是初级规则社会的「静态性」缺陷。改变规则有两种形态：一种是授予立法机关立法权的公法规则，规定谁有权立法、遵循何种程序；另一种是授予私人主体改变自身法律地位的私法规则，如立遗嘱、订立合同、转让财产的规则——哈特指出，这些「授权性规则」（Power-conferring Rules）可被理解为个人行使的「有限的立法权」。\n\n裁判规则（Rules of Adjudication）是授权特定主体对「某一初级规则在具体场合是否已被违反」作出权威性判定的次级规则。它解决的是初级规则社会「社会压力无效率」的缺陷。裁判规则不仅指定谁有权裁判（法官、法院），还界定裁判程序，并由此产生管辖权（Jurisdiction）、判决、法官、法院等一系列法律概念。与施加义务不同，裁判规则授予的是司法权（Judicial Power）与特殊地位，使法官的宣告具有权威性。\n\n两类规则都属于次级规则，都在「更高一层」以初级规则为对象：改变规则决定初级规则如何产生与消灭，裁判规则决定初级规则是否被违反。它们的共同特征，是赋予主体以法律能力（legal power），而不是命令主体履行义务。", "history": "在哈特之前，法律理论长期受「命令—威胁」模型支配，难以解释为何立法机关有权立法、法院有权判决——这些权力显然不是来自上级的威胁。奥斯丁（John Austin）虽承认存在「授予权利的规则」，却把它们勉强归入命令理论的框架，解释力不足。哈特在《法律的概念》第五章把改变规则与裁判规则放到次级规则体系中重新定位，指出它们与承认规则一起，构成从「前法律」迈入「法律」世界的关键阶梯。二十世纪民族国家建构、成文宪法运动与违宪审查制度的兴起，使立法权与司法权的来源问题变得格外紧迫，哈特的分析恰为理解这些制度提供了概念框架。", "principle": "理解两类规则，可从四层展开。\n\n第一层，功能分工。改变规则赋予「改变规则的能力」，裁判规则赋予「判断规则是否被违反的能力」。前者面向未来，使法律体系具有适应性（adaptability）；后者面向过去的具体事件，使纠纷得到终局解决。二者与承认规则合力，分别回应初级规则社会的三大缺陷。\n\n第二层，授权而非义务。改变规则与裁判规则大多属于授权性规则。它们赋予你「如果这样做，就会产生特定法律效果的能力」，强制你必须立法或必须判决的做法并不在其中。这正是命令理论无法解释的现象：法律在此的功能是赋能，压制只是局部图景。哈特强调，正是这种授权功能，使法律成为个人规划生活、安排财产与达成合作的工具。\n\n第三层，与承认规则的结构关联。哈特指出，这三类次级规则彼此紧密相连：凡有改变规则之处，承认规则必然把「立法」纳入识别法律的判准（如某机关制定的文本即视为有效法律）；凡有裁判规则之处，也必然隐含一个初级的承认规则——因为法院对「规则是否被违反」的权威判定，同时也成为「规则是什么」的权威判定，判决由此成为法律的一种渊源。在最简单的形态中，承认规则甚至可能与裁判规则融为一体。\n\n第四层， centralized sanctions（集中的制裁）。哈特进一步指出，现代体系还会在裁判规则之外增加次级规则，规定违反的处罚并授权法官指挥其他官员实施制裁。这使制裁从分散的私力救济，转变为由专门机关垄断的官方权力，大幅提升效率并减少世仇。", "viewpoints": "哈特的核心主张是：改变规则与裁判规则是法律体系不可或缺的次级规则，它们通过授予权力（而非施加义务），使法律体系获得适应变化与终局裁判的能力。立法权与司法权由这类次级规则所授予与界定，神秘的「主权者意志」之说遮蔽了它们的规范性来源。\n\n哈特还强调两类规则与承认规则之间的「必然关联」。其一，改变规则的存在意味着承认规则必然把立法作为识别判准之一，尽管承认规则不必复述立法的全部程序细节——通常官方文本或副本即被当作已依法制定的充分证明。其二，裁判规则的存在必然隐含某种承认规则，因为法院的权威判定同时回答了「规则是什么」，判决因此成为法律渊源，哪怕这种最简形式的承认规则还相当粗糙（判决未必以一般语词表述，其作为准则的使用依赖于对个案的归纳）。", "comparison": "与命令理论比较：奥斯丁把立法权解释为主权者的习惯性服从关系，把司法权解释为主权者的委托；哈特则以改变规则与裁判规则直接解释这些权力的规范性来源——权力是被接受的规则所授予的能力，事实上的强力只是其表象。\n\n与私法授权规则比较：哈特以凯尔森（Hans Kelsen）的观点为参照，指出订立合同、转让财产等活动可被理解为个人行使「有限的立法权」；这打破了公法（立法）与私法（自治）之间的僵硬界限，显示改变规则的逻辑贯穿其中。\n\n与「权力分立」理论比较：传统的分权学说（如孟德斯鸠）强调立法、司法、行政的机构分立；哈特的分析则从规则类型出发，说明三种权力对应三类不同的次级规则，为理解分权提供了更精细的概念工具，而不只是机构层面的描述。", "debates": "围绕改变规则与裁判规则的主要争论，是法官在「法律没有明确规定」的案件中究竟是「发现法律」还是「创制法律」。规则怀疑论者（rule-sceptics）主张，所谓规则只是对法官将如何判决的预测，法官始终在造法。哈特承认，在规则的开放结构地带，法官确实行使某种「有限的、填补空隙的造法权」；但他坚持，在大量「简单案件」中，规则是确定并可被私人自行适用的，不能因为边缘地带的裁量就否认规则的中心地位。\n\n第二个争论是裁判规则是否赋予法官「最终且无误」的权威。哈特区分了「权威性判定」与「正确性」：法官的判决在体系内具有终局性（finality），但这并不意味着它道德上无误（infallibility）。在现代宪制之中，违宪审查制度正是把「谁有权作最终判定」制度化的尝试。美国 1803 年的 Marbury v. Madison 案，就把法院审查立法是否合宪的权力确立起来，成为裁判规则演进的里程碑。", "case": "美国 1803 年的 Marbury v. Madison 案（5 U.S. (1 Cranch) 137），是理解裁判规则与改变规则关系的经典案例。威廉·马伯里（William Marbury）被任命为治安法官，但因政权更替，新政府拒绝发放委任状，马伯里遂依据《1789 年司法法》向最高法院申请强制令。首席大法官马歇尔（John Marshall）裁判的核心结论是：马伯里有权获得委任状，但最高法院无权依《司法法》签发强制令，因为该法赋予最高法院此项初审管辖权的条款违反了宪法第三条——因此该条款无效。此案确立了司法审查（judicial review）原则：法院有权判定立法是否符合宪法，并拒绝适用违宪的法律。\n\n从规则理论看，此案同时牵动三类次级规则：承认规则（宪法为最高法律渊源）、改变规则（国会的立法权及其界限）与裁判规则（法院的管辖权与判定权）。它表明，裁判规则所赋予的「权威判定权」，在现代宪制中可以延伸到对「改变规则之产物（立法）」的合宪性审查。", "caseAnalysis": "就 Marbury v. Madison 而言，事实是马伯里已获任命却未取得委任状，政府拒绝交付；争议焦点是最高法院是否有权依《司法法》签发强制令。法律依据上，马歇尔大法官区分了「权利」与「救济」：权利受侵害应有救济，但救济须由有管辖权的法院提供。裁判理由的关键一步是：既然宪法第三条列举了最高法院的初审管辖权范围，而《司法法》试图扩张的范围与之冲突，就必须在二者间作出选择；宪法作为上位法优先，故扩张条款无效。\n\n理论意义在于：第一，法院对「法律是什么」的权威判定（裁判规则），在此被用来审查「法律如何被制定」（改变规则）的结果，显示次级规则之间的结构联动；第二，它把「谁有权作最终判定」的问题制度化，使承认规则中「宪法至上」的判准获得可操作的司法保障；第三，它也印证了哈特的提醒——裁判规则赋予的是终局性权威，而非道德无误性，司法审查的结论本身仍可经受政治与道德评价。", "summary": "改变规则授予制定、修改与废止初级规则的能力，裁判规则授予权威判定初级规则是否被违反的能力；二者分别回应初级规则社会的静态性与无效率缺陷。两类规则多属授权性规则，体现法律「赋能」而非「压制」的面向，并解释立法权与司法权的规范性来源。它们与承认规则紧密关联：有改变规则处，承认规则必然把立法纳入判准；有裁判规则处，必然隐含初级形态的承认规则。Marbury v. Madison 显示，司法判定权在现代宪制中可延伸至对立法的合宪审查，折射出三类次级规则的结构联动。", "furtherThinking": "1. 私法中的合同、遗嘱规则既然授予个人「有限的立法权」，那么把「立法」与「私法自治」严格对立起来的传统做法是否还站得住脚？\n2. 当宪法法院有权审查立法时，裁判规则与改变规则之间的界限是否会变得模糊？这会不会威胁分权原则？\n3. 若一个体系只有改变规则而没有裁判规则，它能否有效运作？练习从哈特的「三缺陷」框架给出推理。"}, "en": "Rules of Change and Rules of Adjudication", "level": "core", "tags": "哈特, 次级规则, 立法权, 司法权", "source": "Hart, The Concept of Law, ch.5, s.3；Hart, The Concept of Law, ch.6, s.1；Marbury v. Madison, 5 U.S. (1 Cranch) 137 (1803)", "id": "S3M1K3"}, "S3M1K4": {"title": "法律体系的结构与存在条件", "EN": "The Structure and Existence Conditions of a Legal System", "LEVEL": "core", "TAGS": "哈特, 法律体系, 法律效力, 内部观点", "TERMS": "法律体系（Legal System）::初级规则与次级规则结合而成的规则体系；存在条件（Existence Conditions）::判断一个法律体系是否存在的最低事实条件；双面陈述（Janus-faced Statement）::同时指向公民服从与官员接受的存在陈述；内部观点（Internal Point of View）::参与者把规则当作行为标准来接受的态度；病理（Pathology）::法律体系正常运作条件发生局部失败的状态；合法性危机（Legitimacy Crisis）::官员对终极判准产生根本分歧的状态", "SOURCE": "Hart, The Concept of Law, ch.6, ss.1-3；Hart, The Concept of Law, ch.1；Hart, The Concept of Law, Postscript, s.1", "terms": [{"term": "法律体系（Legal System）", "def": "初级规则与次级规则结合而成的规则体系"}, {"term": "存在条件（Existence Conditions）", "def": "判断一个法律体系是否存在的最低事实条件"}, {"term": "双面陈述（Janus-faced Statement）", "def": "同时指向公民服从与官员接受的存在陈述"}, {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作行为标准来接受的态度"}, {"term": "病理（Pathology）", "def": "法律体系正常运作条件发生局部失败的状态"}, {"term": "合法性危机（Legitimacy Crisis）", "def": "官员对终极判准产生根本分歧的状态"}], "sections": {"coreQuestion": "我们说「英国存在一个法律体系」「某国已经没有法治了」，这类判断究竟在什么意义上为真？它是对某种事实的描述，还是一项价值评价？哈特（H. L. A. Hart）认为，「一个法律体系存在」是一个可以被经验地判断的事实陈述，但这个事实具有复杂的结构：它既涉及普通公民对规则的普遍服从，也涉及官员对次级规则的接受。本节要揭示这一「双面」结构，给出法律体系存在的两个最低条件，并说明当这些条件局部失效时，法律体系会呈现怎样的「病理」。", "definition": "法律体系（Legal System）在哈特那里，是初级规则与次级规则相结合的产物：初级规则直接规定行为义务，次级规则（承认规则、改变规则、裁判规则）规定如何识别、改变与裁判初级规则。这种结合被称为法律体系的「核心」。\n\n存在条件（Existence Conditions）指判断一个法律体系是否存在所必须满足的最低事实条件。哈特明确提出两个「必要且充分」的最低条件：其一，根据体系终极效力判准而有效的那些行为规则，必须被普遍服从（generally obeyed）；其二，其承认规则、改变规则与裁判规则，必须被官员作为共同的、公开的公务行为标准而有效接受（effectively accepted）。\n\n「法律体系存在」这一陈述被哈特形容为「双面陈述」（Janus-faced statement）：它一面朝向公民的服从，一面朝向官员的接受。普通公民只需「各自服从」即可，动机可以各异；但官员必须把次级规则当作评判自己与他人行为的共同标准，把偏离视为失职。\n\n当这两个条件不能同时满足时，法律体系就处于「病理」（Pathology）状态——例如革命、敌国占领、无政府状态，或官员内部对终极判准产生分裂。", "history": "在哈特之前，奥斯丁（John Austin）以「多数人对主权者命令的习惯性服从」作为法律存在的充要条件。这一模型把法律的存在化约为单一的事实关系，既无法说明官员接受规则所起的构成性作用，也无法解释革命或独立后法律体系的延续与更替。哈特在《法律的概念》第六章把问题重构为「两个部门的事实」：公民对有效规则的普遍服从，与官员对次级规则的共同接受。二战后殖民体系的瓦解、违宪审查制度的扩散，以及「事实上的政权」与「法律上的政权」之分离，使「法律体系何时存在、何时终止」成为具有现实意义的问题，哈特的分析为此提供了判断框架。", "principle": "理解法律体系的存在，可分四层。\n\n第一层，公民服从与官员接受的分离。在只有初级规则的简单社会中，内部观点必须广泛分布于全体成员，否则根本谈不上规则。但在初级规则与次级规则结合的法律体系中，「接受规则作为共同标准」与「被动地各自服从」可以分离：内部观点甚至可能仅限于官员阶层。哈特承认，这样的社会可能「可悲得像羊群」，羊群可能被送进屠宰场；但他认为没有理由否认它仍是一个法律体系——因为这套规则在官员层面有效运作。\n\n第二层，两个最低条件的具体含义。第一个条件要求「有效的行为规则被普遍服从」——注意是「普遍」（generally），不要求人人服从；且公民的服从可以出于任何动机（计算利益、习惯、恐惧）。第二个条件要求官员「有效接受」次级规则——他们不仅使用这些规则，还要把它们当作批评自己与同僚偏离的共同标准。这是官员层面的内部观点。\n\n第三层，「检验」与「病理」。在正常情形中，公民服从的规则恰好是官员认定的有效规则，两个部门一致，便可自信地说法律体系存在。但当官员认定的有效规则不再被公民普遍服从时，就出现断裂：革命（内部争夺统治权）、敌国占领（外部强加统治）、无政府与匪患（秩序崩溃）都是典型。哈特强调，法律体系何时「最终停止存在」并无精确时点——它不是一个由短期事件即可证伪的判断，因为「法律体系存在」这一陈述足够宽泛，容许中断。\n\n第四层，「胎儿学」（embryology）与承认规则的转移。哈特以英联邦的独立过程说明：殖民地初期，其终极承认规则是「威斯敏斯特议会制定法为法律」；独立后，法院不再承认英国议会的立法权，承认规则「本地化」，于是出现两个独立的法律体系。这一转变的事实证据，正是终极承认规则的内容变化。", "viewpoints": "哈特的核心主张是：法律体系的存在取决于两个可观察的事实条件——有效规则被普遍服从，次级规则被官员有效接受。这是一个事实问题，而非道德问题；一个道德上极其邪恶的体系，只要满足这两个条件，仍然是法律体系。哈特借此与「恶法非法」的自然法立场保持距离：承认某体系是法律，与谴责它、抵抗它，是两个不同的判断。\n\n同时，哈特强调「法律体系存在」陈述的「双面性」与「开放性」。它是双面的，因为同时涉及公民与官员两个部门；它是开放的，因为「是否终止」没有精确界线，需要结合恢复的可能性、战争的结局等因素综合判断。哈特还指出，即使在与宪法有关的严重分裂中，大量不涉及该问题的日常法律操作仍照常进行，因此不宜轻言整个体系已经消亡。", "comparison": "与奥斯丁比较：奥斯丁以单一的习惯性服从解释法律存在，哈特则以「普遍服从＋官员接受」的双条件取而代之，突出了次级规则与内部观点的构成性作用。\n\n与自然法理论比较：自然法倾向于把道德正当性作为法律存在的条件之一；哈特坚持法律的存在是事实问题，道德价值只影响我们是否服从、是否抵抗，不影响「它是不是法律体系」的判断。\n\n与「事实上的政府」理论比较：政治理论中常区分 de facto（事实上的）与 de jure（法律上的）政权；哈特的分析表明，这种区分恰恰对应「公民服从」与「官员接受」两个部门的错位，从而为理解政权的合法性提供概念工具。", "debates": "围绕存在条件的首要争论，是「法律体系的存在是否必然包含道德价值」。哈特承认，任何能存续的法律体系都必须为某些人提供「相互克制的制度」——这与最低限度的自然法相关；但他坚持，这些条件并不必然惠及所有人，奴隶制社会与种族隔离社会的事实足以证明这一点。因此，道德上极端邪恶的体系仍可能是法律体系。\n\n第二个争论关乎「承认规则的单一性与稳定性」。德沃金（Ronald Dworkin）以「法律作为完整性」为立场，强调法律实践中的理论分歧，认为不存在一个所有官员共享、可作为事实描述的承认规则。哈特回应：理论分歧主要发生在「承认规则的开放结构」边缘，不能据此否认多数情形中共享实践的事实；描述性法理学正是要记录这种实践。南非 1954 年的宪法危机显示，即便官员在终极判准上分裂，日常法律操作仍在继续——这说明体系的存在具有韧性，不能因局部病理就整体否定。", "case": "1994 年南非的宪制转型，是观察法律体系「胎儿学」的现实例子。在种族隔离时期，南非的承认规则把议会制定法置于最高地位，而被压迫的大多数人对这套规则的接受程度极低，法律体系高度依赖官员层面的运作与强制。转型期间，1993 年《临时宪法》(Interim Constitution) 与 1994 年民主选举产生了新的制宪机关，1996 年《宪法》确立了以宪法至上、基本权利保障为核心的新的承认规则。旧的议会主权判准被取代，法院与官员开始按照新的效力标准识别法律。这一过程说明：法律体系的更替，在事实层面表现为终极承认规则的内容转换——当法院不再承认旧议会的无限立法权，而以新宪法为最高判准时，一个新的法律体系便从旧体系中诞生。值得注意，这一转型是通过协商与制宪程序完成的，与哈特所述「暴力断裂」的模式有所不同，但其背后的规则结构变化是相通的。", "caseAnalysis": "就 1994 年南非转型而言，事实是旧议会主权体系被以新宪法为顶点的体系取代；争议焦点在于：何时可以说旧体系终止、新体系诞生。从哈特的框架看，判断标准在于官员（尤其法院）实际使用何种终极判准来识别有效法律，政治宣告本身说明不了问题。裁判依据上，新宪法成为新的承认规则的核心内容；理由上，法院通过适用新宪法审查既有法律的效力，从而把新判准制度化。理论意义在于：第一，它印证了「法律体系的存在是事实问题」——转变的标志是官员实践的改变，而非单纯的道义宣示；第二，它说明两个最低条件中的第二个（官员对次级规则的接受）在转型中具有决定性作用；第三，它也提示哈特框架的边界——协商转型中「合法性」的道义力量，实际上影响了官员对新规则的接受，这是纯粹描述性框架所难以充分捕捉的。", "summary": "法律体系是初级规则与次级规则结合的产物，其存在是一个「双面」的事实陈述：一面是公民对有效规则的普遍服从，一面是官员对次级规则的有效接受。哈特提出两个必要且充分的最低条件，分别对应这两个部门。公民可出于任何动机各自服从，官员则必须把次级规则当作评判自己与他人的共同标准。当条件局部失效时，法律体系进入病理状态（革命、占领、无政府、官员分裂）；当承认规则发生根本转移时，新体系从旧体系中诞生。哈特坚持存在是事实问题，道德评价不影响「是不是法律体系」的判断，这一立场为其后的法律与道德之辨奠定基础。", "furtherThinking": "1. 一个体系若只有官员接受次级规则，而公民普遍不服从，按哈特的标准它仍是法律体系；但这样的判断在道德上是否令人不安？这暴露了描述性法理学的什么局限？\n2. 在全球化时代，欧盟法律秩序与成员国宪法之间是否存在多个「承认规则」的竞争？哈特的单一体系模型能否解释这种复数结构？\n3. 若 AI 系统开始参与「识别哪些规则有效」的实践，官员的接受是否仍然构成法律体系存在的必要条件？"}, "en": "The Structure and Existence Conditions of a Legal System", "level": "core", "tags": "哈特, 法律体系, 法律效力, 内部观点", "source": "Hart, The Concept of Law, ch.6, ss.1-3；Hart, The Concept of Law, ch.1；Hart, The Concept of Law, Postscript, s.1", "id": "S3M1K4"}, "S3M1K5": {"title": "法律的开放性结构", "EN": "The Open Texture of Law", "LEVEL": "core", "TAGS": "哈特, 开放结构, 语言, 形式主义", "TERMS": "开放结构（Open Texture）::一般语词规则在边缘地带留下适用不确定性的特征；形式主义（Formalism）::试图掩盖并最小化规则适用中选择必要性的态度；概念法学（Conceptualism）::追求概念体系封闭自足的法律思维；核心地带（Core of Certainty）::规则适用毫无疑问的清楚情形；边缘地带（Penumbra of Doubt）::规则是否适用存在理由冲突的模糊情形；相对无知的事实（Relative Ignorance of Fact）::立法者无法预见未来所有情势组合的处境；目的的相对不确定性（Relative Indeterminacy of Aim）::立法目标在未被设想的情势面前仍不确定的状态", "SOURCE": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, ch.6, s.3；Donoghue v Stevenson [1932] AC 562 (H.L.)", "terms": [{"term": "开放结构（Open Texture）", "def": "一般语词规则在边缘地带留下适用不确定性的特征"}, {"term": "形式主义（Formalism）", "def": "试图掩盖并最小化规则适用中选择必要性的态度"}, {"term": "概念法学（Conceptualism）", "def": "追求概念体系封闭自足的法律思维"}, {"term": "核心地带（Core of Certainty）", "def": "规则适用毫无疑问的清楚情形"}, {"term": "边缘地带（Penumbra of Doubt）", "def": "规则是否适用存在理由冲突的模糊情形"}, {"term": "相对无知的事实（Relative Ignorance of Fact）", "def": "立法者无法预见未来所有情势组合的处境"}, {"term": "目的的相对不确定性（Relative Indeterminacy of Aim）", "def": "立法目标在未被设想的情势面前仍不确定的状态"}], "sections": {"coreQuestion": "「公园内禁止车辆入内」——这条规则清楚吗？对汽车、公交车，答案不言自明；可如果是一辆电动玩具车、自行车、滑轮鞋呢？哈特（H. L. A. Hart）借这个经典例子揭示：一切一般规则都存在一个「开放结构」（Open Texture），在清楚的核心情形与模糊的边缘情形之间，规则的适用不再自动，而需要作出选择。本节要回答：为什么开放结构是语言的必然命运而非立法的疏漏？它与「形式主义」和「规则怀疑论」各自是什么关系？以及为什么哈特说，即便我们向往一部巨细无遗的法典，也不能把这种确定性当作理想？", "definition": "开放结构（Open Texture）指用一般语词表述的规则，在其边缘地带无法确定地预先决定是否适用于某个具体情形的特征。哈特强调，这是「一般语言」（general language）的固有属性，某条法律的缺陷之说失焦：一般分类语词在核心情形（如「车辆」之于汽车）中清楚适用，但在邻近情形下会出现「是否算」的疑问（自行车、飞机、滑轮鞋算不算车辆）。\n\n这一概念有两层根源。其一，语言的开放结构：自然语言在事实上永远「不可还原地开放纹理化」（irreducibly open-textured），任何解释规则（canons of interpretation）本身也是一般规则，也需要解释，无法自我解释。其二，人的处境：哈特提出两个「相连的无能」——相对无知的事实（relative ignorance of fact），即立法者无法预见未来所有情势组合；目的的相对不确定性（relative indeterminacy of aim），即面对未设想的情形时，立法目标本身尚未确定。因此，「必然的选择」被强加给我们，「因为我们是人，不是神」。\n\n与开放结构相对的是核心地带（Core of Certainty）：在反复出现的熟悉情形中，一般语词的适用没有争议，规则可以被私人自行适用。法律体系正是在这个核心上运行的。", "history": "二十世纪法理学长期在两种极端间摇摆：一端是概念法学（Conceptualism）与形式主义（Formalism），相信概念体系可以封闭自足、规则的适用只是逻辑涵摄；另一端是法律现实主义与规则怀疑论，认为规则不过是对法官将如何判决的预测，法律的本质是不确定的。哈特在《法律的概念》第七章试图走出这种摇摆：他承认规则存在开放结构，反对形式主义对选择必要性的掩盖；同时坚核心地带是法律运行的主体，反对规则怀疑论的全盘否定。二战后福利国家与行政规制兴起，大量「合理注意」「公平费率」等可变标准被采用，使「规则与标准」「确定与裁量」的关系成为迫切的理论问题，哈特的分析正是对此的回应。", "principle": "理解开放结构，可分五层。\n\n第一层，核心与边缘的双重结构。任何规则都有「确定的核心」与「可疑的边缘」。哈特以「把帽子脱下」为例：父亲让孩子模仿自己进教堂脱帽的动作，孩子会问要模仿到什么程度——用哪只手、快还是慢、帽子放在哪里？这些疑问正对应法律中「本案是否类似先例」的判断。成文规则看似确定，实则把这种不确定性从「模仿的模糊」转移为「语词的模糊」。\n\n第二层，语言为何必然开放。一般语词是为交流而设，若没有普遍认可的清楚情形，语言根本无法运作；但典型案例之外的变异情形，总会出现「支持与反对使用该语词的理由并存，却没有约定决定取舍」的局面。此时，解决疑问需要「在开放 alternatives 之间作出选择」。解释规则不能消除这种不确定性，只能减少它。\n\n第三层，人的两种无能。哈特强调，即使作为理想，我们也不应追求一部能预先决定一切适用的法典。原因不在于语言本身，而在于人的有限性：我们既不知未来所有事实组合（相对无知的事实），在未设想的情势面前目的也不确定（目的的相对不确定性）。例如「禁止车辆入公园」时，立法者已决定禁止汽车、摩托，但面对「电动玩具车」时，公园的安宁与儿童的兴趣之间如何取舍，尚未决定。当该情势出现，必须作出选择，选择同时也使初始目的更确定。\n\n第四层，形式主义及其代价。哈特批判形式主义（或概念法学）的「概念天堂」（heaven of concepts）：它把规则语词的涵义冻结为在一切场合都相同，抓住核心情形的特征并当作充分必要条件，无视社会后果。这样虽获得确定性，代价却是「在黑暗中预先决定」未来案件，僵化的分类会与设立规则的目的相冲突。\n\n第五层，两种应对技术。哈特区分了两种法律技术：其一是委任立法——立法机关设定宽泛标准（如「公平费率」「安全作业系统」），由熟悉各类情形的行政机关制定具体规则；其二是可变标准——如过失法中的「合理注意」（due care），把权衡交给个人与法院，由法院事后判定。两者都承认开放结构的存在，并以不同方式把「进一步的选择」交给更接近具体情形的机关。", "viewpoints": "哈特的核心主张是：开放结构是法律规则的普遍且必然的特征，它源于一般语言的性质与人的有限性，因而既不能也不应被消除。法律体系的健康，有赖于在两种社会需要之间取得平衡：一是确定性——让个人在广泛领域能自行适用规则、无需官方的进一步指引；二是开放性——为那些只有在具体情形中才能妥善判断的问题，保留由知情官员作权威决定的空间。\n\n哈特反对两种夸张。其一，形式主义掩盖选择的必要性，试图把规则冻成封闭体系；其二，规则怀疑论借边缘地带的裁量否定规则本身。哈特的态度是：开放结构虽使边缘地带的适用成为「一种选择」，但只要这种选择能依「法律上相关且足够接近的类似性」作出，它就不是任意的，仍属于法律推理的范畴。", "comparison": "与形式主义比较：形式主义追求规则的完全确定，把适用视为逻辑涵摄；哈特承认核心地带的确定性，但指出边缘地带的适用需要目的考量与选择，形式主义只是「在黑暗中预先判断」。\n\n与法律现实主义比较：现实主义强调法官实际做什么，倾向于把规则还原为判决预测；哈特则坚持规则的确定核心是法律生活的主要部分，开放结构只出现在边缘，不能据此否认规则的中心地位。\n\n与德沃金比较：德沃金认为法律是「无漏洞」的，原则为疑难案件提供唯一正确答案；哈特坚持总有法律未调整的案件，法官须行使填补空隙的裁量。这是二人关于司法裁量争论的根源。", "debates": "开放结构引发的核心争论，是「疑难案件是否有唯一正确答案」。德沃金认为，法官在疑难案件中应诉诸既适合既有法律、又能为其提供最佳道德正当化的原则，因此存在唯一正确答案；哈特在《后记》中回应，即便法官援引原则进行「类比推理」，相互竞争的原则之间仍可能需要选择，而法律本身并未给出这种选择的优先顺序，因此法官「必须行使造法权」，只是这种权力是「填补空隙的」（interstitial）、受实体约束的。\n\n第二个争论关乎「确定性与开放性的比重」。哈特承认，不同体系、同一体系的不同时期，对这一比重的处理方式不同：有的过度牺牲确定性，使司法解释过于形式化；有的则把太多东西视为永远可重审，不尊重立法语词虽开放却仍提供的限制。哈特主张法理学的任务正是避免在这两种极端之间摇摆，如实描述法律体系如何以不同技术应对人的有限性。", "case": "唐纳休诉斯蒂文森案（Donoghue v Stevenson [1932] AC 562，英国上议院）是开放结构的经典实例。原告在咖啡馆饮用朋友购买的姜汁啤酒，酒瓶中有腐烂的蜗牛，她因此患病。按当时英美法，原告与啤酒制造商之间不存在合同关系，而既有的过失判例只调整若干封闭的类别（如马匹、铁路等）。上议院最终判决制造商负有注意义务，其中阿特金勋爵（Lord Atkin）提出了著名的「邻人原则」（neighbour principle）：你必须采取合理注意，避免那些可以合理预见会伤害你邻人的作为或不作为。\n\n从开放结构看，「邻人」这一一般语词没有事先划定的闭合清单，它处在既有判例类别的边缘之外。法院通过「建构性」的推演，把注意义务扩展到一个先前未被明确规定的情形。哈特在《后记》中正是以此案说明「有限形式的建构性诠释」：法官从既有的多个注意义务规则中提炼出底层原则，但哈特同时指出，这种诠释并不能完全消除选择——相互竞争的类比与原则之间仍需判断。", "caseAnalysis": "就 Donoghue v Stevenson 而言，事实是原告因啤酒中的蜗牛患病，与制造商无合同关系；争议焦点是制造商是否负有注意义务。法律依据上，既有判例只承认零散类别中的注意义务，没有一条规则直接涵盖「制造商对最终消费者」的情形。裁判理由上，阿特金勋爵提炼出「邻人原则」，把可预见性作为承担注意义务的判准，从而把新情形纳入既有原则的射程。理论意义在于：第一，它展示了开放结构——既有规则的边缘之外，需要法官作出「本案是否与核心情形足够类似」的判断；第二，它展示了「类比推理」的作用，法院引用一般原则为新裁决提供理由；第三，它也印证哈特与德沃金的分歧——德沃金视此为原则揭示法律唯一正确答案的范例，哈特则视此为法官在开放地带行使有限造法权的例证，认为「邻人原则」本身并未事先决定所有后续案件。", "summary": "开放结构是一般语词规则在边缘地带适用不确定的特征，其根源在于语言的性质与人的两种有限性——相对无知的事实与目的的相对不确定性。任何规则都有确定的核心与可疑的边缘：核心保证法律的确定性与可自行适用性，边缘则要求选择。哈特反对形式主义掩盖选择的必要性，也反对规则怀疑论借边缘裁量否定规则本身；他主张法律体系应在确定性与开放性之间取得平衡，并以委任立法与可变标准等技术应对。Donoghue v Stevenson 显示，即便通过原则进行类比推理，开放地带的选择也难以被完全消除。", "furtherThinking": "1. 如果立法机关真能预见未来所有情势组合，开放结构是否会消失？哈特为什么说即便作为理想也不应追求这种确定性？\n2. 「邻人原则」这样的一般原则，是否把开放结构从「规则」转移到了「原则」层面，而没有真正消除它？\n3. 在算法量刑系统中，若把「合理性」量化为风险评分，开放结构是被消除了，还是被隐藏在了参数的设定之中？"}, "en": "The Open Texture of Law", "level": "core", "tags": "哈特, 开放结构, 语言, 形式主义", "source": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, ch.6, s.3；Donoghue v Stevenson [1932] AC 562 (H.L.)", "id": "S3M1K5"}, "S3M1K6": {"title": "法律的不确定性", "EN": "The Indeterminacy of Law", "LEVEL": "debate", "TAGS": "哈特, 德沃金, 规则怀疑论, 司法裁量, 开放结构", "TERMS": "法律的不确定性（Indeterminacy of Law）::法律在某些案件中不 uniquely 决定判决结果的状态；规则怀疑论（Rule-Scepticism）::主张法律规则只是对法官判决的预测、谈论规则是神话的立场；形式主义（Formalism）::相信规则能机械决定一切案件结果的态度；疑难案件（Hard Cases）::法律渊源无法唯一决定判决的案件；填补空隙的裁量（Interstitial Discretion）::法官在法律未调整处行使的有限造法权；唯一正确答案（Right Answer Thesis）::德沃金主张疑难案件存在正确答案的命题", "SOURCE": "Hart, The Concept of Law, ch.7, ss.1-4；Hart, The Concept of Law, Postscript, s.6；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；Riggs v. Palmer, 115 N.Y. 506 (1889)", "terms": [{"term": "法律的不确定性（Indeterminacy of Law）", "def": "法律在某些案件中不 uniquely 决定判决结果的状态"}, {"term": "规则怀疑论（Rule-Scepticism）", "def": "主张法律规则只是对法官判决的预测、谈论规则是神话的立场"}, {"term": "形式主义（Formalism）", "def": "相信规则能机械决定一切案件结果的态度"}, {"term": "疑难案件（Hard Cases）", "def": "法律渊源无法唯一决定判决的案件"}, {"term": "填补空隙的裁量（Interstitial Discretion）", "def": "法官在法律未调整处行使的有限造法权"}, {"term": "唯一正确答案（Right Answer Thesis）", "def": "德沃金主张疑难案件存在正确答案的命题"}], "sections": {"coreQuestion": "「法律是不确定的」这句话，既可能是一个洞见，也可能是一句危险的夸张。如果说法律决定不了任何案件，那法治何以可能？如果说法律总是确定的，又如何解释那些让法官和学者争论不休的疑难案件？本节聚焦法理学中关于「法律不确定性」的核心争论：哈特（H. L. A. Hart）以「开放结构」承认边缘地带的不确定性，却坚决反对规则怀疑论的全盘否定；德沃金（Ronald Dworkin）则以「法律作为完整性」和「唯一正确答案」命题，主张法律根本没有漏洞。双方争论的实质，是司法裁量的性质与范围，进而关乎法治、分权与法官角色的根本理解。", "definition": "法律的不确定性（Indeterminacy of Law）指在法律体系中，存在某些案件使得现行有效规则无法唯一地决定应当如何判决的状态。它既可能来自语言的开放结构（规则的边缘模糊），也可能来自规则之间的冲突，或来自法律存在空隙（法律对某情形未作规定）。\n\n围绕这一概念，形成了几种典型立场。其一，形式主义（Formalism）认为法律规则借助逻辑涵摄可以决定一切案件，不确定性只是表面的，可以通过正确的方法消除。其二，规则怀疑论（Rule-Scepticism）走另一极端：主张所谓规则不过是对法官将如何判决的预测，「谈论规则」是掩盖真相的神话；法律的本质就在于其不确定性。其三，哈特的中间立场：法律既非完全确定，也非完全不确定——它有一个确定的核心，只在边缘地带（penumbra）出现不确定性，此时法官行使「填补空隙的裁量」（interstitial discretion）。其四，德沃金的立场：法律包含原则，原则能为疑难案件提供「唯一正确答案」（Right Answer Thesis），因此法律在诠释意义上是「无漏洞」的。\n\n需要注意的是，哈特在《法律的概念》第七章区分了规则怀疑论的几种形态：激进形态否认一切规则（包括次级规则）的存在，哈特认为这自相矛盾——因为承认法院的存在本身就预设了授予管辖权的次级规则；较温和的形态则只针对初级规则，或仅把怀疑论限定为「关于规则在司法裁判中作用」的理论。", "history": "法律不确定性的争论，根植于二十世纪法理学的两次转向。首先是美国法律现实主义（Legal Realism）的兴起：霍姆斯（Oliver Wendell Holmes Jr.）宣称「法律的生命不在逻辑，而在经验」，现实主义者把注意力从「书本上的法」转向「行动中的法」，强调法官对政策与社会后果的判断决定案件结果，规则的确定性被大幅削弱。其次是二战后对极权主义与形式法治的反思：如果法律可以完全形式化地运作，它是否也能为邪恶政权提供工具？这促使法理学追问 determinate（确定的）规则与法官道德责任的关系。\n\n哈特在《法律的概念》第七章以「开放结构」回应这一背景：既承认现实主义对形式主义的批评有道理，又指出规则怀疑论的夸张。德沃金在 1970 年代以后，以《认真对待权利》(Taking Rights Seriously, 1977) 与《法律帝国》(Law's Empire, 1986) 系统反驳哈特，提出法律原则与建构性诠释，主张法律作为「完整性」能提供唯一正确答案。双方在《后记》(Postscript) 中的交锋，成为这场争论的经典文本。", "principle": "要理清哈特的立场，可分四层。\n\n第一层，确定性与不确定性的分布。哈特认为，法律体系的主体是由确定规则构成的：在反复出现的熟悉情形中，一般语词清楚适用，个人可以「自行适用规则于自身」，无需官方指引。不确定性只出现在边缘——那里支持与反对适用某语词的理由并存，没有约定决定取舍，于是必须作出选择。哈特据此反对规则怀疑论：不能因为边缘有裁量，就说规则整体是神话。\n\n第二层，规则怀疑论的内在矛盾。哈特指出，激进的规则怀疑论主张「不存在规则，只有法院判决及其预测」，但这与「存在法院」的说法不能自洽：法院之所以是法院，正因为它由授予管辖权的次级规则所构成。在一个只有「判决」与「判决预测」观念、却没有「规则」观念的社会里，权威判决的观念本身就无从成立，私人判决与法院判决无法区分。\n\n第三层，规则怀疑论的「失望的绝对主义者」心理。哈特分析，规则怀疑论者往往是一个「失望的绝对主义者」（disappointed absolutist）：他心中的规则是形式主义天堂里那种能预先决定一切的东西；一旦发现真实规则有开放结构、有无法穷尽的例外、法官不会因偏离而受身体制裁，便以「规则根本不存在」来表达失望。哈特认为，这是把一种无法实现的理想当作规则的本质。\n\n第四层，哈特对「确定性」的辩护。哈特并不否认边缘地带的法官造法，但他强调这种造法是有限的、填补空隙的：法官须像「有良知的立法者」一样，依据一般性理由、参考既有法律中已被承认的原则与目的来裁决，而不能任意。他区分了「终局性」（finality）与「无误性」（infallibility）：法官的判决在体系内是终局的，但这不等于它在道德上正确无误。", "viewpoints": "哈特的核心主张可概括为：法律的不确定性是局部的、边缘的，而非整体的。规则有一个确定的核心，法律生活的主体依赖这一核心运行；不确定性来自开放结构，此时法官行使有限的造法权。他批判规则怀疑论把边缘的不确定性夸大为整体否定，也批判形式主义掩盖选择的必要性。\n\n在《后记》中，哈特针对德沃金的「唯一正确答案」命题作出系统回应。德沃金认为，法官在疑难案件中通过建构性诠释，诉诸既「适合」（fit）既有法律又为其提供最佳道德证成的原则，可以找到唯一正确答案。哈特的反驳分几步：其一，许多法律原则是靠「谱系」（pedigree）——即由权威机关以特定方式采纳——而被识别的，并非只能通过诠释；其二，德沃金的诠释性判准本身要预设对「既判法」（preinterpretive law）的识别，而这恰恰需要承认规则；其三，即便法官援引原则进行类比推理，相互竞争的原则之间仍可能需要选择，而法律本身并未给出优先顺序，因此造法的时刻只是被推迟，并未被消除。哈特据此坚持：法官确实在行使「填补空隙的裁量」，只是这种裁量受实体约束、是「插曲式的」（interstitial），不能进行大规模改革。", "comparison": "与形式主义比较：形式主义把法律视为封闭的逻辑体系，相信一切案件都能涵摄得出结论；哈特承认核心地带的确定性，但指出边缘需要目的考量与选择，形式主义只是「在黑暗中预先决定」。\n\n与规则怀疑论比较：规则怀疑论认为不确定性是法律的本质，规则只是预测；哈特认为不确定性是边缘现象，规则的中心地位不可动摇。\n\n与德沃金比较：德沃金认为法律是「无漏洞」的，原则是法律的组成部分，疑难案件有唯一正确答案；哈特认为法律存在空隙，原则是法律的一部分（他承认这一点），但原则不能消除所有选择，法官仍须造法。二者的分歧不在「原则是否属于法律」（哈特在《后记》中已让步），而在「原则能否决定一切案件」。", "debates": "这场争论的三条主线值得细致辨析。\n\n其一，「规则是否存在」之争。规则怀疑论者说规则是神话；哈特回应，若否认一切规则，就无法解释法院与权威判决的存在。这是「概念层面」的争论。\n\n其二，「疑难案件是否有唯一正确答案」之争。德沃金以「法律作为完整性」为裁判找到唯一正确答案；哈特认为类比与原则只能推迟而不能消除选择，法官须行使填补空隙的裁量。这是「裁判层面」的争论。\n\n其三，「司法造法的合法性」之争。德沃金批评司法造法不民主、不正义（溯及既往）；哈特回应：其一，处理法律未调整的案件是避免把问题推给立法机关的必要代价，且法官造法受严格约束、只针对个案；其二，向行政机关委任立法权在现代民主中是常态，向司法机关委任类似权力并无更大威胁；其三，溯及既往的不义在于挫败合理期待，而在法律本就未调整的疑难案件中，并不存在可被挫败的「明确既存法律」下的期待。", "case": "里格斯诉帕尔默案（Riggs v. Palmer, 115 N.Y. 506 (1889)，纽约州上诉法院）是法律不确定性争论的经典案例。帕尔默是被继承人（其祖父）的孙子，也是遗嘱指定的继承人。为避免祖父修改遗嘱剥夺自己的继承权，帕尔默毒杀了祖父。遗嘱本身符合法定形式要件，按继承法的字面规则，帕尔默有权继承。但法院判决他不得继承，理由是：不能允许任何人从自己的错误行为中获利——这是一项法律原则（表现为法谚），它构成对遗嘱继承规则的限制。\n\n这个案子在德沃金与哈特的争论中反复出现。德沃金视之为法律原则提供「唯一正确答案」的范例：即便规则字面支持帕尔默，原则仍给出唯一正解。哈特则会指出：法院在此确实援引了一项既存原则（「任何人不得从自己的错误中获利」本身是有谱系的、被法院一贯援引的原则），但问题的难点在于——当「尊重遗嘱自由」与「不得从错误中获利」两项原则冲突时，法律本身并未规定它们的优先次序，法院必须在它们之间作出选择，正是这种选择体现了填补空隙的裁量。", "caseAnalysis": "就 Riggs v. Palmer 而言，事实是孙子为保住继承权毒杀祖父；争议焦点是：形式有效的遗嘱是否仍应让杀人者继承。法律依据上，继承法的形式规则支持帕尔默，而「不得从自己错误中获利」的原则反对。裁判理由上，法院以原则限制规则的适用，阻止了明显不正义的结果。理论意义在于：第一，它展示了法律规则的开放结构——「遗嘱继承」规则在极端情形下的适用引发疑问；第二，它展示了原则在法律推理中的作用，这是德沃金立场的强论据；第三，它也支持哈特的反驳——两项原则之间的冲突需要判断，法律没有预先给出权重，法院的裁决同时也在「发展法律」。因此，同一案件既可以支持德沃金的「原则决定论」，也可以支持哈特的「裁量必要论」，这正体现了争论的深度。", "summary": "法律的不确定性之争，是形式主义、规则怀疑论、哈特中间道路与德沃金诠释论之间的四角较量。哈特承认规则边缘的开放结构带来局部不确定性，法官须行使填补空隙的有限造法权；他批判规则怀疑论把边缘现象夸大为整体否定，也批判形式主义掩盖选择的必要性。德沃金则以法律原则与「唯一正确答案」命题主张法律无漏洞。双方在规则是否存在、疑难案件是否有唯一正确答案、司法造法是否正当三条主线上全面交锋。Riggs v. Palmer 表明，原则虽能提供裁判理由，但原则之间的冲突仍需选择，这正是争论难以消弭的根源。理解这场争论，是理解司法裁量、法治与法官角色的关键。", "furtherThinking": "1. 如果接受哈特的「填补空隙的裁量」，法官在疑难案件中的选择在何种意义上仍是「法律」的，而非纯粹的个人道德判断？\n2. 德沃金的「唯一正确答案」是否预设了一个全知全能的裁判者（Hercules）？现实法官的能力限制，会不会削弱这一命题的现实意义？\n3. 在人工智能参与裁判的场景中，若算法对疑难案件给出唯一输出，这是否实现了德沃金的理想，还是只是把裁量隐藏到了代码之中？"}, "en": "The Indeterminacy of Law", "level": "debate", "tags": "哈特, 德沃金, 规则怀疑论, 司法裁量, 开放结构", "source": "Hart, The Concept of Law, ch.7, ss.1-4；Hart, The Concept of Law, Postscript, s.6；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；Riggs v. Palmer, 115 N.Y. 506 (1889)", "id": "S3M1K6"}, "S3M1K7": {"title": "最低限度的自然法", "EN": "The Minimum Content of Natural Law", "LEVEL": "core", "TAGS": "哈特, 自然法, 法律与道德, 生存", "TERMS": "最低限度的自然法（Minimum Content of Natural Law）::基于人的自然事实、任何法律体系为维系生存都必须具备的最低内容；自然事实（Natural Facts）::人之为人所共有、进而为法律提供理由的经验事实；生存（Survival）::哈特据以推导法律最低内容的核心目标；相互克制（Mutual Forbearance）::法律与道德共有的、以禁止伤害为核心的最低要求；自然 necessity（Natural Necessity）::基于自然事实与目标、非逻辑必然的必要性", "SOURCE": "Hart, The Concept of Law, ch.9, s.2；Hart, The Concept of Law, ch.5, s.2；Hart, The Concept of Law, ch.9, s.3；Universal Declaration of Human Rights (1948)", "terms": [{"term": "最低限度的自然法（Minimum Content of Natural Law）", "def": "基于人的自然事实、任何法律体系为维系生存都必须具备的最低内容"}, {"term": "自然事实（Natural Facts）", "def": "人之为人所共有、进而为法律提供理由的经验事实"}, {"term": "生存（Survival）", "def": "哈特据以推导法律最低内容的核心目标"}, {"term": "相互克制（Mutual Forbearance）", "def": "法律与道德共有的、以禁止伤害为核心的最低要求"}, {"term": "自然 necessity（Natural Necessity）", "def": "基于自然事实与目标、非逻辑必然的必要性"}], "sections": {"coreQuestion": "法律实证主义坚持「法律与道德可以分离」，这是否意味着法律可以与正义毫无关系？哈特（H. L. A. Hart）在《法律的概念》第九章提出了一个精妙的折中：法律与道德之间虽无「必然的概念联系」，但基于人之为人的某些自然事实，任何法律体系若想维系自身与人类的生存，就「必须」具备某些最低限度的内容——禁止暴力、保护财产、尊重承诺。本节要厘清这一「最低限度的自然法」（Minimum Content of Natural Law）学说的论证结构，说明它与传统自然法有何不同，以及它是否动摇了实证主义的分离命题。", "definition": "最低限度的自然法（Minimum Content of Natural Law）是哈特提出的一项学说：由于人具有某些共同的自然事实，且法律与道德都以「生存」（survival）为目标，任何法律体系若要有意义地存在，就必须包含某些最低限度的内容——对人身的保护（禁止杀害与伤害）、对财产的最低尊重、以及使承诺具有约束力的规则。\n\n这一学说的论证形式是「理性关联」（rational connection）：自然事实本身为法律应当具备某种内容提供了「理由」（reason），而非仅仅是因果条件。哈特严格区分两类关联：其一，因果关联——某些心理、经济条件是法律产生的必要原因，但原因不是「理由」；其二，基于目的的理性关联——如果「生存」是目标，那么某些规则就是达成该目标的手段，因而有理由存在。哈特主张的最低限度自然法属于后者。\n\n哈特列出五项自然事实（Natural Facts）：人的脆弱性（human vulnerability）、大致平等（approximate equality）、有限的利他主义（limited altruism）、有限的资源（limited resources）、有限的理解力与意志力（limited understanding and strength of will）。与这些事实相应，法律必须包含相互克制（Mutual Forbearance）的最低要求：禁止暴力、界定财产、保障承诺。", "history": "自然法传统（Natural Law）源远流长：从斯多葛学派、罗马法学家，经由托马斯·阿奎那（Thomas Aquinas），到近代的格劳秀斯（Hugo Grotius）与洛克（John Locke），其核心主张是法律与道德存在必然联系，违背正义的规则不是真正的法律。法律实证主义（Legal Positivism）兴起后，边沁（Jeremy Bentham）与奥斯丁（John Austin）力图把法律从道德中独立出来。二战后，纳粹德国的法律实践使「法律是否必须合乎道德」成为紧迫问题：富勒（Lon Fuller）以「法律的内在道德」主张法律与道德密不可分；哈特则在 1958 年与富勒论战，坚持分离命题，同时又在《法律的概念》第九章承认「最低限度的自然法」。这一学说正是哈特在实证主义框架内对自然法洞见的有限吸收。", "principle": "哈特的论证可从四层展开。\n\n第一层，五项自然事实。其一，人的脆弱性：人容易受到身体攻击，若无禁止杀害与伤害的规则，任何其他规则都失去意义。哈特以反问点明：「如果没有这些规则，像我们这样的存在者拥有其他任何规则还有什么意义？」其二，大致平等：没有人在体力和智力上强大到能长期支配他人而不需合作——即使最强者也要睡觉。这使相互克制成为必需。其三，有限的利他主义：人介于魔鬼（一心毁灭）与天使（从不伤害）之间，这使相互克制既必要又可能。其四，有限的资源：物资稀缺，需要最低限度的财产制度来稳定预期。其五，有限的理解力与意志力：人并非总能认清长远利益并始终守约，因此需要制裁作为「保障」，防止搭便车者牺牲合作者。\n\n第二层，从自然事实到法律内容。哈特强调，这些事实与法律内容之间是「理性关联」：若目标是生存，则禁止暴力、保护财产、保障承诺就是必要的手段。他称这种必要性为「自然必要性」（natural necessity），它既不属于「法律」一词的语义必然（不属于分析命题），也超出了「大多数法律恰好如此」的事实，它是基于人性与目标的实践必然。\n\n第三层，静态规则与动态规则。哈特指出，前三项事实支撑的主要是「禁止性」的静态规则（不得杀人、尊重财产）；而分工与交换的需要，则产生「动态规则」——转让、交换、立约的能力，使个人能改变自己的法律地位。承诺之所以重要，正在于它为合作提供了最低限度的未来确定性。\n\n第四层，最低内容的局限。哈特特别强调：一项社会要生存，必须对「某些人」提供相互克制的制度，但并不必然对「所有人」提供。奴隶制社会、种族隔离社会的事实说明：法律与道德完全可能把某些群体排除在保护之外。这一限定对哈特至关重要——它使最低限度自然法不再是一个能把不义法律逐出「法律」概念的标准。", "viewpoints": "哈特的核心主张是：法律与道德之间虽无必然的概念联系，但基于人的自然事实与生存目标，任何法律体系都必须具备最低限度的内容（禁止暴力、保护财产、保障承诺）。他称这是自然法学说中「稳健的真理内核」（the core of good sense in the doctrine of Natural Law）。\n\n这一立场有两重意义。其一，它解释了为什么纯粹以「形式」定义法律（不涉及任何内容）会失败——法律必须与人的基本需求相联系才能被理解。其二，它保持了与实证主义分离命题的一致性：最低限度的内容是「基于目标的必然」而非「概念上的必然」，因此并不等于说「不道德的规则就不是法律」。哈特明确写道：这些事实说明，若以生存为目标，法律与道德就应当包含某种内容；但它们并不证明「不道德的规则不可能是法律」。", "comparison": "与传统自然法比较：传统自然法（如阿奎那）主张法律与道德在概念上必然联系，违背正义的法律「不是法律」（lex iniusta non est lex）；哈特的最低限度自然法则是一种「经验的自然法」，其内容来自对人性与生存目标的经验反思，且在逻辑上不否认不义法律仍是法律。\n\n与富勒比较：富勒（Lon Fuller）的「法律的内在道德」强调法律的程序性要求（一般性、公开性、不溯及既往等）与法律概念不可分割；哈特的最低限度自然法则聚焦法律的「实体最低内容」（人身、财产、承诺），并坚持这只是「自然必要性」而非概念必然。\n\n与法律实证主义内部比较：拉兹（Joseph Raz）等「排他实证主义」者倾向于严格限制道德进入法律识别；哈特的「包容实证主义／柔性实证主义」则允许承认规则纳入道德判准，最低限度自然法正是这种开放性的体现之一。", "debates": "围绕最低限度自然法的首要争论，是它是否背叛了实证主义的分离命题。批评者（如部分实证主义者）认为，一旦承认法律「必须」具备某种道德内容，分离命题就被掏空。哈特的辩护者回应：最低限度的必然性是「基于目标的实践必然」，而非「概念必然」；它说明法律若要「有价值地存在」需要什么，却不决定「是不是法律」的判准。因此，分离命题在概念层面仍然成立。\n\n第二个争论关乎这一学说的解释力。有学者（如约翰·菲尼斯 John Finnis、尼尔·麦考密克 Neil MacCormick）提出应修正或扩展哈特的清单，加入更多价值（如「共同善」）；也有学者质疑其「生存」目标设定得过低——如果目标仅是生存，法律的最低内容就十分单薄，难以回应现代人权观念。哈特本人承认，这份清单是「可修正的」，其力量在于展示了一种「理性关联」的论证方式，而非提供一份封闭的绝对清单。", "case": "《世界人权宣言》(Universal Declaration of Human Rights, 1948) 是理解最低限度自然法现实意义的适当例子。二战后，国际社会通过这一宣言，确认了生命权、人身安全、财产权、契约自由等基本权利。从哈特的视角看，这些权利正对应他所说的最低限度自然法的核心内容：对人的保护（生命与人身安全）、对财产的保护、对个人自主与承诺的尊重。宣言以「人之为人的固有尊严」为基础，这与哈特从「人的自然事实与生存目标」出发的论证虽有方法论差异（一为尊严话语，一为经验—目的论证），但在内容上高度重合。\n\n同时，宣言的历史语境也印证了哈特的警示：正是纳粹德国等政权系统地把某些群体排除在法律保护之外，才促成了这一宣言。哈特会指出，宣言所体现的最低内容，是任何值得被称为「法律」的体系都应当具备的，但历史上确实存在过缺乏这些内容的法律体系——这再次说明，最低内容是一种实践上的必然要求，而非判定「是不是法律」的概念标准。", "caseAnalysis": "就《世界人权宣言》而言，事实是 1948 年联合国大会通过这一文件，列举了广泛的基本权利；争议焦点在于：这些权利是「被发现的自然权利」还是「被建构的政治产物」。从哈特的框架看，宣言中的生命、财产、契约等权利，可以借助人的脆弱性、大致平等、有限资源与有限利他主义等自然事实获得解释——这些事实为「法律应当保护什么」提供了理由。法律依据上，宣言本身虽非严格意义的条约，却成为后续国际人权法的基础。理论意义在于：第一，它展示最低限度自然法如何在国际层面获得制度表达；第二，它印证哈特的双重立场——既承认法律需要最低道德内容，又坚持这种承认不等于把不义法律逐出法律概念；第三，它也提示一个张力——以「尊严」为基础的人权话语，与以「生存」为基础的哈特论证，在方法论上并不相同，前者可能提供比哈特更丰富的内容。", "summary": "最低限度的自然法是哈特在实证主义框架内对自然法洞见的有限吸收：基于人的五项自然事实与生存目标，任何法律体系都必须具备禁止暴力、保护财产、保障承诺的最低内容。哈特严格区分「基于目的的理性关联」与「因果关联」，把这种必要性定位为「自然必要性」而非概念必然。这一学说既解释了法律为何不能纯以形式界定，又保持了分离命题——它说明法律为生存「需要」什么，却不决定一条不义规则「是不是」法律。哈特同时强调，最低内容只需惠及「某些人」，奴隶制等历史事实说明它不能成为把不义法律排除出法律概念的标准。", "furtherThinking": "1. 如果「生存」是哈特推导最低内容的目标，那么以「人的繁荣」（flourishing）为目标，是否会得出一份更丰富的权利清单？这会不会模糊哈特与自然法的界限？\n2. 哈特说最低内容只需惠及「某些人」，这一限定是否削弱了他批判极权法律的力量？承认「这是法律」是否反而使批判更清醒？\n3. 在人工智能与基因编辑时代，人的「脆弱性」与「大致平等」等自然事实是否发生了改变？若有，最低限度自然法的内容是否也应随之调整？"}, "en": "The Minimum Content of Natural Law", "level": "core", "tags": "哈特, 自然法, 法律与道德, 生存", "source": "Hart, The Concept of Law, ch.9, s.2；Hart, The Concept of Law, ch.5, s.2；Hart, The Concept of Law, ch.9, s.3；Universal Declaration of Human Rights (1948)", "id": "S3M1K7"}, "S3M2K1": {"title": "法律与道德是否必须分离", "EN": "Must Law and Morality Be Separated?", "LEVEL": "debate", "TAGS": "哈特, 富勒, 法律与道德, 分离命题, 实证主义", "TERMS": "分离命题（Separation Thesis）::法律的存在与内容在概念上不取决于道德价值的立场；法律实证主义（Legal Positivism）::主张法律识别最终诉诸社会事实而非道德的理论；自然法理论（Natural Law Theory）::主张法律与道德存在必然联系的理论；法律的内在道德（Inner Morality of Law）::富勒提出的法律程序性要求（一般性、公开性等）；哈特—富勒论战（Hart-Fuller Debate）::1958年围绕法律与道德关系的著名论战；明确法（Positive Law）::由权威制定或承认的法律", "SOURCE": "Hart, The Concept of Law, ch.9；Hart, 'Positivism and the Separation of Law and Morals' (1958) 71 Harvard Law Review 593；Lon Fuller, 'Positivism and Fidelity to Law' (1958) 71 Harvard Law Review 630；Hart, The Concept of Law, Postscript, s.5", "terms": [{"term": "分离命题（Separation Thesis）", "def": "法律的存在与内容在概念上不取决于道德价值的立场"}, {"term": "法律实证主义（Legal Positivism）", "def": "主张法律识别最终诉诸社会事实而非道德的理论"}, {"term": "自然法理论（Natural Law Theory）", "def": "主张法律与道德存在必然联系的理论"}, {"term": "法律的内在道德（Inner Morality of Law）", "def": "富勒提出的法律程序性要求（一般性、公开性等）"}, {"term": "哈特—富勒论战（Hart-Fuller Debate）", "def": "1958年围绕法律与道德关系的著名论战"}, {"term": "明确法（Positive Law）", "def": "由权威制定或承认的法律"}], "sections": {"coreQuestion": "「法律与道德应当分开」是法理学中最著名也最容易被误解的命题。二战后，面对纳粹德国以「合法」形式犯下的暴行，人们迫切追问：那些邪恶的规则究竟算不算法律？如果算，是否意味着我们承认它的正当性？1958 年，哈特（H. L. A. Hart）与富勒（Lon Fuller）在《哈佛法律评论》上展开了一场载入史册的论战。本节要精确呈现「分离命题」的含义，还原双方论据，并回答一个关键问题：把法律与道德分开，究竟是在为恶法张目，还是在为批判恶法提供更清醒的工具？", "definition": "分离命题（Separation Thesis）是法律实证主义的核心主张：一条规则是否属于法律，取决于它是否由合法权威按正确程序制定或承认（即其「来源」），而不取决于它是否道德上正当。它包含几层意思：其一，在概念上，「是不是法律」与「是不是道德上善」是两个不同的问题；其二，存在道德上恶劣却仍然有效的法律；其三，法律的识别无须诉诸道德判断，除非该法律体系自身把道德纳入了效力判准。\n\n需要警惕对分离命题的两种误读。误读之一：实证主义主张「法律不需要道德」或「法律与道德事实上毫无关系」。哈特明确反对这种漫画化——他承认法律与道德在事实上常常相互渗透，也承认法律必须满足「最低限度的自然法」才能维持自身。误读之二：实证主义主张「恶法亦法」意味着「恶法应当被遵守」。哈特强调，「承认它是法律」与「是否应当服从它」是两个判断；承认恶法的效力，恰恰是为了更清醒地指出「正因为它有效力，我们更有道德义务抵抗它」。\n\n对立的一方是自然法理论（Natural Law Theory），其经典命题是「恶法非法」（lex iniusta non est lex）——严重违背正义的规则不是真正的法律。富勒则提出「法律的内在道德」（Inner Morality of Law），强调法律作为「使人类行为服从规则治理的事业」，本身包含程序性的道德要求（一般性、公开性、不溯及既往、不矛盾等）；严重违反这些要求的规则，就丧失了法律的资格。", "history": "分离命题的争论有深远的思想史背景。近代以前，自然法传统长期主导，法律的正当性被追溯到神的理性或自然理性。近代民族国家兴起后，边沁（Jeremy Bentham）与奥斯丁（John Austin）转向以「命令」界定法律，力图把法律从道德中独立出来，使之成为可经验研究的对象。奥斯丁的名言是：「法律的存在是一回事，它的优缺点是另一回事。」\n\n二十世纪的极权主义经验，使这一争论获得了空前的紧迫性。纳粹德国通过形式合法的立法程序，制定了系统迫害犹太人的法律。战后，德国法院在审判那些依据纳粹法律行事的人时，面临难题：如果纳粹法律是有效法律，行为人是否只是「执行法律」？如果它们根本不是法律，又以什么标准把它们排除？富勒与哈特在 1958 年的论战，正是围绕这些问题展开。理解分离命题，必须把它放回这段思想史脉络。", "principle": "要精确把握分离命题，可分四层。\n\n第一层，「存在」与「价值」的区分。哈特延续奥斯丁的问题意识，但以更精致的方式表达：判断一条规则是否存在（是否属于法律体系），与评价它是否正当，是两个不同的问题。前者是一个可以用社会事实回答的问题（它是否被按正确程序制定），后者则涉及道德价值。把两者分开，有助于避免用道德争议模糊法律识别的清晰标准。\n\n第二层，分离命题的「概念性」限定。哈特反复强调，他主张的是「概念上」可以分离，而非「事实上」总是分离。法律与道德在内容上经常重合（如禁止杀人既是法律也是道德要求），但「重合」不等于「必然联系」。概念上的可分离性，意味着我们可以设想一条规则是有效法律却道德恶劣——纳粹法律就是这种可能性的现实例证。\n\n第三层，分离命题的批判价值。哈特在《实证主义与法律与道德的分离》一文中指出，正是在「法律是什么」的问题上保持清晰，才能使道德批判更有力量。把邪恶规则承认作法律，然后说「它虽然是法律，但如此邪恶，以至于我必须抵抗它」，比简单地说「它不是法律」更能准确地定位问题：需要变革的，正是这套有效的法律制度本身。\n\n第四层，柔性实证主义的限定。哈特后来承认，一个社会的承认规则可以把道德原则纳入效力判准（如美国宪法中的平等保护条款）。这意味着「法律识别在事实上不需要道德」并非绝对——当法律自身把道德纳入时，识别就需要道德判断。但这一点与分离命题并不矛盾，因为「法律是否纳入道德」本身是由社会事实（承认规则的内容）决定的。", "viewpoints": "哈特的核心主张是：法律与道德在概念上可以分离，一条规则是不是法律，最终取决于社会承认的效力判准，而非其道德价值；但这种分离不是否认二者的事实联系，也不是主张恶法应当被服从。他坚持，承认恶法的法律地位，能使我们更清醒地批判它。\n\n富勒的核心主张则相反：法律是一种有目的的事业，其本身包含「内在道德」——八项程序性要求（规则的一般性、公开性、不溯及既往、清晰、不矛盾、不要求不可能之事、稳定性、官方行动与宣布的规则的一致性）。这些要求虽是「程序性」而非「实体性」的，却构成法律之所以为法律的内在道德。纳粹法律之所以在某些方面还不算彻底的法律，正因为它在这些程序要求上存在严重缺陷（如秘密法、溯及既往）。富勒的论点是：法律与道德在「内在道德」层面必然联系，实证主义对「分离」的坚持，削弱了人们抵抗恶法的道德资源。", "comparison": "与奥斯丁比较：哈特继承了奥斯丁「存在与价值区分」的问题意识，但摒弃了其命令理论，以承认规则为基础重建分离命题，使之更精致、更能解释授权性规则。\n\n与凯尔森比较：凯尔森的纯粹法学也主张法律与道德分离，但更彻底——他试图把法律从一切意识形态中净化；哈特则承认法律与道德在事实层面的渗透，并承认最低限度的自然法，立场更温和。\n\n与德沃金比较：德沃金在《后记》所针对的批评中，主张法律命题必然包含道德判断，因为法律包含原则，而识别原则需要诠释与道德证成。哈特回应：承认规则可以纳入道德判准（柔性实证主义），但这仍是社会事实决定的；德沃金把「法律包含道德」推向了「法律识别必然是道德判断」，这一步走得太远。", "debates": "哈特—富勒论战的核心交锋点有三。\n\n其一，「分离是否削弱抵抗恶法的能力」。富勒认为，实证主义把法律与道德分开，使人习惯于把任何既存规则都当作「法律」而服从，从而削弱了抵抗纳粹暴政的道德资源。哈特反驳：历史经验恰恰提供了相反的教训——在德国，正是法律实证主义的流行，使法律人把纳粹法令当作「法律」而放弃抵抗；正确的应对在于明确「服从法律并非最高的道德义务」，否认这些规则是法律则解决不了问题。哈特认为，混淆法律与道德，反而可能导致「因为是法律所以说它正当」的危险。\n\n其二，「法律的内在道德是否构成法律的概念要素」。富勒认为，法律若严重违反程序性道德要求，就丧失法律资格。哈特回应：这些要求虽有价值，但把它们作为「法律」的必要条件会造成概念混乱——我们完全可以在保留「法律」一词的同时，明确指出某规则在道德上不可接受；用「不是法律」来谴责，反而模糊了批判的锋芒。\n\n其三，「极端邪恶的法律体系是否还是法律」。德沃金后来提出「内部怀疑论」：对于极其邪恶的体系，我们可以拒绝承认其为法律。哈特在《后记》中回应：这种「内部怀疑论」实际上承认了实证主义者的观点——我们完全可以说「它是法律，但邪恶」，这一表述在多数语境下更有用；把极端邪恶的体系逐出法律概念，并不能自动带来道德上的好处。", "case": "「告密者案」（the grudge informer case）是哈特—富勒论战共同引用的思想实验，其原型来自纳粹德国时期的一个真实情境：一名妻子为摆脱丈夫，依据纳粹时期的一项法律向当局告发丈夫发表了对希特勒的侮辱性言论，导致丈夫被处决。战后，她因「非法剥夺他人自由」被审判。辩护方主张：她的行为符合当时有效的纳粹法律，不构成犯罪。\n\n富勒与哈特借这一情境展开交锋。富勒认为，纳粹那种允许公民因言论而被处死、且具溯及既往与秘密性的法律，严重违反法律的内在道德，因此丧失法律资格，妻子不能援引它作为抗辩。哈特则认为，更好的分析是：承认纳粹法律是有效法律（它是按当时程序制定的），但也承认它极端邪恶；战后德国法院面临一个真正的选择——要么适用「法不溯及既往」原则而释放被告，要么通过一项新的、溯及既往的法律来惩罚她。哈特承认后一选择代价沉重（牺牲了法的安定性），但强调必须诚实面对这一道德抉择，而不是通过宣称「纳粹法律不是法律」来回避它。", "caseAnalysis": "就告密者案而言，事实是妻子依纳粹法律告发丈夫致其死亡，战后因此受审；争议焦点是：纳粹法律是否赋予她免受惩罚的正当依据。从哈特视角看，纳粹法律在形式上有效，故妻子依其行为时的法律并未违法；战后若以溯及既往的新法惩罚她，就牺牲了「法不溯及既往」这一重要的法治价值——这是一个真正的道德两难，不允许用「纳粹法律不是法律」的口号来逃避。从富勒视角看，纳粹法律严重违反内在道德，根本不是法律，故妻子不能主张「依法行事」。\n\n理论意义在于：第一，它把「分离命题」的抽象争论落到了具体的司法两难；第二，它显示哈特立场的力量——直面道德抉择的艰难，而非用定义技巧回避；第三，它也暴露哈特立场的张力——如果「法律」与「道德」可以如此彻底分离，法治所珍视的安定性价值如何得到保障？富勒的批评在这里仍有分量。这一案例至今仍是法理学课堂上讨论法律与道德关系的首选素材。", "summary": "分离命题是法律实证主义的核心主张：一条规则是否属于法律，取决于其社会来源而非道德价值；「是不是法律」与「是不是道德上正当」是两个可分开判断的问题。哈特—富勒论战围绕分离是否削弱抵抗恶法的能力、法律的内在道德是否构成法律的概念要素、极端邪恶的法律是否仍是法律三条主线展开。哈特坚持，承认恶法为法反而能使道德批判更清醒；富勒则以「法律的内在道德」主张法律与道德有必然联系。告密者案将争论落到具体的司法两难，显示两种立场各自的力量与张力。理解这场论战，是理解法理学中法律与道德关系全部讨论的入口。", "furtherThinking": "1. 如果纳粹法律在形式上完全符合「一般性、公开性、不溯及既往」等内在道德要求，富勒的论证还站得住脚吗？这是否说明内在道德不足以区分法律与暴政？\n2. 哈特说「承认恶法是法律，使抵抗更清醒」，这一主张是否预设了人们会自发地作出道德抵抗？若一个社会普遍缺乏这种道德自觉，分离命题是否会变为服从的借口？\n3. 在当代反恐或紧急状态立法中，当法律以「安全」为名克减基本权利，分离命题提醒我们区分哪两个问题？"}, "en": "Must Law and Morality Be Separated?", "level": "debate", "tags": "哈特, 富勒, 法律与道德, 分离命题, 实证主义", "source": "Hart, The Concept of Law, ch.9；Hart, 'Positivism and the Separation of Law and Morals' (1958) 71 Harvard Law Review 593；Lon Fuller, 'Positivism and Fidelity to Law' (1958) 71 Harvard Law Review 630；Hart, The Concept of Law, Postscript, s.5", "id": "S3M2K1"}, "S3M2K2": {"title": "法律的道德基础", "EN": "The Moral Foundations of Law", "LEVEL": "core", "TAGS": "法律与道德, 富勒, 内在道德, 合法性", "TERMS": "法律的内在道德（Inner Morality of Law）::富勒提出的、法律作为规则治理事业所固有的程序性道德要求；合法性（Legality）::法律在形式上应满足的最低程序品质；程序自然法（Procedural Natural Law）::以程序要求而非实体价值界定法律道德性的思路；法的安定性（Legal Certainty）::法律应为人们提供可预测的行为指引的品质；实质正义（Substantive Justice）::法律内容在权利义务分配上的公正性", "SOURCE": "Lon Fuller, The Morality of Law (1964), chs.1-4；Hart, 'Positivism and the Separation of Law and Morals' (1958)；Hart, The Concept of Law, ch.9, s.2；《世界人权宣言》(1948)", "terms": [{"term": "法律的内在道德（Inner Morality of Law）", "def": "富勒提出的、法律作为规则治理事业所固有的程序性道德要求"}, {"term": "合法性（Legality）", "def": "法律在形式上应满足的最低程序品质"}, {"term": "程序自然法（Procedural Natural Law）", "def": "以程序要求而非实体价值界定法律道德性的思路"}, {"term": "法的安定性（Legal Certainty）", "def": "法律应为人们提供可预测的行为指引的品质"}, {"term": "实质正义（Substantive Justice）", "def": "法律内容在权利义务分配上的公正性"}], "sections": {"coreQuestion": "如果法律与道德在概念上可以分离，那么法律还有没有「道德基础」可言？这个问题看似矛盾，实则触及法理学最深的层面。法律凭什么要求人们服从？它的正当性从何而来？富勒（Lon Fuller）会说，法律之所以配称为法律，正因为它是「使人类行为服从规则治理的事业」，这项事业本身内含一套程序性的道德要求。哈特（H. L. A. Hart）则会补充，法律还需具备基于人性的最低实体内容。本节要厘清：法律的道德基础究竟指什么？它与法律的「效力」是什么关系？形式合法性能否担保实质正义？", "definition": "法律的道德基础，指法律之所以具有正当性、之所以值得人们服从所依赖的道德根据。它至少可在三个层面讨论。\n\n其一，程序性基础：富勒的「法律的内在道德」（Inner Morality of Law）。富勒认为，法律是「使人类行为服从规则治理的事业」（the enterprise of subjecting human conduct to the governance of rules），这项事业要成功，规则必须满足八项程序性要求：一般性（generality）、公开性（promulgation）、不溯及既往（non-retroactivity）、清晰性（clarity）、不矛盾（non-contradiction）、不要求不可能之事（not requiring impossible acts）、稳定性（stability）、官方行动与宣布的规则相一致（congruence）。富勒称这些要求为「法律的内在道德」，因为它们从法律这一事业的内部产生，而非外部强加。\n\n其二，实体性基础：哈特的「最低限度的自然法」。基于人的自然事实与生存目标，法律必须包含对人身、财产与承诺的最低保护。这是法律在内容上必须具备的道德底色。\n\n其三，社会性基础：法律的权威需要被治者的某种接受。哈特强调，法律体系的存在要求官员从内部观点接受次级规则；公民虽可出于各种动机服从，但法律若要稳定，通常需要相当程度的自愿合作。", "history": "对法律道德基础的追问，贯穿整个法理学史。自然法传统把法律的道德基础追溯到神意、自然理性或人的本性；法律实证主义兴起后，则倾向于把正当性问题从法理学中排除，专注于描述法律「实际上是什么」。然而，二战的极权主义经验重新激活了这一追问：如果法律与道德彻底分离，法律人如何在纳粹的「合法」暴行面前保持道德立场？\n\n富勒在《实证主义与忠于法律》(1958) 和《法律的道德性》(The Morality of Law, 1964) 中提出「内在道德」，试图在实证主义与自然法之间寻找第三条道路：法律的道德性不在其实体内容（那是「外在道德」），而在其程序形式。哈特则在批判富勒的同时，以「最低限度的自然法」承认法律需要某种实体最低内容。两人的争论，使「法律的道德基础」成为法理学的核心议题。", "principle": "理解法律的道德基础，可分四层。\n\n第一层，程序道德与实体道德的区分。富勒严格区分「法律的内在道德」（程序性）与「法律的外在道德」（实体性，即法律应当促进的善）。他关心的是法律作为规则治理事业是否「运作良好」，法律内容是否正义属于另一层评价。一项秘密制定的法律，即便内容公正，也因缺乏公开性而破坏了「使人们服从规则治理」的事业。\n\n第二层，八项要求的具体含义。一般性要求规则针对一类人而非特定个人；公开性要求规则被颁布使受众知晓；不溯及既往要求规则不惩罚行为时合法的行为；清晰性要求规则可被理解；不矛盾要求规则之间不冲突；不要求不可能之事要求规则在能力范围内；稳定性要求规则不频繁变动；一致性要求官方行动与宣布的规则相符。富勒认为，严重违反这些要求的规则体系，不仅是「坏的法律」，甚至难以被称为法律。\n\n第三层，内在道德与「忠于法律」。富勒强调，内在道德是「忠于法律」（fidelity to law）的职业道德基础。法律人之所以应当忠于法律，正因为法律事业本身蕴含道德；如果法律丧失了内在道德，忠实的法律人反而有理由抵抗。\n\n第四层，哈特的回应与修正。哈特承认富勒的八项要求大都是有价值的，但反对把它们当作「法律」的必要条件。他认为，把「缺乏内在道德」等同于「不是法律」会造成概念混乱；更好的做法是承认「这是法律，但它在程序上如此缺陷，以至于不值得服从」。哈特同时以自己的「最低限度自然法」补充：法律不仅需要程序品质，还需要基于人性的实体最低内容。", "viewpoints": "富勒的核心主张是：法律有其内在道德，即一套程序性的合法性要求；这些要求从法律作为规则治理事业的内部产生，是法律正当性的基础，也是法律人忠于法律的理由。法律若严重违反内在道德，就丧失了法律的资格。\n\n哈特的核心主张则是：法律的道德基础是有限度的。他承认法律与道德在事实层面相互渗透，也承认法律需要「最低限度的自然法」和某种程度的自愿接受，但坚持这些都是「自然必要性」或事实条件，而非法律的概念要素。法律的「效力」与法律的「道德价值」仍应分开判断；把道德价值塞进法律的概念，反而会模糊批判的锋芒。", "comparison": "与奥斯丁比较：奥斯丁以「命令—威胁」为法律基础，几乎不谈道德；富勒与哈特都超越了这一模型，但方向不同——富勒强调程序道德，哈特强调社会事实与最低内容。\n\n与自然法传统比较：传统自然法（如阿奎那）以实体正义为法律的道德基础；富勒把道德基础「程序化」，只要求形式品质，不要求特定实体价值；哈特则承认有限的实体最低内容，但拒绝把它上升为效力标准。\n\n与德沃金比较：德沃金把法律的正当性基础追溯到「法律作为完整性」——法律不仅要有程序一致性，还要在道德上为其所实施的强制提供最佳证成。这比富勒的程序道德更进一步，把实体道德重新引入法律的概念核心。", "debates": "首要争论是「程序道德是否足以构成法律的道德基础」。哈特批评富勒的八项要求中，有些只是「效率」要求（如清晰、不矛盾有助于法律运作），把它们拔高为「道德」可能混淆了「有效运作的条件」与「道德上值得赞许」。富勒回应：这些要求之所以是道德的，正因为它们尊重了人作为理性主体的尊严——秘密法、溯及既往的法律把人当作可以任意摆布的对象，而非能够自我指导的主体。\n\n第二个争论关乎「合法性与正当性的关系」。富勒倾向于把合法性（legality）本身视为一种正当性——程序上合法的法律就具有道德分量。哈特则坚持合法性只是法律的一种「自然善」（natural good），它使法律能有效服务于人的目的，但并不能自动使法律在道德上正当；一部程序完美却内容邪恶的法律，仍然是应该被抵抗的。这一分歧，实质上是「程序正义能否独立担保实质正义」的争论。", "case": "《世界人权宣言》(Universal Declaration of Human Rights, 1948) 为理解法律的道德基础提供了具体载体。宣言在序言中确认「对人类家庭所有成员的固有尊严及其平等权利的承认」，并列举了生命权、人身安全、免受奴役、财产权、言论与信仰自由等一系列权利。从富勒的视角看，宣言所确立的权利清单既包含程序性保障（如依法成立独立公正的法庭、无罪推定），也包含实体性价值（如生命与尊严）。从哈特的视角看，宣言中生命、财产、契约自由等权利，正对应其「最低限度自然法」的核心内容，可以获得基于人性与生存目标的解释。\n\n宣言的历史语境同样重要：它诞生于纳粹暴行之后，是对「法律形式合法却实体极端邪恶」这一教训的直接回应。它提示我们：法律的道德基础不能仅有程序合法性——一部符合富勒八项要求却系统侵犯基本人权的法律，仍然违背了人类对法律的最低道德期待。这一点，既是对富勒程序论的补充，也在一定程度上支持了德沃金把实体道德纳入法律理解的方向。", "caseAnalysis": "就《世界人权宣言》而言，事实是 1948 年联合国大会通过这一文件，确立了广泛的基本权利；争议焦点在于：这些权利是「发现」的自然权利，还是「建构」的政治产物。从哈特的框架看，生命权、财产权、契约自由可借助人的脆弱性、大致平等、有限资源等自然事实获得解释——这些事实为法律应当保护什么提供了理由。从富勒的框架看，宣言中的程序性权利（公平审判、无罪推定）体现了法律的内在道德。宣言以「固有尊严」为基础，与哈特以「生存」为基础、富勒以「规则治理事业」为基础，方法论各不相同。\n\n理论意义在于：第一，它显示法律的道德基础是多层面的——程序合法性、实体最低内容、人的尊严话语都在其中发挥作用；第二，它印证哈特的双重立场——法律需要最低道德内容，但这种承认不把不义法律逐出法律概念；第三，它也揭示了一个张力——「尊严」话语所能支撑的权利，远比哈特的「生存」目标丰富，这提示哈特的最低内容可能设定得过低。", "summary": "法律的道德基础可从程序、实体、社会三个层面理解。富勒的「法律的内在道德」提出八项程序性要求，认为它们从法律作为规则治理事业的内部产生，是法律正当性与法律人忠于法律的根据；哈特则以「最低限度的自然法」承认法律需要基于人性的实体最低内容，并指出法律权威需要某种程度的自愿接受。哈特反对把程序要求当作法律的概念要素，主张合法性只是「自然善」，不自动担保实质正义。《世界人权宣言》显示，法律的道德基础是多层的，尊严话语支撑的权利比哈特的生存目标更丰富。", "furtherThinking": "1. 富勒的八项程序要求中，哪些是真正的「道德」要求，哪些只是「效率」要求？这个区分会影响富勒论证的力度吗？\n2. 一部在程序上完全合法（符合八项要求）却系统侵犯少数群体权利的法律，在富勒与哈特那里分别会得到什么评价？哪种评价更有批判力？\n3. 若把「人的尊严」作为法律道德基础的核心，这在何种意义上超出了哈特「生存」目标的框架？这种超出是理论的进步还是概念的混淆？"}, "en": "The Moral Foundations of Law", "level": "core", "tags": "法律与道德, 富勒, 内在道德, 合法性", "source": "Lon Fuller, The Morality of Law (1964), chs.1-4；Hart, 'Positivism and the Separation of Law and Morals' (1958)；Hart, The Concept of Law, ch.9, s.2；《世界人权宣言》(1948)", "id": "S3M2K2"}, "S3M2K3": {"title": "恶法是否非法", "EN": "Is an Unjust Law Still Law?", "LEVEL": "debate", "TAGS": "恶法非法, 拉德布鲁赫, 自然法, 实证主义, 法律与道德", "TERMS": "恶法非法（Lex Iniusta Non Est Lex）::严重违背正义的规则不是真正法律的命题；拉德布鲁赫公式（Radbruch Formula）::拉德布鲁赫提出的、极端不正义的法律应让位于正义的公式；不可容忍性（Intolerability）::拉德布鲁赫公式中法律与正义冲突达到极限的标准；法的安定性（Legal Certainty）::法律可提供稳定行为预期的价值；恶法亦法::实证主义在效力意义上承认邪恶规则仍是法律的立场", "SOURCE": "Hart, The Concept of Law, ch.9；Hart, 'Positivism and the Separation of Law and Morals' (1958)；Lon Fuller, 'Positivism and Fidelity to Law' (1958)；Gustav Radbruch, 'Statutory Lawlessness and Supra-Statutory Law' (1946)；纽伦堡审判 (1945-1946)", "terms": [{"term": "恶法非法（Lex Iniusta Non Est Lex）", "def": "严重违背正义的规则不是真正法律的命题"}, {"term": "拉德布鲁赫公式（Radbruch Formula）", "def": "拉德布鲁赫提出的、极端不正义的法律应让位于正义的公式"}, {"term": "不可容忍性（Intolerability）", "def": "拉德布鲁赫公式中法律与正义冲突达到极限的标准"}, {"term": "法的安定性（Legal Certainty）", "def": "法律可提供稳定行为预期的价值"}, {"term": "恶法亦法", "def": "实证主义在效力意义上承认邪恶规则仍是法律的立场"}], "sections": {"coreQuestion": "「恶法非法」(lex iniusta non est lex) 是自然法传统最响亮的口号，也是二战后清算纳粹遗产时最有号召力的命题。然而，这句口号经不起细想：如果一条法律因为「邪恶」就自动不是法律，那么「邪恶」由谁定义、依据什么标准？不同人对正义有不同理解，会不会导致「人人皆可宣称不喜欢的法律不是法律」，从而瓦解法治所依赖的安定性？本节要深入辨析「恶法是否非法」这场争论：呈现自然法与实证主义各自的论证，分析拉德布鲁赫公式这一著名的折中方案，并回答——「承认恶法是法律」是否必然意味着道德上的妥协？", "definition": "恶法非法（Lex Iniusta Non Est Lex）主张：严重违背正义的法律不是真正的法律。其逻辑是：法律的概念本身就包含正义，因此不正义的规则在概念上被排除出法律范畴。这一命题在二战后被广泛用来否定纳粹法律的正当性。\n\n与之相对的是实证主义的立场，常被概括为「恶法亦法」——但这一表述需要精确理解。实证主义者的主张是：一条规则是不是法律，取决于它的社会来源（是否按正确程序制定），而非其道德内容。因此，一条道德上极端邪恶的规则，只要符合效力判准，仍然是「法律」——但这并不等于说它是「道德上正当的法律」，更不等于说应当服从它。哈特（H. L. A. Hart）尤其强调，「承认它是法律」与「认为它应当被服从」是两个不同的判断。\n\n拉德布鲁赫公式（Radbruch Formula）是介于两者之间的著名方案。古斯塔夫·拉德布鲁赫（Gustav Radbruch）在 1946 年提出：当法律与正义的冲突达到「不可容忍」（intolerable）的程度，法律就必须让位于正义；但若冲突尚不至于不可容忍，即便法律不正，仍应维护法的安定性（legal certainty）。这一公式试图在正义与法的安定性之间划出一条界线。", "history": "「恶法非法」的思想可追溯到古希腊与中世纪：斯多葛学派与阿奎那（Thomas Aquinas）都主张人法若违背自然法或神法就不是真正的法律。近代实证主义兴起后，这一命题被搁置；边沁（Jeremy Bentham）称其为「无政府主义的口号」。\n\n二战后，纳粹德国以形式合法的立法程序实施了种族灭绝，使这一命题获得空前的现实意义。德国法院在审判纳粹分子与「告密者」时，必须决定：是否援引「恶法非法」来否定纳粹法律的有效性？拉德布鲁赫公式正是在这一背景下提出，成为战后德国司法实践的重要理论工具。与此同时，哈特与富勒（Lon Fuller）在 1958 年围绕「实证主义与忠于法律」展开论战，使「恶法是否非法」成为英语世界法理学的核心议题。", "principle": "要辨析这一争论，可分四层。\n\n第一层，「非法」的两种含义。「恶法非法」中的「非法」可以有两种理解：其一，效力意义上的「不是有效法律」（not valid law）；其二，道德意义上的「不配称为法律、不值得服从」。自然法倾向于前者——正义是法律的概念要素；实证主义则坚持，若把道德不正当等同于「无效」，就会混淆两个不同的判断。\n\n第二层，概念论证与价值判断。自然法论证说：法律的概念内含正义，故恶法在概念上不是法律。实证主义反驳：日常生活中我们完全可以理解并谈论「一条有效但不正义的法律」，这说明「法律」与「正义」在概念上可分离；把不正义的法律逐出法律概念，并非逻辑必然。\n\n第三层，「不可容忍性」的门槛。拉德布鲁赫公式的关键，是设定一条界线：只有当法律与正义的冲突「不可容忍」时，正义才压倒法的安定性。这一门槛试图回应实证主义对「人人自定正义标准」的担忧——只有极端情形才触发例外，日常案件仍以安定性为重。但批评者指出，「不可容忍」本身仍是模糊的、需要判断的。\n\n第四层，后果考量。哈特强调，把恶法逐出法律概念未必带来好处。如果一条规则不被承认是法律，法官就失去了一个明确的批判对象——「正是这套有效的法律制度需要被改革」。相反，承认它是法律，然后明确说它极端邪恶、必须抵抗，反而更准确地定位了问题。", "viewpoints": "哈特的核心主张是：道德上邪恶的规则完全可以是有效法律；「恶法非法」的错误在于把道德评价混同于效力判断。他承认，在极端邪恶的情形下，人们可以选择拒绝把某体系称为法律（如德沃金后来所说的「内部怀疑论」），但这是一种道德抉择，而非概念真理；更常用、更有力的做法，是承认「它是法律，但它邪恶到必须抵抗」。\n\n德沃金的核心立场则更为微妙：他区分「诠释意义上的法律」与「前诠释意义上的法律」，承认极端邪恶的体系可以「在前诠释意义上」是法律，但在诠释意义上（即为其强制寻找道德证成时）可能不被承认。哈特回应说，这种区分实际上向实证主义靠拢——它承认了「是否法律」的判断可以脱离道德而作出。\n\n富勒则坚持：法律若严重违反内在道德（如秘密法、溯及既往），就丧失了法律资格；纳粹法律正是这种情形。拉德布鲁赫公式则以「不可容忍性」为门槛，为否认极端邪恶法律的有效性提供了具体标准。", "comparison": "与传统自然法比较：传统自然法（阿奎那）以「违背理性即非法律」为公式，标准宽泛；拉德布鲁赫公式以「不可容忍性」为门槛，更为审慎，力图兼顾安定性。\n\n与法律实证主义比较：实证主义坚持「存在与价值区分」，认为恶法在效力意义上仍是法律；这与拉德布鲁赫在极端情形下的例外形成对照。但两者并非毫无共识——拉德布鲁赫公式只在极端情形突破安定性，日常仍维护法的确定性。\n\n与哈特的最低限度自然法比较：哈特承认法律需要最低内容，但把它定位为「自然必要性」而非效力标准；拉德布鲁赫则明确让正义在极端情形下压倒法律效力。后者比哈特更愿意用道德推翻效力。", "debates": "争论的第一条主线是「恶法是否仍是法律」。自然法（含拉德布鲁赫）说：极端邪恶的法律丧失法律资格；实证主义（哈特）说：它仍是有效法律，只是道德上恶劣。双方都承认纳粹法律道德上极端邪恶，分歧在于是否用「非法」来标记这种邪恶。\n\n第二条主线是「用『非法』来谴责是否更有力」。富勒认为，否认纳粹法律的法律资格，能更有力地维护法律的道德尊严。哈特反驳：说「纳粹法律不是法律」反而遮蔽了其性质——纳粹暴行恰恰是通过一套有效的法律制度实施的；承认它有效，才能准确说明「需要被彻底变革的正是这套制度」。\n\n第三条主线是「安定性 vs 正义」。实证主义强调，若允许以「正义」为由否定法律效力，就会打开主观判断的洪水闸门，人人可宣称自己不认同的法律「非法」，法治将荡然无存。拉德布鲁赫以「不可容忍性」门槛回应，但这一门槛的模糊性始终受到质疑。", "case": "纽伦堡审判（Nuremberg Trials, 1945–1946）是「恶法是否非法」争论的集中体现。二战结束后，同盟国设立国际军事法庭，审判纳粹主要战犯。辩论中的一个核心问题是：被告实施的行为在当时德国法律下可能是「合法」的（如执行元首命令、依据纳粹法令行事），事后以「反和平罪」「战争罪」「反人道罪」起诉，是否构成不公正的溯及既往？\n\n一种回答是：纳粹法律因极端邪恶而根本不是法律，被告不能主张「依法行事」——这是「恶法非法」的思路。另一种回答（更接近哈特）是：即便纳粹法律在形式上有效，它极端邪恶，被告在道德上仍有服从更高原则的义务；国际法庭所适用的「反人道罪」，是对极端邪恶行为的必要回应——这承认了道德判断的必要性，但不必否认纳粹法律的形式有效性。\n\n纽伦堡审判的深远影响在于：它确立了「个人对国际社会负有高于国家法律的义务」这一原则，同时也暴露了「以道德名义突破实定法」所面临的法理难题——如何在惩罚暴行与维护法不溯及既往之间取得平衡，至今仍是国际刑法的核心问题。", "caseAnalysis": "就纽伦堡审判而言，事实是被告依当时有效的德国法律行事，却因反人道罪受审；争议焦点是：事后定罪是否正当，以及纳粹法律能否作为抗辩。从「恶法非法」视角看，纳粹法律极端违背正义，自始无效，故「依法行事」不构成抗辩。从哈特的视角看，承认纳粹法律在形式上有效，但强调道德义务可以、而且应当压倒对邪恶法律的服从；这既避免了「人人自定正义」的任意性，又直面了道德抉择。\n\n从拉德布鲁赫公式看，纳粹法律与正义的冲突已达到「不可容忍」程度，故正义应压倒法的安定性。理论意义在于：第一，案例把抽象争论落实为「溯及既往的正当性」这一具体难题；第二，它显示三种立场各有解释力——自然法更有道德感召力，实证主义更有助于准确诊断问题，拉德布鲁赫公式提供了折中框架；第三，它揭示了一个未解决的张力——任何以道德名义突破实定法的做法，都必须付出法的安定性代价。", "summary": "「恶法是否非法」的争论，集中在道德邪恶是否使规则丧失法律资格。自然法传统（含拉德布鲁赫公式）主张极端不正义的法律不是法律；实证主义（哈特）则坚持恶法在效力意义上仍是法律，但道德上应受谴责与抵抗。哈特强调，承认恶法为法反而能更准确地定位需要变革的制度，避免用定义技巧回避道德抉择；同时他承认在极端情形下可以选择不承认某体系为法律，但那是道德抉择而非概念真理。纽伦堡审判显示，三种立场各有力量，也共同暴露了「以道德突破实定法」必须付出的安定性代价。", "furtherThinking": "1. 如果「不可容忍性」本身需要主观判断，拉德布鲁赫公式是否真的能约束法官，还是只是把「恶法非法」的判断推迟到了另一个模糊概念上？\n2. 哈特说「承认恶法是法律，使批判更清醒」，这一主张在什么社会条件下才成立？若一个社会的法律人普遍缺乏道德自觉，这种清醒会不会沦为冷漠的借口？\n3. 在国际刑事法院的实践中，如何平衡「惩罚极端暴行」与「法不溯及既往」？这是否说明「恶法非法」在道德上必要、在法理上却永远带有代价？"}, "en": "Is an Unjust Law Still Law?", "level": "debate", "tags": "恶法非法, 拉德布鲁赫, 自然法, 实证主义, 法律与道德", "source": "Hart, The Concept of Law, ch.9；Hart, 'Positivism and the Separation of Law and Morals' (1958)；Lon Fuller, 'Positivism and Fidelity to Law' (1958)；Gustav Radbruch, 'Statutory Lawlessness and Supra-Statutory Law' (1946)；纽伦堡审判 (1945-1946)", "id": "S3M2K3"}, "S3M2K4": {"title": "法律义务与道德义务", "EN": "Legal Obligation and Moral Obligation", "LEVEL": "core", "TAGS": "哈特, 义务, 法律与道德, 内部观点", "TERMS": "法律义务（Legal Obligation）::由有效法律规则施加、可由官方强制力保障的义务；道德义务（Moral Obligation）::由道德原则施加、依靠内在良知与社会评价维系的责任；义务（Obligation）::某行为被当作理所当然应予履行的规范地位；责任（Responsibility）::因违反义务而应受谴责或承担后果的地位；内在观点（Internal Point of View）::参与者把规则当作行为理由与批评标准来接受的态度；服从（Obedience）::行为上符合规则要求，未必伴随接受其正当性", "SOURCE": "Hart, The Concept of Law, ch.7, s.2；Hart, The Concept of Law, ch.8, s.2；Hart, The Concept of Law, ch.5, s.2；Hart, The Concept of Law, Postscript, s.5", "terms": [{"term": "法律义务（Legal Obligation）", "def": "由有效法律规则施加、可由官方强制力保障的义务"}, {"term": "道德义务（Moral Obligation）", "def": "由道德原则施加、依靠内在良知与社会评价维系的责任"}, {"term": "义务（Obligation）", "def": "某行为被当作理所当然应予履行的规范地位"}, {"term": "责任（Responsibility）", "def": "因违反义务而应受谴责或承担后果的地位"}, {"term": "内在观点（Internal Point of View）", "def": "参与者把规则当作行为理由与批评标准来接受的态度"}, {"term": "服从（Obedience）", "def": "行为上符合规则要求，未必伴随接受其正当性"}], "sections": {"coreQuestion": "「我有义务纳税」「我有义务赡养父母」——这两句话都用「义务」，但性质一样吗？前者来自税法，后者来自伦理；前者可由国家强制力保障，后者主要靠良知与舆论。哈特（H. L. A. Hart）在《法律的概念》中专门分析了「义务」的概念，并区分法律义务与道德义务。本节要回答：义务的本质是什么？法律义务与道德义务有哪些相同与不同？为什么说「被迫做某事」并不等于「有义务做某事」？当法律义务与道德义务冲突时，我们又该如何理解这种冲突？", "definition": "义务（Obligation）在哈特那里是一种规范地位：当一个行为被社会成员普遍认为是「理所当然应当做的」，并且偏离会招致批评时，就可以说行为人「有义务」做这件事；纯粹的心理状态不足以解释它。哈特强调，义务的存在与「某人施加了威胁」并非一回事。\n\n法律义务（Legal Obligation）是由有效法律规则施加的义务。它的特征在于：其一，来源于被承认规则识别为有效的法律规则；其二，由官方强制力（制裁）作为保障，但制裁并非其唯一或主要动机——哈特强调，在正常社会中，人们遵守法律多出于内在接受；其三，法律义务有明确的权威判定机关（法院）来确认是否存在违反。\n\n道德义务（Moral Obligation）是由道德原则施加的责任，依靠个人良知、社会评价与道德共同体来维系。它没有专门的官方机关来认定，也没有制度化制裁，但同样具有「应当」的规范力量。\n\n哈特在《后记》中明确回应德沃金（Ronald Dworkin）的批评：德沃金认为法律权利必然具有某种道德力量，因而「法律义务」总是某种「道德义务」；哈特则坚持，法律权利与义务可以在完全缺乏道德正当性的情况下存在——这是分离命题在权利义务层面的体现。", "history": "义务概念的分析，是法理学从「命令理论」走向「规则理论」的关键环节。奥斯丁（John Austin）把义务理解为「遭受制裁的可能性」，即「若不做 X，就会受罚」。哈特在《法律的概念》第五章批判这一观点：抢匪用枪逼你交钱，你「不得不」（obliged）交，但你并没有「义务」（obligation）交——威胁与义务在性质上不同。\n\n哈特进一步指出，义务的概念必须从「内部观点」（Internal Point of View）来理解：义务存在于这样的社会——规则被成员当作共同的行为标准接受，偏离会被批评。二战后，随着对身体强制与道德自主关系的反思加深，法律义务与道德义务的关系成为法理学的重要议题，哈特的分析为理解义务的性质提供了概念基础。", "principle": "理解法律义务与道德义务的区分，可分四层。\n\n第一层，「被迫」与「义务」的区分。哈特以抢匪为例：抢匪命令你交出钱包，并威胁开枪，你交出钱包是「被迫的」（obliged），但你没有交钱包的「义务」（obligation）。义务的概念预设了规则被当作正当的行为标准来接受，而威胁只能产生事实上的服从。这一区分是哈特批判命令理论的核心论据。\n\n第二层，义务的社会基础。哈特指出，义务存在于「规则被从内部观点接受」的社会中。当一个群体把某行为当作「理所当然应当做」，并用「你有义务做 X」来批评偏离时，义务就存在了。这一分析同时适用于法律义务与道德义务——二者都有「被当作应当」的规范性。\n\n第三层，法律义务的特殊性。法律义务除了具有上述规范结构，还有两个特点：其一，它由承认规则识别的有效规则所施加，来源明确；其二，它由官方制裁作为「保障」——但哈特强调，制裁只是「保证那些本会自愿遵守的人不被不遵守者牺牲」的担保，而非服从的主要动机。在稳定的社会中，多数人从内部观点接受法律，守法是习惯性的。\n\n第四层，两种义务的交叉。法律义务与道德义务在内容上常重合（如不得杀人既是法律也是道德义务），但也可以分离：法律可能施加道德上中性的义务（如交通规则），也可能施加道德上恶劣的义务（如纳粹法律要求告发）；道德义务也可能不为法律所承认（如见义勇为在多数法域并非法律义务）。理解这种交叉，是理解二者关系的关键。", "viewpoints": "哈特的核心主张是：义务的本质在于规则被当作正当的行为标准而从内部接受；「被迫」不等于「有义务」。法律义务与道德义务都具备这种规范结构，但法律义务来源于有效法律规则、由官方强制力保障并有权威判定机关，道德义务则依靠良知与社会评价。\n\n哈特特别强调两点。其一，制裁在法律义务中扮演的是「担保」角色，而非主要动机；把义务化约制裁，是奥斯丁命令理论的根本错误。其二，法律义务与道德义务在概念上可以分离：一项规则完全可以在道德上恶劣却仍是有效法律，从而施加法律义务；德沃金关于「法律权利必具道德力量」的主张，被哈特视为把道德评价混入了效力判断。哈特承认，使用「 ought」「must」「have an obligation」这些词时，法律义务与道德义务共享一套规范语汇，但这并不意味着承认法律义务就是承认其道德正当性。", "comparison": "与奥斯丁比较：奥斯丁以制裁定义义务，哈特以「规则被内部接受」定义义务；前者把义务还原为威胁，后者保留了义务的规范维度。\n\n与自然法比较：自然法倾向认为只有符合道德的规则才能施加真正的义务；哈特则坚持，邪恶法律也能施加法律义务（尽管人们道德上应抵抗），这是分离命题的贯彻。\n\n与德沃金比较：德沃金认为法律权利与义务必然带有道德力量，因为识别它们需要道德诠释；哈特在《后记》中反驳：法律权利义务的存在是社会事实问题，其道德价值是另一回事。", "debates": "围绕义务的首要争论，是「制裁是否构成义务的核心」。奥斯丁传统认为，没有制裁就没有义务；哈特以抢匪例子反驳：制裁可以解释「被迫」，却解释不了「义务」的规范体验。现实中，许多法律义务（如宪法义务）并无直接制裁，却仍被视为义务。\n\n第二个争论关乎「法律义务是否必然具有道德分量」。德沃金主张法律权利是「道德权利的一个种类」，因此法律义务总带有道德力量；哈特反驳说，这一主张混淆了「法律上有什么权利」与「那些权利在道德上是否正当」。纳粹法律施加的义务就是明证——它们是法律义务，却毫无道德正当性。\n\n第三个争论关乎「服从法律的道德义务」。自然法传统倾向于认为人们有服从法律的道德义务；哈特则认为，是否服从法律是一个开放的道德问题，取决于法律本身的道德品质，不能一般性地断言。法律义务与道德义务在这里可能发生真正的冲突——此时，哈特主张，个人须自己作出道德判断。", "case": "1994 年南非的真相与和解委员会（Truth and Reconciliation Commission, TRC）为理解法律义务与道德义务的张力提供了深刻案例。种族隔离时期，许多行为（如拘留、酷刑）在当时的法律下是「合法」的，执行者可以说自己履行了法律义务；但从道德上看，这些行为严重违背了基本正义。转型后，新政府设立 TRC，以「揭示真相换取赦免」的方式处理过去：那些完全披露政治罪行的行为人可获得赦免，免于法律追诉。\n\n这个案例把法律义务与道德义务的关系复杂化了：其一，旧制度下的行为人面临「服从法律义务」与「遵从道德良知」的冲突；其二，转型正义中，新的政治共同体选择以「和解」而非「报复」来处理，这本身就是一种道德判断——它决定哪些法律义务（追诉的义务）应让位于更高的道德目标（社会和解）。从哈特的框架看，TRC 显示了法律义务的「可变革性」：通过新的授权规则（赦免法），旧的法律义务被解除；而支撑这一变革的，是道德义务（对受害者负责、对社会和解的承诺）。", "caseAnalysis": "就南非 TRC 而言，事实是种族隔离时期许多暴行在当时法律下「合法」，转型后设立真相与和解委员会处理；争议焦点是：应当追诉（法律义务）还是赦免以促成和解（道德目标）。从哈特的视角看，旧制度下的法律义务虽然在形式上有效，却缺乏道德正当性，行为人面临真正的道德选择。法律依据上，新宪法与赦免法授权 TRC 运作，改变了原有的追诉义务。理由上，社会选择了以真相与和解来重建共同体，这体现了「法律义务可以被道德考量通过法律程序所改变」。\n\n理论意义在于：第一，它显示法律义务与道德义务可能剧烈冲突，且冲突的解决本身需要法律程序；第二，它印证哈特关于「法律义务可变革」的观点——通过承认规则的变化，旧的义务被解除；第三，它也提出哈特框架的挑战——TRC 的赦免决定本质上是道德判断，法律形式只是为其提供外壳，这说明道德义务在深层上塑造着法律义务的内容。", "summary": "义务在哈特那里是一种规范地位，源于规则被从内部观点接受；「被迫」不等于「有义务」，这是批判命令理论的关键。法律义务由有效规则施加、由官方强制力担保并有权威判定，道德义务则依靠良知与社会评价。二者在内容上常重合，但可分离——邪恶法律也能施加法律义务。哈特反对把义务化约制裁（制裁只是担保），也反对德沃金「法律义务必具道德力量」的主张。南非 TRC 显示，法律义务可被法律程序改变，而道德考量常在深层塑造这种改变。", "furtherThinking": "1. 哈特说「制裁只是担保、不是服从的主要动机」，这一经验判断在极端邪恶的法律体系中是否仍然成立？当法律要求你告发亲人时，人们服从的动机是什么？\n2. 德沃金说法律权利必具道德力量，哈特说不必；在 TRC 这类转型正义场景中，哪种理解更能解释人们为何接受新的法律义务？\n3. 在现代社会中，许多道德义务（如环保、诚信）正被逐步立法化；这种趋势会缩小法律义务与道德义务的差距，还是会带来「道德立法化」的新问题？"}, "en": "Legal Obligation and Moral Obligation", "level": "core", "tags": "哈特, 义务, 法律与道德, 内部观点", "source": "Hart, The Concept of Law, ch.7, s.2；Hart, The Concept of Law, ch.8, s.2；Hart, The Concept of Law, ch.5, s.2；Hart, The Concept of Law, Postscript, s.5", "id": "S3M2K4"}, "S3M2K5": {"title": "法律权威的正当性", "EN": "The Legitimacy of Legal Authority", "LEVEL": "core", "TAGS": "法律权威, 正当性, 哈特, 拉兹, 服从", "TERMS": "权威（Authority）::要求他人服从并为其提供行为理由的权力或地位；正当性（Legitimacy）::权威在道德上可被证成、值得被服从的属性；事实权威（De Facto Authority）::事实上被服从但不必然正当的权威；合法权威（De Jure Authority）::在道德上被证成、有权利被服从的权威；法律有效性（Legal Validity）::规则因符合承认规则而属于法律体系的属性；服务性权威观（Service Conception of Authority）::拉兹提出的、权威正当性在于更好地服务于被治者的理论", "SOURCE": "Hart, The Concept of Law, ch.6；Hart, The Concept of Law, ch.9, s.3；Hart, 'Authority and Legal Duty' (1990)；Joseph Raz, The Morality of Freedom (1986), ch.1；Brown v. Board of Education, 347 U.S. 483 (1954)", "terms": [{"term": "权威（Authority）", "def": "要求他人服从并为其提供行为理由的权力或地位"}, {"term": "正当性（Legitimacy）", "def": "权威在道德上可被证成、值得被服从的属性"}, {"term": "事实权威（De Facto Authority）", "def": "事实上被服从但不必然正当的权威"}, {"term": "合法权威（De Jure Authority）", "def": "在道德上被证成、有权利被服从的权威"}, {"term": "法律有效性（Legal Validity）", "def": "规则因符合承认规则而属于法律体系的属性"}, {"term": "服务性权威观（Service Conception of Authority）", "def": "拉兹提出的、权威正当性在于更好地服务于被治者的理论"}], "sections": {"coreQuestion": "我们为什么会服从法律？因为害怕惩罚？因为习惯？还是因为相信法律「有权」要求我们服从？「权力」与「权威」看似相近，实则不同：强盗持枪也能让你交钱，但我们不会说他有「权威」。本节要辨析法律权威的性质与正当性：一个法律体系「有效」（valid）是否就等于它「正当」（legitimate）？哈特（H. L. A. Hart）如何区分「事实上的权威」与「有正当性的权威」？当法律严重不义时，服从法律的道德理由还剩多少？", "definition": "权威（Authority）指一种要求他人服从、并为其提供行为理由的地位或权力。权威不同于纯粹的权力（power）或强力（force）：强力使人「不得不」服从，权威则让人「应当」服从——服从权威被视为有理由的，而不只是被迫的。\n\n正当性（Legitimacy）指权威在道德上可被证成、值得被服从的属性。法理学中通常区分：事实权威（de facto authority）——事实上被服从、有效运作的权威；与合法权威（de jure authority）——在道德上有权利被服从的权威。一个政权可能事实上有权威（人们普遍服从），却在道德上缺乏正当性。\n\n哈特在《法律的概念》中强调，「法律体系存在」是一个事实陈述，它取决于两个最低条件（有效规则被普遍服从、次级规则被官员有效接受），而不取决于该体系的道德价值。这意味着，一个道德上邪恶的体系仍可能是「有效的法律体系」。哈特以此区别于自然法：法律效力（validity）与法律正当性（legitimacy）是两个不同的概念。\n\n拉兹（Joseph Raz）提出「服务性权威观」（Service Conception of Authority）：权威的正当性在于它能更好地服务于被治者——通过协调行动、解决分歧，帮助人们更好地遵从理性要求。权威的合法性取决于它是否真正扮演了这种「中介」角色。", "history": "对权威正当性的追问，是政治哲学与法理学共同的古老问题。传统自然法把权威的正当性追溯到神意、自然法或人民的同意；法律实证主义兴起后，倾向于把「权威是否存在」与「权威是否正当」分开处理。马克斯·韦伯（Max Weber）对权威类型的划分（传统型、卡里斯马型、法理型），为理解现代法律的权威提供了社会学背景。\n\n二战后，极权主义统治以「合法」形式实施暴行，使「有效法律是否值得服从」成为紧迫问题。哈特与富勒（Lon Fuller）的论战、拉德布鲁赫公式的提出，都围绕这一核心。二十世纪后期，拉兹等学者进一步把权威问题纳入法理学的核心，使「法律权威的正当性」成为当代法哲学的重要议题。", "principle": "理解法律权威的正当性，可分四层。\n\n第一层，权威与权力的区分。哈特继承并发展了「威胁」与「义务」的区分：强力使人被迫，权威提供行为理由。法律若仅靠制裁维系，就只是暴力；法律之所以是权威，正因为它被从内部观点接受为行为理由与批评标准。\n\n第二层，有效性与正当性的区分。哈特坚持，一个法律体系「存在」（有效）是事实问题，取决于是否符合两个最低条件；而它是否「正当」，取决于道德评价。把二者分开，使我们既能承认某体系是有效法律，又能对其正当性作出批判性评价。这是分离命题在权威问题上的贯彻。\n\n第三层，权威的事实基础。哈特指出，法律权威预设了某种程度的自愿合作： coercive power（强制力）必须建立在 authority（权威）的基础上——必须有一些人自愿合作并接受规则，强制才可能建立。但他强调，这种接受可以出于多种动机（长期利益、利他、传统、从众），未必是道德认同；人们甚至可能「在道德上认为不应接受，却仍然接受」。\n\n第四层，正当性的可能基础。哈特承认，法律若要稳定，通常需要人们相信它有某种正当性；但他拒绝把它归结为单一的道德认同。拉兹的服务性权威观则提供了一个更实质的标准：权威正当，当且仅当它能在协调行动、解决分歧上更好地服务于被治者的理性利益。这一理论把正当性建立在权威的「功能」之上。", "viewpoints": "哈特的核心主张是：法律权威的存在（有效性）与正当性是可区分的；「法律体系存在」是事实陈述，不依赖道德价值。一个邪恶的法律体系可能有效运作，却缺乏正当性。哈特并不否认正当性问题的重要性——他承认，法律若要稳定，需要相当程度的自愿接受；但他坚持，这种接受是事实问题，而正当性是道德问题，二者不应混淆。这一立场使哈特既能描述法律权威的运作，又能保留对其道德批判的空间。\n\n拉兹的核心主张是：法律权威的正当性在于其「服务性」——权威通过发布能被遵守的指令、协调人们的行为，帮助人们更好地遵循理性，从而证成自身的存在。权威的正当性不在乎人们是否「同意」，而在乎它是否真正服务于被治者的理性利益。", "comparison": "与自然法比较：自然法倾向把正当性作为法律性的内在要素——不正义的法律缺乏权威，甚至不是法律；哈特则坚持有效性独立于正当性，不正义的法律仍是有效法律，只是缺乏正当性。\n\n与韦伯比较：韦伯的「法理型权威」强调权威的合法程序基础；哈特的分析更精细地指出，程序合法性（符合承认规则）只保证有效性，不保证正当性。\n\n与拉兹比较：哈特致力于描述法律权威的结构与存在条件，对正当性问题保持克制；拉兹则提供实质的正当性理论（服务性权威观）。两人虽同属实证主义传统，但研究重心不同。", "debates": "首要争论是「有效权威是否必然正当」。哈特坚决区分二者：有效的法律体系未必正当；拉德布鲁赫公式与富勒的内在道德则倾向于把某种道德门槛纳入法律性。哈特认为，把正当性塞进有效性，会模糊对恶法的批判——承认它「有效但不正当」比说它「不是法律」更清晰。\n\n第二个争论关乎「服从法律的道德义务」。哈特认为这是一个开放问题：是否服从法律，取决于具体法律的道德品质，不能一般性地断言人们有服从法律的道德义务。拉兹的服务性权威观则试图说明，在权威正当的场合，服从权威就是服从理性本身，因而有道德理由。\n\n第三个争论关乎「接受与同意」。哈特强调，法律体系的稳定依赖于某种接受，但这种接受未必是道德认同——它可以出于利益、传统或从众。批评者（如德沃金）认为，这低估了法律权威的道德维度；哈特回应，如实描述事实并不等于否认道德维度的存在，只是拒绝把事实描述与道德评价混为一谈。", "case": "美国 1954 年的布朗诉教育委员会案（Brown v. Board of Education, 347 U.S. 483），是讨论法律权威正当性的经典案例。该案中，最高法院以一致意见宣告公立学校中的种族隔离违反宪法第十四修正案的平等保护条款。此前，1896 年的普莱西诉弗格森案（Plessy v. Ferguson）曾确立「隔离但平等」原则，使种族隔离在数十年来具有形式合法性。布朗案宣告了这一法律秩序的正当性危机：隔离法律虽然「有效」（由合法机关按程序制定并被普遍服从），却在道德上严重违背了平等原则。\n\n从哈特的框架看，布朗案凸显了法律效力与正当性的分离：隔离法律在形式上有效，却缺乏道德正当性；最高法院通过重新解释宪法（承认规则的核心），改变了法律的内容，从而解决了正当性危机。从拉兹的视角看，法院纠正了法律未能服务于「平等」这一理性价值的缺陷，使法律权威重新获得正当性。布朗案说明，法律权威的正当需要不断通过道德反思与法律变革来维系，形式有效性本身并不足够。", "caseAnalysis": "就 Brown v. Board 而言，事实是最高法院推翻了长期存在的「隔离但平等」原则，宣告公立学校种族隔离违宪；争议焦点是：形式有效的隔离法律是否具有真正的正当性。从哈特视角看，隔离法律在效力上有效（符合当时的承认规则），但道德上严重不义；法院通过重新诠释宪法平等条款（承认规则的核心内容），改变了法律。法律依据上，第十四修正案的平等保护条款成为变革的支点。理由上，法院认定隔离本身即构成不平等，无论设施是否“平等”。\n\n理论意义在于：第一，它印证哈特关于「有效性与正当性可分离」的主张——隔离法律有效却不正当；第二，它显示正当性危机如何通过承认规则的调整（宪法重新诠释）在法律体系内部得到解决；第三，它也提示哈特框架的边界——法院之所以能推动变革，靠的是对「平等」这一道德价值的诉诸，这表明法律权威的正当性根植于更深层的道德承诺。", "summary": "法律权威不同于纯粹强力：权威提供行为理由，强力只产生被迫服从。哈特严格区分「有效性」（法律体系是否存在，是事实问题）与「正当性」（权威在道德上是否值得服从，是道德问题），并主张一个邪恶体系可能有效却不正当。法律权威预设某种自愿接受，但接受可出于多种动机，未必是道德认同。拉兹以「服务性权威观」提供实质正当性标准：权威正当，在于它服务于被治者的理性利益。布朗案显示，形式有效的隔离法律因违背平等而丧失正当性，正当性危机需通过承认规则（宪法诠释）的调整来解决。", "furtherThinking": "1. 哈特说人们可能「在道德上认为不应接受，却仍然接受」法律权威，这种分裂的接受能否长期维系一个法律体系？它会不会在某个临界点崩塌？\n2. 拉兹的服务性权威观把正当性建立在「服务于理性」上，这是否又悄悄把道德带回了法律概念，从而接近了哈特所反对的立场？\n3. 在算法治理中，若系统以「客观中立」的姿态作出决定，这种「权威」的正当性来自何处？哈特与拉兹各自会如何评价？"}, "en": "The Legitimacy of Legal Authority", "level": "core", "tags": "法律权威, 正当性, 哈特, 拉兹, 服从", "source": "Hart, The Concept of Law, ch.6；Hart, The Concept of Law, ch.9, s.3；Hart, 'Authority and Legal Duty' (1990)；Joseph Raz, The Morality of Freedom (1986), ch.1；Brown v. Board of Education, 347 U.S. 483 (1954)", "id": "S3M2K5"}, "S3M3K1": {"title": "法律语言的模糊性", "EN": "The Vagueness of Legal Language", "LEVEL": "core", "TAGS": "法律语言, 模糊性, 开放结构, 法律解释", "TERMS": "模糊性（Vagueness）::语词存在边界情形、无法明确划定的语义特征；歧义（Ambiguity）::语词具有两个以上可能含义的特征；开放结构（Open Texture）::哈特所述一般语词在边缘地带留下适用不确定性的特征；核心（Core）::语词适用毫无疑问的清楚情形；边缘（Penumbra）::语词是否适用存在疑问的模糊情形；语义不确定性（Semantic Indeterminacy）::语言本身无法唯一确定适用结果的状态", "SOURCE": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, Postscript, s.3；Timothy Endicott, Vagueness in Law (2000)；Smith v. Goguen, 415 U.S. 566 (1974)", "terms": [{"term": "模糊性（Vagueness）", "def": "语词存在边界情形、无法明确划定的语义特征"}, {"term": "歧义（Ambiguity）", "def": "语词具有两个以上可能含义的特征"}, {"term": "开放结构（Open Texture）", "def": "哈特所述一般语词在边缘地带留下适用不确定性的特征"}, {"term": "核心（Core）", "def": "语词适用毫无疑问的清楚情形"}, {"term": "边缘（Penumbra）", "def": "语词是否适用存在疑问的模糊情形"}, {"term": "语义不确定性（Semantic Indeterminacy）", "def": "语言本身无法唯一确定适用结果的状态"}], "sections": {"coreQuestion": "法律是靠语言运作的，但语言天生就不完美。「合理」「适当」「重大」「车辆」这些词，看似清楚，一旦碰到具体案件就露出模糊的面目。法律语言的模糊性，是法律的缺陷，还是不可避免的代价？它与哈特（H. L. A. Hart）所说的「开放结构」是什么关系？更重要的是：模糊性是否意味着法官可以任意解释？本节将从语义学层面辨析模糊性的性质，说明法律为何必须容忍它，以及法律体系发展出哪些技术来应对它。", "definition": "模糊性（Vagueness）指语词存在「边界情形」（borderline cases），即某些对象是否落在该语词的适用范围内并不明确。例如「秃头」——多少根头发以下算秃头？没有一个明确的界线。模糊性的特点是「程度性」和「边界的渐进性」：从一个明确适用的情形，到明确不适用的情形，中间存在渐变的灰色地带。\n\n歧义（Ambiguity）则不同：它指一个语词有两个以上彼此独立的确定含义，例如「银行」既可指金融机构，也可指河岸。歧义可以通过语境通常消除，而模糊性无法通过语境彻底消除——它源于语词本身的边界不清。\n\n哈特的「开放结构」（Open Texture）与模糊性密切相关但不完全等同。开放结构强调一般语词在边缘地带的适用不确定；模糊性则更侧重语义本身的边界模糊。哈特在《后记》中回应德沃金（Ronald Dworkin）时，用「paradigm cases」（典范情形）和语义不确定性来说明：法律语词有清楚的典范情形，也有边界情形，后者的处理需要选择。\n\n值得注意的是，哈特强调「解释规则无法自我解释」：任何用来澄清模糊性的解释规则，本身也是用一般语词表述的，也会遇到模糊性。因此，模糊性不能被层层解释彻底消除，只能在具体语境中被「管理」。", "history": "二十世纪分析哲学对模糊性的研究，深刻影响了法理学。伯特兰·罗素（Bertrand Russell）在 1923 年指出，模糊性是一个程度问题——从清晰到模糊是连续的。蒂莫西·恩迪科特（Timothy Endicott）在《法律中的模糊性》(Vagueness in Law, 2000) 中系统研究了法律语言的模糊性，捍卫哈特对典范情形的理解，回应德沃金的批评。\n\n在法律实践中，模糊性长期被视为需要克服的缺陷——人们追求一部巨细无遗、毫无歧义的法典。但哈特指出，由于人的有限性（相对无知的事实与目的的相对不确定性），这种理想既不可能也不可欲。二十世纪福利国家与行政规制兴起后，大量「合理」「公平」「安全」等模糊标准被立法采用，模糊性从「需要消除的瑕疵」转变为「需要管理的常态」，法律理论因此必须正视它。", "principle": "要理解法律语言的模糊性，可分五层。\n\n第一层，模糊性的来源。语言为交流而设，一般语词通过抓住典型特征来分类，但世界上的事物是连续渐变的，分类必然留下边界地带。哈特以「车辆」为例：汽车、公交车是典范情形，玩具车、自行车、滑轮鞋则是边界情形。语言的「开放纹理」是不可还原的（irreducibly open-textured）。\n\n第二层，模糊性与开放结构的关系。开放结构是模糊性在法律语境中的表现：当一条规则的语词在边缘地带适用不确定时，规则的适用就需要选择。哈特强调，解释规则只能减少而不能消除这种不确定性，因为解释规则本身也由一般语词构成。\n\n第三层，典范情形的作用。哈特在《后记》中强调，一般语词之所以可用，正是因为有「典范情形」（paradigm cases）——那些被普遍认可、毫无争议的清楚实例。典范情形使语言交流成为可能；边界情形则要求在「类似典范情形」的程度上作出判断。德沃金批评哈特过度依赖典范情形，恩迪科特则为哈特辩护。\n\n第四层，模糊性的功能。模糊性并非纯粹消极。立法者有意使用「合理注意」「公平费率」等模糊标准，是为了把具体判断交给更接近情境的机关（法院、行政机关）。哈特指出，在变化多端、无法预先穷尽的领域，模糊标准比僵硬规则更能适应具体情境。\n\n第五层，应对模糊性的技术。法律体系发展出多种技术：其一是解释规则（如「明示其一即排除其他」），虽不能消除但能减少不确定性；其二是委任立法，由行政机关把宽泛标准具体化；其三是判例制度，通过一个个先例逐步划定边界；其四是「合理性」标准，把权衡交给裁判者。", "viewpoints": "哈特的核心主张是：模糊性是法律语言的必然特征，源于语言性质与人的有限性；它不能被解释规则彻底消除，只能在具体案件中被管理。法律语词有清楚的典范情形，也有边界情形；后者的适用需要在类似性判断中作出选择，但这种选择不是任意的——它受典范情形与规则目的约束。\n\n哈特反对两种极端：其一，形式主义试图冻结语词含义、消除模糊性，代价是僵化与脱离社会目的；其二，规则怀疑论借模糊性否定规则本身。哈特坚持，模糊性只存在于边缘，法律生活的主体仍由确定规则构成。在《后记》中，他进一步明确：德沃金所谓「理论分歧」并不能证明语言本身不确定，而可能只是对典范情形之外如何适用的合理争议。\n\n恩迪科特则捍卫哈特：法律语词的模糊性恰恰需要「典范情形」概念来解释——我们通过参照清楚实例来处理边界情形，而非通过寻找抽象定义。", "comparison": "与德沃金比较：德沃金认为法律概念（如「法律」本身）是「解释性概念」，其适用需要诠释性判断，因此模糊性背后是道德争议；哈特坚持可以区分「语言本身的模糊」与「对如何适用的道德分歧」，前者是语义问题，后者是价值问题。\n\n与形式主义比较：形式主义视模糊性为可消除的技术缺陷；哈特视之为语言与人的有限性的必然结果，法律体系必须在确定性与开放性间平衡。\n\n与法律现实主义比较：现实主义强调模糊性赋予法官广泛裁量，规则不过是判决预测；哈特承认边缘裁量，但坚持典范情形与核心领域仍使法律具有确定性。", "debates": "首要争论是「模糊性能否被彻底消除」。德沃金认为，通过建构性诠释可以找到法律概念的「最佳理解」，从而确定其适用；哈特与恩迪科特则认为，语言的边界情形无法被任何诠释规则彻底消除，诠释本身也依赖语言。\n\n第二个争论关乎「模糊性是否等于不确定性」。哈特区分了「语词的开放结构」与「法官的价值分歧」：前者是语义现象，后者是道德现象。德沃金则倾向于把二者联系起来，认为法律概念本质上是评价性的，因此适用争议不可避免。这一争论的实质，是「法律语言能否体现价值中立」的问题。\n\n第三个争论关乎「模糊标准的正当性」。批评者认为，「合理」「公平」等模糊标准赋予法官过大权力，威胁法的安定性；辩护者（如哈特）则认为，在复杂多变的领域，模糊标准比僵硬规则更能实现实质正义，关键在于通过程序约束裁量。", "case": "美国 1974 年的 Smith v. Goguen 案（415 U.S. 566）是法律语言模糊性的经典案例。一项马萨诸塞州法律把「以任何方式侮辱或轻蔑对待美国国旗」定为犯罪。原告戈根（Goguen）因在牛仔裤上缝了一面小美国国旗而被起诉。最高法院判决该法律因「过于模糊」（void for vagueness）而违宪。\n\n法院的理由是：该法律没有清楚界定什么行为构成「轻蔑对待」，普通人无法预知自己的行为是否违法，执法机关也由此获得过大的裁量空间。「Void for vagueness」（因模糊而无效）原则要求刑事法律必须足够明确，使公民能够理解并据此规划行为。\n\n从哈特的角度看，这一案例展示了语言模糊性的两面：一方面，「侮辱」「轻蔑」是典型边界模糊的语词，其适用在核心情形（焚烧国旗）清楚，在边缘情形（在牛仔裤上缝国旗）却不明确；另一方面，法律体系通过宪法原则（正当程序）来「管理」模糊性——它限制模糊性的危害（防止任意执法），消除则无从做到。这正是哈特所说「对模糊性的管理」的制度化体现。", "caseAnalysis": "就 Smith v. Goguen 而言，事实是原告在牛仔裤上缝小国旗被依「轻蔑对待国旗」法起诉；争议焦点是：该法律是否因语词模糊而违宪。法律依据上，最高法院援引正当程序条款与 void for vagueness 原则。理由上，法律必须给公民明确的行为指引，不能让普通人猜测是否违法，也不能给执法者过大任意裁量。\n\n理论意义在于：第一，它印证哈特关于语言边缘地带的模糊性的分析——「轻蔑对待」有清楚核心，也有模糊边界；第二，它展示了法律体系应对模糊性的具体技术——通过宪法审查宣告模糊法律无效，这是对模糊性的「管理」而非「消除」；第三，它也提示哈特框架的适用边界——void for vagueness 是一个实质性的价值判断（重视公民自由与法的安定性），这说明对模糊性的管理本身需要价值基础。", "summary": "模糊性指语词存在边界情形，与「歧义」（多个确定含义）不同；它与哈特的开放结构密切相关，但更侧重语义本身的边界不清。法律语言的模糊性源于语言性质与人的有限性，不可被解释规则彻底消除，因为解释规则本身也由一般语词构成。哈特强调典范情形的作用，反对形式主义消除模糊性的幻想，也反对规则怀疑论借模糊性否定规则。法律体系通过解释规则、委任立法、判例与「合理性」标准管理模糊性。Smith v. Goguen 显示，宪法上的 void for vagueness 原则是对模糊性的制度化管控，而非彻底消除。", "furtherThinking": "1. 如果法律语言完全精确、毫无模糊性，法律是否就不需要法官解释了？哈特会说这种精确是可能的吗？\n2. 哈特区分「语义模糊」与「价值分歧」，这一区分在 Smith v. Goguen 这类案件中是否站得住脚？「轻蔑对待国旗」的模糊是否本来就夹杂着价值判断？\n3. 在民法典中使用「善良风俗」「诚实信用」等原则性条款，是把模糊性当作缺陷，还是当作适应社会变迁的工具？"}, "en": "The Vagueness of Legal Language", "level": "core", "tags": "法律语言, 模糊性, 开放结构, 法律解释", "source": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, Postscript, s.3；Timothy Endicott, Vagueness in Law (2000)；Smith v. Goguen, 415 U.S. 566 (1974)", "id": "S3M3K1"}, "S3M3K2": {"title": "司法解释", "EN": "Judicial Interpretation", "LEVEL": "core", "TAGS": "司法解释, 法律解释, 文义解释, 目的解释, 法官", "TERMS": "司法解释（Judicial Interpretation）::法院在适用法律时对法律含义的阐明与确定；法律解释（Legal Interpretation）::确定法律规范含义与适用范围的活动；文义解释（Literal Interpretation）::按法律语词通常含义进行解释的方法；目的解释（Purposive Interpretation）::依法律目的阐明规范含义的方法；司法解释权（Judicial Interpretive Power）::法院阐明法律含义的权威；法律漏洞（Gap in Law）::法律对某情形未作规定的状态", "SOURCE": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, Postscript, s.6；Pepper v Hart [1993] AC 593 (H.L.)；Marbury v. Madison, 5 U.S. (1 Cranch) 137 (1803)", "terms": [{"term": "司法解释（Judicial Interpretation）", "def": "法院在适用法律时对法律含义的阐明与确定"}, {"term": "法律解释（Legal Interpretation）", "def": "确定法律规范含义与适用范围的活动"}, {"term": "文义解释（Literal Interpretation）", "def": "按法律语词通常含义进行解释的方法"}, {"term": "目的解释（Purposive Interpretation）", "def": "依法律目的阐明规范含义的方法"}, {"term": "司法解释权（Judicial Interpretive Power）", "def": "法院阐明法律含义的权威"}, {"term": "法律漏洞（Gap in Law）", "def": "法律对某情形未作规定的状态"}], "sections": {"coreQuestion": "法律制定出来后，并不会自动适用。法官面对一条规则，先要回答「它是什么意思」——这就是司法解释。但解释从来不是中性的：法官是在「发现」法律已有的含义，还是在「创造」新的含义？当法律语词模糊、存在漏洞或彼此冲突时，解释的尺度在哪里？本节要厘清司法解释的性质、目标与方法，说明它为何是司法权的核心组成部分，以及它在「依法裁判」与「法官造法」之间处于何种位置。", "definition": "司法解释（Judicial Interpretation）指法院在适用法律过程中，对法律规则的含义、适用范围及其与其他规范的关系进行阐明和确定的活动。它不同于立法解释（立法机关的说明）与学理解释（学者的解释），是由法院作出的、对具体案件具有约束力的权威解释。\n\n司法解释的目标，通常被理解为「确定法律的意旨」——是探求立法者的原意，还是阐明法律文本在当下的合理含义？围绕这一点，形成了不同理论：原意主义（originalism）强调探求立法者在制定时的意图；目的主义（purposivism）强调法律的目的与客观意旨；文本主义（textualism）强调法律语词本身的通常含义。\n\n司法解释与法律漏洞密切相关：当法律对某情形未作规定（漏洞），或规定模糊（开放结构），或规定之间冲突时，就需要解释来填补与澄清。哈特（H. L. A. Hart）认为，在规则的核心地带，解释几乎是自动的；解释的创造性主要体现在边缘地带与疑难案件中。\n\n司法解释权是司法权的一部分，由裁判规则（Rules of Adjudication）所授予。它使法院的裁判具有权威性——法院对法律含义的阐明，在体系内被视为「法律是什么」的权威回答。", "history": "司法解释的理论，与法律解释方法的演进同步。大陆法系传统上强调「法律不外乎条文」，法官的角色是「法律的嘴巴」，解释被严格限制在文义范围内；普通法系则更承认法官通过判决发展法律的功能。随着成文法大量增加、行政规制扩张，司法解释的创造性与日俱增，法院实际上在「解释」的名义下不断重塑法律。\n\n哈特在《法律的概念》第七章以「开放结构」分析解释的限度：解释规则本身也是一般规则，不能自我解释，因此在边缘地带必然有选择。在《后记》中，哈特回应德沃金（Ronald Dworkin）的「建构性诠释」理论，坚持解释/适用中存在法官行使有限造法权的空间。二十世纪后期，关于原意主义、文本主义与目的主义的争论（如美国最高法院的宪法解释之争），使司法解释的方法论成为法理学的核心议题。", "principle": "理解司法解释，可分四层。\n\n第一层，解释的必然性。法律以一般语词表达，而案件总是具体的；从一般到特殊的适用过程，必然包含对语词含义的确定。哈特指出，即使在「简单案件」中，法官也在「适用」规则，只是这种适用依赖典范情形而显得自动。因此，解释属于法律适用的常态，异常之说低估了语言的开放结构。\n\n第二层，解释的创造性边界。哈特反对两种夸张：其一，形式主义认为解释只是机械地探求唯一正确答案；其二，规则怀疑论认为解释纯粹是法官任意造法。哈特主张，在核心地带解释是确定的，在边缘地带解释包含选择，但这种选择受规则目的、典范情形与既有法律原则的约束——是「填补空隙的裁量」。\n\n第三层，解释方法及其位阶。传统解释方法包括文义解释、目的解释、历史解释、体系解释等（后续知识点详述）。这些方法属于「解释的指针」，机械规则的印象需要修正；它们之间可能发生冲突（如文义与目的冲突），此时需要判断何种方法优先。哈特认为，法律体系通常没有明确规定方法的优先顺序，这也是解释中出现选择的根源。\n\n第四层，解释的权威与终局性。法院的解释之所以重要，是因为它由裁判规则赋予权威地位。哈特区分终局性（finality）与无误性（infallibility）：法院的解释在体系内是终局的，但不能保证道德上或认识上无误；它可能被上级法院推翻，或被后续立法修正。", "viewpoints": "哈特的核心主张是：司法解释是法律适用的常态，其创造性集中在规则的边缘地带；法官在解释时必须作出选择，但这种选择是受约束的、填补空隙的，而非任意造法。他反对形式主义掩盖选择的必要性，也反对怀疑论否定规则的核心地位。\n\n德沃金的核心主张则是：司法解释（尤其是疑难案件）应是一种「建构性诠释」（constructive interpretation）——法官要找出既「适合」（fit）既有法律实践、又能为其提供最佳道德证成的原则，从而把法律理解为「完整性」（integrity）。在这种理论下，解释是受「整体性」约束的诠释活动，自由造法之说与之相悖，且存在唯一正确答案。\n\n哈特在《后记》中回应：即便法官诉诸原则进行解释，相互竞争的原则之间仍可能需要选择，而法律并未给出优先顺序，因此「造法的时刻」只是被推迟，并未被消除。", "comparison": "与原意主义比较：原意主义探求立法者制定时的意图；哈特更关注法律文本在当下语境中的适用，且认为「立法者意图」本身常常是模糊或多重的。\n\n与文本主义比较：文本主义强调语词通常含义；哈特承认典范情形提供的确定性，但指出边缘地带必须目的考量，文本不足以决定。\n\n与德沃金的诠释论比较：德沃金把解释理解为道德证成的诠释活动，追求唯一正确答案；哈特坚持解释中存在无法消除的选择，法官须行使有限的造法权。", "debates": "首要争论是「司法解释是发现还是创造」。形式主义与部分原意主义主张「发现」——法律含义已存在于文本或立法者意图中；现实主义与批判法学主张「创造」——法官的政治偏好决定解释结果。哈特取中间立场：核心地带是发现，边缘地带兼有创造。\n\n第二个争论关乎「解释是否有唯一正确答案」。德沃金以「法律作为完整性」主张有唯一正确答案；哈特认为这把诠释的理想当成了现实，实际案件中相互竞争的原则仍需法官选择。\n\n第三个争论关乎「司法解释的民主正当性」。批评者认为，法官通过解释实质造法，威胁民主（法官非民选）；辩护者认为，解释是司法权固有功能，且受法律约束、可被立法纠正。哈特承认这一张力，但认为向司法委任有限的规则制定权，是现代民主可接受的代价。", "case": "英国 1993 年的 Pepper v Hart 案（[1993] AC 593，上议院）是司法解释方法的里程碑案例。争议焦点是：法院在解释一项成文法时，能否参考议会辩论记录（Hansard）来探求立法意图。传统上，英国法院拒绝参考 Hansard（源自 1769 年的规则）；Pepper v Hart 案中，上议院改变了这一立场，确立：当立法语词模糊、含糊或可能导致荒谬结果时，法院可以参考议会辩论中的部长陈述，作为解释的辅助手段。\n\n从哈特的角度看，此案涉及「解释的指针」问题：Hansard 是历史解释的一种材料，能帮助确定立法目的，但它本身不是法律，其使用须受严格限制（仅在语词模糊时）。此案也印证哈特的开放结构理论——正是成文法语词的模糊，才开启了参考外部材料的空间。从德沃金的角度看，此案可被理解为「建构性诠释」的实例——法院通过考察立法背景，为法律寻找最佳的理解。Pepper v Hart 案说明，司法解释方法会在实践需要的推动下不断演进，固定规则之说难以维持。", "caseAnalysis": "就 Pepper v Hart 而言，事实是法院需解释一项模糊的税法条款，争议焦点是能否引用 Hansard；法律依据上，上议院推翻了长期禁止参考 Hansard 的规则。理由上，当文义模糊时，参考立法辩论有助于探求立法目的，且不会实质损害法律确定性（因为有严格条件限制）。\n\n理论意义在于：第一，它印证哈特关于「解释规则不能自我解释、边缘地带需要选择」的分析——正是文义的模糊开启了方法上的选择；第二，它显示解释方法是「可演进的实践」，而非固定的机械规则——这与哈特对法律作为社会制度的理解相符；第三，它也提示一个张力——参考 Hansard 探求「意图」，预设了立法意图是确定且可发现的，而这正是哈特与德沃金争论的问题。", "summary": "司法解释是法院阐明法律含义的权威活动，是司法权的核心组成部分。哈特认为解释是法律适用的常态：核心地带的解释近乎自动，边缘地带的解释包含选择，但这种选择受典范情形、规则目的与既有原则约束，是「填补空隙的裁量」。德沃金则以「建构性诠释」与「法律作为完整性」主张解释受整体性原则约束且存在唯一正确答案。哈特回应称竞争原则间仍需选择。关于解释是「发现」还是「创造」、是否有唯一正确答案、是否威胁民主，双方持续争论。Pepper v Hart 案显示解释方法作为可演进实践的性质。", "furtherThinking": "1. 若接受哈特的「填补空隙的裁量」，司法解释与司法造法的界限在哪里？这种界限是清晰的，还是程度问题？\n2. 德沃金说解释是「建构性诠释」，哈特说存在无法消除的选择；在 Pepper v Hart 这类案件中，哪种描述更贴近法官实际的推理过程？\n3. 当法律语词清晰但适用结果明显荒谬时，法官应坚守文义还是诉诸目的？这是否说明「解释」本身就是一个价值判断？"}, "en": "Judicial Interpretation", "level": "core", "tags": "司法解释, 法律解释, 文义解释, 目的解释, 法官", "source": "Hart, The Concept of Law, ch.7, s.1；Hart, The Concept of Law, Postscript, s.6；Pepper v Hart [1993] AC 593 (H.L.)；Marbury v. Madison, 5 U.S. (1 Cranch) 137 (1803)", "id": "S3M3K2"}, "S3M3K3": {"title": "法官自由裁量权", "EN": "Judicial Discretion", "LEVEL": "core", "TAGS": "司法裁量, 哈特, 德沃金, 疑难案件, 法官造法", "TERMS": "自由裁量（Discretion）::在法律未完全决定结果时，裁判者可在多个合法选项间选择的权力；强意义裁量（Strong Discretion）::裁判者不受法律理由约束、可自由决定的裁量；弱意义裁量（Weak Discretion）::裁判者须依标准但在具体适用中仍有判断空间的裁量；填补空隙的裁量（Interstitial Discretion）::哈特所述法官在法律未调整处行使的有限造法权；疑难案件（Hard Cases）::法律渊源无法唯一决定结果的案件；法官造法（Judicial Law-making）::法官在裁判中发展新规则的活动", "SOURCE": "Hart, The Concept of Law, ch.7, s.2；Hart, The Concept of Law, Postscript, s.6；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；H.L.A. Hart, 'The Concept of Law Revisited' (1996)；R v R [1991] UKHL 12", "terms": [{"term": "自由裁量（Discretion）", "def": "在法律未完全决定结果时，裁判者可在多个合法选项间选择的权力"}, {"term": "强意义裁量（Strong Discretion）", "def": "裁判者不受法律理由约束、可自由决定的裁量"}, {"term": "弱意义裁量（Weak Discretion）", "def": "裁判者须依标准但在具体适用中仍有判断空间的裁量"}, {"term": "填补空隙的裁量（Interstitial Discretion）", "def": "哈特所述法官在法律未调整处行使的有限造法权"}, {"term": "疑难案件（Hard Cases）", "def": "法律渊源无法唯一决定结果的案件"}, {"term": "法官造法（Judicial Law-making）", "def": "法官在裁判中发展新规则的活动"}], "sections": {"coreQuestion": "「法官自由裁量权」是法理学中最容易引发误解的概念之一。有人说法官「只是适用法律的机器」，没有裁量；也有人说法官「想怎么判就怎么判」，裁量无限。哈特（H. L. A. Hart）与德沃金（Ronald Dworkin）围绕裁量展开了持续数十年的争论。本节要厘清：裁量到底存在于哪里？哈特为什么说裁量是「有限的、填补空隙的」？德沃金为什么否认疑难案件中存在真正的裁量？这场争论对理解法官角色与法治意味着什么？", "definition": "自由裁量（Discretion）指在法律没有完全决定结果的情况下，裁判者可以在多个合法选项之间作出选择的权力或空间。分析裁量，需区分其不同层次。\n\n德沃金区分了三种意义的裁量。其一，「弱意义裁量」（weak discretion）：裁判者须服从权威设定的标准，但在具体适用中因标准模糊而仍有判断余地——如「裁判须公平，但何为公平需判断」。其二，「强意义裁量」（strong discretion）：裁判者在某些问题上不受法律标准约束，可自由决定——这是德沃金所反对的。其三，「作为授权规则的裁量」：法律明确授权某机关在若干选项中选择（如行政许可）。\n\n哈特所用的裁量概念，接近德沃金所说的「弱意义裁量」加上「填补空隙的裁量」：法官在法律未调整的「开放地带」，须行使有限的造法权，但这种权力受实体约束——他必须像「有良知的立法者」一样，依据一般性理由、参考既有法律的原则与目的来裁决，不得任意。\n\n裁量不同于「随意」（arbitrary）：裁量是在法律理由用尽之后，仍须给出一般性理由的理性选择；随意则是无理由或任性。理解这一点，是理解裁量概念的关键。", "history": "裁量问题根植于法律的不确定性与法官角色的张力。大陆法系传统上力图通过法典消除裁量，把法官定位为「法律的嘴巴」；普通法则承认法官在判例发展中拥有较大空间。二十世纪法律现实主义强调，法官实际上拥有广泛裁量，法律规则不过是判决的预测，这使裁量成为法理学的焦点。\n\n哈特在《法律的概念》第七章提出「开放结构」，承认边缘地带的裁量；在《后记》中，他系统回应德沃金对裁量的批评。德沃金则在《认真对待权利》《法律帝国》中主张「裁量是法律的空隙」，认为通过原则与建构性诠释，疑难案件也有唯一正确答案，因而法官并无真正的强意义裁量。这场争论成为当代法理学关于司法角色的核心对话。", "principle": "理解哈特的裁量理论，可分四层。\n\n第一层，裁量的存在场域。哈特认为，在任何法律体系中，总有一些案件是法律未调整或调整不明的（legally unregulated / unprovided for）。在这些案件中，法律没有规定唯一正确的答案；若法官要裁判（而不能像边沁设想的那样拒绝管辖或推给立法机关），就必须行使裁量，「为本案造法」。\n\n第二层，裁量的有限性。哈特强调，法官的造法权不同于立法机关：其一，它受实体约束——法官必须参考既有法律中已被承认的原则、类比与目的；其二，它是「插曲式的」（interstitial），只能解决手头的个案，不能制定大规模改革或法典；其三，法官必须给出一般性理由，像有良知的立法者那样，依自己的信念与价值裁决，而非任意。\n\n第三层，类比推理的作用。哈特承认，法官在疑难案件中常通过类比（reasoning by analogy）援引既有原则，这确实「推迟」了造法的时刻。但他指出，在疑难案件中，相互竞争的原则与类比可能同时呈现，而法律并未规定其优先顺序；法官必须在它们之间选择——这正是裁量不可消除的时刻。\n\n第四层，裁量与规则怀疑论的区别。哈特的裁量理论不等于规则怀疑论：规则怀疑论否认规则的存在，认为一切都是法官的判决；哈特则坚持，在大量简单案件中规则是确定的，裁量只存在于边缘与空隙。裁量是「规则之治」的补充，而非否定。", "viewpoints": "哈特的核心主张是：法官在法律未调整的疑难案件中，必须行使有限的、填补空隙的裁量；这种裁量是造法，但受实体约束、限于个案、须给出一般理由。他反对两种夸张：形式主义否认裁量的存在，规则怀疑论夸大裁量为无限。\n\n德沃金的核心主张则相反：法律是「无漏洞」的，原则与建构性诠释能为疑难案件提供唯一正确答案，因此法官在疑难案件中并无强意义裁量——他仍是在「发现」法律，而非「创造」法律。德沃金认为，哈特把裁量理解为「法律的空隙」，是对法律本质的误解；法律作为「完整性」，本就包含未被明文写出但可被诠释出来的原则。\n\n哈特在《后记》中系统回应：其一，许多原则是靠谱系被识别的，可通过承认规则纳入法律；其二，德沃金的诠释预设了对「既判法」的识别，仍离不开承认规则；其三，即便援引原则，竞争原则间仍需选择。因此，裁量虽有限，却不可消除。", "comparison": "与规则怀疑论比较：规则怀疑论认为裁量无处不在、规则是神话；哈特认为裁量限于空隙与边缘，规则中心仍确定。\n\n与形式主义比较：形式主义认为裁量应被消除、法官只是法律嘴；哈特承认裁量不可避免，关键是约束它。\n\n与德沃金比较：德沃金以原则与诠释消除强意义裁量，主张唯一正确答案；哈特坚持裁量不可消除，只是有限的、受约束的。", "debates": "争论的第一条主线是「疑难案件是否有唯一正确答案」。德沃金以「法律作为完整性」主张有；哈特认为竞争原则间仍需选择，故无。\n\n第二条主线是「裁量是否威胁民主与法治」。德沃金批评司法造法不民主、溯及既往；哈特回应：其一，处理法律未调整的案件是避免推给立法机关的必要代价；其二，向司法委任有限权力在民主社会是常态（行政委任立法更普遍）；其三，溯及既往的不义在于挫败合理期待，而疑难案件中本无明确的既存法律可供期待。\n\n第三条主线是「裁量的性质」。德沃金认为法官「发现」法律，哈特认为法官「在有限意义上创造」法律。这一分歧的深层，是「法律是否总是完整的」这一本体论差异。", "case": "英国 1991 年的 R v R 案（[1991] UKHL 12，上议院）是司法裁量与法官造法的经典案例。被告被控强奸其妻子，按当时英国法，强奸罪的定义排除夫妻关系（丈夫不能强奸妻子）。上议院最终判决：丈夫在特定情形下可以强奸妻子，推翻了长期存在的婚姻豁免。\n\n从哈特的角度看，此案是「法律未调整／调整不明」的疑难案件：既有规则（强奸定义）的文字排除丈夫，但社会观念与法律目的已发生根本变化。法官在此行使了填补空隙的裁量——通过重新阐释强奸罪的目的与原则（尊重性的自主），把婚姻豁免排除。这种造法是有限的、插曲式的：它只解决「丈夫能否强奸妻子」这一具体问题，并未制定新的法典；同时它受既有法律原则约束（对人身自主的尊重），并非任意。\n\n从德沃金的角度看，此案可理解为法官通过建构性诠释，发现了隐含在法律原则中的正确答案——法律作为「完整性」要求承认妻子的性自主。哈特则会指出：该案中不同原则（尊重婚姻传统 vs 保护人身自主）之间存在选择，法院的裁决同时也在发展法律，这正体现了填补空隙的裁量。", "caseAnalysis": "就 R v R 而言，事实是被告被控强奸妻子，旧法排除夫妻间的强奸；争议焦点是：法院能否改变长期存在的婚姻豁免。法律依据上，上议院通过重新阐释强奸罪的本质作出裁决。理由上，婚姻不再被视为对性的概括同意，人身自主原则优先。\n\n理论意义在于：第一，它展示疑难案件中法律规则的「空隙」——旧规则文字明确，但与社会目的脱节；第二，它印证哈特的「有限造法」——法院的裁决受人身自主原则约束，且限于具体议题；第三，它揭示争论的核心——德沃金视此为「发现」隐含原则，哈特视此为「填补空隙的裁量」，同一案件可从两种角度解读，正说明争论的深度。", "summary": "自由裁量指在法律未完全决定结果时裁判者的选择空间，可分弱意义、强意义与授权性裁量。哈特主张法官在法律未调整的疑难案件中行使「填补空隙的裁量」：这种裁量是造法，但受实体约束、限于个案、须给出一般理由；它区别于规则怀疑论的无限裁量与形式主义的否认裁量。德沃金则以原则与建构性诠释主张法律无漏洞、疑难案件有唯一正确答案，否认强意义裁量。双方在答案唯一性、民主正当性、裁量性质三条主线上争论。R v R 案显示，同一案件可被解读为「发现原则」或「填补空隙」，体现争论的深度。", "furtherThinking": "1. 如果法官在疑难案件中的选择受「既有原则」约束，而原则之间又需要选择，哈特是否实际上承认了某种「强意义裁量」？他的「有限」限定能否成立？\n2. 德沃金的「唯一正确答案」是否预设了法官具备 Hercules 式的全知能力？现实法官的能力限制，是否使哈特的裁量理论更具现实解释力？\n3. 在量刑指引（sentencing guidelines）广泛采用的今天，法官的裁量被大幅压缩，这是否更接近德沃金的理想？还是只是把裁量转移到了指引的制定者手中？"}, "en": "Judicial Discretion", "level": "core", "tags": "司法裁量, 哈特, 德沃金, 疑难案件, 法官造法", "source": "Hart, The Concept of Law, ch.7, s.2；Hart, The Concept of Law, Postscript, s.6；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；H.L.A. Hart, 'The Concept of Law Revisited' (1996)；R v R [1991] UKHL 12", "id": "S3M3K3"}, "S3M3K4": {"title": "文义解释与目的解释", "EN": "Literal Interpretation and Purposive Interpretation", "LEVEL": "core", "TAGS": "文义解释, 目的解释, 法律解释方法, 法律漏洞", "TERMS": "文义解释（Literal Interpretation）::按法律语词的通常或字面含义进行解释的方法；目的解释（Purposive Interpretation）::依据法律的目的或意旨阐明规范含义的方法；黄金规则（Golden Rule）::当文义导致荒谬时允许偏离字面的折中规则；明示其一即排除其他（Expressio Unius）::列举特定事项即排除未列举事项的解释格言；法律漏洞（Gap in Law）::法律对某情形未作规定的状态；弊端规则（Mischief Rule）::探求法律欲救济的弊端以解释的方法", "SOURCE": "Hart, The Concept of Law, ch.7, s.1；Whiteley v Chappell (1868) LR 4 QB 147；Pepper v Hart [1993] AC 593；Riggs v. Palmer, 115 N.Y. 506 (1889)", "terms": [{"term": "文义解释（Literal Interpretation）", "def": "按法律语词的通常或字面含义进行解释的方法"}, {"term": "目的解释（Purposive Interpretation）", "def": "依据法律的目的或意旨阐明规范含义的方法"}, {"term": "黄金规则（Golden Rule）", "def": "当文义导致荒谬时允许偏离字面的折中规则"}, {"term": "明示其一即排除其他（Expressio Unius）", "def": "列举特定事项即排除未列举事项的解释格言"}, {"term": "法律漏洞（Gap in Law）", "def": "法律对某情形未作规定的状态"}, {"term": "弊端规则（Mischief Rule）", "def": "探求法律欲救济的弊端以解释的方法"}], "sections": {"coreQuestion": "同一条法律，按字面意思是一种结论，按立法目的可能是另一种结论。法官该听哪一个？「文义解释」与「目的解释」是两种最基本的法律解释方法，它们之间的张力，集中体现了法治中「法的安定性」与「实质合理性」的冲突。本节要厘清两种方法各自的含义与理据，分析它们在具体案件中的冲突与协调，并借助哈特（H. L. A. Hart）的开放结构理论，说明为什么法律无法预先规定这两种方法的绝对优先顺序。", "definition": "文义解释（Literal Interpretation）指按照法律语词的通常含义或字面意义来理解法律规范的方法。它的基本预设是：立法者以语言文字表达其意图，因此语词的通常含义就是法律的含义。文义解释的优点是客观、可预测，有利于法的安定性——公民可以据字面理解法律并规划行为。\n\n目的解释（Purposive Interpretation）指依据法律规则所欲实现的目的或意旨来阐明其含义的方法。它要追问「这条法律是为了解决什么问题」，据此确定规范的射程；语词表面只是起点。目的解释的优点是能适应社会变迁、避免机械适用带来的荒谬结果。\n\n两种方法的冲突，在法律史上屡见不鲜。当语词的字面含义清楚，但适用结果明显违背立法目的时，法官面临选择：坚守文义（牺牲合理性）还是诉诸目的（牺牲安定性）。\n\n此外还有一些相关方法：黄金规则（Golden Rule）——当文义导致荒谬结果时，允许偏离字面含义；弊端规则（Mischief Rule）——探求法律欲救济的弊端来解释；以及「明示其一即排除其他」（expressio unius est exclusio alterius）等解释格言。这些方法构成了法官解释的法律工具箱。", "history": "文义解释与目的解释的对立，反映了两大法系的传统差异。大陆法系受法典化传统影响，强调文义解释的优先性，「法律条文的含义就是其字面含义」；普通法系则更灵活，发展出弊端规则、黄金规则等，允许法官探求立法目的。\n\n十九世纪的机械法理学（形式主义）把文义解释推向极致，认为法律是一个封闭的逻辑体系，法官只需机械涵摄。但这种方法在工业化、城市化的社会变迁中暴露出僵化的问题——字面适用常导致不合情理的结果。二十世纪的目的法学、利益法学则强调法律的目的，主张法官应探求立法意旨以实现社会正义。\n\n哈特在《法律的概念》第七章以「开放结构」为这一争论提供了理论框架：语词有确定核心与模糊边缘，文义在核心有效，目的考量在边缘发挥作用。法律通常没有规定文义与目的的优先顺序，因此法官在具体案件中必须判断。", "principle": "理解文义与目的解释的关系，可分五层。\n\n第一层，文义解释的理据。法律以语言为载体，公民据字面理解法律，因此尊重文义是民主与法治的要求——「如果法律的含义可以随意偏离字面，公民就无法预知行为的法律后果」。文义解释还体现对立法权的尊重：法官按字面适用，是在执行立法者的意思，而非自己的价值判断。\n\n第二层，目的解释的理据。语言有开放结构，字面含义在边缘地带不确定；且社会变迁会使立法时的语词脱离原初语境。目的解释通过追问「法律为何而设」，为边缘地带的判断提供指引，使法律保持对社会需求的回应能力。\n\n第三层，两种方法的冲突。经典冲突形态是：语词字面清楚，但适用结果荒谬或不义。此时坚守文义会牺牲实质合理，诉诸目的会削弱法的安定性。哈特指出，由于法律通常未规定方法的优先顺序，这种冲突的解决本身需要判断——这是开放结构在方法论层面的体现。\n\n第四层，协调的技术。法律体系发展出多种协调技术：黄金规则作为折中，允许在文义荒谬时偏离字面；弊端规则探求立法欲救济的问题；目的解释可在文义的范围内选择最符合目的的含义。此外，解释格言（如 expressio unius）提供具体指引。这些方法共同构成「解释的指针」，但都不是绝对的。\n\n第五层，哈特的立场。哈特既不主张文义绝对优先，也不主张目的可以任意取代文义。他承认在核心地带文义足以决定结果，在边缘地带则需要目的考量与选择。重要的是，选择必须有理由，且受既有法律原则约束——这正是「填补空隙的裁量」的方法论表现。", "viewpoints": "哈特的核心主张是：文义解释与目的解释都是法律解释的重要方法，但法律本身并未规定它们的绝对优先顺序；在规则的核心地带，文义足以决定结果，在边缘地带则需目的考量，此时法官的选择受既有原则约束，是「填补空隙的裁量」的一部分。哈特反对两种极端：把文义绝对化的形式主义，以及把目的绝对化、允许法官任意偏离文本的做法。\n\n德沃金对目的解释有更系统的发展：他的「建构性诠释」要求法官在解释法律时，既要「适合」既有法律文本与实践，又要为其提供最佳道德证成。这种方法既非纯粹的文义，也非无拘束的目的探求，而是把文本与道德目的结合的诠释活动。", "comparison": "与原意主义比较：原意主义强调探求立法者原意，常支持文义解释；目的主义强调法律的客观目的，支持目的解释。哈特则关注两种方法在开放结构中的功能，不预设某一方法的绝对优先。\n\n与形式主义比较：形式主义把文义解释绝对化，认为法律含义由字面唯一决定；哈特承认文义在核心的效力，但指出边缘需要目的判断。\n\n与法律现实主义比较：现实主义倾向于把目的解释视为法官政策偏好的掩饰；哈特承认目的判断中有选择，但坚持选择受法律原则约束，不是任意。", "debates": "首要争论是「文义与目的何者优先」。文义优先论者强调法的安定性、民主正当性与可预测性；目的优先论者强调实质正义与法律对社会变迁的回应。哈特认为，由于法律未规定优先顺序，这实际上是一个在具体案件中需要判断的问题——判断本身即裁量的体现。\n\n第二个争论关乎「目的由谁定义」。目的解释须先确定「法律的目的」，但立法目的可能多重、模糊，甚至不存在单一目的。批评者认为，目的解释赋予法官过大权力，可把自己的价值偏好包装为「立法目的」。哈特承认这一风险，但认为在边缘地带完全排除目的考量同样不可接受——关键在于通过原则与先例约束目的判断。\n\n第三个争论关乎「偏离文义的界限」。黄金规则允许在文义荒谬时偏离字面，但「荒谬」本身需要判断。批评者认为，这为法官任意偏离文本打开了缺口。哈特的回应是：这种偏离必须给出一般性理由，且受既有法律体系的目的与原则约束。", "case": "英国 1868 年的 Whiteley v Chappell 案（LR 4 QB 147）是文义解释的经典案例。一项法律规定，任何人「冒充有权投票的人」（personate any person entitled to vote）投票即构成犯罪。被告冒充一名已故者投票。按目的解释，这种行为显然在禁止之列——立法目的是防止选举舞弊。但法院按严格的文义解释认为：已故者「无权投票」（not entitled to vote），因此被告并未「冒充有权投票的人」，不构成该项犯罪，判决被告无罪。\n\n这个案例常被用来说明文义解释的极端后果——遵守字面含义，却明显背离了立法目的。从哈特的视角看，此案中「有权投票的人」的字面含义清楚（核心地带），因此文义解释决定了结果；但这一结果暴露了语言在边缘情形（已故者是否算「有权投票的人」）的局限。哈特会说，此处字面的「核心」在特殊情形下产生了荒谬，法院若采目的解释，就是在填补空隙——但必须诚实承认这是一种选择，而非声称字面「本来」就包含该情形。\n\n此案也说明，文义与目的的冲突会落到具体的判决差异上，理论问题之说低估了它。现代法律体系通常通过更精细的立法技术（如明确界定「人」的范围）来减少这种冲突，但由于语言的开放结构，冲突无法被彻底消除。", "caseAnalysis": "就 Whiteley v Chappell 而言，事实是被告冒充已故者投票；争议焦点是：已故者是否属于「有权投票的人」。法律依据上，法院严格按字面含义解释。理由上，既然已故者无权投票，冒充他就不是冒充「有权投票的人」。\n\n理论意义在于：第一，它展示了文义解释在核心地带的决定力——字面的清楚含义主导了判决；第二，它暴露了文义解释的局限——字面与目的明显背离，却因严格遵守字面而得出似乎不合情理的结论；第三，它印证哈特的开放结构——「有权投票的人」的边缘情形（已故者）暴露了语言分类的局限，法院的选择（文义优先）本身是一种方法论判断。这一案例也提示：立法者可通过更精确的表述减少此类冲突，但无法穷尽所有边缘情形。", "summary": "文义解释按语词通常含义理解法律，强调客观与法的安定性；目的解释依法律目的阐明规范含义，强调实质合理与社会回应。二者冲突时，法官面临安定性与合理性的两难。哈特以开放结构提供框架：核心地带文义足以决定，边缘地带需目的考量与选择，而选择受既有原则约束。德沃金的建构性诠释则把文本与道德目的结合。Whiteley v Chappell 显示，文义解释在核心地带虽有决定力，却可能背离立法目的，暴露语言分类的局限。由于法律未规定两种方法的绝对优先顺序，具体案件中的方法选择本身即是裁量的体现。", "furtherThinking": "1. 如果立法者能通过精确立法彻底消除文义与目的的冲突，法律解释是否就不再需要判断？哈特会说这种精确可能吗？\n2. 在 Whiteley v Chappell 中，法院坚守文义是否体现了对民主立法权的尊重？这种尊重与「实质正义」之间的张力，应如何权衡？\n3. 当代宪法解释中的「原意主义」与「活宪法论」之争，在多大程度上是文义解释与目的解释之争的延续？"}, "en": "Literal Interpretation and Purposive Interpretation", "level": "core", "tags": "文义解释, 目的解释, 法律解释方法, 法律漏洞", "source": "Hart, The Concept of Law, ch.7, s.1；Whiteley v Chappell (1868) LR 4 QB 147；Pepper v Hart [1993] AC 593；Riggs v. Palmer, 115 N.Y. 506 (1889)", "id": "S3M3K4"}, "S3M3K5": {"title": "历史解释与体系解释", "EN": "Historical Interpretation and Systematic Interpretation", "LEVEL": "fundamental", "TAGS": "历史解释, 体系解释, 法律解释方法, 立法意图", "TERMS": "历史解释（Historical Interpretation）::通过立法史料探求法律制定背景与意图的解释方法；体系解释（Systematic Interpretation）::将法律规范置于整个法律体系中、联系其他规范进行解释的方法；立法意图（Legislative Intent）::立法者制定法律时欲达成的目的；立法史料（Legislative History）::法案审议记录、委员会报告等历史材料；法律体系性（Systemicity of Law）::法律规范之间相互关联构成统一整体的属性；Heydon's Case::1584年确立弊端规则的英国判例", "SOURCE": "Hart, The Concept of Law, ch.7, s.1；Heydon's Case (1584) 76 E.R. 637；Pepper v Hart [1993] AC 593 (H.L.)", "terms": [{"term": "历史解释（Historical Interpretation）", "def": "通过立法史料探求法律制定背景与意图的解释方法"}, {"term": "体系解释（Systematic Interpretation）", "def": "将法律规范置于整个法律体系中、联系其他规范进行解释的方法"}, {"term": "立法意图（Legislative Intent）", "def": "立法者制定法律时欲达成的目的"}, {"term": "立法史料（Legislative History）", "def": "法案审议记录、委员会报告等历史材料"}, {"term": "法律体系性（Systemicity of Law）", "def": "法律规范之间相互关联构成统一整体的属性"}, {"term": "Heydon's Case", "def": "1584年确立弊端规则的英国判例"}], "sections": {"coreQuestion": "一条法律的含义，有时需要从它「从哪里来」寻找答案，有时需要从它「在体系中处于什么位置」寻找答案。前者是历史解释，后者是体系解释。这两种方法看似技术性，却涉及对法律的根本理解：法律是立法者某一时刻意图的「化石」，还是一个活生生的、自我调整的规则体系？本节介绍这两种基本解释方法，说明它们的依据、操作方式与局限，并借哈特（H. L. A. Hart）的理论指出：方法本身也有开放结构，选择何种方法同样需要判断。", "definition": "历史解释（Historical Interpretation）指通过考察法律制定时的历史背景、立法材料来探求法律含义的方法。它关注的通常是「立法者当时想解决什么问题」——包括立法审议记录、委员会报告、法案说明等立法史料（Legislative History）。历史解释的典型形态是弊端规则（Mischief Rule）：探求法律欲救济的「弊端」，据此确定规范的射程。\n\n体系解释（Systematic Interpretation）指将法律规范置于整个法律体系中，联系其他相关规范来理解其含义的方法。它基于一个基本预设：法律是相互关联、内在一致的体系（法律体系性），孤立条文的堆砌说明不了它。因此，一条规则的含义，应从它与其他规则、与整个法律秩序的关系中确定。体系解释包括「明示其一即排除其他」（expressio unius）等具体方法，以及上位法优于下位法、特别法优于一般法等冲突规则。\n\n两种方法的差异在于参照系：历史解释向外求诸立法者的历史意图，体系解释向内求诸法律体系的内在结构。它们常与文义解释、目的解释配合使用。", "history": "历史解释的传统源远流长。在英国，1584 年的 Heydon's Case 确立了弊端规则：法官应考察普通法之前的弊病、立法者欲救济的缺陷，据此解释法律。这成为历史解释的经典表述。在大陆法系，历史解释长期与探求「立法者原意」的历史法学派相联系。\n\n体系解释则与法典化传统密切相关：当法律被编纂为体系化的法典时，解释个别条文就必须联系整部法典的结构与逻辑。十九世纪的概念法学把体系解释推向极致，追求概念之间的严密推导。\n\n二十世纪的法律现实主义与形式主义之争，使这两种方法的绝对性受到质疑：批评者指出，「立法意图」往往是模糊、多重甚至虚构的，而「体系一致性」也常掩盖法官的价值判断。哈特以开放结构理论为这些方法定位：它们都是解释的指针，能帮助减少不确定性，但都不能自我解释，也不能消除边缘地带的选择。", "principle": "历史解释的操作可分三步：其一，确定相关的立法史料（如议会辩论、委员会报告）；其二，从中识别立法者欲救济的弊端或欲达成的目的；其三，据此确定争议条文的含义。英国上议院在 Pepper v Hart [1993] 案中确立：只有在法律语词模糊、含糊或可能导致荒谬时，法院才能参考 Hansard（议会辩论记录）。\n\n体系解释的操作则包括：其一，把争议条文放在其所在的法律部门、章节中理解；其二，联系相关条文（如定义条款、例外条款）确定其边界；其三，运用冲突规则（上位法优于下位法、特别法优于一般法、新法优于旧法）解决规范之间的矛盾；其四，确保解释结果与整个法律秩序的基本原则一致。\n\n两种方法的局限也需说明。历史解释的困难在于：立法意图常常是多重的、模糊的，甚至不存在一个统一的「立法者意图」；参考立法史料还可能被批评为「探寻一个从不存在的心理实体」。体系解释的困难在于：法律体系本身可能并不完全融贯，规范之间存在真实的价值冲突，「体系一致性」可能掩盖而非解决这些冲突。\n\n哈特的理论为理解这两种方法提供了框架：它们都是「解释的指针」，能帮助法官在开放地带作出有理由的选择，但都不能提供自动的答案。由于法律通常未规定这些方法的优先顺序，法官在具体案件中的方法选择，本身即是一种判断。", "viewpoints": "哈特的核心主张是：历史解释与体系解释都是法律解释的重要方法，但都受语言的开放结构限制。它们能减少不确定性，却不能彻底消除它；由于法律未规定方法的优先顺序，法官的选择是「填补空隙的裁量」的一部分。哈特不认为存在一种能自动决定一切案件的解释方法——这既是他反对形式主义的地方，也是他区别于规则怀疑论的地方。\n\n就历史解释而言，哈特会提醒：即使参考了立法史料，「立法意图」本身仍需解释——立法者的言论可能有多种理解，且未必能覆盖未曾预见的情形。就体系解释而言，哈特会指出：法律体系的「一致性」是一种理想，现实中存在真实的规范冲突，法官在解决冲突时仍须作出选择。", "comparison": "与原意主义比较：原意主义强调探求立法者在制宪／立法时的原意，是历史解释的一种强形式；哈特对此保持距离，认为「原意」常常是不确定的。\n\n与形式主义比较：形式主义把体系解释推向极致，认为法律是封闭自足的逻辑体系；哈特承认体系性的价值，但指出开放结构使体系无法完全自足。\n\n与德沃金比较：德沃金的「建构性诠释」与体系解释有相通之处——都强调联系整体来理解部分；但德沃金更进一步，要求联系道德原则为法律提供最佳证成，这超出了哈特的描述性框架。", "debates": "围绕这两种方法的首要争论，是「探求立法意图是否可能且正当」。批评者指出，「立法者」往往是一个集合体，其成员各有不同意图，所谓统一的「原意」很可能是一种虚构；历史解释因而被指责为给法官的主观判断披上「还原历史」的外衣。辩护者则回应：立法史料（如审议记录、委员会报告）毕竟提供了可核查的客观材料，据此探求目的，总比法官凭空臆断更可信赖。\n\n第二个争论关乎「体系一致性是否真实存在」。体系解释预设法律是融贯的整体，但批判法学指出，法律体系中充满真实而不可通约的价值冲突，「一致性」往往只是掩盖冲突的修辞。哈特的立场为这一争论提供了议程：他承认法律体系在多数时候是融贯的，但也指出开放结构与边缘争议意味着「一致性」是一种有限度的理想，而非自动可得的答案。\n\n第三个争论是「方法选择本身是否受法律约束」。由于法律通常未规定历史解释与体系解释的优先顺序，法官选择何种方法，往往就决定了结果。哈特把这种选择归入「填补空隙的裁量」：它须给出理由、受原则约束，却无法由法律自动决定。", "case": "英国 1584 年的 Heydon's Case（76 E.R. 637）是历史解释（弊端规则）的经典判例。该案确立了解释成文法的四条规则：一，考察普通法在此类事项上的既有规定；二，识别法律欲救济的「弊端与缺陷」；三，考察立法者为救济弊端而采用的方法；四，据此解释法律，以「压制弊端、促进救济」为目标。这一判例使历史解释有了系统的操作框架，影响了后世数百年的法律解释实践。\n\n从哈特的视角看，Heydon's Case 的意义在于：它明确承认法律解释需要超出字面，探求立法背后的目的与弊端——这正是应对语言开放结构的一种技术。但它也印证哈特的提醒：识别「弊端」与「救济方法」本身需要判断，不同的法官可能对同一法律识别出不同的弊端，因此历史解释并不提供自动的答案。Heydon's Case 确立的是一种「解释的指针」，而非机械规则。", "caseAnalysis": "就 Heydon's Case 而言，事实是法院需解释一项成文法，争议焦点是应采何种解释方法；该案确立了探求弊端与救济目的的解释路径。其法律依据在于普通法与制定法的关系。理由上，法律是为救济特定弊端而制定的，故解释应服务于这一目的。理论意义在于：第一，它展示了历史解释的系统方法；第二，它印证哈特关于「解释需要选择」的分析——识别弊端本身即判断；第三，它与现代 Pepper v Hart 案形成呼应——都试图通过考察立法背景来确定含义，只是材料与条件不同。", "summary": "历史解释通过立法史料探求法律制定背景与意图，典型形态为弊端规则；体系解释将规范置于法律体系中、联系其他规范理解其含义。二者常与文义、目的解释配合使用，其差异在参照系：前者求诸立法历史，后者求诸体系内在结构。哈特以开放结构为二者定位：它们都是解释的指针，能减少但不能消除不确定性；由于法律未规定方法优先顺序，方法选择本身即裁量。Heydon's Case 确立了弊端规则的系统框架，既展示历史解释的方法，也印证其判断性本质。", "furtherThinking": "1. 当立法史料显示立法者的意图与法律文本的通常含义冲突时，应优先考虑哪一个？这反映了法治中哪两种价值的张力？\n2. 体系解释预设法律体系是融贯的，但真实的体系常含价值冲突。当「体系一致性」掩盖了真实冲突时，体系解释是否反而成为法官回避价值判断的借口？\n3. 在跨法域比较中（如解释一部统一适用的国际条约），历史解释与体系解释各自面临什么特殊困难？"}, "en": "Historical Interpretation and Systematic Interpretation", "level": "fundamental", "tags": "历史解释, 体系解释, 法律解释方法, 立法意图", "source": "Hart, The Concept of Law, ch.7, s.1；Heydon's Case (1584) 76 E.R. 637；Pepper v Hart [1993] AC 593 (H.L.)", "id": "S3M3K5"}, "S3M3K6": {"title": "法律原则与规则的关系", "EN": "The Relationship Between Legal Principles and Rules", "LEVEL": "core", "TAGS": "法律原则, 法律规则, 德沃金, 哈特, 疑难案件", "TERMS": "法律规则（Legal Rules）::以全有或全无方式适用的行为规范；法律原则（Legal Principles）::作为裁判理由、可被权衡而未必决定结果的标准；全有或全无（All-or-Nothing）::规则要么适用要么不适用的适用方式；分量（Weight）::原则在权衡中相对重要性的维度；建构性诠释（Constructive Interpretation）::德沃金所述寻找既适合又最佳证成原则的方法；法律作为完整性（Law as Integrity）::德沃金把法律理解为融贯的道德实践的理论", "SOURCE": "Hart, The Concept of Law, Postscript, s.4；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；Ronald Dworkin, Law's Empire (1986)；Riggs v. Palmer, 115 N.Y. 506 (1889)；Donoghue v Stevenson [1932] AC 562", "terms": [{"term": "法律规则（Legal Rules）", "def": "以全有或全无方式适用的行为规范"}, {"term": "法律原则（Legal Principles）", "def": "作为裁判理由、可被权衡而未必决定结果的标准"}, {"term": "全有或全无（All-or-Nothing）", "def": "规则要么适用要么不适用的适用方式"}, {"term": "分量（Weight）", "def": "原则在权衡中相对重要性的维度"}, {"term": "建构性诠释（Constructive Interpretation）", "def": "德沃金所述寻找既适合又最佳证成原则的方法"}, {"term": "法律作为完整性（Law as Integrity）", "def": "德沃金把法律理解为融贯的道德实践的理论"}], "sections": {"coreQuestion": "法律和道德之间，除了「禁止什么」，还有「应当追求什么」。后者常以「原则」的面目出现——如「任何人不得从自己的错误中获利」「尊重人的尊严」。这些原则是法律的一部分吗？如果是，它们与规则有何不同？德沃金（Ronald Dworkin）正是以「法律原则」为武器，挑战哈特（H. L. A. Hart）的「规则模式」与承认规则理论。本节要厘清规则与原则的区别、原则的法律地位，以及哈特在《后记》中如何回应德沃金的挑战。", "definition": "法律规则（Legal Rules）与法律原则（Legal Principles）的区别，是德沃金法理学的核心。德沃金指出，规则以「全有或全无」（all-or-nothing）的方式适用：如果一条规则有效且事实符合其条件，就必须接受它的法律后果——规则要么适用，要么不适用，没有中间地带。例如「遗嘱须有两名证人」这条规则，满足了就有效，不满足就无效。\n\n原则则不同。原则是具有「分量」（weight）的裁判理由：它在具体案件中被权衡，可能支持某个判决，但未必决定它；其他原则可能有更大的分量而压倒它。例如「不得从错误中获利」是一条原则，它支持剥夺杀人继承人的继承权，但并不排除在某些情形下被其他考量压倒。原则不因被压倒而失效——它仍在其他案件中发挥作用。\n\n德沃金据此论证：法律不仅包含规则，也包含原则；而原则无法通过哈特的承认规则（以「谱系」即形式来源为判准）来识别，因为原则的效力来自其内容的道德正当性，而非制定机关。因此，哈特必须放弃承认规则理论。\n\n哈特在《后记》中回应：这一挑战被夸大了。其一，许多法律原则是可以靠「谱系」识别的——它们被法院一贯援引（如「不得从错误中获利」）或被写入宪法（如言论自由条款），因此可由承认规则捕捉。其二，德沃金自己的诠释性判准也预设了对「既判法」的识别，而这仍需承认规则。", "history": "规则与原则的区分，在法理学中源远流长，但德沃金在 1960-70 年代将其系统化为对实证主义的批判。他在《规则的模式》(The Model of Rules, 1967) 与《认真对待权利》(Taking Rights Seriously, 1977) 中，以里格斯诉帕尔默案等疑难案件为据，论证法律包含道德原则，实证主义的「承认规则」无法解释这一点。\n\n哈特长期未作系统回应，直至 1994 年《法律的概念》第二版所附《后记》(Postscript)，才专门回应德沃金。在《后记》第四章「原则与承认规则」中，哈特承认法律原则的存在，但反驳承认规则可以被放弃的结论。这场争论成为当代法理学关于法律性质、法律与道德关系的核心议题。", "principle": "理解规则与原则的关系，可分四层。\n\n第一层，适用方式的差异。规则以全有或全无的方式适用：满足规则条件，就必须接受其结论。原则则以分量方式作用：它是「支持某判决的理由」，但可被其他更强的理由压倒。这一差异是德沃金区分二者的核心。\n\n第二层，原则的谱系识别。哈特指出，许多原则恰恰是靠谱系被识别的：它们被法院在一系列案件中持续援引（如普通法中「不得从自己错误中获利」），或被写入宪法文本（如美国宪法第一修正案）。这些原则的效力来自其被权威机关采纳或使用的方式，而非纯粹的道德内容。因此，原则同样可被承认规则捕捉。\n\n第三层，诠释性判准与承认规则。哈特承认，有些原则可能靠「内容」而非谱系被识别——即德沃金所说的「既适合既有法律又为其提供最佳道德证成」。但哈特指出，这种诠释性判准预设了对「既判法」（preinterpretive law）的识别，而识别既判法恰恰需要承认规则来确定法律渊源及其位阶。因此，承认规则非但没有被放弃，反而是原则识别的前提。\n\n第四层，软化与让步。哈特在《后记》中承认，某些体系（如美国）的承认规则可以把道德原则纳入效力判准（柔性实证主义）。他也承认「规则模式」需要修正——法律不仅包含规则，也包含原则。因此，德沃金的批评虽被夸大，却促使哈特修正了自己的理论。", "viewpoints": "德沃金的核心主张是：法律不仅包含规则，还包含原则；原则以分量的方式起作用，无法靠承认规则的谱系判准识别，因此哈特的规则模式与承认规则理论应当被放弃或修正。法律作为「完整性」（law as integrity），要求法官通过「建构性诠释」找到既适合既有法律、又能为其提供最佳道德证成的原则，并在疑难案件中存在唯一正确答案。\n\n哈特的核心主张是：德沃金夸大了原则对承认规则的挑战。其一，许多原则可靠谱系识别；其二，诠释性判准预设了对既判法的识别，仍需承认规则；其三，承认规则本身可容纳道德判准（柔性实证主义）。因此，承认原则为法律的一部分，与承认规则理论并不矛盾。哈特承认自己的规则模式需要修正，但拒绝放弃承认规则。", "comparison": "与法律实证主义内部比较：哈特的「包容实证主义／柔性实证主义」允许道德原则通过承认规则进入法律；拉兹（Joseph Raz）等「排他实证主义」则坚持法律识别只能诉诸社会来源，不承认道德原则可作为法律。德沃金则站在实证主义之外，主张法律必然包含道德原则。\n\n与形式主义比较：形式主义把法律理解为封闭的规则体系，否认原则的作用；德沃金与哈特（修正后）都承认原则在法律推理中的地位。\n\n与自然法比较：德沃金的原则理论把道德重新引入法律的核心，被认为接近自然法；但与自然法不同的是，德沃金强调原则须「适合」既有法律实践，而非直接诉诸抽象正义。", "debates": "争论的第一条主线是「原则能否靠谱系识别」。德沃金认为原则的效力来自内容，不靠谱系；哈特以「不得从错误中获利」等原则被法院一贯援引为例，说明原则可以靠谱系识别。\n\n第二条主线是「诠释性判准是否预设承认规则」。德沃金认为建构性诠释无需承认规则；哈特指出诠释须先识别「既判法」，而这正是承认规则的功能——因此承认规则是原则识别的前提，而非其替代物。\n\n第三条主线是「疑难案件是否存在唯一正确答案」。德沃金主张存在；哈特坚持竞争原则间仍须选择，法官须行使填补空隙的裁量。", "case": "里格斯诉帕尔默案（Riggs v. Palmer, 115 N.Y. 506 (1889)）是规则与原则关系的经典案例。孙子帕尔默毒杀祖父以确保继承遗产。遗嘱符合所有法定形式要件，按继承规则（规则以全有或全无方式适用），帕尔默有权继承。但法院判决他不得继承，理由是一项法律原则：「任何人不得从自己的错误中获利」。\n\n从德沃金的角度看，此案证明法律原则也是法律，且原则以「分量」压倒了继承规则，为案件提供了唯一正确答案。从哈特的角度看，此案同样可被纳入承认规则框架：「不得从错误中获利」是一项被法院一贯援引的原则，其法律地位可由谱系识别；它作为一项法律原则，与承认规则并不冲突。分歧在于：法院最终在「尊重遗嘱形式」与「不得从错误中获利」之间作出的选择，德沃金认为由原则的分量唯一决定，哈特则认为其中仍包含法官的选择。\n\n另一案例是唐纳休诉斯蒂文森案（Donoghue v Stevenson [1932]），其中「邻人原则」被提炼为注意义务的底层原则，展示了原则在发展法律中的作用。哈特在《后记》中以此说明「有限形式的建构性诠释」，但同时指出它并未消除选择。", "caseAnalysis": "就 Riggs v. Palmer 而言，事实是孙子毒杀祖父；争议焦点是：形式有效的遗嘱是否仍应让杀人者继承。法律依据上，继承规则支持帕尔默，「不得从错误中获利」原则反对。裁判理由上，法院以原则限制规则的适用。理论意义在于：第一，它展示原则作为裁判理由的分量——原则压倒了规则的字面适用；第二，它成为德沃金批判规则模式的主要论据；第三，它也支持哈特的回应——该原则有谱系（被一贯援引），可由承认规则识别。同一案件既支持德沃金的原则理论，也可被哈特纳入修正后的框架，这正体现争论的复杂性。", "summary": "法律规则以全有或全无方式适用，法律原则则以分量方式作为裁判理由，可被更强理由压倒而不失效。德沃金据此论证法律包含原则，而原则无法靠承认规则的谱系判准识别，故应放弃承认规则理论。哈特在《后记》中回应：许多原则可靠谱系识别；诠释性判准预设了对既判法的识别，仍需承认规则；承认规则亦可纳入道德判准。因此承认原则为法律并不要求放弃承认规则。双方在谱系识别、诠释与承认规则的关系、唯一正确答案三条主线上争论。Riggs v. Palmer 显示同一案件可被两种理论各自解释。", "furtherThinking": "1. 如果「不得从错误中获利」这类原则被法院一贯援引而获得谱系，那么德沃金对哈特的批评还剩多少力量？原则的「道德内容」与「谱系」是否真的可以截然分开？\n2. 德沃金说原则为疑难案件提供唯一正确答案，哈特说竞争原则间仍需选择；在实际裁判中，法院的判决是「发现」了答案，还是「作出」了选择？我们如何区分这两种描述？\n3. 在成文法体系中大量采用「诚实信用」「公序良俗」等原则性条款时，这些原则是靠谱系（立法采纳）还是靠内容（道德正当性）获得法律地位的？这对哈特与德沃金之争意味着什么？"}, "en": "The Relationship Between Legal Principles and Rules", "level": "core", "tags": "法律原则, 法律规则, 德沃金, 哈特, 疑难案件", "source": "Hart, The Concept of Law, Postscript, s.4；Ronald Dworkin, Taking Rights Seriously (1977), ch.2；Ronald Dworkin, Law's Empire (1986)；Riggs v. Palmer, 115 N.Y. 506 (1889)；Donoghue v Stevenson [1932] AC 562", "id": "S3M3K6"}, "S3M4K1": {"title": "哈特与富勒的争论", "EN": "The Hart–Fuller Debate", "LEVEL": "debate", "TAGS": "哈特, 富勒, 法律与道德, 内在道德, 恶法", "TERMS": "分离命题（Separation Thesis）::法律的存在与效力取决于社会来源，同它的道德价值属于两个可分别判断的问题；内在道德（Internal Morality）::富勒主张法律作为规则治理事业必须满足的一套程序性品质；八项合法性要求（Eight Desiderata of Legality）::一般性、公布、不溯及既往、清晰、不矛盾、可遵守、稳定、官方行为与公布规则相一致；承认规则（Rule of Recognition）::哈特理论中用以识别有效法律的终极次级规则；目的性事业（Purposive Enterprise）::富勒对法律的根本刻画，即把人类行为置于一般规则治理之下的持续努力；合法性（Legality）::法律制度符合形式与程序要求而堪当法律之名的一种品质", "SOURCE": "Wacks, Understanding Jurisprudence, 2.10.2；Hart, Positivism and the Separation of Law and Morals (1958)；Fuller, Positivism and Fidelity to Law—A Reply to Professor Hart (1958)；Fuller, The Morality of Law, ch.2–3", "terms": [{"term": "分离命题（Separation Thesis）", "def": "法律的存在与效力取决于社会来源，同它的道德价值属于两个可分别判断的问题"}, {"term": "内在道德（Internal Morality）", "def": "富勒主张法律作为规则治理事业必须满足的一套程序性品质"}, {"term": "八项合法性要求（Eight Desiderata of Legality）", "def": "一般性、公布、不溯及既往、清晰、不矛盾、可遵守、稳定、官方行为与公布规则相一致"}, {"term": "承认规则（Rule of Recognition）", "def": "哈特理论中用以识别有效法律的终极次级规则"}, {"term": "目的性事业（Purposive Enterprise）", "def": "富勒对法律的根本刻画，即把人类行为置于一般规则治理之下的持续努力"}, {"term": "合法性（Legality）", "def": "法律制度符合形式与程序要求而堪当法律之名的一种品质"}], "sections": {"coreQuestion": "二次大战结束后，一名德国妻子在1944年向盖世太保检举丈夫发表侮辱希特勒的言论，丈夫因此被判死刑（后改赴俄国前线服役）；战后她因『致使他人丧失自由』被追诉，辩称丈夫当年所受惩罚完全依据1934年的纳粹法律。法院最终定罪，理由是该法律违背了『所有正派人的健全良知与正义感』。这个判决引出一个法理学上极难回避的问题：当制定法极度邪恶时，法官能否以道德为由拒不承认它是法律？哈特（H. L. A. Hart）与富勒（Lon L. Fuller）在1957至1958年围绕此案展开的论战，把『法律与道德是否必须分离』这一抽象命题，变成了一场关于司法义务的正面交锋。本节要厘清：两人各自在什么意义上使用『法律』一词，他们共享了哪些前提，分歧又究竟落在哪一步。", "definition": "分离命题是哈特法律实证主义（Legal Positivism）的基石：一条规则是不是有效法律，取决于它是否出自被承认的权威、依循正确的程序，也就是取决于它的社会来源；它是否道德，属于另一个问题。哈特从不主张法律与道德在事实上互不往来，他坚持的只是两项判断在概念上可以分开。内在道德则是富勒提出的核心概念：法律是一项『把人类行为置于一般规则治理之下』的目的性事业，无论其实质目标为何，这项事业本身都内含若干程序性要求，违反到一定程度，剩下的就只是赤裸的国家强制，而不是法律。富勒把这些要求整理成八项合法性品质：一般性、公布、不溯及既往、清晰、不矛盾、可遵守、稳定，以及官方行为与已公布规则相一致。需要留意，富勒称其为『渴望的道德』（morality of aspiration），区别于『义务的道德』（morality of duty）——它诉诸的是立法者的技艺自尊与受托责任感，而非对最低底线的被动遵守。", "history": "论战的起点是哈特1957年4月在哈佛法学院发表的霍姆斯讲座，题为『实证主义与法律与道德的分离』，次年刊于《哈佛法律评论》；富勒随即以『实证主义与忠于法律——答哈特教授』回应，同样发表于1958年。二战与纽伦堡审判的经验是这场争论的共同背景：极权政权以合法形式贯彻种族灭绝，迫使法学家重新思考『恶法』的地位。德国法学家拉德布鲁赫（Gustav Radbruch）在战后提出，极端不正义的法律应让位于正义，这条思路深刻影响了西德法院的判决。富勒继承了这一方向的关切，却走了一条不同的路：他从法律这种制度的内在结构出发，论证形式与程序要求本身就是道德性的，超越国家制定的高级法并非他的依托。Wacks 把这场论战列为理解法理学的关键入口，原因正在于它把效力与正当性的关系第一次摆到了台面上。", "principle": "哈特的论证分三层展开。第一层是识别标准：在发达法律体系中，承认规则提供有效性的判准，纳粹1934年的授权法经由当时被接受的识别程序生效，因此在描述意义上是一条有效法律。第二层是语言与逻辑层面：把一条极端邪恶的规则逐出『法律』概念，并不能自动解决道德问题，反而会掩盖我们真正应当面对的选择——要么服从，要么抵抗。第三层是让步：哈特承认法律必须满足『最低限度的自然法』条件才能维持自身，例如规则必须可被遵守、必须公开、不得溯及既往地惩罚；但满足这些条件与值得服从之间仍隔着一道道德判断。富勒的论证同样层层推进。他把立法比作一位『雷克斯王』（King Rex）接连八次失败的尝试：没有规则、不公布、溯及既往、语意不清、自相矛盾、要求无法做到的事、朝令夕改、官方行为与宣布的规则脱节。这八种失败对应八项合法性要求。富勒主张，一项制度若在这八方面整体失败，人们便无法以规则规划自己的生活，『法律』也就无从存在；遵守这些要求虽不足以保证实质正义，却使坏法律更难藏身。", "viewpoints": "哈特的核心主张可以概括为：承认恶法的法律地位，同谴责并拒绝服从它，两者完全可以并存。他偏好边沁式的直白表述——『法律可能仍是法律，却邪恶到不该被服从』。在他看来，法院若为了道德目的而宣称纳粹法律根本不是法律，就不得不借助溯及既往的理由定罪；而哈特与富勒其实都更希望当时有一部明确的溯及既往立法来追究告密者，因为那至少诚实地承认了道德选择在起作用。富勒的核心主张则是：忠于法律与忠于不义之间并不存在可以清晰切开的两难，因为一项背离内在道德到如此程度的规范，压根没有资格被称为法律。他批评实证主义把『法』处理成一个道德上中性的材料，仿佛法官只需在『适用不道德的既成事实』与『做正确而体面的事』之间做选择；在富勒看来，这种描绘把实践问题人为地语义化了。双方的分歧因此不在结论而在概念：哈特要维护描述性法理学的清晰，富勒要维护司法者的道德主体性。", "comparison": "把这场争论放在更大的坐标系里，可以看到三种典型姿态。法律实证主义以来源判准识别法律，主张效力判断与价值判断可分；古典自然法诉诸一套实质性的高级规范，主张严重违背正义的规则丧失法律资格；富勒则居于两者之间，他主张的是程序自然法，要求的形式条件并不直接输出实质正义，却构成法律之所以为法律的前提。德沃金后来对这场争论做了一个著名的重新定位：在他看来，『纳粹法律是不是法律』在语义层面是一场空洞争论，真正有意义的问题是解释性的——能否把那段制度史纳入一个既契合又能为其提供最佳道德辩护的原则体系。哈特在《法律的概念》第三版后记中回应说，即便极端邪恶的制度，在『前解释』意义上仍可被称为法律，因为它在制定、裁判、执行等形式特征上与正当制度并无二致。这一回应表明，哈特允许描述性研究与解释性研究并行，而富勒则坚持概念本身承载价值。", "debates": "争论的火力集中在告密者案。哈特指出，西德法院以『健全良知』为由推翻纳粹制定法的效力，实际上是在偷偷援引一项溯及既往的刑法；这种做法牺牲了法律的确定性，却没有带来道德上的诚实。他的论证策略是先把『法是什么』与『法应当是什么』分开，再承认前者无法提供抵抗的理由，从而把道德责任交还给道德判断。富勒反驳说，实证主义的分隔造成了虚假的清醒：一旦法官习惯了把法律当作与价值无涉的给定材料，他就会在道德灾难来临时丧失批判语言。富勒进一步指出，纳粹法制在八项合法性要求上全线溃败——秘密法、任意溯及、规则与官方行为脱节——因此它本来就处在『法律』概念的边缘之外。Wacks 提醒我们注意双方论据的不对称：Summers 认为富勒嘴上主张必然联系，其具体论证多数只支持偶然联系，即遵守八项要求通常有助于善的目标，却无法逻辑地排除一个形式完美而实质邪恶的秩序。南非种族隔离制度很可能满足了全部八项形式要求，富勒只能辩称其种族定义本身过于任意而不够『一般性』。这个反驳并未被完全化解，但它揭示了一个重要事实：形式合法性是法律的重要价值，却从来不是正义的充分条件。", "case": "回到告密者案本身。据 Wacks 记载，1944年一名德国妻子厌恶其丈夫，向盖世太保检举他在谈论战局时侮辱希特勒；丈夫被审判并判处死刑，后改判至俄国前线服役。1949年，妻子因『促成丈夫失去自由』而在战后西德法院受审。她的辩护逻辑十分直白：丈夫所受的处分完全合乎当时有效的法律，她不过是借助了现成的法律机制。法院却拒绝接受这一辩护，判定1934年的纳粹法律触犯了『所有正派人的健全良知和正义感』，据此定罪。这里有一个耐人寻味的细节：哈特与富勒在抽象层面针锋相对，却都认为最好的处理办法是由立法机关制定溯及既往的追究法律。换言之，两人在具体裁判结论上并无根本分歧，他们争夺的是解释这项裁判的法理语言——究竟应说『那不是法律』，还是应说『那是法律，但必须被道德地否定』。", "caseAnalysis": "就事实而言，本案争议的是追诉告密者能否援引一项已经被否定的政权所制定的法律；争点是法院可否以道德理由否定制定法的效力。从法律依据看，辩方依赖的是当时形式有效的纳粹法令，控方则依赖战后自然法式的正义原则。裁判理由的关键，在于法院把『良知与正义感』提升为识别法律的终极标准，这恰好是哈特所警惕的做法：它让法官在个案中以自己的道德判断重写有效性判准。富勒会为此辩护：由于纳粹法制在公布、可遵守、官方行为一致性等方面系统性地失败，法院所做的不过是指认一项早已不成其为法律的东西。本案的理论意义有三层：其一，它显示分离命题的实践意义在于要求抵抗者明确承担道德责任；把它理解为纵容恶法，其实是一种误解；其二，它暴露了形式合法性自身的限度，一个在程序上四平八稳的体系仍可能服务于不义；其三，它说明法理学的概念选择会影响法律人的自我理解——法官究竟把自己看作发现法律的工匠，还是塑造秩序的政治行动者。两种自我理解都会影响判决的说理方式，进而影响公众对司法正当性的判断。", "summary": "哈特与富勒的论战围绕一个具体裁判展开，却上升为关于法律概念边界的根本分歧。哈特以承认规则与社会来源界定法律效力，主张效力判断与道德谴责可以各司其职；富勒以『规则治理的目的性事业』界定法律，提出八项内在道德要求，主张严重背离这些要求的制度已丧失法律资格。两人的论证各有软肋：哈特难以解释为何描述性判准足以构成法官的行动理由，富勒则难以说明纯粹形式的合法性如何担保正义。论战的持久价值在于它确立了一个坐标——此后任何法律理论都必须交代效力与正当性的关系。德沃金把它转译为解释性问题，哈特在后记中以『前解释意义』回应，争论由此延续到下一场交锋。", "furtherThinking": "1. 如果一部法律在程序上完全符合富勒的八项要求，却在内容上系统性歧视某一群体，按富勒的框架应当如何处理这个反例？\n2. 哈特坚持『是法律但不应服从』，富勒坚持『不道德到一定程度即非法律』。在实际的司法裁判中，这两种说法会不会导致不同的判决结果，还是仅仅不同的说理风格？\n3. 当法律体系本身极度不正义时，法官继续任职并以内部观点适用其规则，应当被评价为忠于法律还是助长不义？"}, "en": "The Hart–Fuller Debate", "level": "debate", "tags": "哈特, 富勒, 法律与道德, 内在道德, 恶法", "source": "Wacks, Understanding Jurisprudence, 2.10.2；Hart, Positivism and the Separation of Law and Morals (1958)；Fuller, Positivism and Fidelity to Law—A Reply to Professor Hart (1958)；Fuller, The Morality of Law, ch.2–3", "id": "S3M4K1"}, "S3M4K2": {"title": "哈特与德沃金的争论", "EN": "The Hart–Dworkin Debate", "LEVEL": "debate", "TAGS": "德沃金, 哈特, 规则模式, 法律原则, 自由裁量", "TERMS": "规则模式（Model of Rules）::德沃金对实证主义法律观的概括，认为法律被化约为可由承认规则识别的规则集合；原则（Principle）::具有分量维度的非规则标准，描述权利，要求因正义或公平而被遵守；政策（Policy）::设定有待达成之集体目标的标准，描述目标而非权利；强自由裁量（Strong Discretion）::法官在法律未规定处不受既定标准约束、可依个人判断造权的情形；开放结构（Open Texture）::哈特用来描述规则边缘地带不确定性的概念；语义之刺（Semantic Sting）::德沃金批评实证主义预设法律人共享一套有效性的语义判准，因而无法解释理论性分歧；建构性解释（Constructive Interpretation）::在既契合既有实践又能给出最佳道德辩护的限度内解释法律；法律的整体性（Law as Integrity）::德沃金的核心命题，法律须作为一项连贯的正义事业被理解；连锁小说（Chain Novel）::法官如同接续写作的小说家，须使自己的章节与前人的作品融为一体", "SOURCE": "Wacks, Understanding Jurisprudence, ch.5；Hart, The Concept of Law, Postscript, §§2–6；Dworkin, Taking Rights Seriously；Dworkin, Law’s Empire", "terms": [{"term": "规则模式（Model of Rules）", "def": "德沃金对实证主义法律观的概括，认为法律被化约为可由承认规则识别的规则集合"}, {"term": "原则（Principle）", "def": "具有分量维度的非规则标准，描述权利，要求因正义或公平而被遵守"}, {"term": "政策（Policy）", "def": "设定有待达成之集体目标的标准，描述目标而非权利"}, {"term": "强自由裁量（Strong Discretion）", "def": "法官在法律未规定处不受既定标准约束、可依个人判断造权的情形"}, {"term": "开放结构（Open Texture）", "def": "哈特用来描述规则边缘地带不确定性的概念"}, {"term": "语义之刺（Semantic Sting）", "def": "德沃金批评实证主义预设法律人共享一套有效性的语义判准，因而无法解释理论性分歧"}, {"term": "建构性解释（Constructive Interpretation）", "def": "在既契合既有实践又能给出最佳道德辩护的限度内解释法律"}, {"term": "法律的整体性（Law as Integrity）", "def": "德沃金的核心命题，法律须作为一项连贯的正义事业被理解"}, {"term": "连锁小说（Chain Novel）", "def": "法官如同接续写作的小说家，须使自己的章节与前人的作品融为一体"}], "sections": {"coreQuestion": "如果说哈特与富勒的争论发生在法律的概念边界上，那么哈特与德沃金的争论则深入法律的内部结构。德沃金（Ronald Dworkin）在1960年代末把批判的矛头直指《法律的概念》，称哈特提供的是一幅『规则模式』（model of rules）的图景：法律被理解为一套由承认规则筛选出来的规则集合，规则用尽之处便出现空隙，法官只得行使自由裁量去填补。德沃金认为这幅图景同时做错了两件事——它遗漏了法律原则，也低估了权利的分量。本节要回答：原则与规则究竟有何不同？疑难案件中存在不存在『唯一正确答案』？法官是在发现法律还是在创造法律？哈特在去世前完成的后记中又做了哪些修正与反击？", "definition": "规则在德沃金的描述中具有『全有或全无』（all-or-nothing）的适用方式：一旦有效规则适用于案件，案件就必须按规则指定的方式裁判。原则与之不同，它具有『分量或重要性』（dimension of weight）的维度：原则为裁判提供一个理由，却非结论性理由，须与其他原则相权衡。德沃金进一步区分原则与政策：原则是『应被遵守的标准』，因其体现正义、公平或某种道德要求；政策则是设定集体目标的标准，旨在改善经济、政治或社会状况。简言之，原则描述权利，政策描述目标。强自由裁量是哈特使用的术语，指在法律未予规定的问题上，法官不受既定标准约束，可以自己的判断作出决定。德沃金否认法官在疑难案件中拥有这种强自由裁量，主张他们始终受既有原则的约束。开放结构则是哈特描述规则边缘不确定性的关键概念：规则有清晰的核心地带，也有可争辩的边缘地带。", "history": "德沃金的批判始于一系列1960年代的论文，后结集为《认真对待权利》（Taking Rights Seriously, 1977），并在《法律帝国》（Law’s Empire, 1986）中发展为完整的解释性法理学。他写作的时代背景是英美司法积极主义的扩张：法院在民权、隐私、言论自由等领域不断作出富有争议的判决，传统上『法官只是宣告法律』的神话受到挑战。德沃金关切的核心问题是：如果疑难案件的结果取决于法官个人的价值偏好，那么权利就成了可以被多数利益随时牺牲的脆弱之物。哈特于1996年去世，其在《法律的概念》第三版（1994）中新增的后记，由 Bulloch 与 Raz 编辑，集中回应包括德沃金在内的批评者。Wacks 把这场交锋视为当代法哲学最重要的争论之一，因为它同时触及法的本体论、司法方法与民主正当性三个层面。", "principle": "德沃金的论证从反例开始。在1889年的美国案例 Riggs v Palmer 中，一名孙子为继承遗产而毒杀祖父，遗嘱形式完全有效，继承规则中也找不到排除他的例外。纽约法院却判决杀人者不得继承，所依据的是『任何人不得因自己的错误行为而获利』这一原则。德沃金据此指出：原则平时不被写出来，却在疑难案件中决定结果，因而原则也是法律的一部分。另一个例子是英国上议院1983年审理的 McLoughlin v O’Brian 案，原告在家中得到家人车祸的消息后赶到医院，目睹惨状并遭受精神休克；依既有先例，她不在事故现场且未立即赶到，本不能获赔，上议院仍允许其请求。德沃金把这类案件称为『疑难案件』，主张法官必须诉诸既能契合既有判例、又能为整个制度提供最佳道德辩护的原则。他虚构了一位具有超凡技艺、学识、耐心与洞察力的法官『赫拉克勒斯』（Hercules），让其逐步建构一套能使普通法先例融贯的抽象与具体原则体系。若存在多种一致的重构，赫拉克勒斯会选择最契合共同体制度史的那种理论。这就是建构性解释。德沃金还用『连锁小说』（chain novel）的比喻说明：法官像接续创作的小说家，每一章都须与前人的作品构成一个完整故事，最好的解释就是使整部小说成为单一作者之作的解释。", "viewpoints": "德沃金的核心论断有四项。其一，法律不仅包含规则，也包含原则与政策，因此『法律是初级规则与次级规则的结合』这一公式并不完整。其二，在疑难案件中存在『唯一正确答案』（one right answer）：如同只有八码的鞋才真正合脚，最契合且最能证成既有法律实践的答案只有一个，法官的任务就是把它找出来。其三，他提出『语义之刺』（semantic sting）的批判：实证主义假定法律人共享一套关于法律有效性的语义判准，因而只能解释事实性分歧；但现实中律师往往对制定规则的史实没有争议，却对那些事实是否足以赋予规范以法律效力发生争论，这是理论性分歧，实证主义无法容纳。其四，『法律即整体性』（law as integrity）：法律约束的价值在于在公民之间确立一种平等，使共同体的政治权力获得更坚实的道德正当性，因此权利应被视为『王牌』（trumps），不能被集体目标轻易压倒。哈特的反击集中在后记中：德沃金把他描绘成『语义理论家』与『Plain-fact 实证主义者』是一种误读；他从没有从『法』这个词的含义推出承认规则的存在，他明确区分了概念的意义与概念的适用标准，也明确承认承认规则可以把道德原则纳入有效性判准——这正是后来所谓的『柔性实证主义』（soft positivism）。", "comparison": "两人最深的差异体现在对法律不确定性的诊断上。哈特所称规则的开放结构使法律在边缘处出现真正的空缺，法院在个案中必须行使有限的、『间隙性』（interstitial）的造法权；这种做法类似立法，但受既有原则、类比推理与程序约束，且仅针对具体案件。德沃金则认为，所谓空缺只是实证主义图景的缺陷，法律作为一个『无间隙』的整体，始终包含可供发现的隐含原则，法官无需跨出法律之外。对比两者的方法论也很有启发：哈特自述从事的是一般性的、描述性的法理学，旨在厘清法律这种社会制度的结构；德沃金则主张法理学是法律实践的一部分，是『裁判的一般部分』，理论工作本身带有评价性。哈特在后记中指出，德沃金后来已收敛其『帝国主义式』的主张，承认描述性法理学在追问『意义问题』时自有位置。这场方法论之争提醒我们：法理学家的自我定位，会直接塑造他们给出的答案。", "debates": "围绕自由裁量，德沃金对哈特提出三层批评，哈特逐一回应。第一层是描述性批评：法官与律师在实践中从不说『法官在造法』，他们总是把裁判包装成对既有权利的执行；哈特回答，法庭上的仪式性语言不足以描述司法实践，霍姆斯、卡多佐、麦克米伦、里德等大法官都曾坦承存在法律未完全规制、可在两种情况间择一的案件。第二层是民主批评：未经选举的法官造法不民主；哈特回应，把少量争议交由受约束的法官处理，是避免把问题转交立法机关的合理代价，且议会保留修改或废止的权力，与向行政机关授权并无本质差别。第三层是溯及既往的批评：法官造法相当于事后改变规则，不公平；哈特反驳说，这一指责只在法律已有明确状态、当事人可据以形成预期时才有力量，而疑难案件恰恰是法律尚未明确之处。德沃金的反命题是：若法律原则能给出唯一正确答案，法官就始终在适用法律，自由裁量的空间被压缩到最小。哈特对『唯一正确答案』的怀疑在于：不同原则之间的权重并无法律事先指定的位阶，法官在选择支持哪一种类比时，仍须诉诸个人的价值判断。Wacks 指出，赫拉克勒斯与『疑难案件』都只是理论模型，前者并非现实中存在的法官，后者是展示司法角色的范式案例。", "case": "Riggs v Palmer（1889）是德沃金最重要的例证。案件事实极其简单：帕尔默为早日取得祖父留下的遗产而将其毒杀，遗嘱符合法定形式，继承规则亦无明文排除杀人者。争议焦点是：形式上有效的遗嘱能否因继承人的谋杀行为而失效。纽约法院判决杀人者不得继承，理由是任何人都不得从自己的错误行为中获益。德沃金据此论证，法院并未『创造』新法，而是适用了一项早已隐含在法律实践中的原则；实证主义若坚持只有规则才是法律，就必须说法院在此造法并溯及既往地适用，而这恰恰扭曲了法官的实际推理。哈特在《法律的概念》中曾回应：承认原则为法律并不困难，许多普通法原则正是通过被法院反复援引而获得『谱系』（pedigree）；他在后记中进一步以美国宪法第一修正案和 Donoghue v Stevenson 案中的『邻人原则』为例，说明原则同样可以由承认规则识别。", "caseAnalysis": "本案的事实层面几乎不存在争议，争夺在于对裁判性质的描述。依德沃金的解读，争议焦点是法律是否包含非规则标准；法律依据是『不得因自身过错获利』这一法律原则；裁判理由体现为原则对形式规则的压制；其理论意义在于，它把『恶人能否利用法律形式』的问题转化为『法律是否自始就包含道德原则』的问题。哈特的反解读同样有力：该原则之所以能作为法律理由发挥作用，正因为它在既往判决中被反复援引，即通过一种可被识别的社会来源取得法律身份；这恰好说明承认规则仍然必要，甚至更为必要——因为建构性解释必须从『前解释的既定法律』出发，而识别既定法律正是承认规则的工作。Wacks 提醒读者注意，德沃金与哈特在是否承认原则为法律这一点上的距离，远比初看起来要小；真正的鸿沟在于方法论：德沃金把识别与证成合二为一，哈特坚持描述性研究可以在不对道德立场作承诺的情况下进行。这一分歧在后续 Fallon、Coleman、Raz 等人的论著中持续发酵。", "summary": "哈特与德沃金的争论把法理学从『法律是什么』推进到『法律如何被识别与适用』。德沃金以规则与原则的区分击破了规则模式，以赫拉克勒斯、连锁小说与整体性法重构了疑难案件的裁判图景，并以语义之刺质疑实证主义解释理论性分歧的能力。哈特在后记中承认柔性实证主义、区分概念与适用标准、说明原则可由谱系识别，同时坚持开放结构导致法律在边缘处真正不完整，法官的间隙性造法不可避免。争论的遗产是双重的：此后任何实证主义都必须回答原则难题，任何解释性理论也必须回答确定性与民主正当性的追问。", "furtherThinking": "1. 如果不同法官对同一疑难案件各自建构出一套融贯的原则体系，且都能契合先例，德沃金凭什么断言其中只有一套给出了『唯一正确答案』？\n2. 承认规则若把道德原则纳入有效性判准，是否仍有能力提供哈特所珍视的确定性？这种『柔性实证主义』会不会滑向德沃金的解释性理论？\n3. 在算法辅助裁判的场景中，若由系统给出『最契合先例』的判决建议，赫拉克勒斯的虚构还能为司法者的道德责任留下位置吗？"}, "en": "The Hart–Dworkin Debate", "level": "debate", "tags": "德沃金, 哈特, 规则模式, 法律原则, 自由裁量", "source": "Wacks, Understanding Jurisprudence, ch.5；Hart, The Concept of Law, Postscript, §§2–6；Dworkin, Taking Rights Seriously；Dworkin, Law’s Empire", "id": "S3M4K2"}, "S3M4K3": {"title": "法律实证主义与自然法的冲突", "EN": "The Conflict Between Legal Positivism and Natural Law", "LEVEL": "debate", "TAGS": "法律实证主义, 自然法, 分离命题, 拉德布鲁赫, 新自然法", "TERMS": "自然法理论（Natural Law Theory）::主张法律与道德存在必然联系、严重不义的规则不具备完整法律资格的立场；分离命题（Separation Thesis）::法律的存在取决于社会来源而非道德价值的实证主义基本主张；社会来源命题（Sources Thesis）::拉兹提出的强实证主义命题，认为法律的存在与内容最终由可识别的社会事实决定；包容实证主义（Inclusive Positivism）::主张承认规则可以把道德标准纳入效力判准的柔性立场，亦称柔性实证主义；排除实证主义（Exclusive Positivism）::主张法律效力判准只能来自社会来源的立场；最低限度自然法（Minimum Content of Natural Law）::哈特承认法律基于人类生存需要而必须包含的少量自然法要素；拉德布鲁赫公式（Radbruch Formula）::极端不正义的法律应让位于正义的战后德国法命题", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, 2.10.1, 4.5；Hart, The Concept of Law, ch.9, Postscript §5；Finnis, Natural Law and Natural Rights；Raz, The Concept of a Legal System", "terms": [{"term": "自然法理论（Natural Law Theory）", "def": "主张法律与道德存在必然联系、严重不义的规则不具备完整法律资格的立场"}, {"term": "分离命题（Separation Thesis）", "def": "法律的存在取决于社会来源而非道德价值的实证主义基本主张"}, {"term": "社会来源命题（Sources Thesis）", "def": "拉兹提出的强实证主义命题，认为法律的存在与内容最终由可识别的社会事实决定"}, {"term": "包容实证主义（Inclusive Positivism）", "def": "主张承认规则可以把道德标准纳入效力判准的柔性立场，亦称柔性实证主义"}, {"term": "排除实证主义（Exclusive Positivism）", "def": "主张法律效力判准只能来自社会来源的立场"}, {"term": "最低限度自然法（Minimum Content of Natural Law）", "def": "哈特承认法律基于人类生存需要而必须包含的少量自然法要素"}, {"term": "拉德布鲁赫公式（Radbruch Formula）", "def": "极端不正义的法律应让位于正义的战后德国法命题"}], "sections": {"coreQuestion": "法律实证主义与自然法之争，常被描述为法理学中的头号对抗：一方说法律与道德可以分离，另一方说两者必然相连。然而 Wacks 提醒我们，这场对抗也许部分源于误解——双方有时像是在『不同的层面上打影子拳』（shadow-boxing on different planes）。要判断两家是否真的针锋相对，必须先厘清三件事：他们各自所说的『法律』指向什么层面；『必然联系』究竟是概念命题还是价值主张；以及两派在方法论与社会理想上是否其实共享某些前提。本节将通过拉德布鲁赫公式、哈特的最低限度自然法与芬尼斯的新自然法，把这场抽象冲突还原为若干可辨认的具体命题。", "definition": "自然法理论家族内部差异极大。古典版本以阿奎那（Thomas Aquinas）为代表，把法律理解为『由关心共同体者颁布、以共同善为目标的理性命令』，并以『恶法非法』（lex iniusta non est lex）表述道德与效力的关联。当代新自然法的代表芬尼斯（John Finnis）在《自然法与自然权利》中延续柏拉图、亚里士多德与阿奎那的问题意识，以分析法学的方法重构这一传统，提出七种『人类繁荣的基本形式』与九项『实践合理性的基本要求』。富勒的版本则另辟蹊径，把必然联系限定在程序性的内在道德上。法律实证主义这边的光谱同样丰富：拉兹（Joseph Raz）主张排除实证主义，坚持只有社会来源才可提供合法性判准；科尔曼（Jules Coleman）主张包容实证主义，认为只要承认规则如此规定，道德就可以成为法律效力的条件。哈特在《法律的概念》后记中明确把自己归入后者，同时承认法律必须包含『最低限度的自然法』。", "history": "自然法的现代复兴与二十世纪的灾难直接相关。纽伦堡审判（1945—1946）确立了这样一个原则：某些行为构成『反人类罪』（crimes against humanity），即便它们并未违反当时的实证法条文；审判的法官虽未明确诉诸自然法理论，但其裁判承认了法律并非判定是非的唯一尺度。德国法学家拉德布鲁赫（Gustav Radbruch）在战前本是实证主义者，曾任魏玛共和国司法部长并参与起草《基本法》；1947年他公开谴责实证主义无力阻止纳粹之恶，主张法律理念只能是正义的实现，而正义如同美德、真理与美，是绝对价值。1948年《世界人权宣言》把权利表述为『共同的成就标准』而非可直接推翻普通法的高级法，反映出一种审慎的自然法现代化形态。同期，斯塔姆勒（Rudolf Stammler）提出『内容可变的自然法』，德尔·韦基奥（Giorgio Del Vecchio）则以个体自主为正义核心，把违背该目的的国家称为『犯罪的国家』。", "principle": "理解这场冲突，可以沿三条线索拆解。第一条是效力判准的线索：实证主义问『一条规范凭什么算法律』，回答诉诸制定、判例、习惯等社会事实；自然法问『一条规范凭什么有资格作为法律约束人』，回答诉诸理性、共同善或正义。第二条是方法论的线索：芬尼斯明确说，自然法理论的首要目的未必是为描述性社会科学提供概念框架，而是帮助行动者——法官、政治家、公民——进行实践反思。哈特则坚持一般描述性法理学的独立价值，认为它可以在不承诺任何道德理论的前提下说明法律制度的结构。第三条是最低限度的线索：哈特依据若干关于人类处境的经验事实——人的脆弱性、大体平等、有限的利他主义、资源有限、理解与意志力有限——推论出任何持续存在的法律制度都必须保护人身、财产与承诺，否则制度无从维持。这使法律『自动地与某种善保持一致』，但这种联系是事实性、条件性的，仍非概念上的必然。", "viewpoints": "冲突的正面命题可以压缩为一句：法律效力是否可能在概念上依赖于道德价值。自然法给出肯定回答，实证主义给出否定或条件性回答。但 Wacks 指出，两家其实共享四点重要基础：其一，芬斯本人承认其方法受分析法学传统滋养；其二，双方都试图考察并证成法律的权威；其三，双方都否认对不正义法律存在『初步的服从义务』；其四，双方都重视法治理想。分歧因此远比通俗漫画来得细。实证主义者的典型论证是：把道德纳入效力判准，会使公民难以事先确知何时会遭到强制，并迫使法理学承诺一套有争议的元伦理学立场。自然法一方的典型论证是：若效力完全由来源决定，公民便无从要求法律说明自身为何有权威；回答这个问题必然要进入道德论证。哈特的折中是把道德纳入承认规则的可能性留给具体制度去决定，同时在理论上对道德判断的『客观地位』保持开放。", "comparison": "这场冲突与另两场争论形成有趣的对照。哈特—富勒之争聚焦法律的边界：极端邪恶的规则还算不算法律；哈特—德沃金之争聚焦法律的内容：法律是否只由规则构成。本节的冲突则聚焦法律理论的元层面：描述性与评价性工作应如何分工。富勒的程序自然法与芬斯的实质新自然法也应区分：前者只要求形式上的八项品质，后者则主张从人类繁荣的基本形式推出实质性的实践要求。实证主义内部的分歧同样值得注意：拉兹认为一旦允许道德进入效力判准，法律的指引功能就会受损，因此坚持排他立场；科尔曼与哈特则认为，只要承认规则本身被官员实践所接受，纳入道德判准仍是一种社会事实。Wacks 用『影子拳』提醒读者，很多看似针锋相对的表述其实发生了层面错位：一方谈的是识别法律的标准，另一方谈的是服从法律的道德理由。", "debates": "芬斯对科尔曼与莱特（Brian Leiter）的回应提出了一连串诘难，以南非种族隔离制度下的律师为思想实验：当一位明知法律不义的公民询问『为什么承认规则对我具有权威』时，实证主义者能给出什么理由？芬斯设想了四种回答——出于自利而配合官方、相信官员在追随道德、接受承认规则提供了正确评价标准、以及避免无序与维持自由稳定所需的官员协调。前三种被逐一排除，第四种虽可提供某种理由，却已经承认了秩序、和平与正义这些实质价值，因而事实上滑向自然法。芬斯由此断言，实证主义只能记录态度与趋同行为，无法说明法律对良心的权威。实证主义一方则回应：法律体系的存在本来就依赖官员的接受实践，指出这一点正是在解释合法性概念如何运作，描述行为规律只是其中一环；哈特更强调，要求法理学对道德判断的客观地位表态，等于把一种有争议的哲学立场强加给描述性研究。Wacks 总结说，两派是否真正交锋，取决于我们是否把『识别法律』与『证成法律』视为同一个问题。", "case": "纽伦堡审判提供了检验两派解释力的重要素材。事实是：二战结束后，同盟国在国际军事法庭审判纳粹主要战犯，指控包括『反人类罪』在内的罪名；争议焦点在于，某些行为在当时德国实证法中并无明确禁止条款，甚至可能得到形式有效的法律授权，战犯能否因此免责。法庭的裁判逻辑是：某些行为严重违背文明社会的基本准则，国家法律不能成为免除个人责任的充分理由。Wacks 强调，法官并未明确以自然法理论命名其立场，但这一裁判确立了一项广为接受的原则：法律未必是判定对错的唯一决定因素。这里同样可以看到《世界人权宣言》1948年采取的表述策略——把权利称为『共同的成就标准』，既承认超越实证法的道德尺度，又避免把自然法直接写成可以推翻一切制定法的高级法。", "caseAnalysis": "就纽伦堡审判而言，事实层面是战犯依当时有效法律行事，规范层面是国际社会认定存在不可被国家法律取消的责任。争议焦点因此可以重述为：法律效力是否穷尽了正当性的来源。实证主义的解释是：纳粹法律在识别标准上仍是有效法律，战犯的责任来自另一套被接受的国际法规范，两个判断可以在概念上分开；这一解释的优点是保持了概念清晰，同时说明了国际法秩序的独立性。自然法的解释是：严重违背基本正义的规范自始缺少法律资格，个人本来就无权援引它；这一解释更直接地表达了道德谴责，却需要说明谁来决定何为『严重不义』。理论意义在于，两种解释都否认『服从法律即可免责』，差别只在于把道德限制放在概念内部还是外部。这个差别在平时看似学院化，在制度崩溃的时刻却会影响法官与公民如何理解自身责任。", "summary": "法律实证主义与自然法的冲突，集中体现在法律效力是否依赖道德这一命题上。实证主义以社会来源识别法律，区分效力与正当性；自然法以理性、正义或人类繁荣为法律设定门槛。然而两派共享分析法学的方法、对法律权威的关切、否认对恶法的初步服从义务，并共同重视法治，因此冲突常被夸大为漫画式的对立。哈特的柔性实证主义与最低限度自然法、富勒的程序自然法、芬斯的实质新自然法，构成了介于两极之间的丰富地带。判断两家是否真正交锋，关键在于区分识别法律的标准与服从法律的理由；只要这一区分被澄清，许多表面矛盾便转化为可讨论的层面差异。", "furtherThinking": "1. 若承认规则明确规定『任何违反宪法平等条款的规则均无效』，这究竟是实证主义容纳了道德，还是自然法借用了实证主义的语言？\n2. 哈特的『最低限度自然法』以人类生存需要为根据，这种事实性推论能否真正阻挡一种高效而残酷的极权法律秩序？\n3. 两家都否认对恶法有初步的服从义务，那么在这个共同前提下，他们的分歧对普通公民的实际行动还有多少差别？"}, "en": "The Conflict Between Legal Positivism and Natural Law", "level": "debate", "tags": "法律实证主义, 自然法, 分离命题, 拉德布鲁赫, 新自然法", "source": "Wacks, Understanding Jurisprudence, ch.2, 2.10.1, 4.5；Hart, The Concept of Law, ch.9, Postscript §5；Finnis, Natural Law and Natural Rights；Raz, The Concept of a Legal System", "id": "S3M4K3"}, "S3M4K4": {"title": "法律现实主义的挑战", "EN": "The Challenge of Legal Realism", "LEVEL": "core", "TAGS": "法律现实主义, 霍姆斯, 规则怀疑论, 行动中的法, 司法行为", "TERMS": "法律现实主义（Legal Realism）::强调法律的实际运作而非概念体系、关注法院实际行为的理论运动；行动中的法（Law in Action）::现实主义者主张研究的对象，与实际运作相对的书本上的法；规则怀疑论（Rule Skepticism）::怀疑规则对法官裁判具有决定性约束力的立场；形式主义（Formalism）::把法律推理类比为三段论演绎的思维方式；坏人理论（Bad Man Theory）::霍姆斯提出的视角，从预测法律后果的利害关系人出发理解法律；事实怀疑论（Fact Skepticism）::弗兰克主张的不确定性来自案件事实认定而非规则的立场；功能主义（Functionalism）::卢埃林强调法律的社会功能与实际行动的分析路径", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6；Holmes, The Path of the Law (1897)；Llewellyn, Some Realism about Realism (1931)；Frank, Law and the Modern Mind (1930)；Ross, On Law and Justice", "terms": [{"term": "法律现实主义（Legal Realism）", "def": "强调法律的实际运作而非概念体系、关注法院实际行为的理论运动"}, {"term": "行动中的法（Law in Action）", "def": "现实主义者主张研究的对象，与实际运作相对的书本上的法"}, {"term": "规则怀疑论（Rule Skepticism）", "def": "怀疑规则对法官裁判具有决定性约束力的立场"}, {"term": "形式主义（Formalism）", "def": "把法律推理类比为三段论演绎的思维方式"}, {"term": "坏人理论（Bad Man Theory）", "def": "霍姆斯提出的视角，从预测法律后果的利害关系人出发理解法律"}, {"term": "事实怀疑论（Fact Skepticism）", "def": "弗兰克主张的不确定性来自案件事实认定而非规则的立场"}, {"term": "功能主义（Functionalism）", "def": "卢埃林强调法律的社会功能与实际行动的分析路径"}], "sections": {"coreQuestion": "如果教科书上的法律规则完整而清晰，为什么同样的案件在不同法院会得到不同判决？为什么当事人愿意花巨大成本诉讼，而不是翻开法条直接得出结论？法律现实主义（Legal Realism）正是在这种疑问中诞生的。它把法理学的目光从『书本上的法』转向『行动中的法』（law in action），主张真正塑造判决的是法官对事实、政策与社会后果的判断。本节要处理三个问题：现实主义究竟『现实』在哪里；它对形式主义的批评是否与实证主义相容；以及这种强调法官实际行为的进路，会不会把法律溶解为法官的个人偏好。", "definition": "法律现实主义是二十世纪上半叶在美国兴起、同时在斯堪的纳维亚形成另一分支的理论运动。Wacks 指出，两支虽共享经验主义与实用主义气质、共同拒斥『正义』这类绝对价值，差别却十分显著：美国现实主义者大体是实用主义者与行为主义者，聚焦法院运作，属于『规则怀疑论者』；斯堪的纳维亚现实主义者则发动对法律形而上学基础的哲学攻击，属于『形而上学怀疑论者』。美国现实主义的核心主张，按莱特（Brian Leiter）的概括是：法官主要对案件事实这一刺激作出反应，裁判建立在法官对个案公平与否的判断上，法律规则与理由在上诉审中作用甚微；不少现实主义者提出这一主张，是为了推动规则变得更加具体、更贴近事实。形式主义则是他们的批判对象：它把法律推理比作三段论——大前提是法律规则，小前提是案件事实，结论是判决。现实主义认为，这种图式低估了法官造法的空间。", "history": "现实主义是对世纪之交美国形式主义法学的反弹。霍姆斯（Oliver Wendell Holmes Jr.）在1897年对法学院学生发表的名演讲『法律之路』（The Path of the Law），为运动提供了思想源头。他把普通法比作可辨识的主权者或准主权者的清晰声音，『天空中沉思的幽灵』式的神秘化与他格格不入；研究法律应当分清楚法律是什么与法律应当是什么。1920至1930年代，卢埃林（Karl Llewellyn）、弗兰克（Jerome Frank）等人把这种思路系统化，与当时美国社会科学的兴起同步。Leiter 把法官回应事实的核心主张称为现实主义的『核心命题』。与此同时，瑞典的哈格斯特罗姆（Axel Hägerström）、罗斯（Alf Ross）、奥利韦克罗纳（Karl Olivecrona）与伦德斯特德特（A. V. Lundstedt）从彻底的经验主义出发，主张一切形而上学皆为幻象，只有经验认知才有效。Wacks 称美国现实主义是现代法理学的一大悖论：影响极为深远，却始终含混、未定形。", "principle": "现实主义的内部逻辑可以分三步理解。第一步是视角转换：理解法律的最佳方式，是从『坏人』（bad man）的角度出发。霍姆斯说，想知道法律到底是什么，就得像只关心可预测的物质后果的坏人那样看它；他所说的法律，就是对法院实际上会做什么的预言。这一视角刻意悬置道德评价，与实证主义的描述性抱负相通。第二步是对规则的重新定位：现实主义者并未完全否认规则能约束法院，但主张自由裁量远比通常承认的频繁。在他们看来，法官受政治与道德直觉影响的程度被形式主义严重低估。第三步是经验化的方法论：现实主义拒绝把逻辑当作认识法律的唯一通道，转而引入社会学与心理学。卢埃林有句名言：现实主义是『一项技术，而非一种哲学』。弗兰克则把怀疑论推进到事实层面：多数现实主义者忙于研究上诉法院，患上了『上诉法院炎』，却忽略了审判中事实认定的不确定性——法官与陪审员的偏见会左右案件的结局。", "viewpoints": "『三巨头』各有侧重。霍姆斯强调预测与经验，认为『法律的生命不在逻辑，而在经验』；他相信真正的法律科学应当『从内部确立其前提，依据精确衡量过的社会需求，而非传统』，因而历史让他更感兴趣的是经济学。卢埃林的贡献是功能主义，贯穿《荆棘丛》《晓切之道》与《普通法传统》等著作：法律被理解为服务于特定社会职能的制度装置，规则的意义在于它实际做了什么。卢埃林在《现实主义再议》中列出现实主义者的九项共同出发点。弗兰克是最激进的一位，在《法律与现代心灵》（1930）中区分规则怀疑论者与事实怀疑论者，把自己归入后者：既然即便存在可适用规则，也可能得出两种相反结论，以规则确保确定性的想法便站不住脚。斯堪的纳维亚一边，哈格斯特罗姆甚至否认法律规则能以非自然的方式『存在』，认为权利与义务概念是原始法巫术思维的遗留；罗斯则用象棋比喻说明规范的效力来自社会事实性的行为模式，而诉诸『正义』不过像拍桌子，是把自己的要求提升为绝对命令。", "comparison": "现实主义与法律实证主义的关系颇为微妙。一方面，现实主义者与实证主义者都主张对法律作科学分析，都坚持考察法律『实际上是什么』；正因如此，他们常被归入广义的实证主义阵营。另一方面，现实主义对实证主义所珍视的形式确定性抱有敌意，认为它把法律描绘成无生命的规则体系。与德沃金的理论对照更能显示其特征：德沃金以赫拉克勒斯式建构性解释反驳规则的空缺与法官的强自由裁量，现实主义则倾向于把裁判的不确定性视为常态。与批判法律研究（CLS）相比，现实主义较早提出法律材料不足以逻辑地导出唯一结果，但 CLS 把这一洞见推进到意识形态批判的方向。Wacks 还记录了外界对现实主义的指责：1930年代有人批评它虚无主义，甚至称其反民主、极权；Duxbury 认为这类攻击依据的是一幅与现实主义者的实际关怀相去甚远的漫画。", "debates": "现实主义内部最重要的分歧，是规则怀疑与事实怀疑之争。卢埃林式的规则怀疑论者关注上诉法院，主张既有的法律材料难以逻辑地产生唯一结果，判决中的政策选择不可消除。弗兰克则认为这种关注放错了地方：真正的不可预测性来自初审阶段的事实认定，法官和陪审员对证人、性别、外貌、谈吐的微妙反应会左右事实结论，规则再清晰也无济于事。他反问，如果规则真能带来确定性，人们何必兴讼？另一场争论发生在外界与现实主义之间：批评者认为，否认真定性就是否定法治。现实主义者的典型回应是，他们并未否认法官受规则约束，只是要求把这种约束的程度交给经验研究去检验，而非由概念分析先验裁定。哈特后来在开放结构理论中吸收了这一洞见：规则有确定的核心，也有无法事先划定的边缘，司法裁量在边缘处不可避免。这在某种意义上把现实主义的不确定性直觉纳入了实证主义框架。", "case": "Lochner v New York（1905）是美国最高法院的经典判例，也是霍姆斯异议的著名场域。案件争议是纽约州有关面包师劳动时间的立法是否违反宪法第十四修正案的正当程序条款。多数意见以『契约自由』为由宣告该法违宪；霍姆斯大法官提出异议，指责多数意见把某种经济理论塞进宪法，并写下了那句被广泛引用的话——宪法并不体现某一种特定的经济理论。Wacks 指出，霍姆斯的实用主义与进步倾向正凝结在包括本案在内的一系列异议中。这个案子常被自由派法学作为司法能动与形式主义经济影响的教材，也提示现实主义的核心关切：当法官宣称自己在适用宪法原则时，实际起作用的可能是特定的社会经济学说。", "caseAnalysis": "就 Lochner 案而言，事实是州立法机关试图限制面包师工作时间，法律争点是该限制是否侵犯了宪法所保护的契约自由。形式主义的裁判思路把宪法原则当作大前提，把案件事实当作小前提，再以三段论导出违宪结论。霍姆斯的异议则揭示出一个被掩盖的判断：所谓『契约自由』本身是一种关于社会与经济秩序的实质选择，把它当成自明的法律前提，等于把政策偏好伪装成逻辑演绎。本案的理论意义在于三点：其一，它具体演示了现实主义者对形式主义的指控——演绎外观之下藏着价值选择；其二，它说明现实主义并不必然导向道德虚无，霍姆斯的异议本身带有明确的价值立场；其三，它提示后来的法理学必须回答：若法官的判断不可避免，如何为司法权提供正当性说明。德沃金的整体性理论与哈特的开放结构理论，都在不同程度上回应了这一挑战。", "summary": "法律现实主义把法理学的关注点从抽象概念转向法律的实际运作。霍姆斯的坏人理论与经验命题、卢埃林的功能主义、弗兰克的事实怀疑论，以及斯堪的纳维亚学者的形而上学怀疑论，共同构成了对形式主义的持续挑战。现实主义与实证主义共享经验主义与描述性抱负，却在规则的确定性与法官的造法空间上分歧明显。外界指责其虚无主义或反民主，Wacks 认为这类批评多有漫画化成分。现实主义的持久贡献，在于迫使后来的理论正面处理司法判断中的政策与事实因素：哈特以开放结构与有限裁量回应，德沃金以建构性解释回应，两种回应都承认现实主义提出的问题无法回避。", "furtherThinking": "1. 如果法官的判决确实受事实与政策直觉影响，现实主义应当如何区分『描述法官实际做的事』与『证成法官应当做的事』？\n2. 弗兰克的事实怀疑论把不确定性定位在事实认定阶段，这对规则怀疑论者构成何种挑战？\n3. 在裁判文书公开与大数据分析的条件下，『对法院将做什么的预测』是否会使霍姆斯的坏人视角变得更可行，也更危险？"}, "en": "The Challenge of Legal Realism", "level": "core", "tags": "法律现实主义, 霍姆斯, 规则怀疑论, 行动中的法, 司法行为", "source": "Wacks, Understanding Jurisprudence, ch.6；Holmes, The Path of the Law (1897)；Llewellyn, Some Realism about Realism (1931)；Frank, Law and the Modern Mind (1930)；Ross, On Law and Justice", "id": "S3M4K4"}, "S3M4K5": {"title": "法律与政治权力", "EN": "Law and Political Power", "LEVEL": "core", "TAGS": "法律与权力, 韦伯, 合法支配, 法律自主性, 批判法理论", "TERMS": "合法化（Legitimation）::政治统治将其主张转化为可被承认的正当权威的过程；支配（Domination）::韦伯社会学中权力被稳定组织并被认为正当的状态；法理型支配（Legal-rational Domination）::以形式合理、普遍适用的法律规则为正当性基础的统治形态；形式合理性（Formal Rationality）::法律体系在内部自足、逻辑一致、可计算方面达到的理性化程度；实质合理性（Substantive Rationality）::法律以特定的伦理、宗教或政治价值为目标取向的理性化形态；相对自主性（Relative Autonomy）::韦伯关于法律受经济影响却不为经济单方面决定的命题；批判法理论（Critical Legal Theory）::质疑法律自主与中立、强调法律表达政治经济权力的理论取向", "SOURCE": "Wacks, Understanding Jurisprudence, ch.1, ch.7, 7.5；Hart, The Concept of Law, Introduction by Leslie Green；Ross, On Law and Justice", "terms": [{"term": "合法化（Legitimation）", "def": "政治统治将其主张转化为可被承认的正当权威的过程"}, {"term": "支配（Domination）", "def": "韦伯社会学中权力被稳定组织并被认为正当的状态"}, {"term": "法理型支配（Legal-rational Domination）", "def": "以形式合理、普遍适用的法律规则为正当性基础的统治形态"}, {"term": "形式合理性（Formal Rationality）", "def": "法律体系在内部自足、逻辑一致、可计算方面达到的理性化程度"}, {"term": "实质合理性（Substantive Rationality）", "def": "法律以特定的伦理、宗教或政治价值为目标取向的理性化形态"}, {"term": "相对自主性（Relative Autonomy）", "def": "韦伯关于法律受经济影响却不为经济单方面决定的命题"}, {"term": "批判法理论（Critical Legal Theory）", "def": "质疑法律自主与中立、强调法律表达政治经济权力的理论取向"}], "sections": {"coreQuestion": "法律常常以中立、客观、超越党派的姿态出现：法庭高悬天平，法官身着黑袍，判决以『依法』之名宣告。然而法理学反复追问：这种中立形象本身是否就是权力的一种运作方式？当制度化的法律使统治变得可计算、可预测，它究竟是在约束权力，还是在为权力提供更有效的组织工具？本节从三个层面处理这一问题：法律作为社会建构如何重新分配权力；韦伯如何解释法律理性化与合法支配的关系；批判法理论为何主张法律与政治不可分离。", "definition": "合法化指政治权力把单纯的支配事实转化为被认为正当的权威的过程。韦伯（Max Weber）区分三种合法支配：传统型支配诉诸悠久习俗，卡里斯马型支配诉诸领袖的个人感召，法理型支配则诉诸一套形式合理、普遍适用的规则。在法理型支配下，服从的对象是法律秩序本身，统治者与被统治者之间的关系被非人格化。形式合理性与实质合理性是韦伯分析法律思想的两条轴线：前者关注体系是否内部自足、规则是否逻辑一致且可计算，后者关注法律是否服务于特定的伦理或政治目标。二者交叉形成四种法律思想类型：形式合理、形式非理性、实质合理、实质非理性。相对自主性则是韦伯关于法律与经济关系的命题：法律受经济条件影响，却并非由经济因素单方面决定。批判法理论则进一步主张，法律远非自足的规则体系，它不确定、不融贯，并且表达着特定的政治与经济权力。", "history": "韦伯的法社会学源于一个宏大的历史问题：为什么资本主义首先在西方兴起？他的回答把『理性的法律秩序』列为关键条件。近代欧洲的民族国家、法典化运动与职业法官阶层，使法律从习惯与神谕式的裁判方式，转向以抽象规则为基础的可计算体系。与此同时，法律人的专业化也带来一个新的问题：当法律成为一个由专家垄断的知识门类，普通公民与法律之间的关系会发生什么变化？二十世纪的现实主义者与批判法理论从各自角度给出回答。霍姆斯把普通法描述为可辨识的主权者的声音，拆掉了法律『悬浮于天空』的神秘形象；批判法理论则质疑法理学为法律赋予的『虚假合法性』，指出所谓自主的法学学科掩盖了法律与政治的纠缠。Wacks 把后者归入对法理学基础的激进追问。", "principle": "理解法律与权力的关系，可以从三个递进的判断入手。第一个判断来自哈特《法律的概念》导论作者莱斯利·格林（Leslie Green）：法律是人为的社会建构，初级规则与次级规则的结合带来明确性、可变性与效率，代价则是集中的组织权力可能被用来压迫那些其支持可有可无的人。传统习惯只能在缓慢演化中被改变，而制度化使规则得以被公开确认并迅速修改；这种『规范性劳动分工』既是收益也是风险。格林还指出，典型法律秩序所依赖的是狭窄的官员共识，广泛的社会共识并非其基础；普通民众所被要求的，往往仅是对强制性规范的默许。第二个判断来自韦伯：政治支配从理性制定的法律中获得正当性，法律规则划定权力的范围并为其提供合法性；在法理型支配下，理解政治合法性并不需要评价法律的内容，法律以特定形式存在本身就提供了意识形态基础。第三个判断来自批判法理论：既然法律其内容与形式都携带着权力关系，法学若把自己描绘成中立的注释学，便分担了再生产这种关系的功能。", "viewpoints": "各家对权力问题的切入各不相同。法律实证主义倾向于描述权力如何被组织为制度：承认规则的存在依赖官员的共同接受，这使法律效力最终落脚于一种社会事实，而非道德共识。自然法理论要求在权力之上设置道德门槛，主张严重不义的法律缺少完整法律资格。法律现实主义把注意力转向法庭，揭示法官在事实认定与政策选择上的实际裁量。韦伯社会学提供了另一套坐标：法理型支配的合法性来自形式程序，来自『法律存在本身』，法律体系的形式合理性越高，越能为现代国家提供稳定而可计算的统治工具。批判法理论则直指要害：法律的不确定性、内在矛盾与意识形态功能，说明法律根本无法保持中立。Wacks 指出，这些理论并非简单的互相否定；它们回答的是不同层面的问题——有的分析制度如何运作，有的追问这种运作服务于何种利益。", "comparison": "韦伯与马克思主义传统在法律与经济的关系上存在经典分歧。粗略的马克思主义叙事把法律视为统治阶级意志的直接表达；韦伯则强调法律具有『相对自主性』，经济因素对法律的影响是间接的，法律结构的发展绝非由经济因素单方面决定。这一差异影响深远：若法律完全由经济基础决定，法学研究便还原为阶级分析；若法律享有相对自主性，法律人的专业实践、概念体系与制度惯性便具有独立的解释力。韦伯与哈特之间也有可比之处：两人都强调现代法律秩序以官员的接受或职业共同体的实践为基础，哈特的承认规则与韦伯的法理型支配都把合法性锚定在『被接受』这一社会事实上。差别在于哈特关注概念的结构，韦伯关注支配的历史形态。批判法理论对两者都持怀疑态度：它认为形式中立的描述本身已经是政治选择。", "debates": "法律是否具有自主性，是本节的核心争论。批判法理论认为，法学把法律描绘成独立自主的学科，恰恰遮蔽了法律与政治的不可分离；法律远非确定、融贯的规则整体，它充满矛盾，其裁判结果往往反映政治经济权力。支持法律自主性的一方则给出三点回应。其一，法律的相对独立性使权力受到程序约束，统治者也须按照自己公布的规则行事，这本身是一种限制。其二，若法律完全还原为权力，就无法解释人们为何会依据法律批判权力、以及法学家为何能就规则含义进行有规则的争论。其三，法律的专业化既可能造成知识垄断，也可能为普通人提供可诉诸的确定性标准。韦伯的立场恰居其间：他强调形式合理性使统治可计算，同时承认现代法律趋向实质理性化的压力。Wacks 提醒读者，批判理论的洞见与实务关切之间距离很大，把『法律即政治』直接等同于『法律毫无约束』，是过分简单的推论。", "case": "纽伦堡审判之后的『法官审判』（Justice Trial）提供了法律与权力关系的尖锐素材。据 Wacks 记载，第三帝国的部分法官战后确实在纽伦堡受到追诉。电影《纽伦堡的审判》中由伯特·兰卡斯特扮演的德国法官恩斯特·扬宁，其原型大致对应曾任司法部官员的弗朗茨·施莱格尔贝格尔。他在辩护中声称自己只是服从希特勒这位『最高法官』的命令，而且并非心甘情愿；他强调自己与犹太人并无敌意，其私人医生就是犹太人；他还说自己反对把『半犹太人』送往集中营，主张在绝育与驱逐之间作出选择；最后，他以『如果我辞职，更坏的人会取代我』为留在职位上辩护。这些辩词把法律人职业伦理中最难堪的一面暴露出来：当法律机器被用于实施不义，职业身份究竟是责任的来源还是逃避责任的借口。", "caseAnalysis": "就法官审判而言，事实是被告以司法官员身份参与了纳粹法制的运作，争点在于服从现行法律与服从良知之间如何取舍。法律依据方面，控方诉诸高于国家法律的正当程序与人性原则，辩方则诉诸职务义务与体制压力。裁判理由的关键在于：『我只是适用当时有效的法律』这一辩护，无法解释法官在制度中主动赋予不义以合法外观的作用。理论意义有三层。其一，它印证了格林关于制度代价的分析：专业化的法律机构使权力运转得更有效率，也使个人责任更容易被分摊和掩盖。其二，它检验了韦伯命题的边界：法理型支配可以提供合法性，但合法性的形式外观并不能自动免除行动者的道德判断。其三，它把批判法理论的抽象命题具体化了——法律职业与权力结构之间存在共生关系，法律人既是约束者，也可能是合法化的提供者。Wacks 以这个问题作为应用法理学的练习，正是因为它没有轻松的答案。", "summary": "法律与政治权力的关系可以从三个命题来把握。其一，法律的制度化是一笔混合交易：它带来确定性、可变性与效率，也制造了中央权力压迫少数人的风险，而法律秩序的稳定往往只需官员共识与民众默许。其二，韦伯揭示了现代统治的合法化机制：法理型支配以形式合理的法律为正当性基础，法律形式本身即可提供意识形态支持，法律与经济保持相对自主的关系。其三，批判法理论指出法律并非中立的知识体系，它不确定、不融贯，并表达政治经济权力。三种视角分别描述制度运作、解释历史形态与揭示意识形态功能，彼此构成的张力，正是当代法理学继续讨论法律正当性的动力。", "furtherThinking": "1. 如果法律秩序的稳定只需官员共识与民众默许，这种稳定的正当性基础是否过于薄弱？普通人的『默许』与『同意』之间应否作出区分？\n2. 韦伯说在法理型支配下无需评价法律内容即可说明合法性，这一命题能否解释极权体制下形式合法的法律所制造的不义？\n3. 若法律职业通过一套专门知识维持自身权威，这种专业垄断在何种条件下转化为对权力的制约，又在何种条件下沦为合法化的工具？"}, "en": "Law and Political Power", "level": "core", "tags": "法律与权力, 韦伯, 合法支配, 法律自主性, 批判法理论", "source": "Wacks, Understanding Jurisprudence, ch.1, ch.7, 7.5；Hart, The Concept of Law, Introduction by Leslie Green；Ross, On Law and Justice", "id": "S3M4K5"}, "S3M4K6": {"title": "现代法治的理论困境", "EN": "Theoretical Dilemmas of the Modern Rule of Law", "LEVEL": "core", "TAGS": "法治, 法律确定性, 自由裁量, 实质正义, 合法性", "TERMS": "法治（Rule of Law）::要求公共权力受一般、公开、可预见规则约束的政治法律理想；形式法治（Formal Conception of Rule of Law）::强调程序与形式品质而不预设特定正义内容的法治观；实质法治（Substantive Conception of Rule of Law）::把正义、人权等价值纳入法治内涵的法治观；合法性（Legality）::德沃金用以指称法治诸政治德性的概念；否定性美德（Negative Virtue）::拉兹对法治的定位，即它能减少任意权力的风险却自身不带独立道德价值；法的确定性（Legal Certainty）::公民可预先知晓法律要求并据此规划生活的状态；紧急状态例外（State of Emergency Exception）::在危机中暂时偏离常规法律要求的制度安排", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, 4.4, 5.2.7；Hart, The Concept of Law, ch.7；Fuller, The Morality of Law；Raz, The Authority of Law；Dworkin, Law’s Empire", "terms": [{"term": "法治（Rule of Law）", "def": "要求公共权力受一般、公开、可预见规则约束的政治法律理想"}, {"term": "形式法治（Formal Conception of Rule of Law）", "def": "强调程序与形式品质而不预设特定正义内容的法治观"}, {"term": "实质法治（Substantive Conception of Rule of Law）", "def": "把正义、人权等价值纳入法治内涵的法治观"}, {"term": "合法性（Legality）", "def": "德沃金用以指称法治诸政治德性的概念"}, {"term": "否定性美德（Negative Virtue）", "def": "拉兹对法治的定位，即它能减少任意权力的风险却自身不带独立道德价值"}, {"term": "法的确定性（Legal Certainty）", "def": "公民可预先知晓法律要求并据此规划生活的状态"}, {"term": "紧急状态例外（State of Emergency Exception）", "def": "在危机中暂时偏离常规法律要求的制度安排"}], "sections": {"coreQuestion": "『法治』是当代政治与法律话语中最容易获得共识、也最容易被掏空的词之一。几乎所有政权都声称自己实行法治，而批评者又几乎总能指出其法治的名义性。这种局面源于法治概念内部的几组张力：规则要稳定，社会却要变革；裁判要可预测，个案却需要裁量；形式要一致，结果却要正义。本节要把这些张力呈现为理论困境，并比较富勒、拉兹与德沃金给出的三种代表性回答；罗列法治要素只是起点。核心问题是：法治究竟是一套可形式化地满足的程序条件，还是一项内在包含正义价值的政治德性？", "definition": "法治在最低限度上指公共权力的行使须受一般、公开、可预见的规则约束。形式法治观把法治理解为法律的形式品质：一般性、公开性、不溯及既往、清晰、不矛盾、可遵守、稳定、官方行为与宣布的规则一致。富勒把这八项称为法律的『内在道德』，并强调它们是『渴望的道德』而非可机械核对的最低门槛。实质法治观则主张，缺少正义、尊严或基本权利的法律秩序，即使形式上完美，也称不上法治。拉兹（Joseph Raz）提供了第三种定位：法治是一种『否定性美德』，它能减少行政权滥用的风险，却并不赋予法律独立的道德价值；任意权力的风险本身正是由法律制造出来的。德沃金则用『合法性』（legality）一词统合法治所服务的政治价值，包括效率、公民平等、自我治理与对权力的道德证成。", "history": "现代法治理论的成形与二十世纪的制度经验紧密相连。二战后，宪法权利保障与司法审查在多个法域扩张，美国的权利法案及其在沃伦法院时期的解释、西德《基本法》的制定，都把『法律之下的政府』变成可操作的制度安排。1948年《世界人权宣言》与1959年《德里法治宣言》等文件，则把法治提升为跨国的政治标准。Wacks 指出，这些文件倾向于把自然法理解为衡量实定法的尺度，而非宪法意义上可直接推翻普通法的高级法。与此同时，法治话语的普及也带来概念膨胀：当法治被用来称赞一切既有秩序时，它便丧失了批判功能。正是在这一背景下，法理学家开始反思：法治的吸引力来自何处？它能否同时满足形式确定性与实质正义？", "principle": "法治的困境可以从四组张力逐层展开。第一组是稳定性与变革性的张力。富勒的不溯及既往与稳定性要求，使公民得以依据法律规划生活；但法律若完全不能变动，又会失去适应新情境的能力。富勒把八项要求定位为渴望的道德，正是承认它们无法被彻底实现，只能被持续追求。第二组是确定性与裁量的张力。哈特的开放结构理论表明，任何规则都有边缘地带，法律在那里无法给出唯一答案，法官必须行使有限的造法权。法治要求可预测，个案正义却要求裁量；裁量过多伤及确定性，裁量过少又使法律僵硬。德沃金以建构性解释回应：若法官能在契合先例与最佳道德辩护之间找到唯一正确答案，裁量就不必被视为法治的裂缝。第三组是形式合法与实质正义的张力。Wacks 指出，南非种族隔离制度很可能满足了富勒的全部八项形式要求，这说明形式合法本身并不足以保证正义。第四组是工具价值与内在价值的张力：法治能带来效率与秩序，暴君也可能借它维持统治；德沃金因此强调，法治的价值必须超出效率，指向公民之间的平等与共同体的道德正当性。", "viewpoints": "三位代表人物的立场构成一条清晰的光谱。富勒把合法性条件视为法律的内在道德：遵守八项要求并不保证实质正义，却使坏法律更难藏身；对一个形式要求全面失败的秩序，我们甚至有理由怀疑它是否还在从事『法律』这项事业。拉兹走另一极端：法治仅是一种技术性的、消极的德性，它保证权力以公开一般规则的方式行使，从而减少专断；但即使一个法治完备的法律体系，公民也未必负有初步的服从义务，因为服从义务需要额外的道德论证。德沃金则试图把法治重新道德化：法律的整体性不仅提供可预测性与程序公平，更在公民之间确立平等，使政治权力的行使获得更好的道德证成；他把这种价值称为『合法性』，认为连暴君也不敢完全抛弃法治而纯凭任性或恐怖统治。Wacks 指出，尽管两派争论激烈，自然法与实证主义都重视法治理想，这一共同点恰是理解上述争论的入口。", "comparison": "形式法治与实质法治的区分，可与前几节的争论对应起来。形式法治接近哈特式的思路：先以社会来源识别法律，再以形式品质评价其是否合格；它关心的是权力如何被组织。实质法治则接近自然法与德沃金：正义与权利进入法律识别与证成的过程，法律与道德的分界被放宽。拉兹的位置特殊：他坚持来源命题与价值中立的描述性法理学，同时承认法治的价值，只是把这种价值限定为减少任意权力。富勒的位置同样独特：他既非纯粹形式主义者，也非实质自然法学者，而是把形式程序要求本身理解为一种道德。比较三者的关键不在于谁更『重视法治』，而在于他们把法治的规范性放在哪里：放在程序的内在品质、放在权力风险的降低，还是放在共同体道德正当性的证成。", "debates": "法治能否为法律提供独立的道德理由，是争论的焦点。拉兹的论证是：法律本身制造了任意权力的风险，法治只不过把这种风险降低；既然风险来自法律，降低风险就谈不上法律自身的道德功劳。由此他进一步否认在即使是正义的法律体系中也存在初步的服从义务。德沃金的回应隐含在整体性理论中：法治若仅意味着效率与可预测，便不足以解释我们为何珍视『法律之下』的社会；真正使法治有价值的是它把过去决定中的原则延伸为平等对待公民的义务，这种义务具有超越效率的分量。富勒则会补充：若一个政权在八项合法性要求上系统性失败，它连自称法治的资格都有疑问。Wacks 提示，三家争论背后有一个共同的经验前提：法律既可能约束权力，也可能成为权力的工具。分歧在于，这个双重性应当被概念化为法治的局限，还是法治的使命。", "case": "南非种族隔离制度为形式法治的限度提供了最常被讨论的素材。Wacks 指出，这一法律体系很可能满足了富勒的全部八项原则；在一般性、公布、清晰、稳定等方面，种族隔离时期的制定法与司法运作并非全然无序。争议因此变得尖锐：一个在形式上合乎法治要求的秩序，是否仍可被称作法治社会？富勒本人的回应是，种族隔离立法以任意方式界定种族，违背了『一般性』要求，且法律与官方行为之间的一致性也成问题。这一回应的说服力并不充分，Wacks 把它作为一个开放的问题留给读者。这里不涉及对任何具体判决的虚构，所依据的是 Wacks 对这一制度的形式评估及其引发的法学争论。该案例的价值在于，它把『法治的形式清单是否足够』从抽象命题变成了一个经验上可检验的问题。", "caseAnalysis": "就南非案例而言，事实层面是一套长期存续、形式完备的法律制度；争议焦点在于形式合法性是否穷尽了法治的含义。法律依据方面，支持形式法治论者可以指出一般性、公开性、稳定性等条件大体得到满足；批评者则诉诸平等与尊严等实质价值，认为把人按种族分类并系统剥夺其权利的法律，无法被承认为法治秩序的一部分。裁判理由的比喻在此处不适用，因为我们面对的是制度评估而非个案判决；但理论意义十分明确：其一，它证明遵守程序要求与实现正义之间存在真实缝隙；其二，它说明富勒的八项要求若被当作清单式核对工具，反而可能被滥用为不义制度的背书；其三，它支持德沃金的方向——法治必须包含某种平等维度，否则就无法与赤裸的权力统治区分开来。同时也要看到，若把实质正义设成法治的入场券，又会出现由谁定义正义的新难题。", "summary": "现代法治的理论困境源于四组张力：稳定与变革、确定性与裁量、形式合法与实质正义、工具价值与内在价值。富勒以内在道德回应，强调合法性要求构成法律的渴望；拉兹以否定性美德回应，强调法治仅降低专断风险，不自带独立道德价值；德沃金以合法性与整体性回应，强调法治通过平等与自我治理证成政治权力。南非案例表明，形式清单不足以承载法治的全部承诺，而实质标准的引入又必须面对定义权的归属问题。法治因此是一个持续被争夺的概念：它的力量恰恰来自这种可争议性，它的危险也来自这种可争议性被滥用的时候。", "furtherThinking": "1. 若一套法律在形式上完全符合富勒八项要求，却在内容上系统歧视某一群体，应当说它『有法治但不正义』，还是说它『根本无法治』？两种说法各有何代价？\n2. 拉兹说法治只是否定性美德，德沃金说法治提供平等与自我治理。这两种描述能否同时成立，还是必须选择其一？\n3. 在紧急状态下暂停部分法律保障，是法治的自我保存机制，还是法治向权力让路的开始？"}, "en": "Theoretical Dilemmas of the Modern Rule of Law", "level": "core", "tags": "法治, 法律确定性, 自由裁量, 实质正义, 合法性", "source": "Wacks, Understanding Jurisprudence, ch.2, 4.4, 5.2.7；Hart, The Concept of Law, ch.7；Fuller, The Morality of Law；Raz, The Authority of Law；Dworkin, Law’s Empire", "id": "S3M4K6"}, "S3M5K1": {"title": "人工智能与法律责任", "EN": "Artificial Intelligence and Legal Liability", "LEVEL": "core", "TAGS": "人工智能, 法律责任, 责任缺口, 风险分级, 算法归责", "TERMS": "人工智能（Artificial Intelligence, AI）::使机器执行通常需要人类智能的任务的技术体系；法律责任（Legal Liability）::因违反义务或造成损害而由法律施加的不利后果；责任缺口（Responsibility Gap）::损害确已发生却难以找到可归责主体的现象；产品责任（Product Liability）::生产者对其产品缺陷造成损害承担的赔偿责任；严格责任（Strict Liability）::不以过错为要件、依据损害与风险归属承担责任的方式；法律人格（Legal Personality）::法律上可作为权利义务主体的资格；不透明性（Opacity）::模型内部决策过程难以被外部理解与解释的性质", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6, ch.10；Hart, The Concept of Law, ch.7；Regulation (EU) 2024/1689 (Artificial Intelligence Act)", "terms": [{"term": "人工智能（Artificial Intelligence, AI）", "def": "使机器执行通常需要人类智能的任务的技术体系"}, {"term": "法律责任（Legal Liability）", "def": "因违反义务或造成损害而由法律施加的不利后果"}, {"term": "责任缺口（Responsibility Gap）", "def": "损害确已发生却难以找到可归责主体的现象"}, {"term": "产品责任（Product Liability）", "def": "生产者对其产品缺陷造成损害承担的赔偿责任"}, {"term": "严格责任（Strict Liability）", "def": "不以过错为要件、依据损害与风险归属承担责任的方式"}, {"term": "法律人格（Legal Personality）", "def": "法律上可作为权利义务主体的资格"}, {"term": "不透明性（Opacity）", "def": "模型内部决策过程难以被外部理解与解释的性质"}], "sections": {"coreQuestion": "自动驾驶汽车发生事故、医疗算法给出错误诊断、生成式模型输出诽谤内容——损害是真实的，但责任应落在谁身上？开发者说是使用者误用，部署者说是模型自主输出，使用者说自己只是依赖了专业系统。人工智能（Artificial Intelligence, AI）带来的法理学难题，不在于损害是否应被救济，而在于传统的责任范畴以人的过错与可预见性为中心，面对具有学习能力与黑箱性质的系统时出现了归属困难。本节要讨论：AI本身能否成为责任主体；在开发者、部署者与使用者之间应如何分配责任；以及风险分级监管能否填补归责缺口。", "definition": "法律责任指因违反法定义务或造成法定损害而须承担的不利后果，传统上以过错责任（fault liability）与严格责任（strict liability）为基本形态。过错责任追问行为人是否未尽合理注意，严格责任则把注意义务的问题搁置，直接依据风险的创造与利益归属分配损害。责任缺口是当代 AI 伦理与法学讨论中的核心概念：当系统以不可预测的方式造成损害，而所有相关人类主体都能声称自己缺乏控制时，法律找不到一个可归责的落脚点。法律人格指成为权利义务主体的资格；目前各主要法域普遍不赋予 AI 系统以独立法律人格，其输出的法律后果最终由自然人或组织承担。不透明性则描述深度学习模型内部决策过程难以被外部重构的状态，它直接冲击因果关系与过错的证明。", "history": "AI 从早期的符号主义专家系统发展到机器学习与深度学习，其决策规则逐渐从人类显式编写转向从数据中自动生成。这一转变带来一个法学上的分水岭：传统软件可以按『编程者的意图』理解，而训练出来的模型的行为是统计优化的产物，其具体输出往往连开发者也无法事先逐一预见。生成式 AI 的普及进一步放大了这一问题，内容生成、招聘筛选、信贷评估、医疗辅助等场景使算法决策深度嵌入社会。立法者对此的回应之一，是欧盟在2024年通过《人工智能法案》（Artificial Intelligence Act）：Regulation (EU) 2024/1689 于2024年6月13日通过，2024年8月1日生效，各项规定分阶段适用，最迟到2027年8月全部适用。这部法律采取以风险为轴心的监管思路，为不同风险等级的系统设置不同义务。", "principle": "AI 归责可以沿三个层次分析。第一层是主体资格：法律权利义务的承担者通常须具备辨识与控制自己行为的能力，AI 系统虽能作出复杂输出，却不具备道德主体意义上的可责难性，因此当前法律倾向于把责任分配给链条上的人类与组织。第二层是责任依据：在产品责任路径下，焦点是系统是否存在设计或制造缺陷；在过错路径下，焦点是开发者或部署者是否尽到合理注意；在严格责任路径下，焦点是谁创造了风险并从风险中获益。第三种思路主张由最能控制风险、最有能力分散损失的一方承担，这解释了为何部署者在某些场景下比开发者更合适作为责任主体。第三层是因果与证明：不透明性使『哪一环节导致了损害』变得难以证明，传统上由原告证明因果关系的格局，可能因证据偏在而需要调整举证负担。Wacks 在讨论法律与道德时强调，归责实践离不开对『行动者』的识别；当行动者变成系统，就必须重新说明责任概念所服务的社会功能。", "viewpoints": "关于 AI 责任，主要存在四种方案。其一，扩展既有产品责任，把软件的缺陷与更新纳入『产品』范畴，优点是与现行制度衔接紧密，难点在于自学习系统的缺陷难以在投放市场时确定。其二，引入针对高风险 AI 的严格责任，强调风险创造者应负担损害，优点是受害人救济更确定，批评者担心抑制创新。其三，赋予 AI 有限的法律人格与独立财产，使赔偿请求可直接针对系统，这在法学界仍属少数说，反对意见认为它回避了真正应当负责的人。其四，以强制保险或赔偿基金分散风险，把责任问题转化为风险融资问题。欧盟《人工智能法案》采取的是另一条路径：以风险等级配置义务，对不可接受风险予以禁止，对高风险系统设定提供者与部署者的合规义务，对部分系统设置透明度要求，并辅以为特定 AI 系统建立欧盟数据库等安排。它主要解决事前合规，责任归属仍需结合各法域的侵权与产品责任规则。", "comparison": "AI 责任问题可以用前几节的理论框架重新观察。从哈特的规则理论看，把决策规则写入代码，容易让人误以为算法决定是机械适用规则的结果；实际上，训练数据的选择、目标函数的设定与部署场景的裁剪，都蕴含着类似『次级规则』的制度性选择。从德沃金的原则理论看，归责不能只问形式上的因果关系，还要问何种分配最能尊重个体权利与公平；『谁受益谁负担』的背后正是原则性判断。从法律现实主义看，AI 案件中的事实认定高度依赖专家意见，法官对技术的理解会影响判决，这印证了现实主义关于事实不确定性的洞见。从法治理论看，算法决策带来可预测性与灵活性之间的新张力：完全透明可能损害商业机密与系统安全，完全不透明又使公民无法预判权力如何对自己作出决定。", "debates": "第一场争论是『责任缺口是否真实存在』。一方认为，只要沿着设计、训练、部署、监督各环节审查，总能找到未尽注意义务的主体，缺口只是责任的分散而非消失。另一方认为，当各主体都按最佳实践行事而损害仍发生时，确实出现无法归责的情形，这就需要一个不依赖于过错的救济机制。第二场争论是『AI 应否取得法律人格』。支持者认为独立人格有助于明确责任财产与交易安排；反对者认为，这会让真正控制与获益的人脱身，且把道德主体的地位赋予无意识的系统在概念上难以成立。第三场争论是创新与保护的权衡：严格责任与高额合规成本可能把技术集中到少数大企业，而过宽的免责又会把风险转嫁给弱势的受害者。这些争论目前都没有定论，它们共同说明 AI 责任是法理学基本范畴在技术场景中的压力测试。", "case": "欧盟《人工智能法案》的立法过程本身就是理解 AI 监管的极佳案例。欧洲议会与欧盟理事会于2024年6月13日通过 Regulation (EU) 2024/1689，即《人工智能法案》，2024年7月刊登于《欧盟官方公报》，2024年8月1日生效。该法以风险为基础设置分层义务：禁止若干不可接受风险的做法，对高风险系统规定提供者与部署者的义务，对通用人工智能模型设定专门要求，并对部分系统施加透明度义务。其适用采取分阶段安排，各项规则至2027年8月全部适用。这一立法并未直接创设一套全新的 AI 侵权责任法，而是先把事前的行为规范写清楚，为事后追责提供判断注意义务与违规与否的参照。这里所述的均为立法事实，未涉及任何具体司法判决。", "caseAnalysis": "就《人工智能法案》而言，事实层面是欧盟以统一立法回应 AI 风险，争议焦点在于监管应当针对技术本身还是针对使用行为。法律依据是欧盟在内部市场与基本权利保护方面的权限，立法理由在于：如果各成员国各行其是，会出现规则碎片化，同时公民健康、安全与基本权利需要高水平保护。其理论意义在于三点。其一，风险分级把模糊的『AI 治理』转换为可操作的义务配置，体现了法治对明确性的要求。其二，它把责任链向前延伸到设计与投放阶段，说明法律开始把『可预见的风险』作为组织义务的基础。其三，它也暴露了局限：合规义务并不自动回答个案中的赔偿问题，损害发生后仍需借助侵权法与产品责任法；而技术的快速迭代与立法的分阶段适用之间，始终存在时间差。AI 责任因此是一项持续制度工程，很难靠一部法律一次完成。", "summary": "AI 造成的损害把法律责任的基本范畴推到极限。责任归属的核心难题在于：AI 系统缺少可责难性，人类主体的控制力又被分散到设计、训练、部署与使用各环节，再加上模型不透明，传统的过错与因果关系证明都遇到困难。理论上形成扩展产品责任、高风险严格责任、有限法律人格与风险基金等多种方案；欧盟《人工智能法案》则以风险分级的事前义务配置为主要回应。用哈特、德沃金、现实主义与法治理论重新审视，可以看到 AI 责任并非纯粹技术问题，它同时涉及规则如何被制定、权利如何被尊重、事实如何被认定，以及权力如何保持可预测。技术变化越快，这些法理学基本问题越需要被反复追问。", "furtherThinking": "1. 如果一个人人遵守合规义务的高风险 AI 系统仍造成损害，责任缺口应当通过严格责任填补，还是通过强制保险解决？两种做法对创新激励有何不同影响？\n2. 赋予 AI 有限法律人格在概念上会遇到哪些障碍？它是否真的能让受害者更容易获得救济？\n3. 当算法决策大量取代人工判断时，哈特所说的『开放结构』会从法律规则转移到代码之中吗？这种转移对法治的可预测性意味着什么？"}, "en": "Artificial Intelligence and Legal Liability", "level": "core", "tags": "人工智能, 法律责任, 责任缺口, 风险分级, 算法归责", "source": "Wacks, Understanding Jurisprudence, ch.6, ch.10；Hart, The Concept of Law, ch.7；Regulation (EU) 2024/1689 (Artificial Intelligence Act)", "id": "S3M5K1"}, "S3M5K2": {"title": "算法治理与法律监管", "EN": "Algorithmic Governance and Legal Regulation", "LEVEL": "core", "TAGS": "算法治理, 算法监管, 可解释性, 平台责任, 数字服务法", "TERMS": "算法治理（Algorithmic Governance）::以算法系统参与公共或私人决策并进行规范约束的制度安排；自动化决策（Automated Decision-making）::由系统在没有人工干预的情况下作出决定或生成结果的过程；可解释性（Explainability）::使算法决策的理由能够被相关主体理解的性质；算法偏见（Algorithmic Bias）::系统输出对特定群体产生系统性不利影响的现象；数据保护影响评估（Data Protection Impact Assessment, DPIA）::对高风险数据处理活动进行事前评估的机制；基本权利影响评估（Fundamental Rights Impact Assessment, FRIA）::评估系统对基本权利潜在影响的程序；守门人（Gatekeeper）::数字市场法中对具有结构性平台地位的企业所设定的特殊身份", "SOURCE": "Wacks, Understanding Jurisprudence, ch.6, ch.10；Regulation (EU) 2016/679 (GDPR), Art.22；Regulation (EU) 2022/2065 (Digital Services Act)；Regulation (EU) 2022/1925 (Digital Markets Act)；Regulation (EU) 2024/1689 (AI Act)", "terms": [{"term": "算法治理（Algorithmic Governance）", "def": "以算法系统参与公共或私人决策并进行规范约束的制度安排"}, {"term": "自动化决策（Automated Decision-making）", "def": "由系统在没有人工干预的情况下作出决定或生成结果的过程"}, {"term": "可解释性（Explainability）", "def": "使算法决策的理由能够被相关主体理解的性质"}, {"term": "算法偏见（Algorithmic Bias）", "def": "系统输出对特定群体产生系统性不利影响的现象"}, {"term": "数据保护影响评估（Data Protection Impact Assessment, DPIA）", "def": "对高风险数据处理活动进行事前评估的机制"}, {"term": "基本权利影响评估（Fundamental Rights Impact Assessment, FRIA）", "def": "评估系统对基本权利潜在影响的程序"}, {"term": "守门人（Gatekeeper）", "def": "数字市场法中对具有结构性平台地位的企业所设定的特殊身份"}], "sections": {"coreQuestion": "当招聘筛选、信贷评分、内容推荐、司法风险评估都由算法参与完成时，治理的对象发生了变化：法律过去规范人的决定，如今需要规范生成决定的系统。算法治理的核心问题有三个。其一，算法决策是否应当像公共权力决定一样，接受公开、理由说明与问责？其二，算法造成的不利影响若源于训练数据中的历史偏见，责任应归于数据的提供者、系统的设计者还是使用者？其三，监管本身应当在多大程度上介入技术细节？本节以欧盟的《通用数据保护条例》（GDPR）、《数字服务法》（Digital Services Act）与《人工智能法案》为线索，讨论算法治理中的法理学难题。", "definition": "算法治理指通过规则与制度安排，对算法系统的设计、部署与运行进行约束，并对算法参与的决策提供救济。自动化决策指系统在没有实质性人工介入的情况下作出决定；GDPR 第22条赋予数据主体在一定条件下不受纯粹自动化决定约束的权利，并规定例外与保障。可解释性要求决策理由能够被受影响者理解，它区别于技术上的可复现性：一个系统可能在技术上可重复运行，却无法向当事人说明为何作出该判断。算法偏见指输出对特定群体产生系统性不利影响，其来源可能是历史数据、标签方式、目标函数或部署场景。DPIA 是 GDPR 对高风险处理活动要求的事前评估，FRIA 则是《人工智能法案》为特定高风险系统设置的基本权利影响评估；二者逻辑相近，前者聚焦数据主体权利，后者覆盖非歧视、公正审判等更广泛的基本权利维度。", "history": "算法治理的兴起与平台经济的扩张同步。大型在线平台通过推荐系统决定信息可见性，通过排序机制影响交易机会，逐渐具有类似公共基础设施的地位。与此同时，机器学习在信贷、招聘、保险、医疗等领域的应用，使自动化决策从后台工具变成影响个人重大利益的决定力量。欧盟的回应形成一条渐进的立法链条：GDPR 于2016年通过、2018年适用，其第22条率先处理自动化决策问题；《数字服务法》（Regulation (EU) 2022/2065）于2022年通过，2024年2月起全面适用，要求平台提高推荐系统的透明度并对超大型平台施加风险评估义务；《数字市场法》（Regulation (EU) 2022/1925）为具有结构性地位的平台设定守门人义务；《人工智能法案》则于2024年通过并分阶段适用。这一立法序列显示，监管重点正从单一数据处理行为转向系统性的平台与算法权力。", "principle": "理解算法治理，可以从三条线索展开。第一条是『代码即规则』的线索：算法实际上在执行某种规范，它决定什么被看见、谁获得机会、哪些人被标记为风险；如果把这种规范力量交给市场自行塑造，相当于允许私人主体制定影响公共生活的规则。第二条是治理工具的分类。透明度工具要求披露算法如何运作或为何作出决定；过程性工具要求在部署前进行 DPIA 或 FRIA，把风险识别嵌入组织流程；实体性工具则直接禁止某些做法，例如基于敏感属性的歧视性分类。第三条是治理悖论。可解释性要求往往与商业秘密、系统安全相冲突；过度披露可能为规避行为提供地图，而完全不披露又使当事人无法质疑决定。此外，监管者越来越依赖算法工具进行合规监测，形成『以算法监管算法』的格局，这引发谁来监管监管者的问题。", "viewpoints": "算法治理的主要制度方案可归纳为四类。第一类是事前评估：通过 DPIA 与 FRIA 把风险识别前置，使组织在部署前说明预期目的、必要性与缓解措施。第二类是透明度与说明义务：平台须说明推荐系统的主要参数，用户须被告知自己正与自动化系统互动。第三类是问责与审计：要求保留记录、设立负责人、允许独立审计，使监管从事后追责延伸到过程监督。第四类是权利配置：赋予当事人拒绝纯粹自动化决定、要求人工复核、质疑结果的权利。GDPR 第22条与《人工智能法案》的高风险系统义务分别代表了权利路径与风险路径。Wacks 在讨论法律现实主义时指出，裁判很大程度上取决于法官对事实的判断；在算法案件中，这一判断高度依赖专家知识，法律规则因此无法完全决定结果，这使程序性的问责机制显得格外重要。", "comparison": "算法治理可以用前几节的理论框架加以定位。从富勒的内在道德看，算法决策若要被接受为『法律式的』治理，至少需要一般性、公开性与规则与行动的一致性；秘密运行的黑箱系统在形式上就难以满足这些要求。从德沃金的权利理论看，算法歧视之所以可被谴责，不仅因为它降低效率，更因为它侵犯个体被平等对待的权利；权利在这里发挥『王牌』作用，不能简单被平台效率目标压倒。从哈特的规则理论看，算法既是执行初级规则的工具，又通过设定识别与筛选标准发挥了次级规则的功能，这解释了为什么它可能脱离设计者的原始意图。从法治理论看，算法治理使确定性与灵活性、公开性与安全性之间的经典张力以新的形式出现。现实主义则提醒我们，算法案件的裁决会受法官对技术事实的理解影响，因此应保持对『技术中立』叙事的警惕。", "debates": "第一场争论围绕透明度展开。一方主张算法决定影响个人重大利益时，当事人有权获得可理解的理由；另一方指出，深入披露会暴露商业秘密并可能被恶意利用，且深度模型的解释在技术上仍有困难。折中方案是区分对象：向监管者提供完整审计信息，向当事人提供可理解的要点说明。第二场争论是事前监管与事后责任的取舍。事前评估能够防患于未然，但可能把监管锁定在技术快速变化之前；事后责任灵活，却须等到损害发生。第三场争论是偏见的性质：算法偏见究竟是数据质量的经验问题，还是权力结构的规范问题？若视为前者，治理手段是数据清洗与模型优化；若视为后者，就必须追问谁有权定义『公平』，以及受影响群体是否参与标准制定。这场争论把技术问题重新带回法哲学的价值判断。", "case": "欧盟《数字服务法》（Regulation (EU) 2022/2065）是算法治理的代表性立法。该法于2022年通过，2024年2月起全面适用。它要求在线平台披露推荐系统所使用的参数与用户可选择的设置，使信息排序逻辑不再是完全不可见的黑箱；对超大型在线平台，它还设置了系统性风险评估与缓解义务，要求平台评估其服务对基本权利、公共健康与公共安全的影响。《数字服务法》与《数字市场法》形成分工：前者侧重内容治理与透明度，后者针对具有守门人地位的平台设定行为边界。这里只叙述可核实的立法事实，不涉及任何具体执法个案的细节。", "caseAnalysis": "就《数字服务法》而言，事实层面是欧盟把大型平台的算法治理纳入统一规则，争点在于平台的信息排序权力应否受到公法式约束。法律依据来自欧盟对内部市场与基本权利保护的立法权限，立法理由在于：当少数平台决定信息的可见性时，单纯依靠市场选择不足以保护用户自主与公共讨论的质量。其理论意义有三。其一，透明度义务把富勒意义上的『公开性』要求延伸到算法推荐领域，使原先私人的技术选择变成可问责的治理行为。其二，风险评估义务把治理重心从个案救济移向系统性影响，这回应了算法偏见的结构性特征。其三，它也留下难题：风险评估的标准由谁设定、评估是否充分由谁审查，都涉及监管能力与民主正当性。算法治理因此要求重新思考在算法塑造的社会中，公开性、平等与问责应当如何被制度化，而不能停留在把法律简单套用到技术之上。", "summary": "算法治理是法律面对算法权力时的制度回应。它的核心难题包括：算法决策应否公开并说明理由，偏见应被理解为数据缺陷还是权力结构问题，以及监管如何在透明与安全之间取舍。欧盟通过 GDPR 第22条、《数字服务法》《数字市场法》与《人工智能法案》，逐步建立起以透明度、事前评估、问责审计与个体权利为支柱的治理框架。从法哲学角度看，这些制度回应了富勒的形式要求、德沃金的权利命题与哈特对规则运作的分析，同时也印证了现实主义关于技术事实依赖的洞见。算法治理的未来，取决于能否把这些法理资源转化为既能保护个体、又不窒息技术演进的可操作制度。", "furtherThinking": "1. 向当事人提供『可理解的理由』与向监管者提供『完整的技术审计』之间，应当如何划分边界？这种划分本身是否也是一种价值选择？\n2. 如果算法偏见训练自社会中已有的历史不平等，单纯清理数据能否解决问题？法律在此应当要求什么？\n3. 当监管机关也使用算法工具进行监测时，哈特的『承认规则』在算法治理体系中由谁来掌握？"}, "en": "Algorithmic Governance and Legal Regulation", "level": "core", "tags": "算法治理, 算法监管, 可解释性, 平台责任, 数字服务法", "source": "Wacks, Understanding Jurisprudence, ch.6, ch.10；Regulation (EU) 2016/679 (GDPR), Art.22；Regulation (EU) 2022/2065 (Digital Services Act)；Regulation (EU) 2022/1925 (Digital Markets Act)；Regulation (EU) 2024/1689 (AI Act)", "id": "S3M5K2"}, "S3M5K3": {"title": "数据隐私与个人权利", "EN": "Data Privacy and Individual Rights", "LEVEL": "core", "TAGS": "数据保护, 隐私权, 个人信息, GDPR, 被遗忘权", "TERMS": "数据保护（Data Protection）::通过法律规则规范个人数据处理以保护个人权利的制度；隐私权（Right to Privacy）::个人对其私人生活与信息保持控制的权利；个人数据（Personal Data）::与已识别或可识别自然人有关的信息；数据主体（Data Subject）::个人数据所指向的自然人；处理（Processing）::对个人数据进行的收集、存储、使用、传输等活动；数据控制者（Data Controller）::决定数据处理目的与方式的主体；知情同意（Consent）::数据主体在知情基础上自由作出的同意表示；被遗忘权（Right to Be Forgotten）::在一定条件下要求删除或移除个人信息的权利", "SOURCE": "Wacks, Understanding Jurisprudence, ch.10；Regulation (EU) 2016/679 (GDPR)；Case C-131/12 Google Spain SL v AEPD (2014)；Case C-311/18 Schrems II (2020)", "terms": [{"term": "数据保护（Data Protection）", "def": "通过法律规则规范个人数据处理以保护个人权利的制度"}, {"term": "隐私权（Right to Privacy）", "def": "个人对其私人生活与信息保持控制的权利"}, {"term": "个人数据（Personal Data）", "def": "与已识别或可识别自然人有关的信息"}, {"term": "数据主体（Data Subject）", "def": "个人数据所指向的自然人"}, {"term": "处理（Processing）", "def": "对个人数据进行的收集、存储、使用、传输等活动"}, {"term": "数据控制者（Data Controller）", "def": "决定数据处理目的与方式的主体"}, {"term": "知情同意（Consent）", "def": "数据主体在知情基础上自由作出的同意表示"}, {"term": "被遗忘权（Right to Be Forgotten）", "def": "在一定条件下要求删除或移除个人信息的权利"}], "sections": {"coreQuestion": "在数字环境中，个人的位置、消费、社交、健康乃至情绪都可能被记录与分析。问题随之出现：这些数据在性质上是什么？个人对它们享有什么样的权利？当数据被用于算法训练、精准营销或公共治理时，法律应如何划定边界？本节以欧盟《通用数据保护条例》（General Data Protection Regulation, GDPR）为核心素材，讨论数据隐私作为一项个人权利的法理基础、权利结构与制度局限，并借助欧洲法院的两个判例说明权利如何被具体化。", "definition": "数据保护指通过法律规则规范个人数据的收集、存储、使用与传输，以保护个人的基本权利与自由。隐私权则更宽泛，指向个人对私人生活与信息私密性的控制。GDPR 把保护对象界定为『个人数据』，即与已识别或可识别自然人有关的信息；『处理』涵盖收集、记录、组织、存储、使用、传输等一系列活动。数据控制者是决定处理目的与方式的主体，处理者则按控制者指示行事。GDPR 第5条确立合法性、公平性、透明性、目的限制、数据最小化、准确性、存储限制、完整性与保密性，以及问责原则。第6条列出处理的合法基础：同意、履行合同、法定义务、重大利益、公共任务与合法利益。这一结构说明，数据保护为处理行为设定一套条件与程序，单纯赋予个人一项排他财产权的理解过于狭窄。", "history": "欧盟的数据保护立法可追溯至1995年的《数据保护指令》，其目标是在欧洲范围内协调规则并保障个人数据在内部市场的自由流动。2012年欧盟委员会提出全面改革，2016年4月27日欧洲议会与理事会通过 GDPR（Regulation (EU) 2016/679），同年5月24日生效，2018年5月25日起适用。GDPR 把数据保护提升为基本权利层面的事项，并引入更强的数据主体权利与更高的合规要求。与此同时，欧洲法院通过判例逐步塑造数据权利的具体内容：2014年 Google Spain 案确认搜索引擎在特定条件下可被认定为数据控制者，并支持个人请求移除链接；2020年 Schrems II 案则处理跨境传输与第三国政府监控问题，宣告欧盟—美国隐私盾的充分性决定无效，同时确认标准合同条款在个案评估下仍可使用。", "principle": "数据隐私的法理基础可从三层理解。第一层是权利的性质。隐私权通常被理解为一种防御性权利，要求他人与国家不得干预；但在数据环境中，它越来越包含要求信息控制、更正与删除的积极维度。德沃金把权利理解为『王牌』，强调权利不应被集体目标轻易压倒；把这一思路用于数据保护，意味着个人对自身信息的利益不能简单被效率或商业创新所牺牲。第二层是权利与权力的关系。数据收集能力集中于少数平台与国家手中，个人在信息不对称中处于弱势；法律赋予的知情同意若只是形式上的勾选，就难以真正平衡这种权力差距。第三层是权利的边界。隐私权与言论自由、公众知情权、研究自由存在冲突；被遗忘权要求在记忆与遗忘之间作出制度性取舍，这种取舍本身就属于价值判断。", "viewpoints": "GDPR 建立了一套以原则、合法基础与主体权利为支柱的体系。除第5条原则与第6条合法基础外，它赋予数据主体访问权（第15条）、更正权（第16条）、删除权（第17条）、限制处理权（第18条）、可携权（第20条）、反对权（第21条），以及在一定条件下不受纯粹自动化决定约束的权利（第22条）。在义务侧，它要求高风险处理活动进行 DPIA（第35条），要求发生重大数据泄露时及时向监管机构报告（第33条），并确立隐私设计与默认保护的理念。这些制度把抽象权利转化为可操作的组织义务。学界对这套制度有不同评价：支持者认为它为数字时代的基本权利提供了坚实保障；批评者则指出，同意机制在实践中常被复杂条款架空，高额合规成本可能更有利于资源雄厚的大企业。", "comparison": "数据隐私可以用前几节的框架重新审视。从哈特的规则理论看，GDPR 的原则类似于开放的初级规则，而合法基础、评估义务与救济程序则发挥次级规则功能，使个人数据的处理变得可识别、可监督、可变更。从富勒的内在道德看，数据处理的公开性与目的限制，正是法律一般性要求在数据领域的延伸；秘密改变数据用途相当于规则与官方行为之间的脱节。从德沃金的原则理论看，数据权利的价值在于对个人尊严与平等的尊重；把隐私仅视为财产利益，会忽视其人格维度。从法治理论看，数据治理同时涉及确定性与灵活性：规则过严会妨碍合理的数据利用，规则过宽又使个人无从预判信息将如何被使用。现实主义则提醒我们，数据案件中的事实认定——什么是『可识别』、同意是否『自由』——高度依赖法官对社会语境的判断。", "debates": "第一场争论是知情同意的有效性。支持同意机制者认为，它尊重个人自主，使个人得以决定是否让渡数据；批评者指出，在现实的服务条款中，同意往往是被迫的，个人既无议价能力，也难以理解后果。由此产生以『合法利益』等基础替代同意的倾向。第二场争论是被遗忘权与信息自由的张力。支持删除权者强调个人有权摆脱过时信息的长期束缚；反对者担心删除会损害公共记录、学术研究与新闻自由。第三场争论是跨境数据流动与数据主权。Schrems II 案显示，即便有合同条款，第三国的政府监控法律仍可能削弱保护水平；这引出法律能否有效规制境外权力的问题。这些争论共同说明，数据权利的实现程度取决于制度设计，也取决于对权利边界的价值判断。", "case": "Google Spain SL v Agencia Española de Protección de Datos（Case C-131/12）由欧洲法院于2014年5月13日判决。案件事实是：一名西班牙公民发现，搜索引擎结果显示其姓名与多年前因债务导致的财产拍卖公告相连，他认为这些信息已不再相关，要求搜索服务运营者移除链接。争议焦点是：搜索引擎运营者是否构成数据控制者，以及个人能否要求移除链接。法院认定搜索引擎运营者在其索引与展示个人信息的活动中构成控制者；即便信息最初系合法发布，若其展示对当事人造成不必要损害且与公共利益不相称，个人可请求移除。这一判决奠定了所谓『被遗忘权』在欧洲法上的基础，并显示数据保护义务可以落在并非信息原始发布者的主体身上。", "caseAnalysis": "本案的事实相对简单，理论意义却很丰富。争点在于责任主体的认定：搜索引擎自称为技术中介，法院则依其实际决定信息索引与排序的功能，把它认定为控制者。法律依据是欧盟数据保护规则对个人数据处理的宽泛界定。裁判理由的关键，是把『使个人信息可被检索』本身视为一种处理活动，并衡量继续展示的必要性。理论意义有三。其一，它说明数据权利的保护对象不仅是信息本身，还包括信息被组织与呈现的方式。其二，它体现权利的利益衡量结构：删除权并非绝对，须与公共利益相权衡。其三，它把权力问题具体化——掌握信息分发渠道的主体，即使不生产信息，也要承担保护义务。与 Schrems II 案合看，还可看到数据权利的双重挑战：对内是平台权力，对外是国家监控，二者都要求法律提供有效的救济。", "summary": "数据隐私在当代已从消极的防御性权利，扩展为包含访问、更正、删除、可携与反对自动化决定等内容的权利束。GDPR 以原则、合法基础、主体权利与组织义务构成完整制度，并把数据保护置于基本权利层面。Google Spain 案表明，控制者身份取决于对处理目的与方式的实际决定，而非主体的自我定位；Schrems II 案则揭示跨境场景中合同机制的限度。学理上，数据权利可从哈特的规则结构、富勒的形式要求与德沃金的权利命题获得解释，也始终面临同意有效性、记忆与遗忘、跨境流动与主权之间的张力。数据权利的未来，取决于能否在保护个人与维持合理利用之间建立可被问责的制度平衡。", "furtherThinking": "1. 如果知情同意在实践中常常流于形式，法律应加强同意的实质审查，还是转向以合法利益为基础的风险规制？两种路径对个体自主各有何影响？\n2. 被遗忘权与公众知情权发生冲突时，应否由法院逐案衡量，还是应通过立法设定类型化规则？\n3. Schrems II 案显示合同条款难以约束第三国政府监控，这对传统领土基础上的法律管辖观念提出了什么挑战？"}, "en": "Data Privacy and Individual Rights", "level": "core", "tags": "数据保护, 隐私权, 个人信息, GDPR, 被遗忘权", "source": "Wacks, Understanding Jurisprudence, ch.10；Regulation (EU) 2016/679 (GDPR)；Case C-131/12 Google Spain SL v AEPD (2014)；Case C-311/18 Schrems II (2020)", "id": "S3M5K3"}, "S3M5K4": {"title": "数字时代的知识产权", "EN": "Intellectual Property in the Digital Age", "LEVEL": "core", "TAGS": "知识产权, 著作权, 人工智能生成物, 独创性, 公共领域", "TERMS": "知识产权（Intellectual Property）::对智力创造成果赋予的专有权利体系；著作权（Copyright）::保护文学艺术等作品表达的权利；独创性（Originality）::作品须体现作者独立创作与智力投入的要求；作者身份（Authorship）::法律上被承认为作品创作者的资格；思想与表达二分（Idea–Expression Dichotomy）::著作权保护表达而不保护思想的规则；合理使用（Fair Use）::在特定情况下不经许可使用作品的抗辩制度；技术保护措施（Technological Protection Measures）::用技术手段限制作品访问或复制的措施；公共领域（Public Domain）::不归任何人专有、可供公众自由利用的知识资源", "SOURCE": "Wacks, Understanding Jurisprudence, ch.10；Beijing Internet Court, Li v Liu, 27 Nov 2023；Thaler v Perlmutter (D.D.C. 2023, aff’d D.C. Cir. 2025)；Directive (EU) 2019/790 (Digital Single Market Copyright Directive)；WIPO Copyright Treaty (1996)", "terms": [{"term": "知识产权（Intellectual Property）", "def": "对智力创造成果赋予的专有权利体系"}, {"term": "著作权（Copyright）", "def": "保护文学艺术等作品表达的权利"}, {"term": "独创性（Originality）", "def": "作品须体现作者独立创作与智力投入的要求"}, {"term": "作者身份（Authorship）", "def": "法律上被承认为作品创作者的资格"}, {"term": "思想与表达二分（Idea–Expression Dichotomy）", "def": "著作权保护表达而不保护思想的规则"}, {"term": "合理使用（Fair Use）", "def": "在特定情况下不经许可使用作品的抗辩制度"}, {"term": "技术保护措施（Technological Protection Measures）", "def": "用技术手段限制作品访问或复制的措施"}, {"term": "公共领域（Public Domain）", "def": "不归任何人专有、可供公众自由利用的知识资源"}], "sections": {"coreQuestion": "数字技术给知识产权带来的挑战，主要体现在三个环节：复制变得几乎零成本，作品边界因人工智能参与创作而模糊，训练数据的使用使『使用』与『侵权』的界限难以划定。当一幅由模型生成的图片被他人取用，谁是作者？当模型通过大量受保护作品训练而获得能力，这是否构成侵权？本节要回到知识产权的法理基础：权利为何被赋予、赋予给谁、又应在何处止步；纯技术问题只是表层。", "definition": "知识产权是对智力创造成果赋予的专有权利体系，其中著作权保护的是作品的表达而非思想本身。独创性是作品获得保护的核心门槛，通常要求作品由作者独立创作并体现某种智力投入。作者身份指法律上被承认为创作者的资格，它决定权利归属。思想与表达二分是著作权法的基本界线：思想、事实、方法本身不受保护，保护的是其具体表达。合理使用或公平处理制度，则在特定情形下允许不经许可使用作品，以平衡权利人利益与公众的获取需求。技术保护措施与相应反规避规则，是数字环境中保护权利的技术—法律组合。公共领域则指不受专有权利限制、可供公众自由利用的知识资源，它是创新与表达自由的重要条件。", "history": "现代著作权制度经历了从印刷时代到网络时代的持续调整。国际层面，世界知识产权组织（WIPO）在1967年成立，《世界知识产权组织版权条约》（WIPO Copyright Treaty）于1996年通过，回应数字环境中的复制与传播问题；世界贸易组织《与贸易有关的知识产权协定》（TRIPS）于1994年生效，把知识产权纳入国际贸易规则。美国1998年通过《数字千年版权法》（DMCA），欧盟于2019年通过《数字单一市场版权指令》（Directive (EU) 2019/790），其中包含文本与数据挖掘例外等规定。生成式 AI 的普及把问题推向新阶段：训练数据是否属于『使用』、模型输出是否构成作品，成为各国法院与立法者必须面对的问题。不同法域的回应各有差异，这本身构成比较法上的重要素材。", "principle": "理解数字知识产权，可以从三层展开。第一层是权利证成。劳动论认为创作者对其劳动成果享有权利；人格论强调作品体现作者人格，因而作者享有署名与保护作品完整性的利益；激励论则把著作权视为鼓励创作的社会工具，通过有限期的专有权补偿创作成本。三种理论对 AI 生成物态度不同：劳动论会追问人的智力投入在哪里，人格论会追问作品体现了谁的人格，激励论则关注保护能否产生切实的激励效果。第二层是客体边界。思想与表达二分在数字环境中受到挤压：算法风格、数据集合、界面设计究竟是思想还是表达，往往难以判断。第三层是限制与例外。合理使用、法定许可与公共领域构成权利的外部边界，其存在说明知识产权始终带有社会制度的属性，服务于更广泛的文化目标，其权利范围自有边界。", "viewpoints": "在 AI 生成物的可版权性上，各法域呈现不同路径。美国版权局与联邦法院在 Thaler v Perlmutter 系列程序中坚持人类作者身份是版权保护的基本要求，主张纯由 AI 生成的成果不受保护；该立场在2023年的地区法院判决及后续上诉中得到维持。中国著作权法把作者限定为自然人、法人或非法人组织，AI 本身不能成为著作权法上的作者；但人借助 AI 生成的内容，若体现人的智力投入与独创性，仍可能被认定为作品。欧盟《数字单一市场版权指令》则重点处理文本与数据挖掘例外、在线内容共享平台的责任等问题，为 AI 训练数据的使用提供了讨论框架。这些差异说明，技术问题往往被既有法律概念体系所塑造；同一技术在不同法域会得到不同评价。", "comparison": "数字知识产权可以用前几节的理论框架来定位。从哈特的规则理论看，著作权法中的作者定义、保护期限与例外条款构成初级规则，而权利登记、许可与救济制度则发挥次级规则功能；AI 挑战的正是『作者』这一核心概念的可适用性。从德沃金的权利理论看，作者人格权与财产权的区分，体现了对个体人格利益的尊重；但读者获取知识与参与文化的权利同样具有原则分量，须在解释中加以协调。从法律现实主义看，在判断『独创性』『转换性使用』时，法官的实际判断空间很大，技术事实的描述方式会影响结论。从法治理论看，数字版权规则须在明确性与适应性之间取得平衡：规则过细会迅速过时，规则过粗又会使权利人和使用者都无从预期。", "debates": "第一场争论是 AI 生成物是否可版权。反对赋予保护者认为，模型输出缺乏人类作者的人格与智力投入，且权利主体难以确定；支持者认为，只要使用者在设计提示、调整参数、筛选结果中作出实质性选择，成果就体现人的独创性，应受保护。争论背后是对『创作』概念的不同理解。第二场争论是训练数据使用的合法性。一方认为大规模抓取受保护作品训练模型构成未经许可的使用；另一方认为训练是分析与学习而非表达性复制，且将数据挖掘例外纳入制度更有利于创新。第三场争论是权利扩张与公共领域的平衡：技术保护措施与邻接权的扩张可能压缩公众合理使用的空间，而过度宽松的使用规则又可能削弱创作激励。这些争论尚未有统一答案，但都要求把技术事实还原为规范问题。", "case": "北京互联网法院于2023年11月27日对李某诉刘某案作出一审判决，这是中国首例『AI 文生图』著作权侵权案，双方均未上诉。案件事实是：李某使用 AI 绘画软件，通过设计人物呈现方式、设定并调整提示词顺序、设置和修改参数、从生成结果中选定图片等过程，创作了古风女子画像并标注『AI 插画』发布；刘某在文章中使用该图片，且抹去了署名水印。争议焦点是：利用 AI 生成的图片能否构成作品，以及使用者是否享有著作权。法院认定，涉案图片以线条、色彩构成，具有审美意义；李某在生成过程中体现了智力投入与个性化选择，满足『智力成果』与『独创性』要件，因而构成作品。被告侵害了李某的署名权与信息网络传播权，被判赔礼道歉并赔偿500元。", "caseAnalysis": "本案的事实要点在于，图像虽由模型生成，但人与模型之间存在多轮互动与选择。争点不在『图是不是 AI 画的』，而在『人在这张图里做了什么』。法律依据是著作权法关于作品构成与作者资格的规定；法院明确表示，AI 模型本身不是法律主体，不能成为作者。裁判理由的关键，是把提示设计、参数调整与结果筛选理解为创作过程中的智力投入。理论意义有三。其一，它把可版权性的判断从工具转向过程，避免了『凡 AI 生成皆不保护』或『凡人参与皆保护』两种极端。其二，它与美国的 Thaler 案形成对照：后者否认纯 AI 生成成果的作者身份，两者其实共享一个前提——作者须有人类参与，分歧在于参与达到何种程度才算创作。其三，它留下新的问题：提示词本身是思想还是表达、相同提示下结果不可复现时如何证明因果关系，仍有待后续案件回答。", "summary": "数字时代的知识产权争论，集中在作者身份、客体边界与权利限制三个层面。AI 生成物迫使法学重新追问独创性与人格投入的含义；训练数据引发使用与侵权的界分；技术保护措施与例外制度则关系到公共领域的存亡。美国 Thaler 案坚持人类作者身份，中国北京互联网法院的李某案则把人的实质性选择纳入创作判断，两者均反映出既有概念体系的韧性。用哈特的规则理论、德沃金的权利命题与现实主义的判断理论观察，可以看到这些判决不仅在处理技术争议，也在重新界定创作、人格与公共利益的关系。知识产权制度能否在激励创新与保障获取之间维持平衡，将取决于这些概念能否被持续解释与发展。", "furtherThinking": "1. 若使用者只输入一句简单提示便获得高质量图像，按照本案的判断标准，应当认定缺乏独创性吗？提示词数量的多寡是不是合适的判断标准？\n2. 把模型训练界定为『学习』还是『复制』，会导致截然不同的法律结论。这种界定背后隐藏了哪些价值判断？\n3. 技术保护措施与合理使用规则发生冲突时，应当优先保护权利人的控制能力，还是公众接近知识的利益？"}, "en": "Intellectual Property in the Digital Age", "level": "core", "tags": "知识产权, 著作权, 人工智能生成物, 独创性, 公共领域", "source": "Wacks, Understanding Jurisprudence, ch.10；Beijing Internet Court, Li v Liu, 27 Nov 2023；Thaler v Perlmutter (D.D.C. 2023, aff’d D.C. Cir. 2025)；Directive (EU) 2019/790 (Digital Single Market Copyright Directive)；WIPO Copyright Treaty (1996)", "id": "S3M5K4"}, "S3M5K5": {"title": "国际人权法", "EN": "International Human Rights Law", "LEVEL": "core", "TAGS": "国际人权法, 人权, 主权, 世界人权宣言, 国际法院", "TERMS": "人权（Human Rights）::人因其为人而应享有的基本权利与自由；国际人权法（International Human Rights Law）::由条约、习惯与国际组织实践构成的保护人权的国际法分支；普遍主义（Universalism）::主张人权标准跨文化普遍适用的立场；文化相对主义（Cultural Relativism）::主张人权应依具体文化传统理解的立场；保留（Reservation）::缔约国在批准条约时对特定条款提出的排除或变更声明；对一切义务（Obligations Erga Omnes）::国际社会对整体承担、涉及全体国际成员利益的义务；条约机构（Treaty Body）::监督缔约国履行人权条约的专家委员会；人道主义干预（Humanitarian Intervention）::为制止大规模人道灾难而跨境使用武力的主张", "SOURCE": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Universal Declaration of Human Rights (1948)；ICCPR and ICESCR (1966)；Rome Statute of the International Criminal Court (1998)；ICJ, Barcelona Traction Case (1970)", "terms": [{"term": "人权（Human Rights）", "def": "人因其为人而应享有的基本权利与自由"}, {"term": "国际人权法（International Human Rights Law）", "def": "由条约、习惯与国际组织实践构成的保护人权的国际法分支"}, {"term": "普遍主义（Universalism）", "def": "主张人权标准跨文化普遍适用的立场"}, {"term": "文化相对主义（Cultural Relativism）", "def": "主张人权应依具体文化传统理解的立场"}, {"term": "保留（Reservation）", "def": "缔约国在批准条约时对特定条款提出的排除或变更声明"}, {"term": "对一切义务（Obligations Erga Omnes）", "def": "国际社会对整体承担、涉及全体国际成员利益的义务"}, {"term": "条约机构（Treaty Body）", "def": "监督缔约国履行人权条约的专家委员会"}, {"term": "人道主义干预（Humanitarian Intervention）", "def": "为制止大规模人道灾难而跨境使用武力的主张"}], "sections": {"coreQuestion": "国际人权法同时承诺两件难以兼容的事：权利属于每一个人，而法律主要由主权国家制定与执行。如果人权具有普遍性，一国能否以文化传统为由拒绝某些标准？如果人权条约只是国家同意的产物，它凭什么约束不同意其内容的政权？此外，国际人权机制缺少国内法那样的强制执行机关，其有效性应如何评价？本节以《世界人权宣言》与联合国人权条约体系为线索，讨论国际人权法的规范基础、制度结构与核心争论，并用国际法院的一个判例说明权利义务如何突破纯粹的双边框架。", "definition": "人权指人因其为人而应享有的基本权利与自由，通常包括生命权、自由权、平等权、言论与宗教自由，以及经济、社会与文化方面的权利。国际人权法由国际条约、习惯国际法、国际组织决议与司法判例构成，主要保护个人与群体免受国家权力的侵害，并逐步要求国家采取积极措施实现权利。公民与政治权利（如言论自由、公正审判）通常对应国家的尊重与不作干预义务；经济、社会与文化权利（如健康、教育、社会保障）更多要求国家逐步实现与投入资源。保留是缔约国在批准条约时对某些条款提出的排除或变更，它体现主权同意，也可能削弱条约的统一性。对一切义务指某些义务朝向国际社会整体，所有国家对其履行都具有法律利益。", "history": "现代国际人权法的形成与二战直接相关。纽伦堡审判确立了某些行为构成『反人类罪』，即便它们符合当时国内实证法的形式，这表明法律并非判定对错的唯一尺度。1945年《联合国宪章》把尊重基本人权列为宗旨之一；1948年联合国大会通过《世界人权宣言》。值得注意的是，Wacks 指出宣言把自己表述为『共同的成就标准』，而非宪法意义上可直接推翻普通法的高级法，这体现了一种审慎的定位。1966年联合国通过《公民权利和政治权利国际公约》与《经济、社会及文化权利国际公约》，两者于1976年生效；此后又有1979年《消除对妇女一切形式歧视公约》与1989年《儿童权利公约》。1993年维也纳世界人权会议重申人权的普遍性，1998年《国际刑事法院罗马规约》通过，2002年生效。", "principle": "国际人权法的逻辑可从三层理解。第一层是规范基础。自然法取向把人权视为人之所以为人的尊严要求，其效力不依赖国家同意；法律实证主义取向则强调人权法的效力来自条约、习惯与一般法律原则，须以国家同意或国际社会的法律确信为基础。第二层是义务结构。人权义务传统上被理解为消极的尊重义务，后来扩展为保护与实现义务，要求国家防止第三方侵害并积极提供制度与资源。这种扩展使权利从『不要干涉』走向『要采取措施』，也带来能力差异与资源分配问题。第三层是执行机制。条约机构审议缔约国报告并发表结论性意见，部分公约设有个人申诉程序，国际刑事法院对特定个人追究刑事责任，国际法院处理国家间争端。这些机制缺少国内警察与法院那样的强制力，其效果依赖声誉压力、国际合作与国内法的转化。", "viewpoints": "国际人权法理论中的主要立场可概括如下。普遍主义主张，某些最低限度的人权标准对所有文化与社会都有效，文化差异不能成为系统性剥夺权利的借口。文化相对主义则强调权利概念的历史与文化嵌入性，警惕以人权为名输出特定社会的价值。Wacks 在讨论自然法复兴时提到，现代人权文件常把权利表述为『共同的成就标准』，这既承认超越实定法的道德尺度，也避免把自然法直接等同于可以推翻一切国内法的高级法。在法律实证主义看来，人权的法律性最终来自国际法渊源与国家的接受；德沃金式的权利理论则强调权利对集体目标的优先性，并要求把平等视为权利的核心。批判理论则提醒，人权话语也可能与权力运作交织，成为干预或合法化的工具。", "comparison": "把国际人权法与本课程前面的理论对接，可以获得更清晰的位置感。自然法传统为人权提供了超越国家的道德基础，其弱点是难以说明谁有权确定具体内容。法律实证主义强调人权法的制度来源，有助于确认哪些权利具有法律约束力，却难以解释人权的道德号召力。德沃金把权利理解为『王牌』，有助于说明为何多数决定不能随意牺牲少数人的基本自由，但其理论以稳定共同体为前提，在多元国际社会中适用需要调整。法律现实主义与批判理论则提示，人权判断受裁判者对社会事实的把握影响，国际机制的选择本身也体现权力分配。这些视角并不互斥，它们分别回答人权『为何正当』『何时有效』与『如何运作』的问题。", "debates": "第一场争论是普遍主义与文化相对主义。普遍主义者指出，若接受相对主义，严重侵害行为就可能获得文化辩解；相对主义者回应，人权清单本身带有特定历史印记，强行统一会抹杀多样的生活方式。较温和的立场主张『最低限度普遍主义』：在核心底线问题上坚持普遍标准，在实现路径上允许文化差异。第二场争论是公民政治权利与经济社会权利的优先性。前者强调自由与参与，后者强调生存条件与实质平等；冷战时期二者一度被分置于不同公约，此后主流意见转向承认两类权利相互依存。第三场争论是人道主义干预与不干涉内政。支持干预者以大规模暴行为由主张国际社会的保护责任，反对者担心干预被滥用为霸权工具。Wacks 指出，国际刑事法院的设立标志着战后对『国家所犯重大不义不应不受惩罚』的承认，但如何追究仍然充满争议。", "case": "国际法院在 Barcelona Traction, Light and Power Company 案（1970年）中提出了一个影响深远的区分。案件涉及一家在加拿大注册、在西班牙经营的公司，其比利时股东主张西班牙的行为违反了国际法。国际法院在判决中区分了国家仅对个别他国承担的义务与『对一切义务』（obligations erga omnes），指出后者由于所涉及价值的重要性，所有国家都可主张其履行。法院列举的例子包括禁止侵略、灭绝种族、奴隶制与种族歧视。这一判决把人权保护从双边外交保护的结构中部分解放出来，说明某些义务关涉国际社会整体利益。这里叙述的是国际法院的判决要旨，未涉及任何具体国家责任的最终认定。", "caseAnalysis": "就 Barcelona Traction 案而言，事实层面是国家对公司及其股东的保护争端，法律争点则是义务的相对性：某国侵害另一国国民时，第三国是否有法律利益。国际法院的裁判理由基于某些价值的根本性，把它们归入对一切义务，从而突破了义务只在特定国家之间存在的传统图景。理论意义有三。其一，它为人权义务的『对世性』提供了司法表述，使国际社会整体成为利益的持有者。其二，它显示国际法中的权利义务结构可以超越国家同意的双边框架，这为普遍人权观念提供了法律技术上的支撑。其三，它也留下难题：谁有权代表国际社会主张这类义务、主张的程序为何，判决并未完全回答。把这些与纽伦堡原则、《世界人权宣言》的『共同成就标准』并置，可以看到国际人权法在道德号召与法律可执行性之间持续寻求平衡。", "summary": "国际人权法建立在一种张力之上：它主张权利属于所有人，却必须经由国家同意与国际机制来运作。其规范基础可诉诸自然法的尊严命题或实证主义的条约与习惯；其义务结构从消极尊重扩展到保护与实现；其执行依靠条约机构、个人申诉、国际法院与国际刑事法院，但强制力有限。普遍主义与相对主义、公民政治权利与经济社会权利、人道主义干预与不干涉内政，构成三场持续争论。国际法院在 Barcelona Traction 案中提出的对一切义务，为某些人权价值的特殊性提供了法律表达。理解国际人权法，需要在道德理想与法律技术之间来回切换，并始终追问：谁在主张权利，谁承担义务，谁有权作出有约束力的判断。", "furtherThinking": "1. 若在核心底线问题上坚持最低限度普遍主义，应当如何确定哪些权利属于『底线』？这个确定过程本身是否不可避免地带有文化偏向？\n2. 国际人权条约缺乏国内法意义上的强制执行机关，这是否意味着它们只是道德宣示？其有效性应当用什么标准衡量？\n3. 对一切义务使所有国家对某些侵害拥有法律利益，这种结构会不会与国际秩序中的权力不平等相互作用，选择性启动追责？"}, "en": "International Human Rights Law", "level": "core", "tags": "国际人权法, 人权, 主权, 世界人权宣言, 国际法院", "source": "Wacks, Understanding Jurisprudence, ch.2, ch.10；Universal Declaration of Human Rights (1948)；ICCPR and ICESCR (1966)；Rome Statute of the International Criminal Court (1998)；ICJ, Barcelona Traction Case (1970)", "id": "S3M5K5"}, "S3M5K6": {"title": "全球化与法律秩序", "EN": "Globalization and Legal Order", "LEVEL": "core", "TAGS": "全球化, 全球治理, 法律多元主义, 域外管辖, 国际法", "TERMS": "全球化（Globalization）::人员、资本、信息与风险跨越国界流动并相互依存的过程；全球治理（Global Governance）::国家、国际组织与私人主体共同制定与执行跨国规则的机制；法律多元主义（Legal Pluralism）::一个社会场域中多种法律或规范体系并存并相互作用的现象；域外管辖（Extraterritoriality）::一国法律对其领土之外的人或事主张适用；冲突法（Conflict of Laws）::处理涉外案件应适用何地法律与何地法院的规则体系；跨国法（Transnational Law）::调整跨越国界活动的规范总和，兼含公私法要素；软法（Soft Law）::不具严格法律拘束力却具有规范影响力的国际标准与准则；主权（Sovereignty）::国家在其领土内享有最高权威且独立于外部权力的地位", "SOURCE": "Wacks, Understanding Jurisprudence, ch.7, ch.10；Siems, Comparative Law, Introduction；Regulation (EU) 2016/679 (GDPR), Art.3；Case C-311/18 Schrems II (2020)；WTO Agreement (1994)", "terms": [{"term": "全球化（Globalization）", "def": "人员、资本、信息与风险跨越国界流动并相互依存的过程"}, {"term": "全球治理（Global Governance）", "def": "国家、国际组织与私人主体共同制定与执行跨国规则的机制"}, {"term": "法律多元主义（Legal Pluralism）", "def": "一个社会场域中多种法律或规范体系并存并相互作用的现象"}, {"term": "域外管辖（Extraterritoriality）", "def": "一国法律对其领土之外的人或事主张适用"}, {"term": "冲突法（Conflict of Laws）", "def": "处理涉外案件应适用何地法律与何地法院的规则体系"}, {"term": "跨国法（Transnational Law）", "def": "调整跨越国界活动的规范总和，兼含公私法要素"}, {"term": "软法（Soft Law）", "def": "不具严格法律拘束力却具有规范影响力的国际标准与准则"}, {"term": "主权（Sovereignty）", "def": "国家在其领土内享有最高权威且独立于外部权力的地位"}], "sections": {"coreQuestion": "现代法理学长期以民族国家为基本单位：法律由主权者制定，在一国领土内有效，由国家机关执行。全球化使这一图像变得复杂。资本、数据、人员与环境风险跨越边界，规则却仍以国家为单元制定；一项行为可能同时受到多个法域的评价，而其中一些法域对该行为并无领土关联。本节要回答：全球法律秩序是否正在形成，它采取何种形态；当不同法域的规则冲突时，法律如何协调；以及这种协调的民主正当性与法治品质如何评价。", "definition": "全球化指人员、资本、信息与风险跨越国界流动并形成相互依存的过程。全球治理指国家、国际组织、非政府组织与私人主体共同参与跨国规则制定与执行的机制，它比『世界政府』松散得多。法律多元主义描述一个社会场域中多种法律或规范体系并存并相互作用的状态，在国内法与国际法的交界处尤为明显。域外管辖指一国法律主张适用于其领土之外的人或事，例如对境外处理本国公民数据的行为提出要求。冲突法处理涉外案件应适用何地法律、由何地法院审理的问题。软法则指不具严格拘束力却产生实际规范影响的国际标准、准则与建议。这些概念共同指出一个事实：法律秩序的边界已经无法与领土边界简单重合。", "history": "现代国际法律秩序在二战后加速制度化：联合国与一系列专门机构建立，1948年《世界人权宣言》通过，1994年世界贸易组织随着乌拉圭回合成果成立，其协定涵盖了从关税到知识产权的广泛领域。欧洲一体化则提供了更深层的例证：欧盟法律在成员国境内具有优先适用性，形成了一种超越传统国际法的法律秩序。互联网与数字平台使数据流动成为常态，各国纷纷把保护性规则延伸到境外主体，例如 GDPR 对向欧盟境内个人提供商品或服务、以及监测其行为的境外处理者主张适用。进入2020年代，地缘竞争与供应链重组又带来『去全球化』的讨论，说明全球法律秩序并非单向扩张的过程。", "principle": "全球化对法律秩序的挑战可以从三层理解。第一层是空间重构。传统法律以领土为界，而全球治理按功能组织：贸易、环境、卫生、网络空间各有自己的规则网络。功能秩序与领土秩序并不重合，由此产生管辖权重叠与规范冲突。第二层是冲突协调。冲突法提供选择适用法律的技术，条约与国际组织提供协商平台，软法提供柔性标准，而相互承认与最低限度协调则减少制度摩擦。需要指出的是，冲突的解决往往依赖权力对比，技术性规则背后有利益分配。第三层是正当性。全球规则的制定者未必是民选机关，受规则影响的人也未必有参与渠道，这形成所谓的民主赤字。法治要求公开、可预期与可问责，这些要求在跨国层面比国内层面更难实现。", "viewpoints": "关于全球法律秩序，主要存在几种视角。全球治理理论强调国家之外的多元主体，认为规则制定已从单一国家中心转向网络化的合作。法律多元主义则提醒，不同规范体系在同一场域并存，个体可能在多个秩序中同时承担义务。主权论者强调国家同意仍是国际法效力的基础，担心超国家规则削弱民主问责。比较法学者如西姆斯（Siems）指出，法律家族之间的趋同与分歧并存，法律移植的效果取决于制度环境，不能仅靠文本复制。Wacks 在讨论法律与社会理论时强调，对法律的理解不能脱离其社会条件；在全球层面，这意味着要注意规则所嵌入的权力结构。哈特的承认规则在跨国场景中呈现出分散状态：不同体系各有自己的有效性判准，且彼此之间缺乏终极仲裁者。", "comparison": "全球法律秩序可以用本课程的理论资源重新审视。从哈特的规则理论看，国际法与国内法的差别在于前者缺少统一的承认规则与强制执行机关；全球化使这一差别更加突出，因为有效的规则网络往往是非正式的。从富勒的内在道德看，全球软法在公开性与一般性上可能合格，在官方行为与规则一致性上却难以检验，因为不存在统一的执行机构。从德沃金的整体性看，跨越不同共同体的法律实践能否被纳入同一套解释性原则，是大可怀疑的；这提示全球法治需要承认多元而非强求统一。从法律现实主义看，跨国案件的结果高度依赖法院对外国法律与社会事实的理解，形式规则的作用有限。法治理论在全球层面则面临一个根本问题：当规则、裁判与执行分属不同体系时，可预期性从何而来。", "debates": "第一场争论是全球法律趋同与多元共存。趋同论者认为，贸易、人权与环境标准会逐步收敛，形成共同的法治语言；多元论者认为，法律规则深嵌于本土制度与文化，简单趋同既不现实也可能导致制度霸权。第二场争论是域外管辖的正当性。支持者认为，若一国允许境外主体损害其基本权利却不管辖，法律保护就会落空；反对者认为，过度域外适用会侵犯他国主权，造成管辖冲突。第三场争论是全球治理的民主赤字：国际组织与专家委员会制定的规则缺乏直接民主授权，其正当性只能来自国家同意或技术专业性，这两种来源都不足以回应受影响者的参与诉求。Wacks 所强调的法律与政治权力的交织，在跨国层面表现得尤其明显。", "case": "欧洲法院2020年7月16日判决的 Schrems II 案（Case C-311/18）提供了全球法律秩序冲突的清晰样本。案件事实是：一名奥地利活动人士质疑把个人数据从欧盟传输到美国，理由是美国公共机关基于国家安全理由获取数据的法律与欧盟保护水平不相称。争议焦点是：在缺乏充分性决定的情况下，标准合同条款能否支撑跨境传输，以及欧盟—美国隐私盾是否提供充分保护。法院维持了标准合同条款的有效性，但要求逐案评估目的国的法律与实践；同时宣告欧盟委员会关于隐私盾的充分性决定无效。本案的典型意义在于：欧盟以个人信息保护为理由，对发生在境外、由外国公权力实施的行为作出法律评价，其效果突破了传统领土管辖的框架。", "caseAnalysis": "就 Schrems II 案而言，事实层面是跨大西洋数据流动与外国监控法律的冲突；争点在于欧盟能否以自身基本权利标准评判第三国的法律环境。法律依据包括 GDPR 关于跨境传输的规则与《欧盟基本权利宪章》。裁判理由的关键，是把『充分保护』理解为不仅取决于合同条款，也取决于目的国法律是否允许政府进行不相称的干预，以及是否存在有效救济。理论意义有三。其一，它显示法律秩序的域外延伸通过市场准入与合规要求实现，武力手段已退居幕后。其二，它揭示全球秩序中规范冲突的制度形态：多套法律同时主张适用性，形成一种规范竞争而非法律真空的状态。其三，它暴露了正当性问题：欧盟法院以保护欧盟公民为职责，其判断如何影响第三国的法律政策，缺少相应的民主协商机制。全球化条件下的法治，因此需要在效力冲突之外处理代表性与问责问题。", "summary": "全球化把法律从领土国家有限的秩序中释放出来，形成国家、国际组织与私人主体共同参与的多元治理格局。全球治理、法律多元主义、域外管辖与软法等概念，描述了这一格局的运作方式。冲突法、条约与协调机制提供了技术性应对，但规则的制定与执行仍受权力结构影响，民主赤字与法治品质成为核心难题。用哈特、富勒、德沃金与现实主义的理论加以审视，可以看到全球层面的承认规则分散、内在道德难以检验、整体性解释难以跨共同体展开。Schrems II 案说明，全球法律秩序的冲突往往以数据保护、市场准入等形式出现。理解全球化与法律秩序，需要在规范技术与政治正当性之间保持双重敏感。", "furtherThinking": "1. 当一国以基本权利为由对境外行为主张管辖时，这种域外适用是法治的延伸，还是新的法律帝国主义？判断标准应是什么？\n2. 全球软法不具备严格拘束力，却深刻影响国家与企业行为。应当如何评价这类规范的『法律性』？\n3. 在多种法律体系并存且缺乏终极仲裁者的情况下，哈特的承认规则理论还能否描述一个统一的全球法律秩序？"}, "en": "Globalization and Legal Order", "level": "core", "tags": "全球化, 全球治理, 法律多元主义, 域外管辖, 国际法", "source": "Wacks, Understanding Jurisprudence, ch.7, ch.10；Siems, Comparative Law, Introduction；Regulation (EU) 2016/679 (GDPR), Art.3；Case C-311/18 Schrems II (2020)；WTO Agreement (1994)", "id": "S3M5K6"}}, "questions": {"S1M1K1": {"lesson": "S1M1K1", "questions": [{"order": 1, "qtype": "single", "stem": "根据哈特在《法律的概念》中的观点，法律的核心是什么？", "options": ["A 主权者以制裁为后盾的命令", "B 初级规则与次级规则的结合", "C 实现正义的理性秩序", "D 法官实际做出的判决"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特在批判奥斯丁命令理论的基础上提出，法律的中心是初级规则与次级规则的结合。【逐步演示】初级规则直接规定行为，次级规则规定如何识别、改变、裁判初级规则，二者结合才构成法律体系。【易错提醒】A 是奥斯丁的命令理论，C 接近自然法，D 接近法律现实主义，均非哈特的核心主张。"}, {"order": 2, "qtype": "single", "stem": "下列哪一项最能体现法律的『规范性』（Normativity）？", "options": ["A 描述昨天发生的事件", "B 规定『不得闯红灯』并以『应当』指引行为", "C 统计交通事故的数量", "D 记录历史天气数据"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】规范性指规则以『应当』的形式指引行为，并可引发批评或制裁。【逐步演示】描述（A、C、D）只说明事实是什么，规范则规定应当如何。【易错提醒】不要把『描述事实』与『规定应当』混淆，这是理解法律性质的第一步。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，威胁能够让人『不得不』做某事，因此也能产生『有义务』做的规范体验。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确指出，威胁只能使人『不得不』（obliged）做，不能产生『有义务』（obligation）的规范体验。【逐步演示】这是他批判奥斯丁命令理论的关键论据：抢匪的威胁与法律的义务在性质上不同。【易错提醒】obliged 与 obligation 的区分是哈特理论的经典考点。"}, {"order": 4, "qtype": "blank", "stem": "奥斯丁把法律界定为主权者发布的、以______为后盾的命令。", "options": [], "answer": "", "accepted": ["制裁", "惩罚", "sanction", "威胁", "强制力"], "keywords": [], "explanation": "【答案】制裁（Sanction）。【解题思路】奥斯丁的命令理论三要素为：命令、主权者、制裁。【逐步演示】法律＝主权者的命令＋以制裁为后盾。【易错提醒】『制裁』在其理论中是核心要件，不要答成『道德』或『共识』。"}, {"order": 5, "qtype": "single", "stem": "『恶法非法』（lex iniusta non est lex）这一命题最接近于哪一学派？", "options": ["A 法律实证主义", "B 自然法理论", "C 法律现实主义", "D 分析法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】『恶法非法』主张严重违背正义的规则不是真正的法律，体现法律与道德的必然联系。【逐步演示】这是自然法理论的核心命题，二战后常用于批判纳粹法律。【易错提醒】实证主义主张相反的『恶法亦法』（在效力意义上），注意区分。"}, {"order": 6, "qtype": "single", "stem": "英国没有成文宪法典却仍被认为有宪法，这一事实主要说明：", "options": ["A 法律必须由立法机关制定", "B 法律的边界并非泾渭分明，惯例也可具规范性", "C 不成文的规则都不是法律", "D 宪法必须是单一文件"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】英国宪法的例子说明法律与非法定的社会规范之间存在中间地带。【逐步演示】宪法惯例虽无严格法律制裁，却被内部观点接受为行为标准。【易错提醒】不要误以为『法律＝成文＋法院执行』，这个定义过于狭窄。"}, {"order": 7, "qtype": "multi", "stem": "根据本节内容，下列哪些属于法律的基本特征？", "options": ["A 规范性", "B 制度性", "C 以国家强制力为后盾", "D 必然与道德完全一致"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律具有规范性、制度性、强制性，以及内外两种观点。【逐步演示】D 不成立，因为实证主义强调法律与道德可以分离。【易错提醒】多选慎选『必然』『完全一致』这类绝对化表述。"}, {"order": 8, "qtype": "single", "stem": "霍姆斯『法律的生命不在逻辑，而在经验』这句话最贴近哪一立场？", "options": ["A 自然法理论", "B 法律现实主义", "C 纯粹法学", "D 概念法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】这句话强调经验与现实对法律的决定作用，是美国法律现实主义的标志性表述。【逐步演示】现实主义关注『行动中的法』而非『书本上的法』。【易错提醒】霍尔斯（Holmes）此处拼写作 Oliver Wendell Holmes Jr.，勿与其他学者混淆。"}, {"order": 9, "qtype": "essay", "stem": "试论『法律与道德分离命题』的真正含义，并说明为何把两者分开反而有助于批判恶法。", "options": [], "answer": "", "accepted": [], "keywords": [["区分效力与正当性", "是不是法律与道不道德分开判断"], ["承认恶法是法律", "有效力"], ["更有理由抵抗", "道德批判更清醒"], ["反对漫画化", "并非主张法律无需道德"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先澄清分离命题的准确含义，再说明其批判价值。【逐步演示】第一步区分『效力问题』与『道德评价问题』；第二步指出承认恶法为法不等于赞许它；第三步说明这使抵抗更有针对性。【易错提醒】不要把实证主义漫画化为『法律不需要道德』。"}, {"order": 10, "qtype": "judge", "stem": "按照 Wacks 的看法，找到一个对所有目的都同样适用的『法律』本质定义，是法理学的首要任务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 认为任何定义都服务于特定理论目的，不存在唯一正确的法律本质。【逐步演示】重要的不是找到唯一定义，而是理解每种定义突出了法律的哪个面向。【易错提醒】这体现了 Wacks 对法律理论『目的 relativity』的强调。"}, {"order": 11, "qtype": "single", "stem": "从『内部观点』看，法律主要被理解为：", "options": ["A 被接受的行为理由与评价标准", "B 会被制裁的外部规律", "C 法官的个人偏好", "D 纯粹的文字游戏"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】内部观点指参与者把规则当作正当的行为理由来接受和使用。【逐步演示】官员与公民用法律来证成决定、批评他人。【易错提醒】B 是外部观点，注意区分哈特的两种观点。"}, {"order": 12, "qtype": "essay", "stem": "结合英国宪法的例子，分析为什么说『法律＝国家制定的成文规则』这一定义是不完整的。", "options": [], "answer": "", "accepted": [], "keywords": [["英国无成文宪法典", "仍有宪法"], ["宪法惯例", "constitutional conventions"], ["内部观点接受", "具规范性"], ["边界模糊", "法律与-social规范中间地带"]], "explanation": "【答案要点】见 keywords。【解题思路】以英国宪法为切口，指出定义法的核心困难。【逐步演示】事实：无单一宪法文件；争论：惯例是否算法律；分析：惯例被内部观点接受；结论：法律边界开放。【易错提醒】不要简单断言惯例『就是法律』或『都不是法律』。"}]}, "S1M1K2": {"lesson": "S1M1K2", "questions": [{"order": 1, "qtype": "single", "stem": "哈特在 1957 年霍姆斯讲座中提出的『分离命题』，其准确含义是：", "options": ["A 法律在内容上不必与道德有任何重合", "B 一条规则是否为法律取决于其社会来源，而非其道德价值", "C 法官在裁判时不得考虑任何道德因素", "D 恶法因为不道德而自动失效"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】分离命题针对的是法律的识别标准，主张『是不是法律』取决于来源而非道德。【逐步演示】哈特的表述是法律与道德之间『不存在必然联系』，即道德价值不是法律效力的必要条件。【易错提醒】A 把分离命题漫画化为『法律与道德毫无关系』，C 把效力问题误作裁判方法问题，D 是自然法的立场而非哈特的立场。"}, {"order": 2, "qtype": "single", "stem": "富勒在《法律道德性》（The Morality of Law）中提出的『内在道德』（inner morality of law）主要属于哪一进路？", "options": ["A 实体自然法", "B 程序自然法", "C 法律现实主义", "D 纯粹法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】富勒不诉诸高于国家法律的实体价值，而是从法律作为规则治理事业的程序条件中推出八项要求，故为程序自然法。【逐步演示】一般性、公布、不溯及既往、明确、不矛盾、可行性、稳定性、官方行为与规则一致，这八项都属于形式与程序标准。【易错提醒】富勒反对的是奥斯丁式的实体高阶法设定，不要把他与菲尼斯的实体自然法混同。"}, {"order": 3, "qtype": "judge", "stem": "分离命题意味着：一项法律只要制定程序合法，即便其内容极端不道德，我们在概念上仍应承认它是法律。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这正是哈特在告密者案讨论中的立场：承认纳粹法律是有效法律，不妨碍我们谴责它。【逐步演示】区分效力判断与道德评价，是分离命题的核心操作。【易错提醒】承认它是法律不等于服从它；把它说成『不是法律』反而遮蔽了恶以法律名义发生的事实。"}, {"order": 4, "qtype": "blank", "stem": "自然法传统中表达『严重不正义的规则不成其为法』的拉丁格言是『______』。", "options": [], "answer": "", "accepted": ["lex iniusta non est lex", "恶法非法", "lex iniusta", "不正义的法律不是法律"], "keywords": [], "explanation": "【答案】lex iniusta non est lex（恶法非法）。【解题思路】该格言是自然法理论最凝练的表达，也可说成『不正义的法律不是法律』。【逐步演示】Wacks 指出，阿奎那认为人法若背离理性与共同善，就不再具有法的品格。【易错提醒】不要写成『恶法亦法』，后者是实证主义在效力意义上的主张。"}, {"order": 5, "qtype": "single", "stem": "哈特—富勒论战（1957—1958）的直接导火索是下列哪一案件？", "options": ["A 英国沃尔芬登委员会报告所涉的同性行为非罪化问题", "B 战后西德法院审理的妻子检举丈夫案", "C 美国洞穴探险者案的虚构裁判", "D 南非种族隔离制度的合宪性审查"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】论战焦点是战后西德法院对一名妻子的审判：她 1944 年向盖世太保检举丈夫，1949 年因致使丈夫失去自由被追诉。【逐步演示】争议在于那项 1934 年纳粹法律是否仍是有效法律；哈特说是，富勒说不是。【易错提醒】A 是哈特—德夫林论战的导火索，C 是富勒的虚构案例，D 只是双方讨论中举出的反例。"}, {"order": 6, "qtype": "multi", "stem": "下列哪些属于富勒『法律的内在道德』所要求的八项标准？", "options": ["A 一般性（Generality）", "B 不溯及既往（Non-retroactivity）", "C 官方行为与宣布的规则相一致（Congruence）", "D 法律内容必须符合神学教义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】富勒的八项 desiderata 是程序性的，涵盖一般性、公布、不溯及既往、明确、不矛盾、可行性、稳定性、官行与规则一致。【逐步演示】这八项来自『雷克斯王』失败的故事，是法律作为规则治理事业的形式条件。【易错提醒】D 不是富勒的要求；他的进路是程序自然法，并不要求特定实体教义。"}, {"order": 7, "qtype": "judge", "stem": "在哈特—富勒论战中，哈特主张 1934 年纳粹法律因违背承认规则而自始无效。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特的主张恰好相反：1934 年纳粹法律符合承认规则，因而是有效法律。【逐步演示】哈特认为法院以『违背健全良知』为由否定其效力是错误的，正确做法是承认其有效但极端邪恶，并尽可能通过明确立法处理。【易错提醒】把哈特与富勒的立场记反，是本题最常见的错误。"}, {"order": 8, "qtype": "single", "stem": "德夫林勋爵在 1959 年讲座中反驳沃尔芬登报告时，用来判断行为是否应受刑罚的标准是：", "options": ["A 是否造成可识别的伤害", "B 是否属于陪审团席上的人（the man in the jury box）所认为的严重不道德", "C 是否违反宪法基本权利", "D 是否得到经济学上的效率证明"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德夫林主张社会靠共享道德维系，判断标准是普通社会成员的道德反感。【逐步演示】他甚至认为伤害与否并不重要，道德纽带松弛本身就是社会解体的征兆。【易错提醒】A 是哈特所倚重的密尔式伤害原则；把两者对调是典型失误。"}, {"order": 9, "qtype": "single", "stem": "哈特对德夫林的核心反驳是：", "options": ["A 社会必须依靠单一共享道德才能生存", "B 多元社会未必需要共享道德，且保护共享道德并非社会生存的必要条件", "C 一切不道德行为都应当犯罪化", "D 法律与道德在概念上完全同一"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特质疑德夫林『社会解体论』的经验前提：多元社会可以容纳多种道德观。【逐步演示】他同时承认法律可有家长主义空间，并区分公开行为造成的冒犯与仅因知悉而产生的反感。【易错提醒】哈特并未全盘否定法律与道德的联系，更未主张一切不道德行为都应入罪。"}, {"order": 10, "qtype": "judge", "stem": "哈特否认法律与道德之间存在任何必然联系，因此他反对把道德原则纳入法律，也不承认法律有最低限度的自然法要求。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特承认法律与道德在目的、正义、效力承认等多方面存在连接，也承认最低限度的自然法。【逐步演示】他承认道德原则可通过承认规则被纳入法律体系；他反对的是把道德价值当作法律效力的普遍必要条件。【易错提醒】把哈特漫画化为『法律与道德无关』是最常见的误读。"}, {"order": 11, "qtype": "multi", "stem": "按照 Green 对哈特理论的梳理，下列哪些属于哈特后期承认的法律与道德之间的连接点？", "options": ["A 法律以人类生存为其目的之一（最低限度的自然法）", "B 适用法律本身包含『同样情况同样处理』的形式正义胚芽", "C 道德原则可经由承认规则成为法律原则", "D 一切有效法律都必然是道德上正当的法律"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Green 指出哈特成熟理论承认目的、正义、效力承认三重连接，外加一种事实上的偶然连接。【逐步演示】这些连接都不等同于『法律效力取决于道德价值』，因此不推翻分离命题。【易错提醒】D 与哈特立场直接冲突，注意『有效』与『正当』的区分。"}, {"order": 12, "qtype": "essay", "stem": "试论『法律与道德分离命题』的准确含义，并说明为什么把两者分开反而有助于更清醒地批判恶法。", "options": [], "answer": "", "accepted": [], "keywords": [["区分效力与正当性", "是不是法律与道不道德是两回事"], ["承认恶法是有效法律", "不能否认其以法律名义存在"], ["正因为有效更有理由抵抗", "批判更有针对性"], ["反驳漫画化", "并非主张法律不需要道德"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先澄清分离命题的准确意思，再说明其批判价值。【逐步演示】第一步区分效力判断与道德评价；第二步指出承认恶法为法不等于赞许它；第三步说明这使抵抗的对象更明确；第四步反驳『法律无需道德』的漫画化理解。【易错提醒】不要写成哈特主张法官可以不道德地裁判。"}, {"order": 13, "qtype": "essay", "stem": "结合哈特—富勒论战，分析战后西德『告密者案』中两种处理方案的法理得失。", "options": [], "answer": "", "accepted": [], "keywords": [["哈特方案：承认纳粹法律有效", "它符合承认规则"], ["富勒方案：严重背离道德不成其为法", "支持法院判决"], ["哈特批评：混淆效力与正当性", "遮蔽恶以法律名义发生"], ["共同点：都主张应追究妻子责任", "分歧在追究方式"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先交代案情，再分别呈现两种方案，最后作比较评价。【逐步演示】事实：妻子借纳粹法律陷害丈夫；焦点：以何理由惩罚妻子；哈特：承认效力但谴责；富勒：否认其法律资格；评价：哈特认为追溯立法更诚实。【易错提醒】不要断言哈特支持妻子的行为或主张纳粹法律在道德上正当。"}]}, "S1M1K3": {"lesson": "S1M1K3", "questions": [{"order": 1, "qtype": "single", "stem": "埃利希（Eugen Ehrlich）提出的『活法』（living law）概念，其核心主张是：", "options": ["A 只有写成法典的规则才是真正的法律", "B 正式法律渊源只呈现法律的一部分，实际支配社会生活的是大量不成文规则", "C 宗教戒律高于国家法律", "D 习惯法一旦被国家承认就完全丧失原有性质"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】活法指社会生活中实际起作用、却未必见于正式法源的规则。【逐步演示】Wacks 指出这与庞德的『行动中的法』有相似之处，但批评者认为埃利希未说清活法与国家的关系。【易错提醒】活法不是否认成文法，而是提醒成文法不足以描述法律现实。"}, {"order": 2, "qtype": "single", "stem": "按照哈特的分析，一个只有习惯和社会道德、而没有次级规则的社会，最根本的缺陷是：", "options": ["A 完全没有行为规范", "B 无法确定哪些规则有效，也无法有意识地改变规则或权威地裁判争议", "C 规则数量太少", "D 人们不遵守任何规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为缺乏承认规则、改变规则、裁判规则，使习惯社会无法发展为现代法律体系。【逐步演示】习惯与社会道德只能缓慢演化，没有人能『制定』或『废止』一条习惯。【易错提醒】哈特并未说习惯社会没有规则，他说的是规则缺乏自反性机制。"}, {"order": 3, "qtype": "multi", "stem": "Siems 区分的习惯法类型包括下列哪些？", "options": ["A 活的习惯法（living customary law）", "B 教科书习惯法（textbook customary law）", "C 法典化习惯法（codified customary law）与司法习惯法（judicial customary law）", "D 国际习惯法（international customary law）作为唯一类型"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 区分活的习惯法、教科书习惯法、法典化习惯法、司法习惯法四类。【逐步演示】这一分类显示：习惯被整理、被立法吸收、被法官运用后，其性质与功能会发生变化。【易错提醒】D 不在 Siems 这一分类之内，不要混用国际法语境中的习惯法概念。"}, {"order": 4, "qtype": "judge", "stem": "法律多元主义主张：凡是群体内实际起约束作用的规范，都应当无条件地被称为『法律』。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这只是法律多元主义的粗糙版本，Wacks 引述 Tamanaha 明确反对这种概念泛化。【逐步演示】稳妥的做法是具体考察每个规范体系与国家法的关系、权威基础与实际接受程度。【易错提醒】多元主义不等于『什么都是法』，它也不等于给国家法无条件的优先地位。"}, {"order": 5, "qtype": "blank", "stem": "埃利希用『______』（living law）指称那些在社会中实际运行、却未见于正式法律渊源的规则。", "options": [], "answer": "", "accepted": ["活法", "living law", "活的法律", "生活的法"], "keywords": [], "explanation": "【答案】活法（living law）。【解题思路】这是埃利希法律社会学的核心概念。【逐步演示】它强调正式法源与社会实际运行规则之间的差距。【易错提醒】不要与庞德的『行动中的法』完全等同，两者虽有相似但有各自的理论语境。"}, {"order": 6, "qtype": "single", "stem": "Wacks 引述 Tamanaha 的告诫，研究法律多元主义要避免的两种相反错误是：", "options": ["A 只研究成文法与只研究判例法", "B 给国家法无条件的优先地位，以及假定其他规范体系与国家法平行", "C 只看城市与只看农村", "D 只承认宗教法与只承认习惯法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Tamanaha 提醒：既不能无条件抬高国家法，也不能把其他规范体系想象成与国家法并列的『法律』。【逐步演示】正确做法是逐个考察具体体系中规范之间的关系。【易错提醒】A、C、D 都是对原文的具体化误读。"}, {"order": 7, "qtype": "judge", "stem": "哈特承认，作为法律体系基础的承认规则本身在某种意义上可被视为一种司法习惯规则。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出哈特把承认规则描述为『一种司法习惯规则』，它存在于官员的实践中。【逐步演示】这说明法律与习惯之间并非泾渭分明，法律体系的根基本身带有社会习惯的性质。【易错提醒】这不等于说法律就是习惯；承认规则的特殊地位来自官员的接受与实践。"}, {"order": 8, "qtype": "single", "stem": "关于宗教规范与国家法的关系，下列哪一概括较为稳妥？", "options": ["A 各国一律实行政教合一", "B 美国、英国、德国的处理方式各不相同，不能混为一谈", "C 宗教规范在现代国家中已完全消失", "D 国家法必须全部以宗教经典为依据"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】比较法要求区分具体制度：美国有禁止确立国教的宪法传统，英国有国教会的历史痕迹，德国保障宗教自由同时保持国家法世俗性。【逐步演示】把三者说成同一模式是典型的比较法错误。【易错提醒】不要因某一国家的情况就推演出普遍结论。"}, {"order": 9, "qtype": "essay", "stem": "从制度化程度、强制方式、改变机制与正当性来源四个方面，论述法律与习惯、宗教规范、社会规范的区别。", "options": [], "answer": "", "accepted": [], "keywords": [["制度化：专门机关与程序", "习惯与社会道德只能渐进演化"], ["强制：官方有组织制裁", "习惯靠舆论与内心信念"], ["改变：次级规则使法律可刻意修改", "哈特的承认、改变、裁判规则"], ["正当性：国家法靠程序与授权", "宗教靠经典，习惯靠传统"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】按题目要求的四个维度逐项对照展开。【逐步演示】每个维度先说法律，再对照习惯、宗教与社会规范，最后指出相似之处。【易错提醒】不要声称只有法律才有制裁，宗教社群也可能有组织化惩戒。"}, {"order": 10, "qtype": "multi", "stem": "下列哪些是法律与习惯、宗教、社会规范之间的真实相似之处？", "options": ["A 都以『应当』的形式指引行为", "B 都在不同程度上约束人们的行为", "C 都可能发生内容上的冲突", "D 都必须经过国家立法程序才能存在"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】这些规范共享规范形式、实际约束力，并可能相互冲突。【逐步演示】Siems 举例：伊斯兰教法禁止利息，与现代银行业务直接冲突；集体所有权观念与抵押贷款方式也可能抵触。【易错提醒】D 恰恰是法律区别于其他规范的特征，不是相似点。"}, {"order": 11, "qtype": "single", "stem": "Siems 举出伊斯兰教法禁止利息与现代银行业务冲突的例子，主要想说明：", "options": ["A 宗教法必然高于国家法", "B 不同规范秩序之间的冲突是价值冲突，不能简单宣布一方『不是法』", "C 现代金融应当被全面禁止", "D 国家法与宗教法从未发生冲突"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】这个例子展示的是不同规范体系基于不同价值基础而产生的冲突。【逐步演示】冲突的解决通常要靠制度安排划分管辖范围，而非概念上取消一方。【易错提醒】不要把这个例子读成对宗教或金融的价值判断。"}, {"order": 12, "qtype": "judge", "stem": "法律多元主义的早期倡导者之一 Griffiths 后来放弃了这一概念，认为『规范多元主义』是更贴切的说法。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 记载 Griffiths 承认自己原先的法律多元主义构想是个错误。【逐步演示】他转而认为『规范多元主义』更能描述实际的规范并存现象。【易错提醒】这与法律多元主义仍在传播并不矛盾：一个概念被修正不等于被彻底遗忘。"}, {"order": 13, "qtype": "essay", "stem": "围绕『法律是否必须以国家为中心』，概述国家中心主义与法律多元主义各自的理由与弱点。", "options": [], "answer": "", "accepted": [], "keywords": [["国家中心主义：概念清晰，说明体系统一性", "弱点：难以解释非国家规范的实际效力"], ["多元主义：贴近经验现实", "弱点：可能把一切规范都称为法"], ["Tamanaha：避免两种极端", "具体分析各体系关系"], ["结论：边界动态，由承认规则与实践划定"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分别呈现两派理由与弱点，再寻求调和。【逐步演示】国家中心主义以承认规则为核心；多元主义以社会实际运行为依归；Tamanaha 提供中间立场；结论是边界由制度与实践共同划定。【易错提醒】不要简单站队，题目要求分析双方论据。"}]}, "S1M1K4": {"lesson": "S1M1K4", "questions": [{"order": 1, "qtype": "single", "stem": "哈特关于制裁在法律中地位的著名说法是：", "options": ["A 制裁是法律唯一的核心要素", "B 制裁是法律的『计划 B』，『计划 A』是人们在无监督时自觉遵守", "C 一切法律规则都必须有制裁", "D 制裁与法律完全无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Green 在导论中概括哈特：制裁是 Plan B，Plan A 是自觉遵守。【逐步演示】法律的首要功能是指导行为，制裁只在指导失败时启动。【易错提醒】哈特并不否认制裁的存在，只是否认它是法律的本质。"}, {"order": 2, "qtype": "single", "stem": "哈特用『枪匪情境』（the gunman situation）想要说明的区分是：", "options": ["A 合法暴力与非法暴力的区分", "B 『被迫』（obliged）与『有义务』（obligation）的区分", "C 道德与不道德的区分", "D 成文法与习惯法的区分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】枪匪威胁受害者交出钱包，受害者是『被迫』；依法纳税则是『有义务』。【逐步演示】哈特认为把法律义务还原为威胁下的被迫，是对法律性质的误解。【易错提醒】obliged 与 obligation 的区分是哈特批判命令理论的经典考点。"}, {"order": 3, "qtype": "judge", "stem": "边沁与奥斯丁都强调制裁与义务的连接，在他们的理论中，没有制裁的规则很难算作『完整的法律』。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，边沁强调制裁创造或构成法律义务，这是其理论的重要元素。【逐步演示】奥斯丁同样以制裁为法律三要素之一。【易错提醒】这是古典实证主义的立场，不是哈特的立场，注意区分不同学者。"}, {"order": 4, "qtype": "blank", "stem": "哈特把赋予人们订立合同、成立婚姻、立遗嘱等能力的规则称为『______规则』（power-conferring rules）。", "options": [], "answer": "", "accepted": ["授权性", "授权", "power-conferring", "授权性规则", "赋权性"], "keywords": [], "explanation": "【答案】授权性规则（power-conferring rules）。【解题思路】这类规则提供实现法律效果的『配方』，而非施加义务。【逐步演示】不遵守的后果是预期效果落空，而不是受到惩罚。【易错提醒】不要答成『义务性规则』或『制裁性规则』。"}, {"order": 5, "qtype": "multi", "stem": "下列哪些属于哈特在《法律的概念》中作出的重要区分？", "options": ["A 描述与规范", "B 义务（obligation）与被迫（obliged）", "C 授权性规则与课予义务的规则", "D 内部观点与外部观点"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项都是哈特理论中的基本区分。【逐步演示】这些区分共同服务于一个目标：把法律从『威胁』的粗糙模型中解放出来，理解为一整套规则实践。【易错提醒】本题是全选题，不要漏选授权性规则这一常被忽视的区分。"}, {"order": 6, "qtype": "single", "stem": "美国法典中有规定如何尊重国旗的规则，却没有配套罚则。这个例子最直接地支持哪一命题？", "options": ["A 一切法律规则都必须有制裁", "B 没有制裁的规则也可能是法律规则", "C 国旗规则不是法律而是道德说教", "D 法律与道德完全相同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该规则由有权机关制定并作为行为标准使用，虽无罚则仍是法律规则。【逐步演示】Green 用它说明『制裁是 Plan B』：法律可以在不需要强化动机的场合存在。【易错提醒】不要由『无罚则』推出『不是法律』，这是奥斯丁式标准的局限。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，婚姻不成立或遗嘱无效，实际上是一种由国家施加的制裁。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确反对把『无效』说成制裁：授权性规则中根本没有命令。【逐步演示】所谓『制裁』不过是授权性规则本身，预期的法律效果没有产生而已。【易错提醒】凯尔森曾试图把授权性规则解释为法律片段、制裁藏在别处，但哈特认为这种重构缺乏实践动机。"}, {"order": 8, "qtype": "single", "stem": "按照 Wacks 的介绍，凯尔森基础规范（Grundnorm）的两项主要功能是：", "options": ["A 证明法律符合道德，以及统一法院体系", "B 使强制秩序可被看作客观有效、区别于强盗要求，以及解释法律秩序的统一与无矛盾", "C 授权法官创造法律，以及限制主权者", "D 把习惯法转化为制定法，以及确定国际法效力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确指出基础规范的两项功能：区分强盗与法律的要求、说明法律秩序的连贯统一。【逐步演示】基础规范是被预设的，其效力不来自另一条规范。【易错提醒】凯尔森强调基础规范的本体论中立，不要把它理解为道德正当性的来源。"}, {"order": 9, "qtype": "single", "stem": "Green 说『强制是法律权力的硬边缘，而法律规范的激励性与表达性属于它的软边缘』，这句话意在强调：", "options": ["A 法律只有强制一个维度", "B 非强制性法律同样在分配权力、塑造激励与表达价值", "C 激励性规范不是法律", "D 强制性已被现代法律彻底抛弃"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Green 在承认哈特批评的同时，提醒不要忽视非强制性法律的社会功能。【逐步演示】例如曾经把异族或同性婚姻定为无效的规则，并未强制谁，却深刻塑造了社会生活。【易错提醒】这段话是对哈特的补充而非推翻，不要读成否定哈特。"}, {"order": 10, "qtype": "essay", "stem": "试论法律的强制性与规范性之间的关系，并说明为何不能把法律简单等同于『以制裁为后盾的命令』。", "options": [], "answer": "", "accepted": [], "keywords": [["规范性：以应当指引行为", "提供批评与证成的理由"], ["强制性：以国家强制力为后盾", "制裁是计划B而非本质"], ["义务不同于被迫", "枪匪情境的反例"], ["授权性规则不靠惩罚运作", "命令理论解释力不足"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分别界定强制性与规范性，再用哈特的论据反驳命令理论。【逐步演示】第一步区分描述与规范；第二步指出制裁的后备地位；第三步用义务/被迫与授权性规则两个论据展开。【易错提醒】不要把『法律有强制性』写成『法律即暴力』。"}, {"order": 11, "qtype": "multi", "stem": "下列哪些属于典型的授权性规则？", "options": ["A 规定合同如何成立的规则", "B 规定结婚条件的规则", "C 规定遗嘱如何有效的规则", "D 规定杀人者处死刑的刑法规则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】授权性规则赋予人们改变法律地位的能力，提供实现法律效果的配方。【逐步演示】ABC 都是典型例子；D 是课予义务并附制裁的规则，不属于授权性规则。【易错提醒】不要把『规定条件』的规则误当作『命令』，关键在于它提供的是能力而非义务。"}, {"order": 12, "qtype": "judge", "stem": "拉兹认为，法治是一种『消极德性』，它减少滥权风险，但并不赋予法律独立的道德价值。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 记载拉兹的这一主张：法治降低行政权滥用的风险，却不带来独立的道德功绩。【逐步演示】拉兹甚至认为即使在正当法律体系中，也不存在服从法律的初步道德义务。【易错提醒】这是拉兹的立场，不是自然法理论的立场，注意归属。"}, {"order": 13, "qtype": "essay", "stem": "比较奥斯丁的命令理论与哈特的规则理论，说明后者在解释法律现象上的优势。", "options": [], "answer": "", "accepted": [], "keywords": [["命令理论：主权者命令加制裁", "优点是经验可研究，缺点是解释范围窄"], ["规则理论：初级规则加次级规则", "承认、改变、裁判规则"], ["解释优势：授权性规则、国际法、法律连续性", "义务体验不同于被迫"], ["哈特仍承认制裁与最低社会条件", "区别在地位而非否认"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先概述两种理论，再从解释范围与义务体验两方面比较。【逐步演示】命令理论以威胁为核心；规则理论以承认规则确立的社会实践为核心；后者能解释前者解释不了的现象。【易错提醒】不要说哈特完全否认强制或制裁，他否认的是其核心地位。"}]}, "S1M1K5": {"lesson": "S1M1K5", "questions": [{"order": 1, "qtype": "single", "stem": "庞德（Roscoe Pound）把法律的任务比喻为：", "options": ["A 机械地适用既有规则", "B 社会工程——以最小摩擦与资源浪费满足尽可能多的利益", "C 实现神的旨意", "D 单纯维护统治阶级利益"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】庞德是社会社会学法学的代表，主张法律通过识别与保护利益来进行社会工程。【逐步演示】利益是个人或群体寻求满足的需求，法律赋予其权利地位，冲突利益须在同一层面权衡。【易错提醒】D 是马克思主义批判视角，不是庞德本人的主张。"}, {"order": 2, "qtype": "single", "stem": "卢埃林（Karl Llewellyn）认为法律最重要的工作是：", "options": ["A 制定抽象的法律概念", "B 处理麻烦案件（the disposition of trouble cases）", "C 维护法律的逻辑自洽", "D 保障国际和平"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】卢埃林功能主义的核心是制度实际做什么，他认为最重要的是对纠纷做点什么且做得合理。【逐步演示】他说：『就纠纷做点什么，并且做得合理，这就是法律的事业。』【易错提醒】不要把他与庞德的利益平衡说混同；卢埃林更强调实际运作。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于卢埃林列举的六项『法律工作』？", "options": ["A 调整麻烦案件", "B 预防性地引导行为与预期", "C 分配权威并确定决策程序", "D 保证每个案件都达到实质正义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】卢埃林列出的六项法律工作包括调整麻烦案件、预防性引导、重新引导以适应变化、分配权威与程序、提供方向与激励、法学方法的工作。【逐步演示】D 不是他的清单内容，而且他强调的是『合理处理』而非保证实质正义。【易错提醒】本题不要全选；六项清单中没有实质正义保证这一项。"}, {"order": 4, "qtype": "judge", "stem": "Green 指出，法律作为社会控制的主要功能，主要体现在法庭上的诉讼与审判之中。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Green 明确说，法律作为社会控制的主要功能不在私益诉讼或刑事追诉，而在法庭之外。【逐步演示】诉讼与追诉是『系统失灵时的辅助安排』；法律主要用于在法庭外控制、引导和规划生活。【易错提醒】把法律等同于『打官司』是常见的狭窄理解。"}, {"order": 5, "qtype": "blank", "stem": "庞德强调的『______』（law in action）指实际运作中的法律，与『书本上的法』相对。", "options": [], "answer": "", "accepted": ["行动中的法", "law in action", "行动中的法律", "实际运作的法律"], "keywords": [], "explanation": "【答案】行动中的法（law in action）。【解题思路】庞德区分书本上的法与行动中的法，并力图协调二者。【逐步演示】他说：『在书本上的法与国民意志的冲突中，只能有一个结果——我们不要做法律修士。』【易错提醒】埃利希的『活法』与之相似但有不同理论语境，注意区分。"}, {"order": 6, "qtype": "single", "stem": "涂尔干（Émile Durkheim）关于法律与社会团结的对应关系，正确的是：", "options": ["A 机械团结对应恢复性法律，有机团结对应压制性法律", "B 机械团结对应压制性法律，有机团结对应恢复性法律", "C 两种团结都对应压制性法律", "D 法律与社会团结无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】涂尔干认为简单同质社会的机械团结对应以刑罚为主的压制性法律，分工发达社会的有机团结对应恢复性法律。【逐步演示】恢复性法律包括民法、程序法以及宪法与行政法的主要部分。【易错提醒】把两组对应关系记反是最常见的错误。"}, {"order": 7, "qtype": "judge", "stem": "庞德对利益的详细分类被认为过于人为或形式化，这是他受到的批评之一。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，庞德精细的利益分类虽然繁多，但被批评为过于形式化甚至人为。【逐步演示】此外，功能主义还被批评隐含价值偏好，并非真正价值中立。【易错提醒】承认这一批评不等于全盘否定庞德的贡献。"}, {"order": 8, "qtype": "single", "stem": "Siems 介绍的斯坦福大学『法律在截然不同的国家』课程，以共同问题为线索比较美国、中国、埃及与博茨瓦纳，这体现了比较法的哪一方法？", "options": ["A 只比较法律条文", "B 功能方法——先确定社会问题，再比较不同制度的解答", "C 只比较宗教法", "D 只比较判例法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该课程用『许诺被信赖却未履行』这类共同问题组织比较，体现功能方法。【逐步演示】Siems 认为即使制度『截然不同』，功能方法仍能提供可行的比较框架。【易错提醒】不要误以为比较法只能比较形式相似的规则。"}, {"order": 9, "qtype": "essay", "stem": "概述法律在社会中的主要功能，并说明为什么法律的功能并非总是正面的。", "options": [], "answer": "", "accepted": [], "keywords": [["行为指引与协调", "提供指南与批评标准"], ["纠纷解决与社会控制", "卢埃林处理麻烦案件，功能在法庭外"], ["社会变迁工具与价值表达", "法律推动改革并表达评价"], ["代价与失灵", "压迫风险与法律主义"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先正面列举功能，再转向代价与失灵。【逐步演示】哈特指出制度化有适应性、确定性、效率的收益，也有集中权力被滥用的风险；法律还可能变得技术化、远离生活。【易错提醒】不要写成一份只有好处的清单。"}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于制度化法律可能带来的代价或风险？", "options": ["A 集中的权力可能被用于压迫部分群体", "B 法律可能变得技术化、晦涩、远离被治理者的生活", "C 追求确定性可能牺牲个案公平", "D 法律必然消灭所有社会冲突"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特与 Green 指出现代法律的代价包括压迫风险与法律主义倾向。【逐步演示】不同功能之间的权衡也会带来牺牲，如确定性对个案公平的挤压。【易错提醒】D 是明显错误的绝对化表述，法律并不消灭冲突。"}, {"order": 11, "qtype": "single", "stem": "下列关于『行动中的法』（law in action）与『活法』（living law）关系的说法，较稳妥的是：", "options": ["A 两者完全相同，没有任何差别", "B 两者都关注正式法源之外的法律现实，但各有不同理论语境", "C 两者都否认成文法的存在", "D 两者都是凯尔森提出的概念"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出庞德的行动中的法与埃利希的活法有强相似性，但批评者关注的是两者关系的复杂性。【逐步演示】它们共同反对只研究书本上的法，但分属不同理论传统。【易错提醒】不要把它们完全等同，也不要误归为凯尔森的概念。"}, {"order": 12, "qtype": "judge", "stem": "只要证明法律在社会中发挥了某种功能，就等于证明了该法律是正当的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这是把功能描述混同于价值辩护，正是功能主义受到的核心批评之一。【逐步演示】腐败的制度也可能『发挥功能』，法律制造压迫同样是功能而非正当性证明。【易错提醒】描述『法律做了什么』与评价『法律应当做什么』必须分开。"}, {"order": 13, "qtype": "essay", "stem": "围绕『功能主义能否价值中立』，概述支持者与批评者各自的理由。", "options": [], "answer": "", "accepted": [], "keywords": [["支持者：从社会需求与制度任务出发", "庞德与卢埃林以经验研究为目标"], ["批评者：分类隐含价值偏好", "所谓社会工程已预设目标"], ["马克思主义批判：法治是意识形态", "掩盖权力关系"], ["结论：描述功能不等于价值辩护"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先呈现功能主义的自我理解，再列出主要批评，最后作平衡结论。【逐步演示】支持者强调经验描述；批评者指出利益分类与目标设定已含价值判断；结论是功能分析有价值但需警惕。【易错提醒】不要只写一方。"}]}, "S1M1K6": {"lesson": "S1M1K6", "questions": [{"order": 1, "qtype": "single", "stem": "凯尔森（Hans Kelsen）关于国家与法律关系的主张是：", "options": ["A 国家高于法律，法律只是国家命令", "B 国家与法律秩序在本质上同一，国家机构由法律界定", "C 法律完全独立于国家，不依赖任何强制机器", "D 国家与法律毫无关联"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】凯尔森拒绝把国家理解为立于法律之上的实体，认为国家与法律都是强制秩序。【逐步演示】国家的机构、权力与职能都由法律规定；因此无法再用法律去『证成』国家。【易错提醒】A 是奥斯丁的立场，不是凯尔森的立场。"}, {"order": 2, "qtype": "single", "stem": "按照奥斯丁的主权理论，主权者的核心特征是：", "options": ["A 由宪法明确授权并可被宪法法院审查", "B 享有多数人的习惯性服从，而自己不习惯性服从任何人", "C 必须通过民主选举产生", "D 权力受到基本权利清单的限制"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】奥斯丁定义主权者为多数人习惯服从、自己却不服从任何人的个人或群体。【逐步演示】法律就是这种主权者发布的、以制裁为后盾的命令。【易错提醒】不要把现代立宪君主或民选总统的特征误加到奥斯丁的主权者概念上。"}, {"order": 3, "qtype": "judge", "stem": "凯尔森认为，每一个法律秩序都自动是一个提供法律安全的法治国（Rechtsstaat）。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出，并非每个法律秩序都是法治国。【逐步演示】一个相对集权、专制的强制秩序，即使不提供法律安全，仍是法律秩序、仍构成国家，但这不包含政治价值判断。【易错提醒】凯尔森区分了『是法律秩序』与『是值得赞许的法治国』。"}, {"order": 4, "qtype": "blank", "stem": "德国传统中强调国家须受法治约束、提供法律安全的国家概念称为『______』（Rechtsstaat）。", "options": [], "answer": "", "accepted": ["法治国", "Rechtsstaat", "法治国家", "法的国家"], "keywords": [], "explanation": "【答案】法治国（Rechtsstaat）。【解题思路】这是德语法律传统中的核心概念，强调国家权力受法律约束并提供法律安全。【逐步演示】Wacks 在讨论 Kelsen 与法治时专门分析了这一概念。【易错提醒】不要把它与一般意义上的『法治』完全等同，它带有特定的德国宪制史背景。"}, {"order": 5, "qtype": "multi", "stem": "下列哪些概念与限制国家权力直接相关？", "options": ["A 权力分立（Separation of Powers）", "B 法治（Rule of Law）", "C 违宪审查（Judicial Review）", "D 法律命令说（Command Theory of Law）"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】权力分立、法治、违宪审查都是现代宪制中约束国家权力的机制。【逐步演示】命令理论则强调主权者不受自己命令的约束，属于支持国家权力至上的理论。【易错提醒】不要把命令说误当作限制国家权力的学说。"}, {"order": 6, "qtype": "single", "stem": "Siems 记载，美国最高法院允许对初级立法进行司法审查的里程碑判决发生在：", "options": ["A 1787 年", "B 1803 年", "C 1903 年", "D 1958 年"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 明确指出美国最高法院在 1803 年的里程碑判决中允许对初级立法进行司法审查。【逐步演示】这一事件通常被视为司法审查制度的起点。【易错提醒】1958 年是法国引入有限抽象审查的年份，不要混淆。"}, {"order": 7, "qtype": "single", "stem": "二战后由立法者引入或扩大违宪审查的国家组合，正确的是：", "options": ["A 德国、奥地利、意大利", "B 英国、法国、美国", "C 澳大利亚、以色列、瑞士", "D 加拿大、美国、瑞典"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 记载，德国、奥地利、意大利在二战后引入或扩展违宪审查，加拿大在 1982 年跟进。【逐步演示】英国长期坚持议会主权模式；法国 1958 年才引入有限的抽象审查。【易错提醒】注意区分各国引入审查的时间与方式。"}, {"order": 8, "qtype": "judge", "stem": "英国遵循相对严格的议会主权模式，对司法审查一直较为犹豫；而法国在 1958 年引入了有限的抽象审查，2008 年允许公民提出宪法申诉。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这两点都是 Siems 比较法中的明确记载。【逐步演示】英国与法国在这一问题上的路径差异，说明议会主权并非各国共同起点。【易错提醒】不要把法国的制度说成与美国完全相同，它经历了 1958 年与 2008 年两个不同阶段。"}, {"order": 9, "qtype": "single", "stem": "Siems 概括的关于违宪审查的两种相反理由，分别是：", "options": ["A 法律确定性 vs 法律灵活性", "B 有限政府要求人权约束立法者 vs 民选法官不应挑战议会表达的民意", "C 成文法至上 vs 判例法至上", "D 国内法优先 vs 国际法优先"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出，支持审查的理由是有限政府与人权约束立法者，反对的理由是法官不应挑战议会优先所表达的民意。【逐步演示】这一张力在各国的制度选择中留下不同答案。【易错提醒】不要把这一争论简化为技术与政治的对立。"}, {"order": 10, "qtype": "essay", "stem": "论述法律与国家权力之间的双向关系，并说明为什么『法律是国家的工具』与『法律约束国家』两种说法并不必然矛盾。", "options": [], "answer": "", "accepted": [], "keywords": [["国家创造法律：制定、认可、执行", "经验基础"], ["法律塑造国家：界定机构与权限", "凯尔森的国家法律同一论"], ["法律具有相对独立性", "哈特的承认规则与官员实践"], ["法治与违宪审查", "权力受到法律限制"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分别呈现两个方向，再作调和。【逐步演示】国家提供法律的机器，法律界定国家的机构与权限；哈特的承认规则说明二者在实践中相互构成；现代宪制用权力分立与审查机制落实约束。【易错提醒】不要陷入『非此即彼』的二选一。"}, {"order": 11, "qtype": "multi", "stem": "按照 Siems 的梳理，下列哪些国家由普通法院同时处理宪法问题与其他法律问题？", "options": ["A 美国", "B 瑞典", "C 瑞士", "D 德国"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 指出美国、瑞典、瑞士由同一法院处理宪法与其他法律问题。【逐步演示】德国、奥地利、法国、意大利则设有独立的宪法法院或宪法委员会，这一模式受 Kelsen 影响。【易错提醒】不要把德国归入普通法院模式，它是集中式审查的代表。"}, {"order": 12, "qtype": "judge", "stem": "拉兹认为，即便在正当的法律体系中，公民也存在服从法律的初步道德义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 记载拉兹的结论恰好相反：即使在正当的法律体系中也不存在服从法律的初步义务。【逐步演示】法治对拉兹是消极德性，减少滥权却不赋予法律独立的道德功绩。【易错提醒】这是拉兹的立场，不是自然法理论的立场。"}, {"order": 13, "qtype": "essay", "stem": "围绕违宪审查的民主正当性，概述支持与反对的两派论据，并说明分散式与集中式审查各自的利弊。", "options": [], "answer": "", "accepted": [], "keywords": [["支持：有限政府与基本权利保障", "法律制定者也应受约束"], ["反对：反多数难题", "法官不应推翻民选议会意志"], ["分散式：贴近个案但可能分歧", "美国、瑞典、瑞士"], ["集中式：统一专业但可能脱离语境", "德国等国，受Kelsen影响"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先呈现规范层面的争论，再比较制度组织的两种模式。【逐步演示】支持与反对各有理由；分散式与集中式的差别在于由谁裁判宪法问题，各有代价。【易错提醒】不要简单断言某一模式绝对优越。"}]}, "S1M2K1": {"lesson": "S1M2K1", "questions": [{"order": 1, "qtype": "single", "stem": "按照哈特的观点，法律体系的核心是什么？", "options": ["A 主权者发布的命令集合", "B 初级规则与次级规则的结合", "C 以制裁为后盾的威胁体系", "D 法官判决的总和"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特在《法律的概念》第六章提出，法律体系的中心是初级规则与次级规则的结合。【逐步演示】初级规则直接规定行为，次级规则规定如何识别、改变与裁判初级规则，二者结合才构成体系。【易错提醒】A、C 属于奥斯丁命令理论，D 接近法律现实主义，均非哈特的答案。"}, {"order": 2, "qtype": "single", "stem": "下列哪一项属于哈特所说的『次级规则』？", "options": ["A 不得杀人", "B 必须纳税", "C 规定议会如何制定法律的规则", "D 合同应当履行"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】次级规则是关于规则本身的规则，包括承认规则、改变规则与裁判规则。【逐步演示】『议会如何制定法律』属于改变规则，是典型的次级规则。【易错提醒】A、B、D 都直接规定人们的行为，属于初级规则，注意两类规则的功能差别。"}, {"order": 3, "qtype": "multi", "stem": "根据哈特，次级规则通常包括哪些类型？", "options": ["A 承认规则", "B 改变规则", "C 裁判规则", "D 义务规则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特区分三类次级规则：承认、改变、裁判规则，分别回应规则的不确定性、静态性与争端解决的无效率。【逐步演示】D 义务规则是初级规则的主要形态，不属于次级规则。【易错提醒】改变规则与裁判规则一般授予权力而非设定义务，这是它们与初级规则的重要区别。"}, {"order": 4, "qtype": "judge", "stem": "按照哈特，法律体系的存在只需要有效规则被社会成员普遍遵守这一项条件。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 依哈特指出，法律体系存在须满足两项条件，而非一项。【逐步演示】其二是官员须从内部观点接受改变规则、裁判规则与承认规则。【易错提醒】缺少官员对次级规则的内部接受，规则社会仍停留在前法律阶段。"}, {"order": 5, "qtype": "blank", "stem": "官员据以识别哪些规则属于有效法律的共同标准，哈特称之为______。", "options": [], "answer": "", "accepted": ["承认规则", "rule of recognition", "承认规则（rule of recognition）", "法效力承认规则"], "keywords": [], "explanation": "【答案】承认规则（Rule of Recognition）。【解题思路】承认规则是识别有效法律的终极标准，属最重要的次级规则。【逐步演示】它以官员社会实践的方式存在，其存在条件就是被实际遵循。【易错提醒】不要与凯尔森的『基础规范』混淆，后者是理论预设，前者是可观察的社会实践。"}, {"order": 6, "qtype": "single", "stem": "关于承认规则与基础规范的关系，下列说法符合 Wacks 的阐述的是：", "options": ["A 二者完全等同，可以互换使用", "B 二者功能相近，但前者是社会实践，后者是理论预设", "C 基础规范是哈特提出的", "D 承认规则属于初级规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 第4.1节专门比较二者：功能相近但性质不同。【逐步演示】哈特的承认规则是可经验观察的官员实践；凯尔森的基础规范是被预设的效力支点。【易错提醒】C 张冠李戴，基础规范属于凯尔森；D 错误，承认规则是次级规则。"}, {"order": 7, "qtype": "single", "stem": "德沃金对哈特法律体系理论的主要批评是：", "options": ["A 哈特过分强调制裁的作用", "B 哈特的『规则模型』遗漏了法律原则这一维度", "C 哈特否认法律体系的存在", "D 哈特把法律与道德完全等同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金批评哈特把法律体系描绘为规则模型，忽略原则。【逐步演示】他主张法官在疑难案件中要依据道德原则作出整体性判决。【易错提醒】哈特在后记中承认原则的存在，但坚持可从承认规则角度说明原则如何被识别，争论并未简单分出胜负。"}, {"order": 8, "qtype": "single", "stem": "英国没有成文宪法典却仍被认为拥有宪法，这一事实最能说明：", "options": ["A 法律体系必须以法典为基础", "B 法律体系的成分可以多样，惯例也可能被纳入", "C 不成文规则一律不是法律", "D 宪法必须是单一文件"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】英国宪法由制定法、判例与惯例共同构成，说明体系身份不取决于是否成文。【逐步演示】哈特框架下，惯例因被内部观点接受而可纳入体系的功能范围。【易错提醒】A、C、D 都把法律体系等同于成文法典，误解了体系边界的开放性。"}, {"order": 9, "qtype": "judge", "stem": "在比较法语境中，『大陆法系』与『一个国家的法律体系』属于同一范畴层次，可以互换使用。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确区分法律体系（单一国家的法）与法系（若干体系的分类）。【逐步演示】法系是法律体系的集合概念，如同『哺乳动物』与『一只动物』的关系。【易错提醒】范畴层次混淆是比较法初学者最常犯的错误之一。"}, {"order": 10, "qtype": "multi", "stem": "依据 Siems，划分法系通常参考哪些维度？", "options": ["A 法律历史", "B 法律思维", "C 实在法特征", "D 国土面积"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 指出法系分类依据法律史、法律思维与实在法特征的亲缘关系。【逐步演示】普通法系以英国法为基础，大陆法系受欧洲大陆传统影响，正是这三个维度的体现。【易错提醒】D 属于无关因素，法系划分依据的是法律现象而非地理规模。"}, {"order": 11, "qtype": "essay", "stem": "试论哈特如何用一个『前法律社会』的思想实验说明次级规则对于法律体系的必要性。", "options": [], "answer": "", "accepted": [], "keywords": [["只有初级规则", "前法律社会"], ["不确定性静态性无效率", "三重缺陷"], ["承认改变裁判规则", "分别回应三重缺陷"], ["代价是权力集中", "制度化有得有失"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先描述前法律社会的状态，再指出三重缺陷，最后说明次级规则的回应与代价。【逐步演示】第一步：只有初级规则，靠社会压力维持；第二步：不确定性、静态性、争端解决无效率；第三步：承认、改变、裁判规则逐一对应；第四步：制度化带来确定性与效率，也带来压迫风险。【易错提醒】不要把这个思想实验理解为历史事实，它是哈特的理论模型。"}, {"order": 12, "qtype": "judge", "stem": "哈特认为，法律体系一旦建立，其规则便会自动产生判决，法官只是投入事实、吐出结论的机器。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确反对『自动售货机』式的法律观。【逐步演示】他承认上诉法院大量活动是在解决有争议的案件，而非适用确定规则。【易错提醒】这是把哈特与法律形式主义混为一谈，Wacks 特别提醒哈特从不说法律只是规则。"}, {"order": 13, "qtype": "essay", "stem": "比较哈特与凯尔森关于法律体系统一性的解释，说明承认规则与基础规范的异同。", "options": [], "answer": "", "accepted": [], "keywords": [["都提供效力终极支点", "统一性基础"], ["哈特承认规则是社会实践", "可经验观察"], ["凯尔森基础规范是理论预设", "被预设"], ["Wacks第4.1节比较", "功能相近性质不同"]], "explanation": "【答案要点】见 keywords。【解题思路】先指出共同功能，再分别说明二者性质差异。【逐步演示】第一步：二者都回答『效力最终从何而来』；第二步：哈特把承认规则定位为官员的实际社会实践；第三步：凯尔森的基础规范是被预设的先验支点；第四步：Wacks 认为二者功能相近而性质不同。【易错提醒】不要简单说二者『完全一样』或『毫无关系』，准确表述是功能相近、性质有别。"}]}, "S1M2K2": {"lesson": "S1M2K2", "questions": [{"order": 1, "qtype": "single", "stem": "关于『不成文法』的含义，下列理解正确的是：", "options": ["A 完全没有文字记载的法律", "B 没有系统编纂的权威法典、以判例习惯惯例等形态存在的法律", "C 尚未被法院适用的法律", "D 道德规范的别称"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】不成文法指没有统一法典形式，而非没有文字载体。【逐步演示】英国判例有书面判决报告，但其权威来自判决积累而非编纂法典。【易错提醒】把『不成文』等同于『没有文字』或『不明确』是最常见的误解。"}, {"order": 2, "qtype": "single", "stem": "下列哪一项最能体现大陆法系成文法传统的核心观念？", "options": ["A 法律主要由判例积累而成", "B 法典应清晰连贯自足完整", "C 法官可自由创造法律", "D 习惯法是主要法源"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出大陆法系法典体现启蒙运动的理念：清晰、连贯、系统、自足、完整。【逐步演示】《法国民法典》与《德国民法典》是这一观念的标志性成果。【易错提醒】A、C、D 更接近普通法传统，注意区分两种法律形态的重心。"}, {"order": 3, "qtype": "judge", "stem": "美国所有州都采纳了《统一商法典》，这说明美国已经转变为大陆法系国家。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】 Siems 指出 UCC 只是普通法世界中成文法运动的代表，其内容多为判例整理。【逐步演示】普通法国家的成文法多为既有判例的合并与体系化，与大陆法法典观念不同。【易错提醒】有成文法不等于成为大陆法系，判断法系要看法律思维与整个体系的重心。"}, {"order": 4, "qtype": "blank", "stem": "公元533年东罗马皇帝查士丁尼主持编纂的______，是大陆法系成文法传统的重要源头。", "options": [], "answer": "", "accepted": ["国法大全", "查士丁尼法典", "Corpus Juris Civilis", "民法大全", "查士丁尼国法大全"], "keywords": [], "explanation": "【答案】《国法大全》（Corpus Juris Civilis）。【解题思路】查士丁尼于533年主持编纂，十一世纪在欧洲大陆被继受。【逐步演示】这一传统使大陆法被称为『学者的法』，并最终导向法典化运动。【易错提醒】注意年份533年与继受的十一世纪是两个不同时间点，不要混淆。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，下列哪些属于不成文法的具体形态？", "options": ["A 判例法", "B 习惯法", "C 宪法惯例", "D 议会制定的成文法"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】不成文法以判例、习惯与惯例等形态存在。【逐步演示】D 是典型的成文法，由立法机关制定并以文字颁布。【易错提醒】宪法惯例虽无严格法律制裁，却可能被纳入法律体系的功能范围，不要因其无强制力就排除。"}, {"order": 6, "qtype": "single", "stem": "Siems 引用 Maitland 的名言『我们埋葬了诉讼形式，它们却仍在坟墓中统治我们』，意在说明：", "options": ["A 普通法完全依赖成文法典", "B 普通法的程序形式对实体规则有持久影响", "C 大陆法已经消亡", "D 判例不再具有约束力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】这句话强调普通法早期令状与诉讼形式对后世实体规则的深远影响。【逐步演示】Siems 指出法官把程序性的令状 origins 转化为实体规则，故形式虽废、影响仍在。【易错提醒】不要望文生义理解为『死人统治活人』，它讲的是法律形式的历史延续性。"}, {"order": 7, "qtype": "judge", "stem": "大陆法系国家不存在判例，法官只适用成文法典。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】现代大陆法系国家同样存在大量判例，判例在实践中被下级法院广泛参考。【逐步演示】成文法与不成文法的差别在体系重心，而非有无判例。【易错提醒】把两大法系说成『一个只有成文法、一个只有判例』是过度简化的漫画式理解。"}, {"order": 8, "qtype": "single", "stem": "《法国民法典》第5条禁止法官以一般性规则裁判案件，其制度背景是：", "options": ["A 鼓励法官造法", "B 旧制度下法院以普遍规则阻挠改革，立法者追求严格分权", "C 确立判例的约束力", "D 废除成文法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出该条背景是旧法国法院（Parlements）以普遍规则阻挠改革，法典旨在严格分权、禁止司法造法。【逐步演示】其理想是法律按法典写下的原样被适用。【易错提醒】第九世纪与二十世纪的解释实践已转向目的论方法，第5条的严格字面解释早已不具可行性。"}, {"order": 9, "qtype": "single", "stem": "瑞士民法典第1条第2款规定，法典没有相关规定时法官依习惯法裁判，习惯法也没有时依『他作为立法者会确立的规则』裁判。这反映了大陆法解释方法的何种变化？", "options": ["A 严格字面解释仍占主导", "B 承认在例外情形下法官可填补法律漏洞", "C 完全放弃法典化", "D 判例成为唯一法源"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该条明文授权法官在无规定时依习惯法乃至立法者式的规则裁判，是对漏洞填补的承认。【逐步演示】Siems 以此说明大陆法解释已从机械字面主义转向注解方法与目的论方法。【易错提醒】C、D 走向另一个极端，事实是两大传统正在方法上相互靠拢。"}, {"order": 10, "qtype": "essay", "stem": "试论成文法与不成文法的区分为何是『重心』之分而非『有无』之分。", "options": [], "answer": "", "accepted": [], "keywords": [["来源与表现形式不同", "制定行为与判例习惯"], ["现代各国普遍混合", "大陆法有判例普通法有成文法"], ["重心差别", "法典为骨架与判例为骨架"], ["区分是分析工具", "非永久标签"]], "explanation": "【答案要点】见 keywords。【解题思路】从定义出发，说明两种形态在现代体系中并存，最后归结为重心的不同。【逐步演示】第一步：成文法源于制定行为，不成文法源于判例与习惯；第二步：大陆法国家有判例，普通法国家有成文法与法典；第三步：差别在体系骨架是法典还是判例；第四步：因此该区分是有用的分析工具而非固定标签。【易错提醒】不要用『一个只有成文法、一个只有判例』的绝对化表述。"}, {"order": 11, "qtype": "judge", "stem": "英国宪法惯例因没有严格法律制裁，所以完全不属于法律体系的组成部分。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】惯例虽无严格制裁，却在官员实践中被接受为行为标准、并在裁判中被援引。【逐步演示】从哈特的内部观点看，惯例可被纳入法律体系的功能范围。【易错提醒】把法律等同于『有制裁的成文规则』是过于狭窄的定义，英国宪法正是对它的反例。"}, {"order": 12, "qtype": "multi", "stem": "关于成文法与不成文法，下列说法符合 Siems 阐述的有：", "options": ["A 普通法国家也存在成文法与法典", "B 大陆法法典追求清晰连贯自足完整", "C 两大传统的法律解释方法正在相互靠拢", "D 不成文法传统中制定法被视为某种例外"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项分别对应 Siems 关于成文法在普通法世界的存在、大陆法法典理念、方法趋同与制定法地位的判断。【逐步演示】UCC 是 A 的例证；法典理念见 B；注解方法与目的论方法向普通法靠拢见 C；制定法被视为例外见 D。【易错提醒】本题四选全对，说明成文与不成文的界限比教科书公式更流动。"}]}, "S1M2K3": {"lesson": "S1M2K3", "questions": [{"order": 1, "qtype": "single", "stem": "世界上第一部成文的国家宪法通常指：", "options": ["A 英国《大宪章》（1215）", "B 美国宪法（1787）", "C 德国《基本法》（1949）", "D 法国民法典（1804）"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】美国1787年宪法是世界上第一部成文的国家宪法。【逐步演示】它以根本法姿态为普通法律设定边界，并提出由谁判定法律违宪的问题。【易错提醒】《大宪章》是1215年的封建文件，不是近代意义上的成文宪法典；法国1804年是民法典而非宪法。"}, {"order": 2, "qtype": "single", "stem": "美国确立司法审查制度的标志性判例是：", "options": ["A 马伯里诉麦迪逊案（1803）", "B 布朗诉教育委员会案（1954）", "C 罗诉韦德案（1973）", "D 谢弗林案（1984）"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Marbury v. Madison, 5 US 137 (1803) 是美国最高法院确立司法审查的 landmark decision。【逐步演示】Siems 明确指出，美国最高法院在1803年的这一判决中允许对议会立法进行司法审查。【易错提醒】其他三项虽是美国宪法史上的重要判例，但与司法审查制度的确立无关。"}, {"order": 3, "qtype": "judge", "stem": "在德国，违宪审查主要由普通法院在审理个案时附带进行，与美国模式相同。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德国采取的是独立宪法法院的集中审查模式，与美国普通法院的分散审查不同。【逐步演示】Siems 把德国列入设立独立宪法法院（或宪法委员会）的国家，其理论基础是凯尔森区分适用与评价的主张。【易错提醒】美国、瑞典、瑞士由同一法院处理宪法与其他问题；德国、奥地利、法国、意大利则设专门机关，不要混淆。"}, {"order": 4, "qtype": "blank", "stem": "英国宪法中，议会立法权至上的原则被称为______。", "options": [], "answer": "", "accepted": ["议会主权", "parliamentary sovereignty", "议会至上", "议会主权原则"], "keywords": [], "explanation": "【答案】议会主权（Parliamentary Sovereignty）。【解题思路】英国遵循相对严格的议会主权模型，法院对议会立法的审查持克制态度。【逐步演示】这与美国的司法审查模式形成鲜明对照。【易错提醒】不要因为英国有《权利法案》就以为它采取美国式司法审查，两国宪法哲学不同。"}, {"order": 5, "qtype": "multi", "stem": "关于行政法规，下列说法正确的有：", "options": ["A 由行政机关依法律授权制定", "B 效力低于法律", "C 不得与法律抵触", "D 其制定无需任何法律依据"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】行政法规由行政机关在法律授权范围内制定，效力低于法律，不得抵触法律。【逐步演示】越权无效是行政立法的基本控制原则。【易错提醒】D 错在『无需任何法律依据』，行政机关不能自我授权，这是法律保留与授权明确性要求的核心。"}, {"order": 6, "qtype": "single", "stem": "在大陆法国家，判例的一般地位是：", "options": ["A 正式法源，具有约束力", "B 不是正式法源，但常被下级法院参考", "C 效力高于法律", "D 完全不被法院提及"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出大陆法国家判例通常不是法源，但上级法院裁判在实践中具有类似先例的影响。【逐步演示】法国判决风格简洁，学者评注对沟通判例与学理具有重要作用。【易错提醒】A 是普通法系的特征；D 绝对化，与事实不符。"}, {"order": 7, "qtype": "essay", "stem": "试比较美国与德国的违宪审查模式，并说明其理论基础差异。", "options": [], "answer": "", "accepted": [], "keywords": [["美国普通法院附带分散审查", "马伯里案1803"], ["德国独立宪法法院集中审查", "联邦宪法法院"], ["凯尔森区分适用与评价", "普通法院不评价议会法律"], ["都是宪法至上但制度配置不同", "受历史传统影响"]], "explanation": "【答案要点】见 keywords。【解题思路】先分别说明两种模式，再追溯理论基础，最后指出共同点与制度差异。【逐步演示】第一步：美国自1803年起由普通法院在个案中审查；第二步：德国设联邦宪法法院集中审查；第三步：凯尔森主张普通法院只适用不评价议会法律；第四步：二者都承认宪法至上，但制度配置由各国历史决定。【易错提醒】不要把两种模式说成同一制度的不同阶段，它们是并存的替代方案。"}, {"order": 8, "qtype": "judge", "stem": "凯尔森认为普通法院既应适用议会法律，也有权评价其是否合宪。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出凯尔森主张普通法院只承担适用任务，不承担评价议会法律的任务。【逐步演示】这一立场成为独立宪法法院模式的理论基础。【易错提醒】把凯尔森与美国式分散审查混为一谈是常见错误，他恰好是集中审查模式的理论来源。"}, {"order": 9, "qtype": "single", "stem": "Siems 指出，法国在1958年引入了何种制度变化？", "options": ["A 全面采纳美国式司法审查", "B 引入有限制的抽象形式的违宪审查", "C 废除宪法委员会", "D 确立议会主权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 记述法国最初与英国类似，1958年引入有限制的抽象形式审查，2008年允许公民提出宪法申诉。【逐步演示】这显示审查制度处于渐进演变中。【易错提醒】法国并未全面采纳美国模式，它有自己的宪法委员会（Conseil Constitutionnel）传统。"}, {"order": 10, "qtype": "multi", "stem": "根据 Siems，下列哪些国家采用独立宪法法院（或宪法委员会）模式？", "options": ["A 德国", "B 奥地利", "C 法国", "D 美国"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 列举奥地利、德国、法国、意大利等国设有独立宪法法院或宪法委员会。【逐步演示】D 美国采取的是普通法院附带审查模式，由同一法院处理宪法与其他问题。【易错提醒】瑞典、瑞士与美国同属『同一法院』模式，不要与欧陆集中模式混淆。"}, {"order": 11, "qtype": "blank", "stem": "凯尔森把法律体系描述为一个规范______，每一规范的效力来自更高规范，最终追溯到基础规范。", "options": [], "answer": "", "accepted": ["层级", "体系", "等级体系", "hierarchy", "层级体系"], "keywords": [], "explanation": "【答案】层级（hierarchy）。【解题思路】Wacks 记述凯尔森把法律体系表示为环环相扣的规范层级，从最一般的『应当』到最具体的个案规范。【逐步演示】宪法高于法律、法律高于行政法规，正是这一层级的具体化。【易错提醒】基础规范（Grundnorm）是层级顶端的预设，不要把它与宪法本身等同。"}, {"order": 12, "qtype": "essay", "stem": "结合马伯里诉麦迪逊案，分析『宪法高于法律』这一命题如何从抽象原则转化为具体制度。", "options": [], "answer": "", "accepted": [], "keywords": [["宪法是最高法", "与宪法抵触的法律无效"], ["马歇尔三步推理", "权利受侵害需救济须有法律依据条款违宪"], ["法院宣告违宪法律无效", "司法审查确立"], ["影响多国制度", "1803 landmark decision"]], "explanation": "【答案要点】见 keywords。【解题思路】概述案情与争议焦点，逐层展示判决推理，最后说明制度意义。【逐步演示】第一步：宪法至上只是原则；第二步：马歇尔确认权利有救济但须依法；第三步：《司法法》扩张管辖权违宪故无效；第四步：法院据此取得审查权，形成制度。【易错提醒】不要把该案简化为『马伯里胜诉』，事实上他败诉，制度收益来自判决说理。"}, {"order": 13, "qtype": "judge", "stem": "在英国，法院传统上可以以违宪为由推翻议会通过的主要立法。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】英国遵循相对严格的议会主权模型，法院对议会立法的审查持克制态度。【逐步演示】Siems 把英国列为对司法审查『较为犹豫』的典型。【易错提醒】这与美国1803年后的做法根本不同，反映两种宪法哲学的分歧，不要用美国经验套英国制度。"}]}, "S1M2K4": {"lesson": "S1M2K4", "questions": [{"order": 1, "qtype": "single", "stem": "凯尔森用来解释法律效力传递的核心概念是：", "options": ["A 承认规则", "B 规范层级与基础规范", "C 议会主权", "D 法律与道德分离"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】凯尔森把法律体系描述为规范层级，每一规范的效力来自更高规范，最终追溯到被预设的基础规范。【逐步演示】Wacks 记述这一链条从最抽象的『应当』一直延伸到最个别化的强制行为。【易错提醒】承认规则属于哈特，议会主权属于英国宪法传统，均非凯尔森的概念。"}, {"order": 2, "qtype": "single", "stem": "关于基础规范（Grundnorm）的性质，符合 Wacks 阐述的是：", "options": ["A 它是一部成文宪法", "B 它是被预设的、非可观察的理论支点", "C 它由议会制定", "D 它等同于承认规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】凯尔森的基础规范因其效力不能依赖其他规范，只能被预设。【逐步演示】Wacks 指出这本身是争议话题：基础规范究竟是预设，还是存在于法律意识之中。【易错提醒】基础规范不是宪法本身，也与哈特可观察的承认规则性质不同。"}, {"order": 3, "qtype": "judge", "stem": "哈特的承认规则与凯尔森的基础规范功能相近，但前者是可观察的社会实践，后者是理论预设。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 第4.1节专节比较二者，指出功能相近而性质不同。【逐步演示】承认规则以官员实际遵循为存在条件；基础规范是被预设的效力支点。【易错提醒】不要把二者说成完全等同，这是理解实证主义内部差异的关键。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于法律渊源层级中的冲突解决规则？", "options": ["A 上位法优于下位法", "B 后法优于前法", "C 特别法优于一般法", "D 多数决优于少数决"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】lex superior、lex posterior、lex specialis 是处理规范冲突的三项经典规则。【逐步演示】它们使法律体系在规则打架时仍能保持统一与可预测。【易错提醒】D 是民主决策规则，不是法律渊源层级的冲突规则。"}, {"order": 5, "qtype": "blank", "stem": "凯尔森以『______与强盗』的对比说明：只有前者的要求是客观有效的，因为其强制秩序具有持久有效性。", "options": [], "answer": "", "accepted": ["收税人", "税务官", "征税人", "税收官"], "keywords": [], "explanation": "【答案】收税人。【解题思路】Wacks 记述凯尔森以收税人与强盗作比：二者都要求交钱，但只有收税人的要求客观有效。【逐步演示】差别在于强盗的强制命令缺乏持久有效性，人们不会预设一个要求服从它的基础规范。【易错提醒】这个比喻意在说明有效性与单纯强制的区别，不要理解成道德评价。"}, {"order": 6, "qtype": "single", "stem": "拉兹的『渊源命题』主张：", "options": ["A 法律与道德必然联系", "B 法律的识别应诉诸社会来源而非道德价值", "C 法官可自由创造法律", "D 宪法是可被预设的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】渊源命题（Sources Thesis）主张法律的存在与识别取决于可观察的社会来源。【逐步演示】它把实证主义来源取向推向纯粹形态，道德价值不影响『是不是法律』的判断。【易错提醒】A 是自然法立场，与拉兹相反。"}, {"order": 7, "qtype": "single", "stem": "Siems 提到，瑞士民法典明文规定了法源顺序：法典未规定时依习惯法，仍无规定时依法官作为立法者会确立的规则。这体现了：", "options": ["A 对法官造法的完全禁止", "B 把法源层级规则写进法典的罕见做法", "C 习惯法效力高于法典", "D 判例成为唯一正式法源"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 以瑞士民法典第1条第2款说明大陆法承认在例外情形下由法官填补漏洞。【逐步演示】该条把『法典—习惯法—法官规则』的顺序明文化，是法源层级正式化的罕见实例。【易错提醒】它恰恰允许而非禁止法官在穷尽既定渊源后造法，A 与事实相反。"}, {"order": 8, "qtype": "judge", "stem": "在大陆法国家，学者的『主流学说』虽然没有正式约束力，却可能具有几乎与实在法相当的影响力。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出德国的 herrschende Lehre、法国的 la doctrine 虽非法律渊源，影响力却几乎与实在法相当。【逐步演示】大陆法国家法院常认真参考学术著作，只是不把它当作正式法源。【易错提醒】注意『非正式法源』不等于『没有影响力』，二者是不同维度的判断。"}, {"order": 9, "qtype": "essay", "stem": "比较凯尔森与哈特关于法律效力终极基础的解释，说明二者的异同。", "options": [], "answer": "", "accepted": [], "keywords": [["都寻求效力终极支点", "拒绝以道德为基础"], ["凯尔森基础规范是被预设", "理论构造"], ["哈特承认规则是社会实践", "官员实际遵循"], ["功能相近性质不同", "Wacks第4.1节"]], "explanation": "【答案要点】见 keywords。【解题思路】先指出共同点，再分别说明性质差异，最后归结为功能相近、性质不同。【逐步演示】第一步：二者都回答效力最终从何而来且都排斥道德；第二步：凯尔森溯及被预设的基础规范；第三步：哈特溯及被官员实践遵循的承认规则；第四步：Wacks 认为二者功能相近而性质不同。【易错提醒】不要混淆『逻辑上完备』与『经验上可检验』两种评价维度。"}, {"order": 10, "qtype": "single", "stem": "1930年2月13日，法国最高法院合并庭在 Jand'heur 案中作出的重要裁判是：", "options": ["A 宣告某法律违宪", "B 把民法典第1384条解释为规定严格责任", "C 废除民法典", "D 确立陪审团制度"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 记述，法国最高法院合并庭于1930年2月13日在 Jand'heur 案中把《法国民法典》第1384条解释为规定严格责任。【逐步演示】这显示法国法院在法典框架内通过解释发展责任法，减少了对特别立法的需求。【易错提醒】注意日期与法院：1930年、Cour de Cassation 合并庭，不要与英国1868年的 Rylands 案混淆。"}, {"order": 11, "qtype": "single", "stem": "英国上议院在 Rylands v. Fletcher 案（[1868] UKHL 1）中确立的规则是：", "options": ["A 合同必须履行", "B 某物从土地逃逸造成损害时占有人承担严格责任", "C 议会主权原则", "D 司法审查制度"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 记述，1868年上议院在 Rylands v. Fletcher 案中判定，某物从土地逃逸造成损害时占有人承担严格责任。【逐步演示】这是普通法通过判例创设规则的经典例证。【易错提醒】该案与严格责任相关，与议会主权、司法审查等宪法议题无关。"}, {"order": 12, "qtype": "multi", "stem": "关于 Jand'heur 案与 Rylands 案的对照，下列说法正确的有：", "options": ["A 法国法院诉诸法典条文的解释", "B 英国法院通过判例直接创设规则", "C 德国法院倾向于不越过特别立法", "D 三国法院采取了完全相同的方法"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 的对照显示：德国恪守立法边界，法国通过法典解释发展规则，英国以判例创设规则。【逐步演示】D 不成立，三国方法差异恰恰是渊源层级文化差异的体现。【易错提醒】不要把『问题相似』误认为『方法相同』，比较法关注的正是在相似问题下的不同制度路径。"}, {"order": 13, "qtype": "essay", "stem": "试论德沃金对哈特法律渊源理论的批评及其意义。", "options": [], "answer": "", "accepted": [], "keywords": [["哈特的规则模型遗漏原则", "原则以分量起作用"], ["原则非全有或全无", "与规则适用方式不同"], ["法律渊源扩展到原则", "不只制定法与判例"], ["哈特后记回应原则可经承认规则识别", "争论深化"]], "explanation": "【答案要点】见 keywords。【解题思路】概述德沃金批评，说明原则与规则的差别，最后指出争论意义。【逐步演示】第一步：德沃金批评规则模型遗漏原则；第二步：原则以分量而非全有全无方式适用；第三步：这意味着渊源范围扩展到道德原则；第四步：哈特在后记中回应原则可通过承认规则被识别。【易错提醒】不要说哈特『否认原则存在』，他承认原则但坚持可从社会来源角度说明其识别。"}]}, "S1M2K5": {"lesson": "S1M2K5", "questions": [{"order": 1, "qtype": "single", "stem": "依 Siems 之见，普通法国家与大陆法国家的划分标准主要是：", "options": ["A 国土面积大小", "B 以英国法为基础与受欧洲大陆传统影响", "C 是否实行民主制度", "D 语言是否相同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出，大致而言普通法国家是以英国法为基础的法律体系，大陆法国家是受欧洲大陆传统影响的体系。【逐步演示】这一标签反映了法律史、法律思维与实在法特征的亲缘关系。【易错提醒】法系划分依据法律现象，而非国土、政体或语言等外部因素。"}, {"order": 2, "qtype": "multi", "stem": "Siems 指出『common law』一词具有多重含义，包括：", "options": ["A 一国之内与衡平法相对的部分", "B 与制定法相对的判例法", "C 与地方法相对的共同法", "D 以英国法为渊源的法系"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】Siems 列举了 common law 的四类含义：与 equity 相对、与 statute law 相对的判例法、与地方法相对的适用范围更广的法、以及比较法上的法系标签。【逐步演示】这说明谈差异前必须先确定使用层次。【易错提醒】同一个词在不同语境含义不同，不加区分地讨论容易造成混乱。"}, {"order": 3, "qtype": "single", "stem": "大陆法传统被称为『学者的法』（learned law），主要因为：", "options": ["A 法官主导法律发展", "B 大学推动了罗马法的继受，学者影响深远", "C 立法机关不存在", "D 判例是唯一法源"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出十一世纪欧洲大陆继受罗马法时，大学支持了这一进程，故大陆法常被称为『学者的法』。【逐步演示】德国教授甚至被认为『写』了1900年民法典，学理影响巨大。【易错提醒】A 是普通法特征；C、D 与大陆法的实际制度不符。"}, {"order": 4, "qtype": "blank", "stem": "1066年诺曼征服后，英格兰以标准化的______为基础形成普通法，这些诉讼形式后来转化为实体规则。", "options": [], "answer": "", "accepted": ["令状", "writs", " writ", "诉讼形式", "writs（令状）"], "keywords": [], "explanation": "【答案】令状（Writs）。【解题思路】Siems 指出，威廉及其后继者以标准化令状为基础建立普通法，法院以伦敦为中心，巡回法官在各地办案。【逐步演示】Maitland 名言说这些诉讼形式虽被埋葬却仍在统治，强调其持久影响。【易错提醒】令状是程序形式，后来才转化为实体规则，不要倒置这一历史顺序。"}, {"order": 5, "qtype": "single", "stem": "《法国民法典》1804年与《德国民法典》1900年在风格上的差别，Siems 的描述是：", "options": ["A 前者概念化学院化，后者像圣经一样简单", "B 前者追求通俗易懂，后者更概念化学院化", "C 两者风格完全一致", "D 前者是判例汇编，后者是宪法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出《法国民法典》以抽象方式起草同时力图让公众理解（『像圣经一样简单』），而《德国民法典》风格更概念化、更教授化。【逐步演示】这显示即使同属大陆法系，法典化也造成了内部差异。【易错提醒】注意不要记反两部法典的风格，这是比较法常识题的高频考点。"}, {"order": 6, "qtype": "judge", "stem": "普通法国家不存在法典化，因此『普通法靠判例、大陆法靠法典』是一条绝对准确的对照。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确指出普通法国家的法典化并不罕见，如菲尔德的民事诉讼法典、加州民法典、UCC 及印度独立前的法典。【逐步演示】差别在于普通法法典多为既有判例的合并整理，体系化程度较低。【易错提醒】『绝对准确』『完全不存在』这类表述在比较法中几乎总是危险的。"}, {"order": 7, "qtype": "multi", "stem": "依 Siems，下列哪些属于两大法系差异的核心主题？", "options": ["A 法律渊源与法律方法", "B 法律风格与技术", "C 制度与程序", "D 国土与人口"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 指出比较法通说认为法律渊源与法律方法、法律风格与技术、制度与程序是二分的核心主题，另加合同法这一具体领域。【逐步演示】D 与法律现象无关。【易错提醒】记住『渊源—方法—风格—制度—程序』这一组关键词，可覆盖本节主干。"}, {"order": 8, "qtype": "single", "stem": "普通法司法解释中的『瑕疵规则』（mischief rule）旨在：", "options": ["A 严格按字面含义解释", "B 弥补法律本欲救治的缺陷", "C 避免任何荒谬结果", "D 完全推翻制定法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出普通法传统上有字面规则、黄金规则（避免荒谬结果）与瑕疵规则（弥补法律欲救治的缺陷）。【逐步演示】A 对应 literal rule，C 对应 golden rule，D 无此规则。【易错提醒】三种解释规则的名字与功能容易混淆，建议成对记忆。"}, {"order": 9, "qtype": "single", "stem": "茨威格特与科茨提出的『相似推定』（praesumptio similitudinis）主张：", "options": ["A 各国法律在一切领域都完全相同", "B 撇开深受道德影响的领域，发达国家私法对类似实务需求有相似回应", "C 两大法系没有任何差异", "D 普通法优于大陆法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Zweigert 与 Kötz 主张，撇开家庭法与继承法等受道德观深刻影响的领域，聚焦相对非政治性的私法，发达国家以相同或非常相似的方式回应法律实务需求。【逐步演示】Siems 指出这一命题仅针对发达国家，且差异『更多在形式而非实质』。【易错提醒】该命题有明确的适用边界，不要扩大为『一切领域完全相同』。"}, {"order": 10, "qtype": "judge", "stem": "Siems 认为，二战后比较法由欧陆学者与移居美国的犹太移民主导，这可能使学者倾向于强调不同国家与宗教人群之间的共性。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 给出了对趋同倾向的心理学／社会学解释：二战后比较法领域的主导群体有强调共性的倾向。【逐步演示】这是学术史反思，而非对趋同结论本身的否定。【易错提醒】注意区分『解释某命题为何被提出』与『判断该命题是否正确』，二者不是一回事。"}, {"order": 11, "qtype": "essay", "stem": "试论普通法与大陆法在法官角色上的差异，并说明现代趋势是否正在消解这一差异。", "options": [], "answer": "", "accepted": [], "keywords": [["普通法官造法判例为主干", "反应性自下而上发展"], ["大陆法官适用法遵循立法者", "职业文官层级负荷"], ["方法相互靠拢", "大陆转向目的论普通转向立法史"], ["差异真实但非绝对", "典型倾向而非非此即彼"]], "explanation": "【答案要点】见 keywords。【解题思路】先分别描述两种角色，再说明趋同趋势，最后作辩证总结。【逐步演示】第一步：普通法法官通过先例自下而上发展法律，较愿展现司法创造性；第二步：大陆法法官侧重适用制定法，身处职业层级且负荷高；第三步：大陆法解释转向注解与目的论，普通法解释转向立法史与目的；第四步：差异是典型倾向而非绝对对立。【易错提醒】不要把『趋同』写成『差异消失』，Siems 强调差异仍然存在。"}, {"order": 12, "qtype": "single", "stem": "1930年法国最高法院在 Jand'heur 案中的裁判，体现了大陆法法官的何种方法？", "options": ["A 完全无视法典条文", "B 从民法典一般条款中解释出规则", "C 宣告法律违宪", "D 直接推翻既有判例"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 记述，Cour de Cassation 合并庭于1930年2月13日把《法国民法典》第1384条解释为规定严格责任。【逐步演示】这体现大陆法法官须把论证锚定在法典之上，以解释为主要工具。【易错提醒】不要既用法国法院须锚定法典，又说它『完全无视法典』，两种说法自相矛盾。"}, {"order": 13, "qtype": "multi", "stem": "关于德国、法国、英国在严格责任发展上的对照，下列说法正确的有：", "options": ["A 德国法院倾向于不越过特别立法", "B 法国法院通过解释民法典发展出严格责任", "C 英国上议院在 Rylands 案中以判例创设严格责任", "D 三国的方法完全相同"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 指出德国法院恪守特别法边界、法国法院解释法典一般条款、英国上议院在1868年 Rylands 案中以判例确立严格责任。【逐步演示】D 错误，三国方法的差异正是法系方法差异的例证。【易错提醒】相似的社会问题导致相似结果，不等于相似方法；比较法关注的是路径差异。"}, {"order": 14, "qtype": "essay", "stem": "结合 Siems 的批判性立场，分析『法系分类』的价值与局限。", "options": [], "answer": "", "accepted": [], "keywords": [["法系反映法律史思维实在法亲缘", "世界法律地图"], ["典型特征源于少数国家影响", "法德英美的投射"], ["影响减弱新领域兴起", "国际跨国法具体领域"], ["需反思分类的历史局限", "欧洲中心新殖民偏见"]], "explanation": "【答案要点】见 keywords。【解题思路】先肯定法系分类的描述价值，再指出其简化风险，最后归结为审慎使用。【逐步演示】第一步：法系分类把法律多样性归纳为有亲缘关系的群组；第二步：Siems 指出典型特征主要来自法德英美四国的影响；第三步：法系观念近年影响减弱，比较法转向国际法、跨国法与具体领域；第四步：分类可能带有欧洲中心与新殖民偏见，需保持反思。【易错提醒】不要走向『法系分类毫无价值』的极端，Siems 的立场是既使用又反思。"}]}, "S1M2K6": {"lesson": "S1M2K6", "questions": [{"order": 1, "qtype": "single", "stem": "凯尔森把法律规范还原为哪种基本形式？", "options": ["A 命令加制裁", "B 如果X，那么Y（条件—制裁）", "C 原则加规则", "D 权利加义务"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记述，凯尔森把一切立法还原为『如果X，那么Y』的形式，其中X是某行为，Y是制裁。【逐步演示】这一还原体现他关于法律本质上是强制的预设。【易错提醒】A 是奥斯丁命令理论，C 是德沃金的框架，均非凯尔森的还原式。"}, {"order": 2, "qtype": "judge", "stem": "哈特认为，制裁是法律的『Plan B』，法律规范的『Plan A』是人们在无人监督时自发遵守。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Green 在《法律的概念》导论中指出，制裁是法律的 Plan B，Plan A 是人们在无人监督时自发遵守。【逐步演示】这说明许多法律规范并不以制裁为后盾。【易错提醒】承认制裁不是本质，不等于否认强制的存在；哈特反对的是把强制当作法律的核心。"}, {"order": 3, "qtype": "multi", "stem": "依哈特，下列哪些属于『授权规则』的例子？", "options": ["A 规定如何订立合同", "B 规定结婚的法定方式", "C 禁止杀人", "D 规定如何订立遗嘱"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】授权规则赋予人们改变法律地位的能力，立法、结婚、订立合同、订立遗嘱均属此类。【逐步演示】C 禁止杀人是典型的义务规则，要求人们不做特定行为。【易错提醒】授权规则的不遵守导致『无效』而非『处罚』，这是它与义务规则的关键差别。"}, {"order": 4, "qtype": "single", "stem": "哈特以象棋为喻，说明规则与习惯的差别在于：", "options": ["A 习惯有文字记载，规则没有", "B 规则伴随着批判反思态度，被当作评价标准", "C 规则不由任何人遵守", "D 习惯具有法律效力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记述哈特的象棋例子：棋手除共享走法外，还持有『批判反思态度』，把走法当作标准并互相批评。【逐步演示】这使规则区别于单纯被观察到的行为习惯。【易错提醒】A 表述有误且非哈特论点，C、D 均不符合哈特的原意。"}, {"order": 5, "qtype": "blank", "stem": "哈特指出语言具有『______』：词语有清晰的核心含义，却总有适用与否不确定的临界案件。", "options": [], "answer": "", "accepted": ["开放结构", "open texture", "开放性结构", "语言的开放结构"], "keywords": [], "explanation": "【答案】开放结构（Open Texture）。【解题思路】Wacks 记述哈特认为语言有开放结构，有清晰核心也有『临界案件』（penumbral cases）。【逐步演示】这解释了为何规则无法为一切案件预置答案。【易错提醒】不要因此走向法律现实主义式的『词义完全任意』，哈特明确反对这种极端看法。"}, {"order": 6, "qtype": "judge", "stem": "哈特认为，由于语言具有开放结构，多数案件中法官都必须诉诸道德或政治考量才能作出裁判。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，哈特明确反驳『词义完全任意』的看法，认为多数案件中法官直接适用规则即可。【逐步演示】只有临界案件才需要裁量与道德政治考量。【易错提醒】把哈特与法律现实主义混为一谈是常见错误，他承认模糊性但拒绝规则怀疑论。"}, {"order": 7, "qtype": "single", "stem": "德沃金用 Riggs v. Palmer 案主要是为了证明：", "options": ["A 规则以全有或全无方式适用", "B 法律包含规则之外的原则标准", "C 司法审查的正当性", "D 议会主权原则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记述，德沃金以 Riggs 案反驳『规则模型』，主张法律包含原则。【逐步演示】法院在规则沉默处援引『任何人不得从自己的错误中获利』的原则，说明法律材料大于规则集合。【易错提醒】A 是规则的特征，但恰恰是德沃金要批评的模型，不要答反。"}, {"order": 8, "qtype": "single", "stem": "Riggs v. Palmer 案（115 NY 506, 1889）的争议焦点是：", "options": ["A 遗嘱是否符合形式要求", "B 谋杀者能否依有效遗嘱继承被害人遗产", "C 法院是否有权审查法律", "D 合同是否成立"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记述，该案的核心问题是谋杀者能否依被害人的有效遗嘱继承。【逐步演示】遗嘱形式有效且无明示例外，但法院依据原则否定继承权。【易错提醒】记住判例要旨与年份：纽约州法院1889年判决，不要在细节上张冠李戴。"}, {"order": 9, "qtype": "blank", "stem": "Riggs v. Palmer 案中法院所援引的原则是『任何人不得从自己的______中获利』。", "options": [], "answer": "", "accepted": ["错误", "过错", "违法行为", "wrong", "不法行为", "罪恶"], "keywords": [], "explanation": "【答案】错误（wrong）。【解题思路】Wacks 记述该原则是『no man should profit from his own wrong』。【逐步演示】它以分量压倒了『有效遗嘱应予执行』这一规则所代表的确定性价值。【易错提醒】这是原则而非规则，其适用方式是权衡分量，不是全有全无。"}, {"order": 10, "qtype": "single", "stem": "规则与原则在适用方式上的关键差别是：", "options": ["A 规则有分量，原则全有全无", "B 规则全有全无，原则以分量起作用", "C 二者完全相同", "D 原则一律优于规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金指出，规则以全有或全无方式适用，原则则以分量参与权衡。【逐步演示】原则不直接决定结论，而是在与其他原则的权衡中提供理由。【易错提醒】D 过于绝对，原则并非一律压倒规则，而是视具体情境的分量而定。"}, {"order": 11, "qtype": "essay", "stem": "试比较凯尔森与哈特对法律规范结构的理解，并说明哈特为何把制裁降为『Plan B』。", "options": [], "answer": "", "accepted": [], "keywords": [["凯尔森条件制裁模式", "如果X那么Y"], ["哈特规则实践与内部观点", "批判反思态度"], ["制裁非普遍要素", "无罚则规范与授权规则"], ["Plan A自发遵守Plan B制裁", "反对强制本质论"]], "explanation": "【答案要点】见 keywords。【解题思路】先分别说明两种理解，再解释 Plan B 的含义与理由。【逐步演示】第一步：凯尔森把规范还原为条件—制裁式；第二步：哈特把规范理解为被内部观点接受的规则；第三步：无罚则规范与授权规则显示制裁并非普遍要素；第四步：Plan A 是自发遵守，制裁只是备用方案，故哈特反对以强制界定法律本质。【易错提醒】不要说哈特『否认制裁』，他只是反对把制裁当作法律的核心。"}, {"order": 12, "qtype": "multi", "stem": "关于中文法理学的『三要素说』与哈特的规则分类，下列说法正确的有：", "options": ["A 三要素说分析单条规则的构成", "B 哈特的功能分类分析规则在体系中的作用", "C 二者是竞争关系，必须二选一", "D 二者属不同分析层次，可并用"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】三要素说分析假定条件、行为模式、法律后果；哈特区分义务规则与授权规则、初级与次级规则，属功能与体系层次。【逐步演示】二者分析层次不同，可以并用而非互斥。【易错提醒】C 把不同层次的分析工具说成必须二选一，是范畴错误。"}, {"order": 13, "qtype": "judge", "stem": "哈特在后记中承认法律体系包含原则，但同时坚持原则的识别最终仍须诉诸承认规则的社会实践。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特在后记中作出两项让步：承认原则存在、承认承认规则可识别原则，但坚持识别须诉诸社会实践。【逐步演示】争论焦点因此从『有没有原则』转向『原则如何被识别』。【易错提醒】不要简单说哈特『否认原则』，他承认原则但坚持从社会来源角度说明其识别。"}, {"order": 14, "qtype": "essay", "stem": "结合 Riggs v. Palmer 案，论说法规范体系中规则与原则的互动关系。", "options": [], "answer": "", "accepted": [], "keywords": [["规则全有全无原则有分量", "适用方式不同"], ["原则在规则沉默处介入", "Riggs案谋杀者不得继承"], ["原则不推翻规则而是权衡", "分量压过确定性价值"], ["哈特式追问原则权限来源", "承认规则社会实践"]], "explanation": "【答案要点】见 keywords。【解题思路】从适用方式差异出发，结合案情说明原则如何介入，最后呈现两种理论解读。【逐步演示】第一步：规则全有全无，原则以分量起作用；第二步：Riggs 案中继承规则无例外，法院援引原则否定继承；第三步：原则并非推翻规则，而是其分量压过确定性价值；第四步：哈特可追问法院援引原则的权限来自承认规则的社会实践。【易错提醒】不要把本案说成『原则推翻规则』，准确说法是原则在特定情境中以其分量压倒规则。"}]}, "S1M3K1": {"lesson": "S1M3K1", "questions": [{"order": 1, "qtype": "single", "stem": "霍菲尔德（Hohfeld）把命题『X 有权做 R』拆解为四种含义，下列哪一项不属于这四种之一？", "options": ["A 主张权（Claim Right）", "B 自由权（Liberty/Privilege）", "C 豁免（Immunity）", "D 责任能力（Capacity）"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】霍菲尔德把『权利』拆为主张权、自由权、权力、豁免四种法律关系。【逐步演示】主张权对应义务，自由权对应无权利，权力对应责任（易受性），豁免对应无能力；责任能力不在其列。【易错提醒】不要把『权力（Power）』与『责任能力（Capacity）』混为一谈，前者才是霍菲尔德的四类之一。"}, {"order": 2, "qtype": "single", "stem": "按照霍菲尔德的分析，『X 有权戴帽子』意味着：", "options": ["A Y 负有不得阻止 X 戴帽子的义务", "B Y 对 X 不戴帽子享有主张权", "C X 可自由决定是否戴帽，Y 并不因此负义务", "D X 有权要求 Y 买一顶帽子送给她"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】戴帽子的权利属于自由权（liberty），其对应面是 Y 的『无权利』，而非 Y 的义务。【逐步演示】自由权只表示 X 可以做某事且不欠谁义务；Y 完全可以把帽子买光不卖，并不违约。【易错提醒】这是霍菲尔德的经典例子，切勿把自由权误读为『他人有义务不干涉』的主张权。"}, {"order": 3, "qtype": "judge", "stem": "霍菲尔德认为，自由权（liberty）的对应面（correlative）是他人的义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】自由权的对应面是『无权利』（no-right），主张权的对应面才是义务。【逐步演示】霍菲尔德的图式中：主张权—义务、自由权—无权利、权力—责任、豁免—无能力。【易错提醒】『自由』与『要求他人不干涉的权利』是两种不同性质的法律关系，这是本节最核心的辨析点。"}, {"order": 4, "qtype": "blank", "stem": "在霍菲尔德的图式中，主张权（claim right）的对应面（correlative）是______。", "options": [], "answer": "", "accepted": ["义务", "duty", "他人的义务", " Duty"], "keywords": [], "explanation": "【答案】义务（Duty）。【解题思路】主张权与义务如同一枚硬币的两面，这是相关性命题的核心。【逐步演示】X 有权要求 Y 不得踏入其土地，对应 Y 负有不得踏入的义务。【易错提醒】不要填『无权利』，那是自由权的对应面。"}, {"order": 5, "qtype": "single", "stem": "下列关于『权利与义务相关性命题』的表述，哪一项最为准确？", "options": ["A 任何义务都必然对应某个人的权利，毫无例外", "B 相关性是分析主张权的有力工具，但在刑法义务等场合遭遇反例", "C 权利与义务之间毫无关联", "D 相关性命题只适用于国际法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，相关性是分析法律权利的有力工具，但刑法中的义务（如警察举报犯罪的职责）常常不对应特定人的权利。【逐步演示】哈里斯为相关性辩护，称其为法律的『最小公分母』；麦考密克则指出义务常为保护权利而设，逻辑上先于权利。【易错提醒】A 的『毫无例外』过于绝对，是本节反复提醒要警惕的表述。"}, {"order": 6, "qtype": "single", "stem": "主张『权利的本质是权利人对义务能否履行拥有支配力，尤其是放弃他人义务的能力』，这是哪一理论？", "options": ["A 利益论（Interest Theory）", "B 意志论（Will Theory）", "C 法律现实主义", "D 自然法理论"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】意志论由哈特倡导，强调权利保护个人的选择、自由与自我实现，核心是对义务的支配与放弃能力。【逐步演示】利益论（麦考密克）则主张权利的目的是保护权利人的利益，而非选择。【易错提醒】题干中的『放弃义务的能力』是意志论的标志性表述。"}, {"order": 7, "qtype": "single", "stem": "麦考密克（MacCormick）用下列哪一例子反驳意志论，指出其会得出『儿童没有权利』的荒谬结论？", "options": ["A 警察追捕罪犯", "B 儿童的权利由其父母代为行使，儿童本人无从『放弃』", "C 某人戴帽子的自由", "D 国际条约的批准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】麦考密克指出，儿童的权利由父母或监护人行使，若以『能否放弃权利』为标准，就会得出儿童无权利的荒谬结论。【逐步演示】这成为利益论反驳意志论的关键论据。【易错提醒】儿童权利的例子同时说明：利益论能解释那些无法自主行使的权利，这是它的优势所在。"}, {"order": 8, "qtype": "multi", "stem": "根据 Wacks 的梳理，下列关于人权代际划分的表述，哪些是正确的？", "options": ["A 第一代以消极的政治公民权利为核心", "B 第二代本质是经济、社会、文化等积极权利", "C 第三代是集体的『团结权利』，如发展权、健康环境权", "D 第三代权利已完全取代前两代，成为唯一的人权形态"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 梳理了人权的三个代际：第一代消极权利、第二代积极权利、第三代团结权利。【逐步演示】三代是层累叠加的关系，并非相互替代。【易错提醒】D 的『完全取代』『唯一形态』是典型绝对化表述，与各代并存的史实不符。"}, {"order": 9, "qtype": "judge", "stem": "德沃金（Dworkin）的『权利作为王牌』命题主张，任何情况下个人权利都绝对不可被公共利益压倒。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金虽强调权利的优先性，但明确承认为避免灾难或取得重大利益时，权利可能被公共利益压倒。【逐步演示】他以言论自由为例，指出紧急状态下言论自由可能必须让步。【易错提醒】把德沃金包裹成『权利绝对主义者』是常见的漫画化误读，务必注意他自己的限定。"}, {"order": 10, "qtype": "single", "stem": "在 Johnson v Phillips（1976）一案中，法院倾向于认为：", "options": ["A 警官促进交通顺畅的义务对应每位驾车者的个人权利", "B 该义务属于面向公众的一般义务，并不对应特定个人的权利", "C 警官的行为构成违约", "D 驾车者享有逆行权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Johnson v Phillips 中，法院认为警察促进交通顺畅的职责在此情形下并未产生对应特定个人的权利。【逐步演示】Wacks 借此说明，刑法与公共职责中存在大量『无对应权利』的义务。【易错提醒】这个案例展示了相关性命题的适用边界，不要误以为每一份义务都配一把『权利』的钥匙。"}, {"order": 11, "qtype": "essay", "stem": "试述霍菲尔德对『权利』一词的四分法，并说明自由权（liberty）与主张权（claim right）的关键区别。", "options": [], "answer": "", "accepted": [], "keywords": [["主张权、自由权、权力、豁免四分", "claim right liberty power immunity"], ["主张权对应他人义务", "claim right correlative duty"], ["自由权对应无权利而非义务", "liberty correlative no-right"], ["自由权不要求他人不干涉", "戴帽子的例子"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先列出四分法，再聚焦自由权与主张权的对应面差异。【逐步演示】第一步说明主张权—义务、自由权—无权利的图式；第二步用戴帽子的例子说明自由权不蕴含他人有不干涉的义务；第三步总结二者性质不同。【易错提醒】最常见错误是把自由权说成『他人有义务不干涉』，这正是霍菲尔德要纠正的。"}, {"order": 12, "qtype": "judge", "stem": "Wacks 指出，找到一个能覆盖一切情形的『权利』统一定义，是法理学已经完成的任务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 强调权利概念被使用得过滥，其内涵与边界始终处在争论之中，远未完成统一。【逐步演示】他梳理了三代入权、多种权利理论，恰恰说明权利概念的开放性与争议性。【易错提醒】法理学中几乎没有『已经完成』的统一定义，凡见此类绝对表述都应警惕。"}, {"order": 13, "qtype": "essay", "stem": "结合意志论与利益论，分析『儿童权利』这一概念给权利理论带来的挑战，并说明你更倾向于哪一种理论。", "options": [], "answer": "", "accepted": [], "keywords": [["意志论强调支配与放弃能力", "will theory choice waiver"], ["利益论强调保护利益", "interest theory protector of interest"], ["儿童无法放弃权利", "父母代为行使"], ["若采意志论会得出儿童无权利的荒谬结论", "麦考密克的反驳"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分别说明两种理论的标准，再用儿童权利检验二者。【逐步演示】第一步解释意志论以支配/放弃为核心；第二步指出儿童无法放弃权利；第三步说明利益论能容纳儿童权利；第四步给出自己的立场并论证。【易错提醒】论述时不要简单断言某一理论『完全错误』，应说明各自适用场合与解释力差异。"}]}, "S1M3K2": {"lesson": "S1M3K2", "questions": [{"order": 1, "qtype": "single", "stem": "哈特（Hart）区分了『被迫去做』（being obliged）与『有义务去做』（having an obligation）。根据这一区分，持枪歹徒威胁你交出钱包时，你：", "options": ["A 有义务交出钱包", "B 不得不交出钱包，但并无『应当交出』的规范义务", "C 对歹徒负有契约义务", "D 完全自由地选择不交"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特指出，威胁只能使人『不得不』（obliged）做，无法产生『有义务』（obligation）的规范体验。【逐步演示】这是他批判奥斯丁命令理论的关键：抢匪的威胁与法律的义务性质不同。【易错提醒】obliged 与 obligation 的区分是哈特理论的经典考点，切勿混淆。"}, {"order": 2, "qtype": "judge", "stem": "消极自由（Negative Liberty）强调的是主体实际具备的自我实现能力，而非免于干涉。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】消极自由强调『免于干涉』，积极自由才关注自我实现与实质选择能力。【逐步演示】霍菲尔德的自由权对应『他人无权利』，属于消极自由的传统。【易错提醒】两种自由的定义恰好相反，这是伯林（Berlin）经典区分的核心，需牢记。"}, {"order": 3, "qtype": "single", "stem": "密尔（John Stuart Mill）为言论自由辩护的『真理论证』，其核心主张是：", "options": ["A 言论自由是人的尊严所要求的基本权利", "B 压制任何言论都是『假定自己不会犯错』，真理只能在自由流通中被发现", "C 国家应审查一切有害思想", "D 言论自由的价值完全在于促进经济增长"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】密尔认为任何压制都是『假设 infallible（不会犯错）』，只有 unrestricted 的思想流通才能发现真理。【逐步演示】这是典型的后果论/真理论证，与德沃金的权利论证路径不同。【易错提醒】A 是德沃金式的权利论证，注意区分两种论证路径。"}, {"order": 4, "qtype": "blank", "stem": "美国宪法第______修正案明言国会不得制定法律剥夺言论或出版自由。", "options": [], "answer": "", "accepted": ["一", "第一", "1", "One", "First", "第一修正案"], "keywords": [], "explanation": "【答案】第一修正案（First Amendment）。【解题思路】美国宪法第一修正案是言论自由保护的宪法基础。【逐步演示】Wacks 指出，美国的言论自由辩论以此为背景，保护水平在世界上属最高之列。【易错提醒】不要答成第十四修正案，后者主要涉及正当程序与平等保护。"}, {"order": 5, "qtype": "single", "stem": "Wacks 指出，英国在 1998 年《人权法》（Human Rights Act）影响下，法院对表达自由的理解趋向：", "options": ["A 完全照搬美国第一修正案模式", "B 趋于宽泛，但仍保留利益衡量", "C 彻底取消言论自由保护", "D 只保护政治言论"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出英国法院在人权法影响下对表达自由的理解趋于宽泛，但并未采纳美国近乎绝对的保护。【逐步演示】英国模式强调在言论自由与其他价值间作利益衡量。【易错提醒】美英两国的言论自由保护强度不同，不要混为一谈。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，下列哪些表述符合哈特关于自由与责任的观点？", "options": ["A 被威胁而行动的人，其意志被压倒，通常不被归责", "B 授权性规则让人得以塑造自己的法律世界，是自由的体现", "C 威胁能够产生真正的法律义务", "D 义务之所以是义务，仅因背后有制裁"], "answer": "AB", "accepted": [], "keywords": [], "explanation": "【答案】AB。【解题思路】哈特认为被胁迫者意志被压倒故不被归责；授权性规则把人变成『私人立法者』，体现自由。【逐步演示】C、D 都是哈特明确批判的奥斯丁式观点：威胁不产生义务，义务也非仅因制裁。【易错提醒】哈特反复强调义务与威胁的根本区分，这是其理论基石。"}, {"order": 7, "qtype": "judge", "stem": "富勒（Lon Fuller）的『洞穴探险者案』完全是虚构的，与任何真实判例都没有关联。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】富勒 1949 年的虚拟案例以两起真实判例为基础：R v Dudley & Stephens（1884）与 US v Holmes（1842）。【逐步演示】Wacks 明确指出其事实来源，用以说明必要性抗辩的边界。【易错提醒】思想实验虽是虚构的，但往往植根于真实判例，不要误以为它与法律实践无关。"}, {"order": 8, "qtype": "single", "stem": "在 R v Dudley & Stephens（1884）及相关洞穴探险者案中，法院对『必要性抗辩』的态度是：", "options": ["A 必要性可作为谋杀罪的完整抗辩", "B 必要性不能宽恕杀人，即便不杀也会死", "C 只要抽签公平就可免责", "D 仅在海上遇难时适用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】普通法拒绝把必要性扩展到杀人，即便饥饿致死的风险真实存在。【逐步演示】这划定了自由的边界：法律坚持生命的底线不因极端情境而让渡。【易错提醒】不要误以为『为了活命』就能正当化剥夺他人生命，这是该案最核心的裁判要旨。"}, {"order": 9, "qtype": "essay", "stem": "试论『自由是责任的前提，责任为自由划定边界』这一命题，并结合洞穴探险者案加以说明。", "options": [], "answer": "", "accepted": [], "keywords": [["责任以自由选择为前提", "自由选择是归责基础"], ["意志被压倒则不归责", "被胁迫者减免责任"], ["自由有边界需权衡", "我的自由止于你的自由"], ["洞穴探险者案：必要性不宽恕杀人", "生命底线"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先阐释命题的两面，再用案例检验。【逐步演示】第一步说明自由选择是归责基础；第二步说明意志被压倒时责任松动；第三步说明自由需受边界约束；第四步用洞穴探险者案展示极端情境下的权衡。【易错提醒】不要把命题写成单向的『自由越多责任越少』，二者是依存关系。"}, {"order": 10, "qtype": "single", "stem": "德沃金（Dworkin）把言论自由视为一项基本权利，其论证主要属于：", "options": ["A 后果论/政策论证", "B 原则论证，诉诸尊严与平等关怀", "C 纯粹的经济分析", "D 法律实证主义的渊源命题"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金把言论自由与人格尊严、平等关怀与尊重相连，属于原则论证。【逐步演示】Wacks 指出，保护听众的论证多为政策论证，保护说话者的论证多为原则论证。【易错提醒】德沃金是权利论的代表，不要把他的立场与密尔的后果论混淆。"}, {"order": 11, "qtype": "blank", "stem": "以赛亚·伯林（Isaiah Berlin）对自由概念的经典区分，是______自由与积极自由。", "options": [], "answer": "", "accepted": ["消极", "消极自由", "Negative", "negative"], "keywords": [], "explanation": "【答案】消极（Negative）。【解题思路】伯林区分了消极自由（免于干涉）与积极自由（自我实现）。【逐步演示】这一框架至今仍是分析自由概念的基本工具。【易错提醒】不要填『形式』『实质』等词，伯林的标准术语是消极/积极。"}, {"order": 12, "qtype": "judge", "stem": "按照 Wacks 的介绍，施auer（Schauer）对『真理论证』的质疑之一是：真理可能只是服务于更深层善（如幸福或尊严）的工具。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】施auer 追问真理是否 ultimate 且非工具性，指出真理可能服务于更深层的善。【逐步演示】若真理只是工具性的，『思想自由市场』的论证就不再无条件成立。【易错提醒】这是对密尔真理论证的重要限定，常被用来说明后果论论证的脆弱性。"}, {"order": 13, "qtype": "essay", "stem": "比较美国与英国在言论自由保护上的不同模式，并说明这种差异对『自由与责任』关系意味着什么。", "options": [], "answer": "", "accepted": [], "keywords": [["美国第一修正案近乎绝对保护", "First Amendment"], ["英国人权法下的利益衡量", "Human Rights Act 1998 balancing"], ["自由需与其他价值权衡", "尊严 名誉 公共秩序"], ["不同宪法传统保护强度不同", "非放之四海皆准"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先描述两种模式，再分析其法理含义。【逐步演示】第一步说明美国模式的宪法基础与保护强度；第二步说明英国的利益衡量路径；第三步指出自由总是要与责任及其他价值权衡；第四步提醒不能把某一模式普遍化。【易错提醒】不要简单断言哪一国模式『更好』，应说明各自的历史语境与权衡逻辑。"}]}, "S1M3K3": {"lesson": "S1M3K3", "questions": [{"order": 1, "qtype": "single", "stem": "下列关于权利能力（Legal Capacity）与行为能力（Capacity to Act）的表述，正确的是：", "options": ["A 二者是同一回事，可以互换使用", "B 婴儿有权利能力但无行为能力", "C 婴儿既无权利能力也无行为能力", "D 法人有行为能力但无权利能力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】权利能力是作为权利义务主体的资格，行为能力是以自己行为独立取得权利、承担义务的能力，二者分离。【逐步演示】婴儿可以拥有财产、继承遗产（有权利能力），却不能独立签合同（无行为能力）。【易错提醒】不要认为婴儿不具备任何法律资格，权利能力是法律保护其利益的基础。"}, {"order": 2, "qtype": "judge", "stem": "在罗马法中，奴隶与自由公民一样，都是完整的法律主体。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】罗马法中只有自由的罗马公民才具备完整人格，奴隶是权利的客体而非主体。【逐步演示】罗马法用身份（status）界定谁能成为权利主体，奴隶、外邦人、家子都受不同程度限制。【易错提醒】把现代法律主体的普遍化观念投射到古代，是常见的时代错置错误。"}, {"order": 3, "qtype": "blank", "stem": "法律拟制的人，如公司、社团、基金会，可在法律上独立享有权利与承担义务，这类主体被称为______。", "options": [], "answer": "", "accepted": ["法人", "法律人格", "juridical person", "legal person", "法律拟制人"], "keywords": [], "explanation": "【答案】法人（Juridical/Legal Person）。【解题思路】法人是法律拟制的人，与自然人的区别在于其人格来自法律的承认而非出生。【逐步演示】法人可以独立起诉应诉、拥有财产、承担责任。【易错提醒】不要把法人等同于其成员或股东，法人具有独立人格是現代公司法的基础。"}, {"order": 4, "qtype": "single", "stem": "哈特（Hart）反对把法律简化为『主权者命令臣民』的模型，强调现代法律体系中的主体：", "options": ["A 只能被动服从，无任何创设法律的能力", "B 可通过授权性规则创设自己的法律世界，成为『私人立法者』", "C 一律不具备权利能力", "D 与主权者处于同一个法律人格"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特指出，授权性规则让人能通过遗嘱、合同、婚姻塑造自己的法律世界，成为『私人立法者』。【逐步演示】这是他超越命令理论的关键：主体不仅承担义务，更能创设权利义务。【易错提醒】A 正是哈特批判的奥斯丁式模型，不要与哈特的立场混淆。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，下列关于法律主体能力分级的表述，哪些是正确的？", "options": ["A 权利能力与行为能力是分离的", "B 婴儿有权利能力但行为能力受限", "C 精神病人的行为能力可能受限", "D 权利能力等同于行为能力，没有区别"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】权利能力与行为能力的分离是法律保护与法律自治平衡的结果。【逐步演示】婴儿、精神病人都有权利能力，但行为能力受限，需由监护人代理。【易错提醒】D 否认二者区分，与本节核心观点直接冲突。"}, {"order": 6, "qtype": "single", "stem": "Siems 在比较法研究中提到『揭开公司面纱』（piercing the corporate veil）制度。这一制度的含义是：", "options": ["A 公司永远不能独立承担责任", "B 股东在任何情况下都对公司债务负责", "C 当公司人格被滥用时，法院可否认其独立地位并追究股东责任", "D 公司不得起诉或被起诉"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】揭开公司面纱指当股东滥用公司独立人格（如转移资产、逃避债务）时，法院否认其独立地位。【逐步演示】正常情况下股东以出资额为限承担责任，面纱制度是例外。【易错提醒】不要把它理解为对公司独立人格的全面否定，它只是极端情形下的矫正机制。"}, {"order": 7, "qtype": "judge", "stem": "Wacks 在讨论动物权利时指出，动物能否成为拥有权利的主体是一个尚无定论的问题。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】动物能否成为权利主体至今未有定论，Wacks 把它作为开放争论呈现。【逐步演示】支持者诉诸感受利益的能力，反对者如 RG Frey 视权利为『多余的累赘』。【易错提醒】凡遇『已有定论』这类表述，尤其是涉及争议性话题时，都应高度警惕。"}, {"order": 8, "qtype": "essay", "stem": "试论权利能力与行为能力的区分，并说明这一区分为何体现了法律保护与法律自治之间的平衡。", "options": [], "answer": "", "accepted": [], "keywords": [["权利能力是主体资格", "享有权利承担义务"], ["行为能力是独立行为资格", "以自己行为取得权利"], ["二者分离", "婴儿有权利能力无行为能力"], ["保护与自治的平衡", "保护利益同时防止判断不足受损"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先定义两个概念，再说明其分离的正当性。【逐步演示】第一步界定权利能力与行为能力；第二步用婴儿例子说明分离；第三步指出分离既保护了利益又限制了牟险行为；第四步总结平衡逻辑。【易错提醒】不要把两个能力混为一谈，也不要只讲定义不讲功能。"}, {"order": 9, "qtype": "single", "stem": "大陆法系（civil law）与英美法系（common law）在界定法律主体资格上的典型差异是：", "options": ["A 大陆法系完全依赖判例，英美法系完全依赖法典", "B 大陆法系倾向法典化明文规定，英美法系更多通过判例逐步界定", "C 两大法系的做法完全相同", "D 英美法系没有法律主体概念"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】大陆法系倾向以法典抽象界定主体资格（如德国 BGB），英美法系更多通过判例逐步界定。【逐步演示】但 Wacks 提醒不能把区别绝对化，现代英国有成文人权法，德国法也依赖判例。【易错提醒】不要把两大法系的区别写成『一个只有法典、一个只有判例』的漫画式对立。"}, {"order": 10, "qtype": "judge", "stem": "Siems 认为，比较法研究者可以放心地假定各国对『法律主体』的理解完全一致。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确反对这种假定，主张语境化方法，需把概念放回各自法律文化中考察。【逐步演示】他举中国、日本为例，说明即便有法典和类似法学教育，概念内涵也受语境影响。【易错提醒】比较法的核心警告之一就是不要望文生义、把概念从语境中抽离。"}, {"order": 11, "qtype": "blank", "stem": "古罗马法用『______』（status）来界定谁能成为权利主体，奴隶因此被排除在主体之外。", "options": [], "answer": "", "accepted": ["身份", "status", "人格", "身份等级"], "keywords": [], "explanation": "【答案】身份（status）。【解题思路】罗马法以身份界定法律人格，奴隶、外邦人、家子受不同程度限制。【逐步演示】Wacks 指出，『身份』一词长期承载这种主体资格的区分。【易错提醒】这里填的是『身份』而非『契约』，罗马法的身份等级是Subject资格的基础。"}, {"order": 12, "qtype": "essay", "stem": "结合废奴运动、妇女解放运动与动物权利争论，分析『法律主体资格的边界』为何是一个需要被论证的问题。", "options": [], "answer": "", "accepted": [], "keywords": [["主体资格历史上被排他性分配", "奴隶 妇女曾被排除"], ["资格扩张靠社会运动争取", "民权运动"], ["判断标准争议：理性还是感受利益", "自主意志 感知能力"], ["边界需论证而非自明", "法律判断"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】以历史扩张为线索，分析标准之争。【逐步演示】第一步指出主体资格历史上具有排他性；第二步说明社会运动推动扩张；第三步对比理性标准与利益感受标准；第四步总结边界的论证性。【易错提醒】不要把主体资格写成亘古不变的自然事实，它始终是被建构和争夺的法律判断。"}]}, "S1M3K4": {"lesson": "S1M3K4", "questions": [{"order": 1, "qtype": "single", "stem": "Salomon v A Salomon & Co Ltd（1897）这一上议院判例，在普通法上的核心意义是：", "options": ["A 否认公司的独立人格", "B 确认公司自注册起即为独立法律人格，股东仅以出资为限负责", "C 确立股东对公司一切债务承担无限责任", "D 宣布一人公司非法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Salomon 案确认公司一经合法注册即为独立的法律人，其债务与股东个人财产分离。【逐步演示】该案奠定了公司独立人格与有限责任的基石，股东仅以出资额为限负责。【易错提醒】不要把 Salomon 案与『揭开公司面纱』混淆，后者是在人格被滥用时的例外否认。"}, {"order": 2, "qtype": "judge", "stem": "按照法律人格的理论，公司是自然生成的生物实体，其人格不依赖法律的承认。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法人人格是法律拟制（legal fiction）的产物，依赖法律的承认，而非生物事实。【逐步演示】拟制说认为法人无真实意志，人格来自法律授予；实在说虽强调社会实在性，也不否认人格需法律确认。【易错提醒】法律人格是规则构造的地位，这一点是本节最核心的命题。"}, {"order": 3, "qtype": "blank", "stem": "当股东滥用公司独立人格逃避债务、转移资产时，法院可否认公司的独立地位、追究股东个人责任，这一制度称为『______』。", "options": [], "answer": "", "accepted": ["揭开公司面纱", "公司人格否认", "刺破公司面纱", "piercing the corporate veil", "人格否认"], "keywords": [], "explanation": "【答案】揭开公司面纱（piercing the corporate veil）。【解题思路】Siems 提到这一制度，指人格被滥用时法院否认法人独立地位。【逐步演示】正常情况下股东以出资额为限负责，面纱制度是例外矫正。【易错提醒】它是人格的『例外否认』，不是对公司独立人格的全面否定。"}, {"order": 4, "qtype": "single", "stem": "关于法人本质，认为法人并无真实意志、其人格是法律为便利而拟制、权利能力来自国家授予的理论是：", "options": ["A 实在说（有机体说）", "B 拟制说", "C 自然权利说", "D 社会契约说"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】拟制说认为法人人格是法律为便利而虚构，权利来自国家授予。【逐步演示】实在说（有机体说）则认为法人是有自身意志与目的的实在社会团体，德国团体人格理论更接近后者。【易错提醒】两种理论的方向相反，切勿张冠李戴。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，下列哪些表述符合哈特（Hart）关于法律人格的观点？", "options": ["A 法律人格是规则配置的结果，而非生物事实", "B 同一自然人可同时占据不同的法律人格位置", "C 人格只能通过自然出生取得", "D 授权性规则使人能设立公司、订立遗嘱，塑造自己的法律世界"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】哈特把人格放在规则理论中，强调人格是规则配置的结果，可拆分，并通过授权性规则塑造。【逐步演示】他用『一人二角』说明同一自然人可有公职与私人两种身份。【易错提醒】C 只适用于自然人人格，法人人格来自法律拟制，不是自然出生。"}, {"order": 6, "qtype": "single", "stem": "美国 Citizens United v Federal Election Commission（2010）一案，在本书语境中主要被用来说明哪一争论？", "options": ["A 公司是否应享有言论自由等宪法保护、能否参与政治献金", "B 公司是否必须破产清算", "C 自然人人格是否平等", "D 罗马法奴隶制度的合理性"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】该案涉及公司政治献金与言论自由，被用来说明法人是否应享有基本权利的争论。【逐步演示】支持者认为法人活动也受基本权利保护，反对者担心资本借人权之名膨胀。【易错提醒】此案是争论的标志性例子，不要把焦点错放到破产或清算程序上。"}, {"order": 7, "qtype": "judge", "stem": "Wacks 指出，罗马法中奴隶与自由公民享有平等完整的法律人格。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】罗马法以身份（status）切割人格，奴隶是权利客体而非主体，家子人格也受限。【逐步演示】Wacks 强调『身份』长期承载主体资格的区分。【易错提醒】把现代平等人格观念投射到罗马法，是典型的时代错置。"}, {"order": 8, "qtype": "essay", "stem": "试述法律人格为何是一种法律技术而非自然事实，并结合 Salomon 案与揭开公司面纱制度加以说明。", "options": [], "answer": "", "accepted": [], "keywords": [["人格是规则构造的地位", "法律技术非自然事实"], ["Salomon 案确立独立人格", "1897 上议院"], ["面纱制度在滥用时否认人格", "例外矫正"], ["承认与否认背后是公平与效率判断", "价值判断"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先论证人格的技术性，再用两个制度作正反例证。【逐步演示】第一步说明人格来自规则赋予；第二步用 Salomon 案说明人格的承认；第三步用面纱制度说明人格的否认；第四步总结其背后的价值判断。【易错提醒】不要只讲一个方面，要看到承认与否认构成完整图景。"}, {"order": 9, "qtype": "single", "stem": "自然人人格与法人人格的关键区别在于：", "options": ["A 自然人人格基于出生而普遍平等，法人人格基于法律承认且受目的范围限制", "B 法人人格基于出生，自然人人格基于拟制", "C 二者完全相同，无任何区别", "D 法人不能起诉应诉，自然人可以"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】自然人人格基于出生、普遍平等、不可让与；法人人格基于法律承认，范围受设立目的与法律限定。【逐步演示】二者都能作为权利义务承载者、起诉应诉，这是共同点。【易错提醒】D 错误，法人完全可以起诉应诉，这是独立人格的重要体现。"}, {"order": 10, "qtype": "judge", "stem": "Siems 认为，比较法研究者应当假定各国对法律人格的理解完全一致，才能进行有效的比较。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 主张语境化方法，反对把概念从语境中抽离并假定各国理解一致。【逐步演示】他以中国、日本法院同样讨论揭开公司面纱为例，说明技术细节深嵌于具体制度之中。【易错提醒】比较法的基本警告就是不要望文生义、不要预设概念普适同质。"}, {"order": 11, "qtype": "blank", "stem": "法人人格是法律______（legal fiction）的产物，其主体地位来自法律的承认。", "options": [], "answer": "", "accepted": ["拟制", "虚构", "fiction", "法律拟制"], "keywords": [], "explanation": "【答案】拟制（legal fiction）。【解题思路】法人人格源于法律拟制，与自然人的生物事实不同。【逐步演示】拟制说由此认为法人无真实意志，权利能力来自授予。【易错提醒】不要填『发现』或『自然生成』，这些词与 legal fiction 的方向相反。"}, {"order": 12, "qtype": "essay", "stem": "围绕『公司是否应享有基本权利』这一争论，分别陈述支持与反对的论据，并说明它如何暴露了法律人格标准的局限。", "options": [], "answer": "", "accepted": [], "keywords": [["支持：法人有独立意志与活动", "基本权利需保护组织活动"], ["反对：无人格尊严与感受能力", "稀释人权 资本膨胀"], ["公司有理性决策无感受能力", "暴露标准局限"], ["人格延伸终究是价值判断", "无定论"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分别陈述双方，再点出标准困境。【逐步演示】第一步列出支持方（保护组织活动、权利可能落空）；第二步列出反对方（无人格尊严、资本借名膨胀）；第三步指出公司有理性却无感受，暴露『理性自主 vs 感受利益』标准的局限；第四步说明这是价值判断。【易错提醒】论述要兼顾双方，不要只站一边；务必回到『人格标准局限』这一题眼。"}]}, "S1M3K5": {"lesson": "S1M3K5", "questions": [{"order": 1, "qtype": "single", "stem": "哈特（Hart）在讨论遗嘱、合同等形式要件时指出，缺少见证人的遗嘱所产生的后果是：", "options": ["A 立遗嘱人构成犯罪", "B 遗嘱无效（nullity），但并非违反义务或犯罪", "C 立遗嘱人须缴纳罚款", "D 遗嘱仍然有效但可撤销"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特指出，授权性规则被违反时后果是无效（nullity），而非惩罚——遗嘱少了见证人即无效，但立遗嘱人并未犯罪。【逐步演示】哈特专门反驳把无效当作一种制裁的说法，因为无效是规则自身的组成部分。【易错提醒】不要把『无效』与『犯罪』『违反义务』混为一谈，这是哈特区分规则类型的关键。"}, {"order": 2, "qtype": "judge", "stem": "哈特认为，制裁是法律的核心，一切法律规则都可以毫无扭曲地还原为『命令＋制裁』。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特批判了把一切法律还原为命令加制裁的观点，强调授权性规则与无效并不等同于制裁。【逐步演示】凯尔森式的还原扭曲了法律的社会功能；制裁只是应对规则失败的辅助手段。【易错提醒】这是哈特法律理论的核心命题，凡遇『一切规则都是命令』的表述都应警惕。"}, {"order": 3, "qtype": "blank", "stem": "以过错为承担责任前提的归责原则称为______责任；不以过错为前提、只要造成损害即承担的责任称为严格责任。", "options": [], "answer": "", "accepted": ["过失", "过错", "fault", "过失责任", "过错责任"], "keywords": [], "explanation": "【答案】过失（Fault）。【解题思路】过失责任以过错为前提，严格责任不以过错为前提。【逐步演示】二者分别以道德可非难性与风险控制/损失分散为正当性基础。【易错提醒】不要把『过失责任』理解为『轻微的』责任，它指的是以过错为要件的归责原则。"}, {"order": 4, "qtype": "single", "stem": "Donoghue v Stevenson（1932）中，阿特金勋爵（Lord Atkin）提出的著名原则是：", "options": ["A 合同相对性原则", "B 邻人原则（neighbour principle）：应合理注意避免伤害可预见的邻人", "C 严格责任原则", "D 过失相抵原则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】阿特金勋爵提出邻人原则，要求采取合理注意避免伤害可合理预见的『邻人』。【逐步演示】该案确立了制造商对消费者的注意义务，是产品责任与一般注意义务的里程碑。【易错提醒】此案并非确立严格责任，而是以过失为基础的注意义务，注意区分。"}, {"order": 5, "qtype": "single", "stem": "根据哈特的观点，刑法规则与其制裁的关系最恰当的描述是：", "options": ["A 制裁就是刑法规则的全部内容", "B 刑法设定义务，制裁是应对义务被违反的辅助手段", "C 刑法与制裁毫无关联", "D 制裁只是对法官的命令"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为刑法通过规则设定义务、指导公民行为，制裁只是规则失败时的辅助应对。【逐步演示】他反驳凯尔森把法律还原为『对官员适用制裁的命令』的观点，认为这扭曲了法律的社会功能。【易错提醒】不要把制裁等同于刑法规则本身，这是哈特与凯尔森分歧的要点。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，下列哪些属于归责（imputation）过程中通常要考察的环节？", "options": ["A 义务是否存在", "B 是否违反义务并造成损害", "C 过错标准（过失或严格责任）", "D 是否存在抗辩事由从而减免责任"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】归责通常经过义务存在、违反与损害、过错标准、限制与免除四个环节。【逐步演示】这四个环节层层递进，构成一个完整的责任判断结构。【易错提醒】不要只关注『有没有造成损害』，归责是一个包含义务、因果、标准、抗辩的综合判断。"}, {"order": 7, "qtype": "judge", "stem": "严格责任以行为人的过错为承担责任的必要前提。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】严格责任恰恰不以过错为前提，只要造成法定损害即承担责任。【逐步演示】其正当性在于风险控制与损失分散——谁从危险活动中获益，谁承担风险。【易错提醒】『严格』指的是无需证明过错，而非『责任更严厉』，这是常见的望文生义。"}, {"order": 8, "qtype": "essay", "stem": "试比较过失责任与严格责任的归责逻辑，并分析严格责任是否与『责任以自由选择为前提』相冲突。", "options": [], "answer": "", "accepted": [], "keywords": [["过失责任以过错与可非难性为基础", "fault moral blameworthiness"], ["严格责任以风险控制损失分散为基础", "risk control loss spreading"], ["严格责任不以过错为前提", "无需证明过错"], ["冲突与调和：以获益者担风险论证", "不与自由根本冲突"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先比较两种归责逻辑，再正面回应冲突问题。【逐步演示】第一步说明过失责任的道德基础；第二步说明严格责任的风险基础；第三步指出表面冲突；第四步用获益者担风险的论证调和。【易错提醒】不要只描述区别而不回应『冲突』这一题眼。"}, {"order": 9, "qtype": "single", "stem": "哈特用『一人二角』的例子（立法者以公职身份立法、以私人身份守法）主要想说明：", "options": ["A 法律人格可以被规则拆分和配置", "B 立法者不受法律约束", "C 自然人不能有两个身份", "D 义务不适用于官员"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】哈特用此例说明法律身份是规则配置的结果，可被拆分，而非生物事实。【逐步演示】这支撑了他关于法律人格是制度构造的观点。【易错提醒】此例绝不是说立法者可以凌驾于法律之上，恰恰相反，它说明同一主体可同时受不同规则约束。"}, {"order": 10, "qtype": "judge", "stem": "Siems 指出，德国、英国、法国、美国在损害赔偿范围与责任认定上路径一致，没有明显差异。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确指出各国侵权法在赔偿范围、精神损害赔偿、责任认定上差异明显。【逐步演示】例如德国法院对精神损害赔偿较保守并限制数额，英美法系更依赖判例发展。【易错提醒】比较法研究强调差异与语境，凡遇『各国完全一致』的表述都要警惕。"}, {"order": 11, "qtype": "blank", "stem": "在侵权法中，行为与损害之间『引起与被引起』的关系称为______关系，它是归责的重要环节。", "options": [], "answer": "", "accepted": ["因果", "因果关系", "causation", "因果关系（causation）"], "keywords": [], "explanation": "【答案】因果（Causation）。【解题思路】因果关系指行为与损害之间的引起与被引起关系。【逐步演示】Siems 指出因果关系认定标准的差异是各国侵权法分歧的重要来源。【易错提醒】不要填『逻辑』或『时间先后』，法律上的因果关系有其特定的归责含义。"}, {"order": 12, "qtype": "essay", "stem": "结合 Donoghue v Stevenson 案，说明法律责任的构成环节，并分析法官在该案中是通过何种方法发展出注意义务的。", "options": [], "answer": "", "accepted": [], "keywords": [["存在注意义务", "邻人原则"], ["义务违反并造成损害", "饮料含蜗牛致病"], ["因果关系成立", "饮用致病"]], "explanation": "【答案要点】见 keywords 三组要点。【解题思路】先按环节分析构成，再说明司法方法。【逐步演示】第一步说明注意义务（邻人原则）；第二步说明违反与损害；第三步说明因果关系；第四步说明哈特所说的『建构性解释』——法官揭示了分散规则背后的共同原则。【易错提醒】论述要包含『法官发展法律的方法』这一问，不要只做事实复述。"}]}, "S1M3K6": {"lesson": "S1M3K6", "questions": [{"order": 1, "qtype": "single", "stem": "哈特（Hart）理论中，用以识别哪些规则属于有效法律的根本次级规则是：", "options": ["A 改变规则（Rule of Change）", "B 裁判规则（Rule of Adjudication）", "C 承认规则（Rule of Recognition）", "D 基础规范（Grundnorm）"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】哈特用承认规则来识别哪些规则属于有效法律，它是根本性的次级规则。【逐步演示】改变规则用以引入或改变初级规则，裁判规则用以确定谁有权裁判；承认规则提供有效性标准。【易错提醒】基础规范是凯尔森的概念，不是哈特的，切勿混淆两人理论。"}, {"order": 2, "qtype": "blank", "stem": "凯尔森（Kelsen）理论中，法律体系所有规范效力的终极预设称为『______』（Grundnorm）。", "options": [], "answer": "", "accepted": ["基础规范", "基本规范", "Grundnorm", "basic norm", "基础规范（Grundnorm）"], "keywords": [], "explanation": "【答案】基础规范（Grundnorm）。【解题思路】凯尔森用基础规范解释效力链条的终点——一个被预设的、不再需要更高授权的终极规范。【逐步演示】个别规范的效力层层上溯，最终归于基础规范。【易错提醒】这是凯尔森的术语，不要填哈特的『承认规则』。"}, {"order": 3, "qtype": "judge", "stem": "哈特设想，英国的承认规则大致是『女王议会制定的即为法律』。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特设想英国承认规则大致为『Whatever the Queen in Parliament enacts is law』。【逐步演示】这体现了议会主权传统：议会制定法具有最高效力，法院无权审查。【易错提醒】这是哈特的经典表述，注意与美国以宪法为最高、辅以司法审查的模式相区分。"}, {"order": 4, "qtype": "single", "stem": "法律实证主义的『分离命题』（Separation Thesis）主张：", "options": ["A 法律与道德在事实上毫无关联", "B 法律是否有效与是否道德可以分开判断", "C 法律必须符合道德才有效", "D 恶法不是法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】分离命题主张『是不是法律』与『是不是道德上正当』应分开判断。【逐步演示】哈特承认法律与道德在事实层面常相互渗透，但坚持概念上的区分。【易错提醒】分离命题不等于『法律不需要道德』，这是常见的漫画化误读。"}, {"order": 5, "qtype": "single", "stem": "哈特—富勒（Hart-Fuller）论战围绕的核心问题是：", "options": ["A 法律与道德是否必须分离", "B 法律效力是否只来自主权者命令", "C 国际法是否算法律", "D 公司是否有法律人格"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】论战围绕『法律与道德是否必须分离』展开，背景是纳粹德国的恶法。【逐步演示】富勒主张法律的内在道德与法律概念密不可分；哈特主张承认恶法为法不妨碍谴责它。【易错提醒】Wacks 把这场论战列为理解法理学的关键入口，注意双方论据。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，下列关于哈特承认规则的表述，哪些是正确的？", "options": ["A 它是一种次级规则，用以识别有效法律", "B 它的存在取决于法院、官员等的接受实践", "C 它是一种道德判断，取决于规则是否正义", "D 其内容在不同法律体系中可能不同"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】承认规则是次级规则，根植于社会实践，内容因体系而异。【逐步演示】Green 指出它是一种惯例性社会规则，既非道德判断，也非逻辑预设。【易错提醒】C 与哈特的立场直接冲突——承认规则是社会事实，不是道德评价。"}, {"order": 7, "qtype": "judge", "stem": "按照哈特的观点，『恶法非法』（lex iniusta non est lex）这一命题是法律实证主义的核心主张。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】『恶法非法』是自然法理论的主张，与实证主义的立场相反。【逐步演示】哈特倾向于承认极端邪恶的规则仍是法律，但应予道德谴责；自然法则主张严重不义的规则不是法律。【易错提醒】把『恶法非法』归给实证主义是最常见的学派混淆之一。"}, {"order": 8, "qtype": "essay", "stem": "试述哈特的承认规则理论，并说明它如何回应『恶法是否是法律』这一难题。", "options": [], "answer": "", "accepted": [], "keywords": [["承认规则是识别有效法律的次级规则", "rule of recognition"], ["根植于社会实践而非道德", "社会事实"], ["承认恶法为法同时谴责", "效力与正当性区分"], ["区分使批判更精准", "正因其有效力更应抵抗"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先阐明承认规则，再用它分析恶法问题。【逐步演示】第一步说明承认规则的功能与性质；第二步说明效力由社会来源标准决定；第三步说明哈特承认恶法的效力；第四步指出这种区分让道德批判更清醒。【易错提醒】不要把哈特说成『赞成恶法』，他恰恰是为了更有力地批判恶法。"}, {"order": 9, "qtype": "single", "stem": "美国联邦最高法院有权审查国会立法是否违宪，违反宪法的法律可被宣告无效。这一制度安排说明：", "options": ["A 美国的承认规则以宪法为最高效力来源", "B 美国没有承认规则", "C 法院可以随意创造法律", "D 法律效力完全取决于道德"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】这一安排说明美国法律体系以宪法为最高效力来源，并通过司法审查维护。【逐步演示】Green 转述德沃金：美国法官把宪法当作最高效力的法律渊源。【易错提醒】不要误以为这说明法律效力取决于道德，它是制度安排的结果。"}, {"order": 10, "qtype": "judge", "stem": "法律效力（validity）等同于法律的实效（effectiveness）——被广泛遵守的法律必然在法律上有效。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】效力与实效是两个不同概念：规则可能有效却少人遵守，也可能被广泛遵守却因程序瑕疵而无效。【逐步演示】哈特强调承认规则的存在是社会实践事实，不等同于规则被遵守的程度。【易错提醒】不要把『事实上被遵守』当成『法律上有效』，二者不能画等号。"}, {"order": 11, "qtype": "blank", "stem": "德沃金（Dworkin）对哈特的挑战之一是：法律不仅包含规则，还包含______，其效力并非来自社会来源标准，而是来自道德分量。", "options": [], "answer": "", "accepted": ["原则", "法律原则", "principles", "原则（principles）"], "keywords": [], "explanation": "【答案】原则（Principles）。【解题思路】德沃金主张法律包含原则，原则的效力来自道德分量而非社会来源。【逐步演示】哈特在后记中回应：原则只要被官方承认即可纳入法律，承认规则可包含这种标准。【易错提醒】这是德沃金批判哈特『规则模式』的核心论点。"}, {"order": 12, "qtype": "essay", "stem": "结合英美两国效力来源的不同安排，分析法律效力为何必须放进具体制度语境才能理解。", "options": [], "answer": "", "accepted": [], "keywords": [["英国以议会制定法为最高", "议会主权"], ["美国以宪法为最高并辅司法审查", "judicial review"], ["效力由各体系的承认规则决定", "社会标准"], ["不能把一国模式普遍化", "制度语境"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先描述两种安排，再上升到理论。【逐步演示】第一步说明英国的议会主权模式；第二步说明美国的宪法至上与司法审查；第三步说明效力由各自的承认规则决定；第四步总结不能把美国模式当成唯一模式。【易错提醒】务必回应『为何必须放进具体语境』这一题眼，不要只做制度描述。"}]}, "S1M3K7": {"lesson": "S1M3K7", "questions": [{"order": 1, "qtype": "single", "stem": "大陆法系通常把法律事实分为事件与行为。下列属于『事件』的是：", "options": ["A 订立合同", "B 实施侵权行为", "C 人的出生与死亡", "D 提起诉讼"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】事件是不以当事人意志为转移的法律事实，如出生、死亡、自然灾害、时间经过。【逐步演示】订立合同、实施侵权、提起诉讼都以当事人意志为转移，属于行为。【易错提醒】不要把『事件』理解为『突发事件』，它在这里特指与意志无关的法律事实。"}, {"order": 2, "qtype": "judge", "stem": "法律事实是对自然事实的简单复制，只要事实上发生过，就自动成为法律事实。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法律事实是被法律规则赋予意义、能引起法律后果的事实，是规则筛选与构造的产物，而非自然事实的简单复制。【逐步演示】今天下雨是自然事实，但是否构成『雨天路滑致事故』的法律事实，取决于规则与认定。【易错提醒】这是本节最核心的命题，切勿把法律事实等同于客观发生的事实。"}, {"order": 3, "qtype": "blank", "stem": "在诉讼中，主张某一事实存在的一方通常承担证明该事实的责任，这一制度称为______责任。", "options": [], "answer": "", "accepted": ["举证", "证明", "举证责任", "burden of proof", "举证责任（burden of proof）"], "keywords": [], "explanation": "【答案】举证（Burden of Proof）。【解题思路】举证责任指由哪一方承担证明事实存在的责任，一般原则是『谁主张、谁举证』。【逐步演示】证明达不到标准，主张就不能成立，因此举证责任的分配往往决定案件结果。【易错提醒】不要填『刑事』或『民事』，这里问的是证明责任的制度名称。"}, {"order": 4, "qtype": "single", "stem": "哈特（Hart）用哪一概念说明法律规则在边缘地带存在不确定性、事实是否符合规则常常可争辩？", "options": ["A 承认规则（Rule of Recognition）", "B 开放结构（Open Texture）", "C 基础规范（Grundnorm）", "D 分离命题（Separation Thesis）"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特用开放结构说明规则有确定核心，也有可争辩的边缘地带。【逐步演示】这种不确定性同样适用于事实认定——事实是否符合规则描述常常没有唯一答案。【易错提醒】承认规则是识别有效法律的规则，与开放结构不是同一概念。"}, {"order": 5, "qtype": "single", "stem": "霍姆斯（Oliver Wendell Holmes Jr.）『法律的生命不在逻辑，而在经验』这句话，最贴近哪一立场？", "options": ["A 法律形式主义", "B 法律现实主义", "C 自然法理论", "D 法律实证主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】这句话强调经验与现实对法律的决定作用，是美国法律现实主义的标志性表述。【逐步演示】现实主义者主张真正决定案件结果的是法官对事实与社会后果的判断。【易错提醒】注意拼写 Oliver Wendell Holmes Jr.，勿与其他学者混淆。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，下列关于法律事实认定的表述，哪些是正确的？", "options": ["A 法律事实由证据证明，经事实认定进入裁判", "B 举证责任的分配会影响案件结果", "C 事实认定与法律评价有时难以截然分开", "D 事实认定是一个纯粹客观、毫无判断的过程"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律事实经证据与认定进入裁判，举证责任影响结果，事实与法律评价常纠缠。【逐步演示】哈特的开放结构与现实主义都指出事实认定包含判断。【易错提醒】D 与本节核心观点直接冲突——事实认定并非纯粹客观的过程。"}, {"order": 7, "qtype": "judge", "stem": "大陆法系的职权主义与英美法系的当事人主义，代表事实认定的两种不同模式，且在现代已完全融合、毫无差别。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】两种模式确实不同，Siems 指出随着交流差异有所缩小，但制度基因仍在，并未完全融合。【逐步演示】职权主义由法官主导调查，当事人主义由双方举证对抗。【易错提醒】『完全融合』『毫无差别』是典型的绝对化误述。"}, {"order": 8, "qtype": "essay", "stem": "试论法律事实与自然事实的区别，并说明为什么举证责任的分配会影响案件结果。", "options": [], "answer": "", "accepted": [], "keywords": [["法律事实由规则筛选构造", "引起法律后果"], ["自然事实是客观发生", "未必有法律意义"], ["举证责任决定证明成败", "谁主张谁举证"], ["分配影响结果", "证明不足则主张不成立"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先区分两类事实，再分析举证责任的功能。【逐步演示】第一步说明法律事实是规则构造的产物；第二步说明自然事实未必有法律意义；第三步说明举证责任的运作；第四步指出分配决定成败。【易错提醒】不要把『事实认定』说成纯技术过程，要看到其中的价值与政策考量。"}, {"order": 9, "qtype": "single", "stem": "Donoghue v Stevenson（1932）中，啤酒瓶不透明、消费者无法事先查看这一事实，在法律推理中被用来支持：", "options": ["A 制造商与消费者关系紧密、消费者无从自我保护", "B 消费者自身有过错", "C 合同关系成立", "D 制造商无注意义务"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】啤酒瓶不透明的事实被构造为制造商与消费者关系紧密、消费者无从自我保护的理由，支持注意义务。【逐步演示】哈特把此案作为建构性解释的范例：事实认定与法律原则揭示相互交织。【易错提醒】此案恰恰确立了制造商的注意义务，D 与判决相反。"}, {"order": 10, "qtype": "blank", "stem": "在事实与法律问题的关系上，哈特指出『合理注意』『可预见性』这类标准本身带有______性，使事实认定与法律评价难以截然分开。", "options": [], "answer": "", "accepted": ["规范", "规范性", "normative", "规范（normative）"], "keywords": [], "explanation": "【答案】规范（Normative）。【解题思路】这类标准本身带有规范性，使事实认定与法律评价相互纠缠。【逐步演示】要说某行为构成违约或过失，既要确定事实，又要适用带有价值标准的规则。【易错提醒】不要填『客观』，这些标准恰恰不是纯客观的。"}, {"order": 11, "qtype": "judge", "stem": "法律现实主义完全否认法律规则的确定性，认为法官可以任意裁判。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 提醒不能把现实主义漫画化为『法官可任意裁判』；它强调边缘地带的判断，而非全盘否定确定性。【逐步演示】法律在大多数案件中提供相对确定的指引，现实主义针对的是规则不确定的边缘情形。【易错提醒】警惕把任何学派推向极端，这往往是理解法理学的大忌。"}, {"order": 12, "qtype": "essay", "stem": "结合法律形式主义与现实主义的争论，分析『以事实为根据』这一司法原则在边缘案件中面临的挑战。", "options": [], "answer": "", "accepted": [], "keywords": [["形式主义：事实客观规则确定", "逻辑推演"], ["现实主义：判断与选择不可避免", "开放结构经验"], ["边缘案件事实与规则均可争辩", "不确定性"], ["原则仍成立但需理解为受约束的判断", "非任意"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先呈现双方立场，再分析挑战，最后给出平衡理解。【逐步演示】第一步说明形式主义主张；第二步说明现实主义的反驳；第三步指出边缘案件中事实与规则的可争辩性；第四步说明原则应理解为『受约束的判断』而非机械决定。【易错提醒】不要简单站队，要呈现双方论据并给出自己的综合判断。"}]}, "S1M3K8": {"lesson": "S1M3K8", "questions": [{"order": 1, "qtype": "single", "stem": "法律关系的三个构成要素是：", "options": ["A 主体、客体、内容", "B 权利、义务、责任", "C 法院、法官、当事人", "D 法律、道德、习惯"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法律关系由主体、客体与内容三要素构成：主体是当事人，客体是权利义务指向的对象，内容是权利义务。【逐步演示】B 只是内容的一部分，D 是法律渊源，均非三要素。【易错提醒】不要与法律规则的构成或法律渊源相混淆。"}, {"order": 2, "qtype": "blank", "stem": "霍菲尔德（Hohfeld）图式中，主张权（claim right）的对应面是义务，自由权（liberty）的对应面是______。", "options": [], "answer": "", "accepted": ["无权利", "no-right", "无权利（no-right）", "无权利要求"], "keywords": [], "explanation": "【答案】无权利（no-right）。【解题思路】霍菲尔德图式中：主张权—义务、自由权—无权利、权力—责任、豁免—无能力。【逐步演示】自由权只表示主体可自由行动，不意味着他人负有义务。【易错提醒】不要填『义务』，那是主张权的对应面。"}, {"order": 3, "qtype": "judge", "stem": "霍菲尔德所说的『权力（power）』，其对应面是他人的『责任』（liability，即被改变法律地位的易受性）。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】权力的对应面是责任（liability），指他人易受权力影响、被改变法律地位的状态。【逐步演示】豁免的对应面则是无能力（disability）。【易错提醒】此处的『责任』是霍菲尔德技术意义上的易受性，不等于道德谴责或法律责任。"}, {"order": 4, "qtype": "single", "stem": "可对抗不特定所有人的权利（如物权）与仅可对抗特定人的权利（如债权），在大陆法系通常分别称为：", "options": ["A 对人权与对物权", "B 对物权与对人权", "C 公权与私权", "D 绝对权与相对权（含义与前者相反）"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】对物权（right in rem）可对抗所有人，对人权（right in personam）仅可对抗特定人。【逐步演示】物权属对物权，合同债权属对人权。【易错提醒】注意顺序：题干先说的是可对抗所有人的物权，故选『对物权与对人权』。"}, {"order": 5, "qtype": "single", "stem": "哈特（Hart）认为，把松散的『初级规则社会』变成真正法律体系的关键，是：", "options": ["A 主权者的命令与威胁", "B 初级规则与次级规则的结合", "C 道德共识的普遍接受", "D 成文法典的编纂"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特主张法律的核心是初级规则与次级规则的结合。【逐步演示】次级规则（承认、改变、裁判规则）克服了初级规则的确定性不足、静态性与无效力争议，使法律关系获得确定性与可裁判性。【易错提醒】A 是奥斯丁的命令理论，为哈特所批判。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，霍菲尔德的基本法律关系（jural relations）包括下列哪些？", "options": ["A 主张权与义务", "B 自由权与无权利", "C 权力与责任", "D 豁免与无能力"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】霍菲尔德的四组基本对应关系即：主张权—义务、自由权—无权利、权力—责任、豁免—无能力。【逐步演示】每组都是同一关系从两端看的对应面。【易错提醒】不要漏掉『豁免—无能力』这一组，它常被忽视。"}, {"order": 7, "qtype": "judge", "stem": "Wacks 指出，相关性命题在法律实践中毫无例外——每一项义务都必然对应某个人的权利。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出相关性命题遭遇反例：刑法义务、公共职责常不对应特定人的权利。【逐步演示】Johnson v Phillips 中警察的义务就没有对应的个人权利；麦考密克也质疑相关性。【易错提醒】『毫无例外』『必然』是法理学中需要高度警惕的绝对化表述。"}, {"order": 8, "qtype": "essay", "stem": "试述霍菲尔德的四组基本法律关系，并说明相关性命题面对公共职责时遇到的挑战。", "options": [], "answer": "", "accepted": [], "keywords": [["四组对应关系", "主张权义务自由权无权利权力责任豁免无能力"], ["相关性命题含义", "同一关系两端描述"], ["公共职责无对应个人权利", "Johnson v Phillips"], ["哈里斯辩护与麦考密克质疑", "诉讼对抗方便方式"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先列出四组关系，再用公共职责检验相关性。【逐步演示】第一步列出四组对应面；第二步说明相关性；第三步用 Johnson v Phillips 展示公共职责中对应权利的缺失；第四步呈现哈里斯的辩护与麦考密克的质疑。【易错提醒】不要只罗列概念，要回应『挑战』这一题眼。"}, {"order": 9, "qtype": "single", "stem": "哈里斯（J. W. Harris）为霍菲尔德相关性命题辩护的核心理由是：", "options": ["A 所有义务都必然对应权利", "B 每一项司法争议至少涉及两方，相关性是描述诉讼关系的方便方式", "C 法律概念可以脱离历史语境分析", "D 权利概念本身就是多余的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈里斯认为相关性是法律的『最低共同点』——诉讼总以对抗双方展开，故相关性是描述诉讼关系的方便方式。【逐步演示】他同时承认需要非霍菲尔德的分析来补充。【易错提醒】哈里斯的辩护是有限度的，并非主张所有义务都必然对应权利。"}, {"order": 10, "qtype": "judge", "stem": "法律关系可以由道德关系或社会情谊自然产生，无须经过法律规则的调整。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法律关系是法律规则调整社会关系的结果，其特殊性正在于由法律界定并可引发法律救济。【逐步演示】朋友情谊、路人礼貌虽是关系，却不由法律调整，不产生法律上的强制力。【易错提醒】不要把一般社会关系与法律关系混为一谈。"}, {"order": 11, "qtype": "blank", "stem": "哈特指出，法律体系的基础是______规则与次级规则的结合，前者直接规定人们的行为义务。", "options": [], "answer": "", "accepted": ["初级", "初级规则", "primary", "primary rules", "第一性"], "keywords": [], "explanation": "【答案】初级（Primary）。【解题思路】哈特主张法律是初级规则与次级规则的结合，初级规则直接规定义务，次级规则规定识别、改变与裁判。【逐步演示】这一结合是法律体系区别于松散规则社会的关键。【易错提醒】不要填『次级』，题干说『直接规定行为义务』，指的是初级规则。"}, {"order": 12, "qtype": "essay", "stem": "结合霍菲尔德的分析与哈特的制度理论，说明法律关系何以既具有清晰的形式结构，又在实践中保持开放。", "options": [], "answer": "", "accepted": [], "keywords": [["霍菲尔德提供形式语法", "四组对应基本关系"], ["哈特提供制度条件", "次级规则使关系确定可变可裁判"], ["开放结构使边缘可争辩", "哈特的open texture"], ["形式清晰与实践开放并存", "需语境与判断"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先分层说明两位学者的贡献，再解释『清晰』与『开放』的并存。【逐步演示】第一步说明霍菲尔德的形式分析；第二步说明哈特的制度框架；第三步用开放结构说明边缘的可争辩性；第四步总结形式清晰与实践开放的统一。【易错提醒】不要只写一方，要体现两个层次的互补关系。"}]}, "S1M4K1": {"lesson": "S1M4K1", "questions": [{"order": 1, "qtype": "single", "stem": "哈特认为，正义观念中包含一个恒定不变的成分，可以概括为下列哪一项？", "options": ["A 最大化社会幸福", "B 相同案件相同处理", "C 给予每个人按其功绩应得之物", "D 保护私有财产神圣不可侵犯"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特在《法律的概念》中指出，正义包含一个恒定的成分即『Treat like cases alike』，以及一个变动的判断案件是否相同的标准。【逐步演示】恒定成分保证适用的一致性，变动成分处理具体情境中的同异判断。【易错提醒】C 是亚里士多德式的应得表述，A 属功利主义，均非哈特指出的恒定成分。"}, {"order": 2, "qtype": "single", "stem": "亚里士多德在《尼各马可伦理学》第五卷中，把正义主要理解为哪一种德性？", "options": ["A 一种追求过度与不及之间中道的德性", "B 一种纯粹的程序规则", "C 一种与道德无关的制度技术", "D 一种只适用于法院的裁判方法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出，亚里士多德沿着柏拉图的思路，把包括正义在内的伦理德性理解为理性的、情感的与社会的技能，并把德性视为对中道的追求。【逐步演示】勇敢过度成鲁莽、不及成怯懦，正义同样是在极端之间保持恰当比例。【易错提醒】B、C、D 都把正义缩减为技术性规则，与亚里士多德的德性论不符。"}, {"order": 3, "qtype": "multi", "stem": "根据本节内容，下列哪些属于正义概念内部结构的组成部分？", "options": ["A 形式上的一致性要求", "B 判断案件同异的实质标准", "C 应得根据的选择", "D 法官个人好恶的任意发挥"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】正义具有应得结构、形式层面与实质层面。【逐步演示】形式要求一致适用；实质标准决定何时同、何时异；应得根据决定分配理由。【易错提醒】D 与正义的『一致性』要求直接冲突，任意偏私恰是正义所反对的。"}, {"order": 4, "qtype": "judge", "stem": "按照 Wacks 引述的莱昂斯（David Lyons）的观点，以统一、常规的方式处理案件是正义的充分条件。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】莱昂斯的原话是：以统一、常规的方式处理案件『可能是正义的必要条件，却不是充分条件』。【逐步演示】一致适用只是形式层面，若规则本身不公，一致适用仍会产生不义。【易错提醒】『必要条件』与『充分条件』的区别是本节高频考点，切勿混淆。"}, {"order": 5, "qtype": "blank", "stem": "亚里士多德把 justice 视为一种德性，并区分了分配正义与______正义，后者是法院在矫正犯罪与民事过错时适用的正义。", "options": [], "answer": "", "accepted": ["矫正", "矫正正义", "交换", " corrective", "commutative", "correction"], "keywords": [], "explanation": "【答案】矫正（Corrective / Commutative Justice）。【解题思路】Wacks 明确指出，亚里士多德区分了 corrective 或 commutative justice 与 distributive justice。【逐步演示】前者是法院的正义，要求人人被平等对待；后者是立法者关心的、按功绩分配的正义。【易错提醒】两个术语可互换使用，但不要填入『报应』或『程序』。"}, {"order": 6, "qtype": "single", "stem": "自然法理论与法律实证主义在『法律与正义关系』上的核心分歧是：", "options": ["A 法律是否应当由法院执行", "B 严重不正义的规则是否仍属法律", "C 法律是否应当公开颁布", "D 法官是否应当有自由裁量权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】自然法主张法律与道德有必然联系，严重不正义者非法律；实证主义主张分离命题，是不是法律取决于来源。【逐步演示】双方的分歧集中在『恶法非法』与『恶法亦法（效力意义上）』的对立。【易错提醒】A、C、D 属于法治技术要求，不是两派的根本分歧。"}, {"order": 7, "qtype": "single", "stem": "罗尔斯在《正义论》中提出的理论通常被概括为：", "options": ["A 功利主义的正义", "B 资格理论", "C 作为公平的正义", "D 最小国家理论"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】Wacks 指出，罗尔斯提出 『justice as fairness』（作为公平的正义）。【逐步演示】他以原初状态与无知之幕为思想装置，推导两条正义原则。【易错提醒】B、D 都是诺齐克的立场，A 是罗尔斯与诺齐克共同反对的对象。"}, {"order": 8, "qtype": "multi", "stem": "关于纽伦堡审判，下列哪些表述符合本节所述内容？", "options": ["A 由国际军事法庭于1945至1946年主持", "B 被告以『行为依当时德国法合法』作为抗辩", "C 法庭最终驳回了这一抗辩", "D 它削弱了自然法思想在战后的复兴"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 记载了纽伦堡审判的基本事实与被告抗辩。【逐步演示】法庭坚持严重违反国际法与人类基本道德的行为应担责，从而驳回抗辩。【易错提醒】D 与史实相反——Wacks 指出纽伦堡审判对自然法思想的复兴产生了重大影响。"}, {"order": 9, "qtype": "judge", "stem": "诺齐克的资格理论认为，判断分配是否正义的关键是看它是否符合某种预期的分配模式。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】诺齐克主张正义取决于持有物的历史来源是否正当（即获取与转让的正当性），而非是否符合某种模式。【逐步演示】他明确反对一切『patterned』的分配理论，并以此批评罗尔斯。【易错提醒】『模式化分配』正是诺齐克批判的靶子，切勿张冠李戴。"}, {"order": 10, "qtype": "blank", "stem": "哈特与富勒关于法律与道德的著名论战于1957年发起、1958年发表于《______法律评论》。", "options": [], "answer": "", "accepted": ["哈佛", "Harvard", "Harvard Law Review", "哈佛法律评论"], "keywords": [], "explanation": "【答案】哈佛（Harvard）。【解题思路】Wacks 记载哈特与富勒的论战文章发表于1958年《哈佛法律评论》。【逐步演示】哈特主张分离命题，富勒主张法律具有『内在道德』。【易错提醒】年份与期刊是常考细节，注意是1958年的《哈佛法律评论》。"}, {"order": 11, "qtype": "essay", "stem": "试论正义概念的形式层面与实质层面，并说明为何仅有形式一致性不足以保证正义。", "options": [], "answer": "", "accepted": [], "keywords": [["形式层面", "相同案件相同处理", "一致适用"], ["实质层面", "判断同异的标准", "应得根据"], ["形式只是必要条件", "莱昂斯", "非充分条件"], ["不义法律一致适用仍不义", "种族隔离", "实质标准不公"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先界定两个层面，再引用哈特与莱昂斯说明关系。【逐步演示】第一步说明一致性的价值与限度；第二步指出判断标准本身可能不公；第三步以歧视性法律为例说明一致适用仍可产生不义。【易错提醒】不要只写『形式重要、实质也重要』，必须落到『必要条件而非充分条件』这一具体判断。"}, {"order": 12, "qtype": "single", "stem": "Wacks 把『正义』描述为一个怎样的问题？", "options": ["A 已经被彻底解决的问题", "B 难以捉摸的理想（elusive ideal）", "C 纯粹的语言游戏", "D 只属于伦理学、与法学无关的问题"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 在《Understanding Jurisprudence》第9章开篇即称正义为 『elusive ideal』。【逐步演示】从柏拉图、亚里士多德到边沁、罗尔斯、诺齐克，定义始终未统一。【易错提醒】Wacks 并未否认正义研究的意义，只是强调其概念的开放性。"}, {"order": 13, "qtype": "essay", "stem": "结合纽伦堡审判，分析『法律与正义是否存在必然联系』这一争论的现实意义。", "options": [], "answer": "", "accepted": [], "keywords": [["自然法立场", "恶法非法", "必然联系"], ["实证主义立场", "分离命题", "承认恶法为法"], ["纽伦堡抗辩", "依当时国内法合法", "被驳回"], ["现实意义", "形式合法性非道德豁免", "面对极端不正义"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先呈现两派论据，再用审判事实检验。【逐步演示】第一步写被告抗辩的实证主义逻辑；第二步写法庭驳回的理由；第三步说明争论不只是概念游戏，而是关乎如何面对极端不正义。【易错提醒】不要简单站队，应呈现双方论据及其各自的制度后果。"}]}, "S1M4K2": {"lesson": "S1M4K2", "questions": [{"order": 1, "qtype": "single", "stem": "根据 Wacks 的判断，哈特的『相同案件相同处理』标准在性质上主要属于：", "options": ["A 实体正义标准", "B 基本上是程序性的标准", "C 结果导向的标准", "D 功利主义标准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确指出，哈特『基本上程序性的标准』已获广泛接受。【逐步演示】该标准要求一致适用，但不回答判断同异的标准是否公正。【易错提醒】勿因其涉及『正义』就误判为实体标准；它恰恰是形式／程序取向的。"}, {"order": 2, "qtype": "single", "stem": "自然正义（Natural Justice）的两项基本要求是：", "options": ["A 公开审判与迅速裁判", "B 任何人不得做自己案件的法官、听取另一方意见", "C 律师代理与陪审团审判", "D 无罪推定与排除合理怀疑"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】自然正义的核心是 nemo judex in causa sua（中立裁判）与 audi alteram partem（听取双方）。【逐步演示】前者排除偏私，后者保障参与。【易错提醒】C、D 是正当程序的具体制度，不等同于自然正义的两项最低原则。"}, {"order": 3, "qtype": "judge", "stem": "Wacks 认为，只要法官严格遵守程序与形式正义原则，就足以保证实体正义与道德正确。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确表示，仅遵守形式正义原则是『道德上正确的不充分门槛』。【逐步演示】严格执行不道德法律的法官，即便满足正当程序，也未能做到正义。【易错提醒】这是本节的核心命题，切勿把程序合规等同于结果正当。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于程序正义所关注的内容？", "options": ["A 裁判者保持中立", "B 当事人获得陈述与申辩机会", "C 决定过程公开、理由说明", "D 刑罚与罪责是否相称"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】程序正义关注决定如何作出，包括中立、参与、公开与说理。【逐步演示】D 涉及处罚的适当性，属于实体正义的范畴。【易错提醒】区分『过程是否公平』与『结果是否公正』是做对本题的关键。"}, {"order": 5, "qtype": "blank", "stem": "富勒在《法律的道德性》中提出，法律应当具备一套程序性的最低要求，他称之为法律的『______道德』。", "options": [], "answer": "", "accepted": ["内在", "内部", "internal", "内在道德", "internal morality"], "keywords": [], "explanation": "【答案】内在（Internal Morality）。【解题思路】Wacks 指出富勒主张法律具有『internal morality』，并采取程序性自然法立场。【逐步演示】其要求包括一般性、公开性、不溯及既往、明确性等。【易错提醒】不要填『外在』或『实质』道德，富勒关注的是使法律成为可能的程序条件。"}, {"order": 6, "qtype": "single", "stem": "吉迪恩诉温赖特案（Gideon v. Wainwright, 1963）的核心裁决是：", "options": ["A 贫困被告在重罪案件中有获得律师帮助的权利", "B 所有案件必须实行陪审团审判", "C 各州可以自行决定是否为被告指定律师", "D 律师权只适用于可能判死刑的案件"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】美国最高法院裁定第六修正案律师协助权属根本性权利，通过第十四修正案正当程序条款适用于各州。【逐步演示】法院推翻旧判例，吉迪恩重审后获无罪。【易错提醒】D 正是被本案推翻的旧规则，切勿混淆。"}, {"order": 7, "qtype": "single", "stem": "Wacks 引述莱昂斯（David Lyons）关于统一处理案件的观点，其准确含义是：", "options": ["A 它是正义的充分条件", "B 它是正义的必要条件但非充分条件", "C 它与正义无关", "D 它只适用于民事案件"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】莱昂斯认为统一、常规地处理案件可能是正义的必要条件，却不是充分条件。【逐步演示】若法律本身不公，一致适用只会放大不义。【易错提醒】必要／充分条件的区分是本节高频考点。"}, {"order": 8, "qtype": "multi", "stem": "关于实体正义与程序正义的关系，下列哪些表述符合本节内容？", "options": ["A 二者是评价法律的两套不同标准", "B 二者可能发生冲突", "C 程序保障完全无助于实体正义的实现", "D 吉迪恩案说明程序缺陷可能导致实体错误"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】程序与实体是两套标准，可能冲突，也可能相互促进。【逐步演示】吉迪恩案中缺乏律师帮助的审判既程序有缺陷，也导致错误定罪。【易错提醒】C 与本案结论直接矛盾，程序保障对减少错判有实际作用。"}, {"order": 9, "qtype": "judge", "stem": "德沃金所说的『政治完整性』（political integrity）意味着政府必须依一套原则上适用于所有人的原则来治理，反对任意强制。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，德沃金的合法性概念服务于政治完整性，其含义是政府须依普遍适用的原则治理。【逐步演示】任意的强制或惩罚违反政治平等这一核心维度。【易错提醒】注意这与单纯『依法条字面执行』的狭义合法性不同。"}, {"order": 10, "qtype": "blank", "stem": "在种族隔离制度下严格适用隔离法的法官，从______正义角度看无可指摘，但从实体正义角度看却在助长不义。", "options": [], "answer": "", "accepted": ["程序", "形式", "procedural", "formal", "程序性", "形式正义"], "keywords": [], "explanation": "【答案】程序（／形式）。【解题思路】该法官符合中立、一致适用等程序性要求。【逐步演示】Wacks 以这一情境说明程序标准无法担保实体正当。【易错提醒】题干与『实体正义』对举，应填程序或形式，而非『实质』。"}, {"order": 11, "qtype": "essay", "stem": "试论程序正义与实体正义的关系，并说明为什么仅在程序层面难以找到令人满意的正义概念。", "options": [], "answer": "", "accepted": [], "keywords": [["两套不同标准", "过程如何作出", "结果是什么"], ["可能冲突", "隔离法法官", "一致适用仍不义"], ["莱昂斯", "必要非充分条件", "形式正义门槛不足"], ["Wacks结论", "程序层面找不到满意正义", "严格执行不道德法律仍不正义"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先区分两套标准，再呈现冲突情境，最后给出 Wacks 的结论。【逐步演示】第一步界定程序与实体；第二步用隔离法法官说明冲突；第三步引用莱昂斯与 Wacks 说明程序标准的局限。【易错提醒】论述应包含『必要非充分条件』这一关键判断。"}, {"order": 12, "qtype": "single", "stem": "Wacks 在讨论法官道德时提到的『deferential 法官为恶法背书』与『以改善制度为由留任』的区分，旨在说明：", "options": ["A 司法德性足以确保道德正确", "B 仅凭中立、无偏私等司法德性不足以保证道德正确", "C 法官不应辞职抗议", "D 法律实证主义是错误的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，一位公平公正却认为隔离在道德上可辩护的法官，说明司法德性不足以保证实体道德。【逐步演示】这进一步支持『程序层面找不到满意正义』的判断。【易错提醒】Wacks 并未主张法官一律辞职，而是揭示德性概念的复杂性。"}, {"order": 13, "qtype": "essay", "stem": "结合吉迪恩案，分析程序正义是否只是实体正义的『工具』。", "options": [], "answer": "", "accepted": [], "keywords": [["吉迪恩案情", "拒绝指定律师", "自行辩护被定罪"], ["最高法院裁决", "第六修正案", "第十四修正案正当程序"], ["程序与实体关联", "程序缺陷导致实体错误", "重审无罪"], ["程序独立价值", "人的尊严与参与", "约束权力"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述案情与裁决，再讨论程序的工具价值与独立价值。【逐步演示】第一步说明缺乏律师如何导致错判；第二步指出程序保障减少实体错误；第三步补充程序还具有尊严、参与等独立价值。【易错提醒】不要走向两个极端：程序既非纯粹工具，也非与结果无关。"}]}, "S1M4K3": {"lesson": "S1M4K3", "questions": [{"order": 1, "qtype": "single", "stem": "亚里士多德把分配正义界定为按什么方式分配？", "options": ["A 所有人在一切方面一律平等", "B 按功绩或价值成比例地分配", "C 按法院判决逐案裁量", "D 按抽签随机分配"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，亚里士多德认为分配正义关心按每个人的应得或功绩给予份额。【逐步演示】这对应他所说的『几何的平等』，即按相应比例分配。【易错提醒】A 混淆了分配正义与矫正正义；后者才要求人人一律平等。"}, {"order": 2, "qtype": "single", "stem": "罗尔斯『差别原则』的核心内容是：", "options": ["A 所有社会不平等都应被消除", "B 不平等只有在有利于最不利者时才可接受", "C 应按每个人的功绩成比例分配", "D 只要持有来路正当即正义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】差别原则要求社会经济不平等的组织须有利于社会中境况最差成员的最大利益。【逐步演示】它并不要求消除一切不平等，而是为其设定证成条件。【易错提醒】D 是诺齐克的资格理论，A 是对差别原则的常见误读。"}, {"order": 3, "qtype": "blank", "stem": "罗尔斯设想，人们在『原初状态』中、在一层______之后选择正义原则，因而不知道自身阶级、天赋与善观念。", "options": [], "answer": "", "accepted": ["无知之幕", "无知之幕（veil of ignorance）", "veil of ignorance", "无知"], "keywords": [], "explanation": "【答案】无知之幕（Veil of Ignorance）。【解题思路】Wacks 生动描述了 POP 在无知之幕下商议正义原则的意象。【逐步演示】遮蔽信息确保无人能利用偶然优势讨价还价。【易错提醒】不要填『原初状态』，那是选择所处的整体处境，而非遮蔽信息的装置。"}, {"order": 4, "qtype": "multi", "stem": "根据本节内容，下列哪些属于罗尔斯对功利主义的批评？", "options": ["A 未认真对待人的分离性", "B 把社会当作可跨人加总幸福的超个人", "C 没有把正当置于善之前", "D 过分强调个人权利的不可侵犯"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 指出罗尔斯的敌意基于两点：不承认人的分离性，以及正当应先于善。【逐步演示】把社会当作可加总幸福的超个人正是第一点的展开。【易错提醒】D 恰恰与事实相反——高度重视个人权利是罗尔斯与诺齐克的共同点。"}, {"order": 5, "qtype": "single", "stem": "诺齐克用来批判模式化分配的著名思想实验是：", "options": ["A 洞穴寓言", "B 张伯伦论证（Wilt Chamberlain example）", "C 电车难题", "D 无知之幕"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，诺齐克以张伯伦论证说明自愿交易会从正义初始状态中自发产生不平等。【逐步演示】维持分配模式必持续干预自由交换。【易错提醒】D 属于罗尔斯，A 属于柏拉图，均与诺齐克无关。"}, {"order": 6, "qtype": "judge", "stem": "诺齐克认为，只要分配结果不符合某种平等模式，即使每一笔持有都来路正当，该分配也是不正义的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】诺齐克的资格理论主张：只要获取与转让的历史正当，分配就是正义的，无论呈现何种模式。【逐步演示】他明确反对以结果模式作为正义判据。【易错提醒】『来路正当即正义』是诺齐克的核心命题，切勿与罗尔斯的结果取向混淆。"}, {"order": 7, "qtype": "single", "stem": "罗尔斯与诺齐克在分配正义问题上虽然对立，但共同的问题是：", "options": ["A 都主张最弱意义国家", "B 都反对功利主义", "C 都支持刚性配额", "D 都否认个人权利"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确指出，诺齐克虽正面攻击罗尔斯，但两人『share hostility to utilitarianism』。【逐步演示】他们都高度重视个人权利的不可侵犯性。【易错提醒】A 仅为诺齐克立场，C、D 与两人的基本立场都不符。"}, {"order": 8, "qtype": "multi", "stem": "关于加州大学董事会诉巴基案（1978），下列哪些表述符合本节内容？", "options": ["A 涉及医学院为少数族裔保留名额", "B 最高法院裁定刚性种族配额违宪", "C 多数意见允许种族作为录取考量因素之一", "D 最高法院裁定一切种族考量均违宪"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】本案裁定刚性配额违宪，但允许种族作为多样性考量因素。【逐步演示】巴克最终获准入学。【易错提醒】D 与本案折中结论直接矛盾，切勿把『禁止刚性配额』等同于『禁止一切种族考量』。"}, {"order": 9, "qtype": "blank", "stem": "诺齐克主张一种职能仅限于防止暴力、盗窃、欺诈并保护契约的『______国家』，即所谓守夜人式国家。", "options": [], "answer": "", "accepted": ["最弱意义", "最小", "守夜人", "minimal", "night-watchman", "最弱意义的"], "keywords": [], "explanation": "【答案】最弱意义（minimal）。【解题思路】Wacks 指出诺齐克主张 minimal state／night-watchman state。【逐步演示】其职能被严格限定在保护性范围内。【易错提醒】不要填『福利国家』或『极权国家』，两者都与诺齐克立场相反。"}, {"order": 10, "qtype": "judge", "stem": "Wacks 记载，批评者（包括德沃金）认为罗尔斯的原初状态可能预先设定了它所要寻求的结论。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 在『对罗尔斯的批判』中明确指出，原初状态被批评为必然提供罗尔斯所假定的结果。【逐步演示】德沃金主张平等关怀与尊重的权利实为罗尔斯契约论的前提而非产物。【易错提醒】这一批评属于对罗尔斯的批判部分，不要误记为诺齐克对罗尔斯的唯一批评。"}, {"order": 11, "qtype": "essay", "stem": "试比较罗尔斯差别原则与诺齐克资格理论在正义判断对象、自由平等关系与国家角色上的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["判断对象", "罗尔斯重结果结构", "诺齐克重历史来源"], ["自由平等", "罗尔斯协调二者", "诺齐克认为不可调和"], ["国家角色", "罗尔斯需要制度调节", "诺齐克主张最弱意义国家"], ["共同点", "都反对功利主义", "都重视个人权利"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】按三个维度逐一对照，最后补充共同点。【逐步演示】先写判断对象差异，再写自由平等观，再写国家角色，最后指出共同反对功利主义。【易错提醒】不要只写对立而遗漏共同前提，Wacks 特别强调两人共享对功利主义的敌意。"}, {"order": 12, "qtype": "single", "stem": "在罗尔斯的理论中，自由与平等的关系被理解为：", "options": ["A 二者不可调和，必须牺牲其一", "B 通过差别原则等安排加以协调", "C 平等应完全让位于自由", "D 自由应完全让位于平等"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】罗尔斯以平等自由原则与差别原则的组合来协调自由和平等。【逐步演示】不平等只有在惠及最不利者时才被接受。【易错提醒】『不可调和』是诺齐克的著名主张，属于高频混淆项。"}, {"order": 13, "qtype": "essay", "stem": "结合巴基案，分析教育资源分配中『照顾不利者』与『尊重个体资格』之间的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["案件背景", "保留少数族裔名额", "巴基被拒"], ["照顾不利者", "罗尔斯式证成", "历史歧视矫正"], ["个体资格", "诺齐克式批评", "按成绩获得资格"], ["法院折中", "刚性配额违宪", "种族可作考量因素"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述案情，再分别用两种理论分析，最后评价法院折中。【逐步演示】第一步交代保留名额与诉讼；第二步用差别原则与资格理论对照；第三步说明折中方案的理由与不足。【易错提醒】不要简单判定某一派『正确』，应说明两种价值在制度中的持续张力。"}]}, "S1M4K4": {"lesson": "S1M4K4", "questions": [{"order": 1, "qtype": "single", "stem": "根据 Wacks 的归纳，亚里士多德所说的矫正正义（或交换正义）主要是哪一类主体的事务？", "options": ["A 立法者", "B 法院", "C 行政机关", "D 教会"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确指出，矫正或交换正义『是法院的正义』，适用于对犯罪或民事过错的救济。【逐步演示】与之相对，分配正义才主要是立法者关心的事务。【易错提醒】本题常与分配正义混淆，记住『法院对矫正、立法对分配』。"}, {"order": 2, "qtype": "single", "stem": "矫正正义所依据的平等形式是：", "options": ["A 几何的平等", "B 算术的平等", "C 按功绩比例平等", "D 机会平等"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】亚里士多德区分了算术的平等（矫正正义）与几何的平等（分配正义）。【逐步演示】算术平等不问身份，要求对所有当事人一律平等。【易错提醒】A、C 都属于分配正义的几何平等逻辑。"}, {"order": 3, "qtype": "judge", "stem": "矫正正义的目标是对侵害者施加超出损害范围的额外惩罚，以威慑他人。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】矫正正义着眼于消除不当得失、恢复原状，而非额外惩罚。【逐步演示】额外的罪责应报属于报应正义，威慑属于工具主义目标。【易错提醒】不要把矫正正义与报应／威慑混为一谈。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于矫正正义的核心结构或特征？", "options": ["A 预设初始平等状态", "B 以恢复被破坏的平等为目标", "C 以过错作为归责纽带", "D 按各人功绩成比例分配利益"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】矫正正义包含初始平等、不当得失、恢复原状与过错归责。【逐步演示】D 是分配正义的几何比例逻辑，不属于矫正正义。【易错提醒】区分『按比例的份额分配』与『对等的损害填补』是本题考查重点。"}, {"order": 5, "qtype": "blank", "stem": "矫正正义在亚里士多德传统中又称______正义，强调对等交换与返还。", "options": [], "answer": "", "accepted": ["交换", "commutative", "交换正义", "Commutative"], "keywords": [], "explanation": "【答案】交换（Commutative）。【解题思路】Wacks 指出 corrective 与 commutative justice 可互换使用。【逐步演示】二者都指法院对犯罪与民事过错的救济。【易错提醒】不要填『分配』或『报复』，那是另外的概念。"}, {"order": 6, "qtype": "single", "stem": "唐纳休诉史蒂文森案（Donoghue v. Stevenson, 1932）中，上议院确立的核心原则是：", "options": ["A 合同相对性原则", "B 邻人原则（neighbor principle）与注意义务", "C 严格责任原则", "D 无过错责任原则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】阿特金勋爵提出邻人原则，要求对可预见会受影响的人负注意义务。【逐步演示】本案突破了合同相对性的限制，确立制造商对消费者的注意义务。【易错提醒】A 正是本案试图突破的旧原则，切勿选反。"}, {"order": 7, "qtype": "single", "stem": "Wacks 提到，诺齐克把报应性惩罚描述为：", "options": ["A 一种纯粹的经济激励", "B 一种交流行为（an act of communicative behavior）", "C 一种社会风险的分散机制", "D 一种分配模式"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，诺齐克把报应性惩罚描述为『an act of communicative behavior』，并由汉普顿加以发展。【逐步演示】这一理论把惩罚理解为对错误行为的回应与沟通。【易错提醒】C 是工具主义／损失分散的观点，不是诺齐克的报应论。"}, {"order": 8, "qtype": "judge", "stem": "唐纳休案中，原告与制造商之间存在直接的合同关系，因此她依据合同相对性原则获得了赔偿。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本案中饮料是朋友代买的，原告与制造商之间并无直接合同关系。【逐步演示】法院正是突破了合同相对性，才以注意义务为依据判原告胜诉。【易错提醒】本案的事实细节是常考点：无合同关系恰恰是案件的难点所在。"}, {"order": 9, "qtype": "essay", "stem": "试比较矫正正义与分配正义在判断对象、平等形式与制度归属上的区别。", "options": [], "answer": "", "accepted": [], "keywords": [["判断对象", "矫正处理已发生错误", "分配处理利益份额"], ["平等形式", "算术平等", "几何比例平等"], ["制度归属", "法院的正义", "立法者的正义"], ["时间向度", "面向过去恢复原状", "面向未来的制度设计"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】按三个指定维度对照，并补充时间向度。【逐步演示】先写判断对象，再写平等形式，再写制度归属，最后说明一个向后看、一个向前看。【易错提醒】不要只写『两者不同』，须落到算术／几何、法院／立法这些具体区别。"}, {"order": 10, "qtype": "blank", "stem": "补偿正义着眼于使受害者______，而报应正义着眼于使犯罪者承受与其罪责相称的惩罚。", "options": [], "answer": "", "accepted": ["恢复原状", "恢复原状或得到赔偿", "恢复", "得到赔偿", "恢复原状（restitution）"], "keywords": [], "explanation": "【答案】恢复原状。【解题思路】补偿正义以损害填补为目标，使受害者回到侵害未发生时的状态。【逐步演示】这与报应正义关注罪责应报形成对照。【易错提醒】不要填『获得超额赔偿』，矫正正义以对等为原则。"}, {"order": 11, "qtype": "single", "stem": "关于侵权法的目的，矫正正义理论与经济分析理论的争论焦点可概括为：", "options": ["A 是否应当保护消费者", "B 侵权法应向后看纠正错误还是向前看配置成本", "C 是否应当承认合同自由", "D 是否应当废除陪审团"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】矫正正义向后看、关注错误纠正；工具主义向前看、关注事故成本最小化与风险分散。【逐步演示】过错责任与无过错责任的并存正体现这一张力。【易错提醒】A、C、D 都不是本节所述争论的焦点。"}, {"order": 12, "qtype": "multi", "stem": "关于唐纳休案，下列哪些表述符合本节内容？", "options": ["A 由英国上议院于1932年判决", "B 原告与制造商之间没有直接合同关系", "C 法院以邻人原则确立制造商的注意义务", "D 案件确立了矫正义务可由过错与可预见损害产生"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均符合本案事实与理论意义。【逐步演示】本案突破合同相对性，以注意义务作为矫正责任的根据。【易错提醒】注意法院是英国上议院（House of Lords），年份为1932年。"}, {"order": 13, "qtype": "essay", "stem": "结合唐纳休案，分析矫正正义的具体规则为何需要随社会关系变化而演化。", "options": [], "answer": "", "accepted": [], "keywords": [["旧规则局限", "合同相对性", "密封产品消费者无从检验"], ["邻人原则", "可预见性", "接近性"], ["矫正与分配交织", "由最能控制风险者担责", "政策判断"], ["演化必要", "覆盖新损害形态", "两大法系发展"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先说明旧规则为何失灵，再说明新原则如何回应，最后上升到矫正与分配的交织。【逐步演示】第一步指出合同相对性使受害者无法获救济；第二步说明邻人原则以可预见性确定矫正义务；第三步指出规则演化中始终交织矫正与分配考量。【易错提醒】不要只叙述案情，要落到『规则为何必须演化』这一分析问题上。"}]}, "S1M4K5": {"lesson": "S1M4K5", "questions": [{"order": 1, "qtype": "single", "stem": "平等原则最简洁的表达，与哈特正义理论中的哪一命题一致？", "options": ["A 最大化幸福", "B 相同案件相同处理", "C 按功绩成比例分配", "D 恢复原状"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特把『Treat like cases alike』视为正义的恒定成分，也是形式平等的核心。【逐步演示】A 属功利主义，C 属分配正义，D 属矫正正义。【易错提醒】本题检验对哈特基本命题的记忆，注意与正义概念一节联动。"}, {"order": 2, "qtype": "single", "stem": "形式平等与实质平等的核心分歧在于：", "options": ["A 是否允许任何差别对待", "B 形式中立是否足以实现真正公平", "C 法律是否应当成文", "D 法院是否应当独立"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】形式平等强调规则一致与无歧视，实质平等关注实际处境与结构性不利。【逐步演示】二者的分歧集中在形式中立能否达成真正公平。【易错提醒】形式平等并不禁止一切差别对待，只禁止任意的差别对待，故 A 错误。"}, {"order": 3, "qtype": "judge", "stem": "根据 Wacks 的记载，哈特认为种族歧视者通常公开承认被歧视者与自己完全平等。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，哈特认为种族歧视通常被辩称被歧视者『不是完全的人』。【逐步演示】这正说明平等原则被广泛接受，歧视必须伪装。【易错提醒】题干与哈特的原意相反，注意『不是完全的人』这一关键表述。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于德沃金『政治完整性』（political integrity）的含义？", "options": ["A 法律面前人人平等", "B 政府须依普遍适用于所有人的原则治理", "C 任意强制违反政治平等", "D 效率永远优先于平等"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 指出，德沃金的政治完整性意味着政府依普遍原则治理，任意强制违反政治平等。【逐步演示】D 与德沃金立场相反，他明确反对以效率牺牲平等。【易错提醒】德沃金把合法性理解为独立的道德价值，而非效率工具。"}, {"order": 5, "qtype": "blank", "stem": "美国宪法第______修正案的平等保护条款，是平等原则在宪法上的集中体现。", "options": [], "answer": "", "accepted": ["十四", "14", "第十四", "14th", "Fourteenth"], "keywords": [], "explanation": "【答案】十四（Fourteenth）。【解题思路】1868年通过的第十四修正案包含平等保护条款。【逐步演示】它成为反对种族隔离、性别歧视等斗争的宪法武器。【易错提醒】不要填『十三』或『十五』修正案，它们分别涉及废奴与投票权。"}, {"order": 6, "qtype": "single", "stem": "布朗诉教育委员会案（Brown v. Board of Education, 1954）的核心裁决是：", "options": ["A 维持『隔离但平等』原则", "B 宣告公立教育中的种族隔离本身违反平等保护", "C 要求各校统一经费", "D 只禁止私立学校的种族隔离"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】最高法院一致裁定公共教育中的种族隔离本身即违反平等保护条款。【逐步演示】法院推翻了『隔离但平等』在公立教育领域的适用。【易错提醒】A 正是被推翻的旧原则，属于典型逆向选择题。"}, {"order": 7, "qtype": "judge", "stem": "布朗案中，最高法院主要依据隔离学校之间物质设施的差异作出判决。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法院的核心理由是隔离本身造成的伤害与低人一等的标签，而非设施差异。【逐步演示】即使设施相当，隔离仍构成不平等。【易错提醒】这是从形式平等迈向实质平等的关键，切勿误解为『设施比较』。"}, {"order": 8, "qtype": "single", "stem": "德沃金对罗尔斯的批评中，他认为罗尔斯『深层理论』的核心是：", "options": ["A 最大最小化策略", "B 每个人获得平等关怀与尊重的权利", "C 资格理论", "D 功利计算"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，德沃金主张罗尔斯深层理论的核心是每个人获得平等关怀与尊重的权利，且这一权利是契约的前提而非产物。【逐步演示】A 属罗尔斯自身的推理策略，C 属诺齐克。【易错提醒】本题检验对罗尔斯批判部分的掌握。"}, {"order": 9, "qtype": "essay", "stem": "试论形式平等与实质平等的分歧，并说明布朗案如何体现从形式到实质的推进。", "options": [], "answer": "", "accepted": [], "keywords": [["形式平等", "规则一致", "无任意差别对待"], ["实质平等", "关注实际处境", "结构性不利"], ["分歧焦点", "形式中立是否足够", "效果与实际影响"], ["布朗案", "超越设施比较", "隔离本身伤害尊严"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先界定两种平等，再指出分歧焦点，最后用布朗案说明。【逐步演示】第一步写形式与实质的定义；第二步写分歧；第三步说明法院如何超越『隔离但平等』的形式比较。【易错提醒】不要只叙述案情，要落到两种平等观的对比上。"}, {"order": 10, "qtype": "blank", "stem": "平等原则真正的敌人是______，而非一切区别；有正当理由的差别对待可以是平等的。", "options": [], "answer": "", "accepted": ["任意性", "任意", "专断", "arbitrariness", "任意的差别对待"], "keywords": [], "explanation": "【答案】任意性（arbitrariness）。【解题思路】平等原则禁止基于不相关或任意理由的差别对待。【逐步演示】有正当理由的差别（如按成绩录取、累进税制）并不违反平等。【易错提醒】不要填『一切差别』，平等并不要求绝对的平均划一。"}, {"order": 11, "qtype": "single", "stem": "关于平等与正义的关系，下列哪一表述较符合本节内容？", "options": ["A 平等就是正义的全部", "B 平等是正义的重要部分但不是全部", "C 正义与平等毫无关系", "D 正义必然要求结果绝对平均"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】平等是正义的组成部分，但正义还包括应得、功绩与矫正等维度。【逐步演示】一项安排可能平等却不正义，也可能正义却不平等。【易错提醒】A、C、D 都把二者关系简单化或绝对化。"}, {"order": 12, "qtype": "judge", "stem": "德沃金认为，平等关怀与尊重的权利是社会契约的产物。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 记载，德沃金认为这种权利不是社会契约的产物，反而是契约的前提。【逐步演示】这使平等成为法律论证的底盘性价值。【易错提醒】题干颠倒了前提与产物的关系。"}]}, "S1M4K6": {"lesson": "S1M4K6", "questions": [{"order": 1, "qtype": "single", "stem": "法律公平与社会公平的主要区别在于：", "options": ["A 前者关注过程与形式，后者关注结果与结构", "B 前者只存在于大陆法系，后者只存在于英美法系", "C 前者是道德概念，后者是法律概念", "D 二者没有区别"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法律公平评价规则制定与适用是否公平，社会公平评价利益与机会分配的结果。【逐步演示】二者是内部德性与外部结果的关系。【易错提醒】B、C、D 都误置了二者的关系，法律公平并非某一法系独有。"}, {"order": 2, "qtype": "multi", "stem": "下列哪些属于法律公平的具体内容？", "options": ["A 规则的一般性与公开性", "B 适用的一致性与程序中立", "C 裁判者无偏私与当事人听证", "D 社会财富的平等分配"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律公平体现为一般性、公开性、一致适用、程序中立等要求。【逐步演示】富勒的内在道德列举的正是这类程序性要求。【易错提醒】D 属于社会公平的范畴，不是法律公平本身的内容。"}, {"order": 3, "qtype": "judge", "stem": "法律公平是社会公平的充分条件：只要法律制度在程序上公平，社会结果就必然公平。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节结论是：法律公平是社会公平的必要制度条件之一，但不是充分条件。【逐步演示】严格保护形式财产权可能固化巨大的社会不平等。【易错提醒】『充分条件』是本题陷阱，注意与『必要条件』区分。"}, {"order": 4, "qtype": "single", "stem": "Wacks 指出，哈特的『相同案件相同处理』标准主要体现的是：", "options": ["A 社会公平", "B 法律公平／形式正义", "C 分配正义", "D 报应正义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特的标准是程序性、形式性的，构成法律公平的核心。【逐步演示】它要求一致适用，但不回答结果是否公正。【易错提醒】注意本题与 S1M4K2 的联动，哈特标准被 Wacks 判定为『基本上是程序性的』。"}, {"order": 5, "qtype": "blank", "stem": "富勒提出的法律『______道德』，包括一般性、公开性、不溯及既往、明确性等程序性要求。", "options": [], "answer": "", "accepted": ["内在", "内部", "internal", "内在道德", "internal morality"], "keywords": [], "explanation": "【答案】内在（Internal Morality）。【解题思路】富勒在《法律的道德性》中提出法律的内在道德。【逐步演示】这些要求构成了法律公平的重要内容。【易错提醒】不要填『外在』或『实质』道德。"}, {"order": 6, "qtype": "single", "stem": "奥贝格费尔诉霍奇斯案（Obergefell v. Hodges, 2015）中，最高法院的裁决是：", "options": ["A 各州可自行决定是否承认同性婚姻", "B 各州必须为同性伴侣颁发结婚证书并承认其他州的合法同性婚姻", "C 只禁止私立机构歧视同性伴侣", "D 把婚姻问题完全交回各州民主程序"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】最高法院以5比4多数意见判决各州须颁发并承认同性婚姻。【逐步演示】法院结合正当程序与平等保护两条宪法线索。【易错提醒】D 接近反对意见的立场，不是多数意见的裁决。"}, {"order": 7, "qtype": "judge", "stem": "奥贝格费尔案中，反对意见主要从社会公平出发，批评多数意见未能充分保护同性伴侣的尊严。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】反对意见恰恰是从法律公平角度提出：婚姻制度变革应经民主程序，法院强行统一规则损害各州自主与可预测性。【逐步演示】多数意见才强调平等与尊严的实体价值。【易错提醒】本题检验能否把两种公平观与多数／反对意见正确对应。"}, {"order": 8, "qtype": "single", "stem": "德沃金把哪一价值注入对合法性的理解，从而把实体性的平等带入法律概念？", "options": ["A 效率最大化", "B 政治完整性", "C 最小国家", "D 最大最小化"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，德沃金的合法性服务于政治完整性，即政府须依普遍适用的原则治理。【逐步演示】任意强制违反政治平等这一核心维度。【易错提醒】C 属诺齐克，D 属罗尔斯的策略。"}, {"order": 9, "qtype": "essay", "stem": "试论法律公平与社会公平的关系，并说明为什么法律公平不是社会公平的充分条件。", "options": [], "answer": "", "accepted": [], "keywords": [["评价标准不同", "法律重过程形式", "社会重结果结构"], ["相互促进", "正当程序减少错判", "吉迪恩案"], ["相互冲突", "保护财产权固化不平等", "再分配削弱确定性"], ["必要非充分", "法律改变规则难改结构", "社会公平需多方条件"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先区分评价标准，再双向分析关系，最后落到必要非充分条件。【逐步演示】第一步写二者定义差异；第二步写促进与冲突两种情形；第三步说明法律作用的限度。【易错提醒】不要只写两者『互相影响』，须给出必要／充分条件这一具体判断。"}, {"order": 10, "qtype": "multi", "stem": "下列关于批判理论对法治／法律公平的质疑，哪些符合本节所述？", "options": ["A 形式中立可能掩盖结构性不平等", "B 法律规则反映既有权力与资源格局", "C 形式平等可能使不平等看起来合法", "D 法律公平总能自动带来社会公平"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】批判性立场质疑形式法律公平可能再生产社会不平等。【逐步演示】D 与批判立场及本节结论都相反。【易错提醒】不要把批判理论的质疑误写成对法律公平价值的完全否认。"}, {"order": 11, "qtype": "judge", "stem": "法律公平是社会公平的必要制度条件之一，但这并不意味着只要法律公平，社会就必然公平。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这正是本节的总结性判断。【逐步演示】法律公平是社会公平的重要制度基础，但资源占有与社会结构的改变还需要法律之外的条件。【易错提醒】注意这句话同时肯定必要性、否定充分性，两部分都成立。"}, {"order": 12, "qtype": "essay", "stem": "结合奥贝格费尔案，分析法院推进社会公平的方式为何会引发法律公平层面的争议。", "options": [], "answer": "", "accepted": [], "keywords": [["案件裁决", "颁发并承认同性婚姻", "正当程序与平等保护"], ["多数意见", "尊严与实质平等", "社会公平导向"], ["反对意见", "民主程序", "司法克制与可预测性"], ["双重评价", "宪法裁判既是程序又载价值", "兼顾程序与结果正当"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述裁决，再呈现多数与反对意见各自的价值关切，最后总结双重评价。【逐步演示】第一步说明法院改变了规则体系；第二步写多数意见的实质平等导向；第三步写反对意见对民主程序与确定性的关切。【易错提醒】不要简单判定哪一方『正确』，要呈现双方论据。"}]}, "S1M5K1": {"lesson": "S1M5K1", "questions": [{"order": 1, "qtype": "single", "stem": "戴雪（A. V. Dicey）法治理论的三层含义不包括下列哪一项？", "options": ["A 法律至上性", "B 法律面前人人平等", "C 宪法是权利保障的结果而非渊源", "D 法院必须服从行政机关"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】戴雪法治观包括法律至上、法律面前人人平等、宪法为权利保障之结果三层。【逐步演示】D 与法律至上原则直接冲突。【易错提醒】本题为否定式选择题，注意选出『不包括』的一项。"}, {"order": 2, "qtype": "single", "stem": "拉兹（Joseph Raz）如何定位法治？", "options": ["A 一种赋予法律独立道德价值的德性", "B 一种否定性德性（negative virtue）", "C 一种实质正义理论", "D 一种自然法命题"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，拉兹认为法治能减少专断权力之害但不赋予法律独立道德价值，故为『否定性德性』。【逐步演示】拉兹甚至主张即使在公正法律体系中也没有服从法律的初步义务。【易错提醒】A 与拉兹立场相反，是本题主要干扰项。"}, {"order": 3, "qtype": "judge", "stem": "『依法统治』（Rule by Law）与『法治』（Rule of Law）含义相同，都要求法律本身受到约束。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】依法统治只要求依法律行事，法律本身可以是压迫性的、可任意修改；法治则要求法律本身具备一般性、稳定性并真正约束权力。【逐步演示】二者的区别在于法律是否受约束。【易错提醒】这是理解法治含义的关键区分，切勿混用。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于形式法治所强调的内容？", "options": ["A 规则的一般性与公开性", "B 明确性与不溯及既往", "C 法律的稳定性", "D 法律内容必须符合实质正义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】形式法治强调法律的形式品质，如一般性、公开性、明确性、不溯及既往与稳定性。【逐步演示】这些正是富勒『内在道德』所列的要求。【易错提醒】D 属于实质法治的诉求，不是形式法治的核心。"}, {"order": 5, "qtype": "blank", "stem": "马伯里诉麦迪逊案（Marbury v. Madison, 1803）确立了美国联邦法院审查国会立法是否合宪的权力，即______制度。", "options": [], "answer": "", "accepted": ["司法审查", "违宪审查", "judicial review", "司法复审", "司法审查制度"], "keywords": [], "explanation": "【答案】司法审查（Judicial Review）。【解题思路】本案通过判定《1789年司法法》违宪，确立了司法审查制度。【逐步演示】它把法律至上具体化为宪法至上。【易错提醒】不要填『议会主权』，那是英国宪法的原则。"}, {"order": 6, "qtype": "single", "stem": "形式法治与实质法治争论的焦点是：", "options": ["A 法律是否应当公开", "B 法治是否必须包含正义与基本权利保障", "C 法律是否应当有法院执行", "D 法律是否应当成文化"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】形式法治只要求形式品质与权力约束，实质法治要求内容符合正义与人权。【逐步演示】分歧焦点在于法治是否必须包含实质价值。【易错提醒】A、C、D 属于两派大体共享的技术性要求，不是分歧所在。"}, {"order": 7, "qtype": "judge", "stem": "Wacks 指出，有人主张法律因符合法治理想而具有道德性，拉兹接受了这一主张。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出拉兹『refutes this proposition』（反驳了这一命题）。【逐步演示】拉兹认为法治只是减少权力滥用，不赋予法律独立道德价值。【易错提醒】注意题干把拉兹的立场写反了。"}, {"order": 8, "qtype": "single", "stem": "德沃金『政治完整性』（political integrity）对法治理论的贡献在于：", "options": ["A 把实体性的平等价值注入合法性概念", "B 主张法律与道德彻底分离", "C 提出最小国家理论", "D 否定宪法审查的正当性"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出，德沃金的合法性服务于政治完整性，要求政府依普遍原则治理。【逐步演示】这把实体平等价值带入对法律的理解。【易错提醒】B 是实证主义立场，C 属诺齐克，均与德沃金不符。"}, {"order": 9, "qtype": "essay", "stem": "试述戴雪、富勒、拉兹、德沃金各自对法治理论的贡献，并指出形式法治与实质法治的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["戴雪", "三层含义", "法律至上与平等"], ["富勒", "内在道德", "程序性要求"], ["拉兹", "否定性德性", "价值中立"], ["德沃金", "政治完整性", "形式与实质分歧焦点"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】按四位学者逐一说明，最后归纳分歧。【逐步演示】第一步写戴雪的三层框架；第二步写富勒的程序要求；第三步写拉兹的否定性德性；第四步写德沃金的实体注入与分歧焦点。【易错提醒】不要把拉兹与德沃金的立场对调。"}, {"order": 10, "qtype": "blank", "stem": "Wacks 记录的马克思主义批评者______把法治理解为对权力的有效抑制与对公民自由的保护，但其意识形态功能也受到质疑。", "options": [], "answer": "", "accepted": ["汤普森", "E. P. Thompson", "EP Thompson", "Thompson", "E.P.汤普森"], "keywords": [], "explanation": "【答案】汤普森（E. P. Thompson）。【解题思路】Wacks 记录了汤普森关于法治作为对权力有效抑制的观点及其所受批评。【逐步演示】这属于法治的社会批判维度。【易错提醒】不要填『马克思』本人，Wacks 此处讨论的是后世马克思主义者的立场。"}, {"order": 11, "qtype": "single", "stem": "马伯里案中，最高法院裁定《1789年司法法》的相关条款无效，其理由是：", "options": ["A 该法未经总统签署", "B 该法与宪法第三条关于最高法院管辖权的规定冲突", "C 该法违反了英国普通法", "D 该法未获参议院批准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】马歇尔法院认为该法赋予最高法院的原始管辖权超出宪法第三条允许的范围。【逐步演示】宪法高于普通法律，故该条款无效。【易错提醒】A、C、D 都不是本案的裁判理由。"}, {"order": 12, "qtype": "judge", "stem": "马伯里案表明，法治只需要有法律即可，不需要独立的司法机构来约束权力。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本案正是通过独立司法与违宪审查，把法律至上变成可操作的制度约束。【逐步演示】没有独立司法，法律至上难以对权力形成真实约束。【易错提醒】本题检验对法治制度载体的理解。"}, {"order": 13, "qtype": "essay", "stem": "结合马伯里案，分析法治与民主之间的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["司法审查", "法院推翻民选立法", "宪法至上"], ["法治价值", "约束权力", "保障权利"], ["民主关切", "反多数难题", "应由民选机关决定"], ["张力", "Wacks民主与法治专题", "制度平衡"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先说明本案确立的司法审查，再呈现法治与民主各自的价值关切，最后落到张力。【逐步演示】第一步写法院推翻立法的制度事实；第二步写法治约束权力的价值；第三步写民主的『反多数难题』质疑。【易错提醒】不要简单否定司法审查，要呈现双方论据。"}]}, "S1M5K2": {"lesson": "S1M5K2", "questions": [{"order": 1, "qtype": "single", "stem": "在戴雪的法治理论中，『法律面前人人平等』属于第几层含义？", "options": ["A 第一层", "B 第二层", "C 第三层", "D 不属于法治的含义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】戴雪法治观的三层为法律至上、法律面前人人平等、宪法作为权利保障的结果。【逐步演示】平等适用是第二层。【易错提醒】不要与第一层的『法律至上性』混淆。"}, {"order": 2, "qtype": "single", "stem": "普莱西诉弗格森案（Plessy v. Ferguson, 1896）确立的原则是：", "options": ["A 隔离但平等", "B 隔离即不平等", "C 法律面前人人平等", "D 司法审查"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】本案确立了『separate but equal』（隔离但平等）原则。【逐步演示】1954年布朗案才宣告公立教育中的种族隔离违反平等保护。【易错提醒】B 是布朗案的结论，恰与普莱西案相反。"}, {"order": 3, "qtype": "judge", "stem": "法律面前人人平等要求法律对所有情形作完全相同的处理，不允许任何合理差别。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】该原则反对的是任意的特权与歧视，允许基于正当理由并普遍适用的合理差别。【逐步演示】如对未成年人的特别保护并不违反这一原则。【易错提醒】『完全相同』是常见误读，关键词是『任意性』。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于『法律面前人人平等』的含义？", "options": ["A 任何人不得凌驾于法律之上", "B 法律对所有人一体适用", "C 所有人平等享有法律保护与救济", "D 所有人在事实上必须达到同等财富水平"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】该原则包含守法平等、适用平等与保护平等三层。【逐步演示】D 属于结果平等的诉求，不是形式意义上的法律面前人人平等。【易错提醒】不要把法律上的平等与事实上的平等混为一谈。"}, {"order": 5, "qtype": "blank", "stem": "美国宪法第______修正案的平等保护条款，是法律面前人人平等在宪法上的具体制度形态。", "options": [], "answer": "", "accepted": ["十四", "14", "第十四", "14th", "Fourteenth"], "keywords": [], "explanation": "【答案】十四（Fourteenth）。【解题思路】1868年第十四修正案包含平等保护条款。【逐步演示】它成为反种族隔离等运动的宪法依据。【易错提醒】注意与第十三修正案（废除奴隶制）区分。"}, {"order": 6, "qtype": "single", "stem": "Wacks 引述哈特的观察：种族歧视者往往辩称被歧视者『不是完全的人』。这一观察说明：", "options": ["A 平等原则已被广泛接受，歧视必须伪装", "B 哈特支持种族歧视", "C 法律面前人人平等没有规范力量", "D 歧视者通常公开承认平等"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】哈特认为平等原则已被广泛接受，以致歧视必须伪装成『被歧视者不同』。【逐步演示】这体现了平等原则的强大规范力量。【易错提醒】B、C、D 都与哈特原意相反。"}, {"order": 7, "qtype": "single", "stem": "德沃金对罗尔斯的批评中，他认为罗尔斯深层理论的核心是：", "options": ["A 差别原则", "B 每个人获得平等关怀与尊重的权利", "C 资格理论", "D 最大最小化"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，德沃金认为该权利是罗尔斯理论的核心，且是契约的前提而非产物。【逐步演示】这使平等具有道德底盘地位。【易错提醒】A、D 是罗尔斯自己的理论要素，不是德沃金批评的核心主张。"}, {"order": 8, "qtype": "judge", "stem": "普莱西案中，最高法院认为只要隔离设施相当，种族隔离不违反平等保护。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】本案裁判理由正是『隔离但平等』——设施相当即可。【逐步演示】这一形式平等逻辑后被布朗案推翻。【易错提醒】注意区分普莱西案（1896）与布朗案（1954）的结论。"}, {"order": 9, "qtype": "essay", "stem": "试论法律面前人人平等的形式含义与实质含义，并以普莱西案和布朗案说明二者的差异。", "options": [], "answer": "", "accepted": [], "keywords": [["形式含义", "同受约束与保护", "反对身份特权"], ["实质含义", "关注实际效果", "结构性不利"], ["普莱西案", "隔离但平等", "形式自洽"], ["布朗案", "隔离本身即伤害", "走向实质平等"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先界定两种含义，再用两个判例对照说明。【逐步演示】第一步写形式与实质的区别；第二步写普莱西案如何以形式平等固化等级；第三步写布朗案如何推进实质平等。【易错提醒】不要把两案的结论写反。"}, {"order": 10, "qtype": "blank", "stem": "判断一个法律分类是否违反平等，关键在于差别对待的理由是否正当、是否______。", "options": [], "answer": "", "accepted": ["任意", "任意的", "专断", "arbitrary", "无正当理由"], "keywords": [], "explanation": "【答案】任意（arbitrary）。【解题思路】法律面前人人平等反对的是任意的差别对待。【逐步演示】有正当理由且与目的相关的分类可以被接受。【易错提醒】不要填『存在』或『合理』，题干已经给出『正当』，此处强调其反面。"}, {"order": 11, "qtype": "single", "stem": "关于法律面前人人平等与法律至上的关系，下列哪一表述较准确？", "options": ["A 二者互不相关", "B 二者是法治的一体两面，平等适用是法律至上的保障", "C 法律至上必然导致不平等", "D 平等优先于法律至上，可无限牺牲法律确定性"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】戴雪法治理论中二者相互支撑：没有平等适用，法律至上可能沦为部分人统治。【逐步演示】A、C、D 都误置了二者关系。【易错提醒】D 的『无限牺牲』表述过于绝对，不符合法治的平衡要求。"}, {"order": 12, "qtype": "judge", "stem": "对残疾人提供无障碍设施属于不合理的特权，违反法律面前人人平等。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】基于正当理由并普遍适用的合理差别不违反该原则。【逐步演示】无障碍设施是对实际处境差异的合理回应，旨在实现更实质的平等。【易错提醒】本题检验能否把『合理差别』与『特权／歧视』区分开。"}]}, "S1M5K3": {"lesson": "S1M5K3", "questions": [{"order": 1, "qtype": "single", "stem": "富勒『内在道德』中，直接关系到法律可预测性的两项要求是：", "options": ["A 一般性与公开性", "B 明确性与不溯及既往", "C 稳定性与可遵守性", "D 官方行为与法律一致"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】明确性使人理解法律要求，不溯及既往使人能依行为当时的法律安排行为，二者直接支撑可预测性。【逐步演示】其他选项也是内在道德的内容，但与可预测性的关联不如 B 直接。【易错提醒】本题问的是『直接相关』的两项，注意审题。"}, {"order": 2, "qtype": "judge", "stem": "哈特与富勒在论战中都主张，面对纳粹时期的罪行，绝对不能制定溯及既往的立法。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，哈特与富勒『都更倾向于制定溯及既往的立法』来处理纳粹罪行。【逐步演示】两人的分歧在于如何理论化这一做法，而非是否应当追诉。【易错提醒】题干把两人立场写反了，属于对论战细节的常见误解。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于富勒『内在道德』所列举的法律要求？", "options": ["A 一般性", "B 公开颁布", "C 明确性与不矛盾", "D 内容必须符合实质正义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】富勒的内在道德包括一般性、公开性、不溯及既往、明确性、不矛盾、可遵守、稳定性、官方行为一致。【逐步演示】D 不属于富勒的清单，他关注的是程序健全而非内容正义。【易错提醒】Wacks 特别强调富勒采取的是程序性自然法立场。"}, {"order": 4, "qtype": "blank", "stem": "法律只适用于其生效后发生的行为、不得追诉既往行为的要求，称为______。", "options": [], "answer": "", "accepted": ["不溯及既往", "法不溯及既往", "非溯及既往", "non-retroactivity", "不溯及既往原则"], "keywords": [], "explanation": "【答案】不溯及既往（Non-retroactivity）。【解题思路】这是可预测性的时间维度。【逐步演示】它要求公民只能依行为当时的法律判断其合法性。【易错提醒】不要填『明确性』，那是空间／内容维度的要求。"}, {"order": 5, "qtype": "single", "stem": "哈特关于法律语言『开放结构』（open texture）的观点，主要强调：", "options": ["A 法律在任何情况下都完全确定", "B 法律核心地带相对确定，边缘地带存在不确定", "C 法律应当被废除以保障自由", "D 法官绝不能行使自由裁量"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特承认法律语言在核心地带确定、边缘地带不确定，这是任何法律体系的常态。【逐步演示】这使他对明确性的态度比富勒更现实。【易错提醒】A、D 都可能与哈特立场冲突，他承认边缘案件的裁量需要。"}, {"order": 6, "qtype": "single", "stem": "帕帕克里斯托诉杰克逊维尔市案（Papachristou v. Jacksonville, 1972）中，最高法院裁定流浪条例违宪的主要理由是：", "options": ["A 条例用语过于模糊，赋予警察过大裁量权", "B 条例未经市议会批准", "C 条例只适用于白人", "D 条例规定了过高的罚款"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法院认为条例用语模糊，公民无法预判何种行为违法，且导致任意执法。【逐步演示】这是『模糊无效』原则的经典适用。【易错提醒】B、C、D 都不是本案的裁判理由。"}, {"order": 7, "qtype": "judge", "stem": "德沃金认为，在疑难案件中法官应行使强自由裁量，创造新的法律规则。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金反对哈特式的『强自由裁量』观，主张法律包含可供援引的原则，法官应寻求『唯一正确答案』。【逐步演示】这使他在不牺牲可预测性的前提下解释法律的开放性。【易错提醒】本题把德沃金与哈特（或现实主义）的立场混淆了。"}, {"order": 8, "qtype": "blank", "stem": "美国法中，因法律用语过于模糊、普通公民无法理解而宣告其违宪的原则，称为『______无效』（Void for Vagueness）。", "options": [], "answer": "", "accepted": ["模糊", "模糊无效", "vague", "模糊（void for vagueness）"], "keywords": [], "explanation": "【答案】模糊（Void for Vagueness）。【解题思路】该原则要求法律给出可理解的禁止标准。【逐步演示】帕帕克里斯托案是其标志性判例。【易错提醒】不要填『不明确』或『笼统』，标准术语是『模糊无效』。"}, {"order": 9, "qtype": "essay", "stem": "试论法律明确性与可预测性对法治的意义，并说明明确性与自由裁量之间的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["服务于自主", "使人知道法律要求", "法律可被服从"], ["约束权力", "缩小任意解释空间", "防止选择性执法"], ["明确性与裁量", "明确性高则裁量小", "裁量必要以防僵化"], ["平衡", "核心地带确定边缘开放", "哈特开放结构"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先说明两项价值，再讨论张力与平衡。【逐步演示】第一步写明确性对人的自主与权力约束的意义；第二步写裁量的必要性；第三步用哈特的开放结构说明如何在二者间取得平衡。【易错提醒】不要走向两个极端，要承认裁量不可避免但需受约束。"}, {"order": 10, "qtype": "single", "stem": "关于富勒的内在道德，Wacks 的重要限定是：", "options": ["A 遵守它保证法律内容正义", "B 它只适用于大陆法系", "C 遵守它并不保证法律一定正义", "D 它否定了法律与道德的区分"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】Wacks 明确提醒，遵守富勒的内在道德并不保证法律正义，其论证支持的往往只是偶然的联系。【逐步演示】这体现了 Wacks 对富勒立场的审慎态度。【易错提醒】A 与 Wacks 的限定直接相反。"}, {"order": 11, "qtype": "judge", "stem": "明确性属于法治的形式要求，它本身并不保证法律内容的正义。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】明确性是形式要求，形式法治与实质正义的区分说明它不保证内容正义。【逐步演示】Wacks 对富勒的限定也支持这一判断。【易错提醒】不要因为明确性重要就认为它能替代对法律内容的实质评价。"}, {"order": 12, "qtype": "essay", "stem": "结合哈特与富勒的论战，分析溯及既往立法与法治原则之间的紧张关系。", "options": [], "answer": "", "accepted": [], "keywords": [["论战背景", "1958年哈佛法律评论", "纳粹罪行惩治"], ["富勒立场", "内在道德要求不溯及既往", "纳粹法非法律"], ["哈特立场", "两害相权取其轻", "溯及既往立法可接受"], ["理论意义", "效力与正当性关系", "形式原则可否权衡"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述论战背景，再呈现双方论据，最后上升到理论意义。【逐步演示】第一步写二战后惩治纳粹的情境；第二步写富勒基于内在道德的反对；第三步写哈特基于道德必要性的回应；第四步写这一争论对效力与正当性关系的意义。【易错提醒】注意两人实际上都倾向于溯及既往立法，分歧在理论化处理。"}]}, "S1M5K4": {"lesson": "S1M5K4", "questions": [{"order": 1, "qtype": "single", "stem": "司法独立的两个基本层面是：", "options": ["A 机构独立与个人独立", "B 立法独立与行政独立", "C 中央独立与地方独立", "D 实体独立与程序独立"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】司法独立包括法院在组织财政人事上的机构独立，以及法官在个案裁判中的个人独立。【逐步演示】B、C、D 都不是本节所述的基本划分。【易错提醒】注意不要把司法独立与整个国家的分权混为一谈。"}, {"order": 2, "qtype": "single", "stem": "系统阐述分权学说、为司法独立提供经典论证的思想家是：", "options": ["A 边沁", "B 孟德斯鸠", "C 奥斯丁", "D 哈特"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】孟德斯鸠在《论法的精神》中主张立法、行政、司法三权分立以防止权力滥用。【逐步演示】若司法权与立法权合并，法官将成为立法者。【易错提醒】A、C、D 虽是法理学家，但分权学说的经典表述者是孟德斯鸠。"}, {"order": 3, "qtype": "judge", "stem": "司法独立意味着法官不受任何形式的监督与约束，包括上诉审查与纪律监督。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】司法独立保障的是不受『不当干预』，而非不受任何监督；它必须与司法问责相平衡。【逐步演示】上诉制度、公开说理与纪律监督都是对司法的必要制约。【易错提醒】『独立』不等于『免责』，这是本节关键区分。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于保障司法独立的具体制度安排？", "options": ["A 法官任期保障", "B 法官薪酬保障", "C 法院在预算与人事上的自主管理", "D 政府对个案裁判的审批权"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】任期、薪酬与机构自主管理是司法独立的典型保障。【逐步演示】这些安排的共同目标是使法官敢于依法裁判。【易错提醒】D 恰是对司法独立的破坏，属于反向干扰项。"}, {"order": 5, "qtype": "blank", "stem": "英国1701年______确立了法官『品行端正期间任职』的原则，被视为司法独立的重要制度起点。", "options": [], "answer": "", "accepted": ["王位继承法", "王位继承法（Act of Settlement）", "Act of Settlement", "1701年王位继承法"], "keywords": [], "explanation": "【答案】王位继承法（Act of Settlement）。【解题思路】该法使法官不再随国王意志任免。【逐步演示】美国宪法第三条也以『良好行为』保障联邦法官任期。【易错提醒】不要填《大宪章》或《权利法案》，它们虽重要但与此原则直接相关的是1701年《王位继承法》。"}, {"order": 6, "qtype": "single", "stem": "Siems 的比较法研究指出，大陆法系的法官常被描述为：", "options": ["A 从资深律师中产生的法官", "B 在等级体系中按资历晋升的职业法官", "C 完全不受任何约束的法官", "D 由选举产生的法官"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出民法法系的 career judge 在等级体系中晋升，强调法律适用的统一。【逐步演示】普通法系法官则多从资深律师中产生，更强调个人判断。【易错提醒】注意区分两大法系的法官角色，不要混为一谈。"}, {"order": 7, "qtype": "single", "stem": "布什诉戈尔案（Bush v. Gore, 2000）中，最高法院多数意见裁定停止重新计票的主要宪法依据是：", "options": ["A 各郡采用不同计票标准违反平等保护条款", "B 总统选举属于政治问题法院无权受理", "C 州法院无权解释州法", "D 计票违反言论自由"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】多数意见认为不同郡的不同计票标准使选票效力因地域而异，违反第十四修正案平等保护。【逐步演示】法院据此叫停重新计票。【易错提醒】B 是反对介入者可能主张的『政治问题』理论，并非多数意见的依据。"}, {"order": 8, "qtype": "judge", "stem": "布什诉戈尔案中，最高法院以一致意见作出裁决，未引发争议。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本案以5比4的分裂投票作出，在美国社会引发关于司法能动与越权的巨大争议。【逐步演示】它成为司法独立与民主张力讨论的经典案例。【易错提醒】注意票数比例是5比4，不是一致意见。"}, {"order": 9, "qtype": "essay", "stem": "试论司法独立与司法问责的关系，并说明为何二者需要平衡。", "options": [], "answer": "", "accepted": [], "keywords": [["司法独立", "不受不当干预", "机构与个人独立"], ["司法问责", "上诉审查与公开说理", "纪律监督"], ["平衡理由", "独立保证公正裁判", "问责防止司法专横"], ["正当性", "独立依赖裁判可论证性", "公众接受"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先界定两个概念，再说明各自的必要性，最后落到平衡。【逐步演示】第一步写独立的价值；第二步写无制约的风险；第三步写问责如何强化独立的正当性。【易错提醒】不要把二者写成零和关系，合理的问责反而支撑独立。"}, {"order": 10, "qtype": "single", "stem": "霍姆斯『法律的生命不在逻辑，而在经验』这一名言，对司法独立的启示是：", "options": ["A 法官完全不受任何影响", "B 法官的背景与政策判断会影响裁判，需警惕以独立之名掩盖价值选择", "C 法律推理毫无意义", "D 法官应完全服从公众意见"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出这句话体现法律现实主义立场，提示真实决定案件的因素往往是法官的经验与政策判断。【逐步演示】这使我们对『独立即客观』保持警惕。【易错提醒】C、D 都是对现实主义名言的极端误读。"}, {"order": 11, "qtype": "judge", "stem": "德沃金认为，在疑难案件中法官应从法律原则中寻找『唯一正确答案』，这既支持司法独立也强调法律对法官的约束。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】德沃金反对强自由裁量观，主张法律原则包含正确答案。【逐步演示】法官需独立于政治压力，但受法律原则约束，并非随心所欲。【易错提醒】注意与哈特承认边缘地带裁量的立场区分。"}, {"order": 12, "qtype": "essay", "stem": "结合布什诉戈尔案，分析司法能动主义与司法克制的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["案件情境", "选举计票争议", "联邦最高法院介入"], ["能动主义", "积极适用宪法", "纠正州法院错误"], ["克制主义", "尊重民选机关", "政治问题与5比4争议"], ["张力实质", "独立法院角色", "合法性依赖说理与接受"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述情境，再呈现两种司法倾向的论据，最后总结张力。【逐步演示】第一步写法院介入政治争议的事实；第二步写支持者为何视之为维护法治；第三步写批评者为何担忧越权；第四步说明司法独立的正当性依赖于裁判说理。【易错提醒】不要简单站队，需呈现双方论据。"}]}, "S1M5K5": {"lesson": "S1M5K5", "questions": [{"order": 1, "qtype": "single", "stem": "戴雪法治理论的第一层含义是：", "options": ["A 法律面前人人平等", "B 法律至上性", "C 宪法是权利保障的结果", "D 司法独立"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】戴雪三层含义的第一层是法律至上性（Supremacy of Law）。【逐步演示】它强调法律高于专断权力。【易错提醒】A 是第二层，C 是第三层，注意层次顺序。"}, {"order": 2, "qtype": "single", "stem": "行政机关超越法律授权范围的行为无效，这一原则称为：", "options": ["A 越权无效（Ultra Vires）", "B 法律保留", "C 比例原则", "D 正当程序"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Ultra Vires 指权力超出授权范围即无效。【逐步演示】恩蒂克案是该原则的经典来源。【易错提醒】B、C、D 都是行政法重要原则，但含义不同。"}, {"order": 3, "qtype": "judge", "stem": "拉兹认为，遵守法治能赋予法律独立的道德价值，因此法治是一种肯定性的道德德性。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，拉兹认为法治能减少权力滥用但不赋予法律独立道德价值，是『否定性德性』。【逐步演示】拉兹甚至否认公正法律体系中服从法律的初步义务。【易错提醒】题干与拉兹立场完全相反。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于权力受法律约束的制度机制？", "options": ["A 法律依据原则", "B 越权无效原则", "C 司法审查", "D 行政官员的自我评价权"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律依据、越权无效与司法审查都是约束权力的机制。【逐步演示】它们共同确保权力有据可查、越界可纠。【易错提醒】D 不在其列，自我评价无法构成对权力的有效约束。"}, {"order": 5, "qtype": "blank", "stem": "行政机关超越法律授权范围的行为无效，拉丁法谚表述为______。", "options": [], "answer": "", "accepted": ["ultra vires", "Ultra Vires", "越权无效", "超越权限", "越权"], "keywords": [], "explanation": "【答案】Ultra Vires（越权无效）。【解题思路】该原则指权力超出授权范围即属无效。【逐步演示】恩蒂克案是其经典判例来源。【易错提醒】不要填『due process』或『stare decisis』，它们是其他法律原则。"}, {"order": 6, "qtype": "single", "stem": "恩蒂克诉卡林顿案（Entick v. Carrington, 1765）中，卡姆登勋爵的核心主张是：", "options": ["A 国务大臣的命令本身就是法律", "B 任何对公民财产的侵犯都必须有法律根据", "C 搜查令可由行政机关自由签发", "D 国家安全优先于公民财产权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】卡姆登勋爵强调，对公民权利的每次侵犯都需法律支持，行政权不能凭自身权威创设权力。【逐步演示】无法律授权的搜查令无效。【易错提醒】A 恰是法院否定的主张。"}, {"order": 7, "qtype": "judge", "stem": "恩蒂克案中，法院认定国务大臣签发的搜查令因缺乏法律依据而无效，官员行为构成非法侵入。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】本案事实即官员持搜查令进入民宅，法院判决其无法律依据、构成非法侵入。【逐步演示】本案确立了越权无效原则。【易错提醒】注意年份是1765年，法院为英国普通法法院。"}, {"order": 8, "qtype": "single", "stem": "现代行政法中，自由裁量与权力约束的关系是：", "options": ["A 二者完全对立，必须取消裁量", "B 裁量不可避免，需通过范围界定、理由说明与审查纳入法治轨道", "C 裁量越大越能实现法治", "D 裁量与法治无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律不可能预见一切情形，裁量不可避免，但须受范围、程序与审查的约束。【逐步演示】这与拉兹『减少专断风险』的定位一致。【易错提醒】A、C、D 都走极端，不符合现代行政法的实际。"}, {"order": 9, "qtype": "essay", "stem": "试论权力受法律约束的含义、制度机制与理论分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["含义", "权力有法律依据", "不得越界"], ["制度机制", "越权无效与司法审查", "分权制衡"], ["理论分歧", "形式约束对实质约束", "拉兹否定性德性"], ["局限", "法律本身可能不义", "德沃金政治完整性"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先写含义，再写机制，最后写分歧与局限。【逐步演示】第一步写法律依据与不越界；第二步写越权无效、司法审查等机制；第三步呈现形式与实质约束之争及拉兹、德沃金的立场。【易错提醒】不要只罗列制度，要落到形式与实质的理论分歧上。"}, {"order": 10, "qtype": "blank", "stem": "戴雪把法治的第一层含义称为法律的______，意指法律高于专断权力。", "options": [], "answer": "", "accepted": ["至上", "至上性", "supremacy", "法律至上", "Supremacy of Law"], "keywords": [], "explanation": "【答案】至上（Supremacy）。【解题思路】戴雪法治观第一层为 Supremacy of Law。【逐步演示】它强调法律高于任意意志。【易错提醒】不要填『平等』，那是第二层。"}, {"order": 11, "qtype": "judge", "stem": "形式法治论者认为，只要权力有法律依据、不越权，就足以实现对权力的充分约束。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是形式法治立场的核心主张：形式约束标准清晰、可操作。【逐步演示】实质论者则反驳说法本身可能不义，需加入实质限制。【易错提醒】本题问的是形式论者的立场，不是本节最终结论。"}, {"order": 12, "qtype": "essay", "stem": "结合恩蒂克案，分析司法审查在把『法律至上』转化为实际权力约束中的作用。", "options": [], "answer": "", "accepted": [], "keywords": [["案件事实", "搜查令进入民宅", "无法律授权"], ["裁判理由", "权力需法律根据", "越权无效"], ["司法审查作用", "法院检验法律依据", "宣告无据行为无效"], ["理论意义", "法治区别于依法统治", "需独立司法与救济"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述案情与裁判，再说明司法审查的功能。【逐步演示】第一步写搜查令缺乏法律依据；第二步写法院如何以越权无效宣告其行为无效；第三步说明这使法律至上成为可诉的规则。【易错提醒】不要只复述案情，要落到司法审查的制度作用上。"}]}, "S1M5K6": {"lesson": "S1M5K6", "questions": [{"order": 1, "qtype": "single", "stem": "自然正义（Natural Justice）的两项最低要求是：", "options": ["A 公开审判与迅速裁判", "B 裁判者中立与听取另一方意见", "C 律师代理与陪审团", "D 无罪推定与排除合理怀疑"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】自然正义的核心是 nemo judex in causa sua（中立）与 audi alteram partem（听证）。【逐步演示】前者排除偏私，后者保障参与。【易错提醒】C、D 是正当程序的具体制度，不是自然正义的两条最低原则。"}, {"order": 2, "qtype": "judge", "stem": "程序正当性只要求结果正确，至于决定过程是否公平并不重要。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】程序正当性的核心命题是：结果正确不能为过程专断辩护。【逐步演示】即使结果碰巧正确，过程不公仍构成正当性缺陷。【易错提醒】这是本节的基本立场，切勿混淆过程评价与结果评价。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于程序正当性的具体要求？", "options": ["A 裁判者中立无偏私", "B 当事人获得听证与陈述机会", "C 决定过程公开并说明理由", "D 决定结果符合分配正义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】中立、参与、公开与说理都是程序正当性的要求。【逐步演示】D 属于实体正义的评价维度。【易错提醒】区分『过程是否公平』与『结果是否公正』是做对本题的关键。"}, {"order": 4, "qtype": "blank", "stem": "美国宪法第______修正案的正当程序条款，是程序正当性的宪法依据之一。", "options": [], "answer": "", "accepted": ["十四", "14", "第十四", "第五和第十四", "5和14", "14th", "Fourteenth"], "keywords": [], "explanation": "【答案】十四（及第五）。【解题思路】第五修正案约束联邦、第十四修正案约束各州，均含正当程序条款。【逐步演示】戈德堡案即以第十四修正案为依据。【易错提醒】如果只能填一个，填『十四』，因本案针对州政府行为。"}, {"order": 5, "qtype": "single", "stem": "戈德堡诉凯利案（Goldberg v. Kelly, 1970）的核心裁决是：", "options": ["A 终止福利给付前必须提供通知与听证机会", "B 福利属于政府恩惠，可随时终止", "C 只有司法程序才受正当程序约束", "D 事后书面说明即可满足正当程序"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】最高法院要求终止福利前须提供充分通知与建设性听证。【逐步演示】本案把正当程序扩展到行政福利领域。【易错提醒】B、C、D 都是法院明确否定或超越的旧观念。"}, {"order": 6, "qtype": "judge", "stem": "戈德堡案中，最高法院以行政成本过高为由，认定事后听证即可满足正当程序。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法院虽承认成本增加，但认为这是保障程序公平的合理代价，要求在终止前听证。【逐步演示】本案拒绝了『成本优先』的政府主张。【易错提醒】题干与判决结论相反。"}, {"order": 7, "qtype": "single", "stem": "Wacks 对程序正当性的重要提醒是：", "options": ["A 程序越完善，实体正义越有保证", "B 仅遵守程序不足以保证实体正义", "C 程序与道德完全无关", "D 程序正当性只适用于法院"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确表示，仅遵守形式正义原则不足以达到道德上正确的门槛。【逐步演示】严格执行不义法律的法官仍未做到正义。【易错提醒】A 把程序与实体的关系绝对化了，程序有助于但不能保证实体正义。"}, {"order": 8, "qtype": "blank", "stem": "富勒把公开、明确、不溯及既往等程序要求称为法律的『______道德』。", "options": [], "answer": "", "accepted": ["内在", "内部", "internal", "内在道德", "internal morality"], "keywords": [], "explanation": "【答案】内在（Internal Morality）。【解题思路】富勒在《法律的道德性》中提出这一概念。【逐步演示】它体现了程序性自然法立场。【易错提醒】不要填『外在』或『实质』道德。"}, {"order": 9, "qtype": "essay", "stem": "试论程序正当性与实体正义的关系，并说明为何仅有程序不足以保证正义。", "options": [], "answer": "", "accepted": [], "keywords": [["程序价值", "保障尊严与参与", "约束权力"], ["促进实体", "听证减少错判", "吉迪恩与戈德堡案"], ["程序局限", "严格执行不义法律", "Wacks形式门槛不足"], ["综合", "程序与实体互补", "法治需二者兼顾"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先写程序的价值，再写其对实体的促进，最后写局限。【逐步演示】第一步写尊严与权力约束；第二步用案例说明程序减少错判；第三步引用 Wacks 说明执行不义法律的情形。【易错提醒】不要走向两个极端，要呈现程序与实体的互补关系。"}, {"order": 10, "qtype": "single", "stem": "关于正当程序条款，二十世纪美国法院发展出的『实体正当程序』理论主要涉及：", "options": ["A 审判程序的具体步骤", "B 某些基本权利内容不受政府任意干涉", "C 法院的诉讼费用", "D 行政听证的时间长度"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】实体正当程序用该条款保护不受政府任意干涉的基本权利。【逐步演示】它与关注过程公平的程序性正当程序相对。【易错提醒】A 属于程序性正当程序的范畴。"}, {"order": 11, "qtype": "judge", "stem": "程序正当性与形式正义完全相同，没有任何区别。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】形式正义强调规则一致适用，程序正当性还包含参与、听证、说理等要求，范围更广。【逐步演示】二者相关但不等同。【易错提醒】注意本题要求识别『完全相同』这一绝对化表述的问题。"}, {"order": 12, "qtype": "essay", "stem": "结合戈德堡案，分析程序保障与行政效率之间的权衡。", "options": [], "answer": "", "accepted": [], "keywords": [["案件背景", "未听证即终止福利", "市政府主张成本"], ["法院立场", "福利关乎基本生存", "事前通知与听证"], ["效率论据", "成本与程序负担", "事后救济可能足够"], ["权衡结论", "程序是合法性成本", "紧急情形需替代保障"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述案情，再呈现效率与程序双方的论据，最后给出权衡。【逐步演示】第一步写未听证终止福利的事实；第二步写政府基于成本的主张；第三步写法院为何要求事前听证；第四步延伸到紧急情形的替代保障。【易错提醒】不要只站在程序一边，要承认效率论据的合理性。"}]}, "S1M5K7": {"lesson": "S1M5K7", "questions": [{"order": 1, "qtype": "single", "stem": "法治与人治的核心区别在于：", "options": ["A 是否有法律存在", "B 权力是否真正受法律约束", "C 是否有法院", "D 是否有统治者"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法治意味着权力受普遍规则约束，人治则取决于统治者个人意志。【逐步演示】二者区别不在『有没有法律』，而在权力是否真正受法律约束。【易错提醒】A 是常见误答——人治社会也可能有法律，只是法律不约束权力。"}, {"order": 2, "qtype": "single", "stem": "柏拉图『哲学王』（Philosopher-King）设想属于哪一传统的经典论证？", "options": ["A 法治", "B 人治／贤人政治", "C 法律实证主义", "D 分权理论"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】柏拉图在《理想国》中设想由掌握善的理念的智者统治，是人治／贤人政治的经典表达。【逐步演示】亚里士多德则在《政治学》中主张法治优于人治。【易错提醒】不要把柏拉图与亚里士多德的立场对调。"}, {"order": 3, "qtype": "judge", "stem": "『依法统治』（Rule by Law）与『法治』（Rule of Law）含义相同，可以互换使用。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】依法统治只要求依法律行事，法律本身可以是压迫性、可任意修改的工具；法治要求法律本身具备一般性、稳定性并真正约束权力。【逐步演示】二者有本质区别。【易错提醒】本题是理解本节的核心考点。"}, {"order": 4, "qtype": "multi", "stem": "亚里士多德论证法治优于人治的理由包括：", "options": ["A 法律凝聚多数人的智慧", "B 法律不受个人欲望与偏见支配", "C 权力容易腐蚀人", "D 法律能够完全预见一切具体情境"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】亚里士多德认为法律凝聚集体智慧、无欲望，且权力易腐蚀人。【逐步演示】D 恰是人治一方对法律的批评，不是亚里士多德的论据。【易错提醒】注意题目问的是『亚里士多德的论据』。"}, {"order": 5, "qtype": "blank", "stem": "拉兹把法治定位为一种『______德性』，认为它不能保证良政，但能减少专断权力之害。", "options": [], "answer": "", "accepted": ["否定性", "消极", "negative", "否定性的", "消极的"], "keywords": [], "explanation": "【答案】否定性（Negative Virtue）。【解题思路】Wacks 记载，拉兹认为法治不赋予法律独立道德价值，但能减少权力滥用。【逐步演示】这是一种低调但坚实的法治辩护。【易错提醒】不要填『肯定性』，那与拉兹立场相反。"}, {"order": 6, "qtype": "single", "stem": "英国最高法院 R（米勒）诉首相案（2019）的核心裁决是：", "options": ["A 首相建议议会休会属政治问题，法院无权审查", "B 无正当理由的休会建议违法并无效", "C 议会无权监督政府", "D 首相拥有不受法律约束的特权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】最高法院一致裁定首相建议休会违法且无效，因其妨碍议会履行宪法职能。【逐步演示】本案是英国历史上法院首次裁定首相建议违法。【易错提醒】A、C、D 都与判决结论相反。"}, {"order": 7, "qtype": "judge", "stem": "米勒案中，英国最高法院以微弱多数作出裁决，引发巨大分歧。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本案由11名法官组成合议庭并作出一致裁定。【逐步演示】一致判决强化了裁决的宪制权威。【易错提醒】注意本案是『一致裁定』，而非『微弱多数』。"}, {"order": 8, "qtype": "single", "stem": "现代法治对『人的判断』的态度是：", "options": ["A 完全排除一切自由裁量", "B 允许裁量但须在法律框架内并接受程序与审查约束", "C 裁量越大越好", "D 裁量与法治无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】现代法治追求『规则之治下的合理裁量』，既承认裁量的必要，又要求其受约束。【逐步演示】这避免了机械规则与任意人治两个极端。【易错提醒】A、C、D 都是极端化表述。"}, {"order": 9, "qtype": "essay", "stem": "试论法治与人治的核心区别，并分析『依法统治』为何不等于法治。", "options": [], "answer": "", "accepted": [], "keywords": [["核心区别", "普遍规则对个人意志", "权力受约束与可预测"], ["依法统治", "法律作为统治工具", "法律本身不受约束"], ["亚里士多德论证", "法律凝聚多人智慧", "权力易腐蚀"], ["拉兹定位", "否定性德性", "减少专断之害"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先写核心区别，再写依法统治与法治的分野，最后补充理论支持。【逐步演示】第一步从规则普遍性、权力约束、可预测性三方面写区别；第二步说明依法统治为何可能只是人治伪装；第三步引用亚里士多德与拉兹。【易错提醒】不要只喊口号，要落到具体的区别维度。"}, {"order": 10, "qtype": "blank", "stem": "戴雪法治理论把法律面前人人平等作为第______层含义。", "options": [], "answer": "", "accepted": ["二", "2", "第二", "second"], "keywords": [], "explanation": "【答案】二（Second）。【解题思路】戴雪三层为法律至上、法律面前人人平等、宪法作为权利保障的结果。【逐步演示】平等适用是第二层。【易错提醒】不要填『一』，第一层是法律至上性。"}, {"order": 11, "qtype": "judge", "stem": "法治的支持者通常承认贤人可能作出更好的个别决定，但坚持制度性约束更可靠。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】现代法治的折中立场承认人的判断价值，但坚持权力须受法律约束。【逐步演示】这既回应了人治的灵活性优势，又坚持了法治的制度底线。【易错提醒】法治并非否认贤人的价值，而是不把命运寄托于个人品德。"}, {"order": 12, "qtype": "essay", "stem": "结合米勒案，分析法治原则如何现实地约束最高行政权力，并讨论其中体现的司法独立与民主的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["案件事实", "首相建议休会", "最高法院裁定违法无效"], ["法治约束", "特权亦须守法", "议会宪法职能"], ["司法独立", "法院界定权力界限", "守护宪法原则"], ["民主张力", "法院介入政治", "反多数质疑与合法性"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先述案情与裁决，再分析法治约束，最后讨论司法与民主的张力。【逐步演示】第一步写休会建议被宣告无效；第二步说明这如何体现权力受法律约束；第三步写法院介入政治引发的民主质疑。【易错提醒】不要只赞美或只批评，要呈现双方的价值关切。"}]}, "S2M1K1": {"lesson": "S2M1K1", "questions": [{"order": 1, "qtype": "single", "stem": "自然法思想在古希腊语境中主要表现为哪一对概念的区分？", "options": ["A 法律与道德", "B 自然（Physis）与约定（Nomos）", "C 权利与义务", "D 主权与臣民"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】古希腊自然法思想的原初问题，是事物本性与人为约定何者优先。【逐步演示】physis 指依本性的秩序，nomos 指城邦制定的人为规则，自然法由此主张存在高于约定的正义标准。【易错提醒】法律与道德的区分是近代实证主义的论题，不是古希腊表述这一问题的原始方式。"}, {"order": 2, "qtype": "single", "stem": "下列哪一项最准确地概括了自然法的基本主张？", "options": ["A 法律的有效性完全来自制定程序", "B 存在可被理性发现、高于人定法的普遍正义原则", "C 法律只是法官实际做出的判决", "D 法律与道德在概念上必须分离"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】自然法主张客观正义原则可被理性发现，且高于特定城邦或王国的制定法。【逐步演示】它包含三项要点：客观正义、普遍适用、人法须受其检验。【易错提醒】A 与 D 属实证主义立场，C 属法律现实主义立场，均与自然法相左。"}, {"order": 3, "qtype": "judge", "stem": "自然法理论认为，一项法律的正当性最终来自它被合法机关依程序制定这一事实。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这正是实证主义的主张，自然法强调法律内容须符合更高正义原则。【逐步演示】自然法把正当性系于内容正义与理性秩序，而非制定来源。【易错提醒】『来源』与『内容』是区分自然法与实证主义的关键坐标，勿混淆。"}, {"order": 4, "qtype": "blank", "stem": "斯多葛学派把支配宇宙的普遍理性称为______，认为人因分有它而同属一个世界共同体。", "options": [], "answer": "", "accepted": ["Logos", "宇宙理性", "逻各斯", "理性法则"], "keywords": [], "explanation": "【答案】宇宙理性（Logos）。【解题思路】斯多葛学派以 Logos 解释自然法的普遍性与人的平等。【逐步演示】人因分有 Logos 而与神、与他人同属宇宙共同体，由此推出世界公民观念。【易错提醒】不要把 Logos 与赫拉克利特的『火』或柏拉图的『理念』混为一谈。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，下列哪些属于自然法传统中的代表性立场或人物？", "options": ["A 柏拉图对正义理念的追求", "B 斯多葛学派的宇宙理性", "C 罗马法学家的万民法概念", "D 奥斯丁的命令理论"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】自然法传统包含柏拉图的理念论、斯多葛的 Logos、罗马法的 ius gentium。【逐步演示】D 属法律实证主义，主张法律来自主权者命令，与自然法传统对立。【易错提醒】多选题要排除明显属于对立学派的选项。"}, {"order": 6, "qtype": "single", "stem": "西塞罗『真正的法律是正当的理性，永恒不变，对所有民族有效』这一表述属于哪一思想传统？", "options": ["A 法律实证主义", "B 斯多葛式自然法", "C 法律现实主义", "D 功利主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】西塞罗以正当理性界定真正的法律，是斯多葛自然法的经典表述。【逐步演示】其要点是法律的普遍性与永恒性，违背它的制定法不具法律性质。【易错提醒】西塞罗的这一命题是强自然法的古代版本，注意与阿奎那的论述相区别。"}, {"order": 7, "qtype": "judge", "stem": "强自然法与软自然法都主张，严重不正义的规则根本不能被称为法律。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】强自然法否认恶法的法资格，软自然法则承认其仍为法但丧失服从义务。【逐步演示】二者分歧正在于『是否仍为法律』这一判断。【易错提醒】Wacks 区分 hard 与 soft natural law，此区分是理解当代自然法内部差异的关键。"}, {"order": 8, "qtype": "blank", "stem": "古罗马法学家乌尔比安把自然法界定为『自然教给一切______的规则』。", "options": [], "answer": "", "accepted": ["动物", "生灵", "万物", "animals"], "keywords": [], "explanation": "【答案】动物。【解题思路】乌尔比安的名言把自然法界定为自然教给一切动物的规则。【逐步演示】这一界定体现自然法的普遍性与目的论色彩，不局限于人类。【易错提醒】此处『动物』的提法常与罗马法承认奴隶制的现实形成张力，是理解自然法局限的切入点。"}, {"order": 9, "qtype": "essay", "stem": "试述古希腊 physis 与 nomos 之争的实质，并说明它如何预示了后世自然法与法律实证主义的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["自然与约定的对立", "physis与nomos"], ["智者学派主张约定优先", "法律是强者利益"], ["苏格拉底柏拉图主张客观正义", "理性可把握"], ["预示正当性来源之争", "内容正义与制定来源"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先解释 physis/nomos 的含义，再说明双方论据，最后把它与后世之争对接。【逐步演示】实质是法律正当性来自本性还是约定；智者学派怀疑客观正义，苏格拉底与柏拉图坚持理性可把握正义；这一结构在后世转化为内容正义与制定来源之争。【易错提醒】不要简单把智者学派说成『无法学家』，他们提出了有力的怀疑论论证。"}, {"order": 10, "qtype": "single", "stem": "自然法理论在二十世纪复兴的两个主要代表人物是：", "options": ["A 奥斯丁与边沁", "B 富勒与菲尼斯", "C 霍姆斯与卢埃林", "D 凯尔森与拉兹"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】二战后自然法复兴的代表是富勒（程序性自然法）与菲尼斯（基本善理论）。【逐步演示】富勒提出内在道德，菲尼斯重述阿奎那的基本善与实践理性。【易错提醒】A 是古典实证主义代表，C 是法律现实主义代表，D 中凯尔森与拉兹属实证主义。"}, {"order": 11, "qtype": "multi", "stem": "下列哪些主张属于自然法传统？", "options": ["A 恶法非法（lex iniusta non est lex）", "B 国际法受自然法约束", "C 法的效力取决于承认规则", "D 人法应从自然法获得约束力"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】自然法主张恶法非法、国际法受自然法约束、人法从自然法获得效力。【逐步演示】C 是哈特的实证主义命题，承认规则属社会来源标准。【易错提醒】『恶法非法』严格说来并非阿奎那原话，但确属自然法传统的核心命题。"}, {"order": 12, "qtype": "judge", "stem": "纽伦堡审判中，检方以被告行为符合当时德国制定法为由主张其无罪。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】提出『符合当时法律』抗辩的是辩护方，检方诉诸更高正义原则。【逐步演示】检方主张某些行为即使形式上合法，也因严重违背文明社会基本准则而构成犯罪。【易错提醒】注意区分控辩双方立场，这是理解自然法思维在审判中体现的关键。"}, {"order": 13, "qtype": "essay", "stem": "结合自然法的起源，分析为何国际人权法常采用『人人生而自由』式的普遍命题，而非『某国公民享有某些权利』式的特殊授权。", "options": [], "answer": "", "accepted": [], "keywords": [["斯多葛世界公民观念", "普遍理性"], ["自然法高于人定法", "权利不依赖国家授予"], ["普遍命题形式", "所有人一体适用"], ["特殊授权依赖国家", "可被取消"]], "explanation": "【答案要点】见 keywords。【解题思路】从斯多葛普遍主义切入，分析权利来源与表述形式的关系。【逐步演示】自然法主张人因理性而平等，权利先于国家；普遍命题形式正体现这一点，而特殊授权则把权利系于国家意志。【易错提醒】不要简单断言普遍人权『就是自然法』，应说明其思想渊源上的承继关系。"}]}, "S2M1K2": {"lesson": "S2M1K2", "questions": [{"order": 1, "qtype": "single", "stem": "亚里士多德在《尼各马可伦理学》中区分的两种正义是：", "options": ["A 自然正义与法律正义", "B 分配正义与矫正正义", "C 抽象正义与具体正义", "D 形式正义与实质正义"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】亚里士多德区分自然正义（依本性普遍有效）与法律正义（由城邦规定、可变）。【逐步演示】自然正义不因人们认可与否而改变，法律正义则源于具体城邦规定。【易错提醒】分配正义与矫正正义也是亚里士多德的区分，但属于正义的『类型』而非『根据』，勿混淆。"}, {"order": 2, "qtype": "single", "stem": "罗马法中被认为由自然本身确立、动物与人类共同具有的规则称为：", "options": ["A 万民法（ius gentium）", "B 市民法（ius civile）", "C 自然法（ius naturale）", "D 神法（ius divinum）"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】罗马法中的 ius naturale 即自然法，被界定为自然教给一切动物的规则。【逐步演示】万民法是各民族共同理性形成的法，市民法是城邦专属的法，二者与自然法构成层级分类。【易错提醒】万民法与自然法内容常重合，但原初含义不同，注意区分。"}, {"order": 3, "qtype": "judge", "stem": "斯多葛学派的世界公民观念认为，只有希腊城邦的自由民才分有宇宙理性。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】斯多葛学派主张人人分有 Logos，无论希腊人或野蛮人、自由人或奴隶。【逐步演示】这一普遍主义是近代国际法与个人权利观念的重要源头。【易错提醒】罗马法现实中的奴隶制与自然法的平等承诺之间存在张力，不要因此否认斯多葛理论的普遍主义。"}, {"order": 4, "qtype": "blank", "stem": "罗马法学家______在《法学阶梯》开篇区分了市民法与万民法。", "options": [], "answer": "", "accepted": ["盖尤斯", "Gaius", "盖尤士"], "keywords": [], "explanation": "【答案】盖尤斯（Gaius）。【解题思路】《法学阶梯》开篇即区分罗马民族特有的市民法与自然理性在所有民族中确立的万民法。【逐步演示】这一区分被查士丁尼《法学总论》继承，成为罗马法分类的正统框架。【易错提醒】乌尔比安以自然法定义闻名，盖尤斯以《法学阶梯》的分类闻名，勿张冠李戴。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，古代自然法思想包含下列哪些要素？", "options": ["A 目的论的宇宙观", "B 理性可发现正义原则", "C 规范效力有等级", "D 法律与道德在概念上完全分离"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】古代自然法包含目的论、理性可发现性、效力等级三要素。【逐步演示】D 属法律实证主义的分离命题，与自然法师徒相对。【易错提醒】『完全分离』这类绝对化表述，通常不属于自然法立场。"}, {"order": 6, "qtype": "single", "stem": "西塞罗在《国家篇》中表达的『真正的法律是正当的理性』命题，最接近下列哪一立场？", "options": ["A 强自然法", "B 法律实证主义", "C 法律现实主义", "D 功利主义"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】西塞罗主张违背正当理性的元老院决议或人民法不具法律性质，属强自然法命题。【逐步演示】强自然法否认严重不正义规则的法资格。【易错提醒】不要把西塞罗与主张『恶法亦法』的实证主义混淆。"}, {"order": 7, "qtype": "judge", "stem": "把『恶法非法』这一命题直接归于亚里士多德，是一种时代错置。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】亚里士多德承认自然正义与法律正义并存，并未主张不正义的制定法当然无效。【逐步演示】『恶法非法』是后世尤其经阿奎那与二战后自然法复兴才明确化的命题。【易错提醒】思想史判断要注意概念的历史性，避免把后世命题投射到前人。"}, {"order": 8, "qtype": "single", "stem": "古代自然法中，斯多葛学派与罗马法学家的主要差别在于：", "options": ["A 前者重哲学思辨与普遍伦理，后者重法律分类与司法技术", "B 前者主张法律与道德分离，后者主张法律与道德联系", "C 前者只讨论国际法，后者只讨论国内法", "D 两者完全相同"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】希腊斯多葛学派提供自然法的哲学与伦理灵魂，罗马法学家提供法律技术骨架。【逐步演示】斯多葛关注 Logos 与世界公民，罗马法学家关注法律分类、效力与管辖。【易错提醒】不要因两者都讲自然法就忽视其问题意识与方法的差异。"}, {"order": 9, "qtype": "essay", "stem": "试论古罗马三种法的划分（自然法、万民法、市民法）及其对现代国际法与比较法的意义。", "options": [], "answer": "", "accepted": [], "keywords": [["三层效力等级", "普遍到特殊"], ["万民法处理跨民族关系", "自然理性"], ["市民法特定城邦有效", "可变"], ["现代意义", "普遍标准与地方法律并存"]], "explanation": "【答案要点】见 keywords。【解题思路】先说明三种法的含义与层级，再讨论其现代回响。【逐步演示】自然法最普遍、市民法最特殊，万民法处理跨民族关系；这一层级结构在今天转化为国际法与国内法、普遍标准与地方法律的关系。【易错提醒】不要简单把万民法等同于现代国际法，二者历史语境不同。"}, {"order": 10, "qtype": "blank", "stem": "斯多葛学派把使自然法普遍有效的宇宙理性称为______（Logos）。", "options": [], "answer": "", "accepted": ["Logos", "宇宙理性", "逻各斯"], "keywords": [], "explanation": "【答案】Logos（宇宙理性）。【解题思路】斯多葛学派以 Logos 解释自然法的普遍性与必然性。【逐步演示】人因分有 Logos 而与神、他人构成理性共同体。【易错提醒】Logos 在此指支配宇宙的理性法则，不宜与一般意义上的『逻辑』混同。"}, {"order": 11, "qtype": "single", "stem": "乌尔比安把法学界定为：", "options": ["A 关于神事与人事的知识、正义与不义的区分", "B 主权者发布的命令", "C 法官实际做出什么", "D 法律与道德的分离"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】乌尔比安把法学界定为『神事与人事的知识、正义与不义的区分』。【逐步演示】这一界定把法学理解为关于正义的知识，体现自然法传统对法律的道德理解。【易错提醒】B 是奥斯丁的命令理论，C 接近现实主义，D 属实证主义。"}, {"order": 12, "qtype": "judge", "stem": "罗马法中的万民法原初含义接近『各民族共有的实在法』，后来才逐渐与自然法理念合流。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】万民法在罗马法中更接近各民族共有的法律实践，与自然法理念在历史中逐渐合流。【逐步演示】这一细节对准确理解罗马法中的自然法概念很重要。【易错提醒】不要把万民法从一开始就当作纯粹的自然法理念。"}, {"order": 13, "qtype": "essay", "stem": "乌尔比安一方面说自然法教给一切动物，另一方面承认奴隶制的正当性。这一矛盾说明了什么？", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】从概念张力入手，分析自然法承诺与现实制度的关系。【逐步演示】自然法的平等承诺与奴隶制现实的并存，说明普遍原则的具体化需要制度中介，也说明自然法语言可能被用于为现状辩护。【易错提醒】不要因此简单否认自然法的批判价值，应看到其双面性。", "keywords": [["普遍平等承诺与现实制度落差", "自然法与奴隶制矛盾"], ["概念可被用于不同目的", "为现状辩护或批判现状"], ["自然法需具体化", "原则与现实的中介"], ["警惕把特定制度包装成自然", "批判性反思"]]}]}, "S2M1K3": {"lesson": "S2M1K3", "questions": [{"order": 1, "qtype": "single", "stem": "阿奎那区分的四种法律是：", "options": ["A 永恒法、自然法、人法、神法", "B 自然法、万民法、市民法、神法", "C 宪法、法律、法规、判例", "D 国际法、国内法、习惯法、判例法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】阿奎那区分永恒法、自然法、人法与神法四种法律。【逐步演示】永恒法是上帝的宇宙计划，自然法是理性生物对永恒法的分有，人法由人类权威制定，神法通过启示补充。【易错提醒】B 是罗马法的三分，常被混淆，注意区分阿奎那的四分与罗马法的三分。"}, {"order": 2, "qtype": "blank", "stem": "阿奎那认为，自然法是理性生物对______的分有（participation）。", "options": [], "answer": "", "accepted": ["永恒法", "Eternal Law", "上帝的理性计划"], "keywords": [], "explanation": "【答案】永恒法。【解题思路】自然法是永恒法在理性生物中的分有。【逐步演示】菲尼斯指出，阿奎那所谓分有聚焦因果关系：某性质之所以存在于一物，是因为它被具有类似性质的更高原因所造成。【易错提醒】分有不是简单的『部分分享整体』，而是因果上的依赖与传导。"}, {"order": 3, "qtype": "judge", "stem": "『恶法非法』（lex iniusta non est lex）是阿奎那在《神学大全》中的原话。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，阿奎那本人似乎从未明确提出这一命题。【逐步演示】阿奎那更接近的说法是：违背自然法的法律丧失道德权威，他称这类法律为『法律的腐败』。【易错提醒】菲尼斯也把『恶法非法』一类命题称为『松散的』表述，注意这一学术细节。"}, {"order": 4, "qtype": "single", "stem": "根据 Wacks 的梳理，阿奎那认为人法的约束力来自：", "options": ["A 主权者的命令", "B 自然法", "C 法官的判决", "D 社会习俗"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】阿奎那明确主张人法（posited human law）的约束力源于自然法。【逐步演示】这构成其法律等级体系的核心环节：人法—自然法—永恒法。【易错提醒】A 是奥斯丁的命令理论，与阿奎那的立场相反。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，阿奎那自然法理论的要素包括：", "options": ["A 实践理性的可认识性", "B 第一原则与次级原则的区分", "C 法律以共同善为目标", "D 法律与道德在概念上完全分离"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】阿奎那强调实践理性、原则分层与共同善。【逐步演示】D 属实证主义分离命题，与阿奎那的法律观相悖。【易错提醒】阿奎那虽区分法律与道德的层次，但从未主张二者在概念上完全分离。"}, {"order": 6, "qtype": "judge", "stem": "阿奎那区分第一原则与次级原则，并承认次级原则在具体适用中可能因环境而难以判断。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】阿奎那承认自然法原则在具体化过程中可能模糊。【逐步演示】第一原则自明，次级原则由推理得出，可能因情境而难以确定。【易错提醒】这一承认为自然法应对『不确定性』批评提供了资源。"}, {"order": 7, "qtype": "single", "stem": "阿奎那把严重违背自然法的法律称为：", "options": ["A 法律的腐败", "B 有效的法律", "C 主权者的命令", "D 习惯法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】阿奎那把违背自然法、丧失道德权威的法律称为『法律的腐败』（corruptio legis）。【逐步演示】这一概念比『恶法非法』的口号更精细，区分了不同情形。【易错提醒】不要把『法律的腐败』等同于阿奎那从未说过的『恶法非法』原话。"}, {"order": 8, "qtype": "essay", "stem": "试述阿奎那四种法律的等级结构，并说明人法效力来自自然法这一命题的意义。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明四种法的含义与层级，再分析人法效力命题的理论后果。【逐步演示】等级结构使法律的正当性有超越根据；人法若背离自然法就丧失充分正当性，这为批判不义法律提供了概念空间。【易错提醒】不要把阿奎那简化为『教会权威代言人』，其理论中有实践理性与共同善的精细论述。", "keywords": [["四法等级", "永恒法自然法人法神法"], ["人法效力源于自然法", "下位法从上位法获得正当性"], ["共同善是法律目的", "法律须指向公共福祉"], ["为批判不义之法留下空间", "法律的腐败"]]}, {"order": 9, "qtype": "blank", "stem": "菲尼斯指出，阿奎那所谓『分有』（participatio）在焦点意义上包含因果性与______两个概念。", "options": [], "answer": "", "accepted": ["similitude", "相似性", "类似", "类似性"], "keywords": [], "explanation": "【答案】相似性（similitude）。【解题思路】菲尼斯指出阿奎那的分有聚焦因果关系与相似性的结合。【逐步演示】某性质之所以被分有，是因为它被具有类似性质的更高原因所造成。【易错提醒】此细节体现菲尼斯对阿奎那的精细化解读，注意不要把它与普通的『部分—整体』关系混淆。"}, {"order": 10, "qtype": "single", "stem": "德国战后的『拉德布鲁赫公式』在自然法脉络中的核心主张是：", "options": ["A 一切制定法均有效", "B 极端不正义的法律丧失法的性质", "C 法官只需适用规则文字", "D 法律效力与道德完全无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】拉德布鲁赫公式主张当制定法与正义的矛盾不可容忍时，该法律丧失法的性质。【逐步演示】这一公式在德国战后司法中被援引，带有明显的自然法色彩。【易错提醒】拉德布鲁赫本身出自实证主义传统，其公式是对法律确定性原则的例外性修正，勿简单等同于古典自然法。"}, {"order": 11, "qtype": "judge", "stem": "阿奎那主张，法律只需关注外在行为与共同秩序，不必指向共同善。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】阿奎那明确主张法律必须以共同善（common good）为目标。【逐步演示】法律若沦为统治者私人利益的工具，就背离了法律的本质。【易错提醒】共同善是阿奎那法律定义的核心要素，不可遗漏。"}, {"order": 12, "qtype": "multi", "stem": "关于阿奎那与菲尼斯的关系，下列说法正确的有：", "options": ["A 菲尼斯继承阿奎那的实践理性与基本善思路", "B 菲尼斯刻意淡化阿奎那的神学形而上学色彩", "C 菲尼斯认为阿奎那的贡献长期被误解", "D 菲尼斯完全否认自然法与阿奎那的关联"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】菲尼斯继承并重新阐释阿奎那，淡化其神学色彩，主张阿奎那被误解。【逐步演示】D 明显错误，菲尼斯的工作正是以阿奎那为资源。【易错提醒】菲尼斯对阿奎那是『重新阐释』而非『全盘否定』，注意这一区分。"}, {"order": 13, "qtype": "essay", "stem": "结合菲尼斯对阿奎那的解读，分析把『恶法非法』直接归于阿奎那为何是一种过度简化。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】从学术史细节切入，说明简化带来的理论后果。【逐步演示】Wacks 与菲尼斯均指出阿奎那本人未明确提出该命题；阿奎那的论述更接近『丧失道德权威』与『法律的腐败』；把口号归于他，会遮蔽其立场的精细性。【易错提醒】不要因此否认自然法传统中确有明显的不正义法律批判命题。", "keywords": [["阿奎那本人未明确说恶法非法", "原话问题"], ["他区分法律的腐败与法律本身", "精细处理"], ["丧失道德权威不等于不存在", "效力与正当性分开"], ["过度简化的后果", "漫画化自然法立场"]]}]}, "S2M1K4": {"lesson": "S2M1K4", "questions": [{"order": 1, "qtype": "single", "stem": "格劳秀斯在《战争与和平法》中提出的著名假设『即使假设上帝不存在』（etiamsi daremus）旨在说明：", "options": ["A 自然法的有效性不依赖神的意志", "B 上帝不存在", "C 国际法不需要任何基础", "D 法律与道德完全分离"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】格劳秀斯以这一思想实验说明自然法合乎人的理性与社会本性，即使不存在上帝依然有效。【逐步演示】Wacks 指出，格劳秀斯认为某些行为是『内在地错误的』，无论上帝是否规定。【易错提醒】这是一个思想实验，不是神学断言，勿误解为无神论宣言。"}, {"order": 2, "qtype": "blank", "stem": "格劳秀斯的代表作《______》系统阐述了战争的正当性、条约约束力与国际法基本原则。", "options": [], "answer": "", "accepted": ["战争与和平法", "De Jure Belli ac Pacis", "战争与和平法（De Jure Belli ac Pacis）"], "keywords": [], "explanation": "【答案】《战争与和平法》（De Jure Belli ac Pacis, 1625）。【解题思路】该书被视为近代国际法的奠基之作。【逐步演示】格劳秀斯在其中系统讨论正当战争的理由与战争行为的限制。【易错提醒】注意书名中的『战争』与『和平』二者并重，不要只答其中一半。"}, {"order": 3, "qtype": "judge", "stem": "霍布斯认为自然权利在逻辑上先于自然法，而洛克则由自然法推导出自然权利。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 明确指出，霍布斯与洛克在自然权利与自然法的优先性上方向相反。【逐步演示】霍布斯以自我保存的权利为出发点，自然法只是理性推导的戒条；洛克从自然法（理性）推导出生命、自由、财产等权利。【易错提醒】这一对比是理解近代自然法内部差异的关键考点。"}, {"order": 4, "qtype": "single", "stem": "Wacks 指出，霍布斯政治理论中统一解释『按约建立的主权』与『以取得方式建立的主权』的共同因素是：", "options": ["A 理性", "B 恐惧", "C 爱", "D 传统"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，霍布斯以恐惧为统一解释：人们因恐惧暴力死亡而让渡权利建立主权。【逐步演示】无论是按约建立还是以取得方式建立，其共同逻辑都是恐惧。【易错提醒】霍布斯虽讲理性推导，但其政治理论的动力是恐惧与自我保存。"}, {"order": 5, "qtype": "multi", "stem": "下列哪些属于格劳秀斯自然法理论的核心主张？", "options": ["A 自然法有效性不依赖神的意志", "B 国家间关系受自然法约束", "C 条约必须遵守", "D 法律只来自主权者命令"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】格劳秀斯主张自然法独立于神意、约束国家、条约必须遵守。【逐步演示】D 是奥斯丁的命令理论，与格劳秀斯立场相悖。【易错提醒】『条约必须遵守』（pacta sunt servanda）是国际法基本原则，属格劳秀斯传统的核心命题。"}, {"order": 6, "qtype": "single", "stem": "洛克在《政府论（下篇）》中主张，政府的正当性来自：", "options": ["A 神权", "B 被统治者对保护其自然权利的同意", "C 强者的命令", "D 传统习惯"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】洛克主张政府正当性来自被统治者同意，其目的是保护生命、自由、财产等自然权利。【逐步演示】当政府违背这一目的时，人民有权反抗。【易错提醒】洛克与霍布斯都讲社会契约，但洛克强调同意与限制政府权力，霍布斯强调主权与安全。"}, {"order": 7, "qtype": "judge", "stem": "Wacks 把霍布斯的自然权利观称为『自由市场版本的自然权利』，它以每个人保全自己生命的基本权利为前提。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是 Wacks 对霍布斯自然权利观的原话式概括。【逐步演示】霍布斯以自我保存为出发点，强调个人权利在逻辑上的优先性。【易错提醒】这一概括体现霍布斯与古典自然法（义务与共同善本位）的差别。"}, {"order": 8, "qtype": "essay", "stem": "试述格劳秀斯把自然法『世俗化』的意义，并说明其对近代国际法的贡献。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】从『世俗化』的含义入手，说明其哲学与国际法后果。【逐步演示】格劳秀斯把自然法基础从神意转向人的理性与社会性，使其可被不同信仰者共同接受；这一普遍标准为国际法提供了正当性依据。【易错提醒】不要把格劳秀斯说成完全否认神，他的命题是思想实验，强调自然法的独立有效性。", "keywords": [["自然法独立于神的意志", "理性与社会本性为基础"], ["普遍可论证", "跨信仰跨文化"], ["国际法以自然法为基础", "国家受共同法律约束"], ["为主权国家体系提供秩序", "战争与条约规则"]]}, {"order": 9, "qtype": "blank", "stem": "霍布斯的代表作《______》系统阐述了社会契约与主权理论。", "options": [], "answer": "", "accepted": ["利维坦", "Leviathan", "利维坦（Leviathan）"], "keywords": [], "explanation": "【答案】《利维坦》（Leviathan, 1651）。【解题思路】霍布斯在《利维坦》中系统阐述自然状态、社会契约与主权者理论。【逐步演示】它以恐惧与自我保存为动力，主张建立强有力的主权以避免暴力死亡。【易错提醒】霍布斯的《利维坦》与洛克的《政府论》风格与结论差别很大。"}, {"order": 10, "qtype": "single", "stem": "关于人道主义干预的争论中，援引普遍人权与『保护责任』以突破不干涉原则的论证，在思想脉络上最接近：", "options": ["A 格劳秀斯式自然法的普遍主义", "B 霍布斯的绝对主权", "C 奥斯丁的命令理论", "D 凯尔森的纯粹法学"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】普遍人权论证延续格劳秀斯式自然法的普遍主义，认为人的尊严先于国家主权。【逐步演示】『保护责任』框架在主权与人道关切之间折中，但仍以普遍价值为前提。【易错提醒】不要误选霍布斯，霍布斯强调主权者的绝对权威，与人道干预的普遍人权逻辑相反。"}, {"order": 11, "qtype": "judge", "stem": "洛克从自然法推导出自然权利，而霍布斯则把自然权利置于自然法之前。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是对 Wacks 所述两人方向相反的准确复述。【逐步演示】洛克由理性（自然法）得权利，霍布斯由自我保存的权利得自然法戒条。【易错提醒】第3题与本题表述方向一致，注意与题干问法对应。"}, {"order": 12, "qtype": "multi", "stem": "下列哪些属于近代社会契约理论的代表人物？", "options": ["A 霍布斯", "B 洛克", "C 卢梭", "D 阿奎那"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】霍布斯、洛克、卢梭是近代社会契约理论的代表。【逐步演示】Wacks 把格劳秀斯、霍布斯、洛克、卢梭、布莱克斯通并列为自然法世俗化（政治化）的代表。【易错提醒】阿奎那是中世纪神学家，其理论以上帝的永恒法为基础，不属近代社会契约论者。"}, {"order": 13, "qtype": "essay", "stem": "比较霍布斯与洛克社会契约理论的差异，并说明这种差异对现代宪政思想的影响。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】从自然状态、契约方式、政府目的三方面比较，再谈宪政影响。【逐步演示】霍布斯强调恐惧与安全，主张强大主权；洛克强调自然权利与政府信托，主张限制权力与反抗权。这一分歧构成近代宪政中权威与自由的两大主题。【易错提醒】不要把两人都说成主张『人民主权』，霍布斯的主权者并非人民整体。", "keywords": [["自然状态不同", "霍布斯战争状态洛克相对和平"], ["权力让渡不同", "霍布斯让渡给主权者洛克信托政府"], ["政府目的不同", "安全与保护权利"], ["宪政影响", "权威与自由的不同侧重"]]}]}, "S2M1K5": {"lesson": "S2M1K5", "questions": [{"order": 1, "qtype": "single", "stem": "富勒所说的法律『内在道德』（inner morality of law）主要指的是：", "options": ["A 法律内容必须符合实质正义", "B 法律体系应满足的八项程序性要求", "C 法官的个人道德修养", "D 法律必须源于神的意志"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】富勒的内在道德指法律作为规则体系应满足的八项程序性要求。【逐步演示】包括一般性、公开性、不溯及既往、清晰、不矛盾、可履行、稳定、官方行为与规则一致。【易错提醒】富勒采取程序性自然法进路，而非实体性自然法进路，勿误选 A。"}, {"order": 2, "qtype": "multi", "stem": "下列哪些属于富勒归纳的『法律的内在道德』之要求？", "options": ["A 一般性（存在规则）", "B 不溯及既往", "C 清晰明确", "D 官方行为与宣布的规则一致"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均属富勒的八项要求。【逐步演示】其余四项为公开性、不矛盾、可履行性、稳定性。【易错提醒】八项要求是常考点，建议整体记忆，避免遗漏『官方行为与规则一致』这一项。"}, {"order": 3, "qtype": "judge", "stem": "富勒把内在道德定性为『义务的道德』，即法律颁布者必须履行的最低义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】富勒把内在道德定性为『愿望的道德』（morality of aspiration），而非义务的道德。【逐步演示】它是法律体系力求达到的卓越标准，诉诸管理者的『受托感』。【易错提醒】愿望的道德与义务的道德的区分是富勒伦理学的重要概念，注意区分。"}, {"order": 4, "qtype": "blank", "stem": "富勒用来说明制定法律可能失败的八种方式的著名寓言，虚构了一位名叫______的君主。", "options": [], "answer": "", "accepted": ["Rex", "雷克斯", "Rex 君主"], "keywords": [], "explanation": "【答案】Rex（雷克斯）。【解题思路】富勒在《法律的道德性》中以虚构君主 Rex attempts 制定法律却屡屡失败的寓言，归纳八项要求。【逐步演示】每项要求都对应一种『制定法律失败』的方式。【易错提醒】Rex 是虚构人物，勿与真实历史君主混淆。"}, {"order": 5, "qtype": "single", "stem": "菲尼斯在《自然法与自然权利》中提出的『基本善』（basic goods）的数量是：", "options": ["A 五", "B 七", "C 九", "D 十二"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】菲尼斯提出七种基本的人类繁盛形式（基本善）。【逐步演示】九是实践合理性的基本要求的数量，勿与七混淆。【易错提醒】『七种基本善』与『九项实践合理性要求』两个数字常被交叉考查，务必分清。"}, {"order": 6, "qtype": "single", "stem": "下列哪一项不属于菲尼斯所列举的基本善？", "options": ["A 生命", "B 知识", "C 游戏", "D 权力"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】菲尼斯的基本善包括生命、知识、游戏、审美体验、社交（友谊）、实践合理性、宗教，不包括权力。【逐步演示】Wacks 转述了这七种基本善的清单。【易错提醒】记忆时注意『权力』不在其列，这是常见干扰项。"}, {"order": 7, "qtype": "judge", "stem": "菲尼斯认为，人的基本善是从人的欲望与经验事实中推导出来的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】菲尼斯明确拒绝从欲望推导应当，基本善是实践理性直接把握的自明前提。【逐步演示】Wacks 指出，菲尼斯认为欲望无法告诉我们应当欲望什么，他同意休谟对『是—应当』论证的批评。【易错提醒】把基本善说成『从经验推导』，恰好违背菲尼斯的方法论前提。"}, {"order": 8, "qtype": "essay", "stem": "比较富勒与菲尼斯在自然法复兴中的不同路径，并说明各自面临的主要批评。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别说明两人的路径、核心主张与批评。【逐步演示】富勒以程序条件界定法律，被批评只关乎效率且保证不了正义；菲尼斯以基本善重建实体内容，被批评理想化、保守与狭隘。【易错提醒】不要把两人混为同一路径，程序与实体的差别是关键。", "keywords": [["富勒程序性路径", "内在道德八项要求"], ["菲尼斯实体性路径", "基本善与实践合理性"], ["富勒批评", "只支持偶然联系不保证正义"], ["菲尼斯批评", "家庭理想化政治保守基本善狭隘"]]}, {"order": 9, "qtype": "blank", "stem": "富勒在洞穴探险者案之外，最系统的自然法著作是《______》。", "options": [], "answer": "", "accepted": ["法律的道德性", "The Morality of Law", "法律的道德性（The Morality of Law）"], "keywords": [], "explanation": "【答案】《法律的道德性》（The Morality of Law）。【解题思路】富勒在该书中系统阐述内在道德与八项要求。【逐步演示】该书第三、四章是其程序性自然法的核心文本。【易错提醒】洞穴探险者案是论文（1949年《哈佛法律评论》），与本书不同。"}, {"order": 10, "qtype": "single", "stem": "Wacks 指出，许多评论者认为富勒的论证实际上只支持法律与道德之间的：", "options": ["A 必然联系", "B 偶然联系", "C 完全分离", "D 因果关系"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 引述评论认为，富勒的论证大多只支持偶然联系（contingent connection）。【逐步演示】满足内在道德的法律体系仍可能是邪恶的，例如种族隔离法。【易错提醒】富勒本人主张必然联系，但评论者对其论证力度有保留，注意区分『主张』与『论证支持』。"}, {"order": 11, "qtype": "judge", "stem": "菲尼斯在其2011年后记中，把『恶法非法』一类命题称为『松散的』表述。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，菲尼斯在2011年后记中把这类命题描述为『松散的』（loose）。【逐步演示】这体现菲尼斯对古典自然法口号的审慎态度。【易错提醒】菲尼斯是自然法论者，但这并不意味着他接受所有自然法口号。"}, {"order": 12, "qtype": "multi", "stem": "根据 Wacks 的论述，对菲尼斯理论的批评包括：", "options": ["A 家庭模型过于理想化", "B 政治立场过于保守", "C 基本善过于狭隘", "D 完全否认共同善的重要性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 提到对菲尼斯的三项批评：家庭理想化、政治保守、基本善狭隘。【逐步演示】D 错误，菲尼斯恰恰强调共同的善的中心地位。【易错提醒】注意菲尼斯对第三项基本善的说法在后期有所让步，体现其理论的可修正性。"}, {"order": 13, "qtype": "essay", "stem": "试论富勒的『内在道德』是否配称为『道德』，并结合哈特的批评加以分析。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明富勒的理由，再陈述哈特的批评，最后作评价。【逐步演示】富勒以八项要求为法律的概念条件并称之为愿望的道德；哈特认为它们只关乎法律是否有效运作；种族隔离法表明满足要求并不保证正义。【易错提醒】评价要平衡，既要看到富勒对法律形式品质的洞见，也要承认批评的力度。", "keywords": [["富勒主张程序道德", "愿望的道德受托感"], ["哈特批评其关乎效率", "efficacy而非道德"], ["满足八项不保证正义", "种族隔离法反例"], ["评价", "程序合法性价值与限度"]]}]}, "S2M1K6": {"lesson": "S2M1K6", "questions": [{"order": 1, "qtype": "single", "stem": "强自然法、弱自然法与法律实证主义对『恶法』的典型立场依次是：", "options": ["A 恶法非法／恶法是法但不应服从／恶法是法且是否服从是另一问题", "B 恶法是法／恶法非法／恶法非法", "C 三者都主张恶法非法", "D 三者都主张恶法是法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】强自然法否认恶法的法资格；弱自然法承认其仍为法但丧失服从义务；实证主义主张识别法律与道德评价分开。【逐步演示】三者分歧集中在『不道德是否影响法资格』。【易错提醒】实证主义并不主张恶法在道德上可取，只主张概念上应分开判断。"}, {"order": 2, "qtype": "single", "stem": "哈特所说的『最低限度的自然法』（minimum content of natural law）指的是：", "options": ["A 法律必须满足的全部正义要求", "B 法律为维持自身必须满足的若干基于人性事实的条件", "C 自然法的全部内容", "D 法官必须遵守的道德准则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特承认基于人的脆弱性、大体平等、有限利他主义等事实，法律必须包含禁止暴力等最低条件。【逐步演示】这是法律存在的必要条件，而非法律概念的道德要素。【易错提醒】不要把『最低限度的自然法』等同于菲尼斯的实体自然法，二者层次不同。"}, {"order": 3, "qtype": "judge", "stem": "哈特主张，把极端邪恶的规则排除出『法律』概念，会使我们更清醒地批判它。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特主张相反：承认它是法律，然后说正因为它有效力，我们更有道德义务抵抗它。【逐步演示】哈特认为排除会遮蔽对其性质的认识。【易错提醒】这是哈特—富勒论战中哈特的核心反驳，注意题干把立场说反了。"}, {"order": 4, "qtype": "blank", "stem": "拉兹（Joseph Raz）主张，识别法律的存在与内容只需诉诸社会来源，无需道德论证，这一命题称为______命题。", "options": [], "answer": "", "accepted": ["渊源", "sources thesis", "渊源命题", "来源命题"], "keywords": [], "explanation": "【答案】渊源命题（Sources Thesis）。【解题思路】拉兹以渊源命题主张法律识别只依赖社会事实。【逐步演示】Wacks 引述拉兹：若法律的识别依赖某种道德信念，就违反了渊源命题。【易错提醒】渊源命题是排他实证主义的标志，与包容实证主义相区分。"}, {"order": 5, "qtype": "multi", "stem": "关于哈特—富勒论战，下列说法正确的有：", "options": ["A 论战发生于1950年代的《哈佛法律评论》", "B 分歧之一在于法律与道德是否有必然联系", "C 富勒拒绝承认纳粹法律为法律", "D 哈特认为富勒的八项要求关乎效率而非道德"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为论战的基本事实与分歧点。【逐步演示】Wacks 指出论战发表于1958年71卷《哈佛法律评论》，双方在必然联系、内在道德性质、恶法称谓上分歧。【易错提醒】Wacks 也指出双方在具体案件上并非总对立，例如都倾向于支持在洞穴探险者案中颁布溯及既往立法。"}, {"order": 6, "qtype": "single", "stem": "包容实证主义与排他实证主义的主要分歧在于：", "options": ["A 法律是否必须有制裁", "B 道德标准能否通过承认规则进入法律有效性条件", "C 法律是否来自主权者", "D 法律是否可以有原则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】包容实证主义允许承认规则纳入道德标准，排他实证主义（拉兹）坚决反对。【逐步演示】哈特后期倾向于包容立场，拉兹则维护渊源命题的纯粹性。【易错提醒】两派都属实证主义，都坚持分离命题的核心，分歧只在道德能否通过社会来源『进入』法律。"}, {"order": 7, "qtype": "judge", "stem": "拉德布鲁赫公式主张，只要法律不正义，法官就应拒绝适用。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】拉德布鲁赫公式设定了极高门槛：只有制定法与正义的矛盾达到『不可容忍』程度时，法律才丧失法的性质。【逐步演示】这一门槛旨在维护法律安定性，避免法官凭个人偏好否定法律。【易错提醒】『不可容忍』是公式的关键限定，不可省略。"}, {"order": 8, "qtype": "essay", "stem": "试述哈特—富勒论战的三个核心分歧，并说明这场论战为何至今仍是法理学的关键坐标。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先列出三个分歧，再说明论战的理论意义。【逐步演示】三个分歧为必然联系、内在道德性质、极端恶法的称谓；论战迫使所有法理学交代效力与正当性的关系。【易错提醒】不要说论战『分出胜负』，Wacks 明确指出它无定论（inconclusive）。", "keywords": [["必然联系之争", "法律与道德是否必然联系"], ["内在道德性质之争", "道德还是效率"], ["恶法称谓之争", "是否仍为法律"], ["坐标意义", "效力与正当性关系"]]}, {"order": 9, "qtype": "single", "stem": "德国战后『告密者案』中，法院判定依当时纳粹法律实施告发行为的被告有罪，其裁判思路最接近：", "options": ["A 严格的法律实证主义", "B 拉德布鲁赫式的自然法立场", "C 纯粹法学", "D 法律现实主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院以极端不正义的法律丧失效力为根据，体现拉德布鲁赫公式。【逐步演示】这是自然法式立场：违背文明社会基本准则的法律不能作为辩护理由。【易错提醒】哈特虽认同裁判结论在道德上可取，但会认为概念上更诚实的做法是承认那些法律形式有效再予以谴责。"}, {"order": 10, "qtype": "blank", "stem": "德沃金（Ronald Dworkin）以『______』（integrity）的解释性概念处理法律与道德的关系，主张原则也是法律的一部分。", "options": [], "answer": "", "accepted": ["整体性", "integrity", "法的整体性"], "keywords": [], "explanation": "【答案】整体性（integrity）。【解题思路】德沃金以整体性解释法律实践，主张在疑难案件中从既往实践中提炼最能证成它们的原则。【逐步演示】这既不同于强自然法的本体论主张，也不同于实证主义的分离命题。【易错提醒】德沃金的关键概念是『原则』与『整体性』，不要答成『承认规则』。"}, {"order": 11, "qtype": "judge", "stem": "南非种族隔离法的例子说明，满足富勒八项内在道德要求的法律体系，仍可能是极端不正义的。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是反驳富勒『内在道德足以区分法律与蛮力』的重要论据。【逐步演示】Wacks 提到富勒认为种族隔离法严重偏离内在道德，但批评者指出其在形式上可能符合公开性、一般性、不溯及既往等要求。【易错提醒】这一反例针对的是富勒论证的充分性，不否认程序合法性本身的价值。"}, {"order": 12, "qtype": "multi", "stem": "在分析自然法与实在法关系时，下列属于实证主义阵营的立场有：", "options": ["A 排他实证主义", "B 包容实证主义", "C 哈特的最低限度自然法", "D 富勒的内在道德"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】排他实证主义、包容实证主义、哈特的最低限度自然法均属实证主义阵营的不同形态。【逐步演示】D 富勒的内在道德属自然法立场。【易错提醒】哈特虽承认最低限度的自然法，仍属实证主义，这是常见的判断难点。"}, {"order": 13, "qtype": "essay", "stem": "结合告密者案，分析『承认恶法为法律再予以谴责』与『否认恶法效力』两种进路的优劣。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别说明两种进路的内容、优点与风险，再作比较。【逐步演示】哈特进路保持概念清晰，使抵抗更有针对性；拉德布鲁赫进路为拒绝适用提供直接依据，但存在标准模糊之虞。【易错提醒】不要简单判定某一方『正确』，应说明各自依赖的价值权衡。", "keywords": [["哈特进路", "承认法律效力保持概念清晰"], ["道德批判更清醒", "有效力更有义务抵抗"], ["拉德布鲁赫进路", "否认效力提供直接裁判依据"], ["风险对比", "确定性与道德清醒"]]}]}, "S2M1K7": {"lesson": "S2M1K7", "questions": [{"order": 1, "qtype": "single", "stem": "Wacks 转述的说法认为，自然法理论试图化解哪两者之间的张力？", "options": ["A 法律与道德", "B 是什么（is）与应当是什么（ought）", "C 个人与国家", "D 权利与义务"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 转述：对自然法的最佳描述是它提供了处理 is 与 ought 张力的东西。【逐步演示】自然法理论试图弥合事实描述与价值规范之间的鸿沟。【易错提醒】法律与道德的关系是自然法的主题之一，但此处 Wacks 的特定表述指向 is/ought 问题。"}, {"order": 2, "qtype": "multi", "stem": "下列哪些属于自然法理论通常被承认的优势？", "options": ["A 提供批判恶法与暴政的概念工具", "B 为人权与国际法提供正当性基础", "C 把法律理解为有目的的实践", "D 保证法律裁判的绝对确定性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】自然法的优势在批判、论证与整合三方面，但不保证绝对确定性。【逐步演示】D 错误，自然法因原则不确定而常被批评损害法律安定性。【易错提醒】『绝对确定性』这类表述通常不属于自然法的优势，反而是其弱点所在。"}, {"order": 3, "qtype": "single", "stem": "休谟（David Hume）对自然法理论提出的经典质疑是：", "options": ["A 法律不能来自主权者", "B 不能从『是』（事实）逻辑地推出『应当』（规范）", "C 法官应当自由裁量", "D 法律与道德应当完全分离"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】休谟质疑从描述性前提推出规范性结论的有效性。【逐步演示】菲尼斯承认这一质疑，拒绝从欲望或事实推导应当，转而诉诸实践理性。【易错提醒】不要把休谟的质疑等同于法律实证主义的分离命题，二者虽相关但不同。"}, {"order": 4, "qtype": "judge", "stem": "菲尼斯主张，基本善是从人的经验欲望中归纳出来的普遍事实。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】菲尼斯把基本善理解为实践理性直接把握的自明前提，不可还原。【逐步演示】Wacks 指出，他明确拒绝从欲望推导应当。【易错提醒】『自明』是菲尼斯基本善理论的关键，勿误述为经验归纳。"}, {"order": 5, "qtype": "blank", "stem": "自然法理论被批评的核心弱点之一，是其核心概念如『人性』『理性』『正义』往往具有______，难以提供确定标准。", "options": [], "answer": "", "accepted": ["含混", "模糊", "不确定性", "多义性"], "keywords": [], "explanation": "【答案】含混（或模糊、不确定性）。【解题思路】自然法核心概念的含混是其常被批评的弱点。【逐步演示】『人性』『理性』『共同善』缺乏统一定义，不同理论家可赋予不同内容。【易错提醒】这一批评并不否认自然法有价值，而是指出其标准确定性的困难。"}, {"order": 6, "qtype": "single", "stem": "Wacks 在评价菲尼斯时提到，批评者认为其基本善理论：", "options": ["A 过于理想化家庭、政治保守、基本善狭隘", "B 完全否认共同善", "C 主张法律与道德分离", "D 拒绝任何自然法传统"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 提到对菲尼斯的三项批评：家庭模型理想化、政治保守、基本善狭隘。【逐步演示】例如批评者追问共同的善是否应包含工作的权利。【易错提醒】菲尼斯后期对第三项基本善的说法有所让步，说明其理论具有可修正性。"}, {"order": 7, "qtype": "judge", "stem": "国际刑事法院（ICC）的《罗马规约》把种族灭绝、反人类罪等列为国际罪行，并主张国内法授权不能免责，这一制度带有明显的自然法色彩。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】ICC 的制度逻辑承认超越国家法律的底线保护，延续了自然法思路。【逐步演示】《罗马规约》以补充性原则处理国际正义与国家主权的关系。【易错提醒】ICC 的实际运作仍受国际政治影响，这正印证了对自然法『谁的正义』的质疑。"}, {"order": 8, "qtype": "essay", "stem": "试论自然法理论的主要优势与主要批评，并给出你自己的评价。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别列出优势与批评，再作平衡评价。【逐步演示】优势在批判、论证、整合；批评集中在含混、is/ought、多元与保守；评价时应承认其批判功能不可替代，同时正视确定性质疑。【易错提醒】评价要避免简单站队，应体现对双方论据的理解。", "keywords": [["优势", "批判恶法人权基础法律目的"], ["批评", "含混是应当问题多元保守"], ["是应当问题", "休谟质疑菲尼斯回应"], ["评价", "批判功能与确定性困境并存"]]}, {"order": 9, "qtype": "single", "stem": "Wacks 对自然法与实证主义之争的总体评价最接近：", "options": ["A 自然法已彻底战胜实证主义", "B 争论无定论，但确立了效力与正当性的坐标", "C 实证主义已完全终结自然法", "D 争论毫无意义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 认为这场争论重要却无定论（inconclusive），并确立了理论坐标。【逐步演示】它迫使所有法理学交代效力与正当性的关系。【易错提醒】不要把 Wacks 的立场误读为倾向某一方，他强调的是争论的开放性。"}, {"order": 10, "qtype": "multi", "stem": "根据本节内容，对自然法『保守』倾向的批评主要基于哪些理由？", "options": ["A 诉诸人的本性可能固化既有社会结构", "B 把某种生活形式包装成『自然』的要求", "C 菲尼斯被批评家庭模型理想化、政治保守", "D 自然法否认一切社会变革的可能"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】批评基于固化现状、包装特定价值、菲尼斯个人理论倾向三点。【逐步演示】D 错误，自然法并不否认变革，反而可为批判现状提供标准。【易错提醒】『保守』批评是倾向性判断，不宜绝对化为『否认变革』。"}, {"order": 11, "qtype": "judge", "stem": "强自然法允许法官以『不正义』为由否认法律效力，这一做法可能损害法律的安定性。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】强自然法强化道德批判，却可能因标准主观而损害法律安定性。【逐步演示】若每个人都可凭自己的正义观否认法律效力，法律作为公共指引的功能将受损。【易错提醒】这一批评正是软自然法与实证主义对强自然法的主要保留。"}, {"order": 12, "qtype": "blank", "stem": "自然法理论常被批评为难以从『是』推出『应当』，这一质疑在哲学史上被称为______问题。", "options": [], "answer": "", "accepted": ["是—应当", "是应当", "is-ought", "休谟问题", "事实与价值"], "keywords": [], "explanation": "【答案】是—应当问题（is—ought problem）。【解题思路】这是休谟提出的经典质疑。【逐步演示】菲尼斯承认其有效性，因而拒绝从欲望与事实推导应当。【易错提醒】答案可接受『休谟问题』这一表述，注意与『法律与道德分离命题』区分。"}, {"order": 13, "qtype": "essay", "stem": "结合国际刑事法院的实践，分析自然法优势与批评的『双面性』。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明 ICC 如何体现自然法优势，再说明它如何印证批评。【逐步演示】ICC 为追究大规模暴行提供法律基础；但其标准与运作受国家政治影响，批评者指责选择性起诉，呼应『谁的正义』之问。【易错提醒】不要简单肯定或否定 ICC，应展示自然法双重面相的具体运作。", "keywords": [["优势体现", "追究暴行保护尊严超越国内法"], ["批评体现", "标准由条約政治协商决定"], ["选择性起诉质疑", "普遍正义可能带偏见"], ["双面性结论", "批判力量与不确定性并存"]]}]}, "S2M2K1": {"lesson": "S2M2K1", "questions": [{"order": 1, "qtype": "single", "stem": "法律实证主义的核心主张是：", "options": ["A 法律必须符合正义才是法律", "B 法律的存在取决于社会来源而非道德价值", "C 法律就是法官的判决", "D 法律来自神的意志"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】实证主义主张法律的存在取决于制定来源等社会事实，而非内容道德。【逐步演示】分离命题与社会来源命题是其核心。【易错提醒】A 是自然法，C 是法律现实主义，D 是神学法律观。"}, {"order": 2, "qtype": "judge", "stem": "法律实证主义主张法律不需要道德，恶法就是好法。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这是对实证主义的漫画化。【逐步演示】实证主义只主张『是不是法律』与『是否道德正当』应分开判断，并不否认法律应当追求正义，也不赞许恶法。【易错提醒】哈特明确承认法律与道德在事实层面常相互渗透。"}, {"order": 3, "qtype": "blank", "stem": "边沁（Jeremy Bentham）以功利主义批判自然法与普通法的不确定性，Wacks 称他为『法理学的______』。", "options": [], "answer": "", "accepted": ["路德", "Luther", "马丁路德", "宗教改革家路德"], "keywords": [], "explanation": "【答案】路德（Luther）。【解题思路】Wacks 把边沁称为『法理学的路德』，喻指其像路德挑战教会权威一样挑战传统法律观。【逐步演示】边沁猛烈抨击自然法与布莱克斯通的法律观。【易错提醒】这个称号是 Wacks 章节标题中的比喻，不是边沁自封。"}, {"order": 4, "qtype": "single", "stem": "奥斯丁（John Austin）为古典实证主义奠定的核心理论是：", "options": ["A 法律规则理论", "B 命令理论", "C 纯粹法学", "D 渊源命题"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】奥斯丁提出法律是主权者的命令、以制裁为后盾的命令理论。【逐步演示】这构成古典实证主义的核心，后被哈特的规则理论取代。【易错提醒】A 属哈特，C 属凯尔森，D 属拉兹。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，现代法律实证主义的代表人物包括：", "options": ["A 哈特（Hart）", "B 凯尔森（Kelsen）", "C 拉兹（Raz）", "D 富勒（Fuller）"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特、凯尔森、拉兹是现代实证主义代表。【逐步演示】Wacks 把他们与科尔曼并列为现代实证主义代表。【易错提醒】富勒是自然法论者，以内在道德与哈特论战，不属实证主义。"}, {"order": 6, "qtype": "judge", "stem": "Wacks 指出，实证主义并非仅仅是法理学立场，其中心主张是唯一真正的知识是科学知识。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出实证主义有逻辑、科学、哲学、社会学、法律等多种形态。【逐步演示】其共同中心主张是唯科学知识为真知。【易错提醒】不要把法律实证主义与一般实证主义哲学完全等同，前者是后者在法律领域的应用。"}, {"order": 7, "qtype": "essay", "stem": "试述法律实证主义的三个核心承诺，并澄清『实证主义主张法律不需要道德』这一常见误解。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先列出三项承诺，再针对误解逐层澄清。【逐步演示】分离、来源、描述构成实证主义核心；但它不否认法律应追求正义，哈特也承认最低限度自然法。【易错提醒】澄清时不要走向另一极端，把实证主义说成自然法的同义词。", "keywords": [["分离命题", "法律与道德概念上分开"], ["社会来源命题", "有效性来自来源"], ["描述性立场", "描述法律实际是什么"], ["澄清误解", "不等于赞许恶法或无视道德"]]}, {"order": 8, "qtype": "single", "stem": "边沁批判普通法（common law）的核心论据，是其：", "options": ["A 过于强调逻辑", "B 不确定性（indeterminacy）", "C 来自神意", "D 缺乏制裁"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出边沁抨击普通法理论和实践脱节，规则表达不清、效力可疑。【逐步演示】边沁认为不确定性会传染到合法性，导致盲目服从。【易错提醒】边沁对普通法的批判不等于对一切法律的否定，他主张法典化改革。"}, {"order": 9, "qtype": "blank", "stem": "实证主义主张法律与道德在概念上可以分开，这一命题称为______命题。", "options": [], "answer": "", "accepted": ["分离", "Separation", "分离命题", "separating thesis"], "keywords": [], "explanation": "【答案】分离命题（Separation Thesis）。【解题思路】这是实证主义的核心命题之一。【逐步演示】它主张法律识别与道德评价应分别回答。【易错提醒】分离命题不等于『法律与道德事实上毫无关联』。"}, {"order": 10, "qtype": "judge", "stem": "英国没有成文宪法典，这一事实对『法律＝制定法＋制裁』的简单实证主义模型构成挑战。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】英国宪法由惯例、判例、制定法等构成，显示法律边界模糊。【逐步演示】哈特的承认规则与内部观点能较好解释这一现象。【易错提醒】不要因此断言惯例『就是法律』或『都不是法律』，应看到中间地带。"}, {"order": 11, "qtype": "single", "stem": "MacCormick 的名言『哈特是休谟式的，凯尔森是康德式的』主要说明：", "options": ["A 两人的哲学气质与方法路径不同", "B 哈特赞成自然法", "C 凯尔森反对一切法律理论", "D 两人结论完全相同"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】该名言概括哈特的经验主义与凯尔森的先验哲学气质差异。【逐步演示】哈特从社会实践出发，凯尔森从逻辑前提建构体系。【易错提醒】这是哲学气质的对比，不是法律结论的直接对立。"}, {"order": 12, "qtype": "multi", "stem": "下列哪些属于实证主义内部的分歧？", "options": ["A 排他实证主义与包容实证主义之争", "B 分离命题的强弱版本之争", "C 法律效力基础是主权还是实效之争", "D 法律是否必须正义之争（此属自然法）"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】实证主义内部在排他／包容、分离强弱、效力基础上均有分歧。【逐步演示】D 属实证主义与自然法之间的外部争论。【易错提醒】注意区分内部争论与外部争论。"}, {"order": 13, "qtype": "essay", "stem": "结合国际法与英国宪法的例子，分析法律实证主义模型面临的解释困难。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】以两个例子说明简单模型的不足与现代理论的修正。【逐步演示】国际法与英国宪法都挑战『制定法＋制裁』模型；哈特以承认规则、原始法律体系等概念扩展解释。【易错提醒】不要因这些困难就断言实证主义『失败』，应看到其自我修正能力。", "keywords": [["国际法无世界政府", "难以归入命令模型"], ["英国宪法无成文法典", "惯例与判例构成"], ["边界模糊", "法律与非法律中间地带"], ["理论修正", "承认规则扩展解释"]]}]}, "S2M2K2": {"lesson": "S2M2K2", "questions": [{"order": 1, "qtype": "single", "stem": "奥斯丁命令理论的三个核心要素是：", "options": ["A 规则、承认规则、裁判规则", "B 命令、主权者、制裁", "C 规范、基础规范、实效", "D 原则、政策、道德"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】奥斯丁把法律界定为主权者的命令、以制裁为后盾，三要素为命令、主权者、制裁。【逐步演示】A 是哈特的规则理论，C 是凯尔森的规范理论。【易错提醒】三要素是奥斯丁理论的常考点，勿与其他理论混淆。"}, {"order": 2, "qtype": "blank", "stem": "奥斯丁的代表作《______》系统阐述了命令理论与主权理论。", "options": [], "answer": "", "accepted": ["法理学范围之确定", "法理学范围之限定", "The Province of Jurisprudence Determined", "法理学范围"], "keywords": [], "explanation": "【答案】《法理学范围之确定》（The Province of Jurisprudence Determined, 1832）。【解题思路】这是奥斯丁的代表作。【逐步演示】其讲稿死后产生巨大影响，成为分析法学奠基文本。【易错提醒】注意书名的准确翻译，勿与边沁或哈特的著作混淆。"}, {"order": 3, "qtype": "judge", "stem": "奥斯丁界定主权者为：被社会大多数人习惯服从、而自身不服从任何确定权威的权威。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是奥斯丁对主权者的经典界定。【逐步演示】习惯性服从构成主权者的社会事实基础。【易错提醒】奥斯丁区分按约建立与以取得方式建立的主权，二者共同逻辑是恐惧。"}, {"order": 4, "qtype": "single", "stem": "哈特用『持枪者理论』（gunman theory）讽刺奥斯丁模型，意在说明：", "options": ["A 命令＋威胁的模型无法区分法律与匪徒威胁", "B 法律必须有制裁", "C 主权者应受法律限制", "D 法律来自道德"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】哈特指出，匪徒持枪命令交出钱包也是命令＋威胁，但我们不称之为法律。【逐步演示】这说明奥斯丁模型无法解释法律的规范性与义务体验。【易错提醒】obliged（被迫）与 obligation（义务）的区分是哈特批判的关键。"}, {"order": 5, "qtype": "judge", "stem": "奥斯丁认为，缺乏制裁的命令仍可构成严格意义上的法律。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】奥斯丁坚持没有制裁就没有严格意义上的法律。【逐步演示】制裁是其定义的必要要素。【易错提醒】哈特正是以授权性规则（无制裁）反驳奥斯丁这一主张。"}, {"order": 6, "qtype": "multi", "stem": "根据本节内容，奥斯丁命令理论面临的解释困难包括：", "options": ["A 无法解释授权性规则", "B 无法解释习惯法", "C 难以解释国际法", "D 无法解释法律与道德分离"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】命令理论难以解释授权性规则、习惯法与国际法。【逐步演示】D 错误，法律与道德分离恰是奥斯丁的核心主张而非困难。【易错提醒】注意题目问的是『解释困难』，不要选其理论主张。"}, {"order": 7, "qtype": "essay", "stem": "试述奥斯丁命令理论的内容与历史贡献，并说明哈特为何以『持枪者理论』批判它。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明理论内容与贡献，再说明哈特批判。【逐步演示】命令理论使法学经验化，但无法解释法律连续性与规范性；哈特以被迫与义务的区分批判之。【易错提醒】评价要平衡，既看到奥斯丁的历史贡献，也看到其模型局限。", "keywords": [["三要素", "命令主权者制裁"], ["贡献", "把法律从形而上学拉回经验事实"], ["持枪者批判", "威胁不能产生义务体验"], ["规则取代命令", "连续性与授权性规则"]]}, {"order": 8, "qtype": "single", "stem": "Wacks 指出，奥斯丁与边沁在实证主义谱系中的关系是：", "options": ["A 两者立场完全相反", "B 两者都站在实证主义一端，边沁更接近极端", "C 奥斯丁是自然法论者", "D 边沁主张法律来自神意"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出边沁『用事实的硬通货支付一切』，与奥斯丁同属实证主义一端，边沁更接近极端。【逐步演示】两者都反对自然法与普通法模糊性。【易错提醒】不要忽视两者的差别，边沁重改革与法典化，奥斯丁重概念定义。"}, {"order": 9, "qtype": "blank", "stem": "Wacks 以『______的经验主义者？』这一带问号的概括提示奥斯丁理论的洞见与局限。", "options": [], "answer": "", "accepted": ["天真", "naive", "朴素"], "keywords": [], "explanation": "【答案】天真（naive）。【解题思路】Wacks 章节标题为『John Austin: naive empiricist?』。【逐步演示】问号形式提示奥斯丁的经验主义虽有洞见但过度简化。【易错提醒】这一概括是 Wacks 的评价，不是奥斯丁自称。"}, {"order": 10, "qtype": "judge", "stem": "奥斯丁认为国际法是严格意义上的法律，因为它由各国同意产生。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】奥斯丁因国际法没有世界主权者，倾向于否认其严格意义上的法律地位。【逐步演示】这一结论被批评为过度狭窄。【易错提醒】现代实证主义通过扩展法律体系概念来处理国际法问题。"}, {"order": 11, "qtype": "single", "stem": "下列关于主权者权力的说法，符合奥斯丁观点的是：", "options": ["A 主权者受宪法明确限制", "B 主权者权力不受法律限制", "C 主权者必须遵守自然法", "D 主权者由人民选举产生"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】奥斯丁认为主权者自身不受法律约束，因为它是法律的来源。【逐步演示】Wacks 指出，授予主权者无限权力是其相互义务逻辑的结果。【易错提醒】这一立场与现代宪政限制政府权力的实践形成张力。"}, {"order": 12, "qtype": "multi", "stem": "下列哪些属于奥斯丁命令理论的特征？", "options": ["A 法律来自主权者意志", "B 以制裁为后盾", "C 主权者地位由习惯性服从构成", "D 法律与道德在概念上必须结合"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】命令、制裁、习惯性服从构成奥斯丁理论的核心。【逐步演示】D 错误，奥斯丁主张法律与道德分离。【易错提醒】不要把奥斯丁与自然法立场混淆。"}, {"order": 13, "qtype": "essay", "stem": "结合授权性规则（如规定如何订立遗嘱的规则），分析奥斯丁命令理论为何解释力不足。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】以授权性规则为切口，说明命令模型的局限。【逐步演示】这类规则赋予权力而非施加义务、无制裁，却无疑是法律；哈特以次级规则解释之。【易错提醒】不要因此完全否定奥斯丁，应看到其历史贡献与模型简化之间的张力。", "keywords": [["授权性规则不施加义务", "赋予权力与程序"], ["无制裁相伴", "不符合命令定义"], ["哈特次级规则解释", "规则理论补充"], ["模型简化现实", "定义过窄"]]}]}, "S2M2K3": {"lesson": "S2M2K3", "questions": [{"order": 1, "qtype": "single", "stem": "凯尔森『纯粹法学』的『纯粹』主要指：", "options": ["A 排除道德、社会学与政治等非法律因素", "B 只研究成文法", "C 主张法律必须纯粹道德", "D 拒绝一切理论体系"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】凯尔森试图建立排除道德、社会学、政治因素的纯粹法律科学。【逐步演示】它只研究法律规范本身，不研究道德价值或实际行为。【易错提醒】『纯粹』不是指内容高尚，而指方法上的净化。"}, {"order": 2, "qtype": "blank", "stem": "凯尔森把法律体系中作为效力最终根据的被假定的最高规范称为______（Grundnorm）。", "options": [], "answer": "", "accepted": ["基础规范", "基本规范", "Grundnorm", "基本规范（Grundnorm）"], "keywords": [], "explanation": "【答案】基础规范（Grundnorm / Basic Norm）。【解题思路】基础规范是凯尔森体系的基石。【逐步演示】它是法律效力的逻辑前提，不是由更高规范授权的实在法。【易错提醒】基础规范与哈特的承认规则不同：前者是逻辑假定，后者存在于官员实践中。"}, {"order": 3, "qtype": "judge", "stem": "凯尔森严格区分『是』（Sein）与『应当』（Sollen），并把法律归入『应当』的规范范畴。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是凯尔森理论的哲学基础。【逐步演示】法律属于规范（应当）的范畴，与描述事实的『是』严格区分。【易错提醒】这一区分是理解纯粹法学的前提。"}, {"order": 4, "qtype": "single", "stem": "MacCormick 的名言『哈特是休谟式的，凯尔森是康德式的』，主要强调凯尔森：", "options": ["A 受康德哲学影响，追求先验逻辑体系", "B 主张法律来自经验事实", "C 否认一切哲学", "D 是功利主义者"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】凯尔森是康德的追随者，追求逻辑严密的规范体系。【逐步演示】Wacks 引述该名言概括哈特经验主义与凯尔森先验哲学的气质差异。【易错提醒】这是哲学气质对比，不是法律结论的直接对立。"}, {"order": 5, "qtype": "multi", "stem": "根据 Wacks 的论述，凯尔森理论的核心要素包括：", "options": ["A 基础规范", "B 规范层级", "C 实效（efficacy）与效力的区分", "D 法律与道德必须结合"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】基础规范、规范层级、实效与效力区分是凯尔森理论核心。【逐步演示】Wacks 指出凯尔森把法的效力基础系于实效。【易错提醒】D 错误，凯尔森坚决主张法律与道德分离。"}, {"order": 6, "qtype": "judge", "stem": "凯尔森认为法律科学家应研究人们实际上如何行为，因此重视心理学与社会学方法。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】凯尔森明确指出法律科学家不关心人的实际行为，而关心规范。【逐步演示】Wacks 指出，凯尔森认为法律科学家关注的不是人类行为，而是规范所要求的应当行为。【易错提醒】这一立场使纯粹法学与法律现实主义、社会学法学形成对照。"}, {"order": 7, "qtype": "essay", "stem": "试述凯尔森基础规范理论的内容，并说明它面临的主要批评。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明基础规范的功能与性质，再列出批评。【逐步演示】基础规范是效力链条的终点、法律思维的逻辑假定；批评者追问一个被假定的规范如何能支撑整个体系的效力。【易错提醒】注意哈特虽承认其必要性，但认为凯尔森解释不足。", "keywords": [["效力终点", "基础规范是最终根据"], ["逻辑假定", "非实在法而是思维前提"], ["规范层级", "逐级授权"], ["批评", "假定的规范如何支撑效力"]]}, {"order": 8, "qtype": "single", "stem": "Wacks 指出，奥斯丁与凯尔森在法律效力基础上的差别是：", "options": ["A 奥斯丁系于主权，凯尔森系于实效", "B 奥斯丁系于实效，凯尔森系于主权", "C 两者都系于道德", "D 两者都系于法官判决"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出，奥斯丁把法的效力基础系于主权，凯尔森系于实效（efficacy）。【逐步演示】这构成两人虽同属实证主义但路径不同的关键。【易错提醒】不要混淆两人的效力基础。"}, {"order": 9, "qtype": "blank", "stem": "凯尔森的代表作《______》系统阐述了纯粹法学理论。", "options": [], "answer": "", "accepted": ["纯粹法学", "Pure Theory of Law", "法与国家的一般理论", "纯粹法理论"], "keywords": [], "explanation": "【答案】《纯粹法学》（Pure Theory of Law；另著《法与国家的一般理论》）。【解题思路】这是凯尔森的代表性著作。【逐步演示】Wacks 在其书第四章第三节讨论凯尔森的纯粹法学。【易错提醒】《实践理性与规范》是拉兹的著作，勿混淆。"}, {"order": 10, "qtype": "judge", "stem": "凯尔森主张法律规范的效力取决于它在道德上是否正当。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】凯尔森坚持法律与道德严格分离，效力不取决于道德。【逐步演示】规范效力来自上位规范授权，最终追溯至基础规范。【易错提醒】这是凯尔森与拉兹共同的实证主义立场。"}, {"order": 11, "qtype": "single", "stem": "凯尔森参与起草1920年奥地利宪法并任宪法法院法官，这一实践经历与其理论的哪一部分关联最直接？", "options": ["A 法律与道德分离", "B 规范层级与宪法审查", "C 法律现实主义", "D 功利主义改革"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】宪法审查制度以规范层级为理论基础：普通法律不得抵触宪法。【逐步演示】宪法法院审查普通法律是否符合宪法上位规范。【易错提醒】凯尔森的理论虽抽象，却与宪法审查实践密切相关。"}, {"order": 12, "qtype": "multi", "stem": "下列关于凯尔森『实效』与『效力』关系的说法，正确的有：", "options": ["A 实效属于『是』的范畴，效力属于『应当』的范畴", "B 基础规范的效力预设法律体系大体具有实效", "C 有效力必然有实效", "D 二者的区分体现凯尔森对经验事实的某种容纳"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】实效属事实范畴，效力属规范范畴；基础规范预设体系大体实效；这一区分显示凯尔森对经验因素的某种容纳。【逐步演示】C 错误，有效力的规范可能实效不佳。【易错提醒】这一区分是批评凯尔森『纯粹性』不彻底的重要切入点。"}, {"order": 13, "qtype": "essay", "stem": "结合宪法审查制度，分析凯尔森规范层级理论的解释力与局限。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明规范层级如何解释宪法审查，再指出其局限。【逐步演示】违宪法律因缺乏上位授权而无效；但规范层级无法回答『谁来解释宪法』这一现实政治问题。【易错提醒】不要简单否定凯尔森，应看到其提供的清晰概念工具。", "keywords": [["规范层级", "宪法高于普通法律"], ["违宪无效", "效力来自上位授权"], ["解释力", "清晰说明效力结构"], ["局限", "回避政治与解释问题"]]}]}, "S2M2K4": {"lesson": "S2M2K4", "questions": [{"order": 1, "qtype": "single", "stem": "哈特认为法律体系的核心是：", "options": ["A 主权者的命令", "B 初级规则与次级规则的结合", "C 基础规范", "D 法官的判决"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特的核心命题是法律的中心为初级规则与次级规则的结合。【逐步演示】初级规则直接规定行为，次级规则规定如何识别、改变与裁判初级规则。【易错提醒】A 是奥斯丁，C 是凯尔森，D 是现实主义。"}, {"order": 2, "qtype": "multi", "stem": "哈特区分的次级规则包括：", "options": ["A 承认规则", "B 改变规则", "C 裁判规则", "D 道德规则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特区分承认规则、改变规则与裁判规则三种次级规则。【逐步演示】它们分别解决法律体系的不确定性、静态性与无效性。【易错提醒】道德规则不是哈特次级规则的分类之一。"}, {"order": 3, "qtype": "blank", "stem": "哈特用以识别哪些规则属于有效法律的最终标准称为______规则。", "options": [], "answer": "", "accepted": ["承认", "承认规则", "Rule of Recognition", "认可规则"], "keywords": [], "explanation": "【答案】承认规则（Rule of Recognition）。【解题思路】承认规则是识别有效法律的最终标准。【逐步演示】它本身不被更高规则授权，而存在于官员的共同实践中。【易错提醒】承认规则不是写在某处的一条法律，而是一种社会实践。"}, {"order": 4, "qtype": "judge", "stem": "哈特认为，从外部观察法律规律性与从内部把规则当作行为理由接受，是两种不同观点。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特区分内部观点与外部观点。【逐步演示】内部观点把规则当作正当行为理由来接受与使用，外部观点只观察行为规律。【易错提醒】法律体系的存在需要官员从内部观点接受承认规则。"}, {"order": 5, "qtype": "single", "stem": "哈特用『被迫』（obliged）与『义务』（obligation）的区分，主要批判：", "options": ["A 自然法理论", "B 奥斯丁的命令理论", "C 凯尔森的纯粹法学", "D 批判法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特指出抢匪威胁只让人『被迫』，不能产生『义务』体验，以此批判命令理论。【逐步演示】这是其『持枪者理论』批判的核心。【易错提醒】obliged 与 obligation 的区分是哈特理论的经典考点。"}, {"order": 6, "qtype": "judge", "stem": "哈特认为，语言的『开放结构』意味着法官在疑难案件中可以不受任何法律约束地自由创造法律。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特承认开放结构与裁量，但强调裁量仍在法律框架内进行。【逐步演示】大多数案件有明确答案，裁量只存在于边缘地带。【易错提醒】哈特既反对机械形式主义，也反对规则怀疑论。"}, {"order": 7, "qtype": "essay", "stem": "试述哈特如何从奥斯丁的命令理论转向规则理论，并说明承认规则在其中的地位。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明批判理由，再说明规则理论与承认规则。【逐步演示】命令理论无法解释连续性、授权性规则与规范性；哈特以规则结合回应，承认规则是最终识别标准。【易错提醒】不要忽略哈特对凯尔森基础规范的批判与继承。", "keywords": [["批判命令理论", "持枪者与被迫义务"], ["规则结合", "初级与次级规则"], ["前法律社会三缺陷", "不确定静态无效"], ["承认规则地位", "最终标准存在实践中"]]}, {"order": 8, "qtype": "single", "stem": "Wacks 把哈特的理论概括为：", "options": ["A 中性理论", "B 纯粹法学", "C 自然法理论", "D 法律现实主义"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出，哈特在批判奥斯丁与凯尔森的基础上提出了一种中性（neutral）的法律理论。【逐步演示】它试图在强制论与纯粹规范论之间开辟道路。【易错提醒】『中性』指方法论立场，不意味着哈特无视道德问题。"}, {"order": 9, "qtype": "blank", "stem": "哈特承认，任何法律体系都必须满足某些基于人性事实的最低条件，他称之为『最低限度的______』。", "options": [], "answer": "", "accepted": ["自然法", "自然法内容", "minimum content of natural law"], "keywords": [], "explanation": "【答案】自然法（minimum content of natural law）。【解题思路】哈特在《法律的概念》第九章提出这一概念。【逐步演示】基于人的脆弱性、大体平等、有限利他主义等事实，法律必须包含禁止暴力等基本内容。【易错提醒】这不意味着哈特放弃分离命题，他把联系定位为法律存在的必要条件。"}, {"order": 10, "qtype": "judge", "stem": "哈特的《法律的概念》第三版包含德沃金撰写的后记（Postscript）。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】《法律的概念》第三版由 Leslie Green 作导论，含德沃金后记。【逐步演示】德沃金在后记中批评哈特忽视法律原则，哈特作出回应。【易错提醒】第二版由 Bulloch 与拉兹编辑，不要与第三版混淆。"}, {"order": 11, "qtype": "single", "stem": "根据《法律的概念》中的观点，加州限速55英里的规定之所以是有效法律，是因为：", "options": ["A 制定它的立法者恰好掌权", "B 加州人民接受并持续接受宪法确立的权威体系", "C 它道德上正当", "D 它有制裁"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 转述：对哈特而言，该规定为真是因为人们接受并持续接受宪法权威体系。【逐步演示】这与奥斯丁『立法者恰好掌权』的解释形成对照。【易错提醒】注意区分奥斯丁与哈特对同一问题的不同回答。"}, {"order": 12, "qtype": "multi", "stem": "下列哪些属于哈特对前法律社会缺陷的描述？", "options": ["A 不确定性", "B 静态性", "C 无效性", "D 道德性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特指出只有初级规则的社会存在不确定性、静态性与无效性三个缺陷。【逐步演示】次级规则分别对应解决这三个缺陷。【易错提醒】『道德性』不是哈特列举的缺陷。"}, {"order": 13, "qtype": "essay", "stem": "结合司法先例制度，分析哈特承认规则理论如何解释『哪些先例具有约束力』这一问题。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】以先例制度说明承认规则的具体运作。【逐步演示】识别先例约束力的标准存在于司法共同体实践中，体现内部观点；适用范围总有争议，体现开放结构。【易错提醒】不要把承认规则理解为一条写明的具体法条。", "keywords": [["先例约束力标准", "存在于司法实践"], ["承认规则具体化", "法院层级与判决理由"], ["开放结构", "适用总有争议"], ["内部观点", "法官接受共同标准"]]}]}, "S2M2K5": {"lesson": "S2M2K5", "questions": [{"order": 1, "qtype": "single", "stem": "『法律效力』与『道德正当性』的区别在于：", "options": ["A 前者问是不是有效法律，后者问是否值得道德服从", "B 两者是同一问题", "C 前者问法律是否正义，后者问法律是否生效", "D 前者由法官决定，后者由立法者决定"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】效力回答法资格问题，正当性回答道德评价问题。【逐步演示】分离命题主张二者应分开判断。【易错提醒】不要把效力等同于正义，也不要把正当性等同于生效。"}, {"order": 2, "qtype": "judge", "stem": "分离命题等于主张『法律与道德事实上毫无关联』。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】分离命题只主张概念上应分开判断。【逐步演示】哈特承认法律与道德在事实层面常相互渗透。【易错提醒】这是最常见的误解，务必区分概念命题与事实描述。"}, {"order": 3, "qtype": "blank", "stem": "德国战后提出的『______公式』主张，当制定法与正义的矛盾不可容忍时，法律丧失法的性质。", "options": [], "answer": "", "accepted": ["拉德布鲁赫", "Radbruch", "拉德布鲁赫公式"], "keywords": [], "explanation": "【答案】拉德布鲁赫公式（Radbruch Formula）。【解题思路】这是二战后德国处理纳粹法律问题的重要准则。【逐步演示】它在德国法院判决中被援引。【易错提醒】拉德布鲁赫本人出自实证主义传统，其公式是对法律确定性的例外性修正。"}, {"order": 4, "qtype": "single", "stem": "哈特—富勒论战的三个核心分歧不包括：", "options": ["A 法律与道德是否有必然联系", "B 内在道德是否真为道德", "C 极端恶法是否仍为法律", "D 法律是否必须有制裁"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】哈特—富勒论战的三个分歧为必然联系、内在道德性质、恶法称谓。【逐步演示】『法律是否必须有制裁』是奥斯丁与哈特之间的争论。【易错提醒】注意区分不同论战的主题。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，关于法律效力与道德正当性关系的立场包括：", "options": ["A 强自然法", "B 弱自然法", "C 排他实证主义", "D 包容实证主义"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四种立场构成分析该问题的完整谱系。【逐步演示】强自然法否认恶法法资格，弱自然法承认但拒服从，排他实证主义只认社会来源，包容实证主义允许道德通过承认规则进入。【易错提醒】不要把四种立场混为一谈。"}, {"order": 6, "qtype": "judge", "stem": "Wacks 指出，哈特与富勒的论战分出了明确胜负，确立了实证主义的胜利。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出论战无定论（inconclusive）。【逐步演示】它的重要性在于确立效力与正当性的坐标，而非分出胜负。【易错提醒】不要用『谁赢了』来理解这场论战。"}, {"order": 7, "qtype": "essay", "stem": "试述强自然法、弱自然法与法律实证主义对『恶法』的不同处理，并分析其各自的理论后果。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别说明三种立场及其后果。【逐步演示】强自然法强化批判但损害确定性，弱自然法温和但模糊，实证主义保持清晰但需另寻批判语汇。【易错提醒】评价要避免简单站队，应说明各自依赖的价值权衡。", "keywords": [["强自然法", "恶法非法丧失法资格"], ["弱自然法", "仍是法但无服从义务"], ["实证主义", "承认法是法再予谴责"], ["理论后果", "确定性与道德批判的权衡"]]}, {"order": 8, "qtype": "single", "stem": "德国战后『告密者案』中，法院以纳粹法律违背文明社会基本准则为由否定其效力，这最接近：", "options": ["A 严格实证主义", "B 拉德布鲁赫式的自然法立场", "C 法律现实主义", "D 纯粹法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院做法体现极端不正义法律丧失法性质的拉德布鲁赫公式。【逐步演示】这是自然法式立场。【易错提醒】哈特虽认同结论道德上可取，但认为概念上更诚实的做法是承认其形式效力。"}, {"order": 9, "qtype": "blank", "stem": "拉兹主张，识别法律的存在与内容只需诉诸社会来源，无需道德论证，这一命题称为______命题。", "options": [], "answer": "", "accepted": ["渊源", "来源", "sources thesis", "渊源命题"], "keywords": [], "explanation": "【答案】渊源命题（Sources Thesis）。【解题思路】这是拉兹排他实证主义的基石。【逐步演示】Wacks 引述拉兹：法律识别若依赖道德信念即违反渊源命题。【易错提醒】渊源命题是排他实证主义的标志。"}, {"order": 10, "qtype": "judge", "stem": "南非种族隔离法的例子说明，满足富勒八项内在道德要求的法律体系，仍可能极端不正义。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是反驳富勒『内在道德足以区分法律与蛮力』的重要论据。【逐步演示】Wacks 提到该反例。【易错提醒】这一批评针对富勒论证的充分性，不否认程序合法性本身价值。"}, {"order": 11, "qtype": "single", "stem": "德沃金处理法律与道德关系的核心概念是：", "options": ["A 承认规则", "B 整体性（integrity）", "C 基础规范", "D 实效"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金以整体性解释法律实践，主张原则也是法律。【逐步演示】Wacks 指出他把法律与道德关系理解为解释性关系。【易错提醒】承认规则属哈特，基础规范属凯尔森。"}, {"order": 12, "qtype": "multi", "stem": "下列关于哈特『最低限度的自然法』的说法，正确的有：", "options": ["A 基于人的脆弱性、大体平等、有限利他主义等事实", "B 是法律存在的必要条件", "C 意味着哈特完全放弃了分离命题", "D 要求法律包含禁止暴力等基本内容"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】最低限度自然法基于人性事实，是法律存在的必要条件，包含禁止暴力等内容。【逐步演示】C 错误，哈特并未因此放弃分离命题。【易错提醒】这一概念常被误读为哈特向自然法投降，应注意其精确定位。"}, {"order": 13, "qtype": "essay", "stem": "结合哈特—富勒论战，分析『承认恶法为法律反而有助于抵抗恶法』这一命题。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明哈特命题的含义，再说明富勒反驳，最后评价。【逐步演示】哈特认为承认法资格使批判更准确；富勒认为这模糊了法律与蛮力。【易错提醒】不要把它简化为『哈特支持恶法』，这是对分离命题的漫画化。", "keywords": [["哈特命题", "承认法是法"], ["道德清醒", "有效力更有义务抵抗"], ["富勒反驳", "恶法不配称法"], ["评价", "概念清晰与道德批判关系"]]}]}, "S2M2K6": {"lesson": "S2M2K6", "questions": [{"order": 1, "qtype": "single", "stem": "拉兹的渊源命题（Sources Thesis）主张：", "options": ["A 法律的识别需要道德论证", "B 法律的识别只依赖社会来源，无需道德论证", "C 法律就是主权者命令", "D 法律必须符合自然法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 引述拉兹：识别法律的存在与内容不需要也不求助于道德论证。【逐步演示】这使法律能被公共地、确定地识别。【易错提醒】渊源命题是排他实证主义的标志，与包容实证主义相对。"}, {"order": 2, "qtype": "judge", "stem": "拉兹主张道德标准可以通过承认规则进入法律有效性条件。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这正是哈特的包容实证主义立场，拉兹坚决反对。【逐步演示】拉兹认为若法律识别依赖道德信念就违反渊源命题。【易错提醒】排他／包容实证主义的分歧是常考点。"}, {"order": 3, "qtype": "blank", "stem": "拉兹区分了『承诺性陈述』与『______陈述』，使法学家能在不认同某法律体系道德价值的前提下描述其内容。", "options": [], "answer": "", "accepted": ["超脱性", "超脱", "detached", "超脱性陈述"], "keywords": [], "explanation": "【答案】超脱性陈述（detached statements）。【解题思路】这是拉兹对法理学方法论的重要贡献。【逐步演示】超脱性陈述描述法律主张而不接受其内容。【易错提醒】承诺性陈述则是从体系内部接受法律有效性。"}, {"order": 4, "qtype": "single", "stem": "为了规范地描述法律体系，拉兹借用了凯尔森的哪一概念？", "options": ["A 承认规则", "B 法律人的基础规范", "C 实效", "D 开放结构"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，拉兹认为法学家须非承诺地或虚幻地接受『法律人的基础规范』（凯尔森式基础规范）。【逐步演示】这使描述法律体系成为可能。【易错提醒】拉兹并非完全接受凯尔森理论，只是借用这一工具。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，拉兹理论的核心要素包括：", "options": ["A 渊源命题", "B 排他实证主义", "C 法律主张正当权威", "D 法律与道德在本体论上必然联系"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】渊源命题、排他实证主义、法律权威是拉兹理论核心。【逐步演示】D 是自然法立场，与拉兹相悖。【易错提醒】拉兹虽强调法律权威，但以社会来源与实践理性说明，不诉诸道德本体论。"}, {"order": 6, "qtype": "judge", "stem": "Wacks 指出，拉兹的渊源命题与菲尼斯的自然法理论虽结论相反，却共享对『法律何以能主张权威』的关切。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出两者虽结论相反却共享这一问题意识。【逐步演示】这提示实证主义与自然法之争的深层共同前提。【易错提醒】共享问题意识不等于立场接近，两者结论仍然对立。"}, {"order": 7, "qtype": "essay", "stem": "试述拉兹的渊源命题及其对排他实证主义的支持，并说明其与哈特包容实证主义的分歧。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明渊源命题内容，再说明它如何支持排他立场，最后比较哈特。【逐步演示】拉兹担心道德进入法律识别会损害确定性与描述性；哈特则允许承认规则纳入道德。【易错提醒】两派都属实证主义，勿把分歧夸大为实证主义与自然法之争。", "keywords": [["渊源命题", "识别只靠社会来源"], ["排他实证主义", "道德不能成为效力条件"], ["与哈特分歧", "承认规则能否纳入道德"], ["理由", "确定性与描述性"]]}, {"order": 8, "qtype": "single", "stem": "拉兹的代表作包括：", "options": ["A 《实践理性与规范》", "B 《法理学范围之确定》", "C 《纯粹法学》", "D 《法律的道德性》"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】《实践理性与规范》（Practical Reason and Norms）是拉兹的代表作。【逐步演示】B 是奥斯丁，C 是凯尔森，D 是富勒。【易错提醒】注意各学者代表作的对应关系。"}, {"order": 9, "qtype": "judge", "stem": "拉兹认为，法学家在描述一个法律体系时，必须承诺接受该体系的道德正当性。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】拉兹区分承诺性与超脱性陈述，法学家可用超脱性陈述描述而不接受。【逐步演示】这是价值中立方法论的基础。【易错提醒】若必须承诺接受，法理学就无法保持描述性。"}, {"order": 10, "qtype": "blank", "stem": "拉兹主张，法律对其受众提出______权威的主张，这种主张可由实践理性说明。", "options": [], "answer": "", "accepted": ["正当", "正当的", "legitimate", "合法"], "keywords": [], "explanation": "【答案】正当权威（legitimate authority）。【解题思路】拉兹强调法律的本质性主张是拥有正当权威。【逐步演示】实践理性可说明这种权威的可能基础。【易错提醒】这并不意味着所有法律事实上都正当，只是说法律『主张』正当。"}, {"order": 11, "qtype": "single", "stem": "关于宪法中『人的尊严』等道德性条款，拉兹式回应最可能是：", "options": ["A 法院在进行独立的道德论证", "B 条款的法律效力来自宪法制定这一社会事实", "C 这类条款不是法律", "D 法律与道德在此完全融合"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】拉兹会强调条款因被写入宪法而成为法律，效力来自社会来源。【逐步演示】法院适用它们是在执行社会来源确认的内容。【易错提醒】德沃金会给出相反回答：适用必然涉及道德解释。"}, {"order": 12, "qtype": "multi", "stem": "下列关于承诺性陈述与超脱性陈述的说法，正确的有：", "options": ["A 前者从法律体系内部接受其有效性", "B 后者描述法律主张而不接受", "C 二者区分使法理学可保持描述性", "D 二者实际上没有区别"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】承诺性陈述接受有效性，超脱性陈述只描述，二者区分支撑描述性法理学。【逐步演示】D 明显错误。【易错提醒】这一区分是拉兹方法论的核心，常与渊源命题结合考查。"}, {"order": 13, "qtype": "essay", "stem": "结合国际法中的『强行法』（ius cogens）概念，分析渊源命题的解释力与限度。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明强行法，再分别以拉兹与自然法立场解释，最后评价。【逐步演示】拉兹强调其被条约与习惯确认；自然法强调其反映普遍尊严。【易错提醒】不要简单判定某一方正确，应展示两种解释各自的理据。", "keywords": [["强行法概念", "禁止种族灭绝等强制性规范"], ["拉兹式解释", "效力来自条约习惯等社会来源"], ["自然法式解释", "效力来自人类尊严"], ["限度", "道德语汇的运作难纯以来源解释"]]}]}, "S2M2K7": {"lesson": "S2M2K7", "questions": [{"order": 1, "qtype": "single", "stem": "德沃金对法律实证主义的核心批评是：", "options": ["A 实证主义忽视法律中的原则与道德维度", "B 实证主义过度强调道德", "C 实证主义否认法律有制裁", "D 实证主义主张自然法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】德沃金批评实证主义把法律理解为规则体系，忽视具有道德维度的法律原则。【逐步演示】他主张原则以『分量』方式起作用，是法律的一部分。【易错提醒】不要误以为德沃金是自然法论者，他的路径是解释性的。"}, {"order": 2, "qtype": "judge", "stem": "德沃金认为法律规则与法律原则都以『全有或全无』的方式适用。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金区分规则（全有或全无）与原则（以分量起作用）。【逐步演示】原则的适用涉及权衡，而非机械适用。【易错提醒】这一区分是德沃金批评实证主义的基础。"}, {"order": 3, "qtype": "blank", "stem": "德沃金解释性法理学的核心德性称为『______』（integrity），要求把法律实践理解为连贯整体。", "options": [], "answer": "", "accepted": ["整体性", "integrity", "法的整体性"], "keywords": [], "explanation": "【答案】整体性（integrity）。【解题思路】德沃金以整体性作为解释性德性。【逐步演示】法官须像链式小说作者一样，在保持与既往实践连贯的前提下推进法律。【易错提醒】整体性不是简单的『一致性』，而是包含道德判断的解释德性。"}, {"order": 4, "qtype": "multi", "stem": "对法律实证主义的主要批评来自：", "options": ["A 自然法理论", "B 德沃金的解释性法理学", "C 法律现实主义", "D 批判法学"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四条批评路线分别是自然法、德沃金、现实主义与批判法学。【逐步演示】它们分别指向法律的道德本质、原则、经验运作与社会权力维度。【易错提醒】各批评侧重不同，不要混为一谈。"}, {"order": 5, "qtype": "single", "stem": "霍姆斯『法律的生命不在逻辑，而在经验』这一命题，代表的批评路线是：", "options": ["A 自然法", "B 法律现实主义", "C 纯粹法学", "D 排他实证主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该命题强调经验与现实对法律的决定作用，是美国法律现实主义的标志。【逐步演示】现实主义关注『行动中的法』。【易错提醒】霍姆斯（Oliver Wendell Holmes Jr.）勿与其他学者混淆。"}, {"order": 6, "qtype": "judge", "stem": "自然法论者批评实证主义对价值中立法律描述的追求，忽略了法律的本质即其道德性。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 转述了自然法论者的这一批评。【逐步演示】自然法论者认为制定法律的行为能够而且应当受道德原则指导。【易错提醒】这一批评与实践中的反例（如种族隔离法满足程序要求）需要结合理解。"}, {"order": 7, "qtype": "essay", "stem": "试述德沃金与哈特在『法律是否包含原则』问题上的争论，并说明哈特的回应。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明德沃金批评，再说明哈特回应，最后点明争论实质。【逐步演示】德沃金主张原则的法律效力源于道德解释，哈特坚持须经社会来源识别。【易错提醒】哈特在后期著作中已承认法律中包含原则，不要说他完全否认。", "keywords": [["德沃金批评", "法律包含道德原则"], ["原则特性", "分量而非全有全无"], ["哈特回应", "承认规则可容纳原则"], ["争论实质", "社会来源与道德解释"]]}, {"order": 8, "qtype": "single", "stem": "纽约上诉法院1889年『里格斯诉帕尔默案』中，法院否定杀人者依遗嘱继承的权利，主要依据是：", "options": ["A 遗嘱形式要件不符", "B 任何人不得从自身错误中获利的法律原则", "C 法律明文禁止杀人者继承", "D 法官个人道德偏好"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院以『不得从自身错误中获利』原则优先于遗嘱继承规则。【逐步演示】该案常用于说明法律原则在疑难案件中的作用。【易错提醒】该案说明原则与规则冲突时的处理，不等于法官任意创造法律。"}, {"order": 9, "qtype": "judge", "stem": "批判法学认为法律是连贯中立、与社会权力无关的规则体系。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，批判法律理论的中心主题是怀疑统一法律秩序的可能性。【逐步演示】CLS 把法律描绘为不确定、与社会政治经济权力相连的。【易错提醒】这与实证主义对法律确定性的强调形成对照。"}, {"order": 10, "qtype": "blank", "stem": "法律现实主义怀疑规则能决定案件结果，这一立场称为______怀疑论。", "options": [], "answer": "", "accepted": ["规则", "rule", "规则怀疑论"], "keywords": [], "explanation": "【答案】规则怀疑论（rule skepticism）。【解题思路】现实主义怀疑规则对裁判的决定作用。【逐步演示】它与事实怀疑论共同构成现实主义的两面。【易错提醒】规则怀疑论不等于否认一切规则，而是怀疑规则的决定力。"}, {"order": 11, "qtype": "single", "stem": "Wacks 指出，现实主义常被视为实证主义的一支，这被称为现代法理学的：", "options": ["A 一大悖论", "B 一大胜利", "C 一大错误", "D 一大终结"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 称美国法律现实主义为『现代法理学的一大悖论』。【逐步演示】它既拒绝自然法形而上学（近于实证主义），又强调经验与社会因素（异于实证主义）。【易错提醒】这一悖论提示现实主义对实证主义的批评主要是方法论层面的。"}, {"order": 12, "qtype": "multi", "stem": "德沃金『权利是王牌』（rights as trumps）命题的含义包括：", "options": ["A 个人权利优先于集体功利目标", "B 权利是法律实践中的王牌", "C 权利可以被功利轻易压倒", "D 权利 thesis 是其理论的重要部分"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】权利王牌命题强调个人权利优先于功利，Wacks 书中专设『the rights thesis』一节。【逐步演示】C 错误，与王牌命题相反。【易错提醒】这一命题体现德沃金对功利主义的批评。"}, {"order": 13, "qtype": "essay", "stem": "比较自然法批评与法律现实主义批评对实证主义的差异，并分析二者能否结盟。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别说明两种批评，再比较其异同。【逐步演示】自然法从道德价值切入，现实主义从经验运作切入；两者都反形式主义，但理论基础不同，结盟有限。【易错提醒】不要简单认为两者立场一致，它们对法律性质的根本看法不同。", "keywords": [["自然法批评", "法律忽视道德本质"], ["现实主义批评", "过度形式化脱离实际"], ["差异", "价值批判与经验批判"], ["能否结盟", "共同反对形式主义但基础不同"]]}]}, "S2M3K1": {"lesson": "S2M3K1", "questions": [{"order": 1, "qtype": "single", "stem": "霍姆斯『法律的生命不在逻辑，而在经验』这一命题最直接针对的是：", "options": ["A 自然法理论", "B 法律形式主义", "C 纯粹法学", "D 包容实证主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该命题强调经验对抗逻辑决定论，直接针对相信规则逻辑可决定裁判的形式主义。【逐步演示】现实主义以此反对『自动售货机』式司法观。【易错提醒】霍姆斯反的是形式主义，不是一般意义的法律理论。"}, {"order": 2, "qtype": "blank", "stem": "现实主义主张研究『______中的法』，而非书本上的法。", "options": [], "answer": "", "accepted": ["行动", "行动中的法", "law in action", "实际运作"], "keywords": [], "explanation": "【答案】行动（law in action）。【解题思路】现实主义把注意力从书本上的法转向行动中的法。【逐步演示】这体现其经验主义取向。【易错提醒】不要答成『书本』或『制定法』，那恰是现实主义批评的对象。"}, {"order": 3, "qtype": "multi", "stem": "美国法律现实主义的代表人物包括：", "options": ["A 霍姆斯", "B 卢埃林", "C 弗兰克", "D 罗斯"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 把霍姆斯、卢埃林、弗兰克列为美国现实主义三大家。【逐步演示】D 罗斯属斯堪的纳维亚现实主义。【易错提醒】注意区分美国与北欧现实主义代表。"}, {"order": 4, "qtype": "single", "stem": "弗兰克（Jerome Frank）的法律思想以下列哪一项为核心？", "options": ["A 规则怀疑论", "B 事实怀疑论", "C 基础规范", "D 基本善"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】弗兰克以事实怀疑论著称，怀疑审判中事实认定的可靠性。【逐步演示】Wacks 指出，弗兰克若被理解为极端特殊主义者，其立场与早期罗斯相邻。【易错提醒】规则怀疑论更常与卢埃林关联。"}, {"order": 5, "qtype": "judge", "stem": "Wacks 把美国法律现实主义称为现代法理学的『一大悖论』，因为它既反形而上学而近于实证主义，又怀疑规则决定力而挑战实证主义。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 以『一大悖论』概括现实主义的复杂定位。【逐步演示】它分享了实证主义的经验主义与反形而上学，却怀疑规则对裁判的决定作用。【易错提醒】这一悖论提示现实主义与实证主义关系复杂，不能简单归类。"}, {"order": 6, "qtype": "judge", "stem": "美国现实主义与斯堪的纳维亚现实主义在哲学气质与研究方法上基本相同。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出两者相似往往只是表面的。【逐步演示】美国人处于英国经验主义传统、更重经验；斯堪的纳维亚人更具哲学与形而上学批判色彩、范围更广。【易错提醒】不要因同称『现实主义』就忽视其差异。"}, {"order": 7, "qtype": "essay", "stem": "试述美国法律现实主义的规则怀疑论，并说明哈特如何用『开放结构』回应。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明规则怀疑论与现实主义论据，再说明哈特回应。【逐步演示】现实主义认为规则不能自动决定结果；哈特承认开放结构，但坚持大多数案件有明确答案，裁量仍在框架内。【易错提醒】哈特并未完全否认现实主义洞见，而是给出中间道路。", "keywords": [["规则怀疑论", "怀疑规则决定案件"], ["现实主义论据", "经验与后果影响裁判"], ["哈特回应", "开放结构有限裁量"], ["中间道路", "反对形式主义与怀疑论"]]}, {"order": 8, "qtype": "single", "stem": "卢埃林（Karl Llewellyn）关于法律的名言最接近：", "options": ["A 法律是主权者的命令", "B 法律就是官员处理纠纷所做的事", "C 法律是神的理性", "D 法律是基础规范体系"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】卢埃林把法律理解为官员实际处理纠纷的行为。【逐步演示】这体现现实主义的经验取向。【易错提醒】A 是奥斯丁，C 是自然法，D 是凯尔森。"}, {"order": 9, "qtype": "blank", "stem": "现实主义以美国最高法院1930年代的『______』判例转型为现实素材，说明社会语境对裁判的影响。", "options": [], "answer": "", "accepted": ["新政", "New Deal", "新政时期"], "keywords": [], "explanation": "【答案】新政（New Deal）。【解题思路】新政时期最高法院从推翻社会立法转向认可广泛规制权。【逐步演示】现实主义以此说明法律判断与社会语境的关系。【易错提醒】不要答成『进步时代』，那更早且侧重不同议题。"}, {"order": 10, "qtype": "judge", "stem": "Wacks 指出，对现实主义的批评之一是它低估了法律规则的约束功能，可能流于保守。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 提到对现实主义者保守主义的批评。【逐步演示】这一批评在 CLS 与女性主义、后现代理论中被重新提起。【易错提醒】批评的是现实主义低估了法律规则的约束功能，可能流于对现状的默认。"}, {"order": 11, "qtype": "single", "stem": "现实主义对批判法学（CLS）的影响主要表现为：", "options": ["A CLS 完全否认现实主义", "B CLS 继承并激进了现实主义对法律中立与确定性的怀疑", "C CLS 是现实主义的反对者", "D CLS 与现实主义毫无关联"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，CLS 在许多方面类似于美国法律现实主义，并继承其怀疑精神。【逐步演示】差别在于 CLS 更强调政治与权力结构。【易错提醒】现实主义是 CLS、女性主义与后现代理论的先驱。"}, {"order": 12, "qtype": "multi", "stem": "根据本节内容，现实主义求助于下列哪些科学探究路径？", "options": ["A 社会学", "B 心理学", "C 逻辑涵摄（唯一路径）", "D 经验观察"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】Wacks 指出现实主义者拒绝逻辑的单一路径，寻求社会学、心理学等经验科学。【逐步演示】C 错误，逻辑涵摄正是现实主义批评的对象。【易错提醒】注意『拒绝单一路径』不等于『拒绝逻辑』。"}, {"order": 13, "qtype": "essay", "stem": "结合洞穴探险者案中 Handy 法官与 Foster 法官的分歧，分析法官角色对法律适用的影响。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明两位法官的立场，再分析法官角色的影响与边界。【逐步演示】Wacks 指出 Handy 是极端现实主义者、Foster 采取目的论进路；这说明司法理念塑造裁判，但判断仍受制度约束。【易错提醒】不要由此得出『裁判完全任意』的结论。", "keywords": [["Handy法官", "极端现实主义者"], ["Foster法官", "目的论解释"], ["分歧实质", "司法理念影响裁判"], ["制度约束", "判断非任意"]]}]}, "S2M3K2": {"lesson": "S2M3K2", "questions": [{"order": 1, "qtype": "single", "stem": "斯堪的纳维亚法律现实主义的代表人物是：", "options": ["A 霍姆斯、卢埃林、弗兰克", "B 罗斯、奥利弗克罗纳、朗兹特", "C 哈特、拉兹、德沃金", "D 富勒、菲尼斯、阿奎那"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出罗斯、奥利弗克罗纳、朗兹特是斯堪的纳维亚现实主义代表。【逐步演示】A 是美国现实主义，C 是实证主义与德沃金，D 是自然法。【易错提醒】注意区分美国与北欧现实主义代表。"}, {"order": 2, "qtype": "blank", "stem": "奥利弗克罗纳的代表作《______》对法律形而上学发起了激进攻击。", "options": [], "answer": "", "accepted": ["作为事实的法律", "Law as Fact", "法律作为事实"], "keywords": [], "explanation": "【答案】《作为事实的法律》（Law as Fact, 1939）。【解题思路】这是奥利弗克罗纳的代表作。【逐步演示】他在书中提出『独立命令』概念并批判法律语言的魔幻色彩。【易错提醒】《法律与正义》是罗斯的著作，勿混淆。"}, {"order": 3, "qtype": "judge", "stem": "奥利弗克罗纳认为法律规则是『独立命令』，其约束力可由心理与社会事实说明。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是奥利弗克罗纳的核心主张。【逐步演示】他追问法律效力来源时，认为诉诸抽象规范是无意义的形而上学回答。【易错提醒】独立命令概念是其反形而上学立场的关键。"}, {"order": 4, "qtype": "single", "stem": "罗斯在《法律与正义》中用以说明规则与社会实践关系的著名比喻是：", "options": ["A 持枪者比喻", "B 象棋类比", "C 机器比喻", "D 有机体比喻"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】罗斯以一局象棋与旁观者的例子，说明规则存在于参与者的态度与实践中。【逐步演示】Wacks 指出，罗斯用这一类比说明法律既非纯物理事实也非超验实体。【易错提醒】持枪者比喻是哈特讽刺奥斯丁的，勿混淆。"}, {"order": 5, "qtype": "multi", "stem": "根据 Wacks 的论述，斯堪的纳维亚现实主义与美国现实主义的差别包括：", "options": ["A 前者更具哲学批判色彩，后者更重经验", "B 前者范围更广涵盖整个法律体系，后者更集中司法过程", "C 前者与实证主义更亲和，后者呈悖论关系", "D 两者完全相同"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 从哲学气质、研究范围、与实证主义关系三方面区分两者。【逐步演示】D 明显错误。【易错提醒】Wacks 甚至提示两者相似往往只是表面的。"}, {"order": 6, "qtype": "judge", "stem": "奥利弗克罗纳颠倒了通常『法律反映道德价值』的观点，主张法律影响道德。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，奥利弗克罗纳颠倒了通常法律反映道德价值的观点。【逐步演示】他主张法律影响道德而非相反。【易错提醒】Wacks 指出这一主张受到批评，其心理学预设也被质疑。"}, {"order": 7, "qtype": "essay", "stem": "试述奥利弗克罗纳对法律形而上学的批判，并说明其『独立命令』与『魔幻意义』概念。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明其反形而上学立场，再解释两个核心概念。【逐步演示】奥利弗克罗纳认为法律规则仿佛通过魔咒就能给出答案，法律概念被赋魔幻意义；他主张以心理与社会事实说明约束力。【易错提醒】注意他的心理学路径受到批评。", "keywords": [["反形而上学", "追问效力来源无意义"], ["独立命令", "命令性命题"], ["魔幻意义", "法律语言被赋魔幻色彩"], ["心理与社会事实", "解释约束力"]]}, {"order": 8, "qtype": "single", "stem": "朗兹特（Lundstedt）法律理论的核心概念是：", "options": ["A 基础规范", "B 社会福利", "C 承认规则", "D 基本善"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】朗兹特以『社会福利』为法律目的与评价标准。【逐步演示】Wacks 指出，这一概念因模糊而受批评，其观点甚至常成为笑柄。【易错提醒】A 属凯尔森，C 属哈特，D 属菲尼斯。"}, {"order": 9, "qtype": "judge", "stem": "罗斯在《法律与正义》中完全接受了奥利弗克罗纳的『心理现实主义』。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，罗斯在《法律与正义》中拒绝了奥利弗克罗纳的心理现实主义。【逐步演示】两人共享反形而上学立场，但具体路径不同。【易错提醒】不要因同属北欧现实主义就认为两人立场完全一致。"}, {"order": 10, "qtype": "blank", "stem": "Wacks 指出，斯堪的纳维亚现实主义者与法律实证主义者的亲和性在这一流派中达到______（apogee）。", "options": [], "answer": "", "accepted": ["顶点", "apogee", "顶峰", "极致"], "keywords": [], "explanation": "【答案】顶点（apogee）。【解题思路】Wacks 指出两者亲和性在斯堪的纳维亚现实主义中达到顶点。【逐步演示】这与美国现实主义和实证主义的『悖论』关系形成对照。【易错提醒】亲和不等于同一，北欧现实主义仍区别于实证主义。"}, {"order": 11, "qtype": "single", "stem": "Wacks 把斯堪的纳维亚现实主义者的核心哲学立场概括为：", "options": ["A 形而上学怀疑论", "B 自然法实在论", "C 道德实在论", "D 法律形式主义"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出北欧现实主义者是『metaphysics-sceptics』（形而上学怀疑论者）。【逐步演示】他们拒斥不可经验验证的法律实体与抽象规范概念。【易错提醒】这与他们的反自然法立场直接相关。"}, {"order": 12, "qtype": "multi", "stem": "下列关于罗斯象棋类比的说法，正确的有：", "options": ["A 规则不能仅从棋子的物理移动中读出", "B 规则存在于参与者对它的态度中", "C 法律既非纯物理事实也非超验实体", "D 该类比说明法律与游戏规则完全相同"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】ABC 准确概括象棋类比的含义。【逐步演示】D 错误，类比有局限——法律与国家强制、制度权威相连，比游戏规则复杂。【易错提醒】类比用于说明规范的『存在方式』，不意味着法律等同游戏。"}, {"order": 13, "qtype": "essay", "stem": "比较罗斯与奥利弗克罗纳的法律思想，分析北欧现实主义内部的差异。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明共同立场，再比较二人差异。【逐步演示】二人都反形而上学，但奥利弗克罗纳更重心理还原与魔幻意义批判，罗斯更重规则作为社会事实的制度性，并明确拒绝心理现实主义。【易错提醒】不要把两人视为完全同一立场。", "keywords": [["共同立场", "反形而上学拒斥自然法"], ["奥利弗克罗纳", "独立命令与心理条件作用"], ["罗斯", "象棋类比拒绝心理现实主义"], ["差异意义", "经验还原与社会实践的不同侧重"]]}]}, "S2M3K3": {"lesson": "S2M3K3", "questions": [{"order": 1, "qtype": "single", "stem": "哈特用『开放结构』（open texture）概念主要说明：", "options": ["A 法律规则在边缘地带存在不确定性", "B 法律完全由法官创造", "C 法律不需要语言表述", "D 法律与道德必然联系"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】哈特以开放结构说明语言在边缘地带的不确定性。【逐步演示】大多数案件有明确答案，只在边缘地带存在裁量。【易错提醒】哈特并未因此主张法官可任意创造法律。"}, {"order": 2, "qtype": "judge", "stem": "弗兰克的事实怀疑论认为，即使规则明确，案件结果也可能因事实认定的不确定性而不同。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】事实怀疑论怀疑审判中事实认定的可靠性。【逐步演示】证人记忆、证据与心理因素都会影响事实认定，进而影响判决。【易错提醒】这一怀疑针对事实认定，而非规则适用本身。"}, {"order": 3, "qtype": "blank", "stem": "德沃金要求法官把法律实践理解为连贯整体，这一解释德性称为______（integrity）。", "options": [], "answer": "", "accepted": ["整体性", "integrity", "法的整体性"], "keywords": [], "explanation": "【答案】整体性（integrity）。【解题思路】德沃金以整体性作为解释性德性。【逐步演示】法官须像链式小说作者一样，在保持连贯的前提下推进法律。【易错提醒】整体性不只是形式一致，还包含道德判断。"}, {"order": 4, "qtype": "single", "stem": "在洞穴探险者案中，Wacks 指出 Handy 法官的立场是：", "options": ["A 极端的现实主义者", "B 严格的形式主义者", "C 自然法论者", "D 纯粹法学者"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出 Handy 法官是极端的现实主义者（arch-realist）。【逐步演示】Foster 法官则采取目的论的解释进路。【易错提醒】该案虽是富勒虚构的思想实验，却成为法理学经典文本。"}, {"order": 5, "qtype": "multi", "stem": "影响法官法律适用的因素包括：", "options": ["A 规则语言的开放结构", "B 事实认定的不确定性", "C 法官的个人经验与政策判断", "D 制度约束与职业传统"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项都是影响法官裁判的因素。【逐步演示】前三项为判断空间的来源，第四项为约束判断的制度因素。【易错提醒】不要只看到法官个人因素而忽略制度约束。"}, {"order": 6, "qtype": "judge", "stem": "德沃金认为法官在疑难案件中的裁量是任意的，不受法律原则约束。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金主张法官即使在疑难案件中也受原则约束，并可通过整体性解释找到正确答案。【逐步演示】他批评把裁量理解为任意选择的观点。【易错提醒】德沃金为司法判断设定了规范性框架。"}, {"order": 7, "qtype": "essay", "stem": "试述现实主义、哈特与德沃金对法官角色的不同理解，并分析其分歧的实质。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】分别说明三种立场，再分析分歧。【逐步演示】现实主义强调判断的普遍存在，哈特限定其范围，德沃金以原则消解任意性。【易错提醒】三者并非完全对立，都承认规则不能机械决定所有案件。", "keywords": [["现实主义", "法官判断与经验决定裁判"], ["哈特", "开放结构与有限裁量"], ["德沃金", "整体性原则约束判断"], ["分歧实质", "判断空间大小与客观性"]]}, {"order": 8, "qtype": "single", "stem": "英国『女王诉达德利与斯蒂芬斯案』（R v Dudley & Stephens, 1884）的核心争议是：", "options": ["A 合同是否成立", "B 必要能否作为谋杀罪的抗辩", "C 遗嘱是否有效", "D 宪法修正案的效力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该案涉及漂流船员为求生杀死同伴，争议在于必要能否作为谋杀罪抗辩。【逐步演示】法院拒绝必要抗辩，判定谋杀罪成立但量刑宽大。【易错提醒】该案 Wacks 有提及，并与洞穴探险者案相关联。"}, {"order": 9, "qtype": "judge", "stem": "现实主义认为法官的个人背景与政策偏好影响判决，这一影响应被承认为法律运作的真实组成部分。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】现实主义把法官判断视为法律运作的真实组成部分。【逐步演示】Wacks 指出现实主义关注法官实际做的事。【易错提醒】批评者认为这损害法治平等性，应通过制度提升透明度。"}, {"order": 10, "qtype": "blank", "stem": "法官在规则不确定地带作出选择的余地，称为司法______。", "options": [], "answer": "", "accepted": ["裁量", "自由裁量", "discretion", "司法裁量"], "keywords": [], "explanation": "【答案】裁量（discretion）。【解题思路】司法裁量指法官在规则不确定地带的判断空间。【逐步演示】现实主义扩大其范围，哈特限定其范围，德沃金试图以原则消解它。【易错提醒】裁量不等于任意，需区分不同理论对裁量的理解。"}, {"order": 11, "qtype": "single", "stem": "洞穴探险者案作为思想实验，其理论价值在于：", "options": ["A 它是真实判例", "B 它展示不同司法理念可导致不同裁判结论", "C 它证明法律完全不确定", "D 它否定一切法律原则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该案以多位法官的不同意见展示司法理念对裁判的影响。【逐步演示】Wacks 以其作为理解各法理立场的切入口。【易错提醒】它是富勒虚构的思想实验，不是真实判例。"}, {"order": 12, "qtype": "multi", "stem": "约束法官判断的制度性因素包括：", "options": ["A 遵循先例", "B 上级审查", "C 法律教育与职业文化", "D 法官个人好恶"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】遵循先例、上级审查、职业文化都是约束法官判断的制度因素。【逐步演示】D 是个人因素，属于判断空间的来源而非约束。【易错提醒】卢埃林后期也强调使裁判可预期的稳定性因素。"}, {"order": 13, "qtype": "essay", "stem": "结合达德利案，分析法官如何在法律规则与道德直觉之间平衡，并说明现实主义与哈特各自如何理解这种平衡。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明案件，再分别以现实主义与哈特立场解读。【逐步演示】法院坚持谋杀罪规则却在量刑上宽大，体现规则与后果的平衡；现实主义视之为法官判断，哈特视之为框架内的裁量。【易错提醒】不要简单判定某一种解读『正确』。", "keywords": [["案件事实", "漂流船员杀死同伴"], ["现实主义解读", "后果与政策判断影响裁判"], ["哈特解读", "判断在法律框架内"], ["平衡意义", "规则严格性与量刑宽大"]]}]}, "S2M3K4": {"lesson": "S2M3K4", "questions": [{"order": 1, "qtype": "single", "stem": "『书本上的法』（law in books）与『行动中的法』（law in action）的区分，主要源于哪一法学流派？", "options": ["A 自然法理论", "B 法律现实主义", "C 纯粹法学", "D 分析法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律现实主义把注意力从书本上的法转向行动中的法。【逐步演示】霍姆斯『法律的生命不在逻辑，而在经验』是这一转向的标志。【易错提醒】自然法关注正义，纯粹法学关注规范结构，均非这一区分的来源。"}, {"order": 2, "qtype": "blank", "stem": "奥地利法学家埃利希（Eugen Ehrlich）提出『______』（living law）概念，指实际支配社会生活的秩序。", "options": [], "answer": "", "accepted": ["活法", "living law", "活的法律", "生活中的法"], "keywords": [], "explanation": "【答案】活法（living law）。【解题思路】埃利希在《法律社会学基本原理》中提出这一概念。【逐步演示】它把法律研究的视野从国家制定法扩展到社会自发秩序。【易错提醒】活法不等于习惯法，它强调实际支配行为的秩序。"}, {"order": 3, "qtype": "judge", "stem": "法律的『效力』与『实效』是同一概念，只要法律有效就必然在社会中被遵守。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】效力与实效是两个不同概念：有效力的法律未必有实效。【逐步演示】凯尔森也区分二者；禁酒令就是形式上有效却实效不佳的例子。【易错提醒】不要因法律有效就推断它一定被遵守。"}, {"order": 4, "qtype": "single", "stem": "美国1920至1933年的禁酒令案例，最常用于说明：", "options": ["A 法律与道德必然联系", "B 法律规则与社会现实脱节导致实效不佳", "C 法律必须有制裁", "D 法律来自主权者命令"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】禁酒令虽有效却因社会普遍规避而实效不佳，并催生地下经济。【逐步演示】这体现书本上的法与行动中的法的落差。【易错提醒】禁酒令在废止前仍是有效法律，不要说它『无效』。"}, {"order": 5, "qtype": "multi", "stem": "根据本节内容，研究法律与社会现实的关系，需要关注：", "options": ["A 行动中的法", "B 活法与社会自发秩序", "C 法律移植的社会语境", "D 纯粹的概念分析"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律与社会现实的研究关注实际运作、活法与社会语境。【逐步演示】D 纯粹概念分析属分析法学路径，与社会取向相对。【易错提醒】不要认为关注社会现实就要放弃概念分析，哈特采取中间立场。"}, {"order": 6, "qtype": "judge", "stem": "比较法研究（如 Siems）表明，法律制度的实际效果往往取决于它所在的社会语境。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 的比较法研究强调法律传统与社会条件的关联。【逐步演示】这提示法律移植须考虑社会契合度。【易错提醒】这不意味着法律完全由社会决定，法律也有自身制度逻辑。"}, {"order": 7, "qtype": "essay", "stem": "试述『书本上的法』与『行动中的法』的区分，并结合禁酒令说明其意义。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明区分的含义，再以禁酒令说明。【逐步演示】禁酒令在文本上有效，但实际中被普遍规避并催生犯罪，说明效力与实效的落差。【易错提醒】不要把实效不佳等同于法律无效。", "keywords": [["区分含义", "文本规则与实际运作"], ["现实主义取向", "关注行动中的法"], ["禁酒令例证", "有效但实效差"], ["理论意义", "效力与实效区分"]]}, {"order": 8, "qtype": "single", "stem": "奥利弗克罗纳颠倒通常『法律反映道德价值』的观点，主张：", "options": ["A 道德决定法律", "B 法律影响道德", "C 法律与道德无关", "D 道德与法律同一"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，奥利弗克罗纳主张法律影响道德而非相反。【逐步演示】这体现法律对社会现实的塑造作用。【易错提醒】这一主张受到批评，不要把它当作无争议的定论。"}, {"order": 9, "qtype": "blank", "stem": "把法律制度从一个社会移转到另一个社会的现象，比较法上称为法律______。", "options": [], "answer": "", "accepted": ["移植", "法律移植", "legal transplant", "迁植"], "keywords": [], "explanation": "【答案】移植（legal transplant）。【解题思路】法律移植是比较法的重要概念。【逐步演示】Siems 的比较法研究提示，移植的成功取决于社会语境的契合。【易错提醒】不要把它与法律继承或法律统一混为一谈。"}, {"order": 10, "qtype": "judge", "stem": "凯尔森的纯粹法学主张法律科学家应排除社会事实，这与现实主义的社会取向形成对照。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】凯尔森坚持法律科学家不关心人的实际行为，与现实主义关注社会运作相反。【逐步演示】Wacks 指出两者取向截然不同。【易错提醒】这只是方法论差异，不意味着凯尔森否认法律与社会的一切关联。"}, {"order": 11, "qtype": "single", "stem": "下列关于法律社会学与分析法学的说法，正确的是：", "options": ["A 两者方法论完全相同", "B 前者引入社会学方法，后者追求概念纯粹", "C 前者否认法律存在", "D 后者主张法律应被社会决定"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律社会学引入经验方法，分析法学追求概念纯粹。【逐步演示】凯尔森的纯粹法学是后者的极端形态。【易错提醒】两者并非完全对立，哈特就采取中间立场。"}, {"order": 12, "qtype": "multi", "stem": "法律与社会现实脱节可能导致的后果包括：", "options": ["A 法律被普遍规避", "B 形成与文本不同的运作逻辑", "C 法律丧失实效", "D 法律自动获得正当性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】脱节可导致规避、非正式运作与实效丧失。【逐步演示】禁酒令即例证。【易错提醒】D 错误，脱节不会自动带来正当性，反而可能削弱正当性。"}, {"order": 13, "qtype": "essay", "stem": "结合埃利希的『活法』概念与比较法视角，分析法律改革为何必须考虑社会现实。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明活法与落差，再谈比较法启示与改革意义。【逐步演示】活法提示社会中存在实际支配行为的秩序；若改革忽视这些秩序，纸面规则可能被规避。【易错提醒】不要走向另一极端，否认法律塑造社会的能力。", "keywords": [["活法概念", "社会自发秩序"], ["文本与实践落差", "行动中的法"], ["社会语境", "法律移植条件"], ["改革启示", "制度须契合社会"]]}]}, "S2M3K5": {"lesson": "S2M3K5", "questions": [{"order": 1, "qtype": "single", "stem": "批判法学运动（CLS）兴起的时间与地点是：", "options": ["A 十九世纪中叶的英国", "B 二十世纪七十年代的美国", "C 二十世纪初的德国", "D 二战后的法国"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出，CLS 于二十世纪七十年代在美国发展。【逐步演示】它表达对法律与法律理论的广泛马克思主义批判。【易错提醒】不要与欧洲的法兰克福学派或其他批判理论混淆。"}, {"order": 2, "qtype": "single", "stem": "Wacks 指出，批判法律理论的中心主题是：", "options": ["A 证明法律逻辑完备", "B 怀疑能否发现统一的规则与教义体系", "C 论证自然法的优越性", "D 建立纯粹法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】CLS 的中心主题是怀疑统一规则教义体系的可能性。【逐步演示】法律被描绘为不确定、矛盾、与社会权力相连的。【易错提醒】这与形式主义对法律统一性的信念直接对立。"}, {"order": 3, "qtype": "judge", "stem": "CLS 认为社会正义是一个可以实现的中立目标，法律能够客观地推进它。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，在 CLS 看来社会正义是空洞的承诺。【逐步演示】CLS 对法律抱深度怀疑，认为所谓中立推进正义是神话。【易错提醒】不要将 CLS 与自由主义法律理论的正义观混淆。"}, {"order": 4, "qtype": "blank", "stem": "CLS 用以揭示法律概念内在矛盾与政治性的批判方法称为『______』（trashing）。", "options": [], "answer": "", "accepted": ["拆解", "trashing", "拆解方法", "解构"], "keywords": [], "explanation": "【答案】拆解（trashing）。【解题思路】Wacks 的书以『Trashing CLS?』为章节标题。【逐步演示】拆解既是 CLS 批判主流理论的方法，也被用于自我反思。【易错提醒】trashing 在此为学术批判方法，非日常意义上的贬义。"}, {"order": 5, "qtype": "multi", "stem": "根据 Wacks 的论述，CLS 的特征包括：", "options": ["A 广义马克思主义批判", "B 强调法律不确定性", "C 跨学科方法", "D 主张法律与政治完全分离"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】CLS 具马克思主义批判、不确定性主张与跨学科特征。【逐步演示】D 错误，CLS 恰恰强调法律的政治性。【易错提醒】注意 CLS 与实证主义在法律与政治关系上的对立。"}, {"order": 6, "qtype": "judge", "stem": "Wacks 指出，CLS 在许多方面类似更早的美国法律现实主义，并继承其对法律中立性的怀疑。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出 CLS 在许多方面类似美国法律现实主义。【逐步演示】差别在于 CLS 更强调政治与权力结构。【易错提醒】现实主义是 CLS、女性主义与后现代理论的先驱。"}, {"order": 7, "qtype": "essay", "stem": "试述 CLS 的核心主张，并分析其与法律现实主义的继承与差别。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明 CLS 核心主张，再比较其与现实主义的异同。【逐步演示】CLS 继承现实主义的怀疑精神，但把不确定性政治化，并以马克思主义与跨学科方法深化批判。【易错提醒】不要只强调差别而忽略继承关系。", "keywords": [["核心主张", "法律不确定与政治性"], ["继承现实主义", "怀疑法律中立与确定"], ["差别", "更强调政治与权力结构"], ["影响", "女性主义后现代理论"]]}, {"order": 8, "qtype": "single", "stem": "葛兰西（Antonio Gramsci）的哪一概念被 CLS 等批判理论用于分析法律如何维持社会支配？", "options": ["A 基础规范", "B 意识形态霸权", "C 承认规则", "D 开放结构"], "answer": "B", "accepted": [], "keywords": ["意识形态霸权"], "explanation": "【答案】B。【解题思路】Wacks 指出，意识形态霸权概念出现在葛兰西的狱中著作中。【逐步演示】它解释统治观念如何借教育文化机制取得支配地位。【易错提醒】A 属凯尔森，C 属哈特，D 属哈特。"}, {"order": 9, "qtype": "judge", "stem": "Wacks 指出，CLS 的影响在后期持续上升，已成为当代法理学的主流范式。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出 CLS 的影响处于下降之中（declining influence）。【逐步演示】但它对后续批判理论影响深远。【易错提醒】影响下降不等于消失，应区分直接影响与思想遗产。"}, {"order": 10, "qtype": "blank", "stem": "Wacks 指出，共同体主义转向是 CLS 工程与______主义共享的特征。", "options": [], "answer": "", "accepted": ["社群", "共同体", "communitarian", "社群主义"], "keywords": [], "explanation": "【答案】社群／共同体主义（communitarianism）。【解题思路】Wacks 指出共同体主义转向是 CLS 与社群主义共享的特征。【逐步演示】这体现 CLS 对自由主义个人主义的批判与替代性价值寻求。【易错提醒】注意『共同体主义』与『社会主义』不是同一概念。"}, {"order": 11, "qtype": "single", "stem": "美国最高法院1896年『普莱西诉弗格森案』确立的『隔离但平等』原则，被 CLS 视为：", "options": ["A 法律中立的典范", "B 法律作为权力工具、为不平等提供合法性的例证", "C 自然法的胜利", "D 法治的完美体现"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】从 CLS 视角看，该原则为种族等级秩序提供合法性叙事。【逐步演示】法律教义的矛盾性使同一条款可支持不同社会安排。【易错提醒】该原则后被1954年布朗案推翻。"}, {"order": 12, "qtype": "multi", "stem": "对 CLS 的主要批评包括：", "options": ["A 夸大法律的不确定性", "B 拆解方法可能消解批判自身根据", "C 长于批判短于建构", "D 完全否认法律与政治的关联"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】批评集中在夸大不确定性、拆解方法的破坏性与缺乏建设性方案。【逐步演示】D 错误，CLS 恰恰强调法律与政治的关联。【易错提醒】Wacks 的『Trashing CLS?』提示 CLS 也需自我反思。"}, {"order": 13, "qtype": "essay", "stem": "结合布朗案推翻普莱西案的历史，分析 CLS 与法治论者对法律角色的不同理解。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明两案，再分别以 CLS 与法治论立场分析。【逐步演示】CLS 强调教义不确定与政治语境，法治论强调平等保护原则的批判力量。【易错提醒】不要简单判定某一解读『正确』，应展示各自理据。", "keywords": [["两案事实", "隔离但平等被推翻"], ["CLS解读", "法律教义矛盾与政治判断"], ["法治论解读", "普遍原则挑战不义制度"], ["评价", "法律的约束与批判双面"]]}]}, "S2M3K6": {"lesson": "S2M3K6", "questions": [{"order": 1, "qtype": "single", "stem": "法律工具论（Instrumental View of Law）的核心主张是：", "options": ["A 法律是统治集团意志与利益的工具", "B 法律是中立规则体系", "C 法律来自神的理性", "D 法律完全自主"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法律工具论把法律视为权力意志的直接表达。【逐步演示】Wacks 指出，古典马克思主义理论拒斥法律中立的观念。【易错提醒】工具论受到批评，因为它过于简单，无法解释法律保护弱者的情形。"}, {"order": 2, "qtype": "blank", "stem": "葛兰西提出的『______霸权』（ideological hegemony）概念，指统治观念借教育文化机制取得支配地位。", "options": [], "answer": "", "accepted": ["意识形态", "ideological", "意识形态霸权", "思想意识"], "keywords": [], "explanation": "【答案】意识形态（ideological hegemony）。【解题思路】Wacks 指出该概念出自葛兰西的狱中著作。【逐步演示】它解释权力如何靠塑造观念而非仅靠压制来维持。【易错提醒】霸权不等于赤裸强制，强调的是『自愿』接受。"}, {"order": 3, "qtype": "judge", "stem": "法律相对自主论认为法律完全独立于社会权力，与权力结构毫无关联。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】相对自主论承认法律与权力相连，只强调法律有自身的制度逻辑。【逐步演示】哈特的规则理论与法治理论是其资源。【易错提醒】『相对自主』不是『完全独立』，注意程度差别。"}, {"order": 4, "qtype": "multi", "stem": "分析法律与权力结构关系的模型包括：", "options": ["A 工具论", "B 构成论", "C 霸权论", "D 相对自主论"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四种模型分别侧重表达、构成、观念支配与制度自主。【逐步演示】它们构成分析法律与权力关系的完整谱系。【易错提醒】各模型并非互斥，可结合使用。"}, {"order": 5, "qtype": "single", "stem": "自由主义法理论对法律与权力关系的核心立场是：", "options": ["A 法律是阶级工具", "B 法律的普遍规则可约束权力并保障权利", "C 法律完全是意识形态", "D 法律没有规范性与"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】自由主义强调法治、普遍规则与权利保障。【逐步演示】哈特、拉兹、德沃金分别从规则、权威与权利角度说明。【易错提醒】选项 D 明显错误，自由主义并不否认法律的规范性。"}, {"order": 6, "qtype": "judge", "stem": "德沃金的『权利是王牌』命题主张个人权利优先于集体功利目标。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】权利王牌命题强调个人权利优先于功利。【逐步演示】Wacks 书中专设『the rights thesis』一节讨论。【易错提醒】这一命题体现德沃金对功利主义的批评。"}, {"order": 7, "qtype": "essay", "stem": "试述法律工具论与相对自主论的分歧，并说明哈特的规则理论如何支持相对自主论。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明两种立场，再说明哈特理论的贡献。【逐步演示】工具论强调法律被权力决定；哈特的承认规则存在于官员实践中，显示法律有相对独立的制度逻辑。【易错提醒】相对自主论不是完全否认法律与权力的关联。", "keywords": [["工具论", "法律是权力意志表达"], ["相对自主论", "法律有自身制度逻辑"], ["哈特资源", "承认规则与内部观点"], ["分歧实质", "法律是否被社会力量完全决定"]]}, {"order": 8, "qtype": "single", "stem": "美国最高法院1954年『布朗诉教育委员会案』推翻1896年普莱西案确立的隔离原则，这一历史最能说明：", "options": ["A 法律只是权力工具", "B 法律的普遍原则可成为挑战既有权力结构的资源", "C 法律完全由社会决定", "D 法律没有批判功能"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】布朗案说明平等保护原则可被用来挑战种族隔离制度。【逐步演示】这体现法律超越其社会起源的批判潜力。【易错提醒】CLS 会强调两案都反映政治语境，不要忽略这种解读。"}, {"order": 9, "qtype": "judge", "stem": "Wacks 指出，古典马克思主义理论拒斥『法律可以是中立的』这一观念。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 明确指出古典马克思主义拒斥法律中立观念。【逐步演示】马克思主义法学的一大任务是批判自由主义政治哲学的核心。【易错提醒】这并不意味着所有马克思主义者立场完全相同。"}, {"order": 10, "qtype": "blank", "stem": "把法律当作独立自足的神秘实体的观念，马克思主义批判称之为法律______。", "options": [], "answer": "", "accepted": ["拜物教", "法律拜物教", "fetishism", "法拜物教"], "keywords": [], "explanation": "【答案】拜物教（legal fetishism）。【解题思路】Wacks 指出，许多马克思主义者拒斥法律拜物教。【逐步演示】他们主张揭示法律背后的社会关系。【易错提醒】不要把法律拜物教与商品拜物教完全等同，虽两者相关。"}, {"order": 11, "qtype": "single", "stem": "在 Wacks 的论述中，革命马克思主义者对权利的态度是：", "options": ["A 高度重视权利", "B 基本没有兴趣，因其体现个人主义与自由主义观念", "C 主张权利是法律的核心", "D 认为权利是自然法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出革命马克思主义者对权利基本没有兴趣。【逐步演示】这反映马克思主义内部对权利问题的分歧。【易错提醒】不要因此认为所有马克思主义者都否认权利。"}, {"order": 12, "qtype": "multi", "stem": "下列关于霸权论的说法，正确的有：", "options": ["A 强调法律通过塑造观念取得自愿接受", "B 源于葛兰西的意识形态霸权理论", "C 比单纯强制论更精细", "D 否认一切强制因素的作用"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】霸权论强调观念支配、源于葛兰西、比强制论精细。【逐步演示】D 错误，霸权论并不否认强制，只是更强调同意机制。【易错提醒】葛兰西理论的核心是『强制＋同意』的结合。"}, {"order": 13, "qtype": "essay", "stem": "结合普莱西案与布朗案，分析法律作为『权力工具』与『批判资源』的双重面相。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords。【解题思路】先说明两案，再分析法律的双重角色。【逐步演示】普莱西案体现法律作为权力工具，布朗案体现法律作为批判资源；相对自主论能较好解释这种双面性。【易错提醒】不要简单判定法律『只是工具』或『完全中立』。", "keywords": [["普莱西案", "法律维护种族等级"], ["布朗案", "普遍原则挑战不义"], ["双重面相", "工具与资源的并存"], ["理论解释", "相对自主论的解释力"]]}]}, "S2M4K1": {"lesson": "S2M4K1", "questions": [{"order": 1, "qtype": "single", "stem": "Zweigert 与 Kötz 功能主义路径的第一步是：", "options": ["A 比较各国法条的措辞", "B 从社会问题或功能需求出发提出问题", "C 统计各国判例数量", "D 追溯规则的罗马法起源"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】功能主义以功能性问题为比较起点，而非以概念或条文为起点。【逐步演示】先问『社会问题如何解决』，再寻找各国的功能等价物，最后评价效果。【易错提醒】A 是术语比较，D 是法律史方法，均非功能主义的第一步。"}, {"order": 2, "qtype": "single", "stem": "比较整个法律体系或法律家族（如普通法系与大陆法系）属于：", "options": ["A 微观比较", "B 宏观比较", "C 数值比较", "D 明示比较"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】按尺度划分，比较整个法律体系或法律家族为宏观比较。【逐步演示】比较具体规则或个案则为微观比较。【易错提醒】明示/默示是按研究自觉性划分，与尺度无关。"}, {"order": 3, "qtype": "judge", "stem": "Legrand 提出『法律移植的不可能性』，其核心论据是规则的意义取决于解释者所在的文化认知框架。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Legrand 认为法律不只是文本中的词，意义是解释的函数，故规则在移植中必然变形。【逐步演示】他借 Latour 的说法『没有不变形的运输』来论证。【易错提醒】这与 Watson 的乐观移植论构成对照。"}, {"order": 4, "qtype": "blank", "stem": "功能主义路径中，不同法律体系里解决同一社会问题的不同制度或规则被称为______。", "options": [], "answer": "", "accepted": ["功能等价物", "functional equivalent", "功能对等物", "功能 equivalents"], "keywords": [], "explanation": "【答案】功能等价物（Functional Equivalent）。【解题思路】这是功能主义比较的核心概念。【逐步演示】名称不同、教义不同，只要承担相同功能即可比较。【易错提醒】不要答成『同一制度』，功能等价物恰恰允许形式不同。"}, {"order": 5, "qtype": "multi", "stem": "根据本节，比较法的功能包括下列哪些？", "options": ["A 理解外国法", "B 反思并改进本国法", "C 推动法律协调与统一", "D 支持法律发展"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】比较法服务于理解、改进、协调、发展等多重目的。【逐步演示】立法借鉴对应 B，区域统一对应 C，发展研究对应 D。【易错提醒】比较法功能多元，不宜只选一两项。"}, {"order": 6, "qtype": "single", "stem": "Siems 对早期功能主义的主要批评不包括：", "options": ["A 倾向于聚焦西方国家", "B 把规则从语境中抽离", "C 把价值判断伪装成中立分析", "D 主张法律与宗教必须分离"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】D 是西方传统法的一般特征，非 Siems 对功能主义的批评。【逐步演示】Siems 的批评集中于西方中心、去语境化与隐蔽的价值判断。【易错提醒】审题时注意『不包括』。"}, {"order": 7, "qtype": "single", "stem": "在社会学、政治学研究中不那么自觉地运用的比较视角，Siems 称之为：", "options": ["A 明示的比较法", "B 默示的比较法", "C 微观比较", "D 功能比较"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】默示的比较法（implicit comparative law）指社会科学中不自觉的比较视角。【逐步演示】明示的比较法才是以比较为自觉对象的系统研究。【易错提醒】注意 explicit 与 implicit 的区分。"}, {"order": 8, "qtype": "judge", "stem": "法理学关心同一时段不同空间中的法律差异，比较法关心『法律是什么』这类普遍问题。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】题干把二者关系说反了。【逐步演示】法理学追问普遍问题，比较法强调不同地方的法律如何不同又如何相通。【易错提醒】二者互补而非等同，注意区分研究对象。"}, {"order": 9, "qtype": "essay", "stem": "试论功能主义与文化主义在比较法方法上的主要分歧，并说明为什么方法选择本身就是一种理论立场。", "options": [], "answer": "", "accepted": [], "keywords": [["比较起点不同", "功能问题对文化意义"], ["对差异态度不同", "可通约对不可化约"], ["对移植判断不同", "乐观对怀疑"], ["方法即立场", "问题框架投射塑造结论"]], "explanation": "【答案要点】见 keywords 四组。【解题思路】先分别说明两派主张，再归纳三个分歧轴，最后点明方法论的理论性。【逐步演示】起点、差异态度、移植判断三层展开；指出相似功能是否『真实』取决于观察框架。【易错提醒】不要把两派漫画化为『只谈条文』与『只谈玄学』。"}, {"order": 10, "qtype": "single", "stem": "关于『善意』(good faith) 的功能比较，Siems 援引的研究表明其在英美司法实践中是：", "options": ["A 完全不存在的概念", "B 一个较弱的解释工具", "C 与大陆法完全相同的原则", "D 仅适用于消费者合同的规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】研究表明善意在英美只是『一个较弱的解释工具』。【逐步演示】普通法靠默示条款、衡平救济等实现相近功能。【易错提醒】不要误判为『完全不存在』或『完全相同』两个极端。"}, {"order": 11, "qtype": "blank", "stem": "把法律规则放回其政治、经济与社会环境中理解的研究取向，Siems 称之为______。", "options": [], "answer": "", "accepted": ["语境化", "语境论", "contextualisation", "语境化方法"], "keywords": [], "explanation": "【答案】语境化（Contextualisation）。【解题思路】这是 Siems 教科书的核心特色。【逐步演示】他以此修正早期比较法重规则轻背景的倾向。【易错提醒】语境化强调法律与社会的关联，非单纯历史叙述。"}, {"order": 12, "qtype": "judge", "stem": "Teubner 把善意原则移植到普通法称为『法律刺激物』(legal irritant)，认为它是大陆法律文化的独特表达。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Teubner 以『法律刺激物』描述这种开放原则进入异质文化后的扰动效应。【逐步演示】他认为这是『大陆法律文化的独特表达』。【易错提醒】该比喻用于移植研究，也见于合同法比较。"}, {"order": 13, "qtype": "essay", "stem": "结合『善意』案例，分析功能等价物的解释力与限度。", "options": [], "answer": "", "accepted": [], "keywords": [["功能上有相近效果", "默示条款与衡平救济"], ["结果相似机制不同", "教义装置相反"], ["文化视角的提醒", "法律刺激物"], ["经验数据", "Common Core 三十案例的结果分布"]], "explanation": "【答案要点】见 keywords。【解题思路】先肯定功能比较的解释力，再指出其限度。【逐步演示】用默示条款等说明功能相近；用 Sacco、Teubner 与 Common Core 数据说明机制差异。【易错提醒】不要只给一方结论，须同时回答『结果是否相似』与『如何制造相似』。"}, {"order": 14, "qtype": "multi", "stem": "下列关于比较法与相邻学科关系的表述，哪些是正确的？", "options": ["A 比较法与法理学研究对象有别", "B 比较法与法律史互为补充", "C 比较法可借鉴社会法学方法", "D 比较法与法律史完全无关"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】比较法与法理学、法律史有别但互补，并可吸收社会法学方法。【逐步演示】Siems 强调严肃比较离不开历史语境，故 D 错误。【易错提醒】警惕『完全无关』这类绝对化表述。"}]}, "S2M4K2": {"lesson": "S2M4K2", "questions": [{"order": 1, "qtype": "single", "stem": "公元六世纪查士丁尼主持编纂、十一世纪在欧洲大陆复兴的法典是：", "options": ["A 法国民法典", "B 德国民法典", "C 国法大全（Corpus Juris Civilis）", "D 瑞士民法典"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】《国法大全》533 年编成，十一世纪在大陆复兴，引发罗马法继受。【逐步演示】法国民法典 1804 年、德国民法典 1900 年，均晚于此。【易错提醒】不要把查士丁尼法典与近代民法典混淆。"}, {"order": 2, "qtype": "blank", "stem": "中世纪欧洲超越国界、取代或补充地方法习惯的通用法律传统被称为______。", "options": [], "answer": "", "accepted": ["共同法", "ius commune", "Ius Commune", "通用法"], "keywords": [], "explanation": "【答案】共同法（Ius Commune）。【解题思路】它是继受时期覆盖欧洲的罗马法共同传统。【逐步演示】民族国家兴起后其共同性被法典化削弱。【易错提醒】与万民法 ius gentium 区分，后者处理民族间共同问题。"}, {"order": 3, "qtype": "judge", "stem": "Siems 认为，1804 年法国民法典与 1900 年德国民法典的风格完全一致，都是抽象而通俗易懂的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法国民法典追求通俗易懂，德国民法典更概念化、教授化。【逐步演示】Siems 指出法典化反而导致欧洲大陆法律的分化。【易错提醒】法德差异是比较法的重要考点。"}, {"order": 4, "qtype": "single", "stem": "大陆法常被称为『学者法』(learned law)，主要原因是：", "options": ["A 法官主导法律发展", "B 大学推动了罗马法的继受与传播", "C 议会制定全部法律", "D 陪审团决定法律规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出大学支持罗马法继受，故大陆法有学者法之称。【逐步演示】潘德克顿学派甚至被认为写就了德国民法典。【易错提醒】法官主导是英格兰普通法特征。"}, {"order": 5, "qtype": "multi", "stem": "根据本节，推动比较法形成与扩散的历史动力包括：", "options": ["A 罗马法继受", "B 民族国家法典化", "C 殖民扩张", "D 日本、土耳其等主动移植法典"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四条线索共同推动比较法的形成与世界扩散。【逐步演示】殖民与主动移植解释了大陆法的全球传播。【易错提醒】不要把移植仅理解为殖民强制。"}, {"order": 6, "qtype": "single", "stem": "1066 年诺曼征服后，英格兰普通法形成的基础是：", "options": ["A 查士丁尼法典", "B 标准化的令状（writs）与巡回审判", "C 法国民法典", "D 大学教授的学说"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】威廉一世以令状与巡回审判统一法律，陪审团负责事实认定。【逐步演示】这与大陆的学者法路径明显不同。【易错提醒】不要把英格兰普通法的起源归于罗马法继受。"}, {"order": 7, "qtype": "essay", "stem": "分析法典化运动对大陆法的双重效应：既传播了大陆法，又造成内部分化。", "options": [], "answer": "", "accepted": [], "keywords": [["传播效应", "殖民与主动移植扩散法典"], ["分化效应", "法德风格不同"], ["共同性削弱", "各国法典修改罗马法版本"], ["分类反思", "法律家族不宜绝对化"]], "explanation": "【答案要点】见 keywords。【解题思路】从传播与分化两面展开，再落到分类反思。【逐步演示】指出法国民法典通俗、德国民法典概念化，彼此差异显著。【易错提醒】不要只谈传播而忽略分化。"}, {"order": 8, "qtype": "judge", "stem": "Siems 指出，欧洲不同地方的『共同法』完全相同，并在罗马法继受后统一消失了。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 强调各地有不同的共同法（droit commun、gemeine Recht 等），并未因继受而消失。【逐步演示】民族国家法典化才逐渐削弱其共同性。【易错提醒】注意『完全相同』『统一消失』的绝对化表述。"}, {"order": 9, "qtype": "single", "stem": "Siems 把下列哪一组国家并列为『自愿移植大陆法主要法典』的例子？", "options": ["A 美国与澳大利亚", "B 日本与土耳其", "C 英国与爱尔兰", "D 印度与加拿大"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 明确以日本和土耳其作为主动移植大陆法典的例子。【逐步演示】美国、澳大利亚、印度属普通法传播范围。【易错提醒】区分殖民传播与主动移植。"}, {"order": 10, "qtype": "blank", "stem": "经济学与政治学用法律传统解释经济绩效的研究路径被称为______。", "options": [], "answer": "", "accepted": ["法律起源", "legal origins", "法律起源理论", "法起源"], "keywords": [], "explanation": "【答案】法律起源（Legal Origins）。【解题思路】该路径把法律家族概念用于解释经济绩效。【逐步演示】Siems 指出这在经济学家与政治科学家中重新流行。【易错提醒】与法律家族概念相关但不完全等同。"}, {"order": 11, "qtype": "multi", "stem": "Siems 提醒，把世界法律画成普通法与大陆法两张标签会遮蔽哪些事实？", "options": ["A 法国法与德国法的显著差异", "B 美国法与英格兰法的分歧", "C 殖民地的混合体系", "D 两大法系之间没有任何共性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 主张避免夸大二元对立，但并未否认共性。【逐步演示】D 走向另一极端，故不成立。【易错提醒】批判二分法不等于否认一切差异或共性。"}, {"order": 12, "qtype": "essay", "stem": "结合日本法律现代化，说明法律家族归属描述的是历史谱系还是当下现实。", "options": [], "answer": "", "accepted": [], "keywords": [["主动移植", "明治维新参照德法"], ["谱系与运作区分", "来源是历史实践是当下"], ["移植后变形", "没有不变形的运输"], ["本土要素", "习惯法持续存在"]], "explanation": "【答案要点】见 keywords。【解题思路】以日本为切口区分谱系与现实。【逐步演示】说明法典来源决定分类，但实际运作发生变形，本土习惯仍在。【易错提醒】不要把归属理解为完全等同。"}]}, "S2M4K3": {"lesson": "S2M4K3", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 指出，法律家族分类的核心思想是：", "options": ["A 各国法律完全随机", "B 世界法律多样性并非随机，成组国家共享特征", "C 只有大陆法国家才有共同特征", "D 分类等同于法律史研究"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律家族思想强调多样性并非随机，而是成组共享历史、思维与规则。【逐步演示】这是 Siems 对 legal families 基本理念的概括。【易错提醒】不要走向『完全随机』或『只有某一法系有共性』的极端。"}, {"order": 2, "qtype": "blank", "stem": "大陆法系内部以法国民法典为范本的分支通常被称为______法族。", "options": [], "answer": "", "accepted": ["罗马", "罗马法", "Romanist", "罗马法族"], "keywords": [], "explanation": "【答案】罗马（Romanist）。【解题思路】大陆法常分为罗马法族与日耳曼法族。【逐步演示】前者以法国民法典为范本，后者以德国民法典为范本。【易错提醒】与『日耳曼法族』区分。"}, {"order": 3, "qtype": "single", "stem": "不少分类法把北欧国家单列一类，主要理由是：", "options": ["A 它们完全不受罗马法影响", "B 它们没有采纳综合性法典", "C 它们使用普通法语言", "D 它们没有法院"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出北欧国家因未采纳综合性法典而与其他大陆体系有别。【逐步演示】故一些分类为其单设类别。【易错提醒】不要误以为北欧『完全不受罗马法影响』。"}, {"order": 4, "qtype": "judge", "stem": "Siems 认为，一个国家属于哪个法律家族，主要由其法律的『方式』（法律渊源、方法、法院组织等）决定。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 强调 way of doing law 与 way of thinking about law 是分类的关键标准。【逐步演示】渊源、方法、推理风格均为常用指标。【易错提醒】分类标准不是单一的种族或语言因素。"}, {"order": 5, "qtype": "multi", "stem": "Siems 归纳的分类中的三种偏向包括：", "options": ["A 过度强调差异", "B 过度强调共性", "C 忽视混合体", "D 完全否认法律传统的存在"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】这是 Siems 在第三章批判分析部分明确列出的三种偏向。【逐步演示】D 并非其归纳，且他并不否认传统。【易错提醒】注意他批判的是『绝对化』，而非否认分类本身。"}, {"order": 6, "qtype": "single", "stem": "经济学与政治学中用法律传统解释经济绩效的研究路径被称为：", "options": ["A 法律文化研究", "B 法律起源理论", "C 法律解释学", "D 法律社会学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律起源理论把法律家族作为解释变量研究经济绩效。【逐步演示】Siems 指出其在经济学家与政治科学家中流行。【易错提醒】与法学家的法律家族研究视角不同。"}, {"order": 7, "qtype": "essay", "stem": "论述法律家族分类的认知价值与局限，并说明为何不应把它绝对化。", "options": [], "answer": "", "accepted": [], "keywords": [["认知价值", "整理多样性揭示亲缘关系"], ["理想类型", "现实国家很少完全符合"], ["三种偏向", "过度差异过度共性忽视混合"], ["标签非本质", "分类是工具而非本质判断"]], "explanation": "【答案要点】见 keywords。【解题思路】先肯定价值，再分析局限，最后落到审慎立场。【逐步演示】用法德差异、混合体系与西方化作论据。【易错提醒】批判二分法不等于否认一切差异。"}, {"order": 8, "qtype": "judge", "stem": "Siems 主张，法国法与德国法的差异必然小于法国法与英格兰法的差异。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 引用观点指出，法国法与德国法的差异可能『一样大甚至更大』。【逐步演示】这正是批判大陆法内部同质化的论据。【易错提醒】注意题干把或然说成必然。"}, {"order": 9, "qtype": "single", "stem": "下列哪一法域最典型地体现『混合法律体系』？", "options": ["A 纯大陆法的法国", "B 纯普通法的英格兰", "C 私法承法国传统、公法趋同美国的路易斯安那", "D 未受外来影响的孤立部落法"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】路易斯安那融合大陆私法与普通法公法，是混合体系典型。【逐步演示】魁北克、南非也常被列为混合体。【易错提醒】混合体系是常态而非异常，不能因此否定分类。"}, {"order": 10, "qtype": "blank", "stem": "Zweigert 与 Kötz 的分类体系以德语概念______（法律圈）为核心。", "options": [], "answer": "", "accepted": ["Rechtskreis", "法律圈", "法圈", "Rechtskreise"], "keywords": [], "explanation": "【答案】Rechtskreis（法律圈）。【解题思路】这是 Zweigert 与 Kötz 分类体系的核心概念。【逐步演示】他们以法律样式与思维方式划分法律圈。【易错提醒】与法律家族、法律传统等术语相区分。"}, {"order": 11, "qtype": "multi", "stem": "下列关于法律家族与法律文化关系的表述，哪些正确？", "options": ["A 法律家族强调制度与规则的亲缘", "B 法律文化强调价值观念与思维习惯", "C 二者解释层面不同可互补", "D 二者是完全同一的概念"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律家族偏制度亲缘，法律文化偏价值思维，二者互补。【逐步演示】D 把二者等同，错误。【易错提醒】注意题干中的『完全同一』。"}, {"order": 12, "qtype": "essay", "stem": "以路易斯安那为例，说明混合体系对法律家族分类的挑战。", "options": [], "answer": "", "accepted": [], "keywords": [["私法承法国传统", "民法典传统"], ["公法趋同美国", "普通法环境"], ["归入任一格都遮蔽一半", "分类边界模糊"], ["混合体为常态", "历史接触产物"]], "explanation": "【答案要点】见 keywords。【解题思路】先描述混合特征，再说明对分类的挑战。【逐步演示】指出其私法与公法分属不同传统，单一标签失效。【易错提醒】不要把混合体系当成分类的失败，Siems 视其为常态。"}]}, "S2M4K4": {"lesson": "S2M4K4", "questions": [{"order": 1, "qtype": "single", "stem": "被视为法律移植概念奠基人、并主张『借用，哪怕是不假思索的借用，才是法律游戏的名称』的学者是：", "options": ["A Pierre Legrand", "B Alan Watson", "C Gunther Teubner", "D Mathias Siems"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Alan Watson 是法律移植概念奠基人，持乐观立场。【逐步演示】他从罗马法继受出发，认为私法规则可脱离特定民族与地点存续。【易错提醒】Legrand 是怀疑论代表，立场相反。"}, {"order": 2, "qtype": "single", "stem": "Legrand『法律移植的不可能性』命题的核心论据是：", "options": ["A 各国立法者从不互相借鉴", "B 规则意义取决于解释者所在文化认知框架，移植中必然改变", "C 外国规则总是质量低劣", "D 移植会导致法律趋同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Legrand 认为意义是规则被适用的函数，解释受文化心智塑造，故移植必然变形。【逐步演示】他借 Latour『没有不变形的运输』论证。【易错提醒】他不否认立法者会抄文本，只否认『真正移植』。"}, {"order": 3, "qtype": "judge", "stem": "Siems 认为，不存在纯粹的法律体系，所有体系都在吸收世界各地的观念，因此一概怀疑外来影响是夸大其词。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 以『不存在纯粹法律体系』反驳对外来影响的全面怀疑。【逐步演示】他主张反对盲目照搬而非反思性学习。【易错提醒】这并不等于他赞成不加选择的移植。"}, {"order": 4, "qtype": "blank", "stem": "Teubner 用来描述外来规则进入本土体系后引发扰动的用语是『法律______』。", "options": [], "answer": "", "accepted": ["刺激物", "irritant", "法律刺激物", "legal irritant"], "keywords": [], "explanation": "【答案】刺激物（Legal Irritant）。【解题思路】Teubner 以『法律刺激物』描述移植的扰乱效应。【逐步演示】该比喻也用于描述善意原则进入普通法。【易错提醒】与 Watson 的乐观术语区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，法律移植的动机类型包括：", "options": ["A 成本节约型移植", "B 合法性生成型移植", "C 企业家型移植", "D 降低交易成本的移植"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】Siems 列出多种移植动机，说明移植未必是理性择优。【逐步演示】合法性生成型为获取声望，企业家型由利益集团推动。【易错提醒】不要只把移植理解为效益驱动。"}, {"order": 6, "qtype": "single", "stem": "Siems 开启法律移植一章所使用的当代案例是：", "options": ["A 法国民法典的编纂", "B 2005 年中国公司法引入股东代表诉讼", "C 德国民法典的制定", "D 英国普通法的形成"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 以 2005 年中国公司法引入美式股东代表诉讼开篇。【逐步演示】由此引出为何移植、是否运作、是否可取等问题。【易错提醒】该制度源自美国法模型。"}, {"order": 7, "qtype": "essay", "stem": "比较 Watson 与 Legrand 关于法律移植的对立立场，并说明 Siems 如何试图调和二者。", "options": [], "answer": "", "accepted": [], "keywords": [["Watson 乐观", "私法规则可脱离语境存续"], ["Legrand 怀疑", "意义随解释改变移植不可能"], ["Siems 调和", "无纯粹体系反盲目照搬取中间立场"], ["术语之争", "双方都承认会抄文本"]], "explanation": "【答案要点】见 keywords。【解题思路】先述两派主张，再述 Siems 的综合。【逐步演示】指出 Siems 认为分歧部分是术语之争，关键是审慎选择与设计。【易错提醒】不要把 Siems 误归为任何一方的极端拥护者。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，移植、趋同与发展之间存在必然的因果关系：移植必然带来趋同，趋同必然促进发展。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确说三者关系是『典型但非必然』。【逐步演示】移植可能导致分化，趋同未必带来发展。【易错提醒】注意『必然』这一绝对化表述。"}, {"order": 9, "qtype": "single", "stem": "Siems 主张，对法律移植的批评应当针对：", "options": ["A 一切域外学习", "B 盲目照搬而非反思性学习", "C 所有外国法律", "D 法律家族分类"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 主张批评盲目照搬，肯定反思性学习。【逐步演示】他援引 Rubin『借来的很少，学到的很多』。【易错提醒】不要把他理解为全面反对移植。"}, {"order": 10, "qtype": "blank", "stem": "Siems 引用 Galanter 的比喻：法律像语言，能吸收外来影响同时保留自身独特的______与风味。", "options": [], "answer": "", "accepted": ["结构", "distinctive structure", "独特结构", "结构特色"], "keywords": [], "explanation": "【答案】结构（structure）。【解题思路】Galanter 把法律比作语言，吸收外来影响但保留独特结构与风味。【逐步演示】Arvind 则以葡萄藤嫁接作比。【易错提醒】区分不同学者的比喻。"}, {"order": 11, "qtype": "multi", "stem": "评估一项法律移植是否『有效』时，Siems 指出『运作』可能指：", "options": ["A 像在母国一样运作", "B 得到良好执行", "C 契合输入国社会需求", "D 必然与母国文字完全一致"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 指出『work』含义不清，可指原文照搬式运作、良好执行或契合需求。【逐步演示】D 把有效等同于文字一致，非其意。【易错提醒】这是定义难题，是各方争论根源之一。"}, {"order": 12, "qtype": "essay", "stem": "结合中国 2005 年公司法股东代表诉讼，分析移植、趋同与发展之间的『典型但非必然』关系。", "options": [], "answer": "", "accepted": [], "keywords": [["移植美国范本", "derivative action"], ["可视为趋同", "公司法相似"], ["意在促进发展", "刺激经济"], ["关系非必然", "移植也可能导致分化"]], "explanation": "【答案要点】见 keywords。【解题思路】以案例说明三者关联但不必然。【逐步演示】指出移植可能导致分化、趋同未必带来发展。【易错提醒】不要断言移植必然成功或必然趋同。"}]}, "S2M4K5": {"lesson": "S2M4K5", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 对『法律趋同』的界定，下列哪一项最准确？", "options": ["A 各国法律终将完全相同", "B 法律现象变得更相似，但不意味完全相同，也不能绝对预测", "C 仅指刻意统一规则", "D 仅指西方化"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 明确说趋同是变得更相似，不意味相同，也不能绝对预测。【逐步演示】他强调其价值在于理解塑造法律发展的力量。【易错提醒】A 把趋势写成必然规律，错误。"}, {"order": 2, "qtype": "judge", "stem": "法律移植必然导致法律趋同，趋同也必然促进经济发展。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出移植也可能导致分化，移植、趋同与发展关系『典型但非必然』。【逐步演示】若多数国家移植异类规则，全球会更分化。【易错提醒】注意『必然』的绝对化。"}, {"order": 3, "qtype": "blank", "stem": "不同法律规则产生可比效果而形成的趋同，在公司法文献中被称为______趋同。", "options": [], "answer": "", "accepted": ["功能", "functional", "功能趋同", "functional convergence"], "keywords": [], "explanation": "【答案】功能（Functional）。【解题思路】Gilson 主张功能趋同比形式趋同更可能。【逐步演示】功能趋同指效果可比而规则文本未必一致。【易错提醒】与形式趋同（文本一致）区分。"}, {"order": 4, "qtype": "multi", "stem": "根据 Siems，公司法文献中提到的趋同类型包括：", "options": ["A 形式趋同与功能趋同", "B 契约趋同", "C 混合趋同", "D 规范趋同与制度趋同"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】Siems 列出 formal、functional、contractual、hybrid、normative、institutional 等趋同类型。【逐步演示】各自对应文本、效果、合同安排、注册地迁移、法外规范与事实结构。【易错提醒】类型多样，不宜只选一两项。"}, {"order": 5, "qtype": "single", "stem": "主张功能趋同比形式趋同更可能的学者是：", "options": ["A Ronald Gilson", "B Colin Hay", "C Curtis Milhaupt", "D David Charny"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Gilson 认为功能趋同更可能，因为正式统一的障碍太多而问题相似。【逐步演示】Hay 提出政治学的因果链分类，Milhaupt 提规范趋同，Charny 提制度趋同。【易错提醒】区分各学者对应的概念。"}, {"order": 6, "qtype": "essay", "stem": "论述法律趋同与法律移植、协调（harmonisation）的联系与区别。", "options": [], "answer": "", "accepted": [], "keywords": [["移植是单向输入", "趋同是多向靠近"], ["移植可致分化", "非必然趋同"], ["协调刻意统一", "趋同更宽泛含自发演化"], ["三种现象并列", "趋同区域化跨国化"]], "explanation": "【答案要点】见 keywords。【解题思路】分别辨析三组关系。【逐步演示】指出移植是机制之一但也可能分化；协调是有意设计，趋同更宽泛。【易错提醒】不要把三者等同。"}, {"order": 7, "qtype": "single", "stem": "Siems 把『是否正在趋同』与『是否应当趋同』的区分称为：", "options": ["A 事实与价值的区分", "B 规范性与实证性的讨论", "C 形式与功能的区分", "D 移植与趋同的区分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 在讨论中区分 normative 与 positive 两个层面。【逐步演示】即事实判断与价值判断须分开。【易错提醒】不要误选一般性的『事实与价值』表述，尽管含义相近。"}, {"order": 8, "qtype": "judge", "stem": "Siems 警告，法律规则的相似可能主要是知识分子的建构，而非真实的全球现象。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 明确质疑共同性是真实全球现象还是智力建构。【逐步演示】这贯穿其对全球比较法的审慎态度。【易错提醒】他并非否认一切趋同，而是要求批判性检验。"}, {"order": 9, "qtype": "blank", "stem": "有研究显示，中东欧国家股东保护水平向西方模式靠拢，Siems 以此说明公司法中的______现象。", "options": [], "answer": "", "accepted": ["西方化", "Westernisation", "趋同", "股东保护趋同"], "keywords": [], "explanation": "【答案】西方化（Westernisation）/趋同。【解题思路】Siems 以中东欧股东保护曲线说明西方化与趋同。【逐步演示】但强调曲线可能停滞或逆转。【易错提醒】趋同不是单向不可逆的过程。"}, {"order": 10, "qtype": "multi", "stem": "根据 Siems，维持或扩大法律差异的反向力量包括：", "options": ["A 路径依赖与本土法律文化", "B 既有制度的互补性", "C 国家主权对法律统一的抵制", "D 移植的失败"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】这些力量都会维持或扩大法律差异。【逐步演示】法律与发展批评者还指外来法律『不起作用』。【易错提醒】不要把趋同视为单向无阻的过程。"}, {"order": 11, "qtype": "essay", "stem": "分析『趋同还是分化』争论中实证层面与规范层面的分歧，并说明 Siems 的审慎立场。", "options": [], "answer": "", "accepted": [], "keywords": [["实证之争", "是否真的趋同文本与实践差异"], ["规范之争", "趋同是否可取西方化担忧"], ["事实价值分开", "positive 与 normative"], ["审慎折中", "答案非简单是否警惕建构"]], "explanation": "【答案要点】见 keywords。【解题思路】从两个层面展开，再述 Siems 立场。【逐步演示】指出相似可能是投射结果，须区分文本、执行、制度三层次。【易错提醒】不要给出简单的『是』或『否』结论。"}, {"order": 12, "qtype": "single", "stem": "Siems 在『国家边界消逝』框架下讨论的三种相近但不同的现象是：", "options": ["A 趋同、区域化、跨国化", "B 移植、继受、法典化", "C 分化、多元、混合", "D 宏观、微观、数值"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 明确把 convergence、regionalisation、transnationalisation 作为三种变体。【逐步演示】它们共同构成国家边界消逝的主题。【易错提醒】EU 是区域化典型，跨国商事惯例属跨国化。"}]}, "S2M5K1": {"lesson": "S2M5K1", "questions": [{"order": 1, "qtype": "single", "stem": "普通法系形成的历史起点通常被认为是：", "options": ["A 1804 年法国民法典", "B 1066 年诺曼征服后英格兰王室司法", "C 查士丁尼编纂国法大全", "D 1900 年德国民法典"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出普通法源于 1066 年诺曼征服后威廉一世建立的令状与法院体系。【逐步演示】罗马法与法德民法典属大陆法脉络。【易错提醒】不要把普通法起源归于罗马法继受。"}, {"order": 2, "qtype": "blank", "stem": "中世纪英格兰开启诉讼的标准化司法文书称为______。", "options": [], "answer": "", "accepted": ["令状", "writ", "Writ", "诉讼令状"], "keywords": [], "explanation": "【答案】令状（Writ）。【解题思路】标准化令状是普通法形成的基础。【逐步演示】Maitland 名言说诉讼形式虽被埋葬仍统治我们。【易错提醒】与陪审团、判决理由等概念区分。"}, {"order": 3, "qtype": "single", "stem": "Siems 指出，普通法的法律推理风格总体上是：", "options": ["A 演绎的、三段论的", "B 归纳的、论辩的、实用主义的", "C 纯粹形式主义的", "D 完全排斥先例的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 描述普通法判决为归纳式、论辩式、实用主义。【逐步演示】演绎三段论是大陆法风格。【易错提醒】注意两大法系推理风格的对照。"}, {"order": 4, "qtype": "judge", "stem": "在美国，民事陪审团至今仍是显著制度；而在多数普通法国家，民事陪审团已消失。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出民事陪审团在多数普通法国家消失，美国是显著例外。【逐步演示】陪审团在美国被视为文化与民主要素。【易错提醒】不要以为陪审团是所有普通法国家现存的共同制度。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，下列哪些属于普通法系的核心特征？", "options": ["A 判例为主要法律渊源", "B 遵循先例原则", "C 对抗制诉讼程序", "D 法官通过判决自下而上发展法律"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为普通法系核心特征。【逐步演示】这些要素相互关联形成连贯的制度束。【易错提醒】不要把陪审团当作所有普通法国家现存制度。"}, {"order": 6, "qtype": "single", "stem": "Robert Kagan 用哪一概念形容『美国的法律方式』？", "options": ["A 法律实证主义", "B 对抗性法治主义（adversarial legalism）", "C 形式主义", "D 社群主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Kagan 以『对抗性法治主义』概括美国例外论。【逐步演示】他认为这使美国区别于所有其他体系包括英格兰。【易错提醒】与法律实证主义等法理学概念区分。"}, {"order": 7, "qtype": "essay", "stem": "论述普通法系的共同内核，并说明为什么不应把英格兰法与美国法混为一谈。", "options": [], "answer": "", "accepted": [], "keywords": [["共同内核", "判例先例对抗制法官造法"], ["英美差异", "陪审团开示法官遴选费用规则"], ["美国例外论", "Kagan 对抗性法治主义"], ["英格兰更像大陆", "欧洲视角的判断"]], "explanation": "【答案要点】见 keywords。【解题思路】先述共同性，再述差异，最后落到方法论提醒。【逐步演示】用陪审团、开示、违宪审查等具体差异支撑。【易错提醒】避免走向『英美完全相同』或『毫无共性』两端。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，从欧洲视角看，英格兰的司法体系比美国的司法体系更接近大陆体系。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 引述观点：英格兰司法体系更像大陆体系而非美国。【逐步演示】这与美国例外论相互印证。【易错提醒】这是视角性判断，非绝对结论。"}, {"order": 9, "qtype": "blank", "stem": "判决中具有约束力、构成先例核心的法律理由称为______。", "options": [], "answer": "", "accepted": ["判决理由", "ratio decidendi", "Ratio Decidendi", "判决的要旨"], "keywords": [], "explanation": "【答案】判决理由（Ratio Decidendi）。【解题思路】它与无约束力的附带意见相对。【逐步演示】识别先例须区分二者。【易错提醒】obiter dicta 是附带意见，不具约束力。"}, {"order": 10, "qtype": "single", "stem": "Siems 用哪一说法说明：即便陪审团在形式上消亡，其影响仍塑造普通法审判？", "options": ["A 法律刺激物", "B 幽灵陪审团（phantom jury）", "C 司法 slot machine", "D 法律家族"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 用『幽灵陪审团』说明陪审团的结构性遗产。【逐步演示】它帮助理解口头原则与审判作为单一事件。【易错提醒】『司法 slot machine』是 Pound 批评大陆法的比喻。"}, {"order": 11, "qtype": "multi", "stem": "下列哪些是美国法与英格兰法的具体差异？", "options": ["A 美国保留民事陪审团，英格兰已基本取消", "B 美国有广泛审前开示，英格兰开示较弱", "C 美国法官多经选举或政治任命，英格兰重专业晋升", "D 美国有违宪审查，英格兰奉行议会至上"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为 Siems 列举的英美差异。【逐步演示】它们相互关联，构成美国例外论的具体表现。【易错提醒】不要把这些差异误认为大陆法与普通法的差异。"}, {"order": 12, "qtype": "essay", "stem": "以证据开示（discovery）规则为例，说明普通法程序与陪审团、审前准备之间的内在关联。", "options": [], "answer": "", "accepted": [], "keywords": [["陪审团与单一事件", "审判集中审理"], ["广泛审前开示", "美国 1938 年引入"], ["英格兰开示较弱", "英美差异"], ["大陆替代机制", "举证责任转移严格责任"]], "explanation": "【答案要点】见 keywords。【解题思路】从陪审团推出集中审理，再推出开示需求。【逐步演示】对比英格兰与大陆的替代机制。【易错提醒】注意开示规则 1938 年才在美国引入，非自古有之。"}]}, "S2M5K2": {"lesson": "S2M5K2", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 指出，大陆法被称为『学者法』(learned law)，主要因为：", "options": ["A 法官主导法律发展", "B 大学推动了罗马法的继受与传播", "C 陪审团决定法律", "D 议会制定全部法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】大学推动罗马法继受，故大陆法有学者法之称。【逐步演示】潘德克顿学派甚至被认为写就了德国民法典。【易错提醒】法官主导是普通法特征。"}, {"order": 2, "qtype": "single", "stem": "关于法国民法典与德国民法典的风格，下列说法正确的是：", "options": ["A 两者都抽象概念化", "B 法国简明通俗，德国概念化教授化", "C 德国简明通俗，法国概念化", "D 两者都以判例为主"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出法国民法典追求通俗易懂，德国民法典更概念化、教授化。【逐步演示】法典化反而造成大陆内部分化。【易错提醒】法德差异是重要考点。"}, {"order": 3, "qtype": "blank", "stem": "大陆法裁判中把具体事实归入抽象法律规则的操作称为______。", "options": [], "answer": "", "accepted": ["涵摄", "Subsumption", "subsumption", "归入"], "keywords": [], "explanation": "【答案】涵摄（Subsumption）。【解题思路】它是三段论推理的中间环节。【逐步演示】先识别规则，再涵摄事实，最后适用后果。【易错提醒】与三段论、演绎等概念关联但不同。"}, {"order": 4, "qtype": "judge", "stem": "Pound 用『司法自动售货机』(judicial slot machine) 的比喻批评大陆法法官机械适用法律。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Pound 1921 年以此比喻讽刺大陆法官投入事实、吐出判决。【逐步演示】Siems 指出此说既可刻薄批评，也可善意理解为可预测。【易错提醒】这是对理想类型的批评，非全部现实。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，下列哪些属于大陆法系的共同特征？", "options": ["A 以法典为主要渊源", "B 演绎与概念化的法律思维", "C 法官作为法律适用者", "D 法学教授影响深远"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为大陆法系共同特征。【逐步演示】它们相互关联形成连贯整体。【易错提醒】判例为主要渊源是普通法特征。"}, {"order": 6, "qtype": "single", "stem": "瑞士民法典授权法官在法典无规定时依习惯法、再依其作为立法者会确立的规则裁判，这体现的解释方法是：", "options": ["A 字面解释", "B 类推适用与法官补充", "C 严格遵循先例", "D 排斥目的论解释"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该条款允许法官在法无明文时补充法律。【逐步演示】它说明大陆法解释已超越狭隘字面主义。【易错提醒】不要误判为严格字面解释或普通法先例原则。"}, {"order": 7, "qtype": "essay", "stem": "分析法国民民法典与德国民法典在风格与判决写作上的差异，及其所反映的制度文化。", "options": [], "answer": "", "accepted": [], "keywords": [["法典风格", "法国简明对德国概念化"], ["判决风格", "德国学术化条文链对法国极简"], ["制度文化", "德国教授法传统法国议会至上"], ["Lasser 二元划分", "政策论证在判决之外"]], "explanation": "【答案要点】见 keywords。【解题思路】先述法典差异，再述判决差异，最后上升到制度文化。【逐步演示】用 Paragraphenkette、Cour de Cassation、Lasser 等具体材料。【易错提醒】不要简单断言法国法『没有』政策考量。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，现代大陆法国家完全是罗马法的统一现代版本，内部没有实质差异。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 明确指出大陆法并非罗马法的统一现代版本，内部差异显著。【逐步演示】各地有不同共同法，法典化造成分化。【易错提醒】警惕『完全统一』『没有差异』的绝对化。"}, {"order": 9, "qtype": "single", "stem": "Siems 指出，德国民法典的编纂主要受哪一学派影响？", "options": ["A 法律现实主义", "B 潘德克顿学派（Pandectists）", "C 自然法学派", "D 社会法学派"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出潘德克顿学派基本上写就了德国民法典。【逐步演示】德国 2002 年改革也以教授报告为基础。【易错提醒】与其他法学流派区分。"}, {"order": 10, "qtype": "blank", "stem": "德国法中关于通说的概念称为 herrschende Lehre，法国对应的概念是______。", "options": [], "answer": "", "accepted": ["la doctrine", "doctrine", "法国通说", "学说"], "keywords": [], "explanation": "【答案】la doctrine。【解题思路】Siems 指出德国 herrschende Lehre 与法国 la doctrine 对应。【逐步演示】二者地位几近实在法。【易错提醒】注意德语与法语术语的区分。"}, {"order": 11, "qtype": "multi", "stem": "Siems 提到的大陆法解释方法包括：", "options": ["A 探求立法者意图的启示法", "B 依据法律客观目的的目的论方法", "C 类推适用", "D 完全排斥任何解释"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 列举启示法、目的论方法与例外情况下的类推。【逐步演示】大陆法早已超越狭隘字面主义。【易错提醒】D 与大陆法实践完全不符。"}, {"order": 12, "qtype": "essay", "stem": "结合法德判决风格的比较，说明为什么把『大陆法』当作单一对象分析可能误导。", "options": [], "answer": "", "accepted": [], "keywords": [["法德差异显著", "差异可大于与英美差异"], ["多种共同法", "droit commun gemeine Recht"], ["内部分类", "罗马法族日耳曼法族北欧"], ["具体分析优于笼统标签", "比较具体法域"]], "explanation": "【答案要点】见 keywords。【解题思路】从判决差异出发上升到方法论反思。【逐步演示】指出法德差异、历史共同法多样性与内部分类。【易错提醒】不要走向否认大陆法共同基因的另一极端。"}]}, "S2M5K3": {"lesson": "S2M5K3", "questions": [{"order": 1, "qtype": "single", "stem": "1900 年生效、以概念化体系著称的德国民法典简称：", "options": ["A Code Civil", "B BGB（Bürgerliches Gesetzbuch）", "C UCC", "D ZPO"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】BGB 是德国民法典的德文缩写。【逐步演示】Code Civil 是法国民法典，ZPO 是德国民事诉讼法。【易错提醒】注意区分法德法典的缩写。"}, {"order": 2, "qtype": "blank", "stem": "十九世纪德国主张以罗马法材料构建严密概念体系、被誉为写就民法典的学派是______。", "options": [], "answer": "", "accepted": ["潘德克顿学派", "Pandectists", "潘德克顿", "法典学派"], "keywords": [], "explanation": "【答案】潘德克顿学派（Pandectists）。【解题思路】Siems 指出他们基本上写就了 1900 年民法典。【逐步演示】德国 2002 年改革也以教授报告为基础。【易错提醒】与历史法学派区分，后者反对仓促法典化。"}, {"order": 3, "qtype": "single", "stem": "德国民法典采用的、统辖各编的抽象一般规则部分称为：", "options": ["A 分则", "B 总则（Allgemeiner Teil）", "C 附则", "D 判例要旨"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德国民法典含总则编，统辖合同、物权、亲属、继承等分则。【逐步演示】这是其抽象—概括编纂技术的体现。【易错提醒】与法国民法典平铺体例区分。"}, {"order": 4, "qtype": "judge", "stem": "德国法中的通说（herrschende Lehre）虽非正式法源，却几乎与实在法同等重要。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出德国通说地位几近实在法。【逐步演示】教授撰写多卷本评注，法院判决经常引用学术著作。【易错提醒】注意『非正式法源但影响巨大』这一微妙定位。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，德国法律传统的特征包括：", "options": ["A 概念化体系化的民法典", "B 教义学与通说影响巨大", "C 教授对立法与司法解释影响深远", "D 严谨学术化的判决风格"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为德国法特征。【逐步演示】它们共同构成德国法的概念—教义性格。【易错提醒】不要因此否认德国法保持适应性的面向。"}, {"order": 6, "qtype": "single", "stem": "德国民法典中以意思表示为核心、统合合同与遗嘱等行为的抽象概念是：", "options": ["A 法律关系", "B 法律行为（Rechtsgeschäft）", "C 侵权责任", "D 不当得利"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律行为以意思表示为核心，是德国法抽象思维的产物。【逐步演示】它把具体行为统合于一般理论之下。【易错提醒】与其他债法概念区分。"}, {"order": 7, "qtype": "essay", "stem": "论述德国法『概念—教义』传统的形成、表现与Siems对它的审慎评价。", "options": [], "answer": "", "accepted": [], "keywords": [["形成", "潘德克顿学派大学教授主导"], ["表现", "总则结构法律行为条文链判决"], ["通说地位", "几近实在法"], ["审慎评价", "非机械概念法学一般条款保持适应性"]], "explanation": "【答案要点】见 keywords。【解题思路】从形成、表现到评价三层展开。【逐步演示】引用 BGB §242、§311 说明适应性。【易错提醒】不要把德国法简化为僵化的概念法学。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，把德国法官描述为『狭窄、机械、无创造性』是准确的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 转述批评观点指出这种描述并不准确。【逐步演示】德国法通过一般条款发展法律，法院角色积极。【易错提醒】警惕对大陆法的漫画化。"}, {"order": 9, "qtype": "blank", "stem": "德国民法典中要求依诚信原则履行的一般条款（第 242 条）体现了______原则。", "options": [], "answer": "", "accepted": ["善意", "诚信", "good faith", "Treu und Glauben"], "keywords": [], "explanation": "【答案】善意/诚信（good faith）。【解题思路】BGB §242 是善意履行的一般条款。【逐步演示】Siems 强调德国法院借此发展可靠规则而非任意裁量。【易错提醒】与普通法对善意的疑虑对照。"}, {"order": 10, "qtype": "single", "stem": "德国法中把缔约前关系纳入债的关系、适用善意原则的条款是：", "options": ["A BGB §242", "B BGB §311(2)", "C BGB §280(1)", "D BGB §343"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】BGB 第 311 条第 2 款处理缔约过失，使善意适用于缔约前关系。【逐步演示】§242 是一般善意条款，§280(1) 涉及过错责任。【易错提醒】区分不同条文的功能。"}, {"order": 11, "qtype": "multi", "stem": "下列关于德国法与法国法差异的表述，哪些正确？", "options": ["A 德国法典概念化，法国法典简明通俗", "B 德国判决学术化引用密集，法国判决极简", "C 德国有总则编，法国无", "D 两国完全相同，没有差异"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三项均为Siems指出的法德差异。【逐步演示】D 否认差异，错误。【易错提醒】法德同属大陆法但差异显著。"}, {"order": 12, "qtype": "essay", "stem": "结合缔约过失责任，分析德国教义学如何在个案公平与法的安定性之间取得平衡。", "options": [], "answer": "", "accepted": [], "keywords": [["缔约过失", "BGB §311(2)"], ["善意适用", "纳入债的关系"], ["规则操作化", "发展可靠适用类别"], ["功能比较", "法国侵权荷兰公平路径"]], "explanation": "【答案要点】见 keywords。【解题思路】以缔约过失为切口说明教义学能力。【逐步演示】指出德国把抽象原则转化为可预测规则，他国有功能等价物。【易错提醒】不要误判为法官任意裁量。"}]}, "S2M5K4": {"lesson": "S2M5K4", "questions": [{"order": 1, "qtype": "single", "stem": "被视为现代大陆法传统象征、1804 年颁布的法国民法典又称：", "options": ["A BGB", "B 拿破仑法典（Code Napoléon）", "C UCC", "D 国法大全"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】1804 年法国民法典又称拿破仑法典。【逐步演示】BGB 是德国民法典，UCC 是美国统一商法典。【易错提醒】注意法德法典的不同名称。"}, {"order": 2, "qtype": "single", "stem": "法国民法典第 5 条禁止法官以一般性与规范性规定裁判案件，其目的在于：", "options": ["A 鼓励法官造法", "B 维护分权、禁止司法造法", "C 确立判例优先", "D 引入陪审团"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】第 5 条背景是旧制度法院阻挠改革，旨在维护分权、要求依法典文字适用。【逐步演示】它体现对法官造法的警惕。【易错提醒】不要误读为鼓励法官造法。"}, {"order": 3, "qtype": "blank", "stem": "法国公法领域的最高法院是______。", "options": [], "answer": "", "accepted": ["最高行政法院", "Conseil d'État", "行政法院", "conseil d'etat"], "keywords": [], "explanation": "【答案】最高行政法院（Conseil d'État）。【解题思路】它是法国公法领域最高法院。【逐步演示】民刑领域最高法院是 Cour de Cassation。【易错提醒】与德国联邦宪法法院区分。"}, {"order": 4, "qtype": "judge", "stem": "法国最高法院（Cour de Cassation）的判决风格近几十年来已变得与德国判决一样详尽且大量引用先例。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出 Cour de Cassation 的风格至今未变，仍极简且不引先例。【逐步演示】巴黎上诉法院自七十年代末提供更详尽理由，但最高法院不然。【易错提醒】区分不同审级法院。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，法国法律传统的特征包括：", "options": ["A 简明通俗的法典", "B 议会立法至上与法官抑制", "C 民刑与行政双轨法院体系", "D 极简且不引先例的判决风格"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为法国法特征。【逐步演示】它们共同构成法国法的制度文化。【易错提醒】不要把『判决极简』理解为没有政策思考。"}, {"order": 6, "qtype": "single", "stem": "Mitchell Lasser 用哪一概念描述法国政策论证与判决文本相分离的现象？", "options": ["A 法律刺激物", "B 二元划分（Bifurcation）", "C 幽灵陪审团", "D 司法自动售货机"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Lasser 以『二元划分』描述政策论证在判决之外的现象。【逐步演示】证据见于报告法官与总检察长意见。【易错提醒】与其他学者的比喻区分。"}, {"order": 7, "qtype": "essay", "stem": "结合 Lasser 的『二元划分』理论，分析法国极简判决是否意味着司法推理的缺失。", "options": [], "answer": "", "accepted": [], "keywords": [["极简判决", "几行不引先例学说"], ["二元划分", "政策论证在判决之外"], ["报告法官与总检察长意见", "论证的载体"], ["司法心态差异", "非有无实质审议"]], "explanation": "【答案要点】见 keywords。【解题思路】先描述现象，再引入 Lasser 解释，最后上升到方法论。【逐步演示】引用 Wells 的美国视角作对照。【易错提醒】不要简单断言法国法官『不推理』。"}, {"order": 8, "qtype": "judge", "stem": "Siems 指出，法国民法典以抽象、概念化、教授化的风格著称，与德国民法典相似。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】概念化、教授化是德国民法典风格；法国民法典简明通俗。【逐步演示】Siems 明确对比二者。【易错提醒】这是法德比较的常见考点，切忌混淆。"}, {"order": 9, "qtype": "blank", "stem": "法国合同法中排除责任的事由、Siems 在比较违约赔偿时提到的是______。", "options": [], "answer": "", "accepted": ["不可抗力", "force majeure", "Force Majeure", "不可抗力事由"], "keywords": [], "explanation": "【答案】不可抗力（Force Majeure）。【解题思路】Siems 指出法国法更常区分合同类型，仅在不可抗力时排除损害赔偿。【逐步演示】这与德国过错要求、普通法严格责任对照。【易错提醒】与大陆法一般免责事由区分。"}, {"order": 10, "qtype": "single", "stem": "关于违约金条款，法国民法典第 1152 条允许法院在何种情况下增减违约金？", "options": ["A 任何时候", "B 明显过高或过低时", "C 仅在构成犯罪时", "D 从不调整"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出法国法在违约金明显过高或过低时可增减。【逐步演示】德国法可减至合理数额，普通法则区分罚金与预定损害赔偿。【易错提醒】区分法德调整方式的不同。"}, {"order": 11, "qtype": "multi", "stem": "下列关于法德差异的表述，哪些正确？", "options": ["A 法国法典简明，德国法典概念化", "B 法国判决极简，德国判决学术化", "C 法国最高行政法院宪法职能有限，德国联邦宪法法院权能强大", "D 法国有总则编，德国没有"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三项均为Siems指出的法德差异。【逐步演示】D 说反了：德国民法典有总则编，法国没有。【易错提醒】总则编是德国民法典的特征。"}, {"order": 12, "qtype": "essay", "stem": "以违约金规则为例，比较法国法、德国法与普通法的处理方式的异同。", "options": [], "answer": "", "accepted": [], "keywords": [["法国调整", "明显过高或过低可增减"], ["德国减额", "过高减至合理数额"], ["普通法区分", "罚金无效预定损害赔偿有效"], ["功能相近教义不同", "Sacco 操作规则相似"]], "explanation": "【答案要点】见 keywords。【解题思路】先分述三种制度，再归纳功能与教义的关系。【逐步演示】指出普通法罚金禁令源于对价理论。【易错提醒】不要只罗列差异，须点明功能比较视角。"}]}, "S2M5K5": {"lesson": "S2M5K5", "questions": [{"order": 1, "qtype": "single", "stem": "斯堪的纳维亚国家在传统法律家族分类中通常被归入：", "options": ["A 普通法系", "B 日耳曼大陆法", "C 宗教法系", "D 社会主义法系"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出斯堪的纳维亚国家最常被归入日耳曼大陆法。【逐步演示】但也有理由支持独立分类。【易错提醒】不要误判为普通法系。"}, {"order": 2, "qtype": "single", "stem": "一些分类法把北欧国家单列，主要理由是：", "options": ["A 它们完全不受罗马法影响", "B 它们没有采纳综合性法典", "C 它们使用普通法语言", "D 它们没有法院"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出北欧因未采纳综合法典而被单列。【逐步演示】福利国家模式与立法者互动也支持独立分类。【易错提醒】不要误判为『完全不受罗马法影响』。"}, {"order": 3, "qtype": "judge", "stem": "北欧法律传统以高度抽象、概念化的综合性民法典著称。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】北欧法恰恰缺乏法德式综合法典。【逐步演示】这是其被单列的重要理由。【易错提醒】抽象概念化综合法典是德国民法典特征。"}, {"order": 4, "qtype": "blank", "stem": "北欧法律思维务实、经验主义，受强调法律社会效果的______思潮影响较深。", "options": [], "answer": "", "accepted": ["法律现实主义", "Legal Realism", "现实主义", "斯堪的纳维亚现实主义"], "keywords": [], "explanation": "【答案】法律现实主义（Legal Realism）。【解题思路】北欧法律现实主义关注法律实际运作。【逐步演示】这与 Siems 的社会法学方法相契合。【易错提醒】与美国法律现实主义区分，但有相通之处。"}, {"order": 5, "qtype": "multi", "stem": "支持把北欧法视为独立法律家族的理由包括：", "options": ["A 福利国家模式", "B 立法者之间的密切互动", "C 未采纳综合性法典", "D 与德国法完全没有任何联系"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 列举福利国家模式、立法者互动、无综合法典等理由。【逐步演示】D 走向极端，北欧私法与德国法有历史联系。【易错提醒】不要把独立分类的理由绝对化。"}, {"order": 6, "qtype": "essay", "stem": "论述北欧法律传统的分类地位，并说明它如何体现法律家族分类的相对性。", "options": [], "answer": "", "accepted": [], "keywords": [["传统归类", "日耳曼大陆法族"], ["独立理由", "无综合法典福利国家模式"], ["理想类型", "分类为认知目的服务"], ["交叉地带", "兼有大陆与普通法特征"]], "explanation": "【答案要点】见 keywords。【解题思路】先述两种分类主张，再上升到方法论。【逐步演示】指出分类的目的决定分析单位的选择。【易错提醒】不要给出唯一『正确』归属。"}, {"order": 7, "qtype": "judge", "stem": "Siems 认为，北欧法的分类难题说明法律家族边界清晰、分类结果唯一。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 以此说明法律家族分类的相对性与边界模糊。【逐步演示】法律体系常处于交叉地带。【易错提醒】注意『边界清晰』『唯一』的错误表述。"}, {"order": 8, "qtype": "single", "stem": "北欧法与德国法的主要差异在于：", "options": ["A 北欧有综合法典，德国没有", "B 北欧无综合法典且思维务实，德国概念体系化", "C 两者完全相同", "D 北欧采用陪审团"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】北欧无综合法典、思维务实、受现实主义影响，德国则概念体系化。【逐步演示】两者共享大陆法基因但风格不同。【易错提醒】A 说反了。"}, {"order": 9, "qtype": "blank", "stem": "北欧法的核心组成部分、常指丹麦、瑞典、挪威三国法的是______法。", "options": [], "answer": "", "accepted": ["斯堪的纳维亚", "Scandinavian", "北欧", "斯堪的纳维亚法"], "keywords": [], "explanation": "【答案】斯堪的纳维亚（Scandinavian）。【解题思路】斯堪的纳维亚法是北欧法的核心。【逐步演示】通常指丹麦、瑞典、挪威三国法。【易错提醒】与北欧法概念相近但范围略窄。"}, {"order": 10, "qtype": "blank", "stem": "北欧福利国家模式强调国家主导的______与再分配。", "options": [], "answer": "", "accepted": ["社会保障", "社会福利", "welfare", "社会保障体系"], "keywords": [], "explanation": "【答案】社会保障。【解题思路】Siems 以福利国家模式解释北欧法的独立分类理由。【逐步演示】国家主导社会保障与再分配是其治理特征。【易错提醒】与自由放任模式区分。"}, {"order": 11, "qtype": "single", "stem": "北欧法律中强调法律社会效果的现实主义思潮，又称哪一学派？", "options": ["A 潘德克顿学派", "B 乌普萨拉学派（Uppsala School）", "C 历史法学派", "D 概念法学派"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】北欧法律现实主义又称乌普萨拉学派。【逐步演示】它关注法律的实际运作与社会效果。【易错提醒】与德国潘德克顿学派区分。"}, {"order": 12, "qtype": "judge", "stem": "北欧法在方法论上更接近德国式的概念教义学，而非务实经验主义。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】北欧法思维务实、经验主义，受法律现实主义影响。【逐步演示】这与德国概念教义学形成对照。【易错提醒】不要把北欧法等同于德国法。"}]}, "S2M5K6": {"lesson": "S2M5K6", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 把下列哪一项列为法律家族分类的三大偏向之一？", "options": ["A 过度强调差异", "B 忽视混合体", "C 过度强调共性", "D 以上都是"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】Siems 列出的三大偏向为过度强调差异、过度强调共性与忽视混合体。【逐步演示】混合体系正对应『忽视混合体』。【易错提醒】三项都是，故选 D。"}, {"order": 2, "qtype": "single", "stem": "下列哪一法域最典型地体现大陆法私法与普通法公法的混合？", "options": ["A 纯大陆法的法国", "B 纯普通法的英格兰", "C 私法承法国传统、公法趋同美国的路易斯安那", "D 孤立部落法"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】路易斯安那私法承大陆法、公法趋同普通法，是混合体系典型。【逐步演示】魁北克、苏格兰、南非亦为混合体。【易错提醒】不要把混合视为异常。"}, {"order": 3, "qtype": "judge", "stem": "Siems 断言，今天世界上有少数纯粹的法律体系，其余都是混合的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 的论断是『不存在纯粹的法律体系』，所有体系都在吸收各地观念。【逐步演示】他把混合提升为常态而非少数例外。【易错提醒】注意『存在少数纯粹体系』与题干不符。"}, {"order": 4, "qtype": "blank", "stem": "指同一社会中存在多个法律秩序并存的现象，称为法律______主义。", "options": [], "answer": "", "accepted": ["多元", "pluralism", "法律多元", "legal pluralism"], "keywords": [], "explanation": "【答案】多元（Legal Pluralism）。【解题思路】法律多元主义指国家法与习惯法、宗教法等并存。【逐步演示】它与混合体系相关但侧重不同。【易错提醒】与混合法律体系区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，混合法律体系的主要形式包括：", "options": ["A 大陆法与普通法的混合", "B 西方传统与宗教法的混合", "C 西方传统与习惯法的混合", "D 一种传统内部的自我演化"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 提到混合的多种形式，包括大陆/普通法、西方/宗教法、西方/习惯法。【逐步演示】D 不是混合体系的定义。【易错提醒】注意混合须涉及两种以上传统。"}, {"order": 6, "qtype": "single", "stem": "Siems 提到，在非洲西方传统与习惯法混合的语境下，原初不成文的习惯法形态称为：", "options": ["A 法典化习惯法", "B 教科书习惯法", "C 活的习惯法（living customary law）", "D 宗教习惯法"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】活的习惯法是原初的不成文形态。【逐步演示】此外还有教科书习惯法、法典化习惯法等类型。【易错提醒】区分不同类型的习惯法。"}, {"order": 7, "qtype": "essay", "stem": "论述混合法律体系对法律家族分类的挑战及其理论意义。", "options": [], "answer": "", "accepted": [], "keywords": [["挑战标签", "单一归类遮蔽一半事实"], ["理想类型", "分类为认知目的服务"], ["常态化", "不存在纯粹法律体系"], ["方法论窗口", "观察传统接触移植变形"]], "explanation": "【答案要点】见 keywords。【解题思路】先述挑战，再述 Siems 立场，最后上升到理论意义。【逐步演示】以路易斯安那为例说明标签限度。【易错提醒】不要走向『分类完全失败』的极端。"}, {"order": 8, "qtype": "judge", "stem": "混合体系应被视为法律分类中的异常例外，比较法应把它们排除在常规研究之外。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 主张把混合体视为常态并正视之，而非排除。【逐步演示】『忽视混合体』正是他所批判的偏向。【易错提醒】警惕『异常例外』『排除』等表述。"}, {"order": 9, "qtype": "single", "stem": "在 Siems 看来，研究混合体系时最有价值的方法是：", "options": ["A 只看法律条文的字面", "B 从具体问题入手的功能主义方法", "C 完全放弃比较", "D 只研究法律史"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】传统标签失效时，功能主义从问题入手考察不同传统如何搭配运作。【逐步演示】Siems 主张把混合体作为检验分类边界的试金石。【易错提醒】不要误选『放弃比较』。"}, {"order": 10, "qtype": "blank", "stem": "源于荷兰、在南非等地沿用的大陆法传统称为______法。", "options": [], "answer": "", "accepted": ["罗马-荷兰", "罗马荷兰", "Roman-Dutch", "罗马—荷兰"], "keywords": [], "explanation": "【答案】罗马—荷兰法（Roman-Dutch Law）。【解题思路】它是南非混合体系中的大陆法成分。【逐步演示】与普通法成分并存形成混合。【易错提醒】与荷兰法、德国法区分。"}, {"order": 11, "qtype": "judge", "stem": "法律多元主义与混合法律体系是完全相同的概念。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】二者相关但不同：前者指多个法律秩序并存，后者指一个体系内融合多种传统。【逐步演示】混合常是法律多元制度化的结果。【易错提醒】注意『完全相同』的表述。"}, {"order": 12, "qtype": "single", "stem": "下列哪一国家以罗马—荷兰法与普通法并存而成为混合体系典型？", "options": ["A 法国", "B 南非", "C 德国", "D 日本"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】南非融合罗马—荷兰法与普通法，是混合体系典型。【逐步演示】Siems 在分类中提及苏格兰、南非等混合体。【易错提醒】与路易斯安那、魁北克区分。"}]}, "S2M5K7": {"lesson": "S2M5K7", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 指出，西方法律传统区别于宗教与部落共同体法律的具体因素之一是：", "options": ["A 法律与宗教的分离", "B 宗教经典的统治", "C 部落法院的普遍设立", "D 习惯法的成文化"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 把法律与宗教的分离列为西方法律的具体因素。【逐步演示】他还列出人权、法治、理性法、专门法律职业等。【易错提醒】不要把这一区分绝对化。"}, {"order": 2, "qtype": "single", "stem": "Siems 指出，普通法与哪一法律传统都基于分权化的制度体系，因而存在可比之处？", "options": ["A 印度教法", "B 伊斯兰法", "C 犹太法", "D 教会法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出普通法与伊斯兰法都基于分权化的制度体系。【逐步演示】这一洞见提示宗教法与现代法律并非截然对立。【易错提醒】与其他宗教法区分。"}, {"order": 3, "qtype": "blank", "stem": "基于长期形成的习俗与惯例、而非成文立法的法律称为______法。", "options": [], "answer": "", "accepted": ["习惯", "customary", "Customary Law", "习惯法"], "keywords": [], "explanation": "【答案】习惯（Customary Law）。【解题思路】习惯法基于习俗惯例而非成文立法。【逐步演示】在非洲等地与国家法长期共存。【易错提醒】与宗教法、国家制定法区分。"}, {"order": 4, "qtype": "multi", "stem": "Siems 提到的习惯法类型包括：", "options": ["A 活的习惯法", "B 教科书习惯法", "C 法典化习惯法", "D 纯粹成文的议会立法"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 区分活的习惯法、教科书习惯法、法典化习惯法等类型。【逐步演示】它们展示习惯法的不同形态。【易错提醒】议会立法不属于习惯法。"}, {"order": 5, "qtype": "judge", "stem": "Siems 认为，宗教法与传统法只是历史遗存，在当代世界已不再具有实际功能。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 把宗教法与传统法视为当代比较法必须严肃对待的现象。【逐步演示】它们在家庭、继承、基层纠纷解决中持续发挥作用。【易错提醒】警惕『已无功能』的断言。"}, {"order": 6, "qtype": "single", "stem": "同一社会中国家法、宗教法与习惯法并存的现象称为：", "options": ["A 法律移植", "B 法律多元主义", "C 法律趋同", "D 法典化"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法律多元主义指多个法律秩序在同一社会并存。【逐步演示】宗教法、习惯法与国家法可分域调整。【易错提醒】与混合法律体系相关但侧重不同。"}, {"order": 7, "qtype": "essay", "stem": "论述宗教法与传统法在当代世界的地位，以及比较法应如何处理普遍标准与文化语境的关系。", "options": [], "answer": "", "accepted": [], "keywords": [["当代地位", "家庭继承商事持续作用"], ["非历史遗存", "活的习惯法与功能"], ["普遍主义与文化相对主义", "张力与中间路线"], ["语境化方法", "放回社会文化环境"]], "explanation": "【答案要点】见 keywords。【解题思路】先述地位，再述争论，最后落到语境化方法。【逐步演示】引用普通法与伊斯兰法可比性、非洲习惯法类型。【易错提醒】避免西方中心主义的简单裁断。"}, {"order": 8, "qtype": "judge", "stem": "Siems 主张以西方现代法治标准简单评判宗教法与传统法的优劣。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 反对西方中心的简单裁断，主张理解法律的社会语境。【逐步演示】他批判西方化的简单化叙述。【易错提醒】他也不回避价值问题，但不是简单评判。"}, {"order": 9, "qtype": "blank", "stem": "以古兰经与圣训为基础、在穆斯林国家发挥重要作用的宗教法是______法。", "options": [], "answer": "", "accepted": ["伊斯兰", "Islamic", "Sharia", "伊斯兰法", "沙里亚"], "keywords": [], "explanation": "【答案】伊斯兰（Islamic Law / Sharia）。【解题思路】伊斯兰法以古兰经与圣训为基础。【逐步演示】在家庭、继承、金融等领域持续发挥作用。【易错提醒】与教会法、犹太法区分。"}, {"order": 10, "qtype": "single", "stem": "Siems 在讨论宗教法分类时指出，宗教的分类可从下列哪些主要类别入手？", "options": ["A 亚伯拉罕诸教、印度宗教与东亚宗教", "B 大陆法、普通法与习惯法", "C 公法、私法与刑法", "D 成文法、判例法与习惯法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 指出宗教分类可从亚伯拉罕诸教、印度宗教与东亚宗教入手。【逐步演示】B、C、D 是法律而非宗教的分类。【易错提醒】注意题干问的是宗教分类。"}, {"order": 11, "qtype": "blank", "stem": "基督教教会制定的法律体系称为______法。", "options": [], "answer": "", "accepted": ["教会", "canon", "Canon Law", "教会法"], "keywords": [], "explanation": "【答案】教会（Canon Law）。【解题思路】教会法是基督教教会制定的法律体系。【逐步演示】Siems 把它列为宗教法类型之一。【易错提醒】与伊斯兰法、犹太法区分。"}, {"order": 12, "qtype": "judge", "stem": "习惯法通常是成文的议会立法，由立法机关制定。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】习惯法基于长期习俗惯例，多为不成文，非议会制定。【逐步演示】Siems 区分活的习惯法、法典化习惯法等类型。【易错提醒】与国家制定法区分。"}]}, "S2M6K1": {"lesson": "S2M6K1", "questions": [{"order": 1, "qtype": "single", "stem": "德国上诉制度中，上级法院可替代下级法院裁判的模式称为：", "options": ["A 撤销模型（Cassation Model）", "B 再审模型（Revision Model）", "C 陪审模型", "D 参审模型"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德国采再审模型，上级法院可替代下级裁判。【逐步演示】法国采撤销模型，仅撤销并发回。【易错提醒】区分德法两种上诉模式。"}, {"order": 2, "qtype": "single", "stem": "法国上诉制度中，上级法院只能撤销下级裁判并发回重审的模式称为：", "options": ["A 再审模型", "B 撤销模型（Cassation Model）", "C 合议模型", "D 独任模型"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法国撤销模型只允许上级法院撤销并发回。【逐步演示】德国再审模型则可替代下级裁判。【易错提醒】注意德法模式的区别。"}, {"order": 3, "qtype": "judge", "stem": "大陆法国家的上诉法院通常只能审查法律问题，不能重新审查案件事实。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出大陆法上诉更广泛，第一级上诉可复审法律与事实。【逐步演示】普通法上诉通常不能重新审查事实。【易错提醒】题干把两大法系说反了。"}, {"order": 4, "qtype": "blank", "stem": "德国 1924 年废除陪审团，代之以由职业法官与非职业法官共同组成合议庭的______制度。", "options": [], "answer": "", "accepted": ["参审员", "Schöffen", "参审", "参审制"], "keywords": [], "explanation": "【答案】参审员（Schöffen）。【解题思路】德国以参审员制度取代陪审团。【逐步演示】参审员既决定事实也决定法律，与英美陪审团不同。【易错提醒】与陪审团区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，大陆法国家法院组织的特征包括：", "options": ["A 按领域设专门法院", "B 上诉可复审事实", "C 法官为职业公务员", "D 合议庭审判较常见"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为大陆法法院组织特征。【逐步演示】德国有行政、劳动、社保、税务等专门法院。【易错提醒】独任审判较常见是普通法特征。"}, {"order": 6, "qtype": "single", "stem": "Damaska 用哪一概念概括大陆法权威组织的理想类型？", "options": ["A 协调制（horizontal）理想", "B 等级制（vertical）理想", "C 分散制理想", "D 参与制理想"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Damaska 以等级制理想概括大陆法、协调制理想概括普通法。【逐步演示】他还从集中/分散、协调/保护维度构建矩阵。【易错提醒】注意两者对应关系。"}, {"order": 7, "qtype": "essay", "stem": "比较德法上诉模式的差异，并说明其与法官组织方式的内在关联。", "options": [], "answer": "", "accepted": [], "keywords": [["德国再审模型", "上级可替代下级裁判"], ["法国撤销模型", "仅撤销并发回"], ["等级制与问责", "职业法官层级结构"], ["分权与效率", "两种模式不同价值"]], "explanation": "【答案要点】见 keywords。【解题思路】先述差异，再解释制度逻辑。【逐步演示】指出大陆法职业法官层级结构使复审合理。【易错提醒】不要停留在制度描述，须追问功能与价值。"}, {"order": 8, "qtype": "judge", "stem": "普通法国家传统上不区分私法与公法法院，国家在民事赔偿中时常只是普通当事人。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出普通法国家传统上不区分公私法院。【逐步演示】国家在普通管辖法院中作为普通一方。【易错提醒】这与大陆法的专门行政法院形成对照。"}, {"order": 9, "qtype": "blank", "stem": "法国公法领域的最高法院是______，其宪法职能较德国联邦宪法法院有限。", "options": [], "answer": "", "accepted": ["最高行政法院", "Conseil d'État", "行政法院", "conseil d'etat"], "keywords": [], "explanation": "【答案】最高行政法院（Conseil d'État）。【解题思路】它是法国公法最高法院，宪法职能较德国有限。【逐步演示】德国联邦宪法法院权能强大。【易错提醒】与法国最高法院 Cour de Cassation 区分。"}, {"order": 10, "qtype": "single", "stem": "Siems 用哪一说法说明陪审团虽在形式上消亡、仍塑造普通法审判？", "options": ["A 法律刺激物", "B 幽灵陪审团（phantom jury）", "C 司法自动售货机", "D 二元划分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 以『幽灵陪审团』说明陪审团的结构性遗产。【逐步演示】它帮助理解口头原则与集中审理。【易错提醒】其他比喻分属不同学者与议题。"}, {"order": 11, "qtype": "multi", "stem": "根据 Siems，普通法国家法院组织的特征包括：", "options": ["A 传统上不区分公私法院", "B 上诉通常不涉及事实", "C 法官多为独立专业人士", "D 陪审团历史上用于民事刑事"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为普通法法院组织特征。【逐步演示】美国保留民事陪审团，英格兰已基本取消。【易错提醒】专门法院是大陆法特征。"}, {"order": 12, "qtype": "essay", "stem": "结合专门法院的设置，分析法院组织与法律治理理念之间的关系。", "options": [], "answer": "", "accepted": [], "keywords": [["大陆专门法院", "德国行政劳动社保税务"], ["普通法无公私之分", "国家为普通当事人"], ["律师专业化替代", "solicitors barristers"], ["等级制与协调制", "Damaska 治理理念"]], "explanation": "【答案要点】见 keywords。【解题思路】从专门法院差异上升到治理理念。【逐步演示】指出普通法以律师专业化替代专门法院。【易错提醒】不要孤立看制度，须联系整体法律方法。"}]}, "S2M6K2": {"lesson": "S2M6K2", "questions": [{"order": 1, "qtype": "single", "stem": "Siems 指出，今天普通法国家在制定法方面的状况可概括为：", "options": ["A 完全没有制定法", "B 进入『成文法时代』", "C 制定法完全取代判例", "D 只承认判例"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出普通法国家已进入 age of statutes。【逐步演示】但制定法在概念上仍常被视次要，判例仍是基础。【易错提醒】不要误判为制定法完全取代判例。"}, {"order": 2, "qtype": "judge", "stem": "MacCormick 与 Summers 的研究发现，大陆法法院详细讨论先例并仔细考量事实，而普通法法院倾向于把裁判化约为法律原则。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】题干把两者说反了。【逐步演示】普通法法院详细讨论先例与事实，大陆法法院化约为原则。【易错提醒】这是先例比较研究的核心考点。"}, {"order": 3, "qtype": "blank", "stem": "先例中具有约束力的核心法律理由称为______。", "options": [], "answer": "", "accepted": ["判决理由", "ratio decidendi", "Ratio Decidendi", "判决要旨"], "keywords": [], "explanation": "【答案】判决理由（Ratio Decidendi）。【解题思路】它与无约束力的附带意见相对。【逐步演示】识别先例须区分二者。【易错提醒】obiter dicta 是附带意见。"}, {"order": 4, "qtype": "single", "stem": "Siems 指出，普通法的法典化（如 UCC）与大陆法法典化的主要区别在于：", "options": ["A 普通法完全无法典化", "B 普通法法典多为对既有判例的整合", "C 大陆法法典都是判例汇编", "D 两者没有任何区别"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出普通法法典化多为对既有判例的整合。【逐步演示】UCC 受大陆法起草风格影响，是例外。【易错提醒】不要误判为普通法完全无法典化。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，普通法制定法解释的传统规则包括：", "options": ["A 字面规则（literal rule）", "B 黄金规则（golden rule）", "C 瑕疵规则（mischief rule）", "D 完全排斥目的解释"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 列举字面、黄金、瑕疵三种解释规则。【逐步演示】他还指出解释已逐渐转向立法史与目的。【易错提醒】D 与趋势不符。"}, {"order": 6, "qtype": "essay", "stem": "论述判例制度与成文法制度的真实差异与趋同，并说明为何不能把二者绝对化。", "options": [], "answer": "", "accepted": [], "keywords": [["真实差异", "渊源推理法官角色判决风格"], ["趋同表现", "大陆判例上升普通法成文法时代"], ["解释方法靠拢", "Vogenauer 比较研究"], ["程度非类别", "都平衡确定性与灵活性"]], "explanation": "【答案要点】见 keywords。【解题思路】先述差异，再述趋同，最后上升到方法论。【逐步演示】引用 MacCormick-Summers 与 Vogenauer 研究。【易错提醒】不要走向『已无差别』的极端。"}, {"order": 7, "qtype": "single", "stem": "Vogenauer 对法国、德国、英格兰制定法解释的比较研究发现：", "options": ["A 三国解释方法完全不同", "B 三国起点不同但实际使用相似的论证组合", "C 英格兰完全不用目的解释", "D 法国完全不用字面解释"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Vogenauer 发现三国虽起点不同，实际使用相似的正式与价值导向论证组合。【逐步演示】这支持趋同论。【易错提醒】不要误判为完全不同。"}, {"order": 8, "qtype": "judge", "stem": "在法国传统中，拿破仑法典的制定目的之一是防止法官造法，因此法院判决传统上不具正式约束力。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出拿破仑法典旨在防止法官造法，判决非渊源。【逐步演示】但一些大陆法国家有特别法赋予最高法院判决约束力。【易错提醒】注意『传统上』的限定。"}, {"order": 9, "qtype": "blank", "stem": "由 Karl Llewellyn 等人主导起草、被美国各州广泛采纳的普通法法典是______。", "options": [], "answer": "", "accepted": ["统一商法典", "UCC", "Uniform Commercial Code", "UCC 统一商法典"], "keywords": [], "explanation": "【答案】统一商法典（UCC）。【解题思路】UCC 由 Llewellyn 主导起草，被各州采纳。【逐步演示】Siems 指出其起草风格受大陆法影响。【易错提醒】与 Field 的民事诉讼法典区分。"}, {"order": 10, "qtype": "single", "stem": "Duncan Kennedy 提出『法律思想的三次全球化』，其中十九世纪的古典法律思想以哪国概念为基础？", "options": ["A 法国", "B 德国", "C 美国", "D 英国"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Kennedy 的古典法律思想（1850—1914）以德国法律科学概念为基础。【逐步演示】社会阶段由法国学术驱动，政策分析由美国学术驱动。【易错提醒】区分三个阶段的代表国家。"}, {"order": 11, "qtype": "multi", "stem": "根据 Siems，下列哪些观点质疑了『大陆法官机械适用法律』的刻板印象？", "options": ["A Martin Shapiro 称之为根本错误", "B Markesinis 与 Fedtke 称不准确", "C 一般条款使法官增量发展法律", "D 大陆法官完全不受任何约束"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三项均为 Siems 引述的质疑。【逐步演示】他同时指出普通法法官也受宽泛原则约束。【易错提醒】D 走向另一极端，错误。"}, {"order": 12, "qtype": "essay", "stem": "以 UCC 为例，说明普通法成文法化的特点及其对两大法系趋同的意义。", "options": [], "answer": "", "accepted": [], "keywords": [["UCC 起草", "Llewellyn 主导受大陆法影响"], ["整合判例", "普通法典化特点"], ["成文法时代", "普通法制定法激增"], ["趋同有限", "判例仍为基础"]], "explanation": "【答案要点】见 keywords。【解题思路】以 UCC 为切口说明特点与意义。【逐步演示】指出普通法法典化多为判例整合，与大陆法不同。【易错提醒】不要夸大趋同程度。"}]}, "S2M6K3": {"lesson": "S2M6K3", "questions": [{"order": 1, "qtype": "single", "stem": "普通法中合同成立所需的、当事人交换有价值之物的要素称为：", "options": ["A 善意（good faith）", "B 对价（consideration）", "C 意思表示合意", "D 实际履行"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】对价是普通法合同成立的核心要素。【逐步演示】赠与因无对价，须以契据形式才有约束力。【易错提醒】大陆法无对价概念。"}, {"order": 2, "qtype": "judge", "stem": "Sacco 的赠与例子表明，英格兰法与法国法对赠与的操作规则相似，但解释它们的教义装置完全相反。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Sacco 以此说明功能相似而教义装置相反。【逐步演示】英法对正式赠与的有效性给出相反理由。【易错提醒】这是功能比较的经典例证。"}, {"order": 3, "qtype": "blank", "stem": "大陆法中以德国民法典第 311 条第 2 款为代表、把缔约前关系纳入债的关系的责任称为______。", "options": [], "answer": "", "accepted": ["缔约过失", "culpa in contrahendo", "缔约过失责任", "前合同责任"], "keywords": [], "explanation": "【答案】缔约过失（Culpa in Contrahendo）。【解题思路】BGB §311(2) 使善意原则适用于缔约前关系。【逐步演示】法国依侵权法、荷兰依公平原则处理类似问题。【易错提醒】与违约责任区分。"}, {"order": 4, "qtype": "single", "stem": "Teubner 把善意原则移植到普通法称为：", "options": ["A 幽灵陪审团", "B 法律刺激物（legal irritant）", "C 司法自动售货机", "D 二元划分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Teubner 以『法律刺激物』描述善意移植的扰动效应。【逐步演示】他认为善意是大陆法律文化的独特表达。【易错提醒】与其他比喻区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，普通法中承担善意类似功能的机制包括：", "options": ["A 默示条款", "B 对显失公平交易的衡平救济", "C 消费者保护立法", "D 一般善意原则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】普通法靠默示条款、衡平救济与消费者保护立法达致公平。【逐步演示】D 一般善意原则正是普通法长期拒斥的。【易错提醒】注意普通法没有一般善意原则。"}, {"order": 6, "qtype": "essay", "stem": "比较两大法系在合同救济上的差异：实际履行、过错要件与违约金，并说明功能比较的视角。", "options": [], "answer": "", "accepted": [], "keywords": [["实际履行", "大陆原则对普通法损害赔偿与有效违约"], ["过错要件", "德国过错法国不可抗力普通法严格责任"], ["违约金", "大陆允许调整对普通法罚金两分"], ["功能趋同", "起点不同结果常相似"]], "explanation": "【答案要点】见 keywords。【解题思路】分三主题对照，再上升到功能比较。【逐步演示】引用 Holmes、Alderslade、UCC §2-716 等材料。【易错提醒】不要只罗列差异，须指出结果常相似。"}, {"order": 7, "qtype": "single", "stem": "Holmes 关于普通法守约义务的著名说法是：", "options": ["A 守约就是道德义务", "B 守约义务只是不守约就赔钱的预测", "C 必须实际履行", "D 违反合同构成犯罪"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Holmes 说普通法上守约义务只是『不守约就赔钱』的预测。【逐步演示】这为有效违约提供理论基础。【易错提醒】与实际履行原则区分。"}, {"order": 8, "qtype": "judge", "stem": "Common Core 项目关于善意的研究显示，三十个案例中欧洲各国结果完全一致，没有任何分歧。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】研究显示十一个相同、九个大体和谐、十个显著分歧。【逐步演示】英格兰法常常但并非总是走自己的路。【易错提醒】不要夸大趋同程度。"}, {"order": 9, "qtype": "blank", "stem": "1945 年 Alderslade v Hendon Laundry 案体现了普通法合同责任的起点是______责任。", "options": [], "answer": "", "accepted": ["严格", "strict", "严格责任", "无过错"], "keywords": [], "explanation": "【答案】严格（Strict）。【解题思路】该案表明洗衣公司须对未洗好衣物负责，不以尽到注意抗辩。【逐步演示】体现普通法严格责任起点。【易错提醒】与大陆法过错责任对照。"}, {"order": 10, "qtype": "single", "stem": "美国 UCC 第 2-716 条允许在何种情形下判实际履行？", "options": ["A 任何违约", "B 物品独特或其他适当情形", "C 仅在消费者合同", "D 从不"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】UCC §2-716 允许在物品独特或其他适当情形下判实际履行。【逐步演示】这是普通法实际履行原则的例外。【易错提醒】不要以为普通法完全不适用实际履行。"}, {"order": 11, "qtype": "multi", "stem": "关于违约金条款，下列说法正确的包括：", "options": ["A 大陆法原则上允许并可调整", "B 德国法可减至合理数额", "C 法国法在明显过高或过低时可增减", "D 普通法区分罚金与预定损害赔偿"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均符合 Siems 的论述。【逐步演示】普通法因对价理论，罚金条款无效、预定损害赔偿有效。【易错提醒】注意法德调整方式的不同。"}, {"order": 12, "qtype": "essay", "stem": "结合 Sacco 的赠与例子与 Common Core 研究，分析功能比较在合同法中的价值与限度。", "options": [], "answer": "", "accepted": [], "keywords": [["功能等价", "操作规则相似"], ["教义差异", "概念装置相反"], ["经验研究", "三十案例结果分布"], ["价值限度", "功能相似不意味机制相同"]], "explanation": "【答案要点】见 keywords。【解题思路】以两个材料为支点展开。【逐步演示】指出功能比较揭示结果趋同，但不能抹平教义与文化差异。【易错提醒】不要只肯定或只否定功能比较。"}]}, "S2M6K4": {"lesson": "S2M6K4", "questions": [{"order": 1, "qtype": "single", "stem": "大陆法中物权种类由法律限定、当事人不得自由创设的原则称为：", "options": ["A 物权法定（Numerus Clausus）", "B 契约自由", "C 信托", "D 先占"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】物权法定原则限定物权种类，保障交易安全。【逐步演示】普通法通过判例发展的权益类型也有类似功能。【易错提醒】与契约自由区分。"}, {"order": 2, "qtype": "single", "stem": "关于信托与大陆法的关系，Siems 的观点是：", "options": ["A 信托是普通法独有、大陆法完全无法类比", "B 两大法系在类信托安排上并无根本不同", "C 信托只能存在于英格兰", "D 信托已从大陆法消失"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 明确指出两大法系在类信托安排类型上并无根本不同。【逐步演示】功能相近但概念化方式不同。【易错提醒】不要误判为信托是普通法独有。"}, {"order": 3, "qtype": "judge", "stem": "Siems 指出，Glenn 在描述英格兰法时提到信托法的罗马渊源，说明信托与大陆法并非毫无历史关联。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 引 Glenn 提到信托的罗马渊源（fideicommissum）。【逐步演示】这说明信托并非纯粹土生土长。【易错提醒】与信托移植的教义障碍并不矛盾。"}, {"order": 4, "qtype": "blank", "stem": "普通法中受托人为受益人管理财产、实现所有权与受益权分离的制度称为______。", "options": [], "answer": "", "accepted": ["信托", "trust", "Trust", "信托制度"], "keywords": [], "explanation": "【答案】信托（Trust）。【解题思路】信托实现普通法所有权与衡平法所有权分离。【逐步演示】它源于英格兰中世纪用益制度。【易错提醒】与大陆法用益权区分。"}, {"order": 5, "qtype": "multi", "stem": "根据本节，两大法系财产权制度的差异体现在：", "options": ["A 所有权观念", "B 物权类型限定方式", "C 财产管理制度", "D 概念化方式"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为两大法系财产权制度的差异维度。【逐步演示】但功能上常有等价安排。【易错提醒】差异不等于无法比较。"}, {"order": 6, "qtype": "essay", "stem": "以信托为例，论述财产权比较中功能与教义两个层面的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["功能等价", "财产管理受益人保护"], ["教义障碍", "双重所有权难纳入大陆法"], ["移植难题", "概念翻译困难"], ["功能非概念兼容", "Siems 审慎立场"]], "explanation": "【答案要点】见 keywords。【解题思路】从信托的功能与教义两面展开。【逐步演示】引用海牙信托公约与 Siems 的移植观点。【易错提醒】不要只谈功能等价而忽略教义障碍。"}, {"order": 7, "qtype": "single", "stem": "信托制度源于中世纪英格兰的哪一制度？", "options": ["A 用益（use）制度", "B 封建军事制度", "C 陪审团", "D 令状"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】信托源于中世纪英格兰的用益（use）制度。【逐步演示】为规避封建负担，财产转移给受托人。【易错提醒】与其他普通法制度区分。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，功能上的等价意味着信托的概念可以直接移植到大陆法而不产生任何问题。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 强调功能等价不等于概念兼容。【逐步演示】信托的双重所有权结构在大陆法中缺乏对应范畴。【易错提醒】不要混淆功能与概念两个层面。"}, {"order": 9, "qtype": "blank", "stem": "普通法信托中受托人享有的是______法所有权，受益人享有衡平法所有权。", "options": [], "answer": "", "accepted": ["普通", "common law", "普通法", "legal"], "keywords": [], "explanation": "【答案】普通（Common Law）。【解题思路】信托结构为普通法所有权与衡平法所有权分离。【逐步演示】这使其在大陆法中缺乏精确对应。【易错提醒】与大陆法所有权观念区分。"}, {"order": 10, "qtype": "single", "stem": "关于信托的跨法域传播，Siems 提到哪一国际文件反映了大陆法国家承认信托的努力？", "options": ["A 1985 年海牙信托公约", "B 法国民法典", "C 德国民法典", "D UCC"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】1985 年海牙信托公约反映大陆法国家承认信托的努力。【逐步演示】但纳入本土框架时遇到概念困难。【易错提醒】与其他法律文件区分。"}, {"order": 11, "qtype": "single", "stem": "大陆法中的用益权（Usufruct）是指：", "options": ["A 对物的完全所有权", "B 在他人之物上设定的使用收益权利", "C 一种刑事处罚", "D 合同的违约金"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】用益权是在他人之物上设定的使用收益权利。【逐步演示】它是大陆法他物权的一种，可承担类似信托的部分功能。【易错提醒】与所有权、信托区分。"}, {"order": 12, "qtype": "judge", "stem": "先占（Occupation）是两大法系中都存在的取得无主物所有权的方式。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】先占是通过占有无主物取得所有权的方式，为各法系共有。【逐步演示】Siems 指出财产权制度共享基本划分。【易错提醒】注意与登记、交付等取得方式区分。"}]}, "S2M6K5": {"lesson": "S2M6K5", "questions": [{"order": 1, "qtype": "single", "stem": "关于两大法系的侵权法，Siems 指出它们：", "options": ["A 完全没有任何共同点", "B 把私法划分为财产侵权合同等领域并以相似方式分析", "C 只有普通法有侵权法", "D 只有大陆法有侵权法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出各体系共享私法的基本划分并以相似方式分析。【逐步演示】差异主要在结构与概念工具。【易错提醒】不要误判为毫无共性。"}, {"order": 2, "qtype": "single", "stem": "普通法侵权法的体系结构特征主要是：", "options": ["A 以民法典一般条款统摄", "B 由 negligence、trespass 等独立侵权类型构成", "C 完全依赖成文法典", "D 没有侵权责任"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】普通法侵权法由独立侵权类型构成，从业经验主义。【逐步演示】大陆法以一般条款统摄。【易错提醒】不要把大陆法结构安到普通法上。"}, {"order": 3, "qtype": "blank", "stem": "普通法中用于限定责任范围、强调损害是否可合理预见的概念是______。", "options": [], "answer": "", "accepted": ["可预见性", "foreseeability", "Foreseeability", "可预见"], "keywords": [], "explanation": "【答案】可预见性（Foreseeability）。【解题思路】它是普通法限定责任范围的概念。【逐步演示】Palsgraf 案是其体现。【易错提醒】与大陆法法规目的理论区分。"}, {"order": 4, "qtype": "judge", "stem": "Siems 指出，侵权法的实际运作与诉讼率、陪审团、风险代理、保险体系等制度环境密切相关。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是 Siems 社会法学方法的核心主张。【逐步演示】他比较美英德荷日的诉讼率差异。【易错提醒】侵权法效果不能脱离制度环境理解。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，侵权法的功能包括：", "options": ["A 补偿受害人", "B 威慑不当行为", "C 损失分散", "D 完全排斥保险机制"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】补偿、威慑、损失分散是侵权法主要功能。【逐步演示】D 与损失分散功能相悖。【易错提醒】注意功能多元。"}, {"order": 6, "qtype": "single", "stem": "Siems 用哪一概念概括美国法律风格，认为其侵权法尤为激进？", "options": ["A 法律实证主义", "B 对抗性法治主义（adversarial legalism）", "C 形式主义", "D 社群主义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Kagan 以『对抗性法治主义』概括美国风格，Siems 引用之。【逐步演示】它体现于陪审团、风险代理、集体诉讼。【易错提醒】与其他法理学概念区分。"}, {"order": 7, "qtype": "essay", "stem": "比较普通法类型化侵权与大陆法一般条款的结构差异，并说明功能比较的视角。", "options": [], "answer": "", "accepted": [], "keywords": [["普通法类型化", "独立侵权类型个案类推"], ["大陆法一般条款", "法 1382 德 823 原则演绎"], ["归责原则", "过失到严格责任扩展"], ["功能相通", "救济分配威慑共同目标"]], "explanation": "【答案要点】见 keywords。【解题思路】先述结构差异，再述功能相通。【逐步演示】引用法国民法典 1382 条、德国 823 条。【易错提醒】不要走向『完全相同』或『毫无共性』的两端。"}, {"order": 8, "qtype": "judge", "stem": "Siems 指出，美国侵权法中的惩罚性赔偿与责任扩张，与陪审团、风险代理和集体诉讼等制度密切相关。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出这些制度共同塑造美国侵权的激进风格。【逐步演示】形成『诉讼人激进主义』。【易错提醒】注意这是美国特性，非所有普通法国家。"}, {"order": 9, "qtype": "blank", "stem": "法国民法典第 1382 条是侵权法中的______条款，任何人因过错致他人损害应负赔偿责任。", "options": [], "answer": "", "accepted": ["一般", "一般条款", "general clause", "概括"], "keywords": [], "explanation": "【答案】一般（General Clause）。【解题思路】法国民法典 1382 条是过错责任的一般条款。【逐步演示】德国民法典 823 条结构更精细。【易错提醒】与普通法类型化结构区分。"}, {"order": 10, "qtype": "single", "stem": "Siems 在社会法学章节中比较侵权法时提到的经验问题之一是：", "options": ["A 各国诉讼率差异", "B 完全无差异", "C 侵权法不存在于大陆法", "D 侵权法与社会保障无关"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 在社会法学章节讨论诉讼率、责任扩张等经验问题。【逐步演示】涉及美英德荷日等国的比较。【易错提醒】不要误判为侵权法无差异或与社保无关。"}, {"order": 11, "qtype": "blank", "stem": "德国民法典中作为侵权责任一般条款的是第______条。", "options": [], "answer": "", "accepted": ["823", "第823条", "§823", "823条"], "keywords": [], "explanation": "【答案】823。【解题思路】德国民法典第 823 条是侵权责任的一般条款。【逐步演示】其结构较法国民法典第 1382 条更精细。【易错提醒】与法国民法典 1382 条区分。"}, {"order": 12, "qtype": "judge", "stem": "普通法侵权法以民法典中的一般条款统摄各类侵权行为。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】以一般条款统摄侵权是大陆法特征；普通法由独立侵权类型构成。【逐步演示】Siems 强调二者结构差异。【易错提醒】注意把两大法系说反了。"}]}, "S2M6K6": {"lesson": "S2M6K6", "questions": [{"order": 1, "qtype": "single", "stem": "普通法国家刑事程序传统的典型模式是：", "options": ["A 职权主义（Inquisitorial）", "B 对抗制（Adversarial）", "C 纠问制", "D 书面审"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】普通法刑事程序采对抗制，控辩主导、法官中立。【逐步演示】大陆法传统采职权主义。【易错提醒】注意两大法系的模式对应。"}, {"order": 2, "qtype": "single", "stem": "Siems 在社会法学章节讨论比较刑法时，把哪一关系作为研究主题？", "options": ["A 政治经济与监禁率", "B 语言与法律", "C 宗教与法律", "D 地理与法律"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Siems 把政治经济与监禁率的关系作为研究主题。【逐步演示】体现社会法学方法。【易错提醒】与其他主题区分。"}, {"order": 3, "qtype": "judge", "stem": "在大陆法的混合法庭中，非职业法官只决定事实问题，不参与法律问题的决定。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出大陆法混合法庭中非职业法官既决定事实也决定法律。【逐步演示】这与英美陪审团只决定事实不同。【易错提醒】注意混合法庭与陪审团的区别。"}, {"order": 4, "qtype": "blank", "stem": "控辩双方协商以被告人认罪换取较轻处理的机制称为______。", "options": [], "answer": "", "accepted": ["辩诉交易", "plea bargaining", "Plea Bargaining", "认罪协商"], "keywords": [], "explanation": "【答案】辩诉交易（Plea Bargaining）。【解题思路】它是美国刑事司法的显著特征。【逐步演示】绝大多数美国刑事案件由此解决。【易错提醒】与大陆法的协商机制区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，美国刑事司法的特征包括：", "options": ["A 高监禁率", "B 辩诉交易普遍", "C 陪审团在刑事审判中仍重要", "D 刑罚相对严厉"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项均为 Siems 描述的美国刑事司法特征。【逐步演示】Kagan 以对抗性法治主义概括。【易错提醒】注意这些是美国特性，非所有普通法国家。"}, {"order": 6, "qtype": "essay", "stem": "比较对抗制与职权主义刑事程序的差异，并说明评价两种模式为何不能脱离社会语境。", "options": [], "answer": "", "accepted": [], "keywords": [["对抗制", "控辩主导法官中立证据规则严格"], ["职权主义", "法官查明事实混合法庭"], ["社会语境", "监禁率与政治经济相关"], ["趋同与审慎", "人权公约推动程序统一"]], "explanation": "【答案要点】见 keywords。【解题思路】先述程序差异，再述社会语境，最后落到审慎评价。【逐步演示】引用监禁率与 Kagan 观点。【易错提醒】不要简单断言某一模式优越。"}, {"order": 7, "qtype": "single", "stem": "德国 1924 年废除刑事陪审团后，代之以何种制度？", "options": ["A 参审员（Schöffen）制度", "B 辩诉交易", "C 治安法官", "D 恢复性司法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】德国 1924 年以参审员制度取代陪审团。【逐步演示】参审员与职业法官组成混合法庭。【易错提醒】与英美陪审团区分。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，刑事司法中的监禁率差异可以单纯从法律规则的文本推断出来。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 强调监禁率与政治经济、社会政策相关，不能单纯从规则推断。【逐步演示】这体现社会法学方法。【易错提醒】注意『单纯从文本推断』的错误。"}, {"order": 9, "qtype": "blank", "stem": "强调修复损害与当事人和解的司法模式称为______司法。", "options": [], "answer": "", "accepted": ["恢复性", "restorative", "Restorative", "恢复"], "keywords": [], "explanation": "【答案】恢复性（Restorative）。【解题思路】恢复性司法强调修复损害与和解。【逐步演示】北欧国家以此著称，监禁率较低。【易错提醒】与惩罚性司法区分。"}, {"order": 10, "qtype": "single", "stem": "关于陪审团在美国刑事司法中的地位，Siems 指出：", "options": ["A 已被完全废除", "B 被视为文化与民主的关键要素，至今重要", "C 只用于民事案件", "D 仅存在于理论中"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Siems 指出陪审团在美国被视为文化与民主的关键要素。【逐步演示】但多数刑事案件实际通过辩诉交易解决。【易错提醒】陪审团重要不等于多数案件用它审判。"}, {"order": 11, "qtype": "blank", "stem": "法国审理严重刑事犯罪的法庭称为重罪法庭（cour d'______）。", "options": [], "answer": "", "accepted": ["assises", "assises 法庭", "重罪法庭", "cour d'assises"], "keywords": [], "explanation": "【答案】assises。【解题思路】法国重罪法庭 cour d'assises 仍保留陪审员。【逐步演示】Siems 以此为大陆法陪审的例子。【易错提醒】与德国参审员制度区分。"}, {"order": 12, "qtype": "judge", "stem": "大陆法传统上对辩诉交易较为谨慎，但近几十年也引入了各种协商机制。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Siems 指出大陆法传统谨慎，但近几十年出现协商机制。【逐步演示】如德国的处罚令与协商程序。【易错提醒】注意『传统谨慎』与『近年引入』的限定。"}]}, "S2M6K7": {"lesson": "S2M6K7", "questions": [{"order": 1, "qtype": "single", "stem": "普通法制定法解释中，为避免荒谬结果而修正条文字面含义的规则是：", "options": ["A 字面规则（Literal Rule）", "B 黄金规则（Golden Rule）", "C 瑕疵规则（Mischief Rule）", "D 启示法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】黄金规则用于避免字面解释导致荒谬结果。【逐步演示】字面规则按字面含义，瑕疵规则探求法律欲补救的缺陷。【易错提醒】区分三种普通法解释规则。"}, {"order": 2, "qtype": "single", "stem": "大陆法中探求立法者意图、给法律以完整效果的解释方法称为：", "options": ["A 字面规则", "B 启示法（Exegetical Method）", "C 黄金规则", "D 瑕疵规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】启示法探求立法者意图。【逐步演示】目的论方法则依据法律客观目的。【易错提醒】与普通法解释规则区分。"}, {"order": 3, "qtype": "judge", "stem": "Vogenauer 的比较研究发现，法国、德国、英格兰在制定法解释上使用完全不同的方法，没有任何共同点。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Vogenauer 发现三国起点不同但实际使用相似的正式与价值导向论证组合。【逐步演示】这挑战了刻板印象。【易错提醒】不要误判为完全不同。"}, {"order": 4, "qtype": "blank", "stem": "大陆法中依据法律客观目的进行解释、对一般性条款尤其重要的方法称为______方法。", "options": [], "answer": "", "accepted": ["目的论", "teleological", "Teleological", "目的"], "keywords": [], "explanation": "【答案】目的论（Teleological）。【解题思路】目的论方法依据法律客观目的。【逐步演示】对一般性条款尤其重要。【易错提醒】与启示法区分。"}, {"order": 5, "qtype": "multi", "stem": "根据 Siems，大陆法的解释方法包括：", "options": ["A 启示法", "B 目的论方法", "C 扩张解释与类推适用", "D 完全排斥目的论证"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Siems 列举启示法、目的论方法、扩张解释与类推。【逐步演示】瑞士民法典明确授权法官补充法律。【易错提醒】D 与大陆法实践不符。"}, {"order": 6, "qtype": "essay", "stem": "论述两大法系法律解释方法的差异与趋同，并说明为何不能把差异绝对化。", "options": [], "answer": "", "accepted": [], "keywords": [["传统差异", "普通法文本先例对大陆法意图目的"], ["方法体系", "字面黄金瑕疵对启示目的类推"], ["趋同证据", "Vogenauer 三国相似论证组合"], ["去绝对化", "都平衡确定性与灵活性"]], "explanation": "【答案要点】见 keywords。【解题思路】先述差异，再述趋同，最后上升到方法论。【逐步演示】引用 Vogenauer、瑞士民法典第 1 条。【易错提醒】不要走向『差异消失』的极端。"}, {"order": 7, "qtype": "single", "stem": "瑞士民法典第 1 条授权法官在法典无规定时依习惯法、再依其作为立法者会确立的规则裁判，这说明：", "options": ["A 大陆法完全禁止法官补充法律", "B 大陆法早已承认法官在法律补充中的角色", "C 瑞士采用判例法", "D 大陆法没有民法典"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该条款说明大陆法已承认法官补充法律的角色。【逐步演示】机械适用只是漫画化想象。【易错提醒】不要误判为大陆法禁止法官补充法律。"}, {"order": 8, "qtype": "judge", "stem": "Siems 认为，把大陆法官描述为『狭窄、机械、无创造性』是准确的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 转述 Markesinis、Fedtke、Shapiro 等观点，认为这种描述不准确。【逐步演示】大陆法通过一般条款发展法律。【易错提醒】警惕对大陆法的漫画化。"}, {"order": 9, "qtype": "blank", "stem": "Duncan Kennedy 提出法律思想三次全球化，其中十九世纪古典法律思想以______法律科学概念为基础。", "options": [], "answer": "", "accepted": ["德国", "German", "德意志", "德国法"], "keywords": [], "explanation": "【答案】德国（German）。【解题思路】Kennedy 的古典法律思想以德国法律科学为基础。【逐步演示】社会阶段由法国学术驱动，政策分析由美国学术驱动。【易错提醒】区分三次全球化的代表国家。"}, {"order": 10, "qtype": "single", "stem": "关于解释方法，Siems 的总体立场是：", "options": ["A 形式主义完全正确", "B 现实主义完全正确", "C 两大法系都发展出平衡确定性与灵活性的机制", "D 法律解释不重要"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】Siems 审慎认为两大法系都发展出平衡确定性与灵活性的机制。【逐步演示】差异是程度与表述上的，而非本质上的。【易错提醒】不要走向任一极端。"}, {"order": 11, "qtype": "single", "stem": "普通法制定法解释中，探求法律欲补救的缺陷的规则是：", "options": ["A 字面规则", "B 黄金规则", "C 瑕疵规则（Mischief Rule）", "D 启示法"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】瑕疵规则探求法律欲补救的缺陷。【逐步演示】字面规则按字面含义，黄金规则避免荒谬结果。【易错提醒】区分三种普通法解释规则。"}, {"order": 12, "qtype": "judge", "stem": "Siems 指出，普通法法官在解释制定法时从不考虑立法史与法律目的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Siems 指出普通法解释已从字面转向立法史与目的。【逐步演示】英国法院已放弃狭隘解释，允许类推。【易错提醒】注意『从不』的绝对化表述。"}]}, "S3M1K1": {"lesson": "S3M1K1", "questions": [{"order": 1, "qtype": "single", "stem": "根据哈特在《法律的概念》中的观点，一个法律体系的核心是什么？", "options": ["A 主权者以制裁为后盾的命令", "B 初级规则与次级规则的结合", "C 体现正义的理性秩序", "D 法官判决的可预测性"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特批判奥斯丁命令理论后提出，法律的中心是初级规则与次级规则的结合。【逐步演示】初级规则直接规定行为义务，次级规则规定如何识别、改变与裁判初级规则，二者结合才使松散的规则社会转变为法律体系。【易错提醒】A 属于奥斯丁，C 接近自然法，D 接近规则怀疑论，均非哈特的核心主张。"}, {"order": 2, "qtype": "single", "stem": "按照哈特的分析，仅靠初级规则的社会所面临的三大缺陷不包括下列哪一项？", "options": ["A 规则的不确定性", "B 规则的静态性", "C 社会压力的无效率", "D 规则内容的道德空洞化"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】哈特列举的三大缺陷是 uncertainty、static quality 与 the inefficiency of diffuse social pressure。【逐步演示】不确定性指无从识别规则，静态性指无法有意改变，无效率指纠纷无人作权威判定。【易错提醒】道德空洞化并非哈特所列的缺陷，此题考察对三大缺陷的准确记忆。"}, {"order": 3, "qtype": "judge", "stem": "次级规则主要是向人们施加义务的规则，而非授予权力的规则。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】次级规则大多属于授予权力（power-conferring）的规则。【逐步演示】承认规则、改变规则、裁判规则分别授予识别、立法与裁判的能力，而非主要施加义务；施加义务主要是初级规则的功能。【易错提醒】授权性规则正是命令理论无法解释、而哈特理论能够解释的关键现象。"}, {"order": 4, "qtype": "blank", "stem": "在哈特的理论中，用来克服初级规则社会『不确定性』缺陷的次级规则被称为______。", "options": [], "answer": "", "accepted": ["承认规则", "承认规则（Rule of Recognition）", "rule of recognition", "Rule of Recognition", "确认规则"], "keywords": [], "explanation": "【答案】承认规则（Rule of Recognition）。【解题思路】承认规则指明某一特征为识别有效初级规则的终局标志。【逐步演示】它可以是权威文本、制定法、习惯或判例，其出现带来了法律效力的观念。【易错提醒】不要与解决静态性的『改变规则』或解决无效率的『裁判规则』混淆。"}, {"order": 5, "qtype": "single", "stem": "哈特认为，克服初级规则『静态性』（无法有意识地修改规则）缺陷的补救是：", "options": ["A 承认规则", "B 改变规则", "C 裁判规则", "D 制裁规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】改变规则授权特定机关或个人引入新规则、废止旧规则。【逐步演示】它使法律能够有意识地适应变化，私法中订立遗嘱、合同的授权规则也属此类。【易错提醒】承认规则解决识别问题，裁判规则解决纠纷判定问题，各有分工。"}, {"order": 6, "qtype": "single", "stem": "在哈特的理论中，界定『法官』『法院』『管辖权』『判决』等概念的是哪一类次级规则？", "options": ["A 初级规则", "B 承认规则", "C 改变规则", "D 裁判规则"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】裁判规则授权特定主体对初级规则是否被违反作出权威判定。【逐步演示】这类规则界定谁有权裁判、遵循何种程序，由此产生法官、法院、管辖权等概念。【易错提醒】注意裁判规则与承认规则虽紧密关联，但功能侧重不同。"}, {"order": 7, "qtype": "multi", "stem": "根据哈特的分类，下列哪些属于次级规则？", "options": ["A 承认规则", "B 改变规则", "C 裁判规则", "D 不得杀人的义务规则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特把次级规则分为承认、改变、裁判三类。【逐步演示】三者都以初级规则为对象，处于更高的层级。【易错提醒】D 是直接规定行为义务的初级规则，不要误选。"}, {"order": 8, "qtype": "judge", "stem": "哈特认为，初级规则与次级规则的结合本身就是法律体系的全部内容。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确说这种结合是法律体系的『中心』，但『并非全部』。【逐步演示】离开中心越远，越需容纳开放结构、法律与道德关系等不同性质的要素。【易错提醒】此题考察哈特理论的自我克制，避免把他的核心命题夸大为穷尽性定义。"}, {"order": 9, "qtype": "single", "stem": "关于承认规则在哈特理论中的地位，下列说法正确的是：", "options": ["A 它是一条普通的初级规则", "B 它是确定法律效力的终极次级规则", "C 它是一条实体道德原则", "D 它等同于法院的具体判决"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】承认规则是用来识别哪些初级规则有效的终极标准。【逐步演示】它为法律体系提供统一识别判准，是法律效力的社会基础。【易错提醒】承认规则不是具体判决，而是使判决具有权威性的规则，二者层次不同。"}, {"order": 10, "qtype": "single", "stem": "从『内部观点』看，规则的参与者把法律规则主要理解为：", "options": ["A 会受到制裁的外部规律", "B 行为理由与批评他人及自己的标准", "C 法官的个人偏好", "D 纯粹的文字游戏"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】内部观点指参与者把规则当作正当的行为理由与评价标准来接受。【逐步演示】他们用『这是法律』『这是有效的规则』来证成决定、批评他人。【易错提醒】A 描述的是外部观点，注意区分哈特的两种观点。"}, {"order": 11, "qtype": "judge", "stem": "合同、遗嘱等授权性规则可以被奥斯丁的命令理论充分解释。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】命令理论以威胁为核心，无法解释赋予人们达成合法安排能力的授权性规则。【逐步演示】哈特以次级规则理论解释这类『权力授予』规则，这是命令理论的根本缺陷之一。【易错提醒】这是哈特批判奥斯丁的经典论据，需牢记。"}, {"order": 12, "qtype": "essay", "stem": "试述仅有初级规则的社会所面临的三大缺陷，以及哈特提出的三种次级规则补救。", "options": [], "answer": "", "accepted": [], "keywords": [["不确定性", "uncertainty", "无从识别规则"], ["静态性", "static quality", "无法有意改变"], ["无效率", "diffuse social pressure", "私力救济"], ["承认规则/改变规则/裁判规则", "三种补救", "识别/改变/裁判"]], "explanation": "【答案要点】见 keywords 四组要点。【解题思路】先列三大缺陷，再逐一对应补救。【逐步演示】不确定性由承认规则解决，静态性由改变规则解决，无效率由裁判规则解决；三者与初级规则结合构成法律体系的核心。【易错提醒】不要把三类规则的功能张冠李戴，尤其承认规则与裁判规则。"}, {"order": 13, "qtype": "essay", "stem": "结合英国宪法的演进，说明次级规则如何把一组零散的规则整合为法律体系。", "options": [], "answer": "", "accepted": [], "keywords": [["大宪章到议会主权", "渐进演进"], ["承认规则", "议会制定法为最高渊源"], ["改变规则与裁判规则", "议会法/法院管辖权"], ["无成文宪法典仍有法律体系", "边界开放"]], "explanation": "【答案要点】见 keywords。【解题思路】以英国宪法为切口说明次级规则的功能。【逐步演示】议会主权提供统一识别标准（承认规则），《议会法》提供变更框架，法院审判权构成裁判规则，零散规则由此被整合为体系。【易错提醒】不要断言宪法惯例『就是法律』或『都不是法律』，其地位仍是开放问题。"}]}, "S3M1K2": {"lesson": "S3M1K2", "questions": [{"order": 1, "qtype": "single", "stem": "关于承认规则在哈特理论中的性质，下列哪一表述最准确？", "options": ["A 它是一条由宪法明确写出的初级规则", "B 它是用以识别有效法律的终极次级规则", "C 它是法院在个案中作出的具体判决", "D 它是一条约束法官道德的规范"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】承认规则是提供法律效力判准的终极次级规则。【逐步演示】它规定什么样的规则算法律，并为整个体系提供统一识别标准。【易错提醒】承认规则不是具体判决，也不必写成条文，其存在体现为官员的实践。"}, {"order": 2, "qtype": "single", "stem": "哈特用什么比喻来说明承认规则在日常运作中『被使用而不被复述』？", "options": ["A 交通红绿灯", "B 比赛的记分规则", "C 音乐乐谱", "D 机器说明书"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特以比赛的计分规则作比。【逐步演示】比赛中裁判与选手很少复述计分规则，却持续用它判断何为得分、谁获胜。【易错提醒】此比喻强调承认规则是实践中的规则，非纸面条文。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，承认规则的效力来自另一条更高层级的法律规则的授权。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】承认规则是终极规则，其存在来自官员群体实际的接受与使用这一社会事实。【逐步演示】若它还需更高规则授权，就会陷入无穷后退；哈特正是以此切断后退。【易错提醒】这是承认规则『终极性』的核心含义。"}, {"order": 4, "qtype": "blank", "stem": "法官说『这是法律』属于哈特所称的______陈述，而法学家说『在该国人们视某机关制定的规则为法律』属于______陈述。", "options": [], "answer": "", "accepted": ["内部；外部", "内部陈述和外部陈述", "internal and external", "内部、外部"], "keywords": [], "explanation": "【答案】内部陈述／外部陈述。【解题思路】前者从接受规则的立场发言，后者从观察者立场描述他人的接受。【逐步演示】哈特借此说明描述性法理学可从外部记录内部观点。【易错提醒】注意区分『这是法律』与『人们视此为法律』两种语气。"}, {"order": 5, "qtype": "single", "stem": "在现代法律体系中，承认规则判准之间的冲突通常如何处理？", "options": ["A 一律由法官自由裁量", "B 通过判准的位阶排列（如上位法优于下位法）", "C 诉诸国际法", "D 由行政机关决定"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】承认规则会对多种判准安排相对位阶。【逐步演示】例如普通法从属于制定法，冲突时按位阶解决。【易错提醒】哈特强调要区分『位阶从属』与『来源派生』，习惯与判例的效力来自承认规则的授予。"}, {"order": 6, "qtype": "multi", "stem": "根据哈特，下列哪些可以成为承认规则所指定的法律效力判准？", "options": ["A 由特定立法机关制定", "B 长期习惯做法", "C 司法判决先例", "D 载入权威文本"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】承认规则可指向权威文本、立法、习惯、判例等多种渊源。【逐步演示】这些判准可单独或复合使用，并可按位阶排列。【易错提醒】判准是多元的，不要误以为只有制定法一种。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为承认规则只能以『谱系』式的形式来源为判准，绝不可能纳入道德价值。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确承认某些体系（如美国）可把正义原则或实体道德纳入效力判准。【逐步演示】这就是『柔性实证主义』立场，也是他回应德沃金的重要论据。【易错提醒】不要把哈特误作僵化的『 Plain-fact 实证主义者』。"}, {"order": 8, "qtype": "single", "stem": "南非 1954 年 Harris v Dönges 案在哈特理论中主要被用来说明：", "options": ["A 国际法优于国内法", "B 承认规则作为官员共同实践一旦分裂，法律体系即陷入病理", "C 法官应当服从行政机关", "D 制定法一律无效"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该案中议会与法院对终极效力判准各执一词，是承认规则的病理案例。【逐步演示】哈特借此说明承认规则的存在依赖官员实践的一致性。【易错提醒】这不是普通的效力争议，而是关于『标准本身是什么』的争议。"}, {"order": 9, "qtype": "single", "stem": "关于凯尔森的『基础规范』与哈特的『承认规则』，下列说法正确的是：", "options": ["A 两者完全相同", "B 基础规范是先验预设，承认规则是经验的社会事实", "C 承认规则是先验预设", "D 基础规范是具体判决"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】凯尔森的基础规范是逻辑上的先验假定，哈特的承认规则是官员实践的经验事实。【逐步演示】哈特认为后者更能说明法律体系的现实运作与演变。【易错提醒】二者虽同为『终极』根据，但性质 radically 不同。"}, {"order": 10, "qtype": "judge", "stem": "承认规则本身作为一般规则，同样具有开放结构，在边缘情形下其适用可能发生争议。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特明确指出终极判准和具体规则一样有开放结构。【逐步演示】Harris v Dönges 正是终极判准边缘争议的体现。【易错提醒】承认规则的终极性不等于它完全确定无争议。"}, {"order": 11, "qtype": "single", "stem": "根据哈特，『这是法律』与『在英国人们视议会制定法为法律』的区别在于：", "options": ["A 前者为真，后者为假", "B 前者是内部陈述，后者是外部陈述", "C 前者是道德判断，后者是事实判断", "D 两者没有区别"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】前者从接受规则的立场说，后者从观察者立场描述他人的接受。【逐步演示】哈特以此说明外部观察者可以描述内部观点而不必接受它。【易错提醒】不要误认为外部陈述就是道德判断。"}, {"order": 12, "qtype": "essay", "stem": "试论承认规则为何被称为『终极的次级规则』，并说明它如何为法律效力提供社会基础。", "options": [], "answer": "", "accepted": [], "keywords": [["提供效力判准", "识别有效法律"], ["终极", "不再由更高规则授权"], ["社会实践事实", "官员共同接受与使用"], ["切断无穷后退", "法律效力锚定"]], "explanation": "【答案要点】见 keywords。【解题思路】从功能、地位、存在方式三方面论述。【逐步演示】功能上提供判准；地位上置于顶点不再后退；存在方式上是官员实践的事实。【易错提醒】避免把承认规则说成某条写成条文的普通法律规则。"}, {"order": 13, "qtype": "essay", "stem": "结合德沃金的批评，分析承认规则能否容纳法律原则，以及哈特在《后记》中的回应。", "options": [], "answer": "", "accepted": [], "keywords": [["德沃金：原则无法由谱系判准识别", "主张放弃承认规则"], ["哈特：原则可经承认规则识别", "宪法原则条款/柔性实证主义"], ["建构性诠释预设既判法的识别", "仍离不开承认规则"]], "explanation": "【答案要点】见 keywords。【解题思路】先述德沃金挑战，再述哈特回应。【逐步演示】德沃金以法律原则否定承认规则；哈特指出原则可凭谱系或内容被纳入，且诠释本身预设了对既判法的识别。【易错提醒】不要把哈特简化为只承认形式的『 Plain-fact 实证主义者』。"}]}, "S3M1K3": {"lesson": "S3M1K3", "questions": [{"order": 1, "qtype": "single", "stem": "哈特提出改变规则主要是为了解决初级规则社会的哪一项缺陷？", "options": ["A 不确定性", "B 静态性", "C 无效率", "D 道德空洞"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】改变规则授权有意识地引入、修改与废止规则，解决静态性。【逐步演示】不确定性由承认规则解决，无效率由裁判规则解决。【易错提醒】三大缺陷与三类补救须准确对应。"}, {"order": 2, "qtype": "single", "stem": "裁判规则在哈特理论中的核心功能是：", "options": ["A 识别哪些规则是法律", "B 授权权威判定初级规则是否被违反", "C 制定新的法律", "D 规定道德标准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】裁判规则授权对违反事实作权威判定，并界定法官、法院、管辖权。【逐步演示】它以初级规则为对象，属于更高层级的次级规则。【易错提醒】A 是承认规则的功能，C 是改变规则的功能。"}, {"order": 3, "qtype": "judge", "stem": "改变规则与裁判规则主要是通过向主体施加义务来发挥作用的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】这两类规则多属授权性规则，赋予主体法律能力而非施加义务。【逐步演示】立法权、司法权、缔约能力都由这类规则授予。【易错提醒】这正是命令理论难以解释、而哈特理论能够解释的现象。"}, {"order": 4, "qtype": "blank", "stem": "哈特指出，订立合同、立遗嘱等私法规则可以被理解为个人行使的『有限的______权』。", "options": [], "answer": "", "accepted": ["立法", "立法权", "legislative", "legislative power"], "keywords": [], "explanation": "【答案】立法（权）。【解题思路】哈特借凯尔森的观点，把私法自治理解为个人行使有限的立法权。【逐步演示】合同、遗嘱等授权规则改变了个人在初级规则下的法律地位。【易错提醒】不要答成『司法权』或『行政权』。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，裁判规则的存在会带来哪些法律概念的界定？", "options": ["A 法官与法院", "B 管辖权", "C 判决", "D 法律效力判准"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】裁判规则界定谁裁判、按何程序裁判及其判决地位。【逐步演示】由此产生法官、法院、管辖权与判决等概念。【易错提醒】D 主要由承认规则界定，不要误选。"}, {"order": 6, "qtype": "single", "stem": "关于改变规则与承认规则的关系，哈特认为：", "options": ["A 二者毫无关联", "B 有改变规则之处，承认规则必然把立法纳入识别判准", "C 承认规则必然被改变规则取代", "D 立法不再需要任何判准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】凡有改变规则之处，承认规则必然把立法作为识别判准之一。【逐步演示】通常官方文本即被当作已依法制定的充分证明。【易错提醒】承认规则不必复述立法的全部程序细节。"}, {"order": 7, "qtype": "single", "stem": "关于裁判规则与承认规则的关系，哈特认为：", "options": ["A 有裁判规则之处必然隐含某种承认规则", "B 裁判规则与承认规则互相排斥", "C 法院判决不可能成为法律渊源", "D 承认规则由裁判规则创造"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法院对违反事实的权威判定，同时也回答了规则是什么，故隐含初级形态的承认规则。【逐步演示】判决因此成为法律渊源。【易错提醒】这种最简形式的承认规则仍很粗糙，不等于发达的承认规则。"}, {"order": 8, "qtype": "judge", "stem": "美国 1803 年 Marbury v. Madison 案确立了对立法的司法审查原则，体现了裁判规则与改变规则之间的结构联动。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】该案确立司法审查，法院有权判定立法是否合宪。【逐步演示】裁判规则所赋予的判定权被用来审查改变规则的产物（立法）。【易错提醒】该案事实与年份为 5 U.S. (1 Cranch) 137 (1803)，由马歇尔大法官主笔。"}, {"order": 9, "qtype": "single", "stem": "按照哈特，法官的判决在体系内的终局性（finality）意味着：", "options": ["A 判决在道德上必然无误", "B 判决具有权威性但未必道德无误", "C 判决不能被任何机关更改", "D 判决等同于立法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特区分终局性与无误性（infallibility）。【逐步演示】判决在体系内权威且终局，但仍可受道德与政治评价。【易错提醒】不要把『有权威』等同于『道德上正确』。"}, {"order": 10, "qtype": "judge", "stem": "哈特认为，规则怀疑论者关于『规则只是对法官判决的预测』的主张完全正确，没有任何限制。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特承认开放结构地带存在裁量，但坚持大量简单案件中规则是确定的。【逐步演示】不能因边缘裁量就否认规则的中心地位。【易错提醒】哈特走的是形式主义与规则怀疑论之间的中间道路。"}, {"order": 11, "qtype": "multi", "stem": "下列哪些现象可以借哈特的『授权性规则』概念得到解释？", "options": ["A 议会立法", "B 订立合同", "C 立遗嘱", "D 在威胁下的被迫服从"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】立法、缔约、立遗嘱都是赋予法律能力的授权性规则。【逐步演示】它们使主体能改变法律关系，而非被强制履行义务。【易错提醒】D 属于命令理论解释的『不得不』，不是授权性规则。"}, {"order": 12, "qtype": "essay", "stem": "试论改变规则与裁判规则的区分，并说明它们分别如何回应初级规则社会的缺陷。", "options": [], "answer": "", "accepted": [], "keywords": [["改变规则授权立法与变更", "解决静态性"], ["裁判规则授权权威判定", "解决无效率"], ["授权性规则", "赋予法律能力而非义务"], ["与承认规则联动", "判决成为渊源"]], "explanation": "【答案要点】见 keywords。【解题思路】先定义两类规则，再对应三大缺陷，最后谈与承认规则的关系。【逐步演示】改变规则面向未来赋予变更能力；裁判规则面向具体事件赋予判定权；二者与承认规则协同运作。【易错提醒】不要把两类规则的功能互换。"}, {"order": 13, "qtype": "essay", "stem": "结合 Marbury v. Madison 案，分析司法审查如何体现哈特所说的立法权、司法权与承认规则之间的结构关联。", "options": [], "answer": "", "accepted": [], "keywords": [["马歇尔大法官/1803", "确立司法审查"], ["法院判定立法合宪性", "裁判规则"], ["宪法为最高渊源", "承认规则"], ["终局性不等于无误性"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件事实切入，联系三类次级规则。【逐步演示】法院以裁判权审查立法（改变规则的产物），依据宪法至上的承认规则作出判定。【易错提醒】注意区分『权利』与『救济』的论证思路。"}]}, "S3M1K4": {"lesson": "S3M1K4", "questions": [{"order": 1, "qtype": "single", "stem": "哈特认为，判断一个法律体系存在的两个最低条件（必要且充分）是：", "options": ["A 有宪法典且有法院", "B 有效规则被普遍服从，且次级规则被官员有效接受", "C 主权者被普遍服从，且有制裁", "D 法律与道德一致，且被普遍遵守"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特提出两个最低条件：有效规则被普遍服从＋次级规则被官员有效接受。【逐步演示】前者对应公民部门，后者对应官员部门。【易错提醒】A、C 仍停留在形式或命令理论的框架，D 混入了自然法立场。"}, {"order": 2, "qtype": "single", "stem": "哈特把『一个法律体系存在』这一陈述称为：", "options": ["A 纯粹的价值判断", "B 双面陈述（Janus-faced statement）", "C 道德命题", "D 逻辑真理"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】该陈述一面朝向公民服从，一面朝向官员接受，故称双面陈述。【逐步演示】它同时涉及两个社会部门的事实。【易错提醒】哈特坚持它是事实陈述，而非道德判断。"}, {"order": 3, "qtype": "judge", "stem": "按照哈特的最低条件说，普通公民必须从道德上认同法律，法律体系才存在。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】公民只需『各自服从』有效规则，动机可以各异（利益计算、习惯、恐惧）。【逐步演示】道德认同并非必要条件；只有官员需把次级规则当作共同标准接受。【易错提醒】注意公民服从与官员接受的要求强度不同。"}, {"order": 4, "qtype": "blank", "stem": "哈特指出，在复杂法律体系中，内部观点甚至可以仅限于______阶层，而这样的社会仍可能是法律体系。", "options": [], "answer": "", "accepted": ["官员", "officials", "official", "统治者"], "keywords": [], "explanation": "【答案】官员（officials）。【解题思路】哈特认为接受次级规则的内部观点可能仅限于官方世界。【逐步演示】他称这样的社会『可悲得像羊群』，但仍否认不了其法律体系地位。【易错提醒】这体现哈特对法律存在的描述性、非道德化理解。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，以下哪些情形属于法律体系的『病理』？", "options": ["A 革命", "B 敌国占领", "C 无政府与匪患", "D 官员对终极判准产生分裂"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】哈特列举的革命、占领、无政府以及官员分裂，都是正常运作条件局部失败的表现。【逐步演示】它们都属于法律体系的病理状态。【易错提醒】病理不等于体系必然已经消亡，判断何时终止并无精确时点。"}, {"order": 6, "qtype": "single", "stem": "哈特用哪个词形容法律体系从旧体系向新体系转换的过程（如殖民地独立）？", "options": ["A 病理学", "B 胎儿学（embryology）", "C 社会学", "D 诠释学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特以『法律体系的胎儿学』比喻新体系从旧体系中诞生。【逐步演示】以英联邦独立为例，终极承认规则从『威斯敏斯特议会立法』转向本地化。【易错提醒】胎儿学对应体系的诞生，病理学对应体系的病变，勿混用。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，只要官员之间在终极判准上发生严重分歧，整个法律体系就立即停止存在。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特认为存在陈述容许中断，何时最终停止并无精确时点。【逐步演示】即使宪法层面分裂，大量日常法律操作仍照常进行。【易错提醒】不要轻言整个体系已经消亡，须考虑恢复的可能性和具体语境。"}, {"order": 8, "qtype": "single", "stem": "哈特坚持『法律体系存在』是事实问题而非道德问题，这一立场意味着：", "options": ["A 邪恶体系不可能是法律体系", "B 道德上邪恶的体系只要满足条件仍是法律体系", "C 法律的存在取决于其正义程度", "D 事实与价值完全无法区分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特把存在（是不是法律）与价值（该不该服从）分开。【逐步演示】承认某体系是法律，不妨碍谴责与抵抗它。【易错提醒】这与自然法的『恶法非法』形成对照。"}, {"order": 9, "qtype": "single", "stem": "南非 1994 年宪制转型在哈特框架中主要体现为：", "options": ["A 法律道德的全面胜利", "B 终极承认规则的内容转换（新体系从旧体系中诞生）", "C 国际法取代国内法", "D 裁判规则消失"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】转型的事实证据是官员（尤其法院）实际使用的终极判准发生变化。【逐步演示】新宪法成为最高判准，标志新法律体系诞生。【易错提醒】判断依据是官员实践的改变，而非单纯的道义宣示。"}, {"order": 10, "qtype": "judge", "stem": "在只有初级规则的简单社会中，内部观点必须广泛分布；而在法律体系中，接受规则与被动服从可以分离。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特指出，次级规则的出现使『接受为共同标准』与『各自被动服从』可以分离。【逐步演示】内部观点甚至可能仅限于官员阶层。【易错提醒】这是理解法律体系复杂性的关键点。"}, {"order": 11, "qtype": "multi", "stem": "根据哈特，关于法律体系的存在，下列说法正确的有哪些？", "options": ["A 它是可经验判断的事实陈述", "B 它具有双面结构", "C 公民的服从动机可以各异", "D 它的终止有精确的时点"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】存在是事实陈述、具有双面结构、公民动机不限。【逐步演示】D 错误，因为哈特明确说何时最终停止并无精确时点。【易错提醒】留意『精确时点』这类绝对化表述。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特关于法律体系存在的两个最低条件，并说明『双面陈述』的含义。", "options": [], "answer": "", "accepted": [], "keywords": [["有效规则被普遍服从", "公民部门"], ["次级规则被官员有效接受", "官员部门"], ["双面陈述", "公民服从与官员接受"], ["事实问题", "非道德判断"]], "explanation": "【答案要点】见 keywords。【解题思路】先列两条件，再解释双面性。【逐步演示】第一个条件针对公民（各自服从即可），第二个针对官员（须当作共同标准）；两者构成存在的事实基础。【易错提醒】不要额外附加道德正当性作为条件。"}, {"order": 13, "qtype": "essay", "stem": "结合 1994 年南非宪制转型，说明哈特『法律体系的胎儿学』理论，并评价其解释力与局限。", "options": [], "answer": "", "accepted": [], "keywords": [["新宪法成为承认规则核心", "议会主权被取代"], ["官员实践改变是判断依据", "事实问题"], ["转型通过协商制宪", "与暴力断裂不同"], ["描述性框架的局限", "道义力量的影响"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，说明承认规则转移，再作评价。【逐步演示】判断标准是官员实际使用的终极判准；但协商转型中合法性道义力量也影响了接受，这是纯描述框架的边界。【易错提醒】避免把转型简单归结为暴力革命模式。"}]}, "S3M1K5": {"lesson": "S3M1K5", "questions": [{"order": 1, "qtype": "single", "stem": "哈特用『公园内禁止车辆入内』的例子主要说明：", "options": ["A 法律规则总是完全确定的", "B 一般语词规则具有开放结构", "C 法官可以任意解释法律", "D 立法者从不需要预见未来"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】汽车、公交车清楚属于『车辆』，但玩具车、自行车、滑轮鞋处于边缘，说明规则有开放结构。【逐步演示】核心清楚、边缘模糊是一般规则的普遍特征。【易错提醒】开放结构不等于法官可以任意解释，边缘选择仍须有理由。"}, {"order": 2, "qtype": "single", "stem": "哈特认为开放结构的根源在于：", "options": ["A 立法者的疏忽", "B 一般语言的性质与人的有限性", "C 法官的偏见", "D 法律的阶级本质"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】开放结构源于一般语言本身的开放纹理，以及人相对无知的事实与目的的相对不确定性。【逐步演示】哈特说『必然的选择』被强加给我们，『因为我们是人，不是神』。【易错提醒】这不是立法技术的偶然缺陷，而是普遍且必然的特征。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，解释规则（canons of interpretation）可以彻底消除法律语言的开放结构。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确指出解释规则本身也是一般规则，也需要解释，无法自我解释。【逐步演示】它们只能减少而不能消除不确定性。【易错提醒】注意『减少』与『消除』的区别。"}, {"order": 4, "qtype": "blank", "stem": "哈特把规则适用毫无疑问的清楚情形称为______，把是否适用存在理由冲突的模糊情形称为______。", "options": [], "answer": "", "accepted": ["核心地带；边缘地带", "确定的核心和可疑的边缘", "core of certainty; penumbra of doubt", "核心与边缘"], "keywords": [], "explanation": "【答案】核心地带／边缘地带。【解题思路】哈特以确定的核心与可疑的边缘描述规则的双重结构。【逐步演示】核心保证确定性，边缘产生开放结构。【易错提醒】不要把『核心』理解为法律的实质内容，而是指适用无疑的情形。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，导致开放结构的人的两种『相连的无能』是：", "options": ["A 相对无知的事实", "B 目的的相对不确定性", "C 绝对的道德无知", "D 语言能力的缺失"], "answer": "AB", "accepted": [], "keywords": [], "explanation": "【答案】AB。【解题思路】哈特提出 relative ignorance of fact 与 relative indeterminacy of aim。【逐步演示】前者指无法预见未来情势，后者指面对未设想情势时目标尚未确定。【易错提醒】C、D 并非哈特所列，不要凭印象选择。"}, {"order": 6, "qtype": "single", "stem": "哈特批判的『形式主义』（或概念法学）的核心错误是：", "options": ["A 承认规则的开放结构", "B 掩盖并最小化规则适用中选择的必要性", "C 主张法律与道德分离", "D 强调判例的作用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】形式主义把规则语词冻结为处处同义，无视选择必要性。【逐步演示】哈特称其代价是『在黑暗中预先决定』未来案件，僵化分类与规则目的冲突。【易错提醒】『概念天堂』是哈特对形式主义极致的描述。"}, {"order": 7, "qtype": "judge", "stem": "哈特主张，开放结构只存在于判例法，成文法因为语词明确而没有开放结构。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特强调成文法同样有开放结构，只是不确定性的表现方式不同。【逐步演示】立法语词把不确定性从模仿的模糊转移为语词的模糊。【易错提醒】开放结构是一切一般规则的特征，不限于判例法。"}, {"order": 8, "qtype": "single", "stem": "哈特提到的应对开放结构的两种法律技术不包括：", "options": ["A 委任立法（设定宽泛标准由行政机关具体化）", "B 可变标准（如过失法中的合理注意）", "C 把一切决定交给法官任意裁量", "D 保留核心地带的确定性"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】哈特主张在确定性与开放性间平衡，反对把一切交给法官任意裁量。【逐步演示】委任立法与可变标准是两种应对技术，核心地带仍保持确定性。【易错提醒】哈特的裁量是受约束的填补空隙，不是任意裁量。"}, {"order": 9, "qtype": "single", "stem": "唐纳休诉斯蒂文森案（Donoghue v Stevenson）在开放结构讨论中的意义在于：", "options": ["A 证明法律完全没有漏洞", "B 『邻人原则』把注意义务扩展到既有类别的边缘之外", "C 否定一切类比推理", "D 确立法官无需说明理由"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】阿特金勋爵提出邻人原则，把注意义务扩展到先前未被明确规定的情形。【逐步演示】哈特在《后记》中以此说明有限形式的建构性诠释。【易错提醒】此案年份为 1932，由英国上议院判决。"}, {"order": 10, "qtype": "judge", "stem": "德沃金与哈特都同意，疑难案件中存在法律未调整的情形，法官必须行使造法权。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金认为法律是『无漏洞』的，原则提供唯一正确答案，法官无需造法。【逐步演示】哈特则坚持总有未调整案件，法官须行使填补空隙的造法权。【易错提醒】这是二人司法裁量之争的核心分歧。"}, {"order": 11, "qtype": "multi", "stem": "关于开放结构，下列符合哈特观点的有哪些？", "options": ["A 它是一般语言的必然特征", "B 它在核心地带仍然确定", "C 边缘地带的适用需要选择", "D 它意味着法律完全不确定"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】开放结构是语言必然特征，核心确定、边缘需选择。【逐步演示】D 错误，因为哈特坚持核心地带是法律运行的主体。【易错提醒】警惕把开放结构夸大为法律全面不确定。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特开放结构理论的两层根源，并说明他如何在形式主义与规则怀疑论之间寻找中间道路。", "options": [], "answer": "", "accepted": [], "keywords": [["一般语言的开放纹理", "解释规则无法自我解释"], ["相对无知的事实与目的的相对不确定性", "人是人不是神"], ["反对形式主义掩盖选择", "反对规则怀疑论否定规则"], ["确定性与开放性平衡", "核心与边缘"]], "explanation": "【答案要点】见 keywords。【解题思路】先述两层根源，再述中间道路。【逐步演示】语言根源＋人的有限性构成开放结构；哈特既反对形式主义的冻结，也反对怀疑论的全盘否定。【易错提醒】不要把开放结构等同于规则的全面失效。"}, {"order": 13, "qtype": "essay", "stem": "结合 Donoghue v Stevenson 案，分析哈特与德沃金对『疑难案件是否存在唯一正确答案』的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["邻人原则", "1932年上议院"], ["德沃金：原则提供唯一正确答案", "建构性诠释"], ["哈特：开放地带仍需选择", "有限的造法权"], ["类比推理推迟但不消除选择"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，对比两人立场。【逐步演示】德沃金视原则为揭示唯一答案；哈特认为竞争原则间仍需选择，类比推理只推迟而不消除造法时刻。【易错提醒】哈特并不否认原则的作用，只否认它能彻底消除选择。"}]}, "S3M1K6": {"lesson": "S3M1K6", "questions": [{"order": 1, "qtype": "single", "stem": "哈特在开放结构争论中采取的立场最接近于：", "options": ["A 形式主义：规则能决定一切案件", "B 规则怀疑论：规则只是判决预测", "C 中间道路：核心确定、边缘不确定", "D 法律现实主义：政策决定结果"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】哈特承认确定的核心与不确定的边缘，反对两种极端。【逐步演示】法律生活的主体依赖确定规则，边缘地带才需要选择。【易错提醒】不要把哈特归入规则怀疑论或形式主义任何一端。"}, {"order": 2, "qtype": "judge", "stem": "哈特认为，规则怀疑论主张『不存在规则、只有法院判决及其预测』是自相矛盾的，因为它无法解释法院权威判决的存在。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特指出法院的存在预设了授予管辖权的次级规则。【逐步演示】没有规则观念，就无法区分私人判决与法院判决。【易错提醒】这是哈特反驳激进规则怀疑论的关键论据。"}, {"order": 3, "qtype": "single", "stem": "哈特把规则怀疑论者的心理根源称为：", "options": ["A 失望的绝对主义者", "B 天真的现实主义者", "C 激进的实证主义者", "D 保守的形式主义者"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】哈特称其为 disappointed absolutist。【逐步演示】他心中的规则是形式主义天堂式能决定一切的东西，发现现实不符便否定规则存在。【易错提醒】这是一种心理分析，不是对怀疑论逻辑的认同。"}, {"order": 4, "qtype": "blank", "stem": "德沃金主张疑难案件中存在______，即通过建构性诠释可找到唯一正确的判决。", "options": [], "answer": "", "accepted": ["唯一正确答案", "正确答案", "right answer", "right answer thesis", "唯一正解"], "keywords": [], "explanation": "【答案】唯一正确答案（Right Answer Thesis）。【解题思路】德沃金认为原则能为疑难案件提供唯一正确答案。【逐步演示】法律在诠释意义上是无漏洞的。【易错提醒】哈特反对此命题，认为选择无法被完全消除。"}, {"order": 5, "qtype": "single", "stem": "哈特在《后记》中回应德沃金时，承认了下列哪一点？", "options": ["A 法律原则不是法律的一部分", "B 原则可以经由承认规则被识别为法律", "C 疑难案件总有唯一正确答案", "D 法官从不造法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特在《后记》中让步，承认原则可凭谱系或内容纳入承认规则。【逐步演示】他坚持的剩余分歧是原则能否决定一切案件。【易错提醒】勿以为哈特完全否认原则的法律地位。"}, {"order": 6, "qtype": "multi", "stem": "根据哈特，法官在疑难案件中行使的『填补空隙的裁量』具有哪些特征？", "options": ["A 是有限造法权，不能进行大规模改革", "B 须像有良知的立法者依一般理由裁决", "C 完全任意、不受任何约束", "D 只是插曲式的（interstitial）"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】哈特强调裁量受实体约束、填补空隙、不能任意。【逐步演示】法官须参考既有法律的原则与目的，像有良知的立法者一样裁决。【易错提醒】C 与哈特立场相反，他坚决反对任意裁量。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，法官判决的终局性（finality）意味着它在道德上必然是正确的、无误的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确区分终局性与无误性（infallibility）。【逐步演示】判决在体系内终局且权威，但仍可受道德评价。【易错提醒】不要把『体系内权威』等同于『道德正确』。"}, {"order": 8, "qtype": "single", "stem": "德沃金批评司法造法的两个主要理由是：", "options": ["A 不民主且溯及既往", "B 太效率且太民主", "C 违反国际法且违宪", "D 不专业且不公开"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】德沃金认为法官非民选，造法不民主；且溯及既往不正义。【逐步演示】哈特逐一回应：处理未调整案件是必要代价，且疑难案件中并无可挫败的明确期待。【易错提醒】注意哈特对这两项批评的具体反驳。"}, {"order": 9, "qtype": "single", "stem": "里格斯诉帕尔默案（Riggs v. Palmer）中，法院判决孙子不得继承的主要理由是：", "options": ["A 遗嘱形式要件不符", "B 不能允许任何人从自己的错误行为中获利", "C 继承人年龄不足", "D 遗嘱未经公证"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院以『不得从自己错误中获利』的原则限制遗嘱继承规则。【逐步演示】这是原则与规则交互的经典案例，年份为 1889，纽约州上诉法院。【易错提醒】遗嘱本身符合形式要件，障碍来自原则而非形式。"}, {"order": 10, "qtype": "judge", "stem": "德沃金与哈特都同意，法律原则属于法律的一部分；他们的分歧在于原则能否决定一切案件。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特在《后记》中已承认原则可纳入法律。【逐步演示】剩余分歧是原则能否消除所有选择、提供唯一正确答案。【易错提醒】这是理解二人后期争论的关键。"}, {"order": 11, "qtype": "multi", "stem": "关于法律的不确定性，下列符合哈特观点的有哪些？", "options": ["A 不确定性集中在规则边缘", "B 核心地带仍确定", "C 法官在某些案件须行使裁量", "D 法律整体是完全不确定的"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特主张不确定性局部而非整体。【逐步演示】核心确定，边缘需裁量，但规则中心地位不变。【易错提醒】D 是规则怀疑论的立场，哈特明确反对。"}, {"order": 12, "qtype": "essay", "stem": "试比较形式主义、规则怀疑论与哈特中间道路对法律不确定性的不同态度。", "options": [], "answer": "", "accepted": [], "keywords": [["形式主义：规则决定一切", "掩盖选择必要性"], ["规则怀疑论：规则是神话", "只有判决预测"], ["哈特：核心确定边缘不确定", "开放结构"], ["中间道路", "填补空隙的裁量"]], "explanation": "【答案要点】见 keywords。【解题思路】先述三种立场，再述哈特如何取中。【逐步演示】形式主义与怀疑论各执一端，哈特以核心／边缘结构承认局部不确定性。【易错提醒】避免把哈特等同于任何一端。"}, {"order": 13, "qtype": "essay", "stem": "结合 Riggs v. Palmer 案，分析哈特与德沃金关于『疑难案件是否有唯一正确答案』的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["不得从错误中获利原则", "限制遗嘱继承规则"], ["德沃金：原则提供唯一正确答案", "建构性诠释"], ["哈特：原则冲突仍需选择", "裁量无法消除"], ["同一案件支持两种解读"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，对比两人对同一案件的不同解读。【逐步演示】德沃金视原则给出唯一正解；哈特认为两原则冲突时法律未定优先顺序，仍需选择。【易错提醒】哈特并非否认原则作用，只否认其能彻底消除选择。"}]}, "S3M1K7": {"lesson": "S3M1K7", "questions": [{"order": 1, "qtype": "single", "stem": "哈特『最低限度的自然法』学说的核心目标是：", "options": ["A 实现最大多数人的最大幸福", "B 生存（survival）", "C 实现绝对正义", "D 维护主权者权威"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特以生存为出发点，推导法律必须具备的最低内容。【逐步演示】若没有某些最低内容，人们结合成社会以求得生存的目的就无法实现。【易错提醒】生存目标设定较低，与自然法的『共同善』话语不同。"}, {"order": 2, "qtype": "multi", "stem": "根据哈特，下列哪些属于支撑最低限度自然法的『自然事实』？", "options": ["A 人的脆弱性", "B 大致平等", "C 有限的利他主义与有限的资源", "D 有限的理解力与意志力"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】哈特列出五项自然事实，四个选项均在其中。【逐步演示】这些事实为法律应当包含特定内容提供了理由。【易错提醒】五项事实是哈特明确列举的，需准确记忆。"}, {"order": 3, "qtype": "single", "stem": "哈特区分了自然事实与法律规则之间的两类关联，其中构成最低限度自然法基础的是：", "options": ["A 因果关联", "B 基于目的的理性关联", "C 语义关联", "D 逻辑关联"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特区分因果关联（原因不是理由）与基于目的的理性关联。【逐步演示】若生存是目标，某些规则就是必要手段，因而有理由存在。【易错提醒】不要把因果上的必要条件误当作理由。"}, {"order": 4, "qtype": "judge", "stem": "哈特认为，由于最低限度自然法的存在，任何不道德的规则都自动丧失法律效力。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特坚持最低内容是『自然必要性』而非概念必然，不决定『是不是法律』。【逐步演示】承认某规则是法律，不妨碍道德上谴责它。【易错提醒】这正是哈特与自然法『恶法非法』的分野。"}, {"order": 5, "qtype": "blank", "stem": "哈特把基于人的自然事实与生存目标的必要性称为______ necessity（自然必要性）。", "options": [], "answer": "", "accepted": ["自然", "natural", "自然的"], "keywords": [], "explanation": "【答案】自然（natural）必要性。【解题思路】哈特以『自然必要性』描述最低内容的地位。【逐步演示】它既非语义必然，也非单纯事实，而是基于目标的实践必然。【易错提醒】不要答成『逻辑必然』或『概念必然』。"}, {"order": 6, "qtype": "single", "stem": "按照哈特，最低限度的自然法要求法律具备的核心内容不包括：", "options": ["A 禁止杀害与人身伤害", "B 对财产的最低尊重", "C 使承诺具有约束力", "D 确保所有人都享有同等财富"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】哈特的最低内容包括人身保护、财产与承诺。【逐步演示】它并不要求财富平等，更不保证惠及所有人。【易错提醒】最低内容『单薄』，不能等同于现代完整人权清单。"}, {"order": 7, "qtype": "judge", "stem": "哈特强调，一个社会要生存，必须把相互克制制度的保护扩展到其疆域内的所有人。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确指出社会只需对『某些人』提供相互克制，未必惠及所有人。【逐步演示】奴隶制与种族隔离社会的事实即为明证。【易错提醒】这一限定是哈特保持分离命题一致性的关键。"}, {"order": 8, "qtype": "single", "stem": "与传统自然法（如阿奎那）相比，哈特最低限度自然法的独特性在于：", "options": ["A 主张恶法非法", "B 以经验的人性与生存目标为基础，且不否认不义法律仍是法律", "C 完全否认法律与道德的任何联系", "D 以神的理性为法律基础"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特的版本是经验的自然法，基于人性与生存，且不把不义法律逐出法律概念。【逐步演示】它吸收自然法的『稳健内核』，却保持实证主义的分离命题。【易错提醒】哈特并未完全否认法律与道德的事实联系。"}, {"order": 9, "qtype": "single", "stem": "哈特在第五章讨论『仅有初级规则的社会』时，已提到规则必须包含某些限制，这与第九章的哪一学说相呼应？", "options": ["A 承认规则理论", "B 最低限度的自然法", "C 开放结构理论", "D 规则怀疑论"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】第五章提到初级规则社会必须限制暴力、偷窃与欺骗，正是最低限度自然法的前奏。【逐步演示】两处都基于人性与共存的需要。【易错提醒】这是哈特理论前后呼应的体现。"}, {"order": 10, "qtype": "multi", "stem": "关于最低限度的自然法，下列符合哈特观点的有哪些？", "options": ["A 它是基于目的的理性关联而非因果关联", "B 它是『自然必要性』而非概念必然", "C 它不否认不义法律仍是法律", "D 它要求法律与道德在概念上必然同一"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特把最低内容定位为基于目的的必然，不否认不义法律的法律地位。【逐步演示】D 是传统自然法立场，哈特明确反对。【易错提醒】注意把握哈特在自然法与实证主义之间的微妙平衡。"}, {"order": 11, "qtype": "judge", "stem": "哈特认为，人的脆弱性、大致平等等自然事实是法律产生的原因，因此因果上决定了法律的内容。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特强调这些事实为法律内容提供的是『理由』，而非仅仅是因果条件。【逐步演示】原因是事实，理由则关联于有意识的目标（生存）。【易错提醒】混淆因果关联与理性关联是对哈特最常见的误读。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特最低限度自然法的论证结构，并说明它如何与实证主义的分离命题相容。", "options": [], "answer": "", "accepted": [], "keywords": [["五项自然事实", "生存目标"], ["基于目的的理性关联", "自然必要性"], ["最低内容：人身/财产/承诺", "相互克制"], ["不决定效力判准", "相容于分离命题"]], "explanation": "【答案要点】见 keywords。【解题思路】先述论证结构，再述相容性。【逐步演示】从自然事实与生存目标推出最低内容，其必然性是实践的而非概念的，故不冲击分离命题。【易错提醒】避免把最低内容说成判定法律效力的标准。"}, {"order": 13, "qtype": "essay", "stem": "结合《世界人权宣言》(1948)，分析最低限度自然法的现实意义及其与尊严话语的张力。", "options": [], "answer": "", "accepted": [], "keywords": [["生命/财产/契约权利", "对应最低内容"], ["1948年联合国大会", "历史语境"], ["尊严话语 vs 生存论证", "方法论差异"], ["最低内容单薄", "不等于完整人权清单"]], "explanation": "【答案要点】见 keywords。【解题思路】以宣言切入，说明内容对应与方法论差异。【逐步演示】宣言的生命、财产、契约权对应最低内容；但其以尊严为基础，与哈特以生存为基础不同。【易错提醒】不要简单等同两种论证，哈特的最低内容较单薄。"}]}, "S3M2K1": {"lesson": "S3M2K1", "questions": [{"order": 1, "qtype": "single", "stem": "哈特『分离命题』的准确含义是：", "options": ["A 法律与道德事实上毫无关系", "B 法律不需要道德", "C 是不是法律与是不是道德上正当在概念上可分开判断", "D 恶法应当被遵守"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】分离命题是概念性主张：效力判断与道德评价可分开。【逐步演示】哈特承认法律与道德在事实层面常相互渗透。【易错提醒】A、B、D 都是对分离命题的漫画化，哈特明确反对。"}, {"order": 2, "qtype": "single", "stem": "1958 年哈特—富勒论战主要围绕什么问题展开？", "options": ["A 法律与道德是否必须分离", "B 国际法是否算法律", "C 法官是否应受判例约束", "D 宪法是否需要成文化"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】论战围绕法律与道德的关系展开。【逐步演示】双方围绕抵抗恶法、内在道德、极端邪恶体系是否仍是法律交锋。【易错提醒】论战发表于 1958 年《哈佛法律评论》，需记牢。"}, {"order": 3, "qtype": "multi", "stem": "富勒『法律的内在道德』包括下列哪些程序性要求？", "options": ["A 规则的一般性与公开性", "B 不溯及既往", "C 规则不矛盾、不要求不可能之事", "D 官方行动与宣布的规则一致"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】富勒的八项要求包括一般性、公开性、不溯及既往、清晰、不矛盾、不要求不可能之事、稳定性、官方行动与规则一致。【逐步演示】这些都是程序性而非实体性的道德要求。【易错提醒】不要与哈特的『最低限度自然法』（实体内容）混淆。"}, {"order": 4, "qtype": "judge", "stem": "哈特认为，承认一条规则是有效法律，逻辑上就意味着认可它在道德上是正当的。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确区分效力承认与道德认可。【逐步演示】可以承认恶法有效，同时坚决抵抗它。【易错提醒】这正是分离命题的核心，也是哈特反漫画化的重点。"}, {"order": 5, "qtype": "blank", "stem": "自然法理论的经典命题是『______』，意为严重违背正义的规则不是真正的法律。", "options": [], "answer": "", "accepted": ["恶法非法", "lex iniusta non est lex", "恶法非法（lex iniusta non est lex）", "不正义的法律不是法律"], "keywords": [], "explanation": "【答案】恶法非法（lex iniusta non est lex）。【解题思路】该命题体现法律与道德的必然联系。【逐步演示】二战后常用于批判纳粹法律。【易错提醒】与实证主义的『恶法亦法』（效力意义上）相对。"}, {"order": 6, "qtype": "single", "stem": "哈特对告密者案的分析，最接近下列哪一主张？", "options": ["A 纳粹法律不是法律，故妻子不能援引", "B 纳粹法律是有效但邪恶的法律，战后惩罚妻子需面对溯及既往的道德代价", "C 妻子的行为完全合法，不应受任何惩罚", "D 法律与道德完全无关，无需讨论"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特主张承认纳粹法有效，同时直面道德两难。【逐步演示】若以溯及既往的新法惩罚，就牺牲了法的安定性，这是必须诚实面对的抉择。【易错提醒】哈特反对用『纳粹法不是法律』的口号回避道德责任。"}, {"order": 7, "qtype": "judge", "stem": "富勒认为，法律严重违反其内在道德（如秘密法、溯及既往）时，就丧失了法律的资格。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】富勒把内在道德视为法律的概念要素。【逐步演示】纳粹法的秘密性与溯及既往使其丧失法律资格。【易错提醒】这与哈特『承认其有效但邪恶』形成对照。"}, {"order": 8, "qtype": "single", "stem": "哈特回应富勒时指出，把极端邪恶的规则排除出『法律』概念的危险在于：", "options": ["A 会使法律变得过于确定", "B 会遮蔽对恶法性质的认识，且未必增强抵抗", "C 会加强法的安定性", "D 会使法官失去自由裁量"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为否认恶法是法律会遮蔽其性质，也未必带来更好的抵抗。【逐步演示】承认它是法律，反而能更准确地定位需要变革的对象。【易错提醒】哈特并非为恶法张目，而是主张更清醒的批判。"}, {"order": 9, "qtype": "single", "stem": "关于分离命题，哈特在《后记》中承认的『柔性实证主义』是指：", "options": ["A 法律必须包含道德内容", "B 承认规则可以把道德原则纳入效力判准", "C 法律与道德在概念上必然同一", "D 法官应服从道德而非法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特承认某些体系的承认规则可纳入道德判准（如美国宪法）。【逐步演示】但这仍由社会事实决定，与分离命题相容。【易错提醒】柔性实证主义不等于自然法。"}, {"order": 10, "qtype": "multi", "stem": "根据本节，下列哪些是对分离命题的常见误读？", "options": ["A 法律不需要道德", "B 法律与道德事实上毫无关系", "C 恶法应当被遵守", "D 效力判断与道德评价应区分"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】A、B、C 都是哈特明确反对的漫画化。【逐步演示】D 才是分离命题的准确表述。【易错提醒】识别误读有助于准确理解哈特立场。"}, {"order": 11, "qtype": "judge", "stem": "哈特承认『最低限度的自然法』，这意味着他最终放弃了 separation thesis。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】最低限度自然法是『自然必要性』，不决定效力判准，与分离命题相容。【逐步演示】哈特借此吸收自然法洞见，却未放弃概念分离。【易错提醒】不要把哈特的折中说成立场背叛。"}, {"order": 12, "qtype": "essay", "stem": "试精确阐述哈特『分离命题』的含义，并分析为何把法律与道德分开反而有助于批判恶法。", "options": [], "answer": "", "accepted": [], "keywords": [["效力判断与道德评价分开", "概念性主张"], ["承认恶法为法", "不等于认可或服从"], ["更清醒定位变革对象", "更有理由抵抗"], ["反对漫画化", "承认事实联系与最低内容"]], "explanation": "【答案要点】见 keywords。【解题思路】先澄清含义，再述批判价值。【逐步演示】分离使效力判断清晰；承认恶法为法后用道德标准谴责它，比定义技巧更有力。【易错提醒】避免把分离命题说成『法律与道德无关』。"}, {"order": 13, "qtype": "essay", "stem": "结合告密者案，比较哈特与富勒对『极端邪恶法律是否为法律』的不同立场及其各自的力量与局限。", "options": [], "answer": "", "accepted": [], "keywords": [["哈特：有效但邪恶，直面两难", "承认法的安定性代价"], ["富勒：违反内在道德即非法律", "否认其资格"], ["哈特的力量", "诚实面对道德抉择"], ["富勒的力量", "强调法律的内在道德"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，对比两种立场。【逐步演示】哈特承认有效而邪恶、直面溯及既往代价；富勒以内在道德否认其法律资格。【易错提醒】注意双方各有力量与张力，避免简单判定胜负。"}]}, "S3M2K2": {"lesson": "S3M2K2", "questions": [{"order": 1, "qtype": "single", "stem": "富勒『法律的内在道德』主要指：", "options": ["A 法律内容必须符合的实体正义", "B 法律作为规则治理事业所固有的程序性要求", "C 法律必须服从主权者意志", "D 法官个人的道德信念"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】富勒的内在道德是程序性要求，从法律事业内部产生。【逐步演示】它与『外在道德』（实体价值）相区分。【易错提醒】不要把内在道德误解为实体正义。"}, {"order": 2, "qtype": "multi", "stem": "下列哪些属于富勒列举的法律内在道德要求？", "options": ["A 一般性、公开性", "B 不溯及既往、清晰性", "C 不矛盾、不要求不可能之事", "D 稳定性、官方行动与规则一致"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】富勒提出八项程序性要求，四个选项均涵盖。【逐步演示】这些要求旨在使法律成为有效的规则治理事业。【易错提醒】与哈特的『最低限度自然法』（实体内容）区分开。"}, {"order": 3, "qtype": "judge", "stem": "富勒认为，法律的内在道德是实体性的，要求法律内容必须实现特定的正义分配。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】富勒的内在道德是程序性的，外在道德才是实体性的。【逐步演示】他关心的是法律作为规则治理事业是否运作良好，而非具体内容是否正义。【易错提醒】注意程序／实体这一关键区分。"}, {"order": 4, "qtype": "blank", "stem": "富勒把法律界定为『使人类行为服从______治理的事业』。", "options": [], "answer": "", "accepted": ["规则", "rules", "规则治理", "规则的"], "keywords": [], "explanation": "【答案】规则（rules）。【解题思路】富勒的名言是『the enterprise of subjecting human conduct to the governance of rules』。【逐步演示】内在道德正从这项事业内部产生。【易错提醒】不要答成『道德』或『主权者』。"}, {"order": 5, "qtype": "single", "stem": "哈特对富勒内在道德的主要批评是：", "options": ["A 这些要求毫无价值", "B 把它们当作法律的必要条件会造成概念混乱，且可能只是效率要求", "C 法律应完全服从道德", "D 程序要求比实体正义更重要"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特承认这些要求有价值，但反对把它们当作法律的概念要素。【逐步演示】他认为有些只是效率要求，把缺乏内在道德等同于『不是法律』会造成混乱。【易错提醒】哈特并非全盘否定富勒。"}, {"order": 6, "qtype": "single", "stem": "哈特为法律提供的实体性道德基础是：", "options": ["A 法律的内在道德", "B 最低限度的自然法", "C 法律作为完整性", "D 主权者命令"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特以最低限度的自然法作为法律基于人性的实体最低内容。【逐步演示】它要求人身、财产与承诺的最低保护。【易错提醒】内在道德是富勒的概念，勿张冠李戴。"}, {"order": 7, "qtype": "judge", "stem": "富勒认为，严重违反内在道德（如秘密法、溯及既往）的法律体系，不仅是坏法律，甚至难以被称为法律。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】富勒把内在道德视为法律事业成功的前提。【逐步演示】严重缺陷使规则治理事业失败，从而丧失法律资格。【易错提醒】这与哈特『承认其有效但邪恶』形成对照。"}, {"order": 8, "qtype": "single", "stem": "关于合法性与正当性的关系，哈特的立场是：", "options": ["A 合法性自动等于正当性", "B 合法性是『自然善』，使法律有效运作，但不自动担保实质正当", "C 正当性完全无关紧要", "D 法律不需要合法性"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特把合法性定位为『自然善』而非正当性的充分条件。【逐步演示】程序完美的法律若内容邪恶，仍应被抵抗。【易错提醒】这是程序正义能否担保实质正义争论的核心。"}, {"order": 9, "qtype": "single", "stem": "《世界人权宣言》(1948) 在本文中被用来说明：", "options": ["A 法律与道德毫无关系", "B 法律的道德基础是多层面的，且尊严话语比生存目标更丰富", "C 程序合法性足以担保一切权利", "D 国际法不是法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】宣言既有程序性权利也有实体性权利，以尊严为基础。【逐步演示】它显示道德基础的多层面性，也提示哈特生存目标设定较低。【易错提醒】勿把宣言简单等同于哈特的最低内容。"}, {"order": 10, "qtype": "multi", "stem": "根据本节，法律的社会性道德基础涉及：", "options": ["A 官员从内部观点接受次级规则", "B 公民相当程度的自愿合作", "C 法律体系需要稳定才能存续", "D 法律必须与道德在概念上同一"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特指出法律权威需要某种程度的接受与合作。【逐步演示】D 是自然法立场，哈特明确反对。【易错提醒】注意社会性基础是事实条件，不是概念条件。"}, {"order": 11, "qtype": "judge", "stem": "德沃金『法律作为完整性』比富勒的内在道德更进一步，把实体道德重新引入法律的概念核心。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】德沃金要求法律在道德上为其强制提供最佳证成。【逐步演示】这超出了富勒纯程序性的内在道德。【易错提醒】理解三人（富勒、哈特、德沃金）立场的分际。"}, {"order": 12, "qtype": "essay", "stem": "试比较富勒『法律的内在道德』与哈特『最低限度的自然法』作为法律道德基础的不同。", "options": [], "answer": "", "accepted": [], "keywords": [["富勒：程序性八项要求", "内在道德"], ["哈特：实体最低内容", "基于人性与生存"], ["功能定位不同", "事业成功 vs 自然必要性"], ["是否构成法律概念要素", "富勒是，哈特否"]], "explanation": "【答案要点】见 keywords。【解题思路】从性质、内容、功能三方面对比。【逐步演示】富勒重程序且视为法律要素，哈特重实体最低内容且视为自然必要性。【易错提醒】不要把两个概念混用。"}, {"order": 13, "qtype": "essay", "stem": "结合《世界人权宣言》，论述法律的道德基础是否仅限于程序合法性，并评价富勒与哈特各自的解释力。", "options": [], "answer": "", "accepted": [], "keywords": [["宣言含程序与实体权利", "以尊严为基础"], ["富勒：程序合法性", "解释程序权利"], ["哈特：最低内容", "解释生命财产契约权"], ["尊严话语更丰富", "程序合法性不足"]], "explanation": "【答案要点】见 keywords。【解题思路】以宣言切入，评价两种解释。【逐步演示】富勒解释程序权利，哈特解释最低实体权利，但尊严话语支撑的内容更丰富。【易错提醒】避免断言程序合法性足以担保实质正义。"}]}, "S3M2K3": {"lesson": "S3M2K3", "questions": [{"order": 1, "qtype": "single", "stem": "『恶法非法』（lex iniusta non est lex）这一命题最接近于：", "options": ["A 法律实证主义", "B 自然法理论", "C 法律现实主义", "D 分析法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】恶法非法主张严重违背正义的规则不是真正的法律，体现法律与道德的必然联系。【逐步演示】这是自然法的核心命题，二战后常用于批判纳粹法律。【易错提醒】与实证主义『恶法亦法』（效力意义上）相对。"}, {"order": 2, "qtype": "single", "stem": "拉德布鲁赫公式的核心内容是：", "options": ["A 一切不正义的法律都自动无效", "B 当法律与正义冲突达到不可容忍程度时，正义压倒法的安定性", "C 法律永远优先于正义", "D 法官可凭个人好恶否定法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】拉德布鲁赫以『不可容忍性』为门槛，极端情形下正义压倒安定性。【逐步演示】日常案件仍维护法的安定性，例外仅限极端情形。【易错提醒】它不是『一切不正义法律都无效』。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，承认一条极端邪恶的规则是有效法律，逻辑上就等于认可人们应当服从它。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特严格区分『是不是法律』与『该不该服从』。【逐步演示】承认恶法有效，恰是为了更清醒地批判与抵抗它。【易错提醒】这是哈特反漫画化的核心。"}, {"order": 4, "qtype": "blank", "stem": "拉德布鲁赫公式中，决定正义能否压倒法的安定性的关键标准是法律与正义冲突的______性。", "options": [], "answer": "", "accepted": ["不可容忍", "intolerable", "不可容忍性", "极端"], "keywords": [], "explanation": "【答案】不可容忍（性）。【解题思路】拉德布鲁赫以 intolerability 为门槛。【逐步演示】只有冲突不可容忍时才触发正义优先。【易错提醒】这个门槛本身的模糊性正是该公式受批评之处。"}, {"order": 5, "qtype": "single", "stem": "哈特反对用『恶法非法』来谴责纳粹法律，主要理由是：", "options": ["A 纳粹法律其实是正义的", "B 否认其法律资格会遮蔽其性质，且不利于准确定位需要变革的制度", "C 法官没有道德判断能力", "D 法律与道德毫无关系"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为承认恶法为法能更准确诊断问题。【逐步演示】纳粹暴行正是通过有效法律制度实施的，需要变革的正是这套制度。【易错提醒】哈特并非为纳粹辩护，而是主张更清醒的批判。"}, {"order": 6, "qtype": "multi", "stem": "围绕『恶法是否非法』的争论，涉及下列哪些主线？", "options": ["A 恶法是否仍是法律", "B 用『非法』谴责是否更有力", "C 法的安定性与正义的权衡", "D 法律是否必须由主权者制定"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三条主线分别是效力问题、谴责方式与安定性/正义权衡。【逐步演示】D 属于命令理论的话题，与本争论无直接关联。【易错提醒】聚焦争论的三条主线。"}, {"order": 7, "qtype": "judge", "stem": "德沃金区分诠释意义与诠释前意义，承认极端邪恶法律可在诠释前意义上是法律，这一让步被哈特视为向实证主义靠拢。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特认为德沃金的区分实际承认了效力判断可脱离道德。【逐步演示】这削弱了德沃金对实证主义的批评。【易错提醒】德沃金仍保留其诠释性立场。"}, {"order": 8, "qtype": "single", "stem": "纽伦堡审判（1945–1946）中，被告常提出的抗辩是：", "options": ["A 行为依当时有效的德国法律行事（含执行上级命令）", "B 行为完全符合国际法", "C 法庭没有管辖权", "D 行为未造成实际损害"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】被告主张依当时法律与命令行事，引出溯及既往与恶法问题。【逐步演示】审判确立了个人对国际社会的义务高于国家法律。【易错提醒】年份与法庭需记牢。"}, {"order": 9, "qtype": "single", "stem": "实证主义对『恶法非法』的主要担忧是：", "options": ["A 会使法律过于确定", "B 人人可自定正义标准宣称法律无效，瓦解法的安定性", "C 会加强法官服从法律的习惯", "D 会使法律失去道德色彩"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特等担心以道德否定效力会打开主观判断的闸门。【逐步演示】若人人可宣称不认同的法律非法，法治的安定性将受损。【易错提醒】这是实证主义的核心顾虑。"}, {"order": 10, "qtype": "judge", "stem": "哈特承认，在极端邪恶的情形下，人们可以选择不把某体系称为法律，但这是道德抉择而非概念真理。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特在《后记》中回应德沃金的内部怀疑论时承认这种可能性。【逐步演示】但他强调这是选择，不是『恶法非法』的概念必然。【易错提醒】这体现哈特立场的微妙。"}, {"order": 11, "qtype": "multi", "stem": "关于『恶法非法』与『恶法亦法』，下列符合哈特观点的有哪些？", "options": ["A 邪恶规则可以是有效法律", "B 承认其有效不等于认可其道德正当", "C 应抵抗极端邪恶的法律", "D 邪恶规则在概念上不可能是法律"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特主张恶法可有效，但应受道德抵抗。【逐步演示】D 是自然法立场，哈特反对。【易错提醒】把握哈特的两面：效力上承认、道德上抵抗。"}, {"order": 12, "qtype": "essay", "stem": "试比较自然法的『恶法非法』与实证主义的『恶法亦法』，并说明哈特为何认为承认恶法为法反而更有助于批判。", "options": [], "answer": "", "accepted": [], "keywords": [["自然法：正义是法律概念要素", "恶法非法"], ["实证主义：效力取决于社会来源", "恶法亦法"], ["哈特：区分效力与服从", "承认有效但邪恶"], ["更准确定位变革对象", "避免定义技巧回避"]], "explanation": "【答案要点】见 keywords。【解题思路】先对比两立场，再述哈特理由。【逐步演示】哈特认为承认恶法为法可准确诊断制度问题，并避免用定义回避道德抉择。【易错提醒】勿把哈特等同于『恶法应当服从』。"}, {"order": 13, "qtype": "essay", "stem": "结合纽伦堡审判，评价拉德布鲁赫公式在平衡正义与法安定性上的贡献与局限。", "options": [], "answer": "", "accepted": [], "keywords": [["不可容忍性门槛", "正义压倒安定性"], ["贡献：提供折中框架", "兼顾极端不义"], ["局限：门槛模糊", "仍需主观判断"], ["纽伦堡的安定性代价", "溯及既往难题"]], "explanation": "【答案要点】见 keywords。【解题思路】以审判切入，评价公式。【逐步演示】公式以不可容忍性为门槛提供折中，但门槛本身模糊，且突破实定法必付安定性代价。【易错提醒】避免只讲贡献或只讲局限。"}]}, "S3M2K4": {"lesson": "S3M2K4", "questions": [{"order": 1, "qtype": "judge", "stem": "哈特认为，抢匪用枪逼你交出钱包，你『不得不』交，但并没有交钱包的『义务』。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特区分 obliged（被迫）与 obligation（义务）。【逐步演示】威胁只能产生事实服从，义务预设规则被内部接受为正当标准。【易错提醒】这是批判奥斯丁命令理论的经典论据。"}, {"order": 2, "qtype": "single", "stem": "按照哈特，义务概念的社会基础是：", "options": ["A 存在强大的制裁机关", "B 规则被成员从内部观点接受为行为标准", "C 主权者的命令", "D 多数人的恐惧"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】义务存在于规则被当作『理所当然应当做』而被内部接受的社会。【逐步演示】偏离会招致批评，这是义务与被迫的根本区别。【易错提醒】制裁不是义务的基础，而是担保。"}, {"order": 3, "qtype": "single", "stem": "哈特在讨论法律义务时，把制裁的角色定位为：", "options": ["A 服从的主要动机", "B 保证本会自愿守法者不被不守法者牺牲的担保", "C 义务的唯一来源", "D 法律的全部本质"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为制裁是『担保』而非主要动机。【逐步演示】在健康社会中，多数人从内部观点接受法律，守法是习惯性的。【易错提醒】把义务化约为制裁是命令理论的根本错误。"}, {"order": 4, "qtype": "multi", "stem": "根据本节，法律义务相对于道德义务的特殊性包括：", "options": ["A 来源于被承认规则识别的有效规则", "B 有官方强制力作为保障", "C 有法院等权威机关判定是否违反", "D 完全依靠个人良知维系"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】法律义务有明确来源、官方保障与权威判定机关。【逐步演示】D 是道德义务的特征，不是法律义务的。【易错提醒】注意不要把两类特征混淆。"}, {"order": 5, "qtype": "judge", "stem": "哈特认为，承认一条规则施加了法律义务，也就承认了它在道德上正当、应当被服从。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特区分效力问题与道德评价。【逐步演示】邪恶法律也能施加法律义务，但道德上应被抵抗。【易错提醒】这是分离命题在义务层面的体现。"}, {"order": 6, "qtype": "single", "stem": "德沃金关于法律权利义务的核心主张是：", "options": ["A 法律义务与道德义务毫无关系", "B 法律权利必具有某种道德力量，是道德权利的种类", "C 义务完全来自制裁", "D 法官不应考虑道德"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金认为法律权利必然带有道德力量。【逐步演示】哈特在《后记》中反驳这混淆了效力与道德评价。【易错提醒】这是二人争论在义务层面的体现。"}, {"order": 7, "qtype": "blank", "stem": "哈特用抢匪的例子区分了『______』（obliged，被迫）与『______』（obligation，义务）。", "options": [], "answer": "", "accepted": ["被迫；义务", "obliged; obligation", "不得不；有义务", "被迫；有义务"], "keywords": [], "explanation": "【答案】被迫／义务（obliged / obligation）。【解题思路】这是哈特批判命令理论的经典区分。【逐步演示】威胁产生被迫，规则的内部接受产生义务。【易错提醒】两个词形近义异，需准确区分。"}, {"order": 8, "qtype": "single", "stem": "南非真相与和解委员会（TRC）案例主要说明：", "options": ["A 法律义务永远高于道德义务", "B 法律义务可通过法律程序被改变，道德考量常深层塑造这种改变", "C 道德义务不能被法律承认", "D 转型正义与法律无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】TRC 通过赦免法改变追诉义务，体现道德对法律义务的重塑。【逐步演示】旧制度下的行为在道德上恶劣，转型选择以和解替代报复。【易错提醒】勿把 TRC 简单看作『无视法律』。"}, {"order": 9, "qtype": "judge", "stem": "法律义务与道德义务在内容上可能重合，也可能分离；邪恶法律施加的义务没有道德正当性。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】二者内容可重合（如不得杀人）也可分离（如邪恶法律）。【逐步演示】纳粹法律施加的义务就是有效但无道德正当性的例子。【易错提醒】这体现哈特分离命题的贯彻。"}, {"order": 10, "qtype": "single", "stem": "奥斯丁用制裁定义义务，哈特对此的批评是：", "options": ["A 制裁毫无作用", "B 制裁能解释被迫，却解释不了义务的规范体验", "C 义务不需要规则", "D 法律义务就是道德义务"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特认为制裁解释不了义务的『应当』维度。【逐步演示】义务来自规则被内部接受，而非威胁。【易错提醒】哈特并未否认制裁的作用，只反对其作为义务的本质。"}, {"order": 11, "qtype": "multi", "stem": "关于法律义务与道德义务，下列符合哈特观点的有哪些？", "options": ["A 二者都有『被当作应当』的规范结构", "B 法律义务由有效规则施加", "C 道德义务依靠良知与社会评价", "D 二者在概念上必然同一"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特承认二者规范结构相似，但来源与维系方式不同。【逐步演示】D 与哈特的分离立场相悖。【易错提醒】把握『结构相似、来源有别』。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特关于『义务』的分析，并说明为什么『被迫』不等于『有义务』。", "options": [], "answer": "", "accepted": [], "keywords": [["义务是规范地位", "源于规则被内部接受"], ["抢匪例子", "obliged vs obligation"], ["制裁只是担保", "非主要动机"], ["义务 vs 被迫", "规范体验不同"]], "explanation": "【答案要点】见 keywords。【解题思路】先定义义务，再用抢匪例子说明。【逐步演示】义务预设规则被当作正当标准接受，威胁只产生事实服从。【易错提醒】避免把义务还原为制裁或恐惧。"}, {"order": 13, "qtype": "essay", "stem": "结合南非真相与和解委员会案例，分析法律义务与道德义务的冲突及其通过法律程序的解决。", "options": [], "answer": "", "accepted": [], "keywords": [["旧制度下行为形式合法", "道德上恶劣"], ["追诉义务与和解目标冲突", "道德判断"], ["赦免法改变义务", "承认规则变化"], ["道德深层塑造法律义务"]], "explanation": "【答案要点】见 keywords。【解题思路】以 TRC 切入，分析冲突与解决。【逐步演示】新程序解除旧义务，道德考量通过法律形式重塑义务内容。【易错提醒】不要断言哈特框架能完全解释转型正义中的道德维度。"}]}, "S3M2K5": {"lesson": "S3M2K5", "questions": [{"order": 1, "qtype": "single", "stem": "按照哈特，法律权威与纯粹强力的根本区别在于：", "options": ["A 强力更有效", "B 权威提供行为理由，使人『应当』服从；强力只使人『不得不』服从", "C 权威不需要被接受", "D 强力总是正当的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特区分强力的『迫使』与权威的『提供理由』。【逐步演示】权威被从内部观点接受为行为理由，强力只产生事实服从。【易错提醒】不要混淆权力（power）、强力（force）与权威（authority）。"}, {"order": 2, "qtype": "single", "stem": "哈特认为，一个法律体系『有效』（存在）与『正当』的关系是：", "options": ["A 有效必然正当", "B 有效是事实问题，正当是道德问题，二者可分离", "C 正当必然有效", "D 二者完全无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特区分有效性（事实）与正当性（道德）。【逐步演示】邪恶体系可能有效却不正当。【易错提醒】D 错在『完全无关』，哈特承认二者有事实关联。"}, {"order": 3, "qtype": "judge", "stem": "哈特主张，只有当人们从道德上认同法律时，法律体系才存在。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法律体系的存在取决于两个最低条件（普遍服从＋官员接受），不依赖道德认同。【逐步演示】接受可出于利益、传统、从众等多种动机。【易错提醒】这与自然法把正当性作为法律性要素不同。"}, {"order": 4, "qtype": "blank", "stem": "拉兹提出的权威理论认为，权威的正当性在于它能更好地服务于被治者，这被称为______权威观。", "options": [], "answer": "", "accepted": ["服务性", "服务", "service conception", "服务的", "服务性权威观"], "keywords": [], "explanation": "【答案】服务性（service conception）。【解题思路】拉兹的服务性权威观把正当性建立在权威服务于被治者理性利益之上。【逐步演示】权威通过协调行动、解决分歧而证成自身。【易错提醒】这是拉兹的理论，不要与哈特混淆。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，法律权威的稳定预设了某种自愿接受，这种接受可以出于哪些动机？", "options": ["A 长期利益计算", "B 利他或传统态度", "C 从众心理", "D 必然是道德认同"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特列举多种接受动机，不必然是道德认同。【逐步演示】人们甚至可能在道德上不认同却仍接受。【易错提醒】D 与哈特立场相悖。"}, {"order": 6, "qtype": "single", "stem": "布朗诉教育委员会案（Brown v. Board of Education, 1954）在权威正当性讨论中的意义在于：", "options": ["A 证明形式有效的法律无需正当性", "B 显示形式有效的隔离法律因违背平等而丧失正当性", "C 确立主权者不受限制", "D 否定宪法解释的作用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】隔离法律形式有效却道德不义，法院通过宪法诠释解决正当性危机。【逐步演示】效力与正当性的分离在案中凸显。【易错提醒】年份为 1954，推翻了 Plessy v. Ferguson 的『隔离但平等』。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，是否服从法律是一个开放的道德问题，不能一般性地断言人们有服从法律的道德义务。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特把服从法律视为开放的道德问题。【逐步演示】是否服从取决于具体法律的道德品质。【易错提醒】这与主张一般性服从义务的自然法立场不同。"}, {"order": 8, "qtype": "single", "stem": "关于『事实权威』与『合法权威』的区分，正确的是：", "options": ["A 事实权威必然正当", "B 事实权威是事实上被服从，合法权威是道德上被证成", "C 合法权威不被人服从", "D 二者完全相同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】de facto 权威重事实服从，de jure 权威重道德证成。【逐步演示】一个政权可能事实上有权威却缺乏正当性。【易错提醒】注意区分事实判断与道德判断。"}, {"order": 9, "qtype": "single", "stem": "哈特对正当性问题保持克制，主要致力于：", "options": ["A 提供实质的正当性理论", "B 描述法律权威的结构与存在条件", "C 证明所有法律都正当", "D 否定道德的作用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特的描述性法理学重在描述结构与存在条件。【逐步演示】拉兹才提供实质正当性理论（服务性权威观）。【易错提醒】‘克制’不等于‘否定道德’。"}, {"order": 10, "qtype": "multi", "stem": "下列关于哈特权威观的说法，正确的有哪些？", "options": ["A 权威提供行为理由", "B 有效性与正当性可分离", "C 接受可出于多种动机", "D 正当性是法律性的内在要素"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特主张权威提供理由、有效与正当可分、接受动机多样。【逐步演示】D 是自然法立场，哈特反对。【易错提醒】把握哈特作为描述性实证主义者的特点。"}, {"order": 11, "qtype": "judge", "stem": "拉兹的服务性权威观认为，权威的正当性在于它是否真正服务于被治者的理性利益。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】拉兹把正当性建立在权威的协调功能上。【逐步演示】权威帮助人们更好地遵循理性，从而证成自身。【易错提醒】这是拉兹而非哈特的核心主张。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特如何区分法律的有效性（validity）与正当性（legitimacy），并说明这一区分的意义。", "options": [], "answer": "", "accepted": [], "keywords": [["有效性是事实问题", "两个最低条件"], ["正当性是道德问题", "值得服从"], ["邪恶体系可有效不正当", "分离命题"], ["意义：保留批判空间", "准确诊断"]], "explanation": "【答案要点】见 keywords。【解题思路】先区分两个概念，再述意义。【逐步演示】有效性由社会事实决定，正当性由道德决定；承认恶法有效但不当，使批判更准确。【易错提醒】不要说二者『完全无关』。"}, {"order": 13, "qtype": "essay", "stem": "结合布朗案与拉兹的服务性权威观，分析法律权威的正当性如何可能以及如何维系。", "options": [], "answer": "", "accepted": [], "keywords": [["隔离法律有效但不正当", "违背平等"], ["法院通过宪法诠释变革", "承认规则调整"], ["拉兹：服务于理性利益", "正当性基础"], ["正当性需不断反思维系"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，联系拉兹理论。【逐步演示】形式有效不足以保证正当，须通过诠释使法律服务于平等价值。【易错提醒】注意哈特（描述）与拉兹（实质正当性）的侧重差异。"}]}, "S3M3K1": {"lesson": "S3M3K1", "questions": [{"order": 1, "qtype": "single", "stem": "下列关于『模糊性』（Vagueness）与『歧义』（Ambiguity）的区分，正确的是：", "options": ["A 二者完全相同", "B 模糊性指边界情形不清，歧义指语词有多个确定含义", "C 歧义指边界不清", "D 模糊性可通过语境完全消除"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】模糊性是边界情形问题，歧义是多个确定含义问题。【逐步演示】歧义常可通过语境消除，模糊性则无法彻底消除。【易错提醒】勿把二者混为一谈。"}, {"order": 2, "qtype": "judge", "stem": "哈特认为，解释规则可以层层递进地彻底消除法律语言的模糊性。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】解释规则本身也由一般语词构成，也会遇到模糊性。【逐步演示】它们只能减少而不能消除不确定性。【易错提醒】『减少』与『消除』是本题关键。"}, {"order": 3, "qtype": "single", "stem": "哈特在《后记》中强调，一般语词之所以可用于交流，是因为存在：", "options": ["A 抽象定义", "B 典范情形（paradigm cases）", "C 完美词典", "D 法官共识"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特强调典范情形使语言交流成为可能。【逐步演示】边界情形的处理参照清楚实例判断类似性。【易错提醒】这是哈特回应德沃金的重要概念。"}, {"order": 4, "qtype": "blank", "stem": "语词适用毫无疑问的清楚情形称为______，是否适用存在疑问的模糊情形称为______。", "options": [], "answer": "", "accepted": ["核心；边缘", "核心地带；边缘地带", "core; penumbra", "典范情形；边界情形"], "keywords": [], "explanation": "【答案】核心／边缘（或典范情形／边界情形）。【解题思路】哈特以清楚核心与模糊边缘描述语词的适用结构。【逐步演示】核心使交流可能，边缘需要判断。【易错提醒】不要把『核心』理解为语词的中心词义。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，法律体系应对语言模糊性的技术包括：", "options": ["A 解释规则减少不确定性", "B 委任立法把标准具体化", "C 判例逐步划定边界", "D 通过宪法审查宣告模糊法律无效"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】这些都是法律体系中管理模糊性的技术。【逐步演示】它们共同点是『管理』而非『彻底消除』模糊性。【易错提醒】哈特认为模糊性不可彻底消除。"}, {"order": 6, "qtype": "single", "stem": "Smith v. Goguen (1974) 案中，最高法院判决相关法律违宪的主要理由是：", "options": ["A 法律太严厉", "B 法律过于模糊（void for vagueness），无法提供明确指引且导致任意执法", "C 法律违反平等保护", "D 法院没有管辖权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】void for vagueness 原则要求刑事法律足够明确。【逐步演示】『轻蔑对待国旗』边界不清，赋予执法者过大裁量。【易错提醒】年份为 1974，属美国最高法院判例。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，模糊性只存在于法律语词的边缘，法律生活的主体仍由确定规则构成。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特反对规则怀疑论借模糊性否定规则整体。【逐步演示】典范情形与核心领域仍使法律具有确定性。【易错提醒】这体现哈特的中间道路。"}, {"order": 8, "qtype": "single", "stem": "关于模糊性与开放结构的关系，下列说法正确的是：", "options": ["A 二者毫无关系", "B 开放结构是模糊性在法律语境中的表现", "C 模糊性只存在于文学语言", "D 开放结构可以被完全消除"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】开放结构是一般语词模糊性在法律适用中的体现。【逐步演示】当规则语词在边缘地带适用不确定，即需要选择。【易错提醒】开放结构不能被完全消除。"}, {"order": 9, "qtype": "single", "stem": "德沃金与哈特（及恩迪科特）在模糊性问题上的主要分歧是：", "options": ["A 语言是否有模糊性", "B 模糊性背后是否夹杂价值判断、法律概念是否是解释性概念", "C 法官是否应适用法律", "D 法律是否需要语言"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金强调法律概念的解释性与评价性，哈特区分语义模糊与价值分歧。【逐步演示】恩迪科特为哈特的典范情形说辩护。【易错提醒】双方都不否认语言有模糊现象。"}, {"order": 10, "qtype": "judge", "stem": "立法者使用『合理注意』『公平费率』等模糊标准，往往是为了把具体判断交给更接近情境的机关。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特指出模糊标准在变化多端的领域比僵硬规则更适应情境。【逐步演示】判断被交给法院或行政机关。【易错提醒】模糊性不全是消极的，也有功能面向。"}, {"order": 11, "qtype": "multi", "stem": "下列关于法律语言模糊性的说法，符合哈特观点的有哪些？", "options": ["A 它源于语言性质与人的有限性", "B 它不可被解释规则彻底消除", "C 典范情形使语言交流成为可能", "D 它必然导致法律完全不确定"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特主张模糊性必然、不可消除、有典范情形。【逐步演示】D 是规则怀疑论立场，哈特反对。【易错提醒】警惕把模糊性夸大为全面不确定。"}, {"order": 12, "qtype": "essay", "stem": "试述法律语言模糊性的性质与来源，并说明哈特为何认为它不能被彻底消除。", "options": [], "answer": "", "accepted": [], "keywords": [["模糊性是边界情形问题", "与歧义区分"], ["源于语言与人的有限性", "不可还原的开放纹理"], ["解释规则自身也模糊", "无法自我解释"], ["典范情形与边缘", "管理而非消除"]], "explanation": "【答案要点】见 keywords。【解题思路】先界定性质与来源，再述不可消除的理由。【逐步演示】解释规则本身由一般语词构成，故只能管理模糊性。【易错提醒】避免把模糊性等同于歧义。"}, {"order": 13, "qtype": "essay", "stem": "结合 Smith v. Goguen 案，分析法律体系如何『管理』语言模糊性，并评价 void for vagueness 原则的局限。", "options": [], "answer": "", "accepted": [], "keywords": [["轻蔑对待国旗边界模糊", "1974年"], ["void for vagueness", "宣告模糊法律无效"], ["管理而非消除模糊", "限制任意执法"], ["局限：价值判断", "需实质标准"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，说明管理方式及其局限。【逐步演示】宪法原则限制模糊性的危害，但这一原则本身需实质价值判断。【易错提醒】勿把 void for vagueness 说成彻底消除模糊。"}]}, "S3M3K2": {"lesson": "S3M3K2", "questions": [{"order": 1, "qtype": "single", "stem": "关于司法解释的性质，哈特的核心立场是：", "options": ["A 解释只是机械探求唯一正确答案", "B 解释是法律适用的常态，核心近乎自动、边缘包含受约束的选择", "C 解释纯粹是法官任意造法", "D 法律不需要解释"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特取形式主义与怀疑论之间的中间立场。【逐步演示】核心地带解释近乎自动，边缘地带选择受规则目的与原则约束。【易错提醒】避免把哈特归入任一极端。"}, {"order": 2, "qtype": "single", "stem": "德沃金所说的『建构性诠释』（constructive interpretation）要求法官寻找：", "options": ["A 立法者的心理意图", "B 既适合既有法律实践又能提供最佳道德证成的原则", "C 法律的字面含义", "D 多数人的意见"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】建构性诠释强调 fit 与 moral justification 双重标准。【逐步演示】由此把法律理解为『完整性』。【易错提醒】不要把它等同于原意主义或文本主义。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，法院的司法解释在体系内具有终局性，因此它在道德上必然无误。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特区分终局性（finality）与无误性（infallibility）。【逐步演示】解释在体系内终局，但可被上级法院推翻或立法修正。【易错提醒】不要把『权威』等同于『正确』。"}, {"order": 4, "qtype": "blank", "stem": "德沃金把司法解释理解为一种______诠释，并主张法律是一种『完整性』的事业。", "options": [], "answer": "", "accepted": ["建构性", "constructive", "建构性的", "constructive interpretation"], "keywords": [], "explanation": "【答案】建构性（constructive）。【解题思路】德沃金的核心概念是 constructive interpretation。【逐步演示】它要求诠释既适合实践又有最佳道德证成。【易错提醒】这是德沃金而非哈特的概念。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特，约束司法解释中选择的因素包括：", "options": ["A 典范情形", "B 规则的目的", "C 既有法律原则", "D 法官的纯粹个人偏好"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特认为边缘选择受典范情形、目的与原则约束。【逐步演示】因此裁量是『填补空隙的』，而非任意的。【易错提醒】D 与哈特立场相悖。"}, {"order": 6, "qtype": "single", "stem": "Pepper v Hart [1993] 案在英国司法解释史上的意义是：", "options": ["A 确立法院可参考 Hansard 探求立法意图（在语词模糊时）", "B 确立法院必须忽略立法意图", "C 否定成文法的效力", "D 确立法官可任意解释"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】该案改变了禁止参考 Hansard 的传统。【逐步演示】在语词模糊等条件下，可参考议会辩论作为解释辅助。【易错提醒】参考受严格条件限制，并非任意。"}, {"order": 7, "qtype": "judge", "stem": "哈特认为，法律体系通常明确规定了各种解释方法的优先顺序，因此解释结果完全确定。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特指出法律通常未规定解释方法的优先顺序。【逐步演示】这正是解释中出现选择的根源之一。【易错提醒】不要误以为法律能自我决定解释方法。"}, {"order": 8, "qtype": "single", "stem": "关于『司法解释是发现还是创造』，哈特的立场最接近：", "options": ["A 纯粹发现", "B 纯粹创造", "C 核心是发现、边缘兼有创造", "D 完全取决于法官心情"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】哈特取中间立场。【逐步演示】核心地带适用确定（发现），边缘地带包含选择（创造）。【易错提醒】这体现他对两种夸张的反对。"}, {"order": 9, "qtype": "single", "stem": "批评者认为司法解释威胁民主，主要理由是：", "options": ["A 解释太复杂", "B 法官非民选，通过解释实质造法", "C 解释不需要法律训练", "D 解释总是错误的"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】民主批评聚焦于非民选法官的实质造法。【逐步演示】哈特回应：向司法委任有限规则制定权是现代民主可接受的代价。【易错提醒】哈特承认这一张力，但认为可容忍。"}, {"order": 10, "qtype": "judge", "stem": "哈特在《后记》中承认，即便法官诉诸原则进行解释，相互竞争的原则之间仍可能需要选择。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是哈特回应德沃金的关键论据。【逐步演示】法律未给出原则的优先顺序，造法时刻只是被推迟而非消除。【易错提醒】哈特并非否认原则作用。"}, {"order": 11, "qtype": "multi", "stem": "下列哪几项属于常见的法律解释方法？", "options": ["A 文义解释", "B 目的解释", "C 历史解释", "D 体系解释"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】文义、目的、历史、体系是四种基本解释方法。【逐步演示】它们之间可能冲突，需判断优先顺序。【易错提醒】哈特认为法律通常未明示这些方法冲突的解决规则。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特关于司法解释性质的观点，并比较其与德沃金『建构性诠释』的分歧。", "options": [], "answer": "", "accepted": [], "keywords": [["解释是适用常态", "核心自动、边缘选择"], ["选择受典范情形/目的/原则约束", "填补空隙的裁量"], ["德沃金：建构性诠释", "fit 与道德证成"], ["哈特：造法时刻被推迟未消除"]], "explanation": "【答案要点】见 keywords。【解题思路】先述哈特观点，再对比德沃金。【逐步演示】哈特强调选择的受限性，德沃金强调诠释的约束与唯一答案。【易错提醒】避免把二人立场绝对对立。"}, {"order": 13, "qtype": "essay", "stem": "结合 Pepper v Hart 案，分析司法解释方法作为『可演进实践』的性质及其理论意义。", "options": [], "answer": "", "accepted": [], "keywords": [["改变禁止参考 Hansard 的传统", "1993年上议院"], ["语词模糊才开启方法选择", "开放结构"], ["解释方法可演进", "非固定机械规则"], ["预设立法意图可发现", "与德沃金争论关联"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，说明方法的演进性。【逐步演示】模糊性开启方法选择，方法随实践需要演进，但参考 Hansard 预设了意图可发现。【易错提醒】勿把参考 Hansard 说成任意解释。"}]}, "S3M3K3": {"lesson": "S3M3K3", "questions": [{"order": 1, "qtype": "single", "stem": "哈特所说的『填补空隙的裁量』（interstitial discretion）主要指：", "options": ["A 法官可任意裁判", "B 法官在法律未调整的案件中行使的有限造法权", "C 立法机关的立法权", "D 行政机关的许可权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特的裁量是法律空隙处的有限造法权。【逐步演示】它受实体约束、限于个案、须给出一般理由。【易错提醒】裁量不等于任意。"}, {"order": 2, "qtype": "single", "stem": "德沃金所反对的『强意义裁量』（strong discretion）是指：", "options": ["A 裁判者须服从权威标准", "B 裁判者在某些问题上不受法律标准约束、可自由决定", "C 法律明确授权的选择", "D 法官依原则裁判"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】强意义裁量指不受法律标准约束的自由决定，德沃金反对之。【逐步演示】弱意义裁量仍须服从标准，只是适用有判断余地。【易错提醒】区分强／弱意义是理解争论的关键。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，法官的造法权与立法机关相同，可以进行大规模社会改革。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特强调法官造法是『插曲式的』（interstitial），限于个案。【逐步演示】它不能像立法机关那样制定法典或大规模改革。【易错提醒】这是哈特回应『司法造法不民主』批评的论据之一。"}, {"order": 4, "qtype": "multi", "stem": "根据哈特，法官行使裁量时应受到哪些约束？", "options": ["A 参考既有法律的原则与目的", "B 像有良知的立法者依一般理由裁决", "C 限于解决手头的具体案件", "D 完全依个人好恶"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特强调裁量受实体约束、限于个案、须有理由。【逐步演示】D 的『完全依个人好恶』是任意，不是裁量。【易错提醒】裁量与任意须严格区分。"}, {"order": 5, "qtype": "single", "stem": "德沃金否认强意义裁量的核心理由是：", "options": ["A 法官总是服从立法者", "B 法律包含原则，建构性诠释可为疑难案件提供唯一正确答案", "C 法律从不模糊", "D 法官没有判断能力"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金以原则与诠释主张法律无漏洞、有唯一答案。【逐步演示】因此法官是在发现法律，而非自由造法。【易错提醒】这是『法律作为完整性』的核心。"}, {"order": 6, "qtype": "blank", "stem": "哈特认为，法官在疑难案件中通过______推理援引既有原则，但这只能推迟而不能消除造法的时刻。", "options": [], "answer": "", "accepted": ["类比", "analogy", "类比推理", "reasoning by analogy"], "keywords": [], "explanation": "【答案】类比（analogy）。【解题思路】哈特指出法官常通过类比推理援引原则。【逐步演示】但竞争原则间仍需选择，造法时刻只是被推迟。【易错提醒】类比不能彻底消除选择。"}, {"order": 7, "qtype": "judge", "stem": "德沃金批评司法造法不民主、溯及既往；哈特回应说，疑难案件中本无明确的既存法律可供形成合理期待。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特认为溯及既往的不义在于挫败合理期待，而疑难案件中并无清晰既存法律。【逐步演示】这是他对德沃金批评的回应之一。【易错提醒】哈特承认向司法委任有限权力是现代民主可接受的代价。"}, {"order": 8, "qtype": "single", "stem": "英国 R v R [1991] 案中，上议院的判决主要体现：", "options": ["A 法官严格依字面适用法律", "B 法官在疑难案中行使填补空隙的裁量，推翻婚姻豁免", "C 立法机关修改法律", "D 法官拒绝裁判"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】上议院通过重新阐释强奸罪本质，排除婚姻豁免。【逐步演示】这是有限、插曲式的造法，受人身自主原则约束。【易错提醒】案件年份为 1991，由上议院判决。"}, {"order": 9, "qtype": "single", "stem": "哈特的裁量理论与规则怀疑论的根本区别在于：", "options": ["A 哈特认为裁量无限", "B 哈特坚持规则中心确定，裁量只在空隙与边缘", "C 哈特否认裁量存在", "D 二者完全相同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特坚持大量简单案件中规则确定，裁量只是补充。【逐步演示】规则怀疑论则否认规则整体。【易错提醒】不要把哈特等同于规则怀疑论。"}, {"order": 10, "qtype": "judge", "stem": "哈特在《后记》中承认，即便法官诉诸原则，竞争原则间仍需选择，因此裁量不可彻底消除。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】这是哈特回应德沃金的关键。【逐步演示】法律未规定原则的优先顺序，故造法时刻只是被推迟。【易错提醒】哈特并非否认原则的作用。"}, {"order": 11, "qtype": "multi", "stem": "围绕司法裁量，哈特与德沃金争论的主线包括：", "options": ["A 疑难案件是否有唯一正确答案", "B 司法造法是否威胁民主", "C 法官是在发现还是创造法律", "D 法律是否需要语言"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三条主线分别是答案唯一性、民主正当性、裁量性质。【逐步演示】D 与裁量争论无直接关系。【易错提醒】聚焦争论的核心主线。"}, {"order": 12, "qtype": "essay", "stem": "试述哈特『填补空隙的裁量』理论，并说明它如何区别于任意裁量与规则怀疑论。", "options": [], "answer": "", "accepted": [], "keywords": [["裁量存在于法律空隙", "疑难案件"], ["有限造法权", "受实体约束/限于个案"], ["须给一般理由", "非任意"], ["规则中心确定", "区别于怀疑论"]], "explanation": "【答案要点】见 keywords。【解题思路】先定义裁量，再述有限性，最后作区分。【逐步演示】哈特的裁量是受约束的填补空隙，与任意和怀疑论都不同。【易错提醒】避免把裁量说成无限。"}, {"order": 13, "qtype": "essay", "stem": "结合 R v R 案，分析哈特与德沃金对法官角色的不同理解，并评价各自的解释力。", "options": [], "answer": "", "accepted": [], "keywords": [["推翻婚姻豁免", "1991年上议院"], ["哈特：填补空隙的造法", "受原则约束"], ["德沃金：发现隐含原则", "建构性诠释"], ["同一案件两种解读"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，对比二人立场。【逐步演示】哈特视有限造法，德沃金视发现原则；两种解读各有说服力。【易错提醒】避免简单判定一方正确。"}]}, "S3M3K4": {"lesson": "S3M3K4", "questions": [{"order": 1, "qtype": "single", "stem": "文义解释（Literal Interpretation）的基本预设是：", "options": ["A 法律含义由法官目的决定", "B 立法者以语言表意，语词的通常含义即法律含义", "C 法律没有确定含义", "D 法官应探求社会效果"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】文义解释预设语词通常含义即法律含义。【逐步演示】它强调客观与可预测，利于法的安定性。【易错提醒】不要把文义解释等同于目的解释。"}, {"order": 2, "qtype": "single", "stem": "目的解释（Purposive Interpretation）的核心在于：", "options": ["A 严格按字面适用", "B 依据法律规则所欲实现的目的阐明含义", "C 探求法官个人价值", "D 完全忽略文本"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】目的解释追问『法律为何而设』以确定规范射程。【逐步演示】它能适应社会变迁、避免荒谬结果。【易错提醒】目的解释不等于任意偏离文本。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，法律通常明确规定了文义解释与目的解释的绝对优先顺序。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特指出法律通常未规定方法的优先顺序。【逐步演示】这正是开放结构在方法论层面的体现，具体案件中须判断。【易错提醒】不要以为法律能自我决定解释方法。"}, {"order": 4, "qtype": "blank", "stem": "当文义解释导致荒谬结果时，允许偏离字面含义的折中规则在传统上被称为______规则。", "options": [], "answer": "", "accepted": ["黄金", "golden", "黄金规则", "golden rule"], "keywords": [], "explanation": "【答案】黄金规则（Golden Rule）。【解题思路】它是文义与目的之间的折中。【逐步演示】当字面荒谬时允许偏离，但须给出理由。【易错提醒】『荒谬』本身也需判断，存在任意风险。"}, {"order": 5, "qtype": "single", "stem": "Whiteley v Chappell (1868) 案中，法院判决被告无罪的主要理由是：", "options": ["A 被告没有投票", "B 已故者不属于『有权投票的人』，故不构成冒充有权投票者", "C 法律违宪", "D 证据不足"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院按字面认定已故者无权投票，故不构成该罪。【逐步演示】这是文义解释的经典案例，结论明显背离立法目的。【易错提醒】案件年份为 1868，属英国判例。"}, {"order": 6, "qtype": "judge", "stem": "Whiteley v Chappell 案常被引用来说明：严格遵守文义可能导致明显背离立法目的的结果。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】该案是文义解释极端后果的例证。【逐步演示】它显示文义在核心地带的决定力与局限性。【易错提醒】此案不代表文义解释一概错误。"}, {"order": 7, "qtype": "multi", "stem": "根据哈特，文义解释与目的解释的关系可如何刻画？", "options": ["A 核心地带文义足以决定结果", "B 边缘地带需要目的考量", "C 法律未规定二者的绝对优先顺序", "D 目的解释可完全取代文义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特以开放结构刻画二者功能。【逐步演示】D 错误，哈特反对目的任意取代文本。【易错提醒】注意哈特的平衡立场。"}, {"order": 8, "qtype": "single", "stem": "文义解释相对于目的解释的主要优势在于：", "options": ["A 更灵活", "B 更客观、可预测，利于法的安定性", "C 总能实现实质正义", "D 不需要语言"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】文义解释的优势在客观、可预测。【逐步演示】公民可据字面规划行为，限制法官任意。【易错提醒】优势不等于绝对正确。"}, {"order": 9, "qtype": "single", "stem": "目的解释面临的主要批评是：", "options": ["A 太客观", "B 可能赋予法官过大权力，把自己的价值包装为『立法目的』", "C 完全无法适用", "D 只适用于刑法"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】批评者担心『目的』由谁定义的问题。【逐步演示】立法目的多重或模糊时，法官可能以目的之名行任意之实。【易错提醒】哈特承认风险，但认为完全排除目的也不可接受。"}, {"order": 10, "qtype": "judge", "stem": "德沃金的『建构性诠释』要求解释既适合既有法律文本与实践，又为其提供最佳道德证成。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】建构性诠释有 fit 与 moral justification 双重要求。【逐步演示】它把文本约束与道德目的结合。【易错提醒】这不是纯粹文义，也不是无拘束的目的探求。"}, {"order": 11, "qtype": "multi", "stem": "下列哪些属于法律解释的相关方法或格言？", "options": ["A 黄金规则", "B 弊端规则", "C 明示其一即排除其他", "D 完全凭法官心情"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】这些都是法律解释的工具。【逐步演示】它们构成『解释的指针』，但都不是绝对的。【易错提醒】D 不是解释方法，而是任意。"}, {"order": 12, "qtype": "essay", "stem": "试比较文义解释与目的解释的理据与优劣，并说明哈特如何用开放结构理论处理二者的冲突。", "options": [], "answer": "", "accepted": [], "keywords": [["文义：客观/安定/民主", "字面含义"], ["目的：合理/回应变迁", "立法意旨"], ["冲突：安定 vs 合理", "两难"], ["哈特：核心文义、边缘目的", "优先顺序未定"]], "explanation": "【答案要点】见 keywords。【解题思路】先比较理据优劣，再述哈特框架。【逐步演示】哈特以核心／边缘说明二者分工，具体选择须有理由且受原则约束。【易错提醒】避免主张某一方法绝对优先。"}, {"order": 13, "qtype": "essay", "stem": "结合 Whiteley v Chappell 案，分析文义解释的局限，以及法院在文义与目的冲突中的选择所体现的裁量。", "options": [], "answer": "", "accepted": [], "keywords": [["冒充已故者投票", "1868年"], ["文义导致的荒谬结论", "背离立法目的"], ["语言分类的局限", "开放结构"], ["方法选择本身是裁量"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，分析局限与裁量。【逐步演示】文义在核心决定的同时暴露边缘局限，方法选择本身需判断。【易错提醒】勿把此案解读为文义解释一概错误。"}]}, "S3M3K5": {"lesson": "S3M3K5", "questions": [{"order": 1, "qtype": "single", "stem": "历史解释（Historical Interpretation）的参照系主要是：", "options": ["A 法律语词的通常含义", "B 法律制定时的历史背景与立法意图", "C 法律体系的内在结构", "D 案件的社会效果"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】历史解释通过立法史料探求制定背景与意图。【逐步演示】其典型形态是探求立法欲救济弊端的弊端规则。【易错提醒】注意与体系解释的参照系区分。"}, {"order": 2, "qtype": "single", "stem": "体系解释（Systematic Interpretation）的参照系主要是：", "options": ["A 立法者的心理意图", "B 法律规范在整个体系中的位置与关联", "C 语词的字典含义", "D 法官的个人偏好"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】体系解释把规范置于法律体系中联系其他规范理解。【逐步演示】它运用上位法优于下位法等冲突规则。【易错提醒】勿与历史解释混淆。"}, {"order": 3, "qtype": "judge", "stem": "哈特认为，历史解释与体系解释能提供自动答案，彻底消除法律解释中的不确定性。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特认为这些方法只是『解释的指针』。【逐步演示】它们能减少而不能消除不确定性，方法选择本身仍须判断。【易错提醒】这是开放结构在方法论上的体现。"}, {"order": 4, "qtype": "blank", "stem": "英国 1584 年的______案确立了探求法律欲救济之弊端的『弊端规则』。", "options": [], "answer": "", "accepted": ["Heydon's Case", "Heydon", "海登案", "Heydon's Case (1584)"], "keywords": [], "explanation": "【答案】Heydon's Case（1584）。【解题思路】该案确立弊端规则的四条解释准则。【逐步演示】它影响了后世数百年的法律解释实践。【易错提醒】年份为 1584，注意拼写。"}, {"order": 5, "qtype": "multi", "stem": "体系解释常用的具体方法或规则包括：", "options": ["A 明示其一即排除其他", "B 上位法优于下位法", "C 特别法优于一般法", "D 探求立法者的心理动机"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】这些都是体系解释的具体方法或冲突规则。【逐步演示】D 属于历史解释的范畴。【易错提醒】注意区分两种方法的技术。"}, {"order": 6, "qtype": "single", "stem": "历史解释面临的主要困难是：", "options": ["A 完全无法找到任何材料", "B 立法意图常是多重、模糊甚至虚构的", "C 法律体系不融贯", "D 语词没有通常含义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】立法意图的多重与模糊是历史解释的核心困难。【逐步演示】法院在 Pepper v Hart 中为此设定严格的参考条件。【易错提醒】不要把历史解释的困难与体系解释混淆。"}, {"order": 7, "qtype": "judge", "stem": "Pepper v Hart [1993] 案确立：只要法律适用有争议，法院就可任意参考 Hansard 探求立法意图。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】该案设定了严格条件：仅在语词模糊、含糊或致荒谬时才可参考。【逐步演示】并非任意参考。【易错提醒】注意『严格条件』这一限定。"}, {"order": 8, "qtype": "single", "stem": "关于历史解释与体系解释的关系，下列说法正确的是：", "options": ["A 二者参照系不同，常与文义、目的解释配合使用", "B 二者完全相同", "C 二者互相排斥", "D 体系解释就是历史解释"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】历史解释求诸立法历史，体系解释求诸体系结构，二者参照系不同。【逐步演示】它们常与其他方法配合。【易错提醒】注意区分而非对立。"}, {"order": 9, "qtype": "single", "stem": "Heydon's Case 确立的解释框架，其步骤不包括：", "options": ["A 考察普通法的既有规定", "B 识别法律欲救济的弊端", "C 考察立法采用的救济方法", "D 完全无视立法目的"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】Heydon's Case 的四步都围绕探求立法目的与弊端。【逐步演示】它要求解释服务于压制弊端、促进救济。【易错提醒】D 与该判例精神相反。"}, {"order": 10, "qtype": "judge", "stem": "德沃金的建构性诠释与体系解释有相通之处，但更进一步要求联系道德原则为法律提供最佳证成。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】二者都强调联系整体理解部分。【逐步演示】德沃金更进一步引入道德证成，超出哈特的描述性框架。【易错提醒】注意『相通但更进一步』的分寸。"}, {"order": 11, "qtype": "multi", "stem": "下列符合哈特对解释方法定位的有哪些？", "options": ["A 方法是解释的指针", "B 能减少不确定性但不能消除", "C 法律未规定方法优先顺序", "D 存在一种能自动决定一切的方法"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特视方法为指针，不能自动决定。【逐步演示】优先顺序未定，故方法选择是判断。【易错提醒】D 与哈特立场相悖。"}, {"order": 12, "qtype": "essay", "stem": "试比较历史解释与体系解释的参照系、操作方式与各自局限。", "options": [], "answer": "", "accepted": [], "keywords": [["历史解释求诸立法背景", "弊端规则"], ["体系解释求诸体系关联", "冲突规则"], ["局限：意图模糊/体系冲突", "各自困难"], ["哈特：解释的指针", "不能自动决定"]], "explanation": "【答案要点】见 keywords。【解题思路】从参照系、操作、局限三方面比较。【逐步演示】二者参照系不同，都受开放结构限制，只是指针。【易错提醒】避免把二者说成互斥。"}, {"order": 13, "qtype": "essay", "stem": "结合 Heydon's Case，说明历史解释的方法及其判断性本质，并联系 Pepper v Hart 谈其当代发展。", "options": [], "answer": "", "accepted": [], "keywords": [["Heydon's Case 1584", "弊端规则四步"], ["识别弊端本身需判断", "非自动答案"], ["Pepper v Hart 1993", "严格条件参考 Hansard"], ["方法作为指针的延续"]], "explanation": "【答案要点】见 keywords。【解题思路】以判例切入，说明方法与判断性，再谈发展。【逐步演示】识别弊端需判断，Pepper v Hart 以严格条件规范参考。【易错提醒】勿把参考 Hansard 说成任意参考。"}]}, "S3M3K6": {"lesson": "S3M3K6", "questions": [{"order": 1, "qtype": "single", "stem": "德沃金区分规则与原则的核心标准是：", "options": ["A 规则由立法机关制定，原则由法院创造", "B 规则以全有或全无方式适用，原则以分量方式起作用", "C 规则是成文的，原则是不成文的", "D 规则有制裁，原则没有"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金以适用方式区分：规则全有或全无，原则有分量。【逐步演示】原则可被更强理由压倒而不失效。【易错提醒】不要用成文／不成文或有无制裁来区分。"}, {"order": 2, "qtype": "single", "stem": "『任何人不得从自己的错误中获利』在法律推理中通常被视为：", "options": ["A 一条法律规则", "B 一项法律原则", "C 一项道德格言而非法律", "D 一项程序规则"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】它以分量方式作为裁判理由，是法律原则。【逐步演示】Riggs v. Palmer 案中它压倒了继承规则。【易错提醒】原则也是法律的一部分，不是单纯的道德。"}, {"order": 3, "qtype": "judge", "stem": "哈特在《后记》中完全否认法律原则的存在，坚持法律只是规则的体系。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特在《后记》中承认原则可纳入法律，只是反驳放弃承认规则。【逐步演示】他修正了『规则模式』，但拒绝放弃承认规则。【易错提醒】勿把哈特说成完全否认原则。"}, {"order": 4, "qtype": "blank", "stem": "德沃金把法律理解为一种融贯的道德实践，称之为『法律作为______』。", "options": [], "answer": "", "accepted": ["完整性", "integrity", "law as integrity", "整体性与完整性"], "keywords": [], "explanation": "【答案】完整性（integrity）。【解题思路】law as integrity 是德沃金《法律帝国》的核心命题。【逐步演示】它要求法官通过建构性诠释找到最佳证成的原则。【易错提醒】这是德沃金而非哈特的概念。"}, {"order": 5, "qtype": "multi", "stem": "根据哈特在《后记》中的回应，下列哪些是他反驳德沃金的理由？", "options": ["A 许多原则可靠谱系识别", "B 诠释性判准预设对既判法的识别，仍需承认规则", "C 承认规则可纳入道德判准（柔性实证主义）", "D 法律根本不包含原则"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特以谱系识别、既判法预设与柔性实证主义三点回应。【逐步演示】D 错误，哈特承认原则存在。【易错提醒】哈特是修正而非放弃承认规则。"}, {"order": 6, "qtype": "single", "stem": "里格斯诉帕尔默案（Riggs v. Palmer）中，法院的判决依据是：", "options": ["A 遗嘱形式要件不符", "B 『不得从错误中获利』原则压倒了继承规则", "C 继承人未成年", "D 遗嘱未经登记"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院以原则限制规则的字面适用。【逐步演示】这是规则与原则关系的经典案例（1889，纽约州上诉法院）。【易错提醒】遗嘱本身符合形式要件。"}, {"order": 7, "qtype": "judge", "stem": "德沃金认为，法律原则的效力来自其被权威机关采纳的方式（谱系），而非其道德内容。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】德沃金认为原则效力来自内容（道德正当性），哈特才强调谱系。【逐步演示】这是二人分歧的焦点之一。【易错提醒】不要把两人的立场搞反。"}, {"order": 8, "qtype": "single", "stem": "哈特在《后记》中用哪个案例说明『有限形式的建构性诠释』？", "options": ["A Riggs v. Palmer", "B Donoghue v Stevenson", "C Marbury v. Madison", "D Brown v. Board"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特以 Donoghue v Stevenson 的邻人原则说明有限诠释。【逐步演示】但他指出诠释并未消除选择。【易错提醒】Riggs v. Palmer 也是重要案例，但此处哈特论诠释主要引唐纳休案。"}, {"order": 9, "qtype": "single", "stem": "关于原则与规则，德沃金与哈特的主要分歧在于：", "options": ["A 法律是否包含原则", "B 原则能否决定一切案件、是否需放弃承认规则", "C 规则是否有制裁", "D 法律是否使用语言"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】双方都承认原则存在，分歧在其能否由承认规则识别并提供唯一答案。【逐步演示】德沃金主张放弃承认规则，哈特反驳。【易错提醒】不要说分歧是『法律是否包含原则』。"}, {"order": 10, "qtype": "judge", "stem": "哈特认为，德沃金的诠释性判准要运作，须先识别『既判法』，而这恰恰需要承认规则。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特指出诠释预设既判法的识别，仍需承认规则。【逐步演示】因此承认规则是原则识别的前提而非替代物。【易错提醒】这是哈特回应的关键一环。"}, {"order": 11, "qtype": "multi", "stem": "下列关于法律原则的说法，符合德沃金观点的有哪些？", "options": ["A 原则以分量方式起作用", "B 原则可为疑难案件提供唯一正确答案", "C 原则是法律的一部分", "D 原则与规则以相同方式适用"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】德沃金主张原则有分量、能给唯一答案、属法律一部分。【逐步演示】D 错误，原则与规则适用方式不同。【易错提醒】区分规则的『全有或全无』与原则的『分量』。"}, {"order": 12, "qtype": "essay", "stem": "试比较法律规则与法律原则在适用方式上的不同，并说明德沃金据此对哈特规则模式的批评。", "options": [], "answer": "", "accepted": [], "keywords": [["规则全有或全无", "原则有分量"], ["原则可被压倒不失效", "作为裁判理由"], ["德沃金：原则无法靠谱系识别", "应放弃承认规则"], ["法律包含原则"]], "explanation": "【答案要点】见 keywords。【解题思路】先述适用方式差异，再述德沃金批评。【逐步演示】原则的分量特征使德沃金认为规则模式不足，承认规则无法解释原则。【易错提醒】不要混淆双方的立场。"}, {"order": 13, "qtype": "essay", "stem": "结合 Riggs v. Palmer 案，分析哈特在《后记》中如何回应德沃金的挑战，并评价其说服力。", "options": [], "answer": "", "accepted": [], "keywords": [["不得从错误中获利原则", "压倒继承规则"], ["哈特：原则可靠谱系识别", "一贯被援引"], ["诠释预设既判法", "仍需承认规则"], ["同一案件两种解读"]], "explanation": "【答案要点】见 keywords。【解题思路】以案件切入，述哈特回应并评价。【逐步演示】哈特以谱系识别与既判法预设回应，但德沃金仍可争辩原则的道德维度。【易错提醒】避免简单判定一方胜出。"}]}, "S3M4K1": {"lesson": "S3M4K1", "questions": [{"order": 1, "qtype": "single", "stem": "哈特与富勒论战的直接导火索是下列哪一案件？", "options": ["A 美国辛普森案", "B 战后西德法院审理的妻子检举丈夫案", "C 英国麦克洛克林诉奥布莱恩案", "D 纽伦堡审判中的法官审判案"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 明确指出，争论聚焦于一桩战后西德法院的判决：妻子1944年向盖世太保检举丈夫，战后因致使丈夫失去自由而被追诉。【逐步演示】辩方援引1934年纳粹法律，法院却以该法触犯正派人的良知为由定罪，由此引出恶法是否为法的问题。【易错提醒】D 中的法官审判案是讨论司法者道德责任时常被引用的材料，但并非哈特—富勒论战的直接争点。"}, {"order": 2, "qtype": "single", "stem": "关于哈特在论战中的立场，下列表述最准确的是：", "options": ["A 纳粹法律因不道德而丧失法律效力", "B 纳粹法律在描述意义上有效，但邪恶到不应被服从", "C 法官有权以个人道德否定任何制定法", "D 法律与道德在任何情况下都毫无关联"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特维护分离命题，认为1934年纳粹法律符合当时的承认规则，因而是有效法律；他同时主张该法邪恶到不该服从。【逐步演示】A 是富勒的结论；C 与哈特对法院判决的批评相反；D 把分离命题漫画化，哈特承认法律与道德存在事实上的诸多联系及最低限度的自然法条件。【易错提醒】『有效』与『正当』的区分是哈特立场的枢纽，不可混同。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于富勒所列举的法律『内在道德』要求？", "options": ["A 一般性", "B 不溯及既往", "C 官方行为与公布的规则相一致", "D 法律内容必须体现特定的实质正义观"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】富勒的八项要求是一般性、公布、不溯及既往、清晰、不矛盾、可遵守、稳定、官方行为与规则一致。【逐步演示】这些要求属于形式与程序层面，富勒明确拒绝预设某一套实质正义标准。【易错提醒】D 属于实质性自然法的进路，富勒走的是程序自然法路线，切勿混淆。"}, {"order": 4, "qtype": "judge", "stem": "哈特主张，法律与道德在事实上毫无联系，因此法理学可以完全无视道德问题。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特主张的是概念上的可分离，从未否认法律与道德在事实层面经常相互渗透。【逐步演示】他还承认法律必须满足最低限度的自然法条件，并强调区分效力与正当性恰恰是为了更清醒地批判恶法。【易错提醒】把分离命题等同于『法律无需道德』，是 Wacks 与哈特本人都反复警告的漫画化理解。"}, {"order": 5, "qtype": "blank", "stem": "哈特把『是不是法律』与『是不是道德上正当』应分开判断的主张，称为______命题。", "options": [], "answer": "", "accepted": ["分离", "分离命题", "Separation Thesis", "可分离", "separability"], "keywords": [], "explanation": "【答案】分离命题（Separation Thesis）。【解题思路】这是法律实证主义区分法律效力与道德价值的基本主张。【逐步演示】哈特在《法律的概念》及1957年霍姆斯讲座中系统阐述了这一命题。【易错提醒】不要答成『渊源命题』，后者由拉兹提出，强调法律的识别最终诉诸社会来源。"}, {"order": 6, "qtype": "single", "stem": "战后西德法院在告密者案中给妻子定罪的核心理由是：", "options": ["A 丈夫早已死亡，追诉条件消失", "B 1934年法律触犯了正派人的健全良知与正义感", "C 妻子伪造了盖世太保的文件", "D 法律明确规定了溯及既往的追诉程序"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】据 Wacks 记载，法院以该纳粹法律违背『所有正派人的健全良知和正义感』为由拒绝适用。【逐步演示】D 恰好相反：当时并无这样的溯及既往立法，哈特与富勒都希望立法机关事后制定一部。【易错提醒】法院以道德理由否定制定法效力，正是哈特批评的对象。"}, {"order": 7, "qtype": "single", "stem": "富勒把法律的内在道德称为哪一种道德？", "options": ["A 义务的道德", "B 渴望的道德", "C 后果主义的道德", "D 私德"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】富勒称内在道德是『渴望的道德』（morality of aspiration），诉诸立法者的技艺自尊与受托感。【逐步演示】它与要求最低底线的『义务的道德』（morality of duty）相对。【易错提醒】这一区分说明富勒并不把八项要求当作可被机械执行的最低标准，而是制度努力的方向。"}, {"order": 8, "qtype": "judge", "stem": "在告密者案应如何处理这个问题上，哈特与富勒的具体结论其实相当接近：两人都更希望有一部溯及既往的追究立法。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 明确指出，双方都倾向于以溯及既往立法来追究告密者。【逐步演示】这提示我们，两人的分歧主要在概念与说理语言，而非具体裁判结论。【易错提醒】不要因为两人论战激烈就推定他们在每一个案子上都持相反结论。"}, {"order": 9, "qtype": "essay", "stem": "试析哈特『承认恶法是法律有助于我们更清醒地抵抗它』这一论证的逻辑，并说明富勒可能提出的反驳。", "options": [], "answer": "", "accepted": [], "keywords": [["区分效力判断与道德评价", "是不是法与应不应服从分开"], ["承认其有效性不意味着赞许", "道德责任交还道德判断"], ["逐出法律概念会掩盖真实选择", "迫使法官借用溯及既往理由"], ["富勒反驳", "分离造成虚假清醒与道德中性的法观念"], ["形式合法性不保证正义", "南非种族隔离反例"]], "explanation": "【答案要点】见 keywords 五组。【解题思路】先重构哈特的三层论证，再给出富勒方向相反的诊断。【逐步演示】哈特：识别判准在承认规则→邪恶仍属有效→抵抗需要明确的道德理由；富勒：把法说成道德中性材料→法官失去批判语言→八项内在道德已划定概念边界。【易错提醒】不要停留在『两人各执一词』的层面，要说清每方论证的支点及其软肋。"}, {"order": 10, "qtype": "multi", "stem": "根据本节内容，下列哪些是哈特论证『纳粹法律仍是法律』时所依赖的要素？", "options": ["A 承认规则提供的有效性判准", "B 最低限度的自然法条件", "C 富勒的八项合法性要求", "D 效力与道德评价概念上可分"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】哈特以承认规则界定有效性，承认最低限度自然法条件，并坚持效力与道德可分。【逐步演示】C 是富勒的论证工具，哈特并未把它作为自己结论的前提。【易错提醒】哈特承认某些形式条件，这一点容易与富勒的主张混淆，但两者在是否据此排除『法律』资格上立场相反。"}, {"order": 11, "qtype": "single", "stem": "Summers 对富勒论证的评价是：", "options": ["A 富勒成功证明了法律与道德的必然联系", "B 富勒的明确论证多数只支持偶然联系", "C 富勒完全否认法律有形式要求", "D 富勒的理论就是拉德布鲁赫公式的翻版"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 引述 Summers：尽管富勒主张必然联系，其具体论证大多只支持偶然联系。【逐步演示】即遵守八项要求通常有助于道德目标，使坏法律较难被采纳，但逻辑上并不担保正义。【易错提醒】这并不意味着富勒的立场毫无价值，Wacks 强调它提醒我们形式合法性本身也是一种重要价值。"}, {"order": 12, "qtype": "judge", "stem": "南非种族隔离制度很可能满足了富勒的全部八项形式要求，这说明遵守内在道德并不足以保证法律秩序的正义。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 以种族隔离南非为例，指出形式合法性与实质正义之间存在缝隙。【逐步演示】富勒的回应是种族定义本身过于任意，不符合『一般性』要求；这一回应是否充分仍有争议。【易错提醒】这个反例削弱的是『形式合法即正义』的推论，并不否定八项要求本身的实践价值。"}, {"order": 13, "qtype": "essay", "stem": "德沃金如何重新定位哈特—富勒关于『纳粹法律是不是法律』的争论？哈特在后记中又如何回应？", "options": [], "answer": "", "accepted": [], "keywords": [["语义层面争论空洞", "前解释阶段"], ["真正问题是解释性的", "最佳契合与道德辩护"], ["哈特接受前解释意义", "邪恶制度仍可称法"], ["描述性法理学与解释性法理学并行", "各自分工"]], "explanation": "【答案要点】见 keywords 四组。【解题思路】从德沃金对语义争论的批评入手，再说明哈特后记中的让步与坚持。【逐步演示】德沃金：问题不在词的定义而在能否把制度史纳入最佳解释；哈特：即便极端邪恶制度也可在前解释意义被称为法，描述性研究自有其任务。【易错提醒】不要把哈特的让步说成他接受了德沃金的整体理论，他只是承认两种研究可以并存。"}]}, "S3M4K2": {"lesson": "S3M4K2", "questions": [{"order": 1, "qtype": "single", "stem": "德沃金所说的『规则模式』（model of rules）主要指涉下列哪一主张？", "options": ["A 法律由主权者的命令构成", "B 法律被化约为可由承认规则识别的规则集合", "C 法律完全是法官判决的总和", "D 法律与道德在概念上必然同一"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金把哈特的实证主义概括为『规则模式』，即法律被理解为由承认规则筛选出的规则体系。【逐步演示】他据此批评该模式遗漏了原则与政策这类非规则标准。【易错提醒】A 是奥斯丁的命令理论，德沃金批判的对象是哈特而非奥斯丁；C 接近法律现实主义。"}, {"order": 2, "qtype": "single", "stem": "关于规则与原则的区别，下列表述正确的是：", "options": ["A 规则具有分量维度，原则全有或全无", "B 规则全有或全无地适用，原则具有分量维度", "C 原则只能由立法机关制定", "D 规则不可能是明确的法律标准"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金指出，规则以全有或全无的方式适用，原则则具有『分量或重要性』的维度。【逐步演示】原则提供的是可被权衡的理由，而非结论性指令。【易错提醒】这一区分是德沃金反驳规则模式的第一块基石，切勿颠倒。"}, {"order": 3, "qtype": "judge", "stem": "德沃金主张，法律不仅包含规则，也包含原则与政策这类非规则标准。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 指出，德沃金认为法律不仅由规则构成，还包括他所谓的『非规则标准』，即原则与政策。【逐步演示】不过在裁判中，民事案件应依原则而非政策决定，因为政策指向集体目标。【易错提醒】承认政策属于法律标准，与主张法官应按政策裁判，是两个不同问题。"}, {"order": 4, "qtype": "blank", "stem": "德沃金虚构了一位具有超凡技艺与学识的法官，用来展示疑难案件中的建构性解释，这位法官名叫______。", "options": [], "answer": "", "accepted": ["赫拉克勒斯", "Hercules", "大力神", "赫拉克勒斯法官"], "keywords": [], "explanation": "【答案】赫拉克勒斯（Hercules）。【解题思路】该法官被设想为具有超人的技艺、学识、耐心与洞察力。【逐步演示】他建构一套能为普通法先例提供融贯辩护的原则体系，是德沃金方法论的范式模型。【易错提醒】Wacks 提醒，赫拉克勒斯只是理论模型，德沃金并不认为现实中存在这样的法官。"}, {"order": 5, "qtype": "single", "stem": "在 Riggs v Palmer 案中，纽约法院否定杀人者继承权所依据的是：", "options": ["A 遗嘱形式上的瑕疵", "B 成文法中明文排除继承的条款", "C 『任何人不得因自己的错误行为而获利』原则", "D 法官的个人道德偏好"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】该案遗嘱形式有效、继承规则无例外，法院以不得因自身过错获利的原则阻止继承。【逐步演示】德沃金以此证明原则虽未被明文写出，仍属法律的一部分。【易错提醒】哈特的后记回应说，这类原则同样可能因被法院反复援引而取得法律身份，即通过『谱系』被识别。"}, {"order": 6, "qtype": "multi", "stem": "下列哪些属于德沃金法理论的核心论断？", "options": ["A 法律包含原则与政策", "B 疑难案件中存在唯一正确答案", "C 权利可被视为对抗集体目标的王牌", "D 法律在边缘处存在真正空缺，须由法官填补"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】A、B、C 分别对应原则命题、唯一正确答案命题与权利作为王牌的命题。【逐步演示】D 是哈特基于开放结构的主张，德沃金明确拒绝法律存在真正空缺。【易错提醒】『法律无间隙』是德沃金整体论的必要前提，与哈特的间断性图景正相反。"}, {"order": 7, "qtype": "single", "stem": "德沃金所说的『语义之刺』（semantic sting）针对的是实证主义的哪一预设？", "options": ["A 法律必须有制裁", "B 法律人共享一套有效性的语义判准，因而无理论性分歧", "C 法官总是机械适用规则", "D 国际法不是严格意义上的法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金认为，实证主义把有效性判准归结为法律人共享的规则，于是律师之间只可能有事实性分歧。【逐步演示】但现实中常见的是：对规则如何制定并无争议，对其是否因此有效却争论不休，这属于理论性分歧。【易错提醒】哈特在后记中回应说，他从没有把承认规则建立在『法』一词的含义之上，并已区分概念的意义与适用标准。"}, {"order": 8, "qtype": "judge", "stem": "德沃金否认法官在疑难案件中拥有不受既定标准约束的强自由裁量。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】德沃金主张法官始终受隐含原则约束，所谓强自由裁量与『法律无间隙』的整体论不相容。【逐步演示】他因此批评哈特的『间隙性造法』图景误解了司法推理。【易错提醒】哈特本人承认法官有有限的、受约束的造法权；双方争论的焦点是这种权力的性质与范围。"}, {"order": 9, "qtype": "essay", "stem": "试论德沃金『唯一正确答案』命题的含义，并说明哈特可能提出的质疑。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先说明『正确答案』的判定标准，再呈现哈特从不确定性出发的质疑。【逐步演示】德沃金：答案须同时满足契合与证成双重要求；哈特：不同原则之间缺少法律预先规定的权重次序，选择本身仍是判断。【易错提醒】不要把这个命题理解为『每个案件都有现成条文可查』，它针对的是疑难案件中的解释性判断。", "keywords": [["答案须契合既有法律实践", "契合制度史"], ["答案还须提供最佳道德辩护", "最佳证成"], ["德沃金以鞋码与棋例说明唯一性", "塔尔的微笑"], ["哈特质疑原则权重无先定阶位", "法官仍须作价值选择"], ["开放结构导致真正的不确定", "法律在边缘处不完整"]]}, {"order": 10, "qtype": "single", "stem": "哈特在《法律的概念》后记中，为回应德沃金而明确接受的一种立场是：", "options": ["A 彻底的自然法理论", "B 柔性实证主义（承认规则可纳入道德原则）", "C 法律现实主义", "D 纯粹法学"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】哈特承认，承认规则可以把符合道德原则或实质价值作为法律效力判准，这就是柔性或包容实证主义。【逐步演示】但他坚持这仍是社会来源问题，因为该判准本身须被官员实践所接受。【易错提醒】哈特同时驳斥德沃金把他归为『Plain-fact 实证主义者』，他的立场从来不是只认谱系。"}, {"order": 11, "qtype": "multi", "stem": "德沃金对哈特自由裁量理论提出的主要批评包括：", "options": ["A 该理论对司法过程的描述不真实", "B 未经选举的法官造法不民主", "C 法官造法相当于溯及既往，因而不公", "D 该理论过度强调法律的确定性"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】哈特在后记中列出德沃金的三项批评：描述性错误、民主正当性不足、溯及既往的不公。【逐步演示】哈特逐项回应：司法语言具有仪式性；受约束的授权与行政授权类似；疑难案件中本无明确法律可供形成预期。【易错提醒】D 与德沃金的实际批评方向相反，他批评的是哈特承认不确定性，而非过度强调确定性。"}, {"order": 12, "qtype": "judge", "stem": "哈特认为，疑难案件中的法官造法与溯及既往立法完全等同，因而应被一概否定。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】哈特明确反驳这一指控：溯及既往之所以不公，是因为它打破了当事人可据以行动的明确预期，而疑难案件恰恰缺少这种明确状态。【逐步演示】他还强调司法造法是受限的、间隙性的，不同于立法机关的广泛改革权。【易错提醒】哈特并未否认法官造法需要理由约束，他要求法官像有良知的立法者那样依据一般理由裁判。"}, {"order": 13, "qtype": "essay", "stem": "以 Riggs v Palmer 为例，比较德沃金与哈特对同一判决的两种解读，并说明各自的理论后果。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先叙述案件事实，再分别重构两种解释。【逐步演示】德沃金：原则一直在法律之中，法官只是发现它；哈特：原则的法律身份来自被接受的识别实践，承认规则仍不可少。【易错提醒】两人对判决结果并无分歧，争论的是该结果应当如何被法理学地描述。", "keywords": [["德沃金解读", "法院适用隐含原则而非造法"], ["哈特解读", "原则因反复援引取得谱系"], ["承认规则仍必要", "前解释的既定法律须先被识别"], ["理论后果差异", "法理学是裁判的一般部分或描述性研究"], ["分歧实质", "识别与证成是否可分"]]}]}, "S3M4K3": {"lesson": "S3M4K3", "questions": [{"order": 1, "qtype": "single", "stem": "法律实证主义与自然法之争的核心命题是：", "options": ["A 法律是否应当有制裁", "B 法律效力是否在概念上依赖道德价值", "C 法官是否有权解释宪法", "D 国际法是否属于法律"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】两派对立的焦点是法律效力与道德之间是否存在概念上的必然联系。【逐步演示】实证主义主张分离，自然法主张关联；其他选项均为法理学中的其他问题。【易错提醒】不要把争论表述为『实证主义主张法律不需要道德』，那是漫画化的说法。"}, {"order": 2, "qtype": "multi", "stem": "根据 Wacks，法律实证主义与自然法虽然对立，却共享下列哪些基础？", "options": ["A 都受分析法学传统影响", "B 都试图考察并证成法律的权威", "C 都否认对不正义法律存在初步服从义务", "D 都完全否认法治理想的价值"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】Wacks 列举了四项共同基础：分析方法、权威问题、否认对恶法的初步服从义务、重视法治。【逐步演示】D 与第四项直接相反。【易错提醒】承认共同点有助于理解为何他说两派有时像在『打影子拳』，但这不意味着分歧消失。"}, {"order": 3, "qtype": "single", "stem": "关于实证主义内部分歧，下列表述正确的是：", "options": ["A 拉兹主张道德可经承认规则成为效力判准", "B 科尔曼主张只有社会来源能提供合法性判准", "C 拉兹主张排除实证主义，科尔曼主张包容实证主义", "D 两者都主张自然法与实证主义应合并"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】拉兹是排除实证主义的代表，坚持只有社会来源构成合法性判准；科尔曼是包容实证主义的代表。【逐步演示】哈特在后记中明确把自己归入柔性（包容）立场。【易错提醒】A、B 把两位学者的立场对调，是常见错误。"}, {"order": 4, "qtype": "judge", "stem": "哈特在《法律的概念》后记中承认，承认规则可以把道德原则纳入法律效力判准，这被称作柔性或包容实证主义。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】哈特在后记中反驳德沃金把他归为『Plain-fact 实证主义者』，明确承认道德可以被纳入效力判准。【逐步演示】但他坚持这仍取决于官员的接受实践，因而是社会事实问题。【易错提醒】这一让步并未使哈特变成自然法学者，他仍拒绝法律与道德的概念必然联系。"}, {"order": 5, "qtype": "blank", "stem": "哈特基于人的脆弱性、有限资源等经验事实，主张任何法律体系都必须包含少量______，以维持制度自身。", "options": [], "answer": "", "accepted": ["最低限度的自然法", "自然法的最低限度内容", "minimum content of natural law", "最低限度自然法"], "keywords": [], "explanation": "【答案】最低限度的自然法。【解题思路】哈特在《法律的概念》第九章提出此说。【逐步演示】这些内容是经验推论的结果，与道德价值存在事实上的重合，仍非概念上的必然联系。【易错提醒】不要把它等同于古典自然法的『恶法非法』命题，两者的论证路径不同。"}, {"order": 6, "qtype": "single", "stem": "拉德布鲁赫在1947年立场转变，主要是因为：", "options": ["A 他读了哈特的《法律的概念》", "B 他谴责实证主义无力阻止纳粹之恶，转而强调正义的绝对价值", "C 他成为纯粹法学的奠基人", "D 他主张法律与道德应彻底分离"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，拉德布鲁赫战前是实证主义者，战后公开谴责实证主义未能防止纳粹罪行。【逐步演示】他提出法律理念只能是正义的实现，正义具有绝对价值。【易错提醒】哈特—富勒论战正是围绕拉德布鲁赫式的思路展开，但哈特并不接受其结论。"}, {"order": 7, "qtype": "judge", "stem": "纽伦堡审判的法官在判决中明确以自然法理论作为裁判依据。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出，法官并未诉诸明确的自然法理论。【逐步演示】但判决承认了某些行为构成反人类罪，从而确认法律并非判定对错的唯一尺度。【易错提醒】『未明确诉诸自然法』与『裁判中不含自然法式判断』是两回事，注意措辞分寸。"}, {"order": 8, "qtype": "single", "stem": "1948年《世界人权宣言》把其条款描述为：", "options": ["A 可直接推翻国内制定法的高级法", "B 共同的成就标准", "C 主权者的命令", "D 纯粹的道德劝诫，与法律无关"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出宣言把自己表述为『共同的成就标准』，法文文本作『有待实现的共同理想』。【逐步演示】这体现了一种审慎的现代自然法形态：承认超越实证法的尺度，又不直接把它写成可推翻一切立法的规范。【易错提醒】D 过于贬低其法律意义，A 又过于夸大其直接效力。"}, {"order": 9, "qtype": "essay", "stem": "概述芬尼斯以种族隔离制度下的公民为例，对科尔曼与莱特提出的诘难，并说明实证主义一方可以如何回应。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先复现思想实验，再分析四种回答的归属。【逐步演示】芬尼斯认为第四种回答承认了秩序与正义等实质价值；实证主义则可强调社会接受实践本身就构成合法性解释。【易错提醒】不要把芬尼斯的论证简化为『实证主义完全不讲道德』，他的批评针对的是权威解释的充分性。", "keywords": [["诘难设定", "不义制度下的公民询问法律权威"], ["四种可能回答", "自利、相信官员追随道德、接受标准、避免无序"], ["芬尼斯结论", "第四种已承认实质价值，实证主义滑向自然法"], ["实证主义回应", "承认规则是接受实践，解释合法性而非仅记录行为"], ["方法论分歧", "法理学是否须承诺道德客观地位"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于自然法理论传统中的不同版本？", "options": ["A 阿奎那的古典理性命令说", "B 富勒的程序性内在道德说", "C 芬尼斯的新自然法说", "D 拉兹的排除实证主义"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】古典自然法、富勒的程序自然法与芬尼斯的新自然法构成自然法家族的主要版本。【逐步演示】D 属于法律实证主义内部的强硬立场，与自然法相对。【易错提醒】富勒的版本尤其特殊：他主张的是形式程序要求，并不预设一套实质正义标准。"}, {"order": 11, "qtype": "single", "stem": "Wacks 用『在不同层面上打影子拳』来形容两派，意在说明：", "options": ["A 两派完全没有任何共同点", "B 很多对立源于层面错位，双方未必真正交锋", "C 自然法已经彻底战胜实证主义", "D 法理学争论毫无意义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 借此提示：识别法律的标准与服从法律的理由属于不同层面，双方常在各说各话。【逐步演示】他列出两派的四项共同基础，进一步说明分歧被夸大。【易错提醒】这是一种诊断，并不等于宣布争论无意义，也不等于取消双方差异。"}, {"order": 12, "qtype": "judge", "stem": "法律实证主义与自然法两派都认为，对不正义的法律存在初步的服从义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，两派都否认对不正义法律存在初步的服从义务，这正是他们的共同基础之一。【逐步演示】分歧在于把这种否认放在概念内部还是外部。【易错提醒】『无初步服从义务』与『可以不服从任何法律』并非一回事，切勿过度推广。"}, {"order": 13, "qtype": "essay", "stem": "试析哈特『最低限度自然法』论证的性质：它是否成功地在实证主义框架内承认了自然法要素？", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先重构论证前提与结论，再评估其与自然法主张的距离。【逐步演示】哈特承认法律与某种善的事实性重合，但拒绝把道德作为概念性效力判准。【易错提醒】不要把这一承认说成哈特转向自然法，他的核心立场仍是分离命题。", "keywords": [["经验事实前提", "脆弱性、大体平等、有限利他、资源有限"], ["推论结果", "必须保护人身、财产与承诺"], ["与道德的联系是事实性", "条件性而非概念必然"], ["与古典自然法区别", "恶法非法属实质命题"], ["可能的批评", "无法阻挡残酷而高效的秩序"]]}]}, "S3M4K4": {"lesson": "S3M4K4", "questions": [{"order": 1, "qtype": "single", "stem": "法律现实主义把研究重心放在：", "options": ["A 法律概念的逻辑分析", "B 行动中的法，即法律的社会实际运作", "C 自然法的道德基础", "D 国际条约的条文结构"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】现实主义反对概念法学，强调研究法院与法律在社会中的实际运作，即『行动中的法』。【逐步演示】与之相对的是『书本上的法』。【易错提醒】现实主义虽重视经验，仍被广义归入实证主义阵营，与纯粹的自然法探究有别。"}, {"order": 2, "qtype": "single", "stem": "霍姆斯『坏人理论』的要点是：", "options": ["A 法律应当以坏人的道德为标准", "B 从只关心可预测后果的利害关系人视角理解法律", "C 坏人比法官更懂法律条文", "D 法律应当惩罚一切坏人"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】霍姆斯说，若只想了解法律，就要像坏人那样看它，因为他只关心法律知识的物质后果。【逐步演示】由此得出著名命题：法律就是对法院实际上会做什么的预言。【易错提醒】这是一种分析视角，不是道德主张，更不是在赞美坏人。"}, {"order": 3, "qtype": "judge", "stem": "美国现实主义者与斯堪的纳维亚现实主义者立场完全一致，差别只是名称不同。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 强调两支差别显著，有人甚至认为相似之处仅是字面上的。【逐步演示】美国人偏实用与行为主义，聚焦法院，是规则怀疑论者；斯堪的纳维亚人攻击法律形而上学，是形而上学怀疑论者。【易错提醒】两支确有共同点：经验主义、实用主义、拒斥绝对价值，但不能因此抹平差异。"}, {"order": 4, "qtype": "multi", "stem": "根据莱特的概括，美国现实主义『核心命题』包含下列哪些要素？", "options": ["A 法官对案件底层事实作出反应", "B 法律规则在上诉审中作用有限", "C 许多现实主义者希望规则更贴近事实", "D 法官完全不受任何规则约束"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】莱特列出三要素：法官回应事实、法律规则与理由效果甚微、推动规则具体化。【逐步演示】D 过于绝对，现实主义者并未完全否认规则可能约束法院。【易错提醒】『作用有限』与『毫无作用』的差别，是理解现实主义分寸感的关键。"}, {"order": 5, "qtype": "blank", "stem": "霍姆斯在《法律之路》中写道：法律的生命不在逻辑，而在______。", "options": [], "answer": "", "accepted": ["经验", "experience", "社会生活经验", "实际经验"], "keywords": [], "explanation": "【答案】经验（experience）。【解题思路】这是霍姆斯最著名的命题，集中体现现实主义对形式主义的反抗。【逐步演示】他同时强调真正的法律科学须依据精确衡量过的社会需求。【易错提醒】不要把它理解为『法律不需要逻辑』，霍姆斯反对的是把逻辑当成唯一通道。"}, {"order": 6, "qtype": "single", "stem": "弗兰克区分规则怀疑论者与事实怀疑论者，他把自己归入：", "options": ["A 规则怀疑论者", "B 事实怀疑论者", "C 形式主义者", "D 自然法学者"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】弗兰克认为多数现实主义者患上了『上诉法院炎』，忽略事实认定的不确定性。【逐步演示】他关注法官与陪审员受偏见影响的程度，认为这才是不可预测性的主要来源。【易错提醒】卢埃林通常被归入规则怀疑论者，注意区分两人的侧重点。"}, {"order": 7, "qtype": "single", "stem": "卢埃林关于现实主义的一句名言是：", "options": ["A 法律是主权者的命令", "B 现实主义不是哲学，而是一项技术", "C 法律是理性的命令", "D 法律是民族精神的体现"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 引述卢埃林：『Realism is not a philosophy—it is a technology』。【逐步演示】这与现实主义强调功能分析与经验研究的取向一致。【易错提醒】A 属奥斯丁，C 属古典自然法，D 属历史法学派。"}, {"order": 8, "qtype": "judge", "stem": "现实主义者完全否认法律规则对法官有任何约束力。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确指出，现实主义者并未彻底否认法院可能受规则约束。【逐步演示】他们主张的是自由裁量比通常设想的更频繁，以及规则在上诉审中作用有限。【易错提醒】1930年代把现实主义斥为虚无主义的批评，Duxbury 认为是对其实际关怀的漫画化。"}, {"order": 9, "qtype": "essay", "stem": "试比较形式主义的三段论裁判模式与现实主义的核心命题，并说明后者对前者提出了哪些质疑。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现形式主义的推理图式，再用现实主义的三项主张逐一拆解。【逐步演示】形式主义把裁判显示为逻辑必然；现实主义指出其掩盖了政策选择与事实不确定性。【易错提醒】现实主义并未取缔逻辑，而是要求把被遮蔽的判断公开出来接受检验。", "keywords": [["形式主义三段论", "大前提规则小前提事实结论判决"], ["现实主义核心命题", "法官回应事实而非规则"], ["自由裁量被低估", "规则无法逻辑导出唯一结果"], ["事实认定的不确定性", "弗兰克的事实怀疑论"], ["经验方法", "社会学心理学进入法学"]]}, {"order": 10, "qtype": "multi", "stem": "关于斯堪的纳维亚现实主义，下列哪些表述符合本节内容？", "options": ["A 哈格斯特罗姆否认法律规则能以非自然方式存在", "B 罗斯认为诉诸正义类似拍桌子", "C 他们主要研究上诉法院的判决模式", "D 他们主张一切形而上学皆为幻象"], "answer": "ABD", "accepted": [], "keywords": [], "explanation": "【答案】ABD。【解题思路】哈格斯特罗姆否认法律规则的非自然存在；罗斯把诉诸正义比作拍桌子；斯堪的纳维亚学者彻底拒斥形而上学。【逐步演示】C 是美国现实主义尤其是规则怀疑论者的关注点。【易错提醒】哈特曾批评把『公正』『不公正』说成毫无意义会导致荒谬，可结合种族隔离的例子理解。"}, {"order": 11, "qtype": "single", "stem": "在 Lochner v New York（1905）案中，霍姆斯大法官的异议主要针对：", "options": ["A 法院把某种经济理论伪装成宪法原则", "B 面包师劳动时间过长", "C 宪法第十四修正案的制定程序", "D 陪审团的事实认定"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】霍姆斯指责多数意见把特定的经济理论塞进宪法，以契约自由之名宣告立法违宪。【逐步演示】该案常被用来说明形式主义演绎背后隐藏的价值选择。【易错提醒】霍姆斯的异议并不否认宪法审查本身，而是反对把政策偏好装成逻辑结论。"}, {"order": 12, "qtype": "judge", "stem": "Duxbury 认为，1930年代把现实主义斥为虚无主义、反民主的批评，依据的是一幅与现实主义者实际关怀相去甚远的漫画。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 引述 Duxbury 的观点，指出这类攻击建立在漫画化理解之上。【逐步演示】现实主义者的关怀包含改革规则、经验研究等专业与教学动机。【易错提醒】这并不等于现实主义毫无可被批评之处，只是批评应针对其真实主张。"}, {"order": 13, "qtype": "essay", "stem": "现实主义提出的问题如何影响了哈特与德沃金的理论建构？", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先说明现实主义的核心挑战，再分别呈现两种回应。【逐步演示】哈特在规则边缘承认裁量，德沃金以隐含原则和无间隙法律否认裁量空间。【易错提醒】两种回应都承认问题无法回避，差别在于是否把不确定性吸收进法律概念内部。", "keywords": [["哈特吸收不确定性直觉", "开放结构与边缘案例"], ["哈特承认有限造法权", "间隙性裁量"], ["德沃金以解释反驳", "建构性解释与整体法"], ["德沃金否认强自由裁量", "赫拉克勒斯"], ["共同点", "必须正面处理司法判断中的政策与事实"]]}]}, "S3M4K5": {"lesson": "S3M4K5", "questions": [{"order": 1, "qtype": "single", "stem": "韦伯区分的三种合法支配类型是：", "options": ["A 民主、专制、共和", "B 传统型、卡里斯马型、法理型", "C 立法、行政、司法", "D 神权、王权、民权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】韦伯以传统、卡里斯马（个人感召）与法理型三种支配说明合法性的不同来源。【逐步演示】法理型支配的合法性来自形式合理的规则，服从对象是法律秩序本身。【易错提醒】A 是政体分类，D 是权力主体的分类，均与韦伯的支配类型学不同。"}, {"order": 2, "qtype": "single", "stem": "在韦伯看来，法理型支配的合法性主要来自：", "options": ["A 统治者的个人魅力", "B 悠久的传统习俗", "C 理性制定、普遍适用的法律规则", "D 宗教经典的启示"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】法理型支配的正当性基础是形式合理的规则体系，政治支配从理性制定的法律中获得正当性。【逐步演示】这种合法性是非人格化的， 服从指向法律秩序而非特定个人。【易错提醒】A 对应卡里斯马型，B 对应传统型，D 接近神权式的实质非理性类型。"}, {"order": 3, "qtype": "multi", "stem": "根据莱斯利·格林的分析，法律的制度化带来的收益与代价包括：", "options": ["A 提高确定性、可变性与效率", "B 集中权力可能被用于压迫", "C 普通民众通常只需默许强制性规范", "D 法律秩序必须依靠全民热烈拥护才能维持"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】格林把制度化视为混合交易：收益是适应性、确定性与效率，代价是组织权力被滥用的风险。【逐步演示】他还指出法律秩序常依赖狭窄的官员共识与民众的默许。【易错提醒】D 与格林的判断相反，他把『广泛共识』视为前法律社会的特征。"}, {"order": 4, "qtype": "judge", "stem": "格林认为，典型的现代法律秩序依赖普通民众对法律的高度认同与广泛社会共识。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】格林指出，典型法律秩序依赖的是狭窄的官员共识，普通民众所需做的往往只是默许。【逐步演示】他把内部观点可能仅限官员群体的情形称为政治上的重大风险。【易错提醒】请不要把『法律有效运作』与『法律获得普遍道德认同』混为一谈。"}, {"order": 5, "qtype": "blank", "stem": "韦伯主张法律受经济条件影响却不为经济单方面决定，这一命题通常被称为法律的______。", "options": [], "answer": "", "accepted": ["相对自主性", "相对的自主性", "relative autonomy", "相对独立性"], "keywords": [], "explanation": "【答案】相对自主性。【解题思路】韦伯认为法律与经济基本相关，但法律结构的发展绝非由经济因素单独决定。【逐步演示】这一命题使法学研究保有独立解释空间。【易错提醒】不要把它说成『法律完全独立于经济』，韦伯反对这种绝对化表述。"}, {"order": 6, "qtype": "single", "stem": "韦伯所说法律理性化的最高阶段，其特征是：", "options": ["A 法律完全由神谕决定", "B 法律命题被整合为逻辑清晰、内部一致、至少在理论上无间隙的规则体系", "C 法官依伦理情感逐案裁断", "D 法律与道德完全不分"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】韦伯把形式合理性的顶点描述为逻辑清晰、内在一致、理论上无间隙的规则体系。【逐步演示】A 属形式非理性，C 接近实质非理性的『卡迪司法』，D 属实质合理性。【易错提醒】韦伯以『理想类型』方式描述，不必认定现实中真有无间隙的法典。"}, {"order": 7, "qtype": "single", "stem": "韦伯所说的『卡迪司法』（Khadi justice）属于哪一类型？", "options": ["A 形式合理", "B 形式非理性", "C 实质合理", "D 实质非理性"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】卡迪司法依伦理、情感与政治考虑逐案裁断，不诉诸一般原则，属于实质非理性。【逐步演示】与之相对，大陆法系法典被视为形式合理的典型。【易错提醒】『实质』指其以具体价值为目标，『非理性』指缺乏内部自足的规则程序。"}, {"order": 8, "qtype": "judge", "stem": "批判法理论主张法律是确定、融贯而中立的规则体系，法学的任务只是对其作忠实注释。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，批判法理论质疑法律的自主性，认为法律不确定、不融贯，也并非理性中立。【逐步演示】它主张法律表达政治经济权力，法学的中立姿态可能提供虚假合法性。【易错提醒】把批判理论的说法照字面当成法律实务的描述，会忽略其批判意图。"}, {"order": 9, "qtype": "essay", "stem": "试述法律自主性争论中批判法理论的主张与反击，并说明韦伯的『相对自主性』命题提供了何种中介立场。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先给出批判命题，再列出自主性一方回应，最后以韦伯定位。【逐步演示】批判理论指向意识形态功能；反击强调法律的规范约束；韦伯以形式合理化解释可计算性及其代价。【易错提醒】不要把『法律即政治』直接推到『法律毫无约束力』，Wacks 认为那是过度简化。", "keywords": [["批判理论主张", "法律与政治不可分"], ["法律不确定不融贯", "表达政治经济权力"], ["反击理由", "程序约束权力且法律可被用来批判权力"], ["韦伯中介", "法律受经济影响但相对自主"], ["形式合理性", "使统治可计算亦提供约束"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于韦伯按法律思想划分的类型？", "options": ["A 形式合理", "B 形式非理性", "C 实质合理", "D 实质非理性"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】韦伯以形式／实质与理性／非理性两条轴线交叉，得出四种法律思想类型。【逐步演示】形式合理以大陆法典为例，形式非理性以神谕裁判为例，实质合理以神权法为例，实质非理性以卡迪司法为例。【易错提醒】 『形式』关注体系是否内部自足，『理性』关注材料如何被适用，两个维度不可互换。"}, {"order": 11, "qtype": "single", "stem": "在 Wacks 所述的纽伦堡『法官审判』相关材料中，被告提出的核心辩解是：", "options": ["A 自己从未参与任何审判", "B 只是服从作为『最高法官』的希特勒的命令、且若辞职会有更坏的人接替", "C 当时德国根本不存在法院", "D 国际法当时已明确禁止该行为"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 记载，以施莱格尔贝格尔为原型的被告以服从命令、并无恶意、辞职会带来更坏替代者等理由辩护。【逐步演示】这类辩词把职业义务与道德责任的张力推到极端。【易错提醒】D 与史实不符，当时并未有如此明确可援用的禁止性国际法依据。"}, {"order": 12, "qtype": "judge", "stem": "韦伯认为经济因素直接且单方面地决定了西方法律结构的发展。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】韦伯主张法律具有相对自主性，经济因素对法律的影响是间接的。【逐步演示】他明确表示法律结构的发展绝非由经济因素单方面决定。【易错提醒】把他等同于经济决定论是 Wacks 所称的『粗略但严重的简化』。"}, {"order": 13, "qtype": "essay", "stem": "结合格林的制度代价论与韦伯的法理型支配论，分析第三帝国法官以『服从法律』为由辩护为何难以成立。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先用格林说明制度如何放大权力，再用韦伯说明形式合法性的边界。【逐步演示】法官不仅适用规则，也以其职业身份为不义秩序提供合法外观，因此『服从』叙事无法承担全部辩解功能。【易错提醒】结论应停留在法理分析层面，避免把历史人物的具体罪责判断简单化。", "keywords": [["制度代价", "组织权力可被用于压迫"], ["官员共识与责任分散", "个人责任易被分摊"], ["法理型合法性有限", "形式合法不免除道德判断"], ["洪流中的选择", "辞职与替代者不是充分辩护"], ["理论意义", "法律人既约束权力也可能合法化权力"]]}]}, "S3M4K6": {"lesson": "S3M4K6", "questions": [{"order": 1, "qtype": "single", "stem": "形式法治观与实质法治观的根本分歧在于：", "options": ["A 法律是否应当公布", "B 法治是否必须包含正义、人权等价值内容", "C 法律是否应有法院", "D 法律是否应由议会制定"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】形式法治观关注法律的形式与程序品质，实质法治观主张正义与权利构成法治的必要内涵。【逐步演示】公布、法院、议会立法等属于制度技术层面的问题，两派通常并无分歧。【易错提醒】不要把形式法治说成『不要正义』，它只是把正义问题留在法治概念之外处理。"}, {"order": 2, "qtype": "single", "stem": "拉兹把法治定位为『否定性美德』，其含义是：", "options": ["A 法治本身就是最高的道德价值", "B 法治减少任意权力风险，但不赋予法律独立道德价值", "C 法治只适用于民主国家", "D 法治要求法律内容必须正义"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】拉兹认为，遵守法治可减少行政权滥用，但任意权力的风险本由法律制造，因此法治不自带独立道德功劳。【逐步演示】他甚至主张，即使在正义的法律体系中也不存在初步的服从义务。【易错提醒】『否定性』指其功能是减少恶，并非说法治毫无价值。"}, {"order": 3, "qtype": "judge", "stem": "拉兹认为，一个满足法治要求的法律体系因此就获得了独立的道德正当性，公民负有初步服从义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 指出，拉兹明确否认法治赋予法律独立的道德价值。【逐步演示】他的结论是：即使在正义的法律体系中，也不存在初步的服从义务。【易错提醒】这与德沃金把合法性视为道德德性的立场形成鲜明对照。"}, {"order": 4, "qtype": "multi", "stem": "下列哪些属于富勒列出的合法性形式要求？", "options": ["A 不溯及既往", "B 清晰且不矛盾", "C 官方行为与公布规则一致", "D 法律必须由选举产生的机关制定"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】不溯及既往、清晰、不矛盾、官方行为与规则一致均属于八项要求。【逐步演示】D 是民主程序要求，富勒的清单聚焦法律的一般形式品质，并未把特定立法机关作为条件。【易错提醒】富勒称八项要求为『渴望的道德』，它们是制度努力的方向。"}, {"order": 5, "qtype": "blank", "stem": "德沃金用______（legality）一词统合法治所服务的政治价值，包括效率、平等与自我治理。", "options": [], "answer": "", "accepted": ["合法性", "合法性（legality）", "legality", "法律性"], "keywords": [], "explanation": "【答案】合法性（legality）。【解题思路】Wacks 指出，德沃金把法治与整体性所服务的政治德性称为 legality。【逐步演示】这一概念强调法律约束的价值超出效率，指向公民平等与政治权力的道德证成。【易错提醒】不要与实证主义所说的『有效性』（validity）混同，后者是识别法律的概念。"}, {"order": 6, "qtype": "single", "stem": "Wacks 以南非种族隔离制度为例，主要是为了说明：", "options": ["A 形式合法并不足以保证实质正义", "B 法治在任何国家都不可能实现", "C 富勒的八项要求毫无价值", "D 种族隔离制度完全没有法律形式"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出该制度很可能满足了富勒的全部八项形式要求，从而显示形式合法与正义之间的缝隙。【逐步演示】富勒试图以种族定义的任意性回应，但这一回应是否充分仍有争议。【易错提醒】这并不推翻八项要求的价值，只否定『形式合法即正义』的推论。"}, {"order": 7, "qtype": "single", "stem": "法治中『稳定性与变革性』的张力，主要表现为：", "options": ["A 法律越稳定就越正义", "B 规则需要稳定以供规划，又必须能适应新情境", "C 法律不应被修改", "D 法律应每天更新"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】不溯及既往与稳定性保障可预期性，但完全不可变的法律无法回应社会变化。【逐步演示】富勒把八项要求称为渴望的道德，正体现了这种持续追求而不能一劳永逸的状态。【易错提醒】两种极端表述（永不修改或每日更新）都取消了张力本身。"}, {"order": 8, "qtype": "judge", "stem": "富勒把八项合法性要求称为『义务的道德』，意思是一旦满足即可高枕无忧。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】富勒称其为『渴望的道德』（morality of aspiration），区别于『义务的道德』。【逐步演示】它诉诸立法者的受托感与技艺自尊，是制度不断努力的方向，而非一次性核对清单。【易错提醒】Wacks 提醒，满足八项要求并不会使一个法律体系免于批评。"}, {"order": 9, "qtype": "essay", "stem": "比较富勒、拉兹与德沃金对法治的定位，说明他们各自把法治的规范性放在何处。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先分别概括三人的命题，再比较规范性的落点。【逐步演示】富勒放在程序的内在道德，拉兹放在风险的降低，德沃金放在共同体道德正当性。【易错提醒】不要简单地说谁更重视法治，三人的分歧在于法治为何值得珍视。", "keywords": [["富勒", "内在道德与渴望的道德"], ["拉兹", "否定性美德与减少专断"], ["德沃金", "合法性与整体性"], ["规范性的不同落点", "程序品质、风险控制、道德证成"], ["共同前提", "法治既约束权力也可能被权力借用"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于本节所列的现代法治理论困境？", "options": ["A 稳定性与变革性的张力", "B 确定性与司法裁量的张力", "C 形式合法与实质正义的张力", "D 工具价值与内在价值的张力"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四组张力构成本节对法治困境的基本分析框架。【逐步演示】它们分别对应富勒的渴望道德、哈特与德沃金的裁量之争、南非反例、以及效率与平等之争。【易错提醒】四组张力彼此关联，答题时最好能说明每一组对应的理论争论。"}, {"order": 11, "qtype": "single", "stem": "德沃金强调法治的价值超出效率，主要因为他认为法治还服务于：", "options": ["A 统治者的便利", "B 公民之间的平等与共同体的自我治理", "C 法律的完全自动适用", "D 行政权的扩张"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金认为法律的整体性保障公民平等并促进民主参与，使政治权力获得更好的道德证成。【逐步演示】他明确指出，暴君也不会完全抛弃法治而纯凭任性统治，但法治的价值不止于效率。【易错提醒】D 与法治的限制权力取向相反。"}, {"order": 12, "qtype": "judge", "stem": "Wacks 指出，自然法理论与法律实证主义虽然争论激烈，却都重视法治理想。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Wacks 在列举两派共同基础时，明确把『都接受法治理想的重要性』列为其中之一。【逐步演示】这说明法治是两派对话的共同平台，而非某一方的专属价值。【易错提醒】承认共同点不等于取消分歧，尤其在法律效力是否依赖道德这一点上。"}, {"order": 13, "qtype": "essay", "stem": "为什么说紧急状态中的法律例外措施构成法治的自我理解难题？请结合本节的张力分析。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】用稳定性与变革、确定性与裁量、形式与实质三组张力分析例外措施。【逐步演示】例外既可能是法治自我保存的手段，也可能成为权力摆脱约束的通道，关键在于可否被公开、限时和审查。【易错提醒】答题时避免简单宣称例外必然破坏法治或必然必要，应呈现两面。", "keywords": [["例外的必要性", "危机中常规规则可能失灵"], ["确定性受损", "暂停保障削弱可预期性"], ["形式合法风险", "授权例外可能被常态化"], ["实质正义维度", "须检验措施是否歧视或任意"], ["制度约束", "公开、时限、审查可缩小例外空间"]]}]}, "S3M5K1": {"lesson": "S3M5K1", "questions": [{"order": 1, "qtype": "single", "stem": "『责任缺口』（responsibility gap）在 AI 语境中主要指：", "options": ["A AI 系统完全不会造成损害", "B 损害确已发生却难以找到可归责的主体", "C 法律根本不存在侵权责任制度", "D 受害者无权获得任何救济"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】责任缺口指当系统以不可预测方式致害、各人类主体都能声称缺乏控制时，归责失去落脚点。【逐步演示】争议在于它是真正的缺口，还是责任在链条上被分散。【易错提醒】它并不等于法律制度对 AI 损害完全不作为。"}, {"order": 2, "qtype": "single", "stem": "关于 AI 系统的法律人格，当前主要法域的一般立场是：", "options": ["A 一律赋予完整法律人格", "B 普遍不赋予独立法律人格，后果由自然人或组织承担", "C 只在刑事案件中赋予人格", "D 由国际条约统一赋予人格"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】本节指出，各主要法域普遍未赋予 AI 系统独立法律人格，其输出后果由链条上的人或组织承担。【逐步演示】有限法律人格仍是学界少数方案，反对者担心真正控制者脱身。【易错提醒】『不赋予人格』不意味着 AI 输出没有法律意义，只意味着责任主体另有其人。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于本节讨论的 AI 责任方案？", "options": ["A 扩展既有产品责任", "B 对高风险 AI 引入严格责任", "C 赋予 AI 有限法律人格", "D 以强制保险或赔偿基金分散风险"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四种方案分别对应既有制度延伸、风险归责、主体资格扩张与风险融资。【逐步演示】每种方案各有优劣，本节并未认定某一种为唯一答案。【易错提醒】欧盟《人工智能法案》主要配置事前合规义务，与上述事后责任方案属于不同层面。"}, {"order": 4, "qtype": "judge", "stem": "欧盟《人工智能法案》直接创设了一套全新的 AI 侵权责任法，因此个案赔偿无需再借助侵权或产品责任规则。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】《人工智能法案》主要规定事前合规义务与风险分级，并未取代各法域的侵权与产品责任规则。【逐步演示】它为判断注意义务与违规提供参照，个案赔偿仍需结合既有责任法。【易错提醒】合规与赔偿是两个层面，不要把监管法等同于责任法。"}, {"order": 5, "qtype": "blank", "stem": "欧盟《人工智能法案》的法规编号是 Regulation (EU)______。", "options": [], "answer": "", "accepted": ["2024/1689", "EU 2024/1689", "2024/1689 (Artificial Intelligence Act)"], "keywords": [], "explanation": "【答案】2024/1689。【解题思路】该法全称为 Regulation (EU) 2024/1689，2024年6月13日通过。【逐步演示】2024年8月1日生效，规则分阶段适用至2027年。【易错提醒】不要与 GDPR 的 Regulation (EU) 2016/679 混淆。"}, {"order": 6, "qtype": "single", "stem": "严格责任与过错责任的关键差别在于：", "options": ["A 严格责任不以过错为要件，依风险归属分配损害", "B 严格责任要求证明被告有故意", "C 过错责任不要求有损害结果", "D 两者完全相同"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】严格责任把注意义务问题搁置，直接依据风险创造与利益归属分配损害。【逐步演示】过错责任则须证明行为人未尽合理注意。【易错提醒】严格责任不等于绝对责任，仍可能存在法定抗辩事由。"}, {"order": 7, "qtype": "single", "stem": "模型的不透明性对传统侵权责任的主要冲击是：", "options": ["A 使损害不再发生", "B 使因果关系与过错的证明变得困难", "C 使法律人格自动成立", "D 使监管变得多余"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】深度学习模型的内部过程难以外部重构，原告难以证明哪一环节导致了损害。【逐步演示】证据偏在可能要求调整举证负担。【易错提醒】不透明性是程度问题，并非所有 AI 系统都同等不可解释。"}, {"order": 8, "qtype": "judge", "stem": "欧盟《人工智能法案》于2024年8月1日生效，其各项规定分阶段适用，最迟到2027年8月全部适用。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】Regulation (EU) 2024/1689 于2024年8月1日生效，适用采取分阶段安排。【逐步演示】不同风险类别的义务有不同时间表，全部规则至2027年8月适用。【易错提醒】『生效』与『全部适用』是两个不同时间点，答题时须区分。"}, {"order": 9, "qtype": "essay", "stem": "试述『责任缺口是否真实存在』的争论，并说明它对侵权法归责逻辑提出了什么挑战。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现双方立场，再说明其共同指向的法学难题。【逐步演示】传统侵权法以人的过错与控制为中心，AI 场景把这些前提都变成可争议的问题。【易错提醒】不要把争论写成『AI 应否被惩罚』，焦点在于归责机制能否运行。", "keywords": [["缺口方主张", "各主体皆守规却致害时无人可归责"], ["反方主张", "缺口只是责任分散而非消失"], ["过错逻辑的压力", "控制力分散与不可预见"], ["因果关系证明", "不透明性与举证负担"], ["制度回应", "严格责任或强制保险等不依过错机制"]]}, {"order": 10, "qtype": "multi", "stem": "根据本节内容，欧盟《人工智能法案》的风险分级监管包括下列哪些做法？", "options": ["A 禁止不可接受风险的做法", "B 对高风险系统设定提供者与部署者义务", "C 对部分系统施加透明度要求", "D 对所有 AI 系统一律适用同一套义务"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】该法以风险为轴心分层配置义务，不同等级对应不同要求。【逐步演示】D 与风险分级的思路直接冲突。【易错提醒】风险分级的意义在于把监管资源集中于高风险场景，而非平均用力。"}, {"order": 11, "qtype": "single", "stem": "从哈特的规则理论看，把决策规则写入代码容易掩盖的事实是：", "options": ["A 代码没有逻辑结构", "B 数据选择、目标设定与部署场景裁剪都蕴含制度性选择", "C 算法不能被任何人理解", "D 法律规则与代码完全相同"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】算法输出看似是规则适用，实则背后有大量的设计选择。【逐步演示】这些选择类似于哈特所说的次级规则，决定了初级规则如何被识别与执行。【易错提醒】不要因为代码可执行就把它等同于法律效力，二者分属不同规范体系。"}, {"order": 12, "qtype": "judge", "stem": "风险分级监管意味着所有 AI 系统都受到同等强度的法律监管。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】风险分级的核心正是区别对待：不可接受风险被禁止，高风险系统负担特定义务，其他系统要求较轻。【逐步演示】这种差异配置旨在平衡保护与创新。【易错提醒】『分级』与『一律』是相反的监管逻辑。"}, {"order": 13, "qtype": "essay", "stem": "结合德沃金的原则理论，分析 AI 损害归责中『谁受益谁负担』这一直觉的法理依据与限度。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】把受益负担直觉改写为德沃金式的原则命题，再指出其在多主体链条中的适用困难。【逐步演示】原则要求认真对待受害者权利，但受益者分散时须借助制度工具补足。【易错提醒】不要停留在道德直觉层面，要落到原则与政策的区分上。", "keywords": [["原则而非政策", "归责须尊重个体权利"], ["公平原则", "风险创造者负担损害"], ["权利作为王牌", "不能为创新任意牺牲受害者"], ["限度", "受益主体分散且难界定"], ["制度替代", "保险与基金可补充"]]}]}, "S3M5K2": {"lesson": "S3M5K2", "questions": [{"order": 1, "qtype": "single", "stem": "GDPR 第22条主要处理的问题是：", "options": ["A 数据跨境传输", "B 数据主体在一定条件下不受纯粹自动化决定约束", "C 数据税的征收", "D 平台的市场支配地位"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】GDPR 第22条规定数据主体有权在特定情形下不受仅基于自动化处理的决定约束，并设置例外与保障。【逐步演示】这是早期把自动化决策纳入权利框架的重要立法尝试。【易错提醒】第22条并非全面禁止自动化决策，而是设置条件与保障。"}, {"order": 2, "qtype": "multi", "stem": "本节归纳的算法治理工具包括：", "options": ["A 透明度与说明义务", "B 事前评估（DPIA/FRIA）", "C 问责与审计", "D 完全放弃监管、交由市场自发调节"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】三类工具分别从事前、信息、过程三个维度约束算法权力。【逐步演示】D 属于放任立场，与本节讨论的制度回应方向相反。【易错提醒】三类工具常组合使用，答题时不宜把它们理解为互斥方案。"}, {"order": 3, "qtype": "single", "stem": "欧盟《数字服务法》（Regulation (EU) 2022/2065）的适用时间点是：", "options": ["A 2018年5月", "B 2020年7月", "C 2022年11月", "D 2024年2月起全面适用"], "answer": "D", "accepted": [], "keywords": [], "explanation": "【答案】D。【解题思路】《数字服务法》2022年通过，2024年2月起全面适用。【逐步演示】A 对应 GDPR 开始适用，B 对应 Schrems II 判决日期，C 接近该法生效时间。【易错提醒】注意区分『通过』『生效』与『全面适用』三个时间点。"}, {"order": 4, "qtype": "judge", "stem": "算法的可解释性等同于技术上的可复现性：只要系统能被重复运行，当事人就获得了可理解的理由。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节明确区分可解释性与技术可复现性。【逐步演示】一个系统可被重复执行，仍可能无法向受影响者说明其判断理由。【易错提醒】法律上的说明理由面向人的理解，不等同于工程上的可重复。"}, {"order": 5, "qtype": "blank", "stem": "GDPR 要求对高风险数据处理活动进行事前评估，这种机制简称为______。", "options": [], "answer": "", "accepted": ["DPIA", "数据保护影响评估", "data protection impact assessment", "数据保护影响评价"], "keywords": [], "explanation": "【答案】DPIA（数据保护影响评估）。【解题思路】DPIA 聚焦对个人数据主体权利的高风险影响。【逐步演示】《人工智能法案》另设 FRIA，覆盖更广泛的基本权利维度。【易错提醒】DPIA 与 FRIA 逻辑相近但范围不同，不要混用。"}, {"order": 6, "qtype": "single", "stem": "与 DPIA 相比，FRIA 的特点是：", "options": ["A 只关注数据主体隐私权", "B 覆盖非歧视、公正审判等更广泛的基本权利", "C 仅适用于公共机关", "D 仅在损害发生后进行"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】本节指出，FRIA 覆盖更广泛的基本权利维度，包括非歧视与公正审判等。【逐步演示】DPIA 主要聚焦数据主体的隐私与数据权利。【易错提醒】二者都是事前机制，不是事后救济。"}, {"order": 7, "qtype": "judge", "stem": "算法透明度要求与商业秘密、系统安全之间可能存在冲突，需要作出制度上的平衡。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】本节把透明度与商业秘密、安全的冲突列为治理悖论之一。【逐步演示】常见折中是向监管者提供完整审计信息，向当事人提供可理解的要点说明。【易错提醒】这不是要求完全公开源代码，而是分层配置信息。"}, {"order": 8, "qtype": "single", "stem": "把算法偏见理解为『规范问题』而非单纯的『数据问题』，意味着：", "options": ["A 只需要清洗训练数据", "B 必须追问谁有权定义公平以及受影响群体是否参与", "C 模型准确性不再重要", "D 法律不应介入"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】规范问题的理解把偏见追溯到权力结构与价值标准的制定过程。【逐步演示】数据清洗只能应对经验层面，无法回答何为公平的规范问题。【易错提醒】两种理解并非互斥，但法律关切的重点不同。"}, {"order": 9, "qtype": "essay", "stem": "试述算法可解释性争论中的双方理由，并提出一种分层披露的折中思路。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现两种理由，再说明分层披露如何平衡。【逐步演示】支持方诉诸当事人质疑权，反对方诉诸技术现实与滥用风险；分层披露按对象配置信息。【易错提醒】不要主张完全公开源代码，那既不可行也未必有助理解。", "keywords": [["支持方理由", "重大利益决定须说明理由"], ["反对方理由", "商业秘密、安全与技术困难"], ["分层披露", "监管者完整审计、当事人要点说明"], ["可解释不等于可复现", "面向人的理解"], ["制度意义", "把黑箱决定纳入问责"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于欧盟算法与平台治理的立法链条？", "options": ["A GDPR 第22条", "B 《数字服务法》", "C 《数字市场法》", "D 《人工智能法案》"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四者分别涉及自动化决策、平台透明度与风险、守门人义务、高风险 AI 系统义务。【逐步演示】它们共同体现从数据处理到系统治理的监管演进。【易错提醒】四部法规功能不同，不应笼统地说它们都是『人工智能法』。"}, {"order": 11, "qtype": "single", "stem": "从德沃金的权利理论看，算法歧视之所以应被谴责，主要因为它：", "options": ["A 降低系统运行效率", "B 侵犯个体被平等对待的权利", "C 违反商业惯例", "D 造成服务器负担"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】德沃金把权利视为对抗集体目标的王牌，算法歧视的核心问题在于侵犯平等权。【逐步演示】效率损失只是附带问题，不能替代权利判断。【易错提醒】若仅以效率为判准，某些高效但歧视的系统就可能被容忍。"}, {"order": 12, "qtype": "judge", "stem": "从哈特的规则理论看，算法只执行既有的初级规则，本身不承担任何类似次级规则的功能。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节指出，算法通过设定识别与筛选标准，同样发挥了类似次级规则的功能。【逐步演示】数据选择、目标函数与部署场景的裁剪，决定了哪些初级规则如何被适用。【易错提醒】把算法简单理解为『执行工具』，会忽略其规则塑造作用。"}, {"order": 13, "qtype": "essay", "stem": "比较算法治理中事前评估与事后责任两种路径的优势与局限。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】分别列出两种路径的得失，再说明组合的可能。【逐步演示】事前评估把风险识别前置，事后责任提供个案救济；理想方案是按风险等级分配二者权重。【易错提醒】不要把两者写成非此即彼，现实制度通常并用。", "keywords": [["事前评估优势", "防患于未然并嵌入流程"], ["事前评估局限", "技术变化快且可能流于形式"], ["事后责任优势", "灵活并针对实际损害"], ["事后责任局限", "救济滞后且证明困难"], ["组合思路", "风险分级配置两套机制"]]}]}, "S3M5K3": {"lesson": "S3M5K3", "questions": [{"order": 1, "qtype": "single", "stem": "关于 GDPR 的时间表，下列表述正确的是：", "options": ["A 2016年通过并立即适用", "B 2016年通过，2018年5月25日起适用", "C 2018年通过，2020年适用", "D 2020年通过，2024年适用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】GDPR（Regulation (EU) 2016/679）于2016年4月27日通过、5月24日生效，2018年5月25日起适用。【逐步演示】两年的过渡期使各成员国与企业得以调整制度。【易错提醒】区分『通过』『生效』『适用』三个时间点。"}, {"order": 2, "qtype": "multi", "stem": "下列哪些属于 GDPR 第5条确立的处理原则？", "options": ["A 目的限制与数据最小化", "B 合法、公平、透明", "C 存储限制与问责", "D 数据必须无偿公开"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】第5条确立合法性、公平性、透明性、目的限制、数据最小化、准确性、存储限制、完整性与保密性、问责等原则。【逐步演示】D 不在原则清单内，与数据保护目标相反。【易错提醒】『问责』要求控制者能够证明合规，不只是内心负责。"}, {"order": 3, "qtype": "single", "stem": "欧洲法院在 Google Spain 案（2014）中的核心结论是：", "options": ["A 搜索引擎运营者在特定条件下构成数据控制者，个人可请求移除链接", "B 搜索引擎永远只是技术中介", "C 个人信息一旦合法发布就永久不可删除", "D 数据保护不适用于互联网"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法院依搜索引擎对信息索引与展示的实际控制，认定其可构成控制者，并支持符合条件的移除请求。【逐步演示】该案奠定了『被遗忘权』在欧洲法上的基础。【易错提醒】删除权并非绝对，仍须与公共利益相权衡。"}, {"order": 4, "qtype": "judge", "stem": "Google Spain 案中，欧洲法院接受了搜索引擎『只是技术中介』的自我定位，因此否认其承担数据保护义务。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】法院依据主体对处理目的与方式的实际决定认定控制者身份。【逐步演示】使个人信息可被检索本身即构成处理活动，因此运营者须承担相应义务。【易错提醒】法律认定看实际功能，而非主体的自我描述。"}, {"order": 5, "qtype": "blank", "stem": "个人在一定条件下要求删除或移除其个人信息的权利，通常被称为______。", "options": [], "answer": "", "accepted": ["被遗忘权", "删除权", "right to be forgotten", "right to erasure", "数据删除权"], "keywords": [], "explanation": "【答案】被遗忘权（right to be forgotten）。【解题思路】该权利源于 Google Spain 案，并在 GDPR 第17条中以删除权形式制度化。【逐步演示】其适用须与个人信息的相关性、损害及公共利益相衡量。【易错提醒】它不是无条件的『删除一切』权利。"}, {"order": 6, "qtype": "single", "stem": "欧洲法院在 Schrems II 案（2020）中的处理是：", "options": ["A 宣告欧盟—美国隐私盾决定无效，同时确认标准合同条款在个案评估下仍可使用", "B 全面禁止个人数据跨境传输", "C 认定标准合同条款一律无效", "D 免除数据控制者的评估义务"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】该案（Case C-311/18，2020年7月16日判决）宣告隐私盾充分性决定无效，同时维持标准合同条款的有效性，但要求个案评估。【逐步演示】这促成了传输影响评估的实践。【易错提醒】判决并未全面禁止跨境传输，也不是承认绝对的数据主权。"}, {"order": 7, "qtype": "judge", "stem": "数据隐私权在当代只具有防御性，个人无权要求更正、删除或转移其数据。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节指出，数据隐私已从消极防御扩展为包含访问、更正、删除、可携与反对自动化决定的权利束。【逐步演示】GDPR 第15至22条具体规定了这些权利。【易错提醒】把隐私权等同于单纯的『别管我』，已无法描述数字环境中的权利实践。"}, {"order": 8, "qtype": "single", "stem": "对知情同意机制的主要批评是：", "options": ["A 同意总是被法律禁止", "B 实践中同意往往流于形式，个人缺乏议价能力与理解能力", "C 同意会损害数据处理者利益", "D 同意机制从未被法律采用"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】批评者指出，复杂条款与不透明实践使同意难以体现真实自主。【逐步演示】这促使人们重视合法利益等其他处理基础与风险规制。【易错提醒】批评同意机制不等于否定个人自主的价值。"}, {"order": 9, "qtype": "essay", "stem": "试论被遗忘权与信息自由、公众知情权之间的张力，并说明法律应如何处理。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现双方价值，再说明衡量标准与制度方案。【逐步演示】Google Spain 案说明即便信息原本合法发布，继续展示仍可能失去正当性，但公共性可构成保留理由。【易错提醒】不要给出『删除权优先』或『信息自由优先』的简单答案。", "keywords": [["权利依据", "个人对过时信息的控制利益"], ["冲突价值", "言论自由、新闻与学术"], ["利益衡量", "相关性、损害与公共性"], ["制度方案", "类型化规则或个案衡量"], ["风险", "删除过度损害公共记忆"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于 GDPR 赋予数据主体的权利？", "options": ["A 访问权", "B 更正权与删除权", "C 可携权与反对权", "D 无限制地获取他人数据的权利"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】GDPR 第15至21条分别规定访问、更正、删除、限制、可携与反对等权利。【逐步演示】第22条另设自动化决定相关保障。【易错提醒】数据主体权利保护的是自身数据，不构成获取他人信息的普遍权利。"}, {"order": 11, "qtype": "single", "stem": "GDPR 要求对可能给数据主体带来高风险的处理活动进行事前评估，这一义务规定在：", "options": ["A 第5条", "B 第22条", "C 第35条", "D 第6条"], "answer": "C", "accepted": [], "keywords": [], "explanation": "【答案】C。【解题思路】GDPR 第35条规定数据保护影响评估（DPIA）。【逐步演示】第5条是原则，第6条是合法基础，第22条是自动化决定。【易错提醒】各条款功能不同，答题时应把条款号与制度功能对应起来。"}, {"order": 12, "qtype": "judge", "stem": "从法理上看，数据隐私权主要是一项财产权，其价值在于数据的市场交易价格。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节强调数据权利具有人格与尊严维度，不能简化为财产利益。【逐步演示】德沃金式的权利理解把隐私视为对抗集体目标的王牌。【易错提醒】承认数据具有经济价值，与把隐私权等同于财产权，是两个不同命题。"}, {"order": 13, "qtype": "essay", "stem": "用德沃金『权利作为王牌』的思路，分析数据保护为何不能仅以效率或创新为由被牺牲。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先解释王牌命题，再把它应用于数据场景，并说明其限度。【逐步演示】创新与效率属于政策目标，权利对其有优先性；但权利之间仍需协调。【易错提醒】不要把王牌理解为绝对权利，德沃金的理论仍要求在原则之间作解释性判断。", "keywords": [["权利命题", "个人数据利益具独立性"], ["王牌含义", "不能被集体目标轻易压倒"], ["尊严与平等", "人格维度非财产化"], ["例外与衡量", "权利仍须与他人权利协调"], ["制度含义", "合法基础与救济程序不可空缺"]]}]}, "S3M5K4": {"lesson": "S3M5K4", "questions": [{"order": 1, "qtype": "single", "stem": "思想与表达二分规则的含义是：", "options": ["A 著作权保护思想而不保护表达", "B 著作权保护表达而不保护思想本身", "C 著作权同时保护思想与表达", "D 著作权只保护已发表的作品"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】著作权保护的是思想的具体表达形式，思想、事实与方法本身不归任何人专有。【逐步演示】这条界线是划定权利客体的基本工具。【易错提醒】A 把规则颠倒，C 过度扩张权利，均不符合著作权法理。"}, {"order": 2, "qtype": "single", "stem": "中国著作权法上的作者范围是：", "options": ["A 仅自然人", "B 自然人、法人或非法人组织", "C 包括人工智能系统", "D 仅注册登记的主体"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】本节指出，中国著作权法以自然人、法人或非法人组织依法创作的作品为保护对象，AI 本身不能成为作者。【逐步演示】人借助 AI 生成的内容若符合作品构成条件，仍可能受到保护。【易错提醒】『AI 不能当作者』与『AI 生成物一概不保护』并不等同。"}, {"order": 3, "qtype": "multi", "stem": "下列哪些属于著作权的典型证成理论？", "options": ["A 劳动论", "B 人格论", "C 激励论", "D 主权命令论"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】劳动论诉诸创作者劳动，人格论诉诸作品与人格的联系，激励论诉诸社会福利与创作激励。【逐步演示】三种理论对 AI 生成物会给出不同判断。【易错提醒】D 属于法的命令理论，与知识产权证成无关。"}, {"order": 4, "qtype": "judge", "stem": "美国 Thaler v Perlmutter 案的最终立场是承认人工智能可以作为版权法上的作者。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】美国版权局与法院坚持人类作者身份是版权保护的基本要求，未承认 AI 为作者。【逐步演示】该立场在2023年地区法院判决及后续上诉中得到维持。【易错提醒】该案否定的只是『纯 AI 生成成果』的作者身份，并非否定所有借助 AI 的创作。"}, {"order": 5, "qtype": "blank", "stem": "北京互联网法院对首例『AI 文生图』著作权侵权案作出一审判决的日期是2023年______月27日。", "options": [], "answer": "", "accepted": ["11", "十一", "11月", "十一月"], "keywords": [], "explanation": "【答案】11月。【解题思路】该案于2023年11月27日一审宣判，双方均未上诉。【逐步演示】法院认定涉案图片具有独创性，构成作品。【易错提醒】注意与案件立案时间（2023年5月）区分。"}, {"order": 6, "qtype": "single", "stem": "李某诉刘某案中，法院认定作品构成的关键理由是：", "options": ["A 图片完全由 AI 自动生成", "B 使用者在提示设计、参数调整与结果筛选中体现了智力投入与个性化选择", "C 图片已获得广泛网络传播", "D 被告承认侵权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】法院把创作过程中的人类智力投入作为独创性的依据。【逐步演示】它明确表示 AI 模型不是法律主体，不能成为作者。【易错提醒】传播范围与被告态度都不是作品构成的法定要件。"}, {"order": 7, "qtype": "judge", "stem": "根据李某案与 Thaler 案可以推出的共同前提是：作者须有人类参与；两案的分歧在于参与达到何种程度才算创作。", "options": [], "answer": "对", "accepted": [], "keywords": [], "explanation": "【答案】对。【解题思路】两案都坚持人类作者身份，差别在于对人类智力投入的判断标准。【逐步演示】这反映既有法律概念体系在技术挑战下的韧性。【易错提醒】不要把两案理解为结论完全相反，它们共享更深层的前提。"}, {"order": 8, "qtype": "single", "stem": "关于知识产权国际条约的时间，下列表述正确的是：", "options": ["A TRIPS 协定于1994年生效，《世界知识产权组织版权条约》于1996年通过", "B 两者均于2019年通过", "C TRIPS 协定由世界知识产权组织于1967年通过", "D 《世界知识产权组织版权条约》是欧盟指令"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】TRIPS 协定于1994年生效，WIPO 版权条约于1996年通过。【逐步演示】2019年通过的是欧盟《数字单一市场版权指令》，不是国际条约。【易错提醒】注意区分国际条约、WTO 协定与欧盟指令三种不同的法律文件。"}, {"order": 9, "qtype": "essay", "stem": "试述 AI 生成物可版权性的争论，并说明劳动论、人格论与激励论各自可能给出的答案。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现正反理由，再用三种证成理论分别检验。【逐步演示】不同理论对同一技术事实会导向不同规范结论，这说明争论实质是价值选择。【易错提醒】不要仅以『技术中性』回避规范判断。", "keywords": [["反对保护理由", "缺乏人类作者与人格投入"], ["支持保护理由", "人有实质性选择与投入"], ["劳动论", "追问智力劳动归属"], ["人格论", "追问体现谁的人格"], ["激励论", "关注保护能否促进创作"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于著作权权利限制或公共获取机制？", "options": ["A 合理使用", "B 法定许可", "C 公共领域", "D 技术保护措施"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】合理使用、法定许可与公共领域构成权利外部边界，保障公众获取。【逐步演示】D 是权利人强化控制的手段，与限制机制方向相反。【易错提醒】技术保护措施也可能受到反规避规则的约束，但它本身服务于权利保护。"}, {"order": 11, "qtype": "single", "stem": "公共领域对于知识产权制度的意义在于：", "options": ["A 使所有作品永久免费", "B 保留不受专有权利限制的知识资源，供公众自由利用", "C 取消作者的一切权利", "D 只适用于政府文件"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】公共领域是不归任何人专有、可供公众自由利用的知识资源，是创新与表达自由的重要条件。【逐步演示】它说明著作权是有限期的制度安排。【易错提醒】公共领域不等于取消知识产权，而是划定其边界。"}, {"order": 12, "qtype": "judge", "stem": "把模型训练界定为『学习』还是『复制』，对法律结论没有影响，因为二者在技术上没有差别。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节明确指出，界定方式不同会导致截然不同的法律结论。【逐步演示】若视为复制，训练数据使用可能构成侵权；若视为学习，则可能落入例外范围。【易错提醒】这是一个规范定性问题，不能仅靠技术描述解决。"}, {"order": 13, "qtype": "essay", "stem": "结合哈特的规则理论与德沃金的权利理论，分析 AI 生成物裁判中『作者』概念的作用。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先说明作者概念在规则体系中的位置，再引入权利维度的平衡。【逐步演示】AI 挑战的不是某一条规则，而是核心概念的可适用性，因而需要解释性判断。【易错提醒】不要只谈技术，应回到法理学框架。", "keywords": [["哈特视角", "作者定义是初级规则的核心概念"], ["次级规则功能", "登记许可救济使权利可操作"], ["德沃金视角", "作者人格权体现个体尊严"], ["读者权利", "获取知识亦具原则分量"], ["解释性判断", "概念适用须结合实践整体"]]}]}, "S3M5K5": {"lesson": "S3M5K5", "questions": [{"order": 1, "qtype": "single", "stem": "根据 Wacks，1948年《世界人权宣言》对自身条款的定位是：", "options": ["A 可直接推翻国内法的高级法", "B 共同的成就标准", "C 具有强制力的国际条约", "D 纯粹的道德劝诫"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】Wacks 指出宣言把自身表述为『共同的成就标准』，法文文本作『有待实现的共同理想』。【逐步演示】这种定位承认超越实定法的尺度，又避免直接推翻国内制定法。【易错提醒】它既不是宪法性高级法，也不是毫无法律意义的宣示。"}, {"order": 2, "qtype": "multi", "stem": "国际人权法的主要渊源包括：", "options": ["A 国际条约", "B 习惯国际法", "C 国际组织实践与司法判例", "D 单一国家的国内刑法"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】国际人权法由条约、习惯、国际组织实践与判例等构成。【逐步演示】D 属于国内法，与国际人权法渊源不同。【易错提醒】不要把国内宪法的基本权利条款与国际人权法渊源混为一谈。"}, {"order": 3, "qtype": "single", "stem": "《公民权利和政治权利国际公约》与《经济、社会及文化权利国际公约》的通过时间与生效时间是：", "options": ["A 1948年通过并生效", "B 1966年通过，1976年生效", "C 1998年通过，2002年生效", "D 1989年通过并生效"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】两公约于1966年通过，1976年生效。【逐步演示】C 对应《国际刑事法院罗马规约》的时间。【易错提醒】注意区分宣言、公约与规约的不同时间点。"}, {"order": 4, "qtype": "judge", "stem": "《世界人权宣言》作为联合国大会通过的宣言，其本身即是可直接推翻国内制定法的宪法性高级法。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】Wacks 明确把它理解为衡量实定法的尺度，而非宪法意义上可推翻普通法的高级法。【逐步演示】其表述是『共同的成就标准』。【易错提醒】这并不否定其巨大的规范影响力，只是对其法律性质的准确定位。"}, {"order": 5, "qtype": "blank", "stem": "国际法院在 Barcelona Traction 案中提出，某些义务是面向国际社会整体承担的，称为______义务。", "options": [], "answer": "", "accepted": ["对一切", "对一切义务", "erga omnes", "对世", "对世义务"], "keywords": [], "explanation": "【答案】对一切义务（obligations erga omnes）。【解题思路】国际法院1970年在该案中区分了双边义务与对一切义务。【逐步演示】其例子包括禁止侵略、灭绝种族、奴隶制与种族歧视。【易错提醒】该判决并未最终认定具体国家责任，只作出一般性的法律区分。"}, {"order": 6, "qtype": "single", "stem": "国际法院在 Barcelona Traction 案（1970）中的核心贡献是：", "options": ["A 确认某些义务关涉国际社会整体利益", "B 判决某国承担灭绝种族责任", "C 废止外交保护制度", "D 建立个人在国际法院的出庭权"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】该案提出对一切义务的概念，突破了义务仅存在于特定国家之间的框架。【逐步演示】B、C、D 均非本案内容。【易错提醒】本案是一般性法律判断，不等于具体追责。"}, {"order": 7, "qtype": "judge", "stem": "人权义务传统上只是消极的尊重义务，从不包含要求国家采取积极措施的内容。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节指出，人权义务已从消极尊重扩展为保护与实现的义务。【逐步演示】这要求国家防止第三方侵害并积极提供制度与资源。【易错提醒】积极义务涉及资源能力问题，其履行通常具有渐进性。"}, {"order": 8, "qtype": "single", "stem": "在普遍主义与文化相对主义的争论中，较为温和的立场是：", "options": ["A 彻底否定普遍人权", "B 在核心底线上坚持普遍标准，在实现路径上允许文化差异", "C 一切价值均由文化决定", "D 只承认公民政治权利"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】本节称这一立场为『最低限度普遍主义』。【逐步演示】它既避免为严重侵害提供文化辩解，也承认实现方式的多样性。【易错提醒】该立场仍需回答谁来界定『底线』的问题。"}, {"order": 9, "qtype": "essay", "stem": "试比较普遍主义与文化相对主义在人权问题上的主张，并评估最低限度普遍主义的可行性。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先呈现两种立场的理由，再评估折中方案。【逐步演示】最低限度普遍主义兼顾底线与多样性，但界定底线的程序仍可能存在权力偏向。【易错提醒】不要简单判定某一方完全正确，应呈现双方关切。", "keywords": [["普遍主义", "核心标准跨文化有效"], ["相对主义", "人权嵌入具体文化传统"], ["双方理由", "防止辩解侵害与避免价值输出"], ["折中方案", "底线普遍与路径多元"], ["待解问题", "底线由谁界定"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于国际人权法的执行或监督机制？", "options": ["A 条约机构审议缔约国报告", "B 部分公约下的个人申诉程序", "C 国际刑事法院对个人追究刑事责任", "D 国际法院处理国家间争端"], "answer": "ABCD", "accepted": [], "keywords": [], "explanation": "【答案】ABCD。【解题思路】四项分别对应报告制度、个人申诉、刑事追责与国家间争端解决。【逐步演示】它们共同构成没有统一警察力量情况下的执行网络。【易错提醒】这些机制的强制力与管辖范围各不相同，不宜笼统等同。"}, {"order": 11, "qtype": "single", "stem": "纽伦堡审判对国际人权法的意义在于：", "options": ["A 确立了法律并非判定对错的唯一尺度", "B 废止了国内法体系", "C 创立了联合国", "D 通过了对一切义务原则"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】Wacks 指出，纽伦堡审判确认某些行为构成反人类罪，即便它们未违反具体实证法条文。【逐步演示】这为后来的人权法与国际刑法提供了重要观念基础。【易错提醒】D 对应国际法院1970年的判决，而非纽伦堡审判。"}, {"order": 12, "qtype": "judge", "stem": "经济、社会与文化权利只是道德愿望，其重要性低于公民与政治权利。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节指出，两类权利被分置于不同公约是历史产物，主流意见现已转向承认二者相互依存。【逐步演示】缺乏基本生存条件，自由与参与也难以真正实现。【易错提醒】两类权利的义务结构与实现方式不同，但不存在价值上的高低序列。"}, {"order": 13, "qtype": "essay", "stem": "分别用自然法、法律实证主义与德沃金的权利理论，说明国际人权法正当性基础的不同论证路径。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】分别重构三种论证及其软肋。【逐步演示】自然法回答为何正当，实证主义回答何时有效，德沃金回答权利为何优先于集体目标。【易错提醒】不要把三者写成互相排斥的结论，它们回答的是不同层面问题。", "keywords": [["自然法路径", "尊严与普遍道德"], ["实证主义路径", "条约习惯与国家同意"], ["德沃金路径", "权利作为王牌与平等"], ["各自限度", "具体化困难、道德号召不足、共同体前提"], ["综合理解", "回答效力与正当性的不同层面"]]}]}, "S3M5K6": {"lesson": "S3M5K6", "questions": [{"order": 1, "qtype": "single", "stem": "『全球治理』相对于『世界政府』的关键特征是：", "options": ["A 存在一个统一的世界立法机关", "B 国家、国际组织与私人主体共同参与，机制松散", "C 完全排除国家的作用", "D 只处理经济贸易问题"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】全球治理指多元主体共同参与跨国规则制定，远非统一的世界政府。【逐步演示】它覆盖人权、环境、网络等多领域，而非仅限经贸。【易错提醒】全球治理并不否定国家，国家仍是最主要的主体之一。"}, {"order": 2, "qtype": "single", "stem": "世界贸易组织成立的时间及其协定通过的时间分别是：", "options": ["A 1945年与1948年", "B 1995年与1994年", "C 2002年与1998年", "D 2016年与2018年"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】WTO 协定于1994年达成，世界贸易组织于1995年成立。【逐步演示】A 对应联合国与《世界人权宣言》，C 对应国际刑事法院。【易错提醒】注意区分『协定达成』与『组织成立』。"}, {"order": 3, "qtype": "multi", "stem": "全球化给传统法律秩序带来的挑战包括：", "options": ["A 法律规则与领土边界不再简单重合", "B 多个法域对同一行为主张管辖", "C 全球规则的民主正当性受到质疑", "D 各国法律从此完全相同"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】空间重构、管辖重叠与正当性问题构成全球化三大挑战。【逐步演示】D 与法律多元主义的观察相反，趋同与分歧并存。【易错提醒】全球化不意味着法律统一化，更不意味着民族国家消亡。"}, {"order": 4, "qtype": "judge", "stem": "全球治理意味着一个拥有统一立法、司法与警察权力的世界政府已经形成。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节明确指出全球治理比世界政府松散得多，不存在统一的强制执行机关。【逐步演示】国际法仍以国家同意为主要基础。【易错提醒】把全球治理等同于世界政府，是对该概念最常见的误解。"}, {"order": 5, "qtype": "blank", "stem": "一国法律主张适用于其领土之外的人或事，这种现象称为______。", "options": [], "answer": "", "accepted": ["域外管辖", "域外适用", "extraterritoriality", "域外效力"], "keywords": [], "explanation": "【答案】域外管辖（extraterritoriality）。【解题思路】GDPR 对境外处理者主张适用即属典型。【逐步演示】它引发与他国主权及管辖规则的冲突。【易错提醒】域外管辖不同于国际法上的普遍管辖，二者依据与范围不同。"}, {"order": 6, "qtype": "single", "stem": "欧洲法院在 Schrems II 案（2020）中的结论是：", "options": ["A 全面禁止个人数据跨境传输", "B 维持标准合同条款的有效性但要求逐案评估，并宣告隐私盾决定无效", "C 认定美国监控法符合欧盟保护标准", "D 否定欧盟法院对跨境传输的管辖权"], "answer": "B", "accepted": [], "keywords": [], "explanation": "【答案】B。【解题思路】判决维持标准合同条款，要求考虑目的国法律与实践，并宣告隐私盾充分性决定无效。【逐步演示】它显示多套法律秩序在同一事实上同时主张适用。【易错提醒】判决并未全面禁止跨境传输。"}, {"order": 7, "qtype": "judge", "stem": "Schrems II 案宣告欧盟—美国隐私盾无效，因此所有跨大西洋数据流动都立即停止。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】判决宣告的是委员会的充分性决定无效，同时维持标准合同条款作为传输工具。【逐步演示】它要求逐案评估保护措施是否充分。【易错提醒】『充分性决定无效』与『传输全面禁止』不是一回事。"}, {"order": 8, "qtype": "single", "stem": "法律多元主义的核心主张是：", "options": ["A 同一场域中多种规范体系并存并相互作用", "B 所有法律终将统一", "C 只有国家法才是法律", "D 国际法优先于一切国内法"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】法律多元主义描述多种法律或规范体系在同一场域并存、互动的状态。【逐步演示】它尤其适用于国际法与国内法的交界处。【易错提醒】它不预设某一体系必然优先，而是描述并存事实。"}, {"order": 9, "qtype": "essay", "stem": "试述域外管辖的正当性争论，并说明它可能如何引发法律秩序之间的冲突。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】先给出双方理由，再说明冲突的表现与协调方式。【逐步演示】GDPR 的域外适用与 Schrems II 案说明，冲突常以保护基本权利的形式出现。【易错提醒】不要简单把域外管辖等同于霸权，也不可忽视其主权成本。", "keywords": [["支持理由", "防止基本权利保护落空"], ["反对理由", "侵犯他国主权并造成管辖冲突"], ["冲突形态", "多套规则同时主张适用"], ["协调手段", "冲突法、条约、相互承认"], ["深层问题", "规则背后的权力分配"]]}, {"order": 10, "qtype": "multi", "stem": "下列哪些属于全球化条件下协调规范冲突的机制？", "options": ["A 冲突法规则", "B 国际条约与组织", "C 软法与标准", "D 完全依靠单边武力"], "answer": "ABC", "accepted": [], "keywords": [], "explanation": "【答案】ABC。【解题思路】冲突法、条约组织与软法构成技术性与制度性的协调工具。【逐步演示】它们各自提供不同强度的规范确定性。【易错提醒】单边武力不属于法律协调机制，且与法治原则相冲突。"}, {"order": 11, "qtype": "single", "stem": "全球治理中的『民主赤字』主要指：", "options": ["A 全球规则制定者缺乏直接民主授权，受影响者参与渠道有限", "B 各国都有过多选举", "C 国际组织经费不足", "D 全球规则完全由法院制定"], "answer": "A", "accepted": [], "keywords": [], "explanation": "【答案】A。【解题思路】民主赤字指全球规则的制定与执行缺少直接民主授权和参与机制。【逐步演示】国家同意与专家专业性常被用来补足正当性，但二者都有局限。【易错提醒】这不是说全球治理毫无正当性，而是指出其正当性来源薄弱。"}, {"order": 12, "qtype": "judge", "stem": "在全球化条件下，哈特的承认规则在全球层面已经统一，不存在体系之间的有效性判准分歧。", "options": [], "answer": "错", "accepted": [], "keywords": [], "explanation": "【答案】错。【解题思路】本节指出，跨国场景中承认规则呈现分散状态，不同体系各有有效性判准，且缺乏终极仲裁者。【逐步演示】这正是全球法律秩序与国内法律秩序的重要差别。【易错提醒】不要把国内法的成功经验直接外推到全球层面。"}, {"order": 13, "qtype": "essay", "stem": "结合富勒的内在道德与德沃金的整体性，分析全球层面法治面临的特殊困难。", "options": [], "answer": "", "accepted": [], "explanation": "【答案要点】见 keywords 五组。【解题思路】分别以两位理论家的标准检验全球层面。【逐步演示】富勒的形式要求在全球软法中部分可实现，但一致性缺乏检验主体；德沃金的整体性依赖共同体历史，跨国适用受限。【易错提醒】结论不宜是『全球法治不可能』，而应呈现具体困难。", "keywords": [["富勒视角", "公开性一般性较易、官方行为一致性难检验"], ["德沃金视角", "整体性以稳定共同体为前提"], ["执行缺口", "缺少统一机关与问责渠道"], ["多元现实", "多体系并存难归单一解释"], ["可能方向", "承认多元的法治标准"]]}]}}, "cases": {"C1": {"title": "马伯里诉麦迪逊（Marbury v. Madison）", "court": "美国最高法院（Supreme Court of the United States）", "year": "1803", "theme": "司法审查（Judicial Review）", "sections": [{"title": "一、案件背景", "body": "1800 年美国总统大选中，联邦党（Federalist）领袖约翰·亚当斯（John Adams）败给民主共和党（Democratic-Republican）的托马斯·杰斐逊（Thomas Jefferson）。在政权交接前的“跛脚鸭”时期，联邦党人试图抢先安插本党人士进入司法系统：1801 年，亚当斯任命威廉·马伯里（William Marbury）等人担任哥伦比亚特区治安法官（justice of the peace），委任状（commission）经总统签署并加盖国玺，本应由国务卿送达，但因交接仓促，部分委任状未能发出。杰斐逊就任后，明确指示新任国务卿詹姆斯·麦迪逊（James Madison）扣押未送达的委任状。马伯里因此向最高法院提起诉讼，请求法院颁发执行令（writ of mandamus，又译“训令”），命令麦迪逊交付委任状。\n\n此案发生在美国建国初期，最高法院地位尚未稳固，联邦党与民主共和党之间的党争相当激烈。马伯里的律师查尔斯·李（Charles Lee，前联邦总检察长）选择在最高法院直接起诉，依据的是国会 1789 年《司法法》（Judiciary Act of 1789）第 13 条——该条授权最高法院对此类案件享有初审管辖权（original jurisdiction）。这一诉讼策略表面上是为当事人争取权利，实则把最高法院推入与行政部门正面冲突的境地。"}, {"title": "二、当事人", "body": "- 原告：威廉·马伯里（William Marbury），商人，被任命为治安法官但未取得委任状。\n- 被告：詹姆斯·麦迪逊（James Madison），时任美国国务卿，奉杰斐逊总统之命扣押委任状。\n- 主审法官：首席大法官约翰·马歇尔（John Marshall）主笔判决意见，大法官佩特森（Paterson）、蔡斯（Chase）、华盛顿（Washington）附议；大法官库欣（Cushing）、穆尔（Moore）未参与审理。值得注意的是，马歇尔本人正是亚当斯任命的国务卿，在“午夜任命”中签署过包括马伯里在内的委任状，由他主审此案，利益冲突问题在后世引起不少讨论。"}, {"title": "三、核心争议", "body": "案件表面争议是：马伯里是否有权取得委任状，最高法院应否颁发执行令。但马歇尔把问题重组为三个层次：（1）马伯里的权利是否受到侵害？（2）若权利受侵害，法律是否提供救济？（3）最高法院是否有权颁令救济——换言之，国会《司法法》第 13 条授予的初审管辖权，是否越过了宪法划定的界限？\n\n其中第三个问题才是案件的真正枢纽：当国会制定法与联邦宪法发生冲突时，法院应当适用哪一个？这直接关系到成文宪法（written constitution）究竟是“最高法”，还是可以被普通立法修改的普通法律。"}, {"title": "四、适用法律", "body": "- 美国宪法第三条第二款：最高法院对“一切有关大使、其他使节、领事以及以一州为当事人的案件”享有初审管辖权，对其他案件享有上诉管辖权（appellate jurisdiction）。\n- 宪法第六条“最高条款”（Supremacy Clause）：宪法及依宪法制定的法律为“国家的最高法律”，法官受其约束。\n- 1789 年《司法法》第 13 条：授权最高法院向政府官员颁发执行令。\n- 此外，马歇尔还诉诸“权力分立”与法官的宪法宣誓义务作为论证资源。"}, {"title": "五、裁判结果", "body": "最高法院一致裁定：马伯里有权取得委任状，政府扣押行为构成权利侵害，且法律应当提供救济；但最高法院最终拒绝颁发执行令，理由是《司法法》第 13 条试图扩张宪法明文列举的初审管辖权，属于违宪立法，因而是无效的（void）。马伯里的诉求在程序上被驳回，他最终没有拿到委任状。然而，法院借此首次宣告：国会制定法若与宪法抵触，法院有权也有义务拒绝适用——司法审查（违宪审查）原则由此确立。"}, {"title": "六、判决理由", "body": "马歇尔的论证分三步推进。\n\n第一步，确认权利与救济。马伯里已获总统任命、委任状经签署并盖印，依法律其“任命”已完成，交付只是程序性手续；麦迪逊的扣押构成对既得权利的侵害。马歇尔写道（大意）：政府的首要职责之一是向受侵害者提供法律保护；一个自称“法治政府而非人治政府”的政权，若对法定权利的侵害不提供救济，就不配这个称号。\n\n第二步，管辖权与违宪审查。马歇尔先引宪法第三条第二款，指出最高法院的初审管辖权以列举事项为限，马伯里案不在其中，依宪法最高法院无初审权。马伯里的律师之所以直接向最高法院起诉，靠的是《司法法》第 13 条。于是问题变成：国会能否通过普通法律扩张宪法授予的管辖权？\n\n马歇尔的推理（大意）是：人民为建立政府而制定宪法，为各政府部门分配权力并划定界限；若这些界限可以被被约束者随意突破，宪法便失去意义。宪法是“至高无上的、不能以普通方式改变的根本法”，与宪法相抵触的立法不是法律。那么，当一部违宪的法律与宪法同时适用于某个案件，法院必须决定适用哪一个——“宣示法律是什么，正是司法部门的职责所在”（大意）。他进一步指出，宪法第六条最高条款只承认“依宪法制定”的法律才是最高法律；法官的宣誓义务要求他们支持宪法，若执行违宪法律，即为违背誓言。\n\n第三步，政治智慧。法院一方面裁定《司法法》违宪，展示司法权对立法权的制约；另一方面以“无权管辖”为由拒发执行令，避免与杰斐逊政府正面较量——若下令交付委任状而行政部门拒不执行，最高法院的权威反而受损。这一“以退为进”的策略，使司法审查原则在几乎不流血的情况下得以确立。"}, {"title": "七、学术评价", "body": "马伯里案被誉为“世界宪政第一案”，在法理学与宪法学上的地位极高。\n\n其一，它确立了司法审查（Judicial Review）制度。美国宪法文本并未明文授权法院审查立法合宪性，这一权力是法院通过判决“自我证成”的。马歇尔的论证逻辑——成文宪法高于普通法律、法院职责在于“说法律是什么”、最高条款与法官宣誓——成为后世违宪审查的经典范式。这一模式后来被许多国家在不同程度上借鉴，也影响了德国等国的宪法法院制度（但各国制度安排差异很大，不可混为一谈）。\n\n其二，它提出了关于“反多数难题”（counter-majoritarian difficulty）的持久争论。由非民选的法官推翻民选立法机关的法律，民主正当性从何而来？批评者（包括杰斐逊本人以及后来的一些法律现实主义者和批判法学者）认为这是司法部门篡夺民主权力；辩护者则回应：宪法本身是人民更高层次的意志，法院维护宪法恰是维护人民的长远意志，且司法审查是对“多数暴政”的防范。这一争论至今未息。\n\n其三，从法律实证主义（Legal Positivism）与自然法（Natural Law）之争的角度看，马歇尔的论证带有明显的自然法色彩：他预设存在一种高于普通制定法的“根本法”，其正当性来自人民制宪权，而非仅仅来自“被制定”这一事实。这与哈特（H. L. A. Hart）后来强调的“承认规则”（Rule of Recognition）形成有趣对照——在哈特框架中，司法审查的正当性最终取决于法律共同体对宪法作为最高法律渊源的接受，而非某个道德命题。Wacks 也指出，司法审查的确立使“效力”（validity）与“正当性”（legitimacy）的关系成为宪政理论的核心问题。\n\n其四，方法论上，本案展示了“司法克制”与“司法能动”之间的微妙平衡：马歇尔在实体权利问题上支持马伯里，却在救济问题上主动退让，这种策略常被后世法官引用为审慎行使权力的范例。"}, {"title": "八、现实意义", "body": "马伯里案的影响远超一个治安法官的委任状纠纷。\n\n首先，它奠定了美国“三权分立与制衡”（separation of powers / checks and balances）的实际运作机制。没有司法审查，宪法对立法、行政的明文限制就可能沦为一纸空文；有了它，法院成为宪法秩序的守护者。此后，最高法院在 1954 年布朗案中推翻种族隔离、在 1973 年罗伊案中处理堕胎问题等，都延续了这一权力逻辑（这些具体判决的后续存废属于另一问题，需另行考察）。\n\n其次，它为“权力受到法律约束”的法治（Rule of Law）理想提供了制度支点：不仅公民要守法，政府权力本身也必须来源于宪法和法律的授权，越权行为可被法院宣告无效。这与英国普通法传统中“行政机关权力必须有法律依据”的原则（参见案例研究中的恩蒂克诉卡灵顿案）遥相呼应，但两者的制度载体不同：美国有成文宪法与违宪审查，英国则依靠议会主权与普通法的渐进演进。\n\n再次，它也提醒我们司法审查自身的张力：法院在行使这一权力时，如何既维护宪法又不越界变成“司法至上”？这是当代各国宪政讨论中持续存在的问题。\n\n对学习者而言，马伯里案的价值在于：它把“法律是什么”“宪法为何高于普通法律”“法院能否以及应否审查立法”这些抽象问题，浓缩进一个关于委任状的具体故事，是理解成文宪法、权力分立与司法审查不可绕过的起点。"}]}, "C2": {"title": "布朗诉教育委员会（Brown v. Board of Education of Topeka）", "court": "美国最高法院（Supreme Court of the United States）", "year": "1954", "theme": "平等保护（Equal Protection）", "sections": [{"title": "一、案件背景", "body": "19 世纪末，美国最高法院在“普莱西诉弗格森案”（Plessy v. Ferguson, 1896）中确立了“隔离但平等”（separate but equal）原则，允许各州以种族为由在公共设施中实行隔离，只要为黑人提供的设施“平等”即可。这一判决为南方各州的种族隔离制度（吉姆·克劳法，Jim Crow laws）提供了宪法背书。到 20 世纪中期，公立学校的种族隔离已成为美国种族不平等的核心象征。\n\n20 世纪 30 年代起，全国有色人种协进会（NAACP）在霍华德大学法学院查尔斯·汉密尔顿·休斯顿（Charles Hamilton Houston）等人带领下，策划了一系列挑战教育隔离的诉讼，采取“逐步推进”策略：先争取研究生院、专业性学院中的平等权利，再进攻中小学。1950 年代初，来自堪萨斯、南卡罗来纳、弗吉尼亚、特拉华和哥伦比亚特区的五个案件被合并，以“布朗诉教育委员会”之名上诉至最高法院。"}, {"title": "二、当事人", "body": "- 上诉人（原告）：奥利弗·布朗（Oliver Brown）等人。奥利弗·布朗是堪萨斯州托皮卡市的黑人牧师，其 8 岁的女儿琳达·布朗（Linda Brown）因种族原因被拒绝进入附近的白人小学，只能到较远的黑人学校就读。其余合并案件分别涉及南卡罗来纳州的布里格斯诉埃利奥特案（Briggs v. Elliott）、弗吉尼亚州的戴维斯诉爱德华王子县教育委员会案（Davis v. County School Board of Prince Edward County）、特拉华州的贝尔顿诉杰布哈特案与布拉诉杰布哈特案（Belton v. Gebhart & Bulah v. Gebhart），以及哥伦比亚特区的博林诉夏普案（Bolling v. Sharpe）。\n- 被上诉人（被告）：堪萨斯州托皮卡市教育委员会等地方教育当局。\n- 代理律师：NAACP 的瑟古德·马歇尔（Thurgood Marshall，后成为美国首位黑人最高法院大法官）担任首席律师，罗伯特·卡特（Robert L. Carter）、杰克·格林伯格（Jack Greenberg）等参与。\n- 主审法官：首席大法官厄尔·沃伦（Earl Warren）。沃伦在审理期间成功促成九位大法官达成一致意见，这在最高法院历史上颇为难得。"}, {"title": "三、核心争议", "body": "本案的核心问题是：各州法律要求或允许公立学校按种族隔离，是否违反美国宪法第十四修正案的平等保护条款（Equal Protection Clause）？具体拆开又有三层：（1）第十四修正案的制宪原意是否包含禁止学校隔离？（2）判断隔离是否违宪时，应考察 1868 年修正案通过时的历史条件，还是应考虑现代教育在社会生活中的地位？（3）如果黑、白学校的校舍、师资等“有形”因素（tangible factors）已经或趋于平等，隔离本身是否仍构成对平等保护的违反？\n\n被告方主张，普莱西案先例仍然有效，只要设施平等，隔离即为合法；原告方则主张，隔离本身即是对黑人儿童的歧视与伤害，与“平等”背道而驰。"}, {"title": "四、适用法律", "body": "- 美国宪法第十四修正案第一款（1868 年通过）平等保护条款：“任何州……不得否认任何人享有平等的法律保护”（大意）。\n- 第五修正案正当程序条款（Due Process Clause）：适用于哥伦比亚特区的博林诉夏普案。因第十四修正案仅约束“州”，而特区属联邦管辖，沃伦法院以第五修正案的正当程序条款达到同样结论。\n- 普莱西诉弗格森案（1896）确立的“隔离但平等”原则——本案的主要攻击对象。\n- 原告方还提交了社会科学家（如肯尼斯·克拉克 Kenneth B. Clark 的“娃娃实验”）关于隔离对黑人儿童心理伤害的研究，作为事实层面的证据。"}, {"title": "五、裁判结果", "body": "1954 年 5 月 17 日，最高法院以 9 票对 0 票作出一致判决：公立学校中的种族隔离违反第十四修正案的平等保护条款，因而是违宪的；“隔离教育设施本质上就是不平等的”（separate educational facilities are inherently unequal，通行译法），“隔离但平等”原则在公共教育领域“没有容身之地”（has no place）。法院同时宣布，普莱西案在涉及公共教育的范围内被推翻。\n\n由于判决书只宣布原则而未给出具体执行方案，最高法院于 1955 年 5 月 31 日作出“布朗第二案”（Brown II）判决，指示各州“以一切审慎的速度”（with all deliberate speed）制定废除隔离的计划。这一措辞因过于模糊，在后世引发了大量拖延与抵抗。"}, {"title": "六、判决理由", "body": "沃伦法院的判决意见出人意料地简短，但论证结构清晰。\n\n第一，法院把问题从“有形的平等”转向“隔离本身的影响”。沃伦写道（大意）：本案不能仅比较校舍、课程、教师资格等有形因素，必须考察隔离本身对儿童地位的影响。原告方提交的社会科学证据——尤其是克拉克夫妇的“娃娃实验”显示，黑人儿童在白色娃娃与棕色娃娃之间，倾向于认为白色娃娃“好”、棕色娃娃“坏”，并常把自己的肤色与“坏”联系起来——说明隔离制度已经内化为黑人儿童的自我否定。法院据此认定：把黑人儿童仅因种族与其他年龄、资格相仿的儿童隔离开来，会让他们在社区中的地位产生低人一等之感，从而对其心灵与思想造成无法弥补的伤害。\n\n第二，法院拒绝以 1868 年的历史原意作为判决的唯一依据。判决书承认，第十四修正案的制宪者对公共教育问题的态度“并不明确”（inconclusive），因此法院不能、也不应被冻结在 19 世纪的条件里，而必须“根据公共教育的充分发展及其在今天美国生活中的地位”来判断（大意）。这是一种典型的“活的宪法”（living constitution）思路——宪法原则的适用要随社会条件演变。\n\n第三，法院从正面重申教育权的重要性。沃伦写道（大意）：教育显然是州与地方最重要、最根本的职能之一；既然州已经承担起提供公共教育的责任，这种机会就必须以平等的条件向所有人开放。既然隔离本质不平等，黑人儿童被剥夺的正是这种平等的教育机会。\n\n第四，法院以克制的方式处理先例。在公共教育领域，普莱西案确立的“隔离但平等”原则不再适用。沃伦法院没有全面否定普莱西案在其他领域的历史，而是谨慎地把推翻限定在“公共教育”范围内——这种克制使九位大法官得以形成一致意见。"}, {"title": "七、学术评价", "body": "布朗案被广泛认为是美国最高法院历史上最重要的判决之一，其法理学意义可从以下几个层面理解。\n\n其一，它重新定义了“平等”的含义。在布朗案之前，形式意义上的平等——即“隔离但平等”——长期被当作宪法所允许的状态；布朗案把平等理解提升到实体层面：判断一种制度是否违反平等保护，不仅要看表面上是否提供了相似的资源，更要看这种制度安排本身是否制造并固化了等级与羞辱。这种从“形式平等”到“实质平等”的转向，是现代宪法平等理论的核心成果，也对后世的反歧视法（包括间接歧视、结构性歧视理论）产生了深远影响。\n\n其二，它是“活宪法论”与“原意主义”（originalism）之争的经典战场。沃伦法院明确表示不能停留在 1868 年的历史条件中，这与后来以斯卡利亚（Antonin Scalia）为代表的原意主义形成尖锐对立。原意主义者批评法院“凭社会科学的时尚而非宪法文本”作判决，指责司法能动主义（judicial activism）；支持者则回应：若固守制宪者对教育的有限认识，宪法就不足以应对现代社会的现实。这场争论至今仍是美国宪法解释理论的主线之一。\n\n其三，它凸显了司法审查的“反多数难题”（参见马伯里案）：九位非民选的法官推翻了多个州经民主程序制定的法律，其正当性何来？布朗案的回答是：平等保护条款本身就是人民通过宪法表达的更高层次的承诺，法院不过是兑现这一承诺；而且，被隔离的黑人儿童作为政治过程中的弱势少数，很难通过多数决策保护自己，这恰恰是司法审查存在的理由。这一论证后来成为“强化代表”（representation-reinforcing）理论的重要支点。\n\n其四，从法律现实主义（Legal Realism）的视角看，布朗案也是“行动中的法”压倒“书本上的法”的范例：法院明显受到了民权运动、社会科学的进步以及冷战时期美国国际形象压力等现实因素的影响。Wacks 指出，判决的社会后果与现实语境，往往是理解司法决定的关键变量。\n\n其五，判决的“执行难题”同样具有学术价值。Brown II 的“以一切审慎的速度”因模糊而饱受批评，1957 年阿肯色州小石城事件甚至需要艾森豪威尔总统派联邦军队介入。它说明：宣布权利是一回事，实现权利是另一回事；法律的社会效果受制于政治阻力、资源分配与地方执行力。"}, {"title": "八、现实意义", "body": "布朗案的直接影响是结束了公立学校种族隔离的宪法合法性，成为美国民权运动（Civil Rights Movement）的催化剂。此后，最高法院与国会通过一系列判决与立法（如 1964 年《民权法案》Civil Rights Act、1965 年《投票权法案》Voting Rights Act）把平等原则扩展到公共交通、就业、投票等领域。瑟古德·马歇尔本人于 1967 年被任命为最高法院大法官，象征着这一斗争的历史成果。\n\n在比较法层面，布朗案对世界各地的反歧视与平等权保护产生了广泛影响：它常被引用为“通过司法推动社会变革”的范例，也促使各国思考如何在宪法层面处理结构性不平等问题。但必须注意，美国以违宪审查推动平等的路径，与欧洲通过《欧洲人权公约》（European Convention on Human Rights）及其法院——例如“达奇森诉英国案”中对少数群体权利的保护——走的是不同的制度道路，不能混为一谈。\n\n同时，布朗案也留下了未竟的课题。判决书宣布的“隔离本质上不平等”针对的是法律上的隔离（de jure segregation），而现实中因居住隔离、学区划分、经济差距形成的“事实上的隔离”（de facto segregation）至今仍是美国教育公平的核心难题。2019 年美国政府问责局（GAO）的研究仍显示，美国学校的种族与经济隔离并未消除。\n\n对学习者而言，布朗案展示了法律、政治与社会变迁的复杂互动：一个看似技术性的宪法解释问题——第十四修正案的“平等保护”意味着什么——如何成为改变一个国家制度面貌的力量。它是理解平等权、司法能动主义以及“法与社会责任”关系的必读案例。"}]}, "C3": {"title": "多诺霍诉史蒂文森（Donoghue v Stevenson）", "court": "英国上议院（House of Lords）", "year": "1932", "theme": "侵权法与注意义务（Negligence & Duty of Care）", "sections": [{"title": "一、案件背景", "body": "本案是英国普通法（common law）侵权法史上最著名的判决之一，俗称“姜啤蜗牛案”。1928 年 8 月 26 日晚，梅·多诺霍（May Donoghue，诉讼时也以婚前姓 McAlister 出现，故本案又称 M'Alister v Stevenson）与一位朋友在苏格兰佩斯利（Paisley）的一家咖啡馆聚会。朋友为她买了一瓶姜汁啤酒（ginger beer）。多诺霍喝下约半瓶后，发现瓶中有一只已经腐烂的蜗牛——由于酒瓶不透明，她在饮用前无法看见瓶内情况。她因此患上肠胃炎并遭受精神惊吓。\n\n当时英国合同法有一条顽固的原则——合同相对性（privity of contract）：只有合同当事人才能依合同主张权利。多诺霍并没有购买那瓶啤酒（是朋友买的），因此她与咖啡馆老板、与啤酒制造商之间都不存在买卖合同；按照“货物出门概不负责”（caveat emptor）的旧观念，她似乎无从索赔。多诺霍于 1929 年向制造商大卫·史蒂文森（David Stevenson）提起诉讼，索赔 500 英镑。一审与上诉审均以“不存在合同关系”为由驳回。她最终上诉至英国上议院——当时英国的最高司法机关。"}, {"title": "二、当事人", "body": "- 上诉人（原告）：梅·多诺霍（May Donoghue / May McAlister），苏格兰消费者。\n- 被上诉人（被告）：大卫·史蒂文森（David Stevenson），佩斯利的姜汁啤酒制造商。\n- 审理法院：英国上议院，由五名大法官审理，1932 年 5 月 26 日以 3 票对 2 票作出判决。\n- 多数意见：阿特金勋爵（Lord Atkin）主笔，麦克米伦勋爵（Lord Macmillan）、坦克斯顿勋爵（Lord Thankerton）附议。\n- 少数（异议）意见：巴克马斯特勋爵（Lord Buckmaster）、汤姆林勋爵（Lord Tomlin）。"}, {"title": "三、核心争议", "body": "表面的争议是：啤酒制造商是否要对一个与他没有任何合同关系的最终消费者承担赔偿责任？更深层的争议是：在普通法传统中，过失侵权（negligence）的注意义务（duty of care）能否脱离合同关系而独立存在？如果能，其边界在哪里——换言之，“谁是我的邻居”，即谁有权主张我未尽合理注意？\n\n被告的核心抗辩是：他只与咖啡馆老板有合同关系，与多诺霍之间不存在合同，因而对她不负有任何义务；若任意扩大责任范围，制造商将对无法预见的无数人承担责任，诉讼将泛滥。原告则主张：制造商把产品投入市场，明知消费者无法检验密封瓶内的状况，就应当对产品安全负合理注意义务，这种义务来自法律而非合同。"}, {"title": "四、适用法律", "body": "- 英国普通法中的过失侵权（negligence）原理，特别是注意义务（duty of care）的成立条件。\n- 合同相对性原则（privity of contract）与“货物出门概不负责”（caveat emptor）——被告抗辩的主要依据，也是法院要突破的旧框架。\n- 判例法资源：阿特金勋爵援引了宗教与道德训诫作为类比（如“爱邻如己”的“邻人”观念），用以说明法律义务背后的道德基础；本案以前的“危险物”思路亦被论及。\n- 本案判决本身成为此后注意义务理论的“母法”，后经“卡帕罗工业公司诉迪克曼”（Caparo Industries plc v Dickman, 1990）等案进一步发展出三要素测试法。"}, {"title": "五、裁判结果", "body": "上议院以 3 票对 2 票判决原告胜诉：啤酒制造商对作为最终消费者的多诺霍负有注意义务，若因未按合理注意生产、装瓶而导致消费者患病，应承担侵权损害赔偿责任。多诺霍最终获得的赔偿数额并不大，且据记载双方后来达成和解，但本案确立的法律原则影响极为深远：它突破了合同相对性对侵权责任的束缚，宣告“制造商对其产品的最终消费者负有合理注意义务”。"}, {"title": "六、判决理由", "body": "阿特金勋爵的判词是本案的灵魂。\n\n第一，从“谁是我的邻居”出发提炼一般原则。阿特金写道（大意）：在法律上，谁是“我的邻居”？答案是：那些如此紧密、直接地受我的行为影响的人，以至于当我在思考该作为或不作为时，理应把他们纳入考虑范围。由此，他给出了著名的“邻人原则”（Neighbour Principle）：你必须采取合理的注意，避免那些你可以合理预见、很可能伤害到邻人的作为或不作为（大意）。\n\n第二，把邻人原则适用于制造商与消费者。阿特金指出（大意）：啤酒制造商把产品投入市场，产品到达最终消费者手中时，中间没有任何合理的检验机会——酒瓶不透明，消费者无法发现其中的蜗牛；制造商明知这一点，就应当预见到若装瓶过程缺乏合理注意，消费者将受到伤害。因此，制造商与消费者之间的关系完全符合“邻人”的定义，制造商负有注意义务。\n\n第三，回应“责任泛滥”的担忧。阿特金承认，注意义务不能无限扩张；但本案情形边界清晰：被告是生产者，产品经其装瓶密封后直接面向消费者，损害是身体伤害，且属于可合理预见的范围，因此不存在责任漫无边际的问题。麦克米伦勋爵则更强调：随着社会分工深化，消费者越来越依赖生产者，法律必须让侵权法跟上这种现实，不能固守合同相对性的旧壳。\n\n第四，异议意见的担忧同样值得注意。巴克马斯特勋爵与汤姆林勋爵认为（大意）：原告并非购买者，若允许她索赔，等于让制造商对不确定范围的公众承担抽象义务，这是把法律从“合同”推向“道德”，缺乏明确边界；产品责任应当由议会立法解决，而非法院造法。这一异议代表了法律实证主义（Legal Positivism）对司法造法的典型警惕——即担心法官以道德判断代替明确的法律规则。\n\n第五，判决方法上，本案是普通法“渐进造法”的范例：上议院没有宣布一条抽象的法典式规则，而是从具体案情中提炼出可推广的原则，再通过后续判例逐步划定其边界。这正是普通法区别于大陆法系（civil law）成文法传统的重要特征。"}, {"title": "七、学术评价", "body": "多诺霍案在法理学与侵权法上的地位，可用“现代过失侵权法的出生证明”来形容。\n\n其一，它确立了“邻人原则”，把注意义务从合同关系中解放出来。在此之前，英国侵权法长期被合同相对性遮蔽，消费者几乎没有独立的侵权法救济。阿特金的公式化表述——以“可合理预见性”作为注意义务的核心——为法官处理新型案件提供了可操作的起点。Wacks 等学者指出，这一原则把侵权法的重心从“保护既有权利”转向“防止可预见的损害”，完成了过失侵权理论的体系化。\n\n其二，它开启了产品责任（product liability）制度的普通法路径。制造商对最终消费者负有安全注意义务的原则，后来被英国《1987 年消费者保护法》（Consumer Protection Act 1987）以及各国产品责任立法以成文法形式吸收、细化。可以说，本案是现代消费者权益保护法在普通法世界的思想源头。\n\n其三，它引发了关于“司法造法”与“法律确定性”的持久讨论。异议大法官的担忧并非全无道理：如果注意义务仅凭“可预见性”判断，边界确实模糊。此后，英国上议院在“卡帕罗工业公司诉迪克曼案”（1990）中把注意义务的成立归纳为三要素：（1）损害是否可合理预见（reasonable foreseeability）；（2）当事人之间是否有足够近的关系（proximity）；（3）施加注意义务是否“公平、公正且合理”（fair, just and reasonable）。这一三要素测试正是为了给邻人原则套上更精致的缰绳，回应本案异议所提出的确定性难题。\n\n其四，从法哲学看，它触及了哈特（H. L. A. Hart）关注的“法律的开放性结构”（open texture of law）问题：当既有规则（合同相对性）无法覆盖新型社会关系（大规模生产下的消费伤害）时，法官如何在规则的“开放地带”作出理性且可被接受的判决？本案的回答是诉诸法律原则与社会目的，而非机械涵摄——这与法律现实主义（Legal Realism）关于“法官实际上如何判决”的洞见相吻合。\n\n其五，本案也体现了普通法与成文法两种传统的分工：法院通过判例确立一般原则，议会则通过立法（如消费者保护法）对具体领域作精细规定。两者互补，对立之说并不成立。"}, {"title": "八、现实意义", "body": "多诺霍案的影响早已超出一瓶姜汁啤酒。\n\n首先，它是当代产品责任法的基石。今天，消费者因产品缺陷受到人身伤害时，可以直接依据侵权法或消费者保护法向制造商索赔，无需证明合同关系——这一规则的思想源头正是本案。从食品安全到药品责任，从汽车安全到电子产品，制造商的“合理注意义务”观念无处不在。\n\n其次，“邻人原则”已经渗透到过失侵权法的各个分支：医师对患者、律师对客户、驾车人对路人、物业管理者对访客——判断注意义务是否存在时，仍然经常回到“是否可合理预见”“关系是否足够密切”这些源自本案的问题。\n\n再次，本案对比较法研究具有重要价值。它展示了普通法系如何通过单个判例实现法律制度的重大转向，与大陆法系通过民法典或特别法确立产品责任的路径形成鲜明对照——这正体现了比较法学者（如 Siems）所强调的“不同法律风格”（legal style）的差异。\n\n最后，本案也提醒人们注意法律与道德的关系：阿特金勋爵借用了宗教式的“爱邻人”语言，但判决的落脚点仍是世俗的、可操作的标准——“合理预见”。这种“以道德为灵感、以法律为准绳”的写法，正是普通法判决说理的典型风格。\n\n对学习者来说，多诺霍案是理解普通法方法论（从个案到原则、以类比与区分推进）、侵权法结构（注意义务—违反—因果关系—损害）以及“司法如何在旧框架中创制新规则”的最佳入口之一。"}]}, "C4": {"title": "恩蒂克诉卡灵顿（Entick v Carrington）", "court": "英国王座法院（Court of King's Bench）", "year": "1765", "theme": "国家权力与个人自由（State Power and Individual Liberty）", "sections": [{"title": "一、案件背景", "body": "18 世纪中叶的英国，政府与激进报刊之间的冲突相当尖锐。约翰·威尔克斯（John Wilkes）等人创办的《监察者报》（The Monitor, or British Freeholder）等刊物不断抨击政府，被当局认定为“煽动性诽谤”（seditious libel）。当时的行政机关常用一种“一般令状”（general warrant，又称“搜查与扣押令状”）授权治安官或信使随意搜查可疑人员的住所、扣押其文件，令状上往往不写明具体罪名、具体物品与具体对象。\n\n1762 年 11 月 11 日，国王首席信使内森·卡灵顿（Nathan Carrington）与另外三名国王信使（James Watson、Thomas Ardran、Robert Blackmore），持北方事务大臣（Secretary of State for the Northern Department）哈利法克斯勋爵（Lord Halifax）签发的令状，“持械强行”闯入住在斯蒂普尼圣邓斯坦教区的作家约翰·恩蒂克（John Entick）家中。他们破门撬锁、翻查所有房间，历时约四小时，带走约 100 张图表和 100 本小册子，造成约 2000 英镑损失。令状要求搜查《监察者报》一文的“作者或参与者”。恩蒂克是威尔克斯的友人、一位靠笔谋生的“格拉布街作家”（Grub Street writer）。他以非法侵入（trespass）为由起诉四名信使，案件于 1765 年 11 月 2 日在威斯敏斯特厅审理，由民事诉讼法院首席大法官坎登勋爵（Lord Camden）主审，判决收入王座法院判例集（[1765] EWHC KB J98; 19 Howell's State Trials 1029）。"}, {"title": "二、当事人", "body": "- 原告：约翰·恩蒂克（John Entick，约 1703—1773），作家，住所遭搜查、文件被扣押。\n- 被告：内森·卡灵顿（Nathan Carrington）等四名国王信使。他们辩称自己是奉哈利法克斯勋爵的令状行事，具有合法授权，不构成侵权。\n- 实际授权者：哈利法克斯勋爵（Lord Halifax），时任北方事务大臣，其签发的一般令状是本案审查的对象；他本人并未被列为被告。\n- 主审法官：坎登勋爵（Lord Camden），时任民事诉讼法院首席大法官。他在本案中给出了英国宪法史上最著名的判词之一。"}, {"title": "三、核心争议", "body": "案件的直接争议是：四名被告闯入恩蒂克家、扣押其财物，是否构成非法侵入（trespass）？他们的抗辩是：自己持有国务大臣签发的令状，故行为合法。\n\n由此引出的深层争议有三层：（1）国务大臣是否有权签发此类搜查令状——其权力来自哪一项法律或先例？（2）如果找不到明确的法律依据，行政机关能否凭“国家利益”或“维持秩序”自行创设权力？（3）当国家权力与个人财产、住宅安宁发生冲突时，举证责任应由谁承担？\n\n用今天的话说，本案触及的是法治（Rule of Law）的核心命题：对公民而言，“法无禁止即可为”；对国家而言，“法无授权不可为”。这一命题在本案中第一次被清晰地司法表述出来。"}, {"title": "四、适用法律", "body": "- 英国普通法（common law）中的非法侵入（trespass）侵权：未经许可踏入他人土地即构成侵权，损害大小并非要件。\n- 普通法上“ every invasion of private property, be it ever so minute, is a trespass ”（对私人财产的每一次侵犯，无论多么轻微，都构成非法侵入）的原则——坎登勋爵在判词中重申了这一点。\n- 一般令状（general warrant）的合法性：此前在“威尔克斯诉伍德案”（Wilkes v Wood, 1763）中，法院已宣告此类令状违反宪法基本原则；本案进一步确认国务大臣并无签发此类令状的普通法或制定法权力。\n- 宪法性资源：坎登援引英国宪制中“财产权神圣”的传统，以及“政府权力必须源于法律”的法治观念。需要说明，英国当时并无成文宪法典，相关依据散布于普通法、判例与《大宪章》（Magna Carta）传统之中。"}, {"title": "五、裁判结果", "body": "法院判决原告恩蒂克胜诉，认定四名被告的闯入与扣押构成非法侵入，须承担损害赔偿责任。坎登勋爵明确宣告：哈利法克斯勋爵签发的令状没有任何制定法（statute）依据，也没有普通法先例支持，因此不能作为合法抗辩；“若某项权力是法律，它必然写在我们的法律书里；若书中找不到，它就不是法律”（大意，原文为 “If it is law, it will be found in our books”）。法院还强调，搜查、扣押公民的全部文件而不仅限于涉嫌犯罪的材料，违背了英国法的精神。"}, {"title": "六、判决理由", "body": "坎登勋爵的论证可从四个层次把握。\n\n第一，从财产权与非法侵入的一般规则出发。判词（大意）写道：人们组成社会的主要目的在于保障自己的财产；这一权利除非被公共法律为整体利益而剥夺或限制，否则应被保持为神圣而不可侵犯的。按照英格兰的法律，对私人财产的每一次侵犯，无论多么轻微，都是非法侵入——未经我的许可，任何人都不得踏入我的土地，即便损害为零也应承担责任。\n\n第二，举证责任的分配。被告若主张其行为合法，就必须指出一项“积极的法律”（positive law）作为授权；这项抗辩要交由法官审查，法官须到法律书中查找其依据。如果既找不到制定法条文，也找不到普通法原则作为依据，那么“法律书的沉默”本身就是反对被告的证据——这是一句极有力量的表述（大意）。\n\n第三，对“国家利益”抗辩的拒绝。政府方曾暗示，搜查煽动性刊物的作者属于维护治安的需要。坎登回应（大意）：本案中没有出现任何可以支持这种权力的法律先例；无奈的先例与行政惯例不能变成法律；政府的必要性不能成为侵犯公民住宅与文件的正当理由。判词还特别指出，令状授权扣押“全部文件”而非仅涉嫌犯罪的材料，过于宽泛，与英国法律的精神相悖。\n\n第四，原则的提炼。后人对本案的经典概括是：国家只能做法律明确授权的事，而个人可以做法律未禁止的事（此为对坎登判决的通行概括，非逐字原文）。这一命题把“权力法定”确立为英国宪法的基石。值得注意的是，坎登的论证方式非常“普通法”：他从侵权法的具体规则（非法侵入）一步步推导出宪法性结论，而非宣布一部成文宪法条文，体现了普通法“从个案到原则”的思维特征。"}, {"title": "七、学术评价", "body": "恩蒂克案在英国宪法史与法理学上的地位极高，常与马伯里案相提并论，但二者制度语境完全不同。\n\n其一，它是“法治”原则最经典的司法表述之一。法治（Rule of Law）的核心不只是“公民守法”，更是“权力受法约束”——政府行使强制权力必须能指出明确的法律依据。戴雪（A. V. Dicey）在《英宪精义》中系统阐述的法治思想，其历史根源之一正是本案所确立的原则。Wacks 在讨论法治与权力约束时，也把“政府权力必须具有法律依据”作为核心要素。\n\n其二，它划定了普通法中“自由”的默认状态。本案确立的“个人可为法律未禁止之事，国家仅可为法律授权之事”，实际上是一种关于自由的推定：自由是原则，限制是例外，且限制的合法性须由主张限制的一方证明。这一思路后来深刻影响了隐私权与搜索扣押法的发展。\n\n其三，它体现了普通法作为“自由守护者”的角色。与大陆法系依赖成文宪法条文不同，英国没有单一宪法典，公民的住宅与文件自由是通过一个个像恩蒂克案这样的判例逐步建构起来的。这种“司法渐进主义”是英国宪制的重要特征，Siems 在比较法研究中把这种差异视为不同法律风格（legal style）的典型体现。\n\n其四，它对美国宪法产生了直接影响。本案（连同威尔克斯诉伍德案）是美国宪法第四修正案（Fourth Amendment）的重要历史背景，美国最高法院曾将其称为“伟大的判决”“英国自由的里程碑之一”“英国宪法的永久纪念碑之一”，并把它作为理解第四修正案起草者原意的重要指南。这里需要区分：美国是通过成文宪法条文禁止无理搜查扣押，英国则是通过普通法判例限制行政权力，制度载体不同，原则精神相通。\n\n其五，学术上的讨论亦提示其局限：本案保护的主要是财产权与住宅安宁，其“财产权语言”在今天看来带有历史局限（当时妇女、贫民等并未享有同等保护）；但它所提供的“权力必须有法律依据”的论证框架，却是超越时代的。"}, {"title": "八、现实意义", "body": "恩蒂克案的影响延续至今。\n\n首先，在搜索与扣押法领域，它确立了这样的常识：警察或行政机关搜查公民住宅、扣押财物，必须有明确的法律授权和符合法定形式的令状；令状必须具体说明搜查地点、对象与物品，笼统的“一般令状”为现代法治所不容。从英国的《1984 年警察与刑事证据法》（Police and Criminal Evidence Act 1984）到美国的第四修正案判例，这一精神一脉相承。\n\n其次，它成为限制公权力、保障个人隐私与住宅权利的思想资源。在数字时代，当政府要求调取公民通信记录、定位数据或社交媒体信息时，“是否具有明确法律授权”“是否过于宽泛”仍是核心追问——恩蒂克案关于“全部文件”式扣押的批评，在数字时代反而更显敏锐。\n\n再次，在比较法与法治教育中，本案是讲解“权力法定”“程序正当”“法律保留”等概念的必引案例。它与马伯里案一起说明：无论是通过成文宪法下的司法审查，还是通过普通法下的侵权诉讼，法律都能为权力划定边界。\n\n最后，本案也提醒我们注意法律与政治现实的复杂关系：恩蒂克本人并未产生巨大的政治影响，真正被搜查的目标是威尔克斯；但正因为一位普通作家坚持诉讼，才把一个具体的侵权案件变成了宪政史上的里程碑。这正是普通法传统的魅力——伟大的法律原则，常常诞生于微小而具体的权利主张之中。"}]}, "C5": {"title": "R 诉 Jogee（R v Jogee）", "court": "英国最高法院（Supreme Court of the United Kingdom）", "year": "2016", "theme": "共同犯罪与归责（Joint Enterprise and Criminal Responsibility）", "sections": [{"title": "一、案件背景", "body": "“共同犯罪”（joint enterprise）是英国刑法中一个长期使用、也长期饱受争议的领域：两人以上共同实施犯罪 A 的过程中，其中一人又实施了犯罪 B（常见情形是在斗殴、抢劫中发生的杀人），另一人是否也要对犯罪 B 承担刑事责任？过去三十余年，在英国法与若干英联邦法域中流行的一条规则是：只要第二人对犯罪 B 的发生有所“预见”（foresight），即预见到主犯可能实施该罪，却仍继续参与犯罪 A，就可以被认定为对犯罪 B 具有必要的犯罪心态。这条规则被称为“寄生性从犯责任”（parasitic accessory liability），其源头通常被追溯至 1985 年枢密院审理的“陈永兆诉女王案”（Chan Wing-Siu v The Queen, [1985] AC 168，一宗由香港上诉至枢密院的案件）以及 1999 年上议院的“R 诉 Powell and English 案”（[1999] 1 AC 1）。\n\n批评者长期指出，这一规则把较轻的“预见”等同于“故意协助或教唆”，使得一些身处犯罪团伙边缘、并未希望或意图杀人的人，也被以谋杀罪论处，且最低刑期极重。2015 年 10 月，英国最高法院与枢密院司法委员会联合开庭审理 R 诉 Jogee 及其关联的 Ruddock 诉女王案（来自牙买加的上诉），于 2016 年 2 月 18 日作出判决（[2016] UKSC 8；[2016] UKPC 7）。"}, {"title": "二、当事人", "body": "- 上诉人（原审被告）：Jogee（贾吉）。2011 年 6 月 9 日晚，他与同案人 Hirsi 一起吸毒、饮酒，情绪越来越激动，两次前往 Naomi Reid 的住所（Reid 与被害人 Paul Fyfe 是伴侣关系）。Reid 发短信要求 Jogee 不要再带 Hirsi 回来，但两人几分钟后第三次返回。凌晨约 2 时 30 分，Fyfe 已回到屋内，双方发生激烈争执；Jogee 在屋外挥舞瓶子并高声鼓动 Hirsi，Hirsi 随后持刀刺死 Fyfe。\n- 原审：Jogee 在诺丁汉刑事法院（Nottingham Crown Court）被判谋杀罪成立，判处无期徒刑，最低服刑 20 年；上诉法院将最低刑期减为 18 年，但维持谋杀罪定罪。\n- 关联上诉人：Ruddock（来自牙买加，Ruddock v The Queen），涉及在抢劫出租车司机过程中发生的致命袭击。\n- 合议庭：由五名法官一致判决——院长纽伯格勋爵（Lord Neuberger）、副院长黑尔女男爵（Lady Hale）、休斯勋爵（Lord Hughes）、托尔森勋爵（Lord Toulson）与托马斯勋爵（Lord Thomas）。判决由休斯勋爵与托尔森勋爵共同执笔。"}, {"title": "三、核心争议", "body": "本案的核心争议是一个刑法教义问题：从犯（secondary party）对主犯在实施犯罪 A 过程中实施的犯罪 B 承担刑事责任，所需的犯罪心态（mens rea，犯罪故意/罪过）究竟是什么？\n\n具体分为三个问题：（1）从犯是否只需“预见”犯罪 B 可能发生，就足以成立责任？（2）“寄生性从犯责任”是否是普通法中一条独立且较低标准的归责规则？（3）如果是历史判例走错了方向，法院能否、应否予以纠正，纠正后又应如何处理以往依旧规则作出的定罪？\n\n这背后是一个更根本的刑法哲学问题：刑事归责应以“行为人自己的故意”为基础，还是可以以“对他人行为的预见”替代故意？前者体现责任主义（personal responsibility）与罪责原则，后者则更侧重对团伙暴力的打击效果。"}, {"title": "四、适用法律", "body": "- 英国普通法中关于从犯责任（accessory liability / secondary liability）的一般规则：从犯须有帮助、教唆、鼓励主犯实施犯罪的客观行为，并具“协助或教唆的故意”。这一一般规则的成文法基础包括《1861 年从犯与教唆法》（Accessories and Abettors Act 1861）第 8 条。\n- 争议中的先例：Chan Wing-Siu v The Queen [1985] AC 168 与 R v Powell and English [1999] 1 AC 1 所确立的“预见即可归责”规则。\n- 谋杀罪的罪过要求： intent to kill or cause grievous bodily harm（杀人或造成严重身体伤害的故意）。\n- 上诉程序：英国最高法院依据《2005 年宪法改革法》（Constitutional Reform Act 2005）受理来自英格兰及威尔士上诉法院的上诉；对牙买加的上诉则由枢密院司法委员会审理，两案由同一合议庭联合判决。"}, {"title": "五、裁判结果", "body": "最高法院（与枢密院）一致裁定：准许两案上诉，撤销原判中依“寄生性从犯责任”规则作出的谋杀罪定罪；宣告 Chan Wing-Siu 与 Powell and English 两案在推理上“走错了方向”（took a wrong turning），普通法应回到该两案之前的正确轨道。\n\n法院重新表述的规则是：从犯对犯罪 B 承担责任，必须具备“协助或教唆犯罪 B 的故意”；对犯罪 B 的“预见”本身不是独立的归责标准，而仅是证明这种故意的证据——有时是很有力的证据，但终究只是证据。是否具备该故意，应由陪审团在具体案件中判断。就 Jogee 本人而言，法院认为他至少可成立过失杀人（manslaughter），并将就谋杀罪是否应重审听取进一步意见。\n\n对于以往依旧规则定罪的案件，法院指出：如欲逾期上诉或由刑事案件复审委员会（Criminal Cases Review Commission）复核，须适用“实质性不公”（substantial injustice）标准，并非自动推翻。"}, {"title": "六、判决理由", "body": "休斯勋爵与托尔森勋爵的联合判决（大意）按以下逻辑展开。\n\n第一，厘清概念。法院指出，“共同犯罪”一词若仅指两人以上共同犯罪，并无特别含义；本案真正涉及的是一个更狭窄的领域——从犯在共同实施犯罪 A 时，对主犯实施的犯罪 B 是否负责。过去这一领域被称为“寄生性从犯责任”，但该标签本身不应模糊其归责标准。\n\n第二，梳理历史。法院仔细审查了 Chan Wing-Siu 与 Powell and English 所援引的早期判例，认为这些先例并未支持它们所宣布的新规则；两案实际上确立了一项新原则（laying down a new principle），且偏离了从犯责任一贯要求的“协助或教唆故意”。法院还指出，两案出于“不想让造成死亡的共同犯罪者逃脱定罪”的政策考量，却没有充分考虑从犯在多数情形下本可构成过失杀人，这说明其推理存在缺陷。\n\n第三，纠正错误。判决强调，预见犯罪 B 可能被实施，并不等于授权或同意该犯罪。旧规则的错误正在于把“预见”当作对犯罪 B 的“自动授权”（automatic authorisation）。正确的规则是：犯罪心态必须是协助或教唆的故意；这种故意可以是“有条件的”——从犯希望犯罪 B 不必发生，但仍有意在必要时提供帮助——但无论如何必须有“故意”，而不能仅仅是“预见到可能性”。法院同时明确：协助或教唆的故意，并不要求从犯“希望”犯罪 B 发生；在实践中，多数案件仍会通过“大家都是一伙的、都意图犯罪发生”来证明这一故意。\n\n第四，制度层面的自我反思。法院指出，这一领域的法律历来属于普通法而非制定法，因此由创造它的法院来审查并纠正错误，是正当且必要的。这体现了普通法“司法自我纠错”的传统：先例并非不可动摇，当发现历史推理有误时，法院可以在严格论证后予以推翻。\n\n第五，处理遗留问题。法院没有让旧规则下的所有定罪自动失效，而是设置了“实质性不公”的门槛，以平衡纠错与法律安定性（legal certainty）之间的张力——这一处理本身，就体现了对法治中“可预测性”价值的顾及。"}, {"title": "七、学术评价", "body": "R 诉 Jogee 是当代英国刑法最重要的判例之一，其法理学意义体现在多个层面。\n\n其一，它重申了责任主义（principle of personal responsibility）在刑法中的核心地位。刑事责任应以行为人自身的可责难心态为基础，不能以单纯的“预见”替代“故意”。这一点与刑法理论中“罪责原则”（culpability）的要求相吻合：刑罚的正当性在于行为人对自己的行为具有控制与选择能力，仅因身处某个团伙、预见到可能出事就被以谋杀罪重判，与这一原则不合。\n\n其二，它展示了普通法法院如何对待“错判的先例”。法院没有因为遵循先例（stare decisis）的稳定性要求而维持明显有误的规则，而是在详尽历史考察后予以纠正，同时又通过“实质性不公”标准防止纠错引发连锁震荡。这体现了法律确定性（certainty）与个案正义（justice）之间的平衡，也是 Wacks 在讨论司法裁量与法的确定性时关注的典型张力。\n\n其三，它引发了关于“司法造法还是立法改革”的争论。有论者认为，共同犯罪这样涉及重罪认定的领域，应由议会通过立法明确界定，而非法院以判例变更；也有人（包括案件判决本身）强调，普通法既是这一规则的创造者，就有责任纠正它。这一争论实质上延续了法律实证主义（Legal Positivism）关于“法官是否应造法”的老问题——与多诺霍案中异议大法官的担忧遥相呼应，但本案的最高法院采取了更积极的自我纠错立场。\n\n其四，它具有社会与刑事政策意义。批评者长期指出，“共同犯罪”规则在实践中对来自弱势社区、卷入街头暴力的年轻人影响尤深；Jogee 案提高了归责门槛，使“站在旁边、并未意图杀人的人”更难被以谋杀罪论处。英国议会此后还就“重大贡献”（significant contribution）等改革展开讨论，说明判例与立法之间形成了互动。\n\n其五，在比较法层面，本案提示我们：不同法域对团伙犯罪中的归责问题采取了不同路径——英国通过普通法的自我修正，大陆法系国家则多以刑法典中的“共同正犯”“间接正犯”等概念处理。研究本案时应避免把英国“joint enterprise”直接等同于中国刑法中的“共同犯罪”概念，二者在构成要件与归责原理上并不完全相同。"}, {"title": "八、现实意义", "body": "首先，本案直接改变了英国共同犯罪的司法实践：陪审团在审理此类案件时，必须被指示区分“预见”与“协助或教唆的故意”，以往那种“预见到可能杀人即按谋杀罪处理”的做法不再成立。数千起依旧规则作出的定罪由此面临复核可能， Criminal Cases Review Commission 的工作因此大幅增加。\n\n其次，本案对“群体暴力中的个人责任”这一现实问题给出了更审慎的法律回答：既承认多人共同犯罪时各自责任的复杂性，又坚持不能因为一个人“在现场、预见到风险”就把最严重的罪名加诸其身。这种审慎对刑事司法的人权保障具有普遍意义。\n\n再次，本案与后续立法讨论说明：一个法律规则即使运行多年、被广泛援引，也仍可能因理论基础错误而被推翻——“先例的权威”不能替代“论证的正确”。这种敢于自我纠错的司法态度，是普通法体系保持活力的重要机制。\n\n最后，对学习者而言，Jogee 案是理解刑法归责原理（行为—心态—责任）、普通法先例制度运作（遵循与推翻）、以及“法律确定性 vs 个案公正”这一永恒张力的绝佳教材。它也提醒我们：教义上看似技术性的“mens rea 标准”之争，落实到具体的人身上，可能就是十年、二十年乃至终身监禁的差别。"}]}, "C6": {"title": "汉迪赛德诉英国（Handyside v United Kingdom）", "court": "欧洲人权法院（European Court of Human Rights）", "year": "1976", "theme": "表达自由与比例原则（Freedom of Expression and Proportionality）", "sections": [{"title": "一、案件背景", "body": "本案是《欧洲人权公约》（European Convention on Human Rights, ECHR）早期最重要的判例之一，也是“表达自由”（freedom of expression）与“比例原则”（proportionality）法理的奠基性案件。案件起因于一册名为《小红皮书》（The Little Red Schoolbook）的出版物。该书由丹麦作者索伦·汉森（Søren Hansen）与耶斯佩尔·延森（Jesper Jensen）撰写，以青少年为读者对象，内容涉及教育、社会与性等问题，其中关于“学生”的一章有长达 26 页讨论“性”（Sex）。该书已在丹麦、比利时、芬兰、法国、西德、希腊、冰岛、意大利、荷兰、挪威、瑞典、瑞士等多个欧洲国家出版。\n\n英国出版商理查德·汉迪赛德（Richard Handyside）是“Stage 1”出版社的业主，购得该书的英国版权，并寄送数百本样书及新闻稿给各类报刊，还刊登广告。1971 年 3 月 31 日，当局扣押了 1069 册，4 月 1 日又扣押 139 册；但约 18800 册（总印数 20000 册）未被扣押并已售出。1971 年 7 月 1 日，治安法院裁定汉迪赛德犯有“持有淫秽书籍意图牟利出版”两项罪名，各罚款 25 英镑，另承担 110 英镑诉讼费；其上诉被驳回。汉迪赛德于 1972 向欧洲人权委员会提出申诉，案件最终于 1976 年 12 月 7 日由欧洲人权法院以 13 票对 1 票作出判决（申请号 5493/72，Series A No. 24）。"}, {"title": "二、当事人", "body": "- 申请人：理查德·汉迪赛德（Richard Handyside），英国出版商，主张其《欧洲人权公约》第 10 条表达自由权受到侵害，同时主张财产权（第一议定书第 1 条）受侵犯。\n- 被申请人：联合王国（英国政府）。政府抗辩：对表达自由的限制是依法作出的、旨在保护道德，符合第 10 条第 2 款的例外情形。\n- 审理机构：欧洲人权法院（当时为 19 人组成的法院，本案由大法庭审理）。法官赫尔穆特·莫斯勒（H. Mosler）提出异议意见，认为存在违反公约之处；法官梅赫迪·泽基亚（M. Zekia）就财产权问题提出协同意见。"}, {"title": "三、核心争议", "body": "案件的核心争议是：英国当局依据《1959 年淫秽出版物法》（Obscene Publications Act 1959）扣押、销毁该书并对出版商定罪，是否构成对第 10 条表达自由的不当限制？\n\n据此可分三层：（1）是否存在“干预”（interference）——这一点并无争议，扣押与刑罚显然构成干预；（2）该干预是否“依法规定”（prescribed by law）并具有第 10 条第 2 款所列的合法目的——英国政府主张目的是“保护道德”（protection of morals）；（3）该干预是否为“民主社会所必需”（necessary in a democratic society）——这既是比例原则的审查核心，也是本案最具理论价值之处。\n\n更深层的问题是：在欧洲各国道德观念并不统一的情况下，由一个国际法院来审查缔约国对“道德”的判断，其正当性边界在哪里？这正是“各国裁量余地”（margin of appreciation，又译“判断余地”） doctrine 所要回答的问题。"}, {"title": "四、适用法律", "body": "- 《欧洲人权公约》第 10 条第 1 款：人人享有表达自由的权利，包括持有意见及不受公共权力干涉地接收与传递信息与思想的权利。\n- 第 10 条第 2 款：行使表达自由可受“依法规定、且在民主社会中为……保护道德……所必需”的限制与处罚。\n- 第 17 条（禁止滥用权利）与第一议定书第 1 条（财产权保护）——申请人亦援引，欧洲人权委员会曾一并审查。\n- 英国国内法：《1959 年淫秽出版物法》。\n- 程序背景：欧洲人权委员会 1975 年通过报告，多数认为未违反第 10、17 条及第一议定书第 1 条；案件随后移交欧洲人权法院。"}, {"title": "五、裁判结果", "body": "欧洲人权法院以 13 票对 1 票裁定：英国当局对该书采取的措施虽构成对表达自由的干预，但该项干预“依法规定”、具有“保护道德”这一合法目的，且为“民主社会所必需”，因此不构成对第 10 条的违反（no violation）。法院就财产权问题（第一议定书第 1 条）一致认定未受违反。换言之，汉迪赛德败诉。\n\n判决同时宣布了一项影响深远的原则：表达自由不仅保护那些受到欢迎、被视为无害或无关紧要的“信息”与“思想”，也保护那些“冒犯、震惊或扰乱国家或人口中某一部分人”的表达——这正是多元、宽容与开放精神的要求，没有它们就没有“民主社会”（判决第 49 段，通行译法/大意）。"}, {"title": "六、判决理由", "body": "法院的论证遵循“三段式”审查框架，这一框架后来成为欧洲人权法院审理限制性措施的经典范式。\n\n第一，确认干预的存在。法院指出，扣押、没收、销毁书籍以及对出版商定罪处罚，显然构成对第 10 条第 1 款权利的干预；因此必须审查这种干预能否依第 10 条第 2 款获得正当化。\n\n第二，“依法规定”与“合法目的”。法院认为，相关措施有《1959 年淫秽出版物法》作为依据，且目的在保护青少年道德，因此满足第 2 款的前两项条件。\n\n第三，“民主社会所必需”与比例原则。法院强调，“必需”并不意味着“不可或缺”，但要求干预与所追求的合法目的之间相称（proportionate）。法院指出，第 10 条第 2 款意义上的“形式、条件、限制或处罚”，都必须与所追求的合法目的相称（大意）。\n\n第四，“各国裁量余地”理论——本案最核心的贡献。法院承认，缔约国在保障公约权利方面承担首要责任；由于各国主管机关与其社会“活的力量”保持着直接而持续的联系，原则上比国际法官更有资格判断本国道德要求的具体内容，以及某项限制是否“必需”。但法院同时强调：这种裁量余地并非无限，它“与欧洲监督并行不悖”（goes hand in hand with European supervision）——最终判断某项限制是否与公约相容，仍是欧洲人权法院的职责。法院还指出，在缔约国国内法中找不到统一的道德观念，道德要求因时因地而异，这正是给予裁量余地的理由。\n\n第五，结合事实的权衡。法院考虑到该书专门面向青少年、其中关于性的章节具有刺激性，且英国各地对类似出版物的处理方式存在差异，认为英国当局在保护青少年道德方面的判断处于其合理的裁量余地之内，所采取的措施并未过度（not excessive），因此不构成对公约的违反。\n\n第六，异议意见的价值。莫斯勒法官认为存在违反：当局只扣押了不足 10% 的印数，约 90% 已流入社会，措施的实际效果与目标之间明显不成比例，客观上不足以实现“保护青少年”的目的；英国不同地区做法的差异也令人怀疑伦敦措施的必要性。这一异议以比例原则反逼多数意见的论证，对后世讨论颇具启发。"}, {"title": "七、学术评价", "body": "汉迪赛德案在欧洲人权法与法理学上地位极高。\n\n其一，它奠定了“表达自由包括令人不适的表达”这一经典命题。判决第 49 段关于“冒犯、震惊或扰乱”的表述，被后世无数判决引用，成为衡量表达自由保护范围的试金石。它提醒人们：表达自由的价值恰恰在那些挑战主流、边缘甚至令人反感的言论上受到真正的检验；只保护“好听的话”的表达自由是廉价的。\n\n其二，它系统确立了“各国裁量余地”（margin of appreciation） doctrine。这一理论试图调和人权保护的普遍性与各国道德、文化、法律传统的多样性：既承认国家在评价本地需求方面的比较优势，又保留欧洲层面的监督。Wacks 在讨论人权与国际监督时指出，裁量余地体现了国际人权机制特有的“辅助性”（subsidiarity）逻辑——国际法院在这里扮演国内机关的补充角色，替代品的定位并不准确。\n\n其三，它使“比例原则”（proportionality）成为欧洲人权法的核心分析方法。比例原则要求：限制措施须适合达成合法目的、为实现目的所必要、且与目的相称。这套“三段式”审查后来被广泛用于第 8、9、10、11 条等几乎所有“有限权利”（qualified rights）案件，并深刻影响了欧盟法乃至全球宪法审查的方法论。\n\n其四，它引发了持续的批判性讨论。批评者认为，裁量余地理论可能成为缔约国规避公约义务的挡箭牌，使“欧洲监督”流于形式；支持者则强调，没有裁量余地，人权法院将不堪重负，且会丧失对地方民主的尊重。这一争论的实质，是国际人权保护中“统一标准”与“多元宽容”之间的张力——也正是本案自己在各处强调的 pluralism（多元主义）命题的延伸。\n\n其五，需要明确法域区分。本案的审查依据是国际条约（《欧洲人权公约》）及其法院的判例，与美国最高法院依据宪法第一修正案处理表达自由案件（如“布兰登堡诉俄亥俄州案”）分属不同体系：美国采取更绝对的“内容中立”保护路径，欧洲则明确采用“利益衡量+比例原则”的路径。把两者混为一谈是常见的错误。"}, {"title": "八、现实意义", "body": "首先，本案确立的审查框架至今仍是欧洲人权法院处理表达自由案件的日常工具：凡涉及诽谤、淫秽、仇恨言论、宗教冒犯、国家安全等限制表达的措施，法院都会依次追问“是否依法规定”“是否追求合法目的”“是否在民主社会必需且相称”。\n\n其次，“各国裁量余地”理论的影响早已超出表达自由领域，被适用于私生活保护、宗教自由、财产权等广泛议题，并成为欧洲人权制度最具辨识度的理论品牌之一。它也促使人们思考：在跨文化、跨法域的人权保护中，如何在普遍价值与地方差异之间取得平衡——这一问题在今日的移民、宗教符号、网络治理等议题上愈发重要。\n\n再次，本案对新闻出版、艺术创作与网络平台的内容治理具有直接启发：当平台或国家以“保护青少年”“维护公共道德”为由限制内容时，必须证明措施的正当性、必要性与相称性；“令人不适”本身不能成为压制的充分理由。\n\n最后，莫斯勒法官的异议提醒我们：比例原则不只是口号，还需要对措施的实际效果进行经验审查——一项看似合理的限制，如果根本没有实现其宣称的目标，就难以通过比例原则的检验。\n\n对学习者而言，汉迪赛德案是把抽象人权条款转化为可操作审查方法的典范：它既展示了表达自由的宽广射程，也展示了这种自由如何在民主社会中与道德、青少年保护等其他价值相协调。它是理解比例原则、裁量余地以及欧洲人权法方法论不可绕过的起点。"}]}, "C7": {"title": "达奇森诉英国（Dudgeon v United Kingdom）", "court": "欧洲人权法院（European Court of Human Rights）", "year": "1981", "theme": "私人生活与道德立法（Private Life and Morality Legislation）", "sections": [{"title": "一、案件背景", "body": "本案是《欧洲人权公约》（European Convention on Human Rights, ECHR）历史上第一起判决支持同性恋者权利的里程碑案件。申请人杰弗里·达奇森（Jeffrey Dudgeon）是北爱尔兰贝尔法斯特的一名船务职员和同性恋权利活动人士。1976 年，皇家阿尔斯特警队（Royal Ulster Constabulary）就他的性生活对他进行讯问，并搜查、扣押了他的一些物品；但他并未因此受到刑事起诉。\n\n问题在于当时仍然有效的刑事法律：1885 年《刑法修正案》（Criminal Law Amendment Act 1885）第 11 条把男性之间的同性性行为（当时法律术语为“严重猥亵”，gross indecency）定为犯罪。这一条原本适用于整个英国；但英格兰和威尔士已通过 1967 年《性犯罪法》（Sexual Offences Act 1967）将成年男性之间自愿、私下的同性性行为非罪化，苏格兰于 1980 年跟进，唯独北爱尔兰仍保留原状。英国政府辩称：尽管法律仍在形式上存在，但检察机关已表示不会起诉私下自愿的同性行为，因此实际上并无“干预”。\n\n达奇森于 1975 年（一说 1976 年）向欧洲人权委员会提出申诉，委员会于 1979 年宣布申诉可受理，案件于 1981 年 4 月由 19 名法官组成的大法庭开庭审理，1981 年 10 月 22 日作出判决（申请号 7525/76，Series A No. 45）。达奇森由大律师吉福德勋爵（Lord Gifford）、特里·穆尼亚德（Terry Munyard）及事务律师保罗·克莱恩（Paul Crane）代理。"}, {"title": "二、当事人", "body": "- 申请人：杰弗里·达奇森（Jeffrey Dudgeon），北爱尔兰贝尔法斯特的船务职员、同志权利活动者。他主张北爱尔兰继续维持刑事禁令本身即构成对其私生活权的持续干预。\n- 被申请人：联合王国（英国政府）。政府主张：（1）第 8 条不适用于本案，因为申请人并未被起诉，其私生活未受实际干涉；（2）即便适用，相关限制也是为了保护道德，符合第 8 条第 2 款，且北爱尔兰民意支持维持禁令。\n- 审理机构：欧洲人权法院。法院以 15 票对 4 票认定违反第 8 条；并以 14 票对 5 票认为无必要再依第 14 条（结合第 8 条）审查歧视问题。双方均提交了少数意见。"}, {"title": "三、核心争议", "body": "案件围绕《欧洲人权公约》第 8 条“私生活、家庭生活、住宅与通信受尊重的权利”展开，可分三层：\n\n（1）第 8 条第 1 款是否适用？——“私生活”（private life）是否包含个人的性生活？一项“仅仅存在”而未实际执行的刑事法律，是否构成对国家干预？\n\n（2）第 8 条第 2 款的抗辩是否成立？——维持禁令是否属于“依法规定”且“为保护道德所必需”？旨在反映公众道德反感的法律，能否构成对私人性生活的合法限制？\n\n（3）是否还有必要依第 14 条（禁止歧视）审查？——比较异性恋与同性恋在同意年龄上的差别待遇是否构成歧视？\n\n其中第一层最具理论突破性：法院必须回答，一部悬而未用的刑法是否也会“说话”——它的存在本身是否就对公民的自由空间产生压迫性效果。"}, {"title": "四、适用法律", "body": "- 《欧洲人权公约》第 8 条第 1 款：人人享有私生活、家庭生活、住宅与通信受尊重的权利。\n- 第 8 条第 2 款：公共权力对此权利的干预，只有“依法规定”且为“民主社会所必需”，并出于国家安全、公共安全、经济福祉、防止混乱或犯罪、保护健康或道德、保护他人权利自由等目的，方可正当化。\n- 第 14 条：在公约所载权利自由的享有上禁止歧视（申请人兼而援引，法院最终认为无必要单独审查）。\n- 国内法背景：1885 年《刑法修正案》第 11 条；1967 年《性犯罪法》（英格兰和威尔士）；1980 年苏格兰的非罪化改革。\n- 比较背景：欧洲委员会成员国中越来越多的国家已将同性性行为非罪化，这一“欧洲共识”趋势构成法院判断“裁量余地”范围的重要背景。"}, {"title": "五、裁判结果", "body": "欧洲人权法院判决：北爱尔兰维持 1885 年第 11 条、将成年男性之间自愿私下的同性性行为定为犯罪，违反《欧洲人权公约》第 8 条（15 票对 4 票）。法院指出：不仅实际起诉构成干预，法律的“持续存在”本身即构成对申请人私生活权的持续干预——因为在法律的两难之下，他要么选择遵守法律、压抑自己的性倾向，要么选择实施行为并因此面临刑事追诉（判决第 41 段，大意）。\n\n法院进一步认定，基于该限制“范围之广与绝对性”（breadth and absolute character），且不论可能刑罚之严厉程度，这种限制与所追求的目的之间已构成“不成比例”（disproportionate），因此不能以“保护道德”为由正当化。至于第 14 条的歧视问题，法院以 14 票对 5 票认为，既然已认定第 8 条被违反，再单独审查歧视已无实际法律意义。\n\n判决的直接后果是：1982 年 10 月，北爱尔兰将男性同性性行为非罪化，与英格兰、威尔士、苏格兰的立场趋于一致。1983 年 2 月 24 日的第 50 条（公平赔偿）程序中，法院未判给金钱损害赔偿，认为胜诉判决本身即已构成充分救济，但判给 3315 英镑的诉讼费用。"}, {"title": "六、判决理由", "body": "法院的论证可归纳为五个环节。\n\n第一，“私生活”的解释。法院确认，第 8 条意义上的“私生活”是一个宽泛的、无法穷尽列举的概念，涵盖个人的身体与心理完整、身份认同、姓名、性取向与性生活等；个人的性生活属于“私生活”的核心领域（这一认定也为后来的“个人自主”理论奠定了基础）。\n\n第二，“法律存在本身即构成干预”。这是本案最重要的理论突破。法院认同欧洲人权委员会的意见（大意）：维持系争立法即对申请人依第 8 条享有的私生活权（包括其性生活）构成持续干预；就申请人的个人处境而言，这部法律的存在本身就持续而直接地影响其私生活——他要么克制自己、放弃其性倾向所驱使的（即便在私下与自愿伴侣之间的）行为，要么实施该行为并因此承担被刑事追诉的风险。这一推理拒绝了英国政府“未起诉即无干预”的抗辩，揭示了刑法的规范宣示功能本身对自由的收缩效果。\n\n第三，对“保护道德”抗辩的审查。法院承认保护道德可以是第 8 条第 2 款下的合法目的，也承认各国在道德判断上享有一定的裁量余地；但法院强调，当干预指向个人私生活中“最为私密”的方面时，必须有“特别严重的理由”（particularly serious reasons）才能正当化（大意）。英国政府所诉诸的北爱尔兰公众舆论，不足以提供这样的理由。法院还指出：“非罪化并不意味着认可”（decriminalisation does not imply approval）——担心改革会被误解为对同性行为的赞许，并不构成维持带有种种不当特征的法律的正当理由（大意）。\n\n第四，比例原则与“欧洲共识”。法院注意到，在欧洲委员会成员国中，将成年同性之间的自愿性行为非罪化已成为明显趋势；英国本土的英格兰、威尔士和苏格兰也已完成改革。在这一背景下，北爱尔兰的绝对禁令显得“过于宽泛且绝对”，尤其因为它同时适用于私下、自愿、成年人的行为，且不论刑罚轻重，均不成比例。裁量余地在此被明显收窄。\n\n第五，程序上的克制。法院以 14 票对 5 票认为，既然第 8 条已被违反，就不再有必要审查第 14 条的歧视主张。这一处理既避免了在歧视问题上作出更宽泛的宣告，也体现了“必要时才裁判”的司法克制（judicial restraint）。"}, {"title": "七、学术评价", "body": "达奇森案在人权法与法理学上的地位，可从以下几方面理解。\n\n其一，它重新界定了“私生活”的保护范围与“干预”的概念。本案确立了两条影响深远的规则：性生活属于第 8 条保护的私生活；刑法规范的“存在本身”即可构成持续干预，而不以实际执法为前提。这使大量“潜在受害者”得以在未被起诉的情况下求助国际人权机制，极大拓展了人权保护的实际覆盖面。后来的 A.D.T. v United Kingdom（2000）等案正是沿此路径展开。\n\n其二，它展示了“活的法律工具”（living instrument）解释方法。法院没有把 1950 年公约起草时对同性恋的理解当作永恒标准，而是参考欧洲各国不断演进的法律实践，认定公约必须按“当今条件”来解释。这种方法论与汉迪赛德案中的“裁量余地”形成有趣对照：在道德多元、缺乏共识的领域，裁量余地较宽（如汉迪赛德案）；而当欧洲范围内出现明显共识趋势、且涉及个人最私密的自主时，裁量余地收窄（如达奇森案）。两案并读，方能完整理解欧洲人权法院的方法论。\n\n其三，它提出了“道德立法”的限度问题。法律是否可以把多数人的道德反感强加于少数人的私人生活？法院的回答是：单纯的“公众反感”不足以正当化对个人私生活的干预；“保护道德”必须建立在更坚实的、与损害原则相称的理由之上。这一结论与密尔（J. S. Mill）在《论自由》中所主张的“伤害原则”（harm principle）遥相呼应——社会干涉个人自由的正当理由只能是防止对他人的伤害，而非单纯的道德不悦。Wacks 在讨论法律与道德的关系时，也把这类案件作为“法律不应强制执行多数道德”的范例。\n\n其四，它开启了欧洲人权法院保护性少数权利的历史。此后，Norris v Ireland（1988）、Modinos v Cyprus（1993）等案延续了这一路径，欧洲委员会最终要求成员国不得将同性性行为入罪。达奇森案还被美国最高法院肯尼迪大法官在 Lawrence v Texas（2003）的判决中援引，成为跨国宪法对话的一部分——但须注意：美国是通过宪法第十四修正案正当程序条款处理同类问题，欧洲则通过国际人权条约，法域基础不同，不可混为一谈。\n\n其五，少数意见亦值得重视。4 名持异议的法官更倾向于尊重北爱尔兰本地的民意与裁量余地，他们的担忧反映了联邦式、多元社会中“地方民主”与“统一人权标准”之间的真实张力。这种张力并非完全消极——它促使法院在后续案件中更精细地界定裁量余地的范围与条件。"}, {"title": "八、现实意义", "body": "首先，达奇森案直接推动了法律改革：北爱尔兰于 1982 年 10 月非罪化，此后整个英国在同性性行为的刑事规制上趋于统一。更广泛地，它与后续判例一起，促成欧洲委员会成员国陆续废除对同性性行为的刑事处罚，成为欧洲性少数权利保护的法律基石。\n\n其次，本案确立了“私人生活权”作为对抗道德立法的重要工具。从性取向到性别认同、从个人自主到身体完整，第 8 条的解释在后续判例中不断扩展——Schlumpf v Switzerland（2009）等案明确把性取向纳入“私生活”范畴，并强调“个人自主”是解释第 8 条的重要原则。这一保护网络如今已覆盖个人信息、数据隐私、家庭形成等诸多领域。\n\n再次，本案对“法律的象征功能”提出了深刻洞见：一部不执行的法律仍在传递“某类人低人一等”的信息，从而损害其人格尊严。这一认识对今天讨论刑事定罪对污名化的影响、仇恨言论立法、以及反歧视法的功能，仍具现实意义。\n\n最后，本案在方法论上提供了“裁量余地随共识而伸缩”的范例：在缺乏欧洲共识的议题上，国家享有较宽余地；而在存在明确趋势、且涉及核心人格自主的议题上，余地收窄、监督加强。这一精细的平衡艺术，是欧洲人权法院能够在尊重多元的同时维护权利底线的重要原因。\n\n对学习者而言，达奇森案是把抽象的人权条款转化为具体权利保护的典范：它既展示了“私生活”概念的解释力，也展示了比例原则如何用来审查以道德为名的立法限制。它与汉迪赛德案并列，构成理解《欧洲人权公约》方法论的两大支柱——前者关乎私生活与道德立法，后者关乎表达自由与多元宽容。"}]}}, "glossary": {"法（Law）": {"term": "法（Law）", "def": "由国家制定或认可、以国家强制力保证实施、调整人们行为的社会规范体系", "lesson": "S1M1K1"}, "法理学（Jurisprudence）": {"term": "法理学（Jurisprudence）", "def": "对法律的本质与运作进行系统反思的学科", "lesson": "S1M1K1"}, "规范（Norm）": {"term": "规范（Norm）", "def": "规定应当如何行为的标准", "lesson": "S1M1K1"}, "制裁（Sanction）": {"term": "制裁（Sanction）", "def": "违反规则时由国家施加的不利后果", "lesson": "S1M1K1"}, "规范性（Normativity）": {"term": "规范性（Normativity）", "def": "规则以“应当”而非“描述”的方式指引行为", "lesson": "S1M1K1"}, "主权者（Sovereign）": {"term": "主权者（Sovereign）", "def": "奥斯丁理论中法律命令的来源", "lesson": "S1M1K1"}, "分离命题（Separation Thesis）": {"term": "分离命题（Separation Thesis）", "def": "法律是否为法律取决于其社会来源而非道德价值", "lesson": "S1M1K2"}, "自然法理论（Natural Law Theory）": {"term": "自然法理论（Natural Law Theory）", "def": "主张法律与道德存在必然联系的学说", "lesson": "S1M1K2"}, "法律实证主义（Legal Positivism）": {"term": "法律实证主义（Legal Positivism）", "def": "以社会事实而非道德价值识别法律的学说", "lesson": "S1M1K2"}, "内在道德（Internal Morality of Law）": {"term": "内在道德（Internal Morality of Law）", "def": "富勒提出的法律在程序上应满足的八项要求", "lesson": "S1M1K2"}, "恶法非法（lex iniusta non est lex）": {"term": "恶法非法（lex iniusta non est lex）", "def": "严重不正义的规则不成其为法", "lesson": "S1M1K2"}, "法律道德主义（Legal Moralism）": {"term": "法律道德主义（Legal Moralism）", "def": "主张国家可以用刑罚强制执行主流道德的立场", "lesson": "S1M1K2"}, "伤害原则（Harm Principle）": {"term": "伤害原则（Harm Principle）", "def": "密尔主张只有防止伤害他人才能正当地干涉自由", "lesson": "S1M1K2"}, "最低限度的自然法（Minimum Content of Natural Law）": {"term": "最低限度的自然法（Minimum Content of Natural Law）", "def": "哈特承认法律必须满足的若干生存条件", "lesson": "S1M1K2"}, "习惯（Custom）": {"term": "习惯（Custom）", "def": "长期反复实践而形成的、被共同体视为应当遵循的行为常规", "lesson": "S1M1K3"}, "社会规范（Social Norm）": {"term": "社会规范（Social Norm）", "def": "群体内非国家制定却实际约束行为的标准", "lesson": "S1M1K3"}, "法律多元主义（Legal Pluralism）": {"term": "法律多元主义（Legal Pluralism）", "def": "同一社会中存在多个法律或规范秩序并存的状态", "lesson": "S1M1K3"}, "活法（Living Law）": {"term": "活法（Living Law）", "def": "埃利希提出的、实际支配社会生活而非见于法典的规则", "lesson": "S1M1K3"}, "宗教法（Religious Law）": {"term": "宗教法（Religious Law）", "def": "以宗教经典与权威解释为依据的规范体系", "lesson": "S1M1K3"}, "活的习惯法（Living Customary Law）": {"term": "活的习惯法（Living Customary Law）", "def": "未成文、仍在地方社会实际运行的习惯法", "lesson": "S1M1K3"}, "强制性（Coercivity）": {"term": "强制性（Coercivity）", "def": "法律以国家强制力为后盾而具有的约束性质", "lesson": "S1M1K4"}, "义务（Obligation）": {"term": "义务（Obligation）", "def": "被社会规则承认为应当履行、可受批评要求履行的事项", "lesson": "S1M1K4"}, "被迫（Obliged）": {"term": "被迫（Obliged）", "def": "因受威胁而不得不做某事的状态", "lesson": "S1M1K4"}, "授权性规则（Power-conferring Rules）": {"term": "授权性规则（Power-conferring Rules）", "def": "赋予人们改变法律地位之能力的规则", "lesson": "S1M1K4"}, "基础规范（Grundnorm）": {"term": "基础规范（Grundnorm）", "def": "凯尔森理论中被预设为法律体系效力最终根据的规范", "lesson": "S1M1K4"}, "内部观点（Internal Point of View）": {"term": "内部观点（Internal Point of View）", "def": "参与者把规则当作正当行为理由来接受的态度", "lesson": "S1M1K4"}, "功能主义（Functionalism）": {"term": "功能主义（Functionalism）", "def": "从法律对社会所起的作用来理解法律的进路", "lesson": "S1M1K5"}, "社会控制（Social Control）": {"term": "社会控制（Social Control）", "def": "社会引导成员行为、维持秩序的机制", "lesson": "S1M1K5"}, "社会工程（Social Engineering）": {"term": "社会工程（Social Engineering）", "def": "庞德把法律视为权衡利益、构建社会的工具", "lesson": "S1M1K5"}, "法律工作（Law Jobs）": {"term": "法律工作（Law Jobs）", "def": "卢埃林提出的法律在社会中承担的六项基本任务", "lesson": "S1M1K5"}, "法的行动（Law in Action）": {"term": "法的行动（Law in Action）", "def": "实际运作中的法律，与书本上的法相对", "lesson": "S1M1K5"}, "恢复性法律（Restitutive Law）": {"term": "恢复性法律（Restitutive Law）", "def": "以恢复原状而非惩罚为中心的法律类型", "lesson": "S1M1K5"}, "国家（State）": {"term": "国家（State）", "def": "在特定领土上垄断合法强制力的政治组织", "lesson": "S1M1K6"}, "主权（Sovereignty）": {"term": "主权（Sovereignty）", "def": "最高、独立、不受更高权威支配的权力", "lesson": "S1M1K6"}, "权力分立（Separation of Powers）": {"term": "权力分立（Separation of Powers）", "def": "立法、行政、司法权由不同机关行使的制度安排", "lesson": "S1M1K6"}, "法治（Rule of Law）": {"term": "法治（Rule of Law）", "def": "权力行使须受一般、公开、稳定规则约束的理念", "lesson": "S1M1K6"}, "法治国（Rechtsstaat）": {"term": "法治国（Rechtsstaat）", "def": "德国传统中受法治保障、提供法律安全国家", "lesson": "S1M1K6"}, "违宪审查（Judicial Review）": {"term": "违宪审查（Judicial Review）", "def": "由法院审查法律是否符合宪法的制度", "lesson": "S1M1K6"}, "法律体系（Legal System）": {"term": "法律体系（Legal System）", "def": "由初级规则与次级规则结合而成、具有统一识别标准的规范性制度整体", "lesson": "S1M2K1"}, "初级规则（Primary Rules）": {"term": "初级规则（Primary Rules）", "def": "直接规定人们应当做或不得做什么的行为规则", "lesson": "S1M2K1"}, "次级规则（Secondary Rules）": {"term": "次级规则（Secondary Rules）", "def": "规定如何识别、改变与裁判初级规则的特殊规则", "lesson": "S1M2K1"}, "承认规则（Rule of Recognition）": {"term": "承认规则（Rule of Recognition）", "def": "官员据以识别哪些规则属于有效法律的共同标准", "lesson": "S1M2K1"}, "改变规则（Rule of Change）": {"term": "改变规则（Rule of Change）", "def": "授权特定机关制定、修改或废止法律规则的规则", "lesson": "S1M2K1"}, "裁判规则（Rule of Adjudication）": {"term": "裁判规则（Rule of Adjudication）", "def": "授权特定机关判断规则是否被违反并作出裁判的规则", "lesson": "S1M2K1"}, "法系（Legal Family）": {"term": "法系（Legal Family）", "def": "依据法律历史、思维方法与实在法特征对各国法律体系所作的分类", "lesson": "S1M2K1"}, "成文法（Statute Law）": {"term": "成文法（Statute Law）", "def": "由立法机关按法定程序制定并以文字形式颁布的法律", "lesson": "S1M2K2"}, "不成文法（Unwritten Law）": {"term": "不成文法（Unwritten Law）", "def": "未以统一法典形式出现、而以判例、习惯或惯例形态存在的法律", "lesson": "S1M2K2"}, "制定法（Statute）": {"term": "制定法（Statute）", "def": "立法机关制定的单项规范性文件", "lesson": "S1M2K2"}, "判例法（Case Law）": {"term": "判例法（Case Law）", "def": "由法院判决形成、可供后续案件援引的法律", "lesson": "S1M2K2"}, "习惯法（Customary Law）": {"term": "习惯法（Customary Law）", "def": "由长期社会实践并形成法律确信的习惯性规则", "lesson": "S1M2K2"}, "法典化（Codification）": {"term": "法典化（Codification）", "def": "将某一法律领域的规则系统编排为统一法典的活动", "lesson": "S1M2K2"}, "宪法（Constitution）": {"term": "宪法（Constitution）", "def": "规定国家根本制度与公民基本权利的最高法", "lesson": "S1M2K3"}, "法律（Statute）": {"term": "法律（Statute）", "def": "由立法机关制定的规范性文件", "lesson": "S1M2K3"}, "行政法规（Administrative Regulation）": {"term": "行政法规（Administrative Regulation）", "def": "行政机关依法律授权制定的规范性文件", "lesson": "S1M2K3"}, "判例（Precedent）": {"term": "判例（Precedent）", "def": "可作为后续案件裁判依据的先前判决", "lesson": "S1M2K3"}, "司法审查（Judicial Review）": {"term": "司法审查（Judicial Review）", "def": "法院审查法律是否符合宪法的制度", "lesson": "S1M2K3"}, "议会主权（Parliamentary Sovereignty）": {"term": "议会主权（Parliamentary Sovereignty）", "def": "英国宪法中议会立法权至上的原则", "lesson": "S1M2K3"}, "违宪审查（Constitutional Review）": {"term": "违宪审查（Constitutional Review）", "def": "由特定机关判断法律是否违宪的制度", "lesson": "S1M2K3"}, "法律渊源（Sources of Law）": {"term": "法律渊源（Sources of Law）", "def": "法律规则借以取得效力与权威的来源或表现形式", "lesson": "S1M2K4"}, "正式法源（Formal Sources）": {"term": "正式法源（Formal Sources）", "def": "被法律体系明确承认可直接援引的法源", "lesson": "S1M2K4"}, "非正式法源（Informal Sources）": {"term": "非正式法源（Informal Sources）", "def": "学理、惯例等有影响力但不具正式约束力的材料", "lesson": "S1M2K4"}, "效力层级（Hierarchy of Norms）": {"term": "效力层级（Hierarchy of Norms）", "def": "规范依效力高低排列形成的等级序列", "lesson": "S1M2K4"}, "渊源命题（Sources Thesis）": {"term": "渊源命题（Sources Thesis）", "def": "拉兹主张法律的识别应诉诸社会来源而非道德价值的命题", "lesson": "S1M2K4"}, "Lex Superior": {"term": "Lex Superior", "def": "上位法优于下位法的冲突规则", "lesson": "S1M2K4"}, "Lex Posterior": {"term": "Lex Posterior", "def": "后法优于前法的冲突规则", "lesson": "S1M2K4"}, "Lex Specialis": {"term": "Lex Specialis", "def": "特别法优于一般法的冲突规则", "lesson": "S1M2K4"}, "普通法（Common Law）": {"term": "普通法（Common Law）", "def": "以英国法为基础、以判例为主干渊源的法律传统", "lesson": "S1M2K5"}, "大陆法（Civil Law）": {"term": "大陆法（Civil Law）", "def": "受欧洲大陆罗马法传统影响、以法典为核心渊源的法律传统", "lesson": "S1M2K5"}, "令状（Writs）": {"term": "令状（Writs）", "def": "中世纪英格兰标准化的诉讼形式，普通法由此生长", "lesson": "S1M2K5"}, "先例约束（Stare Decisis）": {"term": "先例约束（Stare Decisis）", "def": "既往判决对后续案件具有约束力的原则", "lesson": "S1M2K5"}, "法院组织（Court Organisation）": {"term": "法院组织（Court Organisation）", "def": "不同法系在普通法院与专门法院之间的制度安排差异", "lesson": "S1M2K5"}, "相似推定（Praesumptio Similitudinis）": {"term": "相似推定（Praesumptio Similitudinis）", "def": "茨威格特与科茨提出的、发达国家法律实务结果往往相似的命题", "lesson": "S1M2K5"}, "法律规范（Legal Norm）": {"term": "法律规范（Legal Norm）", "def": "规定人们在特定条件下应当如何行为的标准", "lesson": "S1M2K6"}, "行为模式（Pattern of Behaviour）": {"term": "行为模式（Pattern of Behaviour）", "def": "法律规范中规定可以、应当或禁止如何行为的部分", "lesson": "S1M2K6"}, "法律后果（Legal Consequence）": {"term": "法律后果（Legal Consequence）", "def": "法律规范中规定遵守或违反时产生何种结果的部分", "lesson": "S1M2K6"}, "义务规则（Duty-imposing Rules）": {"term": "义务规则（Duty-imposing Rules）", "def": "要求人们做或不做特定行为的规则", "lesson": "S1M2K6"}, "授权规则（Power-conferring Rules）": {"term": "授权规则（Power-conferring Rules）", "def": "赋予人们改变法律地位之能力的规则", "lesson": "S1M2K6"}, "法律原则（Legal Principles）": {"term": "法律原则（Legal Principles）", "def": "以『分量』而非全有全无方式起作用的评价标准", "lesson": "S1M2K6"}, "开放结构（Open Texture）": {"term": "开放结构（Open Texture）", "def": "语言在核心明确之外总存在边界模糊情形的特性", "lesson": "S1M2K6"}, "临界案件（Penumbral Cases）": {"term": "临界案件（Penumbral Cases）", "def": "语言适用与否不确定的边缘情形", "lesson": "S1M2K6"}, "权利（Right）": {"term": "权利（Right）", "def": "法律上主体可主张的利益、自由、权力或豁免", "lesson": "S1M3K1"}, "义务（Duty）": {"term": "义务（Duty）", "def": "法律要求主体为或不为一定行为的约束", "lesson": "S1M3K1"}, "主张权（Claim Right）": {"term": "主张权（Claim Right）", "def": "与他人义务相对应的权利，是狭义的『权利』", "lesson": "S1M3K1"}, "自由权（Liberty/Privilege）": {"term": "自由权（Liberty/Privilege）", "def": "主体可为或不为某事而他人不负相应义务", "lesson": "S1M3K1"}, "权力（Power）": {"term": "权力（Power）", "def": "主体通过其意志改变他人法律地位的能力", "lesson": "S1M3K1"}, "豁免（Immunity）": {"term": "豁免（Immunity）", "def": "主体不受他人权力改变其法律地位的状态", "lesson": "S1M3K1"}, "相关性（Correlativity）": {"term": "相关性（Correlativity）", "def": "权利与义务如同一枚硬币的两面，一方存在意味着另一方存在", "lesson": "S1M3K1"}, "意志论（Will Theory）": {"term": "意志论（Will Theory）", "def": "以主体能否支配义务履行为权利本质的理论", "lesson": "S1M3K1"}, "利益论（Interest Theory）": {"term": "利益论（Interest Theory）", "def": "以保护权利人的利益为权利目的的理论", "lesson": "S1M3K1"}, "自由（Liberty/Freedom）": {"term": "自由（Liberty/Freedom）", "def": "主体可按自己意志行动而不受外部强制的状态", "lesson": "S1M3K2"}, "消极自由（Negative Liberty）": {"term": "消极自由（Negative Liberty）", "def": "免于他人或国家干涉的自由", "lesson": "S1M3K2"}, "积极自由（Positive Liberty）": {"term": "积极自由（Positive Liberty）", "def": "主体得以自我实现、参与自治的实质能力", "lesson": "S1M3K2"}, "责任（Responsibility）": {"term": "责任（Responsibility）", "def": "主体因其行为而应承受法律评价或后果的地位", "lesson": "S1M3K2"}, "强制（Coercion）": {"term": "强制（Coercion）", "def": "以威胁或不利后果迫使他人行动", "lesson": "S1M3K2"}, "必要性抗辩（Defence of Necessity）": {"term": "必要性抗辩（Defence of Necessity）", "def": "为避免更大损害而实施通常违法行为的抗辩事由", "lesson": "S1M3K2"}, "言论自由（Freedom of Expression）": {"term": "言论自由（Freedom of Expression）", "def": "表达思想与意见而不受不当限制的自由", "lesson": "S1M3K2"}, "法律主体（Legal Subject）": {"term": "法律主体（Legal Subject）", "def": "能享有权利、承担义务并参与法律关系的主体", "lesson": "S1M3K3"}, "自然人（Natural Person）": {"term": "自然人（Natural Person）", "def": "基于出生而取得法律人格的人", "lesson": "S1M3K3"}, "法律主体资格（Legal Personality）": {"term": "法律主体资格（Legal Personality）", "def": "作为权利义务承载者的法律地位", "lesson": "S1M3K3"}, "权利能力（Legal Capacity）": {"term": "权利能力（Legal Capacity）", "def": "作为权利义务主体的法律资格", "lesson": "S1M3K3"}, "行为能力（Capacity to Act）": {"term": "行为能力（Capacity to Act）", "def": "以自己的行为独立取得权利、承担义务的能力", "lesson": "S1M3K3"}, "法人（Juridical/Legal Person）": {"term": "法人（Juridical/Legal Person）", "def": "法律拟制的人，可独立享有权利与承担义务", "lesson": "S1M3K3"}, "无能力（Disability/Incapacity）": {"term": "无能力（Disability/Incapacity）", "def": "法律上不能独立实施有效法律行为的状态", "lesson": "S1M3K3"}, "法律人格（Legal Personality）": {"term": "法律人格（Legal Personality）", "def": "作为权利义务主体的法律地位与资格", "lesson": "S1M3K4"}, "自然人人格（Natural Personality）": {"term": "自然人人格（Natural Personality）", "def": "基于出生而取得的、每个人平等享有的法律人格", "lesson": "S1M3K4"}, "法人人格（Juridical Personality）": {"term": "法人人格（Juridical Personality）", "def": "法律拟制的人所享有的独立主体地位", "lesson": "S1M3K4"}, "独立人格（Separate Personality）": {"term": "独立人格（Separate Personality）", "def": "法人与其成员在法律上相互区分的状态", "lesson": "S1M3K4"}, "有限责任（Limited Liability）": {"term": "有限责任（Limited Liability）", "def": "股东仅以出资额为限对公司债务承担责任", "lesson": "S1M3K4"}, "揭开公司面纱（Piercing the Corporate Veil）": {"term": "揭开公司面纱（Piercing the Corporate Veil）", "def": "在人格被滥用时否认法人独立地位、追究成员责任的制度", "lesson": "S1M3K4"}, "人格权（Personality Rights）": {"term": "人格权（Personality Rights）", "def": "保护主体人格利益的权利", "lesson": "S1M3K4"}, "法律责任（Legal Liability）": {"term": "法律责任（Legal Liability）", "def": "主体因违反义务或造成法定损害而应承受的不利法律后果", "lesson": "S1M3K5"}, "义务（Obligation/Duty）": {"term": "义务（Obligation/Duty）", "def": "法律要求主体为或不为一定行为的约束", "lesson": "S1M3K5"}, "归责（Imputation/Attribution）": {"term": "归责（Imputation/Attribution）", "def": "将损害或行为归于特定主体并使其承担责任的过程", "lesson": "S1M3K5"}, "过失责任（Fault Liability）": {"term": "过失责任（Fault Liability）", "def": "以过错为承担责任前提的归责原则", "lesson": "S1M3K5"}, "严格责任（Strict Liability）": {"term": "严格责任（Strict Liability）", "def": "不以过错为前提、只要造成损害即承担的责任", "lesson": "S1M3K5"}, "因果关系（Causation）": {"term": "因果关系（Causation）", "def": "行为与损害之间的引起与被引起关系", "lesson": "S1M3K5"}, "无效（Nullity）": {"term": "无效（Nullity）", "def": "法律行为因欠缺要件而不产生预期效果", "lesson": "S1M3K5"}, "法律效力（Legal Validity）": {"term": "法律效力（Legal Validity）", "def": "一项规则或行为在法律体系内被承认为有效、具有约束力的属性", "lesson": "S1M3K6"}, "有效性标准（Criteria of Validity）": {"term": "有效性标准（Criteria of Validity）", "def": "判断一项规则是否属于法律的依据", "lesson": "S1M3K6"}, "基础规范（Grundnorm/Basic Norm）": {"term": "基础规范（Grundnorm/Basic Norm）", "def": "凯尔森理论中法律体系效力的终极预设", "lesson": "S1M3K6"}, "无效（Invalidity/Nullity）": {"term": "无效（Invalidity/Nullity）", "def": "法律行为或规则不发生预期法律效力的状态", "lesson": "S1M3K6"}, "法律事实（Legal Facts）": {"term": "法律事实（Legal Facts）", "def": "被法律规则赋予法律意义、能够引起法律后果的事实", "lesson": "S1M3K7"}, "事件（Event）": {"term": "事件（Event）", "def": "不以当事人意志为转移而能引起法律后果的事实", "lesson": "S1M3K7"}, "行为（Act）": {"term": "行为（Act）", "def": "以当事人意志为转移、能引起法律后果的事实", "lesson": "S1M3K7"}, "事实认定（Fact-finding）": {"term": "事实认定（Fact-finding）", "def": "确定案件事实是否成立的司法过程", "lesson": "S1M3K7"}, "举证责任（Burden of Proof）": {"term": "举证责任（Burden of Proof）", "def": "由哪一方承担证明事实存在的责任", "lesson": "S1M3K7"}, "司法认知（Judicial Notice）": {"term": "司法认知（Judicial Notice）", "def": "法院对某些显著事实无须证明即可认定", "lesson": "S1M3K7"}, "法律关系（Legal Relation）": {"term": "法律关系（Legal Relation）", "def": "法律规则调整主体之间形成的权利义务联系", "lesson": "S1M3K8"}, "法律地位（Legal Position）": {"term": "法律地位（Legal Position）", "def": "主体在法律关系中所处的权利义务状态", "lesson": "S1M3K8"}, "对物权/对人权（Right in Rem / Right in Personam）": {"term": "对物权/对人权（Right in Rem / Right in Personam）", "def": "可对抗所有人或仅可对抗特定人的权利", "lesson": "S1M3K8"}, "法律关系三要素（Three Elements）": {"term": "法律关系三要素（Three Elements）", "def": "法律关系的主体、客体与内容", "lesson": "S1M3K8"}, "正义（Justice）": {"term": "正义（Justice）", "def": "给予每个人应得之物、使相同案件受到相同处理的社会理想与德性", "lesson": "S1M4K1"}, "应得（Desert）": {"term": "应得（Desert）", "def": "依据功绩、需要或贡献而应获得某种对待的根据", "lesson": "S1M4K1"}, "分配正义（Distributive Justice）": {"term": "分配正义（Distributive Justice）", "def": "关于社会利益与负担如何在成员间分配的正义", "lesson": "S1M4K1"}, "矫正正义（Corrective Justice）": {"term": "矫正正义（Corrective Justice）", "def": "关于矫正错误、补偿损害的正义", "lesson": "S1M4K1"}, "程序正义（Procedural Justice）": {"term": "程序正义（Procedural Justice）", "def": "关于决定过程是否公平的正义", "lesson": "S1M4K1"}, "实体正义（Substantive Justice）": {"term": "实体正义（Substantive Justice）", "def": "关于决定结果与内容是否公正的正义", "lesson": "S1M4K1"}, "自然法（Natural Law）": {"term": "自然法（Natural Law）", "def": "主张法律与道德存在必然联系的理论", "lesson": "S1M4K1"}, "形式正义（Formal Justice）": {"term": "形式正义（Formal Justice）", "def": "规则被一致、公开、无偏私地适用的正义", "lesson": "S1M4K2"}, "正当程序（Due Process）": {"term": "正当程序（Due Process）", "def": "要求国家在剥夺个人生命、自由或财产前遵循公平程序的原则", "lesson": "S1M4K2"}, "自然正义（Natural Justice）": {"term": "自然正义（Natural Justice）", "def": "英美法中要求裁判者中立、听取双方意见的最低程序原则", "lesson": "S1M4K2"}, "内在道德（Internal Morality）": {"term": "内在道德（Internal Morality）", "def": "富勒提出的法律在程序上应具备的最低要求", "lesson": "S1M4K2"}, "功绩（Desert/Merit）": {"term": "功绩（Desert/Merit）", "def": "依据贡献、努力或才能而应得分配份额的根据", "lesson": "S1M4K3"}, "原初状态（Original Position）": {"term": "原初状态（Original Position）", "def": "罗尔斯设想的选择正义原则的虚拟处境", "lesson": "S1M4K3"}, "无知之幕（Veil of Ignorance）": {"term": "无知之幕（Veil of Ignorance）", "def": "使选择者不知自身社会地位与天赋的思想装置", "lesson": "S1M4K3"}, "差别原则（Difference Principle）": {"term": "差别原则（Difference Principle）", "def": "允许不平等仅在有利于最不利者时被接受的原则", "lesson": "S1M4K3"}, "资格理论（Entitlement Theory）": {"term": "资格理论（Entitlement Theory）", "def": "诺齐克主张正义取决于持有物获取与转让历史正当性的理论", "lesson": "S1M4K3"}, "交换正义（Commutative Justice）": {"term": "交换正义（Commutative Justice）", "def": "矫正正义的别称，强调对等交换与返还", "lesson": "S1M4K4"}, "算术的平等（Arithmetical Equality）": {"term": "算术的平等（Arithmetical Equality）", "def": "不问身份高低、对当事人一律平等对待的平等观", "lesson": "S1M4K4"}, "报应正义（Retributive Justice）": {"term": "报应正义（Retributive Justice）", "def": "主张刑罚正当性在于罪责与应报的正义理论", "lesson": "S1M4K4"}, "补偿正义（Compensatory Justice）": {"term": "补偿正义（Compensatory Justice）", "def": "主张以赔偿使受害者恢复原状的正义理论", "lesson": "S1M4K4"}, "过错责任（Fault Liability）": {"term": "过错责任（Fault Liability）", "def": "以过错作为承担责任基础的归责原则", "lesson": "S1M4K4"}, "平等原则（Principle of Equality）": {"term": "平等原则（Principle of Equality）", "def": "要求相同情况相同对待、禁止任意差别对待的基本法律原则", "lesson": "S1M4K5"}, "形式平等（Formal Equality）": {"term": "形式平等（Formal Equality）", "def": "要求规则一致适用、不因身份而区别对待的平等观", "lesson": "S1M4K5"}, "实质平等（Substantive Equality）": {"term": "实质平等（Substantive Equality）", "def": "要求考虑实际处境差异、通过差别对待实现真正公平的平等观", "lesson": "S1M4K5"}, "平等保护（Equal Protection）": {"term": "平等保护（Equal Protection）", "def": "美国宪法第十四修正案要求各州对任何人提供平等法律保护的原则", "lesson": "S1M4K5"}, "政治完整性（Political Integrity）": {"term": "政治完整性（Political Integrity）", "def": "德沃金提出的政府须依普遍适用于所有人的原则治理的价值", "lesson": "S1M4K5"}, "法律公平（Legal Fairness）": {"term": "法律公平（Legal Fairness）", "def": "法律制度在规则制定与适用中所体现的公平，包括程序中立与平等适用", "lesson": "S1M4K6"}, "社会公平（Social Fairness）": {"term": "社会公平（Social Fairness）", "def": "社会在利益、机会与负担分配上达到的实质公平状态", "lesson": "S1M4K6"}, "实质正义（Substantive Justice）": {"term": "实质正义（Substantive Justice）", "def": "结果与内容本身公正的正义", "lesson": "S1M4K6"}, "依法统治（Rule by Law）": {"term": "依法统治（Rule by Law）", "def": "把法律仅当作统治工具、法律本身不受约束的治理方式", "lesson": "S1M5K1"}, "法律至上（Supremacy of Law）": {"term": "法律至上（Supremacy of Law）", "def": "戴雪法治理论的第一层含义，即法律高于专断权力", "lesson": "S1M5K1"}, "形式法治（Formal Rule of Law）": {"term": "形式法治（Formal Rule of Law）", "def": "强调规则的一般性、公开性、明确性与不溯及既往的法治观", "lesson": "S1M5K1"}, "实质法治（Substantive Rule of Law）": {"term": "实质法治（Substantive Rule of Law）", "def": "要求法律内容本身符合正义与人权保障的法治观", "lesson": "S1M5K1"}, "否定性德性（Negative Virtue）": {"term": "否定性德性（Negative Virtue）", "def": "拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立的道德价值", "lesson": "S1M5K1"}, "法律面前人人平等（Equality Before the Law）": {"term": "法律面前人人平等（Equality Before the Law）", "def": "所有人同受法律约束、同受法律保护、不因身份享有特权或遭受歧视的原则", "lesson": "S1M5K2"}, "特权（Privilege）": {"term": "特权（Privilege）", "def": "特定身份或群体享有的、不受普遍法律约束的特殊权利", "lesson": "S1M5K2"}, "法律明确性（Legal Clarity/Certainty）": {"term": "法律明确性（Legal Clarity/Certainty）", "def": "法律规则应当清晰、确定、可被理解地表达的要求", "lesson": "S1M5K3"}, "可预测性（Predictability）": {"term": "可预测性（Predictability）", "def": "人们能够依据法律预先安排行为并预期其法律后果的性质", "lesson": "S1M5K3"}, "不溯及既往（Non-retroactivity）": {"term": "不溯及既往（Non-retroactivity）", "def": "法律只适用于其生效后发生的行为、不得追诉既往行为的要求", "lesson": "S1M5K3"}, "法的明确性原则（Principle of Legal Certainty）": {"term": "法的明确性原则（Principle of Legal Certainty）", "def": "要求法律内容清楚、稳定且可被公民据以规划行为的原则", "lesson": "S1M5K3"}, "模糊无效（Void for Vagueness）": {"term": "模糊无效（Void for Vagueness）", "def": "美国法中因法律用语过于模糊而宣告其违宪的原则", "lesson": "S1M5K3"}, "司法独立（Judicial Independence）": {"term": "司法独立（Judicial Independence）", "def": "法院与法官在裁判时不受行政、立法及私人不当影响的状态", "lesson": "S1M5K4"}, "分权（Separation of Powers）": {"term": "分权（Separation of Powers）", "def": "立法、行政、司法三种权力由不同机关行使的宪制原则", "lesson": "S1M5K4"}, "司法问责（Judicial Accountability）": {"term": "司法问责（Judicial Accountability）", "def": "法官须对其裁判行为承担责任、接受监督的要求", "lesson": "S1M5K4"}, "职业法官（Career Judge）": {"term": "职业法官（Career Judge）", "def": "在民法法系中经专门训练、按等级晋升的法官类型", "lesson": "S1M5K4"}, "司法能动主义（Judicial Activism）": {"term": "司法能动主义（Judicial Activism）", "def": "法院积极介入政策与权利保护的司法倾向", "lesson": "S1M5K4"}, "司法克制（Judicial Restraint）": {"term": "司法克制（Judicial Restraint）", "def": "法院尊重民选机关决定、审慎行使审查权的司法倾向", "lesson": "S1M5K4"}, "权力受法律约束（Power Bound by Law）": {"term": "权力受法律约束（Power Bound by Law）", "def": "国家权力的存在与行使均须有法律依据并受法律限制的原则", "lesson": "S1M5K5"}, "越权无效（Ultra Vires）": {"term": "越权无效（Ultra Vires）", "def": "行政机关超越法定权限的行为无效的原则", "lesson": "S1M5K5"}, "自由裁量（Discretion）": {"term": "自由裁量（Discretion）", "def": "在法律授权范围内由官员酌情判断的权力", "lesson": "S1M5K5"}, "消极德性（Negative Virtue）": {"term": "消极德性（Negative Virtue）", "def": "拉兹对法治的定位，指法治能减少专断权力之害但不赋予法律独立道德价值", "lesson": "S1M5K5"}, "程序正当性（Procedural Propriety）": {"term": "程序正当性（Procedural Propriety）", "def": "权力行使的过程应当公平、中立、公开并保障参与的要求", "lesson": "S1M5K6"}, "听证权（Right to be Heard）": {"term": "听证权（Right to be Heard）", "def": "当事人在对其不利的决定作出前获得陈述机会的权利", "lesson": "S1M5K6"}, "程序中立（Impartiality）": {"term": "程序中立（Impartiality）", "def": "裁判者不得有偏私、须平等对待双方的要求", "lesson": "S1M5K6"}, "人治（Rule of Man）": {"term": "人治（Rule of Man）", "def": "权力行使主要取决于统治者个人意志而非普遍规则的治理方式", "lesson": "S1M5K7"}, "贤人政治（Philosopher-King）": {"term": "贤人政治（Philosopher-King）", "def": "柏拉图设想的由智慧统治者治理的理想政体", "lesson": "S1M5K7"}, "专断（Arbitrariness）": {"term": "专断（Arbitrariness）", "def": "权力行使不受规则约束、取决于任意意志的状态", "lesson": "S1M5K7"}, "自然（Physis）": {"term": "自然（Physis）", "def": "古希腊哲学中指事物本性、生长秩序，与人为约定相对", "lesson": "S2M1K1"}, "约定（Nomos）": {"term": "约定（Nomos）", "def": "城邦制定的人为法律与习俗", "lesson": "S2M1K1"}, "宇宙理性（Logos）": {"term": "宇宙理性（Logos）", "def": "斯多葛学派中支配万物的普遍理性法则", "lesson": "S2M1K1"}, "目的论（Teleology）": {"term": "目的论（Teleology）", "def": "以事物内在目的解释其本性与完善状态的思维方式", "lesson": "S2M1K1"}, "法律正义（Legal Justice）": {"term": "法律正义（Legal Justice）", "def": "由城邦制定、可随时代与地方变化的正义", "lesson": "S2M1K2"}, "万民法（Ius Gentium）": {"term": "万民法（Ius Gentium）", "def": "罗马法中据称由各民族共同理性形成、适用于所有民族的法律", "lesson": "S2M1K2"}, "市民法（Ius Civile）": {"term": "市民法（Ius Civile）", "def": "罗马城邦专属、仅适用于罗马公民的法律", "lesson": "S2M1K2"}, "自然法（Ius Naturale）": {"term": "自然法（Ius Naturale）", "def": "罗马法中被认为由自然本身确立、动物与人类共同具有的规则", "lesson": "S2M1K2"}, "永恒法（Eternal Law）": {"term": "永恒法（Eternal Law）", "def": "上帝支配整个宇宙的理性计划", "lesson": "S2M1K3"}, "人法（Human Law）": {"term": "人法（Human Law）", "def": "由人类权威制定的实证法律，其约束力源于自然法", "lesson": "S2M1K3"}, "神法（Divine Law）": {"term": "神法（Divine Law）", "def": "通过《圣经》启示给予的、高于人法与自然法的神圣法律", "lesson": "S2M1K3"}, "分有（Participation）": {"term": "分有（Participation）", "def": "阿奎那用来说明理性生物共享永恒法秩序的核心概念", "lesson": "S2M1K3"}, "实践理性（Practical Reason）": {"term": "实践理性（Practical Reason）", "def": "关于人应当如何行动、追求何种善的理性能力", "lesson": "S2M1K3"}, "格劳秀斯（Hugo Grotius）": {"term": "格劳秀斯（Hugo Grotius）", "def": "十七世纪荷兰法学家，近代国际法与自然法世俗化的关键人物", "lesson": "S2M1K4"}, "即使假设上帝不存在（etiamsi daremus）": {"term": "即使假设上帝不存在（etiamsi daremus）", "def": "格劳秀斯的著名假设，用以说明自然法的有效性不依赖神的意志", "lesson": "S2M1K4"}, "国际法（International Law）": {"term": "国际法（International Law）", "def": "调整国家之间关系的法律体系，格劳秀斯被视为其奠基者之一", "lesson": "S2M1K4"}, "社会契约（Social Contract）": {"term": "社会契约（Social Contract）", "def": "通过同意建立政治权威与法律秩序的理论", "lesson": "S2M1K4"}, "自然权利（Natural Rights）": {"term": "自然权利（Natural Rights）", "def": "人依本性而享有的、先于或独立于国家法律的权利", "lesson": "S2M1K4"}, "法律的内在道德（Inner Morality of Law）": {"term": "法律的内在道德（Inner Morality of Law）", "def": "富勒提出的法律程序性成就标准，包括一般性、公开性、不溯及既往等八项要求", "lesson": "S2M1K5"}, "愿望的道德（Morality of Aspiration）": {"term": "愿望的道德（Morality of Aspiration）", "def": "富勒对内在道德的定性，指法律体系力求达到的卓越标准而非最低义务", "lesson": "S2M1K5"}, "基本善（Basic Goods）": {"term": "基本善（Basic Goods）", "def": "菲尼斯理论中人先天追求、不可再还原的七种根本善", "lesson": "S2M1K5"}, "实践合理性（Practical Reasonableness）": {"term": "实践合理性（Practical Reasonableness）", "def": "菲尼斯理论中统摄基本善追求、回答『我应当做什么』的理性要求", "lesson": "S2M1K5"}, "共同的善（Common Good）": {"term": "共同的善（Common Good）", "def": "共同体成员共享的、使个人善得以实现的社会条件", "lesson": "S2M1K5"}, "实在法（Positive Law）": {"term": "实在法（Positive Law）", "def": "由合法权威按程序制定、以社会事实为存在根据的法律", "lesson": "S2M1K6"}, "必然联系（Necessary Connection）": {"term": "必然联系（Necessary Connection）", "def": "自然法主张法律的性质本身包含道德要求", "lesson": "S2M1K6"}, "拉德布鲁赫公式（Radbruch Formula）": {"term": "拉德布鲁赫公式（Radbruch Formula）", "def": "极端不正义的法律丧失法性质的司法准则", "lesson": "S2M1K6"}, "是—应当问题（Is—Ought Problem）": {"term": "是—应当问题（Is—Ought Problem）", "def": "休谟提出的质疑，即从描述性事实难以逻辑地推出规范性应当", "lesson": "S2M1K7"}, "不确定性（Indeterminacy）": {"term": "不确定性（Indeterminacy）", "def": "自然法原则在具体适用中难以得出唯一确定结论的批评", "lesson": "S2M1K7"}, "硬自然法（Hard Natural Law）": {"term": "硬自然法（Hard Natural Law）", "def": "主张不正义法律丧失法资格的强版本", "lesson": "S2M1K7"}, "软自然法（Soft Natural Law）": {"term": "软自然法（Soft Natural Law）", "def": "承认不正义法律仍为法但丧失服从义务的版本", "lesson": "S2M1K7"}, "法律安定性（Legal Certainty）": {"term": "法律安定性（Legal Certainty）", "def": "法律应提供明确、可预测的行为指引的价值", "lesson": "S2M1K7"}, "法的有效性（Legal Validity）": {"term": "法的有效性（Legal Validity）", "def": "一项规则是否属于特定法律体系的问题", "lesson": "S2M2K1"}, "功利主义（Utilitarianism）": {"term": "功利主义（Utilitarianism）", "def": "以最大多数人的最大幸福为评价标准的伦理理论", "lesson": "S2M2K1"}, "法的确定性（Legal Certainty）": {"term": "法的确定性（Legal Certainty）", "def": "法律应提供明确可预测的行为指引的价值", "lesson": "S2M2K1"}, "命令理论（Command Theory）": {"term": "命令理论（Command Theory）", "def": "把法律界定为主权者发布的、以制裁为后盾的命令的理论", "lesson": "S2M2K2"}, "持枪者理论（Gunman Theory）": {"term": "持枪者理论（Gunman Theory）", "def": "哈特对奥斯丁模型的讽刺性概括，指其与匪徒持枪威胁相似", "lesson": "S2M2K2"}, "习惯性服从（Habitual Obedience）": {"term": "习惯性服从（Habitual Obedience）", "def": "奥斯丁用以说明主权者地位的事实性概念", "lesson": "S2M2K2"}, "纯粹法学（Pure Theory of Law）": {"term": "纯粹法学（Pure Theory of Law）", "def": "凯尔森主张的、排除道德社会学等混杂因素的法律理论", "lesson": "S2M2K3"}, "基础规范（Grundnorm / Basic Norm）": {"term": "基础规范（Grundnorm / Basic Norm）", "def": "法律体系中作为效力最终根据的被假定的最高规范", "lesson": "S2M2K3"}, "规范层级（Hierarchy of Norms）": {"term": "规范层级（Hierarchy of Norms）", "def": "由基础规范向下授权构成的规范性等级结构", "lesson": "S2M2K3"}, "实效（Efficacy）": {"term": "实效（Efficacy）", "def": "规范被实际遵守和适用的事实状态", "lesson": "S2M2K3"}, "应当（Sollen）": {"term": "应当（Sollen）", "def": "凯尔森用以界定法律规范的规范性范畴，与描述事实的『是』相对", "lesson": "S2M2K3"}, "道德正当性（Moral Legitimacy）": {"term": "道德正当性（Moral Legitimacy）", "def": "法律在道德上是否值得服从的性质", "lesson": "S2M2K5"}, "排他实证主义（Exclusive Positivism）": {"term": "排他实证主义（Exclusive Positivism）", "def": "坚持道德不能构成法律效力条件的实证主义版本", "lesson": "S2M2K6"}, "承诺性陈述（Committed Statements）": {"term": "承诺性陈述（Committed Statements）", "def": "从法律体系内部接受其法律有效性的陈述", "lesson": "S2M2K6"}, "超脱性陈述（Detached Statements）": {"term": "超脱性陈述（Detached Statements）", "def": "描述法律主张而不予接受的陈述", "lesson": "S2M2K6"}, "整体性（Integrity）": {"term": "整体性（Integrity）", "def": "德沃金解释性法理学的核心德性，要求把法律实践理解为连贯的整体", "lesson": "S2M2K7"}, "规则怀疑论（Rule Skepticism）": {"term": "规则怀疑论（Rule Skepticism）", "def": "怀疑规则能决定案件结果的法律现实主义立场", "lesson": "S2M2K7"}, "价值中立（Value Neutrality）": {"term": "价值中立（Value Neutrality）", "def": "实证主义追求的描述性理想，即不承诺特定道德立场", "lesson": "S2M2K7"}, "法的安定性（Legal Certainty）": {"term": "法的安定性（Legal Certainty）", "def": "法律应提供明确稳定行为指引的价值", "lesson": "S2M2K7"}, "美国法律现实主义（American Legal Realism）": {"term": "美国法律现实主义（American Legal Realism）", "def": "二十世纪美国以经验与实践为取向、怀疑形式主义的法律理论运动", "lesson": "S2M3K1"}, "事实怀疑论（Fact Skepticism）": {"term": "事实怀疑论（Fact Skepticism）", "def": "怀疑审判中事实认定可靠性的立场", "lesson": "S2M3K1"}, "行动中的法（Law in Action）": {"term": "行动中的法（Law in Action）", "def": "法律在实际运作中的样子，与书本上的法相对", "lesson": "S2M3K1"}, "形式主义（Formalism）": {"term": "形式主义（Formalism）", "def": "相信法律决定可由规则逻辑地推出的司法理念", "lesson": "S2M3K1"}, "斯堪的纳维亚法律现实主义（Scandinavian Legal Realism）": {"term": "斯堪的纳维亚法律现实主义（Scandinavian Legal Realism）", "def": "以形而上学批判为核心、拒斥自然法与规范形而上学的北欧法律理论", "lesson": "S2M3K2"}, "形而上学怀疑论（Metaphysics-scepticism）": {"term": "形而上学怀疑论（Metaphysics-scepticism）", "def": "拒斥不可经验验证的法律实体与抽象规范概念的立场", "lesson": "S2M3K2"}, "独立命令（Independent Imperatives）": {"term": "独立命令（Independent Imperatives）", "def": "奥利弗克罗纳用以描述法律规则的命令性命题", "lesson": "S2M3K2"}, "社会福利（Social Welfare）": {"term": "社会福利（Social Welfare）", "def": "朗兹特用以说明法律目的的核心概念", "lesson": "S2M3K2"}, "象棋类比（Chess Analogy）": {"term": "象棋类比（Chess Analogy）", "def": "罗斯用以说明规则与社会实践关系的著名比喻", "lesson": "S2M3K2"}, "司法裁量（Judicial Discretion）": {"term": "司法裁量（Judicial Discretion）", "def": "法官在规则不确定的地带作出选择的余地", "lesson": "S2M3K3"}, "稳定性因素（Steadying Factors）": {"term": "稳定性因素（Steadying Factors）", "def": "约束法官判断、使裁判可预期的制度与职业因素", "lesson": "S2M3K3"}, "书本上的法（Law in Books）": {"term": "书本上的法（Law in Books）", "def": "以文本形式存在的法律规则", "lesson": "S2M3K4"}, "法律社会学（Sociology of Law）": {"term": "法律社会学（Sociology of Law）", "def": "以经验方法研究法律与社会关系的学科", "lesson": "S2M3K4"}, "法律移植（Legal Transplant）": {"term": "法律移植（Legal Transplant）", "def": "法律制度从一个社会向另一个社会的移转", "lesson": "S2M3K4"}, "批判法学运动（Critical Legal Studies, CLS）": {"term": "批判法学运动（Critical Legal Studies, CLS）", "def": "二十世纪七十年代美国兴起的、以马克思主义与跨学科方法批判法律中立性的运动", "lesson": "S2M3K5"}, "法律不确定性（Legal Indeterminacy）": {"term": "法律不确定性（Legal Indeterminacy）", "def": "法律规则与教义无法确定地决定裁判结果的主张", "lesson": "S2M3K5"}, "拆解（Trashing）": {"term": "拆解（Trashing）", "def": "CLS 用以揭示法律概念内在矛盾与政治性的批判方法", "lesson": "S2M3K5"}, "意识形态霸权（Ideological Hegemony）": {"term": "意识形态霸权（Ideological Hegemony）", "def": "葛兰西提出的、统治观念借文化与制度取得支配地位的观念", "lesson": "S2M3K5"}, "共同体主义转向（Communitarian Move）": {"term": "共同体主义转向（Communitarian Move）", "def": "CLS 与社群主义共享的、强调共同体价值的理论取向", "lesson": "S2M3K5"}, "权力结构（Power Structures）": {"term": "权力结构（Power Structures）", "def": "社会中资源、地位与影响力的制度化分配格局", "lesson": "S2M3K6"}, "法律工具论（Instrumental View of Law）": {"term": "法律工具论（Instrumental View of Law）", "def": "把法律视为统治阶级或强势集团工具的立场", "lesson": "S2M3K6"}, "法律拜物教（Legal Fetishism）": {"term": "法律拜物教（Legal Fetishism）", "def": "把法律当作独立自足的神秘实体的观念", "lesson": "S2M3K6"}, "比较法（Comparative Law）": {"term": "比较法（Comparative Law）", "def": "对两个或两个以上法律体系、制度或规则进行比较研究的学科与方法", "lesson": "S2M4K1"}, "功能等价物（Functional Equivalent）": {"term": "功能等价物（Functional Equivalent）", "def": "不同法律体系中解决同一社会问题的不同制度或规则", "lesson": "S2M4K1"}, "法律文化（Legal Culture）": {"term": "法律文化（Legal Culture）", "def": "一个共同体中关于法律的价值观念、思维习惯与行为模式", "lesson": "S2M4K1"}, "宏观比较（Macro-comparison）": {"term": "宏观比较（Macro-comparison）", "def": "对整个法律体系或法律家族进行的比较", "lesson": "S2M4K1"}, "微观比较（Micro-comparison）": {"term": "微观比较（Micro-comparison）", "def": "对具体法律规则或个案进行的比较", "lesson": "S2M4K1"}, "明示的比较法（Explicit Comparative Law）": {"term": "明示的比较法（Explicit Comparative Law）", "def": "以比较为自觉目的系统展开的学术研究", "lesson": "S2M4K1"}, "默示的比较法（Implicit Comparative Law）": {"term": "默示的比较法（Implicit Comparative Law）", "def": "在社会科学研究中不那么自觉地运用的比较视角", "lesson": "S2M4K1"}, "语境化（Contextualisation）": {"term": "语境化（Contextualisation）", "def": "把法律规则放回其政治经济社会环境中理解的研究取向", "lesson": "S2M4K1"}, "罗马法继受（Reception of Roman Law）": {"term": "罗马法继受（Reception of Roman Law）", "def": "中世纪后期欧洲大陆重新采纳罗马法的历史过程", "lesson": "S2M4K2"}, "共同法（Ius Commune）": {"term": "共同法（Ius Commune）", "def": "中世纪欧洲超越国界的通用法律传统", "lesson": "S2M4K2"}, "法律家族（Legal Family）": {"term": "法律家族（Legal Family）", "def": "基于共同历史、思维与规则而划分的国家法律群体", "lesson": "S2M4K2"}, "法律起源（Legal Origins）": {"term": "法律起源（Legal Origins）", "def": "经济学与政治学用法律传统解释经济绩效的研究路径", "lesson": "S2M4K2"}, "法律传统（Legal Tradition）": {"term": "法律传统（Legal Tradition）", "def": "与法律家族相近、强调历史连续性的分类单位", "lesson": "S2M4K3"}, "混合体系（Hybrid/Mixed Legal System）": {"term": "混合体系（Hybrid/Mixed Legal System）", "def": "融合两种或两种以上法律传统的制度", "lesson": "S2M4K3"}, "罗马法族（Romanist Group）": {"term": "罗马法族（Romanist Group）", "def": "以法国民法典为范本的大陆法分支", "lesson": "S2M4K3"}, "日耳曼法族（Germanic Group）": {"term": "日耳曼法族（Germanic Group）", "def": "以德国民法典为范本的大陆法分支", "lesson": "S2M4K3"}, "法律起源理论（Legal Origins Theory）": {"term": "法律起源理论（Legal Origins Theory）", "def": "用法律传统的差异解释经济与制度绩效的研究路径", "lesson": "S2M4K3"}, "法律借用（Legal Borrowing）": {"term": "法律借用（Legal Borrowing）", "def": "移植的另一种说法，强调主动采纳外国法", "lesson": "S2M4K4"}, "输入的法（Law in Context）": {"term": "输入的法（Law in Context）", "def": "需要结合社会语境理解的法律", "lesson": "S2M4K4"}, "法律刺激物（Legal Irritant）": {"term": "法律刺激物（Legal Irritant）", "def": "Teubner 用语，指外来规则进入本土体系后引发的扰动", "lesson": "S2M4K4"}, "法律移植的不可能性（Impossibility of Legal Transplants）": {"term": "法律移植的不可能性（Impossibility of Legal Transplants）", "def": "Legrand 的主张，认为规则在移植中必然因解释而改变", "lesson": "S2M4K4"}, "合法性生成型移植（Legitimacy-generating Transplant）": {"term": "合法性生成型移植（Legitimacy-generating Transplant）", "def": "为获取声望或现代性象征而采纳外国法的移植", "lesson": "S2M4K4"}, "法律趋同（Convergence of Laws）": {"term": "法律趋同（Convergence of Laws）", "def": "不同法律体系的法律现象随时间变得更加相似的趋势", "lesson": "S2M4K5"}, "法律分化（Legal Divergence）": {"term": "法律分化（Legal Divergence）", "def": "法律体系之间差异扩大或维持的趋势", "lesson": "S2M4K5"}, "协调/统一（Harmonisation）": {"term": "协调/统一（Harmonisation）", "def": "以刻意规划推动法律规则统一的过程", "lesson": "S2M4K5"}, "功能趋同（Functional Convergence）": {"term": "功能趋同（Functional Convergence）", "def": "不同法律规则产生可比效果而形成的趋同", "lesson": "S2M4K5"}, "形式趋同（Formal Convergence）": {"term": "形式趋同（Formal Convergence）", "def": "法律规则文本趋于一致", "lesson": "S2M4K5"}, "西方化（Westernisation）": {"term": "西方化（Westernisation）", "def": "非西方法律体系采纳西方法律模式的现象", "lesson": "S2M4K5"}, "区域化（Regionalisation）": {"term": "区域化（Regionalisation）", "def": "在区域层面形成共同法律规则的过程", "lesson": "S2M4K5"}, "跨国化（Transnationalisation）": {"term": "跨国化（Transnationalisation）", "def": "超越国家框架的私法规则形成过程", "lesson": "S2M4K5"}, "令状（Writ）": {"term": "令状（Writ）", "def": "中世纪英格兰开启诉讼的标准化司法文书", "lesson": "S2M5K1"}, "衡平法（Equity）": {"term": "衡平法（Equity）", "def": "由大法官发展、用以补救普通法僵化的法律体系", "lesson": "S2M5K1"}, "遵循先例（Stare Decisis）": {"term": "遵循先例（Stare Decisis）", "def": "法院受先前判决约束的原则", "lesson": "S2M5K1"}, "判决理由（Ratio Decidendi）": {"term": "判决理由（Ratio Decidendi）", "def": "判决中具有约束力的核心法律理由", "lesson": "S2M5K1"}, "附带意见（Obiter Dicta）": {"term": "附带意见（Obiter Dicta）", "def": "判决中不具有约束力的附带表述", "lesson": "S2M5K1"}, "对抗制（Adversarial System）": {"term": "对抗制（Adversarial System）", "def": "由当事人主导举证与质证的程序模式", "lesson": "S2M5K1"}, "国法大全（Corpus Juris Civilis）": {"term": "国法大全（Corpus Juris Civilis）", "def": "查士丁尼主持编纂的罗马法汇编", "lesson": "S2M5K2"}, "三段论（Syllogism）": {"term": "三段论（Syllogism）", "def": "大陆法裁判的大前提—小前提—结论推理模式", "lesson": "S2M5K2"}, "涵摄（Subsumption）": {"term": "涵摄（Subsumption）", "def": "把具体事实归入抽象法律规则的操作", "lesson": "S2M5K2"}, "职权主义（Inquisitorial）": {"term": "职权主义（Inquisitorial）", "def": "法官在查明事实中发挥主动作用的程序模式", "lesson": "S2M5K2"}, "德国民法典（Bürgerliches Gesetzbuch, BGB）": {"term": "德国民法典（Bürgerliches Gesetzbuch, BGB）", "def": "1900 年生效的德国民法典，以概念化体系著称", "lesson": "S2M5K3"}, "潘德克顿学派（Pandectists）": {"term": "潘德克顿学派（Pandectists）", "def": "十九世纪德国罗马法学者，主张以概念体系重构法律", "lesson": "S2M5K3"}, "概念法学（Begriffsjurisprudenz）": {"term": "概念法学（Begriffsjurisprudenz）", "def": "强调概念体系与逻辑演绎的法学方法", "lesson": "S2M5K3"}, "教义学（Dogmatik）": {"term": "教义学（Dogmatik）", "def": "对现行法进行体系化解释与理论建构的学问", "lesson": "S2M5K3"}, "总则（Allgemeiner Teil）": {"term": "总则（Allgemeiner Teil）", "def": "民法典中统辖各编的抽象一般规则部分", "lesson": "S2M5K3"}, "法律行为（Rechtsgeschäft）": {"term": "法律行为（Rechtsgeschäft）", "def": "以意思表示为核心、旨在产生法律效果的行为", "lesson": "S2M5K3"}, "通说（Herrschende Lehre）": {"term": "通说（Herrschende Lehre）", "def": "德国法学中被普遍接受的主流学说", "lesson": "S2M5K3"}, "法国民法典（Code Civil / Code Napoléon）": {"term": "法国民法典（Code Civil / Code Napoléon）", "def": "1804 年颁布、以简明清晰著称的法国民法典", "lesson": "S2M5K4"}, "拿破仑法典（Code Napoléon）": {"term": "拿破仑法典（Code Napoléon）", "def": "法国民法典的别称", "lesson": "S2M5K4"}, "最高行政法院（Conseil d'État）": {"term": "最高行政法院（Conseil d'État）", "def": "法国最高行政法院，公法领域的最高裁判机关", "lesson": "S2M5K4"}, "最高法院（Cour de Cassation）": {"term": "最高法院（Cour de Cassation）", "def": "法国民刑领域的最高法院", "lesson": "S2M5K4"}, "二元划分（Bifurcation）": {"term": "二元划分（Bifurcation）", "def": "Lasser 用以描述法国政策论证与判决文本分离的概念", "lesson": "S2M5K4"}, "不可抗力（Force Majeure）": {"term": "不可抗力（Force Majeure）", "def": "法国合同法中排除责任的事由", "lesson": "S2M5K4"}, "北欧法（Nordic Law）": {"term": "北欧法（Nordic Law）", "def": "丹麦、瑞典、挪威、芬兰、冰岛等北欧国家的法律传统", "lesson": "S2M5K5"}, "斯堪的纳维亚法（Scandinavian Law）": {"term": "斯堪的纳维亚法（Scandinavian Law）", "def": "北欧法的核心组成部分，常指丹麦、瑞典、挪威三国法", "lesson": "S2M5K5"}, "法律现实主义（Legal Realism）": {"term": "法律现实主义（Legal Realism）", "def": "强调法律社会效果与现实运作的法学思潮", "lesson": "S2M5K5"}, "福利国家模式（Welfare State Model）": {"term": "福利国家模式（Welfare State Model）", "def": "以国家主导社会保障与再分配为特征的治理模式", "lesson": "S2M5K5"}, "混合法律体系（Mixed Legal System）": {"term": "混合法律体系（Mixed Legal System）", "def": "融合两种或两种以上法律传统的制度", "lesson": "S2M5K6"}, "罗马—荷兰法（Roman-Dutch Law）": {"term": "罗马—荷兰法（Roman-Dutch Law）", "def": "源于荷兰、在南非等地沿用的大陆法传统", "lesson": "S2M5K6"}, "民法传统（Civilian Tradition）": {"term": "民法传统（Civilian Tradition）", "def": "大陆法的法律传统", "lesson": "S2M5K6"}, "普通法传统（Common Law Tradition）": {"term": "普通法传统（Common Law Tradition）", "def": "英美法的法律传统", "lesson": "S2M5K6"}, "混合法院（Mixed Court）": {"term": "混合法院（Mixed Court）", "def": "由不同传统法官共同组成的裁判机构", "lesson": "S2M5K6"}, "伊斯兰法（Islamic Law / Sharia）": {"term": "伊斯兰法（Islamic Law / Sharia）", "def": "以古兰经与圣训为基础的伊斯兰法律传统", "lesson": "S2M5K7"}, "教会法（Canon Law）": {"term": "教会法（Canon Law）", "def": "基督教教会制定的法律体系", "lesson": "S2M5K7"}, "世俗化（Secularisation）": {"term": "世俗化（Secularisation）", "def": "法律与宗教制度分离的过程", "lesson": "S2M5K7"}, "专门法院（Specialised Court）": {"term": "专门法院（Specialised Court）", "def": "按案件类型设立的专门审判机构", "lesson": "S2M6K1"}, "普通法院（Ordinary Court）": {"term": "普通法院（Ordinary Court）", "def": "审理一般私刑案件的常规法院", "lesson": "S2M6K1"}, "上诉（Appeal）": {"term": "上诉（Appeal）", "def": "对下级法院裁判的复审程序", "lesson": "S2M6K1"}, "再审模型（Revision Model）": {"term": "再审模型（Revision Model）", "def": "德国式上级法院可替代下级裁判的模式", "lesson": "S2M6K1"}, "撤销模型（Cassation Model）": {"term": "撤销模型（Cassation Model）", "def": "法国式上级法院仅撤销并发回的模式", "lesson": "S2M6K1"}, "陪审团（Jury）": {"term": "陪审团（Jury）", "def": "由普通公民组成、负责事实认定的审判组织", "lesson": "S2M6K1"}, "成文法/制定法（Statute Law）": {"term": "成文法/制定法（Statute Law）", "def": "由立法机关制定的规范性文件", "lesson": "S2M6K2"}, "先例（Precedent）": {"term": "先例（Precedent）", "def": "可供后续案件援引的先前判决", "lesson": "S2M6K2"}, "对价（Consideration）": {"term": "对价（Consideration）", "def": "普通法中合同成立所需的价值交换要素", "lesson": "S2M6K3"}, "意思表示合意（Meeting of Minds）": {"term": "意思表示合意（Meeting of Minds）", "def": "大陆法强调的合同主观要素", "lesson": "S2M6K3"}, "善意（Good Faith）": {"term": "善意（Good Faith）", "def": "大陆法的一般合同原则，普通法中争议较大", "lesson": "S2M6K3"}, "实际履行（Specific Performance）": {"term": "实际履行（Specific Performance）", "def": "要求违约方按约履行的救济方式", "lesson": "S2M6K3"}, "有效违约（Efficient Breach）": {"term": "有效违约（Efficient Breach）", "def": "普通法允许以赔偿代替履行的经济逻辑", "lesson": "S2M6K3"}, "缔约过失（Culpa in Contrahendo）": {"term": "缔约过失（Culpa in Contrahendo）", "def": "合同成立前的过失责任", "lesson": "S2M6K3"}, "罚金条款（Penalty Clause）": {"term": "罚金条款（Penalty Clause）", "def": "约定违约时支付款项的条款", "lesson": "S2M6K3"}, "预定损害赔偿（Liquidated Damages）": {"term": "预定损害赔偿（Liquidated Damages）", "def": "对损失的真诚预先估计", "lesson": "S2M6K3"}, "财产权/物权（Property Rights）": {"term": "财产权/物权（Property Rights）", "def": "对物享有并可由法律保护的支配权", "lesson": "S2M6K4"}, "所有权（Ownership）": {"term": "所有权（Ownership）", "def": "对物最全面的支配权", "lesson": "S2M6K4"}, "物权法定（Numerus Clausus）": {"term": "物权法定（Numerus Clausus）", "def": "物权种类由法律限定、当事人不得自由创设的原则", "lesson": "S2M6K4"}, "信托（Trust）": {"term": "信托（Trust）", "def": "普通法中受托人为受益人管理财产的制度", "lesson": "S2M6K4"}, "用益权（Usufruct）": {"term": "用益权（Usufruct）", "def": "大陆法中他人之物上设定的使用收益权利", "lesson": "S2M6K4"}, "先占（Occupation）": {"term": "先占（Occupation）", "def": "通过占有无主物取得所有权的方式", "lesson": "S2M6K4"}, "登记（Registration）": {"term": "登记（Registration）", "def": "不动产权利变动的公示方式", "lesson": "S2M6K4"}, "侵权法（Tort Law）": {"term": "侵权法（Tort Law）", "def": "调整因侵害他人权益而生赔偿责任的私法部门", "lesson": "S2M6K5"}, "可预见性（Foreseeability）": {"term": "可预见性（Foreseeability）", "def": "普通法限定责任范围的概念", "lesson": "S2M6K5"}, "一般条款（General Clause）": {"term": "一般条款（General Clause）", "def": "大陆法民法典中的概括性责任条款", "lesson": "S2M6K5"}, "侵权法功能（Functions of Tort Law）": {"term": "侵权法功能（Functions of Tort Law）", "def": "补偿、威慑与惩罚等目标", "lesson": "S2M6K5"}, "刑事司法（Criminal Justice）": {"term": "刑事司法（Criminal Justice）", "def": "刑事追诉、审判与刑罚执行的制度体系", "lesson": "S2M6K6"}, "职权主义（Inquisitorial System）": {"term": "职权主义（Inquisitorial System）", "def": "法官主导查明事实的刑事程序", "lesson": "S2M6K6"}, "辩诉交易（Plea Bargaining）": {"term": "辩诉交易（Plea Bargaining）", "def": "控辩协商以认罪换取较轻处理的机制", "lesson": "S2M6K6"}, "监禁率（Incarceration Rate）": {"term": "监禁率（Incarceration Rate）", "def": "被监禁人口占总人口的比例", "lesson": "S2M6K6"}, "恢复性司法（Restorative Justice）": {"term": "恢复性司法（Restorative Justice）", "def": "强调修复损害与和解的司法模式", "lesson": "S2M6K6"}, "法律解释（Legal Interpretation）": {"term": "法律解释（Legal Interpretation）", "def": "确定法律规范含义与适用范围的活动", "lesson": "S2M6K7"}, "字面规则（Literal Rule）": {"term": "字面规则（Literal Rule）", "def": "按条文字面含义解释", "lesson": "S2M6K7"}, "黄金规则（Golden Rule）": {"term": "黄金规则（Golden Rule）", "def": "为避免荒谬结果而修正字面含义", "lesson": "S2M6K7"}, "瑕疵规则（Mischief Rule）": {"term": "瑕疵规则（Mischief Rule）", "def": "探求法律欲补救的缺陷", "lesson": "S2M6K7"}, "启示法（Exegetical Method）": {"term": "启示法（Exegetical Method）", "def": "探求立法者意图的解释方法", "lesson": "S2M6K7"}, "目的论方法（Teleological Method）": {"term": "目的论方法（Teleological Method）", "def": "依据法律客观目的的解释", "lesson": "S2M6K7"}, "改变规则（Rules of Change）": {"term": "改变规则（Rules of Change）", "def": "授权制定/修改/废止初级规则的次级规则", "lesson": "S3M1K1"}, "裁判规则（Rules of Adjudication）": {"term": "裁判规则（Rules of Adjudication）", "def": "授权权威判定初级规则是否被违反的次级规则", "lesson": "S3M1K1"}, "终极规则（Ultimate Rule）": {"term": "终极规则（Ultimate Rule）", "def": "自身不再由更高规则授权、其存在体现为社会实践事实的规则", "lesson": "S3M1K2"}, "内部陈述（Internal Statement）": {"term": "内部陈述（Internal Statement）", "def": "从接受规则立场作出的『这是法律』式表述", "lesson": "S3M1K2"}, "外部陈述（External Statement）": {"term": "外部陈述（External Statement）", "def": "Observer 描述他人接受规则的陈述", "lesson": "S3M1K2"}, "软实证主义（Soft Positivism）": {"term": "软实证主义（Soft Positivism）", "def": "承认道德原则可经由承认规则纳入效力判准的立场", "lesson": "S3M1K2"}, "立法权（Legislative Power）": {"term": "立法权（Legislative Power）", "def": "由改变规则授予的制定与废止法律的权力", "lesson": "S3M1K3"}, "司法权（Judicial Power）": {"term": "司法权（Judicial Power）", "def": "由裁判规则授予的权威判定违反事实的权力", "lesson": "S3M1K3"}, "管辖权（Jurisdiction）": {"term": "管辖权（Jurisdiction）", "def": "裁判规则所划定的裁判权限范围", "lesson": "S3M1K3"}, "存在条件（Existence Conditions）": {"term": "存在条件（Existence Conditions）", "def": "判断一个法律体系是否存在的最低事实条件", "lesson": "S3M1K4"}, "双面陈述（Janus-faced Statement）": {"term": "双面陈述（Janus-faced Statement）", "def": "同时指向公民服从与官员接受的存在陈述", "lesson": "S3M1K4"}, "病理（Pathology）": {"term": "病理（Pathology）", "def": "法律体系正常运作条件发生局部失败的状态", "lesson": "S3M1K4"}, "合法性危机（Legitimacy Crisis）": {"term": "合法性危机（Legitimacy Crisis）", "def": "官员对终极判准产生根本分歧的状态", "lesson": "S3M1K4"}, "概念法学（Conceptualism）": {"term": "概念法学（Conceptualism）", "def": "追求概念体系封闭自足的法律思维", "lesson": "S3M1K5"}, "核心地带（Core of Certainty）": {"term": "核心地带（Core of Certainty）", "def": "规则适用毫无疑问的清楚情形", "lesson": "S3M1K5"}, "边缘地带（Penumbra of Doubt）": {"term": "边缘地带（Penumbra of Doubt）", "def": "规则是否适用存在理由冲突的模糊情形", "lesson": "S3M1K5"}, "相对无知的事实（Relative Ignorance of Fact）": {"term": "相对无知的事实（Relative Ignorance of Fact）", "def": "立法者无法预见未来所有情势组合的处境", "lesson": "S3M1K5"}, "目的的相对不确定性（Relative Indeterminacy of Aim）": {"term": "目的的相对不确定性（Relative Indeterminacy of Aim）", "def": "立法目标在未被设想的情势面前仍不确定的状态", "lesson": "S3M1K5"}, "法律的不确定性（Indeterminacy of Law）": {"term": "法律的不确定性（Indeterminacy of Law）", "def": "法律在某些案件中不 uniquely 决定判决结果的状态", "lesson": "S3M1K6"}, "规则怀疑论（Rule-Scepticism）": {"term": "规则怀疑论（Rule-Scepticism）", "def": "主张法律规则只是对法官判决的预测、谈论规则是神话的立场", "lesson": "S3M1K6"}, "疑难案件（Hard Cases）": {"term": "疑难案件（Hard Cases）", "def": "法律渊源无法唯一决定判决的案件", "lesson": "S3M1K6"}, "填补空隙的裁量（Interstitial Discretion）": {"term": "填补空隙的裁量（Interstitial Discretion）", "def": "法官在法律未调整处行使的有限造法权", "lesson": "S3M1K6"}, "唯一正确答案（Right Answer Thesis）": {"term": "唯一正确答案（Right Answer Thesis）", "def": "德沃金主张疑难案件存在正确答案的命题", "lesson": "S3M1K6"}, "自然事实（Natural Facts）": {"term": "自然事实（Natural Facts）", "def": "人之为人所共有、进而为法律提供理由的经验事实", "lesson": "S3M1K7"}, "生存（Survival）": {"term": "生存（Survival）", "def": "哈特据以推导法律最低内容的核心目标", "lesson": "S3M1K7"}, "相互克制（Mutual Forbearance）": {"term": "相互克制（Mutual Forbearance）", "def": "法律与道德共有的、以禁止伤害为核心的最低要求", "lesson": "S3M1K7"}, "自然 necessity（Natural Necessity）": {"term": "自然 necessity（Natural Necessity）", "def": "基于自然事实与目标、非逻辑必然的必要性", "lesson": "S3M1K7"}, "哈特—富勒论战（Hart-Fuller Debate）": {"term": "哈特—富勒论战（Hart-Fuller Debate）", "def": "1958年围绕法律与道德关系的著名论战", "lesson": "S3M2K1"}, "明确法（Positive Law）": {"term": "明确法（Positive Law）", "def": "由权威制定或承认的法律", "lesson": "S3M2K1"}, "合法性（Legality）": {"term": "合法性（Legality）", "def": "法律在形式上应满足的最低程序品质", "lesson": "S3M2K2"}, "程序自然法（Procedural Natural Law）": {"term": "程序自然法（Procedural Natural Law）", "def": "以程序要求而非实体价值界定法律道德性的思路", "lesson": "S3M2K2"}, "恶法非法（Lex Iniusta Non Est Lex）": {"term": "恶法非法（Lex Iniusta Non Est Lex）", "def": "严重违背正义的规则不是真正法律的命题", "lesson": "S3M2K3"}, "不可容忍性（Intolerability）": {"term": "不可容忍性（Intolerability）", "def": "拉德布鲁赫公式中法律与正义冲突达到极限的标准", "lesson": "S3M2K3"}, "恶法亦法": {"term": "恶法亦法", "def": "实证主义在效力意义上承认邪恶规则仍是法律的立场", "lesson": "S3M2K3"}, "法律义务（Legal Obligation）": {"term": "法律义务（Legal Obligation）", "def": "由有效法律规则施加、可由官方强制力保障的义务", "lesson": "S3M2K4"}, "道德义务（Moral Obligation）": {"term": "道德义务（Moral Obligation）", "def": "由道德原则施加、依靠内在良知与社会评价维系的责任", "lesson": "S3M2K4"}, "内在观点（Internal Point of View）": {"term": "内在观点（Internal Point of View）", "def": "参与者把规则当作行为理由与批评标准来接受的态度", "lesson": "S3M2K4"}, "服从（Obedience）": {"term": "服从（Obedience）", "def": "行为上符合规则要求，未必伴随接受其正当性", "lesson": "S3M2K4"}, "权威（Authority）": {"term": "权威（Authority）", "def": "要求他人服从并为其提供行为理由的权力或地位", "lesson": "S3M2K5"}, "正当性（Legitimacy）": {"term": "正当性（Legitimacy）", "def": "权威在道德上可被证成、值得被服从的属性", "lesson": "S3M2K5"}, "事实权威（De Facto Authority）": {"term": "事实权威（De Facto Authority）", "def": "事实上被服从但不必然正当的权威", "lesson": "S3M2K5"}, "合法权威（De Jure Authority）": {"term": "合法权威（De Jure Authority）", "def": "在道德上被证成、有权利被服从的权威", "lesson": "S3M2K5"}, "法律有效性（Legal Validity）": {"term": "法律有效性（Legal Validity）", "def": "规则因符合承认规则而属于法律体系的属性", "lesson": "S3M2K5"}, "服务性权威观（Service Conception of Authority）": {"term": "服务性权威观（Service Conception of Authority）", "def": "拉兹提出的、权威正当性在于更好地服务于被治者的理论", "lesson": "S3M2K5"}, "模糊性（Vagueness）": {"term": "模糊性（Vagueness）", "def": "语词存在边界情形、无法明确划定的语义特征", "lesson": "S3M3K1"}, "歧义（Ambiguity）": {"term": "歧义（Ambiguity）", "def": "语词具有两个以上可能含义的特征", "lesson": "S3M3K1"}, "核心（Core）": {"term": "核心（Core）", "def": "语词适用毫无疑问的清楚情形", "lesson": "S3M3K1"}, "边缘（Penumbra）": {"term": "边缘（Penumbra）", "def": "语词是否适用存在疑问的模糊情形", "lesson": "S3M3K1"}, "语义不确定性（Semantic Indeterminacy）": {"term": "语义不确定性（Semantic Indeterminacy）", "def": "语言本身无法唯一确定适用结果的状态", "lesson": "S3M3K1"}, "司法解释（Judicial Interpretation）": {"term": "司法解释（Judicial Interpretation）", "def": "法院在适用法律时对法律含义的阐明与确定", "lesson": "S3M3K2"}, "文义解释（Literal Interpretation）": {"term": "文义解释（Literal Interpretation）", "def": "按法律语词通常含义进行解释的方法", "lesson": "S3M3K2"}, "目的解释（Purposive Interpretation）": {"term": "目的解释（Purposive Interpretation）", "def": "依法律目的阐明规范含义的方法", "lesson": "S3M3K2"}, "司法解释权（Judicial Interpretive Power）": {"term": "司法解释权（Judicial Interpretive Power）", "def": "法院阐明法律含义的权威", "lesson": "S3M3K2"}, "法律漏洞（Gap in Law）": {"term": "法律漏洞（Gap in Law）", "def": "法律对某情形未作规定的状态", "lesson": "S3M3K2"}, "强意义裁量（Strong Discretion）": {"term": "强意义裁量（Strong Discretion）", "def": "裁判者不受法律理由约束、可自由决定的裁量", "lesson": "S3M3K3"}, "弱意义裁量（Weak Discretion）": {"term": "弱意义裁量（Weak Discretion）", "def": "裁判者须依标准但在具体适用中仍有判断空间的裁量", "lesson": "S3M3K3"}, "法官造法（Judicial Law-making）": {"term": "法官造法（Judicial Law-making）", "def": "法官在裁判中发展新规则的活动", "lesson": "S3M3K3"}, "明示其一即排除其他（Expressio Unius）": {"term": "明示其一即排除其他（Expressio Unius）", "def": "列举特定事项即排除未列举事项的解释格言", "lesson": "S3M3K4"}, "弊端规则（Mischief Rule）": {"term": "弊端规则（Mischief Rule）", "def": "探求法律欲救济的弊端以解释的方法", "lesson": "S3M3K4"}, "历史解释（Historical Interpretation）": {"term": "历史解释（Historical Interpretation）", "def": "通过立法史料探求法律制定背景与意图的解释方法", "lesson": "S3M3K5"}, "体系解释（Systematic Interpretation）": {"term": "体系解释（Systematic Interpretation）", "def": "将法律规范置于整个法律体系中、联系其他规范进行解释的方法", "lesson": "S3M3K5"}, "立法意图（Legislative Intent）": {"term": "立法意图（Legislative Intent）", "def": "立法者制定法律时欲达成的目的", "lesson": "S3M3K5"}, "立法史料（Legislative History）": {"term": "立法史料（Legislative History）", "def": "法案审议记录、委员会报告等历史材料", "lesson": "S3M3K5"}, "法律体系性（Systemicity of Law）": {"term": "法律体系性（Systemicity of Law）", "def": "法律规范之间相互关联构成统一整体的属性", "lesson": "S3M3K5"}, "Heydon's Case": {"term": "Heydon's Case", "def": "1584年确立弊端规则的英国判例", "lesson": "S3M3K5"}, "法律规则（Legal Rules）": {"term": "法律规则（Legal Rules）", "def": "以全有或全无方式适用的行为规范", "lesson": "S3M3K6"}, "全有或全无（All-or-Nothing）": {"term": "全有或全无（All-or-Nothing）", "def": "规则要么适用要么不适用的适用方式", "lesson": "S3M3K6"}, "分量（Weight）": {"term": "分量（Weight）", "def": "原则在权衡中相对重要性的维度", "lesson": "S3M3K6"}, "建构性诠释（Constructive Interpretation）": {"term": "建构性诠释（Constructive Interpretation）", "def": "德沃金所述寻找既适合又最佳证成原则的方法", "lesson": "S3M3K6"}, "法律作为完整性（Law as Integrity）": {"term": "法律作为完整性（Law as Integrity）", "def": "德沃金把法律理解为融贯的道德实践的理论", "lesson": "S3M3K6"}, "八项合法性要求（Eight Desiderata of Legality）": {"term": "八项合法性要求（Eight Desiderata of Legality）", "def": "一般性、公布、不溯及既往、清晰、不矛盾、可遵守、稳定、官方行为与公布规则相一致", "lesson": "S3M4K1"}, "目的性事业（Purposive Enterprise）": {"term": "目的性事业（Purposive Enterprise）", "def": "富勒对法律的根本刻画，即把人类行为置于一般规则治理之下的持续努力", "lesson": "S3M4K1"}, "规则模式（Model of Rules）": {"term": "规则模式（Model of Rules）", "def": "德沃金对实证主义法律观的概括，认为法律被化约为可由承认规则识别的规则集合", "lesson": "S3M4K2"}, "原则（Principle）": {"term": "原则（Principle）", "def": "具有分量维度的非规则标准，描述权利，要求因正义或公平而被遵守", "lesson": "S3M4K2"}, "政策（Policy）": {"term": "政策（Policy）", "def": "设定有待达成之集体目标的标准，描述目标而非权利", "lesson": "S3M4K2"}, "强自由裁量（Strong Discretion）": {"term": "强自由裁量（Strong Discretion）", "def": "法官在法律未规定处不受既定标准约束、可依个人判断造权的情形", "lesson": "S3M4K2"}, "语义之刺（Semantic Sting）": {"term": "语义之刺（Semantic Sting）", "def": "德沃金批评实证主义预设法律人共享一套有效性的语义判准，因而无法解释理论性分歧", "lesson": "S3M4K2"}, "建构性解释（Constructive Interpretation）": {"term": "建构性解释（Constructive Interpretation）", "def": "在既契合既有实践又能给出最佳道德辩护的限度内解释法律", "lesson": "S3M4K2"}, "法律的整体性（Law as Integrity）": {"term": "法律的整体性（Law as Integrity）", "def": "德沃金的核心命题，法律须作为一项连贯的正义事业被理解", "lesson": "S3M4K2"}, "连锁小说（Chain Novel）": {"term": "连锁小说（Chain Novel）", "def": "法官如同接续写作的小说家，须使自己的章节与前人的作品融为一体", "lesson": "S3M4K2"}, "社会来源命题（Sources Thesis）": {"term": "社会来源命题（Sources Thesis）", "def": "拉兹提出的强实证主义命题，认为法律的存在与内容最终由可识别的社会事实决定", "lesson": "S3M4K3"}, "包容实证主义（Inclusive Positivism）": {"term": "包容实证主义（Inclusive Positivism）", "def": "主张承认规则可以把道德标准纳入效力判准的柔性立场，亦称柔性实证主义", "lesson": "S3M4K3"}, "排除实证主义（Exclusive Positivism）": {"term": "排除实证主义（Exclusive Positivism）", "def": "主张法律效力判准只能来自社会来源的立场", "lesson": "S3M4K3"}, "最低限度自然法（Minimum Content of Natural Law）": {"term": "最低限度自然法（Minimum Content of Natural Law）", "def": "哈特承认法律基于人类生存需要而必须包含的少量自然法要素", "lesson": "S3M4K3"}, "坏人理论（Bad Man Theory）": {"term": "坏人理论（Bad Man Theory）", "def": "霍姆斯提出的视角，从预测法律后果的利害关系人出发理解法律", "lesson": "S3M4K4"}, "合法化（Legitimation）": {"term": "合法化（Legitimation）", "def": "政治统治将其主张转化为可被承认的正当权威的过程", "lesson": "S3M4K5"}, "支配（Domination）": {"term": "支配（Domination）", "def": "韦伯社会学中权力被稳定组织并被认为正当的状态", "lesson": "S3M4K5"}, "法理型支配（Legal-rational Domination）": {"term": "法理型支配（Legal-rational Domination）", "def": "以形式合理、普遍适用的法律规则为正当性基础的统治形态", "lesson": "S3M4K5"}, "形式合理性（Formal Rationality）": {"term": "形式合理性（Formal Rationality）", "def": "法律体系在内部自足、逻辑一致、可计算方面达到的理性化程度", "lesson": "S3M4K5"}, "实质合理性（Substantive Rationality）": {"term": "实质合理性（Substantive Rationality）", "def": "法律以特定的伦理、宗教或政治价值为目标取向的理性化形态", "lesson": "S3M4K5"}, "相对自主性（Relative Autonomy）": {"term": "相对自主性（Relative Autonomy）", "def": "韦伯关于法律受经济影响却不为经济单方面决定的命题", "lesson": "S3M4K5"}, "批判法理论（Critical Legal Theory）": {"term": "批判法理论（Critical Legal Theory）", "def": "质疑法律自主与中立、强调法律表达政治经济权力的理论取向", "lesson": "S3M4K5"}, "形式法治（Formal Conception of Rule of Law）": {"term": "形式法治（Formal Conception of Rule of Law）", "def": "强调程序与形式品质而不预设特定正义内容的法治观", "lesson": "S3M4K6"}, "实质法治（Substantive Conception of Rule of Law）": {"term": "实质法治（Substantive Conception of Rule of Law）", "def": "把正义、人权等价值纳入法治内涵的法治观", "lesson": "S3M4K6"}, "否定性美德（Negative Virtue）": {"term": "否定性美德（Negative Virtue）", "def": "拉兹对法治的定位，即它能减少任意权力的风险却自身不带独立道德价值", "lesson": "S3M4K6"}, "紧急状态例外（State of Emergency Exception）": {"term": "紧急状态例外（State of Emergency Exception）", "def": "在危机中暂时偏离常规法律要求的制度安排", "lesson": "S3M4K6"}, "人工智能（Artificial Intelligence, AI）": {"term": "人工智能（Artificial Intelligence, AI）", "def": "使机器执行通常需要人类智能的任务的技术体系", "lesson": "S3M5K1"}, "责任缺口（Responsibility Gap）": {"term": "责任缺口（Responsibility Gap）", "def": "损害确已发生却难以找到可归责主体的现象", "lesson": "S3M5K1"}, "产品责任（Product Liability）": {"term": "产品责任（Product Liability）", "def": "生产者对其产品缺陷造成损害承担的赔偿责任", "lesson": "S3M5K1"}, "不透明性（Opacity）": {"term": "不透明性（Opacity）", "def": "模型内部决策过程难以被外部理解与解释的性质", "lesson": "S3M5K1"}, "算法治理（Algorithmic Governance）": {"term": "算法治理（Algorithmic Governance）", "def": "以算法系统参与公共或私人决策并进行规范约束的制度安排", "lesson": "S3M5K2"}, "自动化决策（Automated Decision-making）": {"term": "自动化决策（Automated Decision-making）", "def": "由系统在没有人工干预的情况下作出决定或生成结果的过程", "lesson": "S3M5K2"}, "可解释性（Explainability）": {"term": "可解释性（Explainability）", "def": "使算法决策的理由能够被相关主体理解的性质", "lesson": "S3M5K2"}, "算法偏见（Algorithmic Bias）": {"term": "算法偏见（Algorithmic Bias）", "def": "系统输出对特定群体产生系统性不利影响的现象", "lesson": "S3M5K2"}, "数据保护影响评估（Data Protection Impact Assessment, DPIA）": {"term": "数据保护影响评估（Data Protection Impact Assessment, DPIA）", "def": "对高风险数据处理活动进行事前评估的机制", "lesson": "S3M5K2"}, "基本权利影响评估（Fundamental Rights Impact Assessment, FRIA）": {"term": "基本权利影响评估（Fundamental Rights Impact Assessment, FRIA）", "def": "评估系统对基本权利潜在影响的程序", "lesson": "S3M5K2"}, "守门人（Gatekeeper）": {"term": "守门人（Gatekeeper）", "def": "数字市场法中对具有结构性平台地位的企业所设定的特殊身份", "lesson": "S3M5K2"}, "数据保护（Data Protection）": {"term": "数据保护（Data Protection）", "def": "通过法律规则规范个人数据处理以保护个人权利的制度", "lesson": "S3M5K3"}, "隐私权（Right to Privacy）": {"term": "隐私权（Right to Privacy）", "def": "个人对其私人生活与信息保持控制的权利", "lesson": "S3M5K3"}, "个人数据（Personal Data）": {"term": "个人数据（Personal Data）", "def": "与已识别或可识别自然人有关的信息", "lesson": "S3M5K3"}, "数据主体（Data Subject）": {"term": "数据主体（Data Subject）", "def": "个人数据所指向的自然人", "lesson": "S3M5K3"}, "处理（Processing）": {"term": "处理（Processing）", "def": "对个人数据进行的收集、存储、使用、传输等活动", "lesson": "S3M5K3"}, "数据控制者（Data Controller）": {"term": "数据控制者（Data Controller）", "def": "决定数据处理目的与方式的主体", "lesson": "S3M5K3"}, "知情同意（Consent）": {"term": "知情同意（Consent）", "def": "数据主体在知情基础上自由作出的同意表示", "lesson": "S3M5K3"}, "被遗忘权（Right to Be Forgotten）": {"term": "被遗忘权（Right to Be Forgotten）", "def": "在一定条件下要求删除或移除个人信息的权利", "lesson": "S3M5K3"}, "知识产权（Intellectual Property）": {"term": "知识产权（Intellectual Property）", "def": "对智力创造成果赋予的专有权利体系", "lesson": "S3M5K4"}, "著作权（Copyright）": {"term": "著作权（Copyright）", "def": "保护文学艺术等作品表达的权利", "lesson": "S3M5K4"}, "独创性（Originality）": {"term": "独创性（Originality）", "def": "作品须体现作者独立创作与智力投入的要求", "lesson": "S3M5K4"}, "作者身份（Authorship）": {"term": "作者身份（Authorship）", "def": "法律上被承认为作品创作者的资格", "lesson": "S3M5K4"}, "思想与表达二分（Idea–Expression Dichotomy）": {"term": "思想与表达二分（Idea–Expression Dichotomy）", "def": "著作权保护表达而不保护思想的规则", "lesson": "S3M5K4"}, "合理使用（Fair Use）": {"term": "合理使用（Fair Use）", "def": "在特定情况下不经许可使用作品的抗辩制度", "lesson": "S3M5K4"}, "技术保护措施（Technological Protection Measures）": {"term": "技术保护措施（Technological Protection Measures）", "def": "用技术手段限制作品访问或复制的措施", "lesson": "S3M5K4"}, "公共领域（Public Domain）": {"term": "公共领域（Public Domain）", "def": "不归任何人专有、可供公众自由利用的知识资源", "lesson": "S3M5K4"}, "人权（Human Rights）": {"term": "人权（Human Rights）", "def": "人因其为人而应享有的基本权利与自由", "lesson": "S3M5K5"}, "国际人权法（International Human Rights Law）": {"term": "国际人权法（International Human Rights Law）", "def": "由条约、习惯与国际组织实践构成的保护人权的国际法分支", "lesson": "S3M5K5"}, "普遍主义（Universalism）": {"term": "普遍主义（Universalism）", "def": "主张人权标准跨文化普遍适用的立场", "lesson": "S3M5K5"}, "文化相对主义（Cultural Relativism）": {"term": "文化相对主义（Cultural Relativism）", "def": "主张人权应依具体文化传统理解的立场", "lesson": "S3M5K5"}, "保留（Reservation）": {"term": "保留（Reservation）", "def": "缔约国在批准条约时对特定条款提出的排除或变更声明", "lesson": "S3M5K5"}, "对一切义务（Obligations Erga Omnes）": {"term": "对一切义务（Obligations Erga Omnes）", "def": "国际社会对整体承担、涉及全体国际成员利益的义务", "lesson": "S3M5K5"}, "条约机构（Treaty Body）": {"term": "条约机构（Treaty Body）", "def": "监督缔约国履行人权条约的专家委员会", "lesson": "S3M5K5"}, "人道主义干预（Humanitarian Intervention）": {"term": "人道主义干预（Humanitarian Intervention）", "def": "为制止大规模人道灾难而跨境使用武力的主张", "lesson": "S3M5K5"}, "全球化（Globalization）": {"term": "全球化（Globalization）", "def": "人员、资本、信息与风险跨越国界流动并相互依存的过程", "lesson": "S3M5K6"}, "全球治理（Global Governance）": {"term": "全球治理（Global Governance）", "def": "国家、国际组织与私人主体共同制定与执行跨国规则的机制", "lesson": "S3M5K6"}, "域外管辖（Extraterritoriality）": {"term": "域外管辖（Extraterritoriality）", "def": "一国法律对其领土之外的人或事主张适用", "lesson": "S3M5K6"}, "冲突法（Conflict of Laws）": {"term": "冲突法（Conflict of Laws）", "def": "处理涉外案件应适用何地法律与何地法院的规则体系", "lesson": "S3M5K6"}, "跨国法（Transnational Law）": {"term": "跨国法（Transnational Law）", "def": "调整跨越国界活动的规范总和，兼含公私法要素", "lesson": "S3M5K6"}, "软法（Soft Law）": {"term": "软法（Soft Law）", "def": "不具严格法律拘束力却具有规范影响力的国际标准与准则", "lesson": "S3M5K6"}}, "sectionOrder": ["coreQuestion", "definition", "history", "principle", "viewpoints", "comparison", "debates", "case", "caseAnalysis", "summary", "furtherThinking"], "sectionNames": {"coreQuestion": "核心问题", "definition": "概念定义", "history": "历史背景", "principle": "理论原理", "viewpoints": "核心观点", "comparison": "理论比较", "debates": "经典争论", "case": "现实案例", "caseAnalysis": "案例解析", "summary": "本节总结", "furtherThinking": "延伸思考"}};
